typedef struct alignas(16) {
    uint64_t low;
    uint64_t high;
} uint128_t;

template<>
inline bool cas(volatile uint128_t *src, uint128_t cmp, uint128_t with) {
    uint64_t cmp_low = cmp.low;
    uint64_t cmp_high = cmp.high;
    uint64_t with_low = with.low;
    uint64_t with_high = with.high;
    unsigned char result = 0;

    __asm__ __volatile__ (
        "lock cmpxchg16b %1\n\t"
        "setz %0\n\t"
        : "=q" (result), "+m" (*src)
        : "a" (cmp_low), "d" (cmp_high), "b" (with_low), "c" (with_high)
        : "cc", "memory"
    );

    return result;
}

#include <immintrin.h> // For AVX intrinsics

void reorder(float* output, const float* input, size_t length) {
    size_t i = 0;
    while (i < length) {
        // Check if the next 8 floats are contiguous and valid
        if (input[i] != 0 && input[i + 1] != 0 && input[i + 2] != 0 && input[i + 3] != 0 &&
            input[i + 4] != 0 && input[i + 5] != 0 && input[i + 6] != 0 && input[i + 7] != 0) {
            // Load 8 floats from input
            __m256 vec = _mm256_loadu_ps(&input[i]);
            // Store 8 floats to output
            _mm256_storeu_ps(&output[i], vec);
            i += 8;
        } else {
            // Handle non-contiguous or '0'-valued elements
            output[i] = input[i];
            i++;
        }
    }
}

#include <immintrin.h>

   void avx_vcmulcc(cfloat* out, const cfloat* in1, const cfloat* in2, int n) {
       for (int i = 0; i < n; i += 8) {
           __m256 a = _mm256_loadu_ps((const float*)(in1 + i));
           __m256 b = _mm256_loadu_ps((const float*)(in2 + i));

           // Complex conjugate multiply
           __m256 real_a = _mm256_permute_ps(a, _MM_SHUFFLE(2, 3, 0, 1));
           __m256 imag_a = _mm256_permute_ps(a, _MM_SHUFFLE(3, 2, 1, 0));
           __m256 real_b = _mm256_permute_ps(b, _MM_SHUFFLE(2, 3, 0, 1));
           __m256 imag_b = _mm256_permute_ps(b, _MM_SHUFFLE(3, 2, 1, 0));

           __m256 real_out = _mm256_sub_ps(_mm256_mul_ps(real_a, real_b), _mm256_mul_ps(imag_a, imag_b));
           __m256 imag_out = _mm256_add_ps(_mm256_mul_ps(real_a, imag_b), _mm256_mul_ps(imag_a, real_b));

           _mm256_storeu_ps((float*)(out + i), _mm256_permute2f128_ps(real_out, imag_out, 0x20));
       }
   }

void encrypt_chars(int length, char EKey)
{
    char temp_char;

    for (int i = 0; i < length; i++)
    {
        temp_char = OChars[i];
        __asm
        {
            push eax
            push ecx

            movzx ecx, temp_char
            push ecx
            lea eax, EKey
            push eax
            call encrypt4
            add esp, 8
            mov temp_char, al

            pop ecx
            pop eax
        }
