// Function to check if a number is prime
bool isPrime(int n) {
    if (n <= 1) return false; // 0 and 1 are not prime numbers
    if (n <= 3) return true;  // 2 and 3 are prime numbers

    // This is checked so that we can skip middle five numbers in below loop
    if (n % 2 == 0 || n % 3 == 0) return false;

    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0)
            return false;
    }
    return true;
}

// Function to find the next prime number
int nextPrime(int n) {
    int prime = n;
    bool found = false;

    while (!found) {
        prime++;
        if (isPrime(prime))
            found = true;
    }

    return prime;
}

int main() {
    int input;

    std::cout << "Enter a number: ";
    std::cin >> input;

    int nextPrimeNumber = nextPrime(input);
    std::cout << "The next prime number after " << input << " is " << nextPrimeNumber << std::endl;

    return 0;
}

#include <iostream>
#include <string>

std::string longestPalindrome(std::string s) {
    if (s.empty()) return "";

    int n = s.size();
    int start = 0, maxLen = 1;

    auto expandAroundCenter = [&](int left, int right) {
        while (left >= 0 && right < n && s[left] == s[right]) {
            left--;
            right++;
        }
        return right - left - 1;
    };

    for (int i = 0; i < n; i++) {
        int len1 = expandAroundCenter(i, i);       // Odd length palindromes
        int len2 = expandAroundCenter(i, i + 1);   // Even length palindromes
        int len = std::max(len1, len2);

        if (len > maxLen) {
            maxLen = len;
            start = i - (len - 1) / 2;
        }
    }

    return s.substr(start, maxLen);
}

int main() {
    std::string input = "abaxyzzyxf";
    std::string result = longestPalindrome(input);
    std::cout << "The longest palindromic substring is: " << result << std::endl;
    return 0;
}

