template <typename CharT>
size_t custom_strlen(const CharT* str, CharT terminator) {
    size_t length = 0;
    while (*str != terminator) {
        ++length;
        ++str;
    }
    return length;
}

int main() {
    const char* str = "Hello, World!";
    char terminator = '!';

    size_t length = custom_strlen(str, terminator);
    // length should be 13, as it stops at the '!'
    return 0;
}

