class XdmItem;

class XdmValue {
public:
    virtual shared_ptr<XdmItem> itemAt(int n);
    virtual int size();
    void addXdmItem(shared_ptr<XdmItem> val);

protected:
    std::vector<shared_ptr<XdmItem>> values;
};

void XdmValue::addXdmItem(shared_ptr<XdmItem> val) {
    values.push_back(val);
}

shared_ptr<XdmItem> XdmValue::itemAt(int n) {
    if (n >= 0 && (unsigned int)n < values.size()) {
        return values[n];
    }
    return nullptr;
}

int XdmValue::size() {
    return values.size();
}

class XdmItem : public XdmValue {
public:
    int size() override {
        return 1;
    }
};

