       PHP_FUNCTION(matrix_multiply) {
           double *data1, *data2;
           int rows1, cols1, rows2, cols2;
           if (zend_parse_parameters(ZEND_NUM_ARGS(), "ddiiii", &data1, &data2, &rows1, &cols1, &rows2, &cols2) == FAILURE) {
               RETURN_NULL();
           }

           MatrixXd m1(rows1, cols1);
           MatrixXd m2(rows2, cols2);
           for (int i = 0; i < rows1; ++i) {
               for (int j = 0; j < cols1; ++j) {
                   m1(i, j) = data1[i * cols1 + j];
               }
           }
           for (int i = 0; i < rows2; ++i) {
               for (int j = 0; j < cols2; ++j) {
                   m2(i, j) = data2[i * cols2 + j];
               }
           }

           MatrixXd result = m1 * m2;

           double *result_data = (double*)malloc(result.rows() * result.cols() * sizeof(double));
           for (int i = 0; i < result.rows(); ++i) {
               for (int j = 0; j < result.cols(); ++j) {
                   result_data[i * result.cols() + j] = result(i, j);
               }
           }

           RETURN_DOUBLE_ARRAY(result_data, result.rows() * result.cols(), 0);
       }
   }
