     #include <glm/gtc/matrix_transform.hpp>
     #include <glm/gtc/type_ptr.hpp>
     #include <iostream>
     #include <vector>
     #include <random>

     void drawTree(float x, float y, float height, float radius) {
         // Draw the trunk
         glBegin(GL_QUADS);
         glColor3f(0.5, 0.25, 0);  // Brown
         glVertex3f(x - 0.5, y, 0);
         glVertex3f(x + 0.5, y, 0);
         glVertex3f(x + 0.5, y + height, 0);
         glVertex3f(x - 0.5, y + height, 0);
         glEnd();

         // Draw the leaves
         std::random_device rd;
         std::mt19937 gen(rd());
         std::uniform_real_distribution<> dis(-1.0, 1.0);
         for (int i = 0; i < 100; ++i) {
             float angle = dis(gen) * 3.14159 * 2;
             float distance = dis(gen) * radius;
             float leaf_x = x + distance * std::cos(angle) * 2;
             float leaf_y = y + height + distance * std::sin(angle) * 2;
             glBegin(GL_TRIANGLES);
             glColor3f(0, 1, 0);  // Green
             glVertex3f(leaf_x, leaf_y, 0);
             glVertex3f(leaf_x + 0.1, leaf_y + 0.1, 0);
             glVertex3f(leaf_x - 0.1, leaf_y + 0.1, 0);
             glEnd();
         }
     }

     int main() {
         if (!glfwInit()) {
             std::cerr << "Failed to initialize GLFW" << std::endl;
             return -1;
         }

         GLFWwindow* window = glfwCreateWindow(800, 600, "Tree Example", NULL, NULL);
         if (!window) {
             std::cerr << "Failed to create GLFW window" << std::endl;
             glfwTerminate();
             return -1;
         }

         glfwMakeContextCurrent(window);
         glewInit();

         while (!glfwWindowShouldClose(window)) {
             glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

             for (int i = 0; i < 10; ++i) {
                 float x = static_cast<float>(rand()) / RAND_MAX * 20 - 10;
                 float y = static_cast<float>(rand()) / RAND_MAX * 20 - 10;
                 float height = static_cast<float>(rand()) / RAND_MAX * 5 + 3;
                 float radius = static_cast<float>(rand()) / RAND_MAX * 3 + 2;
                 drawTree(x, y, height, radius);
             }

             glfwSwapBuffers(window);
             glfwPollEvents();
         }

         glfwDestroyWindow(window);
         glfwTerminate();
         return 0;
     }

typedef struct {
    float re;
    float im;
} dcmplx;

dcmplx ComplexConv(int len, dcmplx *hat, dcmplx *buf)
{
    dcmplx xout = {0.0, 0.0};

    asm volatile (
        "vdup.32 q0, #0\n\t"  // Initialize q0 with zeros (xout.re, xout.im)
        "mov r3, #0\n\t"
        ".loop:\n\t"
        "vldr s11, [%[hat], #4]\n\t"  // Load hat[i].im
        "vldr s13, [%[hat]]\n\t"      // Load hat[i].re
        "vneg.f32 s11, s11\n\t"       // Conjugate hat[i].im
        "vldr s15, [%[buf], #4]\n\t"  // Load buf[i].im
        "vldr s12, [%[buf]]\n\t"      // Load buf[i].re
        "vmul.f32 s14, s15, s13\n\t"  // Multiply hat[i].re * buf[i].im
        "vmul.f32 s15, s11, s15\n\t"  // Multiply hat[i].im * buf[i].im
        "adds %[hat], #8\n\t"         // Increment hat pointer
        "vmla.f32 s14, s11, s12\n\t"  // Multiply and accumulate hat[i].im * buf[i].re
        "vnmls.f32 s15, s12, s13\n\t" // Multiply and subtract hat[i].re * buf[i].re
        "adds %[buf], #8\n\t"         // Increment buf pointer
        "vadd.f32 s1, s1, s14\n\t"    // Accumulate real part
        "vadd.f32 s0, s0, s15\n\t"    // Accumulate imaginary part
        "adds r3, r3, #1\n\t"         // Increment loop counter
        "cmp r3, %[len]\n\t"          // Compare loop counter with len
        "bne .loop\n\t"
        : [xout]"=w"(xout)            // Output constraint for xout
        : [hat]"r"(hat), [buf]"r"(buf), [len]"r"(len)
        : "r3", "s11", "s12", "s13", "s14", "s15", "cc"
    );

    return xout;
}

#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const int MAX_N = 200;

bool isBipartite(int n, vector<vector<int>>& graph) {
    vector<int> color(n, -1); // -1: not colored, 0: color 1, 1: color 2

    for (int i = 0; i < n; ++i) {
        if (color[i] == -1) {
            color[i] = 0;
            queue<int> q;
            q.push(i);

            while (!q.empty()) {
                int u = q.front();
                q.pop();

                for (int v : graph[u]) {
                    if (color[v] == -1) {
                        color[v] = 1 - color[u];
                        q.push(v);
                    } else if (color[v] == color[u]) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

int main() {
    int n, k;
    while (cin >> n && n != 0) {
        cin >> k;
        vector<vector<int>> graph(n);

        for (int i = 0; i < k; ++i) {
            int a, b;
            cin >> a >> b;
            a--; b--; // Convert to 0-based index
            graph[a].push_back(b);
            graph[b].push_back(a);
        }

        if (isBipartite(n, graph)) {
            cout << "Possible" << endl;
        } else {
            cout << "Not possible" << endl;
        }
    }

    return 0;
}

