#include <unordered_map>
#include <algorithm>
using namespace std;

pair<int, int> longestSubstringWithoutRepeatingCharacters(const string& s) {
    if (s.empty()) return {0, 0};

    unordered_map<char, int> charIndexMap;
    int maxLength = 0, maxUniqueChars = 0, start = 0;

    for (int end = 0; end < s.size(); ++end) {
        if (charIndexMap.find(s[end]) != charIndexMap.end()) {
            start = max(start, charIndexMap[s[end]] + 1);
        }
        charIndexMap[s[end]] = end;
        int currentLength = end - start + 1;
        int currentUniqueChars = charIndexMap.size();

        if (currentLength > maxLength) {
            maxLength = currentLength;
            maxUniqueChars = currentUniqueChars;
        }
    }

    return {maxLength, maxUniqueChars};
}

int main() {
    string s = "pwwkew";
    pair<int, int> result = longestSubstringWithoutRepeatingCharacters(s);
    cout << "The length of the longest substring without repeating characters is " << result.first << '\n';
    cout << "The number of unique characters in that substring is " << result.second << '\n';
    return 0;
}

