class uint128_t {
private:
    unsigned long long high;
    unsigned long long low;

public:
    uint128_t() : high(0), low(0) {}
    uint128_t(unsigned long long low) : high(0), low(low) {}
    uint128_t(unsigned long long high, unsigned long long low) : high(high), low(low) {}

    // Addition
    uint128_t operator+(const uint128_t& other) const {
        unsigned long long new_low = low + other.low;
        unsigned long long new_high = high + other.high + (new_low < low);
        return uint128_t(new_high, new_low);
    }

    // Subtraction
    uint128_t operator-(const uint128_t& other) const {
        unsigned long long new_low = low - other.low;
        unsigned long long new_high = high - other.high - (new_low > low);
        return uint128_t(new_high, new_low);
    }

    // Multiplication
    uint128_t operator*(const uint128_t& other) const {
        unsigned long long a = high, b = low;
        unsigned long long c = other.high, d = other.low;
        unsigned long long ac = a * c;
        unsigned long long bd = b * d;
        unsigned long long ad_plus_bc = a * d + b * c;
        unsigned long long ad_plus_bc_high = ad_plus_bc >> 64;
        unsigned long long ad_plus_bc_low = ad_plus_bc & 0xFFFFFFFFFFFFFFFFULL;
        unsigned long long new_low = bd + ad_plus_bc_low;
        unsigned long long new_high = ac + ad_plus_bc_high + (new_low < bd);
        return uint128_t(new_high, new_low);
    }

    // Division
    uint128_t operator/(const uint128_t& other) const {
        // Implement division using long division algorithm or other methods
        // This is a placeholder for simplicity
        return uint128_t();
    }

    // Equality
    bool operator==(const uint128_t& other) const {
        return high == other.high && low == other.low;
    }

    // Inequality
    bool operator!=(const uint128_t& other) const {
        return !(*this == other);
    }

    // Less than
    bool operator<(const uint128_t& other) const {
        if (high != other.high) return high < other.high;
        return low < other.low;
    }

    // Greater than
    bool operator>(const uint128_t& other) const {
        return other < *this;
    }

    // Less than or equal to
    bool operator<=(const uint128_t& other) const {
        return !(*this > other);
    }

    // Greater than or equal to
    bool operator>=(const uint128_t& other) const {
        return !(*this < other);
    }

    // Conversion to string (for debugging)
    std::string to_string() const {
        std::stringstream ss;
        ss << "0x" << std::hex << high << std::hex << low;
        return ss.str();
    }
};

