int main() {
    TCHAR namedPipeName[] = _T("\\\\.\\pipe\\TitleChangePipe");

    HANDLE pipe = CreateNamedPipe(
        namedPipeName,
        PIPE_ACCESS_DUPLEX | FILE_FLAG_OVERLAPPED, // Allow both read and write
        PIPE_WAIT, // Synchronous pipe
        1, // Only one client at a time
        1024, // Output buffer size
        1024, // Input buffer size
        120 * 1000, // Default time-out
        NULL // Default security attributes
    );

    if (pipe == INVALID_HANDLE_VALUE) {
        _tprintf(_T("Pipe Could Not be Established.\n"));
        return -1;
    }

    _tprintf(_T("Waiting for client to connect...\n"));
    if (!ConnectNamedPipe(pipe, NULL)) {
        _tprintf(_T("Failed to connect to client.\n"));
        CloseHandle(pipe);
        return -1;
    }

    _tprintf(_T("Client connected.\n"));

    char line[512]; DWORD numRead;

    while (true) {
        numRead = 1;
        while ((numRead < 10 || numRead > 511) && numRead > 0) {
            if (!ReadFile(pipe, line, 512, &numRead, NULL) || numRead < 1) {
                _tprintf(_T("Failed to read from pipe.\n"));
                CloseHandle(pipe);
                pipe = CreateNamedPipe(
                    namedPipeName,
                    PIPE_ACCESS_DUPLEX | FILE_FLAG_OVERLAPPED,
                    PIPE_WAIT,
                    1,
                    1024,
                    1024,
                    120 * 1000,
                    NULL
                );
                if (pipe == INVALID_HANDLE_VALUE) {
                    _tprintf(_T("Pipe Could Not be Re-Established.\n"));
                    return -1;
                }
                if (!ConnectNamedPipe(pipe, NULL)) {
                    _tprintf(_T("Failed to re-connect to client.\n"));
                    CloseHandle(pipe);
                    return -1;
                }
                numRead = 1;
            }
        }
        line[numRead] = '\0';
        _tprintf(_T("Received: %s\n"), line);
    }

    CloseHandle(pipe);
    return 0;
}

