struct Point {
    double x, y;
};

// Function to calculate the Euclidean distance between two points
double distance(const Point &p1, const Point &p2) {
    return std::sqrt(std::pow(p1.x - p2.x, 2) + std::pow(p1.y - p2.y, 2));
}

// Function to find the minimum distance between the closest pair of points in a strip
double stripClosest(std::vector<Point> &strip, double d) {
    double min_dist = d;
    size_t n = strip.size();
    for (size_t i = 0; i < n; ++i) {
        for (size_t j = i + 1; j < n && (strip[j].y - strip[i].y) < min_dist; ++j) {
            double dist = distance(strip[i], strip[j]);
            if (dist < min_dist) {
                min_dist = dist;
            }
        }
    }
    return min_dist;
}

// Function to find the closest pair of points using the divide-and-conquer approach
double closestPair(std::vector<Point> &Px, std::vector<Point> &Py) {
    size_t n = Px.size();
    if (n <= 3) {
        double min_dist = std::numeric_limits<double>::max();
        for (size_t i = 0; i < n; ++i) {
            for (size_t j = i + 1; j < n; ++j) {
                double dist = distance(Px[i], Px[j]);
                if (dist < min_dist) {
                    min_dist = dist;
                }
            }
        }
        return min_dist;
    }

    size_t mid = n / 2;
    Point midPoint = Px[mid];

    std::vector<Point> Lx(Px.begin(), Px.begin() + mid);
    std::vector<Point> Rx(Px.begin() + mid, Px.end());

    std::vector<Point> Ly, Ry;
    for (const auto &point : Py) {
        if (point.x <= midPoint.x) {
            Ly.push_back(point);
        } else {
            Ry.push_back(point);
        }
    }

    double dl = closestPair(Lx, Ly);
    double dr = closestPair(Rx, Ry);
    double d = std::min(dl, dr);

    std::vector<Point> strip;
    for (const auto &point : Py) {
        if (std::abs(point.x - midPoint.x) < d) {
            strip.push_back(point);
        }
    }

    return std::min(d, stripClosest(strip, d));
}

// Function to sort points by x and y coordinates
void sortPoints(std::vector<Point> &points) {
    std::vector<Point> Px = points;
    std::vector<Point> Py = points;
    std::sort(Px.begin(), Px.end(), [](const Point &a, const Point &b) {
        return a.x < b.x;
    });
    std::sort(Py.begin(), Py.end(), [](const Point &a, const Point &b) {
        return a.y < b.y;
    });

    double min_dist = closestPair(Px, Py);
    std::cout << "The minimum distance is: " << min_dist << std::endl;
}

int main() {
    std::vector<Point> points = {
        {2, 3}, {12, 30}, {40, 50}, {5, 1}, {12, 10}, {3, 4}
    };

    sortPoints(points);

    return 0;
}

#include <iostream>
#include <vector>

void bubbleSort(std::vector<int> &arr) {
  bool swapped;
  int size = arr.size();
  for (int i = 0; i < size - 1; i++) {
    swapped = false;
    for (int j = 0; j < size - i - 1; j++) {
      if (arr[j] > arr[j + 1]) {
        std::swap(arr[j], arr[j + 1]);
        swapped = true;
      }
    }
    if (!swapped) break;
  }
}

