std::vector<uint8_t> xorEncode(const std::vector<uint8_t>& data, const std::string& password) {
    std::vector<uint8_t> encodedData = data;
    for (size_t i = 0; i < data.size(); ++i) {
        encodedData[i] ^= password[i % password.size()];
    }
    return encodedData;
}

std::vector<uint8_t> xorDecode(const std::vector<uint8_t>& data, const std::string& password) {
    return xorEncode(data, password); // XOR is symmetric
}

void encodeFile(const std::string& inputPath, const std::string& outputPath, const std::string& password) {
    std::ifstream inputFile(inputPath, std::ios::binary);
    std::ofstream outputFile(outputPath, std::ios::binary);

    if (!inputFile.is_open() || !outputFile.is_open()) {
        std::cerr << "Error opening file." << std::endl;
        return;
    }

    std::vector<uint8_t> buffer(1024);
    while (inputFile.read(reinterpret_cast<char*>(buffer.data()), buffer.size())) {
        size_t bytesRead = inputFile.gcount();
        std::vector<uint8_t> encodedBuffer = xorEncode(buffer, password);
        outputFile.write(reinterpret_cast<const char*>(encodedBuffer.data()), bytesRead);
    }

    inputFile.close();
    outputFile.close();
}

void decodeFile(const std::string& inputPath, const std::string& outputPath, const std::string& password) {
    encodeFile(inputPath, outputPath, password); // XOR is symmetric
}

#include <iostream>
using namespace std;

// Define the structure for the node
struct Node {
    int data;
    Node* next;
};

// Function to check if the linked list is circular
bool isCircular(Node* head) {
    if (head == NULL) {
        return false; // An empty list is not circular
    }

    Node* slow = head;
    Node* fast = head;

    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;      // Move slow by one step
        fast = fast->next->next; // Move fast by two steps

        if (slow == fast) {
            return true; // Cycle detected
        }
    }

    return false; // No cycle detected
}

// Function to create a new node
Node* createNode(int data) {
    Node* newNode = new Node();
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to create a circular linked list for testing
Node* createCircularLinkedList() {
    Node* head = createNode(1);
    Node* second = createNode(2);
    Node* third = createNode(3);
    Node* fourth = createNode(4);

    head->next = second;
    second->next = third;
    third->next = fourth;
    fourth->next = head; // Make it circular

    return head;
}

// Function to create a non-circular linked list for testing
Node* createNonCircularLinkedList() {
    Node* head = createNode(1);
    Node* second = createNode(2);
    Node* third = createNode(3);
    Node* fourth = createNode(4);

    head->next = second;
    second->next = third;
    third->next = fourth;
    fourth->next = NULL; // Make it non-circular

    return head;
}

int main() {
    Node* circularList = createCircularLinkedList();
    Node* nonCircularList = createNonCircularLinkedList();

    cout << "Is the circular list circular? " << (isCircular(circularList) ? "Yes" : "No") << endl;
    cout << "Is the non-circular list circular? " << (isCircular(nonCircularList) ? "Yes" : "No") << endl;

    return 0;
}

