// Function to check if a number is prime
bool isPrime(int num) {
    if (num <= 1) return false;
    if (num == 2) return true;
    if (num % 2 == 0) return false;
    for (int i = 3; i <= std::sqrt(num); i += 2) {
        if (num % i == 0) return false;
    }
    return true;
}

// Function to find all prime numbers in the range [M, N]
std::vector<int> findPrimesInRange(int M, int N) {
    std::vector<int> primes;
    for (int num = M; num <= N; ++num) {
        if (isPrime(num)) {
            primes.push_back(num);
        }
    }
    return primes;
}

int main() {
    int M, N;
    std::cout << "Enter the range (M N): ";
    std::cin >> M >> N;

    std::vector<int> primes = findPrimesInRange(M, N);

    std::cout << "Prime numbers between " << M << " and " << N << " are: ";
    for (int prime : primes) {
        std::cout << prime << " ";
    }
    std::cout << std::endl;

    return 0;
}

typedef unsigned long U32;

extern "C" __declspec(dllexport) int ReadFile(LPSTR Path, U32** DataPtr, U32* Count)
{
    FILE *fp;
    U32 *Data;
    CString tempStr(Path);
    long fSize;

    if (!(fp = fopen(tempStr, "rb"))) {
        return 0;
    }

    // Obtain File Size
    fseek(fp, 0, SEEK_END);
    fSize = ftell(fp);
    rewind(fp);

    // Ensure fSize is a multiple of sizeof(U32)
    if (fSize % sizeof(U32) != 0) {
        fclose(fp);
        return -3; // File size is not a multiple of sizeof(U32)
    }

    // Allocate memory
    Data = (U32 *)malloc(fSize);
    if (Data == NULL) {
        fclose(fp);
        return -1;
    }

    // Copy file into the buffer
    *Count = fread(Data, sizeof(U32), fSize / sizeof(U32), fp);
    if (*Count == 0) {
        fclose(fp);
        free(Data);
        return -2;
    }

    *DataPtr = Data;
    fclose(fp);
    return 1;
}

