#include <iostream>
using namespace std;

// Define the structure for a BST node
struct Node {
    int data;
    Node* left;
    Node* right;
};

// Function to create a new BST node
Node* newNode(int data) {
    Node* node = new Node();
    node->data = data;
    node->left = node->right = nullptr;
    return node;
}

// Function to insert a new node in the BST
Node* insert(Node* root, int data) {
    if (root == nullptr) return newNode(data);
    if (data < root->data)
        root->left = insert(root->left, data);
    else
        root->right = insert(root->right, data);
    return root;
}

// Function to find the inorder successor of a given node
Node* findInorderSuccessor(Node* root, Node* node) {
    Node* successor = nullptr;

    while (root != nullptr) {
        if (node->data < root->data) {
            successor = root;
            root = root->left;
        } else if (node->data > root->data) {
            root = root->right;
        } else {
            break;
        }
    }

    if (root != nullptr && root->right != nullptr) {
        Node* current = root->right;
        while (current->left != nullptr) {
            current = current->left;
        }
        successor = current;
    }

    return successor;
}

// Function to find the inorder predecessor of a given node
Node* findInorderPredecessor(Node* root, Node* node) {
    Node* predecessor = nullptr;

    while (root != nullptr) {
        if (node->data > root->data) {
            predecessor = root;
            root = root->right;
        } else if (node->data < root->data) {
            root = root->left;
        } else {
            break;
        }
    }

    if (root != nullptr && root->left != nullptr) {
        Node* current = root->left;
        while (current->right != nullptr) {
            current = current->right;
        }
        predecessor = current;
    }

    return predecessor;
}

// Function to print the inorder successor and predecessor
void printSuccessorAndPredecessor(Node* root, int key) {
    Node* node = root;
    while (node != nullptr && node->data != key) {
        if (key < node->data)
            node = node->left;
        else
            node = node->right;
    }

    if (node == nullptr) {
        cout << "Node with key " << key << " not found in the BST." << endl;
        return;
    }

    Node* predecessor = findInorderPredecessor(root, node);
    Node* successor = findInorderSuccessor(root, node);

    if (predecessor != nullptr)
        cout << "Inorder Predecessor of " << key << " is " << predecessor->data << endl;
    else
        cout << "No inorder predecessor for " << key << endl;

    if (successor != nullptr)
        cout << "Inorder Successor of " << key << " is " << successor->data << endl;
    else
        cout << "No inorder successor for " << key << endl;
}

// Main function to demonstrate the functionality
int main() {
    Node* root = nullptr;
    root = insert(root, 20);
    insert(root, 8);
    insert(root, 22);
    insert(root, 4);
    insert(root, 12);
    insert(root, 10);
    insert(root, 14);

    int key = 12;
    printSuccessorAndPredecessor(root, key);

    return 0;
}

