Ogre::Vector3 TFormVector(const Ogre::Vector3& sourceVector, const Ogre::Entity* sourceEntity, const Ogre::Entity* destEntity) {
    // Check if sourceEntity or destEntity is nullptr
    // and use the world coordinate system accordingly

    Ogre::Vector3 transformedVector = sourceVector;

    // Perform the transformation
    if (sourceEntity) {
        Ogre::Matrix4 sourceTransform = sourceEntity->getParentNode()->_getFullTransform();
        transformedVector = sourceTransform * transformedVector;
    }

    if (destEntity) {
        Ogre::Matrix4 destTransform = destEntity->getParentNode()->_getFullTransform().inverse();
        transformedVector = destTransform * transformedVector;
    }

    return transformedVector;
}

