#include <cuda_runtime.h>
#include <iostream>

#define BLOCK_SIZE 16
#define KERNEL_SIZE 3
#define RADIUS (KERNEL_SIZE / 2)

__constant__ float kernel[KERNEL_SIZE * KERNEL_SIZE] = {
    0, -1, 0,
    -1, 4, -1,
    0, -1, 0
};

__global__ void convolve2D(const float* input, float* output, int width, int height) {
    __shared__ float sharedMem[BLOCK_SIZE + 2 * RADIUS][BLOCK_SIZE + 2 * RADIUS];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    // Load data into shared memory
    if (row < height && col < width) {
        sharedMem[ty + RADIUS][tx + RADIUS] = input[row * width + col];
    }

    // Load boundary conditions
    if (row < RADIUS) {
        sharedMem[ty][tx + RADIUS] = (row == 0) ? 0 : input[(row - 1) * width + col];
    }
    if (row >= height - RADIUS) {
        sharedMem[ty + 2 * RADIUS][tx + RADIUS] = (row == height - 1) ? 0 : input[(row + 1) * width + col];
    }
    if (col < RADIUS) {
        sharedMem[ty + RADIUS][tx] = (col == 0) ? 0 : input[row * width + (col - 1)];
    }
    if (col >= width - RADIUS) {
        sharedMem[ty + RADIUS][tx + 2 * RADIUS] = (col == width - 1) ? 0 : input[row * width + (col + 1)];
    }

    __syncthreads();

    // Perform convolution
    float sum = 0.0f;
    for (int ky = 0; ky < KERNEL_SIZE; ++ky) {
        for (int kx = 0; kx < KERNEL_SIZE; ++kx) {
            sum += sharedMem[ty + RADIUS + ky - RADIUS][tx + RADIUS + kx - RADIUS] * kernel[ky * KERNEL_SIZE + kx];
        }
    }

    if (row < height && col < width) {
        output[row * width + col] = sum;
    }
}

int main() {
    int width = 500;
    int height = 500;
    int size = width * height * sizeof(float);

    float* h_input = new float[width * height];
    float* h_output = new float[width * height];
    float* d_input;
    float* d_output;

    cudaMalloc(&d_input, size);
    cudaMalloc(&d_output, size);

    // Initialize input data
    for (int i = 0; i < width * height; ++i) {
        h_input[i] = 1.0f; // Example data
    }

    cudaMemcpy(d_input, h_input, size, cudaMemcpyHostToDevice);

    dim3 blockSize(BLOCK_SIZE, BLOCK_SIZE);
    dim3 gridSize((width + BLOCK_SIZE - 1) / BLOCK_SIZE, (height + BLOCK_SIZE - 1) / BLOCK_SIZE);

    convolve2D<<<gridSize, blockSize>>>(d_input, d_output, width, height);

    cudaMemcpy(h_output, d_output, size, cudaMemcpyDeviceToHost);

    // Clean up
    cudaFree(d_input);
    cudaFree(d_output);
    delete[] h_input;
    delete[] h_output;

    return 0;
}

