    vector<int> fibs = fibonacci(10);
    for (int num : fibs) {
        cout << num << " ";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

std::pair<int, int> findMinMax(const std::vector<int>& arr) {
    if (arr.empty()) {
        return {0, 0};  // Return a pair of zeros if the array is empty
    }
    int minVal = arr[0];  // Initialize min and max with the first element
    int maxVal = arr[0];
    for (int num : arr) {
        if (num < minVal) {
            minVal = num;
        }
        if (num > maxVal) {
            maxVal = num;
        }
    }
    return {minVal, maxVal};
