using namespace std;

// Define the structure for the singly linked list node
struct SinglyNode {
    int data;
    SinglyNode* next;
};

// Define the structure for the doubly linked list node
struct DoublyNode {
    int data;
    DoublyNode* next;
    DoublyNode* prev;
};

// Function to create a new node for the singly linked list
SinglyNode* createSinglyNode(int data) {
    SinglyNode* newNode = new SinglyNode();
    newNode->data = data;
    newNode->next = nullptr;
    return newNode;
}

// Function to create a new node for the doubly linked list
DoublyNode* createDoublyNode(int data) {
    DoublyNode* newNode = new DoublyNode();
    newNode->data = data;
    newNode->next = nullptr;
    newNode->prev = nullptr;
    return newNode;
}

// Function to convert a singly linked list to a doubly linked list
DoublyNode* convertToDoublyLinkedList(SinglyNode* head) {
    if (head == nullptr) {
        return nullptr;
    }

    DoublyNode* doublyHead = nullptr;
    DoublyNode* currentDoubly = nullptr;
    SinglyNode* currentSingly = head;

    while (currentSingly != nullptr) {
        DoublyNode* newNode = createDoublyNode(currentSingly->data);

        if (doublyHead == nullptr) {
            doublyHead = newNode;
            currentDoubly = newNode;
        } else {
            currentDoubly->next = newNode;
            newNode->prev = currentDoubly;
            currentDoubly = newNode;
        }

        currentSingly = currentSingly->next;
    }

    return doublyHead;
}

// Function to print the doubly linked list
void printDoublyLinkedList(DoublyNode* head) {
    DoublyNode* current = head;
    while (current != nullptr) {
        cout << current->data << " ";
        current = current->next;
    }
    cout << endl;
}

// Function to print the doubly linked list in reverse
void printDoublyLinkedListReverse(DoublyNode* head) {
    if (head == nullptr) {
        return;
    }
    DoublyNode* current = head;
    while (current->next != nullptr) {
        current = current->next;
    }
    while (current != nullptr) {
        cout << current->data << " ";
        current = current->prev;
    }
    cout << endl;
}

int main() {
    // Create a singly linked list: 1 -> 2 -> 3 -> 4
    SinglyNode* head = createSinglyNode(1);
    head->next = createSinglyNode(2);
    head->next->next = createSinglyNode(3);
    head->next->next->next = createSinglyNode(4);

    // Convert the singly linked list to a doubly linked list
    DoublyNode* doublyHead = convertToDoublyLinkedList(head);

    // Print the doubly linked list
    cout << "Doubly Linked List: ";
    printDoublyLinkedList(doublyHead);

    // Print the doubly linked list in reverse
    cout << "Doubly Linked List in Reverse: ";
    printDoublyLinkedListReverse(doublyHead);

    return 0;
}

