bool isHappy(int n) {
    std::unordered_set<int> seen;
    while (n != 1 && seen.find(n) == seen.end()) {
        seen.insert(n);
        int next = 0;
        while (n > 0) {
            int digit = n % 10;
            next += digit * digit;
            n /= 10;
        }
        n = next;
    }
    return n == 1;
}

