#define SERVER_PORT htons(50007)

int main() {
    int serverSock = socket(AF_INET, SOCK_STREAM, 0); 

    if (serverSock < 0) {
        perror("ERROR opening socket");
        exit(1);
    }

    sockaddr_in serverAddr;
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = SERVER_PORT;
    serverAddr.sin_addr.s_addr = INADDR_ANY;

    if (bind(serverSock, (struct sockaddr *)&serverAddr, sizeof(sockaddr)) < 0) {
        perror("ERROR on binding");
        exit(1);
    }

    listen(serverSock, 5);

    sockaddr_in clientAddr;
    socklen_t sin_size = sizeof(struct sockaddr_in);

    int clientSock = accept(serverSock, (struct sockaddr*)&clientAddr, &sin_size);

    if (clientSock < 0) {
        perror("ERROR on accept");
        exit(1);
    }

    // Receive file size
    char sizeBuffer[10];
    int ret = recv(clientSock, sizeBuffer, sizeof(sizeBuffer), 0);
    if (ret < 0) {
        perror("ERROR reading file size from socket");
        exit(1);
    }
    sizeBuffer[ret] = '\0';
    int fileSize = atoi(sizeBuffer);

    FILE* output = fopen("test.jpeg", "wb");

    unsigned int readBytes = 0;

    while (readBytes < fileSize) {
        std::size_t buffer_size = 1024;
        char buffer[1024];

        ret = recv(clientSock, buffer, buffer_size, 0);
        if (ret <= 0) {
            perror("ERROR reading from socket");
            exit(1);    
        }

        fwrite(buffer, sizeof(char), ret, output);    
        readBytes += ret;    
    }

    fclose(output);

    close(serverSock);
    return 0;
}

