class Solution {
public:
    Node* connect(Node* root) {
        if (!root) return root;

        Node* leftmost = root;

        while (leftmost) {
            Node* current = leftmost;
            Node* dummy = new Node(0); // Dummy node to help with the next level
            Node* prev = dummy;

            while (current) {
                if (current->left) {
                    prev->next = current->left;
                    prev = prev->next;
                }
                if (current->right) {
                    prev->next = current->right;
                    prev = prev->next;
                }
                current = current->next;
            }

            leftmost = dummy->next; // Move to the next level
            delete dummy; // Clean up the dummy node
        }

        return root;
    }
};

