void imagePickerAndroid::handleActivityResult(int receiverRequestCode, int resultCode, const QAndroidJniObject &data)
{
    jint RESULT_OK = QAndroidJniObject::getStaticField<jint>("android/app/Activity", "RESULT_OK");
    if (receiverRequestCode == 101 && resultCode == RESULT_OK) {
        QAndroidJniObject uri = data.callObjectMethod("getData", "()Landroid/net/Uri;");
        if (uri.isValid()) {
            QAndroidJniObject contentResolver = QtAndroid::androidActivity().callObjectMethod("getContentResolver", "()Landroid/content/ContentResolver;");
            QAndroidJniObject filePathColumn = QAndroidJniObject::fromString("_data");
            QAndroidJniObject cursor = contentResolver.callObjectMethod("query", "(Landroid/net/Uri;[Ljava/lang/String;Ljava/lang/String;[Ljava/lang/String;Ljava/lang/String;)Landroid/database/Cursor;",
                                          uri.object<jobject>(),
                                          QAndroidJniObject::fromString("_data").object<jobjectArray>(),
                                          nullptr,
                                          nullptr,
                                          nullptr);

            if (cursor.isValid()) {
                jint columnIndex = cursor.callMethod<jint>("getColumnIndexOrThrow", "(Ljava/lang/String;)I", filePathColumn.object<jstring>());
                cursor.callMethod<jboolean>("moveToFirst", "()Z");
                QAndroidJniObject filePath = cursor.callObjectMethod("getString", "(I)Ljava/lang/String;", columnIndex);
                QString imagemCaminho = filePath.toString();
                cursor.callMethod<void>("close", "()V");
                emit imagemCaminhoSignal(imagemCaminho);
                qDebug() << imagemCaminho;
            } else {
                qDebug() << "Cursor is not valid";
            }
        } else {
            qDebug() << "Uri is not valid";
        }
    } else {
        qDebug() << "Caminho errado";
    }
}

