// Function to check if a character is an operator
bool isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/' || c == '^';
}

// Function to get the precedence of an operator
int precedence(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        case '^':
            return 3;
        default:
            return 0;
    }
}

// Function to convert infix to postfix
std::string infixToPostfix(const std::string& infix) {
    std::stack<char> stack;
    std::string postfix;
    for (char c : infix) {
        if (std::isdigit(c)) {
            postfix += c;
        } else if (isOperator(c)) {
            while (!stack.empty() && precedence(stack.top()) >= precedence(c)) {
                postfix += stack.top();
                stack.pop();
            }
            stack.push(c);
        } else if (c == '(') {
            stack.push(c);
        } else if (c == ')') {
            while (!stack.empty() && stack.top() != '(') {
                postfix += stack.top();
                stack.pop();
            }
            if (stack.empty() || stack.top() != '(') {
                throw std::runtime_error("Mismatched parentheses");
            }
            stack.pop();
        }
    }
    while (!stack.empty()) {
        if (stack.top() == '(') {
            throw std::runtime_error("Mismatched parentheses");
        }
        postfix += stack.top();
        stack.pop();
    }
    return postfix;
}

// Function to evaluate a postfix expression
double evaluatePostfix(const std::string& postfix) {
    std::stack<double> stack;
    for (char c : postfix) {
        if (std::isdigit(c)) {
            stack.push(c - '0');
        } else if (isOperator(c)) {
            if (stack.size() < 2) {
                throw std::runtime_error("Invalid expression");
            }
            double b = stack.top(); stack.pop();
            double a = stack.top(); stack.pop();
            switch (c) {
                case '+': stack.push(a + b); break;
                case '-': stack.push(a - b); break;
                case '*': stack.push(a * b); break;
                case '/': 
                    if (b == 0) throw std::runtime_error("Division by zero");
                    stack.push(a / b); 
                    break;
                case '^': stack.push(std::pow(a, b)); break;
            }
        }
    }
    if (stack.size() != 1) {
        throw std::runtime_error("Invalid expression");
    }
    return stack.top();
}

// Function to evaluate a mathematical expression from a string
double evaluateExpression(const std::string& expression) {
    std::string postfix = infixToPostfix(expression);
    return evaluatePostfix(postfix);
}

int main() {
    std::string expression = "3 + 5 * (2 - 4)";
    try {
        double result = evaluateExpression(expression);
        std::cout << "Result: " << result << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}

#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/bio.h>
#include <openssl/buffer.h>
#include <string>
#include <iostream>

std::string base64_encode(const unsigned char* data, size_t length) {
    BIO *bio, *b64;
    BUF_MEM *bufferPtr;

    b64 = BIO_new(BIO_f_base64());
    bio = BIO_new(BIO_s_mem());
    bio = BIO_push(b64, bio);

    BIO_set_flags(bio, BIO_FLAGS_BASE64_NO_NL); //Ignore newlines - write everything in one line
    BIO_write(bio, data, length);
    BIO_flush(bio);
    BIO_get_mem_ptr(bio, &bufferPtr);
    BIO_set_close(bio, BIO_NOCLOSE);
    BIO_free_all(bio);

    std::string base64(bufferPtr->data, bufferPtr->length);
    BUF_MEM_free(bufferPtr);

    return base64;
}

int main() {
    std::string key = "0123456789abcdef"; // 16 bytes key
    std::string iv = "0123456789abcdef"; // 16 bytes IV
    std::string plaintext = "Hello, World!";

    unsigned char keyData[AES_BLOCK_SIZE];
    unsigned char ivData[AES_BLOCK_SIZE];
    std::copy(key.begin(), key.end(), keyData);
    std::copy(iv.begin(), iv.end(), ivData);

    EVP_CIPHER_CTX *ctx;
    unsigned char ciphertext[128];
    int len;
    int ciphertext_len;

    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, keyData, ivData);
    EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*)plaintext.c_str(), plaintext.length());
    ciphertext_len = len;
    EVP_EncryptFinal_ex(ctx, ciphertext + len, &len);
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    std::string encryptedText = base64_encode(ciphertext, ciphertext_len);

    std::cout << "Encrypted: " + encryptedText << std::endl;

    return 0;
}

