#include <winsock2.h>
#include <windows.h>
#include <iostream>

#pragma comment(lib, "ws2_32.lib")

void OnReadComplete(SOCKET sock, DWORD bytesTransferred);
void OnWriteComplete(SOCKET sock, DWORD bytesTransferred);

int main() {
    WSADATA wsaData;
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
        std::cerr << "Failed to initialize Winsock" << std::endl;
        return 1;
    }

    SOCKET clientSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (clientSocket == INVALID_SOCKET) {
        std::cerr << "Failed to create socket" << std::endl;
        WSACleanup();
        return 1;
    }

    sockaddr_in serverAddr;
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(12345);
    serverAddr.sin_addr.s_addr = inet_addr("127.0.0.1");

    if (connect(clientSocket, (sockaddr*)&serverAddr, sizeof(serverAddr)) == SOCKET_ERROR) {
        std::cerr << "Failed to connect to server" << std::endl;
        closesocket(clientSocket);
        WSACleanup();
        return 1;
    }

    WSABUF readBuffer;
    char readData[1024];
    readBuffer.buf = readData;
    readBuffer.len = sizeof(readData);

    DWORD bytesTransferred;
    DWORD flags = 0;
    WSAOVERLAPPED readOverlap = {0};
    readOverlap.hEvent = WSACreateEvent();

    if (WSARecv(clientSocket, &readBuffer, 1, &bytesTransferred, &flags, &readOverlap, NULL) == SOCKET_ERROR) {
        if (WSAGetLastError() != WSA_IO_PENDING) {
            std::cerr << "Failed to start read operation" << std::endl;
            WSACloseEvent(readOverlap.hEvent);
            closesocket(clientSocket);
            WSACleanup();
            return 1;
        }
    }

    HANDLE hEvents[2];
    hEvents[0] = readOverlap.hEvent;
    hEvents[1] = CreateEvent(NULL, TRUE, FALSE, NULL);

    while (true) {
        DWORD result = WaitForMultipleObjects(2, hEvents, FALSE, INFINITE);
        switch (result) {
            case WAIT_OBJECT_0:
                if (WSAGetOverlappedResult(clientSocket, &readOverlap, &bytesTransferred, FALSE, &flags)) {
                    OnReadComplete(clientSocket, bytesTransferred);
                } else {
                    std::cerr << "Read error" << std::endl;
                }
                // Restart the read operation
                if (WSARecv(clientSocket, &readBuffer, 1, &bytesTransferred, &flags, &readOverlap, NULL) == SOCKET_ERROR) {
                    if (WSAGetLastError() != WSA_IO_PENDING) {
                        std::cerr << "Failed to restart read operation" << stdendl;
                        break;
                    }
                }
                break;
            case WAIT_OBJECT_0 + 1:
                // Handle write completion
                OnWriteComplete(clientSocket, bytesTransferred);
                break;
            default:
                std::cerr << "WaitForMultipleObjects error" << std::endl;
                break;
        }
    }

    WSACloseEvent(readOverlap.hEvent);
    CloseHandle(hEvents[1]);
    closesocket(clientSocket);
    WSACleanup();

    return 0;
}

void OnReadComplete(SOCKET sock, DWORD bytesTransferred) {
    std::cout << "Received " << bytesTransferred << " bytes from server" << std::endl;
    // Process the received data
}

void OnWriteComplete(SOCKET sock, DWORD bytesTransferred) {
    std::cout << "Sent " << bytesTransferred << " bytes to server" << std::endl;
    // Handle the write completion
}

#include <iostream>
#include <vector>
#include <utility>
#include <climits>
#include <algorithm>

using namespace std;

vector<pair<int,int>> subarray(vector<int> A, int *value) {
    int n = A.size();

    vector<int> B(n); // Transforming the array to further simplify the problem
    for (int i = 0; i < n; i++) {
        B[i] = (i % 2 ? 1 : -1) * A[i];
    }

    // Start of the Kadane's Algorithm Logic
    vector<int> dp(n);
    vector<int> start_indices(n);
    dp[0] = B[0];
    start_indices[0] = 1;
    int max_val = dp[0];
    int index = 0; 

    for (int i = 1; i < n; ++i) {
        if (dp[i - 1] >= 0) {
            dp[i] = dp[i - 1] + B[i];
            start_indices[i] = start_indices[i - 1];
        } else {
            dp[i] = B[i];
            start_indices[i] = i + 1;
        }

        if (dp[i] > max_val) {
            max_val = dp[i];
            index = i;
        }
    }
    // End of the Kadane's Algorithm Logic

    int end_index = index + 1;
    int start_index = start_indices[index];

    // Extracting pairs resulting in highest non-zero negative value
    vector<pair<int, int>> result;
    *value = max_val;
    for (int i = start_index; i <= end_index; ++i) {
        result.push_back(make_pair(start_index, i));
    }

    return result;
}

int main() {
    vector<int> A = {-4, 6, -7, 2, 2};
    int value;
    vector<pair<int,int>> result = subarray(A, &value);

    cout << "Output Pairs: ";
    for (auto p : result) {
        cout << "(" << p.first << "," << p.second << "),";
    }
    cout << " value = " << value << endl;

    return 0;
}

