uint8_t playerX, playerY;

void drawMap() {
  for (int y = 0; y < sizeof(map1) / sizeof(map1[0]); y++) {
    for (int x = 0; x < strlen(map1[0]); x++) {
      char ch = map1[y][x];
      if (ch == '#') {
        display.fillRect(x * 6, y * 6, 6, 6, WHITE);
      }
    }
  }
}

void setup() {
  display.begin();
  display.setContrast(50);
  display.clearDisplay();

  // Initialize player position
  for (int y = 0; y < sizeof(map1) / sizeof(map1[0]); y++) {
    for (int x = 0; x < strlen(map1[0]); x++) {
      char ch = map1[y][x];
      if (ch == '+') {
        playerX = x;
        playerY = y;
      }
    }
  }
}

void drawPlayer() {
  display.fillRect(playerX * 6, playerY * 6, 6, 6, BLACK);
}

