#include <iostream>
#include <stack>
#include <string>
#include <cctype>
#include <stdexcept>

// Function to perform basic arithmetic operations
double applyOperation(double a, double b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': 
            if (b == 0) throw std::runtime_error("Division by zero");
            return a / b;
        default: throw std::runtime_error("Invalid operator");
    }
}

// Function to evaluate the expression
double evaluateExpression(const std::string& expression) {
    std::stack<double> numbers;
    std::stack<char> operations;

    for (size_t i = 0; i < expression.length(); i++) {
        if (expression[i] == ' ') continue; // Skip spaces

        // If the current character is a digit, read the full number
        if (std::isdigit(expression[i]) || (expression[i] == '-' && (i == 0 || std::isspace(expression[i-1])))) {
            double val = 0;
            bool isNegative = expression[i] == '-';
            if (isNegative) i++;
            while (i < expression.length() && std::isdigit(expression[i])) {
                val = val * 10 + (expression[i] - '0');
                i++;
            }
            if (isNegative) val = -val;
            numbers.push(val);
            i--; // Adjust for the while loop increment
        } else if (expression[i] == '(') {
            operations.push(expression[i]);
        } else if (expression[i] == ')') {
            while (!operations.empty() && operations.top() != '(') {
                double val2 = numbers.top(); numbers.pop();
                double val1 = numbers.top(); numbers.pop();
                char op = operations.top(); operations.pop();
                numbers.push(applyOperation(val1, val2, op));
            }
            operations.pop(); // Pop '('
        } else if (expression[i] == '+' || expression[i] == '-' || expression[i] == '*' || expression[i] == '/') {
            while (!operations.empty() && ((expression[i] != '*' && expression[i] != '/') || (operations.top() == '*' || operations.top() == '/'))) {
                double val2 = numbers.top(); numbers.pop();
                double val1 = numbers.top(); numbers.pop();
                char op = operations.top(); operations.pop();
                numbers.push(applyOperation(val1, val2, op));
            }
            operations.push(expression[i]);
        } else {
            throw std::runtime_error("Invalid character in expression");
        }
    }

    // Apply any remaining operations
    while (!operations.empty()) {
        double val2 = numbers.top(); numbers.pop();
        double val1 = numbers.top(); numbers.pop();
        char op = operations.top(); operations.pop();
        numbers.push(applyOperation(val1, val2, op));
    }

    return numbers.top();
}

int main() {
    std::string expression = "3 + 5 * (2 - 4)";
    try {
        double result = evaluateExpression(expression);
        std::cout << "Result: " << result << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

int levenshteinDistance(const std::string &str1, const std::string &str2) {
    int n = str1.size();
    int m = str2.size();
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(m + 1, 0));

    for (int i = 0; i <= n; ++i) dp[i][0] = i;
    for (int j = 0; j <= m; ++j) dp[0][j] = j;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (str1[i - 1] == str2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 1 + std::min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});
            }
        }
    }

    return dp[n][m];
}

int main() {
    std::string str1 = "kitten";
    std::string str2 = "sitting";
    int distance = levenshteinDistance(str1, str2);
    std::cout << "Levenshtein Distance: " << distance << std::endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int longestUpDownSubsequence(vector<int>& sequence) {
    int n = sequence.size();
    if (n <= 1) {
        return n;
    }

    // dpUp[i] stores the length of the longest increasing subsequence ending at index i
    // dpDown[i] stores the length of the longest decreasing subsequence starting at index i
    vector<int> dpUp(n, 1);
    vector<int> dpDown(n, 1);

    int maxLength = 1;
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (sequence[i] > sequence[j]) {
                dpUp[i] = max(dpUp[i], dpDown[j] + 1);
            } else if (sequence[i] < sequence[j]) {
                dpDown[i] = max(dpDown[i], dpUp[j] + 1);
            }
        }
        maxLength = max(maxLength, max(dpUp[i], dpDown[i]));
    }

    return maxLength;
}

int main() {
    int n;
    cin >> n;

    vector<int> sequence(n);
    for (int i = 0; i < n; i++) {
        cin >> sequence[i];
    }

    int longestLength = longestUpDownSubsequence(sequence);
    cout << longestLength << endl;

    return 0;
}

