struct DataStruct
{
    unsigned char* data;
    int len;
};

extern "C" DLLAPI int API_ReadFile(const wchar_t* filename, DataStruct** outData)
{
    // Example implementation: Allocate memory and read file
    FILE* file = nullptr;
    errno_t err = _wfopen_s(&file, filename, L"rb");
    if (err != 0 || file == nullptr)
    {
        return -1; // Error opening file
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    *outData = new DataStruct();
    (*outData)->data = new unsigned char[fileSize];
    (*outData)->len = fileSize;

    size_t bytesRead = fread((*outData)->data, 1, fileSize, file);
    fclose(file);

    if (bytesRead != fileSize)
    {
        delete[] (*outData)->data;
        delete *outData;
        return -2; // Error reading file
    }

    return 0; // Success
}

extern "C" DLLAPI void API_FreeData(DataStruct* data)
{
    if (data != nullptr)
    {
        delete[] data->data;
        delete data;
    }
}

#include <windows.h>
#include <tlhelp32.h>

BOOL InjectDLL(DWORD dwProcessId, const char* szDllPath) {
    HANDLE hProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, dwProcessId);
    if (hProcess == NULL) {
        return FALSE;
    }

    LPVOID pRemotePath = VirtualAllocEx(hProcess, NULL, strlen(szDllPath) + 1, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (pRemotePath == NULL) {
        CloseHandle(hProcess);
        return FALSE;
    }

    if (!WriteProcessMemory(hProcess, pRemotePath, (LPVOID)szDllPath, strlen(szDllPath) + 1, NULL)) {
        VirtualFreeEx(hProcess, pRemotePath, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return FALSE;
    }

    // LoadLibrary is a function that loads a DLL into a process.
    HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)GetProcAddress(GetModuleHandle("kernel32.dll"), "LoadLibraryA"), pRemotePath, 0, NULL);
    if (hThread == NULL) {
        VirtualFreeEx(hProcess, pRemotePath, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return FALSE;
    }

    WaitForSingleObject(hThread, INFINITE);
    DWORD dwExitCode;
    GetExitCodeThread(hThread, &dwExitCode);

    CloseHandle(hThread);
    VirtualFreeEx(hProcess, pRemotePath, 0, MEM_RELEASE);
    CloseHandle(hProcess);

    return (dwExitCode != 0);
}

