#include <iostream>
#include <string>
#include <unordered_map>

std::unordered_map<std::string, std::string> parseURLArguments(const std::string& url)
{
    std::unordered_map<std::string, std::string> dictionary;

    // Check if URL has parameters
    size_t pos = url.find("?");
    if (pos != std::string::npos) {
        std::string params = url.substr(pos + 1);

        // Split parameters by '&'
        size_t start = 0;
        while (start < params.length()) {
            size_t end = params.find("&", start);
            if (end == std::string::npos)
                end = params.length();

            std::string param = params.substr(start, end - start);

            // Split each parameter by '='
            size_t delimiter = param.find("=");
            if (delimiter != std::string::npos) {
                std::string key = param.substr(0, delimiter);
                std::string value = param.substr(delimiter + 1);

                // URL decode the parameter value (optional)
                // Replace '%20' with ' ' (optional)
                size_t percent = value.find("%20");
                while (percent != std::string::npos) {
                    value.replace(percent, 3, " ");
                    percent = value.find("%20", percent + 1);
                }

                dictionary[key] = value;
            }

            start = end + 1;
        }
    }

    return dictionary;
}

int main()
{
    std::string url = "http://www.example.com?name=John%20Doe&age=25&city=New%20York";

    std::unordered_map<std::string, std::string> result = parseURLArguments(url);

    // Print the dictionary
    for (const auto& pair : result) {
        std::cout << pair.first << ": " << pair.second << std::endl;
    }

    return 0;
}

#include <SFML/Graphics.hpp>
#include <SFML/Window.hpp>
#include <SFML/System.hpp>

const int WINDOW_WIDTH = 800;
const int WINDOW_HEIGHT = 600;
const float PADDLE_SPEED = 5.0f;
const float BALL_RADIUS = 10.0f;
const float BALL_SPEED = 3.0f;

class Paddle {
public:
    sf::RectangleShape shape;
    float speed;

    Paddle(float x, float y, float w, float h, float s) {
        shape.setPosition(x, y);
        shape.setSize({w, h});
        shape.setFillColor(sf::Color::White);
        speed = s;
    }

    void moveUp() {
        sf::Vector2f position = shape.getPosition();
        if (position.y > 0) {
            shape.move(0, -speed);
        }
    }

    void moveDown() {
        sf::Vector2f position = shape.getPosition();
        if (position.y + shape.getSize().y < WINDOW_HEIGHT) {
            shape.move(0, speed);
        }
    }
};

class Ball {
public:
    sf::CircleShape shape;
    sf::Vector2f direction;
    float speed;

    Ball(float x, float y, float r) {
        shape.setPosition(x, y);
        shape.setRadius(r);
        shape.setFillColor(sf::Color::White);
        direction = {1.0f, 1.0f};
        speed = BALL_SPEED;
    }

    void update() {
        sf::Vector2f position = shape.getPosition();
        position += direction * speed;
        if (position.x <= 0 || position.x + 2 * BALL_RADIUS >= WINDOW_WIDTH) {
            direction.x = -direction.x;
        }
        if (position.y <= 0 || position.y + 2 * BALL_RADIUS >= WINDOW_HEIGHT) {
            direction.y = -direction.y;
        }
        shape.setPosition(position);
    }
};

int main() {
    sf::RenderWindow window(sf::VideoMode(WINDOW_WIDTH, WINDOW_HEIGHT), "Pong");

    Paddle player1(50, WINDOW_HEIGHT / 2 - 50, 20, 100, PADDLE_SPEED);
    Paddle player2(WINDOW_WIDTH - 70, WINDOW_HEIGHT / 2 - 50, 20, 100, PADDLE_SPEED);
    Ball ball(WINDOW_WIDTH / 2 - BALL_RADIUS, WINDOW_HEIGHT / 2 - BALL_RADIUS, BALL_RADIUS);

    while (window.isOpen()) {
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed)
                window.close();
        }

        if (sf::Keyboard::isKeyPressed(sf::Keyboard::W)) player1.moveUp();
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::S)) player1.moveDown();
        // AI for player2
        if (ball.shape.getPosition().y > player2.shape.getPosition().y + 50) player2.moveDown();
        if (ball.shape.getPosition().y < player2.shape.getPosition().y + 50) player2.moveUp();

        ball.update();

        window.clear(sf::Color::Black);
        window.draw(player1.shape);
        window.draw(player2.shape);
        window.draw(ball.shape);
        window.display();
    }

    return 0;
}

#include <algorithm>
#include <cmath>

struct Node {
    int key;
    int height;
    Node* left;
    Node* right;
};

// Function to get the height of the tree
int height(Node* N) {
    if (N == NULL)
        return 0;
    return N->height;
}

// Function to create a new node
Node* newNode(int key) {
    Node* node = new Node();
    node->key = key;
    node->left = NULL;
    node->right = NULL;
    node->height = 1; // New node is initially added at leaf
    return(node);
}

// Function to right rotate subtree rooted with y
Node* rightRotate(Node* y) {
    Node* x = y->left;
    Node* T2 = x->right;

    // Perform rotation
    x->right = y;
    y->left = T2;

    // Update heights
    y->height = std::max(height(y->left), height(y->right)) + 1;
    x->height = std::max(height(x->left), height(x->right)) + 1;

    // Return new root
    return x;
}

// Function to left rotate subtree rooted with x
Node* leftRotate(Node* x) {
    Node* y = x->right;
    Node* T2 = y->left;

    // Perform rotation
    y->left = x;
    x->right = T2;

    // Update heights
    x->height = std::max(height(x->left), height(x->right)) + 1;
    y->height = std::max(height(y->left), height(y->right)) + 1;

    // Return new root
    return y;
}

// Get the balance factor of node N
int getBalance(Node* N) {
    if (N == NULL)
        return 0;
    return height(N->left) - height(N->right);
}

// Function to insert a node into the AVL tree
Node* insert(Node* node, int key) {
    // Perform the normal BST insertion
    if (node == NULL)
        return(newNode(key));

    if (key < node->key)
        node->left = insert(node->left, key);
    else if (key > node->key)
        node->right = insert(node->right, key);
    else // Equal keys are not allowed in BST
        return node;

    // Update height of this ancestor node
    node->height = 1 + std::max(height(node->left), height(node->right));

    // Get the balance factor of this ancestor node to check whether this node became unbalanced
    int balance = getBalance(node);

    // If this node becomes unbalanced, then there are 4 cases

    // Left Left Case
    if (balance > 1 && key < node->left->key)
        return rightRotate(node);

    // Right Right Case
    if (balance < -1 && key > node->right->key)
        return leftRotate(node);

    // Left Right Case
    if (balance > 1 && key > node->left->key) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }

    // Right Left Case
    if (balance < -1 && key < node->right->key) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    // Return the (unchanged) node pointer
    return node;
}

