// Function to print the Sudoku grid
void printGrid(int grid[N][N]) {
    for (int row = 0; row < N; row++) {
        for (int col = 0; col < N; col++)
            cout << grid[row][col] << " ";
        cout << endl;
    }
}

// Function to check if it's safe to place a number in a particular cell
bool isSafe(int grid[N][N], int row, int col, int num) {
    // Check if the number is already present in the current row
    for (int i = 0; i < N; i++)
        if (grid[row][i] == num)
            return false;

    // Check if the number is already present in the current column
    for (int i = 0; i < N; i++)
        if (grid[i][col] == num)
            return false;

    // Check if the number is already present in the current 3x3 sub-grid
    int startRow = row - row % 3;
    int startCol = col - col % 3;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            if (grid[i + startRow][j + startCol] == num)
                return false;

    return true;
}

// Function to solve the Sudoku puzzle using backtracking
bool solveSudoku(int grid[N][N]) {
    int row, col;
    bool isEmpty = false;
    for (row = 0; row < N; row++) {
        for (col = 0; col < N; col++) {
            if (grid[row][col] == 0) {
                isEmpty = true;
                break;
            }
        }
        if (isEmpty)
            break;
    }

    // If no empty cell is found, the puzzle is solved
    if (!isEmpty)
        return true;

    // Try placing numbers from 1 to 9 in the empty cell
    for (int num = 1; num <= 9; num++) {
        if (isSafe(grid, row, col, num)) {
            grid[row][col] = num;
            if (solveSudoku(grid))
                return true;
            grid[row][col] = 0; // undo the number if it doesn't work
        }
    }
    return false;
}

// Driver function
int main() {
    int grid[N][N];

    // Read the Sudoku puzzle from input
    cout << "Enter the Sudoku puzzle (0 for empty cells):\n";
    for (int row = 0; row < N; row++)
        for (int col = 0; col < N; col++)
            cin >> grid[row][col];

    // Solve the Sudoku puzzle
    if (solveSudoku(grid)) {
        cout << "Sudoku puzzle solved!\n";
        printGrid(grid);
    } else {
        cout << "No solution exists!\n";
    }

    return 0;
}

