// Precomputed masks for 2, 4, 8, 16, 32 bit repeating patterns
const uint64_t masks[] = {
    0xAAAAAAAAAAAAAAAA,  // 0101010101010101010101010101010101010101010101010101010101010101
    0xCCCCCCCCCCCCCCCC,  // 0011001100110011001100110011001100110011001100110011001100110011
    0xF0F0F0F0F0F0F0F0,  // 0000111100001111000011110000111100001111000011110000111100001111
    0xFF00FF00FF00FF00,  // 0000000011111111000000001111111100000000111111110000000011111111
    0xFFFF0000FFFF0000   // 0000000000000000111111111111111100000000000000001111111111111111
};

// Function to check if the 128-bit block matches a repeating pattern
bool isRepeatingPattern(uint64_t block[2], int patternLength, int& shift) {
    uint64_t mask = masks[patternLength / 2];
    uint64_t combinedBlock = (block[1] << 64) | block[0];

    for (int i = 0; i < patternLength; ++i) {
        uint64_t shiftedMask = (mask >> i) | (mask << (128 - i));
        if ((combinedBlock & shiftedMask) == (combinedBlock & (combinedBlock >> i))) {
            shift = i;
            return true;
        }
    }
    return false;
}

// Main function to identify the repeating pattern and its shift
std::pair<int, int> identifyPattern(uint64_t block[2]) {
    const int patternLengths[] = {2, 4, 8, 16, 32};
    int shift = 0;

    for (int length : patternLengths) {
        if (isRepeatingPattern(block, length, shift)) {
            return {length, shift};
        }
    }

    return {-1, -1}; // No matching pattern found
}

int main() {
    uint64_t block[2] = {0x00001111000011110000111100001111, 0x00001111000011110000111100001111};

    auto [patternLength, shift] = identifyPattern(block);

    if (patternLength != -1) {
        std::cout << "Pattern length: " << patternLength << ", Shift: " << shift << std::endl;
    } else {
        std::cout << "No matching pattern found." << std::endl;
    }

    return 0;
}

