int findLargestNumber(int arr[], int size) {
    if (size == 0) {
        return INT_MIN;  // Return the smallest possible integer if the array is empty
    }
    int largest = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

int main() {
    int array[] = {3, 5, 1, 8, 2};
    int size = sizeof(array) / sizeof(array[0]);
    std::cout << "The largest number is: " << findLargestNumber(array, size) << std::endl;
    return 0;
}

template<class C, typename... Args>
C* ECS::AddComponent(const uint32_t entityId, Args&&... args) {
    auto newComponentID = Component<C>::GetTypeID();

    if (componentMasks[entityId].HasComponent(newComponentID)) {
        return nullptr; // Component already exists for the entity
    }

    componentMasks[entityId].AddComponent(newComponentID);
    Archetype* newArchetype = nullptr;
    C* newComponent = nullptr;

    Record& record = entityArchetypeMap[entityId];
    Archetype* oldArchetype = record.archetype;

    newArchetype = GetOrCreateArchetype(entityId);

    if (oldArchetype) {
        MigrateEntityToArchetype(newArchetype, oldArchetype, entityId, std::forward<Args>(args)...);
    } else {
        AddFirstComponentToEntity(newArchetype, entityId, newComponentID, record, std::forward<Args>(args)...);
    }

    return newComponent;
}

