bool isPrime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i <= std::sqrt(n); i++) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    std::vector<int> primes;
    for (int n = 0; n <= 100; n++) {
        if (isPrime(n)) {
            primes.push_back(n);
        }
    }
    for (int prime : primes) {
