public:
    List(int n) : data(n) {}
    List(const List& other) : data(other.data) {}
    ~List() = default;
    T& operator[](int i) { return data[i]; }
    const T& operator[](int i) const { return data[i]; }

    template <typename U>
    List<U> fmap(std::function<U(T)> func) {
        List<U> result(data.size());
