float* d_velocities_x, *d_velocities_y, *d_velocities_z;

cudaMalloc(&d_positions_x, numParticles * sizeof(float));
cudaMalloc(&d_positions_y, numParticles * sizeof(float));
cudaMalloc(&d_positions_z, numParticles * sizeof(float));
cudaMalloc(&d_velocities_x, numParticles * sizeof(float));
cudaMalloc(&d_velocities_y, numParticles * sizeof(float));
cudaMalloc(&d_velocities_z, numParticles * sizeof(float));

cudaMemcpy(d_positions_x, positions_x, numParticles * sizeof(float), cudaMemcpyHostToDevice);
cudaMemcpy(d_positions_y, positions_y, numParticles * sizeof(float), cudaMemcpyHostToDevice);
cudaMemcpy(d_positions_z, positions_z, numParticles * sizeof(float), cudaMemcpyHostToDevice);
cudaMemcpy(d_velocities_x, velocities_x, numParticles * sizeof(float), cudaMemcpyHostToDevice);
cudaMemcpy(d_velocities_y, velocities_y, numParticles * sizeof(float), cudaMemcpyHostToDevice);
cudaMemcpy(d_velocities_z, velocities_z, numParticles * sizeof(float), cudaMemcpyHostToDevice);

// Free CPU memory
delete[] positions_x;
delete[] positions_y;
delete[] positions_z;
delete[] velocities_x;
delete[] velocities_y;
delete[] velocities_z;

// Kernel function
__global__ void updateParticles(float* positions_x, float* positions_y, float* positions_z,
                                float* velocities_x, float* velocities_y, float* velocities_z,
                                int numParticles, float deltaTime)
{
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    if (idx < numParticles) {
        positions_x[idx] += velocities_x[idx] * deltaTime;
        positions_y[idx] += velocities_y[idx] * deltaTime;
        positions_z[idx] += velocities_z[idx] * deltaTime;
    }
}

// Launch the kernel
int blockSize = 256;
int numBlocks = (numParticles + blockSize - 1) / blockSize;
updateParticles<<<numBlocks, blockSize>>>(d_positions_x, d_positions_y, d_positions_z,
                                          d_velocities_x, d_velocities_y, d_velocities_z,
                                          numParticles, deltaTime);

// Copy results back to CPU and free GPU memory
cudaMemcpy(positions_x, d_positions_x, numParticles * sizeof(float), cudaMemcpyDeviceToHost);
cudaMemcpy(positions_y, d_positions_y, numParticles * sizeof(float), cudaMemcpyDeviceToHost);
cudaMemcpy(positions_z, d_positions_z, numParticles * sizeof(float), cudaMemcpyDeviceToHost);

cudaFree(d_positions_x);
cudaFree(d_positions_y);
cudaFree(d_positions_z);
cudaFree(d_velocities_x);
cudaFree(d_velocities_y);
cudaFree(d_velocities_z);

// Reconstruct the structured objects
for (int i = 0; i < numParticles; ++i) {
    particles[i].position.x = positions_x[i];
    particles[i].position.y = positions_y[i];
    particles[i].position.z = positions_z[i];
}

// Free CPU memory
delete[] positions_x;
delete[] positions_y;
delete[] positions_z;
delete[] particles;

