typedef std::array<uint8_t, 3> Vec3B;
typedef std::array<int32_t, 3> Vec3I;

Vec3B v3bSpread(Vec3B const& source, Vec3B dest, int32_t drop) {
  // Convert uint8_t arrays to int32_t arrays
  Vec3I intSource = {source[0], source[1], source[2]};
  Vec3I intDest = {dest[0], dest[1], dest[2]};

  // Load the data into SIMD registers
  __m128i src = _mm_loadu_si128(reinterpret_cast<const __m128i*>(intSource.data()));
  __m128i dst = _mm_loadu_si128(reinterpret_cast<const __m128i*>(intDest.data()));
  __m128i dropVec = _mm_set1_epi32(drop);

  // Calculate the maximum value
  __m128i maxSrc = _mm_max_epi32(src, _mm_shuffle_epi32(src, 1));
  maxSrc = _mm_max_epi32(maxSrc, _mm_shuffle_epi32(maxSrc, 2));

  // Calculate the spread
  __m128i denom = maxSrc;
  __m128i spread = _mm_sub_epi32(src, _mm_mullo_epi32(_mm_div_epi32(src, denom), dropVec));

  // Clamp the result to the destination
  spread = _mm_max_epi32(spread, dst);

  // Store the result back to the array
  _mm_storeu_si128(reinterpret_cast<__m128i*>(intDest.data()), spread);

  // Convert back to uint8_t
  dest[0] = static_cast<uint8_t>(intDest[0]);
  dest[1] = static_cast<uint8_t>(intDest[1]);
  dest[2] = static_cast<uint8_t>(intDest[2]);

  return dest;
}

