void xxwrite(const unsigned char *buf, size_t wlen, FILE *fo)
{
    size_t xlen;

    for (; wlen > 0; wlen -= xlen, buf += xlen) {
        xlen = wlen;
        if (xlen > 1024)
            xlen = 1024;
        xlen = fwrite(buf, 1, xlen, fo);
        if (xlen != 1024 && ferror(fo)) {
            throw std::runtime_error("Error writing to stdout");
        }
        fflush(fo);
    }
}

int main(int argc, char **argv) {
    if (argc < 5) {
        std::cerr << "Usage: " << argv[0] << " totalbytes bytechunk height width" << std::endl;
        return 1;
    }

    long totalbytes = std::stol(argv[argc-4]);
    long bytechunk = std::stol(argv[argc-3]);
    long height = std::stol(argv[argc-2]);
    long width = std::stol(argv[argc-1]);
    long offset = totalbytes / sizeof(double) / 2;

    std::vector<double> data(totalbytes / sizeof(double));
    int columnindex = 0;
    size_t count = 0;

    // Read in data from pipe
    while (count < totalbytes) {
        size_t bytes_read = fread(&data[columnindex], 1, bytechunk, stdin);
        if (bytes_read != bytechunk && ferror(stdin)) {
            throw std::runtime_error("Error reading from stdin");
        }
        columnindex += bytechunk / sizeof(double);
        count += bytes_read;
    }

    // Calculate the data transform
    MutualInformation MI;
    MI.Initialize(data.data(), height, width, offset);
    MI.calcMI();
    count = 0;
    columnindex = 0;

    std::vector<double> output = MI.getOutput();
    while (count < totalbytes / 2) {
        size_t bytes_written = xxwrite((const unsigned char*)&output[columnindex], bytechunk, stdout);
        if (bytes_written != bytechunk) {
            throw std::runtime_error("Error writing to stdout");
        }
        count += bytes_written;
        columnindex += bytechunk / sizeof(double);
    }

    return 0;
}

int PixyInterpreter::get_frame(unsigned char *current_frame, int frame_size) {
    unsigned int size_frame = 8;          
    unsigned char *pixels;                
    int32_t response, fourcc;
    int8_t renderflags;
    int return_value;
    uint16_t width, height;
    uint32_t numPixels;

    return_value = pixy_command("stop", END_OUT_ARGS, &response, END_IN_ARGS);  
    printf("STOP returned %d response %d\n", return_value, response);

    response = 0;
    return_value = pixy_command("cam_getFrame", 0x01, 0x21, 0x02, 0, 0x02, 0, 0x02, 320, 0x02, 200, 0, &response, &fourcc, &renderflags, &width, &height, &numPixels, &pixels, 0);

    printf("getFrame returned %d response %d\n", return_value, response); 
    printf("returned w %d h %d npix %d\n", width, height, numPixels);  

    if (return_value != 0) return return_value;

    if (numPixels > frame_size) {
        printf("Error: Frame size is larger than the provided buffer size.\n");
        return -1;
    }

    memcpy(current_frame, pixels, numPixels);

    unsigned int i, j, ind, start;

    start = (height / 2) * width + width / 2;
    for (i = 0; i < size_frame; i++) {
        for (j = 0; j < size_frame; j++) {
            ind = i * width + j + start;
            printf(" %02x", current_frame[ind]);
        }
        printf("\n");
    }

    return_value = pixy_command("run", END_OUT_ARGS, &response, END_IN_ARGS);
    printf("START returned %d response %d\n", return_value, response);
    return numPixels;
}

void ToCppString(System::String^ input, char* output)
{
    // Convert System::String^ to std::string
    std::string temp = marshal_as<std::string>(input);
    // Copy the std::string to the caller-allocated buffer
    strcpy(output, temp.c_str());
}

void Foo(const char* input, char* output)
{
    // Convert const char* to System::String^
    System::String^ cli = ::ToCliString(input);

    if (cli == "abc")
    {
        MessageBox::Show("const char* -> CLI: OK");
    }

    // Convert System::String^ to const char* using the caller-allocated buffer
    ::ToCppString(cli, output);

    if (std::strcmp(output, "abc") == 0)
    {
        MessageBox::Show("CLI -> const char*: OK");
    }
    else if (std::strcmp(output, "") == 0)
    {
        MessageBox::Show("ToCppString returned empty string");
    }
    else
    {
        MessageBox::Show("ToCppString returned something else");
    }
}

