bool isPrime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    int count = 0;  // Counter for prime numbers found
    int number = 2; // Starting number to check for primality
    double sum = 0; // Sum of prime numbers
    double average; // Running average of prime numbers

    do {
        if (isPrime(number)) {
            count++;
            sum += number;
            average = sum / count;
            cout << "Prime number " << count << ": " << number << endl;
            cout << "Running average: " << average << endl;
        }
        number++;
    } while (count < 6);

    return 0;
}

