#include <cstdint>

uint64_t multiply_high(uint64_t i, uint64_t j) {
    uint32_t i_low = static_cast<uint32_t>(i);
    uint32_t i_high = static_cast<uint32_t>(i >> 32);
    uint32_t j_low = static_cast<uint32_t>(j);
    uint32_t j_high = static_cast<uint32_t>(j >> 32);

    uint64_t low_low = static_cast<uint64_t>(i_low) * j_low;
    uint64_t high_high = static_cast<uint64_t>(i_high) * j_high;
    uint64_t cross1 = static_cast<uint64_t>(i_high) * j_low;
    uint64_t cross2 = static_cast<uint64_t>(i_low) * j_high;

    uint64_t cross_sum = cross1 + cross2;
    uint64_t carry = (low_low >> 32) + (cross_sum >> 32);

    return high_high + (cross_sum << 32) + carry;
}

int main() {
    uint64_t i = 1234567890123456789ULL;
    uint64_t j = 9876543210987654321ULL;
    uint64_t high_part = multiply_high(i, j);
    // Print the result
    std::cout << "Higher part of the multiplication: " << high_part << std::endl;
    return 0;
}

