#include <iostream>
#include <chrono>
#include <vector>
#include <random>
#include <algorithm>

const size_t NUM_ITERATIONS = 10000000;
const size_t ARRAY_SIZE = 1024 * 1024; // 1MB
const size_t ALIGNMENT = 16;

void warmUp(std::vector<uint8_t>& data) {
    for (size_t i = 0; i < ARRAY_SIZE; i += ALIGNMENT) {
        data[i] = i % 256;
    }
}

void benchmarkAlignedAccess(std::vector<uint8_t>& data) {
    auto start = std::chrono::high_resolution_clock::now();
    for (size_t i = 0; i < NUM_ITERATIONS; ++i) {
        size_t index = (i * 16) % (ARRAY_SIZE - ALIGNMENT);
        uint32_t value = *reinterpret_cast<uint32_t*>(data.data() + index);
        // Use the value to prevent optimization
        std::cout << (value & 0xFF) << std::flush;
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();
    std::cout << "Aligned access took " << duration << " microseconds" << std::endl;
}

void benchmarkUnalignedAccess(std::vector<uint8_t>& data) {
    auto start = std::chrono::high_resolution_clock::now();
    for (size_t i = 0; i < NUM_ITERATIONS; ++i) {
        size_t index = (i * 15) % (ARRAY_SIZE - ALIGNMENT); // Unaligned access
        uint32_t value = *reinterpret_cast<uint32_t*>(data.data() + index);
        // Use the value to prevent optimization
        std::cout << (value & 0xFF) << std::flush;
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();
    std::cout << "Unaligned access took " << duration << " microseconds" << std::endl;
}

int main() {
    std::vector<uint8_t> data(ARRAY_SIZE, 0);
    warmUp(data);

    benchmarkAlignedAccess(data);
    benchmarkUnalignedAccess(data);

    return 0;
}

