   bool AssembleCode(const char* asmCode, unsigned char** outBytes, size_t* outSize) {
       std::string tempFile = "temp.asm";
       std::ofstream asmFile(tempFile);
       if (!asmFile.is_open()) {
           return false;
       }

       asmFile << asmCode;
       asmFile.close();

       std::string objFile = "temp.obj";
       std::string cmd = "nasm -f win32 " + tempFile + " -o " + objFile;
       system(cmd.c_str());

       std::ifstream objStream(objFile, std::ios::binary | std::ios::ate);
       if (!objStream.is_open()) {
           return false;
       }

       size_t size = objStream.tellg();
       std::vector<unsigned char> bytes(size);
       objStream.seekg(0, std::ios::beg);
       objStream.read((char*)bytes.data(), size);
       objStream.close();

       *outBytes = new unsigned char[size];
       std::copy(bytes.begin(), bytes.end(), *outBytes);
       *outSize = size;

       return true;
   }

