// C++ class
class Point {
public:
    Point(int x, int y) : x_(x), y_(y) {}
    int x() const { return x_; }
    void set_x(int x) { x_ = x; }
    int y() const { return y_; }
    void set_y(int y) { y_ = y; }

private:
    int x_;
    int y_;
};

// Accessor functions for x
void GetPointX(Local<String> property, const PropertyCallbackInfo<Value>& info) {
    Point* point = static_cast<Point*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    info.GetReturnValue().Set(Number::New(info.GetIsolate(), point->x()));
}

void SetPointX(Local<String> property, Local<Value> value, const PropertyCallbackInfo<void>& info) {
    Point* point = static_cast<Point*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    point->set_x(value->NumberValue(info.GetIsolate()->GetCurrentContext()).ToChecked());
}

// Accessor functions for y
void GetPointY(Local<String> property, const PropertyCallbackInfo<Value>& info) {
    Point* point = static_cast<Point*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    info.GetReturnValue().Set(Number::New(info.GetIsolate(), point->y()));
}

void SetPointY(Local<String> property, Local<Value> value, const PropertyCallbackInfo<void>& info) {
    Point* point = static_cast<Point*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    point->set_y(value->NumberValue(info.GetIsolate()->GetCurrentContext()).ToChecked());
}

int main() {
    // Initialize V8
    v8::V8::InitializeICUDefaultLocation("");
    v8::V8::InitializeExternalStartupData("");
    std::unique_ptr<v8::Platform> platform = v8::platform::NewDefaultPlatform();
    v8::V8::InitializePlatform(platform.get());
    v8::V8::Initialize();

    // Create a new Isolate and enter its scope
    Isolate* isolate = Isolate::New();
    {
        Isolate::Scope isolate_scope(isolate);
        HandleScope handle_scope(isolate);
        Local<Context> context = Context::New(isolate);
        Context::Scope context_scope(context);

        // Create an ObjectTemplate for the Point class
        Local<ObjectTemplate> point_templ = ObjectTemplate::New(isolate);
        point_templ->SetInternalFieldCount(1); // Reserve one internal field for the C++ pointer

        // Set up accessors
        point_templ->SetAccessor(String::NewFromUtf8(isolate, "x").ToLocalChecked(), GetPointX, SetPointX);
        point_templ->SetAccessor(String::NewFromUtf8(isolate, "y").ToLocalChecked(), GetPointY, SetPointY);

        // Create a new Point instance
        Point* point = new Point(10, 20);

        // Create a new JavaScript object and set the internal field to the C++ pointer
        Local<Object> point_obj = point_templ->NewInstance(context).ToLocalChecked();
        point_obj->SetAlignedPointerInInternalField(0, point);

        // Expose the JavaScript object to the global scope
        context->Global()->Set(context, String::NewFromUtf8(isolate, "point").ToLocalChecked(), point_obj).Check();

        // Run JavaScript code
        Local<String> source = String::NewFromUtf8(isolate, "point.x = point.y * 2; console.log(point.x);").ToLocalChecked();
        Local<Script> script = Script::Compile(context, source).ToLocalChecked();
        Local<Value> result = script->Run(context).ToLocalChecked();

        // Clean up
        delete point;
    }

    // Dispose of the Isolate
    isolate->Dispose();
    v8::V8::Dispose();
    v8::V8::ShutdownPlatform();
    return 0;
}

