#include <cuda_runtime.h>
#include <opencv2/opencv.hpp>

__global__ void bayerToRGB(const unsigned char* bayer, unsigned char* rgb, int width, int height) {
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    if (x >= width || y >= height) return;

    int idx = y * width + x;
    int idx_rgb = idx * 3;

    // Assume the input is a GRBG pattern
    if (x % 2 == 0) {
        if (y % 2 == 0) {
            // G (Green)
            rgb[idx_rgb] = bayer[idx];
            rgb[idx_rgb + 1] = (x < width - 1) ? (bayer[idx + 1] + bayer[idx + width + 1]) / 2 : bayer[idx + 1];
            rgb[idx_rgb + 2] = (y < height - 1) ? (bayer[idx + width] + bayer[idx + width + 1]) / 2 : bayer[idx + width];
        } else {
            // R (Red)
            rgb[idx_rgb] = (x < width - 1) ? (bayer[idx + 1] + bayer[idx + width - 1]) / 2 : bayer[idx + 1];
            rgb[idx_rgb + 1] = (x < width - 1 && y < height - 1) ? (bayer[idx + width] + bayer[idx + width + 1] + bayer[idx - width] + bayer[idx - width + 1]) / 4 : bayer[idx];
            rgb[idx_rgb + 2] = bayer[idx];
        }
    } else {
        if (y % 2 == 0) {
            // B (Blue)
            rgb[idx_rgb] = (y < height - 1) ? (bayer[idx + width] + bayer[idx + width - 1]) / 2 : bayer[idx + width];
            rgb[idx_rgb + 1] = (x > 0 && y < height - 1) ? (bayer[idx + width] + bayer[idx + width - 1] + bayer[idx - width] + bayer[idx - width - 1]) / 4 : bayer[idx];
            rgb[idx_rgb + 2] = bayer[idx];
        } else {
            // G (Green)
            rgb[idx_rgb] = bayer[idx];
            rgb[idx_rgb + 1] = (x > 0) ? (bayer[idx - 1] + bayer[idx + width - 1]) / 2 : bayer[idx - 1];
            rgb[idx_rgb + 2] = (y > 0) ? (bayer[idx - width] + bayer[idx - width - 1]) / 2 : bayer[idx - width];
        }
    }
}

void bayerToRGB_GPU(const cv::Mat& bayer, cv::Mat& rgb) {
    int width = bayer.cols;
    int height = bayer.rows;
    int size = width * height * 3;

    unsigned char* d_bayer, *d_rgb;
    cudaMalloc(&d_bayer, bayer.total() * bayer.elemSize());
    cudaMalloc(&d_rgb, size);

    cudaMemcpy(d_bayer, bayer.ptr(), bayer.total() * bayer.elemSize(), cudaMemcpyHostToDevice);

    dim3 blockSize(16, 16);
    dim3 gridSize((width + blockSize.x - 1) / blockSize.x, (height + blockSize.y - 1) / blockSize.y);

    bayerToRGB<<<gridSize, blockSize>>>(d_bayer, d_rgb, width, height);

    rgb.create(height, width, CV_8UC3);
    cudaMemcpy(rgb.ptr(), d_rgb, size, cudaMemcpyDeviceToHost);

    cudaFree(d_bayer);
    cudaFree(d_rgb);
}

int main() {
    cv::Mat bayer = cv::imread("bayer.png", cv::IMREAD_GRAYSCALE);
    cv::Mat rgb;

    bayerToRGB_GPU(bayer, rgb);

    cv::imwrite("rgb.png", rgb);

    return 0;
}

#include <vector>
using namespace std;

void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
    int i = m - 1; // Pointer for nums1
    int j = n - 1; // Pointer for nums2
    int k = m + n - 1; // Pointer for the end of the merged array

    // Merge in reverse order
    while (i >= 0 && j >= 0) {
        if (nums1[i] > nums2[j]) {
            nums1[k] = nums1[i];
            // Skip duplicates in nums1
            while (i > 0 && nums1[i] == nums1[i - 1]) i--;
            i--;
        } else if (nums1[i] < nums2[j]) {
            nums1[k] = nums2[j];
            // Skip duplicates in nums2
            while (j > 0 && nums2[j] == nums2[j - 1]) j--;
            j--;
        } else {
            nums1[k] = nums1[i];
            k--;
            nums1[k] = nums2[j];
            // Skip duplicates in both nums1 and nums2
            while (i > 0 && nums1[i] == nums1[i - 1]) i--;
            i--;
            while (j > 0 && nums2[j] == nums2[j - 1]) j--;
            j--;
        }
        k--;
    }

    // Copy remaining elements from nums2, if any
    while (j >= 0) {
        nums1[k] = nums2[j];
        // Skip duplicates in nums2
        while (j > 0 && nums2[j] == nums2[j - 1]) j--;
        j--;
        k--;
    }

    // Ensure the resulting vector has no more than m + n elements
    nums1.resize(m + n);
}

// Example usage
int main() {
    vector<int> nums1 = {1, 2, 3, 0, 0, 0};
    int m = 3;
    vector<int> nums2 = {2, 5, 6};
    int n = 3;
    merge(nums1, m, nums2, n);
    for (int num : nums1) {
        cout << num << " ";
    }
    return 0;
}

