class Employee {
public:
    // Constructor
    Employee(int id, std::string name, std::string position, double salary)
        : id(id), name(name), position(position), salary(salary) {}

    // Getters
    int getID() const { return id; }
    std::string getName() const { return name; }
    std::string getPosition() const { return position; }
    double getSalary() const { return salary; }

    // Setters
    void setID(int id) { this->id = id; }
    void setName(std::string name) { this->name = name; }
    void setPosition(std::string position) { this->position = position; }
    void setSalary(double salary) { this->salary = salary; }

private:
    int id;
    std::string name;
    std::string position;
    double salary;
};

class EmployeeManager {
public:
    // Add an employee
    void addEmployee(const Employee& employee) {
        employees.push_back(employee);
    }

    // Remove an employee by ID
    bool removeEmployee(int id) {
        for (auto it = employees.begin(); it != employees.end(); ++it) {
            if (it->getID() == id) {
                employees.erase(it);
                return true;
            }
        }
        return false;
    }

    // Display all employees
    void displayEmployees() const {
        for (const auto& employee : employees) {
            std::cout << "ID: " << employee.getID() << ", Name: " << employee.getName()
                      << ", Position: " << employee.getPosition() << ", Salary: " << employee.getSalary() << std::endl;
        }
    }

private:
    std::vector<Employee> employees;
};

int main() {
    EmployeeManager manager;

    // Adding employees
    manager.addEmployee(Employee(1, "John Doe", "Software Engineer", 75000.0));
    manager.addEmployee(Employee(2, "Jane Smith", "Project Manager", 80000.0));
    manager.addEmployee(Employee(3, "Alice Johnson", "Data Analyst", 65000.0));

    // Displaying all employees
    std::cout << "Employee List:" << std::endl;
    manager.displayEmployees();

    // Removing an employee
    int idToRemove = 2;
    if (manager.removeEmployee(idToRemove)) {
        std::cout << "Employee with ID " << idToRemove << " removed." << std::endl;
    } else {
        std::cout << "Employee with ID " << idToRemove << " not found." << std::endl;
    }

    // Displaying all employees after removal
    std::cout << "\nEmployee List after removal:" << std::endl;
    manager.displayEmployees();

    return 0;
}

