#include <iostream>
#include <cstring>

using namespace std;

const int BOARD_SIZE = 8;
char board[BOARD_SIZE][BOARD_SIZE];

void initialize_board() {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (i == 1) board[i][j] = 'P'; // White pawn
            else if (i == 6) board[i][j] = 'p'; // Red pawn
            else board[i][j] = '.';
        }
    }
}

bool is_valid_move(int x1, int y1, int x2, int y2) {
    if (x2 < 0 || x2 >= BOARD_SIZE || y2 < 0 || y2 >= BOARD_SIZE) return false;
    if (board[x1][y1] == 'P' && (x1 - x2 != 1 || (abs(y1 - y2) > 1 || (board[x2][y2] != '.' && y1 == y2))))
        return false;
    if (board[x1][y1] == 'p' && (x2 - x1 != 1 || (abs(y1 - y2) > 1 || (board[x2][y2] != '.' && y1 == y2))))
        return false;

    return true;
}

void move_piece(int x1, int y1, int x2, int y2) {
    if (is_valid_move(x1, y1, x2, y2)) {
        board[x2][y2] = board[x1][y1];
        board[x1][y1] = '.';
    }
}

void print_board() {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            cout << board[i][j] << " ";
        }
        cout << endl;
    }
}

int main() {
    int x1, y1, x2, y2;
    initialize_board();
    print_board();

    while (true) {
        cin >> x1 >> y1 >> x2 >> y2;
        move_piece(x1, y1, x2, y2);
        print_board();
    }

    return 0;
}

#include <portaudio.h>
   #include <math.h>
   #include <iostream>

   #define SAMPLE_RATE (44100)
   #define FRAMES_PER_BUFFER (64)
   #define NOTE_DURATION (2.0) // seconds

   typedef struct
   {
       double frequency;
       double phase;
   } paTestData;

   int generateSineWave(const void *inputBuffer, void *outputBuffer,
                        unsigned long framesPerBuffer,
                        const PaStreamCallbackTimeInfo* timeInfo,
                        PaStreamCallbackFlags statusFlags,
                        void *userData)
   {
       paTestData *data = (paTestData *)userData;
       float *out = (float *)outputBuffer;
       for (unsigned int i = 0; i < framesPerBuffer; i++)
       {
           *out++ = 0.5 * sin(data->phase); // Sine wave
           data->phase += 2 * M_PI * data->frequency / SAMPLE_RATE;
           if (data->phase > 2 * M_PI) data->phase -= 2 * M_PI;
       }
       return paContinue;
   }

   int main()
   {
       PaError err;
       PaStream *stream;
       paTestData data;

       err = Pa_Initialize();
       if (err != paNoError) goto error;

       data.frequency = 440.0; // A4 note
       data.phase = 0.0;

       err = Pa_OpenDefaultStream(&stream, 0, 1, paFloat32, SAMPLE_RATE,
                                  FRAMES_PER_BUFFER, generateSineWave, &data);
       if (err != paNoError) goto error;

       err = Pa_StartStream(stream);
       if (err != paNoError) goto error;

       Pa_Sleep((int)(NOTE_DURATION * 1000));

       err = Pa_StopStream(stream);
       if (err != paNoError) goto error;

       err = Pa_CloseStream(stream);
       if (err != paNoError) goto error;

       Pa_Terminate();
       return 0;

   error:
       Pa_Terminate();
       fprintf(stderr, "An error occurred while using the portaudio stream\n");
       fprintf(stderr, "Error number: %d\n", err);
       fprintf(stderr, "Error message: %s\n", Pa_GetErrorText(err));
       return -1;
   }

