class Date {
private:
    int day;
    int month;
    int year;

public:
    // Constructor
    Date(int d, int m, int y) : day(d), month(m), year(y) {
        if (day < 1 || day > 31) throw std::invalid_argument("Invalid day");
        if (month < 1 || month > 12) throw std::invalid_argument("Invalid month");
        if (year < 0) throw std::invalid_argument("Invalid year");
    }

    // Getters
    int getDay() const { return day; }
    int getMonth() const { return month; }
    int getYear() const { return year; }

    // Comparison methods
    bool operator==(const Date& other) const {
        return (day == other.day && month == other.month && year == other.year);
    }

    bool operator<(const Date& other) const {
        if (year != other.year) return year < other.year;
        if (month != other.month) return month < other.month;
        return day < other.day;
    }

    bool operator>(const Date& other) const {
        return !(*this < other || *this == other);
    }

    // Additional comparison methods
    bool operator<=(const Date& other) const {
        return *this < other || *this == other;
    }

    bool operator>=(const Date& other) const {
        return *this > other || *this == other;
    }

    // String representation for easy testing
    std::string toString() const {
        return std::to_string(day) + "/" + std::to_string(month) + "/" + std::to_string(year);
    }
};

int main() {
    try {
        Date date1(10, 10, 2020);
        Date date2(10, 11, 2020);

        std::cout << "Date 1: " << date1.toString() << std::endl;
        std::cout << "Date 2: " << date2.toString() << std::endl;

        if (date1 == date2) {
            std::cout << "The dates are equal." << std::endl;
        } else if (date1 < date2) {
            std::cout << "Date 1 is earlier than Date 2." << std::endl;
        } else {
            std::cout << "Date 1 is later than Date 2." << std::endl;
        }
    } catch (const std::invalid_argument& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}

