}

void call_csharp_method(const std::string& assembly_path, const std::string& type_name, const std::string& method_name, const std::string& argument)
{
    hostfxr_handle host_context = nullptr;
    hostfxr_delegate create_delegate = nullptr;

    // Initialize the .NET runtime
    hostfxr_initialize_for_runtime_config(
        "path/to/hostfxr.dll",
        "path/to/app.runtimeconfig.json",
        nullptr,
        &host_context
    );

    // Load the assembly and create a delegate
    hostfxr_runtime_info_get_runtime_delegate(
        host_context,
        "System.String::.op_Add(System.String,System.String)",
        &create_delegate
    );

    // Create the C# object and call the method
    void* pCSharpObject = nullptr;
    hostfxr_runtime_info_load_assembly_and_get_function_pointer(
        host_context,
        assembly_path.c_str(),
        type_name.c_str(),
        method_name.c_str(),
        &pCSharpObject
    );

    // Call the method
    auto result = reinterpret_cast<std::string(*)(const std::string&)>(pCSharpObject)(argument);
    std::cout << result << std::endl;

    // Clean up
    hostfxr_close(host_context);
}

