class DatabaseTask : public QRunnable {
public:
    DatabaseTask(const QString &query, const QVariantList &params)
        : m_query(query), m_params(params) {}

    void run() override {
        QMutexLocker locker(&m_mutex);
        QSqlDatabase db = QSqlDatabase::database("thread_pool_connection");

        if (!db.isOpen()) {
            db = QSqlDatabase::addDatabase("QSQLITE", "thread_pool_connection");
            db.setDatabaseName("path/to/your/database.db");
            if (!db.open()) {
                qDebug() << "Database error:" << db.lastError().text();
                return;
            }
        }

        QSqlQuery q(db);
        q.prepare(m_query);
        for (const QVariant &param : m_params) {
            q.addBindValue(param);
        }
        if (!q.exec()) {
            qDebug() << "Query error:" << q.lastError().text();
        }
    }

private:
    QString m_query;
    QVariantList m_params;
    static QMutex m_mutex;
};

QMutex DatabaseTask::m_mutex;

int main(int argc, char *argv[]) {
