    int fd = open(pipe_name, O_WRONLY);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    const char* message = "Hello from C++\n";
    write(fd, message, strlen(message));

    close(fd);
    unlink(pipe_name);

    return 0;
}

