    int src_x, src_y, dest_x, dest_y;
    while (true) {
        print_board(board);

        // Get source position
        cout << "Enter the source x: ";
        cin >> src_x;
        cout << "Enter the source y: ";
        cin >> src_y;

        // Get destination position
        cout << "Enter the destination x: ";
        cin >> dest_x;
        cout << "Enter the destination y: ";
        cin >> dest_y;

        if (is_valid_move(board, src_x, src_y, dest_x, dest_y)) {
            move_piece(board, src_x, src_y, dest_x, dest_y);
        }
        else {
            cout << "Invalid move! Please try again." << endl;
        }
    }

    return 0;
