void printColumnInfo(const QSqlQuery &query) {
    QSqlRecord record = query.record();
    for (int i = 0; i < record.count(); ++i) {
        QString columnName = record.fieldName(i);
        QVariant::Type columnType = record.field(i).type();
        QTextStream(stdout) << "Column Name: " << columnName << ", Type: " << QVariant::typeToName(columnType) << "\n";
    }
}

bool connectToDatabase(const QString &driver, const QString &database, const QString &host, const QString &user, const QString &password) {
    QSqlDatabase db = QSqlDatabase::addDatabase(driver);
    db.setHostName(host);
    db.setDatabaseName(database);
    db.setUserName(user);
    db.setPassword(password);

    if (!db.open()) {
        QTextStream(stderr) << "Database connection failed: " << db.lastError().text() << "\n";
        return false;
    }
    return true;
}

int main(int argc, char *argv[]) {
