    QString host = "localhost";
    QString database = "your_database_name";
    QString user = "your_username";
    QString password = "REDACTED_CREDENTIAL";

    if (!connectToDatabase(driver, database, host, user, password)) {
        return -1;
    }

    QSqlDatabase db = QSqlDatabase::database();
    QSqlQuery query(db);

    // Prepare a query to retrieve column information
    if (driver == "QPSQL") {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_name = :table_name LIMIT 0");
    } else if (driver == "QMYSQL") {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = :table_name LIMIT 0");
    } else if (driver == "QODBC") {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_catalog = ? AND table_name = ? LIMIT 0");
        query.addBindValue(database);
        query.addBindValue("your_table_name");
    }

    query.bindValue(":table_name", "your_table_name");

    if (!query.exec()) {
        QTextStream(stderr) << "Query execution failed: " << query.lastError().text() << "\n";
        return -1;
    }

    printColumnInfo(query);

    return a.exec();
}

