// Function to convert a string date (YYYY-MM-DD) to a stdime_point
std::chrono::system_clock::time_point stringToDate(const std::string& dateStr) {
    std::tm tm = {};
    std::istringstream ss(dateStr);
    ss >> std::get_time(&tm, "%Y-%m-%d");
    if (ss.fail()) {
        throw std::invalid_argument("Invalid date format. Expected format: YYYY-MM-DD");
    }
    return std::chrono::system_clock::from_time_t(std::mktime(&tm));
}

// Function to calculate the difference between two dates in days
long dateDifference(const std::string& date1, const std::string& date2) {
    auto tp1 = stringToDate(date1);
    auto tp2 = stringToDate(date2);
    auto duration = std::chrono::duration_cast<std::chrono::days>(tp2 - tp1);
    return duration.count();
}

int main() {
    std::string date1 = "2023-01-01";
    std::string date2 = "2023-12-31";
    try {
        long diff = dateDifference(date1, date2);
        std::cout << "The difference between " << date1 << " and " << date2 << " is " << diff << " days." << std::endl;
    } catch (const std::invalid_argument& e) {
        std::cerr << e.what() << std::endl;
    }
    return 0;
}

