std::vector<int> fibonacci(int n) {
    std::vector<int> fibSequence;
    if (n <= 0) return fibSequence;
    if (n == 1) {
        fibSequence.push_back(0);
        return fibSequence;
    }
    if (n == 2) {
        fibSequence.push_back(0);
        fibSequence.push_back(1);
        return fibSequence;
    }

    fibSequence.push_back(0);
    fibSequence.push_back(1);

    for (int i = 2; i < n; i++) {
        int nextValue = fibSequence[i - 1] + fibSequence[i - 2];
        fibSequence.push_back(nextValue);
    }

    return fibSequence;
}

int main() {
    int n = 10;
    std::vector<int> fibSequence = fibonacci(n);
    for (int num : fibSequence) {
        std::cout << num << " ";
    }
    return 0;
}

