#include <bits/stdc++.h>
using namespace std;
int main() {
  int n;
  cin >> n;
  int fixed = 1;
  int l = 2, r = n;
  while (l < r) {
    int size = r - l + 1;
    int mm = min(499, size / 2);
    int tr = l + mm - 1;
    vector<int> tseq;
    tseq.push_back(fixed);
    for (int p = l; p <= tr; p++) {
      tseq.push_back(p);
      tseq.push_back(fixed);
    }
    int kk = tseq.size();
    cout << "0 " << kk;
    for (int id : tseq) cout << " " << id;
    cout << endl;
    cout.flush();
    int resp;
    cin >> resp;
    if (resp > 0) {
      r = tr;
    } else {
      l = tr + 1;
    }
  }
  int j = l;
  cout << "0 2 " << fixed << " " << j << endl;
  cout.flush();
  int resp;
  cin >> resp;
  int open_p, close_p;
  if (resp == 1) {
    open_p = fixed;
    close_p = j;
  } else {
    open_p = j;
    close_p = fixed;
  }
  string ss(n + 1, ' ');
  ss[open_p] = '(';
  ss[close_p] = ')';
  vector<int> remains;
  for (int i = 1; i <= n; i++) {
    if (ss[i] == ' ') remains.push_back(i);
  }
  int posi = 0;
  while (posi < remains.size()) {
    int gs = min(9, (int)remains.size() - posi);
    vector<int> grp;
    for (int ii = 0; ii < gs; ii++) grp.push_back(remains[posi + ii]);
    vector<int> qseq;
    for (int b = 0; b < gs; b++) {
      int mmm = 1 << b;
      for (int tt = 0; tt < mmm; tt++) {
        qseq.push_back(grp[b]);
        qseq.push_back(close_p);
      }
      qseq.push_back(close_p);
    }
    int kkk = qseq.size();
    cout << "0 " << kkk;
    for (int id : qseq) cout << " " << id;
    cout << endl;
    cout.flush();
    int fff;
    cin >> fff;
    int cur = fff;
    for (int b = gs - 1; b >= 0; b--) {
      int mmm = 1 << b;
      int con = mmm * (mmm + 1) / 2;
      if (cur >= con) {
        ss[grp[b]] = '(';
        cur -= con;
      } else {
        ss[grp[b]] = ')';
      }
    }
    posi += gs;
  }
  cout << "1";
  for (int i = 1; i <= n; i++) cout << ss[i];
  cout << endl;
  cout.flush();
  return 0;
}

#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/div.h"
#include "jemalloc/internal/assert.h"
/*
 * Suppose we have n = q * d, all integers. We know n and d, and want q = n / d.
 *
 * For any k, we have (here, all division is exact; not C-style rounding):
 * floor(ceil(2^k / d) * n / 2^k) = floor((2^k + r) / d * n / 2^k), where
 * r = (-2^k) mod d.
 *
 * Expanding this out:
 * ... = floor(2^k / d * n / 2^k + r / d * n / 2^k)
 *     = floor(n / d + (r / d) * (n / 2^k)).
 *
 * The fractional part of n / d is 0 (because of the assumption that d divides n
 * exactly), so we have:
 * ... = n / d + floor((r / d) * (n / 2^k))
 *
 * So that our initial expression is equal to the quantity we seek, so long as
 * (r / d) * (n / 2^k) < 1.
 *
 * r is a remainder mod d, so r < d and r / d < 1 always. We can make
 * n / 2 ^ k < 1 by setting k = 32. This gets us a value of magic that works.
 */
void
div_init(div_info_t *div_info, size_t d) {
	/* Nonsensical. */
	assert(d != 0);
	/*
	 * This would make the value of magic too high to fit into a uint32_t
	 * (we would want magic = 2^32 exactly). This would mess with code gen
	 * on 32-bit machines.
	 */
	assert(d != 1);
	uint64_t two_to_k = ((uint64_t)1 << 32);
	uint32_t magic = (uint32_t)(two_to_k / d);
	/*
	 * We want magic = ceil(2^k / d), but C gives us floor. We have to
	 * increment it unless the result was exact (i.e. unless d is a power of
	 * two).
	 */
	if (two_to_k % d != 0) {
		magic++;
	}
	div_info->magic = magic;
#ifdef JEMALLOC_DEBUG
	div_info->d = d;
#endif
}

