#include <iostream>
#include <vector>
#include <map>
#include <cstdlib>
using namespace std;
// Maximum value of N as per problem statement
const int MAXN = 200005;
// Array to store the result
int a[MAXN];
// Map to store a known position of each distinct element found so far
map<int, int> pos;
/**
 * Recursive function to solve the problem for the range [l, r].
 * Uses a divide and conquer strategy with pruning based on known sorted array properties.
 */
void solve(int l, int r) {
    // Trim indices from the left that are already filled
    while (l <= r && a[l] != 0) l++;
    // Trim indices from the right that are already filled
    while (r >= l && a[r] != 0) r--;

    // Base case: if range is empty or invalid
    if (l > r) return;
    // Interactive query
    cout << "? " << l << " " << r << endl;
    int x, f;
    cin >> x >> f;

    if (x == -1) exit(0); // Should not happen with correct logic
    // Optimization: If the frequency of x equals the length of the current range,
    // then the entire range [l, r] is filled with x.
    if (f == r - l + 1) {
        for (int i = l; i <= r; ++i) a[i] = x;
        pos[x] = l; // Record that we found x at position l
        return;
    }
    // Anchor Optimization:
    // If we have previously encountered the value x, we know its position 'p' (stored in pos[x]).
    // Since the array is sorted, all occurrences of x must be contiguous.
    // Because x is present in the current unfilled range [l, r] (implied by the query result),
    // the block of x must connect to the previously found position 'p'.
    // 'p' cannot be inside [l, r] because [l, r] consists of unfilled (0) elements,
    // and pos[x] is set only when we fill elements.
    if (pos.count(x)) {
        int p = pos[x];

        if (p < l) {
            // x is anchored to the left of the current range.
            // Since x is contiguous and present in [l, r], it must start at l.
            // It occupies the first f positions of [l, r].
            for (int i = 0; i < f; ++i) a[l + i] = x;
            pos[x] = l; // Update anchor (optional)
            // Recurse on the remaining part of the range
            solve(l + f, r);
            return;
        } else if (p > r) {
            // x is anchored to the right of the current range.
            // It must occupy the last f positions of [l, r].
            for (int i = 0; i < f; ++i) a[r - i] = x;
            pos[x] = r;
            // Recurse on the remaining part
            solve(l, r - f);
            return;
        }
    }
    // If no optimizations apply, split the range and recurse.
    int mid = (l + r) / 2;
    solve(l, mid);
    solve(mid + 1, r);
}
int main() {
    // Optimize standard I/O operations (though flushing is necessary for interactive problems)
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    // Solve for the entire array
    solve(1, n);
    // Output the result
    cout << "! ";
    for (int i = 1; i <= n; ++i) {
        cout << a[i] << (i == n ? "" : " ");
    }
    cout << endl;
    return 0;
}

#include "hip/hip_runtime.h"
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <mutex>
#include <random>
#include <stdexcept>
#include <thread>
#define HIP_API_CALL(CALL)                                                                         \
    {                                                                                              \
        hipError_t error_ = (CALL);                                                                \
        if(error_ != hipSuccess)                                                                   \
        {                                                                                          \
            auto _hip_api_print_lk = auto_lock_t{print_lock};                                      \
            fprintf(stderr,                                                                        \
                    "%s:%d :: HIP error : %s\n",                                                   \
                    __FILE__,                                                                      \
                    __LINE__,                                                                      \
                    hipGetErrorString(error_));                                                    \
            throw std::runtime_error("hip_api_call");                                              \
        }                                                                                          \
    }
namespace
{
using auto_lock_t                      = std::unique_lock<std::mutex>;
auto               print_lock          = std::mutex{};
size_t             nthreads            = 2;
size_t             nitr                = 500;
size_t             nsync               = 10;
constexpr unsigned shared_mem_tile_dim = 32;
void
check_hip_error(void);
void
verify(int* in, int* out, int M, int N);
}  // namespace
__global__ void
transpose_a(int* in, int* out, int M, int N);
void
run(int rank, int tid, hipStream_t stream, int argc, char** argv);
int
main(int argc, char** argv)
{
    int rank = 0;
    for(int i = 1; i < argc; ++i)
    {
        auto _arg = std::string{argv[i]};
        if(_arg == "?" || _arg == "-h" || _arg == "--help")
        {
            fprintf(stderr,
                    "usage: transpose [NUM_THREADS (%zu)] [NUM_ITERATION (%zu)] "
                    "[SYNC_EVERY_N_ITERATIONS (%zu)]\n",
                    nthreads,
                    nitr,
                    nsync);
            exit(EXIT_SUCCESS);
        }
    }
    if(argc > 1) nthreads = atoll(argv[1]);
    if(argc > 2) nitr = atoll(argv[2]);
    if(argc > 3) nsync = atoll(argv[3]);
    printf("[transpose] Number of threads: %zu\n", nthreads);
    printf("[transpose] Number of iterations: %zu\n", nitr);
    printf("[transpose] Syncing every %zu iterations\n", nsync);
    // this is a temporary workaround in omnitrace when HIP + MPI is enabled
    int ndevice = 0;
    int devid   = rank;
    HIP_API_CALL(hipGetDeviceCount(&ndevice));
    printf("[transpose] Number of devices found: %i\n", ndevice);
    if(ndevice > 0)
    {
        devid = rank % ndevice;
        HIP_API_CALL(hipSetDevice(devid));
        printf("[transpose] Rank %i assigned to device %i\n", rank, devid);
    }
    if(rank == devid && rank < ndevice)
    {
        std::vector<std::thread> _threads{};
        std::vector<hipStream_t> _streams(nthreads);
        for(size_t i = 0; i < nthreads; ++i)
            HIP_API_CALL(hipStreamCreate(&_streams.at(i)));
        for(size_t i = 1; i < nthreads; ++i)
            _threads.emplace_back(run, rank, i, _streams.at(i), argc, argv);
        run(rank, 0, _streams.at(0), argc, argv);
        for(auto& itr : _threads)
            itr.join();
        for(size_t i = 0; i < nthreads; ++i)
            HIP_API_CALL(hipStreamDestroy(_streams.at(i)));
    }
    HIP_API_CALL(hipDeviceSynchronize());
    HIP_API_CALL(hipDeviceReset());
    return 0;
}
__global__ void
transpose_a(int* in, int* out, int M, int N)
{
    __shared__ int tile[shared_mem_tile_dim][shared_mem_tile_dim];
    int idx = (blockIdx.y * blockDim.y + threadIdx.y) * M + blockIdx.x * blockDim.x + threadIdx.x;
    tile[threadIdx.y][threadIdx.x] = in[idx];
    __syncthreads();
    idx      = (blockIdx.x * blockDim.x + threadIdx.y) * N + blockIdx.y * blockDim.y + threadIdx.x;
    out[idx] = tile[threadIdx.x][threadIdx.y];
}
void
run(int rank, int tid, hipStream_t stream, int argc, char** argv)
{
    unsigned int M = 4960 * 2;
    unsigned int N = 4960 * 2;
    if(argc > 2) nitr = atoll(argv[2]);
    if(argc > 3) nsync = atoll(argv[3]);
    auto_lock_t _lk{print_lock};
    std::cout << "[transpose][" << rank << "][" << tid << "] M: " << M << " N: " << N << std::endl;
    _lk.unlock();
    std::default_random_engine         _engine{std::random_device{}() * (rank + 1) * (tid + 1)};
    std::uniform_int_distribution<int> _dist{0, 1000};
    size_t size       = sizeof(int) * M * N;
    int*   inp_matrix = new int[size];
    int*   out_matrix = new int[size];
    for(size_t i = 0; i < M * N; i++)
    {
        inp_matrix[i] = _dist(_engine);
        out_matrix[i] = 0;
    }
    int* in  = nullptr;
    int* out = nullptr;
    HIP_API_CALL(hipMalloc(&in, size));
    HIP_API_CALL(hipMalloc(&out, size));
    HIP_API_CALL(hipMemsetAsync(in, 0, size, stream));
    HIP_API_CALL(hipMemsetAsync(out, 0, size, stream));
    HIP_API_CALL(hipMemcpyAsync(in, inp_matrix, size, hipMemcpyHostToDevice, stream));
    HIP_API_CALL(hipStreamSynchronize(stream));
    dim3 grid(M / 32, N / 32, 1);
    dim3 block(32, 32, 1);  // transpose_a
    auto t1 = std::chrono::high_resolution_clock::now();
    for(size_t i = 0; i < nitr; ++i)
    {
        transpose_a<<<grid, block, 0, stream>>>(in, out, M, N);
        check_hip_error();
        if(i % nsync == (nsync - 1)) HIP_API_CALL(hipStreamSynchronize(stream));
    }
    auto t2 = std::chrono::high_resolution_clock::now();
    HIP_API_CALL(hipStreamSynchronize(stream));
    HIP_API_CALL(hipMemcpyAsync(out_matrix, out, size, hipMemcpyDeviceToHost, stream));
    double time = std::chrono::duration_cast<std::chrono::duration<double>>(t2 - t1).count();
    float  GB   = (float) size * nitr * 2 / (1 << 30);
    print_lock.lock();
    std::cout << "[" << rank << "][" << tid << "] Runtime of transpose is " << time << " sec\n"
              << "The average performance of transpose is " << GB / time << " GBytes/sec"
              << std::endl;
    print_lock.unlock();
    HIP_API_CALL(hipStreamSynchronize(stream));
    // cpu_transpose(matrix, out_matrix, M, N);
    verify(inp_matrix, out_matrix, M, N);
    HIP_API_CALL(hipFree(in));
    HIP_API_CALL(hipFree(out));
    delete[] inp_matrix;
    delete[] out_matrix;
}
