void VRPN_CALLBACK FDisplayClusterVrpnKeyboardInputDevice::HandleKeyboardDevice(void *UserData, vrpn_BUTTONCB const ButtonData)
{
	auto Dev = reinterpret_cast<FDisplayClusterVrpnKeyboardInputDevice*>(UserData);

	auto Item = Dev->DeviceData.Find(ButtonData.button);
	if (!Item)
	{
		Item = &Dev->DeviceData.Add(ButtonData.button);
		// Explicit initial old state set
		Item->BtnStateOld = false;
	}
	//@note: Actually the button can change state for several time during one update cycle. For example
	//       it could change 0->1->0. Then we will send only the latest state and as a result the state
	//       change won't be processed. I don't process such situations because it's not ok if button
	//       changes the state so quickly. It's probably a contact shiver or something else. Normal button
	//       usage will lead to state change separation between update frames.
	// Convert button state from int to bool here. Actually VRPN has only two states for
	// buttons (0-released, 1-pressed) but still uses int32 type for the state.
	Item->BtnStateNew = (ButtonData.state != 0);
	UE_LOG(LogDisplayClusterInputVRPN, VeryVerbose, TEXT("Keyboard %s:%d - %d"), *Dev->GetId(), ButtonData.button, ButtonData.state);
}

#include "synth/SampleZone.h"
#include "obj/Object.h"
#include "synth/Stream.h"
#include "utl/BinStream.h"
SampleZone::SampleZone(Hmx::Object *owner)
    : mSample(owner), mVolume(0.0f), mPan(0.0f), mCenterNote(0x24), mMinNote(0),
      mMaxNote(0x7f), mMinVel(0), mMaxVel(0x7f), mFXCore(kFXCoreNone) {}
void SampleZone::Save(BinStream &bs) const {
    bs << mSample;
    bs << mVolume;
    bs << mPan;
    bs << mCenterNote;
    bs << mMinNote;
    bs << mMaxNote;
    bs << mFXCore;
    bs << mADSR;
    bs << mMinVel;
    bs << mMaxVel;
}
void SampleZone::Load(BinStreamRev &d) {
    d >> mSample;
    d >> mVolume;
    d >> mPan;
    d >> mCenterNote;
    d >> mMinNote;
    d >> mMaxNote;
    int fx;
    d >> fx;
    mFXCore = (FXCore)fx;
    d >> mADSR;
    if (d.rev >= 2) {
        d >> mMinVel;
        d >> mMaxVel;
    }
}
bool SampleZone::Includes(unsigned char note, unsigned char vel) {
    return mMinNote <= note && note <= mMaxNote && mMinVel <= vel && vel <= mMaxVel;
}
BinStream &operator<<(BinStream &bs, const SampleZone &sz) {
    sz.Save(bs);
    return bs;
}
BinStreamRev &operator>>(BinStreamRev &d, SampleZone &sz) {
    sz.Load(d);
    return d;
}

#include <iostream>
#include <vector>
#include <string>
using namespace std;
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;
    char c1, c2; // c1 = background, c2 = island
    int M; // Number of islands of C2
    int K; // Number of holes of C1 inside C2 islands
    // We choose the background color to be the one with the smaller cost coefficient
    // to minimize the total cost (since background typically uses more tiles).
    // If x < y, Black (@) is cheaper -> Background = @
    // If x >= y, White (.) is cheaper -> Background = .

    if (x < y) {
        c1 = '@';
        c2 = '.';
        // We need 'w' white components (islands).
        // We need 'b' black components. 
        // Background counts as 1 black component.
        // We need b - 1 additional black components (holes inside white islands).
        M = w;
        K = b - 1;
    } else {
        c1 = '.';
        c2 = '@';
        // We need 'b' black components (islands).
        // We need 'w' white components.
        // Background counts as 1 white component.
        // We need w - 1 additional white components (holes inside black islands).
        M = b;
        K = w - 1;
    }
    vector<string> grid;
    if (K == 0) {
        // Case A: No holes needed. We just need M simple islands.
        // A grid of height 2 is sufficient.
        // Row 0 contains the islands separated by background.
        // Row 1 is full background to keep the background connected.
        // Pattern: [Separator] [Island] [Separator] [Island] ...

        string r0 = "", r1 = "";

        // Initial separator
        r0 += c1;
        r1 += c1;

        for (int i = 0; i < M; ++i) {
            r0 += c2; // Island
            r1 += c1; // Background

            r0 += c1; // Separator
            r1 += c1; // Background
        }
        grid.push_back(r0);
        grid.push_back(r1);
    } else {
        // Case B: We need K holes.
        // We construct 1 "Complex Island" that contains all K holes, 
        // and M-1 "Simple Islands".
        // A grid of height 4 is used.
        // Row 3 is full background for connectivity.
        // Rows 0-2 contain the islands.

        string r0 = "", r1 = "", r2 = "", r3 = "";

        // Initial separator column
        r0 += c1; r1 += c1; r2 += c1; r3 += c1;

        // 1. Complex Island containing K holes
        // This island spans 3 rows (0, 1, 2).
        // Row 1 contains alternating C2 and C1. The C1s are the holes.
        // Width required: 2*K + 1
        for (int k = 0; k < 2 * K + 1; ++k) {
            r0 += c2;
            if (k % 2 == 0) r1 += c2; else r1 += c1; // C1 here is a hole
            r2 += c2;
            r3 += c1;
        }

        // Separator column
        r0 += c1; r1 += c1; r2 += c1; r3 += c1;

        // 2. Remaining M-1 simple islands
        for (int i = 0; i < M - 1; ++i) {
            // Simple island just needs to be an isolated C2.
            // We place it in Row 1, surrounded by C1 in R0, R2 and separators.
            r0 += c1;
            r1 += c2;
            r2 += c1;
            r3 += c1;

            // Separator column
            r0 += c1; r1 += c1; r2 += c1; r3 += c1;
        }

        grid.push_back(r0);
        grid.push_back(r1);
        grid.push_back(r2);
        grid.push_back(r3);
    }
    cout << grid.size() << " " << grid[0].size() << "\n";
    for (const string& row : grid) {
        cout << row << "\n";
    }
    return 0;
}

#include "dap/network.h"
#include "dap/io.h"
#include "chan.h"
#include "gmock/gmock.h"
#include "gtest/gtest.h"
#include <chrono>
#include <thread>
namespace {
constexpr int port = 19021;
bool write(const std::shared_ptr<dap::Writer>& w, const std::string& s) {
  return w->write(s.data(), s.size()) && w->write("\0", 1);
}
std::string read(const std::shared_ptr<dap::Reader>& r) {
  char c;
  std::string s;
  while (r->read(&c, sizeof(c)) > 0) {
    if (c == '\0') {
      return s;
    }
    s += c;
  }
  return r->isOpen() ? "<read failed>" : "<stream closed>";
}
}  // anonymous namespace
TEST(Network, ClientServer) {
  dap::Chan<bool> done;
  auto server = dap::net::Server::create();
  if (!server->start(
          port,
          [&](const std::shared_ptr<dap::ReaderWriter>& rw) {
            ASSERT_EQ(read(rw), "client to server");
            ASSERT_TRUE(write(rw, "server to client"));
            done.put(true);
          },
          [&](const char* err) { FAIL() << "Server error: " << err; })) {
    FAIL() << "Couldn't start server";
    return;
  }
  for (int i = 0; i < 5; i++) {
    auto client = dap::net::connect("localhost", port);
    ASSERT_NE(client, nullptr) << "Failed to connect client " << i;
    ASSERT_TRUE(write(client, "client to server"));
    ASSERT_EQ(read(client), "server to client");
    done.take();
    std::this_thread::sleep_for(std::chrono::seconds(1));
  }
  server.reset();
}
TEST(Network, ServerRepeatStopAndRestart) {
  dap::Chan<bool> done;
  auto onConnect = [&](const std::shared_ptr<dap::ReaderWriter>& rw) {
    ASSERT_EQ(read(rw), "client to server");
    ASSERT_TRUE(write(rw, "server to client"));
    done.put(true);
  };
  auto onError = [&](const char* err) { FAIL() << "Server error: " << err; };
  auto server = dap::net::Server::create();
  if (!server->start(port, onConnect, onError)) {
    FAIL() << "Couldn't start server";
    return;
  }
  server->stop();
  server->stop();
  server->stop();
  if (!server->start(port, onConnect, onError)) {
    FAIL() << "Couldn't restart server";
    return;
  }
  auto client = dap::net::connect("localhost", port);
  ASSERT_NE(client, nullptr) << "Failed to connect";
  ASSERT_TRUE(write(client, "client to server"));
  ASSERT_EQ(read(client), "server to client");
  done.take();
  server->stop();
  server->stop();
  server->stop();
  server.reset();
}

#include <iostream>
#include <vector>
#include <numeric>
#include <cmath>
#include <random>
#include <chrono>
#include <algorithm>
// Constants are fixed as per the problem statement
const int N_CONST = 100;
const int L_CONST = 500000;
int N, L; // Read from input, but will be N_CONST, L_CONST
std::vector<int> T;
// Random Number Generator
std::mt19937 rng;
// Evaluation function: simulates the process and calculates total error
long long calculate_error(const std::vector<int>& ab) {
    std::vector<int> counts(N_CONST, 0);
    int current_employee = 0;
    for (int week = 0; week < L_CONST; ++week) {
        counts[current_employee]++;
        int t_x = counts[current_employee];
        if (t_x % 2 != 0) { // odd
            current_employee = ab[current_employee * 2];
        } else { // even
            current_employee = ab[current_employee * 2 + 1];
        }
    }
    long long error = 0;
    for (int i = 0; i < N_CONST; ++i) {
        error += std::abs(counts[i] - T[i]);
    }
    return error;
}
int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    // Seed RNG
    rng.seed(std::chrono::high_resolution_clock::now().time_since_epoch().count());
    // Read input
    std::cin >> N >> L;
    T.resize(N);
    for (int i = 0; i < N; ++i) {
        std::cin >> T[i];
    }
    // 1. Initial solution using Largest Remainder Method
    std::vector<int> ab(2 * N);
    {
        std::vector<double> target_degrees(N);
        for (int i = 0; i < N; ++i) {
            target_degrees[i] = (double)T[i] / L * (2 * N);
        }
        std::vector<int> degrees(N);
        int current_sum = 0;
        std::vector<std::pair<double, int>> remainders;
        remainders.reserve(N);
        for (int i = 0; i < N; ++i) {
            degrees[i] = floor(target_degrees[i]);
            current_sum += degrees[i];
            remainders.push_back({target_degrees[i] - degrees[i], i});
        }
        std::sort(remainders.rbegin(), remainders.rend());
        int to_distribute = 2 * N - current_sum;
        for (int i = 0; i < to_distribute; ++i) {
            degrees[remainders[i].second]++;
        }
        std::vector<int> destinations;
        destinations.reserve(2 * N);
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < degrees[i]; ++j) {
                destinations.push_back(i);
            }
        }
        std::shuffle(destinations.begin(), destinations.end(), rng);
        ab = destinations;
    }
    long long current_error = calculate_error(ab);
    std::vector<int> best_ab = ab;
    long long best_error = current_error;
    // 2. Simulated Annealing
    double time_limit = 2.8; 
    auto start_time = std::chrono::high_resolution_clock::now();

    double start_temp = 500;
    double end_temp = 0.1;
    std::uniform_int_distribution<int> move_dist(0, 99);
    std::uniform_int_distribution<int> idx_dist(0, 2 * N - 1);
    std::uniform_int_distribution<int> val_dist(0, N - 1);
    std::uniform_real_distribution<double> prob_dist(0.0, 1.0);
    while (true) {
        auto current_time = std::chrono::high_resolution_clock::now();
        double elapsed = std::chrono::duration<double>(current_time - start_time).count();
        if (elapsed > time_limit) break;
        double temp = start_temp * (1.0 - elapsed / time_limit) + end_temp * (elapsed / time_limit);
        std::vector<int> next_ab = ab;

        int move_type = move_dist(rng);
        int i, j;
        if (move_type < 90) { // Swap move (90% chance)
            i = idx_dist(rng);
            do {
                j = idx_dist(rng);
            } while (i == j);
            std::swap(next_ab[i], next_ab[j]);
        } else { // Change move (10% chance)
            i = idx_dist(rng);
            int old_val = next_ab[i];
            do {
                j = val_dist(rng);
            } while (j == old_val);
            next_ab[i] = j;
        }
        long long next_error = calculate_error(next_ab);

        double probability = std::exp((double)(current_error - next_error) / temp);
        if (prob_dist(rng) < probability) {
            ab = next_ab;
            current_error = next_error;
            if (current_error < best_error) {
                best_error = current_error;
                best_ab = ab;
            }
        }
    }

    // 3. Output
    for (int i = 0; i < N; ++i) {
        std::cout << best_ab[2 * i] << " " << best_ab[2 * i + 1] << "\n";
    }
    return 0;
}

#include "alarm.h"
#include "callbacks.h"
#include "game_functions.h"
#include "zeal.h"
void Alarm::Set(int minutes, int seconds) {
  if (!enabled) {
    enabled = true;
    duration = ((minutes * 60) + seconds) * 1000;
    std::ostringstream oss;
    oss << "[Alarm] SET! (" << minutes << "m" << seconds << "s)" << std::endl;
    Zeal::Game::print_chat(oss.str());
  } else {
    Zeal::Game::print_chat("[Alarm] Please halt the active alarm before attempting to set a new one.");
  }
}
void Alarm::Halt(void) {
  if (enabled) {
    enabled = false;
    Zeal::Game::print_chat("[Alarm] HALT!");
  } else {
    Zeal::Game::print_chat("[Alarm] No active alarm.");
  }
}
void Alarm::callback_main() {
  if (enabled) {
    if (!start_time) start_time = GetTickCount64();
    if (GetTickCount64() - start_time > duration) {
      Zeal::Game::print_chat("[Alarm] COMPLETED!");
      enabled = false;
    }
  } else {
    start_time = 0;
  }
}
Alarm::Alarm(ZealService *zeal) {
  zeal->callbacks->AddGeneric([this]() { callback_main(); });
}

