    UIComponent::State cstate,
    const Transform &tf,
    Box *box
) {
    MILO_ASSERT(mesh, 0x40);
    mesh->SetWorldXfm(tf);
    if (box) {
        Box localbox = *box;
        CalcBox(mesh, localbox);
        box->GrowToContain(localbox.mMin, false);
        box->GrowToContain(localbox.mMax, false);
    } else {
        UIColor *col = DisplayColor(wstate, cstate);
        if (col) {
            RndMat *mat = mesh->Mat();
            if (mat)
