    void platformAlignedFree(void* ptr)
    {
        _aligned_free(ptr);
    }
#else
    void* platformAlignedAlloc(size_t size)
    {
        return MEMALIGN(16, size);
    }
    void platformAlignedFree(void* ptr)
    {
        ::free(ptr);
    }
#endif
} // end of SSE2NEON namespace

