#include "valdi/runtime/JavaScript/JavaScriptHeapDumpBuilder.hpp"
#include "valdi_core/cpp/Utils/Format.hpp"
#include "valdi_core/cpp/Utils/StringCache.hpp"
#include <benchmark/benchmark.h>
using namespace Valdi;
struct BenchmarkHelper {
    std::vector<StringBox> names;
    std::vector<StringBox> propertyNames;
    BenchmarkHelper() {
        for (size_t i = 0; i < 20; i++) {
            names.emplace_back(STRING_FORMAT("Object{}", i));
        }
        for (size_t i = 0; i < 1000; i++) {
            propertyNames.emplace_back(STRING_FORMAT("prop{}", i));
        }
    }
    void populateHeapDumpBuilder(JavaScriptHeapDumpBuilder& builder) {
        constexpr size_t nodesCount = 100000;
        constexpr size_t edgesPerNodeCount = 5;
        for (size_t i = 0; i < nodesCount; i++) {
            auto nodeType =
                static_cast<JavaScriptHeapDumpNodeType>(i % static_cast<size_t>(JavaScriptHeapDumpNodeType::COUNT));
            builder.beginNode(nodeType, names[i % names.size()], static_cast<uint64_t>(i), 42);
            for (size_t j = i + 1; j < nodesCount && j - i < edgesPerNodeCount; j++) {
                builder.appendEdge(JavaScriptHeapDumpEdgeType::PROPERTY,
                                   JavaScriptHeapEdgeIdentifier::named(propertyNames[j % propertyNames.size()]),
                                   static_cast<uint64_t>(j));
            }
        }
    }
};
static void BuildHeapDump(benchmark::State& state) {
    BenchmarkHelper helper;
    for (auto _ : state) {
        JavaScriptHeapDumpBuilder builder;
        helper.populateHeapDumpBuilder(builder);
        benchmark::DoNotOptimize(builder.build());
    }
}
BENCHMARK(BuildHeapDump);
static void ParseHeapDump(benchmark::State& state) {
    BenchmarkHelper helper;
    JavaScriptHeapDumpBuilder builder;
    helper.populateHeapDumpBuilder(builder);
    auto heapDump = builder.build();
    for (auto _ : state) {
        SimpleExceptionTracker exceptionTracker;
        JavaScriptHeapDumpParser parser(heapDump.data(), heapDump.size(), exceptionTracker);
        for (const auto& node : parser.getNodes()) {
            for (const auto& edge : node.getEdges()) {
                benchmark::DoNotOptimize(edge.getIdentifier());
            }
        }
    }
}
BENCHMARK(ParseHeapDump);
static void MergeHeapDump(benchmark::State& state) {
    BenchmarkHelper helper;
    JavaScriptHeapDumpBuilder builder;
    helper.populateHeapDumpBuilder(builder);
    auto heapDump = builder.build();
    for (auto _ : state) {
        JavaScriptHeapDumpBuilder builder;
        SimpleExceptionTracker exceptionTracker;
        builder.appendDump(heapDump.data(), heapDump.size(), exceptionTracker);
        builder.appendDump(heapDump.data(), heapDump.size(), exceptionTracker);
        builder.appendDump(heapDump.data(), heapDump.size(), exceptionTracker);
        benchmark::DoNotOptimize(builder.build());
    }
}
BENCHMARK(MergeHeapDump);
BENCHMARK_MAIN();

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int main() {
    int R, H;
    cin >> R >> H; // R=75, H=1 in the official test, but we read anyway.
    // Moduli for the tests. Their sum is 30.
    vector<int> moduli = {13, 7, 5, 3, 2};
    // Send all robots at once.
    for (int m : moduli) {
        for (int r = 0; r < m; ++r) {
            // Collect all positions p such that p % m == r.
            vector<int> positions;
            for (int p = 1; p <= 1000; ++p) {
                if (p % m == r) {
                    positions.push_back(p);
                }
            }
            // Output the query for this robot.
            cout << "? " << positions.size();
            for (int pos : positions) {
                cout << " " << pos;
            }
            cout << endl;
            cout.flush();
        }
    }
    // Wait for the results.
    cout << "@" << endl;
    cout.flush();
    int L;
    cin >> L;
    vector<int> responses(L);
    for (int i = 0; i < L; ++i) {
        cin >> responses[i];
    }
    // Decode: split responses according to the moduli.
    vector<vector<int>> positive_sets(moduli.size()); // residues with answer 1 for each modulus
    int idx = 0;
    for (int i = 0; i < moduli.size(); ++i) {
        int m = moduli[i];
        for (int r = 0; r < m; ++r) {
            if (responses[idx + r] == 1) {
                positive_sets[i].push_back(r);
            }
        }
        idx += m;
    }
    // Precompute residues for all numbers 1..1000 for each modulus.
    vector<vector<int>> num_res(1001, vector<int>(moduli.size()));
    for (int p = 1; p <= 1000; ++p) {
        for (int i = 0; i < moduli.size(); ++i) {
            num_res[p][i] = p % moduli[i];
        }
    }
    // Brute-force search over all unordered pairs (i,j), i <= j.
    int a = -1, b = -1;
    for (int i = 1; i <= 1000; ++i) {
        for (int j = i; j <= 1000; ++j) {
            bool ok = true;
            for (int mi = 0; mi < moduli.size(); ++mi) {
                int m = moduli[mi];
                int ri = num_res[i][mi];
                int rj = num_res[j][mi];
                // Check that for every residue r, (ri==r or rj==r) equals whether r is in positive_sets[mi].
                for (int r = 0; r < m; ++r) {
                    bool covered = (ri == r) || (rj == r);
                    bool expected = false;
                    for (int rr : positive_sets[mi]) {
                        if (rr == r) {
                            expected = true;
                            break;
                        }
                    }
                    if (covered != expected) {
                        ok = false;
                        break;
                    }
                }
                if (!ok) break;
            }
            if (ok) {
                a = i;
                b = j;
                break;
            }
        }
        if (a != -1) break;
    }
    // Output the answer.
    cout << "! " << a << " " << b << endl;
    cout.flush();
    return 0;
}

