void LoadSysModule(uint16_t module, const char* moduleName)
{
	int ret = sceSysmoduleLoadModule(module);
	if(ret != SCE_OK)
	{
#ifndef _CONTENT_PACKAGE
		printf("Error sceSysmoduleLoadModule %s failed (%d) \n", moduleName, ret );
#endif
		assert(0);
	}
}
