#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <cmath>
using namespace std;
// Function to simulate the editor process locally
// Returns number of lines needed to display article a with width W.
// Returns 0 if max(a) > W.
int solve_lines(const vector<int>& a, int W) {
    int lines = 1;
    long long current_s = 0;
    for (int x : a) {
        if (x > W) return 0;
        if (current_s + x <= W) {
            current_s += x;
        } else {
            lines++;
            current_s = x;
        }
    }
    return lines;
}
void solve() {
    int N = 100000; 
    // Query 1: N words of length 1.
    // This provides a range of candidate values for W.
    cout << "? " << N;
    for (int i = 0; i < N; ++i) cout << " 1";
    cout << endl;

    int k1;
    cin >> k1;
    // Check for invalid input or termination signal
    if (k1 == 0 || k1 == -1) exit(0);
    // Derive range [L, R] from k1
    // Relation: k1 = ceil(N / W)
    // Inequalities: k1 - 1 < N / W <= k1
    // Lower bound: W >= N / k1  => L = ceil(N / k1)
    // Upper bound: W < N / (k1 - 1)  (for k1 > 1) => W <= floor((N - 1) / (k1 - 1))

    int L = (N + k1 - 1) / k1;
    int R;
    if (k1 == 1) {
        R = 100000;
    } else {
        R = (N - 1) / (k1 - 1);
    }

    // Clamp R to the problem constraint
    if (R > 100000) R = 100000;
    if (L > R) L = R; 

    if (L == R) {
        cout << "! " << L << endl;
        return;
    }

    // Query 2: Random sequence to distinguish W within [L, R]
    // We generate numbers in [1, L]. Since L <= W_true, these words are always valid.
    // Using N=100000 and random values provides a high "slope" for the lines(W) function,
    // minimizing the chance of collisions (different W producing same line count).
    mt19937 rng(1337); 
    vector<int> a(N);
    for (int i = 0; i < N; ++i) {
        // Generate random length in [1, L]
        a[i] = (int)(rng() % L) + 1;
    }

    cout << "? " << N;
    for (int i = 0; i < N; ++i) {
        cout << " " << a[i];
    }
    cout << endl;

    int k2;
    cin >> k2;
    if (k2 == -1) exit(0);

    // Binary search for W in [L, R]
    // The number of lines is non-increasing with respect to W.
    // We search for W such that solve_lines(a, W) == k2.

    int ans = R;
    int low = L, high = R;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        int sim = solve_lines(a, mid);

        if (sim == k2) {
            ans = mid;
            // Assuming uniqueness or finding any consistent W.
            // In case of a small plateau, the problem constraints and strategy 
            // usually imply we should find the consistent value. 
            // Since simulate is monotonic, we can break or try to find boundaries.
            // Given the high variance of the query, a match is likely unique.
            break; 
        } else if (sim < k2) {
            // Observed k2 lines, but mid gives fewer lines.
            // Fewer lines implies mid is too large (capacity too high).
            // We need a smaller W to get more lines.
            high = mid - 1;
        } else {
            // sim > k2
            // Mid gives too many lines. Capacity too low.
            // We need a larger W to reduce line count.
            low = mid + 1;
        }
    }

    cout << "! " << ans << endl;
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (cin >> t) {
        while(t--) {
            solve();
        }
    }
    return 0;
}

#include "lib/common/container/small_vector.hpp"
namespace rocprofiler
{
namespace common
{
namespace container
{
namespace
{
[[noreturn]] void
report_size_overflow(size_t min_size, size_t max_size);
[[noreturn]] void
report_at_maximum_capacity(size_t max_size);
/// Report that min_size doesn't fit into this vector's size type. Throws
/// std::length_error
void
report_size_overflow(size_t min_size, size_t max_size)
{
    std::string Reason =
        "small_vector unable to grow. Requested capacity (" + std::to_string(min_size) +
        ") is larger than maximum value for size type (" + std::to_string(max_size) + ")";
    throw std::length_error(Reason);
}
/// Report that this vector is already at maximum capacity. Throws
/// std::length_error
void
report_at_maximum_capacity(size_t max_size)
{
    std::string Reason =
        "small_vector capacity unable to grow. Already at maximum size " + std::to_string(max_size);
    throw std::length_error(Reason);
}
template <typename SizeT>
size_t
get_new_capacity(size_t min_size, size_t /*t_size*/, size_t old_capacity)
{
    constexpr size_t max_size = std::numeric_limits<SizeT>::max();
    // Ensure we can fit the new capacity.
    // This is only going to be applicable when the capacity is 32 bit.
    if(min_size > max_size) report_size_overflow(min_size, max_size);
    // Ensure we can meet the guarantee of space for at least one more element.
    // The above check alone will not catch the case where grow is called with a
    // default min_size of 0, but the current capacity cannot be increased.
    // This is only going to be applicable when the capacity is 32 bit.
    if(old_capacity == max_size) report_at_maximum_capacity(max_size);
    // In theory 2*capacity can overflow if the capacity is 64 bit, but the
    // original capacity would never be large enough for this to be a problem.
    size_t new_capacity = (2 * old_capacity) + 1;  // Always grow.
    return std::clamp(new_capacity, min_size, max_size);
}
}  // namespace
template <typename SizeT>
void*
small_vector_base<SizeT>::replace_allocation(void*  new_elts,
                                             size_t t_size,
                                             size_t new_capacity,
                                             size_t v_size)
{
    void* new_eltsReplace = ::malloc(new_capacity * t_size);
    if(v_size != 0u) memcpy(new_eltsReplace, new_elts, v_size * t_size);
    free(new_elts);
    return new_eltsReplace;
}
// Note: Moving this function into the header may cause performance regression.
template <typename SizeT>
void*
small_vector_base<SizeT>::malloc_for_grow(void*   first_el,
                                          size_t  min_size,
                                          size_t  t_size,
                                          size_t& new_capacity)
{
    new_capacity = get_new_capacity<SizeT>(min_size, t_size, this->capacity());
    // Even if capacity is not 0 now, if the vector was originally created with
    // capacity 0, it's possible for the malloc to return first_el.
    void* new_elts = ::malloc(new_capacity * t_size);
    if(new_elts == first_el) new_elts = replace_allocation(new_elts, t_size, new_capacity);
    return new_elts;
}
// Note: Moving this function into the header may cause performance regression.
template <typename SizeT>
void
small_vector_base<SizeT>::grow_pod(void* first_el, size_t min_size, size_t t_size)
{
    size_t new_capacity = get_new_capacity<SizeT>(min_size, t_size, this->capacity());
    void*  new_elts;
    if(m_begin_x == first_el)
    {
        new_elts = ::malloc(new_capacity * t_size);
        if(new_elts == first_el) new_elts = replace_allocation(new_elts, t_size, new_capacity);
        // Copy the elements over.  No need to run dtors on PODs.
        memcpy(new_elts, this->m_begin_x, size() * t_size);
    }
    else
    {
        // If this wasn't grown from the inline copy, grow the allocated space.
        new_elts = ::realloc(this->m_begin_x, new_capacity * t_size);
        if(new_elts == first_el)
            new_elts = replace_allocation(new_elts, t_size, new_capacity, size());
    }
    this->m_begin_x  = new_elts;
    this->m_capacity = new_capacity;
}
}  // namespace container
}  // namespace common
}  // namespace rocprofiler
// explicit instantiations
template class rocprofiler::common::container::small_vector_base<uint32_t>;
#if SIZE_MAX > UINT32_MAX
template class rocprofiler::common::container::small_vector_base<uint64_t>;
#endif

