            "network",
            "keyfile",
            ClientOnly,
            [this, rel_base = conf.conf_dir](std::filesystem::path arg) {
                if (arg.empty())
                {
                    keyfile.reset();
                    return;
                }
                if (arg.is_relative())
                    arg = rel_base / arg;
                if (!exists(arg))
