// Encrypts characters using inline assembly
void encrypt_chars(int length, char EKey)
{
    char temp_char;

    // Loop through each character
    for(int i=0;i<length;i++)
    {
        temp_char = OChars[i];
        __asm
        {
            push eax
            push ecx

            movzx ecx, temp_char
            push ecx
            lea eax, EKey
            push eax
            call encrypt4
            add esp, 8
            mov temp_char, al

            pop ecx
            pop eax
        }
        EChars[i] = temp_char;
    }
    return;
}

