// Atomic compare-and-swap for 128-bit value
template<>
inline bool cas(volatile types::uint128_t *src, types::uint128_t cmp, types::uint128_t with)
{
    uint64_t cmp_lo = cmp.lo;
    uint64_t cmp_hi = cmp.hi;
    uint64_t with_lo = with.lo;
    uint64_t with_hi = with.hi;
    unsigned char result = 0;

    __asm__ __volatile__ (
        "lock; cmpxchg16b %1\n\t"
        "setz %0\n\t"
        : "=q"(result), "+m"(*src)
        : "a"(cmp_lo), "d"(cmp_hi), "b"(with_lo), "c"(with_hi)
        : "memory", "cc"
    );

    return result;
}

