// Verifies an ECDSA signature for a given message and key
bool VerifyMessage(const ECDSA<ECP, SHA256>::PublicKey& key, const std::string& message, const std::string& signature)
{
    // Split signature into r and s components (hex-encoded)
    std::string rHex = signature.substr(0, signature.length() / 2);
    std::string sHex = signature.substr(signature.length() / 2);

    std::string r, s;

    // Decode r component from hex
    HexDecoder rDecoder(new StringSink(r));
    rDecoder.Put((const byte*)rHex.data(), rHex.size());
    rDecoder.MessageEnd();

    // Decode s component from hex
    HexDecoder sDecoder(new StringSink(s));
    sDecoder.Put((const byte*)sHex.data(), sHex.size());
    sDecoder.MessageEnd();

    // Create verifier with the provided public key
    ECDSA<ECP, SHA256>::Verifier verifier(key);

    // Verify the message signature
    bool result = verifier.VerifyMessage(
        (const byte*)message.data(), 
        message.size(), 
        (const byte*)r.data(), 
        r.size(), 
        (const byte*)s.data(), 
        s.size()
    );

    return result;
}

