// Template function for dot product calculation
template<int N>
double dot(double x[], double y[])
{
    return x[N-1] * y[N-1] + dot<N-1>(x, y);
}

// Specialization for base case
template<>
double dot<1>(double x[], double y[])
{
    return x[0] * y[0];
}

