    int key = pair.first;
    Test* value = pair.second;

    // Convert value to Python object
    PyObject* py_value = SWIG_NewPointerObj(SWIG_as_voidptr(value), $descriptor(Test*), 0);

    // Insert into dictionary
    PyDict_SetItem($result, PyLong_FromLong(key), py_value);
  }
}

