     // Draws a tree at the specified position
     void drawTree(float x, float y, float height, float radius)
     {
         // Draw the trunk
         glBegin(GL_QUADS);
         glColor3f(0.5f, 0.25f, 0.0f);  // Brown
         glVertex3f(x - 0.5f, y, 0.0f);
         glVertex3f(x + 0.5f, y, 0.0f);
         glVertex3f(x + 0.5f, y + height, 0.0f);
         glVertex3f(x - 0.5f, y + height, 0.0f);
         glEnd();

         // Draw the leaves
         std::random_device rd;
         std::mt19937 gen(rd());
         std::uniform_real_distribution<> dis(-1.0f, 1.0f);
         for(int i=0;i<100;++i)
         {
             float angle = dis(gen) * 3.14159f * 2.0f;
             float distance = dis(gen) * radius;
             float leaf_x = x + distance * std::cos(angle) * 2.0f;
             float leaf_y = y + height + distance * std::sin(angle) * 2.0f;
             glBegin(GL_TRIANGLES);
             glColor3f(0.0f, 1.0f, 0.0f);  // Green
             glVertex3f(leaf_x, leaf_y, 0.0f);
             glVertex3f(leaf_x + 0.1f, leaf_y + 0.1f, 0.0f);
             glVertex3f(leaf_x - 0.1f, leaf_y + 0.1f, 0.0f);
             glEnd();
         }
     }

