         if(!window)
         {
             std::cerr << "Failed to create GLFW window" << std::endl;
             glfwTerminate();
             return -1;
         }

         glfwMakeContextCurrent(window);
         glewInit();

         while(!glfwWindowShouldClose(window))
         {
             glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

             for(int i=0;i<10;++i)
             {
                 float x = static_cast<float>(rand()) / RAND_MAX * 20.0f - 10.0f;
                 float y = static_cast<float>(rand()) / RAND_MAX * 20.0f - 10.0f;
                 float height = static_cast<float>(rand()) / RAND_MAX * 5.0f + 3.0f;
                 float radius = static_cast<float>(rand()) / RAND_MAX * 3.0f + 2.0f;
                 drawTree(x, y, height, radius);
