// Function to check if a number is prime
bool isPrime(int n, int& smallestDivisor)
{
    // Handle edge cases
    if (n <= 1)
    {
        smallestDivisor = 1; // 1 and numbers less than 1 are not prime
        return false;
    }
    if (n <= 3)
    {
        smallestDivisor = n; // 2 and 3 are prime
        return true;
    }
    if (n % 2 == 0)
    {
        smallestDivisor = 2; // Even number greater than 2 is not prime
        return false;
    }
    // Check odd divisors up to sqrt(n)
    for(int i=3; i<=std::sqrt(n); i+=2)
    {
        if(n % i == 0)
        {
            smallestDivisor = i; // Found a divisor, so n is not prime
            return false;
        }
    }
    smallestDivisor = n; // No divisors found, n is prime
    return true;
}

int main()
{
    int number;
    std::cout << "Enter a number: ";
    std::cin >> number;

    int smallestDivisor;
    if(isPrime(number, smallestDivisor))
    {
        std::cout << number << " is a prime number." << std::endl;
    }
    else
    {
        std::cout << number << " is not a prime number. The smallest divisor is " << smallestDivisor << "." << std::endl;
    }

    return 0;

}

