// FMM function wrapper for Python
static PyObject* FMM(PyObject* self, PyObject* args)
{
    PyObject *model_obj;
    PyObject *time_obj;
    PyObject *accepted_obj;
    PyObject *lat_obj;
    PyObject *lon_obj;
    PyObject *h_obj;
    int N;

    // Parse arguments
    if (!PyArg_ParseTuple(args, "OOOOOOi", &model_obj, &time_obj, &accepted_obj, &lat_obj, &lon_obj, &h_obj, &N))
    {
        return NULL;  // Return NULL on error
    }

    // Ensure the numpy C API is initialized
    import_array();

    // Convert input objects to numpy arrays
    PyArrayObject *model = (PyArrayObject *)PyArray_FROM_OTF(model_obj, NPY_FLOAT, NPY_INARRAY);
    PyArrayObject *time = (PyArrayObject *)PyArray_FROM_OTF(time_obj, NPY_FLOAT, NPY_INARRAY);
    PyArrayObject *accepted = (PyArrayObject *)PyArray_FROM_OTF(accepted_obj, NPY_BOOL, NPY_INARRAY);
    PyArrayObject *lat = (PyArrayObject *)PyArray_FROM_OTF(lat_obj, NPY_DOUBLE, NPY_INARRAY);
    PyArrayObject *lon = (PyArrayObject *)PyArray_FROM_OTF(lon_obj, NPY_DOUBLE, NPY_INARRAY);
    PyArrayObject *h = (PyArrayObject *)PyArray_FROM_OTF(h_obj, NPY_DOUBLE, NPY_INARRAY);

    // Check if the arrays are valid
    if (model == NULL || time == NULL || accepted == NULL || lat == NULL || lon == NULL || h == NULL) {
        return NULL;  // Return NULL on error
    }

    // Get pointers to the array data
    float *MODEL = (float *)PyArray_DATA(model);
    float *TIME = (float *)PyArray_DATA(time);
    bool *ACCEPTED = (bool *)PyArray_DATA(accepted);
    double *LAT = (double *)PyArray_DATA(lat);
    double *LON = (double *)PyArray_DATA(lon);
    double *H = (double *)PyArray_DATA(h);

    // Call the FMM function
    _FMM(MODEL, TIME, ACCEPTED, LAT, LON, H, N);

    // Decref the arrays
    Py_DECREF(model);
    Py_DECREF(time);
    Py_DECREF(accepted);
    Py_DECREF(lat);
    Py_DECREF(lon);
    Py_DECREF(h);

    Py_RETURN_NONE;  // Return None
}

