// Function to find maximum subarray sum using Kadane's algorithm
void maxSubArraySum(const vector<int>& arr)
{
    int global_max = INT_MIN;
    int current_max = 0;
    int start = 0;
    int max_start = 0;
    int max_end = 0;
    bool allNegatives = true;
    int maxNegative = INT_MIN;

    for(int end = 0; end < arr.size(); ++end)
    {
        current_max += arr[end];

        if(allNegatives && arr[end] > maxNegative)
        {
            maxNegative = arr[end];
        }

        if(current_max > global_max)
        {
            global_max = current_max;
            max_start = start;
            max_end = end;
            allNegatives = false;
        }

        if(current_max < 0)
        {
            current_max = 0;
            start = end + 1;
        }
    }

    if(allNegatives)
    {
        cout << "All numbers are negative, the maximum element is: " << maxNegative << endl;
        return;
    }

    // Output results
    cout << "The maximum subarray sum is: " << global_max << endl;
    cout << "The starting index of the subarray is: " << max_start << endl;
    cout << "The ending index of the subarray is: " << max_end << endl;
}

int main()
{
    vector<int> arr = {-2, -3, 4, -1, -2, 1, 5, -3}; // Example array
    maxSubArraySum(arr);
    return 0;
}

