// 128-bit unsigned integer implementation
class uint128_t {
private:
    unsigned long long high;
    unsigned long long low;

public:
    // Constructors
    uint128_t() : high(0), low(0) {}
    uint128_t(unsigned long long low_val) : high(0), low(low_val) {}
    uint128_t(unsigned long long high_val, unsigned long long low_val) : high(high_val), low(low_val) {}

    // Addition operator
    uint128_t operator+(const uint128_t& other) const {
        unsigned long long new_low = low + other.low;
        unsigned long long new_high = high + other.high + (new_low < low);
        return uint128_t(new_high, new_low);
    }

    // Subtraction operator
    uint128_t operator-(const uint128_t& other) const {
        unsigned long long new_low = low - other.low;
        unsigned long long new_high = high - other.high - (new_low > low);
        return uint128_t(new_high, new_low);
    }

    // Multiplication operator
    uint128_t operator*(const uint128_t& other) const {
        unsigned long long a = high, b = low;
        unsigned long long c = other.high, d = other.low;
        unsigned long long ac = a * c;
        unsigned long long bd = b * d;
        unsigned long long ad_plus_bc = a * d + b * c;
        unsigned long long ad_plus_bc_high = ad_plus_bc >> 64;
        unsigned long long ad_plus_bc_low = ad_plus_bc & 0xFFFFFFFFFFFFFFFFULL;
        unsigned long long new_low = bd + ad_plus_bc_low;
        unsigned long long new_high = ac + ad_plus_bc_high + (new_low < bd);
        return uint128_t(new_high, new_low);
    }

    // Division operator (placeholder)
    uint128_t operator/(const uint128_t& other) const {
        // Implement division using long division algorithm or other methods
        // This is a placeholder for simplicity
        return uint128_t();
    }

    // Equality operator
    bool operator==(const uint128_t& other) const {
        return high == other.high && low == other.low;
    }

    // Inequality operator
    bool operator!=(const uint128_t& other) const {
        return !(*this == other);
    }

    // Less than operator
    bool operator<(const uint128_t& other) const {
        if (high != other.high) return high < other.high;
        return low < other.low;
    }

    // Greater than operator
    bool operator>(const uint128_t& other) const {
        return other < *this;
    }

    // Less than or equal to operator
    bool operator<=(const uint128_t& other) const {
        return !(*this > other);
    }

    // Greater than or equal to operator
    bool operator>=(const uint128_t& other) const {
        return !(*this < other);
    }

    // Conversion to string (for debugging)
    std::string to_string() const {
        std::stringstream ss;
        ss << "0x" << std::hex << high << std::hex << low;
        return ss.str();
    }
};

#include <stdint.h>

// Function to compute the base-2 logarithm of an integer
static inline int log2(int x)
{
#if defined(__x86_64__) || defined(__i386__)
    // x86 and x86_64 architecture
    int ret;
    asm("bsr %1, %0\n"
        : "=r"(ret)
        : "r"(x)
        : "cc");
    return ret;
#elif defined(__arm__) || defined(__aarch64__)
    // ARM and AArch64 architecture
    if (x == 0) return -1; // Handle the case where x is 0
    int ret;
    asm("clz %0, %1\n"
        : "=r"(ret)
        : "r"(x));
    return 31 - ret;
#else
    // Fallback to a portable C++ implementation
    if (x == 0) return -1; // Handle the case where x is 0
    int ret = 0;
    while ((x >> ret) > 1)
    {
        ret++;
    }
    return ret;
#endif
}

