// ResizeImage function implementation
int Resize::ResizeImage(HBITMAP hBitmap)
{
    // Create a compatible device context (DC) for the bitmap
    HDC hdc = GetDC(NULL);
    HDC memDC = CreateCompatibleDC(hdc);

    // Select the bitmap into the memory DC
    HBITMAP oldBitmap = (HBITMAP)SelectObject(memDC, hBitmap);

    // Get the bitmap's information
    BITMAP bitmapInfo;
    GetObject(hBitmap, sizeof(BITMAP), &bitmapInfo);

    // Get the pixel data
    unsigned char* bitmapData = (unsigned char*)bitmapInfo.bmBits;

    // If the bitmap data is not directly accessible, use GetDIBits
    if(bitmapData == nullptr)
    {
        BITMAPINFO bmi;
        ZeroMemory(&bmi, sizeof(BITMAPINFO));
        bmi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
        bmi.bmiHeader.biWidth = bitmapInfo.bmWidth;
        bmi.bmiHeader.biHeight = bitmapInfo.bmHeight;
        bmi.bmiHeader.biPlanes = 1;
        bmi.bmiHeader.biBitCount = bitmapInfo.bmBitsPixel;
        bmi.bmiHeader.biCompression = BI_RGB;

        bitmapData = new unsigned char[bitmapInfo.bmWidth * bitmapInfo.bmHeight * (bitmapInfo.bmBitsPixel / 8)];
        GetDIBits(memDC, hBitmap, 0, bitmapInfo.bmHeight, bitmapData, &bmi, DIB_RGB_COLORS);
    }

    // Do work with the bitmapData
    // For example, print the first pixel
    // printf("First pixel: %02X %02X %02X\n", bitmapData[0], bitmapData[1], bitmapData[2]);

    // Clean up
    if(bitmapData != (unsigned char*)bitmapInfo.bmBits)
    {
        delete[] bitmapData;
    }
    SelectObject(memDC, oldBitmap);
    DeleteDC(memDC);
    ReleaseDC(NULL, hdc);

    return 0;
}

