// Structure to hold price entry information
struct PriceEntry {
    float cardPrice;
    string PriceDate;
    int Edition;
    int Rarity;
};

// Structure to hold card information
struct cardEntry {
    string cardName;
    long pesize;
    long gsize;
    vector<PriceEntry> cardPrices;
    float vThreshold;
    int fav;
};

// Global vector to store all cards
vector<cardEntry> Cards;

// Function to populate the Cards vector with sample data
void FillCards() {
    int i = 0;
    int j = 0;
    char z[32] = {0};

    for (j = 0; j < 3; j++) {
        cardEntry tmpStruct;

        sprintf(z, "Card Name: %d", i);
        tmpStruct.cardName = z;
        tmpStruct.vThreshold = 1.00;
        tmpStruct.gsize = 0;
        tmpStruct.fav = 1;

        for (i = 0; i < 3; i++) {
            PriceEntry ss;
            ss.cardPrice = i + 1;
            ss.Edition = i;
            ss.Rarity = i - 1;

            sprintf(z, "This is struct %d", i);
            ss.PriceDate = z;

            tmpStruct.cardPrices.push_back(ss);
        }

        tmpStruct.pesize = tmpStruct.cardPrices.size();
        Cards.push_back(tmpStruct);
    }
}

// Serialize PriceEntry vector into a binary buffer
void serializePriceEntries(const vector<PriceEntry>& entries, vector<uint8_t>& buffer) {
    for (const auto& entry : entries) {
        // Serialize cardPrice
        memcpy(&buffer[buffer.size()], &entry.cardPrice, sizeof(entry.cardPrice));
        buffer.resize(buffer.size() + sizeof(entry.cardPrice));

        // Serialize PriceDate size and content
        size_t dateSize = entry.PriceDate.size();
        memcpy(&buffer[buffer.size()], &dateSize, sizeof(dateSize));
        buffer.resize(buffer.size() + sizeof(dateSize));

        memcpy(&buffer[buffer.size()], entry.PriceDate.c_str(), dateSize);
        buffer.resize(buffer.size() + dateSize);

        // Serialize Edition
        memcpy(&buffer[buffer.size()], &entry.Edition, sizeof(entry.Edition));
        buffer.resize(buffer.size() + sizeof(entry.Edition));

        // Serialize Rarity
        memcpy(&buffer[buffer.size()], &entry.Rarity, sizeof(entry.Rarity));
        buffer.resize(buffer.size() + sizeof(entry.Rarity));
    }
}

// Deserialize binary buffer back into PriceEntry vector
void deserializePriceEntries(const uint8_t* buffer, size_t bufferSize, vector<PriceEntry>& entries) {
    size_t pos = 0;

    while (pos < bufferSize) {
        PriceEntry entry;

        // Deserialize cardPrice
        memcpy(&entry.cardPrice, &buffer[pos], sizeof(entry.cardPrice));
        pos += sizeof(entry.cardPrice);

        // Deserialize PriceDate size
        size_t dateSize;
        memcpy(&dateSize, &buffer[pos], sizeof(dateSize));
        pos += sizeof(dateSize);

        // Deserialize PriceDate string
        entry.PriceDate = string((const char*)&buffer[pos], dateSize);
        pos += dateSize;

        // Deserialize Edition
        memcpy(&entry.Edition, &buffer[pos], sizeof(entry.Edition));
        pos += sizeof(entry.Edition);

        // Deserialize Rarity
        memcpy(&entry.Rarity, &buffer[pos], sizeof(entry.Rarity));
        pos += sizeof(entry.Rarity);

        entries.push_back(entry);
    }
}

// Save cards to SQLite database
int SaveCards() {
    int retval;
    int CardCounter = 0;
    int PriceEntries = 0;
    char tmpQuery[256] = {0};

    int q_cnt = 5, q_size = 256;

    sqlite3_stmt *stmt;
    sqlite3 *handle;

    retval = sqlite3_open("sampledb.sqlite3", &handle);

    if (retval) {
        printf("Database connection failed\n");
        return -1;
    }

    printf("Connection successful\n");

    char create_table[] = "CREATE TABLE IF NOT EXISTS Cards (CardName TEXT, PriceData BLOB, PriceNum NUMERIC, Threshold NUMERIC, Fav NUMERIC);";

    retval = sqlite3_exec(handle, create_table, 0, 0, 0);
    if (retval) {
        printf("could not prepare statement: %s\n", sqlite3_errmsg(handle));
        return -1;
    }

    for (CardCounter = 0; CardCounter < Cards.size(); CardCounter++) {
        vector<uint8_t> buffer;
        serializePriceEntries(Cards[CardCounter].cardPrices, buffer);

        char Query[512] = {0};
        sprintf(Query, "INSERT INTO Cards (CardName, PriceData, PriceNum, Threshold, Fav) VALUES('%s', ?, %d, %f, %d)",
            Cards[CardCounter].cardName.c_str(),
            Cards[CardCounter].pesize,
            Cards[CardCounter].vThreshold,
            Cards[CardCounter].fav);

        sqlite3_prepare_v2(handle, Query, -1, &stmt, NULL);
        sqlite3_bind_blob(stmt, 1, &buffer[0], buffer.size(), SQLITE_STATIC);

        retval = sqlite3_step(stmt);
        if (retval != SQLITE_DONE) {
            printf("Could not prepare statement: %s\n", sqlite3_errmsg(handle));
        }

        sqlite3_finalize(stmt);
    }

    sqlite3_close(handle);
    return 0;
}

// Main function
int main() {
    FillCards();
    SaveCards();
    return 0;
}

#include <xmmintrin.h>

struct vector4 {
    float x, y, z, w;
};

// Performs vector calculation using SSE intrinsics
void assemblycalc(const vector4 &p, const vector4 &sc, float m, vector4 &xy)
{
    // Load input vectors
    __m128 px = _mm_loadu_ps(&p.x);
    __m128 scx = _mm_loadu_ps(&sc.x);
    __m128 m1 = _mm_set1_ps(m);
    __m128 xy1 = _mm_loadu_ps(&xy.x);

    // Calculate px * sc - py * sc
    __m128 px_sc = _mm_mul_ps(px, scx);
    __m128 py_sc = _mm_mul_ps(_mm_shuffle_ps(px, px, 0x55), _mm_shuffle_ps(scx, scx, 0xAA));
    __m128 result = _mm_sub_ps(px_sc, py_sc);

    // Scale the result
    result = _mm_mul_ps(result, m1);

    // Subtract from xy
    xy1 = _mm_sub_ps(xy1, result);

    // Store the result
    _mm_storeu_ps(&xy.x, xy1);
}

#include <cstdint>
#include <iostream>

// Computes the high 64 bits of a 128-bit multiplication result
uint64_t multiply_high_part(uint64_t i, uint64_t j)
{
    // Split each 64-bit number into high and low 32-bit parts
    uint32_t i_high = static_cast<uint32_t>(i >> 32);
    uint32_t i_low = static_cast<uint32_t>(i);
    uint32_t j_high = static_cast<uint32_t>(j >> 32);
    uint32_t j_low = static_cast<uint32_t>(j);

    // Compute partial products
    uint64_t part1 = static_cast<uint64_t>(i_high) * j_high;
    uint64_t part2 = static_cast<uint64_t>(i_high) * j_low;
    uint64_t part3 = static_cast<uint64_t>(i_low) * j_high;
    uint64_t part4 = static_cast<uint64_t>(i_low) * j_low;

    // Combine to get the high 64 bits of the full product
    uint64_t high_part = part1 + (part2 + part3 + (part4 >> 32)) >> 32;

    return high_part;
}

int main()
{
    uint64_t i = 1234567890123456789ULL;
    uint64_t j = 9876543210987654321ULL;

    uint64_t high_part = multiply_high_part(i, j);
    std::cout << "Higher part of the multiplication: " << high_part << std::endl;

    return 0;
}

