// Custom shared pointer implementation
template <typename T>
class MySharedPtr {
public:
    // Constructor
    explicit MySharedPtr(T* ptr = nullptr) : ptr_(ptr), ref_count_(new std::size_t(1)) {
        if (ptr == nullptr) {
            delete ref_count_;
            ref_count_ = nullptr;
        }
    }

    // Copy constructor
    MySharedPtr(const MySharedPtr& other) : ptr_(other.ptr_), ref_count_(other.ref_count_) {
        if (ref_count_) {
            (*ref_count_)++;
        }
    }

    // Copy assignment operator
    MySharedPtr& operator=(const MySharedPtr& other) {
        if (this != &other) {
            release();
            ptr_ = other.ptr_;
            ref_count_ = other.ref_count_;
            if (ref_count_) {
                (*ref_count_)++;
            }
        }
        return *this;
    }

    // Destructor
    ~MySharedPtr() {
        release();
    }

    // Get raw pointer
    T* get() const {
        return ptr_;
    }

    // Dereference operator
    T& operator*() const {
        return *ptr_;
    }

    // Member access operator
    T* operator->() const {
        return ptr_;
    }

    // Use count
    std::size_t use_count() const {
        return ref_count_ ? *ref_count_ : 0;
    }

private:
    // Release resources
    void release() {
        if (ref_count_ && --(*ref_count_) == 0) {
            delete ptr_;
            delete ref_count_;
        }
        ptr_ = nullptr;
        ref_count_ = nullptr;
    }

    T* ptr_;
    std::size_t* ref_count_;
};

int main()
{
    MySharedPtr<int> sptr(new int(42));
    std::cout << *sptr << " (" << sptr.use_count() << " references)" << std::endl;
    return 0;

}

