// Multiplies two quaternions
std::array<double, 4> quaternion_multiply(const std::array<double, 4>& q1, const std::array<double, 4>& q2)
{
    double w1 = q1[0], x1 = q1[1], y1 = q1[2], z1 = q1[3];
    double w2 = q2[0], x2 = q2[1], y2 = q2[2], z2 = q2[3];

    double w = w1 * w2 - x1 * x2 - y1 * y2 - z1 * z2;
    double x = w1 * x2 + x1 * w2 + y1 * z2 - z1 * y2;
    double y = w1 * y2 - x1 * z2 + y1 * w2 + z1 * x2;
    double z = w1 * z2 + x1 * y2 - y1 * x2 + z1 * w2;

    return {w, x, y, z};
}

int main()
{
    std::array<double, 4> q1 = {0.98, 0.08, 0.17, -0.01};
    std::array<double, 4> q2 = {0.70, 0.70, 0.0, 0.0};
    std::array<double, 4> result = quaternion_multiply(q1, q2);

    // Print each component of the result
    for(double val : result)
    {
        std::cout<<val<<" ";
    }
    std::cout<<std::endl;

