// Starts a process by name
void StartProcess(const std::string& processName)
{
    STARTUPINFO si;
    PROCESS_INFORMATION pi;

    ZeroMemory(&si, sizeof(si));
    si.cb = sizeof(si);
    ZeroMemory(&pi, sizeof(pi));

    if (!CreateProcessA(processName.c_str(), nullptr, nullptr, nullptr, FALSE, 0, nullptr, nullptr, &si, &pi))
    {
        std::cerr << "Failed to create process: " << GetLastError() << std::endl;
    }
}

// Monitors for a process and restarts it if not found
void MonitorProcess(const std::string& processName)
{
    while (true)
    {
        DWORD processId = 0;
        HANDLE snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);

        if (snapshot != INVALID_HANDLE_VALUE)
        {
            PROCESSENTRY32 processEntry;
            processEntry.dwSize = sizeof(PROCESSENTRY32);

            if (Process32First(snapshot, &processEntry))
            {
                do
                {
                    if (_stricmp(processEntry.szExeFile, processName.c_str()) == 0)
                    {
                        processId = processEntry.th32ProcessID;
                        break;
                    }
                } while (Process32Next(snapshot, &processEntry));
            }

            CloseHandle(snapshot);
        }

        // If process not found, start it
        if (processId == 0)
        {
            StartProcess(processName);
        }

        std::this_thread::sleep_for(std::chrono::seconds(5));
    }
}

int main()
{
    std::string processName = "YourExecutableName.exe";
    MonitorProcess(processName);
    return 0;
}

