#include <QPinchGesture>

// Custom graphics view with pinch gesture support
class MyGraphicsView : public QGraphicsView {
public:
    // Constructor
    MyGraphicsView(QGraphicsScene *scene, QWidget *parent = nullptr)
        : QGraphicsView(scene, parent) {
        setGestureEnabled(true);
    }

protected:
    // Override event handler to process gestures
    bool event(QEvent *event) override {
        if (event->type() == QEvent::Gesture)
            return gestureEvent(static_cast<QGestureEvent*>(event));
        return QGraphicsView::event(event);
    }

    // Handle gesture events
    bool gestureEvent(QGestureEvent *event) {
        if (QPinchGesture *pinch = event->gesture(Qt::PinchGesture)) {
            processPinchGesture(pinch);
        }
        return true;
    }

    // Process pinch gesture changes
    void processPinchGesture(QPinchGesture *pinch) {
        if (pinch->changeFlags() & QPinchGesture::ScaleFactorChanged) {
            qInfo() << "Scale factor changed to" << pinch->scaleFactor();
        }
    }
};

// Main entry point
int main(int argc, char *argv[]) {
    QApplication app(argc, argv);
    QGraphicsScene scene;
    MyGraphicsView view(&scene);
    view.show();
    return app.exec();
}

