// Class representing an XDM value
class XdmValue {
public:
    virtual XdmItem* itemAt(int n);
    virtual int size();
    void addXdmItem(pybind11::object val);

protected:
    std::vector<pybind11::object> values;
};

// Add an XdmItem to the value list
void XdmValue::addXdmItem(pybind11::object val) {
    values.push_back(val);
}

// Get item at position n
XdmItem* XdmValue::itemAt(int n) {
    if (n >= 0 && (unsigned int)n < values.size()) {
        return values[n].cast<XdmItem*>();
    }
    return nullptr;
}

// Return the size of the value list
int XdmValue::size() {
    return values.size();
}

