#include <iostream>
#include <stack>
#include <sstream>
#include <cctype>
#include <cmath>

// Applies the given operator to two operands
int applyOp(int a, int b, char op)
{
    switch (op)
    {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': return a / b;
        case '^': return pow(a, b);
    }
    return 0;
}

// Returns precedence of operators
int precedence(char op)
{
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    if (op == '^') return 3;
    return 0;
}

// Evaluates the given expression
int evaluate(std::string tokens)
{
    std::stack<int> values;
    std::stack<char> ops;
    std::istringstream iss(tokens);
    std::string token;

    while (iss >> token)
    {
        if (std::isdigit(token[0]))
        {
            values.push(std::stoi(token));
        }
        else if (token == "(")
        {
            ops.push('(');
        }
        else if (token == ")")
        {
            while (!ops.empty() && ops.top() != '(')
            {
                int value2 = values.top(); values.pop();
                int value1 = values.top(); values.pop();
                char op = ops.top(); ops.pop();
                values.push(applyOp(value1, value2, op));
            }
            ops.pop();
        }
        else
        {
            while (!ops.empty() && precedence(ops.top()) >= precedence(token[0]))
            {
                int value2 = values.top(); values.pop();
                int value1 = values.top(); values.pop();
                char op = ops.top(); ops.pop();
                values.push(applyOp(value1, value2, op));
            }
            ops.push(token[0]);
        }
    }

    while (!ops.empty())
    {
        int value2 = values.top(); values.pop();
        int value1 = values.top(); values.pop();
        char op = ops.top(); ops.pop();
        values.push(applyOp(value1, value2, op));
    }

    return values.top();
}

// Main function
int main()
{
    std::string expression = "1 + 2 * (3 + 4) - 5";
    // Evaluate and print result
    std::cout << "Result: " << evaluate(expression) << std::endl;
    return 0;
}

