#include <iostream>
#include <regex>
#include <string>
#include <vector>

// Extracts integers from a string
std::vector<std::string> extractIntegers(const std::string& s)
{
    std::regex re("\\d+");
    std::sregex_iterator it(s.begin(), s.end(), re);
    std::sregex_iterator end;

    std::vector<std::string> integers;
    for (; it != end; ++it)
    {
        std::string match = it->str();
        // Check boundaries to avoid decimals
        if (s.find(match) == 0 || (s[s.find(match) - 1] != '.' && s[s.find(match) - 1] != ','))
        {
            if (s.find(match) + match.length() == s.length() || (s[s.find(match) + match.length()] != '.' && s[s.find(match) + match.length()] != ','))
            {
                integers.push_back(match);
            }
        }
    }
    return integers;
}

int main()
{
    std::string s = "111.222dfg333hfg44.55";
    std::vector<std::string> integers = extractIntegers(s);

    // Print extracted integers
    for (const auto& num : integers)
    {
        std::cout << num << std::endl;
    }

    return 0;
}

