// Function to check if AVX-512 is supported
bool is_avx512_supported()
{
    // Check for AVX-512 support using CPU feature detection
    return (std::get_cpuid(7).ebx & (1 << 16)) != 0; // Check for AVX-512F
}

// AVX-2 implementation
uint64_t popcnt_AVX2_lookup(const uint8_t* data, const size_t n)
{
    const __m256i lookup = _mm256_setr_epi8(
        0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4,
        0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4
    );
    const __m256i low_mask = _mm256_set1_epi8(0x0f);
    __m256i acc = _mm256_setzero_si256();

    #define ITER { \
        const __m256i vec = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(data + i)); \
        const __m256i lo  = _mm256_and_si256(vec, low_mask); \
        const __m256i hi  = _mm256_and_si256(_mm256_srli_epi16(vec, 4), low_mask); \
        const __m256i popcnt1 = _mm256_shuffle_epi8(lookup, lo); \
        const __m256i popcnt2 = _mm256_shuffle_epi8(lookup, hi); \
        local = _mm256_add_epi8(local, popcnt1); \
        local = _mm256_add_epi8(local, popcnt2); \
        i += 32; \
    }

    size_t i = 0;
    while (i + 8 * 32 <= n)
    {
        __m256i local = _mm256_setzero_si256();
        ITER ITER ITER ITER
        ITER ITER ITER ITER
        acc = _mm256_add_epi64(acc, _mm256_sad_epu8(local, _mm256_setzero_si256()));
    }

    __m256i local = _mm256_setzero_si256();
    while (i + 32 <= n)
    {
        ITER;
    }

    acc = _mm256_add_epi64(acc, _mm256_sad_epu8(local, _mm256_setzero_si256()));

    #undef ITER

    uint64_t result = 0;
    result += static_cast<uint64_t>(_mm256_extract_epi64(acc, 0));
    result += static_cast<uint64_t>(_mm256_extract_epi64(acc, 1));
    result += static_cast<uint64_t>(_mm256_extract_epi64(acc, 2));
    result += static_cast<uint64_t>(_mm256_extract_epi64(acc, 3));

    for (; i < n; i++)
    {
        result += __builtin_popcount(data[i]);
    }

    return result;
}

// AVX-512 implementation
uint64_t avx512_vpopcnt(const uint8_t* data, const size_t size)
{
    const size_t chunks = size / 64;
    const uint8_t* end = data + size;

    __m512i accumulator = _mm512_setzero_si512();
    for (size_t i = 0; i < chunks; i++, data += 64)
    {
        const __m512i v = _mm512_loadu_si512(reinterpret_cast<const __m512i*>(data));
        const __m512i p = _mm512_popcnt_epi64(v);
        accumulator = _mm512_add_epi64(accumulator, p);
    }

    uint64_t tmp[8] __attribute__((aligned(64)));
    _mm512_store_si512(reinterpret_cast<__m512i*>(tmp), accumulator);

    uint64_t total = 0;
    for (size_t i = 0; i < 8; i++)
    {
        total += tmp[i];
    }

    while (data + 8 <= end)
    {
        total += _mm_popcnt_u64(*reinterpret_cast<const uint64_t*>(data));
        data += 8;
    }

    while (data < end)
    {
        total += __builtin_popcount(*data++);
    }

    return total;
}

// Main function to count bits
uint64_t count_bits(void* ptr, size_t size)
{
    if (is_avx512_supported())
    {
        return avx512_vpopcnt(static_cast<const uint8_t*>(ptr), size);
    }
    else
    {
        return popcnt_AVX2_lookup(static_cast<const uint8_t*>(ptr), size);
    }
}

