public ref class MyWrapper
{
public:
    // Wrapper method for the native function
    static Result Foo([Out] IntPtr% session, ObjectCallback callback, UInt64 turnKey, String^ serverAddress, String^ userId, String^ password)
    {
        // Pin managed strings to prevent garbage collection during conversion
        pin_ptr<const wchar_t> wServerAddress = PtrToStringChars(serverAddress);
        pin_ptr<const wchar_t> wUserId = PtrToStringChars(userId);
        pin_ptr<const wchar_t> wPassword = PtrToStringChars(password);

        // Convert wide strings to UTF-8 C-style strings
        const char* cServerAddress = Convert::ToUtf8String(wServerAddress);
        const char* cUserId = Convert::ToUtf8String(wUserId);
        const char* cPassword = Convert::ToUtf8String(wPassword);

        // Call the native function
        return xcFoo(&session, callback, turnKey, cServerAddress, cUserId, cPassword);
    }

private:
    // Helper method to convert wide character string to UTF-8
    static const char* Convert::ToUtf8String(const wchar_t* wstr)
    {
        // Calculate required buffer size
        int length = WideCharToMultiByte(CP_UTF8, 0, wstr, -1, NULL, 0, NULL, NULL);

        // Allocate buffer for the converted string
        char* buffer = new char[length];

        // Perform the actual conversion
        WideCharToMultiByte(CP_UTF8, 0, wstr, -1, buffer, length, NULL, NULL);

        return buffer;
    }
};

