// Function to determine FizzBuzz value
std::string fizzBuzz(int n)
{
    // Check divisibility by both 3 and 5
    if(n % 3 == 0 && n % 5 == 0)
    {
        return "FizzBuzz";
    }
    // Check divisibility by 3 only
    else if(n % 3 == 0)
    {
        return "Fizz";
    }
    // Check divisibility by 5 only
    else if(n % 5 == 0)
    {
        return "Buzz";
    }
    // Otherwise return the number as string
    else
    {
        return std::to_string(n);
    }
}

