using namespace std;

// Function to count palindromic substrings
int countSubstrings(string s)
{
    int n = s.size();
    vector<vector<bool>> dp(n, vector<bool>(n, false));
    int count = 0;

    // dp[i][j] will be 'true' if the string from index i to j is a palindrome.
    for(int len=1; len<=n; ++len) // length of the substring
    {
        for(int i=0; i<=n-len; ++i)
        {
            int j = i + len - 1; // ending index of the substring
            if(len == 1)
            {
                dp[i][j] = true; // single character is always a palindrome
            }
            else if(len == 2)
            {
                dp[i][j] = (s[i] == s[j]); // two characters are a palindrome if they are the same
            }
            else
            {
                dp[i][j] = (s[i] == s[j]) && dp[i+1][j-1]; // check if the inner substring is a palindrome
            }
            if(dp[i][j])
            {
                count++; // increment count if the substring is a palindrome
            }
        }
    }
    return count;
}

int main()
{
    string s;
    cout << "Enter a string: ";
    cin >> s;
    int result = countSubstrings(s);
    cout << "Number of palindromic substrings: " << result << endl;
    return 0;

}

