#include <thrust/host_vector.h>
#include <thrust/device_vector.h>
#include <thrust/generate.h>
#include <thrust/sort.h>
#include <thrust/reduce.h>
#include <thrust/functional.h>
#include <thrust/tuple.h>
#include <thrust/iterator/zip_iterator.h>
#include <thrust/iterator/permutation_iterator.h>
#include <thrust/sequence.h>
#include <iostream>

// Functor to compute minimum value and its row index within each column
struct min_value_and_index
{
    __host__ __device__
    thrust::tuple<int, int> operator()(const thrust::tuple<int, int>& a, const thrust::tuple<int, int>& b)
    {
        // Return tuple with smaller value; if equal, keep first (stable behavior)
        if (thrust::get<0>(a) < thrust::get<0>(b))
            return a;
        else
            return b;
    }
};

int main()
{
    // Input vectors representing rows of a matrix
    thrust::host_vector<int> h_vec1 = {3, 6, 9};
    thrust::host_vector<int> h_vec2 = {1, 5, 7};
    thrust::host_vector<int> h_vec3 = {2, 4, 8};

    // Concatenate all input vectors into one flat vector
    thrust::host_vector<int> h_concatenated;
    h_concatenated.insert(h_concatenated.end(), h_vec1.begin(), h_vec1.end());
    h_concatenated.insert(h_concatenated.end(), h_vec2.begin(), h_vec2.end());
    h_concatenated.insert(h_concatenated.end(), h_vec3.begin(), h_vec3.end());

    // Copy data from host to device
    thrust::device_vector<int> d_concatenated = h_concatenated;

    // Determine matrix dimensions: number of columns and rows
    int num_cols = h_vec1.size();
    int num_rows = d_concatenated.size() / num_cols;

    // Create key arrays for column and row indices
    thrust::device_vector<int> d_keys(d_concatenated.size());
    thrust::sequence(d_keys.begin(), d_keys.end(), 0, num_rows);

    thrust::device_vector<int> d_row_indices(d_concatenated.size());
    thrust::sequence(d_row_indices.begin(), d_row_indices.end(), 0, 1);

    // Prepare zipped tuples: (column_index, row_index, original_value)
    thrust::device_vector<thrust::tuple<int, int, int>> d_zipped(d_concatenated.size());

    // Fill zipped vector with initial placeholder values
    thrust::sequence(d_zipped.begin(), d_zipped.end(), thrust::make_tuple(0, 0, 0), thrust::make_tuple(1, 1, 1));

    // Combine keys and row indices with original values using zip iterators
    thrust::transform(
        d_keys.begin(), d_keys.end(),
        d_row_indices.begin(),
        d_zipped.begin(),
        thrust::make_zip_iterator(
            thrust::make_tuple(
                thrust::get<0>(thrust::placeholders::_1),
                thrust::get<1>(thrust::placeholders::_1),
                thrust::placeholders::_2
            )
        )
    );

    // Append original values to the tuple
    thrust::transform(
        d_zipped.begin(), d_zipped.end(),
        d_concatenated.begin(),
        d_zipped.begin(),
        thrust::make_zip_iterator(
            thrust::make_tuple(
                thrust::get<0>(thrust::placeholders::_1),
                thrust::get<1>(thrust::placeholders::_1),
                thrust::get<2>(thrust::placeholders::_1),
                thrust::placeholders::_2
            )
        )
    );

    // Sort by column index (first element of tuple), stable sort preserves relative order
    thrust::stable_sort_by_key(
        d_zipped.begin(), d_zipped.end(),
        thrust::get<0>(thrust::placeholders::_1)
    );

    // Reduce by key to find minimum value per column along with its row index
    thrust::device_vector<int> d_output_keys(num_cols);
    thrust::device_vector<thrust::tuple<int, int>> d_output_values(num_cols);

    thrust::reduce_by_key(
        thrust::make_transform_iterator(d_zipped.begin(), thrust::get<0>(thrust::placeholders::_1)),
        thrust::make_transform_iterator(d_zipped.end(),   thrust::get<0>(thrust::placeholders::_1)),
        thrust::make_transform_iterator(d_zipped.begin(), thrust::make_tuple(thrust::get<1>(thrust::placeholders::_1), thrust::get<3>(thrust::placeholders::_1))),
        d_output_keys.begin(),
        d_output_values.begin(),
        thrust::equal_to<int>(),
        min_value_and_index()
    );

    // Copy results back to host
    thrust::host_vector<int> h_output_keys = d_output_keys;
    thrust::host_vector<thrust::tuple<int, int>> h_output_values = d_output_values;

    // Output results: column-wise minimum value and its row index
    for (int i = 0; i < num_cols; ++i)
    {
        std::cout << "Column " << i << ": Min value = " << thrust::get<1>(h_output_values[i])
                  << ", Index = " << thrust::get<0>(h_output_values[i]) / num_rows << std::endl;
    }

    return 0;
}

