// Generates Fibonacci sequence up to n elements
vector<int> fibonacci(int n)
{
    vector<int> fibs;
    if (n <= 0) return fibs;
    fibs.push_back(0);
    if (n == 1) return fibs;
    fibs.push_back(1);
    for(int i=2;i<n;i++)
    {
        fibs.push_back(fibs[i-1]+fibs[i-2]);
    }
    return fibs;
}

int main()
{
    vector<int> fibs = fibonacci(10);
    // Print the Fibonacci numbers
    for(int num:fibs)
    {
        cout<<num<<" ";
    }
    return 0;

}

