#include <vector>
#include <algorithm>

// Function to find minimum and maximum values in a vector
std::pair<int, int> findMinMax(const std::vector<int>& arr)
{
    // Handle empty array case
    if(arr.empty())
    {
        return {0, 0};  // Return a pair of zeros if the array is empty
    }

    // Initialize min and max with the first element
    int minVal = arr[0];
    int maxVal = arr[0];

    // Iterate through all elements to find min and max
    for(int num : arr)
    {
        if(num < minVal)
        {
            minVal = num;
        }
        if(num > maxVal)
        {
            maxVal = num;
        }
    }

    return {minVal, maxVal};
}

int main()
{
    std::vector<int> array = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};
    auto [minVal, maxVal] = findMinMax(array);

    // Print the results
    std::cout << "Minimum: " << minVal << ", Maximum: " << maxVal << std::endl;
    return 0;

}

