// Base class definition
struct Base { };

// Derived class inherits from Base
struct Derived : public Base { };

// Container class with input method
struct Container {
    void input(const std::shared_ptr<Base>& ptr) { }
};

// Pybind11 module definition
PYBIND11_MODULE(PybindTest, m)
{
    // Bind Base class with shared_ptr support
    py::class_<Base, std::shared_ptr<Base>>(m, "Base").def(py::init<>());

    // Bind Derived class, inheriting from Base
    py::class_<Derived, std::shared_ptr<Derived>, Base>(m, "Derived").def(py::init<>());

    // Bind Container class
    py::class_<Container, std::shared_ptr<Container>>(m, "Container")
        .def(py::init<>())
        .def("input", &Container::input)
        // Overload input to accept Derived pointers
        .def("input", [](Container& self, const std::shared_ptr<Derived>& ptr) {
            self.input(ptr);  // Implicit conversion from shared_ptr<Derived> to shared_ptr<Base>
        });
}

