// Function to check if a number is happy
bool isHappy(int n)
{
    std::unordered_set<int> seen;
    while (n != 1 && seen.find(n) == seen.end())
    {
        seen.insert(n);
        int next = 0;
        while (n > 0)
        {
            int digit = n % 10;
            next += digit * digit;
            n /= 10;
        }
        n = next;
    }
    return n == 1;
}

int main()
{
    int limit = 10000;
    // Print all happy numbers up to the limit
    for (int i = 1; i <= limit; ++i)
    {
        if (isHappy(i))
        {
            std::cout << i << " ";
        }
    }
    std::cout << std::endl;
    return 0;

}

