    Node(int _val) : val(_val), left(NULL), right(NULL), next(NULL) {}

    Node(int _val, Node* _left, Node* _right, Node* _next)
        : val(_val), left(_left), right(_right), next(_next) {}
};
*/

class Solution {
public:
    // Connects each node's next pointer to its next right node
    Node* connect(Node* root) {
        if (!root) return root;

        Node* leftmost = root;

        while (leftmost) {
            Node* current = leftmost;
            Node* dummy = new Node(0); // Dummy node to simplify linking the next level
            Node* prev = dummy;

            while (current) {
                if (current->left) {
                    prev->next = current->left;
                    prev = prev->next;
                }
                if (current->right) {
                    prev->next = current->right;
                    prev = prev->next;
                }
                current = current->next;
            }

            leftmost = dummy->next; // Proceed to the next level
            delete dummy; // Free the dummy node memory
        }

        return root;
    }
};

