// Function to find the maximum value in a vector
int findMax(const std::vector<int>& arr)
{
    // Check if the array is empty
    if (arr.empty())
    {
        return INT_MIN;  // Return the smallest possible integer
    }
    int max_value = arr[0];  // Initialize max_value with the first element
    for(int num : arr)
    {
        if(num > max_value)
        {
            max_value = num;
        }
    }
    return max_value;
}

