// CUDA kernel function to process image data
__global__ void funcKernel(const float* srcptr, float* dstptr, size_t srcstep, const size_t dststep, int cols, int rows)
{
    // Calculate thread indices
    int rowInd = blockIdx.y * blockDim.y + threadIdx.y;
    int colInd = blockIdx.x * blockDim.x + threadIdx.x;

    // Boundary check
    if (rowInd >= rows || colInd >= cols)
        return;

    // Convert step sizes from bytes to element counts
    size_t srcStepElements = srcstep / sizeof(float);
    size_t dstStepElements = dststep / sizeof(float);

    // Calculate row pointers
    const float* rowsrcptr = srcptr + rowInd * srcStepElements;
    float* rowdstPtr = dstptr + rowInd * dstStepElements;

    // Process pixel value
    float val = rowsrcptr[colInd];
    if (int(val) % 90 == 0)
        rowdstPtr[colInd] = -1;
    else {
        float acos_val = acos(val);
        rowdstPtr[colInd] = acos_val;
    }
}

