#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

// Function to find the longest subarray with given sum
vector<int> findLongestSubarrayWithSum(const vector<int>& arr, int target)
{
    unordered_map<int, int> sumIndexMap; // Maps cumulative sum to its earliest index
    int maxLength = 0;
    int start = -1; // Start index of the longest subarray
    int currentSum = 0;

    // Initialize the map with sum 0 at index -1 to handle subarrays starting from index 0
    sumIndexMap[0] = -1;

    for(int i=0;i<arr.size();++i)
    {
        currentSum += arr[i];

        // Check if the current sum equals the target
        if(currentSum == target)
        {
            if(i+1 > maxLength)
            {
                maxLength = i+1;
                start = 0;
            }
        }

        // Check if (currentSum - target) has been seen before
        if(sumIndexMap.find(currentSum - target) != sumIndexMap.end())
        {
            int prevIndex = sumIndexMap[currentSum - target];
            if(i - prevIndex > maxLength)
            {
                maxLength = i - prevIndex;
                start = prevIndex + 1;
            }
        }

        // Store the current sum with its index if not already present
        if(sumIndexMap.find(currentSum) == sumIndexMap.end())
        {
            sumIndexMap[currentSum] = i;
        }
    }

    if(start == -1)
    {
        return {}; // No subarray found
    }

    return vector<int>(arr.begin() + start, arr.begin() + start + maxLength);
}

int main()
{
    vector<int> arr = {1, 2, -3, 4, 5, -3, 2};
    int target = 4;
    vector<int> result = findLongestSubarrayWithSum(arr, target);

    if(result.empty())
    {
        cout << "No subarray found" << endl;
    }
    else
    {
        cout << "Longest subarray with sum " << target << ": ";
        for(int num : result)
        {
            cout << num << " ";
        }
        cout << endl;
    }

    return 0;

}

#include <stdio.h>
#include <stdlib.h>
