// Main function to generate a boot sector image
int main(int argc, char** argv)
{
    // Machine code for printing 'A' and halting
    const char program[] =
    {
        0xb4, 0x0e,             // mov ah, 0EH
        0xb0, 0x41,             // mov al, 41H
        0x66, 0xbb, 0x0f, 0x00, // mov bx, 0FH
        0xcd, 0x10,             // int 10H
        0xf4,                   // hlt
        0xeb, 0xfe              // jmp $
    };

    // Boot signature (required for valid boot sector)
    const char boot_signature[] = {0x55, 0xAA};

    // Calculate sizes
    const int program_length = sizeof(program);
    const int boot_signature_length = sizeof(boot_signature);

    // Allocate disk buffer (512 bytes)
    char* disk = (char*)calloc(512, sizeof(char));
    if (disk == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Copy program into disk buffer
    memcpy(disk, program, program_length);

    // Copy boot signature at the end of sector (offset 510)
    memcpy(disk + 510, boot_signature, boot_signature_length);

    // Write disk image to file
    FILE* imgFile = fopen("disk.img", "wb");
    if (imgFile == NULL) {
        fprintf(stderr, "Failed to open file\n");
        free(disk);
        return 1;
    }

    fwrite(disk, sizeof(char), 512, imgFile);
    fclose(imgFile);
    free(disk);

    return 0;

}

