// Pipe server implementation
void PipeServer()
{
    HANDLE hPipe;
    char buffer[1024];
    DWORD dwRead, dwWritten;

    while (true)
    {
        // Create named pipe
        hPipe = CreateNamedPipe(
            TEXT("\\\\.\\pipe\\testpipe"),
            PIPE_ACCESS_DUPLEX,
            PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT,
            1,
            1024 * 16,
            1024 * 16,
            0,
            NULL);

        if (hPipe == INVALID_HANDLE_VALUE)
        {
            printf("CreateNamedPipe failed with %d\n", GetLastError());
            return;
        }

        // Wait for client connection
        if (ConnectNamedPipe(hPipe, NULL) != FALSE)
        {
            // Read and respond to messages
            while (ReadFile(hPipe, buffer, sizeof(buffer) - 1, &dwRead, NULL) != FALSE)
            {
                buffer[dwRead] = '\0';
                printf("Client message: %s\n", buffer);

                char response[1024] = "Message received";
                WriteFile(hPipe, response, (DWORD)strlen(response), &dwWritten, NULL);
            }
        }
        else
        {
            printf("ConnectNamedPipe failed with %d\n", GetLastError());
        }

        CloseHandle(hPipe);
    }
}

int main()
{
    // Start the pipe server
    PipeServer();
    return 0;
}

#include <iostream>
using namespace std;

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

// Function to find the LCA of two nodes
TreeNode* findLCA(TreeNode* root, int n1, int n2)
{
    if (root == NULL) return NULL;

    // If either n1 or n2 matches with root's value, report the presence by returning root
    if (root->val == n1 || root->val == n2)
    {
        return root;
    }

    // Look for keys in left and right subtrees
    TreeNode* left_lca = findLCA(root->left, n1, n2);
    TreeNode* right_lca = findLCA(root->right, n1, n2);

    // If both of the above calls return Non-NULL, then one key is present in one subtree
    // and the other is present in the other subtree. So this node is the LCA
    if (left_lca && right_lca)
    {
        return root;
    }

    // Otherwise, check if left subtree or right subtree is LCA
    return (left_lca != NULL) ? left_lca : right_lca;
}

// Function to build a sample tree
TreeNode* buildTree()
{
    TreeNode *root = new TreeNode(1);
    root->left = new TreeNode(2);
    root->right = new TreeNode(3);
    root->left->left = new TreeNode(4);
    root->left->right = new TreeNode(5);
    root->right->left = new TreeNode(6);
    root->right->right = new TreeNode(7);
    return root;
}

// Main function to test the LCA function
int main()
{
    TreeNode* root = buildTree();
    int n1 = 4, n2 = 5;
    TreeNode* lca = findLCA(root, n1, n2);
    if (lca)
    {
        cout << "LCA of " << n1 << " and " << n2 << " is " << lca->val << endl;
    }
    else
    {
        cout << "LCA of " << n1 << " and " << n2 << " does not exist" << endl;
    }
    return 0;

}

