// Main function to reverse words in each line
int main()
{
    string s;
    // Read lines until EOF
    while(getline(cin, s))
    {
        string tmp = "";
        // Process each character
        for(int i = 0; i <= s.length(); i++)
        {
            // When encountering space or end of string
            if(i == s.length() || s[i] == ' ')
            {
                // Reverse and print the current word
                for(int j = tmp.length() - 1; j >= 0; j--)
                {
                    cout << tmp[j];
                }
                // Print space if not at end of line
                if(i != s.length())
                {
                    cout << " ";
                }
                // Reset temporary string
                tmp = "";
            }
            else
            {
                // Build current word character by character
                tmp += s[i];
            }
        }
        // Newline after each processed line
        cout << endl;
    }
    return 0;
}

