// Checks if a number is prime
bool isPrime(int n)
{
    if (n <= 1) return false;
    for (int i = 2; i <= sqrt(n); i++)
    {
        if (n % i == 0) return false;
    }
    return true;
}

// Calculates the sum of the first n prime numbers
int sumOfFirstNPrimes(int n)
{
    int count = 0;
    int sum = 0;
    int num = 2;
    while (count < n)
    {
        if (isPrime(num))
        {
            sum += num;
            count++;
        }
        num++;
    }
    return sum;
}

int main()
{
    // Output the sum of the first 10 prime numbers
    std::cout << sumOfFirstNPrimes(10) << std::endl;
    return 0;

}

