            sprintf(tmp, "0x%02X", xbee.getResponse().getApiId());
            terminal.puts("Response available at API: ");
            terminal.puts(tmp);
            terminal.puts("\r\n");

            uint8_t api = xbee.getResponse().getApiId();

            // Handle RX_16_RESPONSE packets
            if (api == RX_16_RESPONSE)
            {
                Rx16Response rx16;
                xbee.getResponse().getRx16Response(rx16);

                uint8_t len = rx16.getDataLength();
                char l[20];
                sprintf(l, "%d", len);

                terminal.puts("We have data: ");
                terminal.puts(l);
                terminal.puts("\r\n");
            }
        }

        // Wait 1 second before next iteration
        wait(1);
    }
