class MyClass : public QObject {
    Q_OBJECT
    // Property declaration
    Q_PROPERTY(QVariant myProperty READ myProperty WRITE setMyProperty NOTIFY myPropertyChanged)

public:
    // Constructor
    MyClass(QObject *parent = nullptr) : QObject(parent), m_myProperty(QVariant()) {}

    // Getter method
    QVariant myProperty() const {
        return m_myProperty;
    }

    // Setter method
    void setMyProperty(const QVariant &value) {
        if (m_myProperty != value) {
            m_myProperty = value;
            emit myPropertyChanged();
        }
    }

signals:
