// Finds the maximum element in a vector
int findMax(const std::vector<int>& arr)
{
    if(arr.empty())
    {
        throw std::invalid_argument("Array is empty");
    }
    int maxElement = arr[0];
    for(int num : arr)
    {
        if(num > maxElement)
        {
            maxElement = num;
        }
    }
    return maxElement;
}

int main()
{
    std::vector<int> arr = {3, 5, 1, 8, 2, 9, 4};
    try
    {
        int maxElement = findMax(arr);
