        std::cout<<"The maximum element is: "<<maxElement<<std::endl;
    }
    catch(const std::invalid_argument& e)
    {
        std::cerr<<e.what()<<std::endl;
    }
    return 0;

}

// RDTSCP function to read the time-stamp counter
static unsigned long long rdtscp(void)
{
    unsigned int hi, lo;
    // Inline assembly to execute rdtscp instruction
    __asm__ __volatile__("rdtscp" : "=a"(lo), "=d"(hi));
    // Combine high and low parts into a 64-bit value
    return (unsigned long long)lo | ((unsigned long long)hi << 32);
}

