#include <iostream>
#include <unordered_map>
#include <list>
#include <memory>

template <typename T>
class BisynchronousList {
private:
    struct Node {
        T value;
        std::shared_ptr<Node> prev;
        std::shared_ptr<Node> next;
    };

    std::shared_ptr<Node> head;
    std::shared_ptr<Node> tail;
    std::unordered_map<T, std::shared_ptr<Node>> index;
    std::list<T> cache;

public:
    // Constructor
    BisynchronousList() : head(nullptr), tail(nullptr) {}

    // Insert at the front
    void push_front(const T& value) {
        auto new_node = std::make_shared<Node>(Node{value, nullptr, head});
        if (head) {
            head->prev = new_node;
        } else {
            tail = new_node;
        }
        head = new_node;
        index[value] = new_node;
        cache.push_front(value);
    }

    // Insert at the back
    void push_back(const T& value) {
        auto new_node = std::make_shared<Node>(Node{value, tail, nullptr});
        if (tail) {
            tail->next = new_node;
        } else {
            head = new_node;
        }
        tail = new_node;
        index[value] = new_node;
        cache.push_front(value);
    }

    // Remove from the front
    void pop_front() {
        if (!head) return;
        auto old_head = head;
        head = head->next;
        if (head) {
            head->prev = nullptr;
        } else {
            tail = nullptr;
        }
        index.erase(old_head->value);
        cache.remove(old_head->value);
    }

    // Remove from the back
    void pop_back() {
        if (!tail) return;
        auto old_tail = tail;
        tail = tail->prev;
        if (tail) {
            tail->next = nullptr;
        } else {
            head = nullptr;
        }
        index.erase(old_tail->value);
        cache.remove(old_tail->value);
    }

    // Retrieve by value
    std::shared_ptr<Node> find(const T& value) {
        auto it = index.find(value);
        if (it != index.end()) {
            cache.push_front(value);
            return it->second;
        }
        return nullptr;
    }

    // Print the list
    void print() const {
        auto current = head;
        while (current) {
            std::cout << current->value << " ";
            current = current->next;
        }
        std::cout << std::endl;
    }
};

int main()
{
    BisynchronousList<int> list;
    list.push_front(1);
    list.push_front(2);
    list.push_back(3);
    list.push_back(4);

    list.print(); // Output: 2 1 3 4

    list.pop_front();
    list.pop_back();

    list.print(); // Output: 1 3

    auto node = list.find(3);
    if (node) {
        std::cout << "Found value: " << node->value << std::endl; // Output: Found value: 3
    }

    return 0;
}

#include <coroutine>
#include <iostream>
#include <string>

// Generator template for coroutine-based iteration
template <class T>
struct generator {
    struct promise_type;
    using coro_handle = std::coroutine_handle<promise_type>;

    struct promise_type {
        T current_value;

        auto get_return_object() { return generator{coro_handle::from_promise(*this)}; }

        auto initial_suspend() { return std::suspend_always{}; }

        auto final_suspend() { return std::suspend_always{}; }

        void unhandled_exception() { std::terminate(); }

        auto yield_value(T value) {
            current_value = value;
            return std::suspend_always{};
        }

        auto yield_value() {
            return std::suspend_always{};
        }
    };

    bool next() { 
        return coro ? (coro.resume(), !coro.done()) : false; 
    }

    T value() { 
        return coro.promise().current_value; 
    }

    generator(generator const & rhs) = delete;

    generator(generator &&rhs)
        : coro(rhs.coro)
    {
        rhs.coro = nullptr;
    }

    ~generator() {
        if (coro)
            coro.destroy();
    }

private:
    generator(coro_handle h) : coro(h) {}
    coro_handle coro;
};

// String doubler coroutine implementation
class string_doubler {
public:
    struct promise_type {
        std::string input;
        std::string::iterator current;

        auto get_return_object() { 
            return string_doubler{std::coroutine_handle<promise_type>::from_promise(*this)}; 
        }

        auto initial_suspend() { 
            return std::suspend_always{}; 
        }

        auto final_suspend() { 
            return std::suspend_always{}; 
        }

        void unhandled_exception() { 
            std::terminate(); 
        }

        auto yield_value(char value) {
            return std::suspend_always{};
        }

        void set_input(const std::string& str) {
            input = str;
            current = input.begin();
        }
    };

    bool next() {
        if (coro && !coro.done()) {
            coro.resume();
            return !coro.done();
        }
        return false;
    }

    char value() {
        return coro.promise().current_value;
    }

private:
    std::coroutine_handle<promise_type> coro;

    string_doubler(std::coroutine_handle<promise_type> h) : coro(h) {}
    friend struct promise_type;
};

// Coroutine function that doubles each character
string_doubler double_string() {
    std::string input;
    char current_value;

    for (;;) {
        co_await std::suspend_always{};
        for (auto it = input.begin(); it != input.end(); ++it) {
            current_value = *it * 2; // Double the character
            co_yield current_value;
        }
    }
}

int main() {
    string_doubler gen = double_string();
    gen.promise().set_input("hello world");

    while (gen.next()) {
        std::cout << gen.value() << ' ';
    }
    std::cout << std::endl;

    gen.promise().set_input("abc");
    while (gen.next()) {
        std::cout << gen.value() << ' ';
    }
    std::cout << std::endl;

    return 0;
}

