#include <iostream>
#include <stack>
#include <string>
#include <cctype>
#include <stdexcept>

// Function to perform basic arithmetic operations
double applyOperation(double a, double b, char op)
{
    switch(op)
    {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/':
            if(b == 0) throw std::runtime_error("Division by zero");
            return a / b;
        default: throw std::runtime_error("Invalid operator");
    }
}

// Function to evaluate the expression
double evaluateExpression(const std::string& expression)
{
    std::stack<double> numbers;
    std::stack<char> operations;

    for(size_t i = 0; i < expression.length(); i++)
    {
        if(expression[i] == ' ') continue; // Skip spaces

        // If the current character is a digit, read the full number
        if(std::isdigit(expression[i]) || (expression[i] == '-' && (i == 0 || std::isspace(expression[i-1]))))
        {
            double val = 0;
            bool isNegative = expression[i] == '-';
            if(isNegative) i++;
            while(i < expression.length() && std::isdigit(expression[i]))
            {
                val = val * 10 + (expression[i] - '0');
                i++;
            }
            if(isNegative) val = -val;
            numbers.push(val);
            i--; // Adjust for the while loop increment
        }
        else if(expression[i] == '(')
        {
            operations.push(expression[i]);
        }
        else if(expression[i] == ')')
        {
            while(!operations.empty() && operations.top() != '(')
            {
                double val2 = numbers.top(); numbers.pop();
                double val1 = numbers.top(); numbers.pop();
                char op = operations.top(); operations.pop();
                numbers.push(applyOperation(val1, val2, op));
            }
            operations.pop(); // Pop '('
        }
        else if(expression[i] == '+' || expression[i] == '-' || expression[i] == '*' || expression[i] == '/')
        {
            while(!operations.empty() && ((expression[i] != '*' && expression[i] != '/') || (operations.top() == '*' || operations.top() == '/')))
            {
                double val2 = numbers.top(); numbers.pop();
                double val1 = numbers.top(); numbers.pop();
                char op = operations.top(); operations.pop();
                numbers.push(applyOperation(val1, val2, op));
            }
            operations.push(expression[i]);
        }
        else
        {
            throw std::runtime_error("Invalid character in expression");
        }
    }

    // Apply any remaining operations
    while(!operations.empty())
    {
        double val2 = numbers.top(); numbers.pop();
        double val1 = numbers.top(); numbers.pop();
        char op = operations.top(); operations.pop();
        numbers.push(applyOperation(val1, val2, op));
    }

    return numbers.top();
}

int main()
{
    std::string expression = "3 + 5 * (2 - 4)";
    try
    {
        double result = evaluateExpression(expression);
        std::cout << "Result: " << result << std::endl;
    }
    catch(const std::exception& e)
    {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;

}

