#include <string>
#include <algorithm>

// Computes the Levenshtein distance between two strings
int levenshteinDistance(const std::string &str1, const std::string &str2)
{
    int n = str1.size();
    int m = str2.size();
    // Create DP table initialized with zeros
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(m + 1, 0));

    // Initialize base cases
    for(int i=0;i<=n;++i) dp[i][0] = i;
    for(int j=0;j<=m;++j) dp[0][j] = j;

    // Fill the DP table
    for(int i=1;i<=n;++i)
    {
        for(int j=1;j<=m;++j)
        {
            if(str1[i-1] == str2[j-1])
            {
                dp[i][j] = dp[i-1][j-1];
            }
            else
            {
                dp[i][j] = 1 + std::min({dp[i-1][j], dp[i][j-1], dp[i-1][j-1]});
            }
        }
    }

    return dp[n][m];
}

int main()
{
    std::string str1 = "kitten";
    std::string str2 = "sitting";
    int distance = levenshteinDistance(str1, str2);
    // Output the result
    std::cout<<"Levenshtein Distance: "<<distance<<std::endl;
    return 0;

}

#include <iostream>
#include <vector>
using namespace std;

// Function to find the longest up-down subsequence
int longestUpDownSubsequence(vector<int>& sequence)
{
    int n = sequence.size();
    if (n <= 1)
    {
        return n;
    }

    // dpUp[i] stores the length of the longest increasing subsequence ending at index i
    // dpDown[i] stores the length of the longest decreasing subsequence starting at index i
    vector<int> dpUp(n, 1);
    vector<int> dpDown(n, 1);

    int maxLength = 1;
    for(int i=1;i<n;i++)
    {
        for(int j=0;j<i;j++)
        {
            if(sequence[i] > sequence[j])
            {
                dpUp[i] = max(dpUp[i], dpDown[j] + 1);
            }
            else if(sequence[i] < sequence[j])
            {
                dpDown[i] = max(dpDown[i], dpUp[j] + 1);
            }
        }
        maxLength = max(maxLength, max(dpUp[i], dpDown[i]));
    }

    return maxLength;
}

int main()
{
    int n;
    cin >> n;

    vector<int> sequence(n);
    for(int i=0;i<n;i++)
    {
        cin >> sequence[i];
    }

    int longestLength = longestUpDownSubsequence(sequence);
    cout << longestLength << endl;

    return 0;

}

