#include <cstdio>
#include <cstdlib>
#include <cstring>

// Structure definition for data container
struct DataStruct
{
    unsigned char* data;
    int len;
};

// External C interface for reading file
extern "C" DLLAPI int API_ReadFile(const wchar_t* filename, DataStruct** outData)
{
    // Open file in binary read mode
    FILE* file = nullptr;
    errno_t err = _wfopen_s(&file, filename, L"rb");

    // Check if file opened successfully
    if (err != 0 || file == nullptr)
    {
        return -1; // Error opening file
    }

    // Determine file size
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    // Allocate memory for output structure and data buffer
    *outData = new DataStruct();
    (*outData)->data = new unsigned char[fileSize];
    (*outData)->len = fileSize;

    // Read file contents
    size_t bytesRead = fread((*outData)->data, 1, fileSize, file);
    fclose(file);

    // Verify all bytes were read
    if (bytesRead != fileSize)
    {
        delete[] (*outData)->data;
        delete *outData;
        return -2; // Error reading file
    }

    return 0; // Success
}

// External C interface for freeing allocated data
extern "C" DLLAPI void API_FreeData(DataStruct* data)
{
    if (data != nullptr)
    {
        delete[] data->data;
        delete data;
    }
}

#include <windows.h>
#include <tlhelp32.h>

// Injects a DLL into the specified process
BOOL InjectDLL(DWORD dwProcessId, const char* szDllPath)
{
    // Open the target process with full access rights
    HANDLE hProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, dwProcessId);
    if (hProcess == NULL)
    {
        return FALSE;
    }

    // Allocate memory in the remote process for the DLL path
    LPVOID pRemotePath = VirtualAllocEx(hProcess, NULL, strlen(szDllPath) + 1, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (pRemotePath == NULL)
    {
        CloseHandle(hProcess);
        return FALSE;
    }

    // Write the DLL path to the allocated memory in the remote process
    if (!WriteProcessMemory(hProcess, pRemotePath, (LPVOID)szDllPath, strlen(szDllPath) + 1, NULL))
    {
        VirtualFreeEx(hProcess, pRemotePath, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return FALSE;
    }

    // Create a remote thread to call LoadLibraryA with the DLL path
    HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)GetProcAddress(GetModuleHandle("kernel32.dll"), "LoadLibraryA"), pRemotePath, 0, NULL);
    if (hThread == NULL)
    {
        VirtualFreeEx(hProcess, pRemotePath, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return FALSE;
    }

    // Wait for the remote thread to complete
    WaitForSingleObject(hThread, INFINITE);

    // Get the exit code of the remote thread (indicates success/failure of LoadLibrary)
    DWORD dwExitCode;
    GetExitCodeThread(hThread, &dwExitCode);

    // Cleanup resources
    CloseHandle(hThread);
    VirtualFreeEx(hProcess, pRemotePath, 0, MEM_RELEASE);
    CloseHandle(hProcess);

    // Return TRUE if LoadLibrary succeeded (exit code != 0)
    return (dwExitCode != 0);
}

