// Function to find the index of the largest element in a vector
int findIndexOfLargest(const std::vector<int>& arr)
{
    if(arr.empty())
    {
        return -1; // Return -1 if the array is empty
    }
    int maxIndex = 0;
    for(size_t i=1;i<arr.size();i++)
    {
        if(arr[i] > arr[maxIndex])
        {
            maxIndex = i;
        }
    }
    return maxIndex;
}

