#define WIDTH 800
#define HEIGHT 600

// Structure to hold screen capture data
struct ScreenCaptureData
{
    UINT width;
    UINT height;
    UINT pitch;
    BYTE* data;
};

// Global variables
HWND hwnd = nullptr;
ComPtr<ID3D11Device> pDevice = nullptr;
ComPtr<ID3D11DeviceContext> pContext = nullptr;
ComPtr<IDXGISwapChain> pSwapChain = nullptr;
ComPtr<ID3D11RenderTargetView> pRTV = nullptr;
ComPtr<ID3D11Texture2D> pTexture = nullptr;
ComPtr<ID3D11Texture2D> pStagingTexture = nullptr;
ComPtr<ID3D11ShaderResourceView> pSRV = nullptr;
ComPtr<ID3D11SamplerState> pSamplerState = nullptr;
ComPtr<IWICImagingFactory> pFactory = nullptr;

// Function declarations
LRESULT CALLBACK WindowProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam);
void InitializeD3D(HWND hwnd);
void CaptureScreen(ScreenCaptureData& data);
void CopyScreenToTexture(const ScreenCaptureData& data);
void SaveTextureToFile(LPCWSTR filename);
void Render();
void Cleanup();

int WINAPI wWinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPWSTR lpCmdLine, int nCmdShow)
{
    // Register window class
    WNDCLASSEX wc{};
    wc.cbSize = sizeof(WNDCLASSEX);
    wc.style = CS_HREDRAW | CS_VREDRAW;
    wc.lpfnWndProc = WindowProc;
    wc.hInstance = hInstance;
    wc.hCursor = LoadCursor(NULL, IDC_ARROW);
    wc.lpszClassName = L"MyWindowClass";
    RegisterClassEx(&wc);

    // Create window
    hwnd = CreateWindowEx(0, L"MyWindowClass", L"Screen Capture Demo", WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, WIDTH, HEIGHT, NULL, NULL, hInstance, NULL);
    if (hwnd == NULL)
    {
        return 0;
    }

    // Show window
    ShowWindow(hwnd, nCmdShow);

    // Initialize Direct3D
    InitializeD3D(hwnd);

    // Initialize imaging factory
    CoInitialize(nullptr);
    HRESULT hr = CoCreateInstance(CLSID_WICImagingFactory, nullptr, CLSCTX_INPROC_SERVER, IID_PPV_ARGS(&pFactory));
    if (FAILED(hr))
    {
        return 0;
    }

    // Main message loop
    MSG msg{};
    while (true)
    {
        if (PeekMessage(&msg, NULL, 0, 0, PM_REMOVE))
        {
            if (msg.message == WM_QUIT)
            {
                break;
            }

            TranslateMessage(&msg);
            DispatchMessage(&msg);
        }

        // Render frame
        Render();
    }

    // Cleanup resources
    Cleanup();
    CoUninitialize();
    return static_cast<int>(msg.wParam);
}

LRESULT CALLBACK WindowProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    switch (uMsg)
    {
    case WM_DESTROY:
    {
        PostQuitMessage(0);
        return 0;
    }
    default:
        return DefWindowProc(hwnd, uMsg, wParam, lParam);
    }
}

void InitializeD3D(HWND hwnd)
{
    // Describe swap chain
    DXGI_SWAP_CHAIN_DESC scd{};
    scd.BufferCount = 1;
    scd.BufferDesc.Width = WIDTH;
    scd.BufferDesc.Height = HEIGHT;
    scd.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    scd.BufferDesc.RefreshRate.Numerator = 60;
    scd.BufferDesc.RefreshRate.Denominator = 1;
    scd.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
    scd.OutputWindow = hwnd;
    scd.SampleDesc.Count = 1;
    scd.SampleDesc.Quality = 0;
    scd.Windowed = TRUE;

    // Create device, context, and swap chain
    HRESULT hr = D3D11CreateDeviceAndSwapChain(nullptr, D3D_DRIVER_TYPE_HARDWARE, nullptr, 0, nullptr, 0, D3D11_SDK_VERSION,
        &scd, &pSwapChain, &pDevice, nullptr, &pContext);
    if (FAILED(hr))
    {
        return;
    }

    // Get back buffer from swap chain
    ComPtr<ID3D11Texture2D> pBackBuffer;
    hr = pSwapChain->GetBuffer(0, IID_PPV_ARGS(&pBackBuffer));
    if (FAILED(hr))
    {
        return;
    }

    // Create render target view
    hr = pDevice->CreateRenderTargetView(pBackBuffer.Get(), nullptr, &pRTV);
    if (FAILED(hr))
    {
        return;
    }

    // Create texture for screen capture
    D3D11_TEXTURE2D_DESC desc{};
    desc.Width = WIDTH;
    desc.Height = HEIGHT;
    desc.MipLevels = 1;
    desc.ArraySize = 1;
    desc.Format = DXGI_FORMAT_B8G8R8A8_UNORM;
    desc.SampleDesc.Count = 1;
    desc.Usage = D3D11_USAGE_DYNAMIC;
    desc.BindFlags = D3D11_BIND_SHADER_RESOURCE;
    desc.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
    hr = pDevice->CreateTexture2D(&desc, nullptr, &pTexture);
    if (FAILED(hr))
    {
        return;
    }

    // Create staging texture
    desc.Usage = D3D11_USAGE_STAGING;
    desc.BindFlags = 0;
    desc.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
    hr = pDevice->CreateTexture2D(&desc, nullptr, &pStagingTexture);
    if (FAILED(hr))
    {
        return;
    }

    // Create shader resource view
    D3D11_SHADER_RESOURCE_VIEW_DESC srvDesc{};
    srvDesc.Format = desc.Format;
    srvDesc.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
    srvDesc.Texture2D.MipLevels = desc.MipLevels;
    srvDesc.Texture2D.MostDetailedMip = 0;
    hr = pDevice->CreateShaderResourceView(pTexture.Get(), &srvDesc, &pSRV);
    if (FAILED(hr))
    {
        return;
    }

    // Create sampler state
    D3D11_SAMPLER_DESC samplerDesc{};
    samplerDesc.Filter = D3D11_FILTER_MIN_MAG_MIP_LINEAR;
    samplerDesc.AddressU = D3D11_TEXTURE_ADDRESS_CLAMP;
    samplerDesc.AddressV = D3D11_TEXTURE_ADDRESS_CLAMP;
    samplerDesc.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
    samplerDesc.ComparisonFunc = D3D11_COMPARISON_NEVER;
    samplerDesc.MinLOD = 0;
    samplerDesc.MaxLOD = D3D11_FLOAT32_MAX;
    hr = pDevice->CreateSamplerState(&samplerDesc, &pSamplerState);
    if (FAILED(hr))
    {
        return;
    }
}

void CaptureScreen(ScreenCaptureData& data)
{
    // Get DXGI factory
    ComPtr<IDXGIFactory1> pDXGIFactory = nullptr;
    HRESULT hr = CreateDXGIFactory1(IID_PPV_ARGS(&pDXGIFactory));
    if (FAILED(hr))
    {
        return;
    }

    // Get adapter
    ComPtr<IDXGIAdapter1> pAdapter = nullptr;
    hr = pDXGIFactory->EnumAdapters1(0, &pAdapter);
    if (FAILED(hr))
    {
        return;
    }

    // Get output
    ComPtr<IDXGIOutput> pOutput = nullptr;
    hr = pAdapter->EnumOutputs(0, &pOutput);
    if (FAILED(hr))
    {
        return;
    }

    // Get display mode list
    UINT modeCount = 0;
    DXGI_MODE_DESC* pModeList = nullptr;
    hr = pOutput->GetDisplayModeList(DXGI_FORMAT_B8G8R8A8_UNORM, 0, &modeCount, nullptr);
    if (FAILED(hr))
    {
        return;
    }
    pModeList = new (std::nothrow) DXGI_MODE_DESC[modeCount];
    if (pModeList == nullptr)
    {
        return;
    }
    hr = pOutput->GetDisplayModeList(DXGI_FORMAT_B8G8R8A8_UNORM, 0, &modeCount, pModeList);
    if (FAILED(hr))
    {
        delete[] pModeList;
        return;
    }

    // Get desktop surface
    ComPtr<IDXGISurface1> pDesktopSurface = nullptr;
    hr = pOutput->GetDesktopSurface(&pDesktopSurface);
    if (FAILED(hr))
    {
        delete[] pModeList;
        return;
    }

    // Create DirectX 11 device and context
    ComPtr<ID3D11Device> pDevice = nullptr;
    ComPtr<ID3D11DeviceContext> pContext = nullptr;
    D3D_FEATURE_LEVEL featureLevel = D3D_FEATURE_LEVEL_11_0;
    hr = D3D11CreateDevice(
        pAdapter.Get(),
        D3D_DRIVER_TYPE_UNKNOWN,
        NULL,
        D3D11_CREATE_DEVICE_BGRA_SUPPORT,
        &featureLevel,
        1,
        D3D11_SDK_VERSION,
        &pDevice,
        NULL,
        &pContext
    );
    if (FAILED(hr))
    {
        delete[] pModeList;
        return;
    }

    // Create texture for screen capture
    D3D11_TEXTURE2D_DESC desc{};
    desc.Width = pModeList[0].Width;
    desc.Height = pModeList[0].Height;
    desc.MipLevels = 1;
    desc.ArraySize = 1;
    desc.Format = DXGI_FORMAT_B8G8R8A8_UNORM;
    desc.SampleDesc.Count = 1;
    desc.Usage = D3D11_USAGE_STAGING;
    desc.BindFlags = 0;
    desc.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
    ComPtr<ID3D11Texture2D> pTexture = nullptr;
    hr = pDevice->CreateTexture2D(&desc, nullptr, &pTexture);
    if (FAILED(hr))
    {
        delete[] pModeList;
        return;
    }

    // Copy desktop surface to texture
    pContext->CopyResource(pTexture.Get(), pDesktopSurface.Get());

    // Map texture to get screen capture data
    D3D11_MAPPED_SUBRESOURCE mappedResource{};
    hr = pContext->Map(pTexture.Get(), 0, D3D11_MAP_READ, 0, &mappedResource);
    if (FAILED(hr))
    {
        delete[] pModeList;
        return;
    }

    // Fill screen capture data structure
    data.width = pModeList[0].Width;
    data.height = pModeList[0].Height;
    data.pitch = mappedResource.RowPitch;
    data.data = new (std::nothrow) BYTE[data.pitch * data.height];
    if (data.data == nullptr)
    {
        pContext->Unmap(pTexture.Get(), 0);
        delete[] pModeList;
        return;
    }
    memcpy_s(data.data, data.pitch * data.height, mappedResource.pData, mappedResource.DepthPitch);

    // Unmap texture
    pContext->Unmap(pTexture.Get(), 0);

    // Cleanup
    delete[] pModeList;
}

void CopyScreenToTexture(const ScreenCaptureData& data)
{
    // Map staging texture
    D3D11_MAPPED_SUBRESOURCE mappedResource{};
    HRESULT hr = pContext->Map(pStagingTexture.Get(), 0, D3D11_MAP_WRITE_DISCARD, 0, &mappedResource);
    if (FAILED(hr))
    {
        return;
    }

    // Copy screen capture data to staging texture
    memcpy_s(mappedResource.pData, mappedResource.DepthPitch, data.data, data.pitch * data.height);

    // Unmap staging texture
    pContext->Unmap(pStagingTexture.Get(), 0);

    // Copy staging texture to main texture
    pContext->CopyResource(pTexture.Get(), pStagingTexture.Get());
}

void SaveTextureToFile(LPCWSTR filename)
{
    // Open write stream
    ComPtr<IWICStream> pStream = nullptr;
    HRESULT hr = pFactory->CreateStream(&pStream);
    if (FAILED(hr))
    {
        return;
    }

    hr = pStream->InitializeFromFilename(filename, GENERIC_WRITE);
    if (FAILED(hr))
    {
        return;
    }

    // Create PNG encoder
    ComPtr<IWICBitmapEncoder> pEncoder = nullptr;
    hr = pFactory->CreateEncoder(GUID_ContainerFormatPng, nullptr, &pEncoder);
    if (FAILED(hr))
    {
        return;
    }

    // Initialize encoder with stream
    hr = pEncoder->Initialize(pStream.Get(), WICBitmapEncoderNoCache);
    if (FAILED(hr))
    {
        return;
    }

    // Create bitmap from DXGISurface
    ComPtr<IDXGISurface> pSurface = nullptr;
    hr = pTexture->QueryInterface(&pSurface);
    if (FAILED(hr))
    {
        return;
    }
    ComPtr<IWICBitmap> pBitmap = nullptr;
    hr = pFactory->CreateBitmapFromDXGISurface(pSurface.Get(), nullptr, &pBitmap);
    if (FAILED(hr))
    {
        return;
    }

    // Create frame encoder
    ComPtr<IWICBitmapFrameEncode> pFrameEncode = nullptr;
    hr = pEncoder->CreateNewFrame(&pFrameEncode, nullptr);
    if (FAILED(hr))
    {
        return;
    }
    hr = pFrameEncode->Initialize(nullptr);
    if (FAILED(hr))
    {
        return;
    }

    // Set frame size
    UINT width = 0, height = 0;
    hr = pBitmap->GetSize(&width, &height);
    if (FAILED(hr))
    {
        return;
    }
    hr = pFrameEncode->SetSize(width, height);
    if (FAILED(hr))
    {
        return;
    }

    // Set pixel format
    WICPixelFormatGUID format = {};
    hr = pBitmap->GetPixelFormat(&format);
    if (FAILED(hr))
    {
        return;
    }
    hr = pFrameEncode->SetPixelFormat(&format);
    if (FAILED(hr))
    {
        return;
    }

    // Write bitmap to frame
    hr = pFrameEncode->WriteSource(pBitmap.Get(), nullptr);
    if (FAILED(hr))
    {
        return;
    }

    // Commit frame and encoder
    hr = pFrameEncode->Commit();
    if (FAILED(hr))
    {
        return;
    }
    hr = pEncoder->Commit();
    if (FAILED(hr))
    {
        return;
    }
}

void Render()
{
    // Capture screen to texture
    ScreenCaptureData data{};
    CaptureScreen(data);
    if (data.data == nullptr)
    {
        return;
    }
    CopyScreenToTexture(data);

    // Clear render target
    float clearColor[4] = { 0, 0, 0, 1 };
    pContext->ClearRenderTargetView(pRTV.Get(), clearColor);

    // Set render target and viewport
    pContext->OMSetRenderTargets(1, pRTV.GetAddressOf(), nullptr);
    D3D11_VIEWPORT viewport{};
    viewport.Width = WIDTH;
    viewport.Height = HEIGHT;
    viewport.MinDepth = 0;
    viewport.MaxDepth = 1;
    viewport.TopLeftX = 0;
    viewport.TopLeftY = 0;
    pContext->RSSetViewports(1, &viewport);

    // Set shader resources and sampler
    UINT slot = 0;
    pContext->PSSetShaderResources(slot, 1, pSRV.GetAddressOf());
    pContext->PSSetSamplers(slot, 1, pSamplerState.GetAddressOf());

    // Draw full-screen quad
    pContext->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLESTRIP);
    pContext->Draw(4, 0);

    // Present swap chain
    pSwapChain->Present(0, 0);
}

void Cleanup()
{
    // Release all resources
    hwnd = nullptr;
    pContext = nullptr;
    pSwapChain = nullptr;
    pRTV = nullptr;
    pTexture = nullptr;
    pStagingTexture = nullptr;
    pSRV = nullptr;
    pSamplerState = nullptr;
    pDevice = nullptr;
}

