// Custom typemap for three integer array pointers
%typemap(in) (int *a, int *b, int *c) {
    // Check if input is a numpy array
    if (!PyArray_Check($input)) {
        PyErr_SetString(PyExc_TypeError, "Expected a numpy array");
        return NULL;
    }

    // Cast inputs to PyArrayObject pointers
    PyArrayObject *array_a = (PyArrayObject *)$input;
    PyArrayObject *array_b = (PyArrayObject *)$2_input;
    PyArrayObject *array_c = (PyArrayObject *)$3_input;

    // Verify array data type is int32
    if (PyArray_TYPE(array_a) != NPY_INT32 || 
        PyArray_TYPE(array_b) != NPY_INT32 || 
        PyArray_TYPE(array_c) != NPY_INT32) {
        PyErr_SetString(PyExc_TypeError, "Array must be of int32 type");
        return NULL;
    }

    // Verify arrays are one-dimensional
    if (PyArray_NDIM(array_a) != 1 || 
        PyArray_NDIM(array_b) != 1 || 
        PyArray_NDIM(array_c) != 1) {
        PyErr_SetString(PyExc_TypeError, "Array must be one-dimensional");
        return NULL;
    }

    // Verify all arrays have the same length
    if (PyArray_DIM(array_a, 0) != PyArray_DIM(array_b, 0) || 
        PyArray_DIM(array_a, 0) != PyArray_DIM(array_c, 0)) {
        PyErr_SetString(PyExc_ValueError, "Arrays must have the same length");
        return NULL;
    }

    // Extract raw data pointers
    $1 = (int *)PyArray_DATA(array_a);
    $2 = (int *)PyArray_DATA(array_b);
    $3 = (int *)PyArray_DATA(array_c);
}

