// Function to find the largest number in an array
int findLargestNumber(int arr[], int size)
{
    // Handle empty array case
    if(size == 0)
    {
        return INT_MIN;  // Return the smallest possible integer if the array is empty
    }
    int largest = arr[0];
    for(int i=1;i<size;++i)
    {
        if(arr[i] > largest)
        {
            largest = arr[i];
        }
    }
    return largest;
}

int main()
{
    int array[] = {3, 5, 1, 8, 2};
    int size = sizeof(array) / sizeof(array[0]);
    // Output the largest number
    std::cout<<"The largest number is: "<<findLargestNumber(array, size)<<std::endl;
    return 0;

}

