#include <iostream>

// Back substitution solver for lower triangular system
void backsolve(const int*__restrict__ Lp,
               const int*__restrict__ Li,
               const double*__restrict__ Lx,
               const int n,
               double*__restrict__ x)
{
    // Process in blocks of 4 for efficiency
    for(int i=n-1; i>=0; i-=4)
    {
        for(int j=Lp[i]; j<Lp[i+1]; ++j)
        {
            x[i] -= Lx[j] * x[Li[j]];
        }
        for(int j=Lp[i-1]; j<Lp[i]; ++j)
        {
            x[i-1] -= Lx[j] * x[Li[j]];
        }
        for(int j=Lp[i-2]; j<Lp[i-1]; ++j)
        {
            x[i-2] -= Lx[j] * x[Li[j]];
        }
        for(int j=Lp[i-3]; j<Lp[i-2]; ++j)
        {
            x[i-3] -= Lx[j] * x[Li[j]];
        }
    }

    // Handle remaining elements (less than 4)
    for(int i=(n%4)-1; i>=0; --i)
    {
        for(int j=Lp[i]; j<Lp[i+1]; ++j)
        {
            x[i] -= Lx[j] * x[Li[j]];
        }
    }
}

