// Allocates executable memory using mmap
void* allocate_executable_memory(size_t size)
{
    void *ptr = mmap(
        0,
        size,
        PROT_READ | PROT_WRITE | PROT_EXEC,
        MAP_PRIVATE | MAP_ANONYMOUS,
        -1,
        0
    );
    if (ptr == (void*)(-1))
    {
        perror("mmap");
        return nullptr;
    }
    return ptr;
}

// Copies machine code into the allocated memory
void emit_code_into_memory(size_t code_length, const uint8_t *code, void *memory)
{
    memcpy(reinterpret_cast<uint8_t*>(memory), code, code_length);
}

typedef void (*JittedFunc)();

int main()
{
    // Read the machine code from the binary file
    int fd = open("test.bin", O_RDONLY);
    if (fd == -1)
    {
        perror("open");
        return 1;
    }

    struct stat st;
    if (fstat(fd, &st) == -1)
    {
        perror("fstat");
        close(fd);
        return 1;
    }

    size_t code_length = st.st_size;
    uint8_t code[code_length];
    if (read(fd, code, code_length) != (ssize_t)code_length)
    {
        perror("read");
        close(fd);
        return 1;
    }
    close(fd);

    void *memory = allocate_executable_memory(code_length);
    if (memory == nullptr)
    {
        return 1;
    }

    emit_code_into_memory(code_length, code, memory);
    JittedFunc func = reinterpret_cast<JittedFunc>(memory);
    func();

    // Clean up
    munmap(memory, code_length);

    return 0;
}

