};

struct Vec3f {
    float r, g, b;
    Vec3f operator*(float scalar) const {
        return {r * scalar, g * scalar, b * scalar};
    }
    Vec3f operator+(const Vec3f& other) const {
        return {r + other.r, g + other.g, b + other.b};
    }
};

Vec3f toFloat(const Color& color) {
    return {color.r, color.g, color.b};
}

// Bilinear interpolation function
Vec3f bilinearInterpolation(const Color* pixelCache, int y1, int y2, int x1, int x2, float x, float y, int sizeX)
{
#ifdef USE_SIMD
    // Load color values using SIMD
    __m128 c11 = _mm_loadu_ps((float*)&pixelCache[y1 * sizeX + x1]);
    __m128 c12 = _mm_loadu_ps((float*)&pixelCache[y2 * sizeX + x1]);
    __m128 c22 = _mm_loadu_ps((float*)&pixelCache[y2 * sizeX + x2]);
    __m128 c21 = _mm_loadu_ps((float*)&pixelCache[y1 * sizeX + x2]);

    // Compute interpolation weights
    float s11 = (x2 - x) * (y2 - y);
    float s12 = (x2 - x) * (y - y1);
    float s22 = (x - x1) * (y - y1);
    float s21 = (x - x1) * (y2 - y);

    // Broadcast weights to SIMD registers
    __m128 ms11 = _mm_set1_ps(s11);
    __m128 ms12 = _mm_set1_ps(s12);
    __m128 ms22 = _mm_set1_ps(s22);
    __m128 ms21 = _mm_set1_ps(s21);

    // Perform weighted sum: c11*s11 + c12*s12 + c21*s21 + c22*s22
    __m128 result = _mm_add_ps(
        _mm_add_ps(
            _mm_mul_ps(c11, ms11),
            _mm_mul_ps(c12, ms12)
        ),
        _mm_add_ps(
            _mm_mul_ps(c21, ms21),
            _mm_mul_ps(c22, ms22)
        )
    );

    // Store result into Vec3f
    Vec3f color;
    _mm_storeu_ps((float*)&color, result);
    return color;

#else
    // Scalar implementation
    const Vec3f c11 = toFloat(pixelCache[y1 * sizeX + x1]);
    const Vec3f c12 = toFloat(pixelCache[y2 * sizeX + x1]);
    const Vec3f c22 = toFloat(pixelCache[y2 * sizeX + x2]);
    const Vec3f c21 = toFloat(pixelCache[y1 * sizeX + x2]);

    const Vec3f colour =
            c11 * (x2 - x) * (y2 - y) +
            c21 * (x - x1) * (y2 - y) +
            c12 * (x2 - x) * (y - y1) +
            c22 * (x - x1) * (y - y1);

    return colour;
#endif
}

