// Helper function to check CUDA errors
inline void __checkCudaErrors(cudaError_t err, const char* file, const int line)
{
    if (err != cudaSuccess)
    {
        fprintf(stderr, "CUDA error at %s:%d code=%d(%s) \"%s\" \n", file, line, err, cudaGetErrorString(err), "CUDA API call");
        exit(EXIT_FAILURE);
    }
}

