// Wrapper class for converting C# list to C++ list
public ref class ManagedWrapper
{
public:
    // Converts a C# List<String^> to std::list<std::wstring>
    static std::list<std::wstring> ConvertList(List<String^>^ csharpList)
    {
        std::list<std::wstring> cppList;
        for each (String^ item in csharpList)
        {
            std::wstring wstr = marshal_as<std::wstring>(item);
            cppList.push_back(wstr);
        }
        return cppList;
    }
};

