// Calculates CRC-16 checksum
quint16 calculateCRC(QByteArray data)
{
    quint16 crc = 0xFFFF; // initial value

    for(int i=0;i<data.size();i++)
    {
        crc ^= (quint16)data.at(i) << 8;
        for(int j=0;j<8;j++)
        {
            if(crc & 0x8000)
            {
                crc = (crc << 1) ^ 0x1021; // 0x1021 is the polynomial
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

int main(int argc, char *argv[])
{
    QCoreApplication a(argc, argv);

    QByteArray data("Hello World");
    quint16 crc = calculateCRC(data);

    // Output CRC value
    qDebug() << "CRC: 0x" << QString::number(crc, 16);

    return a.exec();
}

