// Calculator class for basic arithmetic expressions
class Calculator {
public:
    // Constructor initializes the expression
    Calculator(const std::string& expr) : expression(expr) {}

    // Public method to evaluate the expression
    double evaluate() {
        if (expression.empty()) {
            throw std::invalid_argument("Expression is empty");
        }
        return evaluateExpression(0, expression.length() - 1);
    }

private:
    std::string expression;

    // Recursive helper to evaluate sub-expressions
    double evaluateExpression(int start, int end) {
        std::stack<double> numbers;
        std::stack<char> operators;
        int currentNumber = 0;
        char currentOperator = '+';

        for (int i = start; i <= end; i++) {
            if (std::isdigit(expression[i])) {
                currentNumber = currentNumber * 10 + (expression[i] - '0');
            } else if (expression[i] == '(') {
                int j = i;
                int count = 1;
                while (count != 0) {
                    i++;
                    if (expression[i] == '(') count++;
                    if (expression[i] == ')') count--;
                }
                currentNumber = evaluateExpression(j + 1, i - 1);
            }
            // Handle operators and end of expression
            if (!std::isdigit(expression[i]) && !std::isspace(expression[i]) || i == end) {
                applyOperator(numbers, currentOperator, currentNumber);
                currentNumber = 0;
                if (isOperator(expression[i])) {
                    currentOperator = expression[i];
                }
            }
        }

        return numbers.top();
    }

    // Apply operator to the top of the stack
    void applyOperator(std::stack<double>& numbers, char op, double num) {
        switch (op) {
            case '+': numbers.push(num); break;
            case '-': numbers.push(-num); break;
            case '*': numbers.top() *= num; break;
            case '/':
                if (num == 0) throw std::runtime_error("Division by zero");
                numbers.top() /= num;
                break;
            default: throw std::invalid_argument("Invalid operator");
        }
    }

    // Check if character is an operator
    bool isOperator(char ch) {
        return ch == '+' || ch == '-' || ch == '*' || ch == '/';
    }
};

// Main function demonstrating usage
int main()
{
    try {
        Calculator calc("3 + 5 * (10 - 4) / 2");
        std::cout << "Result: " << calc.evaluate() << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;

}

