// Main function to call Python functions from two folders
int main()
{
    PyObject *pName, *pModule, *pDict, *pFunc;

    // Disable bytecode generation
    setenv("PYTHONDONTWRITEBYTECODE", " ", 1);

    // Initialize the Python Interpreter
    Py_Initialize();

    // CALL FUNCTION FROM FOLDER 1:
    std::wstring pathWide = L"./Folder 1";
    std::string path = std::string(pathWide.begin(), pathWide.end());

    // Append the directory to the Python path
    PyObject *sysPath = PySys_GetObject((char*)"path");
    PyList_Append(sysPath, PyUnicode_FromString(path.c_str()));

    // Build the name object
    pName = PyUnicode_FromString((char*)"python_function");
    // Load the module object
    pModule = PyImport_Import(pName);
    if (pModule == NULL) {
        PyErr_Print();
        goto cleanup;
    }
    // pDict is a borrowed reference
    pDict = PyModule_GetDict(pModule);
    // pFunc is also a borrowed reference
    pFunc = PyDict_GetItemString(pDict, (char*)"function");

    if (pFunc != NULL)
    {
        if (PyCallable_Check(pFunc))
        {
            PyObject *pResult;

            pResult = PyObject_CallFunction(pFunc, "");
            Py_XDECREF(pResult);
        }
        else {PyErr_Print();}
    }
    else {std::cout << "pFunc is NULL!" << std::endl;}

    // Clean up after the first call
    Py_XDECREF(pFunc);
    Py_XDECREF(pDict);
    Py_XDECREF(pModule);
    Py_XDECREF(pName);

    // CALL FUNCTION FROM FOLDER 2:
    pathWide = L"./Folder 2";
    path = std::string(pathWide.begin(), pathWide.end());

    // Append the directory to the Python path
    PyList_Append(sysPath, PyUnicode_FromString(path.c_str()));

    // Build the name object
    pName = PyUnicode_FromString((char*)"python_function");
    // Load the module object
    pModule = PyImport_Import(pName);
    if (pModule == NULL) {
        PyErr_Print();
        goto cleanup;
    }
    // pDict is a borrowed reference
    pDict = PyModule_GetDict(pModule);
    // pFunc is also a borrowed reference
    pFunc = PyDict_GetItemString(pDict, (char*)"function");

    if (pFunc != NULL)
    {
        if (PyCallable_Check(pFunc))
        {
            PyObject *pResult;

            pResult = PyObject_CallFunction(pFunc, "");
            Py_XDECREF(pResult);
        }
        else {PyErr_Print();}
    }
    else {std::cout << "pFunc is NULL!" << std::endl;}

cleanup:
    // Final cleanup
    Py_XDECREF(pFunc);
    Py_XDECREF(pDict);
    Py_XDECREF(pModule);
    Py_XDECREF(pName);

    // Finish the Python Interpreter
    Py_Finalize();

    return 0;
}

