// Kernel function
__global__ void updateParticles(float* positions_x, float* positions_y, float* positions_z,
                                float* velocities_x, float* velocities_y, float* velocities_z,
                                int numParticles, float deltaTime)
{
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    if(idx < numParticles)
    {
        positions_x[idx] += velocities_x[idx] * deltaTime;
        positions_y[idx] += velocities_y[idx] * deltaTime;
        positions_z[idx] += velocities_z[idx] * deltaTime;
    }
}

