updateParticles<<<numBlocks, blockSize>>>(d_positions_x, d_positions_y, d_positions_z,
                                          d_velocities_x, d_velocities_y, d_velocities_z,
                                          numParticles, deltaTime);

// Copy results back to CPU and free GPU memory
