// Writes buffer to file in chunks
void xxwrite(const unsigned char *buf, size_t wlen, FILE *fo)
{
    size_t xlen;

    for (; wlen > 0; wlen -= xlen, buf += xlen) {
        xlen = wlen;
        if (xlen > 1024)
            xlen = 1024;
        xlen = fwrite(buf, 1, xlen, fo);
        if (xlen != 1024 && ferror(fo)) {
            throw std::runtime_error("Error writing to stdout");
        }
        fflush(fo);
    }
}

int main(int argc, char **argv)
{
    // Check argument count
    if (argc < 5) {
        std::cerr << "Usage: " << argv[0] << " totalbytes bytechunk height width" << std::endl;
        return 1;
    }

    long totalbytes = std::stol(argv[argc-4]);
    long bytechunk = std::stol(argv[argc-3]);
    long height = std::stol(argv[argc-2]);
    long width = std::stol(argv[argc-1]);
    long offset = totalbytes / sizeof(double) / 2;

    std::vector<double> data(totalbytes / sizeof(double));
    int columnindex = 0;
    size_t count = 0;

    // Read in data from pipe
    while (count < totalbytes) {
        size_t bytes_read = fread(&data[columnindex], 1, bytechunk, stdin);
        if (bytes_read != bytechunk && ferror(stdin)) {
            throw std::runtime_error("Error reading from stdin");
        }
        columnindex += bytechunk / sizeof(double);
        count += bytes_read;
    }

    // Calculate the data transform
    MutualInformation MI;
    MI.Initialize(data.data(), height, width, offset);
    MI.calcMI();
    count = 0;
    columnindex = 0;

    std::vector<double> output = MI.getOutput();
    while (count < totalbytes / 2) {
        size_t bytes_written = xxwrite((const unsigned char*)&output[columnindex], bytechunk, stdout);
        if (bytes_written != bytechunk) {
            throw std::runtime_error("Error writing to stdout");
        }
        count += bytes_written;
        columnindex += bytechunk / sizeof(double);
    }

    return 0;
}

