int PixyInterpreter::get_frame(unsigned char *current_frame, int frame_size)
{
    unsigned int size_frame = 8;
    unsigned char *pixels;
    int32_t response, fourcc;
    int8_t renderflags;
    int return_value;
    uint16_t width, height;
    uint32_t numPixels;

    // Stop camera operations
    return_value = pixy_command("stop", END_OUT_ARGS, &response, END_IN_ARGS);
    printf("STOP returned %d response %d\n", return_value, response);

    response = 0;
    // Request frame from camera
    return_value = pixy_command("cam_getFrame", 0x01, 0x21, 0x02, 0, 0x02, 0, 0x02, 320, 0x02, 200, 0, &response, &fourcc, &renderflags, &width, &height, &numPixels, &pixels, 0);

    printf("getFrame returned %d response %d\n", return_value, response);
    printf("returned w %d h %d npix %d\n", width, height, numPixels);

    if (return_value != 0) return return_value;

    // Check buffer size
    if (numPixels > frame_size)
    {
        printf("Error: Frame size is larger than the provided buffer size.\n");
        return -1;
    }

    // Copy frame data
    memcpy(current_frame, pixels, numPixels);

    // Print center frame sample
    unsigned int i, j, ind, start;

    start = (height / 2) * width + width / 2;
    for (i = 0; i < size_frame; i++)
    {
        for (j = 0; j < size_frame; j++)
        {
            ind = i * width + j + start;
            printf(" %02x", current_frame[ind]);
        }
        printf("\n");
    }

    // Resume camera operations
    return_value = pixy_command("run", END_OUT_ARGS, &response, END_IN_ARGS);
    printf("START returned %d response %d\n", return_value, response);
    return numPixels;
}

