// Splits a string into tokens based on delimiters
void optimized_split(vector<string>& tokens, const string& str, const string& delimiters = " ")
{
    tokens.clear();
    size_t start, end = 0;
    while ((start = str.find_first_not_of(delimiters, end)) != string::npos)
    {
        end = str.find(delimiters, start);
        tokens.emplace_back(str.substr(start, end - start));
        // Skip over consecutive delimiters
        while (end != string::npos && delimiters.find(str[end]) != string::npos)
        {
            ++end;
        }
    }
}

int main()
{
    string input_line;
    vector<string> spline;
    long count = 0;
    auto start = high_resolution_clock::now();

    // Disable synchronization with C standard I/O to speed up I/O operations
    cin.sync_with_stdio(false);

    while (getline(cin, input_line))
    {
        optimized_split(spline, input_line);
        count++;
    }

    auto stop = high_resolution_clock::now();
    auto duration = duration_cast<seconds>(stop - start);
    cerr << "C++   : Saw " << count << " lines in " << duration.count() << " seconds.";
    if (duration.count() > 0)
    {
        long lps = count / duration.count();
        cerr << "  Crunch speed: " << lps << endl;
    }
    else
    {
        cerr << endl;
    }
    return 0;

}

