#include <thrust/device_vector.h>
#include <thrust/scan.h>

// Kernel to perform bottom-up scan
__global__ void bottom_up_scan_kernel(int* node_values, int* child_indices, int num_nodes)
{
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    if (idx < num_nodes)
    {
        int node_value = node_values[idx];
        int num_children = child_indices[idx * 2];
        int* children = &child_indices[idx * 2 + 1];
        int sum = 0;
        for (int i = 0; i < num_children; ++i)
        {
            sum += node_values[children[i]];
        }
        node_values[idx] = node_value + sum;
    }
}

// Host function to orchestrate the bottom-up scan
void bottom_up_scan(int* node_values, int* child_indices, int num_nodes)
{
    thrust::device_vector<int> d_node_values(node_values, node_values + num_nodes);
    thrust::device_vector<int> d_child_indices(child_indices, child_indices + num_nodes * 2);

    int num_blocks = (num_nodes + 255) / 256;
    bottom_up_scan_kernel<<<num_blocks, 256>>>(
        thrust::raw_pointer_cast(d_node_values.data()),
        thrust::raw_pointer_cast(d_child_indices.data()),
        num_nodes
    );

    thrust::inclusive_scan(d_node_values.begin(), d_node_values.end(), d_node_values.begin());

    thrust::copy(d_node_values.begin(), d_node_values.end(), node_values);
}

