// Subclass procedure to handle custom tooltip logic
LRESULT CALLBACK SubclassProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam, UINT_PTR uIdSubclass, DWORD_PTR dwRefData)
{
    static HWND hTooltip = nullptr;

    switch (uMsg)
    {
        case WM_MOUSEMOVE:
        case WM_NCMOUSEMOVE:
        {
            // Create tooltip on first mouse movement
            if (!hTooltip)
            {
                hTooltip = CreateWindowEx(0, TOOLTIPS_CLASS, NULL, WS_POPUP | TTS_ALWAYSTIP,
                                          CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT,
                                          hwnd, NULL, GetModuleHandle(NULL), NULL);
                if (hTooltip)
                {
                    TOOLINFO ti = {0};
                    ti.cbSize = sizeof(ti);
                    ti.uFlags = TTF_IDISHWND | TTF_SUBCLASS;
                    ti.uId = (UINT_PTR)hwnd;
                    ti.hwnd = hwnd;
                    ti.lpszText = L"Your custom tooltip text";
                    SendMessage(hTooltip, TTM_ADDTOOL, 0, (LPARAM)&ti);
                }
            }
            break;
        }
        case WM_DESTROY:
            if (hTooltip)
            {
                DestroyWindow(hTooltip);
                hTooltip = nullptr;
            }
            break;
    }

    // Call the original window procedure
    return DefSubclassProc(hwnd, uMsg, wParam, lParam);
}

// Helper function to apply subclassing to a target window
void SubclassTargetWindow(HWND hwnd)
{
    SetWindowSubclass(hwnd, SubclassProc, 0, 0);
