using namespace rapidjson;

using ComponentLoaderFunction = std::function<void(EntityId, const Value&)>;

// Map to store component loader functions
static std::unordered_map<std::string, ComponentLoaderFunction> componentLoaders;

// Loads a scene from a JSON file
void LoadScene(const std::string& filePath)
{
    FILE* fp = std::fopen(filePath.c_str(), "r");
    if (!fp)
    {
        std::cerr << "Error opening scene file: " << filePath << std::endl;
        return;
    }

    char readBuffer[65536];
    FileReadStream inputStream(fp, readBuffer, sizeof(readBuffer));

    Document document;
    document.ParseStream<0, UTF8<>, FileReadStream>(inputStream);
    std::fclose(fp);

    if (document.HasParseError())
    {
        std::cerr << "Error parsing JSON from scene file: " << filePath << std::endl;
        return;
    }

    // Process entities if present in the JSON
    if (document.HasMember("entities") && document["entities"].IsArray())
    {
        const Value& entities = document["entities"];

        for (SizeType i = 0; i < entities.Size(); i++)
        {
            const Value& entityData = entities[i];

            EntityId entityId = ECS::CreateEntity();

            // Load each registered component for this entity
            for (const auto& component : componentLoaders)
            {
                const char* componentName = component.first.c_str();

                if (entityData.HasMember(componentName))
                {
                    component.second(entityId, entityData[componentName]);
                }
            }
        }
    }
}

