#define ERROR_OPEN_FILE       10
#define ERROR_MEMORY          11
#define ERROR_SIZE            12
#define ERROR_INTERNET_OPEN   13
#define ERROR_INTERNET_CONN   14
#define ERROR_INTERNET_REQ    15
#define ERROR_INTERNET_SEND   16

using namespace std;

int main()
{
    // Local variables
    static char *filename   = "test.txt";   //Filename to be loaded
    static char *filepath   = "C:\\wamp\\www\\post\\test.txt";   //Filename to be loaded
    static char *type       = "text/plain";
    static char boundary[]  = "--BOUNDARY---";            //Header boundary
    static char nameForm[]  = "file";     //Input form name
    static char iaddr[]     = "localhost";        //IP address
    static char url[]       = "/post/upload.php";         //URL

    char hdrs[1024] = {'\0'};                  //Headers
    char * buffer;                   //Buffer containing file + headers
    char * content;                  //Buffer containing file
    FILE * pFile;                    //File pointer
    long lSize;                      //File size
    size_t result;                   

    // Open file
    pFile = fopen(filepath, "rb");
    if (pFile == NULL) 
    {
        printf("ERROR_OPEN_FILE\n");
        return ERROR_OPEN_FILE;
    }
    printf("OPEN_FILE\n");

    // obtain file size:
    fseek(pFile, 0, SEEK_END);
    lSize = ftell(pFile);
    rewind(pFile);

    // allocate memory to contain the whole file:
    content = (char*) malloc(sizeof(char) * (lSize + 1));
    if (content == NULL) 
    {
        printf("ERROR_MEMORY\n");
        fclose(pFile);
        return ERROR_MEMORY;
    }
    printf("MEMORY_ALLOCATED\t \"%ld\" \n", lSize);

    // copy the file into the buffer:
    result = fread(content, 1, lSize, pFile);
    if (result != lSize) 
    {
        printf("ERROR_SIZE\n");
        free(content);
        fclose(pFile);
        return ERROR_SIZE;
    }
    printf("SIZE_OK\n");

    content[lSize] = '\0';

    // terminate
    fclose(pFile);
    printf("FILE_CLOSE\n");

    // allocate memory to contain the whole file + HEADER
    buffer = (char*) malloc(sizeof(char) * (lSize + 2048));
    if (buffer == NULL) 
    {
        printf("ERROR_MEMORY\n");
        free(content);
        return ERROR_MEMORY;
    }

    // print header
    sprintf(hdrs, "Content-Type: multipart/form-data; boundary=%s\r\n", boundary);
    sprintf(buffer, "%s--%s\r\nContent-Disposition: form-data; name=\"%s\"; filename=\"%s\"\r\n", boundary, nameForm, filename);
    sprintf(buffer, "%sContent-Type: %s\r\n", buffer, type);
    sprintf(buffer, "%s\r\n%s\r\n", buffer, content);
    sprintf(buffer, "%s--%s--\r\n", buffer, boundary);

    // Calculate content length
    int contentLength = strlen(buffer);

    // Open internet connection
    HINTERNET hSession = InternetOpen("WINDOWS", INTERNET_OPEN_TYPE_PRECONFIG, NULL, NULL, 0);
    if (hSession == NULL) 
    {
        printf("ERROR_INTERNET_OPEN\n");
        free(content);
        free(buffer);
        return ERROR_INTERNET_OPEN;
    }
    printf("INTERNET_OPENED\n");

    HINTERNET hConnect = InternetConnect(hSession, iaddr, INTERNET_DEFAULT_HTTP_PORT, NULL, NULL, INTERNET_SERVICE_HTTP, 0, 1);
    if (hConnect == NULL) 
    {
        printf("ERROR_INTERNET_CONN\n");
        InternetCloseHandle(hSession);
        free(content);
        free(buffer);
        return ERROR_INTERNET_CONN;
    }
    printf("INTERNET_CONNECTED\n");

    HINTERNET hRequest = HttpOpenRequest(hConnect, "POST", url, NULL, NULL, NULL, INTERNET_FLAG_RELOAD, 1);
    if (hRequest == NULL) 
    {
        printf("ERROR_INTERNET_REQ\n");
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        free(content);
        free(buffer);
        return ERROR_INTERNET_REQ;
    }
    printf("INTERNET_REQ_OPEN\n");

    // Add Content-Length to headers
    char contentLengthHeader[128];
    sprintf(contentLengthHeader, "Content-Length: %d\r\n", contentLength);
    strcat(hdrs, contentLengthHeader);

    BOOL sent = HttpSendRequest(hRequest, hdrs, strlen(hdrs), buffer, contentLength);
    if (!sent) 
    {
        printf("ERROR_INTERNET_SEND\n");
        InternetCloseHandle(hRequest);
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        free(content);
        free(buffer);
        return ERROR_INTERNET_SEND;
    }
    printf("INTERNET_SEND_OK\n");

    InternetCloseHandle(hRequest);
    InternetCloseHandle(hConnect);
    InternetCloseHandle(hSession);

    free(content);
    free(buffer);

    getchar();
    return 0;

}

