namespace foo {
    // Class definition for Foo
    class Foo {
    public:
        void foo() { /* ... */ }
    };
}

// Registration function for pybind11
void regclass_foo_Foo(py::module m)
{
    // Create the class binding
    py::class_<foo::Foo, std::shared_ptr<foo::Foo>> foo(m, "Foo");

    // Bind the member function
    foo.def("foo", &foo::Foo::foo);

    // Static method to create from capsule
    foo.def_static("from_capsule", [](py::object capsule) {
        auto* capsule_ptr = capsule.ptr();
        auto* foo_ptr = reinterpret_cast<std::shared_ptr<foo::Foo>*>(PyCapsule_GetPointer(capsule_ptr, "foo_in_capsule"));
        return *foo_ptr;
    });

    // Static method to convert to capsule
    foo.def_static("to_capsule", [](std::shared_ptr<foo::Foo>& foo_from_python) {
        auto pybind_capsule = py::capsule(new std::shared_ptr<foo::Foo>(foo_from_python), "foo_in_capsule", [](void* ptr) {
            delete reinterpret_cast<std::shared_ptr<foo::Foo>*>(ptr);
        });
        return pybind_capsule;
    });
}

#include <iostream>
#include <string>
#include <vector>
#include <cctype>

enum class TokenType {
    IF,
    ELSE,
    FUNCTION,
    IDENTIFIER,
    NUMBER,
    STRING,
    OPERATOR,
    EOF_TOKEN
};

struct Token {
    TokenType type;
    std::string value;
};

class Lexer {
public:
    Lexer(const std::string& input) : input(input), pos(0) {}

    Token nextToken() {
        skipWhitespace();
        if (pos >= input.size()) {
            return {TokenType::EOF_TOKEN, ""};
        }

        char current = input[pos];
        if (isalpha(current)) {
            return identifierToken();
        } else if (isdigit(current)) {
            return numberToken();
        } else if (current == '"') {
            return stringToken();
        } else {
            return operatorToken();
        }
    }

private:
    std::string input;
    size_t pos;

    void skipWhitespace() {
        while (pos < input.size() && isspace(input[pos])) {
            pos++;
        }
    }

    Token identifierToken() {
        size_t start = pos;
        while (pos < input.size() && isalnum(input[pos])) {
            pos++;
        }
        std::string value = input.substr(start, pos - start);
        if (value == "if") {
            return {TokenType::IF, value};
        } else if (value == "else") {
            return {TokenType::ELSE, value};
        } else if (value == "function") {
            return {TokenType::FUNCTION, value};
        } else {
            return {TokenType::IDENTIFIER, value};
        }
    }

    Token numberToken() {
        size_t start = pos;
        while (pos < input.size() && isdigit(input[pos])) {
            pos++;
        }
        return {TokenType::NUMBER, input.substr(start, pos - start)};
    }

    Token stringToken() {
        pos++; // Skip the opening quote
        size_t start = pos;
        while (pos < input.size() && input[pos] != '"') {
            pos++;
        }
        std::string value = input.substr(start, pos - start);
        pos++; // Skip the closing quote
        return {TokenType::STRING, value};
    }

    Token operatorToken() {
        std::string value(1, input[pos++]);
        return {TokenType::OPERATOR, value};
    }
};

