// Function to reorder bytes in odd-even pattern
uint8x16_t oddeven(uint8x16_t a)
{
    // Extract the lower 8 bytes of a
    auto l = vget_low_u8(a);

    // Extract the higher 8 bytes of a
    auto h = vget_high_u8(a);

    // Unzip the lower and higher 8 bytes
    auto lh = vuzp_u8(l, h);

    // Combine the results
    return vcombine_u8(lh.val[0], lh.val[1]);
}

