// Template class for a simple array
template<typename T, int MAXSIZE>
class Array {
private:
    T data[MAXSIZE];
    int size = 0;

public:
    // Initialize the array
    void init()
    {
        size = 0;
    }

    // Insert an element at the end
    bool insert(const T& x)
    {
        if(size >= MAXSIZE)
        {
            return false;
        }
        data[size++] = x;
        return true;
    }

    // Read element at given index
    bool read(int index, T& x) const
    {
        if(index < 0 || index >= size)
        {
            return false;
        }
        x = data[index];
        return true;
    }

    // Print all elements
    void print() const
    {
        for(int i = 0; i < size; i++)
        {
            cout << data[i] << " ";
        }
        cout << endl;
    }

    // Sort the array
    void sort()
    {
        std::sort(data, data + size);
    }
};

