// Counts unique elements in the array
int count_unique(int array[], int n) 
{
    std::unordered_set<int> seen;
    int count = 0;

    for(int i=0;i<n;i++)
    {
        // Check if element is not already seen
        if(seen.find(array[i]) == seen.end())
        {
            seen.insert(array[i]);
            count++;
        }
    }

    return count;
}

