// Computes the arithmetic mean of a vector of integers
double mean(const std::vector<int>& data)
{
    if (data.empty()) return 0.0;
    double sum = 0.0;
    for(int x : data)
    {
        sum += x;
    }
    return sum / data.size();
}

// Computes the population variance of a vector of integers
double variance(const std::vector<int>& data)
{
    if (data.empty()) return 0.0;
    double mean_value = mean(data);
    double sum = 0.0;
    for(int x : data)
    {
        sum += (x - mean_value) * (x - mean_value);
    }
    return sum / data.size();
}

// Computes the standard deviation as the square root of variance
double standard_deviation(const std::vector<int>& data)
{
    return std::sqrt(variance(data));
}

// Computes the p-th quantile (0 <= p <= 1) of the data
double quantile(const std::vector<int>& data, double p)
{
    if (data.empty()) return 0.0;
    std::vector<int> sorted_data = data;
    std::sort(sorted_data.begin(), sorted_data.end());
    int n = sorted_data.size();
    int index = (int)std::round((n - 1) * p);
    return sorted_data[index];
}

// Computes the interquartile range (Q3 - Q1)
double iqr(const std::vector<int>& data)
{
    if (data.empty()) return 0.0;
    double q1 = quantile(data, 0.25);
    double q3 = quantile(data, 0.75);
    return q3 - q1;
}

int main()
{
    std::vector<int> data = {1, 3, 5, 7, 9, 11, 13};

    try
    {
        if (data.empty())
        {
            throw std::invalid_argument("Array is empty");
        }

        double sd = standard_deviation(data);
        double iqr_value = iqr(data);

        // Output statistical measures
        std::cout << "Standard Deviation: " << sd << std::endl;
        std::cout << "Interquartile Range: " << iqr_value << std::endl;
    }
    catch(const std::exception& e)
    {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;

}

