using namespace std;

// Node class for doubly linked list
class Node {
public:
    int data;
    Node *next;
    Node *prev;

    Node(int data) : data(data), next(NULL), prev(NULL) {}
};

// DoublyLinkedList class with hash map support
class DoublyLinkedList {
    Node *front;
    Node *rear;
    unordered_map<int, Node*> node_map;

public:
    DoublyLinkedList() : front(NULL), rear(NULL) {}

    // Insert a new node at the end
    void insert(int data) {
        Node* node = new Node(data);

        if(rear != NULL) {
            rear->next = node;
            node->prev = rear;
        } else {
            front = node;
        }

        rear = node;

        // Store the node address in the hash map
        node_map[data] = node;
    }

    // Search for a value in the list
    bool search(int data) {
        return node_map.find(data) != node_map.end();
    }

    // Remove a node by value
    void remove(int data) {
        if (node_map.find(data) == node_map.end()) {
            return;
        }

        Node* node = node_map[data];
        if (node->prev) {
            node->prev->next = node->next;
        } else {
            front = node->next;
        }

        if (node->next) {
            node->next->prev = node->prev;
        } else {
            rear = node->prev;
        }

        delete node;
        node_map.erase(data);
    }
};

int main()
{
    DoublyLinkedList dll;
    dll.insert(10);
    dll.insert(20);
    dll.insert(30);

    if(dll.search(20))
        cout << "20 Found\n";
    else
        cout << "20 Not found\n";

    if(dll.search(40))
        cout << "40 Found\n";
    else
        cout << "40 Not found\n";

    dll.remove(20);

    if(dll.search(20))
        cout << "20 Found\n";
    else
        cout << "20 Not found\n";

    return 0;
}

#include <cub/cub.cuh>

// Kernel to compute per-segment prefix sums using CUB
template <typename T>
__global__ void multiPrefixSumKernel(T *input, T *output, int numSegments, int segmentSize)
{
    // Shared memory for CUB block scan operations
    __shared__ T temp_storage[1024];

    int segmentId = blockIdx.x;
    int threadId = threadIdx.x;

    // Pointers to the current segment's data
    T *segmentInput = input + segmentId * segmentSize;
    T *segmentOutput = output + segmentId * segmentSize;

    // Perform inclusive prefix sum within each block/segment
    cub::BlockScan<T, 256> blockScan(temp_storage);
    T threadData = (threadId < segmentSize) ? segmentInput[threadId] : 0;
    T prefixSum;
    blockScan.InclusiveSum(threadData, prefixSum);

    // Store result if within bounds
    if(threadId < segmentSize)
    {
        segmentOutput[threadId] = prefixSum;
    }
}

int main()
{
    // Initialize your data
    int numSegments = 100;
    int segmentSize = 1024;
    int totalSize = numSegments * segmentSize;

    // Allocate and initialize input and output arrays
    float *d_input, *d_output;  // Assuming T=float for demonstration
    cudaMalloc(&d_input, totalSize * sizeof(float));
    cudaMalloc(&d_output, totalSize * sizeof(float));
    // Initialize d_input with your data

    // Configure and launch kernel
    dim3 blockSize(256);
    dim3 gridSize(numSegments);
    multiPrefixSumKernel<<<gridSize, blockSize>>>(d_input, d_output, numSegments, segmentSize);

    // Copy results back and free memory
    float *h_output = new float[totalSize];
    cudaMemcpy(h_output, d_output, totalSize * sizeof(float), cudaMemcpyDeviceToHost);

    cudaFree(d_input);
    cudaFree(d_output);
    delete[] h_output;

    return 0;
}

