// Database task class for concurrent execution
class DatabaseTask : public QRunnable {
public:
    // Constructor initializes query and parameters
    DatabaseTask(const QString &query, const QVariantList &params)
        : m_query(query), m_params(params) {}

    // Execute the database operation
    void run() override {
        // Thread-safe access to database operations
        QMutexLocker locker(&m_mutex);

        QSqlDatabase db = QSqlDatabase::database("thread_pool_connection");

        if (!db.isOpen()) {
            db = QSqlDatabase::addDatabase("QSQLITE", "thread_pool_connection");
            db.setDatabaseName("path/to/your/database.db");

            if (!db.open()) {
                qDebug() << "Database error:" << db.lastError().text();
                return;
            }
        }

        QSqlQuery q(db);
        q.prepare(m_query);

        // Bind all parameters
        for (const QVariant &param : m_params) {
            q.addBindValue(param);
        }

        // Execute query and handle errors
        if (!q.exec()) {
            qDebug() << "Query error:" << q.lastError().text();
        }
    }

private:
    QString m_query;
    QVariantList m_params;
    static QMutex m_mutex;
};

// Initialize static mutex member
QMutex DatabaseTask::m_mutex;

int main(int argc, char *argv[]) {
    QCoreApplication a(argc, argv);

    QThreadPool pool;
    pool.setMaxThreadCount(4); // Adjust thread count as needed

    // Create tasks with sample data
    DatabaseTask *task1 = new DatabaseTask(
        "INSERT INTO table_name (column1, column2) VALUES (?, ?)", 
        { "value1", "value2" }
    );

    DatabaseTask *task2 = new DatabaseTask(
        "INSERT INTO table_name (column1, column2) VALUES (?, ?)", 
        { "value3", "value4" }
    );

    // Submit tasks to thread pool
    pool.start(task1);
    pool.start(task2);

    // Wait for all tasks to complete before exiting
    pool.waitForDone();

    return a.exec();
}

// Computes the greatest common divisor
int gcd(int a, int b)
{
    while(b != 0)
    {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Checks if two numbers are coprime
bool areCoprime(int a, int b)
{
    return gcd(a, b) == 1;
}

#include <windows.h>

// Function to calculate call stack size
int CallStackSize(DWORD64 frameRBP = 0)
{
    DWORD64 pc;
    int tmpint = 0;
    DWORD64 Frame;
    PDWORD64 pFrame, pPrevFrame;

    // If no frame is provided, use current stack frame
    if (!frameRBP)
    {
        // Use RBP register to get current stack frame pointer
        __asm
        {
            mov rax, rbp
            mov Frame, rax
        }
    }
    else
    {
        Frame = frameRBP;
    }

    pFrame = (PDWORD64)Frame;

    do
    {
        pc = pFrame[1];
        pPrevFrame = pFrame;
        pFrame = (PDWORD64)pFrame[0]; // Move to next higher frame on the stack

        // Check alignment: frame pointer must be 8-byte aligned
        if ((DWORD64)pFrame & 7)
            break;

        // Ensure frame pointer moves upward in memory
        if (pFrame <= pPrevFrame)
            break;

        // Verify we can safely read from the frame address
        if (IsBadWritePtr(pFrame, sizeof(QWORD) * 2))
            break;

        tmpint++;
    } while (true);

    return tmpint;
}

