// Function to find the median of three numbers
int findMedian(int a, int b, int c)
{
    // First, check if a is the median
    if((a - b) * (c - a) >= 0)
    {
        return a;
    }
    // Then, check if b is the median
    else if((b - a) * (c - b) >= 0)
    {
        return b;
    }
    // If neither a nor b is the median, then c must be the median
    else
    {
        return c;
    }
}

int main()
{
    int num1, num2, num3;

    std::cout << "Enter three numbers: ";
    std::cin >> num1 >> num2 >> num3;

    int median = findMedian(num1, num2, num3);

    // Output the result
    std::cout << "The median is: " << median << std::endl;

    return 0;

}

