#include <iostream>
#include <string>
#include <unordered_map>
#include <variant>
#include <optional>

enum class TokenType {
    NUMBER,
    VARIABLE,
    OPERATOR,
    PARENTHESIS,
};

struct Token {
    TokenType type;
    std::variant<int, std::string> value;
};

class ExpressionEvaluator {
public:
    ExpressionEvaluator(const std::string& expr, const std::unordered_map<std::string, int>& known_values)
        : expr_(expr), known_values_(known_values) {}

    std::optional<bool> evaluate() {
        std::vector<Token> tokens = tokenize(expr_);
        return evaluate_expression(tokens);
    }

private:
    // Tokenizes the input expression
    std::vector<Token> tokenize(const std::string& expr) {
        std::vector<Token> tokens;
        std::string current_token;
        for (char ch : expr) {
            if (std::isspace(ch)) {
                continue;
            }
            if (ch == '(' || ch == ')' || ch == '&' || ch == '|' || ch == '>') {
                if (!current_token.empty()) {
                    tokens.push_back({current_token[0] == '(' || current_token[0] == ')' ? TokenType::PARENTHESIS : TokenType::VARIABLE, current_token});
                    current_token.clear();
                }
                tokens.push_back({TokenType::OPERATOR, std::string(1, ch)});
            } else {
                current_token += ch;
            }
        }
        if (!current_token.empty()) {
            tokens.push_back({current_token[0] == '(' || current_token[0] == ')' ? TokenType::PARENTHESIS : TokenType::VARIABLE, current_token});
        }
        return tokens;
    }

    // Evaluates the expression after tokenization and variable substitution
    std::optional<bool> evaluate_expression(const std::vector<Token>& tokens) {
        for (size_t i = 0; i < tokens.size(); ++i) {
            const auto& token = tokens[i];
            if (std::holds_alternative<std::string>(token.value)) {
                const std::string& value = std::get<std::string>(token.value);
                if (known_values_.find(value) != known_values_.end()) {
                    tokens[i] = {TokenType::NUMBER, known_values_[value]};
                } else if (value == "true") {
                    tokens[i] = {TokenType::NUMBER, 1};
                } else if (value == "false") {
                    tokens[i] = {TokenType::NUMBER, 0};
                }
            }
        }

        for (size_t i = 0; i < tokens.size(); ++i) {
            if (std::get_if<std::string>(&tokens[i].value)) {
                return std::nullopt; // Still has unknown variables
            }
        }

        return evaluate_tokens(tokens);
    }

    // Evaluates tokens using a stack-based approach
    std::optional<bool> evaluate_tokens(const std::vector<Token>& tokens) {
        std::vector<std::optional<bool>> stack;
        for (const auto& token : tokens) {
            if (token.type == TokenType::NUMBER) {
                stack.push_back(std::get<int>(token.value) > 0);
            } else if (token.type == TokenType::OPERATOR) {
                char op = std::get<std::string>(token.value)[0];
                if (op == '>') {
                    if (stack.size() < 2) return std::nullopt; // Not enough values for comparison
                    auto right = stack.back(); stack.pop_back();
                    auto left = stack.back(); stack.pop_back();
                    stack.push_back(left && right);
                } else if (op == '&') {
                    if (stack.size() < 2) return std::nullopt; // Not enough values for AND
                    auto right = stack.back(); stack.pop_back();
                    auto left = stack.back(); stack.pop_back();
                    stack.push_back(left && right);
                } else if (op == '|') {
                    if (stack.size() < 2) return std::nullopt; // Not enough values for OR
                    auto right = stack.back(); stack.pop_back();
                    auto left = stack.back(); stack.pop_back();
                    stack.push_back(left || right);
                }
            }
        }
        if (stack.size() != 1) return std::nullopt; // Invalid expression
        return stack.front();
    }

private:
    std::string expr_;
    std::unordered_map<std::string, int> known_values_;
};

// Main function to test the evaluator
int main()
{
    std::string expr = "((A>0) && (B>5 || C > 10))";
    std::unordered_map<std::string, int> known_values = {{"A", -1}};

    ExpressionEvaluator evaluator(expr, known_values);
    auto result = evaluator.evaluate();

    if (result) {
        std::cout << "Expression evaluates to: " << std::boolalpha << *result << std::endl;
    } else {
        std::cout << "Expression cannot be fully evaluated with the given values." << std::endl;
    }

    return 0;

}

#include <boost/python.hpp>
