// Convert cv::Mat to numpy array
boost::python::object mat_to_numpy(const cv::Mat& mat)
{
    npy_intp dims[2] = {mat.rows, mat.cols};
    PyObject* py_array = PyArray_SimpleNew(2, dims, NPY_FLOAT64);
    std::memcpy(PyArray_DATA(py_array), mat.ptr<double>(), mat.total() * mat.elemSize());
    return boost::python::object(boost::python::handle<>(boost::python::borrowed(py_array)));
}

// Convert numpy array to cv::Mat
cv::Mat numpy_to_mat(boost::python::object& py_array)
{
    PyArrayObject* array = reinterpret_cast<PyArrayObject*>(py_array.ptr());
    npy_intp* dims = PyArray_DIMS(array);
    cv::Mat mat(dims[0], dims[1], CV_64F, PyArray_DATA(array));
    return mat;
}

// Example function to call scikit-learn
void call_sklearn_classifier()
{
    boost::python::object main_module = boost::python::import("__main__");
    boost::python::object main_namespace = main_module.attr("__dict__");

    // Import scikit-learn
    boost::python::object sklearn = boost::python::import("sklearn");
    boost::python::object datasets = sklearn.attr("datasets");
    boost::python::object linear_model = sklearn.attr("linear_model");

    // Load a dataset
    boost::python::object data = datasets.attr("load_iris")();
    boost::python::object X = data.attr("data");
    boost::python::object y = data.attr("target");

    // Create a classifier
    boost::python::object clf = linear_model.attr("LogisticRegression")();
    clf.attr("fit")(X, y);

    // Predict
    boost::python::object prediction = clf.attr("predict")(X);
    boost::python::list predictions = boost::python::extract<boost::python::list>(prediction);

    // Convert predictions to C++ vector
    std::vector<int> cpp_predictions;
    for(int i=0; i<boost::python::len(predictions); ++i)
    {
        cpp_predictions.push_back(boost::python::extract<int>(predictions[i]));
    }

    // Print predictions
    for(int pred : cpp_predictions)
    {
        std::cout<<pred<<" ";
    }
    std::cout<<std::endl;
}

