// Kernel function declaration (assumed to be defined elsewhere)
__global__ void kernel_increment(float* dPtr1, float* dPtr2, int n);

int main()
{
    // Declare host and device pointers
    float *hPtr1, *hPtr2, *dPtr1, *dPtr2;

    const int n = 1000;

    size_t bytes = n * sizeof(float);

    cudaStream_t str1, str2;

    // Allocate pinned host memory
    cudaMallocHost((void**)&hPtr1, bytes);
    cudaMallocHost((void**)&hPtr2, bytes);

    // Initialize host data
    for(int i = 0; i < n; i++)
        hPtr1[i] = static_cast<float>(i);

    // Allocate device memory
    cudaMalloc<float>(&dPtr1, bytes);
    cudaMalloc<float>(&dPtr2, bytes);

    // Define kernel launch configuration
    dim3 block(16);
    dim3 grid((n + block.x - 1) / block.x);

    // Create CUDA streams
    cudaStreamCreate(&str1);
    cudaStreamCreate(&str2);

    // Perform asynchronous memory copies and kernel execution
    cudaMemcpyAsync(dPtr1, hPtr1, bytes, cudaMemcpyHostToDevice, str1);
    kernel_increment<<<grid, block, 0, str2>>>(dPtr1, dPtr2, n);
    cudaMemcpyAsync(hPtr2, dPtr2, bytes, cudaMemcpyDeviceToHost, str1);

    // Check for errors after operations
    printf("Status: %s\n", cudaGetErrorString(cudaGetLastError()));

    cudaDeviceSynchronize();

    printf("Status: %s\n", cudaGetErrorString(cudaGetLastError()));

    // Clean up streams
    cudaStreamDestroy(str1);
    cudaStreamDestroy(str2);

    // Free device memory
    cudaFree(dPtr1);
    cudaFree(dPtr2);

    // Free pinned host memory
    cudaFreeHost(hPtr1);
    cudaFreeHost(hPtr2);

    return 0;
}

