enum class TokenType {
    NUMBER,
    OPERATOR,
    FUNCTION,
    LEFT_PAREN,
    RIGHT_PAREN,
    END
};

struct Token {
    TokenType type;
    std::string value;
};

// Tokenizes the input expression into a vector of tokens
std::vector<Token> tokenize(const std::string& expression)
{
    std::vector<Token> tokens;
    std::string number;

    for(size_t i = 0; i < expression.length(); ++i)
    {
        char c = expression[i];

        // Handle numbers (including decimals)
        if(std::isdigit(c) || c == '.')
        {
            number += c;
        }
        else
        {
            // Push accumulated number if any
            if(!number.empty())
            {
                tokens.push_back({TokenType::NUMBER, number});
                number.clear();
            }

            // Handle function names (alphabetic characters)
            if(std::isalpha(c))
            {
                std::string func;
                while(std::isalpha(c))
                {
                    func += c;
                    c = expression[++i];
                }
                tokens.push_back({TokenType::FUNCTION, func});
                --i; // Adjust for the extra increment in the loop
            }
            // Handle parentheses
            else if(c == '(')
            {
                tokens.push_back({TokenType::LEFT_PAREN, "("});
            }
            else if(c == ')')
            {
                tokens.push_back({TokenType::RIGHT_PAREN, ")"});
            }
            // Handle operators
            else if(c == '+' || c == '-' || c == '*' || c == '/' || c == '^')
            {
                tokens.push_back({TokenType::OPERATOR, std::string(1, c)});
            }
            // Handle invalid non-whitespace characters
            else if(!std::isspace(c))
            {
                throw std::runtime_error("Invalid character: " + std::string(1, c));
            }
        }
    }

    // Push remaining number if any
    if(!number.empty())
    {
        tokens.push_back({TokenType::NUMBER, number});
    }

    // Add end token
    tokens.push_back({TokenType::END, ""});
    return tokens;
}

