// Pre-load implementation
void HamScrollSpeedIndicator::PreLoad(BinStream &bs) {
    LOAD_REVS(bs);
    ASSERT_REVS(2, 0)
    RndDir::PreLoad(bs);
    bs.PushRev(packRevs(d.altRev, d.rev), this);
}

// Post-load implementation
void HamScrollSpeedIndicator::PostLoad(BinStream &bs) {
    BinStreamRev d(bs, bs.PopRev(this));
    RndDir::PostLoad(bs);
    if ((d.rev & 0xffff) >= 1) {
        bs >> mEnterAnim;
        bs >> mExitAnim;
        bs >> mIndicatorAnim;
    }
    if (2 <= (d.rev & 0xffff)) {
        bs >> mSlowScrollThresholdFrame;
        bs >> mFastScrollThresholdFrame;
    }
}

