#include <iostream>
#include <vector>
#include <string>

using namespace std;

// Helper function to find all paths
void helper(vector<vector<int>> &mat, int r, int c, string path, vector<string> &ans)
{
    // Check for out of bounds or blocked cells
    if(r < 0 || c < 0 || r >= mat.size() || c >= mat[0].size() || mat[r][c] == 0 || mat[r][c] == -1)
    {
        return;
    }

    // Reached destination
    if(r == mat.size() - 1 && c == mat[0].size() - 1)
    {
        ans.push_back(path);
        return;
    }

    // Mark current cell as visited
    mat[r][c] = -1;

    // Explore all four directions
    helper(mat, r+1, c, path+"D", ans); // down
    helper(mat, r-1, c, path+"U", ans); // up
    helper(mat, r, c-1, path+"L", ans); // left
    helper(mat, r, c+1, path+"R", ans); // right

    // Backtrack: unmark current cell
    mat[r][c] = 1;
}

// Function to find all paths from top left to bottom right of a matrix
vector<string> findPath(vector<vector<int>> &mat)
{
    vector<string> ans;
    string path = "";
    helper(mat, 0, 0, path, ans);
    return ans;
}

int main()
{
    vector<vector<int>> mat = {{1, 0, 0, 0}, {1, 1, 0, 1}, {1, 1, 0, 0}, {0, 1, 1, 1}};

    vector<string> ans = findPath(mat);
    for (const auto& str : ans)
    {
        cout << str << endl;
    }
    return 0;
}

