#include <fstream>
#include <iostream>
#include <omp.h>
#include <vector>

#include "bench_utils.h"
#include "superkmeans/common.h"
#include "superkmeans/hierarchical_superkmeans.h"
#include "superkmeans/superkmeans.h"

int main(int argc, char* argv[])
{
    std::string dataset = (argc > 1) ? std::string(argv[1]) : std::string("yahoo");

    auto it = bench_utils::DATASET_PARAMS.find(dataset);
    if (it == bench_utils::DATASET_PARAMS.end())
    {
        std::cerr << "Unknown dataset '" << dataset << "'\n";
        return 1;
    }

    const size_t n = it->second.first;
    const size_t d = it->second.second;
    const size_t n_clusters = 40000; // bench_utils::get_default_n_clusters(n);
    int n_iters = 5;
    float sampling_fraction = 1.0;

    std::string filename = bench_utils::get_data_path(dataset);
    const size_t THREADS = omp_get_max_threads();
    omp_set_num_threads(THREADS);

    std::cout << "=== Assign Benchmark ===" << std::endl;
    std::cout << "Dataset: " << dataset << " (n=" << n << ", d=" << d << ")\n";
    std::cout << "n_clusters=" << n_clusters << " n_iters=" << n_iters
              << " sampling_fraction=" << sampling_fraction << "\n";

    std::vector<float> data;
    try
    {
        data.reserve(n * d);
    }
    catch (const std::bad_alloc& e)
    {
        std::cerr << "Failed to allocate data vector for n*d = " << (n * d) << ": " << e.what()
                  << "\n";
        return 1;
    }

    std::ifstream file(filename, std::ios::binary);
    if (!file)
    {
        std::cerr << "Failed to open " << filename << std::endl;
        return 1;
    }

    file.read(reinterpret_cast<char*>(data.data()), n * d * sizeof(float));
    file.close();

    // --- Training ---
    skmeans::HierarchicalSuperKMeansConfig config;
    config.iters_mesoclustering = 3;
    config.iters_fineclustering = 5;
    config.iters_refinement = 0;
    config.verbose = false;
    config.n_threads = THREADS;
    config.unrotate_centroids = true;
    config.early_termination = false;
    config.sampling_fraction = sampling_fraction;
    config.use_blas_only = false;

    auto is_angular = std::find(
        bench_utils::ANGULAR_DATASETS.begin(), bench_utils::ANGULAR_DATASETS.end(), dataset
    );
    if (is_angular != bench_utils::ANGULAR_DATASETS.end())
    {
        std::cout << "Using spherical k-means" << std::endl;
        config.angular = true;
    }

    auto kmeans =
        skmeans::HierarchicalSuperKMeans<skmeans::Quantization::f32, skmeans::DistanceFunction::l2>(
            n_clusters, d, config
        );

    bench_utils::TicToc timer_train;
    timer_train.Tic();
    auto centroids = kmeans.Train(data.data(), n);
    timer_train.Toc();

    std::cout << "\nTraining completed in " << timer_train.GetMilliseconds() << " ms" << std::endl;

    // --- FastAssign (GEMM+PRUNING fast path) ---
    bench_utils::TicToc timer_fast;
    timer_fast.Tic();
    auto assignments_fast = kmeans.FastAssign(data.data(), centroids.data(), n, n_clusters);
    timer_fast.Toc();
    double fast_ms = timer_fast.GetMilliseconds();
    std::cout << "\nFastAssign: " << fast_ms << " ms" << std::endl;

    // --- Assign (brute force) ---
    bench_utils::TicToc timer_brute;
    timer_brute.Tic();
    auto assignments_brute = kmeans.Assign(data.data(), centroids.data(), n, n_clusters);
    timer_brute.Toc();
    double brute_ms = timer_brute.GetMilliseconds();
    std::cout << "Assign:     " << brute_ms << " ms" << std::endl;

    // --- Compare ---
    double speedup = brute_ms / fast_ms;
    size_t matches = 0;
    for (size_t i = 0; i < n; ++i)
    {
        if (assignments_fast[i] == assignments_brute[i])
        {
            ++matches;
        }
    }

    double match_pct = 100.0 * static_cast<double>(matches) / static_cast<double>(n);
    std::cout << "\nSpeedup: " << speedup << "x" << std::endl;
    std::cout << "Agreement: " << match_pct << "% (" << matches << "/" << n << ")" << std::endl;

    return 0;
}

#include "Enemy.h"

// XP reward constants for enemies
const int Enemy::XP_REWARD_NONE   = 0;
const int Enemy::XP_REWARD_SMALL  = 3;
const int Enemy::XP_REWARD_MEDIUM = 5;
const int Enemy::XP_REWARD_LARGE  = 10;
const int Enemy::XP_REWARD_HUGE   = 20;

#include <vector>

// Recursive function to count coin combinations
void changeCoin(std::vector<int>& coins, int index, int n, int sum, int target, int& count)
{
    // Base case: exact target sum reached
    if(sum == target)
    {
        count++;
        return;
    }
    // Base case: exceeded target or no more coins left
    if(sum > target || index == n)
    {
        return;
    }

    // Include current coin and stay at same index (can reuse)
    changeCoin(coins, index, n, sum + coins[index], target, count);

    // Exclude current coin and move to next index
    changeCoin(coins, index + 1, n, sum, target, count);
}

// Wrapper function to initialize and return count
int countCoinCombinations(std::vector<int>& coins, int target)
{
    int count = 0;
    changeCoin(coins, 0, coins.size(), 0, target, count);
    return count;
}

#include <thread>
#include <small_gicp/points/point_cloud.hpp>
#include <small_gicp/ann/kdtree.hpp>
#include <small_gicp/ann/kdtree_omp.hpp>
#include <small_gicp/util/downsampling.hpp>
#include <small_gicp/benchmark/benchmark.hpp>

#ifdef BUILD_WITH_TBB
#include <small_gicp/ann/kdtree_tbb.hpp>
#endif

// Main function for KD-tree benchmarking
int main(int argc, char** argv)
{
    using namespace small_gicp;

    // Check command-line arguments
    if (argc < 2)
    {
        std::cout << "USAGE: kdtree_benchmark <dataset_path>" << std::endl;
        std::cout << "OPTIONS:" << std::endl;
        std::cout << "  --num_threads <value> (default: 4)" << std::endl;
        std::cout << "  --num_trials <value>" << std::endl;
        std::cout << "  --method <str> (small|omp|tbb)" << std::endl;
        return 0;
    }

    const std::string dataset_path = argv[1];
    int num_threads = 4;
    int num_trials = 100;
    std::string method = "small";

    // Parse command-line options
    for (int i = 1; i < argc; i++)
    {
        const std::string arg = argv[i];
        if (arg == "--num_threads")
        {
            num_threads = std::stoi(argv[i + 1]);
        }
        else if (arg == "--num_trials")
        {
            num_trials = std::stoi(argv[i + 1]);
        }
        else if (arg == "--method")
        {
            method = argv[i + 1];
        }
        else if (arg.size() >= 2 && arg.substr(0, 2) == "--")
        {
            std::cerr << "unknown option: " << arg << std::endl;
            return 1;
        }
    }

    std::cout << "dataset_path=" << dataset_path << std::endl;
    std::cout << "num_threads=" << num_threads << std::endl;
    std::cout << "num_trials=" << num_trials << std::endl;
    std::cout << "method=" << method << std::endl;

#ifdef BUILD_WITH_TBB
    tbb::global_control tbb_control(tbb::global_control::max_allowed_parallelism, num_threads);
#endif

    // Load KITTI dataset
    KittiDataset kitti(dataset_path, 1);
    auto raw_points = std::make_shared<PointCloud>(kitti.points[0]);
    std::cout << "num_raw_points=" << raw_points->size() << std::endl;

    // Binary search to find voxel resolution for target point count
    const auto search_voxel_resolution = [&](size_t target_num_points)
    {
        std::pair<double, size_t> left = {0.1, voxelgrid_sampling(*raw_points, 0.1)->size()};
        std::pair<double, size_t> right = {1.0, voxelgrid_sampling(*raw_points, 1.0)->size()};

        for (int i = 0; i < 20; i++)
        {
            if (left.second < target_num_points)
            {
                left.first *= 0.1;
                left.second = voxelgrid_sampling(*raw_points, left.first)->size();
                continue;
            }
            if (right.second > target_num_points)
            {
                right.first *= 10.0;
                right.second = voxelgrid_sampling(*raw_points, right.first)->size();
                continue;
            }

            const double mid = (left.first + right.first) * 0.5;
            const size_t mid_num_points = voxelgrid_sampling(*raw_points, mid)->size();

            if (std::abs(1.0 - static_cast<double>(mid_num_points) / target_num_points) < 0.001)
            {
                return mid;
            }

            if (mid_num_points > target_num_points)
            {
                left = {mid, mid_num_points};
            }
            else
            {
                right = {mid, mid_num_points};
            }
        }
        return (left.first + right.first) * 0.5;
    };

    std::cout << "---" << std::endl;

    // Generate downsampled point clouds at various resolutions
    std::vector<double> downsampling_resolutions;
    std::vector<PointCloud::Ptr> downsampled;

    for (double target = 1.0; target > 0.05; target -= 0.1)
    {
        const double downsampling_resolution = search_voxel_resolution(raw_points->size() * target);
        downsampling_resolutions.emplace_back(downsampling_resolution);
        downsampled.emplace_back(voxelgrid_sampling(*raw_points, downsampling_resolution));

        std::cout << "downsampling_resolution=" << downsampling_resolution << std::endl;
        std::cout << "num_points=" << downsampled.back()->size() << std::endl;
    }

    std::cout << "---" << std::endl;

    // Warm-up phase
    auto t1 = std::chrono::high_resolution_clock::now();
    while (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::high_resolution_clock::now() - t1).count() < 1)
    {
        auto downsampled_temp = voxelgrid_sampling(*raw_points, 0.1);
        if (method == "small")
        {
            UnsafeKdTree<PointCloud> tree(*downsampled_temp);
        }
        else if (method == "omp")
        {
            UnsafeKdTree<PointCloud> tree(*downsampled_temp, KdTreeBuilderOMP(num_threads));
        }
#ifdef BUILD_WITH_TBB
        else if (method == "tbb")
        {
            UnsafeKdTree<PointCloud> tree(*downsampled_temp, KdTreeBuilderTBB());
        }
#endif
    }

    Stopwatch sw;

    // Benchmark KD-tree construction times
    if (method == "small")
    {
        for (size_t i = 0; i < downsampling_resolutions.size(); i++)
        {
            if (num_threads != 1)
            {
                break;
            }

            Summarizer kdtree_times(true);
            sw.start();
            for (size_t j = 0; j < num_trials; j++)
            {
                UnsafeKdTree<PointCloud> tree(*downsampled[i]);
                sw.lap();
                kdtree_times.push(sw.msec());
            }
            std::cout << "kdtree_times=" << kdtree_times.str() << " [msec]" << std::endl;
        }
    }
    else if (method == "omp")
    {
        for (size_t i = 0; i < downsampling_resolutions.size(); i++)
        {
            Summarizer kdtree_omp_times(true);
            sw.start();
            for (size_t j = 0; j < num_trials; j++)
            {
                UnsafeKdTree<PointCloud> tree(*downsampled[i], KdTreeBuilderOMP(num_threads));
                sw.lap();
                kdtree_omp_times.push(sw.msec());
            }
            std::cout << "kdtree_omp_times=" << kdtree_omp_times.str() << " [msec]" << std::endl;
        }
    }
#ifdef BUILD_WITH_TBB
    else if (method == "tbb")
    {
        for (size_t i = 0; i < downsampling_resolutions.size(); i++)
        {
            Summarizer kdtree_tbb_times(true);
            sw.start();
            for (size_t j = 0; j < num_trials; j++)
            {
                UnsafeKdTree<PointCloud> tree(*downsampled[i], KdTreeBuilderTBB());
                sw.lap();
                kdtree_tbb_times.push(sw.msec());
            }
            std::cout << "kdtree_tbb_times=" << kdtree_tbb_times.str() << " [msec]" << std::endl;
        }
    }
#endif

    return 0;
}

static void upb_FixLocale(char* p) {
  /* printf() is dependent on locales; sadly there is no easy and portable way
   * to avoid this. This little post-processing step will translate 1,2 -> 1.2
   * since JSON needs the latter. Arguably a hack, but it is simple and the
   * alternatives are far more complicated, platform-dependent, and/or larger
   * in code size. */
  for (; *p; p++) {
    if (*p == ',') *p = '.';
  }
}

void _upb_EncodeRoundTripDouble(double val, char* buf, size_t size)
{
    assert(size >= kUpb_RoundTripBufferSize);
    snprintf(buf, size, "%.*g", DBL_DIG, val);
    if (strtod(buf, NULL) != val) {
        snprintf(buf, size, "%.*g", DBL_DIG + 2, val);
        assert(strtod(buf, NULL) == val);
    }
    upb_FixLocale(buf);
}

void _upb_EncodeRoundTripFloat(float val, char* buf, size_t size)
{
    assert(size >= kUpb_RoundTripBufferSize);
    snprintf(buf, size, "%.*g", FLT_DIG, val);
    if (strtof(buf, NULL) != val) {
        snprintf(buf, size, "%.*g", FLT_DIG + 3, val);
        assert(strtof(buf, NULL) == val);
    }
    upb_FixLocale(buf);
}

