#include <bits/stdc++.h>
using namespace std;

struct Company {
    int x, y, r, idx;
};

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Company> comp(n);

    for (int i = 0; i < n; i++) {
        cin >> comp[i].x >> comp[i].y >> comp[i].r;
        comp[i].idx = i;
    }

    // Sort by y-coordinate
    sort(comp.begin(), comp.end(), [](const Company& a, const Company& b) {
        return a.y < b.y;
    });

    // Compute cumulative ideal positions
    vector<double> ideal(n + 1, 0.0);
    for (int i = 1; i <= n; i++) {
        ideal[i] = ideal[i - 1] + (double)comp[i - 1].r / 10000.0;
    }

    // Determine actual end positions
    vector<int> ends(n + 1);
    ends[0] = 0;

    for (int k = 1; k < n; k++) {
        int lower = comp[k - 1].y + 1;
        int upper = comp[k].y;
        double idl = ideal[k];
        double pos_d = round(idl);
        int pos = (int)pos_d;
        pos = max(lower, min(upper, pos));
        ends[k] = pos;
    }

    ends[n] = 10000;

    // Map back to original indices
    vector<int> aa(n), bb(n), cc(n), dd(n);
    for (int si = 0; si < n; si++) {
        int orig = comp[si].idx;
        int bbb = ends[si];
        int ddd = ends[si + 1];
        aa[orig] = 0;
        bb[orig] = bbb;
        cc[orig] = 10000;
        dd[orig] = ddd;
    }

    // Output results
    for (int i = 0; i < n; i++) {
        cout << aa[i] << " " << bb[i] << " " << cc[i] << " " << dd[i] << "\n";
    }

    return 0;
}

#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <ctime>
#include <iomanip>
#include "ROL.hpp"
#include "Teuchos_Comm.hpp"
#include "Teuchos_MpiComm.hpp"
#include "Tpetra_Core.hpp"

// Global MPI session and Kokkos initialization
ROL::GlobalMPISession mpiSession(&argc, &argv);
Kokkos::ScopeGuard kokkosScope(argc, argv);

// Communication setup
ROL::Ptr<const Teuchos::Comm<int>> dcomm, ocomm;
#ifdef HAVE_MPI
  OED_SplitComm<int,Teuchos::MpiComm<int>> splitcomm(1);
  dcomm = splitcomm.getDesignComm();
  ocomm = splitcomm.getSampleComm();
#else
  dcomm = ROL::makePtr<Teuchos::SerialComm<int>>();
  ocomm = Tpetra::getDefaultComm();
#endif

// Determine if current process should print output
const int drank = dcomm->getRank();
const int orank = ocomm->getRank();
bool iprint = (argc > 1) && (drank == 0) && (orank == 0);
iprint = ((argc > 2) ? true : iprint);
auto outStream = ROL::makeStreamPtr(std::cout, iprint);

int errorFlag = 0;

try {
    RealT tol(1e-8);

    // Read XML input parameters
    auto parlist = ROL::getParametersFromXmlFile("input.xml");

    int numSpeakers = 8;
    bool checkDeriv = parlist->sublist("Problem").get("Check Derivatives", false);
    int verbosity = parlist->sublist("General").get("Print Verbosity", 0);
    bool alPrint = parlist->sublist("Step").sublist("Augmented Lagrangian").get("Print Intermediate Optimization History", false);

    verbosity = (iprint ? verbosity : 0);
    alPrint = (iprint ? alPrint : false);
    parlist->sublist("General").set("Print Verbosity", verbosity);
    parlist->sublist("Step").sublist("Augmented Lagrangian").set("Print Intermediate Optimization History", alPrint);

    // Initialize PDE constraint
    auto meshMgr = ROL::makePtr<MeshReader<RealT, DeviceT>>(*parlist);
    auto pde = ROL::makePtr<PDE_Helmholtz_OCT<RealT, DeviceT>>(*parlist);
    auto con = ROL::makePtr<Linear_PDE_Constraint<RealT, DeviceT>>(pde, meshMgr, dcomm, *parlist, *outStream);
    auto assembler = con->getAssembler();
    con->printMeshData(*outStream);

    // Create state vectors
    auto u_ptr = assembler->createStateVector();
    auto r_ptr = assembler->createResidualVector();
    auto up = ROL::makePtr<PDE_PrimalSimVector<RealT, DeviceT>>(u_ptr, pde, assembler, *parlist);
    auto rp = ROL::makePtr<PDE_DualSimVector<RealT, DeviceT>>(r_ptr, pde, assembler, *parlist);
    auto zp = ROL::makePtr<ROL::StdVector<RealT>>(numSpeakers);

    // Create observation function
    auto qoi = ROL::makePtr<QoI_Helmholtz_Observation<RealT, DeviceT>>(pde->getFE(), *parlist);
    auto obs = ROL::makePtr<PDE_Objective<RealT, DeviceT>>(qoi, assembler);

    // Run derivative checks
    if (checkDeriv) {
        up->randomize();  zp->randomize();
        auto dup = up->clone(); dup->randomize();
        auto dzp = zp->clone(); dzp->randomize();
        ROL::Vector_SimOpt<RealT> uz(up, zp), duz(dup, dzp);
        std::vector<RealT> param(2, 0);
        obs->setParameter(param);

        *outStream << "\n\nCheck Jacobian_1 of PDE Constraint\n";
        con->checkApplyJacobian_1(*up, *zp, *dup, *rp, true, *outStream);
        *outStream << "\n\nCheck Jacobian_2 of PDE Constraint\n";
        con->checkApplyJacobian_2(*up, *zp, *dzp, *rp, true, *outStream);
        *outStream << "\n\nCheck Gradient of Full Objective Function\n";
        obs->checkGradient(uz, duz, true, *outStream);
        *outStream << "\n\nCheck Hessian of Full Objective Function\n";
        obs->checkHessVec(uz, duz, true, *outStream);
    }

    // Compute states for factor decomposition and build regression model
    *outStream << std::endl << "Begin: PDE Solves" << std::endl;
    std::vector<ROL::Ptr<ROL::Vector<RealT>>> state(numSpeakers);
    for (int i = 0; i < numSpeakers; ++i) {
        std::clock_t time_r = std::clock();
        con->solve(*rp, *up, *zp->basis(i), tol);
        state[i] = up->clone(); state[i]->set(*up);

        std::stringstream real;
        real << "state_" << i << ".txt";
        con->outputTpetraVector(u_ptr, real.str());

        *outStream
            << "  Solve " << i << " time:      "
            << static_cast<RealT>(std::clock() - time_r) / static_cast<RealT>(CLOCKS_PER_SEC)
            << std::endl;
    }
    *outStream << "End: PDE Solves" << std::endl << std::endl;

    // Build nonlinear model and parameter vector
    auto theta = ROL::makePtr<ROL::StdVector<RealT>>(numSpeakers, 1);
    auto model = ROL::makePtr<ROL::Reduced_Objective_SimOpt<RealT>>(obs, con, up, theta, up, false);

    // Build samplers for experiment space
    std::string pd = parlist->sublist("Problem").sublist("Design").get("Points File", "points_5000.txt");
    std::string wd = parlist->sublist("Problem").sublist("Design").get("Weights File", "weights_5000.txt");
    int nsampd = parlist->sublist("Problem").sublist("Design").get("Number of Samples", 5000);
    std::string po = parlist->sublist("Problem").sublist("Objective").get("Points File", "points_200.txt");
    std::string wo = parlist->sublist("Problem").sublist("Objective").get("Weights File", "weights_200.txt");
    int nsampo = parlist->sublist("Problem").sublist("Objective").get("Number of Samples", 200);

    *outStream << std::endl;
    *outStream << "  Design Points File:     " << pd << std::endl;
    *outStream << "  Design Weights File:    " << wd << std::endl;
    *outStream << "  Objective Points File:  " << po << std::endl;
    *outStream << "  Objective Weights File: " << wo << std::endl;
    *outStream << std::endl;

    auto dbman = ROL::makePtr<ROL::StdTeuchosBatchManager<RealT, int>>(dcomm);
    auto obman = ROL::makePtr<ROL::StdTeuchosBatchManager<RealT, int>>(ocomm);
    auto dsampler = ROL::makePtr<ROL::UserInputGenerator<RealT>>(pd, wd, nsampd, 2, dbman);
    auto osampler = ROL::makePtr<ROL::UserInputGenerator<RealT>>(po, wo, nsampo, 2, obman);

    // Build OED problem factory
    bool useUIG, homNoise;
    std::string regType, dtype;
    homNoise = parlist->sublist("Problem").get("Homoscedastic Noise", true);
    regType = parlist->sublist("Problem").get("Regression Type", "Least Squares");
    auto type = ROL::OED::StringToRegressionType(regType);
    auto noise = ROL::makePtr<Helmholtz_Noise<RealT>>();
    auto cov = ROL::makePtr<ROL::OED::StdMomentOperator<RealT>>(type, homNoise, noise);
    auto factory = ROL::makePtr<ROL::OED::Factory<RealT>>(model, dsampler, theta, cov, *parlist);
    obman->barrier();

    // Print factors if requested
    bool printFactors = parlist->sublist("Problem").get("Print Factors", false);
    if (printFactors) {
        std::stringstream factName_d, noisName_d, factName_o, noisName_o;
        std::ofstream factFile_d, noisFile_d, factFile_o, noisFile_o;
        ROL::Ptr<ROL::Vector<RealT>> Fp = zp->dual().clone();
        std::vector<RealT> pt;

        factName_d << "factors_des_" << dsampler->batchID() << ".txt";
        noisName_d << "noise_des_" << dsampler->batchID() << ".txt";
        factFile_d.open(factName_d.str());
        noisFile_d.open(noisName_d.str());
        factFile_d << std::scientific << std::setprecision(15);
        noisFile_d << std::scientific << std::setprecision(15);

        auto factors = factory->getFactors(theta);
        for (int i = 0; i < dsampler->numMySamples(); ++i) {
            pt = dsampler->getMyPoint(i);
            factors->evaluate(*Fp, pt);

            for (int j = 0; j < numSpeakers; ++j) {
                factFile_d << std::right << std::setw(25)
                           << (*ROL::dynamicPtrCast<ROL::StdVector<RealT>>(Fp)->getVector())[j];
            }
            factFile_d << std::endl;

            for (int j = 0; j < 2; ++j)
                noisFile_d << std::right << std::setw(25) << pt[j];
            noisFile_d << std::right << std::setw(25) << noise->evaluate(pt) << std::endl;
        }
        factFile_d.close();
        noisFile_d.close();

        factName_o << "factors_opt_" << osampler->batchID() << ".txt";
        noisName_o << "noise_opt_" << osampler->batchID() << ".txt";
        factFile_o.open(factName_o.str());
        noisFile_o.open(noisName_o.str());
        factFile_o << std::scientific << std::setprecision(15);
        noisFile_o << std::scientific << std::setprecision(15);

        for (int i = 0; i < osampler->numMySamples(); ++i) {
            pt = osampler->getMyPoint(i);
            factors->evaluate(*Fp, pt);

            for (int j = 0; j < numSpeakers; ++j) {
                factFile_o << std::right << std::setw(25)
                           << (*ROL::dynamicPtrCast<ROL::StdVector<RealT>>(Fp)->getVector())[j];
            }
            factFile_o << std::endl;

            for (int j = 0; j < 2; ++j)
                noisFile_o << std::right << std::setw(25) << pt[j];
            noisFile_o << std::right << std::setw(25) << noise->evaluate(pt) << std::endl;
        }
        factFile_o.close();
        noisFile_o.close();
    }

    // Solve OED problem
    dtype = parlist->sublist("OED").get("Optimality Type", "A");
    useUIG = parlist->sublist("Problem").get("Uniform Initial Guess", false);
    solve<RealT>(factory, dsampler, osampler, *parlist, dtype, *outStream, useUIG, checkDeriv);

    // Get a summary from the time monitor
    Teuchos::TimeMonitor::summarize();
}
catch (std::logic_error &err) {
    std::cout << "Design MPI Rank = " << drank
              << "  Objective MPI Rank = " << orank
              << std::endl << err.what() << std::endl;
    errorFlag = -1000;
}

if (errorFlag != 0)
    std::cout << "End Result: TEST FAILED\n";
else
    std::cout << "End Result: TEST PASSED\n";

return 0;
}

