#include <bits/stdc++.h>
using namespace std;

int n;
vector<int> parent;
vector<vector<int>> children;
vector<int> rep;

// Query function to determine which node is the result
int ask(int a, int b, int c) {
    cout << "0 " << a << " " << b << " " << c << endl;
    int res;
    cin >> res;
    return res;
}

// Find which child of u contains x, or -1 if none
int find_child(int u, int x) {
    vector<int>& ch = children[u];
    if (ch.empty()) return -1;

    vector<int> cand(ch.begin(), ch.end());
    while (!cand.empty()) {
        if (cand.size() == 1) {
            int c = cand[0];
            int res = ask(u, rep[c], x);
            if (res == rep[c]) return c;
            else return -1;
        }

        // Split into two roughly equal groups
        int m = cand.size() / 2;
        vector<int> A(cand.begin(), cand.begin() + m);
        vector<int> B(cand.begin() + m, cand.end());

        int a = A[0];
        int b = B[0];
        int res = ask(rep[a], rep[b], x);

        if (res == rep[a]) {
            cand = A;
        } else if (res == rep[b]) {
            cand = B;
        } else if (res == u) {
            // x is not in any child of u within cand
            return -1;
        } else {
            // should not happen
            assert(false);
        }
    }
    return -1;
}

void insert(int x, int root) {
    int u = root;
    while (true) {
        int c = find_child(u, x);
        if (c == -1) {
            // Attach x as a child of u
            parent[x] = u;
            children[u].push_back(x);
            rep[x] = x;
            break;
        } else {
            u = c;
        }
    }
}

int main() {
    cin >> n;
    parent.assign(n + 1, -1);
    children.resize(n + 1);
    rep.resize(n + 1);

    // Random order of insertion
    vector<int> nodes;
    for (int i = 1; i <= n; ++i) nodes.push_back(i);
    random_shuffle(nodes.begin(), nodes.end());

    int root = nodes[0];
    rep[root] = root;

    for (int i = 1; i < n; ++i) {
        insert(nodes[i], root);
    }

    // Output the discovered edges
    cout << "1";
    for (int i = 1; i <= n; ++i) {
        if (parent[i] != -1) {
            cout << " " << parent[i] << " " << i;
        }
    }
    cout << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Main function for sorting with specific operations
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n + 1), pos(n + 1);

    // Read input and build position mapping
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        pos[a[i]] = i;
    }

    // x=3 allows operations of length 2 and 4; x=1 only length 2 (for n<=2)
    int x = (n <= 2 ? 1 : 3);

    vector<pair<int,int>> ops;
    ops.reserve(200000);

    // Lambda to reverse segment [l, r]
    auto do_rev = [&](int l, int r) {
        while (l < r) {
            int vl = a[l], vr = a[r];
            swap(a[l], a[r]);
            pos[vl] = r;
            pos[vr] = l;
            l++; r--;
        }
    };

    if (x == 1) {
        // Only n<=2 here; adjacent swaps suffice.
        for (int i = 1; i <= n; i++) {
            while (pos[i] > i) {
                int p = pos[i];
                ops.push_back({p - 1, p});
                do_rev(p - 1, p);
            }
        }
    } else {
        // x==3: allowed lengths 2 and 4
        for (int i = 1; i <= n; i++) {
            // First try to bring element i closer using length-4 reversal
            while (pos[i] >= i + 3) {
                int p = pos[i];
                ops.push_back({p - 3, p}); // length 4
                do_rev(p - 3, p);
            }
            // Then use length-2 reversals for remaining distance
            while (pos[i] > i) {
                int p = pos[i];
                ops.push_back({p - 1, p}); // length 2
                do_rev(p - 1, p);
            }
        }
    }

    // Output results
    cout << x << "\n";
    cout << (int)ops.size() << "\n";
    for (auto &pr : ops) {
        cout << pr.first << " " << pr.second << "\n";
    }

    return 0;
}

