#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

// Query function to get distance between u and v
ll query(int u, int v) {
    cout << "? " << u << " " << v << endl;
    cout.flush();
    ll res;
    cin >> res;
    return res;
}

void solve() {
    int n;
    cin >> n;

    // Special case: single node tree
    if (n == 1) {
        cout << "!" << endl;
        return;
    }

    vector<ll> d1(n+1), dB(n+1);

    // Query distances from vertex 1 to all others
    for (int i = 2; i <= n; ++i) {
        d1[i] = query(1, i);
    }
    d1[1] = 0;

    // Find farthest vertex B from vertex 1
    int B = 2;
    for (int i = 3; i <= n; ++i) {
        if (d1[i] > d1[B]) {
            B = i;
        }
    }

    // Query distances from B to all others
    for (int i = 1; i <= n; ++i) {
        if (i != B) {
            dB[i] = query(B, i);
        }
    }
    dB[B] = 0;

    ll L = d1[B];  // Diameter length

    vector<ll> x(n+1), off(n+1);
    vector<int> path;

    // Compute x (distance along main path) and off (offset from main path)
    for (int i = 1; i <= n; ++i) {
        x[i] = (d1[i] + L - dB[i]) / 2;
        off[i] = (d1[i] - L + dB[i]) / 2;

        // Vertices on the main path have off=0
        if (off[i] == 0) {
            path.push_back(i);
        }
    }

    // Sort path vertices by distance from 1
    sort(path.begin(), path.end(), [&](int a, int b) {
        return d1[a] < d1[b];
    });

    // Map x value to vertex on the main path
    map<ll, int> x_to_vertex;
    for (int v : path) {
        x_to_vertex[d1[v]] = v;
    }

    // Group vertices by their attachment point on the main path
    vector<vector<int>> groups(n+1);
    for (int i = 1; i <= n; ++i) {
        if (off[i] == 0) {
            groups[i].push_back(i);
        } else {
            int att = x_to_vertex[x[i]];
            groups[att].push_back(i);
        }
    }

    vector<tuple<int, int, ll>> edges;

    // Add edges on the main path
    for (size_t i = 0; i + 1 < path.size(); ++i) {
        int u = path[i], v = path[i+1];
        ll w = d1[v] - d1[u];
        edges.emplace_back(u, v, w);
    }

    // Process each group attached to the main path
    for (int root : path) {
        vector<int>& group = groups[root];
        if (group.size() <= 1) continue;

        // Sort group by offset (root has off=0, others positive)
        sort(group.begin(), group.end(), [&](int a, int b) {
            return off[a] < off[b];
        });

        // Maintain current tree nodes sorted by off
        vector<int> nodes = {root};

        // Process non-root vertices in increasing order of off
        for (int v : group) {
            if (v == root) continue;

            // Binary search for parent among existing nodes
            int lo = 0, hi = nodes.size();
            while (hi - lo > 1) {
                int mid = (lo + hi) / 2;
                int u = nodes[mid];
                ll dist = query(v, u);

                if (dist == off[v] - off[u]) {
                    lo = mid;
                } else {
                    hi = mid;
                }
            }

            int parent = nodes[lo];
            edges.emplace_back(parent, v, off[v] - off[parent]);

            // Insert v into nodes maintaining sorted order by off
            nodes.push_back(v);
            for (int i = nodes.size()-1; i > 0; --i) {
                if (off[nodes[i]] < off[nodes[i-1]]) {
                    swap(nodes[i], nodes[i-1]);
                } else break;
            }
        }
    }

    // Output the answer
    cout << "!";
    for (auto [u, v, w] : edges) {
        cout << " " << u << " " << v << " " << w;
    }
    cout << endl;
    cout.flush();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        solve();
    }

    return 0;
}

