// Function to compute signature parity fix
unsigned int SignatureParityFix::f(const unsigned int seed)
{
    // Helper function using lambda recursion
    std::function<unsigned int(unsigned int)> aux;
    aux = [&](unsigned int n) -> unsigned int
    {
        if(n <= 0)
        {
            return seed;
        }
        else
        {
            unsigned int n_ = n - 1;
            return aux(n_);
        }
    };

    // Call helper with (seed + 1)
    return aux((seed + 1));
}

