    table1[2] = 3;

    uint32_t table2[3][2];
    table2[0][1] = 10;
    table2[2][1] = 20;

    int i;
    for (i=0; i<10; i++) 
    {
        a[i] = (nd_int() ? 3: 5);
    }  

    int y = nd_int();
    __CRAB_assume(y >= 0);
    __CRAB_assume(y < 10);
    int res = a[y];    
    __CRAB_assert(res >= 0); // ok
    __CRAB_assert(res <= 5); // ok

    int z = compute1(table1);
    __CRAB_assert(z <= 40);  // ok
    z = table1[1];
    __CRAB_assert(z <= 30);  // ok

    int w = compute2(table2);
    __CRAB_assert(w == 30);  // ok

    return res+z+w;
}

