int File::hash_fnct(const File& k) {
    int hashCode = 0;
    // if (k->parent != NULL)
    //	hashCode = hash_fnct(k->getParent());
    wchar_t* ref = (wchar_t*)k.m_abstractPathName.c_str();
    for (unsigned int i = 0; i < k.m_abstractPathName.length(); i++) {
        hashCode += ((hashCode * 33) + ref[i]) % 149;
    }
    return (int)hashCode;
}

