static volatile int Sink;

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
{
    // Initialize IDs array with -1
    int8_t Ids[256];
    memset(Ids, -1, sizeof(Ids));

    // Record first occurrence positions
    for(size_t i = 0; i < Size; i++)
        if(Ids[Data[i]] == -1)
            Ids[Data[i]] = i;

    // Get positions of 'F', 'U', 'Z'
    int F = Ids[(unsigned char)'F'];
    int U = Ids[(unsigned char)'U'];
    int Z = Ids[(unsigned char)'Z'];

    // Check if F, U, Z appear in order
    if(F >= 0 && U > F && Z > U)
    {
        Sink++;
        //fprintf(stderr, "IDS: %d %d %d\n", F, U, Z);
    }

    return 0;
}

