void Render()
{
    // Just clear the backbuffer
    float ClearColor[4] = { 0.0f, 0.125f, 0.3f, 1.0f }; //red,green,blue,alpha
    g_d3dContext->ClearRenderTargetView( g_renderTargetView.Get(), ClearColor );
    g_swapChain->Present( 0, 0 );
}

