// Static constant for dp1
static FLOAT dp1 = 1.;

// Main function implementation
blasint CNAME(blas_arg_t *args, BLASLONG *range_m, BLASLONG *range_n, FLOAT *sa, FLOAT *sb, BLASLONG myid)
{
    // Local variables declaration
    BLASLONG n, lda;
    FLOAT *a;
    FLOAT temp[2];
    BLASLONG i;

    // Extract parameters from args structure
    n      = args -> n;
    a      = (FLOAT *)args -> a;
    lda    = args -> lda;

    // Adjust n and a if range_n is provided
    if (range_n) {
        n      = range_n[1] - range_n[0];
        a     += range_n[0] * (lda + 1) * COMPSIZE;
    }

    // Main loop over i
    for (i = 0; i < n; i++) {
        SCAL_K(i + 1, 0, 0,
               *(a + (i + i * lda) * COMPSIZE + 0), ZERO,
               a + i * lda * COMPSIZE, 1, NULL, 0, NULL, 0);

        // Process off-diagonal elements if not last iteration
        if (i < n - 1) {
            temp[0] = DOTC_K(n - i - 1,
                             a + (i + (i + 1) * lda) * COMPSIZE, lda,
                             a + (i + (i + 1) * lda) * COMPSIZE, lda);
            GET_IMAGE(temp[1]);

            *(a + (i + i * lda) * COMPSIZE + 0) += temp[0];
            *(a + (i + i * lda) * COMPSIZE + 1)  = ZERO;

            GEMV_O(i, n - i - 1, 0, dp1, ZERO,
                   a + (    (i + 1) * lda) * COMPSIZE, lda,
                   a + (i + (i + 1) * lda) * COMPSIZE, lda,
                   a + (     i      * lda) * COMPSIZE, 1, sb);
        }
    }

    return 0;
}

