#include <chrono>

using namespace std;

// Main function to solve Max-Cut using randomized local search
int main()
{
    // Optimize I/O operations for speed
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    // Adjacency list to store the graph (1-based indexing)
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // Best solution found so far
    vector<int> best_s(n + 1, 0);
    long long max_cut_size = -1;

    // Time management: set limit slightly under typical limits (e.g., 0.9s for 1s limit)
    double time_limit = 0.90;
    auto start_time = chrono::high_resolution_clock::now();

    // Random number generator
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

    // Processing order vector
    vector<int> p(n);
    iota(p.begin(), p.end(), 1);
    vector<int> current_s(n + 1);

    // Main optimization loop (Randomized Local Search with restarts)
    while (true) {
        // Random initialization of partition
        for (int i = 1; i <= n; ++i) {
            current_s[i] = rng() & 1;
        }

        // Hill Climbing / Local Search
        bool improved = true;
        while (improved) {
            improved = false;

            // Shuffle vertices for unbiased processing
            shuffle(p.begin(), p.end(), rng);

            for (int u : p) {
                int same_set_neighbors = 0;
                int diff_set_neighbors = 0;

                for (int v : adj[u]) {
                    if (current_s[u] == current_s[v]) {
                        same_set_neighbors++;
                    } else {
                        diff_set_neighbors++;
                    }
                }

                // Flip if moving increases cut size
                if (same_set_neighbors > diff_set_neighbors) {
                    current_s[u] ^= 1;
                    improved = true;
                }
            }
        }

        // Compute cut size for current partition
        long long current_cut = 0;
        for (int u = 1; u <= n; ++u) {
            if (current_s[u] == 0) {
                for (int v : adj[u]) {
                    if (current_s[v] == 1) {
                        current_cut++;
                    }
                }
            }
        }

        // Update best solution if improved
        if (current_cut > max_cut_size) {
            max_cut_size = current_cut;
            best_s = current_s;
        }

        // Check time limit
        auto curr_time = chrono::high_resolution_clock::now();
        chrono::duration<double> elapsed = curr_time - start_time;
        if (elapsed.count() > time_limit) break;
    }

    // Output final partition
    for (int i = 1; i <= n; ++i) {
        cout << best_s[i];
        if (i != n) cout << " ";
    }
    cout << "\n";

    return 0;
}

class Solution {
public:
    // Determines if Alice wins based on vowel presence
    bool doesAliceWin(string s)
    {
        for(int i=0;i<s.size();i++)
            if((0x104111>>(s[i]-97))&1)
                return 1;                                
        return 0;
    }
};

