#include <algorithm>

using namespace llvm;

// Implements writing data to the circular buffer or underlying stream
void circular_raw_ostream::write_impl(const char *Ptr, size_t Size) 
{
  // If no buffer is configured, write directly to the underlying stream
  if (BufferSize == 0) 
  {
    TheStream->write(Ptr, Size);
    return;
  }

  // Write into the buffer, wrapping if necessary
  while (Size != 0) 
  {
    unsigned Bytes = 
      std::min(unsigned(Size), unsigned(BufferSize - (Cur - BufferArray)));

    memcpy(Cur, Ptr, Bytes);
    Size -= Bytes;
    Cur += Bytes;

    // Wrap around to the beginning of the buffer when full
    if (Cur == BufferArray + BufferSize) 
    {
      Cur = BufferArray;
      Filled = true;
    }
  }
}

// Flushes the buffer with an optional banner prefix
void circular_raw_ostream::flushBufferWithBanner() 
{
  if (BufferSize != 0) 
  {
    // Output the banner first
    TheStream->write(Banner, std::strlen(Banner));
    flushBuffer();
  }
}

