  ASSERT_EQ(hipSetDevice(0), hipSuccess);

  result =
      p2pMap(&comm, &proxyConn, &myInfo, &peerInfo, &p2pBuff, &devMem, &ipcPtr);

  EXPECT_EQ(result, ncclInternalError);

  ASSERT_EQ(hipSetDevice(0), hipSuccess);
  ASSERT_EQ(hipFree(p2pBuff.directPtr), hipSuccess);
}

