#include <catch2/catch_test_macros.hpp>
#include <thread>
#include <chrono>
#include <iostream>
#include <Gorgon/Utils/Logging.h>

// Test case for console logging functionality
TEST_CASE("Console test", "[Logger]")
{
    // Initialize logger with module name and options
    Gorgon::Utils::Logger logger("Test module", true, true);

    // Set up string stream for capturing output
    std::stringstream ss;
    logger.InitializeStream(ss);

    // Write initial log messages
    logger << "Hello " << 5;

    // Wait to ensure timestamp differences are valid
    std::this_thread::sleep_for(std::chrono::seconds(1));

    // Continue logging with newlines
    logger << "t" << std::endl << "a";

    // Change section and disable date marking
    logger.SetSection("Changed");
    logger.SetMarkDate(false);

    // Log another message
    logger.Log("One more log! ");

    // Reset stream position for reading
    ss.seekg(0, std::ios::beg);

    // Parse and verify timestamp components
    std::string s1, s2;
    ss >> s1; // date
    ss >> s2; // time

    Gorgon::Time::Date d(s1 + "T" + s2), now = Gorgon::Time::Date::Now();

    REQUIRE((now - d) < 2);

    // Verify section components
    ss >> s1; // section-1
    REQUIRE(s1 == "Test");
    ss >> s1; // section-2
    REQUIRE(s1 == "module");

    // Verify first message parts
    ss >> s1; // message-1
    REQUIRE(s1 == "Hello");
    ss >> s1; // message-2
    REQUIRE(s1 == "5");

    // Skip intermediate tokens and verify newline character
    ss >> s1 >> s1 >> s1 >> s1 >> s1;
    REQUIRE(s1 == "t");

    char c;
    ss.read(&c, 1);
    REQUIRE((c == '\n' || c == '\r'));

    // Verify next token 'a'
    ss >> s1; // a

    // Verify changed section and error message
    ss >> s1 >> s1;
    REQUIRE(s1 == "Changed");
    ss >> s1;
    REQUIRE(s1 == "Error!");

    // Clear the stream for next test
    ss.str("");

    // Disable time marking and log new message
    logger.SetMarkTime(false);
    logger << "Test2";

    ss >> s1;
    REQUIRE(s1 == "Changed");
    ss >> s1;
    REQUIRE(s1 == "Test2");

    // Disable color and verify
    logger.DisableColor();
    REQUIRE(logger.IsColorEnabled() == false);

    // Log success message
    logger.Log("Finally", Gorgon::Utils::Logger::Success);

    ss >> s1;
    REQUIRE(s1 == "Changed");
    ss >> s1;
    REQUIRE(s1 == "Success:");
    ss >> s1;
    REQUIRE(s1 == "Finally");
}

