// Status and log line buffers
static char* statusLines[DebugUI::StatusLines];
static char* logLines[DebugUI::LogLines];
static int currentStatusLine = 0;

// Constructor: initializes buffers and sets up rendering data
DebugUI::DebugUI()
{
    // Allocate and initialize log lines
    for (auto& logLine : logLines)
    {
        logLine = (char*)malloc(LineLength);
        memset(logLine, 0x0, LineLength);
    }

    // Allocate and initialize status lines
    for (auto& statusLine : statusLines)
    {
        statusLine = (char*)malloc(LineLength);
        memset(statusLine, 0x0, LineLength);
    }

    // Initialize render data with font
    RenderData = Iron::Drawlist::New();
    RenderData->SetFont(ReCraftCore::GetInstance()->GetAssetManager()->Get<Iron::Font>("font"));
}

// Destructor: frees allocated memory and resets render data
DebugUI::~DebugUI()
{
    // Free log lines
    for (int i = 0; i < LogLines; i++)
    {
        free(logLines[i]);
    }

    // Free status lines
    for (int i = 0; i < StatusLines; i++)
    {
        free(statusLines[i]);
    }

    // Reset render data
    RenderData.reset();
}

// Writes formatted text to the current status line
void DebugUI::Text(const char* text, ...)
{
    if (currentStatusLine >= StatusLines)
    {
        return;
    }

    va_list args;
    va_start(args, text);
    vsprintf(statusLines[currentStatusLine++], text, args);
    va_end(args);
}

// Adds a new log entry, shifting older entries down
void DebugUI::Log(const char* text, ...)
{
    char* lastLine = logLines[LogLines - 1];

    // Shift all log lines down by one position
    for (int i = LogLines - 1; i > 0; i--)
    {
        logLines[i] = logLines[i - 1];
    }

    // Insert new log at top
    logLines[0] = lastLine;

    va_list args;
    va_start(args, text);
    vsprintf(logLines[0], text, args);
    va_end(args);
}

// Renders the UI elements on screen
void DebugUI::Draw()
{
    RenderData->SetFontScale(0.5);

    // Draw log lines starting from bottom area
    int yOffset = (240 / 3) * 2;
    for (auto& logLine : logLines)
    {
        int step = 12;
        RenderData->DrawText(Amy::fvec2(0, yOffset), logLine, 0xffffffff);
        yOffset += step;
        if (yOffset >= 240)
            break;
    }

    // Draw status lines starting from top
    yOffset = 0;
    for (auto& statusLine : statusLines)
    {
        int step = 12;
        RenderData->DrawText(Amy::fvec2(0, yOffset), statusLine, 0xffffffff);
        yOffset += step;
        memset(statusLine, 0x0, LineLength);
    }

    // Reset status line counter
    currentStatusLine = 0;
}

