void CharIKScale::CaptureBefore() {
    if (mDest)
        mScale = mDest->LocalXfm().v.z;
}

// Capture scale after transformation
void CharIKScale::CaptureAfter() {
    if (mDest)
        mScale = mDest->LocalXfm().v.z / mScale;
}

