  ret = EVP_DigestFinal_ex(*ctx, digest, NULL) ? CURLE_OK : CURLE_SSL_CIPHER;
#endif /* ! NEED_NETBSD_SHA512_256_WORKAROUND */
  EVP_MD_CTX_destroy(*ctx);
  *ctx = NULL;
  return ret;
}

