#include <bits/stdc++.h>
using namespace std;

// Main function to generate a grid based on input x
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned long long x;
    if(!(cin >> x)) return 0;

    // Constructive approach: build a 64x64 grid representing a "snake" pattern
    int n = 64;
    vector<vector<int>> a(n, vector<int>(n, 0));

    // Build snake-like triangle pattern
    for(int i = 0; i < n; ++i)
    {
        if(i % 2 == 0)
        {
            for(int j = 0; j <= i; ++j) a[i][j] = 1;
        }
        else
        {
            for(int j = 0; j <= i; ++j) a[i][n - 1 - j] = 1;
        }
    }

    // Set rightmost column as sink corridor
    for(int i = 0; i < n; ++i) a[i][n - 1] = 1;

    // For each bit set in x, extend the corresponding row to the right
    for(int i = 0; i < n; ++i)
    {
        if(((x >> i) & 1ULL) == 0) continue;

        if(i % 2 == 0)
        {
            // Even row: fill from (i, i) to end
            for(int j = i; j < n; ++j) a[i][j] = 1;
        }
        else
        {
            // Odd row: fill from (i, n-1-i) to end
            for(int j = n - 1 - i; j < n; ++j) a[i][j] = 1;
        }
    }

    // Output grid
    cout << n << "\n";
    for(int i = 0; i < n; ++i)
    {
        for(int j = 0; j < n; ++j)
        {
            if(j) cout << ' ';
            cout << a[i][j];
        }
        cout << "\n";
    }

    return 0;
}

#include <flutter/dart_project.h>
#include <flutter/flutter_view_controller.h>
#include <windows.h>
