    void operator()(const asio::error_code&) {}
    int* count_;
};

void* asio_handler_allocate(std::size_t size,
    custom_allocation_timer_handler* handler)
{
    ++(*handler->count_);
    return ::operator new(size);
}

void asio_handler_deallocate(void* pointer, std::size_t,
