// Main synthesis function for vorbis decoding
int vorbis_synthesis(vorbis_block *vb, ogg_packet *op)
{
    vorbis_dsp_state     *vd = vb->vd;
    private_state        *b = vd->backend_state;
    vorbis_info          *vi = vd->vi;
    codec_setup_info     *ci = vi->codec_setup;
    oggpack_buffer       *opb = &vb->opb;
    int                   type, mode, i;

    /* first things first.  Make sure decode is ready */
    _vorbis_block_ripcord(vb);
    oggpack_readinit(opb, op->packet, op->bytes);

    /* Check the packet type */
    if(oggpack_read(opb, 1) != 0)
    {
        /* Oops.  This is not an audio data packet */
        return(OV_ENOTAUDIO);
    }

    /* read our mode and pre/post windowsize */
    mode = oggpack_read(opb, b->modebits);
    if(mode == -1) return(OV_EBADPACKET);

    vb->mode = mode;
    vb->W = ci->mode_param[mode]->blockflag;

    if(vb->W)
    {
        /* this doesn't get mapped through mode selection as it's used
           only for window selection */
        vb->lW = oggpack_read(opb, 1);
        vb->nW = oggpack_read(opb, 1);
        if(vb->nW == -1)   return(OV_EBADPACKET);
    }
    else
    {
        vb->lW = 0;
        vb->nW = 0;
    }

    /* more setup */
    vb->granulepos = op->granulepos;
    vb->sequence = op->packetno;
    vb->eofflag = op->e_o_s;

    /* alloc pcm passback storage */
    vb->pcmend = ci->blocksizes[vb->W];
    vb->pcm = _vorbis_block_alloc(vb, sizeof(*vb->pcm) * vi->channels);
    for(i = 0; i < vi->channels; i++)
        vb->pcm[i] = _vorbis_block_alloc(vb, vb->pcmend * sizeof(*vb->pcm[i]));

    /* unpack_header enforces range checking */
    type = ci->map_type[ci->mode_param[mode]->mapping];
    return(_mapping_P[type]->inverse(vb, ci->map_param[ci->mode_param[mode]->
						     mapping]));
}

/* used to track pcm position without actually performing decode.
   Useful for sequential 'fast forward' */
int vorbis_synthesis_trackonly(vorbis_block *vb, ogg_packet *op)
{
    vorbis_dsp_state     *vd = vb->vd;
    private_state        *b = vd->backend_state;
    vorbis_info          *vi = vd->vi;
    codec_setup_info     *ci = vi->codec_setup;
    oggpack_buffer       *opb = &vb->opb;
    int                   mode;

    /* first things first.  Make sure decode is ready */
    _vorbis_block_ripcord(vb);
    oggpack_readinit(opb, op->packet, op->bytes);

    /* Check the packet type */
    if(oggpack_read(opb, 1) != 0)
    {
        /* Oops.  This is not an audio data packet */
        return(OV_ENOTAUDIO);
    }

    /* read our mode and pre/post windowsize */
    mode = oggpack_read(opb, b->modebits);
    if(mode == -1) return(OV_EBADPACKET);

    vb->mode = mode;
    vb->W = ci->mode_param[mode]->blockflag;

    if(vb->W)
    {
        vb->lW = oggpack_read(opb, 1);
        vb->nW = oggpack_read(opb, 1);
        if(vb->nW == -1)   return(OV_EBADPACKET);
    }
    else
    {
        vb->lW = 0;
        vb->nW = 0;
    }

    /* more setup */
    vb->granulepos = op->granulepos;
    vb->sequence = op->packetno;
    vb->eofflag = op->e_o_s;

    /* no pcm */
    vb->pcmend = 0;
    vb->pcm = NULL;
    return(0);
}

long vorbis_packet_blocksize(vorbis_info *vi, ogg_packet *op)
{
    codec_setup_info     *ci = vi->codec_setup;
    oggpack_buffer       opb;
    int                  mode;

    oggpack_readinit(&opb, op->packet, op->bytes);

    /* Check the packet type */
    if(oggpack_read(&opb, 1) != 0)
    {
        /* Oops.  This is not an audio data packet */
        return(OV_ENOTAUDIO);
    }

    {
        int modebits = 0;
        int v = ci->modes;
        while(v > 1)
        {
            modebits++;
            v >>= 1;
        }

        /* read our mode and pre/post windowsize */
        mode = oggpack_read(&opb, modebits);
    }

    if(mode == -1) return(OV_EBADPACKET);
    return(ci->blocksizes[ci->mode_param[mode]->blockflag]);
}

int vorbis_synthesis_halfrate(vorbis_info *vi, int flag)
{
    /* set / clear half-sample-rate mode */
    codec_setup_info     *ci = vi->codec_setup;

    /* right now, our MDCT can't handle < 64 sample windows. */
    if(ci->blocksizes[0] <= 64 && flag) return -1;
    ci->halfrate_flag = (flag ? 1 : 0);
    return 0;
}

int vorbis_synthesis_halfrate_p(vorbis_info *vi)
{
    codec_setup_info     *ci = vi->codec_setup;
    return ci->halfrate_flag;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <numeric>
#include <algorithm>

// Disjoint Set Union with union-by-size and path compression
struct DSU {
    std::vector<int> parent;
    std::vector<int> sz;
    int components;

    DSU(int n) {
        parent.resize(n);
        std::iota(parent.begin(), parent.end(), 0);
        sz.assign(n, 1);
        components = n;
    }

    // Default copy constructor is sufficient and correct
    DSU(const DSU& other) = default;

    int find(int i) {
        if (parent[i] == i)
            return i;
        return parent[i] = find(parent[i]);
    }

    void unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) {
            if (sz[root_i] < sz[root_j]) std::swap(root_i, root_j);
            parent[root_j] = root_i;
            sz[root_i] += sz[root_j];
            components--;
        }
    }
};

struct Point {
    int x, y;
};

struct Edge {
    int u, v;
    int d; // Rounded Euclidean distance
};

// Edge in the component graph
struct CompEdge {
    int u, v; // component roots
    double w; // estimated weight

    bool operator<(const CompEdge& other) const {
        return w < other.w;
    }
};

double euclidean_dist(const Point& a, const Point& b) {
    long long dx = a.x - b.x;
    long long dy = a.y - b.y;
    return std::sqrt(static_cast<double>(dx * dx + dy * dy));
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    const int N = 400;
    const int M = 1995;

    std::vector<Point> ps(N);
    for (int i = 0; i < N; ++i) {
        std::cin >> ps[i].x >> ps[i].y;
    }

    std::vector<Edge> edges(M);
    for (int i = 0; i < M; ++i) {
        std::cin >> edges[i].u >> edges[i].v;
        edges[i].d = std::round(euclidean_dist(ps[edges[i].u], ps[edges[i].v]));
    }

    DSU dsu(N);

    for (int i = 0; i < M; ++i) {
        int l;
        std::cin >> l;
        int u = edges[i].u;
        int v = edges[i].v;
        int root_u = dsu.find(u);
        int root_v = dsu.find(v);

        if (root_u == root_v) {
            std::cout << 0 << std::endl;
            continue;
        }

        // Dynamically adjust beta based on progress
        double progress = static_cast<double>(i) / (M - 1);
        double beta = 1.4 + 1.6 * progress * progress;

        std::vector<CompEdge> comp_edges;
        if (i < M - 1) {
            comp_edges.reserve(M - 1 - i);
        }

        for (int j = i + 1; j < M; ++j) {
            int fu = dsu.find(edges[j].u);
            int fv = dsu.find(edges[j].v);
            if (fu != fv) {
                comp_edges.push_back({fu, fv, beta * edges[j].d});
            }
        }

        std::sort(comp_edges.begin(), comp_edges.end());

        double w_path = 1e18; // Effectively infinity
        if (!comp_edges.empty()) {
            DSU comp_dsu = dsu;
            for (const auto& edge : comp_edges) {
                if (comp_dsu.find(edge.u) != comp_dsu.find(edge.v)) {
                    comp_dsu.unite(edge.u, edge.v);
                    if (comp_dsu.find(root_u) == comp_dsu.find(root_v)) {
                        w_path = edge.w;
                        break;
                    }
                }
            }
        }

        if (static_cast<double>(l) < w_path) {
            std::cout << 1 << std::endl;
            dsu.unite(u, v);
        } else {
            std::cout << 0 << std::endl;
        }
    }

    return 0;
}

#include <Application.h>
#include <Window.h>
#include <View.h>
#include <Button.h>
#include <StringView.h>
#include <String.h>

// Message constant for the button click event
const uint32 kButtonClicked = 'btcl';

class ButtonWindow : public BWindow
{
public:
	ButtonWindow(BRect frame)
		:
		BWindow(frame, "Button Example", B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE),
		fClickCount(0)
	{
		// Background view to host controls
		BRect bounds = Bounds();
		BView* background = new BView(bounds, "background", B_FOLLOW_ALL, B_WILL_DRAW);
		background->SetViewColor(220, 220, 220);
		AddChild(background);

		// Button that triggers the counter
		BRect buttonRect(20, 20, 120, 50);
		BButton* button = new BButton(buttonRect, "clickme", "Click Me",
		                               new BMessage(kButtonClicked));
		background->AddChild(button);

		// Initial label
		BRect labelRect(20, 60, 280, 80);
		fLabel = new BStringView(labelRect, "label", "Click the button");
		fLabel->SetFont(be_plain_font);
		background->AddChild(fLabel);
	}

	virtual ~ButtonWindow()
	{
	}

	virtual bool QuitRequested()
	{
		be_app->PostMessage(B_QUIT_REQUESTED);
		return true;
	}

	void MessageReceived(BMessage* message) override
	{
		switch (message->what) {
			case kButtonClicked:
				fClickCount++;
				{
					BString labelText;
					labelText.SetToFormat("Clicked %d time%s",
					                      fClickCount,
					                      fClickCount == 1 ? "" : "s");
					fLabel->SetText(labelText.String());
				}
				break;
			default:
				BWindow::MessageReceived(message);
		}
	}
private:
	BStringView* fLabel;
	int32 fClickCount;
};

class ButtonApp : public BApplication
{
public:
	ButtonApp()
		:
		BApplication("application/x-vnd.example-buttonapp")
	{
	}

	virtual void ReadyToRun()
	{
		BRect rect(100, 100, 320, 200);
		ButtonWindow* window = new ButtonWindow(rect);
		window->Show();
	}
};

// Main program
int main()
{
	ButtonApp app;
	app.Run();
	return 0;
}

#include "let_fix.h"
#include <iostream>

namespace {
    int testStatus = 0;

    void aSsErT(bool condition, const char *message, int line)
    {
        if (condition) {
            std::cout << "Error " __FILE__ "(" << line << "): " << message
                 << "    (failed)" << std::endl;
            if (0 <= testStatus && testStatus <= 100) {
                ++testStatus;
            }
        }
    }

    template <typename A>
    A list_nth(const std::shared_ptr<List<A>> &l, unsigned int n) {
        auto cur = l;
        for (unsigned int i = 0; i < n; ++i) {
            auto &c = std::get<typename List<A>::cons>(cur->v());
            cur = c._a1;
        }
        return std::get<typename List<A>::cons>(cur->v())._a0;
    }
}  // close unnamed namespace

#define ASSERT(X)                                              \
    aSsErT(!(X), #X, __LINE__);

int main()
{
    // Test 1: local_sum [1;2;3;4;5] = 15
    {
        ASSERT(LetFix::test_sum == 15);
        std::cout << "Test 1 (local_sum): PASSED" << std::endl;
    }

    // Test 2: local_rev [1;2;3] = [3;2;1]
    {
        ASSERT(list_nth(LetFix::test_rev, 0) == 3);
        ASSERT(list_nth(LetFix::test_rev, 1) == 2);
        ASSERT(list_nth(LetFix::test_rev, 2) == 1);
        std::cout << "Test 2 (local_rev): PASSED" << std::endl;
    }

    // Test 3: local_mem
    {
        ASSERT(LetFix::test_mem_found == true);
        ASSERT(LetFix::test_mem_missing == false);
        std::cout << "Test 3 (local_mem): PASSED" << std::endl;
    }

    // Test 4: local_flatten [[1;2];[3];[4;5;6]] = [1;2;3;4;5;6]
    {
        ASSERT(list_nth(LetFix::test_flatten, 0) == 1);
        ASSERT(list_nth(LetFix::test_flatten, 5) == 6);
        std::cout << "Test 4 (local_flatten): PASSED" << std::endl;
    }

    if (testStatus == 0) {
        std::cout << "\nAll let_fix tests passed!" << std::endl;
    } else {
        std::cout << "\n" << testStatus << " test(s) failed!" << std::endl;
    }

    return testStatus;
}

