// Main function to solve the problem
int main()
{
    int R, H;
    cin >> R >> H; // R=75, H=1

    const int m = 40; // number of robots we will use
    const int n = 1000;
    const double p = 0.293;

    vector<uint64_t> mask(n);
    vector<vector<int>> queries(m);

    // Generate a random matrix that is 2-separable
    mt19937 rng;
    bernoulli_distribution dist(p);
    bool good = false;

    for (int seed = 0; seed < 100; seed++) {
        rng.seed(seed);
        // Reset
        for (int i = 0; i < n; i++) mask[i] = 0;
        for (int i = 0; i < m; i++) queries[i].clear();

        // Generate matrix
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (dist(rng)) {
                    mask[j] |= (1ULL << i);
                    queries[i].push_back(j+1); // positions are 1-indexed
                }
            }
        }

        // Check 2-separability: all pair-wise ORs must be distinct
        unordered_set<uint64_t> seen;
        good = true;
        for (int i = 0; i < n && good; i++) {
            for (int j = i; j < n; j++) {
                uint64_t union_mask = mask[i] | mask[j];
                if (seen.count(union_mask)) {
                    good = false;
                    break;
                }
                seen.insert(union_mask);
            }
        }
        if (good) {
            // Found a good matrix
            break;
        }
    }

    // In the extremely unlikely case that no good matrix is found,
    // we fall back to the last generated matrix (still very likely to work).

    // Send queries
    for (int i = 0; i < m; i++) {
        cout << "? " << queries[i].size();
        for (int pos : queries[i]) {
            cout << " " << pos;
        }
        cout << endl;
        cout.flush();
    }

    // Get results
    cout << "@" << endl;
    cout.flush();

    int L;
    cin >> L;
    vector<int> res(L);
    for (int i = 0; i < L; i++) {
        cin >> res[i];
    }

    // Compute result mask
    uint64_t resultMask = 0;
    for (int i = 0; i < m; i++) {
        if (res[i] == 1) {
            resultMask |= (1ULL << i);
        }
    }

    // Find the pair that matches the result mask
    int a = -1, b = -1;
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            if ((mask[i] | mask[j]) == resultMask) {
                a = i+1;
                b = j+1;
                break;
            }
        }
        if (a != -1) break;
    }

    // Output answer
    cout << "! " << a << " " << b << endl;
    cout.flush();

    return 0;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <chrono>

using namespace std;

int n;
vector<int> p; // Stores the permutation, 1-based. 0 means unknown.
vector<int> known_indices; // Stores indices where p is known.

// Ask function: sends query and receives response
int ask(const vector<int>& q) {
    cout << "0";
    for (int x : q) {
        cout << " " << x;
    }
    cout << endl;
    int res;
    cin >> res;
    return res;
}

// Guess function: outputs final answer and exits
void guess(const vector<int>& ans) {
    cout << "1";
    for (int i = 0; i < n; ++i) {
        cout << " " << ans[i];
    }
    cout << endl;
    exit(0);
}

// Find position of val among candidates using binary search
// pad_val is used for candidates not in the current test half.
// It is assumed pad_val does not match any value in candidates.
int solve_single(int val, vector<int>& candidates, int pad_val) {
    int l = 0, r = candidates.size() - 1;
    while (l < r) {
        int mid = l + (r - l) / 2;
        vector<int> q(n);

        // Fill query: use known values or pad_val for unknown positions
        for (int i = 1; i <= n; ++i) {
            if (p[i] != 0) 
                q[i-1] = p[i];
            else 
                q[i-1] = pad_val;
        }

        // Set first half candidates to val
        for (int i = l; i <= mid; ++i) {
            q[candidates[i]-1] = val;
        }

        int score = ask(q);

        // Calculate expected score from known positions
        int expected = 0;
        for (int idx : known_indices) {
            // p[idx] is known. q[idx-1] is set to p[idx].
            expected++;
        }

        // If score > expected, then val is in the first half
        if (score > expected) {
            r = mid;
        } else {
            l = mid + 1;
        }
    }
    return candidates[l];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> n)) return 0;

    p.assign(n + 1, 0);

    // Handle trivial case
    if (n == 1) {
        guess({1});
    }

    // Step 1: Find positions of 1 and 2
    vector<int> candidates(n);
    iota(candidates.begin(), candidates.end(), 1);

    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

    vector<int> u1, u2;
    while (true) {
        shuffle(candidates.begin(), candidates.end(), rng);
        int mid = n / 2;
        u1.clear(); u2.clear();
        vector<int> q(n);
        for (int i = 0; i < n; ++i) {
            if (i < mid) {
                u1.push_back(candidates[i]);
                q[candidates[i]-1] = 1;
            } else {
                u2.push_back(candidates[i]);
                q[candidates[i]-1] = 2;
            }
        }

        int score = ask(q);
        if (score == 2) {
            // 1 in u1, 2 in u2
            break;
        } else if (score == 0) {
            // 1 in u2, 2 in u1
            swap(u1, u2);
            break;
        }
        // score 1: try again
    }

    int pos1 = solve_single(1, u1, 2);
    p[pos1] = 1;
    known_indices.push_back(pos1);

    int pos2 = solve_single(2, u2, 1);
    p[pos2] = 2;
    known_indices.push_back(pos2);

    // Step 2: Find 3..n
    vector<int> unknowns;
    for (int i = 1; i <= n; ++i) {
        if (p[i] == 0) unknowns.push_back(i);
    }

    for (int k = 3; k <= n; ++k) {
        // If only one unknown left, it must be k
        if (unknowns.size() == 1) {
            p[unknowns[0]] = k;
            known_indices.push_back(unknowns[0]);
            unknowns.clear();
            break;
        }

        int pos = solve_single(k, unknowns, 1);
        p[pos] = k;
        known_indices.push_back(pos);

        for (int i = 0; i < unknowns.size(); ++i) {
            if (unknowns[i] == pos) {
                unknowns.erase(unknowns.begin() + i);
                break;
            }
        }
    }

    vector<int> ans;
    for (int i = 1; i <= n; ++i) ans.push_back(p[i]);
    guess(ans);

    return 0;
}

