    }
} // Y_UNIT_TEST_SUITE(TestSourceRoot)

#include "draw_rectangular_marquee.h"
#include "gl.h"
#include "glu.h"
#include "../material_colors.h"

// Draw a rectangular marquee (selection box)
IGL_INLINE void igl::opengl2::draw_rectangular_marquee(
  const int from_x,
  const int from_y,
  const int to_x,
  const int to_y)
{
  using namespace std;

  // Save current OpenGL state
  int l;
  glGetIntegerv(GL_LIGHTING, &l);
  int s;
  glGetIntegerv(GL_LINE_STIPPLE, &s);
  double lw;
  glGetDoublev(GL_LINE_WIDTH, &lw);

  // Disable lighting for 2D overlay
  glDisable(GL_LIGHTING);

  // Get current viewport dimensions
  GLint viewport[4];
  glGetIntegerv(GL_VIEWPORT, viewport);
  const int width = viewport[2];
  const int height = viewport[3];

  // Set up projection matrix for 2D screen coordinates
  glMatrixMode(GL_PROJECTION);
  glPushMatrix();
  glLoadIdentity();
  gluOrtho2D(0, width, 0, height);

  // Set up modelview matrix
  glMatrixMode(GL_MODELVIEW);
  glPushMatrix();
  glLoadIdentity();

  // Configure line appearance
  glEnable(GL_LINE_STIPPLE);
  glLineStipple(3, 0xAAAA);
  glLineWidth(1);
  glColor4f(0.2, 0.2, 0.2, 1);

  // Draw the rectangle
  glBegin(GL_LINE_STRIP);
  glVertex2d(from_x, from_y);
  glVertex2d(to_x, from_y);
  glVertex2d(to_x, to_y);
  glVertex2d(from_x, to_y);
  glVertex2d(from_x, from_y);
  glEnd();

  // Restore original matrices
  glPopMatrix();
  glMatrixMode(GL_PROJECTION);
  glPopMatrix();
  glMatrixMode(GL_MODELVIEW);

  // Restore original OpenGL state
  glLineWidth(lw);
  (s ? glEnable(GL_LINE_STIPPLE) : glDisable(GL_LINE_STIPPLE));
  (l ? glEnable(GL_LIGHTING) : glDisable(GL_LIGHTING));
}

