typedef struct alignas(16) {
    uint64_t lower;
    uint64_t upper;
} uint128_val;

template<>
inline bool compare_and_swap(volatile uint128_val *destination, uint128_val expected, uint128_val replacement) {
    uint64_t exp_lower = expected.lower;
    uint64_t exp_upper = expected.upper;
    uint64_t rep_lower = replacement.lower;
    uint64_t rep_upper = replacement.upper;
    unsigned char success_flag = 0;

    __asm__ __volatile__ (
        "lock cmpxchg16b %1\n\t"
        "setz %0\n\t"
        : "=q" (success_flag), "+m" (*destination)
        : "a" (exp_lower), "d" (exp_upper), "b" (rep_lower), "c" (rep_upper)
        : "cc", "memory"
    );

    return success_flag;
}

#include <immintrin.h> // AVX intrinsics header

void reorder(float* dest, const float* src, size_t len) {
    size_t idx = 0;
    while (idx < len) {
        // Verify that the next 8 elements are non-zero and safe to process in bulk
        if (src[idx] != 0.0f && src[idx + 1] != 0.0f && src[idx + 2] != 0.0f && src[idx + 3] != 0.0f &&
            src[idx + 4] != 0.0f && src[idx + 5] != 0.0f && src[idx + 6] != 0.0f && src[idx + 7] != 0.0f) {
            // Load 8 single-precision floats from source
            __m256 simd_vec = _mm256_loadu_ps(&src[idx]);
            // Store 8 floats to destination
            _mm256_storeu_ps(&dest[idx], simd_vec);
            idx += 8;
        } else {
            // Process element-by-element for zero or boundary cases
            dest[idx] = src[idx];
            idx++;
        }
    }
}

#include <immintrin.h>

// Perform complex conjugate multiplication using AVX instructions
void avx_vcmulcc(cfloat* output, const cfloat* inputA, const cfloat* inputB, int count) {
    for (int index = 0; index < count; index += 8) {
        __m256 operand1 = _mm256_loadu_ps((const float*)(inputA + index));
        __m256 operand2 = _mm256_loadu_ps((const float*)(inputB + index));

        // Extract real and imaginary parts with appropriate permutations
        __m256 real_part1 = _mm256_permute_ps(operand1, _MM_SHUFFLE(2, 3, 0, 1));
        __m256 imag_part1 = _mm256_permute_ps(operand1, _MM_SHUFFLE(3, 2, 1, 0));
        __m256 real_part2 = _mm256_permute_ps(operand2, _MM_SHUFFLE(2, 3, 0, 1));
        __m256 imag_part2 = _mm256_permute_ps(operand2, _MM_SHUFFLE(3, 2, 1, 0));

        // Compute real part: real1*real2 - imag1*imag2
        __m256 result_real = _mm256_sub_ps(_mm256_mul_ps(real_part1, real_part2), 
                                           _mm256_mul_ps(imag_part1, imag_part2));

        // Compute imaginary part: real1*imag2 + imag1*real2
        __m256 result_imag = _mm256_add_ps(_mm256_mul_ps(real_part1, imag_part2), 
                                           _mm256_mul_ps(imag_part1, real_part2));

        // Store the result by combining real and imaginary parts
        _mm256_storeu_ps((float*)(output + index), 
                         _mm256_permute2f128_ps(result_real, result_imag, 0x20));
    }
}

