// Encrypts characters using a key through inline assembly
void encrypt_chars(int size, char encryptionKey)
{
    char current_char;

    for (int index = 0; index < size; index++)
    {
        current_char = OChars[index];
        __asm
        {
            push eax
            push ecx

            movzx ecx, current_char
            push ecx
            lea eax, encryptionKey
            push eax
            call encrypt4
            add esp, 8
            mov current_char, al

            pop ecx
            pop eax
        }
        EChars[index] = current_char;
    }
    return;
}

