    virtual double computeCovariance(double input1, double input2) const = 0;
    virtual std::unique_ptr<CovarianceBase> duplicate() const = 0;
};

class RBFKernel : public CovarianceBase {
public:
    RBFKernel(double bandwidth, double amplitude) : m_bandwidth(bandwidth), m_amplitude(amplitude) {}
    RBFKernel(double bandwidth) : m_bandwidth(bandwidth), m_amplitude(1.0) {}

    double computeCovariance(double input1, double input2) const override {
        return m_amplitude * std::exp(-std::norm(input1 - input2) / (m_bandwidth * m_bandwidth));
    }

    std::unique_ptr<CovarianceBase> duplicate() const override {
        return std::make_unique<RBFKernel>(*this);
    }

private:
    double m_bandwidth;
    double m_amplitude;
};

class SumKernel : public CovarianceBase {
public:
    SumKernel(std::unique_ptr<CovarianceBase> partA, std::unique_ptr<CovarianceBase> partB)
        : partA_(std::move(partA)), partB_(std::move(partB)) {}

    double computeCovariance(double input1, double input2) const override {
        return partA_->computeCovariance(input1, input2) + partB_->computeCovariance(input1, input2);
    }

    std::unique_ptr<CovarianceBase> duplicate() const override {
        return std::make_unique<SumKernel>(partA_->duplicate(), partB_->duplicate());
    }

private:
    std::unique_ptr<CovarianceBase> partA_;
    std::unique_ptr<CovarianceBase> partB_;
};

