// Function to find the longest palindromic substring in a given string
std::string findLongestPalindrome(std::string text) {
    if (text.empty()) return "";

    int length = text.size();
    int startIndex = 0, maxLength = 1;

    // Lambda function to expand around a center and return palindrome length
    auto checkPalindrome = [&](int left, int right) {
        while (left >= 0 && right < length && text[left] == text[right]) {
            left--;
            right++;
        }
        return right - left - 1;
    };

    for (int index = 0; index < length; ++index) {
        int oddLength = checkPalindrome(index, index);       // Check odd-length palindromes
        int evenLength = checkPalindrome(index, index + 1);  // Check even-length palindromes
        int currentMax = std::max(oddLength, evenLength);

        if (currentMax > maxLength) {
            maxLength = currentMax;
            startIndex = index - (currentMax - 1) / 2;
        }
    }

    return text.substr(startIndex, maxLength);
}

int main() {
    std::string inputText = "abaxyzzyxf";
    std::string palindromeResult = findLongestPalindrome(inputText);
    std::cout << "The longest palindromic substring is: " << palindromeResult << std::endl;
    return 0;
}

