namespace types {
    struct uint128_t {
        uint64_t low;
        uint64_t high;
    };
}

template<>
inline bool compare_and_swap(volatile types::uint128_t *destination, types::uint128_t expected, types::uint128_t replacement)
{
    uint64_t exp_low = expected.low;
    uint64_t exp_high = expected.high;
    uint64_t rep_low = replacement.low;
    uint64_t rep_high = replacement.high;
    unsigned char success_flag = 0;

    __asm__ __volatile__ (
        "lock; cmpxchg16b %1\n\t"
        "setz %0\n\t"
        : "=q"(success_flag), "+m"(*destination)
        : "a"(exp_low), "d"(exp_high), "b"(rep_low), "c"(rep_high)
        : "memory", "cc"
    );

    return success_flag;
}

