// Verify an ECDSA signature using SHA256
bool CheckSignature(const ECDSA<ECP, SHA256>::PublicKey& publicKey, const std::string& data, const std::string& sig)
{
    std::string rHex = sig.substr(0, sig.length() / 2);
    std::string sHex = sig.substr(sig.length() / 2);

    std::string rValue, sValue;
    HexDecoder rConverter(new StringSink(rValue));
    rConverter.Put(reinterpret_cast<const byte*>(rHex.data()), rHex.size());
    rConverter.MessageEnd();

    HexDecoder sConverter(new StringSink(sValue));
    sConverter.Put(reinterpret_cast<const byte*>(sHex.data()), sHex.size());
    sConverter.MessageEnd();

    ECDSA<ECP, SHA256>::Verifier verifier(publicKey);
    bool isValid = verifier.VerifyMessage(
        reinterpret_cast<const byte*>(data.data()), 
        data.size(), 
        reinterpret_cast<const byte*>(rValue.data()), 
        rValue.size(), 
        reinterpret_cast<const byte*>(sValue.data()), 
        sValue.size()
    );

    return isValid;
}

