// Compute dot product using recursion for array size M
template<int M>
double computeDot(double arr1[], double arr2[]) {
    return arr1[M-1] * arr2[M-1] + computeDot<M-1>(arr1, arr2);
}

// Base case for recursion when size is 1
template<>
double computeDot<1>(double arr1[], double arr2[]) {
    return arr1[0] * arr2[0];
}

