extern "C" {
    PHP_FUNCTION(matrix_multiply) {
        double *inputMatrixA, *inputMatrixB;
        int dimRowsA, dimColsA, dimRowsB, dimColsB;

        if (zend_parse_parameters(ZEND_NUM_ARGS(), "ddiiii", &inputMatrixA, &inputMatrixB, &dimRowsA, &dimColsA, &dimRowsB, &dimColsB) == FAILURE) {
            RETURN_NULL();
        }

        MatrixXd matrixA(dimRowsA, dimColsA);
        MatrixXd matrixB(dimRowsB, dimColsB);

        // Populate first matrix from input data
        for (int row = 0; row < dimRowsA; ++row) {
            for (int col = 0; col < dimColsA; ++col) {
                matrixA(row, col) = inputMatrixA[row * dimColsA + col];
            }
        }

        // Populate second matrix from input data
        for (int row = 0; row < dimRowsB; ++row) {
            for (int col = 0; col < dimColsB; ++col) {
                matrixB(row, col) = inputMatrixB[row * dimColsB + col];
            }
        }

        MatrixXd outputMatrix = matrixA * matrixB;

        size_t totalElements = outputMatrix.rows() * outputMatrix.cols();
        double *outputData = (double*)malloc(totalElements * sizeof(double));

        // Extract result matrix into flat array
        for (int row = 0; row < outputMatrix.rows(); ++row) {
            for (int col = 0; col < outputMatrix.cols(); ++col) {
                outputData[row * outputMatrix.cols() + col] = outputMatrix(row, col);
            }
        }

        RETURN_DOUBLE_ARRAY(outputData, totalElements, 0);
    }
}

