void renderTree(float posX, float posY, float trunkHeight, float canopySize) {
    // Render the trunk
    glBegin(GL_QUADS);
    glColor3f(0.5f, 0.25f, 0.0f);  // Brown color for trunk
    glVertex3f(posX - 0.5f, posY, 0.0f);
    glVertex3f(posX + 0.5f, posY, 0.0f);
    glVertex3f(posX + 0.5f, posY + trunkHeight, 0.0f);
    glVertex3f(posX - 0.5f, posY + trunkHeight, 0.0f);
    glEnd();

    // Render the foliage
    std::random_device randomSeed;
    std::mt19937 rng(randomSeed());
    std::uniform_real_distribution<> angleDist(-1.0, 1.0);

    for (int leafIndex = 0; leafIndex < 100; ++leafIndex) {
        float theta = angleDist(rng) * 3.14159f * 2.0f;
        float radialOffset = angleDist(rng) * canopySize;
        float leafX = posX + radialOffset * std::cos(theta) * 2.0f;
        float leafY = posY + trunkHeight + radialOffset * std::sin(theta) * 2.0f;

        glBegin(GL_TRIANGLES);
        glColor3f(0.0f, 1.0f, 0.0f);  // Green color for leaves
        glVertex3f(leafX, leafY, 0.0f);
        glVertex3f(leafX + 0.1f, leafY + 0.1f, 0.0f);
        glVertex3f(leafX - 0.1f, leafY + 0.1f, 0.0f);
        glEnd();
    }
}

