// Determine if a number is prime and find its smallest divisor
bool checkPrime(int value, int& minFactor) {
    if (value <= 1) {
        minFactor = 1; // Values ≤ 1 are not prime
        return false;
    }
    if (value <= 3) {
        minFactor = value; // 2 and 3 are prime
        return true;
    }
    if (value % 2 == 0) {
        minFactor = 2; // Even numbers > 2 are not prime
        return false;
    }
    for (int j = 3; j <= std::sqrt(value); j += 2) {
        if (value % j == 0) {
            minFactor = j; // Found a divisor, so value is not prime
            return false;
        }
    }
    minFactor = value; // No divisors found, value is prime
    return true;
}

int main() {
    int inputNumber;
    std::cout << "Enter a number: ";
    std::cin >> inputNumber;

    int factor;
    if (checkPrime(inputNumber, factor)) {
        std::cout << inputNumber << " is a prime number." << std::endl;
    } else {
        std::cout << inputNumber << " is not a prime number. The smallest divisor is " << factor << "." << std::endl;
    }

    return 0;
}

