using namespace std;

// Find the longest substring without repeating characters and count unique chars
pair<int, int> findLongestUniqueSubstring(const string& input) {
    if (input.empty()) return {0, 0};

    unordered_map<char, int> positionMap;
    int bestLength = 0, bestUniqueCount = 0, left = 0;

    for (int right = 0; right < input.length(); ++right) {
        if (positionMap.count(input[right]) > 0) {
            left = max(left, positionMap[input[right]] + 1);
        }
        positionMap[input[right]] = right;
        int windowSize = right - left + 1;
        int distinctChars = positionMap.size();

        if (windowSize > bestLength) {
            bestLength = windowSize;
            bestUniqueCount = distinctChars;
        }
    }

    return {bestLength, bestUniqueCount};
}

int main() {
    string text = "pwwkew";
    pair<int, int> answer = findLongestUniqueSubstring(text);
    cout << "The length of the longest substring without repeating characters is " << answer.first << '\n';
    cout << "The number of unique characters in that substring is " << answer.second << '\n';
    return 0;
}

