    // Validate array conversion
    if (grid == NULL || arrival == NULL || mask == NULL || latitude == NULL || longitude == NULL || elevation == NULL) {
        return NULL;  // Return error if any array conversion failed
    }

    // Extract raw data pointers from arrays
    float *GRID_VALUES = (float *)PyArray_DATA(grid);
    float *ARRIVAL_TIMES = (float *)PyArray_DATA(arrival);
    bool *VALID_POINTS = (bool *)PyArray_DATA(mask);
    double *LAT_COORDS = (double *)PyArray_DATA(latitude);
    double *LON_COORDS = (double *)PyArray_DATA(longitude);
    double *ALTITUDES = (double *)PyArray_DATA(elevation);

    // Execute the underlying FMM computation
    _FMM(GRID_VALUES, ARRIVAL_TIMES, VALID_POINTS, LAT_COORDS, LON_COORDS, ALTITUDES, pointCount);

    // Clean up reference counts for numpy arrays
    Py_DECREF(grid);
    Py_DECREF(arrival);
    Py_DECREF(mask);
    Py_DECREF(latitude);
    Py_DECREF(longitude);
    Py_DECREF(elevation);

    Py_RETURN_NONE;  // Return None to Python
}

