// Find the maximum sum of a contiguous subarray
void maxSubArraySum(const vector<int>& inputArray) {
    int bestSum = INT_MIN, currentSum = 0;
    int leftIndex = 0, bestLeft = 0, bestRight = 0;
    bool allNegative = true;
    int largestNegative = INT_MIN;

    for (int right = 0; right < inputArray.size(); ++right) {
        currentSum += inputArray[right];

        if (allNegative && inputArray[right] > largestNegative) {
            largestNegative = inputArray[right];
        }

        if (currentSum > bestSum) {
            bestSum = currentSum;
            bestLeft = leftIndex;
            bestRight = right;
            allNegative = false;
        }

        if (currentSum < 0) {
            currentSum = 0;
            leftIndex = right + 1;
        }
    }

    if (allNegative) {
        cout << "All numbers are negative, the maximum element is: " << largestNegative << endl;
        return;
    }

    cout << "The maximum subarray sum is: " << bestSum << endl;
    cout << "The starting index of the subarray is: " << bestLeft << endl;
    cout << "The ending index of the subarray is: " << bestRight << endl;
}

int main() {
    vector<int> data = {-2, -3, 4, -1, -2, 1, 5, -3}; // Test data
    maxSubArraySum(data);
    return 0;
}

