const unsigned int k_limit = 40000;
const unsigned int size = 10000;

int main() {
    // Initialize data arrays
    vector<double> input1(size, 0.0);
    vector<double> input2(size, 0.0);
    vector<double> coefficients1(k_limit, 0.0);
    vector<double> coefficients2(k_limit, 0.0);

    // Precompute trigonometric values
    vector<double> cos_values(size-1);
    vector<double> sin_values(size-1);

    auto begin_time = high_resolution_clock::now();

    for (unsigned int k_index = 1; k_index <= k_limit; ++k_index) {
        for (unsigned int j_index = 1; j_index < size; ++j_index) {
            cos_values[j_index-1] = cos((k_index) * input1[j_index-1]) - cos((k_index) * input1[j_index]);
            sin_values[j_index-1] = sin((k_index) * input1[j_index-1]) - sin((k_index) * input1[j_index]);
        }
        for (unsigned int j_index = 1; j_index < size; ++j_index) {
            coefficients1[k_index-1] += input2[j_index-1] * cos_values[j_index-1];
            coefficients2[k_index-1] += input2[j_index-1] * sin_values[j_index-1];
        }
    }

    auto end_time = high_resolution_clock::now();
    auto elapsed_time = duration_cast<milliseconds>(end_time - begin_time);

    cout << "Execution time: " << elapsed_time.count() << " milliseconds" << endl;

    return 0;
}

