        cout << "Please enter a positive integer." << endl;
        return;
    }

    cout << "Fibonacci Series up to " << count << " numbers:" << endl;

    for (int index = 1; index <= count; ++index) {
        if (index == 1) {
            cout << prev << ", ";
            continue;
        }
        if (index == 2) {
            cout << curr << ", ";
            continue;
        }
        nextTerm = prev + curr;
        prev = curr;
        curr = nextTerm;
        cout << nextTerm;
        if (index < count) cout << ", ";
    }
    cout << endl;
}

