// Custom 128-bit unsigned integer type
class uint128_t {
private:
    unsigned long long upper;
    unsigned long long lower;

public:
    // Default constructor
    uint128_t() : upper(0), lower(0) {}

    // Constructor from 64-bit value
    uint128_t(unsigned long long lower_val) : upper(0), lower(lower_val) {}

    // Constructor with both high and low parts
    uint128_t(unsigned long long upper_val, unsigned long long lower_val) 
        : upper(upper_val), lower(lower_val) {}

    // Overloaded addition operator
    uint128_t operator+(const uint128_t& rhs) const {
        unsigned long long sum_lower = lower + rhs.lower;
        unsigned long long carry = (sum_lower < lower) ? 1ULL : 0ULL;
        unsigned long long sum_upper = upper + rhs.upper + carry;
        return uint128_t(sum_upper, sum_lower);
    }

    // Overloaded subtraction operator
    uint128_t operator-(const uint128_t& rhs) const {
        unsigned long long diff_lower = lower - rhs.lower;
        unsigned long long borrow = (diff_lower > lower) ? 1ULL : 0ULL;
        unsigned long long diff_upper = upper - rhs.upper - borrow;
        return uint128_t(diff_upper, diff_lower);
    }

    // Overloaded multiplication operator
    uint128_t operator*(const uint128_t& rhs) const {
        unsigned long long a_high = upper;
        unsigned long long a_low  = lower;
        unsigned long long b_high = rhs.upper;
        unsigned long long b_low  = rhs.lower;

        // Compute partial products
        unsigned long long p_ac = a_high * b_high;
        unsigned long long p_bd = a_low  * b_low;
        unsigned long long p_ad_bc = a_high * b_low + a_low * b_high;

        // Extract high and low parts of middle term
        unsigned long long mid_high = p_ad_bc >> 64;
        unsigned long long mid_low  = p_ad_bc & 0xFFFFFFFFFFFFFFFFULL;

        // Combine to get final result
        unsigned long long result_low = p_bd + mid_low;
        unsigned long long overflow   = (result_low < p_bd) ? 1ULL : 0ULL;
        unsigned long long result_high = p_ac + mid_high + overflow;

        return uint128_t(result_high, result_low);
    }

    // Overloaded division operator (placeholder implementation)
    uint128_t operator/(const uint128_t& divisor) const {
        // Placeholder: returns zero for simplicity
        return uint128_t();
    }

    // Equality comparison
    bool operator==(const uint128_t& rhs) const {
        return (upper == rhs.upper) && (lower == rhs.lower);
    }

    // Inequality comparison
    bool operator!=(const uint128_t& rhs) const {
        return !(*this == rhs);
    }

    // Less-than comparison
    bool operator<(const uint128_t& rhs) const {
        if (upper != rhs.upper) {
            return upper < rhs.upper;
        }
        return lower < rhs.lower;
    }

    // Greater-than comparison
    bool operator>(const uint128_t& rhs) const {
        return rhs < *this;
    }

    // Less-than-or-equal-to comparison
    bool operator<=(const uint128_t& rhs) const {
        return !(*this > rhs);
    }

    // Greater-than-or-equal-to comparison
    bool operator>=(const uint128_t& rhs) const {
        return !(*this < rhs);
    }

    // Convert to hexadecimal string representation
    std::string to_string() const {
        std::stringstream stream;
        stream << "0x" << std::hex << upper << std::hex << lower;
        return stream.str();
    }
};

#include <stdint.h>

// Function to compute the base-2 logarithm of an integer
static inline int logBase2(int value) {
#if defined(__x86_64__) || defined(__i386__)
    // x86 and x86_64 architecture
    int result;
    asm ( "bsr %1, %0\n"
          : "=r"(result)
          : "r" (value)
          : "cc"
    );
    return result;
#elif defined(__arm__) || defined(__aarch64__)
    // ARM and AArch64 architecture
    if (value == 0) return -1; // Handle the case where value is 0
    int result;
    asm ( "clz %0, %1\n"
          : "=r"(result)
          : "r" (value)
    );
    return 31 - result;
#else
    // Fallback to a portable C++ implementation
    if (value == 0) return -1; // Handle the case where value is 0
    int exponent = 0;
    while ((value >> exponent) > 1) {
        exponent++;
    }
    return exponent;
#endif
}

