// Function to process a bitmap image and extract pixel data
int ImageProcessor::ProcessBitmap(HBITMAP hImage) {
    // Obtain the desktop device context for compatibility
    HDC screenDC = GetDC(NULL);
    HDC tempDC = CreateCompatibleDC(screenDC);

    // Attach the provided bitmap to the temporary device context
    HBITMAP previousBitmap = (HBITMAP)SelectObject(tempDC, hImage);

    // Retrieve metadata about the bitmap
    BITMAP bmpDetails;
    GetObject(hImage, sizeof(BITMAP), &bmpDetails);

    // Access raw pixel information
    unsigned char* pixelBuffer = (unsigned char*)bmpDetails.bmBits;

    // Fallback: if direct access fails, use DIB functions
    if (pixelBuffer == nullptr) {
        BITMAPINFO info;
        ZeroMemory(&info, sizeof(BITMAPINFO));
        info.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
        info.bmiHeader.biWidth = bmpDetails.bmWidth;
        info.bmiHeader.biHeight = bmpDetails.bmHeight;
        info.bmiHeader.biPlanes = 1;
        info.bmiHeader.biBitCount = bmpDetails.bmBitsPixel;
        info.bmiHeader.biCompression = BI_RGB;

        size_t bufferSize = static_cast<size_t>(bmpDetails.bmWidth) * bmpDetails.bmHeight * (bmpDetails.bmBitsPixel / 8);
        pixelBuffer = new unsigned char[bufferSize];
        GetDIBits(tempDC, hImage, 0, bmpDetails.bmHeight, pixelBuffer, &info, DIB_RGB_COLORS);
    }

    // Perform operations on pixelBuffer (e.g., analysis or transformation)
    // Example: display first RGB values
    // printf("Sample pixel: %02X %02X %02X\n", pixelBuffer[0], pixelBuffer[1], pixelBuffer[2]);

    // Cleanup allocated resources
    if (pixelBuffer != (unsigned char*)bmpDetails.bmBits) {
        delete[] pixelBuffer;
    }
    SelectObject(tempDC, previousBitmap);
    DeleteDC(tempDC);
    ReleaseDC(NULL, screenDC);

    return 0;
}

