// Initialize JNI environment and create Java object
void initializeAndCreateActivity(JavaVM* vm, JNIEnv*& env) {
    JavaVMAttachArgs attachArgs = { JNI_VERSION_1_6, NULL, NULL };
    jboolean attachedFlag;

    // Check if current thread is attached to JVM
    vm->GetEnv((void**)&env, JNI_VERSION_1_6);
    if (env == NULL) {
        vm->AttachCurrentThread(&env, &attachArgs);
    }

    // Load the activity class
    jclass activityClass = env->FindClass("com/example/esActivity");
    if (activityClass == NULL) {
        qDebug() << "Failed to find activity class";
        return;
    }

    // Get constructor method ID
    jmethodID activityConstructor = env->GetMethodID(activityClass, "<init>", "()V");
    if (activityConstructor == NULL) {
        qDebug() << "Failed to find activity constructor";
        return;
    }

    // Create new instance of the activity
    jobject activityObject = env->NewObject(activityClass, activityConstructor);
    if (activityObject == NULL) {
        qDebug() << "Failed to create activity object";
        return;
    }

    // Get toast method ID
    jmethodID toastMethodID = env->GetMethodID(activityClass, "toast", "(Ljava/lang/String;)V");
    if (toastMethodID == NULL) {
        qDebug() << "Failed to find toast method";
        return;
    }

    // Create message string
    jstring toastMessage = env->NewStringUTF("This comes from jni.");
    if (toastMessage == NULL) {
        qDebug() << "Failed to create message string";
        return;
    }

    // Call the toast method on the activity object
    env->CallVoidMethod(activityObject, toastMethodID, toastMessage);
}

