    int versionNum;
    int qualityLevel;
};

struct ProductItem {
    string productName;
    long recordCount;
    long groupSize;
    vector<PriceRecord> priceHistory;
    float alertThreshold;
    int isFavorite;
};

vector<ProductItem> ProductList;

void LoadProducts() {
    int idx = 0;
    int innerIdx = 0;
    char buffer[64] = {0};
    for (idx = 0; idx < 4; idx++) {
        ProductItem newItem;
        snprintf(buffer, sizeof(buffer), "Product %d", idx);
        newItem.productName = buffer;
        newItem.alertThreshold = 2.5f;
        newItem.groupSize = 10;
        newItem.isFavorite = 0;

        for (innerIdx = 0; innerIdx < 4; innerIdx++) {
            PriceRecord rec;
            rec.unitPrice = innerIdx * 1.5f;
            rec.versionNum = innerIdx + 2;
            rec.qualityLevel = innerIdx - 2;
            snprintf(buffer, sizeof(buffer), "Entry #%d", innerIdx);
            rec.recordDate = buffer;
            newItem.priceHistory.push_back(rec);
        }
        newItem.recordCount = newItem.priceHistory.size();
        ProductList.push_back(newItem);
    }
}

void EncodeRecords(const vector<PriceRecord>& records, vector<uint8_t>& dataBuffer) {
    for (const auto& record : records) {
        // Encode each field sequentially
        size_t currentSize = dataBuffer.size();
        memcpy(&dataBuffer[currentSize], &record.unitPrice, sizeof(record.unitPrice));
        dataBuffer.resize(currentSize + sizeof(record.unitPrice));

        size_t dateLength = record.recordDate.length();
        currentSize = dataBuffer.size();
        memcpy(&dataBuffer[currentSize], &dateLength, sizeof(dateLength));
        dataBuffer.resize(currentSize + sizeof(dateLength));

        currentSize = dataBuffer.size();
        memcpy(&dataBuffer[currentSize], record.recordDate.c_str(), dateLength);
        dataBuffer.resize(currentSize + dateLength);

        currentSize = dataBuffer.size();
        memcpy(&dataBuffer[currentSize], &record.versionNum, sizeof(record.versionNum));
        dataBuffer.resize(currentSize + sizeof(record.versionNum));

        currentSize = dataBuffer.size();
        memcpy(&dataBuffer[currentSize], &record.qualityLevel, sizeof(record.qualityLevel));
        dataBuffer.resize(currentSize + sizeof(record.qualityLevel));
    }
}

void DecodeRecords(const uint8_t* dataPtr, size_t totalSize, vector<PriceRecord>& outputRecords) {
    size_t offset = 0;
    while (offset < totalSize) {
        PriceRecord item;
        memcpy(&item.unitPrice, &dataPtr[offset], sizeof(item.unitPrice));
        offset += sizeof(item.unitPrice);

        size_t dateLen;
        memcpy(&dateLen, &dataPtr[offset], sizeof(dateLen));
        offset += sizeof(dateLen);

        item.recordDate.assign(reinterpret_cast<const char*>(&dataPtr[offset]), dateLen);
        offset += dateLen;

        memcpy(&item.versionNum, &dataPtr[offset], sizeof(item.versionNum));
        offset += sizeof(item.versionNum);

        memcpy(&item.qualityLevel, &dataPtr[offset], sizeof(item.qualityLevel));
        offset += sizeof(item.qualityLevel);

        outputRecords.push_back(item);
    }
}

