    }
    cout << "Database opened successfully" << endl;

    const char createTableSQL[] = "CREATE TABLE IF NOT EXISTS Products (ProductName TEXT, HistoryData BLOB, RecordCount NUMERIC, AlertValue NUMERIC, IsFav NUMERIC);";

    status = sqlite3_exec(dbHandle, createTableSQL, nullptr, nullptr, nullptr);
    if (status) {
        cerr << "Table creation failed: " << sqlite3_errmsg(dbHandle) << endl;
        return -1;
    }

    for (productIndex = 0; productIndex < ProductList.size(); productIndex++) {
        vector<uint8_t> blobBuffer;
        EncodeRecords(ProductList[productIndex].priceHistory, blobBuffer);

        char insertStmt[512] = {0};
        snprintf(insertStmt, sizeof(insertStmt),
            "INSERT INTO Products (ProductName, HistoryData, RecordCount, AlertValue, IsFav) VALUES('%s', ?, %d, %f, %d)",
            ProductList[productIndex].productName.c_str(),
            ProductList[productIndex].recordCount,
            ProductList[productIndex].alertThreshold,
            ProductList[productIndex].isFavorite);

        sqlite3_prepare_v2(dbHandle, insertStmt, -1, &preparedStatement, NULL);
        sqlite3_bind_blob(preparedStatement, 1, blobBuffer.data(), blobBuffer.size(), SQLITE_STATIC);

        status = sqlite3_step(preparedStatement);
        if (status != SQLITE_DONE) {
            cerr << "Execution error: " << sqlite3_errmsg(dbHandle) << endl;
        }

        sqlite3_finalize(preparedStatement);
    }

    sqlite3_close(dbHandle);
    return 0;
}

