#include <xmmintrin.h>

struct vec4 {
    float a, b, c, d;
};

void compute_vector(const vec4 &input, const vec4 &scale, float factor, vec4 &output) {
    __m128 in_vec = _mm_loadu_ps(&input.a);
    __m128 scale_vec = _mm_loadu_ps(&scale.a);
    __m128 factor_vec = _mm_set1_ps(factor);
    __m128 out_vec = _mm_loadu_ps(&output.a);

    // Compute component-wise products
    __m128 prod1 = _mm_mul_ps(in_vec, scale_vec);

    // Shuffle to access y and w components for second product
    __m128 shuffled_in = _mm_shuffle_ps(in_vec, in_vec, 0x55);   // y,y,y,y
    __m128 shuffled_scale = _mm_shuffle_ps(scale_vec, scale_vec, 0xAA); // w,w,w,w
    __m128 prod2 = _mm_mul_ps(shuffled_in, shuffled_scale);

    // Subtract the products: (x*a - y*b, y*b - z*c, etc.)
    __m128 diff = _mm_sub_ps(prod1, prod2);

    // Apply scaling factor
    diff = _mm_mul_ps(diff, factor_vec);

    // Update output vector: output -= diff
    out_vec = _mm_sub_ps(out_vec, diff);

    // Store back to memory
    _mm_storeu_ps(&output.a, out_vec);
}

#include <cstdint>
#include <iostream>

// Computes the high 64 bits of the 128-bit product of two 64-bit unsigned integers
uint64_t compute_upper_product(uint64_t a, uint64_t b) {
    uint32_t a_upper = static_cast<uint32_t>(a >> 32);
    uint32_t a_lower = static_cast<uint32_t>(a);
    uint32_t b_upper = static_cast<uint32_t>(b >> 32);
    uint32_t b_lower = static_cast<uint32_t>(b);

    uint64_t term1 = static_cast<uint64_t>(a_upper) * b_upper;
    uint64_t term2 = static_cast<uint64_t>(a_upper) * b_lower;
    uint64_t term3 = static_cast<uint64_t>(a_lower) * b_upper;
    uint64_t term4 = static_cast<uint64_t>(a_lower) * b_lower;

    uint64_t upper_component = term1 + (term2 + term3 + (term4 >> 32)) >> 32;

    return upper_component;
}

int main() {
    uint64_t a = 1234567890123456789ULL;
    uint64_t b = 9876543210987654321ULL;

    uint64_t result = compute_upper_product(a, b);
    std::cout << "Upper portion of the multiplication: " << result << std::endl;

    return 0;
}

