// Generates unique identifiers for component types
template <class TBase>
class ComponentTypeIdentifier
{
public:
    template <class TDerived>
    static std::size_t GenerateUniqueID()
    {
        static const std::size_t identifier = s_nextAvailableId++;
        return identifier;
    }

private:
    static std::size_t s_nextAvailableId;
};

template <class TBase>
std::size_t ComponentTypeIdentifier<TBase>::s_nextAvailableId = 100;

// Factory class for creating components from JSON data
class ComponentManager
{
public:
    // Register a component type with its factory
    template <class C>
    void AddComponentType()
    {
        std::size_t typeId = ComponentTypeIdentifier<C>::GenerateUniqueID<C>();
        m_componentCreators[typeId] = std::make_shared<ComponentCreator<C>>();
    }

    // Retrieve factory for a specific component type
    template <class C>
    std::shared_ptr<ComponentBase> GetComponentCreator()
    {
        std::size_t typeId = ComponentTypeIdentifier<C>::GenerateUniqueID<C>();
        return m_componentCreators[typeId];
    }

    // Create component instance from JSON representation
    std::unique_ptr<ComponentBase> InstantiateComponent(const std::string& typeName, const rapidjson::Value& jsonData)
    {
        std::size_t typeId = m_typeNameLookup.at(typeName);
        auto creator = m_componentCreators[typeId];
        auto instance = creator->BuildFromJson(jsonData);
        return instance;
    }

    // Map component name to its type ID
    template <class C>
    void AssignTypeName(const std::string& displayName)
    {
        std::size_t typeId = ComponentTypeIdentifier<C>::GenerateUniqueID<C>();
        m_typeNameLookup.emplace(displayName, typeId);
    }

private:
    std::unordered_map<std::size_t, std::shared_ptr<ComponentBase>> m_componentCreators;
    std::unordered_map<std::string, std::size_t> m_typeNameLookup;
};

