    ComponentManager entitySystem;
    entitySystem.AddComponentType<Position>();
    entitySystem.AddComponentType<Name>();
    entitySystem.AddComponentType<Size>();
    entitySystem.AddComponentType<Velocity>();
    entitySystem.AssignTypeName<Position>("Position");
    entitySystem.AssignTypeName<Name>("Name");
    entitySystem.AssignTypeName<Size>("Size");
    entitySystem.AssignTypeName<Velocity>("Velocity");

    for (auto& entity : configData.GetArray())
    {
