}

#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <algorithm>

enum class SignalType {
  AM,
  FM
};

struct RadioSignal {
  SignalType type;
  double signalPower;
  double centerFreq;
  double channelWidth;
};

class SpectrumAnalyzer {
public:
  SpectrumAnalyzer() = default;

  std::vector<double> create_spectrum(const double freq_start,
                                      const double freq_end,
                                      const double resolution,
                                      const double snr,
                                      const std::vector<RadioSignal> &signal_list) {

      int num_points = static_cast<int>((freq_end - freq_start) / resolution);
      std::vector<double> result(num_points, 0.0);

      for (const auto &sig : signal_list) {
          populate_signal_spectrum(sig, freq_start, resolution, result);
      }

      inject_noise(result, snr);

      for (auto &value : result) {
          value = 20.0 * std::log10(std::max(value, 1e-9));
      }

      return result;
  }

private:
  void populate_signal_spectrum(const RadioSignal &signal,
                                double base_freq,
                                double step_size,
                                std::vector<double> &spectrum) {

      switch (signal.type) {
          case SignalType::AM:
              compute_AM_spectrum(signal, base_freq, step_size, spectrum);
              break;
          case SignalType::FM:
              compute_FM_spectrum(signal, base_freq, step_size, spectrum);
              break;
          default:
              break;
      }
  }

  void compute_AM_spectrum(const RadioSignal &signal,
                           double base_freq,
                           double step_size,
                           std::vector<double> &spectrum) {

      // Assuming zero carrier frequency and double sideband signal
      int lower_idx = static_cast<int>((signal.centerFreq - signal.channelWidth) * 2 / step_size);
      int upper_idx = static_cast<int>((signal.centerFreq + signal.channelWidth) * 2 / step_size);

      for (int idx = lower_idx; idx <= upper_idx; ++idx) {
          spectrum[idx] += signal.signalPower / (1 + std::abs(idx - signal.centerFreq));
      }
  }

  void compute_FM_spectrum(const RadioSignal &signal,
                           double base_freq,
                           double step_size,
                           std::vector<double> &spectrum) {

      // Assuming narrowband approximation
      int lower_idx = static_cast<int>((signal.centerFreq - signal.channelWidth) * 2 / step_size);
      int upper_idx = static_cast<int>((signal.centerFreq + signal.channelWidth) * 2 / step_size);

      for (int idx = lower_idx; idx <= upper_idx; ++idx) {
          double bessel_factor = std::abs(std::cos(signal.centerFreq * M_PI / signal.channelWidth));
          spectrum[idx] += signal.signalPower * bessel_factor;
      }
  }

  void inject_noise(std::vector<double> &spectrum, const double snr) {
      std::random_device device;
      std::mt19937 engine(device());
      std::normal_distribution<double> distribution(0.0, 1.0);

      double noise_energy = 0.0;
      for (const auto &value : spectrum) {
          noise_energy += value * value;
      }
      noise_energy /= (spectrum.size() * snr);

      for (auto &value : spectrum) {
          value += std::sqrt(noise_energy) * distribution(engine);
      }
  }
};

int main() {
  SpectrumAnalyzer analyzer;
  std::vector<RadioSignal> signals = {
          {SignalType::AM, 1.0, 100.0, 10.0},
          {SignalType::FM, 2.0, 500.0, 20.0}
  };
  auto spectrum_data = analyzer.create_spectrum(0.0, 1000.0, 2.0, 10.0, signals);

  for (const auto &value : spectrum_data) {
      std::cout << value << std::endl;
  }

  return 0;
}

