// Definition for singly-linked list.
struct Node {
    int data;
    Node *link;
    Node(int x) : data(x), link(nullptr) {}
};

// Function to add two numbers represented by linked lists
Node* sumTwoLists(Node* first, Node* second) {
    Node *sentinel = new Node(0);
    Node *ptr1 = first, *ptr2 = second, *curr = sentinel;
    int overflow = 0;

    while (ptr1 != nullptr || ptr2 != nullptr) {
        int a = (ptr1 != nullptr) ? ptr1->data : 0;
        int b = (ptr2 != nullptr) ? ptr2->data : 0;
        int total = overflow + a + b;
        overflow = total / 10;
        curr->link = new Node(total % 10);
        curr = curr->link;

        if (ptr1 != nullptr) ptr1 = ptr1->link;
        if (ptr2 != nullptr) ptr2 = ptr2->link;
    }

    if (overflow > 0) {
        curr->link = new Node(overflow);
    }

    Node* output = sentinel->link;
    delete sentinel; // Free the sentinel node
    return output;
}

// Helper function to display the linked list
void showList(Node* head) {
    while (head != nullptr) {
        cout << head->data << " ";
        head = head->link;
    }
    cout << endl;
}

// Main function to test the sumTwoLists function
int main() {
    // Create the first linked list: 7 -> 0 -> 8 (represents number 807)
    Node* l1 = new Node(7);
    l1->link = new Node(0);
    l1->link->link = new Node(8);

    // Create the second linked list: 9 -> 4 -> 6 (represents number 649)
    Node* l2 = new Node(9);
    l2->link = new Node(4);
    l2->link->link = new Node(6);

    // Add the two numbers
    Node* result = sumTwoLists(l1, l2);

    // Display the result
    showList(result);

    // Clean up memory
    while (l1 != nullptr) {
        Node* temp = l1;
        l1 = l1->link;
        delete temp;
    }
    while (l2 != nullptr) {
        Node* temp = l2;
        l2 = l2->link;
        delete temp;
    }
    while (result != nullptr) {
        Node* temp = result;
        result = result->link;
        delete temp;
    }

    return 0;
}

