#include <tchar.h>

// Function to patch SetUnhandledExceptionFilter to return 0 (success) immediately
bool PatchSetUnhandledExceptionFilter()
{
    // Machine code for: XOR RAX, RAX; RETN
    const BYTE PatchCode[4] = { 0x48, 0x33, 0xC0, 0xC3 };

    // Get handle to kernel32.dll
    HMODULE hKernel32 = GetModuleHandle(_T("kernel32.dll"));
    if (hKernel32 == NULL)
        return false;

    // Locate the address of SetUnhandledExceptionFilter
    BYTE* pFunction = (BYTE*)GetProcAddress(hKernel32, "SetUnhandledExceptionFilter");
    if (pFunction == NULL)
        return false;

    // Apply the patch
    if (!ModifyMemory(pFunction, PatchCode, sizeof(PatchCode)))
        return false;

    // Ensure CPU instruction cache is invalidated
    FlushInstructionCache(GetCurrentProcess(), pFunction, sizeof(PatchCode));

    return true;
}

// Helper function to safely write to memory
static bool ModifyMemory(BYTE* pDestination, const BYTE* pSourceData, DWORD dwLength)
{
    // Validate inputs
    if (pDestination == NULL)
        return false;
    if (pSourceData == NULL)
        return false;
    if (dwLength == 0)
        return false;
    if (IsBadReadPtr(pSourceData, dwLength))
        return false;

    // Change memory protection to allow writing
    DWORD previousProtection = 0;
    if (!VirtualProtect(pDestination, dwLength, PAGE_EXECUTE_READWRITE, &previousProtection))
        return false;

    // Perform the actual memory copy
    memcpy(pDestination, pSourceData, dwLength);

    // Restore original memory protection
    DWORD dummy = 0;
    VirtualProtect(pDestination, dwLength, previousProtection, &dummy);

    return true;
}

