#include <iostream>

// Callback function to read data from file for upload
size_t data_provider(void *buffer, size_t block_size, size_t blocks, void *data) {
    FILE *input = (FILE *)data;
    if (input) {
        size_t bytes_read = fread(buffer, block_size, blocks, input);
        return bytes_read;
    }
    return 0;
}

int main() {
    CURL *handle;
    FILE *source_file;
    CURLcode result;

    curl_global_init(CURL_GLOBAL_ALL);
    handle = curl_easy_init();

    if (handle) {
        source_file = fopen("sample_data.bin", "rb");
        if (source_file) {
            curl_easy_setopt(handle, CURLOPT_URL, "https://example.com/api/upload");
            curl_easy_setopt(handle, CURLOPT_READFUNCTION, data_provider);
            curl_easy_setopt(handle, CURLOPT_READDATA, source_file);
            curl_easy_setopt(handle, CURLOPT_UPLOAD, 1L);

            // Configure resume upload with Content-Range header
            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Content-Range: bytes 0-9999/50000");
            curl_easy_setopt(handle, CURLOPT_HTTPHEADER, headers);

            result = curl_easy_perform(handle);

            if (result != CURLE_OK) {
                std::cerr << "Upload failed: " << curl_easy_strerror(result) << std::endl;
            }

            fclose(source_file);
            curl_slist_free_all(headers);
        }

        curl_easy_cleanup(handle);
    }

    curl_global_cleanup();
    return 0;
}

