struct Coordinate {
    double x, y;
};

// Function to calculate the Euclidean distance between two points
double computeDistance(const Coordinate &pt1, const Coordinate &pt2) {
    return std::sqrt(std::pow(pt1.x - pt2.x, 2) + std::pow(pt1.y - pt2.y, 2));
}

// Function to find the minimum distance between the closest pair of points in a strip
double checkStrip(std::vector<Coordinate> &buffer, double threshold) {
    double best = threshold;
    size_t count = buffer.size();
    for (size_t idx = 0; idx < count; ++idx) {
        for (size_t jdx = idx + 1; jdx < count && (buffer[jdx].y - buffer[idx].y) < best; ++jdx) {
            double current = computeDistance(buffer[idx], buffer[jdx]);
            if (current < best) {
                best = current;
            }
        }
    }
    return best;
}

// Function to find the closest pair of points using the divide-and-conquer approach
double findNearest(std::vector<Coordinate> &sortedX, std::vector<Coordinate> &sortedY) {
    size_t size = sortedX.size();
    if (size <= 3) {
        double smallest = std::numeric_limits<double>::max();
        for (size_t i = 0; i < size; ++i) {
            for (size_t j = i + 1; j < size; ++j) {
                double dist = computeDistance(sortedX[i], sortedX[j]);
                if (dist < smallest) {
                    smallest = dist;
                }
            }
        }
        return smallest;
    }

    size_t centerIndex = size / 2;
    Coordinate centerPoint = sortedX[centerIndex];

    std::vector<Coordinate> leftX(sortedX.begin(), sortedX.begin() + centerIndex);
    std::vector<Coordinate> rightX(sortedX.begin() + centerIndex, sortedX.end());

    std::vector<Coordinate> leftY, rightY;
    for (const auto &pt : sortedY) {
        if (pt.x <= centerPoint.x) {
            leftY.push_back(pt);
        } else {
            rightY.push_back(pt);
        }
    }

    double distLeft = findNearest(leftX, leftY);
    double distRight = findNearest(rightX, rightY);
    double minDist = std::min(distLeft, distRight);

    std::vector<Coordinate> middleBuffer;
    for (const auto &pt : sortedY) {
        if (std::abs(pt.x - centerPoint.x) < minDist) {
            middleBuffer.push_back(pt);
        }
    }

    return std::min(minDist, checkStrip(middleBuffer, minDist));
}

// Function to sort points by x and y coordinates
void organizePoints(std::vector<Coordinate> &coords) {
    std::vector<Coordinate> byX = coords;
    std::vector<Coordinate> byY = coords;
    std::sort(byX.begin(), byX.end(), [](const Coordinate &a, const Coordinate &b) {
        return a.x < b.x;
    });
    std::sort(byY.begin(), byY.end(), [](const Coordinate &a, const Coordinate &b) {
        return a.y < b.y;
    });

    double result = findNearest(byX, byY);
    std::cout << "The shortest distance is: " << result << std::endl;
}

int main() {
    std::vector<Coordinate> locations = {
        {2, 3}, {12, 30}, {40, 50}, {5, 1}, {12, 10}, {3, 4}
    };

    organizePoints(locations);

    return 0;
}

#include <iostream>
#include <vector>

// Perform bubble sort on the input vector
void bubbleSort(std::vector<int> &data) {
  bool hasSwapped;
  int length = data.size();
  for (int pass = 0; pass < length - 1; pass++) {
    hasSwapped = false;
    for (int index = 0; index < length - pass - 1; index++) {
      if (data[index] > data[index + 1]) {
        std::swap(data[index], data[index + 1]);
        hasSwapped = true;
      }
    }
    if (!hasSwapped) break;
  }
}

