using namespace Microsoft::WRL;
using namespace D2D1;

class GraphicsControl : public HwndHost
{
public:
    GraphicsControl() : m_windowHandle(NULL), m_d2dFactory(NULL), m_renderTarget(NULL) {}

    ~GraphicsControl()
    {
        if (m_renderTarget) m_renderTarget->Release();
        if (m_d2dFactory) m_d2dFactory->Release();
    }

    // Create the Win32 window
    HWND CreateNativeWindow(HWND parent, HINSTANCE hInstance)
    {
        WNDCLASS wc = {0};
        wc.lpfnWndProc = DefWindowProc;
        wc.hInstance = hInstance;
        wc.lpszClassName = L"GraphicsControlClass";
        RegisterClass(&wc);

        return CreateWindow(L"GraphicsControlClass", L"GraphicsControl", WS_CHILD | WS_VISIBLE, 0, 0, 0, 0, parent, NULL, hInstance, NULL);
    }

    // Build the window
    HRESULT BuildWindowCore(HWND hwndParent)
    {
        m_windowHandle = CreateNativeWindow(hwndParent, GetModuleHandle(NULL));

        // Initialize Direct2D
        D2D1_FACTORY_OPTIONS factoryOptions = {};
#if defined(_DEBUG)
        factoryOptions.debugLevel = D2D1_DEBUG_LEVEL_INFORMATION;
#endif
        D2D1CreateFactory(D2D1_FACTORY_TYPE_SINGLE_THREADED, factoryOptions, &m_d2dFactory);

        return S_OK;
    }

    // Destroy the window
    void DestroyWindowCore()
    {
        if (m_windowHandle)
        {
            DestroyWindow(m_windowHandle);
            m_windowHandle = NULL;
        }
    }

    // Get the handle of the hosted window
    HWND GetHandle() const
    {
        return m_windowHandle;
    }

    // Create the render target
    void CreateRenderTarget()
    {
        if (m_windowHandle && m_d2dFactory)
        {
            RECT clientRect;
            GetClientRect(m_windowHandle, &clientRect);

            D2D1_SIZE_U dimensions = D2D1::SizeU(clientRect.right - clientRect.left, clientRect.bottom - clientRect.top);

            m_d2dFactory->CreateHwndRenderTarget(
                D2D1::RenderTargetProperties(),
                D2D1::HwndRenderTargetProperties(m_windowHandle, dimensions),
                &m_renderTarget);
        }
    }

    // Render
    void Draw()
    {
        if (m_renderTarget)
        {
            m_renderTarget->BeginDraw();

            m_renderTarget->Clear(D2D1::ColorF(D2D1::ColorF::SkyBlue));

            D2D1_RECT_F rectangle = D2D1::RectF(0, 0, 100, 100);
            ComPtr<ID2D1SolidColorBrush> brush;
            m_renderTarget->CreateSolidColorBrush(D2D1::ColorF(D2D1::ColorF::Red), &brush);
            m_renderTarget->FillRectangle(rectangle, brush.Get());

            m_renderTarget->EndDraw();
        }
    }

    // Handle window messages
    LRESULT WindowProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam)
    {
        switch (msg)
        {
        case WM_PAINT:
            Draw();
            ValidateRect(m_windowHandle, NULL);
            return 0;
        case WM_SIZE:
            if (m_renderTarget)
            {
                RECT clientRect;
                GetClientRect(m_windowHandle, &clientRect);
                D2D1_SIZE_U dimensions = D2D1::SizeU(clientRect.right - clientRect.left, clientRect.bottom - clientRect.top);
                m_renderTarget->Resize(dimensions);
            }
            return 0;
        case WM_DESTROY:
            PostQuitMessage(0);
            return 0;
        }
        return DefWindowProc(hwnd, msg, wParam, lParam);
    }

private:
    HWND m_windowHandle;
    ComPtr<ID2D1Factory> m_d2dFactory;
    ComPtr<ID2D1HwndRenderTarget> m_renderTarget;
};

