std::vector<uint8_t> applyXorCipher(const std::vector<uint8_t>& inputBytes, const std::string& key) {
    std::vector<uint8_t> result = inputBytes;
    for (size_t index = 0; index < inputBytes.size(); ++index) {
        result[index] ^= key[index % key.length()];
    }
    return result;
}

std::vector<uint8_t> revertXorCipher(const std::vector<uint8_t>& encryptedBytes, const std::string& key) {
    return applyXorCipher(encryptedBytes, key); // XOR operation is its own inverse
}

void encryptFileData(const std::string& sourcePath, const std::string& targetPath, const std::string& secretKey) {
    std::ifstream sourceFile(sourcePath, std::ios::binary);
    std::ofstream targetFile(targetPath, std::ios::binary);

    if (!sourceFile.is_open() || !targetFile.is_open()) {
        std::cerr << "Failed to open file." << std::endl;
        return;
    }

    std::vector<uint8_t> chunk(2048);
    while (sourceFile.read(reinterpret_cast<char*>(chunk.data()), chunk.size())) {
        size_t actualRead = sourceFile.gcount();
        std::vector<uint8_t> processedChunk = applyXorCipher(chunk, secretKey);
        targetFile.write(reinterpret_cast<const char*>(processedChunk.data()), actualRead);
    }

    sourceFile.close();
    targetFile.close();
}

void decryptFileData(const std::string& sourcePath, const std::string& targetPath, const std::string& secretKey) {
    encryptFileData(sourcePath, targetPath, secretKey); // XOR decryption uses the same process
}

#include <iostream>
using namespace std;

// Structure definition for a linked list node
struct ListNode {
    int value;
    ListNode* link;
};

// Function to determine whether the linked list forms a cycle
bool hasCycle(ListNode* start) {
    if (start == NULL) {
        return false; // Empty list cannot be cyclic
    }

    ListNode* runner1 = start;
    ListNode* runner2 = start;

    while (runner2 != NULL && runner2->link != NULL) {
        runner1 = runner1->link;       // Advance first pointer by one node
        runner2 = runner2->link->link; // Advance second pointer by two nodes

        if (runner1 == runner2) {
            return true; // Cycle found
        }
    }

    return false; // No cycle detected
}

// Helper function to allocate and initialize a new node
ListNode* makeNode(int value) {
    ListNode* newNode = new ListNode();
    newNode->value = value;
    newNode->link = NULL;
    return newNode;
}

// Build a circular linked list for testing purposes
ListNode* buildCircularList() {
    ListNode* head = makeNode(10);
    ListNode* node2 = makeNode(20);
    ListNode* node3 = makeNode(30);
    ListNode* node4 = makeNode(40);

    head->link = node2;
    node2->link = node3;
    node3->link = node4;
    node4->link = head; // Complete the circle

    return head;
}

// Build a linear (non-circular) linked list for testing purposes
ListNode* buildLinearList() {
    ListNode* head = makeNode(10);
    ListNode* node2 = makeNode(20);
    ListNode* node3 = makeNode(30);
    ListNode* node4 = makeNode(40);

    head->link = node2;
    node2->link = node3;
    node3->link = node4;
    node4->link = NULL; // Terminate the list

    return head;
}

int main() {
    ListNode* circularStructure = buildCircularList();
    ListNode* linearStructure = buildLinearList();

    cout << "Is the circular structure cyclic? " << (hasCycle(circularStructure) ? "Yes" : "No") << endl;
    cout << "Is the linear structure cyclic? " << (hasCycle(linearStructure) ? "Yes" : "No") << endl;

    return 0;
}

