#include <iostream>
#include <vector>
#include <thread>
#include <algorithm>
#include <mutex>
#include <future>

std::mutex print_mtx; // Mutex for safe printing and other shared resources

void sort_array(std::vector<int>& data, int start, int end) {
    if (start < end) {
        int pivot_value = data[(start + end) / 2];
        int low = start, high = end;

        while (low <= high) {
            while (data[low] < pivot_value) low++;
            while (data[high] > pivot_value) high--;
            if (low <= high) {
                std::swap(data[low], data[high]);
                low++;
                high--;
            }
        }

        if (start < high) {
            sort_array(data, start, high);
        }
        if (low < end) {
            sort_array(data, low, end);
        }
    }
}

void parallel_sort(std::vector<int>& data, int start, int end, int cutoff) {
    if (end - start < cutoff) {
        sort_array(data, start, end);
    } else {
        int pivot_value = data[(start + end) / 2];
        int low = start, high = end;

        while (low <= high) {
            while (data[low] < pivot_value) low++;
            while (data[high] > pivot_value) high--;
            if (low <= high) {
                std::swap(data[low], data[high]);
                low++;
                high--;
            }
        }

        std::future<void> left_task;
        std::future<void> right_task;

        if (start < high) {
            left_task = std::async(std::launch::async, parallel_sort, std::ref(data), start, high, cutoff);
        }
        if (low < end) {
            right_task = std::async(std::launch::async, parallel_sort, std::ref(data), low, end, cutoff);
        }

        if (left_task.valid()) {
            left_task.get();
        }
        if (right_task.valid()) {
            right_task.get();
        }
    }
}

int main() {
    std::vector<int> numbers = {3, 6, 8, 10, 1, 2, 1};
    int cutoff_size = 10; // Threshold to switch to single-threaded quicksort

    std::cout << "Unsorted list: ";
    for (int val : numbers) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    parallel_sort(numbers, 0, numbers.size() - 1, cutoff_size);

    std::cout << "Sorted list: ";
    for (int val : numbers) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>
