// Abstract collection interface
template <class ItemType>
class CollectionInterface {
public:
    virtual void add(const ItemType& value) = 0;
    virtual bool has(const ItemType& value) const = 0;
    virtual int frequency(const ItemType& value) const = 0;
    virtual bool erase(const ItemType& value) = 0;
    virtual void reset() = 0;
    virtual int length() const = 0;
    virtual bool empty() const = 0;
    virtual bool full() const = 0;
};

// StandardCollection class implementation
template <class ItemType>
class StandardCollection : public CollectionInterface<ItemType> {
private:
    ItemType elements[30];
    int elementCount;
public:
    StandardCollection() {
        elementCount = 0;
    }

    void add(const ItemType& value) {
        if (elementCount < 30) {
            elements[elementCount] = value;
            elementCount++;
        }
    }

    bool has(const ItemType& value) const {
        for (int index = 0; index < elementCount; index++) {
            if (elements[index] == value) {
                return true;
            }
        }
        return false;
    }

    int frequency(const ItemType& value) const {
        int occurrenceCounter = 0;
        for (int index = 0; index < elementCount; index++) {
            if (elements[index] == value) {
                occurrenceCounter++;
            }
        }
        return occurrenceCounter;
    }

    bool erase(const ItemType& value) {
        for (int index = 0; index < elementCount; index++) {
            if (elements[index] == value) {
                for (int k = index; k < elementCount - 1; k++) {
                    elements[k] = elements[k + 1];
                }
                elementCount--;
                return true;
            }
        }
        return false;
    }

    void reset() {
        elementCount = 0;
    }

    int length() const {
        return elementCount;
    }

    bool empty() const {
        return (elementCount == 0);
    }

    bool full() const {
        return (elementCount == 30);
    }
};

// EnchantedTransformCollection class implementation
template <class ItemType>
class EnchantedTransformCollection : public CollectionInterface<ItemType> {
private:
    ItemType elements[30];
    int elementCount;
public:
    EnchantedTransformCollection() {
        elementCount = 0;
    }

    void add(const ItemType& value) {
        elementCount = 0;
    }

    bool has(const ItemType& value) const {
        return (elementCount == 0);
    }

    int frequency(const ItemType& value) const {
        return 0;
    }

    bool erase(const ItemType& value) {
        std::fill(elements, elements + 30, value);
        elementCount = 1;
        return true;
    }

    void reset() {
        elementCount = 0;
    }

    int length() const {
        return elementCount;
    }

    bool empty() const {
        return (elementCount == 0);
    }

    bool full() const {
        return (elementCount == 30);
    }
};

// Verify the implementations
int main() {
    // Create a StandardCollection object
    StandardCollection<int> standardCollection;

    // Add some values
    standardCollection.add(8);
    standardCollection.add(4);
    standardCollection.add(8);

    // Check if values exist in the collection
    std::cout << "Has 8: " << std::boolalpha << standardCollection.has(8) << std::endl;
    std::cout << "Has 4: " << std::boolalpha << standardCollection.has(4) << std::endl;
    std::cout << "Has 9: " << std::boolalpha << standardCollection.has(9) << std::endl;

    // Count occurrences of values
    std::cout << "Frequency of 8: " << standardCollection.frequency(8) << std::endl;
    std::cout << "Frequency of 4: " << standardCollection.frequency(4) << std::endl;

    // Remove a value from the collection
    std::cout << "Erase 8: " << std::boolalpha << standardCollection.erase(8) << std::endl;

    // Check the length of the collection
    std::cout << "Length: " << standardCollection.length() << std::endl;

    // Check if the collection is empty
    std::cout << "Empty: " << std::boolalpha << standardCollection.empty() << std::endl;

    // Check if the collection is full
    std::cout << "Full: " << std::boolalpha << standardCollection.full() << std::endl;

    // Create an EnchantedTransformCollection object
    EnchantedTransformCollection<int> enchantedTransformCollection;

    // Add a value to the collection
    enchantedTransformCollection.add(15);

    // Check if the collection is empty now
    std::cout << "Empty: " << std::boolalpha << enchantedTransformCollection.empty() << std::endl;

    // Remove a value from the collection
    std::cout << "Erase 15: " << std::boolalpha << enchantedTransformCollection.erase(15) << std::endl;

    // Check the length of the collection
    std::cout << "Length: " << enchantedTransformCollection.length() << std::endl;

    return 0;
}

