#include <array>

class TicTacToeGame {
public:
    TicTacToeGame() : grid({{'.', '.', '.'}, {'.', '.', '.'}, {'.', '.', '.'}}), activePlayer('O') {}

    void displayGrid() const {
        for (const auto& line : grid) {
            for (char spot : line) {
                std::cout << spot << " ";
            }
            std::cout << std::endl;
        }
    }

    bool placeMark(int r, int c) {
        if (r < 0 || r >= 3 || c < 0 || c >= 3 || grid[r][c] != '.') {
            return false; // Invalid position
        }
        grid[r][c] = activePlayer;
        switchTurn();
        return true;
    }

    char determineResult() const {
        // Check rows and columns
        for (int idx = 0; idx < 3; ++idx) {
            if (grid[idx][0] == grid[idx][1] && grid[idx][1] == grid[idx][2] && grid[idx][0] != '.') {
                return grid[idx][0];
            }
            if (grid[0][idx] == grid[1][idx] && grid[1][idx] == grid[2][idx] && grid[0][idx] != '.') {
                return grid[0][idx];
            }
        }

        // Check diagonals
        if (grid[0][0] == grid[1][1] && grid[1][1] == grid[2][2] && grid[0][0] != '.') {
            return grid[0][0];
        }
        if (grid[0][2] == grid[1][1] && grid[1][1] == grid[2][0] && grid[0][2] != '.') {
            return grid[0][2];
        }

        // Check for tie
        for (const auto& line : grid) {
            for (char field : line) {
                if (field == '.') {
                    return '.'; // Game still in progress
                }
            }
        }

        return 'T'; // Tie
    }

    char getActivePlayer() const {
        return activePlayer;
    }

private:
    std::array<std::array<char, 3>, 3> grid;
    char activePlayer;

    void switchTurn() {
        activePlayer = (activePlayer == 'X') ? 'O' : 'X';
    }
};

int main() {
    TicTacToeGame match;
    match.displayGrid();

    while (true) {
        int row, column;
        std::cout << "Player " << match.getActivePlayer() << ", enter your move (row and column): ";
        std::cin >> row >> column;

        if (match.placeMark(row, column)) {
            match.displayGrid();
            char result = match.determineResult();
            if (result == 'X' || result == 'O') {
                std::cout << "Player " << result << " wins!" << std::endl;
                break;
            } else if (result == 'T') {
                std::cout << "It's a tie!" << std::endl;
                break;
            }
        } else {
            std::cout << "Invalid move, try again." << std::endl;
        }
    }

    return 0;
}

