#include <iostream>
#include <memory>
#include <utility>

template <typename T>
class SmartPointer {
public:
    explicit SmartPointer(T* raw_ptr = nullptr) : data_ptr_(raw_ptr), count_ptr_(new std::size_t(1)) {
        if (raw_ptr == nullptr) {
            delete count_ptr_;
            count_ptr_ = nullptr;
        }
    }

    SmartPointer(const SmartPointer& other) : data_ptr_(other.data_ptr_), count_ptr_(other.count_ptr_) {
        if (count_ptr_) {
            (*count_ptr_)++;
        }
    }

    SmartPointer& operator=(const SmartPointer& other) {
        if (this != &other) {
            cleanup();
            data_ptr_ = other.data_ptr_;
            count_ptr_ = other.count_ptr_;
            if (count_ptr_) {
                (*count_ptr_)++;
            }
        }
        return *this;
    }

    ~SmartPointer() {
        cleanup();
    }

    T* access() const {
        return data_ptr_;
    }

    T& dereference() const {
        return *data_ptr_;
    }

    T* arrow_operator() const {
        return data_ptr_;
    }

    std::size_t reference_count() const {
        return count_ptr_ ? *count_ptr_ : 0;
    }

private:
    void cleanup() {
        if (count_ptr_ && --(*count_ptr_) == 0) {
            delete data_ptr_;
            delete count_ptr_;
        }
        data_ptr_ = nullptr;
        count_ptr_ = nullptr;
    }

    T* data_ptr_;
    std::size_t* count_ptr_;
};

int main() {
    SmartPointer<int> smart(new int(42));
    std::cout << smart.dereference() << " (" << smart.reference_count() << " references)" << std::endl;
    return 0;
}

