// Determine whether a given integer is a prime number
bool checkIfPrime(int value) {
    if (value <= 1) return false;
    if (value == 2) return true;
    if (value % 2 == 0) return false;
    for (int j = 3; j <= std::sqrt(value); j += 2) {
        if (value % j == 0) return false;
    }
    return true;
}

// Collect all prime numbers within the interval [A, B]
std::vector<int> collectPrimesInInterval(int A, int B) {
    std::vector<int> primeList;
    for (int candidate = A; candidate <= B; ++candidate) {
        if (checkIfPrime(candidate)) {
            primeList.push_back(candidate);
        }
    }
    return primeList;
}

int main() {
    int A, B;
    std::cout << "Input the range (A B): ";
    std::cin >> A >> B;

    std::vector<int> primes = collectPrimesInInterval(A, B);

    std::cout << "Prime values from " << A << " to " << B << " are: ";
    for (int p : primes) {
        std::cout << p << " ";
    }
    std::cout << std::endl;

    return 0;
}

