typedef unsigned long U32;

extern "C" __declspec(dllexport) int ReadFile(LPSTR Path, U32** DataPtr, U32* Count)
{
    FILE *fileHandle;
    U32 *buffer;
    CString tempStr(Path);
    long fileSize;

    if (!(fileHandle = fopen(tempStr, "rb"))) {
        return 0;
    }

    // Determine file size
    fseek(fileHandle, 0, SEEK_END);
    fileSize = ftell(fileHandle);
    rewind(fileHandle);

    // Verify fileSize is divisible by sizeof(U32)
    if (fileSize % sizeof(U32) != 0) {
        fclose(fileHandle);
        return -3; // File size is not a multiple of sizeof(U32)
    }

    // Allocate required memory
    buffer = (U32 *)malloc(fileSize);
    if (buffer == NULL) {
        fclose(fileHandle);
        return -1;
    }

    // Read file contents into the buffer
    *Count = fread(buffer, sizeof(U32), fileSize / sizeof(U32), fileHandle);
    if (*Count == 0) {
        fclose(fileHandle);
        free(buffer);
        return -2;
    }

    *DataPtr = buffer;
    fclose(fileHandle);
    return 1;
}

