    }

    // Setup CUDA texture and array
    texture<unsigned char, 2, cudaReadModeElementType> texRef;
    cudaChannelFormatDesc channelDesc = cudaCreateChannelDesc(8, 8, 8, 0, cudaChannelFormatKindUnsigned);
    cudaArray* cuArrayPtr = nullptr;

    cudaMallocArray(&cuArrayPtr, &channelDesc, imgWidth, imgHeight);
    cudaMemcpy2DToArray(cuArrayPtr, 0, 0, hostImageData, imgWidth * 3, imgWidth * 3, imgHeight, cudaMemcpyHostToDevice);
    cudaBindTextureToArray(texRef, cuArrayPtr, channelDesc);

    // Device output buffer
    unsigned char* deviceOutput;
    cudaMalloc(&deviceOutput, imgWidth * imgHeight * 3 * sizeof(unsigned char));

    // Kernel configuration
    dim3 threadsPerBlock(16, 16);
    dim3 numBlocks((imgWidth + threadsPerBlock.x - 1) / threadsPerBlock.x,
                   (imgHeight + threadsPerBlock.y - 1) / threadsPerBlock.y);

    // Launch kernel (kernel definition moved before main for completeness in real code)
    processImageKernel<<<numBlocks, threadsPerBlock>>>(deviceOutput, imgWidth, imgHeight);

    // Retrieve result to host
    unsigned char* resultBuffer = new unsigned char[imgWidth * imgHeight * 3];
    cudaMemcpy(resultBuffer, deviceOutput, imgWidth * imgHeight * 3 * sizeof(unsigned char), cudaMemcpyDeviceToHost);

    // Cleanup resources
    cudaFree(deviceOutput);
    cudaFreeArray(cuArrayPtr);
    cudaUnbindTexture(texRef);

    // Use resultBuffer as needed (e.g., save to file or further processing)
    delete[] resultBuffer;

