// Multiply two quaternions and return the resulting quaternion
std::array<double, 4> quaternion_product(const std::array<double, 4>& a, const std::array<double, 4>& b) {
    double wa = a[0], xa = a[1], ya = a[2], za = a[3];
    double wb = b[0], xb = b[1], yb = b[2], zb = b[3];

    double w = wa * wb - xa * xb - ya * yb - za * zb;
    double x = wa * xb + xa * wb + ya * zb - za * yb;
    double y = wa * yb - xa * zb + ya * wb + za * xb;
    double z = wa * zb + xa * yb - ya * xb + za * wb;

    return {w, x, y, z};
}

