void LaunchApplication(const std::string& appName)
{
    STARTUPINFO startupInfo;
    PROCESS_INFORMATION processInfo;

    ZeroMemory(&startupInfo, sizeof(startupInfo));
    startupInfo.cb = sizeof(startupInfo);
    ZeroMemory(&processInfo, sizeof(processInfo));

    if (!CreateProcessA(appName.c_str(), nullptr, nullptr, nullptr, FALSE, 0, nullptr, nullptr, &startupInfo, &processInfo))
    {
        std::cerr << "Error launching process: " << GetLastError() << std::endl;
    }
}

void WatchForApplication(const std::string& targetApp)
{
    while (true)
    {
        DWORD foundId = 0;
        HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);

        if (hSnap != INVALID_HANDLE_VALUE)
        {
            PROCESSENTRY32 entry;
            entry.dwSize = sizeof(PROCESSENTRY32);

            if (Process32First(hSnap, &entry))
            {
                do
                {
                    if (_stricmp(entry.szExeFile, targetApp.c_str()) == 0)
                    {
                        foundId = entry.th32ProcessID;
                        break;
                    }
                } while (Process32Next(hSnap, &entry));
            }

            CloseHandle(hSnap);
        }

        if (foundId == 0)
        {
            LaunchApplication(targetApp);
        }

        std::this_thread::sleep_for(std::chrono::seconds(5));
    }
}

int main()
{
    std::string applicationName = "YourExecutableName.exe";
    WatchForApplication(applicationName);
    return 0;
}

