using namespace std;

struct Location {
    int identifier;
    double posX, posY;
};

double euclideanDistance(Location &p1, Location &p2) {
    return sqrt(pow(p1.posX - p2.posX, 2) + pow(p1.posY - p2.posY, 2));
}

double tourCost(const vector<Location> &route, const vector<int> &order) {
    double sum = 0.0;
    for (size_t idx = 0; idx < order.size(); ++idx) {
        int current = order[idx];
        int next = order[(idx + 1) % order.size()];
        sum += euclideanDistance(route[current], route[next]);
    }
    return sum;
}

vector<vector<double>> buildDistanceTable(const vector<Location> &points) {
    int size = points.size();
    vector<vector<double>> matrix(size, vector<double>(size, 0.0));
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            matrix[i][j] = euclideanDistance(points[i], points[j]);
        }
    }
    return matrix;
}

vector<int> combine(const vector<int> &mom, const vector<int> &dad) {
    int length = mom.size();
    int left = rand() % length;
    int right = rand() % length;
    if (left > right) swap(left, right);

    vector<int> offspring(length, -1);
    for (int pos = left; pos <= right; ++pos) {
        offspring[pos] = mom[pos];
    }

    int index = 0;
    for (int gene = 0; gene < length; ++gene) {
        if (find(offspring.begin(), offspring.end(), dad[gene]) == offspring.end()) {
            while (offspring[index] != -1) index++;
            offspring[index] = dad[gene];
        }
    }
    return offspring;
}

void perturb(vector<int> &solution, double changeProbability) {
    for (int position = 0; position < solution.size(); ++position) {
        if (rand() / double(RAND_MAX) < changeProbability) {
            int swapIndex = rand() % solution.size();
            swap(solution[position], solution[swapIndex]);
        }
    }
}

vector<int> evolutionarySearch(const vector<Location> &destinations, int populationCount, double mutationChance, int iterationLimit) {
    int numPoints = destinations.size();
    vector<vector<int>> group(populationCount, vector<int>(numPoints));

    // Initialize population with random permutations
    for (int k = 0; k < populationCount; ++k) {
        for (int l = 0; l < numPoints; ++l) {
            group[k][l] = l;
        }
        random_shuffle(group[k].begin(), group[k].end());
    }

    vector<pair<double, vector<int>>> evaluatedGroup;

    for (int epoch = 0; epoch < iterationLimit; ++epoch) {
        evaluatedGroup.clear();
        for (const auto &member : group) {
            evaluatedGroup.emplace_back(tourCost(destinations, member), member);
        }
        sort(evaluatedGroup.begin(), evaluatedGroup.end());

        vector<vector<int>> nextGeneration;
        for (int rank = 0; rank < populationCount / 2; ++rank) {
            nextGeneration.push_back(evaluatedGroup[rank].second);
        }

        while (nextGeneration.size() < populationCount) {
            int parentA = rand() % nextGeneration.size();
            int parentB = rand() % nextGeneration.size();
            vector<int> progeny = combine(nextGeneration[parentA], nextGeneration[parentB]);
            perturb(progeny, mutationChance);
            nextGeneration.push_back(progeny);
        }

        group = nextGeneration;
    }

    return evaluatedGroup[0].second; // Return best solution found
}

int main() {
    vector<Location> locations = {{0, 0.0, 0.0}, {1, 1.0, 2.0}, {2, 3.0, 1.0}, {3, 5.0, 5.0}, {4, 6.0, 2.0}};
    int popSize = 100;
    double mutationRate = 0.01;
    int maxGenerations = 1000;

    vector<int> optimalRoute = evolutionarySearch(locations, popSize, mutationRate, maxGenerations);
    cout << "Optimal Route: ";
    for (int cityIndex : optimalRoute) {
        cout << locations[cityIndex].identifier << " ";
    }
    cout << "\nTotal Distance: " << tourCost(locations, optimalRoute) << endl;

    return 0;
}

