#include <iostream>
using namespace std;

// Structure representing a node in the binary search tree
struct TreeNode {
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;
};

// Creates and initializes a new tree node with the specified value
TreeNode* createNode(int value) {
    TreeNode* newNode = new TreeNode();
    newNode->value = value;
    newNode->leftChild = newNode->rightChild = nullptr;
    return newNode;
}

// Inserts a value into the BST, maintaining BST properties
TreeNode* addValue(TreeNode* currentRoot, int value) {
    if (currentRoot == nullptr) return createNode(value);
    if (value < currentRoot->value)
        currentRoot->leftChild = addValue(currentRoot->leftChild, value);
    else
        currentRoot->rightChild = addValue(currentRoot->rightChild, value);
    return currentRoot;
}

// Locates the inorder successor of a given node in the BST
TreeNode* getInorderSuccessor(TreeNode* currentRoot, TreeNode* targetNode) {
    TreeNode* nextLarger = nullptr;

    while (currentRoot != nullptr) {
        if (targetNode->value < currentRoot->value) {
            nextLarger = currentRoot;
            currentRoot = currentRoot->leftChild;
        } else if (targetNode->value > currentRoot->value) {
            currentRoot = currentRoot->rightChild;
        } else {
            break;
        }
    }

    if (currentRoot != nullptr && currentRoot->rightChild != nullptr) {
        TreeNode* temp = currentRoot->rightChild;
        while (temp->leftChild != nullptr) {
            temp = temp->leftChild;
        }
        nextLarger = temp;
    }

    return nextLarger;
}

// Locates the inorder predecessor of a given node in the BST
TreeNode* getInorderPredecessor(TreeNode* currentRoot, TreeNode* targetNode) {
    TreeNode* previousSmaller = nullptr;

    while (currentRoot != nullptr) {
        if (targetNode->value > currentRoot->value) {
            previousSmaller = currentRoot;
            currentRoot = currentRoot->rightChild;
        } else if (targetNode->value < currentRoot->value) {
            currentRoot = currentRoot->leftChild;
        } else {
            break;
        }
    }

    if (currentRoot != nullptr && currentRoot->leftChild != nullptr) {
        TreeNode* temp = currentRoot->leftChild;
        while (temp->rightChild != nullptr) {
            temp = temp->rightChild;
        }
        previousSmaller = temp;
    }

    return previousSmaller;
}

// Displays the inorder predecessor and successor for a given key
void displayPredecessorAndSuccessor(TreeNode* root, int searchKey) {
    TreeNode* currentNode = root;
    while (currentNode != nullptr && currentNode->value != searchKey) {
        if (searchKey < currentNode->value)
            currentNode = currentNode->leftChild;
        else
            currentNode = currentNode->rightChild;
    }

    if (currentNode == nullptr) {
        cout << "Node with key " << searchKey << " not found in the BST." << endl;
        return;
    }

    TreeNode* pred = getInorderPredecessor(root, currentNode);
    TreeNode* succ = getInorderSuccessor(root, currentNode);

    if (pred != nullptr)
        cout << "Inorder Predecessor of " << searchKey << " is " << pred->value << endl;
    else
        cout << "No inorder predecessor for " << searchKey << endl;

    if (succ != nullptr)
        cout << "Inorder Successor of " << searchKey << " is " << succ->value << endl;
    else
        cout << "No inorder successor for " << searchKey << endl;
}

