int main() {
    TreeNode* root = nullptr;
    root = addValue(root, 20);
    addValue(root, 8);
    addValue(root, 22);
    addValue(root, 4);
    addValue(root, 12);
    addValue(root, 10);
    addValue(root, 14);

    int target = 12;
    displayPredecessorAndSuccessor(root, target);

    return 0;
}

