            .reg .u64 %global_ptr;

            ld.param.u64 %global_ptr, [buffer_address];
            %thread_id = threadIdx.x + blockIdx.x * blockDim.x;
            ld.global.u32 %value, [%global_ptr + %thread_id*4];
            add.u32 %value, %value, 1;
            st.global.u32 [%global_ptr + %thread_id*4], %value;
            ret;
        }
    )PTX";
}

