    ~DataUnion() {
        if (textValue) {
            delete[] textValue;
        }
    }
};

struct ReportItem {
    int kind; // 0 for integer, 1 for string
    DataUnion value;
};

extern "C" __declspec(dllexport) void GenerateReport(int* itemCount, ReportItem** resultArray) {
    // Sample data collection
    std::vector<boost::variant<int, std::string>> sourceData = {
        789, "Test", 321, "Sample"
    };

    *itemCount = static_cast<int>(sourceData.size());
    *resultArray = new ReportItem[sourceData.size()];

    for (size_t index = 0; index < sourceData.size(); ++index) {
        if (sourceData[index].which() == 0) {
            (*resultArray)[index].kind = 0;
            (*resultArray)[index].value.numberValue = boost::get<int>(sourceData[index]);
        } else if (sourceData[index].which() == 1) {
            (*resultArray)[index].kind = 1;
            std::string tempStr = boost::get<std::string>(sourceData[index]);
            (*resultArray)[index].value.textValue = new char[tempStr.length() + 1];
            strcpy((*resultArray)[index].value.textValue, tempStr.c_str());
        }
    }
}

extern "C" __declspec(dllexport) void ReleaseReport(int count, ReportItem* items) {
    for (int i = 0; i < count; ++i) {
        if (items[i].kind == 1) {
            delete[] items[i].value.textValue;
        }
    }
    delete[] items;
}

