class ClampValueAssembler : public CodeStubAssembler {
 public:
  ClampValueAssembler(Zone* zone, Isolate* isolate)
      : CodeStubAssembler(zone, isolate, Code::STUB, kNoCallSiteDetails) {}

  Node* ClampValue(Node* input, Node* lower_bound, Node* upper_bound) {
    // Check if input is below the lower bound
    Node* input_below_lower = this->Int32LessThan(input, lower_bound);

    // If input is less than lower_bound, use lower_bound instead
    Node* adjusted_value = this->ChangeInt32ToInt32(
        this->SelectInt32(this->BooleanNot(input_below_lower), input, lower_bound));

    // Check if adjusted value exceeds the upper bound
    Node* adjusted_above_upper = this->Int32GreaterThan(adjusted_value, upper_bound);

    // If adjusted_value is greater than upper_bound, clamp to upper_bound
    Node* result_clamped = this->ChangeInt32ToInt32(
        this->SelectInt32(this->BooleanNot(adjusted_above_upper), adjusted_value, upper_bound));

    return result_clamped;
  }
};

