std::vector<std::string> findWholeNumbers(const std::string& text) {
    std::regex pattern("\\d+");
    std::sregex_iterator iter(text.begin(), text.end(), pattern);
    std::sregex_iterator end_iter;

    std::vector<std::string> results;
    for (; iter != end_iter; ++iter) {
        std::string token = iter->str();
        size_t pos = text.find(token);

        bool valid_start = (pos == 0) || 
                          (text[pos - 1] != '.' && text[pos - 1] != ',');

        bool valid_end = (pos + token.length() == text.length()) || 
                        (text[pos + token.length()] != '.' && text[pos + token.length()] != ',');

        if (valid_start && valid_end) {
            results.push_back(token);
        }
    }
    return results;
}

int main() {
    std::string input = "789.012abc345def67.89";
    std::vector<std::string> found_numbers = findWholeNumbers(input);

    for (const auto& number : found_numbers) {
        std::cout << number << std::endl;
    }

    return 0;
}

