// Constants
const int MAX_KSIZE = 31;

void CreateGaussianKernel1D(double* kernel, int size, double sigma) {
    int halfSize = size / 2;
    double total = 0.0;
    for (int pos = -halfSize; pos <= halfSize; pos++) {
        int offset = pos + halfSize;
        kernel[offset] = exp(-0.5 * pow(pos / sigma, 2)) / (sqrt(2 * CV_PI) * sigma);
        total += kernel[offset];
    }
    for (int idx = 0; idx < size; idx++) {
        kernel[idx] /= total;
    }
}

void ConvolveWithGaussian1D(const cv::Mat &input, cv::Mat &output, int kernelSize, double* kernel) {
    int padding = kernelSize / 2;

    for (int row = 0; row < input.rows; row++) {
        for (int col = 0; col < input.cols; col++) {
            double accumulator[3] = { 0.0 };
            for (int offset = -padding; offset <= padding; offset++) {
                int adjustedCol = col + offset;
                if (adjustedCol < 0) adjustedCol = -adjustedCol;
                if (adjustedCol >= input.cols) adjustedCol = input.cols - (adjustedCol - input.cols + 1);

                if (input.channels() == 3) {
                    cv::Vec3b pixel = input.at<cv::Vec3b>(row, adjustedCol);
                    double weight = kernel[offset + padding];
                    accumulator[0] += weight * pixel[0];
                    accumulator[1] += weight * pixel[1];
                    accumulator[2] += weight * pixel[2];
                } else {
                    accumulator[0] += kernel[offset + padding] * input.at<uchar>(row, adjustedCol);
                }
            }
            if (input.channels() == 3) {
                cv::Vec3b resultPixel = { static_cast<uchar>(accumulator[0]), 
                                          static_cast<uchar>(accumulator[1]), 
                                          static_cast<uchar>(accumulator[2]) };
                output.at<cv::Vec3b>(row, col) = resultPixel;
            } else {
                output.at<uchar>(row, col) = static_cast<uchar>(accumulator[0]);
            }
        }
    }
}

void ApplyGaussianBlur2(const cv::Mat &input, cv::Mat &result, int kernelSize, double sigma) {
    assert(input.channels() == 1 || input.channels() == 3);

    if (kernelSize > MAX_KSIZE) {
        std::cout << "Kernel size is too large! Please use a smaller value!" << std::endl;
        return;
    }

    clock_t start_time = clock();
    clock_t end_time = 0;

    double* gaussianKernel = new double[kernelSize];
    CreateGaussianKernel1D(gaussianKernel, kernelSize, sigma);

    cv::Mat intermediate;
    input.copyTo(intermediate);
    ConvolveWithGaussian1D(intermediate, result, kernelSize, gaussianKernel);
    intermediate.release();
    input.copyTo(intermediate);
    cv::transpose(result, intermediate);
    cv::transpose(input, result);
    ConvolveWithGaussian1D(intermediate, result, kernelSize, gaussianKernel);
    cv::transpose(result, intermediate);

    delete[] gaussianKernel;

    end_time = clock();
    std::cout << "Gaussian blur 2 execution time : " << end_time - start_time << std::endl;
}

