#include <OgreVector3.h>
#include <OgreEntity.h>

// Transform a vector from one entity's coordinate system to another
Ogre::Vector3 ConvertVectorSpace(const Ogre::Vector3& inputVector, 
                                  const Ogre::Entity* originEntity, 
                                  const Ogre::Entity* targetEntity) {
    // Validate input entities and determine transformation path

    Ogre::Vector3 resultVector = inputVector;

    // Apply source entity transformation if available
    if (originEntity) {
        Ogre::Matrix4 localToWorld = originEntity->getParentNode()->_getFullTransform();
        resultVector = localToWorld * resultVector;
    }

    // Apply destination entity inverse transformation if available
    if (targetEntity) {
        Ogre::Matrix4 worldToLocal = targetEntity->getParentNode()->_getFullTransform().inverse();
        resultVector = worldToLocal * resultVector;
    }

    return resultVector;
}

#include <immintrin.h>
#include <x86intrin.h>
#include <cstdint>
#include <cstddef>
#include <cstring>

// Determine if AVX-512 is available on the current system
bool has_avx512_support() {
    // Use CPUID to detect AVX-512 Foundation (AVX-512F) support
    return (std::get_cpuid(7).ebx & (1 << 16)) != 0;
}

// AVX-2 based bit counting using lookup table
uint64_t count_bits_AVX2(const uint8_t* buffer, const size_t len) {
    const __m256i lut = _mm256_setr_epi8(
        0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4,
        0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4
    );
    const __m256i mask_low = _mm256_set1_epi8(0x0f);
    __m256i global_sum = _mm256_setzero_si256();

    #define PROCESS_BLOCK { \
        const __m256i input = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(buffer + idx)); \
        const __m256i lower_nibbles = _mm256_and_si256(input, mask_low); \
        const __m256i upper_nibbles = _mm256_and_si256(_mm256_srli_epi16(input, 4), mask_low); \
        const __m256i cnt_lo = _mm256_shuffle_epi8(lut, lower_nibbles); \
        const __m256i cnt_hi = _mm256_shuffle_epi8(lut, upper_nibbles); \
        temp_reg = _mm256_add_epi8(temp_reg, cnt_lo); \
        temp_reg = _mm256_add_epi8(temp_reg, cnt_hi); \
        idx += 32; \
    }

    size_t idx = 0;
    while (idx + 8 * 32 <= len) {
        __m256i temp_reg = _mm256_setzero_si256();
        PROCESS_BLOCK PROCESS_BLOCK PROCESS_BLOCK PROCESS_BLOCK
        PROCESS_BLOCK PROCESS_BLOCK PROCESS_BLOCK PROCESS_BLOCK
        global_sum = _mm256_add_epi64(global_sum, _mm256_sad_epu8(temp_reg, _mm256_setzero_si256()));
    }

    __m256i temp_reg = _mm256_setzero_si256();
    while (idx + 32 <= len) {
        PROCESS_BLOCK;
    }

    global_sum = _mm256_add_epi64(global_sum, _mm256_sad_epu8(temp_reg, _mm256_setzero_si256()));

    #undef PROCESS_BLOCK

    uint64_t subtotal = 0;
    subtotal += static_cast<uint64_t>(_mm256_extract_epi64(global_sum, 0));
    subtotal += static_cast<uint64_t>(_mm256_extract_epi64(global_sum, 1));
    subtotal += static_cast<uint64_t>(_mm256_extract_epi64(global_sum, 2));
    subtotal += static_cast<uint64_t>(_mm256_extract_epi64(global_sum, 3));

    for (; idx < len; idx++) {
        subtotal += __builtin_popcount(buffer[idx]);
    }

    return subtotal;
}

// AVX-512 optimized bit counting implementation
uint64_t count_bits_AVX512(const uint8_t* buffer, const size_t length) {
    const size_t block_count = length / 64;
    const uint8_t* finish = buffer + length;

    __m512i running_total = _mm512_setzero_si512();
    for (size_t k = 0; k < block_count; k++, buffer += 64) {
        const __m512i chunk = _mm512_loadu_si512(reinterpret_cast<const __m512i*>(buffer));
        const __m512i bit_counts = _mm512_popcnt_epi64(chunk);
        running_total = _mm512_add_epi64(running_total, bit_counts);
    }

    uint64_t local_array[8] __attribute__((aligned(64)));
    _mm512_store_si512(reinterpret_cast<__m512i*>(local_array), running_total);

    uint64_t grand_total = 0;
    for (size_t k = 0; k < 8; k++) {
        grand_total += local_array[k];
    }

    while (buffer + 8 <= finish) {
        grand_total += _mm_popcnt_u64(*reinterpret_cast<const uint64_t*>(buffer));
        buffer += 8;
    }

    while (buffer < finish) {
        grand_total += __builtin_popcount(*buffer++);
    }

    return grand_total;
}

// Public interface to count set bits in a memory region
uint64_t count_bits(void* mem, size_t bytes) {
    if (has_avx512_support()) {
        return count_bits_AVX512(static_cast<const uint8_t*>(mem), bytes);
    } else {
        return count_bits_AVX2(static_cast<const uint8_t*>(mem), bytes);
    }
}

#include <iostream>
#include <vector>
#include <queue>
#include <limits>
#include <unordered_map>
#include <tuple>

using namespace std;

const int MAX_DIST = numeric_limits<int>::max();

// Comparator for the priority queue to implement min-heap behavior
struct DistanceComparator {
    bool operator()(const pair<int, int>& x, const pair<int, int>& y) {
        return x.second > y.second;
    }
};

// Dijkstra's shortest path algorithm implementation
vector<int> findShortestPath(const vector<vector<pair<int, int>>>& adjacencyList, int source, int destination) {
    int nodeCount = adjacencyList.size();
    vector<int> distance(nodeCount, MAX_DIST);  // Shortest known distance from source
    vector<int> predecessor(nodeCount, -1);     // Predecessor for path reconstruction
    priority_queue<pair<int, int>, vector<pair<int, int>>, DistanceComparator> pq;

    distance[source] = 0;
    pq.push({source, 0});

    while (!pq.empty()) {
        int currentNode = pq.top().first;
        int currentDistance = pq.top().second;
        pq.pop();

        if (currentDistance > distance[currentNode]) continue; // Skip outdated entries

        for (const auto& edge : adjacencyList[currentNode]) {
            int nextNode = edge.first;
            int edgeWeight = edge.second;

            if (distance[currentNode] + edgeWeight < distance[nextNode]) {
                distance[nextNode] = distance[currentNode] + edgeWeight;
                predecessor[nextNode] = currentNode;
                pq.push({nextNode, distance[nextNode]});
            }
        }
    }

    // Reconstruct the shortest path from destination to source
    vector<int> path;
    for (int current = destination; current != -1; current = predecessor[current]) {
        path.push_back(current);
    }
    reverse(path.begin(), path.end());

    return path;
}

int main() {
    // Example graph: adjacency list representation with 5 nodes (0-4)
    vector<vector<pair<int, int>>> cityGraph = {
        {{1, 10}, {2, 5}},   // Node 0 connections
        {{2, 2}, {3, 1}},    // Node 1 connections
        {{3, 4}},            // Node 2 connections
        {{4, 7}},            // Node 3 connections
        {}                   // Node 4 has no outgoing edges
    };

    int originNode = 0;
    int targetNode = 4;

    vector<int> optimalRoute = findShortestPath(cityGraph, originNode, targetNode);

    if (optimalRoute.empty()) {
        cout << "No route exists from node " << originNode << " to node " << targetNode << endl;
    } else {
        cout << "Optimal route from node " << originNode << " to node " << targetNode << ": ";
        for (int node : optimalRoute) {
            cout << node << " ";
        }
        cout << endl;
    }

    return 0;
}

