// Initialize CUDA streams and events for asynchronous execution
int main() {
    cudaStream_t s_a, s_b, s_c, s_d;
    cudaEvent_t ev_start, ev_end;

    // Create streams and events
    cudaStreamCreate(&s_a);
    cudaStreamCreate(&s_b);
    cudaStreamCreate(&s_c);
    cudaStreamCreate(&s_d);
    cudaEventCreate(&ev_start);
    cudaEventCreate(&ev_end);

    // Launch kernels on first pair of streams
    kernel1<<<gridDim, blockDim, 0, s_a>>>();
    kernel2<<<gridDim, blockDim, 0, s_b>>>();

    // Record completion events on respective streams
    cudaEventRecord(ev_start, s_a);
    cudaEventRecord(ev_end, s_b);

    // Configure final stream to wait for both events
    cudaStreamWaitEvent(s_d, ev_start, 0);
    cudaStreamWaitEvent(s_d, ev_end, 0);

    // Execute dependent kernel on synchronized stream
    kernel4<<<gridDim, blockDim, 0, s_d>>>();

    // Release all resources
    cudaEventDestroy(ev_start);
    cudaEventDestroy(ev_end);
    cudaStreamDestroy(s_a);
    cudaStreamDestroy(s_b);
    cudaStreamDestroy(s_c);
    cudaStreamDestroy(s_d);

    return 0;
}

