#include <cstdint>

// Atomically acquire a lock using exclusive access
static inline void acquireSpinlock(volatile unsigned int *spinlock_var) {
    unsigned int reg_val1 = 0;
    unsigned int reg_val2 = 0;

    __asm__ volatile(
        "acq_loop%=:                      \n\t" // "%=" generates unique label
        "LDREX %[rv1], [%[slk]]          \n\t" // exclusive read of lock variable
        "CMP %[rv1], #0                  \n\t" // test if lock is free (0)
        "ITT EQ                          \n\t" // conditional execution block
        "STREXEQ %[rv1], %[rv2], [%[slk]]\n\t" // try to store new value (0)
        "CMPEQ %[rv1], #0                \n\t" // check if store succeeded
        "BNE acq_loop%=                  \n\t" // retry if not successful
        "DMB                             \n\t" // memory barrier for subsequent operations
        : [slk] "+m"(*spinlock_var), [rv1] "=l"(reg_val1), [rv2] "=l"(reg_val2)
        : // no inputs
        : "memory");
}

#include <stdio.h>
#include <string.h>
#include <sys/mman.h>

// Allocate a block of memory with read, write, and execute permissions
void* create_executable_region(size_t bytes) {
    void *addr = mmap(
        nullptr,
        bytes,
        PROT_READ | PROT_WRITE | PROT_EXEC,
        MAP_PRIVATE | MAP_ANONYMOUS,
        -1,
        0
    );
    if (addr == reinterpret_cast<void*>(-1)) {
        perror("mmap failed");
        return nullptr;
    }
    return addr;
}

// Copy machine code into the allocated executable memory
void inject_bytes_into_region(size_t len, const unsigned char *src, void *dst) {
    memcpy(dst, src, len);
}

// Function pointer type for the generated code
typedef void (*NativeRoutine)();

int main() {
    // Machine code to print 'A' and exit
    unsigned char program[] = {
        0x48, 0xc7, 0xc0, 0x01, 0x00, 0x00, 0x00,  // mov rax, 1 (sys_write)
        0x48, 0xc7, 0xc7, 0x01, 0x00, 0x00, 0x00,  // mov rdi, 1 (stdout)
        0x48, 0xc7, 0xc6, 0x01, 0x00, 0x00, 0x00,  // mov rsi, message
        0x48, 0xc7, 0xc2, 0x01, 0x00, 0x00, 0x00,  // mov rdx, 1 (message length)
        0x0f, 0x05,                                // syscall
        0x48, 0xc7, 0xc0, 0x3c, 0x00, 0x00, 0x00,  // mov rax, 60 (sys_exit)
        0x48, 0x31, 0xff,                          // xor rdi, rdi (exit code 0)
        0x0f, 0x05                                 // syscall
    };

    void *exec_mem = create_executable_region(sizeof(program));
    if (exec_mem == nullptr) {
        return 1;
    }

    inject_bytes_into_region(sizeof(program), program, exec_mem);
    NativeRoutine entry_point = reinterpret_cast<NativeRoutine>(exec_mem);
    entry_point();

    return 0;
}

#include "ComponentManager.h"

// Transfer component data from one archetype to another
void ComponentManager::TransferComponentData(size_t typeId, Archetype* sourceArch, Archetype* destArch, size_t srcIndex, size_t dstIndex, size_t entityPos) {
    MoveComponentData(typeId, sourceArch, destArch, srcIndex, dstIndex, entityPos, destArch->entityIds.size());
}

// Swap component data within the same archetype
void ComponentManager::SwapComponentData(size_t typeId, Archetype* arch, size_t targetIndex, size_t entityPos) {
    const auto lastEntity = arch->entityIds.size() - 1;

    MoveComponentData(typeId, arch, arch, targetIndex, targetIndex, lastEntity, entityPos);
}

// Remove old component and allocate new space for moved component
void ComponentManager::RemoveAndAllocateComponentData(size_t typeId, Archetype* fromArch, Archetype* toArch, size_t srcIndex, size_t dstIndex, size_t entityPos) {
    const ComponentBase* compBase = GetComponentBase(typeId);
    const std::size_t compSize = compBase->GetSize();

    size_t currentCapacity = FindCurrentSize(typeId, toArch, dstIndex);

    const size_t lastEntity = fromArch->entityIds.size() - 1;

    compBase->MoveData(&fromArch->componentData[srcIndex][entityPos * compSize],
        &toArch->componentData[dstIndex][currentCapacity]);

    if (entityPos != lastEntity) {
        compBase->MoveData(&fromArch->componentData[srcIndex][lastEntity * compSize],
            &fromArch->componentData[srcIndex][entityPos * compSize]);
    }

    compBase->DestroyData(&fromArch->componentData[srcIndex][lastEntity * compSize]);
}

// Determine current size and reallocate if necessary
size_t ComponentManager::FindCurrentSize(size_t typeId, Archetype* arch, size_t slot) {
    const ComponentBase* base = GetComponentBase(typeId);
    const std::size_t& itemSize = base->GetSize();

    std::size_t currentCapacity = arch->entityIds.size() * itemSize;
    std::size_t requiredCapacity = currentCapacity + itemSize;

    if (requiredCapacity > arch->componentDataSize[slot]) {
        Reallocate(typeId, itemSize, arch, slot);
    }

    return currentCapacity;
}

// Double the buffer size and copy existing data
void ComponentManager::Reallocate(size_t typeId, const size_t newItemSize, Archetype* arch, size_t slot) {
    const ComponentBase* compBase = GetComponentBase(typeId);
    const std::size_t compSize = compBase->GetSize();

    arch->componentDataSize[slot] *= 2;
    arch->componentDataSize[slot] += newItemSize;

    unsigned char* newBuffer = new unsigned char[arch->componentDataSize[slot]];

    for (auto i = 0; i < arch->entityIds.size(); ++i) {
        compBase->MoveData(&arch->componentData[slot][i * newItemSize],
            &newBuffer[i * newItemSize]);
        compBase->DestroyData(&arch->componentData[slot][i * newItemSize]);
    }

    delete[] arch->componentData[slot];
    arch->componentData[slot] = newBuffer;
}

// Move component data between locations and destroy source
void ComponentManager::MoveComponentData(size_t typeId, Archetype* fromArch, Archetype* toArch, size_t srcIndex, size_t dstIndex, size_t srcEntity, size_t dstEntity) {
    const ComponentBase* compBase = GetComponentBase(typeId);
    const std::size_t compSize = compBase->GetSize();

    compBase->MoveData(&fromArch->componentData[srcIndex][srcEntity * compSize],
        &toArch->componentData[dstIndex][dstEntity * compSize]);

    compBase->DestroyData(&fromArch->componentData[srcIndex][srcEntity * compSize]);
}

