using namespace std;

// Determine operator precedence level
int getPrecedence(char oper) {
    if (oper == '+' || oper == '-') return 1;
    if (oper == '*' || oper == '/') return 2;
    return 0;
}

// Transform infix notation to postfix notation
string convertToPostfix(string inputExpr) {
    stack<char> operatorStack;
    string result = "";

    for (char currentChar : inputExpr) {
        if (isalnum(currentChar)) {
            // Append operand directly to result
            result += currentChar;
        } else if (currentChar == '(') {
            // Push opening parenthesis onto stack
            operatorStack.push(currentChar);
        } else if (currentChar == ')') {
            // Pop operators until matching opening parenthesis
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                result += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.pop(); // Remove the opening parenthesis
        } else {
            // Handle operators based on precedence
            while (!operatorStack.empty() && getPrecedence(operatorStack.top()) >= getPrecedence(currentChar)) {
                result += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(currentChar);
        }
    }

    // Append any remaining operators in the stack
    while (!operatorStack.empty()) {
        result += operatorStack.top();
        operatorStack.pop();
    }

    return result;
}

int main() {
    string expression;
    cout << "Enter an infix expression: ";
    cin >> expression;

    string output = convertToPostfix(expression);
    cout << "Postfix expression: " << output << endl;

    return 0;
}

