using namespace std;

// Count all palindromic substrings in the given string
int countPalindromicSubstrings(string inputText) {
    int length = inputText.length();
    vector<vector<bool>> isPalindrome(length, vector<bool>(length, false));
    int total = 0;

    // Check substrings by increasing length
    for (int subLen = 1; subLen <= length; ++subLen) { // current substring length
        for (int start = 0; start <= length - subLen; ++start) {
            int end = start + subLen - 1; // ending position

            if (subLen == 1) {
                isPalindrome[start][end] = true; // single character is always palindromic
            } else if (subLen == 2) {
                isPalindrome[start][end] = (inputText[start] == inputText[end]); // two-char palindrome check
            } else {
                isPalindrome[start][end] = (inputText[start] == inputText[end]) && isPalindrome[start + 1][end - 1];
            }

            if (isPalindrome[start][end]) {
                total++; // add to our count when we find a palindrome
            }
        }
    }
    return total;
}

int main() {
    string text;
    cout << "Input a string: ";
    cin >> text;
    int answer = countPalindromicSubstrings(text);
    cout << "Total palindromic substrings found: " << answer << endl;
    return 0;
}

