// Global variables
HWND g_editControl = NULL;

// Window procedure
LRESULT CALLBACK MainWndProc(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_CREATE:
        {
            // Create an edit control
            g_editControl = CreateWindowEx(0, "EDIT", "", 
                                           WS_CHILD | WS_VISIBLE | ES_AUTOHSCROLL, 
                                           20, 20, 250, 30, 
                                           hWnd, (HMENU)100, 
                                           (HINSTANCE)GetWindowLong(hWnd, GWL_HINSTANCE), 
                                           NULL);
        }
        break;

    case WM_COMMAND:
        {
            int controlId = LOWORD(wParam);
            int notificationCode = HIWORD(wParam);

            if (controlId == 100 && notificationCode == EN_CHANGE)
            {
                // Text has changed, handle it here
                char inputText[512];
                GetWindowText(g_editControl, inputText, sizeof(inputText));
                MessageBox(hWnd, inputText, "Content Updated", MB_OK);
            }
        }
        break;

    case WM_DESTROY:
        PostQuitMessage(0);
        break;

    default:
        return DefWindowProc(hWnd, message, wParam, lParam);
    }

    return 0;
}

// WinMain function
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd)
{
    WNDCLASSEX windowClass = { sizeof(WNDCLASSEX) };
    windowClass.style         = CS_HREDRAW | CS_VREDRAW;
    windowClass.lpfnWndProc   = MainWndProc;
    windowClass.cbClsExtra    = 0;
    windowClass.cbWndExtra    = 0;
    windowClass.hInstance     = hInstance;
    windowClass.hIcon         = LoadIcon(NULL, IDI_APPLICATION);
    windowClass.hCursor       = LoadCursor(NULL, IDC_ARROW);
    windowClass.hbrBackground = (HBRUSH)(COLOR_BTNFACE + 1);
    windowClass.lpszMenuName  = NULL;
    windowClass.lpszClassName = "CustomWindowClass";
    windowClass.hIconSm       = LoadIcon(NULL, IDI_APPLICATION);

    if (!RegisterClassEx(&windowClass))
    {
        MessageBox(NULL, "Window Registration Failed!", "Critical Error", MB_ICONERROR | MB_OK);
        return 0;
    }

    HWND mainHandle = CreateWindowEx(0, "CustomWindowClass", "Windows API Input Monitor",
                                     WS_OVERLAPPEDWINDOW, CW_USEDEFAULT, CW_USEDEFAULT, 600, 400,
                                     NULL, NULL, hInstance, NULL);

    if (mainHandle == NULL)
    {
        MessageBox(NULL, "Window Creation Failed!", "System Error", MB_ICONERROR | MB_OK);
        return 0;
    }

    ShowWindow(mainHandle, nShowCmd);
    UpdateWindow(mainHandle);

    MSG message;
    while (GetMessage(&message, NULL, 0, 0))
    {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }

    return (int)message.wParam;
}

