#include <thrust/host_vector.h>
#include <thrust/device_vector.h>
#include <thrust/generate.h>
#include <thrust/sort.h>
#include <thrust/reduce.h>
#include <thrust/functional.h>
#include <thrust/tuple.h>
#include <thrust/iterator/zip_iterator.h>
#include <thrust/iterator/permutation_iterator.h>
#include <thrust/sequence.h>
#include <iostream>

// Functor to determine the minimum value and track its position
struct find_min_with_location
{
    __host__ __device__
    thrust::tuple<int, int> operator()(const thrust::tuple<int, int>& first, const thrust::tuple<int, int>& second)
    {
        if (thrust::get<0>(first) <= thrust::get<0>(second))
            return first;
        else
            return second;
    }
};

int main()
{
    // Input data arrays
    thrust::host_vector<int> h_data1 = {3, 6, 9};
    thrust::host_vector<int> h_data2 = {1, 5, 7};
    thrust::host_vector<int> h_data3 = {2, 4, 8};

    // Combine all input arrays into one
    thrust::host_vector<int> h_combined;
    h_combined.insert(h_combined.end(), h_data1.begin(), h_data1.end());
    h_combined.insert(h_combined.end(), h_data2.begin(), h_data2.end());
    h_combined.insert(h_combined.end(), h_data3.begin(), h_data3.end());

    // Move combined data to GPU device
    thrust::device_vector<int> d_combined = h_combined;

    // Setup indexing parameters
    int columns = h_data1.size();
    int rows = h_combined.size() / columns;

    // Create column index sequence
    thrust::device_vector<int> d_col_indices(d_combined.size());
    thrust::sequence(d_col_indices.begin(), d_col_indices.end(), 0, rows);

    // Create row index sequence
    thrust::device_vector<int> d_row_nums(d_combined.size());
    thrust::sequence(d_row_nums.begin(), d_row_nums.end(), 0, 1);

    // Prepare zipped data structure
    thrust::device_vector<thrust::tuple<int, int, int>> d_compact(d_combined.size());
    thrust::sequence(d_compact.begin(), d_compact.end(), thrust::make_tuple(0, 0, 0), thrust::make_tuple(1, 1, 1));

    // Build composite tuples containing column, row, and value information
    thrust::transform(d_col_indices.begin(), d_col_indices.end(), 
                     d_row_nums.begin(), 
                     d_compact.begin(), 
                     thrust::make_zip_iterator(thrust::make_tuple(
                         thrust::get<0>(thrust::placeholders::_1), 
                         thrust::get<1>(thrust::placeholders::_1), 
                         thrust::placeholders::_2)));

    thrust::transform(d_compact.begin(), d_compact.end(), 
                     d_combined.begin(), 
                     d_compact.begin(), 
                     thrust::make_zip_iterator(thrust::make_tuple(
                         thrust::get<0>(thrust::placeholders::_1), 
                         thrust::get<1>(thrust::placeholders::_1), 
                         thrust::get<2>(thrust::placeholders::_1), 
                         thrust::placeholders::_2)));

    // Sort entries by column index for grouping
    thrust::stable_sort_by_key(d_compact.begin(), d_compact.end(), 
                              thrust::get<0>(thrust::placeholders::_1));

    // Perform reduction to find minimum in each column
    thrust::device_vector<int> d_result_keys(columns);
    thrust::device_vector<thrust::tuple<int, int>> d_result_values(columns);

    thrust::reduce_by_key(
        thrust::make_transform_iterator(d_compact.begin(), 
                                       thrust::make_tuple(thrust::get<0>(thrust::placeholders::_1))),
        thrust::make_transform_iterator(d_compact.end(), 
                                       thrust::make_tuple(thrust::get<0>(thrust::placeholders::_1))),
        thrust::make_transform_iterator(d_compact.begin(), 
                                       thrust::make_tuple(thrust::get<1>(thrust::placeholders::_1), 
                                                         thrust::get<3>(thrust::placeholders::_1))),
        d_result_keys.begin(),
        d_result_values.begin(),
        thrust::equal_to<int>(),
        find_min_with_location()
    );

    // Copy results back to host memory
    thrust::host_vector<int> h_result_keys = d_result_keys;
    thrust::host_vector<thrust::tuple<int, int>> h_result_values = d_result_values;

    // Display final results
    for (int idx = 0; idx < columns; ++idx)
    {
        std::cout << "Column " << idx << ": Min value = " << thrust::get<1>(h_result_values[idx]) 
                  << ", Index = " << thrust::get<0>(h_result_values[idx]) / rows << std::endl;
    }

    return 0;
}

