// Define block and kernel parameters
#define TILE_DIM 16
#define FILTER_SIZE 3
#define HALF_SIZE (FILTER_SIZE / 2)

// Constant memory for the convolution kernel
__constant__ float filter[FILTER_SIZE * FILTER_SIZE] = {
    0, -1, 0,
    -1, 4, -1,
    0, -1, 0
};

// CUDA kernel for 2D convolution using shared memory tiling
__global__ void applyConvolution(const float* src, float* dst, int imgWidth, int imgHeight) {
    // Shared memory buffer with halo regions for boundary handling
    __shared__ float tile[TILE_DIM + 2 * HALF_SIZE][TILE_DIM + 2 * HALF_SIZE];

    // Thread and block indices
    int blockX = blockIdx.x;
    int blockY = blockIdx.y;
    int threadX = threadIdx.x;
    int threadY = threadIdx.y;

    // Global coordinates of the current pixel
    int y = blockY * TILE_DIM + threadY;
    int x = blockX * TILE_DIM + threadX;

    // Load central region into shared memory
    if (y < imgHeight && x < imgWidth) {
        tile[threadY + HALF_SIZE][threadX + HALF_SIZE] = src[y * imgWidth + x];
    }

    // Handle top and bottom boundaries
    if (y < HALF_SIZE) {
        tile[threadY][threadX + HALF_SIZE] = (y == 0) ? 0.0f : src[(y - 1) * imgWidth + x];
    }
    if (y >= imgHeight - HALF_SIZE) {
        tile[threadY + 2 * HALF_SIZE][threadX + HALF_SIZE] = (y == imgHeight - 1) ? 0.0f : src[(y + 1) * imgWidth + x];
    }

    // Handle left and right boundaries
    if (x < HALF_SIZE) {
        tile[threadY + HALF_SIZE][threadX] = (x == 0) ? 0.0f : src[y * imgWidth + (x - 1)];
    }
    if (x >= imgWidth - HALF_SIZE) {
        tile[threadY + HALF_SIZE][threadX + 2 * HALF_SIZE] = (x == imgWidth - 1) ? 0.0f : src[y * imgWidth + (x + 1)];
    }

    __syncthreads();

    // Perform convolution at the current pixel
    float result = 0.0f;
    for (int fy = 0; fy < FILTER_SIZE; ++fy) {
        for (int fx = 0; fx < FILTER_SIZE; ++fx) {
            result += tile[threadY + HALF_SIZE + fy - HALF_SIZE][threadX + HALF_SIZE + fx - HALF_SIZE] * filter[fy * FILTER_SIZE + fx];
        }
    }

    // Write result to global memory if within bounds
    if (y < imgHeight && x < imgWidth) {
        dst[y * imgWidth + x] = result;
    }
}

int main() {
    // Image dimensions
    int width = 500;
    int height = 500;
    int bytes = width * height * sizeof(float);

    // Host memory allocation
    float* hostInput = new float[width * height];
    float* hostOutput = new float[width * height];

    // Device memory allocation
    float* deviceInput;
    float* deviceOutput;

    cudaMalloc(&deviceInput, bytes);
    cudaMalloc(&deviceOutput, bytes);

    // Initialize input data
    for (int i = 0; i < width * height; ++i) {
        hostInput[i] = 1.0f; // Uniform input values
    }

    // Copy input data to device
    cudaMemcpy(deviceInput, hostInput, bytes, cudaMemcpyHostToDevice);

    // Configure grid and block dimensions
    dim3 threadsPerBlock(TILE_DIM, TILE_DIM);
    dim3 numBlocks((width + TILE_DIM - 1) / TILE_DIM, (height + TILE_DIM - 1) / TILE_DIM);

    // Launch the convolution kernel
    applyConvolution<<<numBlocks, threadsPerBlock>>>(deviceInput, deviceOutput, width, height);

    // Copy results back to host
    cudaMemcpy(hostOutput, deviceOutput, bytes, cudaMemcpyDeviceToHost);

    // Cleanup resources
    cudaFree(deviceInput);
    cudaFree(deviceOutput);
    delete[] hostInput;
    delete[] hostOutput;

    return 0;
}

