// Generate the first n Fibonacci numbers
vector<int> generateFibonacci(int count) {
    vector<int> result;
    if (count <= 0) return result;
    result.push_back(0);
    if (count == 1) return result;
    result.push_back(1);
    for (int index = 2; index < count; index++) {
        result.push_back(result[index - 1] + result[index - 2]);
    }
    return result;
}

int main() {
    vector<int> fibSequence = generateFibonacci(10);
    for (int value : fibSequence) {
        cout << value << " ";
    }
    return 0;
}

