// Find the minimum and maximum values in a vector
std::pair<int, int> getRange(const std::vector<int>& data) {
    if (data.empty()) {
        return {0, 0};  // Return zeros for empty input
    }
    int smallest = data[0];  // Start with first element as both min and max
    int largest = data[0];
    for (int value : data) {
        if (value < smallest) {
            smallest = value;
        }
        if (value > largest) {
            largest = value;
        }
    }
    return {smallest, largest};
}

int main() {
    std::vector<int> numbers = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};
    auto [low, high] = getRange(numbers);
    std::cout << "Lowest: " << low << ", Highest: " << high << std::endl;
    return 0;
}

