#include <xmmintrin.h> // for SSE intrinsics
#include <iostream>

// Ensure data is 16-byte aligned
__declspec(align(16)) float firstVec[4];
__declspec(align(16)) float secondVec[4];
__declspec(align(16)) float output[4];

int main() {
    float x = 1.0f, y = 2.0f, z = 3.0f, w = 4.0f;
    float p = 5.0f, q = 6.0f, r = 7.0f, s = 8.0f;

    // Initialize the arrays
    firstVec[0] = x; firstVec[1] = y; firstVec[2] = z; firstVec[3] = w;
    secondVec[0] = p; secondVec[1] = q; secondVec[2] = r; secondVec[3] = s;

    // Load the data into SSE registers
    __m128 reg1 = _mm_load_ps(firstVec);
    __m128 reg2 = _mm_load_ps(secondVec);

    // Perform the multiplication
    __m128 reg3 = _mm_mul_ps(reg1, reg2);

    // Store the result
    _mm_store_ps(output, reg3);

    // Print the results
    std::cout << "Result: " << output[0] << ", " << output[1] << ", " << output[2] << ", " << output[3] << std::endl;

    return 0;
}

