#include <iostream>
using namespace std;

// Structure representing a node in a singly linked list
struct SinglyNode {
    int value;
    SinglyNode* link;
};

// Structure representing a node in a doubly linked list
struct DoublyNode {
    int value;
    DoublyNode* forward;
    DoublyNode* backward;
};

// Factory function to allocate and initialize a new singly node
SinglyNode* makeSinglyNode(int val) {
    SinglyNode* freshNode = new SinglyNode();
    freshNode->value = val;
    freshNode->link = nullptr;
    return freshNode;
}

// Factory function to allocate and initialize a new doubly node
DoublyNode* makeDoublyNode(int val) {
    DoublyNode* freshNode = new DoublyNode();
    freshNode->value = val;
    freshNode->forward = nullptr;
    freshNode->backward = nullptr;
    return freshNode;
}

// Transform a singly linked list into a doubly linked list
DoublyNode* transformToDoubly(SinglyNode* origin) {
    if (origin == nullptr) {
        return nullptr;
    }

    DoublyNode* doublyStart = nullptr;
    DoublyNode* traverseDoubly = nullptr;
    SinglyNode* traverseSingly = origin;

    while (traverseSingly != nullptr) {
        DoublyNode* freshNode = makeDoublyNode(traverseSingly->value);

        if (doublyStart == nullptr) {
            doublyStart = freshNode;
            traverseDoubly = freshNode;
        } else {
            traverseDoubly->forward = freshNode;
            freshNode->backward = traverseDoubly;
            traverseDoubly = freshNode;
        }

        traverseSingly = traverseSingly->link;
    }

    return doublyStart;
}

// Display the doubly linked list from head to tail
void showDoublyForward(DoublyNode* origin) {
    DoublyNode* traverse = origin;
    while (traverse != nullptr) {
        cout << traverse->value << " ";
        traverse = traverse->forward;
    }
    cout << endl;
}

// Display the doubly linked list from tail to head
void showDoublyBackward(DoublyNode* origin) {
    if (origin == nullptr) {
        return;
    }
    DoublyNode* traverse = origin;
    while (traverse->forward != nullptr) {
        traverse = traverse->forward;
    }
    while (traverse != nullptr) {
        cout << traverse->value << " ";
        traverse = traverse->backward;
    }
    cout << endl;
}

int main() {
    // Build a singly linked list: 5 -> 10 -> 15 -> 20
    SinglyNode* start = makeSinglyNode(5);
    start->link = makeSinglyNode(10);
    start->link->link = makeSinglyNode(15);
    start->link->link->link = makeSinglyNode(20);

    // Convert the singly linked list to a doubly linked list
    DoublyNode* doublyStart = transformToDoubly(start);

    // Print the doubly linked list in forward order
    cout << "Doubly Linked List (Forward): ";
    showDoublyForward(doublyStart);

    // Print the doubly linked list in reverse order
    cout << "Doubly Linked List (Backward): ";
    showDoublyBackward(doublyStart);

    return 0;
}

#include <pybind11/pybind11.h>
#include <memory>

namespace py = pybind11;

// Base and derived class definitions
struct Parent { };
struct Child : public Parent { };

// Container that accepts shared pointers to Parent
struct Manager {
    void accept(const std::shared_ptr<Parent>& obj) { }
};

PYBIND11_MODULE(PybindExample, mod) {
    // Bind the Parent class with shared_ptr support
    py::class_<Parent, std::shared_ptr<Parent>>(mod, "Parent").def(py::init<>());

    // Bind the Child class, inheriting from Parent
    py::class_<Child, std::shared_ptr<Child>, Parent>(mod, "Child").def(py::init<>());

    // Bind the Manager class with shared_ptr support
    py::class_<Manager, std::shared_ptr<Manager>>(mod, "Manager")
        .def(py::init<>())
        .def("accept", &Manager::accept)
        .def("accept", [](Manager& self, const std::shared_ptr<Child>& obj) {
            self.accept(obj);  // Implicit conversion from shared_ptr<Child> to shared_ptr<Parent>
        });
}

#include <iostream>
#include <unordered_set>

// Determine if a number is a happy number
bool checkHappyNumber(int value) {
    std::unordered_set<int> visited;
    while (value != 1 && visited.find(value) == visited.end()) {
        visited.insert(value);
        int result = 0;
        while (value > 0) {
            int digit = value % 10;
            result += digit * digit;
            value /= 10;
        }
        value = result;
    }
    return value == 1;
}

int main() {
    int maxRange = 10000;
    for (int num = 1; num <= maxRange; ++num) {
        if (checkHappyNumber(num)) {
            std::cout << num << " ";
        }
    }
    std::cout << std::endl;
    return 0;
}

