// Check if there exists any pair in the vector that sums to the target value
bool containsTwoElementsWithSum(const std::vector<int>& values, int desired) {
    for (size_t index1 = 0; index1 < values.size(); ++index1) {
        for (size_t index2 = index1 + 1; index2 < values.size(); ++index2) {
            if (values[index1] + values[index2] == desired) {
                return true;
            }
        }
    }
    return false;
}

int main() {
    std::vector<int> data = {1, 3, 5, 0, 2};
    int goal = 5;

    if (containsTwoElementsWithSum(data, goal)) {
        std::cout << "There is a pair with sum " << goal << std::endl;
    } else {
        std::cout << "No pair with sum " << goal << std::endl;
    }

    return 0;
}

