#define LISTEN_PORT htons(50007)

int main() {
    int listenSocket = socket(AF_INET, SOCK_STREAM, 0); 

    if (listenSocket < 0) {
        perror("Socket creation failed");
        exit(1);
    }

    sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = LISTEN_PORT;
    serverAddress.sin_addr.s_addr = INADDR_ANY;

    if (bind(listenSocket, (struct sockaddr *)&serverAddress, sizeof(sockaddr)) < 0) {
        perror("Binding failed");
        exit(1);
    }

    listen(listenSocket, 5);

    sockaddr_in clientAddress;
    socklen_t addressSize = sizeof(struct sockaddr_in);

    int connectionSocket = accept(listenSocket, (struct sockaddr*)&clientAddress, &addressSize);

    if (connectionSocket < 0) {
        perror("Accept failed");
        exit(1);
    }

    // Receive file size information
    char sizeData[10];
    int bytesRead = recv(connectionSocket, sizeData, sizeof(sizeData), 0);
    if (bytesRead < 0) {
        perror("Failed to read file size");
        exit(1);
    }
    sizeData[bytesRead] = '\0';
    int totalFileSize = atoi(sizeData);

    FILE* outputFile = fopen("received_image.jpg", "wb");

    unsigned int bytesReceived = 0;

    while (bytesReceived < totalFileSize) {
        std::size_t chunkSize = 2048;
        char dataBuffer[2048];

        bytesRead = recv(connectionSocket, dataBuffer, chunkSize, 0);
        if (bytesRead <= 0) {
            perror("Socket read error");
            exit(1);    
        }

        fwrite(dataBuffer, sizeof(char), bytesRead, outputFile);    
        bytesReceived += bytesRead;    
    }

    fclose(outputFile);

    close(listenSocket);
    return 0;
}

#include <iostream>
