    }
};

// Class representing a complete complex number
class ComplexNumber {
private:
    RealComponent realPart;
    ImaginaryComponent imagPart;

public:
    ComplexNumber(const RealComponent& r, const ImaginaryComponent& i) 
        : realPart(r), imagPart(i) {}

    // Addition operator
    ComplexNumber operator+(const ComplexNumber& other) const {
        return ComplexNumber(realPart + other.realPart, imagPart + other.imagPart);
    }

    // Subtraction operator
    ComplexNumber operator-(const ComplexNumber& other) const {
        return ComplexNumber(realPart - other.realPart, imagPart - other.imagPart);
    }

    // Multiplication operator
    ComplexNumber operator*(const ComplexNumber& other) const {
        return ComplexNumber((realPart * other.realPart) - (imagPart * other.imagPart),
                           (realPart * other.imagPart) + (other.realPart * imagPart));
    }

    // Division operator
    ComplexNumber operator/(const ComplexNumber& other) const {
        double denominator = (other.realPart.getValue() * other.realPart.getValue()) + 
                            (other.imagPart.getValue() * other.imagPart.getValue());
        double realResult = ((realPart.getValue() * other.realPart.getValue()) + 
                            (imagPart.getValue() * other.imagPart.getValue())) / denominator;
        double imagResult = ((imagPart.getValue() * other.realPart.getValue()) - 
                            (realPart.getValue() * other.imagPart.getValue())) / denominator;
        return ComplexNumber(RealComponent(realResult), ImaginaryComponent(imagResult));
    }

    // Magnitude function
    double magnitude() const {
        return std::sqrt((realPart.getValue() * realPart.getValue()) + 
                        (imagPart.getValue() * imagPart.getValue()));
    }

    // Square root function
    ComplexNumber sqrt() const {
        double mag = magnitude();
        double realPartVal = std::sqrt((realPart.getValue() + mag) / 2.0);
        double imagPartVal = std::sqrt(((-1.0 * realPart.getValue()) + mag) / 2.0);
        return ComplexNumber(RealComponent(realPartVal), ImaginaryComponent(imagPartVal));
    }

    // Getter for the real component
    RealComponent getRealComponent() const {
        return realPart;
    }

    // Getter for the imaginary component
    ImaginaryComponent getImaginaryComponent() const {
        return imagPart;
    }
};

int main() {
    // Demonstration of complex number operations
    RealComponent rA(4.5);
    RealComponent rB(5.3);
    ImaginaryComponent iA(2.7);
    ImaginaryComponent iB(1.9);

    ComplexNumber num1(rA, iA);
    ComplexNumber num2(rB, iB);

    ComplexNumber resultSum = num1 + num2;
    ComplexNumber resultDiff = num1 - num2;
    ComplexNumber resultProduct = num1 * num2;
    ComplexNumber resultQuotient = num1 / num2;

    std::cout << "Addition: " << resultSum.getRealComponent().getValue() << " + " 
              << resultSum.getImaginaryComponent().getValue() << "i" << std::endl;
    std::cout << "Subtraction: " << resultDiff.getRealComponent().getValue() << " + " 
              << resultDiff.getImaginaryComponent().getValue() << "i" << std::endl;
    std::cout << "Multiplication: " << resultProduct.getRealComponent().getValue() << " + " 
              << resultProduct.getImaginaryComponent().getValue() << "i" << std::endl;
    std::cout << "Division: " << resultQuotient.getRealComponent().getValue() << " + " 
              << resultQuotient.getImaginaryComponent().getValue() << "i" << std::endl;

    double magnitudeVal = num1.magnitude();
    ComplexNumber resultSqrt = num1.sqrt();

    std::cout << "Magnitude of num1: " << magnitudeVal << std::endl;
    std::cout << "Square root of num1: " << resultSqrt.getRealComponent().getValue() << " + " 
              << resultSqrt.getImaginaryComponent().getValue() << "i" << std::endl;

