    Node* right;
    Node* next;

    Node() : val(0), left(NULL), right(NULL), next(NULL) {}

    Node(int _val) : val(_val), left(NULL), right(NULL), next(NULL) {}

    Node(int _val, Node* _left, Node* _right, Node* _next)
        : val(_val), left(_left), right(_right), next(_next) {}
};
*/

class Solution {
public:
    Node* connect(Node* root) {
        if (!root) return root;

        Node* levelStart = root;

        while (levelStart) {
            Node* traverse = levelStart;
            Node* helper = new Node(0); // Helper node to simplify next level linking
            Node* tail = helper;

            while (traverse) {
                if (traverse->left) {
                    tail->next = traverse->left;
                    tail = tail->next;
                }
                if (traverse->right) {
                    tail->next = traverse->right;
                    tail = tail->next;
                }
                traverse = traverse->next;
            }

            levelStart = helper->next; // Proceed to the subsequent level
            delete helper; // Release the helper node memory
        }

        return root;
    }
};

