namespace py = pybind11;

class MyClass {
public:
    MyClass() {
        value = 10;
    }

    ~MyClass() {}

    int value;
};

class Container {
public:
    Container() {
        items.emplace_back(std::make_shared<MyClass>());
        items.emplace_back(std::make_shared<MyClass>());
    }

    ~Container() {}

    std::vector<std::shared_ptr<MyClass>> items;
};

PYBIND11_MODULE(modulename, module) {
    py::class_<MyClass, std::shared_ptr<MyClass>> cls(module, "MyClass", py::dynamic_attr());
    cls
        .def(py::init<>())
        .def_readwrite("value", &MyClass::value);

    py::class_<Container> cont(module, "Container");
    cont
        .def(py::init<>())
        .def_property_readonly("items", [](Container &c) {
            static std::unordered_map<std::shared_ptr<MyClass>, py::object> obj_cache;
            py::list output;
            for (const auto &sp : c.items) {
                auto iter = obj_cache.find(sp);
                if (iter == obj_cache.end()) {
                    py::object obj = py::cast(sp, py::return_value_policy::reference);
                    obj_cache[sp] = obj;
                    output.append(obj);
                } else {
                    output.append(iter->second);
                }
            }
            return output;
        });
}

