// Retrieve an image from Android storage using ACTION_GET_CONTENT
void imagePickerAndroid::fetchImage()
{
    QAndroidJniObject ACTION_GET_CONTENT = QAndroidJniObject::fromString("android.intent.action.GET_CONTENT");
    QAndroidJniObject intent("android/content/Intent");
    if (ACTION_GET_CONTENT.isValid() && intent.isValid())
    {
        intent.callObjectMethod("setAction", "(Ljava/lang/String;)Landroid/content/Intent;", ACTION_GET_CONTENT.object<jstring>());
        intent.callObjectMethod("setType", "(Ljava/lang/String;)Landroid/content/Intent;", QAndroidJniObject::fromString("image/*").object<jstring>());
        QtAndroid::startActivity(intent.object<jobject>(), 202, this);
        qDebug() << "Success";
    }
    else
    {
        qDebug() << "Failure";
    }
}

// Process the result returned after selecting an image
void imagePickerAndroid::processActivityResult(int requestCode, int result, const QAndroidJniObject &resultData)
{
    jint ACTIVITY_RESULT_OK = QAndroidJniObject::getStaticField<jint>("android/app/Activity", "RESULT_OK");
    if (requestCode == 202 && result == ACTIVITY_RESULT_OK) {
        QAndroidJniObject imageUri = resultData.callObjectMethod("getData", "()Landroid/net/Uri;");
        if (imageUri.isValid()) {
            QAndroidJniObject contentResolver = QtAndroid::androidActivity().callObjectMethod("getContentResolver", "()Landroid/content/ContentResolver;");
            QAndroidJniObject projectionColumn = QAndroidJniObject::fromString("_data");
            QAndroidJniObject cursor = contentResolver.callObjectMethod("query", "(Landroid/net/Uri;[Ljava/lang/String;Ljava/lang/String;[Ljava/lang/String;Ljava/lang/String;)Landroid/database/Cursor;",
                                          imageUri.object<jobject>(),
                                          QAndroidJniObject::fromString("_data").object<jobjectArray>(),
                                          nullptr,
                                          nullptr,
                                          nullptr);

            if (cursor.isValid()) {
                jint dataColumnIndex = cursor.callMethod<jint>("getColumnIndexOrThrow", "(Ljava/lang/String;)I", projectionColumn.object<jstring>());
                cursor.callMethod<jboolean>("moveToFirst", "()Z");
                QAndroidJniObject filePath = cursor.callObjectMethod("getString", "(I)Ljava/lang/String;", dataColumnIndex);
                QString imagePath = filePath.toString();
                cursor.callMethod<void>("close", "()V");
                emit imageFilePathSignal(imagePath);
                qDebug() << imagePath;
            } else {
                qDebug() << "Cursor is invalid";
            }
        } else {
            qDebug() << "URI is invalid";
        }
    } else {
        qDebug() << "Incorrect request or result code";
    }
}

