// Determine if a character is an arithmetic operator
bool isArithmeticOperator(char symbol) {
    return symbol == '+' || symbol == '-' || symbol == '*' || symbol == '/' || symbol == '^';
}

// Retrieve the precedence level of an operator
int getPrecedenceLevel(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        case '^':
            return 3;
        default:
            return 0;
    }
}

// Transform an infix expression to postfix notation
std::string convertInfixToPostfix(const std::string& infixExpr) {
    std::stack<char> operatorStack;
    std::string postfixResult;
    for (char ch : infixExpr) {
        if (std::isdigit(ch)) {
            postfixResult += ch;
        } else if (isArithmeticOperator(ch)) {
            while (!operatorStack.empty() && getPrecedenceLevel(operatorStack.top()) >= getPrecedenceLevel(ch)) {
                postfixResult += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(ch);
        } else if (ch == '(') {
            operatorStack.push(ch);
        } else if (ch == ')') {
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                postfixResult += operatorStack.top();
                operatorStack.pop();
            }
            if (operatorStack.empty() || operatorStack.top() != '(') {
                throw std::runtime_error("Parentheses mismatch");
            }
            operatorStack.pop();
        }
    }
    while (!operatorStack.empty()) {
        if (operatorStack.top() == '(') {
            throw std::runtime_error("Parentheses mismatch");
        }
        postfixResult += operatorStack.top();
        operatorStack.pop();
    }
    return postfixResult;
}

// Compute the value of a postfix expression
double computePostfixExpression(const std::string& postfixExpr) {
    std::stack<double> evaluationStack;
    for (char ch : postfixExpr) {
        if (std::isdigit(ch)) {
            evaluationStack.push(ch - '0');
        } else if (isArithmeticOperator(ch)) {
            if (evaluationStack.size() < 2) {
                throw std::runtime_error("Malformed expression");
            }
            double operand2 = evaluationStack.top(); evaluationStack.pop();
            double operand1 = evaluationStack.top(); evaluationStack.pop();
            switch (ch) {
                case '+': evaluationStack.push(operand1 + operand2); break;
                case '-': evaluationStack.push(operand1 - operand2); break;
                case '*': evaluationStack.push(operand1 * operand2); break;
                case '/': 
                    if (operand2 == 0.0) throw std::runtime_error("Division by zero");
                    evaluationStack.push(operand1 / operand2); 
                    break;
                case '^': evaluationStack.push(std::pow(operand1, operand2)); break;
            }
        }
    }
    if (evaluationStack.size() != 1) {
        throw std::runtime_error("Malformed expression");
    }
    return evaluationStack.top();
}

// Main function to evaluate a mathematical expression given as a string
double calculateExpression(const std::string& input) {
    std::string postfixForm = convertInfixToPostfix(input);
    return computePostfixExpression(postfixForm);
}

int main() {
    std::string mathExpression = "3 + 5 * (2 - 4)";
    try {
        double outcome = calculateExpression(mathExpression);
        std::cout << "Outcome: " << outcome << std::endl;
    } catch (const std::exception& err) {
        std::cerr << "Exception: " << err.what() << std::endl;
    }
    return 0;
}

