    std::string initializationVector = "0123456789abcdef"; // 16-byte IV
    std::string message = "Hello, World!";

    unsigned char keyBuffer[AES_BLOCK_SIZE];
    unsigned char ivBuffer[AES_BLOCK_SIZE];
    std::copy(encryptionKey.begin(), encryptionKey.end(), keyBuffer);
    std::copy(initializationVector.begin(), initializationVector.end(), ivBuffer);

    EVP_CIPHER_CTX *encryptionContext;
    unsigned char encryptedData[128];
    int partialLength;
    int totalEncryptedLength;

    encryptionContext = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(encryptionContext, EVP_aes_128_cbc(), NULL, keyBuffer, ivBuffer);
    EVP_EncryptUpdate(encryptionContext, encryptedData, &partialLength, (unsigned char*)message.c_str(), message.length());
    totalEncryptedLength = partialLength;
    EVP_EncryptFinal_ex(encryptionContext, encryptedData + partialLength, &partialLength);
    totalEncryptedLength += partialLength;

    EVP_CIPHER_CTX_free(encryptionContext);

    std::string encodedResult = base64_encode(encryptedData, totalEncryptedLength);

    std::cout << "Encrypted: " + encodedResult << std::endl;

    return 0;
}

