// Lookup table for converting 2-bit values into XMM masks
static const uint16_t MASK_LUT[4] = { 0x0000, 0x0080, 0x8000, 0x8080 };

xmm2q convert_mask(uint64_t index) {
    assert(index < 4);
    #ifdef USE_ASM
        xmm2q output;
        asm("vpmovsxbq (%1,%2,2), %0" : "=x" (output) : "r" (MASK_LUT), "r" (index));
        return output;
    #else
        // Convert 8-bit to 64-bit elements using intrinsic
        return (xmm2q) _mm_cvtepi8_epi64(*((__m128i*) &MASK_LUT[index]));
    #endif
}

