#include <cuda_runtime.h>
#include <stdlib.h>
#include <iostream>
#include <stdio.h>
#include <cmath>

__global__ void processKernel(const float* input, float* output, size_t inputPitch, size_t outputPitch, int width, int height) {
    int y = blockIdx.y * blockDim.y + threadIdx.y;
    int x = blockIdx.x * blockDim.x + threadIdx.x;

    if (y >= height || x >= width)
        return;

    // Convert byte strides to element counts
    size_t inputStride = inputPitch / sizeof(float);
    size_t outputStride = outputPitch / sizeof(float);

    const float* rowInput = input + y * inputStride;
    float* rowOutput = output + y * outputStride;

    float value = rowInput[x];

    if (static_cast<int>(value) % 90 == 0) {
        rowOutput[x] = -1.0f;
    } else {
        float angle = acosf(value);
        rowOutput[x] = angle;
    }
}

int alignUp(int value, int alignment) {
    return (value + alignment - 1) / alignment;
}

extern "C" {
void processImage(const float* srcData, float* dstData, size_t srcPitch, size_t dstPitch, int imgWidth, int imgHeight) {
    dim3 blockDims(32, 8);
    dim3 gridDims(alignUp(imgWidth, blockDims.x), alignUp(imgHeight, blockDims.y));

    std::cout << "launching CUDA kernel\n";
    processKernel<<<gridDims, blockDims>>>(srcData, dstData, srcPitch, dstPitch, imgWidth, imgHeight);
    std::cout << "kernel execution completed\n";

    cudaDeviceSynchronize();
}
}

