#include <limits>

struct Coordinate3D {
    double a, b, c;

    Coordinate3D(double a, double b, double c) : a(a), b(b), c(c) {}

    double distanceFrom(const Coordinate3D &other) const {
        return std::sqrt((a - other.a) * (a - other.a) +
                         (b - other.b) * (b - other.b) +
                         (c - other.c) * (c - other.c));
    }
};

bool sortByA(const Coordinate3D &p1, const Coordinate3D &p2) {
    return p1.a < p2.a;
}

bool sortByB(const Coordinate3D &p1, const Coordinate3D &p2) {
    return p1.b < p2.b;
}

bool sortByC(const Coordinate3D &p1, const Coordinate3D &p2) {
    return p1.c < p2.c;
}

double smallerValue(double x, double y) {
    return (x < y) ? x : y;
}

double exhaustiveSearch(std::vector<Coordinate3D> &coords, int count) {
    double min_distance = std::numeric_limits<double>::max();
    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count; ++j) {
            double dist = coords[i].distanceFrom(coords[j]);
            if (dist < min_distance) {
                min_distance = dist;
            }
        }
    }
    return min_distance;
}

double nearStrip(std::vector<Coordinate3D> &boundary, int boundarySize, double threshold) {
    double closest = threshold;

    for (int i = 0; i < boundarySize; ++i) {
        for (int j = i + 1; j < boundarySize && (boundary[j].b - boundary[i].b) < closest; ++j) {
            double dist = boundary[i].distanceFrom(boundary[j]);
            if (dist < closest) {
                closest = dist;
            }
        }
    }
    return closest;
}

double recursiveClosest(std::vector<Coordinate3D> &sortedX, std::vector<Coordinate3D> &sortedY, int size) {
    if (size <= 3) return exhaustiveSearch(sortedX, size);

    int centerIndex = size / 2;
    Coordinate3D centerPoint = sortedX[centerIndex];

    std::vector<Coordinate3D> leftY, rightY;
    for (int i = 0; i < size; ++i) {
        if (sortedY[i].a <= centerPoint.a) {
            leftY.push_back(sortedY[i]);
        } else {
            rightY.push_back(sortedY[i]);
        }
    }

    double distLeft = recursiveClosest(sortedX, leftY, centerIndex);
    double distRight = recursiveClosest(sortedX, rightY, size - centerIndex);

    double minDist = smallerValue(distLeft, distRight);

    std::vector<Coordinate3D> strip;
    for (int i = 0; i < size; ++i) {
        if (std::abs(sortedY[i].a - centerPoint.a) < minDist) {
            strip.push_back(sortedY[i]);
        }
    }

    return smallerValue(minDist, nearStrip(strip, strip.size(), minDist));
}

double findMinimumDistance(std::vector<Coordinate3D> &coordinates, int totalPoints) {
    std::vector<Coordinate3D> byX = coordinates;
    std::vector<Coordinate3D> byY = coordinates;

    std::sort(byX.begin(), byX.end(), sortByA);
    std::sort(byY.begin(), byY.end(), sortByB);

    return recursiveClosest(byX, byY, totalPoints);
}

int main() {
    std::vector<Coordinate3D> dataPoints = {{2, 3, 4}, {12, 30, 40}, {40, 50, 60}, {5, 1, 2}, {12, 10, 3}};
    int n = dataPoints.size();
    std::cout << "The smallest distance is " << findMinimumDistance(dataPoints, n) << std::endl;
    return 0;
}

