#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

// Find the longest contiguous subarray with a given target sum
vector<int> getLongestSubsequenceWithSum(const vector<int>& data, int goal) {
    unordered_map<int, int> prefixToIndex; // Stores earliest occurrence of each prefix sum
    int bestLength = 0;
    int begin = -1; // Starting index of the longest valid subsequence
    int runningTotal = 0;

    // Base case: prefix sum 0 occurs before the array starts (at index -1)
    prefixToIndex[0] = -1;

    for (int idx = 0; idx < data.size(); ++idx) {
        runningTotal += data[idx];

        // Case 1: subarray from start to current index sums to goal
        if (runningTotal == goal) {
            if (idx + 1 > bestLength) {
                bestLength = idx + 1;
                begin = 0;
            }
        }

        // Case 2: subarray starting after some earlier index sums to goal
        if (prefixToIndex.count(runningTotal - goal) > 0) {
            int priorPos = prefixToIndex[runningTotal - goal];
            if (idx - priorPos > bestLength) {
                bestLength = idx - priorPos;
                begin = priorPos + 1;
            }
        }

        // Record earliest occurrence of this prefix sum
        if (prefixToIndex.find(runningTotal) == prefixToIndex.end()) {
            prefixToIndex[runningTotal] = idx;
        }
    }

    if (begin == -1) {
        return {}; // No matching subsequence exists
    }

    return vector<int>(data.begin() + begin, data.begin() + begin + bestLength);
}

int main() {
    vector<int> sequence = {1, 2, -3, 4, 5, -3, 2};
    int desiredSum = 4;
    vector<int> output = getLongestSubsequenceWithSum(sequence, desiredSum);

    if (output.empty()) {
        cout << "No subsequence found" << endl;
    } else {
        cout << "Longest subsequence with sum " << desiredSum << ": ";
        for (int val : output) {
            cout << val << " ";
        }
        cout << endl;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char** argv)
{
    // Machine code for BIOS interrupt call to print 'A' and halt
    const unsigned char bios_code[] =
    {
        0xb4, 0x0e,             // mov ah, 0EH
        0xb0, 0x41,             // mov al, 41H (ASCII 'A')
        0x66, 0xbb, 0x0f, 0x00, // mov bx, 0FH
        0xcd, 0x10,             // int 10H
        0xf4,                   // hlt
        0xeb, 0xfe              // jmp $
    };

    // Boot sector signature bytes
    const unsigned char boot_sig[] = {0x55, 0xAA};

    const size_t code_size = sizeof(bios_code);
    const size_t sig_size = sizeof(boot_sig);

    // Allocate memory for the disk image (512 bytes)
    unsigned char* sector = (unsigned char*)calloc(512, sizeof(unsigned char));
    if (sector == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Copy the machine code into the beginning of the sector
    memcpy(sector, bios_code, code_size);

    // Place the boot signature at offset 510
    memcpy(sector + 510, boot_sig, sig_size);

    // Write the disk image to file
    FILE* outputFile = fopen("disk.img", "wb");
    if (outputFile == NULL) {
        fprintf(stderr, "Failed to open output file\n");
        free(sector);
        return 1;
    }

    fwrite(sector, sizeof(unsigned char), 512, outputFile);
    fclose(outputFile);
    free(sector);

    return 0;
}

