std::vector<std::string> splitIntoWords(const std::string& input) {
    std::vector<std::string> wordList;
    std::istringstream stream(input);
    std::string word;
    while (stream >> word) {
        wordList.push_back(word);
    }
    return wordList;
}

std::string convertToLower(const std::string& input) {
    std::string result;
    for (char ch : input) {
        result += std::tolower(ch);
    }
    return result;
}

std::vector<std::string> cleanText(const std::string& input, const std::unordered_set<std::string>& excludedWords) {
    std::vector<std::string> words = splitIntoWords(convertToLower(input));
    std::vector<std::string> cleanedWords;
    for (const std::string& word : words) {
        if (excludedWords.find(word) == excludedWords.end()) {
            cleanedWords.push_back(word);
        }
    }
    return cleanedWords;
}

int main() {
    std::unordered_set<std::string> excludedWords = {"the", "a", "an", "in", "on", "at", "to", "for", "with", "of"};
    std::string sentence = "I want to buy a book in the store.";
    std::vector<std::string> words = cleanText(sentence, excludedWords);
    for (const std::string& word : words) {
        std::cout << word << " ";
    }
    std::cout << std::endl;
    return 0;
}

