std::map<std::string, std::string> mergeStringMaps(const std::map<std::string, std::string>& sourceMap, const std::map<std::string, std::string>& targetMap) {
    std::map<std::string, std::string> output;

    // Copy all entries from the first map
    for (auto it = sourceMap.begin(); it != sourceMap.end(); ++it) {
        output[it->first] = it->second;
    }

    // Add/override with entries from the second map
    for (auto iter = targetMap.begin(); iter != targetMap.end(); ++iter) {
        output[iter->first] = iter->second;
    }

    return output;
}

#include <windows.h>
#include <stdio.h>

void MessageServer()
{
    HANDLE pipeHandle;
    char messageBuffer[2048];
    DWORD bytesRead, bytesWritten;

    while (true)
    {
        pipeHandle = CreateNamedPipe(
            TEXT("\\\\.\\pipe\\messagechannel"),
            PIPE_ACCESS_DUPLEX,
            PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT,
            1,
            2048 * 16,
            2048 * 16,
            0,
            NULL);

        if (pipeHandle == INVALID_HANDLE_VALUE)
        {
            printf("Pipe creation error: %d\n", GetLastError());
            return;
        }

        if (ConnectNamedPipe(pipeHandle, NULL) != FALSE)
        {
            while (ReadFile(pipeHandle, messageBuffer, sizeof(messageBuffer) - 1, &bytesRead, NULL) != FALSE)
            {
                messageBuffer[bytesRead] = '\0';
                printf("Received from client: %s\n", messageBuffer);

                char reply[2048] = "Acknowledged";
                WriteFile(pipeHandle, reply, (DWORD)strlen(reply), &bytesWritten, NULL);
            }
        }
        else
        {
            printf("Connection failed with error %d\n", GetLastError());
        }

        CloseHandle(pipeHandle);
    }
}

int main()
{
    MessageServer();
    return 0;
}

