};

// Function to find the Lowest Common Ancestor of two nodes in a binary tree
Node* getLCA(Node* current, int value1, int value2) {
    if (current == NULL) return NULL;

    // If current node matches either of the target values, return current node
    if (current->data == value1 || current->data == value2) {
        return current;
    }

    // Search for the values in left and right subtrees
    Node* leftResult = getLCA(current->leftChild, value1, value2);
    Node* rightResult = getLCA(current->rightChild, value1, value2);

    // If both subtrees return non-NULL, current node is the LCA
    if (leftResult && rightResult) {
        return current;
    }

    // Otherwise, return the non-NULL result from either subtree
    return (leftResult != NULL) ? leftResult : rightResult;
}

// Function to construct a sample binary tree
Node* createSampleTree() {
    Node* root = new Node(10);
    root->leftChild = new Node(20);
    root->rightChild = new Node(30);
    root->leftChild->leftChild = new Node(40);
    root->leftChild->rightChild = new Node(50);
    root->rightChild->leftChild = new Node(60);
    root->rightChild->rightChild = new Node(70);
    return root;
}

// Main function to test the LCA implementation
int main() {
    Node* treeRoot = createSampleTree();
    int firstValue = 40, secondValue = 50;
    Node* lowestCommonAncestor = getLCA(treeRoot, firstValue, secondValue);

    if (lowestCommonAncestor) {
        cout << "Lowest Common Ancestor of " << firstValue << " and " 
             << secondValue << " is " << lowestCommonAncestor->data << endl;
    } else {
        cout << "Lowest Common Ancestor of " << firstValue << " and " 
             << secondValue << " does not exist" << endl;
    }

    return 0;
}

