#include <winsock2.h>
#include <windows.h>
#include <iostream>

#pragma comment(lib, "ws2_32.lib")

void HandleReadFinish(SOCKET socket, DWORD transferredBytes);
void HandleWriteFinish(SOCKET socket, DWORD transferredBytes);

int main() {
    WSADATA wsaData;
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
        std::cerr << "Unable to initialize Winsock" << std::endl;
        return 1;
    }

    SOCKET clientSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (clientSocket == INVALID_SOCKET) {
        std::cerr << "Socket creation failed" << std::endl;
        WSACleanup();
        return 1;
    }

    sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(12345);
    serverAddress.sin_addr.s_addr = inet_addr("127.0.0.1");

    if (connect(clientSocket, (sockaddr*)&serverAddress, sizeof(serverAddress)) == SOCKET_ERROR) {
        std::cerr << "Connection to server failed" << std::endl;
        closesocket(clientSocket);
        WSACleanup();
        return 1;
    }

    WSABUF inputBuffer;
    char inputData[1024];
    inputBuffer.buf = inputData;
    inputBuffer.len = sizeof(inputData);

    DWORD bytesReceived;
    DWORD flags = 0;
    WSAOVERLAPPED readOverlapped = {0};
    readOverlapped.hEvent = WSACreateEvent();

    if (WSARecv(clientSocket, &inputBuffer, 1, &bytesReceived, &flags, &readOverlapped, NULL) == SOCKET_ERROR) {
        if (WSAGetLastError() != WSA_IO_PENDING) {
            std::cerr << "Read operation initialization failed" << std::endl;
            WSACloseEvent(readOverlapped.hEvent);
            closesocket(clientSocket);
            WSACleanup();
            return 1;
        }
    }

    HANDLE eventArray[2];
    eventArray[0] = readOverlapped.hEvent;
    eventArray[1] = CreateEvent(NULL, TRUE, FALSE, NULL);

    while (true) {
        DWORD waitResult = WaitForMultipleObjects(2, eventArray, FALSE, INFINITE);
        switch (waitResult) {
            case WAIT_OBJECT_0:
                if (WSAGetOverlappedResult(clientSocket, &readOverlapped, &bytesReceived, FALSE, &flags)) {
                    HandleReadFinish(clientSocket, bytesReceived);
                } else {
                    std::cerr << "Error during read" << std::endl;
                }
                // Resume reading
                if (WSARecv(clientSocket, &inputBuffer, 1, &bytesReceived, &flags, &readOverlapped, NULL) == SOCKET_ERROR) {
                    if (WSAGetLastError() != WSA_IO_PENDING) {
                        std::cerr << "Cannot restart read operation" << std::endl;
                        break;
                    }
                }
                break;
            case WAIT_OBJECT_0 + 1:
                // Process write completion
                HandleWriteFinish(clientSocket, bytesReceived);
                break;
            default:
                std::cerr << "WaitForMultipleObjects encountered an issue" << std::endl;
                break;
        }
    }

    WSACloseEvent(readOverlapped.hEvent);
    CloseHandle(eventArray[1]);
    closesocket(clientSocket);
    WSACleanup();

    return 0;
}

void HandleReadFinish(SOCKET sock, DWORD bytesTransferred) {
    std::cout << "Got " << bytesTransferred << " bytes from server" << std::endl;
    // Analyze the incoming data
}

void HandleWriteFinish(SOCKET sock, DWORD bytesTransferred) {
    std::cout << "Successfully sent " << bytesTransferred << " bytes to server" << std::endl;
    // Manage post-send tasks
}

