#include <utility>
#include <climits>
#include <algorithm>

using namespace std;

// Function to find subarrays with maximum alternating sum
vector<pair<int,int>> findMaxSubarray(vector<int> inputArray, int *maxValue) {
    int size = inputArray.size();

    vector<int> transformed(size); // Convert array for alternating sign handling
    for (int i = 0; i < size; i++) {
        transformed[i] = (i % 2 ? -1 : 1) * inputArray[i];
    }

    // Apply modified Kadane's algorithm
    vector<int> dp(size);
    vector<int> startPos(size);
    dp[0] = transformed[0];
    startPos[0] = 1;
    int best_value = dp[0];
    int best_pos = 0; 

    for (int j = 1; j < size; ++j) {
        if (dp[j - 1] >= 0) {
            dp[j] = dp[j - 1] + transformed[j];
            startPos[j] = startPos[j - 1];
        } else {
            dp[j] = transformed[j];
            startPos[j] = j + 1;
        }

        if (dp[j] > best_value) {
            best_value = dp[j];
            best_pos = j;
        }
    }

    int final_end = best_pos + 1;
    int final_start = startPos[best_pos];

    // Build result pairs
    vector<pair<int, int>> outputPairs;
    *maxValue = best_value;
    for (int k = final_start; k <= final_end; ++k) {
        outputPairs.push_back(make_pair(final_start, k));
    }

    return outputPairs;
}

int main() {
    vector<int> data = {-4, 6, -7, 2, 2};
    int maxVal;
    vector<pair<int,int>> pairs = findMaxSubarray(data, &maxVal);

    cout << "Result Pairs: ";
    for (auto element : pairs) {
        cout << "(" << element.first << "," << element.second << "),";
    }
    cout << " max_value = " << maxVal << endl;

    return 0;
}

