#include <iostream>
#include <vector>
#include <string>

// Find the longest common substring between two strings
std::string findMaxCommonSubstr(const std::string& str1, const std::string& str2) {
    int len1 = str1.size();
    int len2 = str2.size();
    std::vector<std::vector<int>> table(len1 + 1, std::vector<int>(len2 + 1, 0));
    int maxLen = 0;
    int endPos = -1;

    // Build the DP table
    for (int row = 1; row <= len1; ++row) {
        for (int col = 1; col <= len2; ++col) {
            if (str1[row - 1] == str2[col - 1]) {
                table[row][col] = table[row - 1][col - 1] + 1;
                if (table[row][col] > maxLen) {
                    maxLen = table[row][col];
                    endPos = row - 1; // Store 0-based ending index
                }
            } else {
                table[row][col] = 0;
            }
        }
    }

    // Retrieve the substring if any common part exists
    if (maxLen > 0) {
        return str1.substr(endPos - maxLen + 1, maxLen);
    }

    return ""; // Return empty string if no common substring found
}

int main() {
    std::string text1 = "ABABC";
    std::string text2 = "BABC";
    std::string output = findMaxCommonSubstr(text1, text2);
    std::cout << "Longest Common Substring: " << output << std::endl;
    return 0;
}

