// Check if a number is prime
bool checkPrime(int value) {
    if (value <= 1) return false;
    for (int j = 2; j <= std::sqrt(value); j++) {
        if (value % j == 0) return false;
    }
    return true;
}

// Calculate sum of first 'count' prime numbers
int calculatePrimeSum(int count) {
    int primesFound = 0;
    int runningSum = 0;
    int currentNumber = 2;
    while (primesFound < count) {
        if (checkPrime(currentNumber)) {
            runningSum += currentNumber;
            primesFound++;
        }
        currentNumber++;
    }
    return runningSum;
}

int main() {
    std::cout << calculatePrimeSum(10) << std::endl;
    return 0;
}

