#include <Ogre.h>

// Transform a vector from one scene node's coordinate space to another
Ogre::Vector3 TFormVector(const Ogre::Vector3& inputVector, 
                          Ogre::SceneNode* originNode, 
                          Ogre::SceneNode* targetNode) {
    Ogre::Vector3 resultVector = inputVector;

    // Use world coordinates if originNode is missing or null
    const Ogre::Vector3& originPos = (originNode) ? originNode->_getDerivedPosition() : Ogre::Vector3::ZERO;
    const Ogre::Quaternion& originRot = (originNode) ? originNode->_getDerivedOrientation() : Ogre::Quaternion::IDENTITY;

    // Use world coordinates if targetNode is missing or null
    const Ogre::Vector3& targetPos = (targetNode) ? targetNode->_getDerivedPosition() : Ogre::Vector3::ZERO;
    const Ogre::Quaternion& targetRot = (targetNode) ? targetNode->_getDerivedOrientation() : Ogre::Quaternion::IDENTITY;

    // Convert input vector to origin node's local space
    resultVector = originRot.Inverse() * (inputVector - originPos);

    // Rotate vector into target node's orientation
    resultVector = targetRot * resultVector;

    // Translate to target node's position in world space
    resultVector = targetPos + resultVector;

    return resultVector;
}

