#include <cstdlib>
#include <ctime>

using namespace std;

// Compute greatest common divisor using Euclidean algorithm
unsigned long long computeGCD(unsigned long long x, unsigned long long y) {
    while (y != 0) {
        unsigned long long temp = y;
        y = x % y;
        x = temp;
    }
    return x;
}

// Pollard's Rho factorization algorithm
unsigned long long rhoFactor(unsigned long long num) {
    if (num % 2 == 0) return 2;

    unsigned long long slow = 2, fast = 2, divisor = 1;
    unsigned long long constant = (unsigned long long)rand() % (num - 1) + 1;

    while (divisor == 1) {
        slow = (slow * slow + constant) % num;
        fast = (fast * fast + constant) % num;
        fast = (fast * fast + constant) % num;
        divisor = computeGCD(abs(slow - fast), num);

        if (divisor == num) return rhoFactor(num); // Restart with new constant
    }

    return divisor;
}

// Recursive function to print prime factors
void getFactors(unsigned long long value) {
    if (value == 1) return;

    if (value % 2 == 0) {
        cout << 2 << " ";
        getFactors(value / 2);
        return;
    }

    unsigned long long factor = rhoFactor(value);
    if (factor == value) {
        cout << value << " ";
    } else {
        getFactors(factor);
        getFactors(value / factor);
    }
}

int main() {
    srand(time(0)); // Initialize random seed
    unsigned long long number = 9999;
    cout << "Prime factors of " << number << " are: ";
    getFactors(number);
    cout << endl;
    return 0;
}

#include <cuda_runtime.h>
#include <iostream>

// Kernel function to read from texture and write to global memory
__global__ void textureFetchKernel(cudaTextureObject_t textureObject, float *resultBuffer, int imgWidth, int imgHeight) {
    int posX = blockIdx.x * blockDim.x + threadIdx.x;
    int posY = blockIdx.y * blockDim.y + threadIdx.y;

    if (posX < imgWidth && posY < imgHeight) {
        float sample = tex2D<float>(textureObject, posX, posY);
        resultBuffer[posY * imgWidth + posX] = sample;
    }
}

int main() {
    // Device memory pointers
    float *deviceInput;
    cudaTextureObject_t texObject;
    float *deviceOutput;

    // Image dimensions
    int width = 256;
    int height = 256;

    // Allocate device memory buffers
    size_t bytes = width * height * sizeof(float);
    cudaMalloc(&deviceInput, bytes);
    cudaMalloc(&deviceOutput, bytes);

    // Initialize input data (zero-fill for demonstration)
    cudaMemset(deviceInput, 0, bytes);

    // Setup resource descriptor for linear texture
    cudaResourceDesc resDesc;
    memset(&resDesc, 0, sizeof(resDesc));
    resDesc.resType = cudaResourceTypeLinear;
    resDesc.res.linear.devPtr = deviceInput;
    resDesc.res.linear.desc.f = cudaChannelFormatKindFloat;
    resDesc.res.linear.desc.x = 32; // 32-bit floating point per channel
    resDesc.res.linear.sizeInBytes = bytes;

    // Configure texture descriptor
    cudaTextureDesc texDesc;
    memset(&texDesc, 0, sizeof(texDesc));
    texDesc.readMode = cudaReadModeElementType;
    texDesc.addressMode[0] = cudaAddressModeClamp;
    texDesc.addressMode[1] = cudaAddressModeClamp;
    texDesc.filterMode = cudaFilterModeLinear;

    // Create CUDA texture object
    cudaCreateTextureObject(&texObject, &resDesc, &texDesc, nullptr);

    // Define execution configuration
    dim3 threadsPerBlock(16, 16);
    dim3 blocksPerGrid((width + threadsPerBlock.x - 1) / threadsPerBlock.x,
                       (height + threadsPerBlock.y - 1) / threadsPerBlock.y);

    // Launch the kernel
    textureFetchKernel<<<blocksPerGrid, threadsPerBlock>>>(texObject, deviceOutput, width, height);
    cudaDeviceSynchronize();

    // Transfer results back to host
    float *hostResult = new float[width * height];
    cudaMemcpy(hostResult, deviceOutput, bytes, cudaMemcpyDeviceToHost);

    // Release resources
    cudaDestroyTextureObject(texObject);
    cudaFree(deviceInput);
    cudaFree(deviceOutput);
    delete[] hostResult;

    return 0;
}

