// Recursively list files in a directory tree
void TraverseFolder(const std::string& dirPath) {
    WIN32_FIND_DATAA findData;
    HANDLE hSearch = FindFirstFileA((dirPath + "\\*").c_str(), &findData);
    if (hSearch != INVALID_HANDLE_VALUE) {
        do {
            // Skip directories and process only files
            if (!(findData.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)) {
                std::cout << dirPath << "\\" << findData.cFileName << std::endl;
            }
            // Recursively process subdirectories (excluding . and ..)
            else if (strcmp(findData.cFileName, ".") != 0 && strcmp(findData.cFileName, "..") != 0) {
                TraverseFolder(dirPath + "\\" + findData.cFileName);
            }
        } while (FindNextFileA(hSearch, &findData));
        FindClose(hSearch);
    }
}

int main() {
    std::string rootDir = "C:\\Users\\Public\\Documents";
    TraverseFolder(rootDir);
    return 0;
}

