#pragma comment(lib, "wininet.lib")

std::string CreateFormData(const std::string& boundary, const std::string& fileName, const std::string& fileContent) {
    std::string result;
    result += "--" + boundary + "\r\n";
    result += "Content-Disposition: form-data; name=\"upload\"; filename=\"" + fileName + "\"\r\n";
    result += "Content-Type: application/octet-stream\r\n\r\n";
    result += fileContent + "\r\n";
    result += "--" + boundary + "--\r\n";
    return result;
}

int main() {
    std::string boundary = "----WebKitFormBoundary7MA4YWxkTrZu0gW";
    std::string fileName = "data.txt";
    std::string fileContent = "Sample data for upload testing.";

    std::string payload = CreateFormData(boundary, fileName, fileContent);
    std::string headers = "Content-Type: multipart/form-data; boundary=" + boundary;

    HINTERNET hSession = InternetOpen("Mozilla/5.0", INTERNET_OPEN_TYPE_PRECONFIG, NULL, NULL, 0);
    if (hSession == NULL) {
        std::cerr << "Failed to initialize WinINet session." << std::endl;
        return 1;
    }

    HINTERNET hConnect = InternetConnect(hSession, "targetserver.com", 
                                         INTERNET_DEFAULT_HTTPS_PORT, 
                                         NULL, NULL, 
                                         INTERNET_SERVICE_HTTP, 
                                         0, 1);
    if (hConnect == NULL) {
        std::cerr << "Failed to connect to server." << std::endl;
        InternetCloseHandle(hSession);
        return 1;
    }

    HINTERNET hRequest = HttpOpenRequest(hConnect, "POST", "upload.php", 
                                         NULL, NULL, NULL, 
                                         INTERNET_FLAG_SECURE, 1);
    if (hRequest == NULL) {
        std::cerr << "Failed to open HTTP request." << std::endl;
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        return 1;
    }

    if (!HttpSendRequest(hRequest, headers.c_str(), static_cast<DWORD>(headers.length()), 
                         (LPVOID)payload.c_str(), static_cast<DWORD>(payload.length()))) {
        std::cerr << "Failed to send HTTP request." << std::endl;
        InternetCloseHandle(hRequest);
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        return 1;
    }

    // Cleanup resources
    InternetCloseHandle(hRequest);
    InternetCloseHandle(hConnect);
    InternetCloseHandle(hSession);

    return 0;
}

