// Read the time-stamp counter using rdtscp instruction
static unsigned long long read_tsc(void)
{
    unsigned int high_val, low_val;
    __asm__ __volatile__("rdtscp" : "=d"(high_val), "=a"(low_val));
    return ((unsigned long long)low_val) | (((unsigned long long)high_val) << 32);
}

