#include <iostream>
#include <unordered_map>
#include <list>
#include <memory>

template <typename T>
class DoublyLinkedCache {
private:
    struct Element {
        T data;
        std::shared_ptr<Element> previous;
        std::shared_ptr<Element> next;
    };

    std::shared_ptr<Element> start;
    std::shared_ptr<Element> end;
    std::unordered_map<T, std::shared_ptr<Element>> lookup;
    std::list<T> recent;

public:
    DoublyLinkedCache() : start(nullptr), end(nullptr) {}

    // Add to the beginning
    void prepend(const T& item) {
        auto new_element = std::make_shared<Element>(Element{item, nullptr, start});
        if (start) {
            start->previous = new_element;
        } else {
            end = new_element;
        }
        start = new_element;
        lookup[item] = new_element;
        recent.push_front(item);
    }

    // Add to the end
    void append(const T& item) {
        auto new_element = std::make_shared<Element>(Element{item, end, nullptr});
        if (end) {
            end->next = new_element;
        } else {
            start = new_element;
        }
        end = new_element;
        lookup[item] = new_element;
        recent.push_front(item);
    }

    // Remove from the beginning
    void remove_first() {
        if (!start) return;
        auto old_start = start;
        start = start->next;
        if (start) {
            start->previous = nullptr;
        } else {
            end = nullptr;
        }
        lookup.erase(old_start->data);
        recent.remove(old_start->data);
    }

    // Remove from the end
    void remove_last() {
        if (!end) return;
        auto old_end = end;
        end = end->previous;
        if (end) {
            end->next = nullptr;
        } else {
            start = nullptr;
        }
        lookup.erase(old_end->data);
        recent.remove(old_end->data);
    }

    // Search by value
    std::shared_ptr<Element> search(const T& item) {
        auto iter = lookup.find(item);
        if (iter != lookup.end()) {
            recent.push_front(item);
            return iter->second;
        }
        return nullptr;
    }

    // Display the list
    void show() const {
        auto current = start;
        while (current) {
            std::cout << current->data << " ";
            current = current->next;
        }
        std::cout << std::endl;
    }
};

int main() {
    DoublyLinkedCache<int> cache;
    cache.prepend(10);
    cache.prepend(20);
    cache.append(30);
    cache.append(40);

    cache.show(); // Output: 20 10 30 40

    cache.remove_first();
    cache.remove_last();

    cache.show(); // Output: 10 30

    auto element = cache.search(30);
    if (element) {
        std::cout << "Value found: " << element->data << std::endl; // Output: Value found: 30
    }

    return 0;
}

#include <coroutine>
#include <iostream>
#include <string>

template <class U>
struct seq_generator {
    struct promise_impl;
    using coro_ref = std::coroutine_handle<promise_impl>;

    struct promise_impl {
        U current_item;
        auto get_return_object() { return seq_generator{coro_ref::from_promise(*this)}; }
        auto initial_suspend() { return std::suspend_always{}; }
        auto final_suspend() { return std::suspend_always{}; }
        void unhandled_exception() { std::terminate(); }
        auto yield_value(U value) {
            current_item = value;
            return std::suspend_always{};
        }
        auto yield_value() {
            return std::suspend_always{};
        }
    };

    bool advance() { return coro ? (coro.resume(), !coro.done()) : false; }
    U retrieve() { return coro.promise().current_item; }

    seq_generator(seq_generator const & rhs) = delete;
    seq_generator(seq_generator &&rhs)
        : coro(rhs.coro)
    {
        rhs.coro = nullptr;
    }
    ~seq_generator() {
        if (coro)
            coro.destroy();
    }
private:
    seq_generator(coro_ref h) : coro(h) {}
    coro_ref coro;
};

class char_duplicator {
public:
    struct promise_impl {
        std::string text_data;
        std::string::iterator pos;

        auto get_return_object() { return char_duplicator{std::coroutine_handle<promise_impl>::from_promise(*this)}; }
        auto initial_suspend() { return std::suspend_always{}; }
        auto final_suspend() { return std::suspend_always{}; }
        void unhandled_exception() { std::terminate(); }
        auto yield_value(char val) {
            return std::suspend_always{};
        }

        void assign_text(const std::string& str) {
            text_data = str;
            pos = text_data.begin();
        }
    };

    bool advance() {
        if (handle && !handle.done()) {
            handle.resume();
            return !handle.done();
        }
        return false;
    }

    char fetch() {
        return handle.promise().current_item;
    }

private:
    std::coroutine_handle<promise_impl> handle;
    char current_item;

    char_duplicator(std::coroutine_handle<promise_impl> h) : handle(h) {}
    friend struct promise_impl;
};

char_duplicator duplicate_chars() {
    std::string text_data;
    char current_item;

    for (;;) {
        co_await std::suspend_always{};
        for (auto iter = text_data.begin(); iter != text_data.end(); iter++) {
            current_item = *iter * 2; // Double the character value
            co_yield current_item;
        }
    }
}

int main() {
    char_duplicator generator_obj = duplicate_chars();
    generator_obj.promise().assign_text("test data");

    while (generator_obj.advance()) {
        std::cout << generator_obj.fetch() << ' ';
    }
    std::cout << std::endl;

    generator_obj.promise().assign_text("xyz");
    while (generator_obj.advance()) {
        std::cout << generator_obj.fetch() << ' ';
    }
    std::cout << std::endl;

    return 0;
}

