    AVStream* audio_avstream = nullptr;

    for (unsigned int idx = 0; idx < input_format_ctx->nb_streams; ++idx) {
        if (input_format_ctx->streams[idx]->codecpar->codec_type == AVMEDIA_TYPE_VIDEO) {
            video_stream_idx = idx;
            video_avstream = input_format_ctx->streams[idx];
        } else if (input_format_ctx->streams[idx]->codecpar->codec_type == AVMEDIA_TYPE_AUDIO) {
            audio_stream_idx = idx;
            audio_avstream = input_format_ctx->streams[idx];
        }
    }

    if (video_stream_idx == -1 || audio_stream_idx == -1) {
        std::cerr << "Required video or audio stream missing" << std::endl;
        return 1;
    }

    // Initialize video decoder
    AVCodec* video_decoder = avcodec_find_decoder(video_avstream->codecpar->codec_id);
    if (!video_decoder) {
        std::cerr << "Video decoder not available" << std::endl;
        return 1;
    }

    AVCodecContext* video_dec_ctx = avcodec_alloc_context3(video_decoder);
    if (!video_dec_ctx) {
        std::cerr << "Could not allocate video codec context" << std::endl;
        return 1;
    }

    if (avcodec_parameters_to_context(video_dec_ctx, video_avstream->codecpar) < 0) {
        std::cerr << "Failed to copy video codec parameters" << std::endl;
        return 1;
    }

    if (avcodec_open2(video_dec_ctx, video_decoder, nullptr) < 0) {
        std::cerr << "Failed to open video decoder" << std::endl;
        return 1;
    }

    // Initialize audio decoder
    AVCodec* audio_decoder = avcodec_find_decoder(audio_avstream->codecpar->codec_id);
    if (!audio_decoder) {
        std::cerr << "Audio decoder not found" << std::endl;
        return 1;
    }

    AVCodecContext* audio_dec_ctx = avcodec_alloc_context3(audio_decoder);
    if (!audio_dec_ctx) {
        std::cerr << "Could not allocate audio codec context" << std::endl;
        return 1;
    }

    if (avcodec_parameters_to_context(audio_dec_ctx, audio_avstream->codecpar) < 0) {
        std::cerr << "Failed to copy audio codec parameters" << std::endl;
        return 1;
    }

    if (avcodec_open2(audio_dec_ctx, audio_decoder, nullptr) < 0) {
        std::cerr << "Failed to open audio decoder" << std::endl;
        return 1;
    }

    // Setup RTP output context
    AVFormatContext* rtp_output_ctx = nullptr;
    char rtp_url_buffer[1024];

    snprintf(rtp_url_buffer, sizeof(rtp_url_buffer), "rtp://localhost:%d?pkt_size=%d", 
             destination_port, MAX_RTP_PACKET_SIZE);

    status = avformat_alloc_output_context2(&rtp_output_ctx, nullptr, "rtp", rtp_url_buffer);
    if (status < 0 || !rtp_output_ctx) {
        std::cerr << "RTP output context initialization failed" << std::endl;
        return 1;
    }

    // Create video stream in RTP output
    AVStream* rtp_video_stream = avformat_new_stream(rtp_output_ctx, nullptr);
    if (!rtp_video_stream) {
        std::cerr << "Failed to create RTP video stream" << std::endl;
        return 1;
    }

    rtp_video_stream->codecpar->codec_id = AV_CODEC_ID_H264;
    rtp_video_stream->codecpar->bit_rate = VIDEO_BITRATE_TARGET;
    rtp_video_stream->codecpar->width = video_avstream->codecpar->width;
    rtp_video_stream->codecpar->height = video_avstream->codecpar->height;
    rtp_video_stream->codecpar->format = video_avstream->codecpar->format;
    rtp_video_stream->time_base = video_avstream->time_base;
    rtp_video_stream->id = 0;

    // Create audio stream in RTP output
    AVStream* rtp_audio_stream = avformat_new_stream(rtp_output_ctx, nullptr);
    if (!rtp_audio_stream) {
        std::cerr << "Failed to create RTP audio stream" << std::endl;
        return 1;
    }

    rtp_audio_stream->codecpar->codec_id = AV_CODEC_ID_AAC;
    rtp_audio_stream->codecpar->sample_rate = AUDIO_SAMPLERATE_TARGET;
    rtp_audio_stream->codecpar->channels = AUDIO_CHANNEL_COUNT;
    rtp_audio_stream->codecpar->channel_layout = av_get_default_channel_layout(AUDIO_CHANNEL_COUNT);
    rtp_audio_stream->codecpar->format = AV_SAMPLE_FMT_FLTP;
    rtp_audio_stream->time_base = audio_avstream->time_base;
    rtp_audio_stream->id = 1;

    // Open output URL
    status = avio_open(&rtp_output_ctx->pb, rtp_url_buffer, AVIO_FLAG_WRITE);
    if (status < 0) {
        std::cerr << "Error opening RTP output destination" << std::endl;
        return 1;
    }

    // Write header
    AVDictionary* format_options = nullptr;
    av_dict_set(&format_options, "sdp_file", "transmission.sdp", 0);

    status = avformat_write_header(rtp_output_ctx, &format_options);
    if (status < 0) {
        std::cerr << "Header writing error" << std::endl;
        return 1;
    }

    // Allocate frame and packet for processing
    AVFrame* decoded_frame = av_frame_alloc();
    AVPacket input_packet;
    av_init_packet(&input_packet);
    input_packet.data = nullptr;
    input_packet.size = 0;

    // Main processing loop
    while (av_read_frame(input_format_ctx, &input_packet) >= 0) {
        if (input_packet.stream_index == video_stream_idx) {
            transmit_rtp_data(rtp_output_ctx, &input_packet, 0);
        } else if (input_packet.stream_index == audio_stream_idx) {
            transmit_rtp_data(rtp_output_ctx, &input_packet, 1);
        }

        av_packet_unref(&input_packet);
        std::this_thread::sleep_for(std::chrono::duration<double>(1.0 / VIDEO_FRAMERATE_TARGET));
    }

    // Cleanup resources
    av_write_trailer(rtp_output_ctx);
    avformat_close_input(&input_format_ctx);
    avformat_free_context(rtp_output_ctx);
    av_frame_free(&decoded_frame);
    avcodec_free_context(&video_dec_ctx);
    avcodec_free_context(&audio_dec_ctx);

    return 0;
}

void transmit_rtp_data(AVFormatContext* rtp_context, AVPacket* pkt, int stream_id)
{
    int usable_payload_space = MAX_RTP_PACKET_SIZE - 12; // Subtract RTP header size

    uint8_t* data_pointer = pkt->data;
    int bytes_remaining = pkt->size;

    while (bytes_remaining > 0) {
        int chunk_size = std::min(usable_payload_space, bytes_remaining);
        AVPacket rtp_chunk;
        av_init_packet(&rtp_chunk);

        rtp_chunk.size = chunk_size;
        rtp_chunk.data = data_pointer;
        rtp_chunk.stream_index = stream_id;

        av_interleaved_write_frame(rtp_context, &rtp_chunk);

        data_pointer += chunk_size;
        bytes_remaining -= chunk_size;
    }
}

