// Check if a number is prime
bool checkPrime(int value) {
    if(value < 2)
        return false;
    for(int j = 2; j <= sqrt(value); j++)
        if(value % j == 0)
            return false;
    return true;
}

// Compute the product of all digits in a number
int multiplyDigits(int num) {
    int result = 1;
    while (num != 0) {
        result *= num % 10;
        num /= 10;
    }
    return result;
}

// Find the smallest prime in the list and return the product of its digits
int getMinPrimeDigitProduct(vector<int>& arr) {
    vector<int> primes;
    for(int element: arr) {
        if(checkPrime(element)) {
            primes.push_back(element);
        }
    }
    if(primes.empty())
        return -1;
    auto smallest = min_element(primes.begin(), primes.end());
    return multiplyDigits(*smallest);
}

int main() {
    vector<int> data = {0, 3, 2, 1, 3, 5, 7, 4, 5, 5, 5, 2, 181, 32, 4, 32, 3, 2, 32, 324, 4, 3};
    int output = getMinPrimeDigitProduct(data);
    cout << "The product of the digits of the smallest prime number is: " << output << endl;
    return 0;
}

