class MyObject : public QObject {
        Q_OBJECT
        Q_PROPERTY(QQmlListProperty<int> dataKeys READ getDataKeys NOTIFY dataKeysChanged)

    public:
        MyObject(QObject *parent = nullptr) : QObject(parent) {}

        QQmlListProperty<int> getDataKeys() {
            return QQmlListProperty<int>(this, this, &MyObject::addDataKey, &MyObject::getDataKeyCount, &MyObject::getDataKeyAt, &MyObject::clearDataKeys);
        }

    signals:
        void dataKeysChanged();

    private:
        QList<int> m_dataKeys;

        static void addDataKey(QQmlListProperty<int> *property, int value) {
            MyObject *obj = qobject_cast<MyObject *>(property->object);
            if (obj) {
                obj->m_dataKeys.append(value);
                emit obj->dataKeysChanged();
            }
        }

        static int getDataKeyCount(QQmlListProperty<int> *property) {
            MyObject *obj = qobject_cast<MyObject *>(property->object);
            return obj ? obj->m_dataKeys.size() : 0;
        }

        static int getDataKeyAt(QQmlListProperty<int> *property, int position) {
            MyObject *obj = qobject_cast<MyObject *>(property->object);
            return obj ? obj->m_dataKeys.at(position) : 0;
        }

        static void clearDataKeys(QQmlListProperty<int> *property) {
            MyObject *obj = qobject_cast<MyObject *>(property->object);
            if (obj) {
                obj->m_dataKeys.clear();
                emit obj->dataKeysChanged();
            }
        }
    };

