#include <iostream>
#include <stack>
#include <string>
#include <cctype>
#include <stdexcept>

// Function to perform basic arithmetic operations
double executeCalculation(double x, double y, char operation) {
    switch (operation) {
        case '+': return x + y;
        case '-': return x - y;
        case '*': return x * y;
        case '/': 
            if (y == 0) throw std::runtime_error("Division by zero");
            return x / y;
        default: throw std::runtime_error("Invalid operator");
    }
}

// Function to evaluate the expression
double computeExpression(const std::string& expr) {
    std::stack<double> operands;
    std::stack<char> operators;

    for (size_t pos = 0; pos < expr.length(); pos++) {
        if (expr[pos] == ' ') continue; // Skip spaces

        // If the current character is a digit, read the full number
        if (std::isdigit(expr[pos]) || (expr[pos] == '-' && (pos == 0 || std::isspace(expr[pos-1])))) {
            double value = 0;
            bool isNegative = expr[pos] == '-';
            if (isNegative) pos++;
            while (pos < expr.length() && std::isdigit(expr[pos])) {
                value = value * 10 + (expr[pos] - '0');
                pos++;
            }
            if (isNegative) value = -value;
            operands.push(value);
            pos--; // Adjust for the while loop increment
        } else if (expr[pos] == '(') {
            operators.push(expr[pos]);
        } else if (expr[pos] == ')') {
            while (!operators.empty() && operators.top() != '(') {
                double secondOperand = operands.top(); operands.pop();
                double firstOperand = operands.top(); operands.pop();
                char op = operators.top(); operators.pop();
                operands.push(executeCalculation(firstOperand, secondOperand, op));
            }
            operators.pop(); // Pop '('
        } else if (expr[pos] == '+' || expr[pos] == '-' || expr[pos] == '*' || expr[pos] == '/') {
            while (!operators.empty() && ((expr[pos] != '*' && expr[pos] != '/') || (operators.top() == '*' || operators.top() == '/'))) {
                double secondOperand = operands.top(); operands.pop();
                double firstOperand = operands.top(); operands.pop();
                char op = operators.top(); operators.pop();
                operands.push(executeCalculation(firstOperand, secondOperand, op));
            }
            operators.push(expr[pos]);
        } else {
            throw std::runtime_error("Invalid character in expression");
        }
    }

    // Apply any remaining operations
    while (!operators.empty()) {
        double secondOperand = operands.top(); operands.pop();
        double firstOperand = operands.top(); operands.pop();
        char op = operators.top(); operators.pop();
        operands.push(executeCalculation(firstOperand, secondOperand, op));
    }

    return operands.top();
}

int main() {
    std::string expression = "3 + 5 * (2 - 4)";
    try {
        double result = computeExpression(expression);
        std::cout << "Result: " << result << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}

#include <iostream>
