using namespace std;

// Function to find the longest alternating up-down subsequence
int maxAlternatingSubseq(vector<int>& arr) {
    int size = arr.size();
    if (size <= 1) {
        return size;
    }

    // inc[i] represents length of longest alternating subsequence ending at i with increasing step
    // dec[i] represents length of longest alternating subsequence ending at i with decreasing step
    vector<int> inc(size, 1);
    vector<int> dec(size, 1);

    int result = 1;
    for (int idx = 1; idx < size; idx++) {
        for (int prev = 0; prev < idx; prev++) {
            if (arr[idx] > arr[prev]) {
                inc[idx] = max(inc[idx], dec[prev] + 1);
            } else if (arr[idx] < arr[prev]) {
                dec[idx] = max(dec[idx], inc[prev] + 1);
            }
        }
        result = max(result, max(inc[idx], dec[idx]));
    }

    return result;
}

