    int elements;
    cin >> elements;

    vector<int> data(elements);
    for (int pos = 0; pos < elements; pos++) {
        cin >> data[pos];
    }

    int answer = maxAlternatingSubseq(data);
    cout << answer << endl;

    return 0;
}

#include <iostream>
using namespace std;

const int SIZE = 9;

// Display the Sudoku board
void displayBoard(char board[SIZE][SIZE]) {
    for (int row = 0; row < SIZE; row++) {
        for (int col = 0; col < SIZE; col++) {
            cout << board[row][col] << " ";
        }
        cout << endl;
    }
}

// Verify if placing digit 'digit' at position (r, c) is valid
bool isValidPlacement(char board[SIZE][SIZE], int r, int c, char digit) {
    // Check row for duplicate
    for (int i = 0; i < SIZE; i++) {
        if (board[r][i] == digit) {
            return false;
        }
    }

    // Check column for duplicate
    for (int i = 0; i < SIZE; i++) {
        if (board[i][c] == digit) {
            return false;
        }
    }

    // Check 3x3 subgrid for duplicate
    int startRow = (r / 3) * 3;
    int startCol = (c / 3) * 3;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (board[startRow + i][startCol + j] == digit) {
                return false;
            }
        }
    }

    return true;
}

// Solve Sudoku using backtracking
bool solveSudoku(char board[SIZE][SIZE]) {
    int r, c;
    bool foundEmpty = false;

    // Locate an empty cell ('.')
    for (r = 0; r < SIZE; r++) {
        for (c = 0; c < SIZE; c++) {
            if (board[r][c] == '.') {
                foundEmpty = true;
                break;
            }
        }
        if (foundEmpty) {
            break;
        }
    }

    // If no empty cell remains, puzzle is solved
    if (!foundEmpty) {
        return true;
    }

    // Try digits '1' through '9'
    for (char digit = '1'; digit <= '9'; digit++) {
        if (isValidPlacement(board, r, c, digit)) {
            board[r][c] = digit;

            // Recursively attempt to solve remaining puzzle
            if (solveSudoku(board)) {
                return true;
            }

            // Backtrack if current choice doesn't lead to solution
            board[r][c] = '.';
        }
    }

    return false;
}

int main() {
    char board[SIZE][SIZE] = {{'5', '3', '.', '.', '7', '.', '.', '.', '.'},
                              {'6', '.', '.', '1', '9', '5', '.', '.', '.'},
                              {'.', '9', '8', '.', '.', '.', '.', '6', '.'},
                              {'8', '.', '.', '.', '6', '.', '.', '.', '3'},
                              {'4', '.', '.', '8', '.', '3', '.', '.', '1'},
                              {'7', '.', '.', '.', '2', '.', '.', '.', '6'},
                              {'.', '6', '.', '.', '.', '.', '2', '8', '.'},
                              {'.', '.', '.', '4', '1', '9', '.', '.', '5'},
                              {'.', '.', '.', '.', '8', '.', '.', '7', '9'}};

    if (solveSudoku(board)) {
        cout << "Solved Sudoku:" << endl;
        displayBoard(board);
    } else {
        cout << "No valid solution found." << endl;
    }

    return 0;
}

