#include <cstdio>
#include <cwchar>

struct FileData
{
    unsigned char* buffer;
    int size;
};

extern "C" DLLAPI int API_LoadFile(const wchar_t* path, FileData** result)
{
    // Open file in binary mode
    FILE* fp = nullptr;
    errno_t status = _wfopen_s(&fp, path, L"rb");
    if (status != 0 || fp == nullptr)
    {
        return -1; // Failed to open file
    }

    // Determine file size
    fseek(fp, 0, SEEK_END);
    long length = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    // Allocate output structure and data buffer
    *result = new FileData();
    (*result)->buffer = new unsigned char[length];
    (*result)->size = length;

    // Read file contents
    size_t actualRead = fread((*result)->buffer, 1, length, fp);
    fclose(fp);

    // Validate read operation
    if (actualRead != static_cast<size_t>(length))
    {
        delete[] (*result)->buffer;
        delete *result;
        return -2; // Incomplete read
    }

    return 0; // Operation successful
}

extern "C" DLLAPI void API_ReleaseBuffer(FileData* info)
{
    if (info != nullptr)
    {
        delete[] info->buffer;
        delete info;
    }
}

#include <windows.h>
#include <tlhelp32.h>

// Injects a DLL into the specified process
BOOL LoadLibraryIntoProcess(DWORD targetPid, const char* dllFilePath) {
    // Open the target process with full access rights
    HANDLE hTargetProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, targetPid);
    if (hTargetProcess == NULL) {
        return FALSE;
    }

    // Allocate memory in the target process for the DLL path
    LPVOID remoteBuffer = VirtualAllocEx(hTargetProcess, NULL, strlen(dllFilePath) + 1, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (remoteBuffer == NULL) {
        CloseHandle(hTargetProcess);
        return FALSE;
    }

    // Write the DLL path into the allocated memory
    if (!WriteProcessMemory(hTargetProcess, remoteBuffer, (LPVOID)dllFilePath, strlen(dllFilePath) + 1, NULL)) {
        VirtualFreeEx(hTargetProcess, remoteBuffer, 0, MEM_RELEASE);
        CloseHandle(hTargetProcess);
        return FALSE;
    }

    // Get the address of LoadLibraryA from kernel32.dll
    HMODULE hKernel32 = GetModuleHandle("kernel32.dll");
    FARPROC loadLibAddr = GetProcAddress(hKernel32, "LoadLibraryA");

    // Create a remote thread to call LoadLibraryA with the DLL path
    HANDLE hRemoteThread = CreateRemoteThread(hTargetProcess, NULL, 0, 
        (LPTHREAD_START_ROUTINE)loadLibAddr, remoteBuffer, 0, NULL);
    if (hRemoteThread == NULL) {
        VirtualFreeEx(hTargetProcess, remoteBuffer, 0, MEM_RELEASE);
        CloseHandle(hTargetProcess);
        return FALSE;
    }

    // Wait for the remote thread to complete
    WaitForSingleObject(hRemoteThread, INFINITE);

    // Retrieve the exit code of the remote thread (return value of LoadLibraryA)
    DWORD resultCode;
    GetExitCodeThread(hRemoteThread, &resultCode);

    // Clean up resources
    CloseHandle(hRemoteThread);
    VirtualFreeEx(hTargetProcess, remoteBuffer, 0, MEM_RELEASE);
    CloseHandle(hTargetProcess);

    return (resultCode != 0);
}

