// Compute the nth Fibonacci number using iterative approach
int fibonacci(int position) {
    if (position == 0) return 0;
    if (position == 1) return 1;

    int prev = 0, curr = 1, nextVal;
    for (int index = 2; index <= position; ++index) {
        nextVal = prev + curr;
        prev = curr;
        curr = nextVal;
    }
    return curr;
}

int main() {
    int n = 10;
    std::cout << "Fibonacci value at index " << n << " is " << fibonacci(n) << std::endl;
    return 0;
}

