using namespace std;

// Compute optimal value for 0/1 Knapsack using tabulation approach
int solveKnapsack(int capacity, vector<int> weights, vector<int> profits, int itemCount) {
    vector<vector<int>> dpTable(itemCount + 1, vector<int>(capacity + 1));

    // Fill the DP table iteratively from base cases to final solution
    for (int itemIdx = 0; itemIdx <= itemCount; itemIdx++) {
        for (int currentWeight = 0; currentWeight <= capacity; currentWeight++) {
            if (itemIdx == 0 || currentWeight == 0)
                dpTable[itemIdx][currentWeight] = 0;
            else if (weights[itemIdx - 1] <= currentWeight)
                dpTable[itemIdx][currentWeight] = max(
                    profits[itemIdx - 1] + dpTable[itemIdx - 1][currentWeight - weights[itemIdx - 1]],
                    dpTable[itemIdx - 1][currentWeight]
                );
            else
                dpTable[itemIdx][currentWeight] = dpTable[itemIdx - 1][currentWeight];
        }
    }

    // The bottom-right cell contains the maximum achievable profit
    return dpTable[itemCount][capacity];
}

int main() {
    vector<int> profits = {75, 130, 150};
    vector<int> weights = {12, 24, 36};
    int maxCapacity = 60;
    int numItems = profits.size();

    cout << "Optimal knapsack value: " << solveKnapsack(maxCapacity, weights, profits, numItems) << endl;

    return 0;
}

