// Function to extract query parameters from a URL into a map
std::unordered_map<std::string, std::string> extractQueryParams(const std::string& urlString)
{
    std::unordered_map<std::string, std::string> paramMap;

    // Locate the start of query string
    size_t questionMarkPos = urlString.find("?");
    if (questionMarkPos != std::string::npos) {
        std::string queryString = urlString.substr(questionMarkPos + 1);

        // Process each key-value pair separated by '&'
        size_t currentIndex = 0;
        while (currentIndex < queryString.length()) {
            size_t nextAmpersand = queryString.find("&", currentIndex);
            if (nextAmpersand == std::string::npos)
                nextAmpersand = queryString.length();

            std::string segment = queryString.substr(currentIndex, nextAmpersand - currentIndex);

            // Split segment into key and value using '='
            size_t equalsSign = segment.find("=");
            if (equalsSign != std::string::npos) {
                std::string paramKey = segment.substr(0, equalsSign);
                std::string paramValue = segment.substr(equalsSign + 1);

                // Perform basic URL decoding: replace %20 with space
                size_t percentIndex = paramValue.find("%20");
                while (percentIndex != std::string::npos) {
                    paramValue.replace(percentIndex, 3, " ");
                    percentIndex = paramValue.find("%20", percentIndex + 1);
                }

                paramMap[paramKey] = paramValue;
            }

            currentIndex = nextAmpersand + 1;
        }
    }

    return paramMap;
}

int main()
{
    std::string testUrl = "http://www.example.com?name=Jane%20Smith&department=Engineering&location=Los%20Angeles";

    std::unordered_map<std::string, std::string> parsedData = extractQueryParams(testUrl);

    // Display all extracted parameters
    for (const auto& entry : parsedData) {
        std::cout << entry.first << ": " << entry.second << std::endl;
    }

    return 0;
}

#include <SFML/Graphics.hpp>
