// Game configuration constants
const int SCREEN_WIDTH = 800;
const int SCREEN_HEIGHT = 600;
const float PADDLE_VELOCITY = 5.0f;
const float BALL_SIZE = 10.0f;
const float BALL_RATE = 3.0f;

class Racket {
public:
    sf::RectangleShape body;
    float rate;

    Racket(float x, float y, float w, float h, float v) {
        body.setPosition(x, y);
        body.setSize({w, h});
        body.setFillColor(sf::Color::White);
        rate = v;
    }

    void goUp() {
        sf::Vector2f currentPos = body.getPosition();
        if (currentPos.y > 0) {
            body.move(0, -rate);
        }
    }

    void goDown() {
        sf::Vector2f currentPos = body.getPosition();
        if (currentPos.y + body.getSize().y < SCREEN_HEIGHT) {
            body.move(0, rate);
        }
    }
};

class Sphere {
public:
    sf::CircleShape body;
    sf::Vector2f motion;
    float velocity;

    Sphere(float x, float y, float r) {
        body.setPosition(x, y);
        body.setRadius(r);
        body.setFillColor(sf::Color::White);
        motion = {1.0f, 1.0f};
        velocity = BALL_RATE;
    }

    void refresh() {
        sf::Vector2f currentPos = body.getPosition();
        currentPos += motion * velocity;

        // Horizontal collision with walls
        if (currentPos.x <= 0 || currentPos.x + 2 * BALL_SIZE >= SCREEN_WIDTH) {
            motion.x = -motion.x;
        }

        // Vertical collision with top/bottom
        if (currentPos.y <= 0 || currentPos.y + 2 * BALL_SIZE >= SCREEN_HEIGHT) {
            motion.y = -motion.y;
        }

        body.setPosition(currentPos);
    }
};

int main() {
    sf::RenderWindow display(sf::VideoMode(SCREEN_WIDTH, SCREEN_HEIGHT), "Pong");

    Racket leftRacket(50, SCREEN_HEIGHT / 2 - 50, 20, 100, PADDLE_VELOCITY);
    Racket rightRacket(SCREEN_WIDTH - 70, SCREEN_HEIGHT / 2 - 50, 20, 100, PADDLE_VELOCITY);
    Sphere ball(SCREEN_WIDTH / 2 - BALL_SIZE, SCREEN_HEIGHT / 2 - BALL_SIZE, BALL_SIZE);

    while (display.isOpen()) {
        sf::Event action;
        while (display.pollEvent(action)) {
            if (action.type == sf::Event::Closed)
                display.close();
        }

        // Player 1 controls
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::W)) leftRacket.goUp();
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::S)) leftRacket.goDown();

        // Simple AI for Player 2
        if (ball.body.getPosition().y > rightRacket.body.getPosition().y + 50) rightRacket.goDown();
        if (ball.body.getPosition().y < rightRacket.body.getPosition().y + 50) rightRacket.goUp();

        ball.refresh();

        display.clear(sf::Color::Black);
        display.draw(leftRacket.body);
        display.draw(rightRacket.body);
        display.draw(ball.body);
        display.display();
    }

    return 0;
}

#include <algorithm>
#include <cmath>

struct TreeNode {
    int value;
    int depth;
    TreeNode* leftChild;
    TreeNode* rightChild;
};

// Function to compute the depth of a subtree
int getDepth(TreeNode* T) {
    if (T == nullptr)
        return 0;
    return T->depth;
}

// Function to allocate and initialize a new tree node
TreeNode* createNode(int value) {
    TreeNode* newNodePtr = new TreeNode();
    newNodePtr->value = value;
    newNodePtr->leftChild = nullptr;
    newNodePtr->rightChild = nullptr;
    newNodePtr->depth = 1; // Newly inserted node starts as a leaf
    return newNodePtr;
}

// Function to perform a right rotation on the subtree rooted at 'parent'
TreeNode* rotateRight(TreeNode* parent) {
    TreeNode* child = parent->leftChild;
    TreeNode* subtree = child->rightChild;

    // Perform rotation
    child->rightChild = parent;
    parent->leftChild = subtree;

    // Update depths
    parent->depth = std::max(getDepth(parent->leftChild), getDepth(parent->rightChild)) + 1;
    child->depth = std::max(getDepth(child->leftChild), getDepth(child->rightChild)) + 1;

    // Return new root of this subtree
    return child;
}

// Function to perform a left rotation on the subtree rooted at 'parent'
TreeNode* rotateLeft(TreeNode* parent) {
    TreeNode* child = parent->rightChild;
    TreeNode* subtree = child->leftChild;

    // Perform rotation
    child->leftChild = parent;
    parent->rightChild = subtree;

    // Update depths
    parent->depth = std::max(getDepth(parent->leftChild), getDepth(parent->rightChild)) + 1;
    child->depth = std::max(getDepth(child->leftChild), getDepth(child->rightChild)) + 1;

    // Return new root of this subtree
    return child;
}

// Compute balance factor for a given node
int getBalanceFactor(TreeNode* node) {
    if (node == nullptr)
        return 0;
    return getDepth(node->leftChild) - getDepth(node->rightChild);
}

// Insert a value into the AVL tree
TreeNode* addValue(TreeNode* root, int value) {
    // Standard BST insertion
    if (root == nullptr)
        return createNode(value);

    if (value < root->value)
        root->leftChild = addValue(root->leftChild, value);
    else if (value > root->value)
        root->rightChild = addValue(root->rightChild, value);
    else // Duplicate values are not permitted
        return root;

    // Update depth of current ancestor node
    root->depth = 1 + std::max(getDepth(root->leftChild), getDepth(root->rightChild));

    // Check balance factor
    int balance = getBalanceFactor(root);

    // Handle four possible imbalance cases

    // Left Left Case
    if (balance > 1 && value < root->leftChild->value)
        return rotateRight(root);

    // Right Right Case
    if (balance < -1 && value > root->rightChild->value)
        return rotateLeft(root);

    // Left Right Case
    if (balance > 1 && value > root->leftChild->value) {
        root->leftChild = rotateLeft(root->leftChild);
        return rotateRight(root);
    }

    // Right Left Case
    if (balance < -1 && value < root->rightChild->value) {
        root->rightChild = rotateRight(root->rightChild);
        return rotateLeft(root);
    }

    // Return unchanged node pointer if balanced
    return root;
}

#include <iostream>
using namespace std;
#define SIZE 9

// Function to display the Sudoku board
void displayBoard(int board[SIZE][SIZE]) {
    for (int r = 0; r < SIZE; r++) {
        for (int c = 0; c < SIZE; c++)
            cout << board[r][c] << " ";
        cout << endl;
    }
}

// Function to verify if placing a value at position is valid
bool isValidPlacement(int board[SIZE][SIZE], int row, int col, int value) {
    // Check if the value already exists in the current row
    for (int i = 0; i < SIZE; i++)
        if (board[row][i] == value)
            return false;

    // Check if the value already exists in the current column
    for (int i = 0; i < SIZE; i++)
        if (board[i][col] == value)
            return false;

    // Check if the value already exists in the current 3x3 sub-grid
    int startRow = row - row % 3;
    int startCol = col - col % 3;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            if (board[i + startRow][j + startCol] == value)
                return false;

    return true;
}

// Function to solve the Sudoku puzzle using backtracking
bool solveSudoku(int board[SIZE][SIZE]) {
    int row, col;
    bool foundEmpty = false;

    // Find the first empty cell (represented by 0)
    for (row = 0; row < SIZE; row++) {
        for (col = 0; col < SIZE; col++) {
            if (board[row][col] == 0) {
                foundEmpty = true;
                break;
            }
        }
        if (foundEmpty)
            break;
    }

    // If no empty cell is found, the puzzle is solved
    if (!foundEmpty)
        return true;

    // Try placing digits from 1 to 9 in the empty cell
    for (int num = 1; num <= 9; num++) {
        if (isValidPlacement(board, row, col, num)) {
            board[row][col] = num;
            if (solveSudoku(board))
                return true;
            board[row][col] = 0; // backtrack if solution not found
        }
    }
    return false;
}

// Main function
int main() {
    int puzzle[SIZE][SIZE];

    // Read the Sudoku puzzle from input
    cout << "Enter the Sudoku puzzle (0 for empty cells):\n";
    for (int r = 0; r < SIZE; r++)
        for (int c = 0; c < SIZE; c++)
            cin >> puzzle[r][c];

    // Solve the Sudoku puzzle
    if (solveSudoku(puzzle)) {
        cout << "Sudoku puzzle solved!\n";
        displayBoard(puzzle);
    } else {
        cout << "No solution exists!\n";
    }

    return 0;
}

