// Find the index of the maximum element in a vector
int locateMaxElementIndex(const std::vector<int>& data) {
    if (data.empty()) {
        return -1; // Return -1 for empty input
    }
    int bestIndex = 0;
    for (size_t pos = 1; pos < data.size(); ++pos) {
        if (data[pos] > data[bestIndex]) {
            bestIndex = static_cast<int>(pos);
        }
    }
    return bestIndex;
}

