const char* mqtt_token = "your_MQTT_password";

// Topic names for sensor data
const char* topic_temp = "home/air_quality/temperature";
const char* topic_humid = "home/air_quality/humidity";
const char* topic_pres = "home/air_quality/pressure";
const char* topic_co2_val = "home/air_quality/co2";

// Sensor objects
Adafruit_BME280 bme_sensor;
MH_Z19 co2_sensor(Serial2);

WiFiClient esp_client;
PubSubClient mqtt_client(esp_client);

void setup() {
  Serial.begin(115200);
  WiFi.begin(wifi_ssid, wifi_pass);

  while (WiFi.status() != WL_CONNECTED) {
    delay(1000);
    Serial.println("Establishing WiFi connection...");
  }

  Serial.println("WiFi connected successfully");

  mqtt_client.setServer(mqtt_broker, mqtt_port_num);
  mqtt_client.setCallback(message_handler);

  while (!mqtt_client.connected()) {
    Serial.println("Connecting to MQTT server...");
    if (mqtt_client.connect("ESP32Client", mqtt_username, mqtt_token)) {
      Serial.println("MQTT connection established");
    } else {
      Serial.print("Connection failed with error code ");
      Serial.print(mqtt_client.state());
      delay(2000);
    }
  }

  // Initialize BME280 sensor
  if (!bme_sensor.begin(0x76)) {
    Serial.println("BME280 sensor not detected. Verify wiring.");
    while (1);
  }
}

void loop() {
  if (!mqtt_client.connected()) {
    reconnect_mqtt();
  }
  mqtt_client.loop();

  // Acquire sensor readings
  float temp_reading = bme_sensor.readTemperature();
  float humid_reading = bme_sensor.readHumidity();
  float pressure_kPa = bme_sensor.readPressure() / 100.0F;
  int co2_ppm = co2_sensor.getCO2();

  // Send data via MQTT
  mqtt_client.publish(topic_temp, String(temp_reading).c_str());
  mqtt_client.publish(topic_humid, String(humid_reading).c_str());
  mqtt_client.publish(topic_pres, String(pressure_kPa).c_str());
  mqtt_client.publish(topic_co2_val, String(co2_ppm).c_str());

  delay(5000); // Wait for 5 seconds before next reading
}

void reconnect_mqtt() {
  while (!mqtt_client.connected()) {
    Serial.println("Attempting MQTT reconnection...");
    if (mqtt_client.connect("ESP32Client", mqtt_username, mqtt_token)) {
      Serial.println("Reconnected to MQTT server");
    } else {
      Serial.print("Reconnection failed with state ");
      Serial.print(mqtt_client.state());
      delay(2000);
    }
  }
}

void message_handler(char* topic_name, byte* data_buffer, unsigned int data_length) {
  Serial.print("Received message on [");
  Serial.print(topic_name);
  Serial.print("]: ");
  for (unsigned int idx = 0; idx < data_length; idx++) {
    Serial.print((char)data_buffer[idx]);
  }
  Serial.println();
}

