uint_8 GFXUTIL_GetNearestPaletteIndex(const uint_8* palette, size_t size, uint_8 red, uint_8 green, uint_8 blue)
{
    if(palette == NULL || size == 0)
        return 0;

    uint_8 bestIndex = 0;
    int smallestDistance = INT_MAX;

    for(size_t index = 0; index < size; ++index)
    {
        int diffRed = palette[0] - red;
        int diffGreen = palette[1] - green;
        int diffBlue = palette[2] - blue;
        int currentDistance = (diffRed * diffRed) + (diffGreen * diffGreen) + (diffBlue * diffBlue);

        if(currentDistance < smallestDistance)
        {
            bestIndex = index;
            smallestDistance = currentDistance;
        }

        palette += 3; // Advance to next RGB entry
    }

    return bestIndex;
}

#include <stdio.h>

// Helper function to compare and swap elements depending on sorting direction
__device__ void exchangeElements(int *data, int pos1, int pos2, int sortDirection) {
    if ((data[pos1] > data[pos2] && sortDirection == 1) || 
        (data[pos1] < data[pos2] && sortDirection == 0)) {
        int buffer = data[pos1];
        data[pos1] = data[pos2];
        data[pos2] = buffer;
    }
}

// Device kernel for merging bitonic sequences
__global__ void mergeBitonic(int *data, int totalSize, int segmentSize, int order) {
    int index = threadIdx.x + blockIdx.x * blockDim.x;
    int half = segmentSize / 2;

    if (index < totalSize && (index / segmentSize) % 2 == order) {
        if ((index / half) % 2 == 0) {
            exchangeElements(data, index, index + half, order);
        }
    }
}

// Device kernel for sorting bitonic sequences
__global__ void sortBitonic(int *data, int totalSize, int segmentSize, int order) {
    int index = threadIdx.x + blockIdx.x * blockDim.x;
    int half = segmentSize / 2;

    if (index < totalSize) {
        for(int step = half; step > 0; step /= 2) {
            int partner = index ^ step;

            if (partner > index) {
                if ((index & segmentSize) == 0) {
                    exchangeElements(data, index, partner, order);
                } else {
                    exchangeElements(data, index, partner, !order);
                }
            }

            __syncthreads();
        }
    }
}

// Host function to perform parallel bitonic sort using CUDA
void parallelBitonicSort(int *inputArray, int size) {
    int *gpu_array;

    int bytes = size * sizeof(int);

    cudaMalloc((void**)&gpu_array, bytes);
    cudaMemcpy(gpu_array, inputArray, bytes, cudaMemcpyHostToDevice);

    dim3 grid(ceil(size / 256.0), 1, 1);
    dim3 block(256, 1, 1);

    for (int segmentSize = 2; segmentSize <= size; segmentSize *= 2) {
        for (int order = 1; order >= 0; order--) {
            sortBitonic <<<grid, block>>> (gpu_array, size, segmentSize, order);
        }
    }

    cudaMemcpy(inputArray, gpu_array, bytes, cudaMemcpyDeviceToHost);
    cudaFree(gpu_array);
}

// Sequential implementation of bitonic sorting algorithm
void sequentialBitonicSort(int *inputArray, int size) {
    for (int segmentSize = 2; segmentSize <= size; segmentSize *= 2) {
        for (int order = 1; order >= 0; order--) {
            for (int i = 0; i < size; i++) {
                if ((i & segmentSize) == 0) {
                    for (int j = 0; j < segmentSize / 2; j++) {
                        int k = i ^ (j << 1);
                        if (k < size) {
                            exchangeElements(inputArray, i, k, order);
                        }
                    }
                }
            }
        }
    }
}

int main() {
    int size = 16;
    int data[size] = {12, 9, 15, 6, 10, 8, 5, 13, 7, 11, 14, 4, 1, 3, 2, 0};

    printf("Initial Array:\n");
    for (int idx = 0; idx < size; idx++) {
        printf("%d ", data[idx]);
    }

