using namespace std;

// Structure representing a connection in the graph
struct Connection {
    int destination;  // Target node
    int cost;         // Cost of the edge
};

// Function to insert an edge into the adjacency list
void insertEdge(vector<vector<Connection>>& adjacencyList, int source, int target, int weight) {
    adjacencyList[source].emplace_back(target, weight);
}

// Dijkstra's algorithm to compute shortest paths from start to all reachable nodes
vector<int> computeShortestPath(const vector<vector<Connection>>& adjacencyList, int origin, int target) {
    int numberOfNodes = adjacencyList.size();
    vector<int> distances(numberOfNodes, numeric_limits<int>::max());
    vector<int> predecessors(numberOfNodes, -1);
    distances[origin] = 0;

    // Min-heap priority queue storing (distance, node)
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> minHeap;
    minHeap.emplace(0, origin);

    while (!minHeap.empty()) {
        int currentNode = minHeap.top().second;
        int currentDistance = minHeap.top().first;
        minHeap.pop();

        // Early exit if we reached the target
        if (currentNode == target) break;

        // Skip if we've already found a better path
        if (currentDistance > distances[currentNode]) continue;

        // Explore neighbors and relax edges
        for (const Connection& conn : adjacencyList[currentNode]) {
            int neighbor = conn.destination;
            int edgeCost = conn.cost;
            if (distances[currentNode] + edgeCost < distances[neighbor]) {
                distances[neighbor] = distances[currentNode] + edgeCost;
                predecessors[neighbor] = currentNode;
                minHeap.emplace(distances[neighbor], neighbor);
            }
        }
    }

    // Reconstruct the shortest path from origin to target
    vector<int> path;
    for (int node = target; node != -1; node = predecessors[node]) {
        path.push_back(node);
    }
    reverse(path.begin(), path.end());

    return path;
}

int main() {
    // Graph definition: 5 nodes labeled 0 through 4
    int nodeCount = 5;
    vector<vector<Connection>> adjacencyList(nodeCount);

    // Populate graph with weighted directed edges
    insertEdge(adjacencyList, 0, 1, 10);
    insertEdge(adjacencyList, 0, 2, 5);
    insertEdge(adjacencyList, 1, 2, 2);
    insertEdge(adjacencyList, 1, 3, 1);
    insertEdge(adjacencyList, 2, 1, 3);
    insertEdge(adjacencyList, 2, 3, 9);
    insertEdge(adjacencyList, 2, 4, 2);
    insertEdge(adjacencyList, 3, 4, 4);

    // Compute shortest path from node 0 to node 4
    vector<int> shortestPath = computeShortestPath(adjacencyList, 0, 4);

    // Output the resulting path
    cout << "Shortest path: ";
    for (int node : shortestPath) {
        cout << node << " ";
    }
    cout << endl;

    return 0;
}

