// Find the maximum value in an integer array
int findMaxValue(int data[], int length) {
    if (length == 0) {
        return INT_MIN;  // Return the smallest possible integer if the array is empty
    }
    int maxVal = data[0];
    for (int index = 1; index < length; ++index) {
        if (data[index] > maxVal) {
            maxVal = data[index];
        }
    }
    return maxVal;
}

int main() {
    int numbers[] = {3, 5, 1, 8, 2};
    int count = sizeof(numbers) / sizeof(numbers[0]);
    std::cout << "The largest number is: " << findMaxValue(numbers, count) << std::endl;
    return 0;
}

