template<class ComponentType, typename... Parameters>
ComponentType* ECS::AddComponent(const uint32_t entityID, Parameters&&... parameters) {
    auto componentTypeID = Component<ComponentType>::GetTypeID();

    if (componentMasks[entityID].HasComponent(componentTypeID)) {
        return nullptr; // Entity already has this component type
    }

    componentMasks[entityID].AddComponent(componentTypeID);
    Archetype* targetArchetype = nullptr;
    ComponentType* componentPtr = nullptr;

    Record& recordRef = entityArchetypeMap[entityID];
    Archetype* previousArchetype = recordRef.archetype;

    targetArchetype = GetOrCreateArchetype(entityID);

    if (previousArchetype) {
        MigrateEntityToArchetype(targetArchetype, previousArchetype, entityID, std::forward<Parameters>(parameters)...);
    } else {
        AddFirstComponentToEntity(targetArchetype, entityID, componentTypeID, recordRef, std::forward<Parameters>(parameters)...);
    }

    return componentPtr;
}

