// Perform in-place quicksort on the given vector
void sortArray(std::vector<int>& data, int start, int end) {
    if (start < end) {
        int midValue = data[(start + end) / 2];
        int low = start, high = end;
        while (low <= high) {
            while (data[low] < midValue) low++;
            while (data[high] > midValue) high--;
            if (low <= high) {
                std::swap(data[low], data[high]);
                low++;
                high--;
            }
        }
        if (start < high) sortArray(data, start, high);
        if (low < end) sortArray(data, low, end);
    }
}

int main() {
    std::vector<int> values = {3, 6, 8, 10, 1, 2, 1};
    sortArray(values, 0, values.size() - 1);
    for (int element : values) {
        std::cout << element << " ";
    }
    return 0;
}

