// Handles component data operations for entity-component-system architecture
class ComponentDataManager {
public:
    // Copies component data from one archetype to another and cleans up source
    static void MoveAndCleanupComponent(const ComponentBase* baseComponent, Archetype* sourceArch, Archetype* destArch, size_t srcOffset, size_t dstOffset) {
        std::size_t componentByteSize = baseComponent->GetComponentSize();
        std::size_t currentCapacity = destArch->entityCount * componentByteSize;

        baseComponent->CopyData(&sourceArch->dataBuffer[srcOffset], &destArch->dataBuffer[dstOffset]);
        baseComponent->ReleaseData(&sourceArch->dataBuffer[srcOffset]);
    }

    // Exchanges component data between two positions within the same archetype
    static void ExchangeComponentData(const ComponentBase* baseComponent, Archetype* archetype, size_t offset, size_t posA, size_t posB) {
        std::size_t elementSize = baseComponent->GetComponentSize();

        baseComponent->CopyData(&archetype->dataBuffer[offset] + posA * elementSize, 
                               &archetype->dataBuffer[offset] + posB * elementSize);
        baseComponent->ReleaseData(&archetype->dataBuffer[offset] + posA * elementSize);
    }

    // Transfers component data between archetypes while maintaining internal consistency
    static void RelocateAndReorderComponents(const ComponentBase* baseComponent, Archetype* sourceArch, Archetype* targetArch, 
                                            size_t srcPos, size_t dstPos, size_t lastEntityPos, size_t targetEntityPos) {
        std::size_t componentByteSize = baseComponent->GetComponentSize();
        size_t targetCapacity = targetArch->entityCount * componentByteSize;

        baseComponent->CopyData(&sourceArch->dataBuffer[srcPos] + targetEntityPos * componentByteSize, 
                               &targetArch->dataBuffer[dstPos] + targetCapacity);

        if (targetEntityPos != lastEntityPos) {
            baseComponent->CopyData(&sourceArch->dataBuffer[srcPos] + lastEntityPos * componentByteSize, 
                                   &sourceArch->dataBuffer[srcPos] + targetEntityPos * componentByteSize);
        }

        baseComponent->ReleaseData(&sourceArch->dataBuffer[srcPos] + lastEntityPos * componentByteSize);
    }
};

