#include <iostream>

// Back-substitution for lower triangular system using loop unrolling
void backsolve(const int* __restrict__ colPtr,
               const int* __restrict__ rowIdx,
               const double* __restrict__ values,
               const int size,
               double* __restrict__ solution) {
    // Process 4 rows at a time with loop unrolling
    for (int i = size - 1; i >= 0; i -= 4) {
        // Update x[i]
        for (int k = colPtr[i]; k < colPtr[i + 1]; ++k) {
            solution[i] -= values[k] * solution[rowIdx[k]];
        }
        // Update x[i-1]
        for (int k = colPtr[i - 1]; k < colPtr[i]; ++k) {
            solution[i - 1] -= values[k] * solution[rowIdx[k]];
        }
        // Update x[i-2]
        for (int k = colPtr[i - 2]; k < colPtr[i - 1]; ++k) {
            solution[i - 2] -= values[k] * solution[rowIdx[k]];
        }
        // Update x[i-3]
        for (int k = colPtr[i - 3]; k < colPtr[i - 2]; ++k) {
            solution[i - 3] -= values[k] * solution[rowIdx[k]];
        }
    }

    // Handle remaining rows (less than 4)
    int remainder = size % 4;
    for (int i = remainder - 1; i >= 0; --i) {
        for (int k = colPtr[i]; k < colPtr[i + 1]; ++k) {
            solution[i] -= values[k] * solution[rowIdx[k]];
        }
    }
}

