// Function to create a numpy array with custom memory management
py::array_t<double> create_numpy_array(const py::ssize_t length) {
    double* buffer = new double[length];
    // Lambda function to handle memory deallocation
    auto cleanup = [](double* ptr) { delete[] ptr; };
