#include <sys/resource.h>
#include <iostream>

int main() {
    double elapsed = 0.0;
    int count = 2000000;
    int iterations = 5;

    struct rusage info;
    struct timeval user_start, user_end, sys_start, sys_end;

    for (int j = 0; j < iterations; j++) {
        getrusage(RUSAGE_SELF, &info);
        user_start = info.ru_utime;
        sys_start = info.ru_stime;

        for (int idx = 0; idx < count; idx++) continue;

        getrusage(RUSAGE_SELF, &info);
        user_end = info.ru_utime;
        sys_end = info.ru_stime;

        double user_time = user_end.tv_sec + user_end.tv_usec / 1e6;
        double sys_time = sys_end.tv_sec + sys_end.tv_usec / 1e6;
        double start_time = user_start.tv_sec + user_start.tv_usec / 1e6 + sys_start.tv_sec + sys_start.tv_usec / 1e6;

        elapsed += ((user_time + sys_time) - start_time) / static_cast<double>(iterations);
    }

    std::cout << elapsed << '\n';

    return 0;
}

