                inputStream.close();
                storage[fileName] = content;
            }
        }
    }

    const std::string& retrieveContent(const std::string& fileName) {
        return storage[fileName];
    }

private:
    DataReader() {}
    std::map<std::string, std::string> storage;
};

extern "C" {
    JNIEXPORT void JNICALL Java_com_example_DataLoader_nativeLoadFile(JNIEnv* env, jobject obj, jstring fileName) {
        const char* path = env->GetStringUTFChars(fileName, nullptr);
        DataReader::getReference().loadContent(path);
        env->ReleaseStringUTFChars(fileName, path);
    }

    JNIEXPORT jstring JNICALL Java_com_example_DataLoader_nativeRetrieveData(JNIEnv* env, jobject obj, jstring fileName) {
        const char* path = env->GetStringUTFChars(fileName, nullptr);
        std::string content = DataReader::getReference().retrieveContent(path);
        env->ReleaseStringUTFChars(fileName, path);
        return env->NewStringUTF(content.c_str());
    }
