   void* create_executable_region(size_t bytes) {
       void *addr = mmap(
           nullptr,
           bytes,
           PROT_READ | PROT_WRITE | PROT_EXEC,
           MAP_PRIVATE | MAP_ANONYMOUS,
           -1,
           0
       );
       if (addr == MAP_FAILED) {
           perror("mmap failed");
           return nullptr;
       }
       return addr;
   };

   void copy_bytes_to_region(size_t len, const unsigned char *src, void *dst) {
       memcpy(static_cast<unsigned char*>(dst), src, len);
   };

   typedef void (*FunctionPtr)();

   int main() {
       // Open the binary file containing machine code
       int file_desc = open("test.bin", O_RDONLY);
       if (file_desc == -1) {
           perror("Failed to open file");
           return 1;
       }

       struct stat file_info;
       if (fstat(file_desc, &file_info) == -1) {
           perror("Failed to get file stats");
           close(file_desc);
           return 1;
       }

       size_t code_size = file_info.st_size;
       unsigned char buffer[code_size];
       if (read(file_desc, buffer, code_size) != (ssize_t)code_size) {
           perror("Failed to read file");
           close(file_desc);
           return 1;
       }
       close(file_desc);

       void *exec_mem = create_executable_region(code_size);
       if (exec_mem == nullptr) {
           return 1;
       }

       copy_bytes_to_region(code_size, buffer, exec_mem);
       FunctionPtr run_code = reinterpret_cast<FunctionPtr>(exec_mem);
       run_code();

       // Release memory
       munmap(exec_mem, code_size);

       return 0;
   }

