sampler2D sourceTexture : register(s0);

// Constants for CRT simulation
float2 screenResolution = float2(1280, 720); // Display resolution configuration
float curvatureFactor = 1.5; // Controls the strength of the curved screen effect

// Function to simulate barrel distortion for screen curvature
float2 applyBarrelDistortion(float2 texCoords, float curvature)
{
    float2 centerPoint = float2(0.5, 0.5);
    texCoords = (texCoords - centerPoint) * (1.0 + curvature * (distance(texCoords, centerPoint)));
    texCoords += centerPoint;
    return texCoords;
}

float4 pixelShaderFunction(float2 uv : TEXCOORD0) : COLOR
{
    // Apply barrel distortion to simulate screen curvature
    float2 distortedUV = applyBarrelDistortion(uv, curvatureFactor);

    // Validate texture coordinates are within bounds [0, 1]
    if (distortedUV.x < 0.0 || distortedUV.x > 1.0 || distortedUV.y < 0.0 || distortedUV.y > 1.0)
        return float4(0.0, 0.0, 0.0, 1.0);

    // Sample the input texture using the distorted coordinates
    float4 sampledColor = tex2D(sourceTexture, distortedUV);

    // Generate scanline effect
    float scanlineDarkness = 0.1;
    float scanlineThickness = 2.0;
    float scanlineSpacing = 4.0;
    float rowNumber = floor(uv.y * screenResolution.y);
    float scanlineFactor = (fmod(rowNumber, scanlineSpacing) < scanlineThickness) ? scanlineDarkness : 1.0;

    // Apply scanline modulation to RGB channels
    sampledColor.rgb *= scanlineFactor;

    return sampledColor;
}

technique CRTRendering
