#include <jni.h>
#include <android/log.h>
#include <google_breakpad/writer/minidump_writer.h>

extern JavaVM* jvm; // Ensure this is properly initialized in your code

#define INFO_LOG(...) __android_log_print(ANDROID_LOG_INFO, "CrashReporter", __VA_ARGS__)
#define ERROR_LOG(...) __android_log_print(ANDROID_LOG_ERROR, "CrashReporter", __VA_ARGS__)

bool crash_handler(const google_breakpad::MinidumpDescriptor& dump_desc, void* user_data, bool success) {
    JNIEnv* env = nullptr;

    // Check if the current thread is attached to the JVM
    jint status = jvm->GetEnv(reinterpret_cast<void**>(&env), JNI_VERSION_1_6);
    if (status == JNI_EDETACHED) {
        if (DEBUG_MODE)
            INFO_LOG("Attaching native thread to JVM...");
        jvm->AttachCurrentThread(&env, nullptr);
    } else if (status == JNI_OK) {
        if (DEBUG_MODE)
            INFO_LOG("Native thread already attached");
    } else {
        if (DEBUG_MODE)
            INFO_LOG("Failed to retrieve JNIEnv");
        return false;
    }

    if (DEBUG_MODE)
        INFO_LOG("Processing crash event");

    jclass CrashHandlerClass = (jclass)env->NewGlobalRef(env->FindClass("com/example/AppExceptionHandler"));
    if (CrashHandlerClass == NULL) {
        ERROR_LOG("Unable to locate Java exception handler class");
        if (status == JNI_EDETACHED) {
            jvm->DetachCurrentThread();
        }
        return false;
    }

    jmethodID CrashHandlerMethod = env->GetStaticMethodID(CrashHandlerClass, "onCrashOccurred", "()V");
    if (CrashHandlerMethod == NULL) {
        ERROR_LOG("Could not find static method 'onCrashOccurred'");
        env->DeleteGlobalRef(CrashHandlerClass);
        if (status == JNI_EDETACHED) {
            jvm->DetachCurrentThread();
        }
        return false;
    }

    // Invoke the Java callback
    env->CallStaticVoidMethod(CrashHandlerClass, CrashHandlerMethod);

    if (env->ExceptionCheck()) {
        INFO_LOG("Java exception detected during crash handling");
        env->ExceptionDescribe();
        env->ExceptionClear(); // Prevent propagation of pending exception
    }

    if (DEBUG_MODE)
        INFO_LOG("Crash event successfully processed");

    env->DeleteGlobalRef(CrashHandlerClass);

    // Detach thread only if we attached it ourselves
    if (status == JNI_EDETACHED) {
        jvm->DetachCurrentThread();
    }

    return true;
}

