// Find the maximum value in an integer array
int findMaximum(int values[], int length) {
    if (length <= 0) {
        std::cerr << "Array length must be positive." << std::endl;
        return INT_MIN; // Return the smallest possible integer as an error indicator
    }

    int highest = values[0]; // Assume the first element is the maximum
    for (int index = 1; index < length; ++index) {
