#include <iostream>
#include <stack>
#include <string>
#include <cctype>
#include <sstream>

// Determine if a character is an arithmetic operator
bool isArithmeticOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Return the precedence level of an operator
int getPrecedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Perform calculation using two operands and an operator
double performOperation(double x, double y, char op) {
    switch (op) {
        case '+': return x + y;
        case '-': return x - y;
        case '*': return x * y;
        case '/': return x / y;
    }
    return 0.0;
}

// Main function to compute the value of an arithmetic expression
double computeExpression(const std::string& expr) {
    std::stack<double> operandStack;
    std::stack<char> operatorStack;

    std::istringstream stream(expr);
    std::string currentToken;

    while (stream >> currentToken) {
        // Check if token is a number
        if (std::all_of(currentToken.begin(), currentToken.end(), ::isdigit)) {
            operandStack.push(std::stod(currentToken));
        } 
        // Handle operators
        else if (isArithmeticOperator(currentToken[0])) {
            char currentOp = currentToken[0];
            while (!operatorStack.empty() && 
                   getPrecedence(operatorStack.top()) >= getPrecedence(currentOp)) {
                double secondOperand = operandStack.top(); operandStack.pop();
                double firstOperand = operandStack.top(); operandStack.pop();
                char operation = operatorStack.top(); operatorStack.pop();
                operandStack.push(performOperation(firstOperand, secondOperand, operation));
            }
            operatorStack.push(currentOp);
        }
    }

    // Process remaining operators
    while (!operatorStack.empty()) {
        double secondOperand = operandStack.top(); operandStack.pop();
        double firstOperand = operandStack.top(); operandStack.pop();
        char operation = operatorStack.top(); operatorStack.pop();
        operandStack.push(performOperation(firstOperand, secondOperand, operation));
    }

    return operandStack.top();
}

int main() {
    std::string inputExpr = "3 + 5 * 2 - 4 / 2";
    double finalResult = computeExpression(inputExpr);
    std::cout << "Computed Value: " << finalResult << std::endl;
