int main() {
    // Create a shared memory object for image data transfer
    const char* shared_mem_name = "/image_buffer_shm";
    int mem_fd = shm_open(shared_mem_name, O_CREAT | O_RDWR, 0666);
    if (mem_fd == -1) {
        perror("shm_open failed");
        return 1;
    }

    // Define image dimensions and calculate total size
    const int width = 640;
    const int height = 480;
    const int channels = 3;
    const size_t buffer_size = width * height * channels;

    // Set the shared memory segment size
    if (ftruncate(mem_fd, buffer_size) == -1) {
        perror("ftruncate");
        return 1;
    }

    // Map the shared memory into the process's address space
    void* mapped_data = mmap(0, buffer_size, PROT_WRITE, MAP_SHARED, mem_fd, 0);
    if (mapped_data == MAP_FAILED) {
        perror("mmap failed");
        return 1;
    }

    // Initialize OpenCV matrix with shared memory as data buffer
    cv::Mat frame(height, width, CV_8UC3, mapped_data);
    cv::VideoCapture camera(0);

    if (!camera.isOpened()) {
        std::cerr << "Failed to open camera" << std::endl;
        munmap(mapped_data, buffer_size);
        close(mem_fd);
        return 1;
    }

    camera >> frame;

    // Clean up resources
    munmap(mapped_data, buffer_size);
    close(mem_fd);

    return 0;
}

