#include <iostream>
#include <array>
#include <chrono>
#include <immintrin.h>

int main() {
    long long accumulator = 0;
    std::array<int, 1024> buffer;
    int* dataPtr = buffer.data();

    for(int idx = 0; idx < 1024; ++idx) {
        dataPtr[idx] = idx;
    }

    auto startTime = std::chrono::high_resolution_clock::now();

    for(int outerLoop = 0; outerLoop < 1024 * 1024 * 10; ++outerLoop) {
        __m256i vectorSum = _mm256_setzero_si256();
        for(int innerIdx = 0; innerIdx < 1024; innerIdx += 8) {
            __m256i chunk = _mm256_loadu_si256(reinterpret_cast<__m256i*>(dataPtr + innerIdx));
            vectorSum = _mm256_add_epi32(vectorSum, chunk);
        }

        long long partial1 = _mm256_extract_epi64(_mm256_slli_epi64(vectorSum, 32), 0) + _mm256_extract_epi64(vectorSum, 0);
        long long partial2 = _mm256_extract_epi64(_mm256_slli_epi64(vectorSum, 32), 1) + _mm256_extract_epi64(vectorSum, 1);
        accumulator += (partial1 + partial2);
    }

    auto endTime = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::micro> duration = endTime - startTime;

    std::cout << "Unrestricted: " << duration.count() << " us, Value = " << accumulator << std::endl;

    return 0;
}

#include <immintrin.h>

struct PixelColor {
    float red, green, blue;
    float GetRed() const { return red; }
    float GetGreen() const { return green; }
    float GetBlue() const { return blue; }
};

struct Vector3D {
    float x, y, z;
    Vector3D operator*(float factor) const {
        return {x * factor, y * factor, z * factor};
    }
    Vector3D operator+(const Vector3D& rhs) const {
        return {x + rhs.x, y + rhs.y, z + rhs.z};
    }
};

Vector3D convertToFloat(const PixelColor& pixel) {
    return {pixel.red, pixel.green, pixel.blue};
}

Vector3D bilinearSample(const PixelColor* buffer, int row1, int row2, int col1, int col2, float posX, float posY, int width) {
#ifdef USE_SIMD
    __m128 p11 = _mm_loadu_ps((float*)&buffer[row1 * width + col1]);
    __m128 p12 = _mm_loadu_ps((float*)&buffer[row2 * width + col1]);
    __m128 p22 = _mm_loadu_ps((float*)&buffer[row2 * width + col2]);
    __m128 p21 = _mm_loadu_ps((float*)&buffer[row1 * width + col2]);

    float w11 = (col2 - posX) * (row2 - posY);
    float w12 = (col2 - posX) * (posY - row1);
    float w22 = (posX - col1) * (posY - row1);
    float w21 = (posX - col1) * (row2 - posY);

    __m128 weight11 = _mm_set1_ps(w11);
    __m128 weight12 = _mm_set1_ps(w12);
    __m128 weight22 = _mm_set1_ps(w22);
    __m128 weight21 = _mm_set1_ps(w21);

    __m128 output = _mm_add_ps(
        _mm_add_ps(
            _mm_mul_ps(p11, weight11),
            _mm_mul_ps(p12, weight12)
        ),
        _mm_add_ps(
            _mm_mul_ps(p21, weight21),
            _mm_mul_ps(p22, weight22)
        )
    );

    Vector3D result;
    _mm_storeu_ps((float*)&result, output);
    return result;
#else
    const Vector3D p11 = convertToFloat(buffer[row1 * width + col1]);
    const Vector3D p12 = convertToFloat(buffer[row2 * width + col1]);
    const Vector3D p22 = convertToFloat(buffer[row2 * width + col2]);
    const Vector3D p21 = convertToFloat(buffer[row1 * width + col2]);

    const Vector3D interpolated =
            p11 * (col2 - posX) * (row2 - posY) +
            p21 * (posX - col1) * (row2 - posY) +
            p12 * (col2 - posX) * (posY - row1) +
            p22 * (posX - col1) * (posY - row1);

    return interpolated;
#endif
}

