#include <iostream>
#include <emmintrin.h>  // SSE2 intrinsics

// Compute minimum and maximum values in an array using SSE2
void computeRangeSSE(const int* inputArray, size_t length, int& minResult, int& maxResult) {
    if (length == 0) return;

    __m128i currentMin = _mm_set1_epi32(inputArray[0]);
    __m128i currentMax = _mm_set1_epi32(inputArray[0]);

    for (size_t idx = 0; idx < length; idx += 4) {
        __m128i loadedVec = _mm_loadu_si128(reinterpret_cast<const __m128i*>(inputArray + idx));
        currentMin = _mm_min_epi32(currentMin, loadedVec);
        currentMax = _mm_max_epi32(currentMax, loadedVec);
    }

    // Reduce vector to scalar for minimum
    currentMin = _mm_min_epi32(currentMin, _mm_shuffle_epi32(currentMin, 0x4E)); // shuffle by 1
    currentMin = _mm_min_epi32(currentMin, _mm_shuffle_epi32(currentMin, 0x1B)); // shuffle by 2
    // Reduce vector to scalar for maximum
    currentMax = _mm_max_epi32(currentMax, _mm_shuffle_epi32(currentMax, 0x4E)); // shuffle by 1
    currentMax = _mm_max_epi32(currentMax, _mm_shuffle_epi32(currentMax, 0x1B)); // shuffle by 2

    minResult = _mm_cvtsi128_si32(currentMin);
    maxResult = _mm_cvtsi128_si32(currentMax);
}

int main() {
    int sampleData[] = {5, 15, 25, 35, 45, 55, 65, 75};
    int minValue, maxValue;
    computeRangeSSE(sampleData, 8, minValue, maxValue);

    std::cout << "Minimum: " << minValue << ", Maximum: " << maxValue << std::endl;

    return 0;
}

#include <cstring> // Added for memcpy

uint8* Gfx::ScreenshotBuffer(int& width, int& height, int& totalBytes) {
    width = IwGxGetDeviceWidth();
    height = IwGxGetDeviceHeight();

    int bytesPerRow = width * 4; // Each pixel is RGBA with 1 byte per channel
    totalBytes = bytesPerRow * height;

    glPixelStorei(GL_UNPACK_ALIGNMENT, 1);
    glPixelStorei(GL_PACK_ALIGNMENT, 1);

    uint8* tempData = new uint8[totalBytes];
    glReadPixels(0, 0, width, height, GL_RGBA, GL_UNSIGNED_BYTE, tempData);

    // Verify no OpenGL errors occurred
    GLenum glError = glGetError();
    if (glError != GL_NO_ERROR) {
        IwTrace(GFX, (IwString("OpenGL error: 0x%04x"), glError));
    }

    // Vertically flip the image data
    uint8* resultBuffer = new uint8[totalBytes];
    for (int rowIndex = 0; rowIndex < height; ++rowIndex) {
        std::memcpy(resultBuffer + (height - 1 - rowIndex) * bytesPerRow, 
                   tempData + rowIndex * bytesPerRow, 
                   bytesPerRow);
    }

    delete[] tempData;
    return resultBuffer;
}

void Gfx::ScreenshotImage(CIwImage* image, uint8*& bufferRef) {
    int screenWidth, screenHeight, bufferSize;
    bufferRef = ScreenshotBuffer(screenWidth, screenHeight, bufferSize);
    image->SetFormat(CIwImage::ABGR_8888);
    image->SetWidth(screenWidth);
    image->SetHeight(screenHeight);
    image->SetBuffers(bufferRef, bufferSize, 0, 0);
}

