    -0.5f,  0.5f, -0.5f,  1.0f, 0.5f, 1.0f  // Top Left Back
};

unsigned int cubeIndices[] = {
    0, 1, 3,   1, 2, 3, // Front face
    4, 5, 7,   5, 6, 7, // Back face
    0, 1, 5,   0, 5, 4, // Right face
    2, 3, 7,   2, 7, 6, // Left face
    0, 3, 7,   0, 7, 4, // Top face
    1, 2, 6,   1, 6, 5  // Bottom face
};

const char* vertexShaderCode = R"(
#version 330 core
layout (location = 0) in vec3 position;
layout (location = 1) in vec3 color;

out vec3 vertexColor;

void main()
{
    gl_Position = vec4(position, 1.0);
    vertexColor = color;
}
)";

const char* fragmentShaderCode = R"(
#version 330 core
out vec4 outputColor;
in vec3 vertexColor;

void main()
{
    outputColor = vec4(vertexColor, 1.0);
}
)";

unsigned int buildShader(const char* shaderSource, unsigned int shaderType) {
    unsigned int shaderID = glCreateShader(shaderType);
    glShaderSource(shaderID, 1, &shaderSource, nullptr);
    glCompileShader(shaderID);

    int success;
    glGetShaderiv(shaderID, GL_COMPILE_STATUS, &success);
    if (success == GL_FALSE) {
        int logLength;
        glGetShaderiv(shaderID, GL_INFO_LOG_LENGTH, &logLength);
        char* logMessage = (char*)alloca(logLength * sizeof(char));
        glGetShaderInfoLog(shaderID, logLength, &logLength, logMessage);
        std::cout << "Shader compilation failed: " 
                  << (shaderType == GL_VERTEX_SHADER ? "vertex" : "fragment") 
                  << " shader" << std::endl;
        std::cout << logMessage << std::endl;
        glDeleteShader(shaderID);
        return 0;
    }
    return shaderID;
}

unsigned int linkShaderProgram(const char* vsSource, const char* fsSource) {
    unsigned int program = glCreateProgram();
    unsigned int vertexShader = buildShader(vsSource, GL_VERTEX_SHADER);
    unsigned int fragmentShader = buildShader(fsSource, GL_FRAGMENT_SHADER);

    glAttachShader(program, vertexShader);
    glAttachShader(program, fragmentShader);
    glLinkProgram(program);
    glValidateProgram(program);

    glDeleteShader(vertexShader);
    glDeleteShader(fragmentShader);

    return program;
}

int main() {
    // Initialize GLFW
    if (!glfwInit()) {
        std::cerr << "Error: Could not initialize GLFW" << std::endl;
        return -1;
    }

    // Create window and OpenGL context
    GLFWwindow* displayWindow = glfwCreateWindow(800, 600, "3D Cube Renderer", nullptr, nullptr);
    if (!displayWindow) {
        std::cerr << "Error: Could not create GLFW window" << std::endl;
        glfwTerminate();
        return -1;
    }

    // Set context
    glfwMakeContextCurrent(displayWindow);

    // Load OpenGL functions with GLAD
    if (!gladLoadGLLoader((GLADloadproc)glfwGetProcAddress)) {
        std::cerr << "Error: Failed to initialize GLAD" << std::endl;
        return -1;
    }

    // Generate VAO
    unsigned int vao;
    glGenVertexArrays(1, &vao);
    glBindVertexArray(vao);

    // Generate VBO
    unsigned int vbo;
    glGenBuffers(1, &vbo);
    glBindBuffer(GL_ARRAY_BUFFER, vbo);
    glBufferData(GL_ARRAY_BUFFER, sizeof(cubeVertices), cubeVertices, GL_STATIC_DRAW);

    // Generate EBO
    unsigned int ebo;
    glGenBuffers(1, &ebo);
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, ebo);
    glBufferData(GL_ELEMENT_ARRAY_BUFFER, sizeof(cubeIndices), cubeIndices, GL_STATIC_DRAW);

    // Setup vertex attributes
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 6 * sizeof(float), (void*)0);
    glEnableVertexAttribArray(0);
    glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, 6 * sizeof(float), (void*)(3 * sizeof(float)));
    glEnableVertexAttribArray(1);

    // Compile shader program
    unsigned int shaderProgram = linkShaderProgram(vertexShaderCode, fragmentShaderCode);
    glUseProgram(shaderProgram);

    // Main rendering loop
    while (!glfwWindowShouldClose(displayWindow)) {
        // Handle input
        if (glfwGetKey(displayWindow, GLFW_KEY_ESCAPE) == GLFW_PRESS)
            glfwSetWindowShouldClose(displayWindow, true);

        // Clear screen
        glClearColor(0.2f, 0.3f, 0.3f, 1.0f);
        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

        // Draw cube
        glUseProgram(shaderProgram);
        glBindVertexArray(vao);
        glDrawElements(GL_TRIANGLES, 36, GL_UNSIGNED_INT, 0);

        // Update window
        glfwSwapBuffers(displayWindow);
        glfwPollEvents();
    }

    // Release resources
    glDeleteVertexArrays(1, &vao);
    glDeleteBuffers(1, &vbo);
    glDeleteBuffers(1, &ebo);
    glDeleteProgram(shaderProgram);

    // Shutdown GLFW
    glfwTerminate();
    return 0;
}

