using namespace std;

// Compute the median for each sliding window of size k
vector<double> computeSlidingMedian(vector<int>& data, int windowSize) {
    multiset<double> currentWindow(data.begin(), data.begin() + windowSize);
    vector<double> medians;

    auto calculateMedian = [&currentWindow, windowSize]() -> double {
        auto it = currentWindow.begin();
        advance(it, windowSize / 2);
        if (windowSize % 2 == 0) {
            double value1 = *it;
            double value2 = *prev(it);
            return (value1 + value2) / 2.0;
        } else {
            return *it;
        }
    };

    medians.push_back(calculateMedian());

    for (int index = windowSize; index < data.size(); ++index) {
        // Remove the element exiting the window
        currentWindow.erase(currentWindow.find(data[index - windowSize]));
        // Add the new element entering the window
        currentWindow.insert(data[index]);
        // Calculate and store the new median
        medians.push_back(calculateMedian());
    }

    return medians;
}

int main() {
    vector<int> inputNumbers = {1, 3, -1, -3, 5, 3, 6, 7};
    int windowWidth = 3;
    vector<double> expectedOutput = {1, -1, -1, 3, 5, 6};
    vector<double> actualResult = computeSlidingMedian(inputNumbers, windowWidth);

    assert(actualResult == expectedOutput);
    cout << "All tests passed!" << endl;

    return 0;
}

#include <iostream>
