// Compute the sum of integers from 0 to n-1
unsigned long long computeSum(unsigned long long limit)
{
    unsigned long long accumulator = 0;

    for (unsigned long long index = 0; index < limit; index++)
        accumulator += index;

    return accumulator;
}

int main()
{
    LARGE_INTEGER frequency, startTime, endTime;
    QueryPerformanceFrequency(&frequency);
    QueryPerformanceCounter(&startTime);

    unsigned long long result = computeSum(1000000000ULL);

    QueryPerformanceCounter(&endTime);
    double duration = (double)(endTime.QuadPart - startTime.QuadPart) / frequency.QuadPart * 1000.0;

    printf("Result: %llu\n", result);
    printf("Delta: %f ms\n", duration);

    return 0;
}

