std::vector<char> base64_decode(const std::string& input) {
    int length = input.size();
    int pos = 0;
    int count = 0;
    int index = 0;
    unsigned char buffer_4[4], buffer_3[3];
    std::vector<char> result;

    while (length-- && (input[index] != '=') && std::isalnum(input[index])) {
        unsigned char ch = static_cast<unsigned char>(input[index]);
        int value = (ch >= 'A' && ch <= 'Z') ? (ch - 'A') : 
                    (ch >= 'a' && ch <= 'z') ? (ch - 'a' + 26) : 
                    (ch >= '0' && ch <= '9') ? (ch - '0' + 52) : 
                    (ch == '+') ? 62 : 63;
        buffer_4[pos++] = static_cast<unsigned char>(value);

        if (pos == 4) {
            buffer_3[0] = (buffer_4[0] << 2) | ((buffer_4[1] & 0x30) >> 4);
            buffer_3[1] = ((buffer_4[1] & 0x0F) << 4) | ((buffer_4[2] & 0x3C) >> 2);
            buffer_3[2] = ((buffer_4[2] & 0x03) << 6) | buffer_4[3];

            for (pos = 0; pos < 3; pos++)
                result.push_back(static_cast<char>(buffer_3[pos]));
            pos = 0;
        }
        index++;
    }

    if (pos > 0) {
        for (count = pos; count < 4; count++)
            buffer_4[count] = 0;

        buffer_3[0] = (buffer_4[0] << 2) | ((buffer_4[1] & 0x30) >> 4);
        buffer_3[1] = ((buffer_4[1] & 0x0F) << 4) | ((buffer_4[2] & 0x3C) >> 2);
        buffer_3[2] = ((buffer_4[2] & 0x03) << 6) | buffer_4[3];

        for (count = 0; count < pos - 1; count++)
            result.push_back(static_cast<char>(buffer_3[count]));
    }

    return result;
}

#include <QCoreApplication>
#include <QByteArray>
#include <QDebug>

quint16 computeChecksum(QByteArray buffer)
{
    quint16 checksum = 0xFFFF; // starting value

    for (int index = 0; index < buffer.length(); ++index) {
        checksum ^= (quint16)buffer.at(index) << 8;
        for (int bit = 0; bit < 8; ++bit) {
            if (checksum & 0x8000) {
                checksum = (checksum << 1) ^ 0x1021; // generator polynomial
            } else {
                checksum <<= 1;
            }
        }
    }

    return checksum;
}

int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);

    QByteArray message("Hello World");
    quint16 result = computeChecksum(message);

    qDebug() << "Checksum: 0x" << QString::number(result, 16);

    return app.exec();
}

