struct WirelessSignal {
  double transmitPower; // in dBm
  double carrierFreq;
  double channelBandwidth;
};

class FullbandSpectrumSynthesizer {
public:
  // Constructor
  FullbandSpectrumSynthesizer(double minFreq, double maxFreq, double samplingRate, double baselineNoise, double signalToNoise, std::vector<WirelessSignal> txSignals) :
    m_minFreq(minFreq), m_maxFreq(maxFreq), m_samplingRate(samplingRate), m_baselineNoise(baselineNoise), m_signalToNoise(signalToNoise), m_txSignals(txSignals) {}

  // Synthesize the power spectrum across the specified frequency band
  std::vector<double> synthesize() {
    // Establish frequency grid
    double deltaFreq = m_samplingRate / m_spectrumLength;
    std::vector<double> frequencyGrid(m_spectrumLength);
    for (size_t idx = 0; idx < frequencyGrid.size(); ++idx) {
      frequencyGrid[idx] = m_minFreq + idx * deltaFreq;
    }

    // Create baseline noise contribution
    std::vector<double> noiseFloor = synthesizeNoiseFloor(frequencyGrid);

    // Add each transmitter's contribution
    for (const WirelessSignal& tx : m_txSignals) {
      std::vector<double> txContribution = synthesizeTxSpectrum(tx, frequencyGrid);
      for (size_t idx = 0; idx < m_spectrumLength; ++idx) {
        m_fullSpectrum[idx] += txContribution[idx];
      }
    }

    // Combine with noise floor
    for (size_t idx = 0; idx < m_spectrumLength; ++idx) {
      m_fullSpectrum[idx] += noiseFloor[idx];
    }

    return m_fullSpectrum;
  }

private:
  double m_minFreq; // Lower bound of frequency range
  double m_maxFreq; // Upper bound of frequency range
  double m_samplingRate; // Sampling frequency
  double m_baselineNoise; // Baseline noise level in dBm
  double m_signalToNoise; // Target SNR in dB
  std::vector<WirelessSignal> m_txSignals; // Transmitters to model
  size_t m_spectrumLength = 1024; // Number of frequency bins
  std::vector<double> m_fullSpectrum = std::vector<double>(m_spectrumLength, m_baselineNoise); // Initialize with noise floor

  // Synthesize spectrum for a single transmitter
  std::vector<double> synthesizeTxSpectrum(const WirelessSignal& tx, const std::vector<double>& freqs) {
    std::vector<double> txSpectrum(m_spectrumLength, 0.0);
    for (size_t idx = 0; idx < m_spectrumLength; ++idx) {
      double f = freqs[idx];
      if (f >= tx.carrierFreq - tx.channelBandwidth / 2 && f <= tx.carrierFreq + tx.channelBandwidth / 2) {
        double p_watts = dBmToWatts(tx.transmitPower);
        double n_watts = p_watts / dBToRatio(m_signalToNoise);

        std::complex<double> txComplex = createTxComplex(p_watts, f);
        std::complex<double> noiseComplex = createNoiseComplex(n_watts);
        std::complex<double> combined = txComplex + noiseComplex;

        double magnitude = std::abs(combined);
        double magnitudeDbm = WattsTodBm(magnitude);
        double psd = WattsTodBm(magnitude / m_samplingRate) - 30.0;

        txSpectrum[idx] = psd;
      }
    }
    return txSpectrum;
  }

  // Synthesize noise floor across frequency bins
  std::vector<double> synthesizeNoiseFloor(const std::vector<double>& freqs) {
    std::vector<double> noiseFloor(m_spectrumLength);
    double baseNoiseWatts = dBmToWatts(m_baselineNoise);
    for (size_t idx = 0; idx < m_spectrumLength; ++idx) {
      double noiseSample = generateNoiseSample(baseNoiseWatts);
      double psd = WattsTodBm(noiseSample / m_samplingRate) - 30.0;
      noiseFloor[idx] = psd;
    }
    return noiseFloor;
  }

  // Generate noise sample with given power
  double generateNoiseSample(double power) {
    std::normal_distribution<double> dist(0.0, std::sqrt(power));
    double realPart = dist(m_randomEngine);
    double imagPart = dist(m_randomEngine);
    std::complex<double> complexNoise(realPart, imagPart);
    return std::norm(complexNoise);
  }

  // Create complex baseband representation of a signal
  std::complex<double> createTxComplex(double power, double frequency) {
    double phase = m_uniformDist(m_randomEngine) * 2.0 * M_PI;
    double amplitude = std::sqrt(dBmToWatts(power));
    double realComponent = amplitude * std::cos(2.0 * M_PI * frequency / m_samplingRate + phase);
    double imagComponent = amplitude * std::sin(2.0 * M_PI * frequency / m_samplingRate + phase);
    return std::complex<double>(realComponent, imagComponent);
  }

  // Create complex noise sample from given power
  std::complex<double> createNoiseComplex(double power) {
    std::normal_distribution<double> dist(0.0, std::sqrt(dBmToWatts(power)));
    double realPart = dist(m_randomEngine);
    double imagPart = dist(m_randomEngine);
    return std::complex<double>(realPart, imagPart);
  }

  // Convert dBm to watts
  double dBmToWatts(double dbm) {
    return std::pow(10.0, dbm / 10.0 - 3.0);
  }

  // Convert watts to dBm
  double WattsTodBm(double w) {
    return 10.0 * std::log10(w * 1000.0);
  }

  // Convert dB to linear ratio
  double dBToRatio(double db) {
    return std::pow(10.0, db / 10.0);
  }

  std::mt19937 m_randomEngine; // Mersenne Twister RNG
  std::uniform_real_distribution<double> m_uniformDist{0.0, 1.0}; // Uniform distribution for phase
};

