// Check if a number is a power of two using bitwise operation
template<typename T>
inline bool check_power_of_two(const T value) {
    if (__builtin_expect(value == 0, false)) {
        return false;
    }
    T temp = value & (value - 1);
    return __builtin_expect(temp == 0, true);
}

