class ExpressionEvaluator {
public:
    ExpressionEvaluator(const std::string& input) : expr(input) {}

    double compute() {
        if (expr.empty()) {
            throw std::invalid_argument("Input expression is empty");
        }
        return parseExpression(0, expr.length() - 1);
    }

private:
    std::string expr;

    double parseExpression(int left, int right) {
        std::stack<double> values;
        std::stack<char> ops;
        int num = 0;
        char lastOp = '+';

        for (int idx = left; idx <= right; ++idx) {
            if (std::isdigit(expr[idx])) {
                num = num * 10 + (expr[idx] - '0');
            } else if (expr[idx] == '(') {
                int end = idx;
                int balance = 1;
                while (balance != 0 && ++end <= right) {
                    if (expr[end] == '(') ++balance;
                    if (expr[end] == ')') --balance;
                }
                num = parseExpression(idx + 1, end - 1);
                idx = end - 1;
            }

            // Process when encountering an operator or at the end
            if ((idx == right || (!std::isdigit(expr[idx]) && !std::isspace(expr[idx]))) && 
                (lastOp != '\0')) {
                performOperation(values, lastOp, num);
                num = 0;
                if (isArithmeticOperator(expr[idx])) {
                    lastOp = expr[idx];
                }
            }
        }

        return values.top();
    }

    void performOperation(std::stack<double>& values, char operation, double operand) {
        switch (operation) {
            case '+': values.push(operand); break;
            case '-': values.push(-operand); break;
            case '*': values.top() *= operand; break;
            case '/':
                if (operand == 0.0) throw std::runtime_error("Division by zero");
                values.top() /= operand;
                break;
            default: throw std::invalid_argument("Unsupported operator");
        }
    }

    bool isArithmeticOperator(char symbol) {
        return symbol == '+' || symbol == '-' || symbol == '*' || symbol == '/';
    }
};

int main() {
    try {
        ExpressionEvaluator evaluator("3 + 5 * (10 - 4) / 2");
        std::cout << "Result: " << evaluator.compute() << std::endl;
    } catch (const std::exception& error) {
        std::cerr << "Error: " << error.what() << std::endl;
    }
    return 0;
}

