template <typename T>
struct has_fmap : std::false_type {};

// Specialization for List type
template <typename T>
struct has_fmap<List<T>> : std::true_type {};

// Function template to apply a transformation to a functor
template <typename Func, typename Container, typename ResultType>
constexpr auto transform(Func func, Container& container) {
    static_assert(has_fmap<Container>::value, "Container must support fmap operation");
    return container.fmap(func);
}

// Custom List class implementation
template <typename Element>
class List {
private:
    std::vector<Element> elements;
public:
    explicit List(int size) : elements(size) {}
    List(const List& source) : elements(source.elements) {}
    ~List() = default;

    Element& operator[](int index) { return elements[index]; }
    const Element& operator[](int index) const { return elements[index]; }

    // Apply function to each element and return new List
    template <typename NewType>
    List<NewType> fmap(std::function<NewType(Element)> operation) {
        List<NewType> output(elements.size());
        for (int idx = 0; idx < elements.size(); ++idx) {
            output[idx] = operation(elements[idx]);
        }
        return output;
    }
};

