int main()
{
    PyObject *module_name, *loaded_module, *module_dict, *callable_func;

    setenv("PYTHONDONTWRITEBYTECODE", " ", 1);

    // Initialize the Python Interpreter
    Py_Initialize();

    // CALL FUNCTION FROM FOLDER 1:
    std::wstring dirPathWide = L"./Folder 1";
    std::string dirPath = std::string(dirPathWide.begin(), dirPathWide.end());

    // Append the directory to the Python path
    PyObject *pythonSysPath = PySys_GetObject((char*)"path");
    PyList_Append(pythonSysPath, PyUnicode_FromString(dirPath.c_str()));

    // Build the module name object
    module_name = PyUnicode_FromString((char*)"python_function");
    // Load the module object
    loaded_module = PyImport_Import(module_name);
    if (loaded_module == NULL) {
        PyErr_Print();
        goto end;
    }
    // module_dict is a borrowed reference
    module_dict = PyModule_GetDict(loaded_module);
    // callable_func is also a borrowed reference
    callable_func = PyDict_GetItemString(module_dict, (char*)"function");

    if (callable_func != NULL)
    {
        if (PyCallable_Check(callable_func))
        {
            PyObject *return_value;

            return_value = PyObject_CallFunction(callable_func, "");
            Py_XDECREF(return_value);
        }
        else {PyErr_Print();}
    }
    else {std::cout << "callable_func is NULL!" << std::endl;}

    // Clean up after the first call
    Py_XDECREF(callable_func);
    Py_XDECREF(module_dict);
    Py_XDECREF(loaded_module);
    Py_XDECREF(module_name);

    // CALL FUNCTION FROM FOLDER 2:
    dirPathWide = L"./Folder 2";
    dirPath = std::string(dirPathWide.begin(), dirPathWide.end());

    // Append the directory to the Python path
    PyList_Append(pythonSysPath, PyUnicode_FromString(dirPath.c_str()));

    // Build the module name object
    module_name = PyUnicode_FromString((char*)"python_function");
    // Load the module object
    loaded_module = PyImport_Import(module_name);
    if (loaded_module == NULL) {
        PyErr_Print();
        goto end;
    }
    // module_dict is a borrowed reference
    module_dict = PyModule_GetDict(loaded_module);
    // callable_func is also a borrowed reference
    callable_func = PyDict_GetItemString(module_dict, (char*)"function");

    if (callable_func != NULL)
    {
        if (PyCallable_Check(callable_func))
        {
            PyObject *return_value;

            return_value = PyObject_CallFunction(callable_func, "");
            Py_XDECREF(return_value);
        }
        else {PyErr_Print();}
    }
    else {std::cout << "callable_func is NULL!" << std::endl;}

end:
    // Final cleanup
    Py_XDECREF(callable_func);
    Py_XDECREF(module_dict);
    Py_XDECREF(loaded_module);
    Py_XDECREF(module_name);

    // Finish the Python Interpreter
    Py_Finalize();

    return 0;
}

