cudaMemcpy(d_loc_y, loc_y, numEntities * sizeof(float), cudaMemcpyHostToDevice);
cudaMemcpy(d_loc_z, loc_z, numEntities * sizeof(float), cudaMemcpyHostToDevice);
cudaMemcpy(d_spd_x, spd_x, numEntities * sizeof(float), cudaMemcpyHostToDevice);
cudaMemcpy(d_spd_y, spd_y, numEntities * sizeof(float), cudaMemcpyHostToDevice);
cudaMemcpy(d_spd_z, spd_z, numEntities * sizeof(float), cudaMemcpyHostToDevice);

// Release host memory
delete[] loc_x;
delete[] loc_y;
delete[] loc_z;
delete[] spd_x;
delete[] spd_y;
delete[] spd_z;

// Device kernel: update positions based on velocities
__global__ void advanceEntities(float* pos_x, float* pos_y, float* pos_z,
                                float* vel_x, float* vel_y, float* vel_z,
                                int entityCount, float stepSize)
{
    int tid = threadIdx.x + blockIdx.x * blockDim.x;
    if (tid < entityCount) {
        pos_x[tid] += vel_x[tid] * stepSize;
        pos_y[tid] += vel_y[tid] * stepSize;
        pos_z[tid] += vel_z[tid] * stepSize;
    }
}

// Configure kernel launch parameters
int threadsPerBlock = 256;
int blocksPerGrid = (numEntities + threadsPerBlock - 1) / threadsPerBlock;
advanceEntities<<<blocksPerGrid, threadsPerBlock>>>(d_loc_x, d_loc_y, d_loc_z,
                                                    d_spd_x, d_spd_y, d_spd_z,
                                                    numEntities, timeStep);

// Retrieve updated data from device
cudaMemcpy(loc_x, d_loc_x, numEntities * sizeof(float), cudaMemcpyDeviceToHost);
cudaMemcpy(loc_y, d_loc_y, numEntities * sizeof(float), cudaMemcpyDeviceToHost);
cudaMemcpy(loc_z, d_loc_z, numEntities * sizeof(float), cudaMemcpyDeviceToHost);

// Free device memory
cudaFree(d_loc_x);
cudaFree(d_loc_y);
cudaFree(d_loc_z);
cudaFree(d_spd_x);
cudaFree(d_spd_y);
cudaFree(d_spd_z);

// Reconstruct structured representation
for (int i = 0; i < numEntities; ++i) {
    entities[i].location.x = loc_x[i];
    entities[i].location.y = loc_y[i];
    entities[i].location.z = loc_z[i];
}

// Final cleanup
delete[] loc_x;
delete[] loc_y;
delete[] loc_z;
delete[] entities;

