struct check_value_in_array
{
    const thrust::device_ptr<int> sorted_data;
    const int size;

    check_value_in_array(thrust::device_ptr<int> sorted_data, int size) : sorted_data(sorted_data), size(size) {}

    __device__ bool operator()(int pos, int target)
    {
        if (pos < size && sorted_data[pos] == target)
        {
            return true;
        }
        return false;
    }
};

int main()
{
    // Sample data for processing
    thrust::host_vector<int> input_sorted = {1, 2, 3, 5, 7, 8, 10};
    thrust::host_vector<int> query_values = {1, 3, 4, 8, 10, 11};

    // Move data to GPU memory
    thrust::device_vector<int> device_sorted = input_sorted;
    thrust::device_vector<int> device_query = query_values;

    // Compute insertion positions using lower_bound
    thrust::device_vector<int> indices(device_query.size());
    thrust::lower_bound(device_sorted.begin(), device_sorted.end(), device_query.begin(), device_query.end(), indices.begin());

    // Determine presence of each queried value
    thrust::device_vector<bool> flags(device_query.size());
    thrust::transform(indices.begin(), indices.end(), device_query.begin(), flags.begin(), check_value_in_array(device_sorted.data(), device_sorted.size()));

    // Transfer results back to host
    thrust::host_vector<int> result_indices = indices;
    thrust::host_vector<bool> result_flags = flags;

    for (size_t idx = 0; idx < query_values.size(); ++idx)
    {
        std::cout << "Element " << query_values[idx] << " located at index " << result_indices[idx] << " (exists: " << result_flags[idx] << ")" << std::endl;
    }

    return 0;
}

