#include <immintrin.h>
#include <algorithm>
#include <array>
#include <inttypes.h>

typedef std::array<uint8_t, 3> ColorRGB;
typedef std::array<int32_t, 3> IntVector3;

ColorRGB applyColorSpread(ColorRGB const& input, ColorRGB output, int32_t amount) {
  // Convert uint8_t arrays to int32_t arrays
  IntVector3 intInput = {input[0], input[1], input[2]};
  IntVector3 intOutput = {output[0], output[1], output[2]};

  // Load the data into SIMD registers
  __m128i srcData = _mm_loadu_si128(reinterpret_cast<const __m128i*>(intInput.data()));
  __m128i dstData = _mm_loadu_si128(reinterpret_cast<const __m128i*>(intOutput.data()));
  __m128i amountVec = _mm_set1_epi32(amount);

  // Find maximum component in source vector
  __m128i maxVal = _mm_max_epi32(srcData, _mm_shuffle_epi32(srcData, 0x4E)); // shuffle with offset 1
  maxVal = _mm_max_epi32(maxVal, _mm_shuffle_epi32(maxVal, 0x1));           // shuffle with offset 2

  // Compute spread adjustment
  __m128i divisor = maxVal;
  __m128i quotient = _mm_div_epi32(srcData, divisor);
  __m128i product = _mm_mullo_epi32(quotient, amountVec);
  __m128i adjusted = _mm_sub_epi32(srcData, product);

  // Ensure result is not less than destination
  adjusted = _mm_max_epi32(adjusted, dstData);

  // Store the computed values back
  _mm_storeu_si128(reinterpret_cast<__m128i*>(intOutput.data()), adjusted);

  // Convert back to uint8_t
  output[0] = static_cast<uint8_t>(intOutput[0]);
  output[1] = static_cast<uint8_t>(intOutput[1]);
  output[2] = static_cast<uint8_t>(intOutput[2]);

  return output;
}

