void writeBuffer(const unsigned char *buffer, size_t length, FILE *outputFile)
{
    size_t chunkSize;

    for (; length > 0; length -= chunkSize, buffer += chunkSize) {
        chunkSize = length;
        if (chunkSize > 1024)
            chunkSize = 1024;
        chunkSize = fwrite(buffer, 1, chunkSize, outputFile);
        if (chunkSize != 1024 && ferror(outputFile)) {
            throw std::runtime_error("Error writing to output stream");
        }
        fflush(outputFile);
    }
}

int main(int argumentCount, char **argumentVector) {
    if (argumentCount < 5) {
        std::cerr << "Usage: " << argumentVector[0] << " totalbytes bytechunk height width" << std::endl;
        return 1;
    }

    long totalBytes = std::stol(argumentVector[argumentCount-4]);
    long byteChunk = std::stol(argumentVector[argumentCount-3]);
    long imageHeight = std::stol(argumentVector[argumentCount-2]);
    long imageWidth = std::stol(argumentVector[argumentCount-1]);
    long dataOffset = totalBytes / sizeof(double) / 2;

    std::vector<double> inputData(totalBytes / sizeof(double));
    int columnIndex = 0;
    size_t processedBytes = 0;

    // Read in data from standard input
    while (processedBytes < totalBytes) {
        size_t bytesRead = fread(&inputData[columnIndex], 1, byteChunk, stdin);
        if (bytesRead != byteChunk && ferror(stdin)) {
            throw std::runtime_error("Error reading from standard input");
        }
        columnIndex += byteChunk / sizeof(double);
        processedBytes += bytesRead;
    }

    // Compute the mutual information transformation
    MutualInformation MI;
    MI.Initialize(inputData.data(), imageHeight, imageWidth, dataOffset);
    MI.calculateMutualInformation();
    processedBytes = 0;
    columnIndex = 0;

    std::vector<double> resultData = MI.getOutput();
    while (processedBytes < totalBytes / 2) {
        size_t bytesWritten = writeBuffer((const unsigned char*)&resultData[columnIndex], byteChunk, stdout);
        if (bytesWritten != byteChunk) {
            throw std::runtime_error("Error writing to standard output");
        }
        processedBytes += bytesWritten;
        columnIndex += byteChunk / sizeof(double);
    }

    return 0;
}

