int PixyInterpreter::get_frame(unsigned char *buffer, int buffer_capacity) {
    unsigned int block_size = 4;          
    unsigned char *frame_data;            
    int32_t result, pixel_format;
    int8_t flags;
    int status;
    uint16_t cols, rows;
    uint32_t total_pixels;

    status = pixy_command("stop", END_OUT_ARGS, &result, END_IN_ARGS);  
    printf("STOP command returned %d with response %d\n", status, result);

    result = 0;
    status = pixy_command("cam_getFrame", 0x01, 0x21, 0x02, 0, 0x02, 0, 0x02, 320, 0x02, 200, 0, &result, &pixel_format, &flags, &cols, &rows, &total_pixels, &frame_data, 0);

    printf("getFrame operation returned %d with response %d\n", status, result); 
    printf("dimensions: width %d height %d pixels %u\n", cols, rows, total_pixels);  

    if (status != 0) return status;

    if (total_pixels > static_cast<uint32_t>(buffer_capacity)) {
        printf("Error: Frame data exceeds buffer capacity.\n");
        return -1;
    }

    memcpy(buffer, frame_data, total_pixels);

    unsigned int row_idx, col_idx, pixel_index, offset;

    offset = (rows / 2) * cols + cols / 2;
    for (row_idx = 0; row_idx < block_size; row_idx++) {
        for (col_idx = 0; col_idx < block_size; col_idx++) {
            pixel_index = row_idx * cols + col_idx + offset;
            printf(" %02x", buffer[pixel_index]);
        }
        printf("\n");
    }

    status = pixy_command("run", END_OUT_ARGS, &result, END_IN_ARGS);
    printf("START command returned %d with response %d\n", status, result);
    return static_cast<int>(total_pixels);
}

void ConvertToStdString(System::String^ source, char* destination)
{
    // Convert System::String^ to std::string
    std::string intermediate = marshal_as<std::string>(source);
    // Copy the std::string to the caller-allocated buffer
    strcpy(destination, intermediate.c_str());
}

void ProcessData(const char* source, char* result)
{
    // Convert const char* to System::String^
    System::String^ managed = ::ToCliString(source);

    if (managed == "xyz")
    {
        MessageBox::Show("const char* -> Managed: Success");
    }

    // Convert System::String^ to const char* using the caller-allocated buffer
    ::ConvertToStdString(managed, result);

    if (std::strcmp(result, "xyz") == 0)
    {
        MessageBox::Show("Managed -> const char*: Success");
    }
    else if (std::strcmp(result, "") == 0)
    {
        MessageBox::Show("ConvertToStdString returned empty string");
    }
    else
    {
        MessageBox::Show("ConvertToStdString returned unexpected value");
    }
}

