// Split a string into tokens using specified delimiters
void split_into_tokens(vector<string>& result, const string& text, const string& separators = " ") {
    result.clear();
    size_t begin, finish = 0;
    while ((begin = text.find_first_not_of(separators, finish)) != string::npos) {
        finish = text.find(separators, begin);
        result.push_back(text.substr(begin, finish - begin));
        // Skip multiple consecutive delimiters
        while (finish != string::npos && separators.find(text[finish]) != string::npos) {
            ++finish;
        }
    }
}

int main() {
    string current_line;
    vector<string> parsed_parts;
    long line_number = 0;
    auto start_time = high_resolution_clock::now();

    // Optimize I/O performance by disabling sync with C stdio
    cin.sync_with_stdio(false);

    while (getline(cin, current_line)) {
        split_into_tokens(parsed_parts, current_line);
        line_number++;
    }

    auto end_time = high_resolution_clock::now();
    auto elapsed = duration_cast<seconds>(end_time - start_time);
    cerr << "C++   : Processed " << line_number << " lines in " << elapsed.count() << " seconds.";
    if (elapsed.count() > 0) {
        long throughput = line_number / elapsed.count();
        cerr << "  Throughput: " << throughput << endl;
    } else {
        cerr << endl;
    }
    return 0;
}

