// Check if a number is prime
bool isPrime(int value) {
    if (value <= 1) return false;
    for (int j = 2; j * j <= value; j++) {
        if (value % j == 0) return false;
    }
    return true;
}

int main() {
    int primesFound = 0;      // Counter for prime numbers identified
    int currentNum = 2;       // Current number being tested for primality
    double primesSum = 0;     // Accumulated sum of prime numbers
    double currentAverage;    // Average of primes found so far

    do {
        if (isPrime(currentNum)) {
            primesFound++;
            primesSum += currentNum;
            currentAverage = primesSum / primesFound;
            cout << "Prime #" << primesFound << ": " << currentNum << endl;
            cout << "Current average: " << currentAverage << endl;
        }
        currentNum++;
    } while (primesFound < 6);

    return 0;
}

