class CoroutineWrapper {
public:
    struct coro_promise {
        CoroutineWrapper get_return_object() { return CoroutineWrapper{std::coroutine_handle<coro_promise>::from_promise(*this)}; }
        std::suspend_never initial_suspend() { return {}; }
        std::suspend_never final_suspend() noexcept { return {}; }
        void return_void() {}
        void unhandled_exception() { std::terminate(); }
    };

    bool completed() const { return m_coro_handle.done(); }
    void run() { m_coro_handle.resume(); }
    void suspend_now() { m_coro_handle.promise().m_should_suspend = true; }

private:
    std::coroutine_handle<coro_promise> m_coro_handle;

    CoroutineWrapper(std::coroutine_handle<coro_promise> handle) : m_coro_handle(handle) {}
    ~CoroutineWrapper() { if (m_coro_handle) m_coro_handle.destroy(); }

    friend struct coro_promise;
};

