// Perform matrix multiplication: C = A * B
void computeMatrixProduct(float* matrixA, float* matrixB, float* resultMatrix, int dimension) {
    for (int row = 0; row < dimension; row++) {
        for (int col = 0; col < dimension; col++) {
            float accumulator = 0.0f;
            for (int idx = 0; idx < dimension; idx++) {
                accumulator += matrixA[row * dimension + idx] * matrixB[idx * dimension + col];
            }
            resultMatrix[row * dimension + col] = accumulator;
        }
    }
}

int main() {
