    std::vector<float> firstMatrix(size * size, 1.0f);
    std::vector<float> secondMatrix(size * size, 1.0f);
    std::vector<float> outputMatrix(size * size, 0.0f);

    auto startTime = std::chrono::high_resolution_clock::now();
    computeMatrixProduct(firstMatrix.data(), secondMatrix.data(), outputMatrix.data(), size);
    auto endTime = std::chrono::high_resolution_clock::now();

    std::chrono::duration<double> elapsedTime = endTime - startTime;
    std::cout << "Processing Time: " << elapsedTime.count() << " s" << std::endl;

    return 0;
}

