#define matrixDim 1024
#define threadBlock 16

__global__ void multiplyMatrixKernel(const float* X, const float* Y, float* Z, int dim, int* counter) {
    int yIdx = blockIdx.y * blockDim.y + threadIdx.y;
    int xIdx = blockIdx.x * blockDim.x + threadIdx.x;

    if (yIdx < dim && xIdx < dim) {
        float accum = 0.0f;
        for (int k = 0; k < dim; k++) {
            accum += X[yIdx * dim + k] * Y[k * dim + xIdx];
        }
        Z[yIdx * dim + xIdx] = accum;

        // Increment progress counter atomically
        atomicAdd(counter, 1);
    }
}

void showProgress(int done, int total) {
    int percentage = (done * 100) / total;
    fprintf(stdout, "Completion : %d.%d %%\r", percentage / 100, percentage % 100);
    fflush(stdout);
}

int main() {
    float *host_X, *host_Y, *host_Z, *dev_X, *dev_Y, *dev_Z;
    int *host_counter, *dev_counter;
    size_t memSize = matrixDim * matrixDim * sizeof(float);
    size_t counterMemSize = sizeof(int);

    // Allocate host memory
    host_X = (float*)malloc(memSize);
    host_Y = (float*)malloc(memSize);
    host_Z = (float*)malloc(memSize);
    host_counter = (int*)malloc(counterMemSize);

    // Initialize matrices with default values
    for (int idx = 0; idx < matrixDim * matrixDim; ++idx) {
        host_X[idx] = 1.0f;
        host_Y[idx] = 1.0f;
        host_Z[idx] = 0.0f;
    }

    // Allocate device memory
    CUDA_CHECK(cudaMalloc(&dev_X, memSize));
    CUDA_CHECK(cudaMalloc(&dev_Y, memSize));
    CUDA_CHECK(cudaMalloc(&dev_Z, memSize));
    CUDA_CHECK(cudaMalloc(&dev_counter, counterMemSize));

    // Transfer data to device
    CUDA_CHECK(cudaMemcpy(dev_X, host_X, memSize, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(dev_Y, host_Y, memSize, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(dev_counter, host_counter, counterMemSize, cudaMemcpyHostToDevice));

    // Configure grid and block dimensions
    dim3 blockSizeConfig(threadBlock, threadBlock);
    dim3 gridSizeConfig((matrixDim + threadBlock - 1) / threadBlock, (matrixDim + threadBlock - 1) / threadBlock);

    // Create CUDA stream
    cudaStream_t gpuStream;
    CUDA_CHECK(cudaStreamCreate(&gpuStream));

    // Compute progress tracking parameters
    int totalTasks = matrixDim * matrixDim;
    int updateStep = totalTasks / 100; // Update every 1%

    // Launch kernels iteratively while monitoring progress
    for (int processed = 0; processed < totalTasks; processed += updateStep) {
        multiplyMatrixKernel<<<gridSizeConfig, blockSizeConfig, 0, gpuStream>>>(dev_X, dev_Y, dev_Z, matrixDim, dev_counter);
        CUDA_CHECK(cudaStreamSynchronize(gpuStream));

        // Retrieve current progress from device
        CUDA_CHECK(cudaMemcpy(host_counter, dev_counter, counterMemSize, cudaMemcpyDeviceToHost));
        showProgress(*host_counter, totalTasks);
    }

    // Ensure final kernel completion
    CUDA_CHECK(cudaStreamSynchronize(gpuStream));

    // Copy results back to host
    CUDA_CHECK(cudaMemcpy(host_Z, dev_Z, memSize, cudaMemcpyDeviceToHost));

    // Cleanup resources
    free(host_X);
    free(host_Y);
    free(host_Z);
    free(host_counter);
    CUDA_CHECK(cudaFree(dev_X));
    CUDA_CHECK(cudaFree(dev_Y));
    CUDA_CHECK(cudaFree(dev_Z));
    CUDA_CHECK(cudaFree(dev_counter));
    CUDA_CHECK(cudaStreamDestroy(gpuStream));

    return 0;
}

