// Find the maximum element in a vector of integers
int getMaximum(const std::vector<int>& data) {
    if (data.empty()) {
        return INT_MIN;  // Return the smallest possible integer if the vector is empty
    }
    int current_max = data[0];
    for (int value : data) {
        if (value > current_max) {
            current_max = value;
        }
    }
    return current_max;
}

