// Kernel to compute squared differences and store values below threshold
__global__ void computeDiffs(int numElements, float *inputData, float *outputData) {
    int threadId = blockIdx.x * blockDim.x + threadIdx.x;

    // Check if thread is within valid range
    if (threadId < numElements - 1) {
        float val = inputData[threadId];

        // Process remaining elements in sequence
        for (int j = threadId + 1; j < numElements; j++) {
            float diff = inputData[j] - val;
            float squared = diff * diff;

            if (squared < 10.0f) {
                // Atomically update output array
                atomicExch(&outputData[j], squared);
            }
        }
    }
}

