// Computes the upper 64 bits of the 128-bit product of two 64-bit numbers
uint64_t high_product(uint64_t a, uint64_t b) {
    // Split inputs into high and low 32-bit halves
    uint32_t a_lo = static_cast<uint32_t>(a);
    uint32_t a_hi = static_cast<uint32_t>(a >> 32);
    uint32_t b_lo = static_cast<uint32_t>(b);
    uint32_t b_hi = static_cast<uint32_t>(b >> 32);

    // Compute partial products
    uint64_t p0 = static_cast<uint64_t>(a_lo) * b_lo;
    uint64_t p3 = static_cast<uint64_t>(a_hi) * b_hi;
    uint64_t p1 = static_cast<uint64_t>(a_hi) * b_lo;
    uint64_t p2 = static_cast<uint64_t>(a_lo) * b_hi;

    // Combine cross terms and handle carry
    uint64_t mid_sum = p1 + p2;
    uint64_t overflow = (p0 >> 32) + (mid_sum >> 32);

    // Assemble final result: high part consists of p3, shifted mid_sum, and carry
    return p3 + (mid_sum << 32) + overflow;
}

int main() {
    uint64_t x = 1111111111111111111ULL;
    uint64_t y = 2222222222222222222ULL;
    uint64_t result = high_product(x, y);

    std::cout << "Upper 64 bits of multiplication: " << result << std::endl;
    return 0;
}

