#include <thrust/device_vector.h>
#include <thrust/scan.h>

__global__ void upward_pass_kernel(int* node_data, int* adjacency_info, int node_count) {
    int tid = threadIdx.x + blockIdx.x * blockDim.x;
    if (tid < node_count) {
        int current_val = node_data[tid];
        int child_count = adjacency_info[tid * 3];
        int* child_list = &adjacency_info[tid * 3 + 1];
        int accum = 0;
        for (int j = 0; j < child_count; ++j) {
            accum += node_data[child_list[j]];
        }
        node_data[tid] = current_val + accum;
    }
}

void compute_aggregate_values(int* node_data, int* adjacency_info, int total_nodes) {
    thrust::device_vector<int> d_node_data(node_data, node_data + total_nodes);
    thrust::device_vector<int> d_adjacency(adjacency_info, adjacency_info + total_nodes * 3);

    int block_size = 256;
    int grid_size = (total_nodes + block_size - 1) / block_size;
    upward_pass_kernel<<<grid_size, block_size>>>(
        thrust::raw_pointer_cast(d_node_data.data()),
        thrust::raw_pointer_cast(d_adjacency.data()),
        total_nodes
    );

    thrust::inclusive_scan(d_node_data.begin(), d_node_data.end(), d_node_data.begin());

    thrust::copy(d_node_data.begin(), d_node_data.end(), node_data);
}

