const int arraySize = 5;

__global__ void fillKernel(int *data)
{
    cudaError_t status = cudaMemsetAsync(data, 0xFF, arraySize * sizeof(int), 0);
    if (status != cudaSuccess) {
        printf("CUDA error in cudaMemsetAsync: %s\n", cudaGetErrorString(status));
    }
}

int main()
{
    cudaError_t err;
    int hostData[arraySize] = { 12, 12, 12, 12, 12 };
    int *deviceData = 0;

    err = cudaSetDevice(0);
    if (err != cudaSuccess) {
        fprintf(stderr, "cudaSetDevice failed! Please check if a CUDA-capable GPU is installed.\n");
        goto Cleanup;
    }

    err = cudaMalloc((void**)&deviceData, arraySize * sizeof(int));
    if (err != cudaSuccess) {
        fprintf(stderr, "cudaMalloc failed!\n");
        goto Cleanup;
    }

    err = cudaMemcpy(deviceData, hostData, arraySize * sizeof(int), cudaMemcpyHostToDevice);
    if (err != cudaSuccess) {
        fprintf(stderr, "cudaMemcpy (host to device) failed!\n");
        goto Cleanup;
    }

    fillKernel <<< 1, 1 >>>(deviceData);
    err = cudaGetLastError();
    if (err != cudaSuccess) {
        fprintf(stderr, "Kernel launch failed: %s\n", cudaGetErrorString(err));
        goto Cleanup;
    }

    err = cudaDeviceSynchronize();
    if (err != cudaSuccess) {
        fprintf(stderr, "cudaDeviceSynchronize failed after kernel execution: %s\n", cudaGetErrorString(err));
        goto Cleanup;
    }

    err = cudaMemcpy(hostData, deviceData, arraySize * sizeof(int), cudaMemcpyDeviceToHost);
    if (err != cudaSuccess) {
        fprintf(stderr, "cudaMemcpy (device to host) failed!\n");
        goto Cleanup;
    }

    cudaFree(deviceData);
    err = cudaDeviceReset();
    if (err != cudaSuccess) {
        fprintf(stderr, "cudaDeviceReset failed!\n");
        goto Cleanup;
    }

    printf("Final status code: %d\n", err);
    printf("{%d,%d,%d,%d,%d}\n", hostData[0], hostData[1], hostData[2], hostData[3], hostData[4]);
    return 0;

Cleanup:
    if (deviceData != nullptr) {
        cudaFree(deviceData);
    }
    cudaDeviceReset();
    return 1;
}

