__global__ void computeValues(coordinate* deviceData)  
{  
    // Only the first thread in the grid updates the values
    if (threadIdx.x == 0 && threadIdx.y == 0)
    {  
        deviceData->u = 200.0;  
        deviceData->v = 200.0;    
