#include <emmintrin.h> // For SSE2
#include <omp.h>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <sys/time.h>

void blendOverlay(const uint8_t* inputFrame, const uint8_t* overlayData, uint8_t* outputFrame, int frameWidth, int frameHeight) {
    int totalPixels = frameWidth * frameHeight;
    int alignedPixels = totalPixels - (totalPixels % 16); // Process in 16-pixel blocks

    __m128i nullVector = _mm_set1_epi8(0); // All-zero vector for alpha comparison

    #pragma omp parallel for
    for (int idx = 0; idx < alignedPixels; idx += 16) {
        // Load four consecutive RGBA vectors (each 16 bytes)
        __m128i rgbaBlock0 = _mm_loadu_si128((__m128i const*)(overlayData + idx * 4));
        __m128i rgbaBlock1 = _mm_loadu_si128((__m128i const*)(overlayData + idx * 4 + 16));
        __m128i rgbaBlock2 = _mm_loadu_si128((__m128i const*)(overlayData + idx * 4 + 32));
        __m128i rgbaBlock3 = _mm_loadu_si128((__m128i const*)(overlayData + idx * 4 + 48));

        // Extract alpha channels from each block
        __m128i alpha0 = _mm_shuffle_epi32(rgbaBlock0, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alpha1 = _mm_shuffle_epi32(rgbaBlock1, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alpha2 = _mm_shuffle_epi32(rgbaBlock2, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alpha3 = _mm_shuffle_epi32(rgbaBlock3, _MM_SHUFFLE(3, 3, 3, 3));

        // Create masks: 0xFF where alpha == 0, 0x00 otherwise
        __m128i mask0 = _mm_cmpeq_epi8(alpha0, nullVector);
        __m128i mask1 = _mm_cmpeq_epi8(alpha1, nullVector);
        __m128i mask2 = _mm_cmpeq_epi8(alpha2, nullVector);
        __mm128i mask3 = _mm_cmpeq_epi8(alpha3, nullVector);

        // Load corresponding RGB source data (3 bytes per pixel, unaligned)
        __m128i srcRGB0 = _mm_loadu_si128((__m128i const*)(inputFrame + idx * 3));
        __m128i srcRGB1 = _mm_loadu_si128((__m128i const*)(inputFrame + idx * 3 + 16));
        __m128i srcRGB2 = _mm_loadu_si128((__m128i const*)(inputFrame + idx * 3 + 32));
        __m128i srcRGB3 = _mm_loadu_si128((__m128i const*)(inputFrame + idx * 3 + 48));

        // Blend logic: if alpha is zero, use source; else use overlay
        __m128i result0 = _mm_or_si128(_mm_andnot_si128(mask0, rgbaBlock0), _mm_and_si128(mask0, srcRGB0));
        __m128i result1 = _mm_or_si128(_mm_andnot_si128(mask1, rgbaBlock1), _mm_and_si128(mask1, srcRGB1));
        __m128i result2 = _mm_or_si128(_mm_andnot_si128(mask2, rgbaBlock2), _mm_and_si128(mask2, srcRGB2));
        __m128i result3 = _mm_or_si128(_mm_andnot_si128(mask3, rgbaBlock3), _mm_and_si128(mask3, srcRGB3));

        // Store results to destination (3 bytes per pixel, unaligned)
        _mm_storeu_si128((__m128i*)(outputFrame + idx * 3), result0);
        _mm_storeu_si128((__m128i*)(outputFrame + idx * 3 + 16), result1);
        _mm_storeu_si128((__m128i*)(outputFrame + idx * 3 + 32), result2);
        _mm_storeu_si128((__m128i*)(outputFrame + idx * 3 + 48), result3);
    }

    // Handle remaining pixels not covered by SIMD loop
    for (int idx = alignedPixels; idx < totalPixels; ++idx) {
        if (overlayData[idx * 4 + 3] == 0) {
            outputFrame[idx * 3]     = inputFrame[idx * 3];
            outputFrame[idx * 3 + 1] = inputFrame[idx * 3 + 1];
            outputFrame[idx * 3 + 2] = inputFrame[idx * 3 + 2];
        } else {
            outputFrame[idx * 3]     = overlayData[idx * 4];
            outputFrame[idx * 3 + 1] = overlayData[idx * 4 + 1];
            outputFrame[idx * 3 + 2] = overlayData[idx * 4 + 2];
        }
    }
}

uint64_t getCurrentTimeMicros() {
    struct timeval currentTime;
    gettimeofday(&currentTime, NULL);
    return (uint64_t)currentTime.tv_sec * 1000000ULL + (uint64_t)currentTime.tv_usec;
}

int main(int argc, char **argv) {
    const int SCREEN_WIDTH = 1920;
    const int SCREEN_HEIGHT = 1080;
    size_t rgbBufferSize = SCREEN_WIDTH * SCREEN_HEIGHT * 3;

    uint8_t* overlayBuffer = new uint8_t[SCREEN_WIDTH * SCREEN_HEIGHT * 4];
    uint8_t* inputBuffer   = new uint8_t[rgbBufferSize];
    uint8_t* outputBuffer  = new uint8_t[rgbBufferSize];

    uint64_t startTime = getCurrentTimeMicros();

    for (int iteration = 0; iteration < 1000; ++iteration) {
        blendOverlay(inputBuffer, overlayBuffer, outputBuffer, SCREEN_WIDTH, SCREEN_HEIGHT);
    }

    printf("elapsed_ms: %lu\n", (getCurrentTimeMicros() - startTime) / 1000);

    delete[] overlayBuffer;
    delete[] inputBuffer;
    delete[] outputBuffer;

    return 0;
}

