using json = nlohmann::json;

// Constants for temperature adjustments
const double TEMP_CHANGE_EACH_100_METERS = -0.6;
const std::map<std::string, double> HOUR_OF_DAY_CORRECTION = {
    {"dawn", -2.0},
    {"midday", 0.0},
    {"sunset", -1.0},
    {"midnight", -3.0}
};
const std::map<std::string, double> YEAR_SEASON_CORRECTION = {
    {"cold", -5.0},
    {"bloom", 0.0},
    {"hot", 5.0},
    {"fall", 0.0}
};

double elevationCorrection(double height) {
    return height / 100 * TEMP_CHANGE_EACH_100_METERS;
}

double hourlyCorrection(const std::string& period) {
    auto iter = HOUR_OF_DAY_CORRECTION.find(period);
    return iter != HOUR_OF_DAY_CORRECTION.end() ? iter->second : 0.0;
}

double yearlyCorrection(const std::string& timeOfYear) {
    auto iter = YEAR_SEASON_CORRECTION.find(timeOfYear);
    return iter != YEAR_SEASON_CORRECTION.end() ? iter->second : 0.0;
}

double celsiusToKelvin(double tempCelsius, double elevation, const std::string& period, const std::string& season) {
    double correctedTemp = tempCelsius + elevationCorrection(elevation) + hourlyCorrection(period) + yearlyCorrection(season);
    return correctedTemp * 9 / 5 + 32;
}

json analyzeWeatherData(const json& input, const std::string& format) {
    json outcomes = json::array();
    for (const auto& record : input) {
        double tempCelsius = record.value("temp_celsius", 0.0);
        double elevation = record.value("elevation", 0.0);
        std::string period = record.value("period", "midday");
        std::string season = record.value("season", "bloom");
        double tempFahrenheit = celsiusToKelvin(tempCelsius, elevation, period, season);
        outcomes.push_back({
            {"place", record["place"]},
            {"celsius", tempCelsius},
            {"fahrenheit", tempFahrenheit},
            {"elevation", elevation},
            {"period", period},
            {"season", season}
        });
    }

    if (format == "json") {
        return outcomes;
    } else if (format == "csv") {
        std::ofstream document("results.csv");
        document << "place,celsius,fahrenheit,elevation,period,season\n";
        for (const auto& item : outcomes) {
            document << item["place"] << "," << item["celsius"] << "," << item["fahrenheit"] << "," << item["elevation"] << "," << item["period"] << "," << item["season"] << "\n";
        }
        document.close();
        return json::array();
    } else {
        return outcomes;
    }
}

int main() {
    json dataset = {
        {{"place", "Chicago"}, {"temp_celsius", 22.0}, {"elevation", 18.0}, {"period", "midday"}, {"season", "hot"}},
        {{"place", "Seattle"}, {"temp_celsius", 18.0}, {"elevation", 45.0}, {"period", "sunset"}, {"season", "bloom"}},
        {{"place", "Phoenix"}, {"temp_celsius", 30.0}, {"elevation", 1000.0}, {"period", "midnight"}, {"season", "cold"}}
    };

    json result = analyzeWeatherData(dataset, "json");
    std::cout << result.dump(4) << std::endl;

    return 0;
}

