void Renderer::SetupInstance()
{
    // Initialize Vulkan instance
    VkApplicationInfo appDetails = {};
    appDetails.sType = VK_STRUCTURE_TYPE_APPLICATION_INFO;
    appDetails.pApplicationName = "Graphics Engine";
    appDetails.applicationVersion = VK_MAKE_VERSION(1, 0, 0);
    appDetails.pEngineName = "Zero Engine";
    appDetails.engineVersion = VK_MAKE_VERSION(1, 0, 0);
    appDetails.apiVersion = VK_API_VERSION_1_2;

    VkInstanceCreateInfo initParams = {};
    initParams.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO;
    initParams.pApplicationInfo = &appDetails;

    uint32_t glfwExtCount = 0;
    const char** glfwRequiredExts;
    glfwRequiredExts = glfwGetRequiredInstanceExtensions(&glfwExtCount);
    initParams.enabledExtensionCount = glfwExtCount;
    initParams.ppEnabledExtensionNames = glfwRequiredExts;
    initParams.enabledLayerCount = 0;

    if (vkCreateInstance(&initParams, nullptr, &vulkanInstance) != VK_SUCCESS) {
        throw std::runtime_error("Unable to create Vulkan instance.");
    }
}

void Renderer::ReleaseInstance()
{
    // Destroy Vulkan instance
    vkDestroyInstance(vulkanInstance, nullptr);
}

void Renderer::SelectPhysicalDevice()
{
    // Enumerate available GPUs and select discrete GPU with Vulkan support
    uint32_t gpuCount = 0;
    vkEnumeratePhysicalDevices(vulkanInstance, &gpuCount, nullptr);
    if (gpuCount == 0) {
        throw std::runtime_error("No GPU found with Vulkan capability.");
    }

    std::vector<VkPhysicalDevice> gpus(gpuCount);
    vkEnumeratePhysicalDevices(vulkanInstance, &gpuCount, gpus.data());

    for (const auto& gpu : gpus) {
        VkPhysicalDeviceProperties gpuProps;
        vkGetPhysicalDeviceProperties(gpu, &gpuProps);
        if (gpuProps.deviceType == VK_PHYSICAL_DEVICE_TYPE_DISCRETE_GPU) {
            physicalDevice = gpu;
            break;
        }
    }

    if (physicalDevice == VK_NULL_HANDLE) {
        throw std::runtime_error("No suitable GPU device found.");
    }
}

void Renderer::InitializeLogicalDevice()
{
    // Create Vulkan logical device
    uint32_t queueFamCount = 0;
    vkGetPhysicalDeviceQueueFamilyProperties(physicalDevice, &queueFamCount, nullptr);
    std::vector<VkQueueFamilyProperties> queueFamilies(queueFamCount);
    vkGetPhysicalDeviceQueueFamilyProperties(physicalDevice, &queueFamCount, queueFamilies.data());

    size_t graphicsQueueIdx = std::distance(queueFamilies.begin(), 
        std::find_if(queueFamilies.begin(), queueFamilies.end(), 
            [](VkQueueFamilyProperties const& qfp) {
                return qfp.queueFlags & VK_QUEUE_GRAPHICS_BIT;
            }));

    float queuePriority = 1.0f;
    VkDeviceQueueCreateInfo queueInit = {};
    queueInit.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;
    queueInit.queueFamilyIndex = static_cast<uint32_t>(graphicsQueueIdx);
    queueInit.queueCount = 1;
    queueInit.pQueuePriorities = &queuePriority;

    VkDeviceCreateInfo devCreateInfo = {};
    devCreateInfo.sType = VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO;
    devCreateInfo.pQueueCreateInfos = &queueInit;
    devCreateInfo.queueCreateInfoCount = 1;

    VkPhysicalDeviceFeatures gpuFeatures = {};
    devCreateInfo.pEnabledFeatures = &gpuFeatures;

    devCreateInfo.enabledExtensionCount = 1;
    const char* requiredExtensions[] = {VK_KHR_SWAPCHAIN_EXTENSION_NAME};
    devCreateInfo.ppEnabledExtensionNames = requiredExtensions;

    if (vkCreateDevice(physicalDevice, &devCreateInfo, nullptr, &logicalDevice) != VK_SUCCESS) {
        throw std::runtime_error("Failed to initialize logical device.");
    }
}

void Renderer::ReleaseLogicalDevice()
{
    // Destroy Vulkan logical device
    vkDestroyDevice(logicalDevice, nullptr);
}

