#include <iostream>
#include <chrono>
#include <vector>
#include <random>
#include <algorithm>

const size_t LOOP_COUNT = 10000000;
const size_t BUFFER_LENGTH = 1024 * 1024; // 1MB
const size_t BOUNDARY = 16;

void initializeBuffer(std::vector<uint8_t>& buffer) {
    for (size_t pos = 0; pos < BUFFER_LENGTH; pos += BOUNDARY) {
        buffer[pos] = static_cast<uint8_t>(pos % 256);
    }
}

void measureAlignedReads(std::vector<uint8_t>& buffer) {
    auto beginTime = std::chrono::high_resolution_clock::now();
    for (size_t step = 0; step < LOOP_COUNT; ++step) {
        size_t offset = (step * 16) % (BUFFER_LENGTH - BOUNDARY);
        uint32_t val = *reinterpret_cast<uint32_t*>(buffer.data() + offset);
        // Prevent compiler optimization by using the value
        std::cout << (val & 0xFF) << std::flush;
    }
    auto endTime = std::chrono::high_resolution_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(endTime - beginTime).count();
    std::cout << "Aligned read required " << elapsed << " microseconds" << std::endl;
}

void measureMisalignedReads(std::vector<uint8_t>& buffer) {
    auto beginTime = std::chrono::high_resolution_clock::now();
    for (size_t step = 0; step < LOOP_COUNT; ++step) {
        size_t offset = (step * 15) % (BUFFER_LENGTH - BOUNDARY); // Misaligned access
        uint32_t val = *reinterpret_cast<uint32_t*>(buffer.data() + offset);
        // Prevent compiler optimization by using the value
        std::cout << (val & 0xFF) << std::flush;
    }
    auto endTime = std::chrono::high_resolution_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(endTime - beginTime).count();
    std::cout << "Misaligned read required " << elapsed << " microseconds" << std::endl;
}

int main() {
    std::vector<uint8_t> buffer(BUFFER_LENGTH, 0);
    initializeBuffer(buffer);

    measureAlignedReads(buffer);
    measureMisalignedReads(buffer);

    return 0;
}

