// Find the longest string in a vector of strings
std::string getLongestString(const std::vector<std::string>& words) {
    if (words.empty()) {
        return ""; // Return empty string for empty input
    }
    std::string maxLengthString = words[0];
    for (const std::string& word : words) {
        if (word.size() > maxLengthString.size()) {
            maxLengthString = word;
        }
    }
    return maxLengthString;
}

