extern "C" ASSEMBLER_API bool CompileAssembly(const char* source, unsigned char** resultBuffer, size_t* bufferSize);

// Assembler.cpp
#include "Assembler.h"
#include <iostream>
#include <string>
#include <vector>
#include <fstream>
#include <sstream>
#include <cassert>

bool CompileAssembly(const char* source, unsigned char** resultBuffer, size_t* bufferSize) {
    std::string tempSourceFile = "assembly_input.asm";
    std::ofstream input(tempSourceFile);
    if (!input.is_open()) {
        return false;
    }

    input << source;
    input.close();

    std::string tempObjectFile = "assembly_output.obj";
    std::string commandLine = "nasm -f win32 " + tempSourceFile + " -o " + tempObjectFile;
    system(commandLine.c_str());

    std::ifstream objectStream(tempObjectFile, std::ios::binary | std::ios::ate);
    if (!objectStream.is_open()) {
        return false;
    }

    size_t fileSize = objectStream.tellg();
    std::vector<unsigned char> buffer(fileSize);
    objectStream.seekg(0, std::ios::beg);
    objectStream.read(reinterpret_cast<char*>(buffer.data()), fileSize);
    objectStream.close();

    *resultBuffer = new unsigned char[fileSize];
    std::copy(buffer.begin(), buffer.end(), *resultBuffer);
    *bufferSize = fileSize;

    return true;
}

