extern "C" DOMWALKER_API void WalkDOM(IHTMLDocument2* pDocument);

// DOMWalker.cpp
#include "DOMWalker.h"
#include <mshtml.h>

void WalkDOM(IHTMLDocument2* pDocument) {
    if (pDocument == nullptr) return;

    IHTMLElementCollection* pBodyElements = nullptr;
    pDocument->get_body(&pBodyElements);

    if (pBodyElements == nullptr) return;

    long count = 0;
    pBodyElements->get_length(&count);

    for (long index = 0; index < count; ++index) {
        IHTMLDOMNode* node = nullptr;
        pBodyElements->item(index, &node);

        if (node == nullptr) continue;

        BSTR content = nullptr;
        node->get_nodeValue(&content);

        if (content != nullptr) {
            // Process the text content
            wprintf(L"Text Node: %s\n", content);
            SysFreeString(content);
        }

        IHTMLDOMNode* childNode = nullptr;
        node->get_firstChild(&childNode);

        while (childNode != nullptr) {
            WalkDOMHelper(childNode);
            IHTMLDOMNode* nextSibling = nullptr;
            childNode->get_nextSibling(&nextSibling);
            childNode->Release();
            childNode = nextSibling;
        }

        node->Release();
    }

    pBodyElements->Release();
}

void WalkDOMHelper(IHTMLDOMNode* node) {
    if (node == nullptr) return;

    BSTR content = nullptr;
    node->get_nodeValue(&content);

    if (content != nullptr) {
        // Process the text content
        wprintf(L"Text Node: %s\n", content);
        SysFreeString(content);
    }

    IHTMLDOMNode* childNode = nullptr;
    node->get_firstChild(&childNode);

    while (childNode != nullptr) {
        WalkDOMHelper(childNode);
        IHTMLDOMNode* nextSibling = nullptr;
        childNode->get_nextSibling(&nextSibling);
        childNode->Release();
        childNode = nextSibling;
    }
}

#include <vector>
#include <pybind11/pybind11.h>
#include <pybind11/numpy.h>

namespace py = pybind11;

class Cube3D {
public:
    std::vector<std::vector<std::vector<double>>> storage;
    int dim_x, dim_y, dim_z;

    // Constructor
    Cube3D(int x, int y, int z) : dim_x(x), dim_y(y), dim_z(z) {
        storage.resize(dim_x, std::vector<std::vector<double>>(dim_y, std::vector<double>(dim_z, 0.0)));
    }

    // Overloaded operator() for element access
    double& operator()(int i, int j, int k) {
        return storage[i][j][k];
    }

    // Function to convert Cube3D to a NumPy array
    py::array_t<double> to_numpy_array() const {
        py::array_t<double> np_array({dim_x, dim_y, dim_z});
        auto buffer = np_array.mutable_unchecked<3>();
        for (size_t idx = 0; idx < dim_x; ++idx) {
            for (size_t idy = 0; idy < dim_y; ++idy) {
                for (size_t idz = 0; idz < dim_z; ++idz) {
                    buffer(idx, idy, idz) = storage[idx][idy][idz];
                }
            }
        }
        return np_array;
    }

    // Function to convert a NumPy array to Cube3D
    static Cube3D from_numpy_array(const py::array_t<double>& np_array) {
        auto buffer = np_array.unchecked<3>();
        Cube3D cube(buffer.shape(0), buffer.shape(1), buffer.shape(2));
        for (size_t idx = 0; idx < buffer.shape(0); ++idx) {
            for (size_t idy = 0; idy < buffer.shape(1); ++idy) {
                for (size_t idz = 0; idz < buffer.shape(2); ++idz) {
                    cube.storage[idx][idy][idz] = buffer(idx, idy, idz);
                }
            }
        }
        return cube;
    }
};

