// Coordinate class definition
class Coordinate {
public:
    Coordinate(int x_val, int y_val) : x_coord(x_val), y_coord(y_val) {}
    int get_x() const { return x_coord; }
    void update_x(int new_x) { x_coord = new_x; }
    int get_y() const { return y_coord; }
    void update_y(int new_y) { y_coord = new_y; }

private:
    int x_coord;
    int y_coord;
};

// Getter for x coordinate
void RetrieveCoordinateX(Local<String> prop, const PropertyCallbackInfo<Value>& info) {
    Coordinate* coord = static_cast<Coordinate*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    info.GetReturnValue().Set(Number::New(info.GetIsolate(), coord->get_x()));
}

// Setter for x coordinate
void ModifyCoordinateX(Local<String> prop, Local<Value> val, const PropertyCallbackInfo<void>& info) {
    Coordinate* coord = static_cast<Coordinate*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    coord->update_x(val->NumberValue(info.GetIsolate()->GetCurrentContext()).ToChecked());
}

// Getter for y coordinate
void RetrieveCoordinateY(Local<String> prop, const PropertyCallbackInfo<Value>& info) {
    Coordinate* coord = static_cast<Coordinate*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    info.GetReturnValue().Set(Number::New(info.GetIsolate(), coord->get_y()));
}

// Setter for y coordinate
void ModifyCoordinateY(Local<String> prop, Local<Value> val, const PropertyCallbackInfo<void>& info) {
    Coordinate* coord = static_cast<Coordinate*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    coord->update_y(val->NumberValue(info.GetIsolate()->GetCurrentContext()).ToChecked());
}

int main() {
    // Initialize V8 runtime
    v8::V8::InitializeICUDefaultLocation("");
    v8::V8::InitializeExternalStartupData("");
    std::unique_ptr<v8::Platform> platform_obj = v8::platform::NewDefaultPlatform();
    v8::V8::InitializePlatform(platform_obj.get());
    v8::V8::Initialize();

    // Create new isolate and enter its scope
    Isolate* isolate_ptr = Isolate::New();
    {
        Isolate::Scope isolate_scope(isolate_ptr);
        HandleScope handle_scope(isolate_ptr);
        Local<Context> context_obj = Context::New(isolate_ptr);
        Context::Scope context_scope(context_obj);

        // Create ObjectTemplate for Coordinate class
        Local<ObjectTemplate> coord_template = ObjectTemplate::New(isolate_ptr);
        coord_template->SetInternalFieldCount(1); // Reserve space for C++ pointer

        // Configure accessors
        coord_template->SetAccessor(String::NewFromUtf8(isolate_ptr, "x").ToLocalChecked(), RetrieveCoordinateX, ModifyCoordinateX);
        coord_template->SetAccessor(String::NewFromUtf8(isolate_ptr, "y").ToLocalChecked(), RetrieveCoordinateY, ModifyCoordinateY);

        // Instantiate Coordinate object
        Coordinate* coord = new Coordinate(5, 15);

        // Create JavaScript object with internal field set
        Local<Object> js_object = coord_template->NewInstance(context_obj).ToLocalChecked();
        js_object->SetAlignedPointerInInternalField(0, coord);

        // Expose to global scope
        context_obj->Global()->Set(context_obj, String::NewFromUtf8(isolate_ptr, "coord").ToLocalChecked(), js_object).Check();

        // Execute JavaScript code
        Local<String> script_source = String::NewFromUtf8(isolate_ptr, "coord.x = coord.y * 3; console.log(coord.x);").ToLocalChecked();
        Local<Script> compiled_script = Script::Compile(context_obj, script_source).ToLocalChecked();
        Local<Value> execution_result = compiled_script->Run(context_obj).ToLocalChecked();

        // Cleanup resources
        delete coord;
    }

    // Release isolate resources
    isolate_ptr->Dispose();
    v8::V8::Dispose();
    v8::V8::ShutdownPlatform();
    return 0;
}

