void aricoder::initialize() {
    // Compute scaled reciprocals for each symbol
    for (int idx = 0; idx < num_symbols; ++idx) {
        symbol_table[idx].reciprocal_val = 1073741824 / symbol_table[idx].scale_factor;
    }
}

void aricoder::encode(symbol* sym) {
    unsigned int range_size = chigh - clow + 1;
    cstep = (range_size * sym->reciprocal_val) >> 30;

    chigh = clow + cstep * sym->high_idx - 1;
    clow = clow + cstep * sym->low_idx;

    while ((clow >= 536870912) || (chigh < 536870912)) {
        if (chigh < 536870912) {
            write_zero();
            write_nrbits_as_one();
        } else {
            write_one();
            clow &= 536870911;
            chigh &= 536870911;
            write_nrbits_as_zeros();
        }
        clow <<= 1;
        chigh = (chigh << 1) | 1;
    }

    while ((clow >= 268435456) && (chigh < 805306368)) {
        nrbits++;
        clow &= 268435455;
        chigh ^= 1073741824;
        clow <<= 1;
        chigh = (chigh << 1) | 1;
    }
}

