// Resize a memory buffer and initialize new bytes to zero if expanded
void* adjust_buffer(void* current_ptr, Py_ssize_t prev_len, Py_ssize_t next_len) {
    void* updated_ptr = PyMem_Realloc(current_ptr, next_len);
    if (updated_ptr == NULL) {
        // Memory allocation failed
        return NULL;
    }
    // Zero-initialize newly allocated portion if buffer grew
    if (next_len > prev_len) {
        std::memset(static_cast<char*>(updated_ptr) + prev_len, 0, next_len - prev_len);
    }
    return updated_ptr;
}

