#include <iostream>
#include <limits>

class Element {
public:
    int data;
    Element* previous;
    Element* following;

    Element(int val) : data(val), previous(nullptr), following(nullptr) {}
};

class BidirectionalList {
private:
    Element* start;
    Element* end;
    Element* lowestElement;
    Element* highestElement;

public:
    BidirectionalList() : start(nullptr), end(nullptr), lowestElement(nullptr), highestElement(nullptr) {}

    void add(int value) {
        Element* newElement = new Element(value);

        if (start == nullptr) {
            start = end = lowestElement = highestElement = newElement;
        } else {
            newElement->previous = end;
            end->following = newElement;
            end = newElement;

            if (value < lowestElement->data) {
                lowestElement = newElement;
            }
            if (value > highestElement->data) {
                highestElement = newElement;
            }
        }
    }

    void erase(int value) {
        Element* current = start;
        while (current != nullptr) {
            if (current->data == value) {
                if (current->previous) {
                    current->previous->following = current->following;
                } else {
                    start = current->following;
                }

                if (current->following) {
                    current->following->previous = current->previous;
                } else {
                    end = current->previous;
                }

                if (lowestElement == current) {
                    lowestElement = locateLowest();
                }
                if (highestElement == current) {
                    highestElement = locateHighest();
                }

                delete current;
                return;
            }
            current = current->following;
        }
    }

    int getMinimum() const {
        return lowestElement ? lowestElement->data : std::numeric_limits<int>::max();
    }

    int getMaximum() const {
        return highestElement ? highestElement->data : std::numeric_limits<int>::min();
    }

private:
    Element* locateLowest() const {
        Element* lowest = start;
        Element* current = start;
        while (current != nullptr) {
            if (current->data < lowest->data) {
                lowest = current;
            }
            current = current->following;
        }
        return lowest;
    }

    Element* locateHighest() const {
        Element* highest = start;
        Element* current = start;
        while (current != nullptr) {
            if (current->data > highest->data) {
                highest = current;
            }
            current = current->following;
        }
        return highest;
    }
};

int main() {
    BidirectionalList list;
    list.add(10);
    list.add(5);
    list.add(15);
    list.add(3);

    std::cout << "Lowest: " << list.getMinimum() << std::endl; // Output: Lowest: 3
    std::cout << "Highest: " << list.getMaximum() << std::endl; // Output: Highest: 15

    list.erase(15);
    std::cout << "Highest after erasing 15: " << list.getMaximum() << std::endl; // Output: Highest: 10

    return 0;
}

