#include "ECS.h"

using namespace rapidjson;

using ComponentLoaderCallback = std::function<void(EntityId, const Value&)>;

static std::unordered_map<std::string, ComponentLoaderCallback> componentHandlers;

void ImportScene(const std::string& fileName) {
    FILE* filePtr = std::fopen(fileName.c_str(), "r");
    if (!filePtr) {
        std::cerr << "Failed to open scene file: " << fileName << std::endl;
        return;
    }

    char buffer[65536];
    FileReadStream jsonStream(filePtr, buffer, sizeof(buffer));

    Document sceneDoc;
    sceneDoc.ParseStream<0, UTF8<>, FileReadStream>(jsonStream);
    std::fclose(filePtr);

    if (sceneDoc.HasParseError()) {
        std::cerr << "JSON parsing error in scene file: " << fileName << std::endl;
        return;
    }

    if (sceneDoc.HasMember("gameObjects") && sceneDoc["gameObjects"].IsArray()) {
        const Value& gameObjects = sceneDoc["gameObjects"];

        for (SizeType index = 0; index < gameObjects.Size(); ++index) {
            const Value& objectData = gameObjects[index];

            EntityId newEntity = ECS::CreateEntity();

            for (const auto& handler : componentHandlers) {
                const char* componentName = handler.first.c_str();

                if (objectData.HasMember(componentName)) {
                    handler.second(newEntity, objectData[componentName]);
                }
            }
        }
    }
}

