#include <iostream>
#include <vector>
#include <string>

std::string transform(std::string input, int rows, int cols, char placeholder = 'Z') {
    // Initialize the grid with the placeholder character
    std::vector<std::vector<char>> grid(rows, std::vector<char>(cols, placeholder));

    // Movement directions: right, down, left, up
    int dirX[] = {0, 1, 0, -1};
    int dirY[] = {1, 0, -1, 0};

    int curRow = 0, curCol = 0; // Current position
    int currentDir = 0; // Starting direction (right)
    int pos = 0; // Position in the input string

    while (pos < input.length()) {
        grid[curRow][curCol] = input[pos++];

        // Compute next coordinates
        int nextRow = curRow + dirX[currentDir];
        int nextCol = curCol + dirY[currentDir];

        // Check if next position is invalid or already occupied
        if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols || grid[nextRow][nextCol] != placeholder) {
            // Switch direction
            currentDir = (currentDir + 1) % 4;
            nextRow = curRow + dirX[currentDir];
            nextCol = curCol + dirY[currentDir];
        }

        // Update current position
        curRow = nextRow;
        curCol = nextCol;
    }

    // Traverse the grid in spiral order to build result
    std::string output;
    curRow = 0;
    curCol = 0;
    currentDir = 0;
    bool seen[rows][cols] = {{false}}; // Track visited cells

    while (true) {
        output += grid[curRow][curCol];
        seen[curRow][curCol] = true;

        // Calculate next position
        int nextRow = curRow + dirX[currentDir];
        int nextCol = curCol + dirY[currentDir];

        // Check boundaries and visited status
        if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols || seen[nextRow][nextCol]) {
            // Change direction
            currentDir = (currentDir + 1) % 4;
            nextRow = curRow + dirX[currentDir];
            nextCol = curCol + dirY[currentDir];

            // If still invalid, terminate loop
            if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols || seen[nextRow][nextCol]) {
                break;
            }
        }

        // Move to next cell
        curRow = nextRow;
        curCol = nextCol;
    }

    return output;
}

int main() {
    std::string t1 = "HELLOPROGRAMMING";
    int r1 = 5, c1 = 4;
    std::cout << transform(t1, r1, c1) << std::endl; // Output: "HELLOGRAMMINGPROGRAMLLE"

    std::string t2 = "HELLOPROGRAMMING";
    int r2 = 4, c2 = 4;
    std::cout << transform(t2, r2, c2) << std::endl; // Output: "HELLOGRAMMINGPRO"

    std::string t3 = "A";
    int r3 = 1, c3 = 1;
    std::cout << transform(t3, r3, c3) << std::endl; // Output: "A"

    std::string t4 = "HELLO";
    int r4 = 3, c4 = 3;
    std::cout << transform(t4, r4, c4, 'Z') << std::endl; // Output: "HELXLOX"

    return 0;
}

