#pragma comment(lib, "wininet.lib")
#define ERR_FILE_OPEN         10
#define ERR_ALLOC_MEM         11
#define ERR_FILE_SIZE         12
#define ERR_INET_INIT         13
#define ERR_INET_CONN         14
#define ERR_INET_REQ          15
#define ERR_INET_XMIT         16

using namespace std;

int main()
{
    // Local variables
    static char *targetFile   = "sample.txt";      // Filename to be uploaded
    static char *fullPath     = "C:\\wamp\\www\\post\\sample.txt"; // Full path to file
    static char *mimeType     = "text/plain";
    static char delimiter[]   = "--BOUNDARY---";   // Multipart boundary
    static char formField[]   = "data";            // Form field name
    static char serverAddr[]  = "localhost";       // Server IP
    static char scriptPath[]  = "/post/upload.php";// Script URL

    char headers[1024] = {0};                      // HTTP headers buffer
    char * fullBuffer;                             // Combined buffer (headers + content)
    char * fileData;                               // Raw file content
    FILE * fp;                                     // File handle
    long fileSize;                                 // Size of file
    size_t bytesRead;                              // Bytes read from file

    // Open the file for reading in binary mode
    fp = fopen(fullPath, "rb");
    if (fp == NULL) 
    {
        printf("ERR_FILE_OPEN\n");
        return ERR_FILE_OPEN;
    }
    printf("FILE_OPENED\n");

    // Determine file size
    fseek(fp, 0, SEEK_END);
    fileSize = ftell(fp);
    rewind(fp);

    // Allocate memory for file content
    fileData = (char*) malloc(sizeof(char) * (fileSize + 1));
    if (fileData == NULL) 
    {
        printf("ERR_ALLOC_MEM\n");
        fclose(fp);
        return ERR_ALLOC_MEM;
    }
    printf("MEMORY_ALLOCATION\t \"%ld\" \n", fileSize);

    // Read entire file into buffer
    bytesRead = fread(fileData, 1, fileSize, fp);
    if (bytesRead != fileSize) 
    {
        printf("ERR_FILE_SIZE\n");
        free(fileData);
        fclose(fp);
        return ERR_FILE_SIZE;
    }
    printf("SIZE_VERIFIED\n");

    fileData[fileSize] = '\0'; // Null-terminate string

    // Close file after reading
    fclose(fp);
    printf("FILE_CLOSED\n");

    // Allocate larger buffer for full multipart request
    fullBuffer = (char*) malloc(sizeof(char) * (fileSize + 2048));
    if (fullBuffer == NULL) 
    {
        printf("ERR_ALLOC_MEM\n");
        free(fileData);
        return ERR_ALLOC_MEM;
    }

    // Build multipart headers and body
    sprintf(headers, "Content-Type: multipart/form-data; boundary=%s\r\n", delimiter);
    sprintf(fullBuffer, "%s--%s\r\nContent-Disposition: form-data; name=\"%s\"; filename=\"%s\"\r\n", delimiter, formField, targetFile);
    sprintf(fullBuffer, "%sContent-Type: %s\r\n", fullBuffer, mimeType);
    sprintf(fullBuffer, "%s\r\n%s\r\n", fullBuffer, fileData);
    sprintf(fullBuffer, "%s--%s--\r\n", fullBuffer, delimiter);

    // Compute total length of request payload
    int payloadLength = strlen(fullBuffer);

    // Initialize WinINet session
    HINTERNET hSession = InternetOpen("WININET_CLIENT", INTERNET_OPEN_TYPE_PRECONFIG, NULL, NULL, 0);
    if (hSession == NULL) 
    {
        printf("ERR_INET_INIT\n");
        free(fileData);
        free(fullBuffer);
        return ERR_INET_INIT;
    }
    printf("INET_SESSION_CREATED\n");

    // Connect to HTTP server
    HINTERNET hConnect = InternetConnect(hSession, serverAddr, INTERNET_DEFAULT_HTTP_PORT, NULL, NULL, INTERNET_SERVICE_HTTP, 0, 1);
    if (hConnect == NULL) 
    {
        printf("ERR_INET_CONN\n");
        InternetCloseHandle(hSession);
        free(fileData);
        free(fullBuffer);
        return ERR_INET_CONN;
    }
    printf("INET_CONNECTION_ESTABLISHED\n");

    // Create HTTP POST request
    HINTERNET hRequest = HttpOpenRequest(hConnect, "POST", scriptPath, NULL, NULL, NULL, INTERNET_FLAG_RELOAD, 1);
    if (hRequest == NULL) 
    {
        printf("ERR_INET_REQ\n");
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        free(fileData);
        free(fullBuffer);
        return ERR_INET_REQ;
    }
    printf("HTTP_REQUEST_CREATED\n");

    // Append Content-Length header
    char lenHeader[128];
    sprintf(lenHeader, "Content-Length: %d\r\n", payloadLength);
    strcat(headers, lenHeader);

    // Send HTTP request with payload
    BOOL success = HttpSendRequest(hRequest, headers, strlen(headers), fullBuffer, payloadLength);
    if (!success) 
    {
        printf("ERR_INET_XMIT\n");
        InternetCloseHandle(hRequest);
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        free(fileData);
        free(fullBuffer);
        return ERR_INET_XMIT;
    }
    printf("DATA_TRANSMITTED_SUCCESSFULLY\n");

    // Cleanup handles and memory
    InternetCloseHandle(hRequest);
    InternetCloseHandle(hConnect);
    InternetCloseHandle(hSession);

    free(fileData);
    free(fullBuffer);

    getchar();
    return 0;
}

