        auto pybind_capsule = pybind11::capsule(new std::shared_ptr<bar::Bar>(bar_from_python), "bar_in_capsule", [](void* ptr) {
            delete reinterpret_cast<std::shared_ptr<bar::Bar>*>(ptr);
        });
        return pybind_capsule;
