#include <iostream>
#include <string>
#include <vector>
#include <cctype>

enum class TokenType {
    IF,
    ELSE,
    FUNCTION,
    IDENTIFIER,
    NUMBER,
    STRING,
    OPERATOR,
    EOF_TOKEN
};

struct TokenData {
    TokenType kind;
    std::string literal;
};

class Scanner {
public:
    Scanner(const std::string& source) : text(source), index(0) {}

    TokenData advance() {
        skipSpaces();
        if (index >= text.length()) {
            return {TokenType::EOF_TOKEN, ""};
        }

        char ch = text[index];
        if (isalpha(ch)) {
            return wordToken();
        } else if (isdigit(ch)) {
            return digitToken();
        } else if (ch == '"') {
            return quotedString();
        } else {
            return symbolToken();
        }
    }

private:
    std::string text;
    size_t index;

    void skipSpaces() {
        while (index < text.length() && isspace(text[index])) {
            index++;
        }
    }

    TokenData wordToken() {
        size_t begin = index;
        while (index < text.length() && isalnum(text[index])) {
            index++;
        }
        std::string tokenValue = text.substr(begin, index - begin);
        if (tokenValue == "if") {
            return {TokenType::IF, tokenValue};
        } else if (tokenValue == "else") {
            return {TokenType::ELSE, tokenValue};
        } else if (tokenValue == "function") {
            return {TokenType::FUNCTION, tokenValue};
        } else {
            return {TokenType::IDENTIFIER, tokenValue};
        }
    }

    TokenData digitToken() {
        size_t begin = index;
        while (index < text.length() && isdigit(text[index])) {
            index++;
        }
        return {TokenType::NUMBER, text.substr(begin, index - begin)};
    }

    TokenData quotedString() {
        index++; // Skip the opening double quote
        size_t begin = index;
        while (index < text.length() && text[index] != '"') {
            index++;
        }
        std::string content = text.substr(begin, index - begin);
        index++; // Skip the closing double quote
        return {TokenType::STRING, content};
    }

    TokenData symbolToken() {
        std::string symbol(1, text[index++]);
        return {TokenType::OPERATOR, symbol};
    }
};

