// Process vector by separating odd and even elements using unzip
uint8x16_t oddeven(uint8x16_t input_vector) {
    // Split the input into lower and upper 64-bit lanes
    uint8x8_t low_part = vget_low_u8(input_vector);
    uint8x8_t high_part = vget_high_u8(input_vector);

    // Perform unzip operation to interleave elements from both parts
    uint8x8x2_t unzip_result = vuzp_u8(low_part, high_part);

    // Recombine the two 64-bit results into a single 128-bit vector
    return vcombine_u8(unzip_result.val[0], unzip_result.val[1]);
}

