#include <opencv2/opencv.hpp>

__global__ void demosaicKernel(const unsigned char* input, unsigned char* output, int imgWidth, int imgHeight) {
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    if (col >= imgWidth || row >= imgHeight) return;

    int pixelIndex = row * imgWidth + col;
    int rgbIndex = pixelIndex * 3;

    // Input uses GRBG Bayer pattern
    if (col % 2 == 0) {
        if (row % 2 == 0) {
            // Green pixel at even row, even column
            output[rgbIndex]     = input[pixelIndex];
            output[rgbIndex + 1] = (col < imgWidth - 1) ? (input[pixelIndex + 1] + input[pixelIndex + imgWidth + 1]) / 2 : input[pixelIndex + 1];
            output[rgbIndex + 2] = (row < imgHeight - 1) ? (input[pixelIndex + imgWidth] + input[pixelIndex + imgWidth + 1]) / 2 : input[pixelIndex + imgWidth];
        } else {
            // Red pixel at odd row, even column
            output[rgbIndex]     = (col < imgWidth - 1) ? (input[pixelIndex + 1] + input[pixelIndex + imgWidth - 1]) / 2 : input[pixelIndex + 1];
            output[rgbIndex + 1] = (col < imgWidth - 1 && row < imgHeight - 1) ? 
                (input[pixelIndex + imgWidth] + input[pixelIndex + imgWidth + 1] + input[pixelIndex - imgWidth] + input[pixelIndex - imgWidth + 1]) / 4 : input[pixelIndex];
            output[rgbIndex + 2] = input[pixelIndex];
        }
    } else {
        if (row % 2 == 0) {
            // Blue pixel at even row, odd column
            output[rgbIndex]     = (row < imgHeight - 1) ? (input[pixelIndex + imgWidth] + input[pixelIndex + imgWidth - 1]) / 2 : input[pixelIndex + imgWidth];
            output[rgbIndex + 1] = (col > 0 && row < imgHeight - 1) ? 
                (input[pixelIndex + imgWidth] + input[pixelIndex + imgWidth - 1] + input[pixelIndex - imgWidth] + input[pixelIndex - imgWidth - 1]) / 4 : input[pixelIndex];
            output[rgbIndex + 2] = input[pixelIndex];
        } else {
            // Green pixel at odd row, odd column
            output[rgbIndex]     = input[pixelIndex];
            output[rgbIndex + 1] = (col > 0) ? (input[pixelIndex - 1] + input[pixelIndex + imgWidth - 1]) / 2 : input[pixelIndex - 1];
            output[rgbIndex + 2] = (row > 0) ? (input[pixelIndex - imgWidth] + input[pixelIndex - imgWidth - 1]) / 2 : input[pixelIndex - imgWidth];
        }
    }
}

void convertBayerToRGB(const cv::Mat& source, cv::Mat& result) {
    int cols = source.cols;
    int rows = source.rows;
    int bufferSize = cols * rows * 3;

    unsigned char* deviceInput = nullptr;
    unsigned char* deviceOutput = nullptr;

    cudaMalloc(&deviceInput, source.total() * source.elemSize());
    cudaMalloc(&deviceOutput, bufferSize);

    cudaMemcpy(deviceInput, source.data, source.total() * source.elemSize(), cudaMemcpyHostToDevice);

    dim3 threadsPerBlock(16, 16);
    dim3 blocksPerGrid((cols + threadsPerBlock.x - 1) / threadsPerBlock.x, 
                       (rows + threadsPerBlock.y - 1) / threadsPerBlock.y);

    demosaicKernel<<<blocksPerGrid, threadsPerBlock>>>(deviceInput, deviceOutput, cols, rows);

    result.create(rows, cols, CV_8UC3);
    cudaMemcpy(result.data, deviceOutput, bufferSize, cudaMemcpyDeviceToHost);

    cudaFree(deviceInput);
    cudaFree(deviceOutput);
}

int main() {
    cv::Mat rawImage = cv::imread("bayer_input.png", cv::IMREAD_GRAYSCALE);
    cv::Mat colorImage;

    convertBayerToRGB(rawImage, colorImage);

    cv::imwrite("rgb_output.png", colorImage);

    return 0;
}

