// Find pairs of numbers that sum to 10
std::vector<std::pair<int, int>> locateSumPairs(const std::vector<int>& values) {
    std::unordered_set<int> visited;
    std::vector<std::pair<int, int>> result;
    for (int value : values) {
        int complement = 10 - value;
        if (visited.find(complement) != visited.end()) {
            result.emplace_back(value, complement);
        }
        visited.insert(value);
    }
    return result;
}

int main() {
    std::vector<int> values = {2, 4, 6, 8, 1, 3, 5, 7, 9};
    auto result = locateSumPairs(values);
    for (const auto& item : result) {
        std::cout << "(" << item.first << ", " << item.second << ")" << std::endl;
    }
    return 0;
}

