LRESULT CALLBACK WindowProcedure(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
    static MARGINS extendMargins = {-1};
    static HBRUSH windowBrush = CreateSolidBrush(RGB(240, 240, 240));

    switch (msg) {
    case WM_NCCALCSIZE:
        if (wParam == TRUE) {
            // Modify the non-client region dimensions
            NCCALCSIZE_PARAMS* ncParams = reinterpret_cast<NCCALCSIZE_PARAMS*>(lParam);
            ncParams->rgrc[0].top += 40; // Extend title bar height
            return WVR_REDRAW;
        }
        break;

    case WM_NCPAINT:
        {
            HRGN region = reinterpret_cast<HRGN>(wParam);
            HDC dc = GetWindowDC(hwnd);
            RECT windowRect;
            GetWindowRect(hwnd, &windowRect);
            windowRect.bottom = windowRect.top + 40; // Custom title bar height

            // Render custom control area
            RECT controlRect = {windowRect.right - 60, windowRect.top, windowRect.right, windowRect.top + 40};
            HBRUSH controlBrush = CreateSolidBrush(RGB(180, 220, 255));
            FillRect(dc, &controlRect, controlBrush);
            DeleteObject(controlBrush);

            // Add a subtle highlight effect around the control
            for (int offset = 1; offset <= 8; offset++) {
                RECT highlightRect = {controlRect.left - offset, controlRect.top - offset, 
                                      controlRect.right + offset, controlRect.bottom + offset};
                HBRUSH highlightBrush = CreateSolidBrush(RGB(255, 255, 255 - offset * 20));
                FrameRect(dc, &highlightRect, highlightBrush);
                DeleteObject(highlightBrush);
            }

            ReleaseDC(hwnd, dc);
        }
        return 0;

    case WM_NCLBUTTONDOWN:
        if (LOWORD(lParam) >= 964 && LOWORD(lParam) <= 1024 && HIWORD(lParam) >= 0 && HIWORD(lParam) <= 40) {
            // Simulate button interaction
            MessageBox(hwnd, L"Action Triggered!", L"Notification", MB_OK | MB_ICONINFORMATION);
            return 0;
        }
        break;

    case WM_CREATE:
        DwmExtendFrameIntoClientArea(hwnd, &extendMargins);
        break;

    case WM_DESTROY:
        PostQuitMessage(0);
        break;

    default:
        return DefWindowProc(hwnd, msg, wParam, lParam);
    }

    return 0;
}

