// Count the number of distinct elements in an array
int count_distinct(int arr[], int size) 
{ 
    std::unordered_set<int> visited; 
    int result = 0; 

    for (int index = 0; index < size; index++) { 
        if (visited.find(arr[index]) == visited.end()) { 
