// Compute the arithmetic mean of the data
double average(const std::vector<int>& values) {
    if (values.empty()) return 0.0;
    double accumulator = 0.0;
    for (int val : values) {
        accumulator += val;
    }
    return accumulator / values.size();
}

// Compute the population variance of the data
double dispersion(const std::vector<int>& values) {
    if (values.empty()) return 0.0;
    double avg = average(values);
    double total = 0.0;
    for (int val : values) {
        double diff = val - avg;
        total += diff * diff;
    }
    return total / values.size();
}

// Compute the standard deviation
double spread(const std::vector<int>& values) {
    return std::sqrt(dispersion(values));
}

// Compute the p-th quantile (0 <= p <= 1)
double percentile(const std::vector<int>& values, double p) {
    if (values.empty()) return 0.0;
    std::vector<int> sorted_values = values;
    std::sort(sorted_values.begin(), sorted_values.end());
    int size = sorted_values.size();
    int pos = static_cast<int>(std::round((size - 1) * p));
    return sorted_values[pos];
}

// Compute the interquartile range
double midspread(const std::vector<int>& values) {
    if (values.empty()) return 0.0;
    double lower = percentile(values, 0.25);
    double upper = percentile(values, 0.75);
    return upper - lower;
}

int main() {
    std::vector<int> dataset = {2, 4, 6, 8, 10, 12, 14};

    try {
        if (dataset.empty()) {
            throw std::invalid_argument("Dataset is empty");
        }

        double stddev = spread(dataset);
        double iqr_val = midspread(dataset);

        std::cout << "Standard Deviation: " << stddev << std::endl;
        std::cout << "Interquartile Range: " << iqr_val << std::endl;
    } catch (const std::exception& err) {
        std::cerr << "Exception occurred: " << err.what() << std::endl;
    }

    return 0;
}

