class StaffManager {
public:
    // Add a staff member
    void addStaff(const StaffMember& member) {
        staffList.push_back(member);
    }

    // Remove a staff member by ID
    bool removeStaff(int staffId) {
        for (auto it = staffList.begin(); it != staffList.end(); ++it) {
            if (it->getStaffId() == staffId) {
                staffList.erase(it);
                return true;
            }
        }
        return false;
    }

    // Show all staff members
    void showStaff() const {
        for (const auto& member : staffList) {
            std::cout << "ID: " << member.getStaffId() << ", Name: " << member.getFullName()
                      << ", Role: " << member.getRole() << ", Wage: " << member.getWage() << std::endl;
        }
    }

private:
    std::vector<StaffMember> staffList;
};

