#include <cstring>

using namespace std;

const int GRID_SIZE = 8;
char grid[GRID_SIZE][GRID_SIZE];

void setup_board() {
    for (int row = 0; row < GRID_SIZE; row++) {
        for (int col = 0; col < GRID_SIZE; col++) {
            if (row == 1) grid[row][col] = 'P'; // White pawn
            else if (row == 6) grid[row][col] = 'p'; // Red pawn
            else grid[row][col] = '.';
        }
    }
}

bool check_valid_move(int from_row, int from_col, int to_row, int to_col) {
    if (to_row < 0 || to_row >= GRID_SIZE || to_col < 0 || to_col >= GRID_SIZE) return false;

    if (grid[from_row][from_col] == 'P' && 
        (from_row - to_row != 1 || (abs(from_col - to_col) > 1 || (grid[to_row][to_col] != '.' && from_col == to_col))))
        return false;

    if (grid[from_row][from_col] == 'p' && 
        (to_row - from_row != 1 || (abs(from_col - to_col) > 1 || (grid[to_row][to_col] != '.' && from_col == to_col))))
        return false;

    return true;
}

void execute_move(int from_row, int from_col, int to_row, int to_col) {
    if (check_valid_move(from_row, from_col, to_row, to_col)) {
        grid[to_row][to_col] = grid[from_row][from_col];
        grid[from_row][from_col] = '.';
    }
}

void display_grid() {
    for (int row = 0; row < GRID_SIZE; row++) {
        for (int col = 0; col < GRID_SIZE; col++) {
            cout << grid[row][col] << " ";
        }
        cout << endl;
    }
}

int main() {
    int start_row, start_col, end_row, end_col;
    setup_board();
    display_grid();

    while (true) {
        cin >> start_row >> start_col >> end_row >> end_col;
        execute_move(start_row, start_col, end_row, end_col);
        display_grid();
    }

    return 0;
}

#include <portaudio.h>
#include <cmath>
#include <iostream>

#define AUDIO_SAMPLE_RATE (48000)
#define BUFFER_SIZE (128)
#define TONE_LENGTH (3.0) // seconds

typedef struct
{
    double toneFrequency;
    double currentPhase;
} audioData;

int audioCallback(const void *input, void *output,
                  unsigned long frameCount,
                  const PaStreamCallbackTimeInfo* timeInfo,
                  PaStreamCallbackFlags statusFlags,
                  void *userData)
{
    audioData *info = (audioData *)userData;
    float *outBuffer = (float *)output;
    for (unsigned int idx = 0; idx < frameCount; idx++)
    {
        *outBuffer++ = 0.7 * sin(info->currentPhase); // Generate sine wave
        info->currentPhase += 2.0 * M_PI * info->toneFrequency / AUDIO_SAMPLE_RATE;
        if (info->currentPhase > 2.0 * M_PI) info->currentPhase -= 2.0 * M_PI;
    }
    return paContinue;
}

int main()
{
    PaError result;
    PaStream *audioStream;
    audioData soundData;

    result = Pa_Initialize();
    if (result != paNoError) goto failure;

    soundData.toneFrequency = 523.25; // C5 note
    soundData.currentPhase = 0.0;

    result = Pa_OpenDefaultStream(&audioStream, 0, 1, paFloat32, AUDIO_SAMPLE_RATE,
                                  BUFFER_SIZE, audioCallback, &soundData);
    if (result != paNoError) goto failure;

    result = Pa_StartStream(audioStream);
    if (result != paNoError) goto failure;

    Pa_Sleep((int)(TONE_LENGTH * 1000));

    result = Pa_StopStream(audioStream);
    if (result != paNoError) goto failure;

    result = Pa_CloseStream(audioStream);
    if (result != paNoError) goto failure;

    Pa_Terminate();
    return 0;

failure:
    Pa_Terminate();
    std::cerr << "An error occurred while using the portaudio stream\n";
    std::cerr << "Error code: " << result << "\n";
    std::cerr << "Description: " << Pa_GetErrorText(result) << "\n";
    return -1;
}

