// Compute sum of two constants using inline assembly
static inline uint32_t compute_sum() {
    uint32_t a = 1, b = 2;
    uint32_t result;
    __asm__ __volatile__ (
        "addl %%ebx, %%eax"
        : "=a"(result)           // output operand
        : "a"(a), "b"(b)         // input operands
        : "cc"                   // clobbered condition codes
    );
    return result;
}

#include <iostream>
#include <unordered_map>
using namespace std;

class ListNode { 
public: 
    int value; 
    ListNode *nextNode; 
    ListNode *prevNode; 

    ListNode(int val) : value(val), nextNode(nullptr), prevNode(nullptr) {}
}; 

class DoublyList { 
    ListNode *head; 
    ListNode *tail; 
    unordered_map<int, ListNode*> lookup_table; 

public: 
    DoublyList() : head(nullptr), tail(nullptr) {} 

    void add(int val) { 
        ListNode* newNode = new ListNode(val); 

        if(tail != nullptr) {
            tail->nextNode = newNode; 
            newNode->prevNode = tail; 
        } else {
            head = newNode; 
        }

        tail = newNode; 

        // Store the node address in the hash
        lookup_table[val] = newNode; 
    } 

    bool contains(int val) { 
        return lookup_table.find(val) != lookup_table.end(); 
    } 

    // Optional: Method to delete a node by value
    void erase(int val) {
        if (lookup_table.find(val) == lookup_table.end()) {
            return;
        }

        ListNode* targetNode = lookup_table[val];
        if (targetNode->prevNode) {
            targetNode->prevNode->nextNode = targetNode->nextNode;
        } else {
            head = targetNode->nextNode;
        }

        if (targetNode->nextNode) {
            targetNode->nextNode->prevNode = targetNode->prevNode;
        } else {
            tail = targetNode->prevNode;
        }

        delete targetNode;
        lookup_table.erase(val);
    }
}; 

int main() 
{ 
    DoublyList list; 
    list.add(10); 
    list.add(20); 
    list.add(30); 

    if(list.contains(20)) 
        cout << "20 Found\n"; 
    else
        cout << "20 Not found\n"; 

    if(list.contains(40)) 
        cout << "40 Found\n"; 
    else
        cout << "40 Not found\n"; 

    list.erase(20);

    if(list.contains(20)) 
        cout << "20 Found\n"; 
    else
        cout << "20 Not found\n"; 

    return 0; 
}

#include <cub/cub.cuh>

template <typename DataType>
__global__ void segmentedScanKernel(DataType *d_input, DataType *d_output, int segmentCount, int itemsPerSegment) {
    __shared__ DataType sharedMemory[1024]; // Shared memory buffer for block operations

    int currentSegment = blockIdx.x;
    int threadIndex = threadIdx.x;

    DataType *segmentStartInput = d_input + currentSegment * itemsPerSegment;
    DataType *segmentStartOutput = d_output + currentSegment * itemsPerSegment;

    // Perform inclusive prefix sum within each block
    cub::BlockScan<DataType, 256> blockScanner(sharedMemory);
    DataType localValue = (threadIndex < itemsPerSegment) ? segmentStartInput[threadIndex] : static_cast<DataType>(0);
    DataType runningSum;
    blockScanner.InclusiveSum(localValue, runningSum);

    if (threadIndex < itemsPerSegment) {
        segmentStartOutput[threadIndex] = runningSum;
    }
}

int main() {
    // Configuration parameters
    int totalSegments = 100;
    int elementsPerSegment = 1024;
    int overallSize = totalSegments * elementsPerSegment;

    // Device memory allocation
    float *deviceInput, *deviceOutput;
    cudaMalloc(&deviceInput, overallSize * sizeof(float));
    cudaMalloc(&deviceOutput, overallSize * sizeof(float));
    // Initialize deviceInput with appropriate values

    // Kernel launch configuration
    dim3 threadsPerBlock(256);
    dim3 blocksPerGrid(totalSegments);
    segmentedScanKernel<<<blocksPerGrid, threadsPerBlock>>>(deviceInput, deviceOutput, totalSegments, elementsPerSegment);

    // Retrieve results to host
    float *hostResult = new float[overallSize];
    cudaMemcpy(hostResult, deviceOutput, overallSize * sizeof(float), cudaMemcpyDeviceToHost);

    // Cleanup resources
    cudaFree(deviceInput);
    cudaFree(deviceOutput);
    delete[] hostResult;

    return 0;
}

