extern "C" {
    void gpuElementwiseProduct(int* input1, int* input2, int* output, int length) {
        int* device_input1, * device_input2, * device_output;
        cudaMalloc((void**)&device_input1, length * sizeof(int));
        cudaMalloc((void**)&device_input2, length * sizeof(int));
        cudaMalloc((void**)&device_output, length * sizeof(int));

        cudaMemcpy(device_input1, input1, length * sizeof(int), cudaMemcpyHostToDevice);
        cudaMemcpy(device_input2, input2, length * sizeof(int), cudaMemcpyHostToDevice);

        dim3 blockSize(256);
        dim3 gridSize((length + blockSize.x - 1) / blockSize.x);

        elementwiseProduct<<<gridSize, blockSize>>>(device_input1, device_input2, device_output, length);

        cudaMemcpy(output, device_output, length * sizeof(int), cudaMemcpyDeviceToHost);

        cudaFree(device_input1);
        cudaFree(device_input2);
        cudaFree(device_output);
    }

    __global__ void elementwiseProduct(int* x, int* y, int* z, int n) {
        int index = blockIdx.x * blockDim.x + threadIdx.x;
        if (index < n) {
            z[index] = x[index] * y[index];
        }
    }
}

