std::vector<std::string> enumerateSerialPorts() {
    HKEY hKey;
    LONG status = RegOpenKeyEx(HKEY_LOCAL_MACHINE, TEXT("HARDWARE\\DEVICEMAP\\SERIALCOMM"), 0, KEY_READ, &hKey);
    if (status != ERROR_SUCCESS) {
        return {};
    }

    std::vector<std::string> serial_ports;
    char valueName[1024];
    char valueBuffer[1024];
    DWORD nameLength = 1024;
    DWORD dataLength = 1024;
    DWORD type;

    for (int index = 0; ; index++) {
        nameLength = 1024;
        dataLength = 1024;
        status = RegEnumValue(hKey, index, valueName, &nameLength, NULL, &type, (BYTE*)valueBuffer, &dataLength);
        if (status != ERROR_SUCCESS) {
            break;
        }
        if (type == REG_SZ) {
            serial_ports.push_back(std::string(valueBuffer));
        }
    }

    RegCloseKey(hKey);
    return serial_ports;
}

int main() {
    std::vector<std::string> ports = enumerateSerialPorts();
    for (const auto& port_name : ports) {
        std::cout << port_name << std::endl;
    }
    return 0;
}

