static inline int binaryLog(int value) {
#if defined(__x86_64__) || defined(__i386__)
    // x86 and x86_64 architecture
    int result;
    asm ( "\tbsr %1, %0\n"
        : "=r"(result)
        : "r" (value)
    );
    return result;
#elif defined(__arm__) || defined(__aarch64__)
    // ARM and AArch64 architecture
    return 31 - __builtin_clz(value);
#else
    // Fallback implementation for other architectures
    int result = 0;
    while (value >>= 1) {
        result++;
    }
    return result;
#endif
}

