class CalendarDate {
private:
    int dayNum;
    int monthNum;
    int yearNum;

public:
    // Constructor
    CalendarDate(int d, int m, int y) : dayNum(d), monthNum(m), yearNum(y) {
        if (dayNum < 1 || dayNum > 31) throw std::invalid_argument("Invalid day");
        if (monthNum < 1 || monthNum > 12) throw std::invalid_argument("Invalid month");
        if (yearNum < 0) throw std::invalid_argument("Invalid year");
    }

    // Accessors
    int getDay() const { return dayNum; }
    int getMonth() const { return monthNum; }
    int getYear() const { return yearNum; }

    // Comparison operators
    bool operator==(const CalendarDate& other) const {
        return (dayNum == other.dayNum && monthNum == other.monthNum && yearNum == other.yearNum);
    }

    bool operator<(const CalendarDate& other) const {
        if (yearNum != other.yearNum) return yearNum < other.yearNum;
        if (monthNum != other.monthNum) return monthNum < other.monthNum;
        return dayNum < other.dayNum;
    }

    bool operator>(const CalendarDate& other) const {
        return !(*this < other || *this == other);
    }

    // Additional comparison methods
    bool operator<=(const CalendarDate& other) const {
        return *this < other || *this == other;
    }

    bool operator>=(const CalendarDate& other) const {
        return *this > other || *this == other;
    }

    // String representation for easy testing
    std::string toString() const {
        return std::to_string(dayNum) + "/" + std::to_string(monthNum) + "/" + std::to_string(yearNum);
    }
};

int main() {
    try {
        CalendarDate dateA(10, 10, 2020);
        CalendarDate dateB(10, 11, 2020);

        std::cout << "Date A: " << dateA.toString() << std::endl;
        std::cout << "Date B: " << dateB.toString() << std::endl;

        if (dateA == dateB) {
            std::cout << "The dates are equal." << std::endl;
        } else if (dateA < dateB) {
            std::cout << "Date A is earlier than Date B." << std::endl;
        } else {
            std::cout << "Date A is later than Date B." << std::endl;
        }
    } catch (const std::invalid_argument& err) {
        std::cerr << "Error: " << err.what() << std::endl;
    }

    return 0;
}

