#include <cuda_runtime.h>

// CUDA kernel to convert RGBA image to greyscale
__global__
void rgba_to_grayscale(const uchar4* const inputRgba,
                       unsigned char* const outputGrey,
                       int height, int width)
{
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    if (col >= width || row >= height) {
        return;
    }

    int position = row * width + col;
    uchar4 pixel = inputRgba[position];
    float weightedSum = 0.299f * pixel.x + 0.587f * pixel.y + 0.114f * pixel.z;
    outputGrey[position] = static_cast<unsigned char>(weightedSum);
}

// Host function to launch the CUDA kernel for RGBA to greyscale conversion
void launch_rgba_to_grayscale(const uchar4 * const hostRgbaImage,
                              uchar4 * const deviceRgbaBuffer,
                              unsigned char* const deviceGreyBuffer,
                              size_t imageHeight,
                              size_t imageWidth)
{
    const dim3 threadsPerBlock(16, 16, 1);  // Threads per block
    const dim3 numBlocks((imageWidth + threadsPerBlock.x - 1) / threadsPerBlock.x, 
                         (imageHeight + threadsPerBlock.y - 1) / threadsPerBlock.y, 1);  // Number of blocks

    rgba_to_grayscale<<<numBlocks, threadsPerBlock>>>(deviceRgbaBuffer,
                                                      deviceGreyBuffer,
                                                      imageHeight,
                                                      imageWidth);

    cudaDeviceSynchronize();
    checkCudaErrors(cudaGetLastError());
}

