// Forward declaration
void invoke_dotnet_method(const std::string& dll_path, const std::string& class_name, const std::string& func_name, const std::string& input_value);

int main()
{
    std::string dll_path = "path/to/MyCSharpLibrary.dll";
    std::string class_name = "MyCSharpLibrary.MyClass";
    std::string func_name = "SayHello";
    std::string input_value = "World";

    invoke_dotnet_method(dll_path, class_name, func_name, input_value);

    return 0;
}

void invoke_dotnet_method(const std::string& dll_path, const std::string& class_name, const std::string& func_name, const std::string& input_value)
{
    hostfxr_handle runtime_context = nullptr;
    hostfxr_delegate get_function_ptr = nullptr;

    // Initialize the .NET runtime environment
    hostfxr_initialize_for_runtime_config(
        "path/to/hostfxr.dll",
        "path/to/app.runtimeconfig.json",
        nullptr,
        &runtime_context
    );

    // Retrieve the delegate for loading functions
    hostfxr_runtime_info_get_runtime_delegate(
        runtime_context,
        "System.String::.op_Add(System.String,System.String)",
        &get_function_ptr
    );

    // Load the specified assembly and obtain the function pointer
    void* managed_object = nullptr;
    hostfxr_runtime_info_load_assembly_and_get_function_pointer(
        runtime_context,
        dll_path.c_str(),
        class_name.c_str(),
        func_name.c_str(),
        &managed_object
    );

    // Invoke the method and capture the result
    auto call_func = reinterpret_cast<std::string(*)(const std::string&)>(managed_object);
    std::string output = call_func(input_value);
    std::cout << output << std::endl;

    // Release resources
    hostfxr_close(runtime_context);
}

