#include <Arduino.h>

// Pin assignments for the LED connections
const int LED_PINS[4] = {3, 5, 6, 9};

// Variables to track brightness and fading direction for each LED
byte ledBrightness[4] = {0, 0, 0, 0};
int fadeDir[4] = {1, 1, 1, 1};

// Timing variables for glow and decay phases
unsigned long glowStart[4] = {0, 0, 0, 0};
unsigned long decayStart[4] = {0, 0, 0, 0};

unsigned long currentTime;

// Configuration constants
const int MIN_GLOW_TIME = 400; // Minimum glow phase duration (ms)
const int MAX_GLOW_TIME = 600; // Maximum glow phase duration (ms)

const int MIN_DECAY_TIME = 400; // Minimum decay phase duration (ms)
const int MAX_DECAY_TIME = 600; // Maximum decay phase duration (ms)

void setup() {
  for (int idx = 0; idx < 4; idx++) {
    pinMode(LED_PINS[idx], OUTPUT);
  }
  randomSeed(analogRead(0)); // Initialize random number generator with analog noise
}

void loop() {
  currentTime = millis(); // Capture current time

  for (int j = 0; j < 4; j++) {
    // Handle glow phase: brightness increases or decreases
    if (currentTime - glowStart[j] < random(MIN_GLOW_TIME, MAX_GLOW_TIME)) {
      ledBrightness[j] += 5 * fadeDir[j];

      // Adjust brightness bounds and reverse direction when hitting limits
      if (ledBrightness[j] <= 0 || ledBrightness[j] >= 255) {
        fadeDir[j] = -fadeDir[j];
        ledBrightness[j] = constrain(ledBrightness[j], 0, 255);
      }

      analogWrite(LED_PINS[j], ledBrightness[j]);

    } else if (currentTime - decayStart[j] > random(MIN_DECAY_TIME, MAX_DECAY_TIME)) {
      // Transition from decay to glow phase
      glowStart[j] = currentTime;
      fadeDir[j] = 1;
    } else {
      // Handle decay phase: brightness decreases gradually
      if (ledBrightness[j] > 0) {
        ledBrightness[j] -= 5;
        analogWrite(LED_PINS[j], ledBrightness[j]);
      } else {
        // Transition from glow to decay phase
        decayStart[j] = currentTime;
      }
    }
  }
}

#include <vector>

struct ByteBlock {
    uint64_t location;
    uint8_t* data;
    size_t length;
    std::vector<ByteBlock*> successors;

    ByteBlock(uint64_t loc, uint8_t* buf, size_t len)
        : location(loc), data(buf), length(len) {}

    ~ByteBlock() {
        delete[] data;
        for (auto succ : successors) {
            delete succ;
        }
    }

    void append_successor(ByteBlock* succ) {
        successors.push_back(succ);
    }
};

class BlockTree {
private:
    ByteBlock* head;

public:
    BlockTree() : head(nullptr) {}

    ~BlockTree() {
        if (head) {
            delete head;
        }
    }

    void insert_block(uint64_t loc, uint8_t* buf, size_t len, ByteBlock* prev = nullptr) {
        ByteBlock* block = new ByteBlock(loc, buf, len);
        if (prev) {
            prev->append_successor(block);
        } else {
            head = block;
        }
    }

    ByteBlock* locate_block_at(uint64_t loc) {
        return search_block(head, loc);
    }

private:
    ByteBlock* search_block(ByteBlock* node, uint64_t loc) {
        if (node == nullptr) {
            return nullptr;
        }
        if (node->location == loc) {
            return node;
        }
        for (auto succ : node->successors) {
            ByteBlock* found = search_block(succ, loc);
            if (found) {
                return found;
            }
        }
        return nullptr;
    }
};

#include <QCoreApplication>
