#include <QMutexLocker>

class WorkerTask : public QRunnable {
public:
    WorkerTask(const QString &sqlStatement, const QVariantList &values)
        : m_sql(sqlStatement), m_values(values) {}

    void run() override {
        QMutexLocker lock(&s_mutex);
        QSqlDatabase conn = QSqlDatabase::database("worker_pool_db");

        if (!conn.isOpen()) {
            conn = QSqlDatabase::addDatabase("QSQLITE", "worker_pool_db");
            conn.setDatabaseName("path/to/your/database.db");
            if (!conn.open()) {
                qDebug() << "Connection failed:" << conn.lastError().text();
                return;
            }
        }

        QSqlQuery query(conn);
        query.prepare(m_sql);
        for (const QVariant &val : m_values) {
            query.addBindValue(val);
        }
        if (!query.exec()) {
            qDebug() << "Execution error:" << query.lastError().text();
        }
    }

private:
    QString m_sql;
    QVariantList m_values;
    static QMutex s_mutex;
};

QMutex WorkerTask::s_mutex;

int main(int argc, char *argv[]) {
    QCoreApplication app(argc, argv);

    QThreadPool threadPool;
    threadPool.setMaxThreadCount(4); // Set maximum number of concurrent threads

    // Create and schedule tasks
    WorkerTask *taskA = new WorkerTask("INSERT INTO table_name (column1, column2) VALUES (?, ?)", { "data1", "data2" });
    WorkerTask *taskB = new WorkerTask("INSERT INTO table_name (column1, column2) VALUES (?, ?)", { "data3", "data4" });

    threadPool.start(taskA);
    threadPool.start(taskB);

    // Ensure all pending tasks finish before exiting
    threadPool.waitForDone();

    return app.exec();
}

