// Compute greatest common divisor using Euclidean algorithm
int computeGCD(int x, int y) {
    while (y != 0) {
        int remainder = x % y;
        x = y;
        y = remainder;
    }
    return x;
}

// Check if two integers are relatively prime
bool areRelativelyPrime(int first, int second) {
    return computeGCD(first, second) == 1;
}

#include <windows.h>

// Function to determine the depth of the call stack
int CallStackDepth(DWORD64 baseFrame = 0)
{
    DWORD64 instructionPtr;
    int depthCounter = 0;
    DWORD64 currentFrame;
    PDWORD64 pCurrentFrame, pPreviousFrame;

    if (!baseFrame) // No frame pointer provided; use current one
    {
        // Retrieve the current RBP register value as the frame pointer
        __asm
        {
            mov rax, rbp
            mov currentFrame, rax
        }
    }
    else
    {
        currentFrame = baseFrame;
    }

    pCurrentFrame = (PDWORD64)currentFrame;
    do
    {
        instructionPtr = pCurrentFrame[1];
        pPreviousFrame = pCurrentFrame;
        pCurrentFrame = (PDWORD64)pCurrentFrame[0]; // Move to next stack frame

        // Verify alignment: frame pointer must be 8-byte aligned
        if ((DWORD64)pCurrentFrame & 7)
            break;

        // Ensure frames are growing upward (valid stack layout)
        if (pCurrentFrame <= pPreviousFrame)
            break;

        // Check if memory is accessible for reading two QWORDs
        if (IsBadWritePtr(pCurrentFrame, sizeof(QWORD) * 2))
            break;

        depthCounter++;
    } while (true);

    return depthCounter;
}

