// Determine the median value among three integers
int getMiddleValue(int x, int y, int z) {
    // First, check if x is the median
    if ((x - y) * (z - x) >= 0) {
        return x;
    }
    // Then, check if y is the median
    else if ((y - x) * (z - y) >= 0) {
        return y;
    }
    // If neither x nor y is the median, then z must be the median
    else {
        return z;
    }
}

