    int firstNum, secondNum, thirdNum;

    std::cout << "Enter three numbers: ";
    std::cin >> firstNum >> secondNum >> thirdNum;

    int middle = getMiddleValue(firstNum, secondNum, thirdNum);

    std::cout << "The median is: " << middle << std::endl;

    return 0;
}

