#include <iostream>
#include <string>
#include <unordered_map>
#include <variant>
#include <optional>

enum class TokenType {
    NUMBER,
    VARIABLE,
    OPERATOR,
    PARENTHESIS,
};

struct Token {
    TokenType type;
    std::variant<int, std::string> value;
};

class ExpressionEvaluator {
public:
    ExpressionEvaluator(const std::string& expression, const std::unordered_map<std::string, int>& variable_values)
        : expr_(expression), known_values_(variable_values) {}

    std::optional<bool> compute() {
        std::vector<Token> tokens = parse_tokens(expr_);
        return process_expression(tokens);
    }

private:
    std::vector<Token> parse_tokens(const std::string& expression) {
        std::vector<Token> token_list;
        std::string buffer;
        for (char c : expression) {
            if (std::isspace(c)) {
                continue;
            }
            if (c == '(' || c == ')' || c == '&' || c == '|' || c == '>') {
                if (!buffer.empty()) {
                    token_list.push_back({buffer[0] == '(' || buffer[0] == ')' ? TokenType::PARENTHESIS : TokenType::VARIABLE, buffer});
                    buffer.clear();
                }
                token_list.push_back({TokenType::OPERATOR, std::string(1, c)});
            } else {
                buffer += c;
            }
        }
        if (!buffer.empty()) {
            token_list.push_back({buffer[0] == '(' || buffer[0] == ')' ? TokenType::PARENTHESIS : TokenType::VARIABLE, buffer});
        }
        return token_list;
    }

    std::optional<bool> process_expression(const std::vector<Token>& tokens) {
        std::vector<Token> updated_tokens = tokens;
        for (size_t index = 0; index < updated_tokens.size(); ++index) {
            const auto& current_token = updated_tokens[index];
            if (std::holds_alternative<std::string>(current_token.value)) {
                const std::string& var_name = std::get<std::string>(current_token.value);
                if (known_values_.find(var_name) != known_values_.end()) {
                    updated_tokens[index] = {TokenType::NUMBER, known_values_[var_name]};
                } else if (var_name == "true") {
                    updated_tokens[index] = {TokenType::NUMBER, 1};
                } else if (var_name == "false") {
                    updated_tokens[index] = {TokenType::NUMBER, 0};
                }
            }
        }

        for (const auto& token : updated_tokens) {
            if (std::get_if<std::string>(&token.value)) {
                return std::nullopt; // Contains unresolved variables
            }
        }

        return evaluate_stack(updated_tokens);
    }

    std::optional<bool> evaluate_stack(const std::vector<Token>& tokens) {
        std::vector<std::optional<bool>> evaluation_stack;
        for (const auto& token : tokens) {
            if (token.type == TokenType::NUMBER) {
                evaluation_stack.push_back(std::get<int>(token.value) > 0);
            } else if (token.type == TokenType::OPERATOR) {
                char operation = std::get<std::string>(token.value)[0];
                if (operation == '>') {
                    if (evaluation_stack.size() < 2) return std::nullopt;
                    auto operand_right = evaluation_stack.back(); evaluation_stack.pop_back();
                    auto operand_left = evaluation_stack.back(); evaluation_stack.pop_back();
                    evaluation_stack.push_back(operand_left && operand_right);
                } else if (operation == '&') {
                    if (evaluation_stack.size() < 2) return std::nullopt;
                    auto operand_right = evaluation_stack.back(); evaluation_stack.pop_back();
                    auto operand_left = evaluation_stack.back(); evaluation_stack.pop_back();
                    evaluation_stack.push_back(operand_left && operand_right);
                } else if (operation == '|') {
                    if (evaluation_stack.size() < 2) return std::nullopt;
                    auto operand_right = evaluation_stack.back(); evaluation_stack.pop_back();
                    auto operand_left = evaluation_stack.back(); evaluation_stack.pop_back();
                    evaluation_stack.push_back(operand_left || operand_right);
                }
            }
        }
        if (evaluation_stack.size() != 1) return std::nullopt;
        return evaluation_stack.front();
    }

private:
    std::string expr_;
    std::unordered_map<std::string, int> known_values_;
};

int main() {
    std::string expression = "((X>0) && (Y>5 || Z > 10))";
    std::unordered_map<std::string, int> variable_values = {{"X", -1}};

    ExpressionEvaluator evaluator(expression, variable_values);
    auto outcome = evaluator.compute();

    if (outcome) {
        std::cout << "Expression evaluates to: " << std::boolalpha << *outcome << std::endl;
    } else {
        std::cout << "Expression cannot be fully evaluated with the given values." << std::endl;
    }

    return 0;
}

