// Convert cv::Mat to numpy array (double precision)
boost::python::object convert_matrix_to_array(const cv::Mat& matrix) {
    npy_intp shape[2] = {matrix.rows, matrix.cols};
    PyObject* py_result = PyArray_SimpleNew(2, shape, NPY_FLOAT64);
    std::memcpy(PyArray_DATA(py_result), matrix.ptr<double>(), matrix.total() * matrix.elemSize());
    return boost::python::object(boost::python::handle<>(boost::python::borrowed(py_result)));
}

// Convert numpy array to cv::Mat (double precision)
cv::Mat convert_array_to_matrix(boost::python::object& arr) {
    PyArrayObject* ndarray = reinterpret_cast<PyArrayObject*>(arr.ptr());
    npy_intp* dimensions = PyArray_DIMS(ndarray);
    cv::Mat result(dimensions[0], dimensions[1], CV_64F, PyArray_DATA(ndarray));
    return result;
}

