    boost::python::object iris_data = datasets_mod.attr("load_iris")();
    boost::python::object features = iris_data.attr("data");
    boost::python::object labels = iris_data.attr("target");

    // Initialize and train logistic regression model
    boost::python::object model = linear_models.attr("LogisticRegression")();
    model.attr("fit")(features, labels);

    // Perform prediction
    boost::python::object raw_predictions = model.attr("predict")(features);
    boost::python::list pred_list = boost::python::extract<boost::python::list>(raw_predictions);

    // Transfer predictions to C++ container
    std::vector<int> local_predictions;
    int count = boost::python::len(pred_list);
    for (int idx = 0; idx < count; ++idx) {
        local_predictions.push_back(boost::python::extract<int>(pred_list[idx]));
    }

    // Output results
    for (int val : local_predictions) {
        std::cout << val << " ";
    }
    std::cout << std::endl;
}

