// Function to get current time in seconds with high resolution
double get_time(void) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (double) tv.tv_sec + tv.tv_usec / 1000000.0;
}

// Perform vectorized arithmetic operations using SSE
void perform_vector_ops(double increment, double factor, int count) {
    __m128d inc_vec = _mm_set1_pd(increment);
    __m128d fac_vec = _mm_set1_pd(factor);
    __m128d acc_a = _mm_set_pd(0.3, -0.3);
    __m128d acc_b = _mm_set_pd(0.4, -0.4);
    __m128d vec_x = _mm_set_pd(2.0, 2.2);
    __m128d vec_y = _mm_set_pd(2.3, 2.4);

    int iterations = count / 8; // Each loop performs 8 floating-point ops

    for (int j = 0; j < iterations; j++) {
        vec_x = _mm_mul_pd(vec_x, fac_vec);
        vec_y = _mm_mul_pd(vec_y, fac_vec);
        acc_a = _mm_add_pd(acc_a, inc_vec);
        acc_b = _mm_add_pd(acc_b, inc_vec);
    }

    double out1[2];
    double out2[2];
    _mm_storeu_pd(out1, acc_a);
    _mm_storeu_pd(out2, acc_b);

    double final_val = out1[0] + out1[1] + out2[0] + out2[1];
    printf("Output: %f\n", final_val);
}

int main(int argc, char** argv) {
    if (argc != 2) {
        printf("usage: %s <iterations>\n", argv[0]);
        printf("number of operations: <iterations> millions\n");
        exit(EXIT_FAILURE);
    }

    int num_ops = atoi(argv[1]) * 1000000;
    if (num_ops <= 0)
        num_ops = 1000;

    double a_val = M_E;
    double b_val = 1.0 + 1e-7;
    double start = get_time();
    perform_vector_ops(a_val, b_val, num_ops);
    double elapsed = get_time() - start;
    printf("vector_ops: %.3f s, %.3f Gflops\n", elapsed, (double)num_ops / elapsed / 1e9);
    return EXIT_SUCCESS;
}

