// CUDA kernel to increment array elements
__global__ void kernel_increment(float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = input[idx] + 1.0f;
    }
}

int main() {
    float *srcHost1, *srcHost2, *dstDevice1, *dstDevice2;

    const int arraySize = 1000;

    size_t memoryBytes = arraySize * sizeof(float);

    cudaStream_t streamA, streamB;

    // Allocate pinned host memory
    cudaMallocHost((void**)&srcHost1, memoryBytes);
    cudaMallocHost((void**)&srcHost2, memoryBytes);

    for(int index = 0; index < arraySize; index++)
        srcHost1[index] = static_cast<float>(index);

    cudaMalloc<float>(&dstDevice1, memoryBytes);
    cudaMalloc<float>(&dstDevice2, memoryBytes);

    dim3 threadsPerBlock(16);
    dim3 blocksPerGrid((arraySize + threadsPerBlock.x - 1) / threadsPerBlock.x);

    cudaStreamCreate(&streamA);
    cudaStreamCreate(&streamB);

    cudaMemcpyAsync(dstDevice1, srcHost1, memoryBytes, cudaMemcpyHostToDevice, streamA);
    kernel_increment<<<blocksPerGrid, threadsPerBlock, 0, streamB>>>(dstDevice1, dstDevice2, arraySize);
    cudaMemcpyAsync(srcHost2, dstDevice2, memoryBytes, cudaMemcpyDeviceToHost, streamA);

    printf("Status: %s\n", cudaGetErrorString(cudaGetLastError()));

    cudaDeviceSynchronize();

    printf("Status: %s\n", cudaGetErrorString(cudaGetLastError()));

    cudaStreamDestroy(streamA);
    cudaStreamDestroy(streamB);

    cudaFree(dstDevice1);
    cudaFree(dstDevice2);

    // Free pinned host memory
    cudaFreeHost(srcHost1);
    cudaFreeHost(srcHost2);

    return 0;
}

