#include <vector>
#include <memory>

struct Coordinate {
    float horizontal, vertical;
};

struct BoundingArea {
    float left, top;  // Top-left corner
    float extentX, extentY;

    bool encloses(const Coordinate& pt) const {
        return pt.horizontal >= left && pt.horizontal <= left + extentX &&
               pt.vertical >= top && pt.vertical <= top + extentY;
    }

    bool overlapsWith(const BoundingArea& other) const {
        return left < other.left + other.extentX && left + extentX > other.left &&
               top < other.top + other.extentY && top + extentY > other.top;
    }
};

class SpatialPartitionNode {
public:
    SpatialPartitionNode(const BoundingArea& region, int limit)
        : region(region), limit(limit), split(false) {}

    void addPoint(const Coordinate& pt);
    void divideRegion();
    std::vector<Coordinate> getPointsInArea(const BoundingArea& searchArea);

private:
    BoundingArea region;
    int limit;
    bool split;
    std::vector<Coordinate> storedPoints;
    std::unique_ptr<SpatialPartitionNode> upperLeft, upperRight, lowerLeft, lowerRight;
};

void SpatialPartitionNode::addPoint(const Coordinate& pt) {
    if (!region.encloses(pt)) {
        return;  // Point lies outside this node's area
    }

    if (static_cast<int>(storedPoints.size()) < limit) {
        storedPoints.push_back(pt);
    } else {
        if (!split) {
            divideRegion();
        }

        upperLeft->addPoint(pt);
        upperRight->addPoint(pt);
        lowerLeft->addPoint(pt);
        lowerRight->addPoint(pt);
    }
}

void SpatialPartitionNode::divideRegion() {
    float halfWidth = region.extentX / 2.0f;
    float halfHeight = region.extentY / 2.0f;
    float originX = region.left;
    float originY = region.top;

    upperLeft = std::make_unique<SpatialPartitionNode>(
        BoundingArea{originX, originY, halfWidth, halfHeight}, limit);
    upperRight = std::make_unique<SpatialPartitionNode>(
        BoundingArea{originX + halfWidth, originY, halfWidth, halfHeight}, limit);
    lowerLeft = std::make_unique<SpatialPartitionNode>(
        BoundingArea{originX, originY + halfHeight, halfWidth, halfHeight}, limit);
    lowerRight = std::make_unique<SpatialPartitionNode>(
        BoundingArea{originX + halfWidth, originY + halfHeight, halfWidth, halfHeight}, limit);

    split = true;
}

std::vector<Coordinate> SpatialPartitionNode::getPointsInArea(const BoundingArea& searchArea) {
    std::vector<Coordinate> result;

    if (!region.overlapsWith(searchArea)) {
        return result;
    }

    for (const auto& coord : storedPoints) {
        if (searchArea.encloses(coord)) {
            result.push_back(coord);
        }
    }

    if (split) {
        std::vector<Coordinate> ulPoints = upperLeft->getPointsInArea(searchArea);
        std::vector<Coordinate> urPoints = upperRight->getPointsInArea(searchArea);
        std::vector<Coordinate> llPoints = lowerLeft->getPointsInArea(searchArea);
        std::vector<Coordinate> lrPoints = lowerRight->getPointsInArea(searchArea);

        result.insert(result.end(), ulPoints.begin(), ulPoints.end());
        result.insert(result.end(), urPoints.begin(), urPoints.end());
        result.insert(result.end(), llPoints.begin(), llPoints.end());
        result.insert(result.end(), lrPoints.begin(), lrPoints.end());
    }

    return result;
}

