class BaseEvent
{
public:
    virtual ~BaseEvent() = default;
};

template <typename DataType>
class ConcreteEvent : public BaseEvent
{
public:
    DataType payload;

    explicit ConcreteEvent(const DataType& value)
        : payload{value} {}
};

class MessageCenter
{
public:
    template <typename T>
    void AddListener(std::function<void(const T&)> handler)
    {
        auto typeKey = std::type_index(typeid(ConcreteEvent<T>));
        m_subscribers[typeKey].push_back([handler](const BaseEvent *eventPtr) {
            const auto &concreteEvent = static_cast<const ConcreteEvent<T> *>(eventPtr);
            handler(concreteEvent->payload);
        });
    }

    template <typename T>
    void Dispatch(const T &value)
    {
        const auto typeKey = std::type_index(typeid(ConcreteEvent<T>));
        if (m_subscribers.find(typeKey) == m_subscribers.end())
        {
            return;
        }

        const auto &handlers = m_subscribers[typeKey];
        for (const auto &handler : handlers)
        {
            handler(&ConcreteEvent<T>(value));
        }
    }

private:
    std::unordered_map<std::type_index, std::vector<std::function<void(const BaseEvent *)>>> m_subscribers;
};

int main()
{
    MessageCenter center;

    center.AddListener<int>([](const int &value) {
        std::cout << "Int message received: " << value << std::endl;
    });

    center.AddListener<double>([](const double &value) {
        std::cout << "Double message received: " << value << std::endl;
    });

    center.Dispatch<int>(100);
    center.Dispatch<double>(2.71828);

    return 0;
}

