                break;
            case BISHOP:
                symbol = (layout[row][col].side == LIGHT) ? 'B' : 'b';
                break;
            case QUEEN:
                symbol = (layout[row][col].side == LIGHT) ? 'Q' : 'q';
                break;
            case MONARCH:
                symbol = (layout[row][col].side == LIGHT) ? 'M' : 'm';
                break;
