bool check_move_validity(const Grid& layout, int from_row, int from_col, int to_row, int to_col) {
    // Verify coordinates are within bounds
    if (from_row < 0 || from_row >= GRID_SIZE ||
        from_col < 0 || from_col >= GRID_SIZE ||
        to_row < 0 || to_row >= GRID_SIZE ||
        to_col < 0 || to_col >= GRID_SIZE) {
        return false;
    }

    // Prevent moving onto own piece
    if (layout[from_row][from_col].side == layout[to_row][to_col].side) {
        return false;
    }

    // TODO: Implement specific piece movement rules
    // For now, only basic validation is performed

    return true;
}

bool execute_move(Grid& layout, int from_row, int from_col, int to_row, int to_col) {
    if (check_move_validity(layout, from_row, from_col, to_row, to_col)) {
        layout[to_row][to_col] = layout[from_row][from_col];
        layout[from_row][from_col].kind = BLANK;
        layout[from_row][from_col].side = NO_COLOR;
        return true;
    }
    return false;
}

Grid initialize_layout() {
    Grid layout(GRID_SIZE, vector<Chessman>(GRID_SIZE, { BLANK, NO_COLOR }));

    for (int i = 0; i < GRID_SIZE; ++i) {
