        ChessPiece light_arrangement[8] = { ROOK, HORSE, BISHOP, MONARCH, QUEEN, BISHOP, HORSE, ROOK };
        layout[0][i] = { dark_arrangement[i], DARK };
        layout[7][i] = { light_arrangement[i], LIGHT };
    }

    return layout;
}

