bool establishConnection(const QString &dbDriver, const QString &dbName, const QString &server, const QString &login, const QString &pass) {
    QSqlDatabase connection = QSqlDatabase::addDatabase(dbDriver);
    connection.setHostName(server);
    connection.setDatabaseName(dbName);
    connection.setUserName(login);
    connection.setPassword(pass);

    if (!connection.open()) {
        QTextStream(stderr) << "Connection error: " << connection.lastError().text() << "\n";
        return false;
    }
    return true;
}

