    // Set up query based on database type
    if (driver == "QPSQL") {
        sqlQuery.prepare("SELECT * FROM information_schema.columns WHERE table_name = :table LIMIT 0");
    } else if (driver == "QMYSQL") {
        sqlQuery.prepare("SELECT * FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = :table LIMIT 0");
    } else if (driver == "QODBC") {
