#include <cstdint>

void decompressByUnpacking1(uint8_t *destination, uint8_t *source, uint32_t size) {
    static uint8_t table[4096];
    static const uint8_t table5[8] = { 0, 1, 2, 0, 3, 0, 0, 0 };

    if (table[0] == 0) {    
        /* populate lookup table */
        for (int idx = 0; idx < 4096; idx++) {
            table[idx] = (table5[(idx >> 0) & 7] << 0) +
                         (table5[(idx >> 3) & 7] << 2) +
                         (table5[(idx >> 6) & 7] << 4) +
                         (table5[(idx >> 9) & 7] << 6);
        }
    }
    uint8_t previous = 0;
    for (; size >= 4; size -= 4, source++, destination += 4) {
        uint8_t offset = *source;
        destination[0] = table[offset] >> 9;
        destination[1] = (table[offset] >> 6) & 7;
        destination[2] = (table[offset] >> 3) & 7;
        destination[3] = table[offset] & 7;
    }
    switch (size) {
        case 3:
            previous = *source;
            destination[2] = table5[previous >> 4];
            destination[1] = table5[(previous >> 2) & 3];
            /* fall through */
        case 2:
            previous = *source;
            destination[1] = table5[(previous >> 2) & 3];
            destination[0] = table5[previous & 3];
            /* fall through */
        case 1:
            destination[0] = table5[*source];
            break;
    }
}

#include <vector>
using namespace std;

// Find median of three elements and place it at the end position
int medianOfThree(vector<int> &data, int left, int right) {
    int center = left + (right - left) / 2;

    // Ensure arr[left] <= arr[center]
    if (data[left] > data[center]) swap(data[left], data[center]);

    // Ensure arr[left] <= arr[right]
    if (data[left] > data[right]) swap(data[left], data[right]);

    // Ensure arr[center] <= arr[right]
    if (data[center] > data[right]) swap(data[center], data[right]);

    // Move median to the end position
    swap(data[center], data[right]);

    return data[right];
}

