    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    double getAverageScore() const {
        if (scores.empty()) return 0.0;
        double accumulator = 0.0;
        for (double score : scores) {
            accumulator += score;
        }
        return accumulator / scores.size();
    }
    const std::vector<Publication>& getPublications() const { return publications; }

    // Utility functions
    void displayPublications() const {
        for (const Publication& publication : publications) {
            std::cout << "Title: " << publication.getName() << ", Venue: " << publication.getPublicationName()
                      << ", Year: " << publication.getReleaseYear() << ", Influence: " << publication.getInfluenceMetric() << std::endl;
        }
    }

private:
    std::string firstName;
    std::string lastName;
    std::vector<double> scores;
    std::vector<Publication> publications;
};

