enum class TokenType {
    NUMBER,
    OPERATOR,
    FUNCTION,
    LEFT_PAREN,
    RIGHT_PAREN,
    END
};

struct Token {
    TokenType type;
    std::string value;
};

std::vector<Token> parseExpression(const std::string& expr) {
    std::vector<Token> resultTokens;
    std::string currentNumber;

    for (size_t index = 0; index < expr.size(); ++index) {
        char ch = expr[index];

        if (std::isdigit(ch) || ch == '.') {
            currentNumber += ch;
        } else {
            if (!currentNumber.empty()) {
                resultTokens.push_back({TokenType::NUMBER, currentNumber});
                currentNumber.clear();
            }

            if (std::isalpha(ch)) {
                std::string functionName;
                while (std::isalpha(ch)) {
                    functionName += ch;
                    ch = expr[++index];
                }
                resultTokens.push_back({TokenType::FUNCTION, functionName});
                --index; // Compensate for the extra increment
            } else if (ch == '(') {
                resultTokens.push_back({TokenType::LEFT_PAREN, "("});
            } else if (ch == ')') {
                resultTokens.push_back({TokenType::RIGHT_PAREN, ")"});
            } else if (ch == '+' || ch == '-' || ch == '*' || ch == '/' || ch == '^') {
                resultTokens.push_back({TokenType::OPERATOR, std::string(1, ch)});
            } else if (!std::isspace(ch)) {
                throw std::runtime_error("Unexpected character: " + std::string(1, ch));
            }
        }
    }

    if (!currentNumber.empty()) {
        resultTokens.push_back({TokenType::NUMBER, currentNumber});
    }

    resultTokens.push_back({TokenType::END, ""});
    return resultTokens;
}

