// Convert a date string in YYYY-MM-DD format to a time_point
std::chrono::system_clock::time_point parseDateString(const std::string& dateString) {
    std::tm timeStruct = {};
    std::istringstream stream(dateString);
    stream >> std::get_time(&timeStruct, "%Y-%m-%d");
    if (stream.fail()) {
        throw std::invalid_argument("Incorrect date format. Expected format: YYYY-MM-DD");
    }
    return std::chrono::system_clock::from_time_t(std::mktime(&timeStruct));
}

// Compute the number of days between two date strings
long calculateDaysBetween(const std::string& firstDate, const std::string& secondDate) {
    auto point1 = parseDateString(firstDate);
    auto point2 = parseDateString(secondDate);
    auto diffDuration = std::chrono::duration_cast<std::chrono::days>(point2 - point1);
    return diffDuration.count();
}

int main() {
    std::string startDate = "2023-01-01";
    std::string endDate = "2023-12-31";
    try {
        long daysDiff = calculateDaysBetween(startDate, endDate);
        std::cout << "The difference between " << startDate << " and " << endDate << " is " << daysDiff << " days." << std::endl;
    } catch (const std::invalid_argument& error) {
        std::cerr << error.what() << std::endl;
    }
    return 0;
}

