// Generate the first n Fibonacci numbers
std::vector<int> generateFibonacci(int count) {
    std::vector<int> result;
    if (count <= 0) return result;
    if (count == 1) {
        result.push_back(0);
        return result;
    }
    if (count == 2) {
        result.push_back(0);
        result.push_back(1);
        return result;
    }

    result.push_back(0);
    result.push_back(1);

    for (int index = 2; index < count; index++) {
        int nextNumber = result[index - 1] + result[index - 2];
        result.push_back(nextNumber);
    }

    return result;
}

int main() {
    int n = 10;
    std::vector<int> fibSequence = generateFibonacci(n);
    for (int value : fibSequence) {
        std::cout << value << " ";
    }
    return 0;
}

#include <iostream>
#include <chrono>
#include <vector>

template <typename T>
std::vector<T> generateSequence(T begin, T finish) {
    size_t count = finish - begin;
    std::vector<T> data;
    data.reserve(count);  // Pre-allocate memory
    for (size_t index = 0; index < count; ++index) {
        data.push_back(begin + index);
    }
    return data;
}

int main() {
    auto startTime = std::chrono::high_resolution_clock::now();
    std::vector<int> numbers = generateSequence(0, 1024);
    auto endTime = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> duration = endTime - startTime;
    std::cout << "elapsed time: " << duration.count() << "s\n";
}

