// Main application entry point
int main(int, char**)
{
    // Initialize SDL subsystems
    if (!SDL_Init(SDL_INIT_VIDEO | SDL_INIT_GAMEPAD))
    {
        printf("Error: SDL_Init() failed: %s\n", SDL_GetError());
        return -1;
    }

    // Create the main application window
    Uint32 create_flags = SDL_WINDOW_OPENGL | SDL_WINDOW_RESIZABLE | SDL_WINDOW_HIDDEN;
    SDL_Window* app_window = SDL_CreateWindow("Dear ImGui SDL3 + SDL_Renderer Demo", 1280, 720, create_flags);
    if (app_window == nullptr)
    {
        printf("Error: SDL_CreateWindow() failed: %s\n", SDL_GetError());
        return -1;
    }

    // Setup renderer and vertical sync
    SDL_Renderer* graphics_renderer = SDL_CreateRenderer(app_window, nullptr);
    SDL_SetRenderVSync(graphics_renderer, 1);
    if (graphics_renderer == nullptr)
    {
        SDL_Log("Error: SDL_CreateRenderer() failed: %s\n", SDL_GetError());
        return -1;
    }

    // Center and show the window
    SDL_SetWindowPosition(app_window, SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED);
    SDL_ShowWindow(app_window);

    // Initialize Dear ImGui context
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& imgui_io = ImGui::GetIO(); (void)imgui_io;
    imgui_io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard; // Enable keyboard navigation
    imgui_io.ConfigFlags |= ImGuiConfigFlags_NavEnableGamepad;  // Enable gamepad navigation

    // Apply dark color scheme
    ImGui::StyleColorsDark();

    // Initialize platform and renderer bindings
    ImGui_ImplSDL3_InitForSDLRenderer(app_window, graphics_renderer);
    ImGui_ImplSDLRenderer3_Init(graphics_renderer);

    // Font loading configuration (commented out for brevity)
    // io.Fonts->AddFontDefault();
    // io.Fonts->AddFontFromFileTTF(...);

    // Application state variables
    bool display_demo_window = true;
    bool display_secondary_window = false;
    ImVec4 background_color = ImVec4(0.45f, 0.55f, 0.60f, 1.00f);

    // Main rendering loop
    bool exit_requested = false;
#ifdef __EMSCRIPTEN__
    io.IniFilename = nullptr;
    EMSCRIPTEN_MAINLOOP_BEGIN
#else
    while (!exit_requested)
#endif
    {
        // Event handling
        SDL_Event pending_event;
        while (SDL_PollEvent(&pending_event))
        {
            ImGui_ImplSDL3_ProcessEvent(&pending_event);
            if (pending_event.type == SDL_EVENT_QUIT)
                exit_requested = true;
            if (pending_event.type == SDL_EVENT_WINDOW_CLOSE_REQUESTED && 
                pending_event.window.windowID == SDL_GetWindowID(app_window))
                exit_requested = true;
        }

        // Skip rendering if window is minimized
        if (SDL_GetWindowFlags(app_window) & SDL_WINDOW_MINIMIZED)
        {
            SDL_Delay(10);
            continue;
        }

        // Begin new frame for Dear ImGui
        ImGui_ImplSDLRenderer3_NewFrame();
        ImGui_ImplSDL3_NewFrame();
        ImGui::NewFrame();

        // 1. Display demo window
        if (display_demo_window)
            ImGui::ShowDemoWindow(&display_demo_window);

        // 2. Simple custom window
        {
            static float animation_value = 0.0f;
            static int click_counter = 0;

            ImGui::Begin("Hello, world!"); // Create named window

            ImGui::Text("This is some useful text.");
            ImGui::Checkbox("Demo Window", &display_demo_window);
            ImGui::Checkbox("Secondary Window", &display_secondary_window);
            ImGui::SliderFloat("Animation", &animation_value, 0.0f, 1.0f);
            ImGui::ColorEdit3("Background Color", (float*)&background_color);

            if (ImGui::Button("Increment Counter"))
                click_counter++;

            ImGui::SameLine();
            ImGui::Text("Clicks: %d", click_counter);
            ImGui::Text("Performance: %.3f ms/frame (%.1f FPS)", 
                       1000.0f / imgui_io.Framerate, imgui_io.Framerate);

            ImGui::End();
        }

        // 3. Secondary simple window
        if (display_secondary_window)
        {
            ImGui::Begin("Additional Window", &display_secondary_window);
            ImGui::Text("Greetings from another panel!");
            if (ImGui::Button("Dismiss"))
                display_secondary_window = false;
            ImGui::End();
        }

        // Render Dear ImGui data
        ImGui::Render();

        // Clear screen with configured background color
        SDL_SetRenderDrawColorFloat(graphics_renderer, 
                                   background_color.x, background_color.y, 
                                   background_color.z, background_color.w);
        SDL_RenderClear(graphics_renderer);

        // Render ImGui draw data
        ImGui_ImplSDLRenderer3_RenderDrawData(ImGui::GetDrawData(), graphics_renderer);
        SDL_RenderPresent(graphics_renderer);
    }

#ifdef __EMSCRIPTEN__
    EMSCRIPTEN_MAINLOOP_END;
#endif

    // Cleanup resources
    ImGui_ImplSDLRenderer3_Shutdown();
    ImGui_ImplSDL3_Shutdown();
    ImGui::DestroyContext();
    SDL_DestroyRenderer(graphics_renderer);
    SDL_DestroyWindow(app_window);
    SDL_Quit();

    return 0;
}

