void EnderDragonRenderer::setupRotations(
    std::shared_ptr<Mob> entity,
    float                bob,
    float                bodyRot,
    float                partialTicks
) {
    // 4J - dynamic cast required because we aren't using templates/generics in
    // our version
    std::shared_ptr<EnderDragon> dragon =
        std::dynamic_pointer_cast<EnderDragon>(entity);
    // 4J - reorganised a bit so we can free allocations
    double      posComponents[3];
    doubleArray positionData = doubleArray(posComponents, 3);
    dragon->getLatencyPos(positionData, 7, partialTicks);
    float yawRotation = positionData[0];
    // dragon->getLatencyPos(positionData, 5, partialTicks);
    // float rot2 = positionData[1];
    // dragon->getLatencyPos(positionData, 10,partialTicks);
    // rot2 -= positionData[1];
    float pitchRotation = dragon->getTilt(partialTicks);
    glRotatef(-yawRotation, 0, 1, 0);
    glRotatef(pitchRotation, 1, 0, 0);
    // glRotatef(pitchRotation * 10, 1, 0, 0);
    glTranslatef(0, 0, 1);
    if (dragon->deathTime > 0) {
        float fallAnim = (dragon->deathTime + partialTicks - 1) / 20.0f * 1.6f;
        fallAnim       = sqrt(fallAnim);
        if (fallAnim > 1) fallAnim = 1;
        glRotatef(fallAnim * getFlipDegrees(dragon), 0, 0, 1);
    }
}

void EnderDragonRenderer::renderModel(
    std::shared_ptr<Entity> entity,
    float                   timeWeight,
    float                   weightScale,
    float                   bob,
    float                   headRotMinusBodyRot,
    float                   headRotx,
    float                   scale
) {
    // 4J - dynamic cast required because we aren't using templates/generics in
    // our version
    std::shared_ptr<EnderDragon> dragon =
        std::dynamic_pointer_cast<EnderDragon>(entity);
    if (dragon->dragonDeathTime > 0) {
        float timeFactor = (dragon->dragonDeathTime / 180.0f);
        glDepthFunc(GL_LEQUAL);
        glEnable(GL_ALPHA_TEST);
        glAlphaFunc(GL_GREATER, timeFactor);
        bindTexture(
            dragon->customTextureUrl,
            TN_MOB_ENDERDRAGON_SHUFFLE
        ); // 4J was "/mob/enderdragon/shuffle.png"
        model->render(
            dragon,
            timeWeight,
            weightScale,
            bob,
            headRotMinusBodyRot,
            headRotx,
            scale,
            true
        );
        glAlphaFunc(GL_GREATER, 0.1f);
        glDepthFunc(GL_EQUAL);
    }
    bindTexture(dragon->customTextureUrl, dragon->getTexture());
    model->render(dragon, timeWeight, weightScale, bob, headRotMinusBodyRot, headRotx, scale, true);
    if (dragon->hurtTime > 0) {
        glDepthFunc(GL_EQUAL);
        glDisable(GL_TEXTURE_2D);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
        glColor4f(1, 0, 0, 0.5f);
#ifdef __PSVITA__
        // AP - not sure that the usecompiled flag is supposed to be false. This
        // makes it really slow on vita. Making it true still seems to look the
        // same
        model->render(
            dragon,
            timeWeight,
            weightScale,
            bob,
            headRotMinusBodyRot,
            headRotx,
            scale,
            true
        );
#else
        model->render(
            dragon,
            timeWeight,
            weightScale,
            bob,
            headRotMinusBodyRot,
            headRotx,
            scale,
            false
        );
#endif
        glEnable(GL_TEXTURE_2D);
        glDisable(GL_BLEND);
        glDepthFunc(GL_LEQUAL);
    }
}

void EnderDragonRenderer::render(
    std::shared_ptr<Entity> entity,
    double                  x,
    double                  y,
    double                  z,
    float                   rot,
    float                   partialTicks
) {
    // 4J - dynamic cast required because we aren't using templates/generics in
    // our version
    std::shared_ptr<EnderDragon> dragon =
        std::dynamic_pointer_cast<EnderDragon>(entity);
    EnderDragonRenderer::bossInstance = dragon;
    if (currentModel != DragonModel::MODEL_ID) {
        model        = new DragonModel(0);
        currentModel = DragonModel::MODEL_ID;
    }
    MobRenderer::render(dragon, x, y, z, rot, partialTicks);
    if (dragon->nearestCrystal != NULL) {
        float timeVal = dragon->nearestCrystal->time + partialTicks;
        float heightFactor = sin(timeVal * 0.2f) / 2 + 0.5f;
        heightFactor       = (heightFactor * heightFactor + heightFactor) * 0.2f;
        float xd = (float)(dragon->nearestCrystal->x - dragon->x
                           - (dragon->xo - dragon->x) * (1 - partialTicks));
        float yd = (float)(heightFactor + dragon->nearestCrystal->y - 1 - dragon->y
                           - (dragon->yo - dragon->y) * (1 - partialTicks));
        float zd = (float)(dragon->nearestCrystal->z - dragon->z
                           - (dragon->zo - dragon->z) * (1 - partialTicks));
        float sdd = sqrt(xd * xd + zd * zd);
        float dd  = sqrt(xd * xd + yd * yd + zd * zd);
        // this fixes a problem when the dragon is hit and the beam goes black
        // because the diffuse colour isn't being reset in MobRenderer::render
        glColor4f(1, 1, 1, 1);
        glPushMatrix();
        glTranslatef((float)x, (float)y + 2, (float)z);
        glRotatef((float)(-atan2(zd, xd)) * 180.0f / PI - 90.0f, 0, 1, 0);
        glRotatef((float)(-atan2(sdd, yd)) * 180.0f / PI - 90.0f, 1, 0, 0);
        // 4J-PB - Rotating the healing beam too
        static float rotationSpeed = 0.0f;
        glRotatef(rotationSpeed, 0, 0, 1);
        rotationSpeed += 0.5f; // 4J - rate of rotation changed from 5.0 to 0.5 for
                      // photosensitivity reasons
        if (rotationSpeed >= 360.0f) {
            rotationSpeed = 0.0f;
        }
        Tesselator* t = Tesselator::getInstance();
        Lighting::turnOff();
        glDisable(GL_CULL_FACE);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_DST_ALPHA);
        bindTexture(
            TN_MOB_ENDERDRAGON_BEAM
        ); // 4J was "/mob/enderdragon/beam.png"
        glShadeModel(GL_SMOOTH);
        float v0 = 0
                 - (dragon->tickCount + partialTicks)
                       * 0.005f; // 4J - rate of movement changed from 0.01 to
                                 // 0.005 for photosensitivity reasons
        float v1 = sqrt(xd * xd + yd * yd + zd * zd) / 32.0f
                 - (dragon->tickCount + partialTicks) * 0.005f;
        t->begin(GL_TRIANGLE_STRIP);
        int steps = 8;
        for (int i = 0; i <= steps; i++) {
            double angle = i % steps * PI * 2 / steps;
            float  s = sin(i % steps * PI * 2 / steps) * 0.75f;
            float  c = cos(i % steps * PI * 2 / steps) * 0.75f;
            float  u = i % steps * 1.0f / steps;
            // t->color(0x000000);
            t->vertexUV(s * 0.2f, c * 0.2f, 0, u, v1);
            // t->color(0xffffff);
            t->vertexUV(s, c, dd, u, v0);
        }
        t->end();
        glEnable(GL_CULL_FACE);
        glShadeModel(GL_FLAT);
        glDisable(GL_BLEND);
        glPopMatrix();
        Lighting::turnOn();
    }
}

void EnderDragonRenderer::additionalRendering(
    std::shared_ptr<Mob> entity,
    float                partialTicks
) {
    // 4J - dynamic cast required because we aren't using templates/generics in
    // our version
    std::shared_ptr<EnderDragon> dragon =
        std::dynamic_pointer_cast<EnderDragon>(entity);
    MobRenderer::additionalRendering(dragon, partialTicks);
    Tesselator* t = Tesselator::getInstance();
    if (dragon->dragonDeathTime > 0) {
        Lighting::turnOff();
        float timeFactor = ((dragon->dragonDeathTime + partialTicks) / 180.0f);
        float overDrive = 0;
        if (timeFactor > 0.8f) {
            overDrive = (timeFactor - 0.8f) / 0.2f;
        }
        Random randomGen(432);
        glDisable(GL_TEXTURE_2D);
        glShadeModel(GL_SMOOTH);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_ONE);
        glDisable(GL_ALPHA_TEST);
        glEnable(GL_CULL_FACE);
        glDepthMask(false);
        glPushMatrix();
        glTranslatef(0, -1, -2);
        for (int i = 0; i < (timeFactor + timeFactor * timeFactor) / 2 * 60; i++) {
            glRotatef(randomGen.nextFloat() * 360, 1, 0, 0);
            glRotatef(randomGen.nextFloat() * 360, 0, 1, 0);
            glRotatef(randomGen.nextFloat() * 360, 0, 0, 1);
            glRotatef(randomGen.nextFloat() * 360, 1, 0, 0);
            glRotatef(randomGen.nextFloat() * 360, 0, 1, 0);
            glRotatef(randomGen.nextFloat() * 360 + timeFactor * 90, 0, 0, 1);
            t->begin(GL_TRIANGLE_FAN);
            float dist = randomGen.nextFloat() * 20 + 5 + overDrive * 10;
            float w    = randomGen.nextFloat() * 2 + 1 + overDrive * 2;
            t->color(0xffffff, (int)(255 * (1 - overDrive)));
            t->vertex(0, 0, 0);
            t->color(0xff00ff, 0);
            t->vertex(-0.866 * w, dist, -0.5f * w);
            t->vertex(+0.866 * w, dist, -0.5f * w);
            t->vertex(0, dist, 1 * w);
            t->vertex(-0.866 * w, dist, -0.5f * w);
            t->end();
        }
        glPopMatrix();
        glDepthMask(true);
        glDisable(GL_CULL_FACE);
        glDisable(GL_BLEND);
        glShadeModel(GL_FLAT);
        glColor4f(1, 1, 1, 1);
        glEnable(GL_TEXTURE_2D);
        glEnable(GL_ALPHA_TEST);
        Lighting::turnOn();
    }
}

int EnderDragonRenderer::prepareArmor(
    std::shared_ptr<Mob> entity,
    int                  layer,
    float                partialTicks
) {
    // 4J - dynamic cast required because we aren't using templates/generics in
    // our version
    std::shared_ptr<EnderDragon> dragon =
        std::dynamic_pointer_cast<EnderDragon>(entity);
    if (layer == 1) {
        glDepthFunc(GL_LEQUAL);
    }
    if (layer != 0) return -1;
    bindTexture(
        TN_MOB_ENDERDRAGON_ENDEREYES
    ); // 4J was "/mob/enderdragon/ender_eyes.png"
    float brightness = 1;
    glEnable(GL_BLEND);
    // 4J Stu - We probably don't need to do this on 360 either (as we force it
    // back on the renderer) However we do want it off for other platforms that
    // don't force it on in the render lib CBuff handling Several texture packs
    // have fully transparent bits that break if this is off
#ifdef _XBOX
    glDisable(GL_ALPHA_TEST);
#endif
    glBlendFunc(GL_ONE, GL_ONE);
    glDisable(GL_LIGHTING);
    glDepthFunc(GL_EQUAL);
    if (SharedConstants::TEXTURE_LIGHTING) {
        int col = 0xf0f0;
        int u   = col % 65536;
        int v   = col / 65536;
        glMultiTexCoord2f(GL_TEXTURE1, u / 1.0f, v / 1.0f);
        glColor4f(1, 1, 1, 1);
    }
    glEnable(GL_LIGHTING);
    glColor4f(1, 1, 1, brightness);
    return 1;
}

