#include <cstdint>
#include <cstdio>
#include "ckernel.h"
#include "llk_defs.h"

// Global configuration variables
std::uint32_t unp_cfg_context          = 0;
std::uint32_t pack_sync_tile_dst_ptr   = 0;
std::uint32_t math_sync_tile_dst_index = 0;

#ifdef LLK_TRISC_UNPACK
#include "experimental/llk_unpack_AB_sub_bcast_col_custom.h"
#include "llk_unpack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& config = params->formats;
#endif
    // Configure unpack hardware with specified formats
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        config.unpack_A_src, config.unpack_B_src, config.unpack_A_dst, config.unpack_B_dst, 
        FACE_R_DIM, FACE_R_DIM, 4 /*num_faces */, 4 /* num_faces */);

    // Initialize unpack operation for broadcast column
    _llk_unpack_AB_sub_bcast_col_init_custom_<BROADCAST_TYPE>();

    // Execute unpack operation with provided buffers
    _llk_unpack_AB_sub_bcast_col_custom_<BROADCAST_TYPE>(
        L1_ADDRESS(params->buffer_A[0]), L1_ADDRESS(params->buffer_B[0]), CT_DIM);
}
#endif

#ifdef LLK_TRISC_MATH
#include "experimental/llk_math_eltwise_binary_custom.h"
#include "llk_math_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& config = params->formats;
#endif
    // Initialize math synchronization and configuration
    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(config.math, config.math);

    // Initialize element-wise binary operation with fidelity settings
    _llk_math_eltwise_binary_init_custom_<ELTWISE_BINARY_OP, BROADCAST_TYPE, MATH_FIDELITY>(4, 0);

    // Wait for destination buffer availability
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Execute custom LLK binary operation with reuse
    _llk_math_eltwise_binary_bcast_reuse_custom_(CT_DIM);

    // Signal destination section completion
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& config = params->formats;
#endif

    // Configure pack hardware based on architecture
#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(config.pack_src, config.pack_dst, 16 * 16 * 4);
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(config.pack_src, config.pack_dst, 16 * 16 * 4);
#endif

    // Initialize pack operation
    _llk_pack_init_<false, false>(config.pack_dst);

    // Initialize destination for packing
#ifdef ARCH_BLACKHOLE
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_dest_init_<DstSync::SyncHalf, false, false>();
#endif

    // Wait for math operations to complete
    _llk_packer_wait_for_math_done_();

    // Pack all result tiles
    for (int tile_index = 0; tile_index < params->TILE_CNT; tile_index++)
    {
        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(tile_index, L1_ADDRESS(params->buffer_Res[tile_index]));
    }

    // Signal pack destination section completion
    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

