enum {
    MSG_PERFORM_TASK = 'ptsk',
    MSG_TASK_COMPLETE = 'tcmpl',
    MSG_INITIATE = 'init'
};

// ----- Task Handler -----
class TaskHandler : public BHandler {
public:
    TaskHandler(const char* label) : BHandler(label) {}
    virtual void MessageReceived(BMessage* msg) override {
        switch (msg->what) {
            case MSG_PERFORM_TASK: {
                int32 taskId;
                BMessenger responder;
                if (msg->FindInt32("taskId", &taskId) == B_OK &&
                    msg->FindMessenger("replyTo", &responder) == B_OK) {
                    BMessage progress(MSG_TASK_COMPLETE);
                    progress.AddInt32("taskId", taskId);
                    progress.AddInt32("progress", 1); // In progress
                    responder.SendMessage(&progress);
                    snooze(3000000); // 3 seconds delay
                    progress.ReplaceInt32("progress", 2); // Completed
                    responder.SendMessage(&progress);
                }
                break;
            }
            default:
                BHandler::MessageReceived(msg);
        }
    }
};

// ----- Background Looper -----
class BackgroundLooper : public BLooper {
public:
    BackgroundLooper() : BLooper("BackgroundLooper") {
        fTaskHandler = new TaskHandler("TaskHandler");
        AddHandler(fTaskHandler);
    }
    BHandler* GetHandler() { return fTaskHandler; }
private:
    TaskHandler* fTaskHandler;
};

// ----- Main Application Window -----
class MainWindow : public BWindow {
public:
    MainWindow(BRect frame)
        : BWindow(frame, "BLooper & BHandler GUI Demo",
                  B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE)
    {
        BView* mainView = new BView(Bounds(), "mainView",
                                    B_FOLLOW_ALL, B_WILL_DRAW);
        mainView->SetViewColor(ui_color(B_PANEL_BACKGROUND_COLOR));
        AddChild(mainView);

        fDisplayView = new BStringView(BRect(10, 50, Bounds().Width()-10, Bounds().Height()-10),
                                       "displayView", "", B_FOLLOW_ALL_SIDES);
        mainView->AddChild(fDisplayView);

        fStartButton = new BButton(BRect(10, 10, 150, 35), "startBtn", "Start",
                                   new BMessage(MSG_INITIATE));
        mainView->AddChild(fStartButton);

        fBackgroundLooper = new BackgroundLooper();
        fBackgroundLooper->Run();

        fTotalTasks = 3;
        fFinishedTasks = 0;
    }

    virtual void MessageReceived(BMessage* msg) override {
        switch (msg->what) {
            case MSG_INITIATE:
                ExecuteTasks();
                break;
            case MSG_TASK_COMPLETE: {
                int32 taskId, progress;
                if (msg->FindInt32("taskId", &taskId) == B_OK &&
                    msg->FindInt32("progress", &progress) == B_OK) {
                    BString entry;
                    if (progress == 1)
                        entry << "[Worker] Task " << taskId << " is in progress...";
                    else {
                        entry << "[Worker] Task " << taskId << " completed.";
                        fFinishedTasks++;
                    }
                    UpdateLog(entry);
                    if (fFinishedTasks == fTotalTasks)
                        UpdateLog("[Main] All tasks finished!");
                }
                break;
            }
            default:
                BWindow::MessageReceived(msg);
        }
    }

private:
    void ExecuteTasks() {
        fFinishedTasks = 0;
        UpdateLog("[Main] -----------------");
        UpdateLog("[Main] Initiating tasks...");
        for (int index = 1; index <= fTotalTasks; index++) {
            BMessage task(MSG_PERFORM_TASK);
            task.AddInt32("taskId", index);
            task.AddMessenger("replyTo", BMessenger(this));
            BMessenger(fBackgroundLooper->GetHandler()).SendMessage(&task);
            BString info;
            info << "[Main] Sent task " << index << " to background...";
            UpdateLog(info);
        }
    }

    void UpdateLog(const BString& line) {
        fLogBuffer << line << "\n";
        fDisplayView->SetText(fLogBuffer.String());
    }

private:
    BackgroundLooper* fBackgroundLooper;
    BStringView* fDisplayView;
    BButton* fStartButton;
    BString fLogBuffer;
    int fTotalTasks;
    int fFinishedTasks;
};

// ----- Application Entry Point -----
class Application : public BApplication {
public:
    Application() : BApplication("application/x-vnd.Haiku.BackgroundLooper") {}
    virtual void ReadyToRun() override {
        BWindow* window = new MainWindow(BRect(100, 100, 500, 300));
        window->Show();
    }
};

int main() {
    Application app;
    app.Run();
    return 0;
}

