using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int blackCount, whiteCount, costBlack, costWhite;
    if (!(cin >> blackCount >> whiteCount >> costBlack >> costWhite)) return 0;

    const int ROWS_TOP = 60;
    const int COLS = 80;
    int totalRows = 2 * ROWS_TOP + 1;
    int totalCols = COLS;

    vector<string> canvas(totalRows, string(totalCols, '.'));

    // Choose separator based on which color is cheaper
    char divider = (costBlack <= costWhite) ? '@' : '.';

    // Fill top section with white cells
    for (int row = 0; row < ROWS_TOP; ++row) {
        for (int col = 0; col < totalCols; ++col) {
            canvas[row][col] = '.';
        }
    }

    // Set separator row
    for (int col = 0; col < totalCols; ++col) {
        canvas[ROWS_TOP][col] = divider;
    }

    // Fill bottom section with black cells
    for (int row = ROWS_TOP + 1; row < totalRows; ++row) {
        for (int col = 0; col < totalCols; ++col) {
            canvas[row][col] = '@';
        }
    }

    // Add black islands in the white region (need blackCount - 1 additional black cells)
    int remainingBlack = blackCount - 1;
    for (int row = 0; row < ROWS_TOP && remainingBlack > 0; ++row) {
        if (divider == '@' && row == ROWS_TOP - 1) continue;
        if (row % 2 == 1) {
            for (int col = 1; col < totalCols && remainingBlack > 0; col += 2) {
                canvas[row][col] = '@';
                --remainingBlack;
            }
        }
    }

    // Add white islands in the black region (need whiteCount - 1 additional white cells)
    int remainingWhite = whiteCount - 1;
    for (int row = ROWS_TOP + 1; row < totalRows && remainingWhite > 0; ++row) {
        if (divider == '.' && row == ROWS_TOP + 1) continue;
        if (row % 2 == 1) {
            for (int col = 1; col < totalCols && remainingWhite > 0; col += 2) {
                canvas[row][col] = '.';
                --remainingWhite;
            }
        }
    }

    cout << totalRows << " " << totalCols << "\n";
    for (int row = 0; row < totalRows; ++row) {
        cout << canvas[row] << "\n";
    }

    return 0;
}

