namespace {
namespace legacy {

class PassTimingInfo {
public:
  using PassInstanceID = void *;

private:
  StringMap<unsigned> PassInstanceCountMap;
  DenseMap<PassInstanceID, std::unique_ptr<Timer>> TimerStorage;
  TimerGroup TimerGroupObj;

public:
  PassTimingInfo();
  ~PassTimingInfo();
  static void initialize();
  void print(raw_ostream *OutStream = nullptr);
  Timer *acquireTimer(Pass *, PassInstanceID);

  static PassTimingInfo *GlobalTimingInfo;

private:
  Timer *createNewTimer(StringRef PassName, StringRef PassDescription);
};

static ManagedStatic<sys::SmartMutex<true>> TimingInfoLock;

PassTimingInfo::PassTimingInfo()
    : TimerGroupObj("pass", "Pass execution timing report") {}

PassTimingInfo::~PassTimingInfo() {
  TimerStorage.clear();
}

void PassTimingInfo::initialize() {
  if (!TimePassesIsEnabled || GlobalTimingInfo)
    return;

  static ManagedStatic<PassTimingInfo> TTI;
  GlobalTimingInfo = &*TTI;
}

void PassTimingInfo::print(raw_ostream *OutStream) {
  TimerGroupObj.print(OutStream ? *OutStream : *CreateInfoOutputFile(), true);
}

Timer *PassTimingInfo::createNewTimer(StringRef PassName, StringRef PassDesc) {
  unsigned &count = PassInstanceCountMap[PassName];
  count++;

  std::string NumberedDesc =
      count <= 1 ? PassDesc.str()
                 : formatv("{0} #{1}", PassDesc, count).str();

  return new Timer(PassName, NumberedDesc, TimerGroupObj);
}

Timer *PassTimingInfo::acquireTimer(Pass *P, PassInstanceID ID) {
  if (P->getAsPMDataManager())
    return nullptr;

  initialize();
  sys::SmartScopedLock<true> Guard(*TimingInfoLock);

  std::unique_ptr<Timer> &T = TimerStorage[ID];
  if (!T) {
    StringRef Name = P->getPassName();
    StringRef Arg;
    if (const PassInfo *PI = Pass::lookupPassInfo(P->getPassID()))
      Arg = PI->getPassArgument();

    T.reset(createNewTimer(Arg.empty() ? Name : Arg, Name));
  }

  return T.get();
}

PassTimingInfo *PassTimingInfo::GlobalTimingInfo;

} // namespace legacy
} // namespace

Timer *getPassTimer(Pass *P) {
  legacy::PassTimingInfo::initialize();
  if (legacy::PassTimingInfo::GlobalTimingInfo)
    return legacy::PassTimingInfo::GlobalTimingInfo->acquireTimer(P, P);
  return nullptr;
}

void reportAndResetTimings(raw_ostream *OutStream) {
  if (legacy::PassTimingInfo::GlobalTimingInfo)
    legacy::PassTimingInfo::GlobalTimingInfo->print(OutStream);
}

