Timer &TimePassesHandler::getPassTimer(StringRef PassID, bool IsPass) {
  TimerGroup &TG = IsPass ? PassTimerGroup : AnalysisTimerGroup;

  if (!PerRun) {
    TimerVector &Timers = TimerMap[PassID];
    if (Timers.empty())
      Timers.emplace_back(new Timer(PassID, PassID, TG));
    return *Timers.front();
  }

  TimerVector &Timers = TimerMap[PassID];
  unsigned Count = Timers.size() + 1;
  std::string FullDesc = formatv("{0} #{1}", PassID, Count).str();
  Timer *T = new Timer(PassID, FullDesc, TG);
  Timers.emplace_back(T);
  assert(Count == Timers.size() && "Timer vector not updated correctly.");
  return *T;
}

TimePassesHandler::TimePassesHandler(bool Enabled, bool PerRun)
    : PassTimerGroup("pass", "Pass execution timing report"),
      AnalysisTimerGroup("analysis", "Analysis execution timing report"),
      Enabled(Enabled), PerRun(PerRun) {}

TimePassesHandler::TimePassesHandler()
    : TimePassesHandler(TimePassesIsEnabled, TimePassesPerRun) {}

void TimePassesHandler::setOutputStream(raw_ostream &Out) {
  OutputStream = &Out;
}

void TimePassesHandler::print() {
  if (!Enabled)
    return;

  std::unique_ptr<raw_ostream> CreatedStream;
  raw_ostream *OS = OutputStream;
  if (!OutputStream) {
    CreatedStream = CreateInfoOutputFile();
    OS = &*CreatedStream;
  }

  PassTimerGroup.print(*OS, true);
  AnalysisTimerGroup.print(*OS, true);
}

LLVM_DUMP_METHOD void TimePassesHandler::dump() const {
  dbgs() << "Dumping timers for " << getTypeName<TimePassesHandler>()
         << ":\n\tRunning:\n";
  for (auto &Entry : TimerMap) {
    StringRef PassID = Entry.getKey();
    const TimerVector& TimerList = Entry.getValue();
    for (unsigned idx = 0; idx < TimerList.size(); idx++) {
      const Timer* T = TimerList[idx].get();
      if (T && T->isRunning())
        dbgs() << "\tTimer " << T << " for pass " << PassID << "(" << idx << ")\n";
    }
  }

  dbgs() << "\tCompleted:\n";
  for (auto &Entry : TimerMap) {
    StringRef PassID = Entry.getKey();
    const TimerVector& TimerList = Entry.getValue();
    for (unsigned idx = 0; idx < TimerList.size(); idx++) {
      const Timer* T = TimerList[idx].get();
      if (T && T->hasTriggered() && !T->isRunning())
        dbgs() << "\tTimer " << T << " for pass " << PassID << "(" << idx << ")\n";
    }
  }
}

static bool skipPass(StringRef PassID) {
  return isSpecialPass(PassID,
                       {"PassManager", "PassAdaptor", "AnalysisManagerProxy",
                        "ModuleInlinerWrapperPass", "DevirtSCCRepeatedPass"});
}

void TimePassesHandler::startPassTimer(StringRef PassID) {
  if (skipPass(PassID))
    return;

  if (!ActivePassTimerStack.empty()) {
    assert(ActivePassTimerStack.back()->isRunning());
    ActivePassTimerStack.back()->stopTimer();
  }

  Timer &MyTimer = getPassTimer(PassID, /*IsPass=*/true);
  ActivePassTimerStack.push_back(&MyTimer);
  assert(!MyTimer.isRunning());
  MyTimer.startTimer();
}

void TimePassesHandler::stopPassTimer(StringRef PassID) {
  if (skipPass(PassID))
    return;

  assert(!ActivePassTimerStack.empty() && "Timer stack underflow");
  Timer *MyTimer = ActivePassTimerStack.pop_back_val();
  assert(MyTimer && "Missing timer");
  assert(MyTimer->isRunning());
  MyTimer->stopTimer();

  if (!ActivePassTimerStack.empty()) {
    assert(!ActivePassTimerStack.back()->isRunning());
    ActivePassTimerStack.back()->startTimer();
  }
}

void TimePassesHandler::startAnalysisTimer(StringRef PassID) {
  if (!ActiveAnalysisTimerStack.empty()) {
    assert(ActiveAnalysisTimerStack.back()->isRunning());
    ActiveAnalysisTimerStack.back()->stopTimer();
  }

  Timer &MyTimer = getPassTimer(PassID, /*IsPass=*/false);
  ActiveAnalysisTimerStack.push_back(&MyTimer);
  if (!MyTimer.isRunning())
    MyTimer.startTimer();
}

void TimePassesHandler::stopAnalysisTimer(StringRef PassID) {
  assert(!ActiveAnalysisTimerStack.empty() && "Empty analysis timer stack");
  Timer *MyTimer = ActiveAnalysisTimerStack.pop_back_val();
  assert(MyTimer && "Missing analysis timer");
  if (MyTimer->isRunning())
    MyTimer->stopTimer();

  if (!ActiveAnalysisTimerStack.empty()) {
    assert(!ActiveAnalysisTimerStack.back()->isRunning());
    ActiveAnalysisTimerStack.back()->startTimer();
  }
}

void TimePassesHandler::registerCallbacks(PassInstrumentationCallbacks &PIC) {
  if (!Enabled)
    return;

  PIC.registerBeforeNonSkippedPassCallback(
      [this](StringRef P, Any) { this->startPassTimer(P); });
  PIC.registerAfterPassCallback(
      [this](StringRef P, Any, const PreservedAnalyses &) {
        this->stopPassTimer(P);
      });
  PIC.registerAfterPassInvalidatedCallback(
      [this](StringRef P, const PreservedAnalyses &) {
        this->stopPassTimer(P);
      });
  PIC.registerBeforeAnalysisCallback(
      [this](StringRef P, Any) { this->startAnalysisTimer(P); });
  PIC.registerAfterAnalysisCallback(
      [this](StringRef P, Any) { this->stopAnalysisTimer(P); });
}

