//===----------------------------------------------------------------------===//
//                     AArch64ConstPromoter
//===----------------------------------------------------------------------===//
namespace {

/// Transforms selected constants into module-scoped global variables.
/// Example scenario:
/// static const uint16_t DataTab[32] = { ... };
///
/// Before transformation:
///   ret.val[0] = vld1q_u16(DataTab +  0);
///   ret.val[1] = vld1q_u16(DataTab +  8);
///   ...
/// After transformation:
///   One global load replaces multiple repeated loads.
class AArch64ConstPromoter : public ModulePass {
public:
  struct GlobalEntry {
    bool NeedConversion = false;
    GlobalVariable *GVPtr = nullptr;
  };

  using CacheTy = SmallDenseMap<Constant *, GlobalEntry, 16>;

  struct UpdateInfo {
    Constant *Cnst;
    Instruction *UserInstr;
    unsigned OperandIndex;
    UpdateInfo(Constant *C, Instruction *U, unsigned O)
        : Cnst(C), UserInstr(U), OperandIndex(O) {}
  };

  static char ID;
  AArch64ConstPromoter() : ModulePass(ID) {
    initializeAArch64ConstPromoterPass(*PassRegistry::getPassRegistry());
  }

  StringRef getPassName() const override { return "AArch64 Constant Promoter"; }

  bool runOnModule(Module &Mod) override {
    LLVM_DEBUG(dbgs() << getPassName() << "\n");
    if (skipModule(Mod))
      return false;

    bool Modified = false;
    CacheTy Cache;
    for (auto &Func : Mod) {
      Modified |= runOnFunction(Func, Cache);
    }
    return Modified;
  }

private:
  bool runOnFunction(Function &F, CacheTy &Cache);
  void getAnalysisUsage(AnalysisUsage &AU) const override {
    AU.setPreservesCFG();
    AU.addRequired<DominatorTreeWrapperPass>();
    AU.addPreserved<DominatorTreeWrapperPass>();
  }

  using UseList = SmallVector<std::pair<Instruction *, unsigned>, 4>;
  using InsertionMap = DenseMap<Instruction *, UseList>;

  Instruction *findBestInsertionPoint(Instruction &User, unsigned OpIdx);
  bool isDominatedByExisting(Instruction *NewPt, Instruction *User,
                             unsigned OpIdx, InsertionMap &Points);
  bool tryMergeWithExisting(Instruction *NewPt, Instruction *User,
                            unsigned OpIdx, InsertionMap &Points);

  void computeInsertionPoints(Instruction *User, unsigned OpIdx,
                              InsertionMap &Points);
  void emitDefinitions(Function &F, GlobalVariable &GV, InsertionMap &Points);
  void applyPromotions(Function &F, SmallVectorImpl<UpdateInfo> &Updates,
                       CacheTy &Cache);

  static void moveAndAttachDominatedUses(Instruction *NewPt, Instruction *User,
                                         unsigned OpIdx,
                                         InsertionMap::iterator &It,
                                         InsertionMap &Points) {
    It->second.emplace_back(User, OpIdx);
    Instruction *OldInstr = It->first;
    UseList OldList = std::move(It->second);
    Points[NewPt] = std::move(OldList);
    Points.erase(OldInstr);
  }
};

} // end anonymous namespace

