INITIALIZE_PASS_END(AArch64ConstPromoter, "aarch64-const-promote",
                    "AArch64 Constant Promotion Pass", false, false)

ModulePass *llvm::createAArch64ConstPromoterPass() {
  return new AArch64ConstPromoter();
}

static bool hasVectorComponent(const Type *T) {
  if (T->isVectorTy())
    return true;
  if (T->isStructTy()) {
    for (unsigned Idx = 0, End = T->getStructNumElements(); Idx < End; ++Idx) {
      if (hasVectorComponent(T->getStructElementType(Idx)))
        return true;
    }
  } else if (T->isArrayTy()) {
    return hasVectorComponent(T->getArrayElementType());
  }
  return false;
}

static bool containsOnlyLeafData(const Constant *C) {
  if (isa<ConstantData>(C))
    return true;
  if (isa<GlobalValue>(C) || isa<BlockAddress>(C) || isa<ConstantExpr>(C))
    return false;
  return all_of(C->operands(), [](const Use &U) {
    return containsOnlyLeafData(cast<Constant>(&U));
  });
}

static bool isValidUse(const Constant *Cst, const Instruction *Instr,
                       unsigned OpIdx) {
  if (isa<const ShuffleVectorInst>(Instr) && OpIdx == 2)
    return false;
  if ((isa<const ExtractValueInst>(Instr) || isa<const InsertValueInst>(Instr)) &&
      OpIdx > 1)
    return false;
  if (isa<const AllocaInst>(Instr) && OpIdx > 0)
    return false;
  if ((isa<const LoadInst>(Instr) || isa<const StoreInst>(Instr)) && OpIdx > 0)
    return false;
  if (isa<const GetElementPtrInst>(Instr) && OpIdx > 0)
    return false;
  if (isa<const LandingPadInst>(Instr) || isa<const SwitchInst>(Instr) ||
      isa<const IndirectBrInst>(Instr))
    return false;
  if (isa<const IntrinsicInst>(Instr))
    return false;
  const CallInst *CI = dyn_cast<const CallInst>(Instr);
  return !(CI && CI->isInlineAsm());
}

static bool shouldPromoteImpl(const Constant *Cst) {
  if (isa<const UndefValue>(Cst))
    return false;
  if (Cst->isZeroValue())
    return false;
  if (StressMode)
    return true;
  if (Cst->getType()->isVectorTy())
    return false;
  return hasVectorComponent(Cst->getType());
}

static bool
shouldPromote(Constant &C, AArch64ConstPromoter::CacheTy &Cache) {
  auto Result = Cache.insert(
      std::make_pair(&C, AArch64ConstPromoter::GlobalEntry()));
  if (Result.second)
    Result.first->second.NeedConversion = shouldPromoteImpl(&C);
  return Result.first->second.NeedConversion;
}

Instruction *AArch64ConstPromoter::findBestInsertionPoint(Instruction &User,
                                                          unsigned OpIdx) {
  if (PHINode *Phi = dyn_cast<PHINode>(&User))
    return Phi->getIncomingBlock(OpIdx)->getTerminator();
  return &User;
}

bool AArch64ConstPromoter::isDominatedByExisting(Instruction *NewPt,
                                                 Instruction *User,
                                                 unsigned OpIdx,
                                                 InsertionMap &Points) {
  DominatorTree &DT = getAnalysis<DominatorTreeWrapperPass>(
      *NewPt->getParent()->getParent()).getDomTree();

  for (auto &Entry : Points) {
    if (NewPt == Entry.first || DT.dominates(Entry.first, NewPt) ||
        (Entry.first->getParent() != NewPt->getParent() &&
         DT.dominates(Entry.first->getParent(), NewPt->getParent()))) {
      Entry.second.emplace_back(User, OpIdx);
      LLVM_DEBUG(dbgs() << "Insertion point dominated by:\n");
      LLVM_DEBUG(Entry.first->print(dbgs()));
      LLVM_DEBUG(dbgs() << '\n');
      return true;
    }
  }
  return false;
}

bool AArch64ConstPromoter::tryMergeWithExisting(Instruction *NewPt,
                                                Instruction *User,
                                                unsigned OpIdx,
                                                InsertionMap &Points) {
  DominatorTree &DT = getAnalysis<DominatorTreeWrapperPass>(
      *NewPt->getParent()->getParent()).getDomTree();
  BasicBlock *BB1 = NewPt->getParent();

  for (InsertionMap::iterator It = Points.begin(), End = Points.end();
       It != End; ++It) {
    BasicBlock *BB2 = It->first->getParent();
    if (BB1 == BB2) {
      LLVM_DEBUG(dbgs() << "Merge insertion point with:\n");
      LLVM_DEBUG(It->first->print(dbgs()));
      LLVM_DEBUG(dbgs() << "\nat considered insertion point.\n");
      moveAndAttachDominatedUses(NewPt, User, OpIdx, It, Points);
      return true;
    }

    BasicBlock *Common = DT.findNearestCommonDominator(BB1, BB2);
    if (!Common)
      continue;

    if (Common != BB1) {
      assert(Common != BB2 && "Should have been caught earlier!");
      NewPt = Common->getTerminator();
    }

    LLVM_DEBUG(dbgs() << "Merge insertion point with:\n");
    LLVM_DEBUG(It->first->print(dbgs()));
    LLVM_DEBUG(dbgs() << '\n');
    LLVM_DEBUG(NewPt->print(dbgs()));
    LLVM_DEBUG(dbgs() << '\n');
    moveAndAttachDominatedUses(NewPt, User, OpIdx, It, Points);
    return true;
  }
  return false;
}

void AArch64ConstPromoter::computeInsertionPoints(Instruction *User,
                                                  unsigned OpIdx,
                                                  InsertionMap &Points) {
  LLVM_DEBUG(dbgs() << "Considered use, opidx " << OpIdx << ":\n");
  LLVM_DEBUG(User->print(dbgs()));
  LLVM_DEBUG(dbgs() << '\n');

  Instruction *Pt = findBestInsertionPoint(*User, OpIdx);
  LLVM_DEBUG(dbgs() << "Considered insertion point:\n");
  LLVM_DEBUG(Pt->print(dbgs()));
  LLVM_DEBUG(dbgs() << '\n');

  if (isDominatedByExisting(Pt, User, OpIdx, Points))
    return;

  if (tryMergeWithExisting(Pt, User, OpIdx, Points))
    return;

  LLVM_DEBUG(dbgs() << "Keep considered insertion point\n");
  Points[Pt].emplace_back(User, OpIdx);
}

static void ensureGlobalVariable(Function &F, Constant &C,
                                 AArch64ConstPromoter::GlobalEntry &GE) {
  assert(GE.NeedConversion && "Expected conversion requested");
  if (GE.GVPtr)
    return;

  GE.GVPtr = new GlobalVariable(
      *F.getParent(), C.getType(), true, GlobalValue::InternalLinkage, nullptr,
      "_PromotedConst", nullptr, GlobalVariable::NotThreadLocal);
  GE.GVPtr->setInitializer(&C);
  LLVM_DEBUG(dbgs() << "Global replacement: ");
  LLVM_DEBUG(GE.GVPtr->print(dbgs()));
  LLVM_DEBUG(dbgs() << '\n');
  ++NumGVCreated;
}

void AArch64ConstPromoter::emitDefinitions(Function &F, GlobalVariable &GV,
                                           InsertionMap &Points) {
#ifndef NDEBUG
  DominatorTree &DT = getAnalysis<DominatorTreeWrapperPass>(F).getDomTree();
#endif
  assert(!Points.empty() && "Empty uses does not need a definition");

  for (const auto &Entry : Points) {
    IRBuilder<> Builder(Entry.first);
    LoadInst *Loaded = Builder.CreateLoad(GV.getValueType(), &GV);
    LLVM_DEBUG(dbgs() << "**********\n");
    LLVM_DEBUG(dbgs() << "New def: ");
    LLVM_DEBUG(Loaded->print(dbgs()));
    LLVM_DEBUG(dbgs() << '\n');

    for (auto &Use : Entry.second) {
#ifndef NDEBUG
      assert(DT.dominates(Loaded,
                          findBestInsertionPoint(*Use.first, Use.second)) &&
             "Definition must dominate all uses!");
#endif
      LLVM_DEBUG({
        dbgs() << "Use to update " << Use.second << ":";
        Use.first->print(dbgs());
        dbgs() << '\n';
      });
      Use.first->setOperand(Use.second, Loaded);
      ++NumUsesReplaced;
    }
  }
}

void AArch64ConstPromoter::applyPromotions(
    Function &F, SmallVectorImpl<UpdateInfo> &Updates, CacheTy &Cache) {
  for (auto I = Updates.begin(), E = Updates.end(); I != E;) {
    LLVM_DEBUG(dbgs() << "** Compute insertion points **\n");
    Constant *C = I->Cnst;
    InsertionMap Points;
    do {
      computeInsertionPoints(I->UserInstr, I->OperandIndex, Points);
    } while (++I != E && I->Cnst == C);

    GlobalEntry &Entry = Cache[C];
    ensureGlobalVariable(F, *C, Entry);
    emitDefinitions(F, *Entry.GVPtr, Points);
  }
}

bool AArch64ConstPromoter::runOnFunction(Function &F, CacheTy &Cache) {
  SmallVector<UpdateInfo, 64> Updates;

  for (Instruction &I : instructions(&F)) {
    for (Use &U : I.operands()) {
      Constant *C = dyn_cast<Constant>(U);
      if (!C || isa<GlobalValue>(C) || !containsOnlyLeafData(C))
        continue;
      if (!shouldPromote(*C, Cache))
        continue;
      unsigned OpNo = &U - I.op_begin();
      if (!isValidUse(C, &I, OpNo))
        continue;
      Updates.emplace_back(C, &I, OpNo);
    }
  }

  if (Updates.empty())
    return false;

  applyPromotions(F, Updates, Cache);
  return true;
}

