#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Node structure for distance-based sorting
struct Vertex {
    int identifier;
    long long distance;
};

// Comparison function to order vertices by increasing distance from root
bool sortVertices(const Vertex& x, const Vertex& y) {
    return x.distance < y.distance;
}

int nodesCount;
vector<long long> distances;
vector<int> parentNode;
vector<vector<int>> childList;
vector<int> subtreeSize;
vector<Vertex> orderedVertices;

// Function to ask about distance between two nodes
long long getDistance(int a, int b) {
    cout << "? " << a << " " << b << endl;
    long long d;
    cin >> d;
    return d;
}

// Update subtree sizes along the path to root
void adjustSubtreeSizes(int v) {
    while (v != -1) {
        subtreeSize[v]++;
        v = parentNode[v];
    }
}

// Find ancestor of node at specific depth
int findAncestorAtLevel(int v, long long targetLevel) {
    int current = v;
    while (current != -1) {
        if (distances[current] == targetLevel) 
            return current;

        // Since edge weights >= 1, depth strictly decreases upward
        if (distances[current] < targetLevel) 
            break;

        current = parentNode[current];
    }
    return -1;
}

void process() {
    cin >> nodesCount;

    // Special case: single node tree
    if (nodesCount == 1) {
        cout << "! " << endl;
        return;
    }

    // Initialize distance array
    distances.assign(nodesCount + 1, 0);

    // Step 1: Query distances from root (node 1) to all other nodes
    for (int i = 2; i <= nodesCount; ++i) {
        distances[i] = getDistance(1, i);
    }

    // Prepare vertices for sorting by distance
    orderedVertices.resize(nodesCount);
    for (int i = 1; i <= nodesCount; ++i) {
        orderedVertices[i - 1] = {i, distances[i]};
    }

    // Step 2: Sort vertices by distance from root
    sort(orderedVertices.begin(), orderedVertices.end(), sortVertices);

    // Step 3: Build tree incrementally
    parentNode.assign(nodesCount + 1, -1);
    childList.assign(nodesCount + 1, vector<int>());
    subtreeSize.assign(nodesCount + 1, 1);

    // Process non-root nodes in order of increasing distance
    for (int idx = 1; idx < nodesCount; ++idx) {
        int vertex = orderedVertices[idx].identifier;
        long long distV = orderedVertices[idx].distance;
        int candidateParent = 1; // Start from root
        vector<int> possibleChildren = childList[candidateParent];

        while (true) {
            // If no more candidates, attach as child of current node
            if (possibleChildren.empty()) {
                parentNode[vertex] = candidateParent;
                childList[candidateParent].push_back(vertex);
                adjustSubtreeSizes(candidateParent);
                break;
            }

            // Select child with largest subtree (heavy child heuristic)
            int bestChild = -1;
            int maxSize = -1;
            int bestIndex = -1;
            for (size_t k = 0; k < possibleChildren.size(); ++k) {
                int c = possibleChildren[k];
                if (subtreeSize[c] > maxSize) {
                    maxSize = subtreeSize[c];
                    bestChild = c;
                    bestIndex = k;
                }
            }

            // Find deepest node in heavy child's subtree (leaf)
            int leafNode = bestChild;
            while (!childList[leafNode].empty()) {
                int nextBest = -1;
                int maxS = -1;
                for (int child : childList[leafNode]) {
                    if (subtreeSize[child] > maxS) {
                        maxS = subtreeSize[child];
                        nextBest = child;
                    }
                }
                leafNode = nextBest;
            }

            // Query distance to determine LCA
            long long distUV = getDistance(vertex, leafNode);
            long long lcaDist = (distV + distances[leafNode] - distUV) / 2;

            // Locate LCA node in existing tree
            int lcaNode = findAncestorAtLevel(leafNode, lcaDist);

            if (lcaNode == candidateParent) {
                // LCA is current node, so vertex not in bestChild's subtree
                possibleChildren[bestIndex] = possibleChildren.back();
                possibleChildren.pop_back();
            } else {
                // LCA is deeper, find which child leads toward leafNode
                int childOnPath = leafNode;
                if (childOnPath != lcaNode) {
                    while (parentNode[childOnPath] != lcaNode) {
                        childOnPath = parentNode[childOnPath];
                    }
                } else {
                    // If LCA is leafNode itself, attach vertex as its child
                    parentNode[vertex] = leafNode;
                    childList[leafNode].push_back(vertex);
                    adjustSubtreeSizes(leafNode);
                    break;
                }

                // Move search to LCA
                candidateParent = lcaNode;
                possibleChildren = childList[candidateParent];

                // Remove child that leads toward leafNode
                for (size_t k = 0; k < possibleChildren.size(); ++k) {
                    if (possibleChildren[k] == childOnPath) {
                        possibleChildren[k] = possibleChildren.back();
                        possibleChildren.pop_back();
                        break;
                    }
                }
            }
        }
    }

    // Output final tree
    cout << "!";
    for (int i = 2; i <= nodesCount; ++i) {
        long long weight = distances[i] - distances[parentNode[i]];
        cout << " " << parentNode[i] << " " << i << " " << weight;
    }
    cout << endl;
}

int main() {
    // Faster I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            process();
        }
    }
    return 0;
}

