void HamScrollSpeedIndicator::PostLoad(BinStream &stream) {
    BinStreamRev d(stream, stream.PopRev(this));
    RndDir::PostLoad(stream);

    if ((d.rev & 0xffff) >= 1) {
        stream >> mFadeInAnim;
        stream >> mFadeOutAnim;
        stream >> mDisplayAnim;
    }

    if (2 <= (d.rev & 0xffff)) {
        stream >> mMinScrollDelayFrame;
        stream >> mMaxScrollDelayFrame;
    }
}

