#define print_no  cout << "NO"  << endl_line

inline ll compute_gcd(ll x, ll y) { return std::gcd(x, y); }
inline ll compute_lcm(ll x, ll y) { return (x / std::gcd(x, y)) * y; }

inline ll fast_pow(ll base, ll exponent, ll modulus = MOD) {
    ll result = 1;
    base %= modulus;
    while (exponent > 0) {
        if (exponent & 1) result = (result * base) % modulus;
        base = (base * base) % modulus;
        exponent >>= 1;
    }
    return result;
}

void process_test_case() {
    ll total_items, required_parts;
    cin >> total_items >> required_parts;

    arr<ll> factors;

    // Step 1: Extract small prime factors until we have k-1 parts
    for (ll candidate = 2; candidate * candidate <= total_items && length(factors) < required_parts - 1; ++candidate) {
        while (total_items % candidate == 0 && length(factors) < required_parts - 1) {
            factors.add(candidate);
            total_items /= candidate;
        }
    }

    // Step 2: Validation checks
    if (length(factors) < required_parts - 1 || total_items == 1) {
        cout << -1 << endl_line;
        return;
    }

    // Step 3: Append the remaining value as the last factor
    factors.add(total_items);

    // Output the result
    foreach(factor, factors) cout << factor << " ";
    cout << endl_line;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(15);

    process_test_case();

    return 0;
}

