#include "Widgets/Text/STextBlock.h"
#include "ToolMenus.h"

static const FName PLUGIN_NAMETabIdentifier("PLUGIN_NAME");

#define LOCTEXT_NAMESPACE "FPLUGIN_NAMEModule"

void FPLUGIN_NAMEModule::StartupModule()
{
    // Initialize styling and commands for the plugin
    FPLUGIN_NAMEStyle::Initialize();
    FPLUGIN_NAMEStyle::ReloadTextures();
    FPLUGIN_NAMECommands::Register();

    PluginCommandList = MakeShareable(new FUICommandList);
    PluginCommandList->MapAction(
        FPLUGIN_NAMECommands::Get().OpenPluginWindow,
        FExecuteAction::CreateRaw(this, &FPLUGIN_NAMEModule::OnPluginButtonClicked),
        FCanExecuteAction());

    UToolMenus::RegisterStartupCallback(FSimpleMulticastDelegate::FDelegate::CreateRaw(this, &FPLUGIN_NAMEModule::SetupMenuExtensions));

    FGlobalTabmanager::Get()->RegisterNomadTabSpawner(PLUGIN_NAMETabIdentifier, FOnSpawnTab::CreateRaw(this, &FPLUGIN_NAMEModule::CreatePluginTab))
        .SetDisplayName(LOCTEXT("FPLUGIN_NAMETabTitle", "PLUGIN_NAME"))
        .SetMenuType(ETabSpawnerMenuType::Hidden);
}

void FPLUGIN_NAMEModule::ShutdownModule()
{
    // Clean up resources when module is unloaded
    UToolMenus::UnRegisterStartupCallback(this);
    UToolMenus::UnregisterOwner(this);

    FPLUGIN_NAMEStyle::Shutdown();
    FPLUGIN_NAMECommands::Unregister();
    FGlobalTabmanager::Get()->UnregisterNomadTabSpawner(PLUGIN_NAMETabIdentifier);
}

TSharedRef<SDockTab> FPLUGIN_NAMEModule::CreatePluginTab(const FSpawnTabArgs& SpawnArgs)
{
    FText DisplayMessage = FText::Format(
        LOCTEXT("WindowContentTemplate", "Implement logic in {0} within {1} to customize this tab's content"),
        FText::FromString(TEXT("FPLUGIN_NAMEModule::CreatePluginTab")),
        FText::FromString(TEXT("PLUGIN_NAME.cpp"))
    );

    return SNew(SDockTab)
        .TabRole(ETabRole::NomadTab)
        [
            SNew(SBox)
            .HAlign(HAlign_Center)
            .VAlign(VAlign_Center)
            [
                SNew(STextBlock)
                .Text(DisplayMessage)
            ]
        ];
}

void FPLUGIN_NAMEModule::OnPluginButtonClicked()
{
    FGlobalTabmanager::Get()->TryInvokeTab(PLUGIN_NAMETabIdentifier);
}

void FPLUGIN_NAMEModule::SetupMenuExtensions()
{
    FToolMenuOwnerScoped ScopeOwner(this);

    {
        UToolMenu* MainMenuBar = UToolMenus::Get()->ExtendMenu("LevelEditor.MainMenu.Window");
        if (MainMenuBar)
        {
            FToolMenuSection& LayoutSection = MainMenuBar->FindOrAddSection("WindowLayout");
            LayoutSection.AddMenuEntryWithCommandList(FPLUGIN_NAMECommands::Get().OpenPluginWindow, PluginCommandList);
        }
    }

    {
        UToolMenu* ToolBarMenu = UToolMenus::Get()->ExtendMenu("LevelEditor.LevelEditorToolBar");
        if (ToolBarMenu)
        {
            FToolMenuSection& SettingsSection = ToolBarMenu->FindOrAddSection("Settings");
            FToolMenuEntry& ToolbarButton = SettingsSection.AddEntry(FToolMenuEntry::InitToolBarButton(FPLUGIN_NAMECommands::Get().OpenPluginWindow));
            ToolbarButton.SetCommandList(PluginCommandList);
        }
    }
}

#undef LOCTEXT_NAMESPACE

IMPLEMENT_MODULE(FPLUGIN_NAMEModule, PLUGIN_NAME)

#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <qdk/chemistry/scf/config.h>
#include <filesystem>

namespace py = pybind11;
namespace qcs = qdk::chemistry::scf;

void bind_qdk_chemistry_configuration(py::module& m) {
  // Bind QDKChemistryConfig as a class
  py::class_<qcs::QDKChemistryConfig>(m, "QDKChemistryConfig", R"(
QDKChemistry Configuration class.
This class provides access to QDKChemistry configuration functionality, including resource directory management and other configuration options.
Examples:
    >>> import qdk_chemistry._core as core
    >>> config = core.QDKChemistryConfig()
    >>>
    >>> # Get current resources directory
    >>> current_dir = config.get_resources_dir()
    >>> print(f"Current resources directory: {current_dir}")
    >>>
    >>> # Set custom resources directory
    >>> config.set_resources_dir("/path/to/custom/resources")
    >>>
    >>> # Verify the change
    >>> new_dir = config.get_resources_dir()
    >>> print(f"New resources directory: {new_dir}")
    >>>
    >>> # Or use static methods directly
    >>> core.QDKChemistryConfig.get_resources_dir()
    >>> core.QDKChemistryConfig.set_resources_dir("/another/path")
)")
      .def_static(
          "get_resources_dir",
          []() {
            return qcs::QDKChemistryConfig::get_resources_dir().string();
          },
          R"(
Get the current resources directory path.
Returns:
    str: The current resources directory path as a string.
Examples:
    >>> import qdk_chemistry._core as core
    >>> resources_path = core.QDKChemistryConfig.get_resources_dir()
    >>> print(f"Resources directory: {resources_path}")
)")
      .def_static(
          "set_resources_dir",
          [](const std::string& dir_path) {
            qcs::QDKChemistryConfig::set_resources_dir(
                std::filesystem::path(dir_path));
          },
          py::arg("dir_path"),
          R"(
Set the resources directory path.
Args:
    dir_path (str): The new resources directory path.
Examples:
    >>> import qdk_chemistry._core as core
    >>> core.QDKChemistryConfig.set_resources_dir("/path/to/custom/resources")
    >>> # Verify the change
    >>> print(core.QDKChemistryConfig.get_resources_dir())
)");
}

