/**
 * Tests main functionality of the KeyStore
 * It could run against KeyStoreFile or KeyStoreNet.
 * To run against KeyStoreNet command line like next needs to be specified:
 *      engtest.exe
 * "--url.keystorenet=kvsnet://localhost:9745/?secure=true&tlsCaFile=D%3A%5Cdevelopment%5CRocketRide%5CGIT%5Crocketride-app.applat-7888.keyvaluestorage.2.12%5Cbuild%5Crocketride%5Cdebug%5Capp%5Cserver%5Ccertificates%5Clocal-ca.pem&tlsKeyFile=D%3A%5Cdevelopment%5CRocketRide%5CGIT%5Crocketride-app.applat-7888.keyvaluestorage.2.12%5Cbuild%5Crocketride%5Cdebug%5Capp%5Cserver%5Ccertificates%5Clocalhost-key.pem&tlsCertFile=D%3A%5Cdevelopment%5CRocketRide%5CGIT%5Crocketride-app.applat-7888.keyvaluestorage.2.12%5Cbuild%5Crocketride%5Cdebug%5Capp%5Cserver%5Ccertificates%5Clocalhost-cert.pem"
 * --testArgs=keystore/net,keystoreservice/net --diag To run is successfully,
 * the APP needs to be running, and `--url.keystorenet` parameter points to the
 * correct URL from the running APP To obtain the correct URL - APP could be run
 * with `--engine.keepInput` option, and the URL should be taken from the
 * resulting .json file
 * @param KeystoreClass class name to test against
 * @param keystoreName key store name
 */
template <class KeystoreClass>
void executeKeyStoreTests(TextView storeName) {
    auto logScope = enableTestLogging(Lvl::KeyStore, Lvl::Connection, Lvl::Tls);
    KeystoreClass store;
    //-------------------------------
    // KeyStoreNet not-opened Section
    //-------------------------------
    SECTION("not-opened") {
        REQUIRE_ERROR(store.getValue("partition1", "key1"), Ec::NotOpen);
        REQUIRE_ERROR(store.setValue("partition1", "key1", "value11"),
                      Ec::NotOpen);
        REQUIRE_ERROR(store.deleteKey("partition1", "key1"), Ec::NotOpen);
        REQUIRE_ERROR(store.deleteAll("partition1"), Ec::NotOpen);
        REQUIRE_ERROR(store.getAll("partition1"), Ec::NotOpen);
        REQUIRE_ERROR(store.copyAll("partition1", "partition2"),
                      Ec::NotOpen);
        REQUIRE_ERROR(store.moveAll("partition1", "partition2", true, false),
                      Ec::NotOpen);
    }
    REQUIRE_NO_ERROR(store.open(storeName));
    //-------------------------------
    // KeyStoreNet open Section
    //-------------------------------
    SECTION("open") {
        REQUIRE_ERROR(store.open(storeName), Ec::AlreadyOpened);
    }
    //-------------------------------
    // KeyStoreNet setValue Section
    //-------------------------------
    SECTION("setValue") {
        REQUIRE_NO_ERROR(store.setValue("partition1", "key1", "value11"));
        REQUIRE_NO_ERROR(store.setValue("partition1", "key2", "value12"));
        REQUIRE_NO_ERROR(store.setValue("partition2", "key1", "value21"));
        REQUIRE_NO_ERROR(store.setValue("partition2", "key2", "value22"));
        // default partition
        REQUIRE_NO_ERROR(store.setValue("defaultkey1", "defaultvalue1"));
        REQUIRE_NO_ERROR(store.setValue(KeyStore::PARTITION_DEFAULT,
                                           "defaultkey2", "defaultvalue2"));
    }
    //-------------------------------
    // KeyStoreNet getValue Section
    //-------------------------------
    SECTION("getValue") {
        REQUIRE_VALUE(store.getValue("partition1", "key1"), "value11");
        REQUIRE_VALUE(store.getValue("partition1", "key2"), "value12");
        REQUIRE_VALUE(store.getValue("partition1", "key3"), "");
        REQUIRE_VALUE(store.getValue("partition2", "key1"), "value21");
        REQUIRE_VALUE(store.getValue("partition2", "key2"), "value22");
        REQUIRE_VALUE(store.getValue("partition2", "key3"), "");
        REQUIRE_VALUE(store.getValue("partition3", "key1"), "");
        // default partition
        REQUIRE_VALUE(store.getValue("defaultkey1"), "defaultvalue1");
        REQUIRE_VALUE(
            store.getValue(KeyStore::PARTITION_DEFAULT, "defaultkey2"),
            "defaultvalue2");
    }
    //-------------------------------
    // KeyStoreNet deleteKey Section
    //-------------------------------
    SECTION("deleteKey") {
        REQUIRE_NO_ERROR(store.deleteKey("partition1", "key1"));
        REQUIRE_NO_ERROR(store.deleteKey("partition1", "key1"));
        REQUIRE_NO_ERROR(store.deleteKey("partition1", "key3"));
        REQUIRE_NO_ERROR(store.deleteKey("partition3", "key1"));
        REQUIRE_VALUE(store.getValue("partition1", "key1"), "");
        REQUIRE_VALUE(store.getValue("partition1", "key2"), "value12");
        REQUIRE_VALUE(store.getValue("partition2", "key1"), "value21");
        REQUIRE_VALUE(store.getValue("partition2", "key2"), "value22");
    }
    //-------------------------------
    // KeyStoreNet deleteAll Section
    //-------------------------------
    SECTION("deleteAll") {
        REQUIRE_NO_ERROR(store.deleteAll("partition2"));
        REQUIRE_NO_ERROR(store.deleteAll("partition2"));
        REQUIRE_NO_ERROR(store.deleteAll("partition3"));
        REQUIRE_VALUE(store.getValue("partition1", "key1"), "");
        REQUIRE_VALUE(store.getValue("partition1", "key2"), "value12");
        REQUIRE_VALUE(store.getValue("partition2", "key1"), "");
        REQUIRE_VALUE(store.getValue("partition2", "key2"), "");
    }
    //-------------------------------
    // KeyStoreNet getAll Section
    //-------------------------------
    SECTION("getAll") {
        REQUIRE_NO_ERROR(store.setValue("partition1", "key1", "value11"));
        REQUIRE_VALUE(
            store.getAll("partition1"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(store.getAll("partition2"), KeyStore::Values());
        REQUIRE_VALUE(store.getAll("partition3"), KeyStore::Values());
    }
    //-------------------------------
    // KeyStoreNet copyAll Section
    //-------------------------------
    SECTION("copyAll") {
        REQUIRE_NO_ERROR(store.copyAll("partition1", "partition2"));
        REQUIRE_VALUE(
            store.getAll("partition1"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(
            store.getAll("partition2"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(store.getAll("partition3"), KeyStore::Values());
    }
    //-------------------------------
    // KeyStoreNet moveAll Section
    //-------------------------------
    SECTION("moveAll") {
        REQUIRE_NO_ERROR(store.deleteAll("partition2"));
        // move without check for empty
        REQUIRE_NO_ERROR(
            store.moveAll("partition1", "partition2", true, false));
        REQUIRE_VALUE(store.getAll("partition1"), KeyStore::Values());
        REQUIRE_VALUE(
            store.getAll("partition2"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(store.getAll("partition3"), KeyStore::Values());
        // move with check for empty - should not replace anything
        REQUIRE_NO_ERROR(
            store.moveAll("partition1", "partition2", true, true));
        REQUIRE_VALUE(store.getAll("partition1"), KeyStore::Values());
        REQUIRE_VALUE(
            store.getAll("partition2"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        // checking erasure of destination partition
        REQUIRE_NO_ERROR(store.deleteAll("partition1"));
        REQUIRE_NO_ERROR(store.deleteAll("partition2"));
        REQUIRE_NO_ERROR(store.setValue("partition1", "key1", "value11"));
        REQUIRE_NO_ERROR(store.setValue("partition1", "key2", "value12"));
        REQUIRE_NO_ERROR(store.setValue("partition2", "key3", "value31"));
        REQUIRE_NO_ERROR(store.setValue("partition2", "key4", "value42"));
        REQUIRE_VALUE(
            store.getAll("partition1"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(
            store.getAll("partition2"),
            KeyStore::Values({{"key3", "value31"}, {"key4", "value42"}}));
        REQUIRE_NO_ERROR(
            store.moveAll("partition1", "partition2", true, true));
        REQUIRE_VALUE(store.getAll("partition1"), KeyStore::Values());
        REQUIRE_VALUE(
            store.getAll("partition2"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        // checking that destination partition is not cleaned up
        REQUIRE_NO_ERROR(store.deleteAll("partition1"));
        REQUIRE_NO_ERROR(store.deleteAll("partition2"));
        REQUIRE_NO_ERROR(store.setValue("partition1", "key1", "value11"));
        REQUIRE_NO_ERROR(store.setValue("partition1", "key2", "value12"));
        REQUIRE_NO_ERROR(store.setValue("partition2", "key3", "value31"));
        REQUIRE_NO_ERROR(store.setValue("partition2", "key4", "value42"));
        REQUIRE_VALUE(
            store.getAll("partition1"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(
            store.getAll("partition2"),
            KeyStore::Values({{"key3", "value31"}, {"key4", "value42"}}));
        REQUIRE_NO_ERROR(
            store.moveAll("partition1", "partition2", false, true));
        REQUIRE_VALUE(store.getAll("partition1"), KeyStore::Values());
        REQUIRE_VALUE(store.getAll("partition2"),
                      KeyStore::Values({{"key1", "value11"},
                                        {"key2", "value12"},
                                        {"key3", "value31"},
                                        {"key4", "value42"}}));
    }
}

/**
 * Tests service functionality of the KeyStore.
 * Service key store is a wrapper around main KeyStore (which could be either
 * KeyStoreFile or KeyStoreNet). The service key store modifies keys by adding
 * prefix to them
 * @param KeystoreClass class name to test against (KeyStoreFile or KeyStoreNet)
 * @param keystoreName key store name
 */
template <class KeystoreClass>
void executeKeyStoreServiceTests(TextView storeName) {
    auto logScope = enableTestLogging(Lvl::KeyStore, Lvl::Connection, Lvl::Tls);
    auto errorOrKeystore = open(storeName);
    if (errorOrKeystore.hasCcode()) throw errorOrKeystore.ccode();
    KeyStorePtr store = errorOrKeystore.value();
    const auto serviceKey = "service"_tv;
    errorOrKeystore = makeShared<ServiceKeyStore>(serviceKey, store);
    if (errorOrKeystore.hasCcode()) throw errorOrKeystore.ccode();
    KeyStorePtr servicesstore = errorOrKeystore.value();
    //-------------------------------
    // KeyStoreNet clean-up
    //-------------------------------
    SECTION("clean-up") {
        REQUIRE_NO_ERROR(store->deleteAll("partition1"));
        REQUIRE_NO_ERROR(store->deleteAll("partition2"));
    }
    //-------------------------------
    // KeyStoreNet setValue Section
    //-------------------------------
    SECTION("serviceSetValue") {
        REQUIRE_NO_ERROR(store->setValue("partition1", "key1", "value11"));
        REQUIRE_NO_ERROR(
            servicesstore->setValue("partition1", "key2", "value12"));
        REQUIRE_NO_ERROR(store->setValue("partition2", "key1", "value21"));
        REQUIRE_NO_ERROR(
            servicesstore->setValue("partition2", "key2", "value22"));
        // default partition
        REQUIRE_NO_ERROR(store->setValue("defaultkey1", "defaultvalue1"));
        REQUIRE_NO_ERROR(
            servicesstore->setValue("defaultkey2", "defaultvalue2"));
        REQUIRE_NO_ERROR(store->setValue(
            _ts(serviceKey, "/", KeyStore::PARTITION_DEFAULT), "defaultkey3",
            "defaultvalue3"));
    }
    //-------------------------------
    // KeyStoreNet getValue Section
    //-------------------------------
    SECTION("serviceGetValue") {
        REQUIRE_VALUE(store->getValue("partition1", "key1"), "value11");
        REQUIRE_VALUE(servicesstore->getValue("partition1", "key2"),
                      "value12");
        REQUIRE_VALUE(
            store->getValue(_ts(serviceKey, "/", "partition1"), "key2"),
            "value12");
        REQUIRE_VALUE(store->getValue("partition1", "key3"), "");
        REQUIRE_VALUE(store->getValue("partition2", "key1"), "value21");
        REQUIRE_VALUE(servicesstore->getValue("partition2", "key2"),
                      "value22");
        REQUIRE_VALUE(
            store->getValue(_ts(serviceKey, "/", "partition2"), "key2"),
            "value22");
        REQUIRE_VALUE(store->getValue("partition2", "key3"), "");
        REQUIRE_VALUE(store->getValue("partition3", "key1"), "");
        // default partition
        REQUIRE_VALUE(store->getValue("defaultkey1"), "defaultvalue1");
        REQUIRE_VALUE(servicesstore->getValue("defaultkey2"),
                      "defaultvalue2");
        REQUIRE_VALUE(store->getValue(
                          _ts(serviceKey, "/", KeyStore::PARTITION_DEFAULT),
                          "defaultkey3"),
                      "defaultvalue3");
    }
}

TEST_CASE("keystore/net", "[.]") {
    REQUIRE(optKeyStoreNetUrl);
    executeKeyStoreTests<KeyStoreNet>(_cast<TextView>(optKeyStoreNetUrl));
}
TEST_CASE("keystore/file") {
    executeKeyStoreTests<KeyStoreFile>(defaultKeyStoreFile);
}
TEST_CASE("keystoreservice/net", "[.]") {
    REQUIRE(optKeyStoreNetUrl);
    executeKeyStoreServiceTests<KeyStoreNet>(_cast<TextView>(optKeyStoreNetUrl));
}
TEST_CASE("keystoreservice/file") {
    executeKeyStoreServiceTests<KeyStoreFile>(defaultKeyStoreFile);
}

