std::filesystem::path get_install_prefix() {
  // Determine installation prefix by locating the shared library containing
  // the anchor function via dynamic linking information.
  Dl_info dl_info;
  dladdr((void*)&anchor::example_models_location_anchor, &dl_info);
  const auto library_path = std::filesystem::path(dl_info.dli_fname).lexically_normal();

  // Navigate up two directories from the library path to reach the install root:
  // <install_dir>/lib/roboplan_example_models/lib<name>.so -> <install_dir>
  return library_path.parent_path().parent_path();
}

std::filesystem::path get_package_share_dir() { 
  return get_install_prefix() / "share"; 
}

std::filesystem::path get_package_models_dir() {
  return get_package_share_dir() / "roboplan_example_models" / "models";
}
