const int ROWS = 75;
const int COLS = 1000;

int main() {
    // Generate random matrix M[ROWS][COLS]
    // Store columns as bitset<ROWS> for fast OR operations
    vector<bitset<ROWS>> columnData(COLS);
    // Store rows for constructing queries
    vector<vector<int>> rowQueries(ROWS);

    // Deterministic random number generator
    mt19937 prng(987654321);
    uniform_int_distribution<int> coinFlip(0, 1);

    for (int r = 0; r < ROWS; ++r) {
        for (int c = 0; c < COLS; ++c) {
            if (coinFlip(prng)) {
                columnData[c].set(r);
                rowQueries[r].push_back(c);
            }
        }
    }

    // Send all robots
    for (int r = 0; r < ROWS; ++r) {
        cout << "? " << rowQueries[r].size();
        for (int idx : rowQueries[r]) {
            cout << " " << idx + 1;   // positions are 1-based
        }
        cout << endl;
        cout.flush();
    }

    // Request results after one hour
    cout << "@" << endl;
    cout.flush();

    int numResults;
    cin >> numResults;
    assert(numResults == ROWS);
    vector<int> responses(ROWS);
    for (int r = 0; r < ROWS; ++r) {
        cin >> responses[r];
    }

    // Build target bitset from answers
    bitset<ROWS> goal;
    for (int r = 0; r < ROWS; ++r) {
        if (responses[r]) goal.set(r);
    }

    // Brute-force search for the pair of columns whose OR matches goal
    for (int a = 0; a < COLS; ++a) {
        for (int b = a; b < COLS; ++b) {
            bitset<ROWS> combined = columnData[a] | columnData[b];
            if (combined == goal) {
                cout << "! " << a + 1 << " " << b + 1 << endl;
                cout.flush();
                return 0;
            }
        }
    }

    // Fallback (should never be reached with a 2-separable matrix)
    cout << "! 1 1" << endl;
    cout.flush();
    return 0;
}

