///
/// @brief Determines if the given 64-bit value consists of a contiguous block of 1-bits starting at bit 0
///
/// @param val Input value to evaluate
/// @return true if value is a contiguous sequence of ones from LSB, false otherwise
static bool isContiguousMask_64(uint64_t const val) VB_NOEXCEPT {
  return (val != 0U) && (((val + 1U) & val) == 0U);
}

///
/// @brief Determines if the given 64-bit value contains a contiguous block of 1-bits (not necessarily at LSB)
///
/// The block of ones may be shifted left by some amount
///
/// @param val Input value to evaluate
/// @return true if value is a shifted contiguous mask, false otherwise
static bool isRotatedMask_64(uint64_t const val) VB_NOEXCEPT {
  return (val != 0U) && isContiguousMask_64((val - 1U) | val);
}

bool decodeLogicalImmediate(uint64_t imm, bool const is64bit, uint64_t &encodedForm) VB_NOEXCEPT {
  uint64_t const maxRegisterValue{is64bit ? UINT64_MAX : UINT32_MAX};

  // Immediate values 0 and all-ones cannot be encoded using this scheme
  if ((imm == 0U) || (imm >= maxRegisterValue)) {
    return false;
  }

  // Determine element size: start with full register width and halve until pattern breaks
  uint64_t elementSize{is64bit ? 64_U64 : 32_U64};
  while (elementSize > 2U) {
    elementSize /= 2U;
    uint64_t const elementMask{(1_U64 << elementSize) - 1U};
    if ((imm & elementMask) != ((imm >> elementSize) & elementMask)) {
      elementSize *= 2U;
      break;
    }
  }

  // Isolate the lowest element
  uint64_t const elementBoundaryMask{(elementSize == 64U) ? UINT64_MAX : ((1_U64 << elementSize) - 1U)};
  imm &= elementBoundaryMask;

  // Compute rotation parameters for encoding
  uint64_t CTO;
  uint64_t I;

  if (isRotatedMask_64(imm)) {
    I = static_cast<uint64_t>(ctzll(imm));
    assert(I < 64 && "count trailing zeros on zero is undefined");
    CTO = static_cast<uint64_t>(ctzll(~(imm >> I)));
  } else {
    imm |= ~elementBoundaryMask;
    if (!isRotatedMask_64(~imm)) {
      return false;
    }
    uint64_t const CLZ{static_cast<uint64_t>(clzll(~imm))};
    I = 64_U64 - CLZ;
    uint64_t const CTOinv{static_cast<uint64_t>(ctzll(~imm))};
    CTO = (CLZ + CTOinv) - (64_U64 - elementSize);
  }

  // Compute Immr: number of right rotations needed to transform canonical form into target
  assert(elementSize > I && "rotation count exceeds element size");
  uint64_t const Immr{(elementSize - I) & (elementSize - 1U)};

  // Construct N and Imms fields
  uint64_t NImms{~(elementSize - 1U) << 1U};
  NImms |= CTO - 1U;

  uint64_t const N{((NImms >> 6U) & 1U) ^ 1U};

  encodedForm = (N << 12U) | (Immr << 6U) | (NImms & 0x3FU);
  return true;
}

