using namespace llvm;

namespace {
  struct CrashRecoveryContextImpl;
  static LLVM_THREAD_LOCAL const CrashRecoveryContextImpl *ActiveContext;

  struct CrashRecoveryContextImpl {
    // When threading is disabled, this links all active implementations.
    // With threads enabled, each thread has its own context, so this remains null.
    const CrashRecoveryContextImpl *NextEntry;
    CrashRecoveryContext *Owner;
    ::jmp_buf RecoveryBuffer;
    volatile unsigned Errored : 1;
    unsigned ThreadSwitched : 1;
    unsigned BufferValid : 1;

  public:
    CrashRecoveryContextImpl(CrashRecoveryContext *ctx) noexcept
        : Owner(ctx), Errored(false), ThreadSwitched(false), BufferValid(false) {
      NextEntry = ActiveContext;
      ActiveContext = this;
    }

    ~CrashRecoveryContextImpl() {
      if (!ThreadSwitched)
        ActiveContext = NextEntry;
    }

    void markThreadSwitched() {
#if defined(LLVM_ENABLE_THREADS) && LLVM_ENABLE_THREADS != 0
      ThreadSwitched = true;
#endif
    }

    void handleException(int exitCode, uintptr_t ctxData) {
      ActiveContext = NextEntry;
      assert(!Errored && "Recovery context already triggered!");
      Errored = true;
      if (Owner->DumpStackAndCleanupOnFailure)
        sys::CleanupOnSignal(ctxData);
      Owner->RetCode = exitCode;
      if (BufferValid)
        longjmp(RecoveryBuffer, 1);
    }
  };

  std::mutex &getRecoveryMutex() {
    static std::mutex RecoveryMutex;
    return RecoveryMutex;
  }

  static bool gRecoveryEnabled = false;
  static LLVM_THREAD_LOCAL const CrashRecoveryContext *InRecoveryMode;
}

static void setupSignalHandlers();
static void removeSignalHandlers();

CrashRecoveryContextCleanup::~CrashRecoveryContextCleanup() = default;

CrashRecoveryContext::CrashRecoveryContext() {
  sys::DisableSystemDialogsOnCrash();
}

CrashRecoveryContext::~CrashRecoveryContext() {
  CrashRecoveryContextCleanup *node = head;
  const CrashRecoveryContext *prevRecoveryState = InRecoveryMode;
  InRecoveryMode = this;
  while (node) {
    CrashRecoveryContextCleanup *current = node;
    node = current->next;
    current->cleanupFired = true;
    current->recoverResources();
    delete current;
  }
  InRecoveryMode = prevRecoveryState;
  CrashRecoveryContextImpl *impl = (CrashRecoveryContextImpl *) Impl;
  delete impl;
}

bool CrashRecoveryContext::isRecoveringFromCrash() {
  return InRecoveryMode != nullptr;
}

CrashRecoveryContext *CrashRecoveryContext::GetCurrent() {
  if (!gRecoveryEnabled)
    return nullptr;
  const CrashRecoveryContextImpl *impl = ActiveContext;
  if (!impl)
    return nullptr;
  return impl->Owner;
}

void CrashRecoveryContext::Enable() {
  std::lock_guard<std::mutex> lock(getRecoveryMutex());
  if (gRecoveryEnabled)
    return;
  gRecoveryEnabled = true;
  setupSignalHandlers();
}

void CrashRecoveryContext::Disable() {
  std::lock_guard<std::mutex> lock(getRecoveryMutex());
  if (!gRecoveryEnabled)
    return;
  gRecoveryEnabled = false;
  removeSignalHandlers();
}

void CrashRecoveryContext::registerCleanup(CrashRecoveryContextCleanup *cleanup) {
  if (!cleanup)
    return;
  if (head)
    head->prev = cleanup;
  cleanup->next = head;
  head = cleanup;
}

void CrashRecoveryContext::unregisterCleanup(CrashRecoveryContextCleanup *cleanup) {
  if (!cleanup)
    return;
  if (cleanup == head) {
    head = cleanup->next;
    if (head)
      head->prev = nullptr;
  } else {
    cleanup->prev->next = cleanup->next;
    if (cleanup->next)
      cleanup->next->prev = cleanup->prev;
  }
  delete cleanup;
}

#if defined(_MSC_VER)
#include <windows.h>

static void setupSignalHandlers() {}
static void removeSignalHandlers() {}

static int ExceptionFilter(_EXCEPTION_POINTERS *exceptInfo) {
  const CrashRecoveryContextImpl *impl = ActiveContext;
  if (!impl) {
    CrashRecoveryContext::Disable();
    return EXCEPTION_CONTINUE_SEARCH;
  }
  int code = (int)exceptInfo->ExceptionRecord->ExceptionCode;
  if ((code & 0xF0000000) == 0xE0000000)
    code &= ~0xF0000000;
  const_cast<CrashRecoveryContextImpl *>(impl)->handleException(
      code, reinterpret_cast<uintptr_t>(exceptInfo));
  return EXCEPTION_EXECUTE_HANDLER;
}

#if defined(__clang__) && defined(_M_IX86)
__attribute__((optnone))
#endif
bool CrashRecoveryContext::RunSafely(function_ref<void()> func) {
  if (!gRecoveryEnabled) {
    func();
    return true;
  }
  assert(!Impl && "Context already initialized!");
  Impl = new CrashRecoveryContextImpl(this);
  __try {
    func();
  } __except (ExceptionFilter(GetExceptionInformation())) {
    return false;
  }
  return true;
}
#else // !_MSC_VER

#if defined(_WIN32)
#include "llvm/Support/Windows/WindowsSupport.h"

static LONG CALLBACK ExceptionHandler(PEXCEPTION_POINTERS info) {
  constexpr ULONG DbgPrintExceptionWideC = 0x4001000AL;
  switch (info->ExceptionRecord->ExceptionCode) {
  case DBG_PRINTEXCEPTION_C:
  case DbgPrintExceptionWideC:
  case 0x406D1388:
    return EXCEPTION_CONTINUE_EXECUTION;
  }

  const CrashRecoveryContextImpl *impl = ActiveContext;
  if (!impl) {
    CrashRecoveryContext::Disable();
    return EXCEPTION_CONTINUE_SEARCH;
  }

  int code = (int)info->ExceptionRecord->ExceptionCode;
  if ((code & 0xF0000000) == 0xE0000000)
    code &= ~0xF0000000;
  const_cast<CrashRecoveryContextImpl *>(impl)->handleException(
      code, reinterpret_cast<uintptr_t>(info));
  llvm_unreachable("Should have jumped out via longjmp");
}

static LLVM_THREAD_LOCAL const void* sVEHHandle;

static void setupSignalHandlers() {
  PVOID handle = ::AddVectoredExceptionHandler(1, ExceptionHandler);
  sVEHHandle = handle;
}

static void removeSignalHandlers() {
  PVOID handle = const_cast<PVOID>(sVEHHandle);
  if (handle) {
    ::RemoveVectoredExceptionHandler(handle);
    sVEHHandle = nullptr;
  }
}

#else // !_WIN32

#include <signal.h>

static const int SignalList[] =
    { SIGABRT, SIGBUS, SIGFPE, SIGILL, SIGSEGV, SIGTRAP };
static const unsigned SignalCount = std::size(SignalList);
static struct sigaction OldActions[SignalCount];

static void SignalHandler(int signal) {
  const CrashRecoveryContextImpl *impl = ActiveContext;
  if (!impl) {
    CrashRecoveryContext::Disable();
    raise(signal);
    return;
  }

  sigset_t mask;
  sigemptyset(&mask);
  sigaddset(&mask, signal);
  sigprocmask(SIG_UNBLOCK, &mask, nullptr);

  int code = 128 + signal;
  if (signal == SIGPIPE)
    code = EX_IOERR;
  const_cast<CrashRecoveryContextImpl *>(impl)->handleException(code, signal);
}

static void setupSignalHandlers() {
  struct sigaction action;
  action.sa_handler = SignalHandler;
  action.sa_flags = 0;
  sigemptyset(&action.sa_mask);
  for (unsigned i = 0; i != SignalCount; ++i)
    sigaction(SignalList[i], &action, &OldActions[i]);
}

static void removeSignalHandlers() {
  for (unsigned i = 0; i != SignalCount; ++i)
    sigaction(SignalList[i], &OldActions[i], nullptr);
}

#endif // !_WIN32

bool CrashRecoveryContext::RunSafely(function_ref<void()> func) {
  if (gRecoveryEnabled) {
    assert(!Impl && "Context already initialized!");
    CrashRecoveryContextImpl *impl = new CrashRecoveryContextImpl(this);
    Impl = impl;
    impl->BufferValid = true;
    if (setjmp(impl->RecoveryBuffer) != 0)
      return false;
  }
  func();
  return true;
}

#endif // !_MSC_VER

[[noreturn]] void CrashRecoveryContext::HandleExit(int code) {
#if defined(_WIN32)
  ::RaiseException(0xE0000000 | code, 0, 0, NULL);
#else
  CrashRecoveryContextImpl *impl = (CrashRecoveryContextImpl *)Impl;
  assert(impl && "Context not initialized!");
  impl->handleException(code, 0);
#endif
  llvm_unreachable("Expected setjmp to be called first!");
}

bool CrashRecoveryContext::isCrash(int code) {
#if defined(_WIN32)
  unsigned severity = ((unsigned)code & 0xF0000000) >> 28;
  if (severity != 0xC && severity != 8)
    return false;
#else
  if (code <= 128)
    return false;
#endif
  return true;
}

bool CrashRecoveryContext::throwIfCrash(int code) {
  if (!isCrash(code))
    return false;
#if defined(_WIN32)
  ::RaiseException(code, 0, 0, NULL);
#else
  llvm::sys::unregisterHandlers();
  raise(code - 128);
#endif
  return true;
}

static void setThreadBackgroundPriority() {
#ifdef __APPLE__
  setpriority(PRIO_DARWIN_THREAD, 0, PRIO_DARWIN_BG);
#endif
}

static bool hasThreadBackgroundPriority() {
#ifdef __APPLE__
  return getpriority(PRIO_DARWIN_THREAD, 0) == 1;
#else
  return false;
#endif
}

namespace {
struct ThreadTaskInfo {
  function_ref<void()> Task;
  CrashRecoveryContext *Context;
  bool UseBackgroundPriority;
  bool ExecutionResult;
};
}

static void ThreadTaskWrapper(void *userData) {
  ThreadTaskInfo *info = reinterpret_cast<ThreadTaskInfo*>(userData);
  if (info->UseBackgroundPriority)
    setThreadBackgroundPriority();
  info->ExecutionResult = info->Context->RunSafely(info->Task);
}

bool CrashRecoveryContext::RunSafelyOnThread(function_ref<void()> task,
                                             unsigned stackSize) {
  bool useBgPriority = hasThreadBackgroundPriority();
  ThreadTaskInfo info = { task, this, useBgPriority, false };
  llvm::thread worker(stackSize == 0 ? std::nullopt
                                     : std::optional<unsigned>(stackSize),
                      ThreadTaskWrapper, &info);
  worker.join();
  if (CrashRecoveryContextImpl *impl = (CrashRecoveryContextImpl *)Impl)
    impl->markThreadSwitched();
  return info.ExecutionResult;
}

