// Constructor for ZoneIo class
ZoneIo::ZoneIo(HANDLE ioChannel, __int64 filePosition)
{
    this->ioChannel = ioChannel;
    this->filePosition = filePosition;
}

// Write method that takes a byteArray and size
void ZoneIo::write(byteArray dataBuffer, int byteCount)
{
    ByteBuffer *buffer = ByteBuffer::wrap(dataBuffer);
    // buffer->order(ZonedChunkStorage::BYTEORDER);  // Commented out in original
    buffer->position(dataBuffer.length);
    buffer->flip();
    write(buffer, byteCount);
    delete buffer;
}

// Write method that takes a ByteBuffer pointer and size
void ZoneIo::write(ByteBuffer *buffer, int byteCount)
{
    DWORD bytesWritten;
    SetFilePointer(ioChannel, (int)filePosition, NULL, NULL);
    WriteFile(ioChannel, buffer->getBuffer(), buffer->getSize(), &bytesWritten, NULL);
    filePosition += byteCount;
}

// Read method that returns a ByteBuffer of specified size
ByteBuffer *ZoneIo::read(int size)
{
    DWORD bytesRead;
    byteArray bufferData = byteArray(size);
    SetFilePointer(ioChannel, (int)filePosition, NULL, NULL);
    ByteBuffer *resultBuffer = ByteBuffer::wrap(bufferData);
    resultBuffer->order(ZonedChunkStorage::BYTEORDER);
    resultBuffer->position(size);
    resultBuffer->flip();
    ReadFile(ioChannel, resultBuffer->getBuffer(), resultBuffer->getSize(), &bytesRead, NULL);
    filePosition += size;
    return resultBuffer;
}

