 * Purpose:	Given an object ID return a location for the object.
 *
 * Return:	Success:	Group pointer.
 *		Failure:	NULL
 *
 * Programmer:	Quincey Koziol
 *              Tuesday, September 13, 2005
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5G_locate(hid_t obj_id, H5G_loc_t *location)
{
    herr_t      result = SUCCEED;    /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    switch(H5I_get_type(obj_id)) {
        case H5I_FILE:
            {
                H5F_t	*file;
                /* Get the file struct */
                if(NULL == (file = (H5F_t *)H5I_object(obj_id)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid file ID")
                /* Construct a group location for root group of the file */
                if(H5G_root_loc(file, location) < 0)
                    HGOTO_ERROR(H5E_SYM, H5E_BADVALUE, FAIL, "unable to create location for file")
            } /* end case */
            break;
        case H5I_GENPROP_CLS:
        case H5I_GENPROP_LST:
            HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get group location of property list")
        case H5I_ERROR_CLASS:
        case H5I_ERROR_MSG:
        case H5I_ERROR_STACK:
            HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get group location of error class, message or stack")
        case H5I_GROUP:
            {
                H5G_t	*group;
                if(NULL == (group = (H5G_t *)H5I_object(obj_id)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid group ID")
                if(NULL == (location->oloc = H5G_oloc(group)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get object location of group")
                if(NULL == (location->path = H5G_nameof(group)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get path of group")
            } /* end case */
            break;
        case H5I_DATATYPE:
            {
                H5T_t	*dt;
                if(NULL == (dt = (H5T_t *)H5I_object(obj_id)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid type ID")
                if(NULL == (location->oloc = H5T_oloc(dt)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get object location of datatype")
                if(NULL == (location->path = H5T_nameof(dt)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get path of datatype")
            } /* end case */
            break;
        case H5I_DATASPACE:
            HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get group location of dataspace")
        case H5I_DATASET:
            {
                H5D_t	*dataset;
                if(NULL == (dataset = (H5D_t *)H5I_object(obj_id)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid data ID")
                if(NULL == (location->oloc = H5D_oloc(dataset)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get object location of dataset")
                if(NULL == (location->path = H5D_nameof(dataset)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get path of dataset")
            } /* end case */
            break;
        case H5I_ATTR:
            {
                H5A_t	*attribute;
                if(NULL == (attribute = (H5A_t *)H5I_object(obj_id)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid attribute ID")
                if(NULL == (location->oloc = H5A_oloc(attribute)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get object location of attribute")
                if(NULL == (location->path = H5A_nameof(attribute)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get path of attribute")
            } /* end case */
            break;
        case H5I_REFERENCE:
            HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get group location of reference")
        case H5I_UNINIT:
        case H5I_BADID:
        case H5I_VFL:
        case H5I_NTYPES:
        default:
            HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid object ID")
    } /* end switch */
done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5G_locate() */

/*-------------------------------------------------------------------------
 * Function:	H5G__locate_copy
 *
 * Purpose:	Copy over information for a location
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *		Tuesday, September 13, 2005
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5G__locate_copy(H5G_loc_t *dest, const H5G_loc_t *source, H5_copy_depth_t depth)
{
    herr_t      result = SUCCEED;       /* Return value */
    FUNC_ENTER_PACKAGE
    /* Check args. */
    HDassert(dest);
    HDassert(source);
    /* Copy components of the location */
    if(H5O_loc_copy(dest->oloc, source->oloc, depth) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_CANTOPENOBJ, FAIL, "unable to copy entry")
    if(H5G_name_copy(dest->path, source->path, depth) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_CANTOPENOBJ, FAIL, "unable to copy path")
done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5G__locate_copy() */

/*-------------------------------------------------------------------------
 * Function:	H5G_locate_reset
 *
 * Purpose:	Reset information for a location
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *		Tuesday, September 13, 2005
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5G_locate_reset(H5G_loc_t *location)
{
    herr_t      result = SUCCEED;       /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    /* Check args. */
    HDassert(location);
    /* Reset components of the location */
    if(H5O_loc_reset(location->oloc) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_CANTOPENOBJ, FAIL, "unable to reset entry")
    if(H5G_name_reset(location->path) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_CANTOPENOBJ, FAIL, "unable to reset path")
done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5G_locate_reset() */

/*-------------------------------------------------------------------------
 * Function:	H5G_locate_release
 *
 * Purpose:	Free information for a location
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *		Tuesday, September 13, 2005
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5G_locate_release(H5G_loc_t *location)
{
    herr_t      result = SUCCEED;       /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    /* Check args. */
    HDassert(location);
    /* Reset components of the location */
    if(H5G_name_free(location->path) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_CANTRELEASE, FAIL, "unable to free path")
    if(H5O_loc_free(location->oloc) < 0)
        HGOTO_ERROR(H5E_OHDR, H5E_CANTRELEASE, FAIL, "unable to free object header location")
done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5G_locate_release() */

/*-------------------------------------------------------------------------
 * Function:	H5G_loc_lookup_cb
 *
 * Purpose:	Callback for retrieving object location for an object in a group
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *              Monday, October 17, 2005
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5G_loc_lookup_cb(H5G_loc_t H5_ATTR_UNUSED *grp_loc/*in*/, const char *symbol,
    const H5O_link_t H5_ATTR_UNUSED *lnk, H5G_loc_t *obj_loc, void *_udata/*in,out*/,
    H5G_own_loc_t *own_loc/*out*/)
{
    H5G_loc_fnd_t *data = (H5G_loc_fnd_t *)_udata;   /* User data passed in */
    herr_t result = SUCCEED;         /* Return value */
    FUNC_ENTER_NOAPI_NOINIT
    /* Check if the name in this group resolved to a valid object */
    if(obj_loc == NULL)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "object '%s' doesn't exist", symbol)
    /* Take ownership of the object's group location */
    /* (Group traversal callbacks are responsible for either taking ownership
     *  of the group location for the object, or freeing it. - QAK)
     */
    H5G__loc_copy(data->location, obj_loc, H5_COPY_SHALLOW);
    *own_loc = H5G_OWN_OBJ_LOC;
done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5G_loc_lookup_cb() */

/*-------------------------------------------------------------------------
 * Function:	H5G_locate_find
 *
 * Purpose:	Find a symbol from a location
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *		Tuesday, September 13, 2005
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5G_locate_find(const H5G_loc_t *location, const char *symbol, H5G_loc_t *obj_loc/*out*/,
    hid_t lapl_id, hid_t dxpl_id)
{
    H5G_loc_fnd_t udata;                /* User data for traversal callback */
    herr_t result = SUCCEED;         /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    /* Check args. */
    HDassert(location);
    HDassert(symbol && *symbol);
    HDassert(obj_loc);
    /* Set up user data for locating object */
    udata.location = obj_loc;
    /* Traverse group hierarchy to locate object */
    if(H5G_traverse(location, symbol, H5G_TARGET_NORMAL, H5G_loc_lookup_cb, &udata, lapl_id, dxpl_id) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "can't find object")
done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5G_locate_find() */

/*-------------------------------------------------------------------------
 * Function:	H5G_loc_lookup_by_idx_cb
 *
 * Purpose:	Callback for retrieving object location for an object in a group
 *              according to the order within an index
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *              Monday, November 20, 2006
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5G_loc_lookup_by_idx_cb(H5G_loc_t H5_ATTR_UNUSED *grp_loc/*in*/, const char H5_ATTR_UNUSED *symbol,
    const H5O_link_t H5_ATTR_UNUSED *lnk, H5G_loc_t *obj_loc, void *_udata/*in,out*/,
    H5G_own_loc_t *own_loc/*out*/)
{
    H5G_loc_fbi_t *data = (H5G_loc_fbi_t *)_udata;   /* User data passed in */
    H5O_link_t found_lnk;                 /* Link within group */
    hbool_t lnk_copied = FALSE;         /* Whether the link was copied */
    size_t links_remaining = H5L_NUM_LINKS;  /* # of links left to traverse */
    hbool_t obj_loc_valid = FALSE;      /* Flag to indicate that the object location is valid */
    hbool_t obj_exists = FALSE;         /* Whether the object exists (unused) */
    herr_t result = SUCCEED;         /* Return value */
    FUNC_ENTER_NOAPI_NOINIT
    /* Check if the name in this group resolved to a valid link */
    if(obj_loc == NULL)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "group doesn't exist")
    /* Query link */
    if(H5G_obj_lookup_by_idx(obj_loc->oloc, data->idx_type, data->order,
                data->offset, &found_lnk, data->dxpl_id) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "link not found")
    lnk_copied = TRUE;
    /* Build the initial object location for the link */
    if(H5G__link_to_loc(obj_loc, &found_lnk, data->location) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_CANTINIT, FAIL, "cannot initialize object location")
    obj_loc_valid = TRUE;
    /* Perform any special traversals that the link needs */
    /* (soft links, user-defined links, file mounting, etc.) */
    /* (may modify the object location) */
    if(H5G__traverse_special(obj_loc, &found_lnk, H5G_TARGET_NORMAL, &links_remaining, TRUE, data->location, &obj_exists, data->lapl_id, data->dxpl_id) < 0)
        HGOTO_ERROR(H5E_LINK, H5E_TRAVERSE, FAIL, "special link traversal failed")
done:
    /* Reset the link information, if we have a copy */
    if(lnk_copied)
        H5O_msg_reset(H5O_LINK_ID, &found_lnk);
    /* Release the object location if we failed after copying it */
    if(result < 0 && obj_loc_valid)
        if(H5G_locate_release(data->location) < 0)
            HDONE_ERROR(H5E_SYM, H5E_CANTRELEASE, FAIL, "can't free location")
    /* Indicate that this callback didn't take ownership of the group *
     * location for the object */
    *own_loc = H5G_OWN_NONE;
    FUNC_LEAVE_NOAPI(result)
} /* end H5G_loc_lookup_by_idx_cb() */

/*-------------------------------------------------------------------------
 * Function:	H5G_locate_find_by_idx
 *
 * Purpose:	Find a symbol from a location, according to the order in an index
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *		Monday, November 20, 2006
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5G_locate_find_by_idx(H5G_loc_t *location, const char *group_name, H5_index_t idx_type,
    H5_iter_order_t order, hsize_t offset, H5G_loc_t *obj_loc/*out*/, hid_t lapl_id,
    hid_t dxpl_id)
{
    H5G_loc_fbi_t udata;                /* User data for traversal callback */
    herr_t result = SUCCEED;         /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    /* Check args. */
    HDassert(location);
    HDassert(group_name && *group_name);
    HDassert(obj_loc);
    /* Set up user data for locating object */
    udata.dxpl_id = dxpl_id;
    udata.lapl_id = lapl_id;
    udata.idx_type = idx_type;
    udata.order = order;
    udata.offset = offset;
    udata.location = obj_loc;
    /* Traverse group hierarchy to locate object */
    if(H5G_traverse(location, group_name, H5G_TARGET_NORMAL, H5G_loc_lookup_by_idx_cb, &udata, lapl_id, dxpl_id) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "can't find object")
done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5G_locate_find_by_idx() */

/*-------------------------------------------------------------------------
 * Function:	H5G__locate_insert
 *
 * Purpose:	Insert an object at a location
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *		Tuesday, September 13, 2005
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5G__locate_insert(H5G_loc_t *grp_loc, const char *symbol, H5G_loc_t *obj_loc,
    H5O_type_t obj_type, const void *crt_info, hid_t dxpl_id)
{
    H5O_link_t  lnk;                    /* Link for object to insert */
    herr_t      result = SUCCEED;    /* Return value */
    FUNC_ENTER_PACKAGE
    /* Check args. */
    HDassert(grp_loc);
    HDassert(symbol && *symbol);
    HDassert(obj_loc);
    /* Create link object for the object location */
    lnk.type = H5L_TYPE_HARD;
    lnk.cset = H5F_DEFAULT_CSET;
    lnk.corder = 0;     /* Will be reset if the group is tracking creation order */
    lnk.corder_valid = FALSE;   /* Indicate that the creation order isn't valid (yet) */
    /* Casting away const OK -QAK */
    lnk.name = (char *)symbol;
    lnk.u.hard.addr = obj_loc->oloc->addr;
    /* Insert new group into current group's symbol table */
    if(H5G_obj_insert(grp_loc->oloc, symbol, &lnk, TRUE, obj_type, crt_info,
            dxpl_id) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_CANTINSERT, FAIL, "unable to insert object")
    /* Set the name of the object location */
    if(H5G_name_set(grp_loc->path, obj_loc->path, symbol) < 0)
       HGOTO_ERROR(H5E_SYM, H5E_CANTINIT, FAIL, "cannot set name")
done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5G__locate_insert() */

/*-------------------------------------------------------------------------
 * Function:	H5G_loc_exists_cb
 *
 * Purpose:	Callback for checking if an object exists
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *              Tuesday, February 2, 2010
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5G_loc_exists_cb(H5G_loc_t H5_ATTR_UNUSED *grp_loc/*in*/, const char H5_ATTR_UNUSED *symbol,
    const H5O_link_t H5_ATTR_UNUSED *lnk, H5G_loc_t *obj_loc, void *_udata/*in,out*/,
    H5G_own_loc_t *own_loc/*out*/)
{
    H5G_loc_exists_t *data = (H5G_loc_exists_t *)_udata;   /* User data passed in */
    FUNC_ENTER_NOAPI_NOINIT_NOERR
    /* Check if the name in this group resolved to a valid object */
    if(obj_loc == NULL)
        if(lnk)
            data->found = FALSE;
        else
            data->found = FAIL;
    else
        data->found = TRUE;
    /* Indicate that this callback didn't take ownership of the group *
     * location for the object */
    *own_loc = H5G_OWN_NONE;
    FUNC_LEAVE_NOAPI(SUCCEED)
} /* end H5G_loc_exists_cb() */

/*-------------------------------------------------------------------------
 * Function:	H5G_locate_exists
 *
 * Purpose:	Check if an object actually exists at a location
 *
 * Return:	Success:	TRUE/FALSE
 * 		Failure:	Negative
 *
 * Programmer:	Quincey Koziol
 *		Tuesday, February 2, 2010
 *
 *-------------------------------------------------------------------------
 */
htri_t
H5G_locate_exists(const H5G_loc_t *location, const char *symbol, hid_t lapl_id, hid_t dxpl_id)
{
    H5G_loc_exists_t udata;     /* User data for traversal callback */
    htri_t result;           /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    /* Check args. */
    HDassert(location);
    HDassert(symbol && *symbol);
    /* Set up user data for locating object */
    udata.found = FALSE;
    /* Traverse group hierarchy to locate object */
    if(H5G_traverse(location, symbol, H5G_TARGET_EXISTS, H5G_loc_exists_cb, &udata, lapl_id, dxpl_id) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "can't check if object exists")
    /* Set return value */
    result = udata.found;
done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5G_locate_exists() */

