#include "world.h"
#include <omp.h>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>

// Structure mapping particles to spatial hash buckets
struct ParticleIndex {
    uint32_t bucket;
    int particleId;
};

class GridSimulator : public Simulator {
private:
    // Hardware-specific thread configuration
    int threadCount = 8;

    // Spatial partitioning parameters
    static const int GRID_CAPACITY = 8192; 
    static const int BUCKET_MASK = GRID_CAPACITY - 1;

    // Memory buffers for grid operations
    std::vector<ParticleIndex> indices;
    std::vector<int> bucketBegin;
    std::vector<int> bucketEnd;

    // Optimized layout for cache-friendly access patterns
    std::vector<Particle> orderedParticles;

public:
    void initialize(int particleCount, StepParameters config) override {
        omp_set_num_threads(threadCount);

        indices.resize(particleCount);
        orderedParticles.resize(particleCount);

        bucketBegin.resize(GRID_CAPACITY);
        bucketEnd.resize(GRID_CAPACITY);
    }

    void simulateStep(std::vector<Particle> &particles,
                      std::vector<Particle> &newParticles,
                      StepParameters config) override {
        int count = (int)particles.size();

        // Adjust buffer sizes if particle count changes
        if ((int)indices.size() != count) {
            indices.resize(count);
            orderedParticles.resize(count);
        }

        // Use finer grid resolution: cell size is half the interaction radius
        // This increases neighbor cells from 3x3 to 5x5 but reduces false positives
        float gridSize = config.cullRadius * 0.5f;
        float invGridSize = 1.0f / gridSize;

        // Phase 1: Compute hash values in parallel
        #pragma omp parallel for
        for (int idx = 0; idx < count; idx++) {
            int cellX = static_cast<int>(std::floor(particles[idx].position.x * invGridSize));
            int cellY = static_cast<int>(std::floor(particles[idx].position.y * invGridSize));

            // Combine coordinates using prime-based hashing
            uint32_t h = ((cellX * 73856093) ^ (cellY * 19349663)) & BUCKET_MASK;

            indices[idx] = {h, idx};
        }

        // Phase 2: Sort by hash value for contiguous memory access
        std::sort(indices.begin(), indices.end(), [](const ParticleIndex& x, const ParticleIndex& y) {
            return x.bucket < y.bucket;
        });

        // Phase 3: Reorder particles and build index ranges
        std::fill(bucketBegin.begin(), bucketBegin.end(), -1);

        // Parallel particle reordering
        #pragma omp parallel 
        {
            #pragma omp for
            for (int i = 0; i < count; i++) {
                orderedParticles[i] = particles[indices[i].particleId];
            }
        }

        // Sequential scan to set bucket boundaries
        for (int i = 0; i < count; i++) {
            uint32_t h = indices[i].bucket;
            if (bucketBegin[h] == -1) bucketBegin[h] = i;
            bucketEnd[h] = i + 1;
        }

        float radiusSquared = config.cullRadius * config.cullRadius;

        // Phase 4: Force calculations with spatial locality optimization
        #pragma omp parallel for schedule(dynamic, 32)
        for (int i = 0; i < count; i++) {
            const Particle& current = particles[i];
            Vec2 netForce = {0.0f, 0.0f};

            int cellX = static_cast<int>(std::floor(current.position.x * invGridSize));
            int cellY = static_cast<int>(std::floor(current.position.y * invGridSize));

            // Check 5x5 neighborhood of cells
            for (int dy = -2; dy <= 2; dy++) {
                for (int dx = -2; dx <= 2; dx++) {
                    uint32_t h = (((cellX + dx) * 73856093) ^ ((cellY + dy) * 19349663)) & BUCKET_MASK;

                    int startIdx = bucketBegin[h];
                    if (startIdx == -1) continue;

                    int endIdx = bucketEnd[h];

                    for (int k = startIdx; k < endIdx; k++) {
                        // Skip self-interaction
                        if (indices[k].particleId == i) continue;

                        // Access neighboring particle data sequentially
                        const Particle& neighbor = orderedParticles[k];

                        float diffX = current.position.x - neighbor.position.x;
                        float diffY = current.position.y - neighbor.position.y;
                        float distanceSq = diffX * diffX + diffY * diffY;

                        // Apply force only within interaction radius
                        if (distanceSq < radiusSquared) {
                            netForce += computeForce(current, neighbor, config.cullRadius);
                        }
                    }
                }
            }

            newParticles[i] = updateParticle(current, netForce, config.deltaTime);
        }
    }
};

Simulator* createSimulator() {
    return new GridSimulator();
}

