/// Duplicate a basic block from the source function into the target function,
/// updating value mappings and collecting code characteristics.
BasicBlock *llvm::CloneBasicBlock(const BasicBlock *SrcBB, ValueToValueMapTy &ValueMap,
                                  const Twine &Suffix, Function *TargetFunc,
                                  ClonedCodeInfo *CodeStats,
                                  DebugInfoFinder *DIFinder) {
  BasicBlock *DestBB = BasicBlock::Create(SrcBB->getContext(), "", TargetFunc);
  DestBB->IsNewDbgInfoFormat = SrcBB->IsNewDbgInfoFormat;

  if (SrcBB->hasName())
    DestBB->setName(SrcBB->getName() + Suffix);

  bool ContainsCalls = false, ContainsDynamicAllocas = false, ContainsMemProfMetadata = false;
  Module *CurrentModule = TargetFunc ? TargetFunc->getParent() : nullptr;

  // Iterate through all instructions in the source block
  for (const Instruction &Instr : *SrcBB) {
    if (DIFinder && CurrentModule)
      DIFinder->processInstruction(*CurrentModule, Instr);

    Instruction *NewInstr = Instr.clone();

    if (Instr.hasName())
      NewInstr->setName(Instr.getName() + Suffix);

    NewInstr->insertBefore(*DestBB, DestBB->end());
    NewInstr->cloneDebugInfoFrom(&Instr);
    ValueMap[&Instr] = NewInstr;

    if (isa<CallInst>(Instr) && !Instr.isDebugOrPseudoInst()) {
      ContainsCalls = true;
      ContainsMemProfMetadata |= Instr.hasMetadata(LLVMContext::MD_memprof);
    }

    if (const AllocaInst *AI = dyn_cast<AllocaInst>(&Instr)) {
      if (!AI->isStaticAlloca()) {
        ContainsDynamicAllocas = true;
      }
    }
  }

  if (CodeStats) {
    CodeStats->ContainsCalls |= ContainsCalls;
    CodeStats->ContainsMemProfMetadata |= ContainsMemProfMetadata;
    CodeStats->ContainsDynamicAllocas |= ContainsDynamicAllocas;
  }

  return DestBB;
}

// Duplicate OldFunc into NewFunc, transforming old arguments to references
// in the VMap values.
void llvm::CloneFunctionInto(Function *DestFunc, const Function *SrcFunc,
                             ValueToValueMapTy &ValueMap,
                             CloneFunctionChangeType Changes,
                             SmallVectorImpl<ReturnInst *> &ReturnList,
                             const char *Suffix, ClonedCodeInfo *CodeInfo,
                             ValueMapTypeRemapper *TypeMapper,
                             ValueMaterializer *Materializer) {
  DestFunc->setIsNewDbgInfoFormat(SrcFunc->IsNewDbgInfoFormat);
  assert(Suffix && "Suffix cannot be null!");

#ifndef NDEBUG
  for (const Argument &Arg : SrcFunc->args())
    assert(ValueMap.count(&Arg) && "No mapping from source argument specified!");
#endif

  bool ModuleLevelChanges = Changes > CloneFunctionChangeType::LocalChangesOnly;

  // Copy attributes except those stored in AttributeList
  AttributeList NewAttrs = DestFunc->getAttributes();
  DestFunc->copyAttributesFrom(SrcFunc);
  DestFunc->setAttributes(NewAttrs);

  const RemapFlags FuncGlobalRefFlags =
      ModuleLevelChanges ? RF_None : RF_NoModuleLevelChanges;

  // Fix up personality function
  if (SrcFunc->hasPersonalityFn())
    DestFunc->setPersonalityFn(MapValue(SrcFunc->getPersonalityFn(), ValueMap,
                                        FuncGlobalRefFlags, TypeMapper,
                                        Materializer));

  if (SrcFunc->hasPrefixData()) {
    DestFunc->setPrefixData(MapValue(SrcFunc->getPrefixData(), ValueMap,
                                     FuncGlobalRefFlags, TypeMapper,
                                     Materializer));
  }

  if (SrcFunc->hasPrologueData()) {
    DestFunc->setPrologueData(MapValue(SrcFunc->getPrologueData(), ValueMap,
                                       FuncGlobalRefFlags, TypeMapper,
                                       Materializer));
  }

  SmallVector<AttributeSet, 4> NewArgAttrs(DestFunc->arg_size());
  AttributeList OldAttrs = SrcFunc->getAttributes();

  // Clone argument attributes present in the VMap
  for (const Argument &OldArg : SrcFunc->args()) {
    if (Argument *NewArg = dyn_cast<Argument>(ValueMap[&OldArg])) {
      NewArgAttrs[NewArg->getArgNo()] =
          OldAttrs.getParamAttrs(OldArg.getArgNo());
    }
  }

  DestFunc->setAttributes(
      AttributeList::get(DestFunc->getContext(), OldAttrs.getFnAttrs(),
                         OldAttrs.getRetAttrs(), NewArgAttrs));

  // If source function is just a declaration, nothing more to do
  if (SrcFunc->isDeclaration())
    return;

  std::optional<DebugInfoFinder> DIFinder;
  DISubprogram *SPClonedWithinModule = nullptr;

  if (Changes < CloneFunctionChangeType::DifferentModule) {
    assert((DestFunc->getParent() == nullptr ||
            DestFunc->getParent() == SrcFunc->getParent()) &&
           "Expected DestFunc to have the same parent, or no parent");

    DIFinder.emplace();
    SPClonedWithinModule = SrcFunc->getSubprogram();
    if (SPClonedWithinModule)
      DIFinder->processSubprogram(SPClonedWithinModule);
  } else {
    assert((DestFunc->getParent() == nullptr ||
            DestFunc->getParent() != SrcFunc->getParent()) &&
           "Expected DestFunc to have different parents, or no parent");

    if (Changes == CloneFunctionChangeType::DifferentModule) {
      assert(DestFunc->getParent() &&
             "Need parent of new function to maintain debug info invariants");
      DIFinder.emplace();
    }
  }

  // Clone all basic blocks
  for (const BasicBlock &BB : *SrcFunc) {
    BasicBlock *CBB = CloneBasicBlock(&BB, ValueMap, Suffix, DestFunc, CodeInfo,
                                      DIFinder ? &*DIFinder : nullptr);
    ValueMap[&BB] = CBB;

    if (BB.hasAddressTaken()) {
      Constant *OldBBAddr = BlockAddress::get(const_cast<Function *>(SrcFunc),
                                              const_cast<BasicBlock *>(&BB));
      ValueMap[OldBBAddr] = BlockAddress::get(DestFunc, CBB);
    }

    if (ReturnInst *RI = dyn_cast<ReturnInst>(CBB->getTerminator()))
      ReturnList.push_back(RI);
  }

  if (Changes < CloneFunctionChangeType::DifferentModule &&
      DIFinder->subprogram_count() > 0) {
    ModuleLevelChanges = true;
    auto mapToSelfIfNew = [&ValueMap](MDNode *N) {
      (void)ValueMap.MD().try_emplace(N, N);
    };

    SmallPtrSet<const DISubprogram *, 16> MappedToSelfSPs;
    for (DISubprogram *ISP : DIFinder->subprograms()) {
      if (ISP != SPClonedWithinModule) {
        mapToSelfIfNew(ISP);
        MappedToSelfSPs.insert(ISP);
      }
    }

    for (DIScope *S : DIFinder->scopes()) {
      auto *LScope = dyn_cast<DILocalScope>(S);
      if (LScope && MappedToSelfSPs.count(LScope->getSubprogram()))
        mapToSelfIfNew(S);
    }

    for (DICompileUnit *CU : DIFinder->compile_units())
      mapToSelfIfNew(CU);

    for (DIType *Type : DIFinder->types())
      mapToSelfIfNew(Type);
  } else {
    assert(!SPClonedWithinModule &&
           "Subprogram should be in DIFinder->subprogram_count()...");
  }

  const auto RemapFlag = ModuleLevelChanges ? RF_None : RF_NoModuleLevelChanges;

  // Duplicate metadata attached to cloned function
  SmallVector<std::pair<unsigned, MDNode *>, 1> MDs;
  SrcFunc->getAllMetadata(MDs);
  for (auto MD : MDs) {
    DestFunc->addMetadata(MD.first, *MapMetadata(MD.second, ValueMap, RemapFlag,
                                                 TypeMapper, Materializer));
  }

  // Fix up operand references in cloned instructions
  for (Function::iterator
           BB = cast<BasicBlock>(ValueMap[&SrcFunc->front()])->getIterator(),
           BE = DestFunc->end();
       BB != BE; ++BB)
    for (Instruction &II : *BB) {
      RemapInstruction(&II, ValueMap, RemapFlag, TypeMapper, Materializer);
      RemapDPValueRange(II.getModule(), II.getDbgValueRange(), ValueMap, RemapFlag,
                        TypeMapper, Materializer);
    }

  if (Changes != CloneFunctionChangeType::DifferentModule)
    return;

  // Update !llvm.dbg.cu for DifferentModule changes
  auto *DestModule = DestFunc->getParent();
  auto *NMD = DestModule->getOrInsertNamedMetadata("llvm.dbg.cu");
  SmallPtrSet<const void *, 8> Visited;
  for (auto *Operand : NMD->operands())
    Visited.insert(Operand);

  for (auto *Unit : DIFinder->compile_units()) {
    MDNode *MappedUnit =
        MapMetadata(Unit, ValueMap, RF_None, TypeMapper, Materializer);
    if (Visited.insert(MappedUnit).second)
      NMD->addOperand(MappedUnit);
  }
}

Function *llvm::CloneFunction(Function *F, ValueToValueMapTy &VMap,
                              ClonedCodeInfo *CodeInfo) {
  std::vector<Type *> ArgTypes;

  for (const Argument &I : F->args())
    if (VMap.count(&I) == 0)
      ArgTypes.push_back(I.getType());

  FunctionType *FTy =
      FunctionType::get(F->getFunctionType()->getReturnType(), ArgTypes,
                        F->getFunctionType()->isVarArg());

  Function *NewF = Function::Create(FTy, F->getLinkage(), F->getAddressSpace(),
                                    F->getName(), F->getParent());
  NewF->setIsNewDbgInfoFormat(F->IsNewDbgInfoFormat);

  Function::arg_iterator DestI = NewF->arg_begin();
  for (const Argument &I : F->args())
    if (VMap.count(&I) == 0) {
      DestI->setName(I.getName());
      VMap[&I] = &*DestI++;
    }

  SmallVector<ReturnInst *, 8> Returns;
  CloneFunctionInto(NewF, F, VMap, CloneFunctionChangeType::LocalChangesOnly,
                    Returns, "", CodeInfo);
  return NewF;
}

namespace {
struct PruningFunctionCloner {
  Function *DestFunc;
  const Function *SrcFunc;
  ValueToValueMapTy &ValueMap;
  bool ModuleLevelChanges;
  const char *Suffix;
  ClonedCodeInfo *CodeInfo;
  bool HostFuncIsStrictFP;

  Instruction *cloneInstruction(BasicBlock::const_iterator II);
public:
  PruningFunctionCloner(Function *newFunc, const Function *oldFunc,
                        ValueToValueMapTy &valueMap, bool moduleLevelChanges,
                        const char *nameSuffix, ClonedCodeInfo *codeInfo)
      : DestFunc(newFunc), SrcFunc(oldFunc), ValueMap(valueMap),
        ModuleLevelChanges(moduleLevelChanges), Suffix(nameSuffix),
        CodeInfo(codeInfo) {
    HostFuncIsStrictFP =
        newFunc->getAttributes().hasFnAttr(Attribute::StrictFP);
  }

  void CloneBlock(const BasicBlock *BB, BasicBlock::const_iterator StartingInst,
                  std::vector<const BasicBlock *> &ToClone);
};
} // namespace

static bool hasRoundingModeOperand(Intrinsic::ID CIID) {
  switch (CIID) {
#define INSTRUCTION(NAME, NARG, ROUND_MODE, INTRINSIC)                         \
  case Intrinsic::INTRINSIC:                                                   \
    return ROUND_MODE == 1;
#define FUNCTION INSTRUCTION
#include "llvm/IR/ConstrainedOps.def"
  default:
    llvm_unreachable("Unexpected constrained intrinsic id");
  }
}

Instruction *
PruningFunctionCloner::cloneInstruction(BasicBlock::const_iterator II) {
  const Instruction &OldInst = *II;
  Instruction *NewInst = nullptr;

  if (HostFuncIsStrictFP) {
    Intrinsic::ID CIID = getConstrainedIntrinsicID(OldInst);
    if (CIID != Intrinsic::not_intrinsic) {
      SmallVector<Type *, 2> TParams;
      SmallVector<Intrinsic::IITDescriptor, 8> Descriptor;
      getIntrinsicInfoTableEntries(CIID, Descriptor);

      for (unsigned I = 0, E = Descriptor.size(); I != E; ++I) {
        Intrinsic::IITDescriptor Operand = Descriptor[I];
        switch (Operand.Kind) {
        case Intrinsic::IITDescriptor::Argument:
          if (Operand.getArgumentKind() !=
              Intrinsic::IITDescriptor::AK_MatchType) {
            if (I == 0)
              TParams.push_back(OldInst.getType());
            else
              TParams.push_back(OldInst.getOperand(I - 1)->getType());
          }
          break;
        case Intrinsic::IITDescriptor::SameVecWidthArgument:
          ++I;
          break;
        default:
          break;
        }
      }

      LLVMContext &Ctx = DestFunc->getContext();
      Function *IFn =
          Intrinsic::getDeclaration(DestFunc->getParent(), CIID, TParams);
      SmallVector<Value *, 4> Args;
      unsigned NumOperands = OldInst.getNumOperands();
      if (isa<CallInst>(OldInst))
        --NumOperands;
      for (unsigned I = 0; I < NumOperands; ++I) {
        Value *Op = OldInst.getOperand(I);
        Args.push_back(Op);
      }

      if (const auto *CmpI = dyn_cast<FCmpInst>(&OldInst)) {
        FCmpInst::Predicate Pred = CmpI->getPredicate();
        StringRef PredName = FCmpInst::getPredicateName(Pred);
        Args.push_back(MetadataAsValue::get(Ctx, MDString::get(Ctx, PredName)));
      }

      if (hasRoundingModeOperand(CIID))
        Args.push_back(
            MetadataAsValue::get(Ctx, MDString::get(Ctx, "round.tonearest")));
      Args.push_back(
          MetadataAsValue::get(Ctx, MDString::get(Ctx, "fpexcept.ignore")));

      NewInst = CallInst::Create(IFn, Args, OldInst.getName() + ".strict");
    }
  }

  if (!NewInst)
    NewInst = II->clone();

  return NewInst;
}

void PruningFunctionCloner::CloneBlock(
    const BasicBlock *BB, BasicBlock::const_iterator StartingInst,
    std::vector<const BasicBlock *> &ToClone) {
  WeakTrackingVH &BBEntry = ValueMap[BB];

  if (BBEntry)
    return;

  BasicBlock *NewBB;
  Twine NewName(BB->hasName() ? Twine(BB->getName()) + Suffix : "");
  BBEntry = NewBB = BasicBlock::Create(BB->getContext(), NewName, DestFunc);
  NewBB->IsNewDbgInfoFormat = BB->IsNewDbgInfoFormat;

  if (BB->hasAddressTaken()) {
    Constant *OldBBAddr = BlockAddress::get(const_cast<Function *>(SrcFunc),
                                            const_cast<BasicBlock *>(BB));
    ValueMap[OldBBAddr] = BlockAddress::get(DestFunc, NewBB);
  }

  bool hasCalls = false, hasDynamicAllocas = false, hasStaticAllocas = false;
  bool hasMemProfMetadata = false;

  BasicBlock::const_iterator DbgCursor = StartingInst;
  auto CloneDbgRecordsToHere =
      [NewBB, &DbgCursor](Instruction *NewInst, BasicBlock::const_iterator II) {
        if (!NewBB->IsNewDbgInfoFormat)
          return;
        for (; DbgCursor != II; ++DbgCursor)
          NewInst->cloneDebugInfoFrom(&*DbgCursor, std::nullopt, false);
        NewInst->cloneDebugInfoFrom(&*II);
        DbgCursor = std::next(II);
      };

  for (BasicBlock::const_iterator II = StartingInst, IE = --BB->end(); II != IE;
       ++II) {
    Instruction *NewInst = cloneInstruction(II);
    NewInst->insertInto(NewBB, NewBB->end());

    if (HostFuncIsStrictFP) {
      if (auto *Call = dyn_cast<CallInst>(NewInst))
        Call->addFnAttr(Attribute::StrictFP);
    }

    if (!isa<PHINode>(NewInst) && !isa<DbgVariableIntrinsic>(NewInst)) {
      RemapInstruction(NewInst, ValueMap,
                       ModuleLevelChanges ? RF_None : RF_NoModuleLevelChanges);

      if (Value *V =
              simplifyInstruction(NewInst, BB->getModule()->getDataLayout())) {
        if (DestFunc != SrcFunc)
          if (Value *MappedV = ValueMap.lookup(V))
            V = MappedV;

        if (!NewInst->mayHaveSideEffects()) {
          ValueMap[&*II] = V;
          NewInst->eraseFromParent();
          continue;
        }
      }
    }

    if (II->hasName())
      NewInst->setName(II->getName() + Suffix);

    ValueMap[&*II] = NewInst;

    if (isa<CallInst>(II) && !II->isDebugOrPseudoInst()) {
      hasCalls = true;
      hasMemProfMetadata |= II->hasMetadata(LLVMContext::MD_memprof);
    }

    CloneDbgRecordsToHere(NewInst, II);

    if (CodeInfo) {
      CodeInfo->OrigVMap[&*II] = NewInst;
      if (auto *CB = dyn_cast<CallBase>(&*II))
        if (CB->hasOperandBundles())
          CodeInfo->OperandBundleCallSites.push_back(NewInst);
    }

    if (const AllocaInst *AI = dyn_cast<AllocaInst>(II)) {
      if (isa<ConstantInt>(AI->getArraySize()))
        hasStaticAllocas = true;
      else
        hasDynamicAllocas = true;
    }
  }

  const Instruction *OldTI = BB->getTerminator();
  bool TerminatorDone = false;

  if (const BranchInst *BI = dyn_cast<BranchInst>(OldTI)) {
    if (BI->isConditional()) {
      ConstantInt *Cond = dyn_cast<ConstantInt>(BI->getCondition());
      if (!Cond) {
        Value *V = ValueMap.lookup(BI->getCondition());
        Cond = dyn_cast_or_null<ConstantInt>(V);
      }
      if (Cond) {
        BasicBlock *Dest = BI->getSuccessor(!Cond->getZExtValue());
        ValueMap[OldTI] = BranchInst::Create(Dest, NewBB);
        ToClone.push_back(Dest);
        TerminatorDone = true;
      }
    }
  } else if (const SwitchInst *SI = dyn_cast<SwitchInst>(OldTI)) {
    ConstantInt *Cond = dyn_cast<ConstantInt>(SI->getCondition());
    if (!Cond) {
      Value *V = ValueMap.lookup(SI->getCondition());
      Cond = dyn_cast_or_null<ConstantInt>(V);
    }
    if (Cond) {
      SwitchInst::ConstCaseHandle Case = *SI->findCaseValue(Cond);
      BasicBlock *Dest = const_cast<BasicBlock *>(Case.getCaseSuccessor());
      ValueMap[OldTI] = BranchInst::Create(Dest, NewBB);
      ToClone.push_back(Dest);
      TerminatorDone = true;
    }
  }

  if (!TerminatorDone) {
    Instruction *NewInst = OldTI->clone();
    if (OldTI->hasName())
      NewInst->setName(OldTI->getName() + Suffix);
    NewInst->insertInto(NewBB, NewBB->end());
    CloneDbgRecordsToHere(NewInst, OldTI->getIterator());
    ValueMap[OldTI] = NewInst;

    if (CodeInfo) {
      CodeInfo->OrigVMap[OldTI] = NewInst;
      if (auto *CB = dyn_cast<CallBase>(OldTI))
        if (CB->hasOperandBundles())
          CodeInfo->OperandBundleCallSites.push_back(NewInst);
    }
    append_range(ToClone, successors(BB->getTerminator()));
  } else {
    Instruction *NewInst = NewBB->getTerminator();
    assert(NewInst);
    CloneDbgRecordsToHere(NewInst, OldTI->getIterator());
  }

  if (CodeInfo) {
    CodeInfo->ContainsCalls |= hasCalls;
    CodeInfo->ContainsMemProfMetadata |= hasMemProfMetadata;
    CodeInfo->ContainsDynamicAllocas |= hasDynamicAllocas;
    CodeInfo->ContainsDynamicAllocas |=
        hasStaticAllocas && BB != &BB->getParent()->front();
  }
}

void llvm::CloneAndPruneIntoFromInst(Function *DestFunc, const Function *SrcFunc,
                                     const Instruction *StartingInst,
                                     ValueToValueMapTy &ValueMap,
                                     bool ModuleLevelChanges,
                                     SmallVectorImpl<ReturnInst *> &ReturnList,
                                     const char *Suffix,
                                     ClonedCodeInfo *CodeInfo) {
  assert(Suffix && "Suffix cannot be null!");
  ValueMapTypeRemapper *TypeMapper = nullptr;
  ValueMaterializer *Materializer = nullptr;

#ifndef NDEBUG
  if (!StartingInst)
    for (const Argument &II : SrcFunc->args())
      assert(ValueMap.count(&II) && "No mapping from source argument specified!");
#endif

  PruningFunctionCloner PFC(DestFunc, SrcFunc, ValueMap, ModuleLevelChanges,
                            Suffix, CodeInfo);
  const BasicBlock *StartingBB;
  if (StartingInst)
    StartingBB = StartingInst->getParent();
  else {
    StartingBB = &SrcFunc->getEntryBlock();
    StartingInst = &StartingBB->front();
  }

  SmallVector<const DbgVariableIntrinsic *, 8> DbgIntrinsics;
  for (const auto &BB : *SrcFunc) {
    for (const auto &I : BB) {
      if (const auto *DVI = dyn_cast<DbgVariableIntrinsic>(&I))
        DbgIntrinsics.push_back(DVI);
    }
  }

  std::vector<const BasicBlock *> CloneWorklist;
  PFC.CloneBlock(StartingBB, StartingInst->getIterator(), CloneWorklist);
  while (!CloneWorklist.empty()) {
    const BasicBlock *BB = CloneWorklist.back();
    CloneWorklist.pop_back();
    PFC.CloneBlock(BB, BB->begin(), CloneWorklist);
  }

  SmallVector<const PHINode *, 16> PHIToResolve;
  for (const BasicBlock &BI : *SrcFunc) {
    Value *V = ValueMap.lookup(&BI);
    BasicBlock *NewBB = cast_or_null<BasicBlock>(V);
    if (!NewBB)
      continue;

    NewBB->moveBefore(DestFunc->end());

    for (const PHINode &PN : BI.phis()) {
      if (isa<PHINode>(ValueMap[&PN]))
        PHIToResolve.push_back(&PN);
      else
        break;
    }

    RemapInstruction(NewBB->getTerminator(), ValueMap,
                     ModuleLevelChanges ? RF_None : RF_NoModuleLevelChanges,
                     TypeMapper, Materializer);
  }

  for (unsigned phino = 0, e = PHIToResolve.size(); phino != e;) {
    const PHINode *OPN = PHIToResolve[phino];
    unsigned NumPreds = OPN->getNumIncomingValues();
    const BasicBlock *OldBB = OPN->getParent();
    BasicBlock *NewBB = cast<BasicBlock>(ValueMap[OldBB]);

    for (; phino != PHIToResolve.size() &&
           PHIToResolve[phino]->getParent() == OldBB;
         ++phino) {
      OPN = PHIToResolve[phino];
      PHINode *PN = cast<PHINode>(ValueMap[OPN]);
      for (unsigned pred = 0, e = NumPreds; pred != e; ++pred) {
        Value *V = ValueMap.lookup(PN->getIncomingBlock(pred));
        if (BasicBlock *MappedBlock = cast_or_null<BasicBlock>(V)) {
          Value *InVal =
              MapValue(PN->getIncomingValue(pred), ValueMap,
                       ModuleLevelChanges ? RF_None : RF_NoModuleLevelChanges);
          assert(InVal && "Unknown input value?");
          PN->setIncomingValue(pred, InVal);
          PN->setIncomingBlock(pred, MappedBlock);
        } else {
          PN->removeIncomingValue(pred, false);
          --pred;
          --e;
        }
      }
    }

    PHINode *PN = cast<PHINode>(NewBB->begin());
    NumPreds = pred_size(NewBB);
    if (NumPreds != PN->getNumIncomingValues()) {
      assert(NumPreds < PN->getNumIncomingValues());
      std::map<BasicBlock *, unsigned> PredCount;
      for (BasicBlock *Pred : predecessors(NewBB))
        --PredCount[Pred];
      for (unsigned i = 0, e = PN->getNumIncomingValues(); i != e; ++i)
        ++PredCount[PN->getIncomingBlock(i)];

      BasicBlock::iterator I = NewBB->begin();
      for (; (PN = dyn_cast<PHINode>(I)); ++I) {
        for (const auto &PCI : PredCount) {
          BasicBlock *Pred = PCI.first;
          for (unsigned NumToRemove = PCI.second; NumToRemove; --NumToRemove)
            PN->removeIncomingValue(Pred, false);
        }
      }
    }

    PN = cast<PHINode>(NewBB->begin());
    if (PN->getNumIncomingValues() == 0) {
      BasicBlock::iterator I = NewBB->begin();
      BasicBlock::const_iterator OldI = OldBB->begin();
      while ((PN = dyn_cast<PHINode>(I++))) {
        Value *NV = PoisonValue::get(PN->getType());
        PN->replaceAllUsesWith(NV);
        assert(ValueMap[&*OldI] == PN && "VMap mismatch");
        ValueMap[&*OldI] = NV;
        PN->eraseFromParent();
        ++OldI;
      }
    }
  }

  const DataLayout &DL = DestFunc->getParent()->getDataLayout();
  SmallSetVector<const Value *, 8> Worklist;
  for (unsigned Idx = 0, Size = PHIToResolve.size(); Idx != Size; ++Idx)
    if (isa<PHINode>(ValueMap[PHIToResolve[Idx]]))
      Worklist.insert(PHIToResolve[Idx]);

  for (unsigned Idx = 0; Idx != Worklist.size(); ++Idx) {
    const Value *OrigV = Worklist[Idx];
    auto *I = dyn_cast_or_null<Instruction>(ValueMap.lookup(OrigV));
    if (!I)
      continue;

    CallBase *CB = dyn_cast<CallBase>(I);
    if (CB && CB->getCalledFunction() &&
        !CB->getCalledFunction()->isIntrinsic())
      continue;

    Value *SimpleV = simplifyInstruction(I, DL);
    if (!SimpleV)
      continue;

    for (const User *U : OrigV->users())
      Worklist.insert(cast<Instruction>(U));

    I->replaceAllUsesWith(SimpleV);
    if (isInstructionTriviallyDead(I))
      I->eraseFromParent();
    else
      ValueMap[OrigV] = I;
  }

  for (const auto *DVI : DbgIntrinsics) {
    if (DbgVariableIntrinsic *NewDVI =
            cast_or_null<DbgVariableIntrinsic>(ValueMap.lookup(DVI)))
      RemapInstruction(NewDVI, ValueMap,
                       ModuleLevelChanges ? RF_None : RF_NoModuleLevelChanges,
                       TypeMapper, Materializer);
  }

  Function::iterator Begin = cast<BasicBlock>(ValueMap[StartingBB])->getIterator();
  for (BasicBlock &BB : make_range(Begin, DestFunc->end())) {
    for (Instruction &I : BB) {
      RemapDPValueRange(I.getModule(), I.getDbgValueRange(), ValueMap,
                        ModuleLevelChanges ? RF_None : RF_NoModuleLevelChanges,
                        TypeMapper, Materializer);
    }
  }

  for (BasicBlock &BB : make_range(Begin, DestFunc->end()))
    ConstantFoldTerminator(&BB);

  {
    SmallPtrSet<BasicBlock *, 16> ReachableBlocks;
    SmallVector<BasicBlock *, 16> Worklist;
    Worklist.push_back(&*Begin);
    while (!Worklist.empty()) {
      BasicBlock *BB = Worklist.pop_back_val();
      if (ReachableBlocks.insert(BB).second)
        append_range(Worklist, successors(BB));
    }

    SmallVector<BasicBlock *, 16> UnreachableBlocks;
    for (BasicBlock &BB : make_range(Begin, DestFunc->end()))
      if (!ReachableBlocks.contains(&BB))
        UnreachableBlocks.push_back(&BB);
    DeleteDeadBlocks(UnreachableBlocks);
  }

  Function::iterator I = Begin;
  while (I != DestFunc->end()) {
    BranchInst *BI = dyn_cast<BranchInst>(I->getTerminator());
    if (!BI || BI->isConditional()) {
      ++I;
      continue;
    }

    BasicBlock *Dest = BI->getSuccessor(0);
    if (!Dest->getSinglePredecessor()) {
      ++I;
      continue;
    }

    assert(!isa<PHINode>(Dest->begin()));
    BI->eraseFromParent();
    Dest->replaceAllUsesWith(&*I);
    I->splice(I->end(), Dest);
    Dest->eraseFromParent();
  }

  for (Function::iterator I = cast<BasicBlock>(ValueMap[StartingBB])->getIterator(),
                          E = DestFunc->end();
       I != E; ++I)
    if (ReturnInst *RI = dyn_cast<ReturnInst>(I->getTerminator()))
      ReturnList.push_back(RI);
}

void llvm::CloneAndPruneFunctionInto(
    Function *DestFunc, const Function *SrcFunc, ValueToValueMapTy &ValueMap,
    bool ModuleLevelChanges, SmallVectorImpl<ReturnInst *> &ReturnList,
    const char *Suffix, ClonedCodeInfo *CodeInfo) {
  CloneAndPruneIntoFromInst(DestFunc, SrcFunc, &SrcFunc->front().front(), ValueMap,
                            ModuleLevelChanges, ReturnList, Suffix, CodeInfo);
}

void llvm::remapInstructionsInBlocks(ArrayRef<BasicBlock *> Blocks,
                                     ValueToValueMapTy &VMap) {
  for (auto *BB : Blocks) {
    for (auto &Inst : *BB) {
      RemapDPValueRange(Inst.getModule(), Inst.getDbgValueRange(), VMap,
                        RF_NoModuleLevelChanges | RF_IgnoreMissingLocals);
      RemapInstruction(&Inst, VMap,
                       RF_NoModuleLevelChanges | RF_IgnoreMissingLocals);
    }
  }
}

Loop *llvm::cloneLoopWithPreheader(BasicBlock *Before, BasicBlock *LoopDomBB,
                                   Loop *OrigLoop, ValueToValueMapTy &VMap,
                                   const Twine &Suffix, LoopInfo *LI,
                                   DominatorTree *DT,
                                   SmallVectorImpl<BasicBlock *> &Blocks) {
  Function *F = OrigLoop->getHeader()->getParent();
  Loop *ParentLoop = OrigLoop->getParentLoop();
  DenseMap<Loop *, Loop *> LMap;
  Loop *NewLoop = LI->AllocateLoop();
  LMap[OrigLoop] = NewLoop;

  if (ParentLoop)
    ParentLoop->addChildLoop(NewLoop);
  else
    LI->addTopLevelLoop(NewLoop);

  BasicBlock *OrigPH = OrigLoop->getLoopPreheader();
  assert(OrigPH && "No preheader");
  BasicBlock *NewPH = CloneBasicBlock(OrigPH, VMap, Suffix, F);
  VMap[OrigPH] = NewPH;
  Blocks.push_back(NewPH);

  if (ParentLoop)
    ParentLoop->addBasicBlockToLoop(NewPH, *LI);

  DT->addNewBlock(NewPH, LoopDomBB);

  for (Loop *CurLoop : OrigLoop->getLoopsInPreorder()) {
    Loop *&NewLoop = LMap[CurLoop];
    if (!NewLoop) {
      NewLoop = LI->AllocateLoop();
      Loop *OrigParent = CurLoop->getParentLoop();
      assert(OrigParent && "Could not find the original parent loop");
      Loop *NewParentLoop = LMap[OrigParent];
      assert(NewParentLoop && "Could not find the new parent loop");
      NewParentLoop->addChildLoop(NewLoop);
    }
  }

  for (BasicBlock *BB : OrigLoop->getBlocks()) {
    Loop *CurLoop = LI->getLoopFor(BB);
    Loop *&NewLoop = LMap[CurLoop];
    assert(NewLoop && "Expecting new loop to be allocated");
    BasicBlock *NewBB = CloneBasicBlock(BB, VMap, Suffix, F);
    VMap[BB] = NewBB;
    NewLoop->addBasicBlockToLoop(NewBB, *LI);
    DT->addNewBlock(NewBB, NewPH);
    Blocks.push_back(NewBB);
  }

  for (BasicBlock *BB : OrigLoop->getBlocks()) {
    Loop *CurLoop = LI->getLoopFor(BB);
    if (BB == CurLoop->getHeader())
      LMap[CurLoop]->moveToHeader(cast<BasicBlock>(VMap[BB]));

    BasicBlock *IDomBB = DT->getNode(BB)->getIDom()->getBlock();
    DT->changeImmediateDominator(cast<BasicBlock>(VMap[BB]),
                                 cast<BasicBlock>(VMap[IDomBB]));
  }

  F->splice(Before->getIterator(), F, NewPH->getIterator());
  F->splice(Before->getIterator(), F, NewLoop->getHeader()->getIterator(),
            F->end());
  return NewLoop;
}

BasicBlock *llvm::DuplicateInstructionsInSplitBetween(
    BasicBlock *BB, BasicBlock *PredBB, Instruction *StopAt,
    ValueToValueMapTy &ValueMapping, DomTreeUpdater &DTU) {
  assert(count(successors(PredBB), BB) == 1 &&
         "There must be a single edge between PredBB and BB!");

  BasicBlock::iterator BI = BB->begin();
  for (; PHINode *PN = dyn_cast<PHINode>(BI); ++BI)
    ValueMapping[PN] = PN->getIncomingValueForBlock(PredBB);

  BasicBlock *NewBB = SplitEdge(PredBB, BB);
  NewBB->setName(PredBB->getName() + ".split");
  Instruction *NewTerm = NewBB->getTerminator();

  DTU.applyUpdates({{DominatorTree::Delete, PredBB, BB},
                    {DominatorTree::Insert, PredBB, NewBB},
