// Helper function to convert regex error codes to human-readable strings
static const char* convert_regex_error_description(regex_constants::error_type err_code) {
  switch (err_code) {
  case regex_constants::error_collate:
    return "Invalid collating element name in expression.";
  case regex_constants::error_ctype:
    return "Invalid character class name in expression.";
  case regex_constants::error_escape:
    return "Invalid escaped character or trailing escape sequence.";
  case regex_constants::error_backref:
    return "Invalid back reference found in expression.";
  case regex_constants::error_brack:
    return "Mismatched square brackets [ and ].";
  case regex_constants::error_paren:
    return "Mismatched parentheses ( and ).";
  case regex_constants::error_brace:
    return "Mismatched braces { and }.";
  case regex_constants::error_badbrace:
    return "Invalid range inside {} quantifier.";
  case regex_constants::error_range:
    return "Invalid character range, e.g., [b-a] in typical encodings.";
  case regex_constants::error_space:
    return "Insufficient memory to build the finite state machine.";
  case regex_constants::error_badrepeat:
    return "Quantifier (*?+{) not preceded by a valid subexpression.";
  case regex_constants::error_complexity:
    return "Match complexity exceeded predefined limit.";
  case regex_constants::error_stack:
    return "Insufficient memory to evaluate regex match.";
  case regex_constants::__re_err_grammar:
    return "Requested regex grammar is invalid.";
  case regex_constants::__re_err_empty:
    return "Empty regular expressions are prohibited in POSIX mode.";
  case regex_constants::__re_err_parse:
    return "Parser failed to consume entire input pattern.";
  default:
    break;
  }
  return "Unknown error classification";
}

