// Character class name mapping structure
struct char_class_entry {
  const char* name_;
  regex_traits<char>::char_class_type flags_;
};

// Standard character class definitions
const char_class_entry class_table[] = {
    {"alnum", ctype_base::alnum},
    {"alpha", ctype_base::alpha},
    {"blank", ctype_base::blank},
    {"cntrl", ctype_base::cntrl},
    {"d", ctype_base::digit},
    {"digit", ctype_base::digit},
    {"graph", ctype_base::graph},
    {"lower", ctype_base::lower},
    {"print", ctype_base::print},
    {"punct", ctype_base::punct},
    {"s", ctype_base::space},
    {"space", ctype_base::space},
    {"upper", ctype_base::upper},
    {"w", regex_traits<char>::__regex_word},
    {"xdigit", ctype_base::xdigit}};

// Comparator for binary search on collation entries
struct compare_by_name {
  bool operator()(const collation_entry& entry, const char* target) const {
    return std::strcmp(entry.name_, target) < 0;
  }
  bool operator()(const char_class_entry& entry, const char* target) const {
    return std::strcmp(entry.name_, target) < 0;
  }
};

} // namespace

// Convert collation name string to its corresponding character
std::string __get_collation_name(const char* name) {
  const collation_entry* iter = std::lower_bound(std::begin(collation_table), std::end(collation_table), name, compare_by_name());
  std::string result;
  if (iter != std::end(collation_table) && std::strcmp(name, iter->name_) == 0)
    result = static_cast<char>(iter->value_);
  return result;
}

// Resolve character class name to its bit mask representation
regex_traits<char>::char_class_type __get_classname(const char* name, bool case_insensitive) {
  const char_class_entry* iter = std::lower_bound(std::begin(class_table), std::end(class_table), name, compare_by_name());
  regex_traits<char>::char_class_type result_mask = 0;
  if (iter != std::end(class_table) && std::strcmp(name, iter->name_) == 0) {
    result_mask = iter->flags_;
    if (result_mask == regex_traits<char>::__regex_word)
      result_mask |= ctype_base::alnum | ctype_base::upper | ctype_base::lower;
    else if (case_insensitive) {
      if (result_mask & (ctype_base::lower | ctype_base::upper))
        result_mask |= ctype_base::alpha;
    }
  }
  return result_mask;
}

// Specialization for char type: match any character except newline
template <>
void __match_any_but_newline<char>::__exec(__state& state) const {
  if (state.__current_ != state.__last_) {
    switch (*state.__current_) {
    case '\r':
    case '\n':
      state.__do_   = __state::__reject;
      state.__node_ = nullptr;
      break;
    default:
      state.__do_ = __state::__accept_and_consume;
      ++state.__current_;
      state.__node_ = this->first();
      break;
    }
  } else {
    state.__do_   = __state::__reject;
    state.__node_ = nullptr;
  }
}

// Specialization for wchar_t type: match any wide character except line terminators
template <>
void __match_any_but_newline<wchar_t>::__exec(__state& state) const {
  if (state.__current_ != state.__last_) {
    switch (*state.__current_) {
    case '\r':
    case '\n':
    case 0x2028:
    case 0x2029:
      state.__do_   = __state::__reject;
      state.__node_ = nullptr;
      break;
    default:
      state.__do_ = __state::__accept_and_consume;
      ++state.__current_;
      state.__node_ = this->first();
      break;
    }
  } else {
    state.__do_   = __state::__reject;
    state.__node_ = nullptr;
  }
}

