using namespace std;

// Upper bound on number of nodes based on problem constraints
const int MAX_NODES = 1005;
int nodeCount, edgeCount;

// Adjacency representation using bitsets for fast operations
bitset<MAX_NODES> connections[MAX_NODES];

// Temporary storage during search
vector<int> currentSet;
// Best solution found so far
vector<int> bestSet;
// Size of the largest clique discovered
int maxCliqueSize = 0;

// Timing control
clock_t startTime;
const double MAX_TIME = 1.95; // Keep slightly under 2 seconds

// Reusable arrays for coloring heuristic
static int colorMark[MAX_NODES];
static int colorMarker = 0;

/**
 * Recursive backtracking to find maximum clique
 * candidates: bitset representing vertices eligible for inclusion
 */
void explore(bitset<MAX_NODES> candidates) {
    // Time budget check
    if ((double)(clock() - startTime) / CLOCKS_PER_SEC > MAX_TIME) return;

    int remaining = candidates.count();

    // Base case: no more candidates
    if (remaining == 0) {
        if (currentSet.size() > maxCliqueSize) {
            maxCliqueSize = currentSet.size();
            bestSet = currentSet;
        }
        return;
    }

    // Pruning: cannot improve upon best known solution
    if (currentSet.size() + remaining <= maxCliqueSize) return;

    // Convert bitset to list for processing
    vector<int> vertexList;
    vertexList.reserve(remaining);
    for (int v = 1; v <= nodeCount; ++v) {
        if (candidates[v]) vertexList.push_back(v);
    }

    // Greedy coloring heuristic for upper bound estimation
    vector<int> assignedColor(nodeCount + 1, 0);
    int usedColors = 0;

    for (int vertex : vertexList) {
        colorMarker++;
        // Mark colors used by adjacent already-colored vertices
        for (int neighbor : vertexList) {
            if (neighbor == vertex) continue;
            if (assignedColor[neighbor] != 0 && connections[vertex][neighbor]) {
                colorMark[assignedColor[neighbor]] = colorMarker;
            }
        }

        // Find first available color
        int c = 1;
        while (colorMark[c] == colorMarker) c++;
        assignedColor[vertex] = c;
        if (c > usedColors) usedColors = c;
    }

    // Coloring-based pruning
    if (currentSet.size() + usedColors <= maxCliqueSize) return;

    // Sort vertices by ascending color class
    sort(vertexList.begin(), vertexList.end(), [&](int a, int b) {
        return assignedColor[a] < assignedColor[b];
    });

    // Process vertices in reverse order (higher color classes first)
    for (int idx = (int)vertexList.size() - 1; idx >= 0; --idx) {
        // Periodic time check
        if ((double)(clock() - startTime) / CLOCKS_PER_SEC > MAX_TIME) return;

        int vertex = vertexList[idx];
        int colorClass = assignedColor[vertex];

        // Further pruning using color class information
        if (currentSet.size() + colorClass <= maxCliqueSize) break;

        // Include current vertex in candidate clique
        currentSet.push_back(vertex);

        // Exclude this vertex from future consideration in sibling branches
        candidates[vertex] = 0;

        // Recurse with neighbors only
        explore(candidates & connections[vertex]);

        // Backtrack
        currentSet.pop_back();
    }
}

int main() {
    // Input reading
    if (scanf("%d %d", &nodeCount, &edgeCount) != 2) return 0;

    for (int i = 0; i < edgeCount; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (u >= 1 && u <= nodeCount && v >= 1 && v <= nodeCount) {
            connections[u][v] = 1;
            connections[v][u] = 1;
        }
    }

    startTime = clock();

    // Initialize candidate set with all vertices
    bitset<MAX_NODES> initialCandidates;
    for (int i = 1; i <= nodeCount; ++i) initialCandidates.set(i);

    explore(initialCandidates);

    // Output result
    vector<int> outputFlag(nodeCount + 1, 0);
    for (int v : bestSet) {
        outputFlag[v] = 1;
    }

    for (int i = 1; i <= nodeCount; ++i) {
        printf("%d\n", outputFlag[i]);
    }

    return 0;
}

