// Creates a new integer buffer.
// The newly created buffer will have position 0, limit equal to its capacity, and an undefined mark.
// It will include a backing array with an array offset of zero.
//
// Parameters:
// size - The maximum number of integers the buffer can hold
IntBuffer::IntBuffer(unsigned int size) : Buffer(size)
{
	dataArray = new int[size];
	memset(dataArray, 0, sizeof(int) * size);
}

// Constructs a buffer using an existing array as its backing store.
// Parameters:
// size - The buffer's capacity
// externalArray - Pre-allocated integer array to use as backing storage
IntBuffer::IntBuffer(unsigned int size, int* externalArray) : Buffer(size)
{
	ownsBackingArray = false;
	dataArray = externalArray;
}

IntBuffer::~IntBuffer()
{
	if (ownsBackingArray)
		delete[] dataArray;
}

int* IntBuffer::getData()
{
	return dataArray;
}

// Reverses the buffer's state: sets the limit to the current position and resets position to zero.
// If a mark exists, it is cleared.
//
// Returns:
// Reference to this buffer instance
IntBuffer* IntBuffer::resetPosition()
{
	m_limit = m_position;
	m_position = 0;
	return this;
}

// Reads an integer value from a specific location in the buffer.
// Parameters:
// idx - Zero-based index of the element to retrieve
// Returns:
// The integer value stored at the specified index
int IntBuffer::getElement(unsigned int idx)
{
	assert(idx < m_limit);
	return dataArray[idx];
}

// Copies multiple integers into this buffer from a source array.
// If insufficient space remains (length > remaining()), no elements are copied and an error occurs.
// Otherwise, copies 'length' elements starting at 'startIdx' in the source array,
// placing them beginning at the current buffer position. Updates position accordingly.
//
// Parameters:
// src - Source array containing data to copy
// startIdx - First index in source array to read from
// count - Number of elements to transfer
// Returns:
// This buffer for method chaining
IntBuffer* IntBuffer::write(const intArray& source, unsigned int startIdx, unsigned int count)
{
	assert(startIdx + count <= source.length);
	std::copy(source.data + startIdx, source.data + startIdx + count, dataArray + m_position);
	m_position += count;
	return this;
}

IntBuffer* IntBuffer::write(const intArray& source)
{
	if (source.length > remaining())
		assert(false); // TODO 4J Stu - Implement proper exception handling

	std::copy(source.data, source.data + source.length, dataArray + m_position);
	m_position += source.length;
	return this;
}

// Stores a single integer at the current position and advances the position pointer.
//
// Parameters:
// value - Integer value to store
// Returns:
// This buffer for chaining operations
IntBuffer* IntBuffer::write(int value)
{
	assert(m_position < m_limit);
	dataArray[m_position++] = value;
	return this;
}

#include <vector>
#include <algorithm>

class Solution {
public:
    int findContentChildren(std::vector<int>& greedFactors, std::vector<int>& cookieSizes) {
        int numChildren = greedFactors.size();
        int numCookies = cookieSizes.size();

        std::sort(greedFactors.begin(), greedFactors.end());
        std::sort(cookieSizes.begin(), cookieSizes.end());

        int childIndex = 0;
        int cookieIndex = 0;
        int satisfiedCount = 0;

        while (childIndex < numChildren && cookieIndex < numCookies) {
            if (greedFactors[childIndex] <= cookieSizes[cookieIndex]) {
                satisfiedCount++;
                childIndex++;
                cookieIndex++;
            } else {
                cookieIndex++;
            }
        }

        return satisfiedCount;      
    }
};

