/*
  Determine the number of slices based on circle radius and pixel size.
  \param radius of circle
  \param pixelSize measurement unit
  \return count of divisions for circle approximation
  */
int calculateSegments(double r, double pSize = 1.0) {
  if (r < 0) return 2;
  double angleStep;
  double val = pSize * 0.5 / r;
  if (fabs(1.0 - val) <= 1)
    angleStep = acos(1.0 - val);
  else
    angleStep = M_PI_4;
  assert(angleStep != 0.0);
  int segmentCount = (int)(M_2PI / angleStep);
  return segmentCount != 0 ? segmentCount : 2;
}
}  // end of unnamed namespace
//-----------------------------------------------------------------------------
double tglGetPixelSize2() {
  double matrix[16];
  glMatrixMode(GL_MODELVIEW);
  glGetDoublev(GL_MODELVIEW_MATRIX, matrix);
  double determinant = fabs(matrix[0] * matrix[5] - matrix[1] * matrix[4]);
  if (determinant < TConsts::epsilon) determinant = TConsts::epsilon;
  return 1.0 / determinant;
}
//-----------------------------------------------------------------------------
TRectD tglGetBounds() {
  TAffine4 viewMatrix;
  TAffine4 projMatrix;
  glGetDoublev(GL_MODELVIEW_MATRIX, viewMatrix.a);
  glGetDoublev(GL_PROJECTION_MATRIX, projMatrix.a);
  return (projMatrix * viewMatrix).get2d().inv() * TRectD(-1.0, -1.0, 1.0, 1.0);
}
