void tglDrawSegment(const TPointD &pt1, const TPointD &pt2) {
  glBegin(GL_LINES);
  tglVertex(pt1);
  tglVertex(pt2);
  glEnd();
}
//-----------------------------------------------------------------------------
void tglDrawCircle(const TPointD &center, double radius) {
  if (radius <= 0) return;
  double pixelSize = sqrt( tglGetPixelSize2() );
  int segments = std::max(3, calculateSegments(radius, pixelSize));
  double step = M_2PI / (double)segments;
  double c = cos(step), s = sin(step);
  glPushMatrix();
  glTranslated(center.x, center.y, 0.0);
  glBegin(GL_LINE_STRIP);
  double x = radius, y = 0.0;
  glVertex2d(x, y);
  for(int i = segments - 1; i; --i) {
    double xx = x;
    x = c*xx - s*y;
    y = s*xx + c*y;
    glVertex2d(x, y);
  }
  glVertex2d(radius, 0.0);
  glEnd();
  glPopMatrix();
}
//-----------------------------------------------------------------------------
void tglDrawDisk(const TPointD &c, double r) {
  if (r <= 0) return;
  double pixelSize = 1;
  int segments     = 60;
  if (segments <= 0) segments = calculateSegments(r, pixelSize) >> 1;
  glPushMatrix();
  glTranslated(c.x, c.y, 0.0);
  GLUquadric *quadric = gluNewQuadric();
  gluDisk(quadric, 0, r, segments, 1);
  gluDeleteQuadric(quadric);
  glPopMatrix();
}
