#include <iostream>
#include <vector>
#include <string>
using namespace std;

// Recursive function to explore all valid paths in the grid
void explorePaths(vector<vector<int>> &grid, int row, int col, string currentPath, vector<string> &results) {
    // Check for out-of-bounds, blocked cells, or already visited cells
    if(row < 0 || col < 0 || row >= grid.size() || col >= grid[0].size() || grid[row][col] == 0 || grid[row][col] == -1) {
        return;
    }

    // If reached the bottom-right corner, add the path to results
    if(row == grid.size() - 1 && col == grid[0].size() - 1) {
        results.push_back(currentPath);
        return;
    }

    // Mark current cell as visited
    grid[row][col] = -1;

    // Explore all four directions: Down, Up, Left, Right
    explorePaths(grid, row + 1, col, currentPath + "D", results);
    explorePaths(grid, row - 1, col, currentPath + "U", results);
    explorePaths(grid, row, col - 1, currentPath + "L", results);
    explorePaths(grid, row, col + 1, currentPath + "R", results);

    // Backtrack: unmark the cell for other paths
    grid[row][col] = 1;
}

// Main function to find all paths from top-left to bottom-right
vector<string> getAllPaths(vector<vector<int>> &grid) {
    vector<string> paths;
    string route = "";
    explorePaths(grid, 0, 0, route, paths);
    return paths;
}

int main() {
    // Example grid where 1 represents open path and 0 represents obstacle
    vector<vector<int>> grid = {{1, 0, 0, 0}, {1, 1, 0, 1}, {1, 1, 0, 0}, {0, 1, 1, 1}};

    vector<string> resultPaths = getAllPaths(grid);
    for (const auto& path : resultPaths) {
        cout << path << endl;
    }
    return 0;
}

