// Destructor: Clean up OpenGL buffer
IndexedPointCloudBuffer::~IndexedPointCloudBuffer() {
  if (element_buffer) {
    glDeleteBuffers(1, &element_buffer);
  }
}

// Render the indexed point cloud using the provided shader
void IndexedPointCloudBuffer::render(glk::GLSLShader& shader) const {
  cloud_buffer->bind(shader);
  glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, element_buffer);
  glDrawElements(GL_POINTS, index_count, GL_UNSIGNED_INT, 0);
  glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, 0);
  cloud_buffer->unbind(shader);
}

