/// A placeholder module pass designed to act as a synchronization point in the pass pipeline.
///
/// Since there's no built-in way to terminate a CGSCC pass manager once it begins,
/// extension points that rely on non-module passes can suffer from ambiguous,
/// non-deterministic ordering. This pass serves as a clear demarcation.
class PipelineBarrier : public ModulePass {
public:
  static char ID; // Unique identifier for this pass.
  PipelineBarrier() : ModulePass(ID) {
    initializePipelineBarrierPass(*PassRegistry::getPassRegistry());
  }

  bool runOnModule(Module &mod) override { 
    return false; 
  }
};

}

ModulePass *llvm::createPipelineBarrierPass() { 
  return new PipelineBarrier(); 
}

