// Maximum combined length for chat message components
const unsigned int ChatPacket::MAX_LENGTH =
    SharedConstants::maxChatLength + Player::MAX_NAME_LENGTH + 3;

ChatPacket::ChatPacket() { 
    m_messageType = e_ChatCustom; 
}

// Constructor for legacy chat packets: accepts primary message, type, custom data, and optional extra message
ChatPacket::ChatPacket(
    const std::wstring& msg,
    EChatPacketMessage  pktType /*= e_ChatCustom*/,
    int                 extraData /*= -1*/,
    const std::wstring& extraMsg /*= L""*/
) {
    m_messageType = pktType;
    if (extraData != -1) m_intArgs.push_back(extraData);
    if (msg != L"" || extraMsg != L"")
        m_stringArgs.push_back(msg);
    if (extraMsg != L"") m_stringArgs.push_back(extraMsg);
}

// Deserialize chat packet from stream (may throw IOException)
void ChatPacket::read(DataInputStream* dis) {
    m_messageType = static_cast<EChatPacketMessage>(dis->readShort());
    short packedCounts = dis->readShort();
    int   strCount  = (packedCounts >> 4) & 0xF;
    int   intCount  = (packedCounts >> 0) & 0xF;

    for (int idx = 0; idx < strCount; ++idx) {
        m_stringArgs.push_back(readUtf(dis, MAX_LENGTH));
    }
    for (int idx = 0; idx < intCount; ++idx) {
        m_intArgs.push_back(dis->readInt());
    }
}

// Serialize chat packet to stream (may throw IOException)
void ChatPacket::write(DataOutputStream* dos) {
    dos->writeShort(m_messageType);
    short packedCounts  = 0;
    packedCounts       |= (static_cast<short>(m_stringArgs.size()) & 0xF) << 4;
    packedCounts       |= (static_cast<short>(m_intArgs.size()) & 0xF) << 0;
    dos->writeShort(packedCounts);

    for (int idx = 0; idx < m_stringArgs.size(); ++idx) {
        writeUtf(m_stringArgs[idx], dos);
    }
    for (int idx = 0; idx < m_intArgs.size(); ++idx) {
        dos->writeInt(m_intArgs[idx]);
    }
}

// Dispatch chat packet to appropriate handler
void ChatPacket::handle(PacketListener* listener) {
    listener->handleChat(shared_from_this());
}

// Compute approximate serialized size of the packet
int ChatPacket::getEstimatedSize() {
    int stringBytes = 0;
    for (int idx = 0; idx < m_stringArgs.size(); ++idx) {
        stringBytes += m_stringArgs[idx].length();
    }
    return sizeof(EChatPacketMessage) +      // message type field
           sizeof(short) +                   // packed argument counts
           stringBytes +                     // encoded string arguments
           (m_intArgs.size() * sizeof(int)); // integer arguments
}

