class tst_VersionNegotiation : public QObject
{
    Q_OBJECT

private slots:
    void initialize();
    void teardown();
    // Protocol version negotiation tests
    void testStandardVersionNegotiation();
    void testExplicitVersionNegotiation_data();
    void testExplicitVersionNegotiation();
    void testFallbackOnUnsupportedVersion();

private:
    QMcpServer *serverInstance = nullptr;
    QMcpClient *clientInstance = nullptr;
    QTemporaryFile tempFile;

    // Helper functions
    QtMcp::ProtocolVersion establishConnection();
    QMcpServerSession* retrieveActiveSession();
};

void tst_VersionNegotiation::initialize()
{
    // Initialize MCP server using SSE transport
    serverInstance = new QMcpServer("sse", this);
    // Define supported protocol versions
    serverInstance->setSupportedProtocolVersions({
        QtMcp::ProtocolVersion::v2025_03_26,
        QtMcp::ProtocolVersion::v2024_11_05
    });
    serverInstance->setProtocolVersion(QtMcp::ProtocolVersion::v2025_03_26); // Default to newest
    // Bind server to local address
    serverInstance->start("127.0.0.1:20202");

    // Initialize MCP client using SSE transport
    clientInstance = new QMcpClient("sse", this);
    // Connect client to server endpoint
    clientInstance->start("http://localhost:20202");
}

void tst_VersionNegotiation::teardown()
{
    if (clientInstance) {
        delete clientInstance;
        clientInstance = nullptr;
    }
    if (serverInstance) {
        delete serverInstance;
        serverInstance = nullptr;
    }
}

QtMcp::ProtocolVersion tst_VersionNegotiation::establishConnection()
{
    QSignalSpy startupSpy(clientInstance, &QMcpClient::started);
    if (!startupSpy.wait(8000))
        return QtMcp::ProtocolVersion::Latest;

    QMcpInitializeRequest initReq;
    auto params = initReq.params();
    // Set protocol version in request parameters (enum → string conversion)
    params.setProtocolVersion(QtMcp::protocolVersionToString(clientInstance->protocolVersion()));
    initReq.setParams(params);

    QEventLoop loop;
    QtMcp::ProtocolVersion negotiatedVersion;

    clientInstance->request(initReq, [&negotiatedVersion, &loop](const QMcpInitializeResult &res, const QMcpJSONRPCErrorError *err) {
        if (err) {
            qDebug() << "Init failed:" << err->message();
        } else {
            negotiatedVersion = res.protocolVersion();
        }
        loop.quit();
    });

    QTimer::singleShot(8000, &loop, &QEventLoop::quit);
    loop.exec();
    return negotiatedVersion;
}

QMcpServerSession* tst_VersionNegotiation::retrieveActiveSession()
{
    const auto sessions = serverInstance->sessions();
    return sessions.isEmpty() ? nullptr : sessions.first();
}

void tst_VersionNegotiation::testStandardVersionNegotiation()
{
    const auto clientVer = establishConnection();
    QMcpServerSession *session = retrieveActiveSession();
    QVERIFY(session);
    QCOMPARE(session->protocolVersion(), clientVer);
}

void tst_VersionNegotiation::testExplicitVersionNegotiation_data()
{
    QTest::addColumn<QtMcp::ProtocolVersion>("requested");
    QTest::addColumn<QtMcp::ProtocolVersion>("expected");
    QTest::newRow("Newest requested") << QtMcp::ProtocolVersion::v2025_03_26 << QtMcp::ProtocolVersion::v2025_03_26;
    QTest::newRow("Legacy requested") << QtMcp::ProtocolVersion::v2024_11_05 << QtMcp::ProtocolVersion::v2024_11_05;
}

void tst_VersionNegotiation::testExplicitVersionNegotiation()
{
    QFETCH(QtMcp::ProtocolVersion, requested);
    QFETCH(QtMcp::ProtocolVersion, expected);

    clientInstance->setProtocolVersion(requested);
    const auto actualVer = establishConnection();
    QCOMPARE(actualVer, expected);

    QMcpServerSession *session = retrieveActiveSession();
    QVERIFY(session);
    QCOMPARE(session->protocolVersion(), expected);
}

void tst_VersionNegotiation::testFallbackOnUnsupportedVersion()
{
    // Attempt to use an unsupported version string
    clientInstance->setProtocolVersion(QtMcp::stringToProtocolVersion("9999-99-99"));
    const auto resultVer = establishConnection();

    // Server should fall back to highest supported version
    QCOMPARE(resultVer, QtMcp::ProtocolVersion::v2025_03_26);

    QMcpServerSession *session = retrieveActiveSession();
    QVERIFY(session);
    QCOMPARE(session->protocolVersion(), resultVer);
}

QTEST_MAIN(tst_VersionNegotiation)
