#include "test.h"
using namespace async;

TEST_CASE("async::Buffers") {
    SECTION("Standard") {
        Buffers<char> dataBuffers;
        *dataBuffers.init({});
        auto testData = "Hi!"_tv;
        // Writer side populates the buffer with the test data
        auto buffer = *dataBuffers.writerPop();
        buffer.cursor.copy<char>(testData);
        buffer.cursor += testData.size();
        REQUIRE(buffer.writerSizeUsed() == testData.size());
        dataBuffers.writerPush(_mv(buffer));
        // Flush since we didn't fully consume a buffer and it remains staged
        dataBuffers.flush(false);
        // Reader side: verify partial caching by reading one char at a time
        Text result;
        while (result.size() < testData.size()) {
            buffer = *dataBuffers.readerPop();
            REQUIRE(buffer.readerSizeAvail() == testData.size() - result.size());
            result += *buffer.cursor++;
            dataBuffers.readerPush(_mv(buffer));
        }
        REQUIRE(result == testData);
    }
    SECTION("Custom Ctx") {
        Buffers<char, std::allocator<char>, int> ctxBuffers;
        *ctxBuffers.init({});
        auto testData = "Hi!"_tv;
        // Reader side: read all buffers and ensure context value is preserved
        auto readerTask = async::work::submit(_location, "Reader", [&] {
            auto expectedCtx = 0;
            while (auto buff = ctxBuffers.readerPop()) {
                Text output;
                ASSERTD_MSG(buff->ctx == expectedCtx, buff->ctx, "!=", expectedCtx);
                output.resize(buff->readerSizeAvail());
                _copyTo(output, buff->cursor);
                ctxBuffers.readerPush(_mv(buff), true);
                expectedCtx++;
                ASSERTD_MSG(output == testData, output, "!=", testData);
            }
        });
        // Writer side: fill buffers with test data and assign context values
        for (auto idx = 0; idx < 5; idx++) {
            auto buffer = *ctxBuffers.writerPop();
            buffer.ctx = idx;
            buffer.cursor.copy<char>(testData);
            buffer.cursor += testData.size();
            REQUIRE(buffer.writerSizeUsed() == testData.size());
            ctxBuffers.writerPush(_mv(buffer), true);
        }
        // Signal writer completion and wait for reader to finish
        ctxBuffers.flush();
    }
}

