void CritParticle::tick()
{
	for (int index = 0; index < 16; index++)
	{
		double dirX = random->nextFloat() * 2 - 1;
		double dirY = random->nextFloat() * 2 - 1;
		double dirZ = random->nextFloat() * 2 - 1;
		if (dirX * dirX + dirY * dirY + dirZ * dirZ > 1) continue;

		double posX = targetEntity->x + dirX * targetEntity->bbWidth / 4;
		double posY = targetEntity->bb->y0 + targetEntity->bbHeight / 2 + dirY * targetEntity->bbHeight / 4;
		double posZ = targetEntity->z + dirZ * targetEntity->bbWidth / 4;

		level->addParticle(particleKind, posX, posY, posZ, dirX, dirY + 0.2, dirZ);
	}

	currentLife++;
	if (currentLife >= maxLife)
	{
		remove();
	}
}

