/******************************************************************************/
/* List tracking all nominal-state TSDs */
typedef ql_head(tsd_t) tsd_active_list_t;
static tsd_active_list_t tsd_nominal_list = ql_head_initializer(tsd_nominal_list);
static malloc_mutex_t tsd_nominal_list_lock;

/* Count of active slow-path features */
static atomic_u32_t tsd_slow_feature_count = ATOMIC_INIT(0);

static bool
tsd_is_in_active_list(tsd_t *tsd) {
	tsd_t *cursor;
	bool found = false;
	malloc_mutex_lock(TSDN_NULL, &tsd_nominal_list_lock);
	ql_foreach(cursor, &tsd_nominal_list, TSD_MANGLE(tsd_link)) {
		if (tsd == cursor) {
			found = true;
			break;
		}
	}
	malloc_mutex_unlock(TSDN_NULL, &tsd_nominal_list_lock);
	return found;
}

static void
tsd_insert_into_active_list(tsd_t *tsd) {
	assert(!tsd_is_in_active_list(tsd));
	assert(tsd_state_get(tsd) <= tsd_state_nominal_max);
	ql_elm_new(tsd, TSD_MANGLE(tsd_link));
	malloc_mutex_lock(tsd_tsdn(tsd), &tsd_nominal_list_lock);
	ql_tail_insert(&tsd_nominal_list, tsd, TSD_MANGLE(tsd_link));
	malloc_mutex_unlock(tsd_tsdn(tsd), &tsd_nominal_list_lock);
}

static void
tsd_remove_from_active_list(tsd_t *tsd) {
	assert(tsd_is_in_active_list(tsd));
	assert(tsd_state_get(tsd) <= tsd_state_nominal_max);
	malloc_mutex_lock(tsd_tsdn(tsd), &tsd_nominal_list_lock);
	ql_remove(&tsd_nominal_list, tsd, TSD_MANGLE(tsd_link));
	malloc_mutex_unlock(tsd_tsdn(tsd), &tsd_nominal_list_lock);
}

static void
tsd_trigger_recompute_all(tsdn_t *tsdn) {
	atomic_fence(ATOMIC_RELEASE);
	malloc_mutex_lock(tsdn, &tsd_nominal_list_lock);
	tsd_t *iter_tsd;
	ql_foreach(iter_tsd, &tsd_nominal_list, TSD_MANGLE(tsd_link)) {
		assert(tsd_atomic_load(&iter_tsd->state, ATOMIC_RELAXED)
		    <= tsd_state_nominal_max);
		tsd_atomic_store(&iter_tsd->state,
		    tsd_state_nominal_recompute, ATOMIC_RELAXED);
		atomic_fence(ATOMIC_SEQ_CST);
		te_next_event_fast_set_non_nominal(iter_tsd);
	}
	malloc_mutex_unlock(tsdn, &tsd_nominal_list_lock);
}

void
tsd_slow_feature_enable(tsdn_t *tsdn) {
	atomic_fetch_add_u32(&tsd_slow_feature_count, 1, ATOMIC_RELAXED);
	tsd_trigger_recompute_all(tsdn);
}

void tsd_slow_feature_disable(tsdn_t *tsdn) {
	atomic_fetch_sub_u32(&tsd_slow_feature_count, 1, ATOMIC_RELAXED);
	tsd_trigger_recompute_all(tsdn);
}

static bool
tsd_is_locally_slow(tsd_t *tsd) {
	return !tsd_tcache_enabled_get(tsd)
	    || tsd_reentrancy_level_get(tsd) > 0;
}

bool
tsd_any_slow(void) {
	return atomic_load_u32(&tsd_slow_feature_count, ATOMIC_RELAXED) > 0;
}

/******************************************************************************/
static uint8_t
tsd_determine_current_state(tsd_t *tsd) {
	if (!tsd_nominal(tsd)) {
		return tsd_state_get(tsd);
	}
	if (malloc_slow || tsd_is_locally_slow(tsd) || tsd_any_slow()) {
		return tsd_state_nominal_slow;
	} else {
		return tsd_state_nominal;
	}
}

void
tsd_update_slow_path(tsd_t *tsd) {
	uint8_t prev_state;
	do {
		uint8_t next_state = tsd_determine_current_state(tsd);
		prev_state = tsd_atomic_exchange(&tsd->state, next_state,
		    ATOMIC_ACQUIRE);
	} while (prev_state == tsd_state_nominal_recompute);
	te_recompute_fast_threshold(tsd);
}

void
tsd_set_state(tsd_t *tsd, uint8_t new_state) {
	assert(new_state != tsd_state_nominal_recompute);
	uint8_t current_state = tsd_atomic_load(&tsd->state, ATOMIC_RELAXED);
	if (current_state > tsd_state_nominal_max) {
		assert(!tsd_is_in_active_list(tsd));
		tsd_atomic_store(&tsd->state, new_state, ATOMIC_RELAXED);
		if (new_state <= tsd_state_nominal_max) {
			tsd_insert_into_active_list(tsd);
		}
	} else {
		assert(tsd_is_in_active_list(tsd));
		if (new_state > tsd_state_nominal_max) {
			tsd_remove_from_active_list(tsd);
			tsd_atomic_store(&tsd->state, new_state,
			    ATOMIC_RELAXED);
		} else {
			tsd_update_slow_path(tsd);
		}
	}
	te_recompute_fast_threshold(tsd);
}

static void
tsd_init_prng_state(tsd_t *tsd) {
	*tsd_prng_statep_get(tsd) = config_debug ? 42 :
	    (uint64_t)(uintptr_t)tsd ^ 0xDEADBEEFCAFEBABEULL;
}

static bool
tsd_initialize_data(tsd_t *tsd) {
	rtree_ctx_data_init(tsd_rtree_ctxp_get_unsafe(tsd));
	tsd_init_prng_state(tsd);
	tsd_te_init(tsd);
	tsd_san_init(tsd);
	return tsd_tcache_enabled_data_init(tsd);
}

static void
assert_tsd_cleanup_completed(tsd_t *tsd) {
	assert(!tsd_nominal(tsd));
	assert(!tsd_is_in_active_list(tsd));
	assert(*tsd_arenap_get_unsafe(tsd) == NULL);
	assert(*tsd_iarenap_get_unsafe(tsd) == NULL);
	assert(*tsd_tcache_enabledp_get_unsafe(tsd) == false);
	assert(*tsd_prof_tdatap_get_unsafe(tsd) == NULL);
}

static bool
tsd_initialize_without_cleanup(tsd_t *tsd) {
	assert(tsd_state_get(tsd) == tsd_state_reincarnated ||
	    tsd_state_get(tsd) == tsd_state_minimal_initialized);
	rtree_ctx_data_init(tsd_rtree_ctxp_get_unsafe(tsd));
	*tsd_tcache_enabledp_get_unsafe(tsd) = false;
	*tsd_reentrancy_levelp_get(tsd) = 1;
	tsd_init_prng_state(tsd);
	tsd_te_init(tsd);
	tsd_san_init(tsd);
	assert_tsd_cleanup_completed(tsd);
	return false;
}

tsd_t *
tsd_acquire_slow(tsd_t *tsd, bool minimal) {
	assert(!tsd_fast(tsd));
	if (tsd_state_get(tsd) == tsd_state_nominal_slow) {
		// Already on slow path; no immediate action needed
	} else if (tsd_state_get(tsd) == tsd_state_nominal_recompute) {
		tsd_update_slow_path(tsd);
	} else if (tsd_state_get(tsd) == tsd_state_uninitialized) {
		if (!minimal) {
			if (tsd_global_init_complete) {
				tsd_set_state(tsd, tsd_state_nominal);
				tsd_update_slow_path(tsd);
				tsd_set(tsd);
				tsd_initialize_data(tsd);
			}
		} else {
			tsd_set_state(tsd, tsd_state_minimal_initialized);
			tsd_set(tsd);
			tsd_initialize_without_cleanup(tsd);
			*tsd_min_init_state_nfetchedp_get(tsd) = 1;
		}
	} else if (tsd_state_get(tsd) == tsd_state_minimal_initialized) {
		uint8_t *access_count = tsd_min_init_state_nfetchedp_get(tsd);
		assert(*access_count >= 1);
		(*access_count)++;
		if (!minimal || *access_count == TSD_MIN_INIT_STATE_MAX_FETCHED) {
			tsd_set_state(tsd, tsd_state_nominal);
			assert(*tsd_reentrancy_levelp_get(tsd) >= 1);
			(*tsd_reentrancy_levelp_get(tsd))--;
			tsd_update_slow_path(tsd);
			tsd_initialize_data(tsd);
		} else {
			assert_tsd_cleanup_completed(tsd);
		}
	} else if (tsd_state_get(tsd) == tsd_state_purgatory) {
		tsd_set_state(tsd, tsd_state_reincarnated);
		tsd_set(tsd);
		tsd_initialize_without_cleanup(tsd);
	} else {
		assert(tsd_state_get(tsd) == tsd_state_reincarnated);
	}
	return tsd;
}

void *
malloc_tsd_malloc(size_t size) {
	return a0malloc(CACHELINE_CEILING(size));
}

void
malloc_tsd_dalloc(void *wrapper) {
	a0dalloc(wrapper);
}

#if defined(JEMALLOC_MALLOC_THREAD_CLEANUP) || defined(_WIN32)
static unsigned cleanup_count;
static malloc_tsd_cleanup_t cleanup_routines[MALLOC_TSD_CLEANUPS_MAX];

#ifndef _WIN32
JEMALLOC_EXPORT
#endif
void
thread_cleanup_run(void) {
	bool pending[MALLOC_TSD_CLEANUPS_MAX], retry_needed;
	unsigned i;
	for (i = 0; i < cleanup_count; i++) {
		pending[i] = true;
	}
	do {
		retry_needed = false;
		for (i = 0; i < cleanup_count; i++) {
			if (pending[i]) {
				pending[i] = cleanup_routines[i]();
				if (pending[i]) {
					retry_needed = true;
				}
			}
		}
	} while (retry_needed);
}

#ifndef _WIN32
JEMALLOC_EXPORT
#endif
void
thread_cleanup_register(bool (*f)(void)) {
	assert(cleanup_count < MALLOC_TSD_CLEANUPS_MAX);
	cleanup_routines[cleanup_count] = f;
	cleanup_count++;
}
#endif

static void
tsd_perform_cleanup(tsd_t *tsd) {
	prof_tdata_cleanup(tsd);
	iarena_cleanup(tsd);
	arena_cleanup(tsd);
	tcache_cleanup(tsd);
	witnesses_cleanup(tsd_witness_tsdp_get_unsafe(tsd));
	*tsd_reentrancy_levelp_get(tsd) = 1;
}

void
tsd_destructor(void *arg) {
	tsd_t *tsd = (tsd_t *)arg;
	switch (tsd_state_get(tsd)) {
	case tsd_state_uninitialized:
		break;
	case tsd_state_minimal_initialized:
	case tsd_state_reincarnated:
		assert_tsd_cleanup_completed(tsd);
		JEMALLOC_FALLTHROUGH;
	case tsd_state_nominal:
	case tsd_state_nominal_slow:
		tsd_perform_cleanup(tsd);
		tsd_set_state(tsd, tsd_state_purgatory);
		tsd_set(tsd);
		break;
	case tsd_state_purgatory:
		break;
	default:
		not_reached();
	}
#ifdef JEMALLOC_JET
	test_callback_t test_hook = *tsd_test_callbackp_get_unsafe(tsd);
	int *user_data = tsd_test_datap_get_unsafe(tsd);
	if (test_hook != NULL) {
		test_hook(user_data);
	}
#endif
}

tsd_t *
malloc_tsd_boot0(void) {
	tsd_t *tsd;
#if defined(JEMALLOC_MALLOC_THREAD_CLEANUP) || defined(_WIN32)
	cleanup_count = 0;
#endif
	if (malloc_mutex_init(&tsd_nominal_list_lock, "tsd_active_list_lock",
	    WITNESS_RANK_OMIT, malloc_mutex_rank_exclusive)) {
		return NULL;
	}
	if (tsd_boot0()) {
		return NULL;
	}
	tsd = tsd_acquire();
	return tsd;
}

void
malloc_tsd_boot1(void) {
	tsd_boot1();
	tsd_t *tsd = tsd_acquire();
	tsd_update_slow_path(tsd);
}

#ifdef _WIN32
static BOOL WINAPI
tls_thread_handler(HINSTANCE hinstDLL, DWORD fdwReason, LPVOID lpvReserved) {
	switch (fdwReason) {
#ifdef JEMALLOC_LAZY_LOCK
	case DLL_THREAD_ATTACH:
		isthreaded = true;
		break;
#endif
	case DLL_THREAD_DETACH:
		thread_cleanup_run();
		break;
	default:
		break;
	}
	return true;
}

