#if (!defined(JEMALLOC_MALLOC_THREAD_CLEANUP) && !defined(JEMALLOC_TLS) && \
    !defined(_WIN32))
void *
tsd_init_guard(tsd_init_block_list_t *list, tsd_init_block_t *block) {
	pthread_t self = pthread_self();
	tsd_init_block_t *entry;
	malloc_mutex_lock(TSDN_NULL, &list->lock);
	ql_foreach(entry, &list->active_blocks, link) {
		if (entry->thread == self) {
			malloc_mutex_unlock(TSDN_NULL, &list->lock);
			return entry->data;
		}
	}
	ql_elm_new(block, link);
	block->thread = self;
	ql_tail_insert(&list->active_blocks, block, link);
	malloc_mutex_unlock(TSDN_NULL, &list->lock);
	return NULL;
}

void
tsd_init_done(tsd_init_block_list_t *list, tsd_init_block_t *block) {
	malloc_mutex_lock(TSDN_NULL, &list->lock);
	ql_remove(&list->active_blocks, block, link);
	malloc_mutex_unlock(TSDN_NULL, &list->lock);
}
#endif

void
tsd_prefork(tsd_t *tsd) {
	malloc_mutex_prefork(tsd_tsdn(tsd), &tsd_nominal_list_lock);
}

void
tsd_postfork_parent(tsd_t *tsd) {
	malloc_mutex_postfork_parent(tsd_tsdn(tsd), &tsd_nominal_list_lock);
}

void
tsd_postfork_child(tsd_t *tsd) {
	malloc_mutex_postfork_child(tsd_tsdn(tsd), &tsd_nominal_list_lock);
	ql_new(&tsd_nominal_list);
	if (tsd_state_get(tsd) <= tsd_state_nominal_max) {
		tsd_insert_into_active_list(tsd);
	}
}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

// Irreducible polynomials for GF(2^k) for k = 1 to 15 (modified indices)
const int mod_coeffs[] = {
    0, 
    3,      // 1: x + 1
    7,      // 2: x^2 + x + 1
    13,     // 3: x^3 + x^2 + 1 (alternative irreducible polynomial)
    25,     // 4: x^4 + x^3 + 1
    41,     // 5: x^5 + x^3 + 1
    71,     // 6: x^6 + x^5 + x^2 + x + 1
    137,    // 7: x^7 + x^6 + x^3 + x^2 + 1
    299,    // 8: x^8 + x^6 + x^5 + x^2 + 1
    529,    // 9: x^9 + x^7 + x^5 + x^2 + 1
    1041,   // 10: x^10 + x^9 + x^6 + x^5 + x^4 + x^2 + 1
    2065,   // 11: x^11 + x^9 + x^7 + x^6 + x^5 + x^2 + 1
    4121,   // 12: x^12 + x^11 + x^8 + x^7 + x^6 + x^3 + 1
    8243,   // 13: x^13 + x^12 + x^10 + x^9 + x^8 + x^5 + x^2 + x + 1
    16451,  // 14: x^14 + x^13 + x^12 + x^9 + x^8 + x^7 + x^4 + x + 1
    32781   // 15: x^15 + x^14 + x^12 + x^9 + x^7 + x^5 + x^4 + x + 1
};

// Multiplication in GF(2^k) modulo p (refactored variable names and operations)
int gf_multiply(int operand_a, int operand_b, int degree_k, int modulus_p) {
    int result = 0;
    for (int bit_pos = 0; bit_pos < degree_k; ++bit_pos) {
        if ((operand_b >> bit_pos) & 1) {
            result ^= operand_a;
        }
        bool overflow = (operand_a >> (degree_k - 1)) & 1;
        operand_a <<= 1;
        if (overflow) {
            operand_a ^= modulus_p;
        }
        operand_a &= ((1 << degree_k) - 1);
    }
    return result;
}

// Compute a^3 in GF(2^k) using the modified multiplication function
int gf_cube(int base, int degree_k, int modulus_p) {
    int square = gf_multiply(base, base, degree_k, modulus_p);
    return gf_multiply(square, base, degree_k, modulus_p);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int input_limit;
    if (!(cin >> input_limit)) return 0;
    vector<int> optimal_set;

    // Algebraic construction: T = { y*2^m + y^3 } for y in GF(2^m)
    // This forms a Sidon-like structure with distinct pairwise XOR properties.
    // We iterate over m to find the best fit for input_limit.
    for (int m = 1; m <= 15; ++m) {
        // Early termination condition: skip if minimal element exceeds input range significantly
        if ((1 << m) > input_limit + 100 && m > 5) break;

        vector<int> candidate_set;
        int modulus = mod_coeffs[m];

        int field_size = 1 << m;
        int max_y = (input_limit >> m) + 2;
        if (max_y > field_size) max_y = field_size;

        for (int y = 1; y < max_y; ++y) {
            int y_cubed = gf_cube(y, m, modulus);
            long long constructed_val = ((long long)y << m) ^ y_cubed;
            if (constructed_val >= 1 && constructed_val <= input_limit) {
                candidate_set.push_back(static_cast<int>(constructed_val));
            }
        }

        if (candidate_set.size() > optimal_set.size()) {
            optimal_set = candidate_set;
        }
    }

    // For small input_limit values, use an alternative greedy method
    if (input_limit < 600) {
        vector<int> greedy_selection;
        greedy_selection.push_back(1);
        vector<bool> xor_tracker(4096, false); // Extended buffer for XOR tracking

        for (int candidate = 2; candidate <= input_limit; ++candidate) {
            bool valid = true;
            for (int existing : greedy_selection) {
                int diff = candidate ^ existing;
                if (diff < 4096 && xor_tracker[diff]) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                for (int existing : greedy_selection) {
                    int diff = candidate ^ existing;
                    if (diff < 4096) xor_tracker[diff] = true;
                }
                greedy_selection.push_back(candidate);
            }
        }

        if (greedy_selection.size() > optimal_set.size()) {
            optimal_set = greedy_selection;
        }
    }

    cout << optimal_set.size() << "\n";
    for (size_t idx = 0; idx < optimal_set.size(); ++idx) {
        cout << optimal_set[idx] << (idx == optimal_set.size() - 1 ? "" : " ");
    }
    cout << "\n";
    return 0;
}

#include "arcball.h"

// Static member initialization for sphere radius
double ArcBall::s_sphereRadius = 0.85;

ArcBall::ArcBall()
{
    m_Quat.a  = 0.0;
    m_Quat.qx = m_Quat.qy = m_Quat.qz = 0.0;

    // Initialize arcball with a modified iso viewpoint
    Quaternion qti;
    qti.fromEulerAngles(ROLL, PITCH, YAW);
    Quaternion qtyaw(-45.0, Vector3d(0.0,0.0,1.0));
    setQuat(qti * qtyaw);

    m_Start.set(0.0, 0.0, 1.0);
    m_Current.set(0.0, 0.0, 1.0);
}

void ArcBall::applyRotation(Quaternion const &rotQuat, bool bInverted)
{
    if(bInverted)
        m_Quat = m_Quat * rotQuat;
    else
        m_Quat = rotQuat * m_Quat;
}

/** update current arcball rotation */
void ArcBall::move(double vx, double vy)
{
    getSpherePoint(vx, vy, m_Current);

    // Skip if movement is negligible
    if((m_Current - m_Start).norm() < 1.e-7) 
        return;

    // Compute incremental rotation quaternion between start and current points
    Quaternion qt;
    qt.from2UnitVectors(m_Start.normalized(), m_Current.normalized());

    // Update the accumulated view quaternion
    m_Quat = qt * m_QuatStart;
}

void ArcBall::rotateCrossPoint(float &angleOut, float &xf, float &yf, float &zf)
{
    Vector3d axisRef(1.0, 0.0, 0.0);
    double cosAngle   = axisRef.dot(m_Current);
    double halfCos    = sqrt((1.0 + cosAngle) * 0.5);

    angleOut = 2.0f * acosf(float(halfCos)) * 180.0f / PIf;

    Vector3d crossVec = axisRef.cross(m_Current);
    crossVec.normalize();

    xf = crossVec.xf();
    yf = crossVec.yf();
    zf = crossVec.zf();
}

void ArcBall::setQuat(double realPart, double qx, double qy, double qz)
{
    m_Quat.a  = realPart;
    m_Quat.qx = qx;
    m_Quat.qy = qy;
    m_Quat.qz = qz;
}

void ArcBall::start(double vx, double vy)
{
    getSpherePoint(vx, vy, m_Start);
    m_Current = m_Start;
    m_QuatStart = m_Quat;
}

/** returns a unit vector to the point on the sphere's surface from viewport coordinates */
void ArcBall::getSpherePoint(double xView, double yView, Vector3d &outPt)
{
    double rSquared = s_sphereRadius * s_sphereRadius;
    if(rSquared > xView*xView + yView*yView)
        outPt.set(xView, yView, sqrt(rSquared - xView*xView - yView*yView));
    else
        outPt.set(xView, yView, 0.0);

    outPt.normalize();
}

#include "llvm/ObjectYAML/MinidumpYAML.h"
#include "llvm/ObjectYAML/yaml2obj.h"
#include "llvm/Support/ConvertUTF.h"
#include "llvm/Support/raw_ostream.h"
#include <optional>

using namespace llvm;
using namespace llvm::minidump;
using namespace llvm::MinidumpYAML;

namespace {
/// A helper class to manage the placement of various structures into the final
/// minidump binary. Space for objects can be allocated via various allocate***
/// methods, while the final minidump file is written by calling the writeTo
/// method. The plain versions of allocation functions take a reference to the
/// data which is to be written (and hence the data must be available until
/// writeTo is called), while the "New" versions allocate the data in an
/// allocator-managed buffer, which is available until the allocator object is
/// destroyed. For both kinds of functions, it is possible to modify the
/// data for which the space has been "allocated" until the final writeTo call.
/// This is useful for "linking" the allocated structures via their offsets.
class BlobAllocator {
public:
  size_t position() const { return CurrentOffset; }

  size_t reserveSpace(size_t Size,
                      std::function<void(raw_ostream &)> Handler) {
    size_t Position = CurrentOffset;
    CurrentOffset += Size;
    Handlers.push_back(std::move(Handler));
    return Position;
  }

  size_t storeBytes(ArrayRef<uint8_t> Data) {
    return reserveSpace(
        Data.size(), [Data](raw_ostream &OS) { OS << toStringRef(Data); });
  }

  size_t storeBytes(yaml::BinaryRef Data) {
    return reserveSpace(Data.binary_size(), [Data](raw_ostream &OS) {
      Data.writeAsBinary(OS);
    });
  }

  template <typename T> 
  size_t storeArray(ArrayRef<T> Data) {
    return storeBytes({reinterpret_cast<const uint8_t *>(Data.data()),
                       sizeof(T) * Data.size()});
  }

  template <typename T, typename RangeType>
  std::pair<size_t, MutableArrayRef<T>>
  createNewArray(const iterator_range<RangeType> &Items);

  template <typename T> 
  size_t storeObject(const T &Value) {
    return storeArray(ArrayRef(Value));
  }

  template <typename T, typename... Args>
  std::pair<size_t, T *> createNewObject(Args &&... Parameters) {
    T *Instance = new (Storage.Allocate<T>()) T(std::forward<Args>(Parameters)...);
    return {storeObject(*Instance), Instance};
  }

  size_t storeString(StringRef Text);
  void emitTo(raw_ostream &OS) const;

private:
  size_t CurrentOffset = 0;
  BumpPtrAllocator Storage;
  std::vector<std::function<void(raw_ostream &)>> Handlers;
};
} // namespace

template <typename T, typename RangeType>
std::pair<size_t, MutableArrayRef<T>>
BlobAllocator::createNewArray(const iterator_range<RangeType> &Items) {
  size_t Count = std::distance(Items.begin(), Items.end());
  MutableArrayRef<T> Buffer(Storage.Allocate<T>(Count), Count);
  std::uninitialized_copy(Items.begin(), Items.end(), Buffer.begin());
  return {storeArray(Buffer), Buffer};
}

size_t BlobAllocator::storeString(StringRef Text) {
  SmallVector<UTF16, 32> WideString;
  bool Success = convertUTF8ToUTF16String(Text, WideString);
  assert(Success && "Invalid UTF8 in input string?");
  (void)Success;

  WideString.push_back(0);
  size_t StringSize = 2 * (WideString.size() - 1);
  size_t Offset = createNewObject<support::ulittle32_t>(StringSize).first;
  createNewArray<support::ulittle16_t>(make_range(WideString.begin(), WideString.end()));
  return Offset;
}

void BlobAllocator::emitTo(raw_ostream &OS) const {
  size_t StartPosition = OS.tell();
  for (const auto &Handler : Handlers)
    Handler(OS);
  assert(OS.tell() == StartPosition + CurrentOffset &&
         "Handlers wrote an unexpected number of bytes.");
  (void)StartPosition;
}

static LocationDescriptor configure(BlobAllocator &Context, yaml::BinaryRef Data) {
  return {support::ulittle32_t(Data.binary_size()),
          support::ulittle32_t(Context.storeBytes(Data))};
}

static size_t configure(BlobAllocator &Context, MinidumpYAML::ExceptionStream &S) {
  Context.storeObject(S.MDExceptionStream);
  size_t EndOfData = Context.position();

  S.MDExceptionStream.ThreadContext = configure(Context, S.ThreadContext);
  return EndOfData;
}

static void configure(BlobAllocator &Context, MemoryListStream::entry_type &Range) {
  Range.Entry.Memory = configure(Context, Range.Content);
}

static void configure(BlobAllocator &Context, ModuleListStream::entry_type &M) {
  M.Entry.ModuleNameRVA = Context.storeString(M.Name);
  M.Entry.CvRecord = configure(Context, M.CvRecord);
  M.Entry.MiscRecord = configure(Context, M.MiscRecord);
}

static void configure(BlobAllocator &Context, ThreadListStream::entry_type &T) {
  T.Entry.Stack.Memory = configure(Context, T.Stack);
  T.Entry.Context = configure(Context, T.Context);
}

template <typename EntryT>
static size_t configure(BlobAllocator &Context,
                        MinidumpYAML::detail::ListStream<EntryT> &S) {
  Context.createNewObject<support::ulittle32_t>(S.Entries.size());
  for (auto &Item : S.Entries)
    Context.storeObject(Item.Entry);

  size_t EndOfData = Context.position();
  for (auto &Item : S.Entries)
    configure(Context, Item);
  return EndOfData;
}

static Directory configure(BlobAllocator &Context, Stream &S) {
  Directory Result;
  Result.Type = S.Type;
  Result.Location.RVA = Context.position();
  std::optional<size_t> EndOfDataStream;

  switch (S.Kind) {
  case Stream::StreamKind::Exception:
    EndOfDataStream = configure(Context, cast<MinidumpYAML::ExceptionStream>(S));
    break;

  case Stream::StreamKind::MemoryInfoList: {
    MemoryInfoListStream &InfoList = cast<MemoryInfoListStream>(S);
    Context.createNewObject<minidump::MemoryInfoListHeader>(
        sizeof(minidump::MemoryInfoListHeader), sizeof(minidump::MemoryInfo),
        InfoList.Infos.size());
    Context.storeArray(ArrayRef(InfoList.Infos));
    break;
  }

  case Stream::StreamKind::MemoryList:
    EndOfDataStream = configure(Context, cast<MemoryListStream>(S));
    break;

  case Stream::StreamKind::ModuleList:
    EndOfDataStream = configure(Context, cast<ModuleListStream>(S));
    break;

  case Stream::StreamKind::RawContent: {
    RawContentStream &Raw = cast<RawContentStream>(S);
    Context.reserveSpace(Raw.Size, [&Raw](raw_ostream &OS) {
      Raw.Content.writeAsBinary(OS);
      assert(Raw.Content.binary_size() <= Raw.Size);
      OS << std::string(Raw.Size - Raw.Content.binary_size(), '\0');
    });
    break;
  }

  case Stream::StreamKind::SystemInfo: {
    SystemInfoStream &SysInfo = cast<SystemInfoStream>(S);
    Context.storeObject(SysInfo.Info);
    EndOfDataStream = Context.position();
    SysInfo.Info.CSDVersionRVA = Context.storeString(SysInfo.CSDVersion);
    break;
  }

  case Stream::StreamKind::TextContent:
    Context.storeArray(arrayRefFromStringRef(cast<TextContentStream>(S).Text));
    break;

  case Stream::StreamKind::ThreadList:
    EndOfDataStream = configure(Context, cast<ThreadListStream>(S));
    break;
  }

  Result.Location.DataSize =
      EndOfDataStream.value_or(Context.position()) - Result.Location.RVA;
  return Result;
}

namespace llvm {
namespace yaml {
bool yaml2minidump(MinidumpYAML::Object &Obj, raw_ostream &Out,
                   ErrorHandler /*EH*/) {
  BlobAllocator Context;
  Context.storeObject(Obj.Header);

  std::vector<Directory> DirectoryTable(Obj.Streams.size());
  Obj.Header.StreamDirectoryRVA = Context.storeArray(ArrayRef(DirectoryTable));
  Obj.Header.NumberOfStreams = DirectoryTable.size();

  for (const auto &[Index, Stream] : enumerate(Obj.Streams))
    DirectoryTable[Index] = configure(Context, *Stream);

  Context.emitTo(Out);
  return true;
}
} // namespace yaml
} // namespace llvm

