#include <vector>

// Count all possible ways to make the desired amount using available denominations
int calculateCoinWays(std::vector<int>& denominations, int targetAmount) {
    int result = 0;

    // Recursive helper to explore combinations
    void exploreCombinations(std::vector<int>& denoms, int position, int total, int goal, int& counter) {
        // Found a valid combination
        if (total == goal) {
            counter++;
            return;
        }
        // Base cases: exceeded target or ran out of denominations
        if (total > goal || position == denoms.size()) {
            return;
        }

        // Use current denomination again (unbounded)
        exploreCombinations(denoms, position, total + denoms[position], goal, counter);
        // Skip current denomination and move to next
        exploreCombinations(denoms, position + 1, total, goal, counter);
    }

    exploreCombinations(denominations, 0, 0, targetAmount, result);
    return result;
}

