int main(int argc, char** argv) {
  using namespace small_gicp;

  if (argc < 2) {
    std::cout << "USAGE: kdtree_benchmark <dataset_path>" << std::endl;
    std::cout << "OPTIONS:" << std::endl;
    std::cout << "  --num_threads <value> (default: 4)" << std::endl;
    std::cout << "  --num_trials <value> (default: 100)" << std::endl;
    std::cout << "  --method <str> (small|omp|tbb)" << std::endl;
    return 0;
  }

  const std::string dataset_path = argv[1];
  int num_threads = 4;
  int num_repetitions = 100;
  std::string strategy = "small";

  for (int idx = 1; idx < argc; idx++) {
    const std::string option = argv[idx];
    if (option == "--num_threads") {
      num_threads = std::stoi(argv[idx + 1]);
    } else if (option == "--num_trials") {
      num_repetitions = std::stoi(argv[idx + 1]);
    } else if (option == "--method") {
      strategy = argv[idx + 1];
    } else if (option.size() >= 2 && option.substr(0, 2) == "--") {
      std::cerr << "unknown option: " << option << std::endl;
      return 1;
    }
  }

  std::cout << "dataset_path=" << dataset_path << std::endl;
  std::cout << "num_threads=" << num_threads << std::endl;
  std::cout << "num_trials=" << num_repetitions << std::endl;
  std::cout << "method=" << strategy << std::endl;

#ifdef BUILD_WITH_TBB
  tbb::global_control tbb_control(tbb::global_control::max_allowed_parallelism, num_threads);
#endif

  KittiDataset kitti(dataset_path, 1);
  auto input_points = std::make_shared<PointCloud>(kitti.points[0]);
  std::cout << "num_raw_points=" << input_points->size() << std::endl;

  // Binary search to find voxel resolution for target point count
  const auto compute_voxel_size = [&](size_t desired_num_points) {
    std::pair<double, size_t> lower = {0.1, voxelgrid_sampling(*input_points, 0.1)->size()};
    std::pair<double, size_t> upper = {1.0, voxelgrid_sampling(*input_points, 1.0)->size()};

    for (int step = 0; step < 20; step++) {
      if (lower.second < desired_num_points) {
        lower.first *= 0.1;
        lower.second = voxelgrid_sampling(*input_points, lower.first)->size();
        continue;
      }
      if (upper.second > desired_num_points) {
        upper.first *= 10.0;
        upper.second = voxelgrid_sampling(*input_points, upper.first)->size();
        continue;
      }

      const double mid_val = (lower.first + upper.first) * 0.5;
      const size_t mid_count = voxelgrid_sampling(*input_points, mid_val)->size();

      if (std::abs(1.0 - static_cast<double>(mid_count) / desired_num_points) < 0.001) {
        return mid_val;
      }

      if (mid_count > desired_num_points) {
        lower = {mid_val, mid_count};
      } else {
        upper = {mid_val, mid_count};
      }
    }
    return (lower.first + upper.first) * 0.5;
  };

  std::cout << "---" << std::endl;
  std::vector<double> voxel_sizes;
  std::vector<PointCloud::Ptr> filtered_clouds;

  for (double ratio = 1.0; ratio > 0.05; ratio -= 0.1) {
    const double voxel_resolution = compute_voxel_size(input_points->size() * ratio);
    voxel_sizes.emplace_back(voxel_resolution);
    filtered_clouds.emplace_back(voxelgrid_sampling(*input_points, voxel_resolution));
    std::cout << "voxel_resolution=" << voxel_resolution << std::endl;
    std::cout << "num_points=" << filtered_clouds.back()->size() << std::endl;
  }

  std::cout << "---" << std::endl;

  // Warm-up phase
  auto start_warmup = std::chrono::high_resolution_clock::now();
  while (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::high_resolution_clock::now() - start_warmup).count() < 1) {
    auto temp_cloud = voxelgrid_sampling(*input_points, 0.1);
    if (strategy == "small") {
      UnsafeKdTree<PointCloud> tree(*temp_cloud);
    } else if (strategy == "omp") {
      UnsafeKdTree<PointCloud> tree(*temp_cloud, KdTreeBuilderOMP(num_threads));
    }
#ifdef BUILD_WITH_TBB
    else if (strategy == "tbb") {
      UnsafeKdTree<PointCloud> tree(*temp_cloud, KdTreeBuilderTBB());
    }
#endif
  }

  Stopwatch timer;
  if (strategy == "small") {
    for (size_t i = 0; i < voxel_sizes.size(); i++) {
      if (num_threads != 1) {
        break;
      }
      Summarizer build_times(true);
      timer.start();
      for (size_t rep = 0; rep < num_repetitions; rep++) {
        UnsafeKdTree<PointCloud> tree(*filtered_clouds[i]);
        timer.lap();
        build_times.push(timer.msec());
      }
      std::cout << "kdtree_build_times=" << build_times.str() << " [msec]" << std::endl;
    }
  } else if (strategy == "omp") {
    for (size_t i = 0; i < voxel_sizes.size(); i++) {
      Summarizer omp_build_times(true);
      timer.start();
      for (size_t rep = 0; rep < num_repetitions; rep++) {
        UnsafeKdTree<PointCloud> tree(*filtered_clouds[i], KdTreeBuilderOMP(num_threads));
        timer.lap();
        omp_build_times.push(timer.msec());
      }
      std::cout << "kdtree_omp_build_times=" << omp_build_times.str() << " [msec]" << std::endl;
    }
  }
#ifdef BUILD_WITH_TBB
  else if (strategy == "tbb") {
    for (size_t i = 0; i < voxel_sizes.size(); i++) {
      Summarizer tbb_build_times(true);
      timer.start();
      for (size_t rep = 0; rep < num_repetitions; rep++) {
        UnsafeKdTree<PointCloud> tree(*filtered_clouds[i], KdTreeBuilderTBB());
        timer.lap();
        tbb_build_times.push(timer.msec());
      }
      std::cout << "kdtree_tbb_build_times=" << tbb_build_times.str() << " [msec]" << std::endl;
    }
  }
#endif

  return 0;
}

#include <cstddef>
#include <cassert>

static void upb_FixLocale(char* ptr) {
  /* printf() is locale-dependent; this post-processing step converts decimal
   * commas to periods to ensure JSON-compliant output (1,2 -> 1.2). */
  for (; *ptr; ptr++) {
    if (*ptr == ',') {
      *ptr = '.';
    }
  }
}

void _upb_EncodeRoundTripDouble(double value, char* buffer, size_t bufSize) {
  assert(bufSize >= kUpb_RoundTripBufferSize);

  // First attempt with standard precision
  snprintf(buffer, bufSize, "%.*g", DBL_DIG, value);

  // Verify precision was sufficient
  if (strtod(buffer, nullptr) != value) {
    // Retry with higher precision
    snprintf(buffer, bufSize, "%.*g", DBL_DIG + 2, value);
    assert(strtod(buffer, nullptr) == value);
  }

  upb_FixLocale(buffer);
}

void _upb_EncodeRoundTripFloat(float value, char* buffer, size_t bufSize) {
  assert(bufSize >= kUpb_RoundTripBufferSize);

  // First attempt with standard precision
  snprintf(buffer, bufSize, "%.*g", FLT_DIG, value);

  // Verify precision was sufficient
  if (strtof(buffer, nullptr) != value) {
    // Retry with higher precision
    snprintf(buffer, bufSize, "%.*g", FLT_DIG + 3, value);
    assert(strtof(buffer, nullptr) == value);
  }

  upb_FixLocale(buffer);
}

