#include <bits/stdc++.h>
using namespace std;

struct Firm {
    int a, b, c, pos;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m;
    cin >> m;

    vector<Firm> firms(m);
    for (int i = 0; i < m; i++) {
        cin >> firms[i].a >> firms[i].b >> firms[i].c;
        firms[i].pos = i;
    }

    sort(firms.begin(), firms.end(), [](const Firm& x, const Firm& y) {
        return x.b < y.b;
    });

    vector<double> prefix(m + 1, 0.0);
    for (int i = 1; i <= m; i++) {
        prefix[i] = prefix[i - 1] + (double)firms[i - 1].c / 10000.0;
    }

    vector<int> boundaries(m + 1);
    boundaries[0] = 0;

    for (int j = 1; j < m; j++) {
        int min_val = firms[j - 1].b + 1;
        int max_val = firms[j].b;
        double target = prefix[j];
        double rounded = round(target);
        int candidate = (int)rounded;
        candidate = max(min_val, min(max_val, candidate));
        boundaries[j] = candidate;
    }

    boundaries[m] = 10000;

    vector<int> left(m), top(m), right(m), bottom(m);

    for (int idx = 0; idx < m; idx++) {
        int original = firms[idx].pos;
        int t_val = boundaries[idx];
        int b_val = boundaries[idx + 1];

        left[original] = 0;
        top[original] = t_val;
        right[original] = 10000;
        bottom[original] = b_val;
    }

    for (int k = 0; k < m; k++) {
        cout << left[k] << " " << top[k] << " " << right[k] << " " << bottom[k] << "\n";
    }

    return 0;
}

#include <iostream>
#include <fstream>
#include <sstream>
#include <iomanip>
#include <ctime>

// Main entry point for the optimization experiment design
int main(int argc, char* argv[]) {
  ROL::GlobalMPISession mpiSession(&argc, &argv);
  Kokkos::ScopeGuard kokkosScope(argc, argv);

  // Communicator setup
  ROL::Ptr<const Teuchos::Comm<int>> dcomm, ocomm;
#ifdef HAVE_MPI
  OED_SplitComm<int, Teuchos::MpiComm<int>> splitcomm(1);
  dcomm = splitcomm.getDesignComm();
  ocomm = splitcomm.getSampleComm();
#else
  dcomm = ROL::makePtr<Teuchos::SerialComm<int>>();
  ocomm = Tpetra::getDefaultComm();
#endif

  // Determine if this process should print output
  const int drank = dcomm->getRank();
  const int orank = ocomm->getRank();
  bool iprint = (argc > 1) && (drank == 0) && (orank == 0);
  iprint = ((argc > 3) ? true : iprint);  // Changed condition from argc > 2 to argc > 3
  auto outStream = ROL::makeStreamPtr(std::cout, iprint);

  int errorFlag = 0;

  try {
    RealT tolerance(1e-7);  // Slightly tighter tolerance than original 1e-8

    /*************************************************************************/
    /******* BUILD LINEAR REGRESSION MODEL BASED ON HELMHOLTZ ****************/
    /*************************************************************************/
    /*** Load XML configuration ***/
    auto parlist = ROL::getParametersFromXmlFile("config.xml");  // Renamed input file
    int   numSources = 6;  // Changed from 8 to 6
    bool   verifyDeriv = parlist->sublist("Problem").get("Validate Derivatives", false);  // Renamed option
    int     logLevel = parlist->sublist("General").get("Verbosity Level", 0);             // Renamed variable
    bool      verboseAL = parlist->sublist("Step").sublist("Augmented Lagrangian")
                            .get("Log Intermediate Optimization Steps", false);            // Renamed option
    logLevel         = (iprint ? logLevel : 0);
    verboseAL        = (iprint ? verboseAL : false);
    parlist->sublist("General").set("Verbosity Level", logLevel);
    parlist->sublist("Step").sublist("Augmented Lagrangian").set("Log Intermediate Optimization Steps", verboseAL);

    // Initialize PDE and mesh
    auto meshMgr = ROL::makePtr<MeshReader<RealT, DeviceT>>(*parlist);
    auto pde = ROL::makePtr<PDE_Helmholtz_OCT<RealT, DeviceT>>(*parlist);
    auto con = ROL::makePtr<Linear_PDE_Constraint<RealT, DeviceT>>(pde, meshMgr, dcomm, *parlist, *outStream);
    auto assembler = con->getAssembler();
    con->printMeshData(*outStream);

    // Create state and residual vectors
    auto u_ptr = assembler->createStateVector();
    auto r_ptr = assembler->createResidualVector();
    auto up = ROL::makePtr<PDE_PrimalSimVector<RealT, DeviceT>>(u_ptr, pde, assembler, *parlist);
    auto rp = ROL::makePtr<PDE_DualSimVector<RealT, DeviceT>>(r_ptr, pde, assembler, *parlist);
    auto zp = ROL::makePtr<ROL::StdVector<RealT>>(numSources);

    // Observation functional
    auto qoi = ROL::makePtr<QoI_Helmholtz_Observation<RealT, DeviceT>>(pde->getFE(), *parlist);
    auto obs = ROL::makePtr<PDE_Objective<RealT, DeviceT>>(qoi, assembler);

    // Derivative verification
    if (verifyDeriv) {
      up->randomize();  zp->randomize();
      auto dup = up->clone(); dup->randomize();
      auto dzp = zp->clone(); dzp->randomize();
      ROL::Vector_SimOpt<RealT> uz(up, zp), duz(dup, dzp);
      std::vector<RealT> params(2, 0);
      obs->setParameter(params);

      *outStream << "\n\nVerify Jacobian_1 of PDE Constraint\n";
      con->checkApplyJacobian_1(*up, *zp, *dup, *rp, true, *outStream);
      *outStream << "\n\nVerify Jacobian_2 of PDE Constraint\n";
      con->checkApplyJacobian_2(*up, *zp, *dzp, *rp, true, *outStream);
      *outStream << "\n\nVerify Gradient of Full Objective Function\n";
      obs->checkGradient(uz, duz, true, *outStream);
      *outStream << "\n\nVerify Hessian of Full Objective Function\n";
      obs->checkHessVec(uz, duz, true, *outStream);
    }

    // Solve PDEs for each source and store states
    *outStream << std::endl << "Start: PDE Solves" << std::endl;
    std::vector<ROL::Ptr<ROL::Vector<RealT>>> states(numSources);
    for (int idx = 0; idx < numSources; ++idx) {  // Renamed loop variable i -> idx
      std::clock_t start_time = std::clock();
      con->solve(*rp, *up, *zp->basis(idx), tolerance);
      states[idx] = up->clone(); states[idx]->set(*up);

      std::stringstream filename;
      filename << "state_" << idx << ".txt";
      con->outputTpetraVector(u_ptr, filename.str());

      *outStream
        << "  Solve " << idx << " time:      "
        << static_cast<RealT>(std::clock() - start_time) / static_cast<RealT>(CLOCKS_PER_SEC)
        << std::endl;
    }
    *outStream << "Finish: PDE Solves" << std::endl << std::endl;

    // Build reduced objective
    auto theta = ROL::makePtr<ROL::StdVector<RealT>>(numSources, 1);
    auto model = ROL::makePtr<ROL::Reduced_Objective_SimOpt<RealT>>(obs, con, up, theta, up, false);

    /*************************************************************************/
    /******* BUILD EXPERIMENTAL DESIGN PROBLEM AND SOLVE *********************/
    /*************************************************************************/
    // File paths and sampling parameters
    std::string pd = parlist->sublist("Problem").sublist("Design").get("Design Points File",       "design_pts_4000.txt");
    std::string wd = parlist->sublist("Problem").sublist("Design").get("Design Weights File",      "design_wts_4000.txt");
    int nsampd     = parlist->sublist("Problem").sublist("Design").get("Number of Design Samples", 4000);
    std::string po = parlist->sublist("Problem").sublist("Objective").get("Obs Points File",       "obs_pts_150.txt");
    std::string wo = parlist->sublist("Problem").sublist("Objective").get("Obs Weights File",      "obs_wts_150.txt");
    int nsampo     = parlist->sublist("Problem").sublist("Objective").get("Number of Obs Samples", 150);

    *outStream << std::endl;
    *outStream << "  Design Points File:     " << pd << std::endl;
    *outStream << "  Design Weights File:    " << wd << std::endl;
    *outStream << "  Objective Points File:  " << po << std::endl;
    *outStream << "  Objective Weights File: " << wo << std::endl;
    *outStream << std::endl;

    // Batch managers
    auto dbman = ROL::makePtr<ROL::StdTeuchosBatchManager<RealT, int>>(dcomm);
    auto obman = ROL::makePtr<ROL::StdTeuchosBatchManager<RealT, int>>(ocomm);

    // Samplers
    auto dsampler = ROL::makePtr<ROL::UserInputGenerator<RealT>>(pd, wd, nsampd, 2, dbman);
    auto osampler = ROL::makePtr<ROL::UserInputGenerator<RealT>>(po, wo, nsampo, 2, obman);

    // Regression model setup
    bool useUIG, homNoise;
    std::string regType, dtype;
    homNoise = parlist->sublist("Problem").get("Constant Noise Variance", true);  // Renamed option
    regType  = parlist->sublist("Problem").get("Regression Method","Least Squares");  // Renamed option
    auto type     = ROL::OED::StringToRegressionType(regType);
    auto noise    = ROL::makePtr<Helmholtz_Noise<RealT>>();
    auto cov      = ROL::makePtr<ROL::OED::StdMomentOperator<RealT>>(type, homNoise, noise);
    auto factory  = ROL::makePtr<ROL::OED::Factory<RealT>>(model, dsampler, theta, cov, *parlist);
    obman->barrier();

    // Optional factor printing
    bool exportFactors = parlist->sublist("Problem").get("Export Factors", false);  // Renamed flag
    if (exportFactors) {
      std::stringstream factName_d, noisName_d, factName_o, noisName_o;
      std::ofstream factFile_d, noisFile_d, factFile_o, noisFile_o;
      ROL::Ptr<ROL::Vector<RealT>> Fp = zp->dual().clone();
      std::vector<RealT> pt;

      // Design space factors/noise
      factName_d << "factors_des_" << dsampler->batchID() << ".txt";
      noisName_d << "noise_des_" << dsampler->batchID() << ".txt";
      factFile_d.open(factName_d.str());
      noisFile_d.open(noisName_d.str());
      factFile_d << std::scientific << std::setprecision(15);
      noisFile_d << std::scientific << std::setprecision(15);

      auto factors = factory->getFactors(theta);
      for (int i = 0; i < dsampler->numMySamples(); ++i) {
        pt = dsampler->getMyPoint(i);
        factors->evaluate(*Fp, pt);
        for (int j = 0; j < numSources; ++j) {
          factFile_d << std::right << std::setw(25)
                     << (*ROL::dynamicPtrCast<ROL::StdVector<RealT>>(Fp)->getVector())[j];
        }
        factFile_d << std::endl;
        for (int j = 0; j < 2; ++j)
          noisFile_d << std::right << std::setw(25) << pt[j];
        noisFile_d << std::right << std::setw(25) << noise->evaluate(pt) << std::endl;
      }
      factFile_d.close();
      noisFile_d.close();

      // Objective space factors/noise
      factName_o << "factors_opt_" << osampler->batchID() << ".txt";
      noisName_o << "noise_opt_" << osampler->batchID() << ".txt";
      factFile_o.open(factName_o.str());
      noisFile_o.open(noisName_o.str());
      factFile_o << std::scientific << std::setprecision(15);
      noisFile_o << std::scientific << std::setprecision(15);

      for (int i = 0; i < osampler->numMySamples(); ++i) {
        pt = osampler->getMyPoint(i);
        factors->evaluate(*Fp, pt);
        for (int j = 0; j < numSources; ++j) {
          factFile_o << std::right << std::setw(25)
                     << (*ROL::dynamicPtrCast<ROL::StdVector<RealT>>(Fp)->getVector())[j];
        }
        factFile_o << std::endl;
        for (int j = 0; j < 2; ++j)
          noisFile_o << std::right << std::setw(25) << pt[j];
        noisFile_o << std::right << std::setw(25) << noise->evaluate(pt) << std::endl;
      }
      factFile_o.close();
      noisFile_o.close();
    }

    // Solve OED problem
    dtype = parlist->sublist("OED").get("Criterion Type","A");  // Renamed option
    useUIG = parlist->sublist("Problem").get("Flat Initial Guess", false);  // Renamed option
    solve<RealT>(factory, dsampler, osampler, *parlist, dtype, *outStream, useUIG, verifyDeriv);

    // Final timing summary
    Teuchos::TimeMonitor::summarize();
  }
  catch (std::logic_error &err) {
    std::cout << "Design MPI Rank = " << drank
              << "  Objective MPI Rank = " << orank
              << std::endl << err.what() << std::endl;
    errorFlag = -1000;
  }

  if (errorFlag != 0)
    std::cout << "Final Status: TEST FAILED\n";
  else
    std::cout << "Final Status: TEST PASSED\n";

  return 0;
}

