#include "aeronet/mime-mappings.hpp"
#include <gtest/gtest.h>
#include <cstddef>
#include <string>
using namespace aeronet;

// Test MIME type detection for common file extensions
TEST(MIMEMappings, ContainsKnownExtension) {
  // Verify several standard file extensions map correctly
  auto mappingIndex = DetermineMIMETypeIdx("document.html");
  ASSERT_NE(mappingIndex, kUnknownMIMEMappingIdx);
  if (mappingIndex != kUnknownMIMEMappingIdx) {
    EXPECT_EQ(kMIMEMappings[mappingIndex].mimeType, "text/html");
  }

  mappingIndex = DetermineMIMETypeIdx("photo.jpeg");
  ASSERT_NE(mappingIndex, kUnknownMIMEMappingIdx);
  if (mappingIndex != kUnknownMIMEMappingIdx) {
    EXPECT_EQ(kMIMEMappings[mappingIndex].mimeType, "image/jpeg");
  }

  mappingIndex = DetermineMIMETypeIdx("code.js");
  ASSERT_NE(mappingIndex, kUnknownMIMEMappingIdx);
  if (mappingIndex != kUnknownMIMEMappingIdx) {
    EXPECT_EQ(kMIMEMappings[mappingIndex].mimeType, "text/javascript");
  }
}

// Test handling of unrecognized file extensions
TEST(MIMEMappings, UnknownExtension) {
  EXPECT_EQ(DetermineMIMETypeIdx("data.xyz"), kUnknownMIMEMappingIdx);
  EXPECT_EQ(DetermineMIMETypeIdx("backup.abc"), kUnknownMIMEMappingIdx);
  EXPECT_EQ(DetermineMIMETypeIdx("temp.qqq"), kUnknownMIMEMappingIdx);
}

// Test case-insensitive extension matching
TEST(MIMEMappings, CaseInsensitiveExtensions) {
  auto idx1 = DetermineMIMETypeIdx("LARGE.TXT");
  auto idx2 = DetermineMIMETypeIdx("large.txt");
  EXPECT_EQ(idx1, idx2);
}

// Test handling of filenames with multiple dots
TEST(MIMEMappings, MultiDotFilenames) {
  auto mappingIndex = DetermineMIMETypeIdx("data.backup.tar.gz");
  ASSERT_NE(mappingIndex, kUnknownMIMEMappingIdx);
  if (mappingIndex != kUnknownMIMEMappingIdx) {
    EXPECT_EQ(kMIMEMappings[mappingIndex].mimeType, "application/gzip");
  }
}

// Verify the mappings array is sorted and contains unique entries
TEST(MIMEMappings, SortedAndUnique) {
  std::size_t count = std::size(kMIMEMappings);
  for (std::size_t position = 1; position < count; ++position) {
    const auto& previousEntry = kMIMEMappings[position - 1].extension;
    const auto& currentEntry = kMIMEMappings[position].extension;
    EXPECT_LT(previousEntry, currentEntry) << "Mappings not strictly increasing at index " << (position - 1);
  }
}

// Additional tests for common file extensions using string-based lookup
TEST(MIMEMappingsTest, CommonExtensions) {
  EXPECT_EQ(std::string(DetermineMIMETypeStr("notes.md")), "text/markdown");
  EXPECT_EQ(std::string(DetermineMIMETypeStr("compressed.tar.gz")), "application/gzip");
  EXPECT_EQ(std::string(DetermineMIMETypeStr("home.HTML")), "text/html");
  EXPECT_EQ(std::string(DetermineMIMETypeStr("CONFIG.TXT")), "text/plain");
}

// Test edge cases in filename parsing
TEST(MIMEMappingsTest, EdgeCases) {
  // Filename without dot should return empty result
  EXPECT_TRUE(DetermineMIMETypeStr("README").empty());
  // Filename ending with dot should return empty result
  EXPECT_TRUE(DetermineMIMETypeStr("archive.").empty());
  // Hidden files without proper extension should return empty result
  EXPECT_TRUE(DetermineMIMETypeStr(".gitignore").empty());
}

// Test behavior with maximum extension length
TEST(MIMEMappingsTest, MaxExtensionLengthBehavior) {
  // Find the longest extension in the mapping table
  std::size_t maxLength = 0;
  std::size_t maxIndex = 0;
  for (std::size_t i = 0; i < std::size(kMIMEMappings); ++i) {
    if (kMIMEMappings[i].extension.size() > maxLength) {
      maxLength = kMIMEMappings[i].extension.size();
      maxIndex = i;
    }
  }

  // Test that a path using the longest known extension works correctly
  const std::string testPath = std::string("sample.") + std::string(kMIMEMappings[maxIndex].extension);
  EXPECT_EQ(std::string(DetermineMIMETypeStr(testPath)), std::string(kMIMEMappings[maxIndex].mimeType));

  // Test that extensions longer than the maximum are rejected
  const std::string extendedExtension(maxLength + 1, 'y');
  EXPECT_TRUE(DetermineMIMETypeStr(std::string("file.") + extendedExtension).empty());
}

