#include <iostream>
#include <functional>

// Optimized callback: direct function pointer storage
template<typename Result, typename... Parameters>
struct QuickHandler {
    using FuncPtr = Result(*)(Parameters...);
    FuncPtr func = nullptr;

    QuickHandler() = default;
    QuickHandler(FuncPtr p) : func(p) {}

    Result operator()(Parameters... params) const {
        return func(params...);
    }

    bool is_null() const { return func == nullptr; }
};

// Alternative: Template-based handler (type specified at compile time)
template<typename Type>
struct HandlerWrapper {
    Type invocable;

    HandlerWrapper(Type&& i) : invocable(std::forward<Type>(i)) {}

    template<typename... Args>
    auto operator()(Args&&... args) -> decltype(invocable(args...)) {
        return invocable(std::forward<Args>(args)...);
    }
};

// Example functions
int multiply(int x, int y) {
    return x * y;
}

void display_text(const char* text) {
    std::cout << "Text: " << text << std::endl;
}

// Usage examples
void show_quick_handler() {
    std::cout << "=== QuickHandler Demo ===" << std::endl;

    QuickHandler<int, int, int> handler1 = multiply;
    std::cout << "handler1(6, 7) = " << handler1(6, 7) << std::endl;

    QuickHandler<void, const char*> handler2 = display_text;
    handler2("Greetings from QuickHandler!");
}

void show_handler_wrapper() {
    std::cout << "\n=== HandlerWrapper Demo ===" << std::endl;

    // Type is known at compile time
    auto lambda = [](int val) { return val * 3; };
    HandlerWrapper<decltype(lambda)> wrapper(lambda);

    std::cout << "wrapper(14) = " << wrapper(14) << std::endl;  // 42

    // With capture
    int factor = 8;
    auto captured = [factor](int val) { return val * factor; };
    HandlerWrapper<decltype(captured)> wrapper2(captured);

    std::cout << "wrapper2(6) = " << wrapper2(6) << std::endl;  // 48
}

// Hybrid: Choose based on context needs
void show_hybrid_approach() {
    std::cout << "\n=== Hybrid Approach ===" << std::endl;

    // For no context: use QuickHandler (function pointer)
    QuickHandler<int, int, int> fast = multiply;

    // For context: use HandlerWrapper with specific lambda type
    int delta = 50;
    auto with_delta = [delta](int val) { return val + delta; };
    HandlerWrapper<decltype(with_delta)> flexible(with_delta);

    std::cout << "fast(9, 11) = " << fast(9, 11) << std::endl;
    std::cout << "flexible(7) = " << flexible(7) << std::endl;
}

// Size comparison
void show_size_comparison() {
    std::cout << "\n=== Size Comparison ===" << std::endl;

    std::cout << "sizeof(QuickHandler<int(int,int)>) = "
              << sizeof(QuickHandler<int, int, int>) << " bytes" << std::endl;

    auto lambda = [](int value) { return value; };
    std::cout << "sizeof(HandlerWrapper<decltype(lambda)>) = "
              << sizeof(HandlerWrapper<decltype(lambda)>) << " bytes" << std::endl;

    std::cout << "sizeof(std::function<int(int)>) = "
              << sizeof(std::function<int(int)>) << " bytes" << std::endl;
}

int main() {
    show_quick_handler();
    show_handler_wrapper();
    show_hybrid_approach();
    show_size_comparison();

    std::cout << "\n=== Recommendations ===" << std::endl;
    std::cout << "- QuickHandler: performance-critical paths, no context needed" << std::endl;
    std::cout << "- HandlerWrapper: compile-time known type, with captured state" << std::endl;
    std::cout << "- std::function: runtime polymorphism, maximum flexibility" << std::endl;
    std::cout << "- Select based on your performance/flexibility requirements" << std::endl;

    return 0;
}

