#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int nodes, edges;
    cin >> nodes >> edges;

    vector<vector<int>> graph(nodes + 1);
    vector<int> degree(nodes + 1, 0);

    for (int i = 0; i < edges; i++) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
        degree[u]++;
        degree[v]++;
    }

    vector<int> ordering(nodes);
    iota(ordering.begin(), ordering.end(), 1);
    sort(ordering.begin(), ordering.end(), [&](int x, int y) {
        return degree[x] > degree[y] || (degree[x] == degree[y] && x < y);
    });

    vector<int> assignedColor(nodes + 1, 0);

    for (int node : ordering) {
        vector<int> conflict(4, 0);
        for (int neighbor : graph[node]) {
            int col = assignedColor[neighbor];
            if (col != 0) conflict[col]++;
        }

        int chosenColor = 1;
        int minConflict = conflict[1];

        for (int c = 2; c <= 3; c++) {
            if (conflict[c] < minConflict) {
                minConflict = conflict[c];
                chosenColor = c;
            }
        }

        assignedColor[node] = chosenColor;
    }

    for (int i = 1; i <= nodes; i++) {
        if (i > 1) cout << " ";
        cout << assignedColor[i];
    }
    cout << '\n';

    return 0;
}

