namespace engine::store::filter::filesys::base {
//-------------------------------------------------------------------------
/// @details
///		Determines whether the stored object has been modified by comparing
///		metadata such as timestamps, permissions, and size. If any changes
///		are detected, it updates the entry accordingly and flags it as changed.
///	@param[inout] record
///		The entry representing the file to be verified for modifications
///	@returns
///		Error code indicating success or failure of the operation
//-------------------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseSysInstance<LvlT>::checkChanged(Entry &record) noexcept {
    Error errCode;
    // Retrieve the OS-specific path
    Text osPath;
    if (errCode = Url::osPath(record.url(), osPath)) return errCode;

    auto statResult = ap::file::stat(osPath, true);
    if (!statResult) return statResult.ccode();

    auto stats = _mv(*statResult);

    // Assume no change initially
    record.changed(false);

    // Compare creation time
    if (record.createTime.get() != stats.createTime) {
        record.markChanged(LogLevel, "Creation time different");
        record.createTime(stats.createTime);
    }

    // Update access time without marking as changed
    if (record.accessTime.get() != stats.accessTime) {
        record.accessTime(stats.accessTime);
    }

    // Compare modification time
    if (record.modifyTime.get() != stats.modifyTime) {
        record.markChanged(LogLevel, "Modification time different");
        record.modifyTime(stats.modifyTime);
    }

    // Compare file attributes
    if (record.attrib() != stats.plat.st_mode) {
        record.markChanged(LogLevel, "Attributes have changed");
        record.attrib(stats.plat.st_mode);
    }

    // Compare file size
    if (record.size() != stats.size) {
        record.markChanged(LogLevel, "Size is different");
        record.size(stats.size);
    }

    // Compare disk space usage
    if (record.storeSize() != stats.sizeOnDisk) {
        record.markChanged(LogLevel, "Size on disk is different");
        record.storeSize(stats.sizeOnDisk);
    }

    return {};
}
}  // namespace engine::store::filter::filesys::base

