struct vessel {
    int ammo = 25;
    int health = 150;

    bool fire() {
        if (ammo > 0) {
            --ammo;
            // successfully fired
            return true;
        }
        // cannot fire
        return false;
    }

    bool damage(int amount) {
        health -= amount;
        // has the vessel been destroyed?
        return health < 1;
    }
};

int main() {

    std::cout << "=== usertype fundamentals ===" << std::endl;

    static const bool method_a = true;

    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    if (method_a) {
        lua_vm.new_usertype<vessel>(
             "vessel", // the name of the class, as you want it
                       // to be used in lua List the member
                       // functions you wish to bind:
                       // "name_of_item",
                       // &class_name::function_or_variable
             "fire",
             &vessel::fire,
             "damage",
             &vessel::damage,
             // bind variable types, too
             "health",
             &vessel::health,
             // names in lua don't have to be the same as C++,
             // but it probably helps if they're kept the same,
             // here we change it just to show its possible
             "ammo_remaining",
             &vessel::ammo);
    }
    else {
        // set usertype explicitly, with the given name
        sol::usertype<vessel> class_table
             = lua_vm.new_usertype<vessel>("vessel");
        class_table["fire"] = &vessel::fire;
        class_table["damage"] = &vessel::damage;
        class_table["health"] = &vessel::health;
        class_table["ammo_remaining"] = &vessel::ammo;
    }

    const auto& script_code = R"(
        starship = vessel.new()
        -- note the ":" that is there: this is mandatory for member function calls
        -- ":" means "pass self" in Lua
        local result = starship:fire()
        local is_destroyed = starship:damage(30)
        -- check if it works
        print(is_destroyed) -- the vessel is not destroyed at this point
        print(starship.health .. " health remaining") -- 120 health left
        print(starship.ammo_remaining) -- 24
    )";

    lua_vm.script(script_code);

    std::cout << std::endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int testCases;
    cin >> testCases;
    while (testCases--) {
        // First query: 100000 words of length 1
        cout << "? 100000";
        for (int idx = 0; idx < 100000; ++idx) cout << " 1";
        cout << endl;

        int minLength;
        cin >> minLength;
        if (minLength == -1) return 0;

        const int totalWords = 100000;
        int lowerBound, upperBound;
        if (minLength == 1) {
            lowerBound = upperBound = totalWords;
        } else if (minLength == totalWords) {
            lowerBound = upperBound = 1;
        } else {
            lowerBound = (totalWords + minLength - 1) / minLength;     // ceil(totalWords / minLength)
            upperBound = (totalWords - 1) / (minLength - 1);           // floor((totalWords-1)/(minLength-1))
        }

        if (lowerBound == upperBound) {
            cout << "! " << lowerBound << endl;
            continue;
        }

        // Second query: a single word of length lowerBound+1
        cout << "? 1 " << lowerBound + 1 << endl;
        int secondLength;
        cin >> secondLength;
        if (secondLength == -1) return 0;

        if (secondLength == 0) {
            // Actual length < lowerBound+1 => actual length = lowerBound
            cout << "! " << lowerBound << endl;
        } else {
            // Actual length >= lowerBound+1, but we cannot determine exactly.
            // As a fallback, guess lowerBound+1 (may be incorrect).
            cout << "! " << lowerBound + 1 << endl;
        }
    }
    return 0;
}

#include <iostream>
#include <type_traits>
#include <functional>
#include <string>

struct Multiplier {
    double operator()(int x, int y) const {
        return static_cast<double>(x) * y;
    }
};

int add(int a, int b) {
    return a + b;
}

void demo_invoke_result() {
    std::cout << "=== std::invoke_result Demo ===" << std::endl;

    // Deduce return type at compile time
    using Result1 = std::invoke_result_t<decltype(&Multiplier::operator()), Multiplier, int, int>;
    static_assert(std::is_same_v<Result1, double>);
    std::cout << "Multiplier::operator() returns double" << std::endl;

    using Result2 = std::invoke_result_t<decltype(add), int, int>;
    static_assert(std::is_same_v<Result2, int>);
    std::cout << "add returns int" << std::endl;

    using Result3 = std::invoke_result_t<decltype([]() { return 42; })>;
    static_assert(std::is_same_v<Result3, int>);
    std::cout << "Lambda returns int" << std::endl;
}

// Generic function with compile-time return type handling
template<typename Func, typename... Args>
auto call_and_print(Func&& func, Args&&... args)
    -> std::invoke_result_t<Func, Args...>
{
    using Ret = std::invoke_result_t<Func, Args...>;

    if constexpr (std::is_void_v<Ret>) {
        std::invoke(std::forward<Func>(func), std::forward<Args>(args)...);
        std::cout << "(void return)" << std::endl;
    } else {
        Ret result = std::invoke(std::forward<Func>(func), std::forward<Args>(args)...);
        std::cout << "result: " << result << std::endl;
        return result;
    }
}

void demo_generic_handler() {
    std::cout << "\n=== Generic Handler Demo ===" << std::endl;

    Multiplier mult;

    std::cout << "Calling Multiplier: ";
    call_and_print(mult, 5, 6);

    std::cout << "Calling add: ";
    call_and_print(add, 15, 25);

    std::cout << "Calling void lambda: ";
    call_and_print([]() { std::cout << "Side effect!"; });
}

// Compile-time constraints
template<typename Func, typename... Args>
auto safe_invoke(Func&& func, Args&&... args)
    -> std::enable_if_t<std::is_invocable_v<Func, Args...>,
                       std::invoke_result_t<Func, Args...>>
{
    return std::invoke(std::forward<Func>(func), std::forward<Args>(args)...);
}

// SFINAE example
template<typename Func, typename... Args>
auto invoke_or_error(Func&& func, Args&&... args)
    -> std::enable_if_t<std::is_invocable_v<Func, Args...>, bool>
{
    using Ret = std::invoke_result_t<Func, Args...>;
    if constexpr (!std::is_void_v<Ret>) {
        auto result = std::invoke(std::forward<Func>(func), std::forward<Args>(args)...);
        std::cout << "Result: " << result << std::endl;
    }
    return true;
}

template<typename Func, typename... Args>
auto invoke_or_error(Func&&, Args&&... args)
    -> std::enable_if_t<!std::is_invocable_v<Func, Args...>, bool>
{
    std::cout << "Error: arguments not callable with given types" << std::endl;
    return false;
}

void demo_sfinae() {
    std::cout << "\n=== SFINAE Demo ===" << std::endl;

    auto valid_func = [](int x) { return x * 2; };

    std::cout << "Valid call: ";
    invoke_or_error(valid_func, 21);

    std::cout << "Invalid call: ";
    invoke_or_error(valid_func, "not an int");
}

// Type checking at compile time
template<typename Func, typename... Args>
constexpr bool is_callable_with_return_v =
    std::is_invocable_r_v<int, Func, Args...>;

void demo_type_checking() {
    std::cout << "\n=== Type Checking Demo ===" << std::endl;

    auto returns_int = [](int x) { return x; };
    auto returns_double = [](int x) { return 1.0 * x; };

    std::cout << "Lambda returning int is callable -> int: "
              << is_callable_with_return_v<decltype(returns_int), int> << std::endl;

    std::cout << "Lambda returning double is callable -> int: "
              << is_callable_with_return_v<decltype(returns_double), int> << std::endl;
}

int main() {
    demo_invoke_result();
    demo_generic_handler();
    demo_sfinae();
    demo_type_checking();

    return 0;
}

