namespace engine::store::filter::filesys::base {
//-----------------------------------------------------------------
/// @details
///		Starts the endpoint and performs validation checks to ensure
///		all required settings are properly initialized
///	@param[in]	modeFlags
///		The mode flags indicating how the endpoint should be opened
///	@returns
///		Status code indicating success or failure
//-----------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseEndpoint<LvlT>::beginEndpoint(OPEN_MODE modeFlags_) noexcept {
    // Based on the operational mode of the service
    switch (config.serviceMode) {
        default:
        case SERVICE_MODE::SOURCE:
            // In source mode, scanning and rendering operations are used,
            // so a storePath is not necessary
            break;
        case SERVICE_MODE::TARGET:
            // In target mode, verify that a store path has been provided.
            // This requirement applies regardless of the data format being used
            if (!config.storePath)
                return APERR(Ec::InvalidParam, "Missing storePath configuration");
            break;
    }
    // Extract configuration parameters
    if (auto errCode = config.parameters.lookupAssign("ignoreRemovableDrives",
                                                      m_ignoreRemovableDrives))
        return errCode;
    if (auto errCode = config.parameters.lookupAssign("ignoreSymbolicLinks",
                                                      m_ignoreSymbolicLinks))
        return errCode;
    // Delegate to the base class implementation
    return Parent::beginEndpoint(modeFlags_);
}
//-----------------------------------------------------------------
/// @details
///		Constructs a static, immutable configuration key string
//-----------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseEndpoint<LvlT>::getConfigSubKey(Text &outputKey) noexcept {
    // Generate a fixed standalone key based on the store path
    outputKey = (TextView)config.storePath;
    return {};
}
template <log::Lvl LvlT>
Error IBaseInstance<LvlT>::getPermissions(Entry &targetEntry) noexcept {
    // Initialize the permission handler
    if (auto errCode =
            permissions.beginPerm(targetEntry, m_endpoint.permissionInfo, m_endpoint))
        return errCode;
    return {};
}
template <log::Lvl LvlT>
ErrorOr<std::list<Text>> IBaseInstance<LvlT>::outputPermissions() noexcept {
    return permissions.outputPermissions(m_endpoint.permissionInfo, m_endpoint);
}
