// Constructor for MemPoint with initialization type
MemPoint::MemPoint(eInitType t) {
    if (t == kInitType1) {
        // Collect memory statistics for each heap
        for (int heapIndex = 0; heapIndex < MemNumHeaps(); heapIndex++) {
            int freeBlocks, totalFree, usedBlocks, largestFree, totalAlloc;
            MemFreeBlockStats(heapIndex, freeBlocks, totalFree, heapStats[heapIndex], largestFree, totalAlloc);
        }
        // Record current physical memory usage
        physicalUsageSnapshot = PhysicalUsage();
    } else {
        // Zero out internal state
        memset(heapStats, 0, 0x44);
    }
}

// Compute difference between two MemPoint snapshots
MemPointDelta MemPoint::operator-(const MemPoint &otherPoint) const {
    MemPointDelta delta;
    for (int i = 0; i < MemNumHeaps(); i++) {
        delta.heapStats[i] = otherPoint.heapStats[i] - heapStats[i];
    }
    delta.physicalUsageDiff = physicalUsageSnapshot - otherPoint.physicalUsageSnapshot;
    return delta;
}

// Default constructor initializes delta to zero
MemPointDelta::MemPointDelta() { 
    memset(heapStats, 0, 0x44); 
}

// In-place addition of another delta
MemPointDelta &MemPointDelta::operator+=(const MemPointDelta &rhs) {
    for (int i = 0; i < MemNumHeaps(); i++) {
        heapStats[i] += rhs.heapStats[i];
    }
    physicalUsageDiff += rhs.physicalUsageDiff;
    return *this;
}

// Check if any heap allocation exceeds threshold
bool MemPointDelta::AnyGreaterThan(int threshold) const {
    for (int i = 0; i < MemNumHeaps(); i++) {
        if (heapStats[i] > threshold) {
            return true;
        }
    }
    return (threshold < physicalUsageDiff) & 1;
}

// Generate header string for output formatting
const char *MemPointDelta::HeaderString(const char *suffix) {
    String buffer;
    for (int i = 0; i < MemNumHeaps(); i++) {
        if (i != 0) {
            buffer << ',';
        }
        buffer << MemHeapName(i);
        if (suffix != nullptr) {
            buffer << suffix;
        }
    }
    buffer << ",physical";
    if (suffix != nullptr) {
        buffer << suffix;
    }
    const char *result = MakeString("%s", buffer);
    return result;
}

// Convert delta values to comma-separated string representation
const char *MemPointDelta::ToString(int divisor) const {
    MILO_ASSERT(divisor > 0, 0x5b);
    String buffer;
    for (int i = 0; i < MemNumHeaps(); i++) {
        if (i != 0) {
            buffer << ',';
        }
        buffer << heapStats[i] / divisor;
    }
    buffer << ',';
    buffer << physicalUsageDiff / divisor;
    const char *result = MakeString("%s", buffer);
    return result;
}

