void X86MnemonicTablesEmitter::emit(raw_ostream &OS) {
  emitSourceFileHeader("X86 Mnemonic tables", OS);
  OS << "namespace llvm {\nnamespace X86 {\n\n";

  Record *WriterDef = Target.getAsmWriter();
  unsigned VariantID = WriterDef->getValueAsInt("Variant");

  // Group instructions by their mnemonic string
  StringMap<SmallVector<const CodeGenInstruction *, 0>> MnemonicToInstMap;

  ArrayRef<const CodeGenInstruction *> EnumOrderedInstructions =
      Target.getInstructionsByEnumValue();

  for (const CodeGenInstruction *Instr : EnumOrderedInstructions) {
    const Record *Def = Instr->TheDef;

    // Only process X86-specific instructions
    if (!Def->isSubClassOf("X86Inst"))
      continue;

    X86Disassembler::RecognizableInstrBase RI(*Instr);
    if (!RI.shouldBeEmitted())
      continue;

    // Skip non-parsable or prefix-only instructions
    if (Def->getValueAsString("AsmVariantName") == "NonParsable" ||
        RI.Form == X86Local::PrefixByte)
      continue;

    std::string Mnemonic = X86Disassembler::getMnemonic(Instr, VariantID);
    MnemonicToInstMap[Mnemonic].push_back(Instr);
  }

  // Header section: declare predicate functions
  OS << "#ifdef GET_X86_MNEMONIC_TABLES_H\n";
  OS << "#undef GET_X86_MNEMONIC_TABLES_H\n\n";

  for (StringRef Mnemonic : MnemonicToInstMap.keys())
    OS << "bool is" << Mnemonic << "(unsigned Opcode);\n";

  OS << "#endif // GET_X86_MNEMONIC_TABLES_H\n\n";

  // Implementation section: define predicate functions
  OS << "#ifdef GET_X86_MNEMONIC_TABLES_CPP\n";
  OS << "#undef GET_X86_MNEMONIC_TABLES_CPP\n\n";

  for (StringRef Mnemonic : MnemonicToInstMap.keys()) {
    OS << "bool is" << Mnemonic << "(unsigned Opcode) {\n";
    auto Instructions = MnemonicToInstMap[Mnemonic];

    if (Instructions.size() == 1) {
      const CodeGenInstruction *CGI = *Instructions.begin();
      OS << "\treturn Opcode == " << CGI->TheDef->getName() << ";\n}\n\n";
    } else {
      OS << "\tswitch (Opcode) {\n";
      for (const CodeGenInstruction *CGI : Instructions) {
        OS << "\tcase " << CGI->TheDef->getName() << ":\n";
      }
      OS << "\t\treturn true;\n\t}\n\treturn false;\n}\n\n";
    }
  }

  OS << "#endif // GET_X86_MNEMONIC_TABLES_CPP\n\n";
  OS << "} // end namespace X86\n} // end namespace llvm";
}
} // anonymous namespace

static TableGen::Emitter::OptClass<X86MnemonicTablesEmitter>
    X("gen-x86-mnemonic-tables", "Generate X86 mnemonic tables");

