/**
 * UFTextCrash - Unit test for FText-related crash exploit
 */
UFTextCrash::UFTextCrash(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	UnitTestName = TEXT("FTextCrash");
	UnitTestType = TEXT("SecurityExploit");
	UnitTestDate = FDateTime(2014, 07, 11);
	UnitTestBugTrackIDs.Add(TEXT("JIRA UE-5691"));
	UnitTestCLs.Add(TEXT("2367048 (//depot/UE4/)"));
	ExpectedResult.Add(TEXT("ShooterGame"),			EUnitTestVerification::VerifiedFixed);
	ExpectedResult.Add(TEXT("QAGame"),				EUnitTestVerification::VerifiedFixed);
	ExpectedResult.Add(TEXT("UnrealTournament"),	EUnitTestVerification::VerifiedFixed);
	ExpectedResult.Add(TEXT("FortniteGame"),		EUnitTestVerification::VerifiedFixed);
	ExpectedResult.Add(TEXT("OrionGame"),			EUnitTestVerification::VerifiedFixed);
	UnitTestTimeout = 60;
	SetFlags<EUnitTestFlags::LaunchServer | EUnitTestFlags::AcceptPlayerController | EUnitTestFlags::RequireNUTActor |
				EUnitTestFlags::ExpectServerCrash | EUnitTestFlags::ExpectDisconnect,
				EMinClientFlags::AcceptActors | EMinClientFlags::SendRPCs | EMinClientFlags::NotifyNetActors>();
}

void UFTextCrash::InitializeEnvironmentSettings()
{
	BaseServerURL = UnitEnv->GetDefaultMap(UnitTestFlags);
	BaseServerParameters = UnitEnv->GetDefaultServerParameters();
}

void UFTextCrash::ExecuteClientUnitTest()
{
	// Wait until we receive the NUTActor from the server
	if (UnitNUTActor.IsValid())
	{
		// Construct an empty FText and transmit it to the server — this should provoke an assertion failure on the server side
		FText EmptyText;
		UnitNUTActor->ServerReceiveText(EmptyText);

		// If the exploit attempt fails, the subsequent log entry will be the 'ExploitFailLog' message,
		// as this message originates from the same execution path as the RPC call above
		// (and would be suppressed if the preceding call succeeds).
		SendGenericExploitFailLog();
	}
}

void UFTextCrash::NotifyProcessLog(TWeakPtr<FUnitTestProcess> InProcess, const TArray<FString>& InLogLines)
{
	Super::NotifyProcessLog(InProcess, InLogLines);
	if (InProcess.HasSameObject(ServerHandle.Pin().Get()))
	{
		const TCHAR* CrashLog = TEXT("Unhandled Exception: EXCEPTION_ACCESS_VIOLATION reading address");
		for (const auto& CurrentLine : InLogLines)
		{
			if (CurrentLine.Contains(CrashLog))
			{
				VerificationState = EUnitTestVerification::VerifiedNotFixed;
				break;
			}
			else if (CurrentLine.Contains(GetGenericExploitFailLog()))
			{
				VerificationState = EUnitTestVerification::VerifiedFixed;
				break;
			}
		}
	}
}

#include "ttsafe.h"
#ifdef H5_HAVE_THREADSAFE
#define FILENAME        "ttsafe_dcreate.h5"
#define NUM_THREADS     16

void *tts_dcreate_worker(void *);
typedef struct worker_data {
    int index;
    hid_t file_id;
    const char *dataset_label;
} worker_data;

/*
 * Explicitly define dataset names instead of generating them automatically
 */
const char *dataset_label[NUM_THREADS] = {
    "zero",
    "one",
    "two",
    "three",
    "four",
    "five",
    "six",
    "seven",
    "eight",
    "nine",
    "ten",
    "eleven",
    "twelve",
    "thirteen",
    "fourteen",
    "fifteen"
};

worker_data worker_result[NUM_THREADS];

/*
 **********************************************************************
 * Thread-safe test: concurrent dataset creation
 **********************************************************************
 */
void tts_dcreate(void)
{
    /* thread-related declarations */
    H5TS_thread_t worker_threads[NUM_THREADS];
    /* HDF5 object identifiers */
    hid_t file_id, dataset_id;
    int element_value, loop_index;
    H5TS_attr_t thread_attributes;
    int status;

    /* initialize pthread attributes for global scheduling */
    H5TS_attr_init(&thread_attributes);
    /* enforce system-wide thread scope if supported */
#ifdef H5_HAVE_SYSTEM_SCOPE_THREADS
    H5TS_attr_setscope(&thread_attributes, H5TS_SCOPE_SYSTEM);
#endif /* H5_HAVE_SYSTEM_SCOPE_THREADS */

    /*
     * Create an HDF5 file with truncation mode and default properties
     */
    file_id = H5Fcreate(FILENAME, H5F_ACC_TRUNC, H5P_DEFAULT, H5P_DEFAULT);
    assert(file_id >= 0);

    /* spawn threads to concurrently create datasets */
    for(loop_index = 0; loop_index < NUM_THREADS; loop_index++) {
        worker_result[loop_index].index = loop_index;
        worker_result[loop_index].file_id = file_id;
        worker_result[loop_index].dataset_label = dataset_label[loop_index];
        worker_threads[loop_index] = H5TS_create_thread(tts_dcreate_worker, NULL, &worker_result[loop_index]);
    }

    /* wait for all worker threads to complete */
    for(loop_index = 0; loop_index < NUM_THREADS; loop_index++) {
        H5TS_wait_for_thread(worker_threads[loop_index]);
    }

    /* verify correctness of created datasets */
    for(loop_index = 0; loop_index < NUM_THREADS; loop_index++) {
        if((dataset_id = H5Dopen2(file_id, dataset_label[loop_index], H5P_DEFAULT)) < 0) {
            TestErrPrintf("Dataset label not found - verification failed\n");
            H5Fclose(file_id);
            return;
        } else {
            status = H5Dread(dataset_id, H5T_NATIVE_INT, H5S_ALL, H5S_ALL, H5P_DEFAULT, &element_value);
            assert(status >= 0);
            if(element_value != loop_index) {
                TestErrPrintf("Incorrect value %d for dataset '%s' - verification failed\n",
                            element_value, dataset_label[loop_index]);
                status = H5Dclose(dataset_id);
                assert(status >= 0);
                status = H5Fclose(file_id);
                assert(status >= 0);
                return;
            }
            status = H5Dclose(dataset_id);
            assert(status >= 0);
        }
    }

    /* release remaining resources */
    status = H5Fclose(file_id);
    assert(status >= 0);

    /* cleanup thread attributes */
    H5TS_attr_destroy(&thread_attributes);
}

void *tts_dcreate_worker(void *_worker_info)
{
    hid_t   space_id, dataset_id;
    herr_t  result;
    hsize_t dims[1]; /* dataset dimensions */
    struct worker_data info;

    memcpy(&info, _worker_info, sizeof(struct worker_data));

    /* define 1D dataspace with single element */
    dims[0] = 1;
    space_id = H5Screate_simple(1, dims, NULL);
    assert(space_id >= 0);

    /* create dataset in the shared file */
    dataset_id = H5Dcreate2(info.file_id, info.dataset_label,
                           H5T_NATIVE_INT, space_id, H5P_DEFAULT, H5P_DEFAULT, H5P_DEFAULT);
    assert(dataset_id >= 0);

    /* write dataset value */
    result = H5Dwrite(dataset_id, H5T_NATIVE_INT, H5S_ALL, H5S_ALL,
                      H5P_DEFAULT, &info.index);
    assert(result >= 0);

    /* release dataset and dataspace */
    result = H5Dclose(dataset_id);
    assert(result >= 0);
    result = H5Sclose(space_id);
    assert(result >= 0);

    return NULL;
}

void cleanup_dcreate(void)
{
    HDunlink(FILENAME);
}
#endif /* H5_HAVE_THREADSAFE */

