///
class PrintLoopPassWrapper : public LoopPass {
  raw_ostream &OutputStream;
  std::string Title;
public:
  static char ID;
  PrintLoopPassWrapper() : LoopPass(ID), OutputStream(dbgs()) {}
  PrintLoopPassWrapper(raw_ostream &OS, const std::string &Title)
      : LoopPass(ID), OutputStream(OS), Title(Title) {}
  void getAnalysisUsage(AnalysisUsage &AU) const override {
    AU.setPreservesAll();
  }
  bool runOnLoop(Loop *L, LPPassManager &) override {
    auto BlockIter = llvm::find_if(L->blocks(), [](BasicBlock *BB) { return BB; });
    if (BlockIter != L->blocks().end() &&
        isFunctionInPrintList((*BlockIter)->getParent()->getName())) {
      printLoop(*L, OutputStream, Title);
    }
    return false;
  }
  StringRef getPassName() const override { return "Print Loop IR"; }
};

