class EmbossEffect final : public TStandardRasterFx {
  FX_PLUGIN_DECLARATION(EmbossEffect)
  TRasterFxPort m_source;
  TDoubleParamP m_strength;
  TDoubleParamP m_angle;
  TDoubleParamP m_azimuth;
  TDoubleParamP m_blur;
public:
  EmbossEffect()
      : m_strength(0.7), m_angle(30.0), m_azimuth(120.0), m_blur(1.5) {
    m_blur->setMeasureName("fxLength");
    bindParam(this, "strength", m_strength);
    bindParam(this, "angle", m_angle);
    bindParam(this, "azimuth", m_azimuth);
    bindParam(this, "blur", m_blur);
    addInputPort("Input", m_source);
    m_strength->setValueRange(0.0, 1.0, 0.1);
    m_angle->setValueRange(0.0, 360.0);
    m_azimuth->setValueRange(0.0, 360.0);
    m_blur->setValueRange(0.0, 12.0);
  }
  ~EmbossEffect(){};

  bool doGetBBox(double frame, TRectD &bbox,
                 const TRenderSettings &settings) override {
    if (m_source.isConnected()) {
      bool result = m_source->doGetBBox(frame, bbox, settings);
      return result;
    } else {
      bbox = TRectD();
      return false;
    }
  }

  void transform(double frame, int port, const TRectD &outputRect,
                 const TRenderSettings &outInfo, TRectD &inputRect,
                 TRenderSettings &inInfo) override;

  void doCompute(TTile &tile, double frame, const TRenderSettings &ri) override;

  int getMemoryRequirement(const TRectD &rect, double frame,
                           const TRenderSettings &info) override;

  bool canHandle(const TRenderSettings &info, double frame) override {
    return (isAlmostIsotropic(info.m_affine));
  }
};

//-------------------------------------------------------------------
template <typename PIXEL, typename PIXELGRAY, typename CHANNEL_TYPE>
void applyEmbossEffect(TRasterPT<PIXEL> dst, TRasterPT<PIXEL> input, double azimuth,
                       double elevation, double strength, double blurRadius) {
  double Lx  = cos(azimuth) * cos(elevation) * PIXEL::maxChannelValue;
  double Ly  = sin(azimuth) * cos(elevation) * PIXEL::maxChannelValue;
  double Lz  = sin(elevation) * PIXEL::maxChannelValue;
  double Nz  = (8 * PIXEL::maxChannelValue) * (1 - strength);
  double Nz2 = Nz * Nz;
  int j, m, n;
  int padding            = (int)blurRadius + 1;
  double fractionalPart = blurRadius - (int)blurRadius;
  int wrap = input->getWrap();
  double nsComponent, ewComponent;
  double nsFracComp, ewFracComp;
  double dotProduct;
  double bgLevel = Lz;

  input->lock();
  dst->lock();

  for (j = padding; j < input->getLy() - padding; j++) {
    PIXEL *outputPixel = dst->pixels(j - padding);
    PIXEL *currentPixel = input->pixels(j) + padding;
    PIXEL *endOutput = outputPixel + dst->getLx();

    while (outputPixel < endOutput) {
      double intensityVal;

      // Compute gradient components using discrete differences
      nsComponent = 0;
      ewComponent = 0;

      for (m = 1; m < padding; m++)
        for (n = -m; n <= m; n++) {
          nsComponent += PIXELGRAY::from(*(currentPixel + m * wrap + n)).value;
          nsComponent -= PIXELGRAY::from(*(currentPixel - m * wrap + n)).value;
          ewComponent += PIXELGRAY::from(*(currentPixel + n * wrap + m)).value;
          ewComponent -= PIXELGRAY::from(*(currentPixel + n * wrap - m)).value;
        }

      // Handle fractional part of blur radius for smooth transitions
      nsFracComp = 0;
      ewFracComp = 0;
      for (n = -m; n <= m; n++) {
        nsFracComp += PIXELGRAY::from(*(currentPixel + m * wrap + n)).value;
        nsFracComp -= PIXELGRAY::from(*(currentPixel - m * wrap + n)).value;
        ewFracComp += PIXELGRAY::from(*(currentPixel + n * wrap + m)).value;
        ewFracComp -= PIXELGRAY::from(*(currentPixel + n * wrap - m)).value;
      }

      nsComponent += nsFracComp * fractionalPart;
      ewComponent += ewFracComp * fractionalPart;

      // Normalize and compute lighting response
      double Nx = ewComponent;
      double Ny = nsComponent;
      Nx /= blurRadius;
      Ny /= blurRadius;

      if (Nx == 0 && Ny == 0)
        intensityVal = bgLevel;
      else if ((dotProduct = Nx * Lx + Ny * Ly + Nz * Lz) < 0)
        intensityVal = 0;
      else
        intensityVal = dotProduct / sqrt(Nx * Nx + Ny * Ny + Nz2);

      outputPixel->r = (intensityVal < PIXEL::maxChannelValue)
                          ? (intensityVal > 0 ? (CHANNEL_TYPE)intensityVal : 0)
                          : PIXEL::maxChannelValue;
      outputPixel->g = outputPixel->r;
      outputPixel->b = outputPixel->r;
      outputPixel->m = currentPixel->m;
      *outputPixel = premultiply(*outputPixel);

      currentPixel++;
      outputPixel++;
    }
  }

  input->unlock();
  dst->unlock();
}

//-------------------------------------------------------------------
void EmbossEffect::doCompute(TTile &tile, double frame, const TRenderSettings &ri) {
  if (!m_source.isConnected()) return;

  double min, max, step;
  m_blur->getValueRange(min, max, step);
  double scale     = sqrt(fabs(ri.m_affine.det()));
  double blurRadius = tcrop(m_blur->getValue(frame), min, max) * scale;
  double direction  = (m_azimuth->getValue(frame));
  double elevation  = (m_angle->getValue(frame)) * M_PI_180;
  double strength   = m_strength->getValue(frame);
  double azimuth    = direction * M_PI_180;

  int padding = blurRadius + 1;
  TRasterP srcRas =
      tile.getRaster()->create(tile.getRaster()->getLx() + padding * 2,
                               tile.getRaster()->getLy() + padding * 2);
  TTile srcTile(srcRas, tile.m_pos - TPointD(padding, padding));
  m_source->compute(srcTile, frame, ri);

  TRaster32P raster32    = tile.getRaster();
  TRaster32P srcraster32 = srcTile.getRaster();

  if (raster32)
    applyEmbossEffect<TPixel32, TPixelGR8, UCHAR>(raster32, srcraster32, azimuth,
                                                  elevation, strength, blurRadius);
  else {
    TRaster64P raster64    = tile.getRaster();
    TRaster64P srcraster64 = srcTile.getRaster();
    if (raster64)
      applyEmbossEffect<TPixel64, TPixelGR16, USHORT>(raster64, srcraster64, azimuth,
                                                      elevation, strength, blurRadius);
    else
      throw TException("Emboss: unsupported Pixel Type");
  }
}

//------------------------------------------------------------------
void EmbossEffect::transform(double frame, int port, const TRectD &outputRect,
                             const TRenderSettings &outInfo,
                             TRectD &inputRect, TRenderSettings &inInfo) {
  inInfo = outInfo;
  double min, max, step;
  m_blur->getValueRange(min, max, step);
  double scale  = sqrt(fabs(outInfo.m_affine.det()));
  double blurRadius = (tcrop(m_blur->getValue(frame), min, max) * scale);
  int padding    = blurRadius + 1;
  inputRect = outputRect.enlarge(padding);
}

//------------------------------------------------------------------
int EmbossEffect::getMemoryRequirement(const TRectD &rect, double frame,
                                       const TRenderSettings &info) {
  double scale  = sqrt(fabs(info.m_affine.det()));
  double blurRadius = m_blur->getValue(frame) * scale;
  int padding    = blurRadius + 1;
  return TRasterFx::memorySize(rect.enlarge(padding), info.m_bpp);
}

