#include <bits/stdc++.h>
using namespace std;

const int MAX_NODES = 1005;
int numNodes;
vector<int> parentNode;
vector<vector<int>> childList;
vector<int> representative;

// Query function: asks about the median node among three nodes
int query(int x, int y, int z) {
    cout << "0 " << x << " " << y << " " << z << endl;
    int answer;
    cin >> answer;
    return answer;
}

// Determine which direct child of node 'node' contains 'target', or -1 if none
int locateChild(int node, int target) {
    vector<int>& children = childList[node];
    if (children.empty()) return -1;

    vector<int> candidates = children;
    while (!candidates.empty()) {
        if (candidates.size() == 1) {
            int child = candidates[0];
            int result = query(node, representative[child], target);
            if (result == representative[child]) return child;
            else return -1;
        }

        // Divide candidates into two halves
        int mid = candidates.size() / 2;
        vector<int> firstHalf(candidates.begin(), candidates.begin() + mid);
        vector<int> secondHalf(candidates.begin() + mid, candidates.end());

        int repA = representative[firstHalf[0]];
        int repB = representative[secondHalf[0]];
        int res = query(repA, repB, target);

        if (res == repA) {
            candidates = firstHalf;
        } else if (res == repB) {
            candidates = secondHalf;
        } else if (res == node) {
            return -1;  // target not in any child within candidates
        } else {
            // Unexpected case
            assert(false);
        }
    }
    return -1;
}

// Insert node 'newNode' into tree with given root
void addNode(int newNode, int rootNode) {
    int current = rootNode;
    while (true) {
        int childIndex = locateChild(current, newNode);
        if (childIndex == -1) {
            // Attach newNode as a new child of current
            parentNode[newNode] = current;
            childList[current].push_back(newNode);
            representative[newNode] = newNode;
            break;
        } else {
            current = childIndex;
        }
    }
}

int main() {
    cin >> numNodes;

    // Initialize data structures
    parentNode.assign(numNodes + 1, -1);
    childList.resize(numNodes + 1);
    representative.resize(numNodes + 1);

    // Create shuffled list of nodes for insertion order
    vector<int> nodeOrder;
    for (int i = 1; i <= numNodes; ++i) {
        nodeOrder.push_back(i);
    }
    random_shuffle(nodeOrder.begin(), nodeOrder.end());

    int root = nodeOrder[0];
    representative[root] = root;

    // Insert remaining nodes
    for (int idx = 1; idx < numNodes; ++idx) {
        addNode(nodeOrder[idx], root);
    }

    // Output the constructed tree edges
    cout << "1";
    for (int i = 1; i <= numNodes; ++i) {
        if (parentNode[i] != -1) {
            cout << " " << parentNode[i] << " " << i;
        }
    }
    cout << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    cin >> size;

    vector<int> arr(size + 1), indexMap(size + 1);
    for (int idx = 1; idx <= size; idx++) {
        cin >> arr[idx];
        indexMap[arr[idx]] = idx;
    }

    int mode = (size <= 2 ? 1 : 3); // mode=3 allows operations of lengths 2 and 4; mode=1 only length 2
    vector<pair<int, int>> operations;
    operations.reserve(200000);

    auto apply_reverse = [&](int left, int right) {
        while (left < right) {
            int valLeft = arr[left], valRight = arr[right];
            swap(arr[left], arr[right]);
            indexMap[valLeft] = right;
            indexMap[valRight] = left;
            left++;
            right--;
        }
    };

    if (mode == 1) {
        // Only for size <= 2: use adjacent swaps
        for (int target = 1; target <= size; target++) {
            while (indexMap[target] > target) {
                int pos = indexMap[target];
                operations.push_back({pos - 1, pos});
                apply_reverse(pos - 1, pos);
            }
        }
    } else {
        // mode == 3: allow reversals of length 2 and 4
        for (int target = 1; target <= size; target++) {
            while (indexMap[target] >= target + 3) {
                int pos = indexMap[target];
                operations.push_back({pos - 3, pos}); // reversal of length 4
                apply_reverse(pos - 3, pos);
            }
            while (indexMap[target] > target) {
                int pos = indexMap[target];
                operations.push_back({pos - 1, pos}); // reversal of length 2
                apply_reverse(pos - 1, pos);
            }
        }
    }

    cout << mode << "\n";
    cout << (int)operations.size() << "\n";
    for (auto &op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

