retrieve_bucket(PyInterpreterState *interp, uintptr_t thread_id)
{
    return &interp->brc.table[thread_id % _Py_BRC_NUM_BUCKETS];
}

// Search for a thread state within a hash bucket using its thread ID.
static _PyThreadStateImpl *
locate_thread_state(struct _brc_bucket *bucket, uintptr_t target_tid)
{
    struct llist_node *node;
    llist_for_each(node, &bucket->root) {
        // Extract the containing _PyThreadStateImpl from the linked-list node.
        _PyThreadStateImpl *ts = llist_data(node, _PyThreadStateImpl,
                                            brc.bucket_node);
        if (ts->brc.tid == target_tid) {
            return ts;
        }
    }
    return NULL;
}

// Add an object to the queue for merging by its owning thread. This consumes
// a reference to the object.
void
_Py_brc_enqueue_object(PyObject *obj)
{
    PyInterpreterState *interp = _PyInterpreterState_GET();
    uintptr_t obj_tid = _Py_atomic_load_uintptr(&obj->ob_tid);
    if (obj_tid == 0) {
        // The owner thread may have concurrently decided to merge refcounts.
        Py_DECREF(obj);
        return;
    }

    struct _brc_bucket *bucket = retrieve_bucket(interp, obj_tid);
    PyMutex_Lock(&bucket->mutex);

    _PyThreadStateImpl *tstate = locate_thread_state(bucket, obj_tid);
    if (tstate == NULL) {
        // If the owner thread is no longer present, it must have already exited.
        // It's safe (and necessary) to merge the refcount. Subtract one since
        // we've consumed a reference.
        Py_ssize_t refcount = _Py_ExplicitMergeRefcount(obj, -1);
        PyMutex_Unlock(&bucket->mutex);
        if (refcount == 0) {
            _Py_Dealloc(obj);
        }
        return;
    }

    if (_PyObjectStack_Push(&tstate->brc.objects_to_merge, obj) < 0) {
        PyMutex_Unlock(&bucket->mutex);
        // Fallback: halt all threads and manually merge the refcount
        // if queuing fails.
        _PyEval_StopTheWorld(interp);
        Py_ssize_t refcount = _Py_ExplicitMergeRefcount(obj, -1);
        _PyEval_StartTheWorld(interp);
        if (refcount == 0) {
            _Py_Dealloc(obj);
        }
        return;
    }

    // Signal the owning thread
    _Py_set_eval_breaker_bit(&tstate->base, _PY_EVAL_EXPLICIT_MERGE_BIT);
    PyMutex_Unlock(&bucket->mutex);
}

// Process all objects in the provided stack for merging.
static void
process_stack_of_objects(_PyObjectStack *stack)
{
    PyObject *obj;
    while ((obj = _PyObjectStack_Pop(stack)) != NULL) {
        // Subtract one because the queue held a reference.
        Py_ssize_t refcount = _Py_ExplicitMergeRefcount(obj, -1);
        if (refcount == 0) {
            _Py_Dealloc(obj);
        }
    }
}

// Handle this thread's pending objects for refcount merging.
void
_Py_brc_process_refcounts(PyThreadState *tstate)
{
    struct _brc_thread_state *brc = &((_PyThreadStateImpl *)tstate)->brc;
    struct _brc_bucket *bucket = retrieve_bucket(tstate->interp, brc->tid);
    assert(brc->tid == _Py_ThreadId());

    // Transfer all queued objects into a local stack. We avoid holding the
    // lock during destructor calls.
    PyMutex_Lock(&bucket->mutex);
    _PyObjectStack_Merge(&brc->local_objects_to_merge, &brc->objects_to_merge);
    PyMutex_Unlock(&bucket->mutex);

    // Drain the local stack until empty.
    process_stack_of_objects(&brc->local_objects_to_merge);
}

// Initialize per-interpreter BRC state.
void
_Py_brc_setup_state(PyInterpreterState *interp)
{
    struct _brc_state *brc = &interp->brc;
    for (Py_ssize_t idx = 0; idx < _Py_BRC_NUM_BUCKETS; idx++) {
        llist_init(&brc->table[idx].root);
    }
}

// Initialize per-thread BRC state upon thread creation.
void
_Py_brc_setup_thread(PyThreadState *tstate)
{
    struct _brc_thread_state *brc = &((_PyThreadStateImpl *)tstate)->brc;
    uintptr_t tid = _Py_ThreadId();

    // Insert ourself into the hash table.
    struct _brc_bucket *bucket = retrieve_bucket(tstate->interp, tid);
    PyMutex_Lock(&bucket->mutex);
    brc->tid = tid;
    llist_insert_tail(&bucket->root, &brc->bucket_node);
    PyMutex_Unlock(&bucket->mutex);
}

// Clean up BRC state when a thread exits.
void
_Py_brc_cleanup_thread(PyThreadState *tstate)
{
    struct _brc_thread_state *brc = &((_PyThreadStateImpl *)tstate)->brc;
    if (brc->tid == 0) {
        // Thread was created but never bound to a native thread, so not in table.
        assert(tstate->_status.bound == 0);
        return;
    }

    struct _brc_bucket *bucket = retrieve_bucket(tstate->interp, brc->tid);

    // Fully drain any pending merges before removing ourselves from the table.
    bool drained = false;
    while (!drained) {
        process_stack_of_objects(&brc->local_objects_to_merge);
        PyMutex_Lock(&bucket->mutex);
        drained = (brc->objects_to_merge.head == NULL);
        if (drained) {
            llist_remove(&brc->bucket_node);
        } else {
            _PyObjectStack_Merge(&brc->local_objects_to_merge,
                                 &brc->objects_to_merge);
        }
        PyMutex_Unlock(&bucket->mutex);
    }

    assert(brc->local_objects_to_merge.head == NULL);
    assert(brc->objects_to_merge.head == NULL);
}

// Reset mutexes after a fork.
void
_Py_brc_reinit_after_fork(PyInterpreterState *interp)
{
    // Release all bucket locks. Some may be locked due to lock handoff to
    // parked threads (see lock.c). Consistency isn't at risk since no active
    // modifications occur, though threads might be paused on a lock.
    for (Py_ssize_t idx = 0; idx < _Py_BRC_NUM_BUCKETS; idx++) {
        _PyMutex_at_fork_reinit(&interp->brc.table[idx].mutex);
    }
}

