#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
using namespace std;

int performQuery(const vector<int>& queryVec) {
    cout << "?";
    for (int val : queryVec) cout << " " << val;
    cout << endl;

    int result;
    cin >> result;
    if (result == -1) exit(0);
    return result;
}

void processCase() {
    int size;
    cin >> size;

    // Output initial response
    cout << 1 << endl;

    vector<int> permutation(size + 1, 0);
    vector<int> uncertainNodes;
    vector<int> confirmedNodes;

    mt19937 generator(42);

    // Step 1: Determine regular nodes and their mappings
    // For each position u, attempt to find permutation[u] using binary search
    // If consistently getting D=0, mark as potential 2-cycle node

    for (int pos = 1; pos <= size; ++pos) {
        vector<int> possibleValues;
        for (int idx = 1; idx <= size; ++idx) {
            if (idx != pos) possibleValues.push_back(idx);
        }
        bool isUncertain = false;

        while (possibleValues.size() > 1) {
            bool splitSuccess = false;
            int tries = 0;
            while (tries < 5) {
                tries++;
                vector<int> leftPart, rightPart;

                // Randomize order
                shuffle(possibleValues.begin(), possibleValues.end(), generator);
                int halfPoint = possibleValues.size() / 2;

                for (int i = 0; i < halfPoint; ++i) leftPart.push_back(possibleValues[i]);
                for (int i = halfPoint; i < possibleValues.size(); ++i) rightPart.push_back(possibleValues[i]);

                // Build query vectors
                vector<int> remaining;
                vector<bool> inLeft(size + 1, false);
                for (int val : leftPart) inLeft[val] = true;

                for (int num = 1; num <= size; ++num) {
                    if (num != pos && !inLeft[num]) remaining.push_back(num);
                }

                vector<int> queryA = remaining;
                queryA.push_back(pos);
                queryA.insert(queryA.end(), leftPart.begin(), leftPart.end());

                vector<int> queryB = remaining;
                queryB.insert(queryB.end(), leftPart.begin(), leftPart.end());
                queryB.push_back(pos);

                int responseA = performQuery(queryA);
                int responseB = performQuery(queryB);
                int difference = responseA - responseB;

                if (difference == 1) {
                    // permutation[pos] in leftPart, inverse not in leftPart
                    possibleValues = leftPart;
                    splitSuccess = true;
                    break;
                } else if (difference == -1) {
                    // permutation[pos] not in leftPart (so in rightPart), inverse in leftPart
                    vector<int> updatedCandidates;
                    for(int item : possibleValues) {
                        if (!inLeft[item]) updatedCandidates.push_back(item);
                    }
                    possibleValues = updatedCandidates;
                    splitSuccess = true;
                    break;
                }
                // difference == 0: ambiguous or 2-cycle, try again
            }

            if (!splitSuccess) {
                // Always got 0, assume 2-cycle or inseparable
                // With 5 attempts, failure probability is low
                isUncertain = true;
                break;
            }
        }

        if (isUncertain) {
            uncertainNodes.push_back(pos);
        } else {
            permutation[pos] = possibleValues[0];
            confirmedNodes.push_back(pos);
        }
    }

    // Step 2: Resolve uncertain nodes (2-cycles)
    // We know permutation[u] is in uncertainNodes
    // Also know permutation[permutation[u]] = u

    vector<bool> handled(size + 1, false);
    for (int node : confirmedNodes) handled[node] = true;

    for (int node : uncertainNodes) {
        if (handled[node]) continue;

        // Find partner from uncertain nodes
        vector<int> candidates;
        for (int other : uncertainNodes) {
            if (other != node && !handled[other]) candidates.push_back(other);
        }

        if (candidates.empty()) break;

        // Binary search approach for finding partner
        while (candidates.size() > 1) {
            int midIndex = candidates.size() / 2;
            vector<int> subset;
            for (int i = 0; i < midIndex; ++i) subset.push_back(candidates[i]);

            // Build rest of elements
            vector<int> others;
            vector<bool> inSubset(size + 1, false);
            for(int val : subset) inSubset[val] = true;
            for(int i = 1; i <= size; ++i) {
                if (i != node && !inSubset[i]) others.push_back(i);
            }

            // Query 1: [node, others, subset]
            vector<int> query1;
            query1.push_back(node);
            query1.insert(query1.end(), others.begin(), others.end());
            query1.insert(query1.end(), subset.begin(), subset.end());

            // Query 2: [node, subset, others]
            vector<int> query2;
            query2.push_back(node);
            query2.insert(query2.end(), subset.begin(), subset.end());
            query2.insert(query2.end(), others.begin(), others.end());

            int internalPairs = performQuery(query1);
            int actualCount = performQuery(query2);
            int k = subset.size();

            if (actualCount == k - internalPairs - 1) {
                // Partner is in subset
                candidates = subset;
            } else {
                // Partner not in subset
                vector<int> newCandidates;
                for(int val : candidates) {
                    if (!inSubset[val]) newCandidates.push_back(val);
                }
                candidates = newCandidates;
            }
        }

        int partner = candidates[0];
        permutation[node] = partner;
        permutation[partner] = node;
        handled[node] = true;
        handled[partner] = true;
    }

    cout << "!";
    for (int idx = 1; idx <= size; ++idx) cout << " " << permutation[idx];
    cout << endl;
}

int main() {
    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            processCase();
        }
    }
    return 0;
}

