BoatModel::BoatModel() : Model() {
    parts[0] = new ModelPart(this, 0, 8);
    parts[1] = new ModelPart(this, 0, 0);
    parts[2] = new ModelPart(this, 0, 0);
    parts[3] = new ModelPart(this, 0, 0);
    parts[4] = new ModelPart(this, 0, 0);

    int width  = 24;
    int depth  = 6;
    int height = 20;
    int yOffset = 4;

    parts[0]->addBox((float)(-width / 2), (float)(-height / 2 + 2), -3, width, height - 4, 4, 0);
    parts[0]->setPos(0, (float)(0 + yOffset), 0);

    parts[1]->addBox((float)(-width / 2 + 2), (float)(-depth - 1), -1, width - 4, depth, 2, 0);
    parts[1]->setPos((float)(-width / 2 + 1), (float)(0 + yOffset), 0);

    parts[2]->addBox((float)(-width / 2 + 2), (float)(-depth - 1), -1, width - 4, depth, 2, 0);
    parts[2]->setPos((float)(+width / 2 - 1), (float)(0 + yOffset), 0);

    parts[3]->addBox((float)(-width / 2 + 2), (float)(-depth - 1), -1, width - 4, depth, 2, 0);
    parts[3]->setPos(0, (float)(0 + yOffset), (float)(-height / 2 + 1));

    parts[4]->addBox((float)(-width / 2 + 2), (float)(-depth - 1), -1, width - 4, depth, 2, 0);
    parts[4]->setPos(0, (float)(0 + yOffset), (float)(+height / 2 - 1));

