using asio::ip::tcp;

// Custom memory manager for handler allocation
// Stores a fixed-size buffer and falls back to heap when needed
class handler_storage
{
public:
  handler_storage()
    : occupied_(false)
  {
  }

  handler_storage(const handler_storage&) = delete;
  handler_storage& operator=(const handler_storage&) = delete;

  void* request_memory(std::size_t required_size)
  {
    if (!occupied_ && required_size < sizeof(buffer_))
    {
      occupied_ = true;
      return &buffer_;
    }
    else
    {
      return ::operator new(required_size);
    }
  }

  void release_memory(void* ptr)
  {
    if (ptr == &buffer_)
    {
      occupied_ = false;
    }
    else
    {
      ::operator delete(ptr);
    }
  }

private:
  // Pre-allocated storage space
  typename std::aligned_storage<2048>::type buffer_;
  // Flag indicating whether the storage is currently in use
  bool occupied_;
};

// Allocator class that works with the custom storage
template <typename T>
class custom_handler_allocator
{
public:
  using value_type = T;

  explicit custom_handler_allocator(handler_storage& storage)
    : storage_ref_(storage)
  {
  }

  template <typename U>
  custom_handler_allocator(const custom_handler_allocator<U>& other) noexcept
    : storage_ref_(other.storage_ref_)
  {
  }

  bool operator==(const custom_handler_allocator& other) const noexcept
  {
    return &storage_ref_ == &other.storage_ref_;
  }

  bool operator!=(const custom_handler_allocator& other) const noexcept
  {
    return &storage_ref_ != &other.storage_ref_;
  }

  T* allocate(std::size_t count) const
  {
    return static_cast<T*>(storage_ref_.request_memory(sizeof(T) * count));
  }

  void deallocate(T* pointer, std::size_t /*count*/) const
  {
    storage_ref_.release_memory(pointer);
  }

private:
  template <typename> friend class custom_handler_allocator;
  handler_storage& storage_ref_;
};

// Handler wrapper to integrate custom allocator with Asio operations
template <typename Handler>
class wrapped_handler_with_custom_alloc
{
public:
  using allocator_type = custom_handler_allocator<Handler>;

  wrapped_handler_with_custom_alloc(handler_storage& storage, Handler h)
    : storage_(storage),
      handler_(std::move(h))
  {
  }

  allocator_type get_allocator() const noexcept
  {
    return allocator_type(storage_);
  }

  template <typename... Args>
  void operator()(Args&&... args)
  {
    handler_(std::forward<Args>(args)...);
  }

private:
  handler_storage& storage_;
  Handler handler_;
};

// Convenience function to create a wrapped handler
template <typename Handler>
inline wrapped_handler_with_custom_alloc<Handler> wrap_handler_with_custom_alloc(
    handler_storage& storage, Handler handler)
{
  return wrapped_handler_with_custom_alloc<Handler>(storage, std::move(handler));
}

// Session class handling client communication
class connection_session
  : public std::enable_shared_from_this<connection_session>
{
public:
  connection_session(tcp::socket socket)
    : socket_(std::move(socket))
  {
  }

  void initiate()
  {
    perform_read();
  }

private:
  void perform_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(data_buffer_),
        wrap_handler_with_custom_alloc(storage_for_handler_,
          [this, self](std::error_code error_code, std::size_t bytes_transferred)
          {
            if (!error_code)
            {
              perform_write(bytes_transferred);
            }
          }));
  }

  void perform_write(std::size_t length)
  {
    auto self(shared_from_this());
    asio::async_write(socket_, asio::buffer(data_buffer_, length),
        wrap_handler_with_custom_alloc(storage_for_handler_,
          [this, self](std::error_code error_code, std::size_t /*bytes_written*/)
          {
            if (!error_code)
            {
              perform_read();
            }
          }));
  }

  tcp::socket socket_;
  std::array<char, 1024> data_buffer_;
  handler_storage storage_for_handler_;
};

// Server class accepting incoming connections
class server_instance
{
public:
  server_instance(asio::io_context& context, short port_number)
    : acceptor_(context, tcp::endpoint(tcp::v4(), port_number))
  {
    start_accepting();
  }

private:
  void start_accepting()
  {
    acceptor_.async_accept(
        [this](std::error_code ec, tcp::socket accepted_socket)
        {
          if (!ec)
          {
            std::make_shared<connection_session>(std::move(accepted_socket))->initiate();
          }
          start_accepting();
        });
  }

  tcp::acceptor acceptor_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: server <port>\n";
      return 1;
    }

    asio::io_context io_context;
    server_instance server(io_context, std::atoi(argv[1]));
    io_context.run();
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Error: " << exception.what() << "\n";
  }

  return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
#include <climits>
using namespace std;

class FlowerGarden {
public:
    // Helper function to determine the smallest and largest bloom days
    vector<int> getBloomRange(vector<int>& days) {
        int smallest = INT_MAX;
        int largest = INT_MIN;
        for(int i = 0; i < days.size(); i++) {
            if(days[i] > largest) {
                largest = days[i];
            }
            if(days[i] < smallest) {
                smallest = days[i];
            }
        }
        return {smallest, largest};
    }

    // Greedy helper: checks if we can make enough bouquets by a given day
    bool canProduceBouquets(vector<int>& days, int targetBouquets, int flowersPerBouquet, int limitDay) {
        int produced = 0;
        int currentStreak = 0;
        for (int bloom : days) {
            if (bloom <= limitDay) {
                currentStreak++;
                if (currentStreak == flowersPerBouquet) {
                    produced++;
                    currentStreak = 0; // Reset after completing a bouquet
                }
            } else {
                currentStreak = 0;
            }
        }
        return produced >= targetBouquets;
    }

    // Brute-force approach: check each day from min to max
    int findMinDaysBrute(vector<int>& days, int neededBouquets, int requiredFlowers) {
        long long totalNeeded = (long long)neededBouquets * requiredFlowers;
        if(totalNeeded > days.size()) {
            return -1;
        }

        vector<int> range = getBloomRange(days);
        int startDay = range[0];
        int endDay = range[1];

        // Linearly test each possible day
        for(int candidateDay = startDay; candidateDay <= endDay; candidateDay++) {
            if(canProduceBouquets(days, neededBouquets, requiredFlowers, candidateDay)) {
                return candidateDay;
            }
        }

        return -1;
    }

    // Optimized solution using binary search
    int findMinDaysOptimized(vector<int>& days, int neededBouquets, int requiredFlowers) {
        long long totalNeeded = (long long)neededBouquets * requiredFlowers;
        if(totalNeeded > days.size()) {
            return -1;
        }

        vector<int> range = getBloomRange(days);
        int left = range[0];
        int right = range[1];

        while(left < right) {
            int mid = left + (right - left) / 2;
            if(canProduceBouquets(days, neededBouquets, requiredFlowers, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }
};

int main() {
    vector<int> bloomSchedule = {7,7,7,7,12,7,7};
    int bouquetsNeeded = 2;
    int flowersPerBouquet = 3;

    FlowerGarden garden;
    int result = garden.findMinDaysOptimized(bloomSchedule, bouquetsNeeded, flowersPerBouquet); // Expected: 12

    cout << result << endl;
    return 0;
}

