#include "xh_core.h"
#include "xhook.h"

// Register a hook for the given symbol in modules matching pathname_regex_str
int xhook_register(const char* module_pattern, const char* func_name,
                   void* replacement_func, void** original_func_ptr) {
    return xh_core_register(module_pattern, func_name, replacement_func, original_func_ptr);
}

