void MCAsmInfoCOFF::anchor() {}

// Constructor for MCAsmInfoCOFF
MCAsmInfoCOFF::MCAsmInfoCOFF() {
  // MinGW 4.5 and newer support .comm with log2 alignment, but .lcomm uses byte alignment.
  COMMDirectiveAlignmentIsInBytes = true;
  LCOMMDirectiveAlignmentType = LCOMM::ByteAlignment;
  HasDotTypeDotSizeDirective = false;
  HasSingleParameterDotFile = true;
  WeakRefDirective = "\t.weak\t";
  AvoidWeakIfComdat = false;

  // Visibility attributes not supported:
  HiddenVisibilityAttr = HiddenDeclarationVisibilityAttr = MCSA_Invalid;
  ProtectedVisibilityAttr = MCSA_Invalid;

  // DWARF support setup
  SupportsDebugInformation = true;
  NeedsDwarfSectionOffsetDirective = true;

  // MSVC inline assembly uses arithmetic shift (AShr), so logical shift is disabled
  UseLogicalShr = true;

  // COFF targets typically support associative comdats per spec
  HasCOFFAssociativeComdats = true;

  // Constants in comdat sections can be shared, but require global symbols to avoid null-typed ones
  HasCOFFComdatConstants = true;
}

// Anchor function for MCAsmInfoMicrosoft
void MCAsmInfoMicrosoft::anchor() {}

// Constructor for MCAsmInfoMicrosoft
MCAsmInfoMicrosoft::MCAsmInfoMicrosoft() = default;

// Anchor function for MCAsmInfoGNUCOFF
void MCAsmInfoGNUCOFF::anchor() {}

// Constructor for MCAsmInfoGNUCOFF
MCAsmInfoGNUCOFF::MCAsmInfoGNUCOFF() {
  // For GNU environments (MinGW or Cygwin), disable associative comdats for jump tables,
  // unwind info, and other function-related data
  HasCOFFAssociativeComdats = false;

  // No constants in comdat sections for MinGW
  HasCOFFComdatConstants = false;
}

