#include "InputOutputStream.h"

// ByteArrayInputStream implementation - alternative version with modified identifiers

ByteArrayInputStream::ByteArrayInputStream(byteArray buffer, unsigned int start, unsigned int size)
	: currentPos(start), remainingCount(min(start + size, buffer.length)), markPosition(start)
{
	this->inputBuffer = buffer;
}

// Alternate constructor: initializes stream from entire buffer
ByteArrayInputStream::ByteArrayInputStream(byteArray buffer)
	: currentPos(0), remainingCount(buffer.length), markPosition(0)
{
	this->inputBuffer = buffer;
}

// Reads single byte; returns value in [0,255] or -1 if EOF
int ByteArrayInputStream::read()
{
	if (currentPos >= remainingCount)
		return -1;
	else
		return inputBuffer[currentPos++];
}

// Reads into provided array b (equivalent to read(b, 0, b.length))
int ByteArrayInputStream::read(byteArray destination)
{
	return read(destination, 0, destination.length);
}

// Reads up to length bytes into destination array starting at offset
int ByteArrayInputStream::read(byteArray destination, unsigned int destOffset, unsigned int maxLength)
{
	if (currentPos == remainingCount)
		return -1;

	int bytesRead = min(maxLength, remainingCount - currentPos);
	XMemCpy(&destination[destOffset], &inputBuffer[currentPos], bytesRead);
	currentPos += bytesRead;
	return bytesRead;
}

// No-op close operation – stream remains usable after closing
void ByteArrayInputStream::close()
{
	return;
}

// Skips n bytes forward; returns actual number skipped
__int64 ByteArrayInputStream::skip(__int64 skipAmount)
{
	__int64 newLocation = currentPos + skipAmount;
	if (newLocation > remainingCount) 
		newLocation = remainingCount;

	__int64 actuallySkipped = newLocation - currentPos;
	currentPos = static_cast<unsigned int>(newLocation);
	return actuallySkipped;
}

ByteArrayInputStream::~ByteArrayInputStream()
{
	if (inputBuffer.data != NULL)
		delete[] inputBuffer.data;
}

#include "ReduceUsingSimplifyCFG.h"
#include "llvm/Analysis/TargetTransformInfo.h"
#include "llvm/IR/Constants.h"
#include "llvm/IR/Instructions.h"
#include "llvm/Transforms/Utils/Local.h"

using namespace llvm;

static void reduceUsingSimplifyCFG(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();
  SmallVector<BasicBlock *, 16> BlocksToProcess;

  for (auto &Function : Program) {
    for (auto &Block : Function) {
      if (!O.shouldKeep()) {
        BlocksToProcess.push_back(&Block);
      }
    }
  }

  TargetTransformInfo TTI(Program.getDataLayout());
  for (auto *BB : BlocksToProcess) {
    simplifyCFG(BB, TTI);
  }
}

void llvm::reduceUsingSimplifyCFGDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, reduceUsingSimplifyCFG, "Reducing using SimplifyCFG");
}

static void reduceConditionals(Oracle &O, ReducerWorkItem &WorkItem,
                               bool Direction) {
  Module &M = WorkItem.getModule();
  SmallVector<BasicBlock *, 16> BlocksToSimplify;

  for (auto &F : M) {
    for (auto &BB : F) {
      auto *BR = dyn_cast<BranchInst>(BB.getTerminator());
      if (!BR || !BR->isConditional() || O.shouldKeep()) {
        continue;
      }

      if (Direction) {
        BR->setCondition(ConstantInt::getTrue(BR->getContext()));
      } else {
        BR->setCondition(ConstantInt::getFalse(BR->getContext()));
      }
      BlocksToSimplify.push_back(&BB);
    }
  }

  TargetTransformInfo TTI(M.getDataLayout());
  for (auto *BB : BlocksToSimplify) {
    simplifyCFG(BB, TTI);
  }
}

void llvm::reduceConditionalsTrueDeltaPass(TestRunner &Test) {
  runDeltaPass(
      Test,
      [](Oracle &O, ReducerWorkItem &WorkItem) {
        reduceConditionals(O, WorkItem, true);
      },
      "Reducing conditional branches to true");
}

void llvm::reduceConditionalsFalseDeltaPass(TestRunner &Test) {
  runDeltaPass(
      Test,
      [](Oracle &O, ReducerWorkItem &WorkItem) {
        reduceConditionals(O, WorkItem, false);
      },
      "Reducing conditional branches to false");
}

#include "llvm/Analysis/MemoryBuiltins.h"
#include "llvm/IR/Instructions.h"
