#include "Optimization/PE/LLPE.h"
using namespace llvm;

// Determine whether this specialization context should be finalized (true) or merely advisory (false)
bool InlineAttempt::isActive() {
  if (!Callers.empty()) { // Not root function: check conditions
    if (isPathCondition) // Path condition functions are symbolic and produce no runtime code
      return false;
    else
      return isShared() || active;
  }
  return true; // Root function is always active
}

// Loop iterations are always active if their parent loop is.
bool PeelIteration::isActive() { return true; }
bool PeelAttempt::isActive() { return active; }

// Attempt to set the active (commit) status to 'val'
void InlineAttempt::setActive(bool val, bool skipStats) {
  // Root function cannot be deactivated
  if (Callers.empty())
    return;
  // Shared functions cannot currently be deactivated
  if (isShared())
    return;
  // Path conditions never get committed anyway
  if (isPathCondition)
    return;
  active = val;
  if (!skipStats)
    pass->getRoot()->gatherStats();
}

void PeelIteration::setActive(bool val, bool skipStats) {
  assert(0 && "Cannot selectively disable individual iterations yet");
}

void PeelAttempt::setActive(bool val, bool skipStats) { active = val; }

// Will this specialization context commit in a separate residual function from its parent?
bool InlineAttempt::commitsSeparately() {
  // No parent at all — must commit separately
  if (isRootMainCall())
    return true;

  for (SmallVector<ShadowInstruction *, 1>::iterator iter = Callers.begin(),
                                                     iter_end = Callers.end();
       iter != iter_end; ++iter) {
    // If this function has a CommitF but its parent doesn't, it implies this context was committed
    // before the parent acquired its commit function, and we inherited it implicitly.
    if (CommitF && (*iter)->parent->IA->getFunctionRoot()->CommitF != CommitF)
      return true;
  }
  return false;
}

// Loop iterations always commit in the same function as their immediate parent.
bool PeelIteration::commitsSeparately() { return false; }

// Return true if this function *must* be committed as a residual function
// rather than being inlined everywhere as usual.
// Note: It might still commit out-of-line even if not strictly required,
// e.g., to keep residual function sizes manageable for standard optimizations.
// SaveSplit.cpp handles such decisions.
bool InlineAttempt::mustCommitSeparately() {
  // Root function naturally requires its own residual function
  if (isRootMainCall())
    return true;

  // Vararg functions: we currently don’t rewrite vararg intrinsics,
  // and Dragonegg exposes va_list handling directly, so we need a real va_list.
  if (F.isVarArg())
    return true;

  // Shared functions require out-of-line commitment for multiple callers.
  // (Note: this functionality may be outdated.)
  if (isShared())
    return true;

  // Has the user explicitly marked this as a split point?
  if (pass->splitFunctions.count(&F))
    return true;

  // Unclear why this is needed — possibly missing logic to insert
  // fallback-to-unspecialized-code flags and post-invoke checks?
  if (hasFailedReturnPath()) {
    for (uint32_t idx = 0, limit = Callers.size(); idx != limit; ++idx) {
      if (inst_isa<InvokeInst>(Callers[idx]))
        return true;
    }
  }
  return false;
}

bool PeelIteration::mustCommitSeparately() { return false; }

bool IntegrationAttempt::allAncestorsActive() {
  // Not active?
  if (!isActive())
    return false;

  // Not getting inlined/unrolled at all?
  // Note on use of getUniqueParent: this function determines whether a user
  // can refer to a heap object allocated in a given context.
  // Contexts where allocations escape are unsharable, so if getUniqueParent fails,
  // we’re in a shared function where the allocation doesn’t escape — thus the user
  // context is equal to or a child of this one. Safe to return true:
  // either both committed (use OK) or both uncommitted (no impact).
  IntegrationAttempt *ancestor = getUniqueParent();
  if (ancestor && !ancestor->allAncestorsActive())
    return false;

  return true;
}

