DoubleIntegratorInterface::DoubleIntegratorInterface(const std::string& configPath, const std::string& libDir, bool verbose) {
  // Verify that the configuration file exists
  boost::filesystem::path configFile(configPath);
  if (boost::filesystem::exists(configFile)) {
    std::cerr << "[DoubleIntegratorInterface] Reading configuration from: " << configFile << std::endl;
  } else {
    throw std::invalid_argument("[DoubleIntegratorInterface] Configuration file not found: " + configFile.string());
  }

  // Ensure the library directory exists
  boost::filesystem::path libPath(libDir);
  boost::filesystem::create_directories(libPath);
  std::cerr << "[DoubleIntegratorInterface] Output library directory: " << libPath << std::endl;

  // Load default initial state and target goal
  loadData::loadEigenMatrix(configPath, "initialState", initialState_);
  loadData::loadEigenMatrix(configPath, "finalGoal", finalGoal_);

  // Configure DDP-MPC parameters
  ddpSettings_ = ddp::loadSettings(configPath, "ddp", verbose);
  mpcSettings_ = mpc::loadSettings(configPath, "mpc", verbose);

  /*
   * ReferenceManager & SolverSynchronizedModule
   */
  referenceManagerPtr_.reset(new ReferenceManager);

  /*
   * Optimal control problem formulation
   */
  // Define cost matrices
  matrix_t Qmat(STATE_DIM, STATE_DIM);
  matrix_t Rmat(INPUT_DIM, INPUT_DIM);
  matrix_t Qfmat(STATE_DIM, STATE_DIM);
  loadData::loadEigenMatrix(configPath, "Q", Qmat);
  loadData::loadEigenMatrix(configPath, "R", Rmat);
  loadData::loadEigenMatrix(configPath, "Q_final", Qfmat);

  std::cerr << "Q:  \n" << Qmat << "\n";
  std::cerr << "R:  \n" << Rmat << "\n";
  std::cerr << "Q_final:\n" << Qfmat << "\n";

  problem_.costPtr->add("stage_cost", std::make_unique<QuadraticStateInputCost>(Qmat, Rmat));
  problem_.finalCostPtr->add("terminal_cost", std::make_unique<QuadraticStateCost>(Qfmat));

  // System dynamics
  const matrix_t A_dyn = (matrix_t(STATE_DIM, STATE_DIM) << 0.0, 1.0, 0.0, 0.0).finished();
  const matrix_t B_dyn = (matrix_t(STATE_DIM, INPUT_DIM) << 0.0, 1.0).finished();
  problem_.dynamicsPtr.reset(new LinearSystemDynamics(A_dyn, B_dyn));

  // Rollout configuration
  auto rolloutParams = rollout::loadSettings(configPath, "rollout", verbose);
  rolloutPtr_.reset(new TimeTriggeredRollout(*problem_.dynamicsPtr, rolloutParams));

  // Initialization strategy
  linearSystemInitializerPtr_.reset(new DefaultInitializer(INPUT_DIM));
}

