#include "autowakemanager.h"
#include "settings.h"
#include <QDateTime>
#include <QDebug>

// AutoWakeManager: Manages scheduled automatic wake-up times
AutoWakeManager::AutoWakeManager(Settings* config, QObject* ancestor)
    : QObject(ancestor)
    , m_settings(config)
    , m_timer(new QTimer(this))
{
    m_timer->setSingleShot(true);
    connect(m_timer, &QTimer::timeout, this, &AutoWakeManager::handleTimeout);

    // Reset schedule when user modifies auto-wake configuration
    connect(m_settings, &Settings::autoWakeScheduleChanged, this, [this]() {
        qDebug() << "AutoWakeManager: Configuration updated, recalculating schedule";
        m_triggeredDates.clear();
        computeNextEvent();
    });
}

void AutoWakeManager::handleTimeout() {
    qDebug() << "AutoWakeManager: *** SCHEDULED WAKE EVENT TRIGGERED ***";

    // Record today's date as having triggered for this weekday
    QDate current = QDate::currentDate();
    int weekdayIndex = current.dayOfWeek() - 1;
    m_triggeredDates[weekdayIndex] = current;

    emit wakeRequested();

    // Plan the following wake event
    computeNextEvent();
}

void AutoWakeManager::computeNextEvent() {
    m_timer->stop();
    QDateTime currentTime = QDateTime::currentDateTime();
    QVariantList weeklyPlan = m_settings->autoWakeSchedule();

    static const char* weekdayLabels[] = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"};

    // Search for next wake opportunity within next 7 days maximum
    qint64 shortestDelay = -1;
    int selectedDay = -1;
    QTime selectedTime;

    for (int offsetDays = 0; offsetDays < 7; ++offsetDays) {
        QDate testDate = currentTime.date().addDays(offsetDays);
        int dayIndex = testDate.dayOfWeek() - 1; // Convert Qt weekday (1-7) to array index (0-6)

        if (dayIndex < 0 || dayIndex >= weeklyPlan.size()) continue;

        QVariantMap dailySettings = weeklyPlan[dayIndex].toMap();
        if (!dailySettings.value("active", false).toBool()) continue;

        int targetHour = dailySettings.value("hour", 7).toInt();
        int targetMinute = dailySettings.value("minute", 0).toInt();
        QDateTime proposedTime(testDate, QTime(targetHour, targetMinute, 1));

        // Ignore past times or already-triggered instances today
        if (proposedTime <= currentTime) continue;
        if (m_triggeredDates.value(dayIndex) == testDate) continue;

        qint64 delayMs = currentTime.msecsTo(proposedTime);
        if (shortestDelay < 0 || delayMs < shortestDelay) {
            shortestDelay = delayMs;
            selectedDay = dayIndex;
            selectedTime = QTime(targetHour, targetMinute);
        }

        // Early exit since we process days sequentially and want earliest match
        break;
    }

    if (shortestDelay > 0) {
        int totalSeconds = shortestDelay / 1000;
        int hoursPart = totalSeconds / 3600;
        int minutesPart = (totalSeconds % 3600) / 60;
        int secondsPart = totalSeconds % 60;

        QString formattedDuration;
        if (hoursPart > 0) {
            formattedDuration = QString("%1h %2m").arg(hoursPart).arg(minutesPart);
        } else if (minutesPart > 0) {
            formattedDuration = QString("%1m %2s").arg(minutesPart).arg(secondsPart);
        } else {
            formattedDuration = QString("%1s").arg(secondsPart);
        }

        qDebug() << "AutoWakeManager: Next event:" << weekdayLabels[selectedDay]
                 << selectedTime.toString("HH:mm") << "in" << formattedDuration;
        m_timer->start(shortestDelay);
    } else {
        qDebug() << "AutoWakeManager: No active wake schedules found";
    }
}

void AutoWakeManager::activate() {
    qDebug() << "AutoWakeManager: Initialization complete";
    computeNextEvent();
}

void AutoWakeManager::deactivate() {
    qDebug() << "AutoWakeManager: Shutdown initiated";
    m_timer->stop();
}

