#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;

    // Use 1 as our anchor point for comparisons
    int anchor = 1;
    int low = 2, high = N;

    // Binary search to find the matching parenthesis for anchor
    while (low < high) {
        int segment_size = high - low + 1;
        int half_segment = min(500, segment_size / 2);
        int mid_right = low + half_segment - 1;

        vector<int> test_sequence;
        test_sequence.push_back(anchor);
        for (int idx = low; idx <= mid_right; idx++) {
            test_sequence.push_back(idx);
            test_sequence.push_back(anchor);
        }

        int seq_len = test_sequence.size();
        cout << "0 " << seq_len;
        for (int val : test_sequence) {
            cout << " " << val;
        }
        cout << endl;
        cout.flush();

        int response;
        cin >> response;

        if (response > 0) {
            high = mid_right;
        } else {
            low = mid_right + 1;
        }
    }

    // Determine the matching parenthesis for our anchor
    int candidate = low;
    cout << "0 3 " << anchor << " " << candidate << " " << anchor << endl;
    cout.flush();

    int answer;
    cin >> answer;

    int open_pos, close_pos;
    if (answer == 1) {
        open_pos = anchor;
        close_pos = candidate;
    } else {
        open_pos = candidate;
        close_pos = anchor;
    }

    // Build result string
    string result(N + 1, ' ');
    result[open_pos] = '(';
    result[close_pos] = ')';

    // Collect remaining positions that need assignment
    vector<int> remaining_indices;
    for (int i = 1; i <= N; i++) {
        if (result[i] == ' ') {
            remaining_indices.push_back(i);
        }
    }

    // Process remaining positions in groups of up to 9
    int index = 0;
    while (index < remaining_indices.size()) {
        int group_size = min(10, (int)remaining_indices.size() - index);
        vector<int> current_group;
        for (int j = 0; j < group_size; j++) {
            current_group.push_back(remaining_indices[index + j]);
        }

        // Build query sequence for this group
        vector<int> query_seq;
        for (int bit = 0; bit < group_size; bit++) {
            int count = 1 << bit;
            for (int step = 0; step < count; step++) {
                query_seq.push_back(current_group[bit]);
                query_seq.push_back(close_pos);
            }
            query_seq.push_back(close_pos);
        }

        int query_length = query_seq.size();
        cout << "0 " << query_length;
        for (int val : query_seq) {
            cout << " " << val;
        }
        cout << endl;
        cout.flush();

        int result_value;
        cin >> result_value;
        int temp = result_value;

        // Decode results from most significant bit to least
        for (int bit = group_size - 1; bit >= 0; bit--) {
            int count = 1 << bit;
            int contribution = count * (count + 1) / 2;

            if (temp >= contribution) {
                result[current_group[bit]] = '(';
                temp -= contribution;
            } else {
                result[current_group[bit]] = ')';
            }
        }

        index += group_size;
    }

    // Output final answer
    cout << "1";
    for (int i = 1; i <= N; i++) {
        cout << result[i];
    }
    cout << endl;
    cout.flush();

    return 0;
}

#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/div.h"
#include "jemalloc/internal/assert.h"

/*
 * Given n = q * d (all integers), and known values of n and d, our goal is to
 * compute q = n / d efficiently using multiplication and bit shifts.
 *
 * For any integer k, the following holds (assuming exact division):
 * floor(ceil(2^k / d) * n / 2^k) = floor((2^k + r) / d * n / 2^k), where
 * r = (-2^k) mod d.
 *
 * Expanding:
 * ... = floor(2^k / d * n / 2^k + r / d * n / 2^k)
 *     = floor(n / d + (r / d) * (n / 2^k)).
 *
 * Since d divides n exactly, n/d is an integer, so:
 * ... = n / d + floor((r / d) * (n / 2^k)).
 *
 * To ensure the correction term is less than 1 (so floor doesn't affect the result),
 * we require (r / d) * (n / 2^k) < 1. As r < d, it suffices to make n / 2^k < 1,
 * which is achieved by choosing k = 32.
 */
void
div_init(div_info_t *div_info, size_t divisor) {
	/* Invalid divisor. */
	assert(divisor != 0);
	/*
	 * If divisor were 1, magic would need to be 2^32, which exceeds uint32_t
	 * range and would cause issues on 32-bit platforms.
	 */
	assert(divisor != 1);
	uint64_t power_of_two = ((uint64_t)1 << 32);
	uint32_t multiplier = (uint32_t)(power_of_two / divisor);
	/*
	 * We need ceil(2^k / divisor), but C division gives floor. Thus, we must
	 * increment unless the division was exact (i.e., when divisor is a power
	 * of two).
	 */
	if (power_of_two % divisor != 0) {
		multiplier++;
	}
	div_info->magic = multiplier;
#ifdef JEMALLOC_DEBUG
	div_info->d = divisor;
#endif
}

