// Exit program with status code 7 using syscall
void program_end() {
    long exit_code = 7;
    asm volatile (
        "movq $60, %%rax\n\t"
        "movq %0, %%rdi\n\t"
        "syscall"
        : 
        : "r" (exit_code)
        : "rax", "rdi"
    );
}

