#include "llvm/MC/MCDXContainerWriter.h"
#include "llvm/BinaryFormat/DXContainer.h"
#include "llvm/MC/MCAsmLayout.h"
#include "llvm/MC/MCAssembler.h"
#include "llvm/MC/MCContext.h"
#include "llvm/MC/MCSection.h"
#include "llvm/MC/MCValue.h"
#include "llvm/Support/Alignment.h"
#include "llvm/Support/EndianStream.h"

using namespace llvm;

MCDXContainerTargetWriter::~MCDXContainerTargetWriter() {}

namespace {
class DXContainerObjectWriter : public MCObjectWriter {
  ::support::endian::Writer W;
  std::unique_ptr<MCDXContainerTargetWriter> TargetWriter;
public:
  DXContainerObjectWriter(std::unique_ptr<MCDXContainerTargetWriter> TW,
                          raw_pwrite_stream &Output)
      : W(Output, llvm::endianness::little), TargetWriter(std::move(TW)) {}
  ~DXContainerObjectWriter() override {}

private:
  void recordRelocation(MCAssembler &, const MCAsmLayout &,
                        const MCFragment *, const MCFixup &,
                        MCValue, uint64_t &) override {}
  void executePostLayoutBinding(MCAssembler &,
                                const MCAsmLayout &) override {}
  uint64_t writeObject(MCAssembler &Asm, const MCAsmLayout &Layout) override;
};
} // namespace

uint64_t DXContainerObjectWriter::writeObject(MCAssembler &Asm,
                                              const MCAsmLayout &Layout) {
  llvm::SmallVector<uint64_t, 16> PartOffsets;
  uint64_t CurrentOffset = 0;

  for (const MCSection &Sec : Asm) {
    uint64_t SectionSize = Layout.getSectionAddressSize(&Sec);
    if (SectionSize == 0)
      continue;

    assert(SectionSize < std::numeric_limits<uint32_t>::max() &&
           "Section size exceeds DXContainer limit");
    PartOffsets.push_back(CurrentOffset);
    CurrentOffset += sizeof(dxbc::PartHeader) + SectionSize;
    CurrentOffset = alignTo(CurrentOffset, Align(4));
    if (Sec.getName() == "DXIL")
      CurrentOffset += sizeof(dxbc::ProgramHeader);
  }

  assert(CurrentOffset < std::numeric_limits<uint32_t>::max() &&
         "Total part data exceeds DXContainer capacity");

  uint64_t FirstPartPosition =
      sizeof(dxbc::Header) + (PartOffsets.size() * sizeof(uint32_t));
  uint64_t TotalSize = FirstPartPosition + CurrentOffset;

  assert(TotalSize < std::numeric_limits<uint32_t>::max() &&
         "Final file size exceeds DXContainer limit");

  // Write the DXBC signature
  W.write<char>({'D', 'X', 'B', 'C'});
  // Reserved hash field: 16 zero bytes
  W.OS.write_zeros(16);
  // Version: 1.0
  W.write<uint16_t>(1u);
  W.write<uint16_t>(0u);
  // File size
  W.write<uint32_t>(static_cast<uint32_t>(TotalSize));
  // Number of parts
  W.write<uint32_t>(static_cast<uint32_t>(PartOffsets.size()));

  // Part offsets relative to start of part table
  for (uint64_t Offset : PartOffsets)
    W.write<uint32_t>(static_cast<uint32_t>(FirstPartPosition + Offset));

  for (const MCSection &Sec : Asm) {
    uint64_t SectionSize = Layout.getSectionAddressSize(&Sec);
    if (SectionSize == 0)
      continue;

    unsigned StartPos = W.OS.tell();
    // Write four-character part ID
    W.write<char>(ArrayRef<char>(Sec.getName().data(), 4));

    uint64_t PartSize = SectionSize;
    if (Sec.getName() == "DXIL")
      PartSize += sizeof(dxbc::ProgramHeader);

    PartSize = alignTo(PartSize, Align(4));
    W.write<uint32_t>(static_cast<uint32_t>(PartSize));

    if (Sec.getName() == "DXIL") {
      dxbc::ProgramHeader Header{};
      memset(reinterpret_cast<void *>(&Header), 0, sizeof(dxbc::ProgramHeader));

      const Triple &TT = Asm.getContext().getTargetTriple();
      VersionTuple Ver = TT.getOSVersion();
      Header.MajorVersion = static_cast<uint8_t>(Ver.getMajor());
      if (Ver.getMinor())
        Header.MinorVersion = static_cast<uint8_t>(*Ver.getMinor());
      if (TT.hasEnvironment())
        Header.ShaderKind =
            static_cast<uint16_t>(TT.getEnvironment() - Triple::Pixel);

      Header.Size = (SectionSize + sizeof(dxbc::ProgramHeader) + 3) / 4;

      memcpy(Header.Bitcode.Magic, "DXIL", 4);
      Header.Bitcode.Offset = sizeof(dxbc::BitcodeHeader);
      Header.Bitcode.Size = SectionSize;

      if (sys::IsBigEndianHost)
        Header.swapBytes();

      W.write<char>(ArrayRef<char>(reinterpret_cast<char *>(&Header),
                                   sizeof(dxbc::ProgramHeader)));
    }

    Asm.writeSectionData(W.OS, &Sec, Layout);

    unsigned WrittenSize = W.OS.tell() - StartPos;
    W.OS.write_zeros(offsetToAlignment(WrittenSize, Align(4)));
  }

  return 0;
}

std::unique_ptr<MCObjectWriter> llvm::createDXContainerObjectWriter(
    std::unique_ptr<MCDXContainerTargetWriter> TW, raw_pwrite_stream &OS) {
  return std::make_unique<DXContainerObjectWriter>(std::move(TW), OS);
}

