#include "testlib.h"
#include <bits/stdc++.h>

int main(int argc, char* argv[]) {
    registerInteraction(argc, argv);

    int size = inf.readInt();
    println(size);

    std::vector<int> data(size);
    for (int idx = 0; idx < size; idx++) {
        data[idx] = inf.readInt();
    }

    // Build prefix XOR table for range queries
    std::vector<std::vector<bool>> prefixXor(size + 1, std::vector<bool>(size + 1, false));

    // Fill comparison results
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            prefixXor[i + 1][j + 1] = data[i] > data[j];
        }
    }

    // Compute row-wise XOR prefix sums
    for (int i = 0; i < size; i++) {
        for (int j = 0; j <= size; j++) {
            prefixXor[i + 1][j] = prefixXor[i + 1][j] ^ prefixXor[i][j];
        }
    }

    // Compute column-wise XOR prefix sums
    for (int i = 0; i <= size; i++) {
        for (int j = 0; j < size; j++) {
            prefixXor[i][j + 1] = prefixXor[i][j + 1] ^ prefixXor[i][j];
        }
    }

    // Process up to 1999000 queries
    for (int queryCount = 0; queryCount <= 1999000; queryCount++) {
        int actionType = ouf.readInt();

        if (actionType == 0) {
            int leftBound = ouf.readInt();
            if (leftBound < 1 || leftBound > size) {
                quitf(_wa, "Invalid query: element %d is out of range [1, %d]", leftBound, size);
            }

            int rightBound = ouf.readInt();
            if (rightBound < 1 || rightBound > size) {
                quitf(_wa, "Invalid query: element %d is out of range [1, %d]", rightBound, size);
            }

            if (leftBound > rightBound) {
                quitf(_wa, "Invalid query: not an interval.");
            }

            // Convert to 0-indexed
            leftBound--;

            // Compute result using 2D prefix XOR
            bool result = prefixXor[rightBound][rightBound] ^ 
                         prefixXor[leftBound][rightBound] ^ 
                         prefixXor[rightBound][leftBound] ^ 
                         prefixXor[leftBound][leftBound];

            println(result ? 1 : 0);
        } 
        else if (actionType == 1) {
            std::vector<int> guessedData(size);
            for (int i = 0; i < size; i++) {
                guessedData[i] = ouf.readInt();
            }

            if (guessedData == data) {
                double successRatio = (std::exp(1.0 * -queryCount / 249875) - std::exp(-8)) / (1 - std::exp(-8));
                quitp(successRatio, "Correct guess. Ratio: %.4f", successRatio);
            } else {
                quitp(0.0, "Wrong guess. Ratio: 0.0000");
            }
        } 
        else {
            quitf(_wa, "Invalid action type: expected 0 or 1, but got %d", actionType);
        }
    }

    quitp(0.0, "Too many queries. Ratio: 0.0000");
    return 0;
}

