// Alias for return type: energy + wavefunction pair
using ResultType = std::pair<double, std::shared_ptr<Wavefunction>>;

// Trampoline class to support Python subclassing
class ProjectedMultiConfigurationCalculatorBase
    : public ProjectedMultiConfigurationCalculator,
      public pybind11::trampoline_self_life_support {
public:
  // Override name method for Python override support
  std::string name() const override {
    PYBIND11_OVERRIDE_PURE(std::string, ProjectedMultiConfigurationCalculator, name);
  }

  // Override aliases method
  std::vector<std::string> aliases() const override {
    PYBIND11_OVERRIDE(std::vector<std::string>,
                      ProjectedMultiConfigurationCalculator, aliases);
  }

  // Utility to update internal settings from derived classes
  void update_settings(
      std::unique_ptr<qdk::chemistry::data::Settings> updated) {
    this->_settings = std::move(updated);
  }

protected:
  // Pure virtual implementation hook for run logic
  ResultType _run_impl(
      std::shared_ptr<Hamiltonian> hamiltonian,
      const std::vector<Configuration>& configs) const override {
    PYBIND11_OVERRIDE_PURE(ResultType, ProjectedMultiConfigurationCalculator,
                           _run_impl, hamiltonian, configs);
  }
};

void bind_pmc(py::module& m) {
  // Bind abstract base class
  py::class_<ProjectedMultiConfigurationCalculator,
             ProjectedMultiConfigurationCalculatorBase, py::smart_holder>
      pmc_base(m, "ProjectedMultiConfigurationCalculator",
               R"doc(
Abstract base class for projected multi-configurational (PMC) quantum chemistry calculations.
This interface allows users to define custom determinant spaces for Hamiltonian projection,
enabling integration with external determinant selection methods while leveraging high-performance solvers.

Example usage:
    >>> import qdk_chemistry.algorithms as alg
    >>> import qdk_chemistry.data as data
    >>> class CustomPMC(alg.ProjectedMultiConfigurationCalculator):
    ...     def __init__(self):
    ...         super().__init__()
    ...     def _run_impl(self, hamiltonian: data.Hamiltonian, configurations: list[data.Configuration]) -> tuple[float, data.Wavefunction]:
    ...         # Implement custom PMC logic here
    ...         return energy, wavefunction
)doc");

  // Default constructor
  pmc_base.def(py::init<>(), R"doc(
Constructs an instance of the abstract base class.
Typically invoked via `super().__init__()` in derived Python classes.
)doc");

  // Core run method
  pmc_base.def("execute", &ProjectedMultiConfigurationCalculator::run,
               R"doc(
Executes the projected multi-configuration calculation.

Parameters:
    hamiltonian (qdk_chemistry.data.Hamiltonian): Quantum system Hamiltonian
    configurations (list[qdk_chemistry.data.Configuration]): Determinant space for projection

Returns:
    tuple[float, qdk_chemistry.data.Wavefunction]: Energy and optimized wavefunction

Raises:
    RuntimeError: On computational failure
    ValueError: For invalid inputs
)doc",
               py::arg("hamiltonian"), py::arg("configurations"));

  // Settings accessor
  pmc_base.def("parameters",
               &ProjectedMultiConfigurationCalculator::settings,
               R"doc(
Provides access to configuration parameters.

Returns:
    qdk_chemistry.data.Settings: Reference to internal settings object
)doc",
               py::return_value_policy::reference_internal);

  // Writable _settings property for subclasses
  pmc_base.def_property(
      "_settings",
      [](ProjectedMultiConfigurationCalculatorBase& calc) -> Settings& {
        return calc.parameters();
      },
      [](ProjectedMultiConfigurationCalculatorBase& calc,
         std::unique_ptr<qdk::chemistry::data::Settings> new_params) {
        calc.update_settings(std::move(new_params));
      },
      py::return_value_policy::reference_internal,
      R"doc(
Enables replacement of settings object in derived classes.

Example:
    >>> class CustomPMC(alg.ProjectedMultiConfigurationCalculator):
    ...     def __init__(self):
    ...         super().__init__()
    ...         self._settings = ElectronicStructureSettings()
)doc");

  // Algorithm metadata
  pmc_base.def("identifier", &ProjectedMultiConfigurationCalculator::name,
               R"doc(
Returns the algorithm's identifier string.

Returns:
    str: Name of the algorithm
)");

  pmc_base.def("category", &ProjectedMultiConfigurationCalculator::type_name,
               R"doc(
Returns the algorithm's category/type name.

Returns:
    str: Type classification of the algorithm
)");

  // Factory binding
  qdk::chemistry::python::bind_algorithm_factory<
      ProjectedMultiConfigurationCalculatorFactory,
      ProjectedMultiConfigurationCalculator,
      ProjectedMultiConfigurationCalculatorBase>(
      m, "ProjectedMultiConfigurationCalculatorFactory");

  // Repr implementation
  pmc_base.def("__repr__", [](const ProjectedMultiConfigurationCalculator&) {
    return "<qdk_chemistry.algorithms.ProjectedMultiConfigurationCalculator>";
  });

  // Concrete MACIS-based implementation
  py::class_<microsoft::MacisPmc, ProjectedMultiConfigurationCalculator,
             py::smart_holder>(m, "QdkMacisPmc", R"doc(
Concrete PMC calculator using the Microsoft MACIS library.

Implements projected multi-configuration methods for strongly correlated systems,
accepting user-provided determinant spaces instead of adaptive generation.

Usage example:
    >>> import qdk_chemistry.algorithms as alg
    >>> import qdk_chemistry.data as data
    >>> pmc = alg.QdkMacisPmc()
    >>> pmc.parameters().set("davidson_res_tol", 1e-8)
    >>> pmc.parameters().set("davidson_max_m", 200)
    >>> energy, wf = pmc.execute(hamiltonian, configurations)

See Also:
    :class:`ProjectedMultiConfigurationCalculator`
    :class:`qdk_chemistry.data.Hamiltonian`
    :class:`qdk_chemistry.data.Configuration`
    :class:`qdk_chemistry.data.Wavefunction`
)doc")
      .def(py::init<>(), R"doc(
Default constructor with standard initialization.
)doc");
}

class Solution {
public:
    int countOdds(int low, int high) {
        int result = (high - low) / 2;
        if (low % 2 != 0 || high % 2 != 0)
            result++;
        return result;
    }
};

