namespace {
    // private classes in anon namespace

    using wav_writer = CWavWriter;
    using wav_writer_setup_t = wavWriterSetup_t;

    static pfc::string8 g_capturePath;
    static wav_writer g_recorder;

    class stream_capture_handler : public playback_stream_capture_callback {
    public:
        void on_chunk(const audio_chunk & chunk) override {
            PFC_ASSERT(core_api::is_main_thread());

            try {
                // writing files in main thread is not pretty, but good enough for our demo

                auto & abort = fb2k::noAbort;

                if (g_recorder.is_open() && g_recorder.get_spec() != chunk.get_spec()) {
                    g_recorder.finalize(abort);
                }
                if (!g_recorder.is_open() && !core_api::is_shutting_down()) {
                    wav_writer_setup_t setup; 
                    setup.initialize(chunk, 16, false, false);

                    pfc::string_formatter filename;
                    filename << "recording-" << pfc::print_guid(pfc::createGUID()) << ".wav";
                    pfc::string_formatter filepath = g_capturePath;
                    filepath.add_filename(filename); // pretty method to add file path components with auto inserted delimiter
                    g_recorder.open(filepath, setup, abort);
                }
                g_recorder.write(chunk, abort);
            } catch(std::exception const & e) {
                FB2K_console_formatter() << "Stream capture error: " << e;
                // FIX ME handle this in a pretty manner, likely inaccessible output folder or out of disk space
            }
        }
    };
    static stream_capture_handler g_handler;
    static bool g_isRecording = false;

    static void EndCurrentSegment() {
        if (g_isRecording) {
            g_recorder.finalize(fb2k::noAbort);
        }
    }

    static void DisableCapture() {
        if (g_isRecording) {
            g_isRecording = false;
            playback_stream_capture::get()->remove_callback(&g_handler);
            g_recorder.finalize(fb2k::noAbort);
        }
    }

    static void EnableCapture() {
        PFC_ASSERT(g_capturePath.length() > 0);
        if (!g_isRecording && !core_api::is_shutting_down()) {
            g_isRecording = true;
            playback_stream_capture::get()->add_callback(&g_handler); 
        }
    }

    // Forcibly stop capture when fb2k is shutting down
    class shutdown_handler : public initquit {
    public:
        void on_quit() override {
            PFC_ASSERT(core_api::is_shutting_down());
            DisableCapture();
        }
    };

    // Handle playback stop events to split output WAV files
    class playback_observer : public play_callback_static {
    public:
        unsigned get_flags() override {
            return flag_on_playback_stop;
        }
        void on_playback_stop(play_control::t_stop_reason p_reason) override {
            // Terminate the current stream
            EndCurrentSegment();
        }
        void on_playback_starting(play_control::t_track_command p_command,bool p_paused) override {}
        void on_playback_new_track(metadb_handle_ptr p_track) override {}
        void on_playback_seek(double p_time) override {}
        void on_playback_pause(bool p_state) override {}
        void on_playback_edited(metadb_handle_ptr p_track) override {}
        void on_playback_dynamic_info(const file_info & p_info) override {}
        void on_playback_dynamic_info_track(const file_info & p_info) override {}
        void on_playback_time(double p_time) override {}
        void on_volume_change(float p_new_val) override {}
    };

    // modern macro for service_factory_single_t<>
    FB2K_SERVICE_FACTORY( shutdown_handler );
    FB2K_SERVICE_FACTORY( playback_observer );
}

static void setCaptureFolderAndStart( fb2k::arrayRef location ) {
    if ( g_isRecording ) return; // already recording
    if ( location.is_empty() ) return;
    if ( location->size() != 1 ) return;
    auto obj = location->itemAt(0);
    fsItemFolderPtr folder;
    fb2k::stringRef strFolder;
    if ( strFolder &= obj ) {
        // OK
    } else if ( folder &= obj ) {
        strFolder = folder->canonicalPath();
    }
    if ( strFolder.is_valid() ) {
        g_capturePath = strFolder->c_str();
        EnableCapture();
    }
}

void ToggleRecording() {
#ifdef _WIN32
    // Block modal dialog recursions.
    // Folder picker below is a modal dialog, don't ever call it if there's another modal dialog in progress.
    // Also prevents this function from recursing into itself if someone manages to hit the menu item while already picking folder.
    // This will bump whatever modal dialog already exists, so the user has some idea why this was refused.
    if ( !ModalDialogPrologue() ) return;

    if (g_isRecording) {
        DisableCapture();
    } else {
        const HWND wndParent = core_api::get_main_window();
        modal_dialog_scope scope(wndParent); // we can't have a handle to the modal dialog, but parent handle is good enough
        if (uBrowseForFolder(wndParent, "Select output directory", g_capturePath)) {
            EnableCapture();
        }
    }
#else
    if ( g_isRecording ) {
        DisableCapture();
    } else {
        auto dlg = fb2k::fileDialog::get()->setupOpenFolder();
        dlg->setTitle( "Select output directory" );
        dlg->run( fb2k::fileDialogNotify::create( setCaptureFolderAndStart ) );
    }
#endif
}

bool IsRecordingActive() {
    return g_isRecording;
}

