const wchar_t File::pathSeparator = L'\\';

#ifdef _XBOX
const std::wstring File::pathRoot = L"GAME:";
#else
const std::wstring File::pathRoot = L"";
#endif

// Constructor: combines parent and child path components
File::File(const File& parent, const std::wstring& child) {
    m_abstractPathName = parent.getPath() + pathSeparator + child;
}

// Constructor: creates file from a full pathname string
File::File(const std::wstring& pathname) {
    if (pathname.empty()) {
        m_abstractPathName = std::wstring(L"");
    } else {
        m_abstractPathName = pathname;
    }

#if defined(_WINDOWS64)
    std::string path      = wstringtofilename(m_abstractPathName);
    std::string finalPath = StorageManager.GetMountedPath(path.c_str());
    if (finalPath.empty()) finalPath = path;
    m_abstractPathName = convStringToWstring(finalPath);
#elif defined(_DURANGO)
    std::wstring finalPath =
        StorageManager.GetMountedPath(m_abstractPathName.c_str());
    if (finalPath.empty()) finalPath = m_abstractPathName;
    m_abstractPathName = finalPath;
#endif
}

// Constructor: constructs path from parent and child strings with root prefix
File::File(const std::wstring& parent, const std::wstring& child) {
    m_abstractPathName = pathRoot + pathSeparator + parent + pathSeparator + child;
}

// Deletes the file or directory
bool File::_delete() {
#ifdef _UNICODE
    BOOL result = DeleteFile(getPath().c_str());
#else
    BOOL result = DeleteFile(wstringtofilename(getPath()));
#endif
    if (result == 0) {
        DWORD error = GetLastError();
#ifndef _CONTENT_PACKAGE
        printf("File::_delete - Error code %d (%#0.8X)\n", error, error);
#endif
        return false;
    }
    return true;
}

// Creates a single directory
bool File::mkdir() const {
#ifdef _UNICODE
    return CreateDirectory(getPath().c_str(), NULL) != 0;
#else
    return CreateDirectory(wstringtofilename(getPath()), NULL) != 0;
#endif
}

// Creates directory and all necessary parent directories
bool File::mkdirs() const {
    std::vector<std::wstring> pathComponents =
        stringSplit(m_abstractPathName, pathSeparator);
    std::wstring currentPath = L"";

    for (const auto& component : pathComponents) {
        if (pathRoot == component) {
            currentPath = component;
            continue;
        }

        currentPath += pathSeparator + component;

#ifdef _UNICODE
        if (GetFileAttributes(currentPath.c_str()) == -1) {
            if (CreateDirectory(currentPath.c_str(), NULL) == 0) {
                return false;
            }
        }
#else
        if (GetFileAttributes(wstringtofilename(currentPath)) == -1) {
            if (CreateDirectory(wstringtofilename(currentPath), NULL) == 0) {
                return false;
            }
        }
#endif
    }

    assert(exists());
    return true;
}

// Checks if the file or directory exists
bool File::exists() const {
#ifdef _UNICODE
    return GetFileAttributes(getPath().c_str()) != -1;
#else
    return GetFileAttributes(wstringtofilename(getPath())) != -1;
#endif
}

// Checks if this is a regular file (not a directory)
bool File::isFile() const { 
    return exists() && !isDirectory(); 
}

// Renames/moves the file to a new location
bool File::renameTo(File dest) {
    std::string sourcePath = wstringtofilename(getPath());
    const char* destPath   = wstringtofilename(dest.getPath());

#ifdef _DURANGO
    __debugbreak(); // TODO
    BOOL result = FALSE;
#else
    BOOL result = MoveFile(sourcePath.c_str(), destPath);
#endif

    if (result == 0) {
        DWORD error = GetLastError();
#ifndef _CONTENT_PACKAGE
        printf("File::renameTo - Error code %d (%#0.8X)\n", error, error);
#endif
        return false;
    }
    return true;
