// Lists files in a directory
std::vector<File*>* File::listFiles() const {
    std::vector<File*>* result = new std::vector<File*>();

    if (!isDirectory()) {
        return result;
    }

#ifdef __PS3__
    const char* lpFileName = wstringtofilename(getPath());
    char filePath[256];
    std::string mountedPath = StorageManager.GetMountedPath(lpFileName);
    if (mountedPath.length() > 0) {
        strcpy(filePath, mountedPath.c_str());
    } else if (lpFileName[0] == '/') {
        strcpy(filePath, lpFileName);
    } else {
        sprintf(filePath, "%s/%s", getUsrDirPath(), lpFileName);
    }

    int fd;
    CellFsErrno err = cellFsOpendir(filePath, &fd);
    CellFsDirectoryEntry de;
    std::uint32_t count = 0;

    err = cellFsGetDirectoryEntries(fd, &de, sizeof(CellFsDirectoryEntry), &count);
    while (count != 0) {
        if (de.attribute.st_mode & CELL_FS_S_IFREG) {
            result->push_back(new File(*this, filenametowstring(de.entry_name.d_name)));
        }
        err = cellFsGetDirectoryEntries(fd, &de, sizeof(CellFsDirectoryEntry), &count);
    }
    cellFsClose(fd);

#elif defined(__ORBIS__) || defined(__PSVITA__)
    const char* lpFileName = wstringtofilename(getPath());
    char filePath[256];
    std::string mountedPath = StorageManager.GetMountedPath(lpFileName);
    if (mountedPath.length() > 0) {
        strcpy(filePath, mountedPath.c_str());
    } else if (lpFileName[0] == '/') {
        strcpy(filePath, lpFileName);
    } else {
        sprintf(filePath, "%s/%s", getUsrDirPath(), lpFileName);
    }

    SceFiosDH dh = SCE_FIOS_DH_INVALID;
    SceFiosBuffer buf = {0};
    SceFiosOp op = sceFiosDHOpen(NULL, &dh, filePath, buf);
    int status = sceFiosOpWait(op);

    if (status == SCE_FIOS_OK) {
        SceFiosSize bufferSize = sceFiosOpGetActualCount(op);
        char* buffer = new char[bufferSize];
        buf.set(buffer, static_cast<size_t>(bufferSize));
        sceFiosOpDelete(op);
        sceFiosDHClose(NULL, dh);

        status = sceFiosDHOpenSync(NULL, &dh, filePath, buf);
        if (status == SCE_FIOS_OK) {
            SceFiosDirEntry entry;
            ZeroMemory(&entry, sizeof(SceFiosDirEntry));

            while (sceFiosDHReadSync(NULL, dh, &entry) == SCE_FIOS_OK) {
                result->push_back(new File(
                    *this,
                    filenametowstring(entry.fullPath + entry.offsetToName)
                ));
                ZeroMemory(&entry, sizeof(SceFiosDirEntry));
            }
        }
        sceFiosDHClose(NULL, dh);
        delete[] buffer;
    }
#else
    WIN32_FIND_DATA wfd;
#ifdef _UNICODE
    WCHAR searchPath[MAX_PATH];
    swprintf(searchPath, L"%ls\\*", getPath().c_str());
    HANDLE hFind = FindFirstFile(searchPath, &wfd);
#else
    char searchPath[MAX_PATH];
    sprintf(searchPath, "%s\\*", wstringtofilename(getPath()));
    HANDLE hFind = FindFirstFile(searchPath, &wfd);
#endif

    if (hFind != INVALID_HANDLE_VALUE) {
        do {
            result->push_back(new File(*this, 
#ifdef _UNICODE
                wfd.cFileName
#else
                filenametowstring(wfd.cFileName)
#endif
            ));
        } while (FindNextFile(hFind, &wfd));
        FindClose(hFind);
    }
#endif

    return result;
}

// Lists files filtered by a FileFilter
std::vector<File*>* File::listFiles(FileFilter* filter) const {
    if (!isDirectory()) {
        return NULL;
    }

    std::vector<File*>* result = new std::vector<File*>();

#ifdef __PS3__
    const char* lpFileName = wstringtofilename(getPath());
    char filePath[256];
    std::string mountedPath = StorageManager.GetMountedPath(lpFileName);
    if (mountedPath.length() > 0) {
        strcpy(filePath, mountedPath.c_str());
    } else if (lpFileName[0] == '/') {
        strcpy(filePath, lpFileName);
    } else {
        sprintf(filePath, "%s/%s", getUsrDirPath(), lpFileName);
    }

    int fd;
    CellFsErrno err = cellFsOpendir(filePath, &fd);
    CellFsDirectoryEntry de;
    std::uint32_t count = 0;

    err = cellFsGetDirectoryEntries(fd, &de, sizeof(CellFsDirectoryEntry), &count);
    while (count != 0) {
        File currentFile(*this, filenametowstring(de.entry_name.d_name));
        if (filter->accept(&currentFile)) {
            File storageFile = currentFile;
            if (de.attribute.st_mode & CELL_FS_S_IFREG) {
                result->push_back(&storageFile);
            }
        }
        err = cellFsGetDirectoryEntries(fd, &de, sizeof(CellFsDirectoryEntry), &count);
    }
    cellFsClose(fd);
#else
#ifdef _UNICODE
    WCHAR           searchPath[MAX_PATH];
    WIN32_FIND_DATA wfd;
    swprintf(searchPath, L"%ls\\*", getPath().c_str());
    HANDLE hFind = FindFirstFile(searchPath, &wfd);
#else
    char            searchPath[MAX_PATH];
    WIN32_FIND_DATA wfd;
    sprintf(searchPath, "%s\\*", wstringtofilename(getPath()));
    HANDLE hFind = FindFirstFile(searchPath, &wfd);
#endif

    if (hFind != INVALID_HANDLE_VALUE) {
        do {
            File currentFile(*this, 
#ifdef _UNICODE
                wfd.cFileName
#else
                filenametowstring(wfd.cFileName)
