// Checks if this path refers to a directory
bool File::isDirectory() const {
#ifdef _UNICODE
    return exists()
        && ((GetFileAttributes(getPath().c_str()) & FILE_ATTRIBUTE_DIRECTORY)
            == FILE_ATTRIBUTE_DIRECTORY);
#else
    return exists()
        && ((GetFileAttributes(wstringtofilename(getPath()))
             & FILE_ATTRIBUTE_DIRECTORY)
            == FILE_ATTRIBUTE_DIRECTORY);
#endif
}

// Returns the size of the file in bytes
std::int64_t File::length() {
#ifdef __PS3__
    const char* lpFileName = wstringtofilename(getPath());
    char filePath[256];
    std::string mountedPath = StorageManager.GetMountedPath(lpFileName);
    if (mountedPath.length() > 0) {
        strcpy(filePath, mountedPath.c_str());
    } else if (lpFileName[0] == '/') {
        strcpy(filePath, lpFileName);
    } else {
        sprintf(filePath, "%s/%s", getUsrDirPath(), lpFileName);
    }

    CellFsStat statData;
    if (cellFsStat(filePath, &statData) != CELL_FS_SUCCEEDED ||
        statData.st_mode == CELL_FS_S_IFDIR) {
        return 0;
    }
    return statData.st_size;

#elif defined(__ORBIS__) || defined(__PSVITA__)
    const char* lpFileName = wstringtofilename(getPath());
    char filePath[256];
    std::string mountedPath = StorageManager.GetMountedPath(lpFileName);
    if (mountedPath.length() > 0) {
        strcpy(filePath, mountedPath.c_str());
    } else if (lpFileName[0] == '/') {
        strcpy(filePath, lpFileName);
    } else {
        sprintf(filePath, "%s/%s", getUsrDirPath(), lpFileName);
    }

    SceFiosStat statData;
    if (sceFiosStatSync(NULL, filePath, &statData) != SCE_FIOS_OK ||
        (statData.statFlags & SCE_FIOS_STATUS_DIRECTORY)) {
        return 0;
    }
    return statData.fileSize;

#else
    WIN32_FILE_ATTRIBUTE_DATA fileInfo;
#ifdef _UNICODE
    BOOL success = GetFileAttributesEx(
        getPath().c_str(),
        GetFileExInfoStandard,
        &fileInfo
    );
#else
    BOOL success = GetFileAttributesEx(
        wstringtofilename(getPath()),
        GetFileExInfoStandard,
        &fileInfo
    );
#endif

    if (success && !(fileInfo.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)) {
        LARGE_INTEGER fileSize;
        fileSize.HighPart = fileInfo.nFileSizeHigh;
        fileSize.LowPart  = fileInfo.nFileSizeLow;
        return fileSize.QuadPart;
    }
    return 0;
#endif
}

// Returns the last modification time of the file
std::int64_t File::lastModified() {
    WIN32_FILE_ATTRIBUTE_DATA fileInfo;
#ifdef _UNICODE
    BOOL success = GetFileAttributesEx(
        getPath().c_str(),
        GetFileExInfoStandard,
        &fileInfo
    );
#else
    BOOL success = GetFileAttributesEx(
        wstringtofilename(getPath()),
        GetFileExInfoStandard,
        &fileInfo
    );
#endif

    if (success && !(fileInfo.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)) {
        LARGE_INTEGER modTime;
        modTime.HighPart = fileInfo.ftLastWriteTime.dwHighDateTime;
        modTime.LowPart  = fileInfo.ftLastWriteTime.dwLowDateTime;
        return modTime.QuadPart;
    }
    return 0;
}

// Returns the full path as a wide string
const std::wstring File::getPath() const {
    return m_abstractPathName;
}

// Extracts just the filename from the full path
std::wstring File::getName() const {
    size_t separatorPos = m_abstractPathName.find_last_of(pathSeparator);
    return m_abstractPathName.substr(separatorPos + 1);
}

// Compares two File objects for equality
bool File::eq_test(const File& first, const File& second) {
    return first.getPath().compare(second.getPath()) == 0;
}

// Computes a hash code for a File object
int File::hash_fnct(const File& file) {
    int hashCode = 0;
    const wchar_t* pathChars = file.m_abstractPathName.c_str();

    for (size_t i = 0; i < file.m_abstractPathName.length(); ++i) {
        hashCode = (hashCode * 33 + pathChars[i]) % 149;
    }
    return hashCode;
}

