#include <bits/stdc++.h>
using namespace std;

static void terminate_program() {
    exit(0);
}

static void output_and_flush(const string &text) {
    cout << text << '\n';
    cout.flush();
}

static int input_integer_or_exit() {
    int value;
    if (!(cin >> value)) terminate_program();
    if (value == -1) terminate_program();
    return value;
}

static void disable_connection(int edge_id) {
    output_and_flush("- " + to_string(edge_id));
}

static void restore_connection(int edge_id) {
    output_and_flush("+ " + to_string(edge_id));
}

static int perform_query(int target_node) {
    output_and_flush("? 1 " + to_string(target_node));
    return input_integer_or_exit();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (!(cin >> test_cases)) return 0;

    while (test_cases--) {
        int nodes, edges;
        cin >> nodes >> edges;

        vector<int> source(edges + 1), destination(edges + 1);
        for (int i = 1; i <= edges; i++) {
            cin >> source[i] >> destination[i];
        }

        // Initially disable all connections
        for (int i = 1; i <= edges; i++) {
            disable_connection(i);
        }

        vector<int> is_functional(edges + 1, 0);

        // Check each connection individually
        for (int i = 1; i <= edges; i++) {
            restore_connection(i);

            // Reset to source node of current edge
            (void)perform_query(source[i]);

            // Check if destination is reachable from source
            int result = perform_query(destination[i]);
            is_functional[i] = (result != 0) ? 1 : 0;

            disable_connection(i);
        }

        // Output results
        {
            ostringstream result_stream;
            result_stream << "!";
            for (int i = 1; i <= edges; i++) {
                result_stream << ' ' << is_functional[i];
            }
            output_and_flush(result_stream.str());
        }

        int judge_response = input_integer_or_exit();
        if (judge_response != 1) {
            terminate_program();
        }
    }

    return 0;
}

