// Generate a square matrix based on input parameters
vector<vector<int>> generate_matrix(int rows, int cols_count, vector<int> first_vals, vector<int> second_vals) {
    int dimension = max(1, rows);
    dimension = min(dimension, 240);

    // Initialize matrix with all ones
    vector<vector<int>> matrix(dimension, vector<int>(dimension, 1));

    // Set diagonal elements to their 1-based index
    for (int idx = 0; idx < min(dimension, rows); ++idx) {
        matrix[idx][idx] = idx + 1;
    }

    return matrix;
}

int main() {
