extern "C" int LLVMFuzzerTestOneInput(const uint8_t *InputData, size_t InputSize) {
    int8_t PositionMap[256];
    std::memset(PositionMap, -1, sizeof(PositionMap));

    for (size_t index = 0; index < InputSize; ++index) {
        if (PositionMap[InputData[index]] == -1) {
            PositionMap[InputData[index]] = static_cast<int8_t>(index);
        }
    }

    int PosF = PositionMap[static_cast<unsigned char>('F')];
    int PosU = PositionMap[static_cast<unsigned char>('U')];
    int PosZ = PositionMap[static_cast<unsigned char>('Z')];

    if (PosF >= 0 && PosU > PosF && PosZ > PosU) {
        Sink++;
    }

