#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Global variables to store tree structure
int nodes_count;
vector<vector<int>> adjacency_list;
vector<int> subtree_size;
vector<int> parent_vertex;
vector<int> heavy_child;

// DFS to compute subtree sizes and identify heavy children for HLD
void dfs_subtree(int u, int p) {
    subtree_size[u] = 1;
    parent_vertex[u] = p;
    int max_subtree = -1;
    heavy_child[u] = -1;
    for (int v : adjacency_list[u]) {
        if (v != p) {
            dfs_subtree(v, u);
            subtree_size[u] += subtree_size[v];
            if (subtree_size[v] > max_subtree) {
                max_subtree = subtree_size[v];
                heavy_child[u] = v;
            }
        }
    }
}

// Helper function to perform a query
int ask(int x) {
    cout << "? " << x << endl;
    int answer;
    cin >> answer;
    // -1 indicates invalid query or error in interaction
    if (answer == -1) exit(0); 
    return answer;
}

void process_case() {
    if (!(cin >> nodes_count)) return;
    adjacency_list.assign(nodes_count + 1, vector<int>());
    subtree_size.assign(nodes_count + 1, 0);
    parent_vertex.assign(nodes_count + 1, 0);
    heavy_child.assign(nodes_count + 1, -1);

    for (int i = 0; i < nodes_count - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adjacency_list[u].push_back(v);
        adjacency_list[v].push_back(u);
    }

    // Precompute heavy edges
    dfs_subtree(1, 0);
    int current_node = 1;

    // We have a limit of 160 queries.
    // Strategy: HLD-based Binary Search.
    // Maintain 'current_node' such that the mole is expected to be in the subtree of 'current_node'.
    // In each iteration, construct the heavy path starting from 'current_node'.
    // Use binary search on the heavy path to find the deepest node containing the mole.

    while (true) {
        // Construct heavy path from current_node
        vector<int> path_nodes;
        int temp = current_node;
        while (temp != -1) {
            path_nodes.push_back(temp);
            temp = heavy_child[temp];
        }

        // If path has only 1 node (current_node itself), and since we maintain that mole is in T_current_node,
        // the mole must be at current_node.
        if (path_nodes.size() == 1) {
            cout << "! " << current_node << endl;
            return;
        }

        // Binary Search on the heavy path to find the mole
        // We are looking for a node in path_nodes[1...end] because we are already at path_nodes[0].
        int left = 1; 
        int right = (int)path_nodes.size() - 1;
        int failures = 0;
        bool found_deeper = false;

        // Perform binary search
        while (left <= right) {
            // Bias mid towards the end (deeper nodes). 
            // If we hit 1, we jump deep. If 0, we lose little (mole moves up).
            int mid = (left + right + 1) / 2;
            int result = ask(path_nodes[mid]);

            if (result == 1) {
                // Mole is in the subtree of path_nodes[mid].
                // We successfully narrowed down the location significantly.
                current_node = path_nodes[mid];
                found_deeper = true;
                break; 
            } else {
                // Mole is NOT in the subtree of path_nodes[mid].
                // Mole moves to its parent node.
                // We know mole is above path_nodes[mid] (relative to the path structure or off-path).
                right = mid - 1;
                failures++;
            }
        }

        if (!found_deeper) {
            // We failed to find the mole deeper in the current heavy path.
            // For every failed query (result 0), the mole moved up one step.
            // We need to backtrack 'current_node' upwards to maintain the invariant.
            // However, we clamp at the root (node 1).
            int previous_node = current_node;
            for (int k = 0; k < failures; ++k) {
                if (current_node != 1) {
                    current_node = parent_vertex[current_node];
                }
            }

            // If we were at the root and tried to find the mole but failed,
            // and after backtracking we remain at the root, then the mole is at the root.
            // (Note: If the mole was in a light child of the root, the query on the heavy child
            // would return 0, causing the mole to move to the root).
            if (current_node == 1 && previous_node == 1) {
                cout << "! " << 1 << endl;
                return;
            }
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            process_case();
        }
    }
    return 0;
}

