#include "LiquidCrystal.h"
#include <stdio.h>
#include <string.h>
#include <inttypes.h>
#include "Arduino.h"

// When the display powers up, it is configured as follows:
//
// 1. Display clear
// 2. Function set:
//    DL = 1; 8-bit interface data
//    N = 0; 1-line display
//    F = 0; 5x8 dot character font
// 3. Display on/off control:
//    D = 0; Display off
//    C = 0; Cursor off
//    B = 0; Blinking off
// 4. Entry mode set:
//    I/D = 1; Increment by 1
//    S = 0; No shift
//
// Note, however, that resetting the Arduino doesn't reset the LCD, so we
// can't assume that its in that state when a sketch starts (and the
// LiquidCrystal constructor is called).

// Constructor with full pin configuration (RS, RW, Enable, D0-D7)
LiquidCrystal::LiquidCrystal(uint8_t rs_pin, uint8_t rw_pin, uint8_t en_pin,
                             uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3,
                             uint8_t d4, uint8_t d5, uint8_t d6, uint8_t d7)
{
  init(0, rs_pin, rw_pin, en_pin, d0, d1, d2, d3, d4, d5, d6, d7);
}

// Constructor without RW pin (RW tied to ground)
LiquidCrystal::LiquidCrystal(uint8_t rs_pin, uint8_t en_pin,
                             uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3,
                             uint8_t d4, uint8_t d5, uint8_t d6, uint8_t d7)
{
  init(0, rs_pin, 255, en_pin, d0, d1, d2, d3, d4, d5, d6, d7);
}

// Constructor for 4-bit mode with RW pin
LiquidCrystal::LiquidCrystal(uint8_t rs_pin, uint8_t rw_pin, uint8_t en_pin,
                             uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3)
{
  init(1, rs_pin, rw_pin, en_pin, d0, d1, d2, d3, 0, 0, 0, 0);
}

// Constructor for 4-bit mode without RW pin
LiquidCrystal::LiquidCrystal(uint8_t rs_pin, uint8_t en_pin,
                             uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3)
{
  init(1, rs_pin, 255, en_pin, d0, d1, d2, d3, 0, 0, 0, 0);
}

// Common initialization routine
void LiquidCrystal::init(uint8_t fourbitmode, uint8_t rs_pin, uint8_t rw_pin, uint8_t en_pin,
                         uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3,
                         uint8_t d4, uint8_t d5, uint8_t d6, uint8_t d7)
{
  _rs_pin = rs_pin;
  _rw_pin = rw_pin;
  _enable_pin = en_pin;

  _data_pins[0] = d0;
  _data_pins[1] = d1;
  _data_pins[2] = d2;
  _data_pins[3] = d3;
  _data_pins[4] = d4;
  _data_pins[5] = d5;
  _data_pins[6] = d6;
  _data_pins[7] = d7;

  if (fourbitmode)
    _displayfunction = LCD_4BITMODE | LCD_1LINE | LCD_5x8DOTS;
  else
    _displayfunction = LCD_8BITMODE | LCD_1LINE | LCD_5x8DOTS;

  begin(16, 1);
}

// Initialize display with specified dimensions and font size
void LiquidCrystal::begin(uint8_t cols, uint8_t lines, uint8_t dotsize) {
  if (lines > 1) {
    _displayfunction |= LCD_2LINE;
  }
  _numlines = lines;
  setRowOffsets(0x00, 0x40, 0x00 + cols, 0x40 + cols);

  // Allow selecting 10-pixel font for single-line displays
  if ((dotsize != LCD_5x8DOTS) && (lines == 1)) {
    _displayfunction |= LCD_5x10DOTS;
  }

  pinMode(_rs_pin, OUTPUT);
  if (_rw_pin != 255) {
    pinMode(_rw_pin, OUTPUT);
  }
  pinMode(_enable_pin, OUTPUT);

  // Configure data pins once for performance
  for (int idx = 0; idx < ((_displayfunction & LCD_8BITMODE) ? 8 : 4); ++idx) {
    pinMode(_data_pins[idx], OUTPUT);
  }

  // Wait for LCD power-up stabilization (at least 40ms after VDD > 2.7V)
  delayMicroseconds(50000);

  // Reset control lines before sending commands
  digitalWrite(_rs_pin, LOW);
  digitalWrite(_enable_pin, LOW);
  if (_rw_pin != 255) {
    digitalWrite(_rw_pin, LOW);
  }

  // Initialize in 4-bit or 8-bit mode
  if (!(_displayfunction & LCD_8BITMODE)) {
    // Hitachi HD44780 spec: start in 8-bit mode, then switch to 4-bit
    write4bits(0x03);
    delayMicroseconds(4500);
    write4bits(0x03);
    delayMicroseconds(4500);
    write4bits(0x03);
    delayMicroseconds(150);
    write4bits(0x02);
  } else {
    command(LCD_FUNCTIONSET | _displayfunction);
    delayMicroseconds(4500);
    command(LCD_FUNCTIONSET | _displayfunction);
    delayMicroseconds(150);
    command(LCD_FUNCTIONSET | _displayfunction);
  }

  // Finalize display configuration
  command(LCD_FUNCTIONSET | _displayfunction);

  // Default display settings: ON, no cursor, no blink
  _displaycontrol = LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF;
  display();

  // Clear display
  clear();

  // Set default text direction (left-to-right)
  _displaymode = LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT;
  command(LCD_ENTRYMODESET | _displaymode);
}

// Set row offsets for multi-line displays
void LiquidCrystal::setRowOffsets(int row0, int row1, int row2, int row3)
{
  _row_offsets[0] = row0;
  _row_offsets[1] = row1;
  _row_offsets[2] = row2;
  _row_offsets[3] = row3;
}

// Clear display and return cursor to home position
void LiquidCrystal::clear()
{
  command(LCD_CLEARDISPLAY);
  delayMicroseconds(2000);
}

// Return cursor to home position
void LiquidCrystal::home()
{
  command(LCD_RETURNHOME);
  delayMicroseconds(2000);
}

// Position cursor at column col, row row
void LiquidCrystal::setCursor(uint8_t col, uint8_t row)
{
  const size_t max_lines = sizeof(_row_offsets) / sizeof(*_row_offsets);
  if (row >= max_lines) {
    row = max_lines - 1;
  }
  if (row >= _numlines) {
    row = _numlines - 1;
  }
  command(LCD_SETDDRAMADDR | (col + _row_offsets[row]));
}

// Turn display on/off quickly
void LiquidCrystal::noDisplay() {
  _displaycontrol &= ~LCD_DISPLAYON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::display() {
  _displaycontrol |= LCD_DISPLAYON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

// Control underline cursor visibility
void LiquidCrystal::noCursor() {
  _displaycontrol &= ~LCD_CURSORON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::cursor() {
  _displaycontrol |= LCD_CURSORON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

// Control blinking cursor
void LiquidCrystal::noBlink() {
  _displaycontrol &= ~LCD_BLINKON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::blink() {
  _displaycontrol |= LCD_BLINKON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

// Scroll display contents left/right
void LiquidCrystal::scrollDisplayLeft(void) {
  command(LCD_CURSORSHIFT | LCD_DISPLAYMOVE | LCD_MOVELEFT);
}

void LiquidCrystal::scrollDisplayRight(void) {
  command(LCD_CURSORSHIFT | LCD_DISPLAYMOVE | LCD_MOVERIGHT);
}

// Set text flow direction
void LiquidCrystal::leftToRight(void) {
  _displaymode |= LCD_ENTRYLEFT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::rightToLeft(void) {
  _displaymode &= ~LCD_ENTRYLEFT;
  command(LCD_ENTRYMODESET | _displaymode);
}

// Autoscroll behavior
void LiquidCrystal::autoscroll(void) {
  _displaymode |= LCD_ENTRYSHIFTINCREMENT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::noAutoscroll(void) {
  _displaymode &= ~LCD_ENTRYSHIFTINCREMENT;
  command(LCD_ENTRYMODESET | _displaymode);
}

// Create custom character in CGRAM
void LiquidCrystal::createChar(uint8_t location, uint8_t charmap[]) {
  location &= 0x7; // Only 8 locations available (0-7)
  command(LCD_SETCGRAMADDR | (location << 3));
  for (int i = 0; i < 8; i++) {
    write(charmap[i]);
  }
}

// Send command to LCD
inline void LiquidCrystal::command(uint8_t value) {
  send(value, LOW);
}

// Write data byte to LCD
inline size_t LiquidCrystal::write(uint8_t value) {
  send(value, HIGH);
  return 1;
}

// Low-level data transmission
void LiquidCrystal::send(uint8_t value, uint8_t mode) {
  digitalWrite(_rs_pin, mode);
  if (_rw_pin != 255) {
    digitalWrite(_rw_pin, LOW);
  }
  if (_displayfunction & LCD_8BITMODE) {
    write8bits(value);
  } else {
    write4bits(value >> 4);
    write4bits(value);
  }
}

// Generate enable pulse
void LiquidCrystal::pulseEnable(void) {
  digitalWrite(_enable_pin, LOW);
  delayMicroseconds(1);
  digitalWrite(_enable_pin, HIGH);
  delayMicroseconds(1);
  digitalWrite(_enable_pin, LOW);
  delayMicroseconds(100);
}

// Send 4 bits of data
void LiquidCrystal::write4bits(uint8_t value) {
  for (int i = 0; i < 4; i++) {
    digitalWrite(_data_pins[i], (value >> i) & 0x01);
  }
  pulseEnable();
}

// Send 8 bits of data
void LiquidCrystal::write8bits(uint8_t value) {
  for (int i = 0; i < 8; i++) {
    digitalWrite(_data_pins[i], (value >> i) & 0x01);
  }
  pulseEnable();
}

