} // namespace mlir

using namespace mlir;
using namespace mlir::hacc;

struct FuncRenamerPass : public impl::HACCRenameFunctionBase<FuncRenamerPass> {
public:
  void runOnOperation() override;
};

void FuncRenamerPass::runOnOperation() {
  auto module = getOperation();
  module->walk([&](func::FuncOp functionOp) {
    auto renameAttr =
        functionOp->getAttrOfType<hacc::RenameFuncAttr>(hacc::RenameFuncAttr::name);
    if (!renameAttr)
      return;

    auto targetName = renameAttr.getTargetName();
    if (targetName.name.empty()) {
      functionOp.emitOpError() << "invalid target function name: " << targetName;
      signalPassFailure();
      return;
    }

    // Check for name conflicts before renaming
    auto existingFunc = SymbolTable::lookupNearestSymbolFrom(functionOp, targetName);
    if (existingFunc) {
      functionOp.emitOpError()
          << "cannot rename function to @" << targetName.getValue()
          << " since another function with this name already exists!";
      signalPassFailure();
      return;
    }

    // Replace all symbol references to the old name
    if (failed(SymbolTable::replaceAllSymbolUses(functionOp.getSymNameAttr(),
                                                 targetName.getAttr(), module))) {
      functionOp.emitOpError() << "failed to update symbol references during rename!";
      signalPassFailure();
      return;
    }

    // Apply the new name and remove the temporary attribute
    functionOp->removeAttr(hacc::RenameFuncAttr::name);
    functionOp.setSymName(targetName.getAttr());
  });
}

std::unique_ptr<Pass> mlir::hacc::createRenameFuncPass() {
  return std::make_unique<FuncRenamerPass>();
}

