#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

class Solution {
public:
    void nextPermutation(vector<int>& arr) {
        int size = arr.size();
        int pivot = -1;

        // Step 1: Locate the first index from the right where arr[i] < arr[i+1]
        for (int idx = size - 2; idx >= 0; idx--) {
            if (arr[idx] < arr[idx + 1]) {
                pivot = idx;
                break;
            }
        }

        if (pivot == -1) {
            // If no such index exists, array is in descending order. Reverse whole array
            reverse(arr.begin(), arr.end());
        } else {
            // Step 2: Find the rightmost element greater than arr[pivot] in suffix
            for (int jdx = size - 1; jdx > pivot; jdx--) {
                if (arr[jdx] > arr[pivot]) {
                    swap(arr[jdx], arr[pivot]);
                    break;
                }
            }
            // Step 3: Reverse the elements after the pivot position
            reverse(arr.begin() + pivot + 1, arr.end());
        }
    }
};

