    preset.slope_decay_rate = -5.0f;
    preset.slope_smoothing_tau = -0.04f;
    preset.gain = -1.0f;

    // Apply the preset — should clamp all invalid values
    preset.Apply(engine);

    // Confirm clamping occurred in engine internals
    ASSERT_GE(engine.m_lockup_gamma, 0.1f);
    ASSERT_GE(engine.m_notch_q, 0.1f);
    ASSERT_GE(engine.m_wheelbase_max_nm, 1.0f);
    ASSERT_GE(engine.m_optimal_slip_angle, 0.01f);
    ASSERT_GE(engine.m_optimal_slip_ratio, 0.01f);
    ASSERT_GE(engine.m_slope_alpha_threshold, 0.001f);
    ASSERT_GE(engine.m_slope_decay_rate, 0.1f);
    ASSERT_GE(engine.m_slope_smoothing_tau, 0.001f);
    ASSERT_GE(engine.m_gain, 0.0f);

    // Execute a simulation frame to ensure no crash or NaN output
    TelemInfoV01 telemetry = CreateBasicTestTelemetry(20.0, 0.05);
    double output_force = engine.calculate_force(&telemetry);
    ASSERT_TRUE(!std::isnan(output_force));
