TEST_CASE(test_config_load_validation, "Stability") {
    std::cout << "\nTest: Config Load Validation (v0.7.16)" << std::endl;
    std::string config_path = "test_bad_config.ini";

    {
        std::ofstream cfg_file(config_path);
        cfg_file << "gain=-1.5\n";
        cfg_file << "max_torque_ref=0.0\n";
        cfg_file << "lockup_gamma=-2.0\n";
        cfg_file << "optimal_slip_angle=0.0\n";
        cfg_file << "slope_sg_window=4\n"; // Invalid: even and too small
    }

    FFBEngine engine;
    Config::Load(engine, config_path);

