    ASSERT_GE(engine.m_gain, 0.0f);
    ASSERT_GE(engine.m_wheelbase_max_nm, 1.0f);
    ASSERT_GE(engine.m_lockup_gamma, 0.1f);
    ASSERT_GE(engine.m_optimal_slip_angle, 0.01f);
    ASSERT_TRUE(engine.m_slope_sg_window >= 5);
    ASSERT_TRUE(engine.m_slope_sg_window % 2 != 0);

    // Clean up test file
    std::remove(config_path.c_str());
}

TEST_CASE(test_engine_robustness_to_static_telemetry, "Stability") {
    std::cout << "\nTest: Engine Robustness to Static Telemetry (v0.7.16)" << std::endl;
    FFBEngine engine;
    InitializeEngine(engine);

    // Disable oscillators to prevent non-deterministic behavior
    engine.m_bottoming_enabled = false;

    TelemInfoV01 telemetry = CreateBasicTestTelemetry(20.0, 0.05);
    telemetry.mDeltaTime = 0.0025;

    double initial_force = engine.calculate_force(&telemetry);

    // Simulate many identical frames (e.g., game freeze scenario)
    for (int iteration = 0; iteration < 100; ++iteration) {
        double current_force = engine.calculate_force(&telemetry);
        ASSERT_TRUE(!std::isnan(current_force));
        // Force must remain constant under static input
        ASSERT_NEAR(current_force, initial_force, 0.0001);
    }
}
