constexpr char16_t const *gSupportedEscapes = u"acefnrtuUx";

// Unicode set pattern corresponding to \w (word characters)
constexpr char16_t const *gWordPattern = u"[\\p{Alphabetic}\\p{M}\\p{Nd}\\p{Pc}\\u200c\\u200d]";

