constexpr char16_t const *gGC_ExtendingChars = u"[\\p{Grapheme_Extend}]";
constexpr char16_t const *gGC_LBase = u"[\\p{Hangul_Syllable_Type=L}]";
constexpr char16_t const *gGC_Vowel = u"[\\p{Hangul_Syllable_Type=V}]";
constexpr char16_t const *gGC_Tail = u"[\\p{Hangul_Syllable_Type=T}]";
constexpr char16_t const *gGC_LV = u"[\\p{Hangul_Syllable_Type=LV}]";
constexpr char16_t const *gGC_LVT = u"[\\p{Hangul_Syllable_Type=LVT}]";

RegexStaticSets *RegexStaticSets::gSharedSets = nullptr;
UInitOnce gStaticInitOnce {};

// Constructor: initialize all static sets
RegexStaticSets::RegexStaticSets(UErrorCode *errCode) {
    // Initialize escape character set
    fEscapeCharSet.addAll(UnicodeString(true, gSupportedEscapes, -1)).freeze();

    // Initialize property sets from patterns
    fPropSets[URX_ISWORD_SET].applyPattern(UnicodeString(true, gWordPattern, -1), *errCode).freeze();
    fPropSets[URX_ISSPACE_SET].applyPattern(UnicodeString(true, gWhitespacePattern, -1), *errCode).freeze();
    fPropSets[URX_GC_EXTEND].applyPattern(UnicodeString(true, gGC_ExtendingChars, -1), *errCode).freeze();
    fPropSets[URX_GC_CONTROL].applyPattern(UnicodeString(true, gGC_ControlChars, -1), *errCode).freeze();
    fPropSets[URX_GC_L].applyPattern(UnicodeString(true, gGC_LBase, -1), *errCode).freeze();
    fPropSets[URX_GC_V].applyPattern(UnicodeString(true, gGC_Vowel, -1), *errCode).freeze();
    fPropSets[URX_GC_T].applyPattern(UnicodeString(true, gGC_Tail, -1), *errCode).freeze();
    fPropSets[URX_GC_LV].applyPattern(UnicodeString(true, gGC_LV, -1), *errCode).freeze();
    fPropSets[URX_GC_LVT].applyPattern(UnicodeString(true, gGC_LVT, -1), *errCode).freeze();

    // Build the "normal" grapheme cluster set: complement of control + L/V/T/LV/LVT
    fPropSets[URX_GC_NORMAL].complement();
    fPropSets[URX_GC_NORMAL].remove(0xac00, 0xd7a4);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_CONTROL]);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_L]);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_V]);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_T]);
    fPropSets[URX_GC_NORMAL].freeze();

    // Initialize 8-bit fast bit sets (optional optimization)
    for (int32_t idx = 0; idx < URX_LAST_SET; idx++) {
        fPropSets8[idx].init(&fPropSets[idx]);
    }

    // Rule-specific sets used during pattern parsing
    fRuleSets[kRuleSet_rule_char-128]
            .addAll(UnicodeString(gRuleSet_special_chars)).complement().freeze();
    fRuleSets[kRuleSet_digit_char-128].add(u'0', u'9').freeze();
    fRuleSets[kRuleSet_ascii_letter-128].add(u'A', u'Z').add(u'a', u'z').freeze();
    fDigitAlias = &fRuleSets[kRuleSet_digit_char-128];

    // Prepare an empty UText for internal use
    fEmptyText = utext_openUChars(nullptr, nullptr, 0, errCode);
}

// Destructor: clean up resources
RegexStaticSets::~RegexStaticSets() {
    fDigitAlias = nullptr;
    utext_close(fEmptyText);
