}

static void U_CALLCONV initSharedSets(UErrorCode &status) {
    U_ASSERT(RegexStaticSets::gSharedSets == nullptr);
    ucln_i18n_registerCleanup(UCLN_I18N_REGEX, regex_mem_cleanup);
    RegexStaticSets::gSharedSets = new RegexStaticSets(&status);
