static FLOAT dp1 = 1.0;

blasint CNAME(blas_arg_t *args, BLASLONG *range_m, BLASLONG *range_n, FLOAT *sa, FLOAT *sb, BLASLONG myid) {
  BLASLONG m_count, ld;
  FLOAT *matrix_a;
  FLOAT buffer[2];
  BLASLONG idx;

  m_count = args->n;
  matrix_a = (FLOAT *)args->a;
  ld = args->lda;

  if (range_n) {
    m_count = range_n[1] - range_n[0];
    matrix_a += range_n[0] * (ld + 1) * COMPSIZE;
  }

  for (idx = 0; idx < m_count; idx++) {
    SCAL_K(idx + 1, 0, 0,
           *(matrix_a + (idx + idx * ld) * COMPSIZE + 0), ZERO,
           matrix_a + idx * ld * COMPSIZE, 1, NULL, 0, NULL, 0);

    if (idx < m_count - 1) {
      buffer[0] = DOTC_K(m_count - idx - 1,
                         matrix_a + (idx + (idx + 1) * ld) * COMPSIZE, ld,
                         matrix_a + (idx + (idx + 1) * ld) * COMPSIZE, ld);
      GET_IMAGE(buffer[1]);

      *(matrix_a + (idx + idx * ld) * COMPSIZE + 0) += buffer[0];
      *(matrix_a + (idx + idx * ld) * COMPSIZE + 1) = ZERO;

      GEMV_O(idx, m_count - idx - 1, 0, dp1, ZERO,
             matrix_a + ((idx + 1) * ld) * COMPSIZE, ld,
             matrix_a + (idx + (idx + 1) * ld) * COMPSIZE, ld,
             matrix_a + (idx * ld) * COMPSIZE, 1, sb);
    }
  }
  return 0;
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <chrono>
using namespace std;

int main() {
    // Speed up input/output operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int nodes, edges;
    if (!(cin >> nodes >> edges)) return 0;

    // Graph representation using adjacency list (1-indexed)
    vector<vector<int>> graph(nodes + 1);
    for (int i = 0; i < edges; ++i) {
        int a, b;
        cin >> a >> b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    // Track best partition and maximum cut size
    vector<int> optimal_partition(nodes + 1, 0);
    long long best_cut_value = -1;

    // Time budget management
    const double max_duration = 0.90;
    auto start_timestamp = chrono::high_resolution_clock::now();

    // Random number generator seeded with current time
    mt19937_64 prng(chrono::steady_clock::now().time_since_epoch().count());

    // Vertex ordering for random traversal
    vector<int> order(nodes);
    iota(order.begin(), order.end(), 1);
    vector<int> trial_partition(nodes + 1);

    // Iterative refinement loop
    while (true) {
        // Random initial assignment
        for (int idx = 1; idx <= nodes; ++idx) {
            trial_partition[idx] = prng() & 1;
        }

        // Local search phase: flip vertices to improve cut
        bool changed = true;
        while (changed) {
            changed = false;
            shuffle(order.begin(), order.end(), prng);

            for (int vertex : order) {
                int same_group = 0;
                int other_group = 0;

                for (int neighbor : graph[vertex]) {
                    if (trial_partition[vertex] == trial_partition[neighbor]) {
                        same_group++;
                    } else {
                        other_group++;
                    }
                }

                // Move vertex if it increases cut size
                if (same_group > other_group) {
                    trial_partition[vertex] ^= 1;
                    changed = true;
                }
            }
        }

        // Evaluate current solution
        long long cut_size = 0;
        for (int i = 1; i <= nodes; ++i) {
            if (trial_partition[i] == 0) {
                for (int j : graph[i]) {
                    if (trial_partition[j] == 1) {
                        cut_size++;
                    }
                }
            }
        }

        // Update best known solution
        if (cut_size > best_cut_value) {
            best_cut_value = cut_size;
            optimal_partition = trial_partition;
        }

        // Check time constraint
        auto now = chrono::high_resolution_clock::now();
        chrono::duration<double> diff = now - start_timestamp;
        if (diff.count() >= max_duration) break;
    }

    // Output final partition
    for (int i = 1; i <= nodes; ++i) {
        cout << optimal_partition[i];
        if (i < nodes) cout << " ";
    }
    cout << "\n";

    return 0;
}

