class Solution {
public:
    // Determine if Alice can win based on vowel presence in the string
    bool doesAliceWin(std::string text) {
        // Check each character for vowels using bit manipulation
        for (int index = 0; index < text.length(); ++index) {
            int charPosition = text[index] - 'a';
            if ((0x104111 >> charPosition) & 1) {
                return true;
            }
        }
        return false;
    }
};

