TEST(PythonVersionParsing, TryScanVersionVariant) {
    struct TestCaseData {
        TString InputString;
        bool IsExpectedToSucceed;
        TPythonVersion ExpectedParsedVersion;
    };

    TVector<TestCaseData> testCases = {
        {"Python 3.10.0", true, {3, 10, 0}},
        {"Python 3.10.1", true, {3, 10, 1}},
        {"Python 2.7", true, {2, 7, 0}},
        {"Python 2.7.10", true, {2, 7, 10}},
        {"Python 3.8.15", true, {3, 8, 15}},
        {"Python 3.12.0", true, {3, 12, 0}},
        {"Python 3.12.1", true, {3, 12, 1}},
        {"Python 2.8.3", true, {2, 8, 3}},
        {"Python version 3.10.0, 64 bit", true, {3, 10, 0}},
        {"Version: Python 2.7.15", true, {2, 7, 15}},
        {"Python 4.0.0", false, {}},  // Major not 2 or 3
        {"No version here", false, {}},
        {"Python v9.8.7", false, {}},
    };

    for (const auto& testCase : testCases) {
        TMaybe<TPythonVersion> parsedResult = TryScanVersion(
            TConstArrayRef<char>{testCase.InputString.data(), testCase.InputString.size()}
        );

        if (testCase.IsExpectedToSucceed) {
            ASSERT_TRUE(parsedResult.Defined()) 
                << "Failed to parse version from string: '" << testCase.InputString << "'";

            TString expectedStr = std::to_string(testCase.ExpectedParsedVersion.MajorVersion) + "." +
                                  std::to_string(testCase.ExpectedParsedVersion.MinorVersion) + "." +
                                  std::to_string(testCase.ExpectedParsedVersion.MicroVersion);

            TString actualStr = std::to_string(parsedResult->MajorVersion) + "." +
                                std::to_string(parsedResult->MinorVersion) + "." +
                                std::to_string(parsedResult->MicroVersion);

            EXPECT_EQ(parsedResult->MajorVersion, testCase.ExpectedParsedVersion.MajorVersion)
                << "Major version mismatch for input: '" << testCase.InputString
                << "', expected: " << expectedStr << ", got: " << actualStr;

            EXPECT_EQ(parsedResult->MinorVersion, testCase.ExpectedParsedVersion.MinorVersion)
                << "Minor version mismatch for input: '" << testCase.InputString
                << "', expected: " << expectedStr << ", got: " << actualStr;

            EXPECT_EQ(parsedResult->MicroVersion, testCase.ExpectedParsedVersion.MicroVersion)
                << "Micro version mismatch for input: '" << testCase.InputString
                << "', expected: " << expectedStr << ", got: " << actualStr;
        } else {
            EXPECT_FALSE(parsedResult.Defined())
                << "Should not parse version from string: '" << testCase.InputString << "'";
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int rows, columns;
    cin >> rows >> columns;

    vector<vector<int>> stacks(rows + 2);
    set<int> unique_colors;

    // Read input and populate stacks
    for (int i = 1; i <= rows; i++) {
        for (int j = 0; j < columns; j++) {
            int color_value;
            cin >> color_value;
            stacks[i].push_back(color_value);
            unique_colors.insert(color_value);
        }
    }

    // Convert set to vector for indexed access
    vector<int> color_array(unique_colors.begin(), unique_colors.end());

    // Map each color to its target stack position
    map<int, int> destination_stack;
    for (int idx = 0; idx < rows; idx++) {
        destination_stack[color_array[idx]] = idx + 1;
    }

    vector<pair<int, int>> operations;
    int helper_stack = rows + 1;

    // First phase: move all elements to helper stack
    for (int src = 1; src <= rows; src++) {
        while (!stacks[src].empty()) {
            int current_color = stacks[src].back();
            stacks[src].pop_back();
            stacks[helper_stack].push_back(current_color);
            operations.push_back({src, helper_stack});
        }
    }

    // Second phase: move from helper stack to correct destinations
    while (!stacks[helper_stack].empty()) {
        int current_color = stacks[helper_stack].back();
        stacks[helper_stack].pop_back();
        int target = destination_stack[current_color];
        stacks[target].push_back(current_color);
        operations.push_back({helper_stack, target});
    }

    cout << operations.size() << endl;
    for (auto& op : operations) {
        cout << op.first << " " << op.second << endl;
    }

    return 0;
}

