// Helper function to print list of loaded modules
void DisplayLoadedModules() {
    try {
        LogInfo("=== LOADED MODULES ===");
        HANDLE proc_handle = GetCurrentProcess();
        HMODULE module_handles[1024];
        DWORD bytes_required;
        if (EnumProcessModules(proc_handle, module_handles, sizeof(module_handles), &bytes_required) == 0) {
            std::ostringstream err_msg;
            err_msg << "Failed to enumerate modules - Error: " << GetLastError();
            LogInfo("%s", err_msg.str().c_str());
            LogInfo("=== END LOADED MODULES ===");
            return;
        }

        DWORD module_count = bytes_required / sizeof(HMODULE);
        std::ostringstream count_msg;
        count_msg << "Total modules loaded: " << module_count;
        LogInfo("%s", count_msg.str().c_str());

        for (DWORD idx = 0; idx < module_count; ++idx) {
            wchar_t module_path[MAX_PATH];
            if (GetModuleFileNameW(module_handles[idx], module_path, MAX_PATH) != 0) {
                int required_bytes = WideCharToMultiByte(CP_UTF8, 0, module_path, -1, nullptr, 0, nullptr, nullptr);
                if (required_bytes > 0) {
                    std::vector<char> buffer(required_bytes);
                    WideCharToMultiByte(CP_UTF8, 0, module_path, -1, buffer.data(), required_bytes, nullptr, nullptr);
                    MODULEINFO mod_info = {};
                    std::ostringstream mod_msg;
                    if (GetModuleInformation(proc_handle, module_handles[idx], &mod_info, sizeof(mod_info)) != 0) {
                        mod_msg << "  [" << idx << "] " << buffer.data() << " (Base: 0x" << std::hex << std::uppercase
                                << reinterpret_cast<uintptr_t>(mod_info.lpBaseOfDll) << ", Size: " << std::dec
                                << mod_info.SizeOfImage << " bytes)";
                    } else {
                        mod_msg << "  [" << idx << "] " << buffer.data();
                    }
                    LogInfo("%s", mod_msg.str().c_str());
                }
            } else {
                std::ostringstream mod_msg;
                mod_msg << "  [" << idx << "] <Unknown Module> (Handle: 0x" << std::hex << std::uppercase
                        << reinterpret_cast<uintptr_t>(module_handles[idx]) << ")";
                LogInfo("%s", mod_msg.str().c_str());
            }
        }

        LogInfo("=== END LOADED MODULES ===");
    } catch (...) {
        LogInfo("=== LOADED MODULES ERROR ===");
        LogInfo("Exception occurred while enumerating loaded modules");
        LogInfo("=== END LOADED MODULES ===");
    }
}

// Shared crash report: header, optional section context, version/system/process info,
// exception details, memory load, recent detour calls, undestroyed guards, stack trace, loaded modules.
void GenerateCrashReport(PEXCEPTION_POINTERS ex_ptrs, const char* title, bool include_section_context) {
    LogInfo("%s", title);

    if (include_section_context) {
        const char* monitoring_state = g_continuous_monitoring_section.load(std::memory_order_acquire);
        const char* rendering_state = g_rendering_ui_section.load(std::memory_order_acquire);
        std::ostringstream section_msg;
        section_msg << "g_continuous_monitoring_section: "
                    << (monitoring_state ? monitoring_state : "(null)");
        LogInfo("%s", section_msg.str().c_str());
        section_msg.str("");
        section_msg << "g_rendering_ui_section: " << (rendering_state ? rendering_state : "(null)");
        LogInfo("%s", section_msg.str().c_str());
    }

    DisplayVersionDetails();
    DisplaySystemDetails();
    DisplayProcessDetails();

    if (ex_ptrs && ex_ptrs->ExceptionRecord) {
        const EXCEPTION_RECORD* rec = ex_ptrs->ExceptionRecord;
        std::ostringstream oss;
        oss << "Exception Code: 0x" << std::hex << std::uppercase << rec->ExceptionCode;
        LogInfo("%s", oss.str().c_str());
        oss.str("");
        oss << "Exception Flags: 0x" << std::hex << std::uppercase << rec->ExceptionFlags;
        LogInfo("%s", oss.str().c_str());
        oss.str("");
        oss << "Exception Address: 0x" << std::hex << std::uppercase
            << reinterpret_cast<uintptr_t>(rec->ExceptionAddress);
        LogInfo("%s", oss.str().c_str());
    }

    MEMORYSTATUSEX mem_status = {};
    mem_status.dwLength = sizeof(mem_status);
    if (GlobalMemoryStatusEx(&mem_status)) {
        std::ostringstream mem_details;
        mem_details << "System Memory Load: " << mem_status.dwMemoryLoad << "%";
        LogInfo("%s", mem_details.str().c_str());
    }

    uint64_t crash_timestamp_ns = utils::get_real_time_ns();
    std::string recent_detour_info = detour_call_tracker::FormatRecentDetourCalls(crash_timestamp_ns, 256);
    LogInfo("=== RECENT DETOUR CALLS ===");
    exit_handler::WriteMultiLineToDebugLog(recent_detour_info, "Recent Detour Calls: <none recorded>");
    LogInfo("=== END RECENT DETOUR CALLS ===");

    std::string undestroyed_guards_info = detour_call_tracker::FormatUndestroyedGuards(crash_timestamp_ns);
    LogInfo("=== UNDESTROYED DETOUR GUARDS (CRASH DETECTION) ===");
    exit_handler::WriteMultiLineToDebugLog(undestroyed_guards_info, "Undestroyed Detour Guards: 0");
    LogInfo("=== END UNDESTROYED DETOUR GUARDS ===");

    LogInfo("=== GENERATING STACK TRACE ===");
    CONTEXT* ctx_record =
        (ex_ptrs && ex_ptrs->ContextRecord) ? ex_ptrs->ContextRecord : nullptr;
    auto stack_frames = stack_trace::GenerateStackTrace(ctx_record);
    LogInfo("=== STACK TRACE ===");
    for (const auto& frame : stack_frames) {
        LogInfo("%s", frame.c_str());
    }
    LogInfo("=== END STACK TRACE ===");

    DisplayLoadedModules();
    display_commander::logger::FlushLogs();
}
