namespace process_exit_hooks {
std::atomic<bool> g_initialized{false};
std::atomic<LPTOP_LEVEL_EXCEPTION_FILTER> g_previous_seh_filter{nullptr};
PVOID g_vectored_exception_handle = nullptr;

void OnProcessExit() {
    // Log exit detection
    exit_handler::OnHandleExit(exit_handler::ExitSource::ATEXIT, "Normal process exit via atexit");
}

LONG WINAPI HandleUnhandledException(EXCEPTION_POINTERS* ex_info) {
    // Check if shutdown is in progress to avoid crashes during DLL unload
    if (g_shutdown.load()) {
        return EXCEPTION_EXECUTE_HANDLER;
    }

    // Check if we've seen this exception address before
    uintptr_t exc_addr = 0;
    if (ex_info && ex_info->ExceptionRecord) {
        exc_addr = reinterpret_cast<uintptr_t>(ex_info->ExceptionRecord->ExceptionAddress);
        if (IsExceptionAddressDuplicate(exc_addr)) {
            return EXCEPTION_EXECUTE_HANDLER;
        }
    }

    dbghelp_loader::LoadDbgHelp();
    GenerateCrashReport(ex_info, "=== CRASH DETECTED - DETAILED REPORT ===", false);
    return EXCEPTION_EXECUTE_HANDLER;
}

// Vectored exception handler - catches exceptions early and prints stack traces
LONG WINAPI HandleVectoredException(PEXCEPTION_POINTERS ex) {
    // Check if shutdown is in progress to avoid crashes during DLL unload
    if (g_shutdown.load()) {
        return EXCEPTION_CONTINUE_SEARCH;
    }

    // Ignore debugging and some common language exceptions
    const DWORD code = ex->ExceptionRecord->ExceptionCode;
    if (code == CONTROL_C_EXIT || code == 0x406D1388 /* SetThreadName */ || code == DBG_PRINTEXCEPTION_C
        || code == DBG_PRINTEXCEPTION_WIDE_C || code == STATUS_BREAKPOINT
        || code == 0xE0434352 /* CLR exception */ || code == 0xE06D7363 /* Visual C++ exception */
        || ((code ^ 0xE24C4A00) <= 0xFF) /* LuaJIT exception */) {
        return EXCEPTION_CONTINUE_SEARCH;
    }

    // Check if we've seen this exception address before
    uintptr_t exc_addr = 0;
    if (ex && ex->ExceptionRecord) {
        exc_addr = reinterpret_cast<uintptr_t>(ex->ExceptionRecord->ExceptionAddress);
        if (IsExceptionAddressDuplicate(exc_addr)) {
            std::ostringstream skip_msg;
            skip_msg << "Vectored exception at address 0x" << std::hex << std::uppercase << exc_addr
                     << " already logged, skipping duplicate report";
            LogInfo("%s", skip_msg.str().c_str());
            return EXCEPTION_CONTINUE_SEARCH;
        }
    }

    dbghelp_loader::LoadDbgHelp();
    GenerateCrashReport(ex, "=== VECTORED EXCEPTION HANDLER - CRASH DETECTED ===", true);
    return EXCEPTION_CONTINUE_SEARCH;
}

void Initialize() {
    bool expected = false;
    if (!g_initialized.compare_exchange_strong(expected, true)) {
        return;
    }

    // atexit for graceful exits
    std::atexit(&OnProcessExit);

    // SEH unhandled exception filter for most crash scenarios
    LogInfo("Installing SEH unhandled exception filter");
    g_previous_seh_filter = ::SetUnhandledExceptionFilter(&HandleUnhandledException);

    // Install vectored exception handler to catch exceptions early
    LogInfo("Installing vectored exception handler");
    g_vectored_exception_handle = ::AddVectoredExceptionHandler(1, &HandleVectoredException);
    if (g_vectored_exception_handle == nullptr) {
        LogInfo("Failed to install vectored exception handler");
    } else {
        LogInfo("Vectored exception handler installed successfully");
    }
}

void Shutdown() {
    bool expected = true;
    if (!g_initialized.compare_exchange_strong(expected, false)) {
        return;
    }

    // Restore previous unhandled exception filter
    ::SetUnhandledExceptionFilter(g_previous_seh_filter);
    g_previous_seh_filter.store(nullptr);

    // Remove vectored exception handler
    if (g_vectored_exception_handle != nullptr) {
        ::RemoveVectoredExceptionHandler(g_vectored_exception_handle);
        g_vectored_exception_handle = nullptr;
        LogInfo("Vectored exception handler removed");
    }

    // Clear seen exception addresses
    {
        utils::SRWLockExclusive lock(utils::g_seen_exception_addresses_lock);
        g_exception_address_cache.clear();
    }
}
}  // namespace process_exit_hooks

