/// Eliminate barriers (if not already handled by the GCStrategy), and add
/// defensive stores to roots to guarantee initialization before the first
/// safepoint. Since all roots are considered live at every safepoint, we must
/// ensure each root is initialized prior to reaching the first safepoint.
/// This step is ideally performed by the frontend, but due to historical API
/// limitations, we insert potentially redundant stores as a safeguard.
static bool PerformReduction(Function &Func, GCStrategy &Strategy);

namespace {
/// ReduceGCIntrinsics - Transform calls to llvm.gcread or llvm.gcwrite into
/// basic loads/stores per GCStrategy directives. Also handles automatic root
/// initialization and custom intrinsic lowering.
class ReduceGCIntrinsics : public FunctionPass {
public:
  static char ID;
  ReduceGCIntrinsics();
  StringRef getPassName() const override;
  void getAnalysisUsage(AnalysisUsage &AU) const override;
  bool doInitialization(Module &M) override;
  bool runOnFunction(Function &F) override;
};

/// GCCodeAnalysis - A target-independent pass over machine functions to locate
/// garbage collection safe points in the generated machine code. Inserts labels
/// at safe points and populates GCMetadata for each function.
class GCCodeAnalysis : public MachineFunctionPass {
  GCFunctionInfo *FuncInfo = nullptr;
  const TargetInstrInfo *TII = nullptr;
  void LocateSafePoints(MachineFunction &MF);
  void ProcessCallSite(MachineBasicBlock::iterator CallInstr);
  MCSymbol *EmitLabel(MachineBasicBlock &MBB,
                      MachineBasicBlock::iterator InstrIter,
                      const DebugLoc &DL) const;
  void ComputeStackOffsets(MachineFunction &MF);
public:
  static char ID;
  GCCodeAnalysis();
  void getAnalysisUsage(AnalysisUsage &AU) const override;
  bool runOnMachineFunction(MachineFunction &MF) override;
};
}

PreservedAnalyses GCReductionPass::run(Function &F,
                                       FunctionAnalysisManager &FAM) {
  auto &Info = FAM.getResult<GCFunctionAnalysis>(F);
  bool Modified = PerformReduction(F, Info.getStrategy());
  if (!Modified)
    return PreservedAnalyses::all();
  PreservedAnalyses PA;
  PA.preserve<DominatorTreeAnalysis>();
  return PA;
}

