bool ReduceGCIntrinsics::doInitialization(Module &M) {
  GCModuleInfo *MI = getAnalysisIfAvailable<GCModuleInfo>();
  assert(MI && "ReduceGCIntrinsics did not require GCModuleInfo!?");
  for (Function &F : M)
    if (!F.isDeclaration() && F.hasGC())
      MI->getFunctionInfo(F); // Instantiate the GC strategy.
  return false;
}

static bool CouldBecomeSafepoint(Instruction *Inst) {
  // Conservatively assume instructions that aren't purely local could become
  // safepoints:
  //
  //   - call, invoke (AfterCall, BeforeCall)
  //   - phis (Loops)
  //   - invoke, ret, unwind (Exit)
  //
  // Even simple operations like arithmetic may turn into library calls during
  // lowering (e.g., i64 division on 32-bit platforms), so we err on the side
  // of caution.
  if (isa<AllocaInst>(Inst) || isa<GetElementPtrInst>(Inst) ||
      isa<StoreInst>(Inst) || isa<LoadInst>(Inst))
    return false;
  if (CallInst *CI = dyn_cast<CallInst>(Inst))
    if (Function *Callee = CI->getCalledFunction())
      if (Intrinsic::ID IID = Callee->getIntrinsicID())
        if (IID == Intrinsic::gcroot)
          return false;
  return true;
}

static bool InitializeRoots(Function &Func, ArrayRef<AllocaInst *> Roots) {
  BasicBlock::iterator InsertPos = Func.getEntryBlock().begin();
  while (isa<AllocaInst>(InsertPos))
    ++InsertPos;

  SmallPtrSet<AllocaInst *, 16> AlreadyInitialized;
  for (; !CouldBecomeSafepoint(&*InsertPos); ++InsertPos)
    if (StoreInst *SI = dyn_cast<StoreInst>(InsertPos))
      if (AllocaInst *AI =
              dyn_cast<AllocaInst>(SI->getOperand(1)->stripPointerCasts()))
        AlreadyInitialized.insert(AI);

  bool Changed = false;
  for (AllocaInst *Root : Roots)
    if (!AlreadyInitialized.count(Root)) {
      new StoreInst(
          ConstantPointerNull::get(cast<PointerType>(Root->getAllocatedType())),
          Root, Root->getNextNode());
      Changed = true;
    }
  return Changed;
}

bool ReduceGCIntrinsics::runOnFunction(Function &F) {
  if (!F.hasGC())
    return false;
  GCFunctionInfo &FI = getAnalysis<GCModuleInfo>().getFunctionInfo(F);
  GCStrategy &S = FI.getStrategy();
  return PerformReduction(F, S);
}

bool PerformReduction(Function &Func, GCStrategy &Strategy) {
  SmallVector<AllocaInst *, 32> Roots;
  bool Modified = false;

  for (BasicBlock &BB : Func)
    for (Instruction &I : llvm::make_early_inc_range(BB)) {
      IntrinsicInst *II = dyn_cast<IntrinsicInst>(&I);
      if (!II)
        continue;
      Function *Callee = II->getCalledFunction();
      switch (Callee->getIntrinsicID()) {
      default:
        break;
      case Intrinsic::gcwrite: {
        Value *StoreOp = new StoreInst(II->getArgOperand(0),
                                       II->getArgOperand(2), II);
        II->replaceAllUsesWith(StoreOp);
        II->eraseFromParent();
        Modified = true;
        break;
      }
      case Intrinsic::gcread: {
        Value *LoadOp = new LoadInst(II->getType(), II->getArgOperand(1), "", II);
        LoadOp->takeName(II);
        II->replaceAllUsesWith(LoadOp);
        II->eraseFromParent();
        Modified = true;
        break;
      }
      case Intrinsic::gcroot: {
        Roots.push_back(
            cast<AllocaInst>(II->getArgOperand(0)->stripPointerCasts()));
        break;
      }
      }
    }

  if (!Roots.empty())
    Modified |= InitializeRoots(Func, Roots);
  return Modified;
}

