INITIALIZE_PASS(GCCodeAnalysis, "gc-code-analysis",
                "Analyze Machine Code For Garbage Collection", false, false)

GCCodeAnalysis::GCCodeAnalysis() : MachineFunctionPass(ID) {}

void GCCodeAnalysis::getAnalysisUsage(AnalysisUsage &AU) const {
  MachineFunctionPass::getAnalysisUsage(AU);
  AU.setPreservesAll();
  AU.addRequired<GCModuleInfo>();
}

MCSymbol *GCCodeAnalysis::EmitLabel(MachineBasicBlock &MBB,
                                    MachineBasicBlock::iterator InstrIter,
                                    const DebugLoc &DL) const {
  MCSymbol *Label = MBB.getParent()->getContext().createTempSymbol();
  BuildMI(MBB, InstrIter, DL, TII->get(TargetOpcode::GC_LABEL)).addSym(Label);
  return Label;
}

void GCCodeAnalysis::ProcessCallSite(MachineBasicBlock::iterator CallInstr) {
  MachineBasicBlock::iterator NextInstr = CallInstr;
  ++NextInstr;
  MCSymbol *Label = EmitLabel(*CallInstr->getParent(), NextInstr,
                              CallInstr->getDebugLoc());
  FuncInfo->addSafePoint(Label, CallInstr->getDebugLoc());
}

void GCCodeAnalysis::LocateSafePoints(MachineFunction &MF) {
  for (MachineBasicBlock &MBB : MF)
    for (MachineInstr &MI : MBB)
      if (MI.isCall()) {
        if (MI.isTerminator())
          continue;
        ProcessCallSite(&MI);
      }
}

void GCCodeAnalysis::ComputeStackOffsets(MachineFunction &MF) {
  const TargetFrameLowering *TFI = MF.getSubtarget().getFrameLowering();
  assert(TFI && "TargetFrameLowering unavailable!");
  for (GCFunctionInfo::roots_iterator RI = FuncInfo->roots_begin();
       RI != FuncInfo->roots_end();) {
    if (MF.getFrameInfo().isDeadObjectIndex(RI->Num)) {
      RI = FuncInfo->removeStackRoot(RI);
    } else {
      Register FrameReg;
      auto FrameOffset = TFI->getFrameIndexReference(MF, RI->Num, FrameReg);
      assert(!FrameOffset.getScalable() &&
             "Scalable frame offsets unsupported");
      RI->StackOffset = FrameOffset.getFixed();
      ++RI;
    }
  }
}

bool GCCodeAnalysis::runOnMachineFunction(MachineFunction &MF) {
  if (!MF.getFunction().hasGC())
    return false;

  FuncInfo = &getAnalysis<GCModuleInfo>().getFunctionInfo(MF.getFunction());
  TII = MF.getSubtarget().getInstrInfo();

  const MachineFrameInfo &MFI = MF.getFrameInfo();
  const TargetRegisterInfo *RegInfo = MF.getSubtarget().getRegisterInfo();
  const bool HasDynamicFrame = MFI.hasVarSizedObjects() ||
                               RegInfo->hasStackRealignment(MF);
  FuncInfo->setFrameSize(HasDynamicFrame ? UINT64_MAX : MFI.getStackSize());

  if (FuncInfo->getStrategy().needsSafePoints())
    LocateSafePoints(MF);

  ComputeStackOffsets(MF);
  return false;
}

