#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;

    double baseMM = 10000.0;
    double baseXX = 20001.0;

    // Initial phase: estimate slope and intercept
    double startY = -300000000.0;
    double stepSize = 10000000.0;
    double endY = startY + stepSize;

    cout << "? " << baseXX << " " << startY << endl;
    cout.flush();
    double valStart;
    cin >> valStart;

    cout << "? " << baseXX << " " << endY << endl;
    cout.flush();
    double valEnd;
    cin >> valEnd;

    double initialSlope = (valEnd - valStart) / stepSize;
    double weight = -initialSlope;
    double intercept = valStart + startY * weight;

    double currentSlope = -weight;
    double currentIntercept = intercept;
    int lastA = -10001;

    vector<int> aList, bList;
    const double slopeTolerance = 1e-4;
    const double epsilon = 0.4;
    const double diffTolerance = 3e-5;

    for (int idx = 0; idx < N; idx++) {
        // Binary search to find next 'a'
        int left = lastA + 1;
        int right = 10000;

        while (left < right) {
            int mid = (left + right) / 2;
            double testY = mid * baseXX + baseMM;

            cout << "? " << baseXX << " " << testY << endl;
            cout.flush();
            double fTest;
            cin >> fTest;

            double testY2 = testY + epsilon;
            cout << "? " << baseXX << " " << testY2 << endl;
            cout.flush();
            double fTest2;
            cin >> fTest2;

            double localSlope = (fTest2 - fTest) / epsilon;
            if (localSlope > currentSlope + slopeTolerance) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        // Verify candidate 'a'
        int candidateA = left;
        double verifyY = candidateA * baseXX + baseMM;

        cout << "? " << baseXX << " " << verifyY << endl;
        cout.flush();
        double fVerify;
        cin >> fVerify;

        double verifyY2 = verifyY + epsilon;
        cout << "? " << baseXX << " " << verifyY2 << endl;
        cout.flush();
        double fVerify2;
        cin >> fVerify2;

        double verifySlope = (fVerify2 - fVerify) / epsilon;
        if (verifySlope <= currentSlope + slopeTolerance) {
            continue;
        }

        int finalA = candidateA;

        // Local binary search for precise p value
        double pLow = finalA * baseXX - baseMM;
        double pHigh = finalA * baseXX + baseMM;
        int localIter = 0;
        const int maxLocalIters = 60;

        while ((pHigh - pLow) > 1e-10 && localIter < maxLocalIters) {
            localIter++;
            double pMid = (pLow + pHigh) / 2.0;

            cout << "? " << baseXX << " " << pMid << endl;
            cout.flush();
            double fMid;
            cin >> fMid;

            double expected = currentSlope * pMid + currentIntercept;
            double deviation = fMid - expected;

            if (deviation > diffTolerance) {
                pHigh = pMid;
            } else {
                pLow = pMid;
            }
        }

        double approxP = (pLow + pHigh) / 2.0;
        long long aVal = llround(approxP / baseXX);
        double remainder = approxP - aVal * baseXX;
        double exactP = aVal * baseXX + round(remainder);
        long long bVal = llround(exactP - aVal * baseXX);

        aList.push_back((int)aVal);
        bList.push_back((int)bVal);

        // Update slope and intercept
        double aa = (double)aVal;
        double ww = 1.0 / sqrt(aa * aa + 1.0);
        double oldExp = currentSlope * exactP + currentIntercept;

        currentSlope += 2.0 * ww;
        currentIntercept = oldExp - currentSlope * exactP;
        lastA = (int)aVal;
    }

    // Output results
    cout << "!";
    for (int a : aList) cout << " " << a;
    for (int b : bList) cout << " " << b;
    cout << endl;
    cout.flush();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Connection {
    int from, via, to;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    if (N == 0) {
        cout << 0 << '\n';
        return 0;
    }

    int BLOCK_SIZE = (N + 5) / 4;
    if (BLOCK_SIZE < 1) BLOCK_SIZE = 1;

    vector<Connection> connections;
    long long estimated_capacity = (long long)(max(0, BLOCK_SIZE - 1)) * (N + 1) + (long long)(N + 1);
    connections.reserve(estimated_capacity);

    // Insert connections of distances 2 through BLOCK_SIZE: (i -> i+d) using intermediate node i+1
    for (int dist = 2; dist <= BLOCK_SIZE; dist++) {
        for (int idx = 0; idx + dist <= N; ++idx) {
            connections.push_back({idx, idx + 1, idx + dist});
        }
    }

    // Add connections of length 2*BLOCK_SIZE (if within bounds): (i -> i+2*BLOCK_SIZE) via intermediate i+BLOCK_SIZE
    int STEP = 2 * BLOCK_SIZE;
    if (STEP <= N) {
        for (int idx = 0; idx + STEP <= N; ++idx) {
            connections.push_back({idx, idx + BLOCK_SIZE, idx + STEP});
        }
    }

    cout << connections.size() << '\n';
    for (const auto &conn : connections) {
        cout << conn.from << ' ' << conn.via << ' ' << conn.to << '\n';
    }

    return 0;
}

