#include "llvm/Support/circular_raw_ostream.h"
#include <cstring>
using namespace llvm;

// Implementation for writing data to the circular buffer
void circular_raw_ostream::write_impl(const char *DataPtr, size_t DataSize) {
  // If no buffer is allocated, write directly to underlying stream
  if (BufferCapacity == 0) {
    UnderlyingStream->write(DataPtr, DataSize);
    return;
  }

  // Process data into circular buffer with wrapping as needed
  while (DataSize > 0) {
    size_t AvailableSpace = BufferCapacity - (CurrentPos - BufferStart);
    size_t CopyAmount = std::min(DataSize, AvailableSpace);

    memcpy(CurrentPos, DataPtr, CopyAmount);
    DataSize -= CopyAmount;
    CurrentPos += CopyAmount;

    // Handle buffer wrap-around
    if (CurrentPos == BufferStart + BufferCapacity) {
      CurrentPos = BufferStart;
      BufferFull = true;
    }
  }
}

// Flush buffer content preceded by banner message
void circular_raw_ostream::flushBufferWithBanner() {
  if (BufferCapacity != 0) {
    // Output banner text first
    UnderlyingStream->write(BannerText, std::strlen(BannerText));
    flushBuffer();
  }
}

