#define DEBUG_TYPE "lowerinvoke"

STATISTIC(NumReplacedInvokes, "Number of invokes replaced");

namespace {
  class LowerInvokeLegacyPass : public FunctionPass {
  public:
    static char ID; // Pass identification, replacement for typeid
    explicit LowerInvokeLegacyPass() : FunctionPass(ID) {
      initializeLowerInvokeLegacyPassPass(*PassRegistry::getPassRegistry());
    }
    bool runOnFunction(Function &func) override;
  };
}

char LowerInvokeLegacyPass::ID = 0;

INITIALIZE_PASS(LowerInvokeLegacyPass, "lowerinvoke",
                "Lower invoke and unwind, for unwindless code generators",
                false, false)

static bool processFunction(Function &func) {
  bool Modified = false;

  for (BasicBlock &block : func) {
    if (InvokeInst *invoke = dyn_cast<InvokeInst>(block.getTerminator())) {
      SmallVector<Value *, 16> arguments(invoke->args());
      SmallVector<OperandBundleDef, 1> bundles;
      invoke->getOperandBundlesAsDefs(bundles);

      // Create a regular call instruction
      CallInst *newCall = CallInst::Create(
          invoke->getFunctionType(),
          invoke->getCalledOperand(),
          arguments,
          bundles,
          "",
          invoke
      );

      newCall->takeName(invoke);
      newCall->setCallingConv(invoke->getCallingConv());
      newCall->setAttributes(invoke->getAttributes());
      newCall->setDebugLoc(invoke->getDebugLoc());

      // Replace all uses of the invoke with the call
      invoke->replaceAllUsesWith(newCall);

      // Add an unconditional branch to the normal destination
      BranchInst::Create(invoke->getNormalDest(), invoke);

      // Remove the exception destination as a predecessor
      invoke->getUnwindDest()->removePredecessor(&block);

      // Erase the original invoke instruction
      invoke->eraseFromParent();

      ++NumReplacedInvokes;
      Modified = true;
    }
  }

  return Modified;
}

bool LowerInvokeLegacyPass::runOnFunction(Function &F) {
  return processFunction(F);
}

namespace llvm {
  char &LowerInvokePassID = LowerInvokeLegacyPass::ID;

  // Public Interface To the LowerInvoke pass.
  FunctionPass *createLowerInvokePass() { 
    return new LowerInvokeLegacyPass(); 
  }

  PreservedAnalyses LowerInvokePass::run(Function &F,
                                         FunctionAnalysisManager &AM) {
    bool Changed = processFunction(F);

    if (!Changed)
      return PreservedAnalyses::all();

    return PreservedAnalyses::none();
  }
}

