#define HIP_CALL_CHECK(CMD)                                                                        \
    {                                                                                              \
        hipError_t status_ = (CMD);                                                                \
        if(status_ != hipSuccess)                                                                  \
        {                                                                                          \
            auto _guard = auto_lock_t{output_mutex};                                               \
            fprintf(stderr,                                                                        \
                    "%s:%d :: HIP failure : %s\n",                                                 \
                    __FILE__,                                                                      \
                    __LINE__,                                                                      \
                    hipGetErrorString(status_));                                                   \
            throw std::runtime_error("hip_call_failed");                                           \
        }                                                                                          \
    }
namespace
{
using lock_guard_t                     = std::unique_lock<std::mutex>;
std::mutex         output_mutex        {};
size_t             num_threads         = 2;
size_t             num_iterations      = 500;
size_t             sync_interval       = 10;
constexpr unsigned tile_size           = 32;
void
check_last_hip_error();
void
validate(int* src, int* dst, int rows, int cols);
}  // namespace
__global__ void
transpose_tile(int* input, int* output, int width, int height);
void
execute(int rank, int thread_id, hipStream_t stream, int argc, char** argv);
int
main(int argc, char** argv)
{
    int rank = 0;
    for(int i = 1; i < argc; ++i)
    {
        auto arg_str = std::string{argv[i]};
        if(arg_str == "?" || arg_str == "-h" || arg_str == "--help")
        {
            fprintf(stderr,
                    "usage: transpose [NUM_THREADS (%zu)] [NUM_ITERATIONS (%zu)] "
                    "[SYNC_EVERY_N (%zu)]\n",
                    num_threads,
                    num_iterations,
                    sync_interval);
            exit(EXIT_SUCCESS);
        }
    }
    if(argc > 1) num_threads = atoll(argv[1]);
    if(argc > 2) num_iterations = atoll(argv[2]);
    if(argc > 3) sync_interval = atoll(argv[3]);
    printf("[transpose] Thread count: %zu\n", num_threads);
    printf("[transpose] Iteration count: %zu\n", num_iterations);
    printf("[transpose] Synchronization every %zu iterations\n", sync_interval);
    // temporary workaround for omnitrace with HIP + MPI
    int device_count = 0;
    int device_id    = rank;
    HIP_CALL_CHECK(hipGetDeviceCount(&device_count));
    printf("[transpose] Devices available: %i\n", device_count);
    if(device_count > 0)
    {
        device_id = rank % device_count;
        HIP_CALL_CHECK(hipSetDevice(device_id));
        printf("[transpose] Rank %i mapped to device %i\n", rank, device_id);
    }
    if(rank == device_id && rank < device_count)
    {
        std::vector<std::thread> worker_threads{};
        std::vector<hipStream_t> streams(num_threads);
        for(size_t idx = 0; idx < num_threads; ++idx)
            HIP_CALL_CHECK(hipStreamCreate(&streams[idx]));
        for(size_t idx = 1; idx < num_threads; ++idx)
            worker_threads.emplace_back(execute, rank, idx, streams[idx], argc, argv);
        execute(rank, 0, streams[0], argc, argv);
        for(auto& worker : worker_threads)
            worker.join();
        for(size_t idx = 0; idx < num_threads; ++idx)
            HIP_CALL_CHECK(hipStreamDestroy(streams[idx]));
    }
    HIP_CALL_CHECK(hipDeviceSynchronize());
    HIP_CALL_CHECK(hipDeviceReset());
    return 0;
}
__global__ void
transpose_tile(int* input, int* output, int width, int height)
{
    __shared__ int block[tile_size][tile_size];
    int x = (blockIdx.y * blockDim.y + threadIdx.y) * width + blockIdx.x * blockDim.x + threadIdx.x;
    block[threadIdx.y][threadIdx.x] = input[x];
    __syncthreads();
    x      = (blockIdx.x * blockDim.x + threadIdx.y) * height + blockIdx.y * blockDim.y + threadIdx.x;
    output[x] = block[threadIdx.x][threadIdx.y];
}
void
execute(int rank, int tid, hipStream_t stream, int argc, char** argv)
{
    unsigned int M = 4960 * 2;
    unsigned int N = 4960 * 2;
    if(argc > 2) num_iterations = atoll(argv[2]);
    if(argc > 3) sync_interval = atoll(argv[3]);
    lock_guard_t lk{output_mutex};
    std::cout << "[transpose][" << rank << "][" << tid << "] Dimensions: M=" << M << ", N=" << N 
              << std::endl;
    lk.unlock();
    std::default_random_engine         rng{std::random_device{}() * (rank + 1) * (tid + 1)};
    std::uniform_int_distribution<int> dist{0, 1000};
    size_t buffer_size = sizeof(int) * M * N;
    int*   host_input  = new int[buffer_size];
    int*   host_output = new int[buffer_size];
    for(size_t idx = 0; idx < M * N; ++idx)
    {
        host_input[idx]  = dist(rng);
        host_output[idx] = 0;
    }
    int* device_input  = nullptr;
    int* device_output = nullptr;
    HIP_CALL_CHECK(hipMalloc(&device_input, buffer_size));
    HIP_CALL_CHECK(hipMalloc(&device_output, buffer_size));
    HIP_CALL_CHECK(hipMemsetAsync(device_input, 0, buffer_size, stream));
    HIP_CALL_CHECK(hipMemsetAsync(device_output, 0, buffer_size, stream));
    HIP_CALL_CHECK(hipMemcpyAsync(device_input, host_input, buffer_size, hipMemcpyHostToDevice, stream));
    HIP_CALL_CHECK(hipStreamSynchronize(stream));
    dim3 grid_dims(M / 32, N / 32, 1);
    dim3 block_dims(32, 32, 1);  // transpose_tile
    auto start_time = std::chrono::high_resolution_clock::now();
    for(size_t iter = 0; iter < num_iterations; ++iter)
    {
        transpose_tile<<<grid_dims, block_dims, 0, stream>>>(device_input, device_output, M, N);
        check_last_hip_error();
        if(iter % sync_interval == (sync_interval - 1)) HIP_CALL_CHECK(hipStreamSynchronize(stream));
    }
    auto end_time = std::chrono::high_resolution_clock::now();
    HIP_CALL_CHECK(hipStreamSynchronize(stream));
    HIP_CALL_CHECK(hipMemcpyAsync(host_output, device_output, buffer_size, hipMemcpyDeviceToHost, stream));
    double elapsed_seconds = std::chrono::duration_cast<std::chrono::duration<double>>(end_time - start_time).count();
    float  data_volume_GB  = static_cast<float>(buffer_size) * num_iterations * 2 / (1 << 30);
    output_mutex.lock();
    std::cout << "[" << rank << "][" << tid << "] Execution time: " << elapsed_seconds << " seconds\n"
              << "Average throughput: " << data_volume_GB / elapsed_seconds << " GB/s"
              << std::endl;
    output_mutex.unlock();
    HIP_CALL_CHECK(hipStreamSynchronize(stream));
    // cpu_transpose(host_input, host_output, M, N);
    validate(host_input, host_output, M, N);
    HIP_CALL_CHECK(hipFree(device_input));
    HIP_CALL_CHECK(hipFree(device_output));
    delete[] host_input;
    delete[] host_output;
}
namespace
{
void
check_last_hip_error()
{
    hipError_t err = hipGetLastError();
    if(err != hipSuccess)
    {
        lock_guard_t lk{output_mutex};
        std::cerr << "HIP error: " << hipGetErrorString(err) << std::endl;
        throw std::runtime_error("hip_api_call");
    }
}
void
validate(int* source, int* result, int rows, int cols)
{
    for(int k = 0; k < 10; ++k)
    {
        int r = rand() % rows;
        int c = rand() % cols;
        if(source[r * cols + c] != result[c * rows + r])
        {
            lock_guard_t lk{output_mutex};
            std::cout << "Mismatch at (" << r << "," << c << "): " 
                      << source[r * cols + c] << " vs " << result[c * rows + r] << "\n";
        }
    }
}
}  // namespace

