unsigned int NatSubUnderflowSafe::sub_checked(const unsigned int minuend,
                                              const unsigned int subtrahend) {
  unsigned int result = minuend - subtrahend;
  return ((result > minuend) ? 0 : result);
}

unsigned int NatSubUnderflowSafe::sub_alt(const unsigned int operand_a,
                                          const unsigned int operand_b) {
  unsigned int diff = operand_b - operand_a;
  return ((diff > operand_b) ? 0 : diff);
}

