DiskArrayCollection::DiskArrayCollection(FileHandle& fileRef, ShadowFile& shadowRef,
    bool skipShadowing)
    : fileHandle(fileRef), shadowFile{shadowRef}, bypassShadowing{skipShadowing},
      numHeaders{0} {
    headersForReadTrx.emplace_back(std::make_unique<HeaderPage>());
    headersForWriteTrx.emplace_back(std::make_unique<HeaderPage>());
    headerPagesOnDisk = 0;
}

DiskArrayCollection::DiskArrayCollection(FileHandle& fileRef, ShadowFile& shadowRef,
    page_idx_t startHeaderPage, bool skipShadowing)
    : fileHandle(fileRef), shadowFile{shadowRef}, bypassShadowing{skipShadowing},
      numHeaders{0} {
    // Load headers from disk (no external state in lambda: optimistic read may retry multiple times)
    page_idx_t currentPageIdx = startHeaderPage;
    do {
        std::unique_ptr<HeaderPage> loadedPage;
        page_idx_t nextIdx = INVALID_PAGE_IDX;
        fileHandle.optimisticReadPage(currentPageIdx, [&](auto* frame) {
            const auto* srcPage = reinterpret_cast<HeaderPage*>(frame);
            loadedPage = std::make_unique<HeaderPage>(*srcPage);
            nextIdx = srcPage->nextHeaderPage;
        });
        if (!loadedPage) {
            throw RuntimeException("Unable to load header page from disk.");
        }
        numHeaders += loadedPage->numHeaders;
        headersForReadTrx.emplace_back(std::make_unique<HeaderPage>(*loadedPage));
        headersForWriteTrx.push_back(std::move(loadedPage));
        currentPageIdx = nextIdx;
    } while (currentPageIdx != INVALID_PAGE_IDX);
    headerPagesOnDisk = headersForReadTrx.size();
}

void DiskArrayCollection::checkpoint(page_idx_t firstHeaderPage, PageAllocator& allocator) {
    page_idx_t currentDiskPage = firstHeaderPage;
    for (page_idx_t memIndex = 0; memIndex < headersForWriteTrx.size(); ++memIndex) {
        if (headersForWriteTrx[memIndex]->nextHeaderPage == INVALID_PAGE_IDX &&
            memIndex < headersForWriteTrx.size() - 1) {
            // First-time checkpoint for this array: allocate new header page
            allocateNextHeaderPage(allocator, memIndex);
        }

        // Update only if changed or never written before
        if (memIndex >= headerPagesOnDisk ||
            *headersForWriteTrx[memIndex] != *headersForReadTrx[memIndex]) {
            ShadowUtils::updatePage(*allocator.getDataFH(), currentDiskPage,
                true /*full-page write*/, shadowFile, [&](auto* dstFrame) {
                    memcpy(dstFrame, headersForWriteTrx[memIndex].get(), sizeof(HeaderPage));
                    if constexpr (sizeof(HeaderPage) < LBUG_PAGE_SIZE) {
                        std::fill(dstFrame + sizeof(HeaderPage), dstFrame + LBUG_PAGE_SIZE, 0);
                    }
                });
        }
        currentDiskPage = headersForWriteTrx[memIndex]->nextHeaderPage;
    }
    headerPagesOnDisk = headersForWriteTrx.size();
}

void DiskArrayCollection::allocateNextHeaderPage(PageAllocator& allocator,
    common::page_idx_t memIndex) {
    auto newPageIdx = allocator.allocatePage();
    headersForWriteTrx[memIndex]->nextHeaderPage = newPageIdx;
    // Structural changes (e.g., PKIndex growth) cannot be rolled back; apply to both versions
    headersForReadTrx[memIndex]->nextHeaderPage = newPageIdx;
}

size_t DiskArrayCollection::appendDiskArray() {
    size_t priorSize = numHeaders++;
    const auto pageSlot = numHeaders % HeaderPage::NUM_HEADERS_PER_PAGE;
    if (pageSlot >= headersForWriteTrx.size()) {
        headersForWriteTrx.emplace_back(std::make_unique<HeaderPage>());
        headersForReadTrx.emplace_back(std::make_unique<HeaderPage>());
    }

    auto& targetPage = *headersForWriteTrx[pageSlot];
    DASSERT(targetPage.numHeaders < HeaderPage::NUM_HEADERS_PER_PAGE);
    const auto slotInPage = targetPage.numHeaders;
    targetPage.headers[slotInPage] = DiskArrayHeader{};
    targetPage.numHeaders++;
    headersForReadTrx[pageSlot]->numHeaders++;
    return priorSize;
}

void DiskArrayCollection::releaseStorage(PageAllocator& allocator,
    common::page_idx_t firstHeaderPage) const {
    page_idx_t currentPage = firstHeaderPage;
    for (page_idx_t memIndex = 0; memIndex < headersForReadTrx.size(); ++memIndex) {
        if (currentPage == INVALID_PAGE_IDX) {
            break;
        }
        allocator.freePage(currentPage);
        currentPage = headersForReadTrx[memIndex]->nextHeaderPage;
    }
}

