static cl::opt<std::string>
OutFilename("o", cl::desc("Output filename"), cl::value_desc("filename"),
            cl::init("-"));
static cl::opt<std::string>
DepFilename("d",
            cl::desc("Dependency filename"),
            cl::value_desc("filename"),
            cl::init(""));
static cl::opt<std::string>
InputFilename(cl::Positional, cl::desc("<input file>"), cl::init("-"));
static cl::list<std::string>
IncludePaths("I", cl::desc("Directory of include files"),
             cl::value_desc("directory"), cl::Prefix);
static cl::list<std::string>
DefinedMacros("D", cl::desc("Name of the macro to be defined"),
              cl::value_desc("macro name"), cl::Prefix);
static cl::opt<bool>
OnlyIfChanged("write-if-changed", cl::desc("Only write output if it changed"));
static cl::opt<bool>
MeasurePhases("time-phases", cl::desc("Time phases of parser and backend"));
static cl::opt<bool> SuppressUnusedTemplateWarnings(
    "no-warn-on-unused-template-args",
    cl::desc("Disable unused template argument warnings."));

static int emitError(const char *ProgName, Twine Message) {
  errs() << ProgName << ": " << Message;
  errs().flush();
  return 1;
}

/// Generate a dependency file for `-d` option.
///
/// This functionality is primarily intended for build systems,
/// mirroring GCC's `-M*` options.
static int generateDependencyReport(const TGParser &Parser, const char *argv0) {
  if (OutFilename == "-")
    return emitError(argv0, "the option -d must be used together with -o\n");
  std::error_code EC;
  ToolOutputFile DepOut(DepFilename, EC, sys::fs::OF_Text);
  if (EC)
    return emitError(argv0, "error opening " + DepFilename + ":" +
                                EC.message() + "\n");
  DepOut.os() << OutFilename << ":";
  for (const auto &Item : Parser.getDependencies()) {
    DepOut.os() << ' ' << Item;
  }
  DepOut.os() << "\n";
  DepOut.keep();
  return 0;
}

int llvm::TableGenMain(const char *argv0,
                       std::function<TableGenMainFn> MainFn) {
  RecordKeeper Data;
  if (MeasurePhases)
    Data.startPhaseTiming();

  // Parse the input file.
  Data.startTimer("Parse, build records");
  ErrorOr<std::unique_ptr<MemoryBuffer>> BufferOrErr =
      MemoryBuffer::getFileOrSTDIN(InputFilename, /*IsText=*/true);
  if (std::error_code EC = BufferOrErr.getError())
    return emitError(argv0, "Could not open input file '" + InputFilename +
                                "': " + EC.message() + "\n");
  Data.saveInputFilename(InputFilename);

  // Register buffer with SourceMgr for use by TGParser.
  SrcMgr.AddNewSourceBuffer(std::move(*BufferOrErr), SMLoc());

  // Set up include search paths for the lexer.
  SrcMgr.setIncludeDirs(IncludePaths);

  TGParser Parser(SrcMgr, DefinedMacros, Data, SuppressUnusedTemplateWarnings);
  if (Parser.ParseFile())
    return 1;
  Data.stopTimer();

  // Generate backend output in memory.
  Data.startBackendTimer("Backend overall");
  std::string ResultString;
  raw_string_ostream Result(ResultString);
  unsigned ExitCode = 0;
  TableGen::Emitter::FnT HandlerFn = TableGen::Emitter::Action->getValue();
  if (HandlerFn)
    HandlerFn(Data, Result);
  else if (MainFn)
    ExitCode = MainFn(Result, Data);
  else
    return 1;
  Data.stopBackendTimer();
  if (ExitCode)
    return 1;

  // Ensure depfile is written regardless of early exits — Ninja requires it.
  if (!DepFilename.empty()) {
    if (int Ret = generateDependencyReport(Parser, argv0))
      return Ret;
  }

  Data.startTimer("Write output");
  bool ShouldWrite = true;
  if (OnlyIfChanged) {
    // Only update on-disk file if content differs.
    if (auto ExistingOrErr =
            MemoryBuffer::getFile(OutFilename, /*IsText=*/true))
      if (std::move(ExistingOrErr.get())->getBuffer() == Result.str())
        ShouldWrite = false;
  }

  if (ShouldWrite) {
    std::error_code EC;
    ToolOutputFile FileOut(OutFilename, EC, sys::fs::OF_Text);
    if (EC)
      return emitError(argv0, "error opening " + OutFilename + ": " +
                                  EC.message() + "\n");
    FileOut.os() << Result.str();
    if (ErrorsPrinted == 0)
      FileOut.keep();
  }

  Data.stopTimer();
  Data.stopPhaseTiming();
  if (ErrorsPrinted > 0)
    return emitError(argv0, Twine(ErrorsPrinted) + " errors.\n");
  return 0;
}

#define ENABLE_SOLID_SAFETY 1
#include <sol/sol.hpp>
#include <iostream>

void helper_func() {
    std::cout << "helper function!" << std::endl;
}

void another_helper_func() {
    std::cout << "another helper function!" << std::endl;
}

struct helper_class {
    int data_member = 45;
    double compute_value() {
        return 36.7;
    }
};

int main(int, char*[]) {
    std::cout << "=== functions (all) ===" << std::endl;
    sol::state vm;
    vm.open_libraries(sol::lib::base);

    // Register an instance of "helper_class" into the Lua state
    vm.set("hc", helper_class());

    // Bind a plain function using different syntaxes
    vm["h1"] = helper_func;
    vm.set_function("h2", &another_helper_func);

    // Bind just the member function
    vm["mem_f1"] = &helper_class::compute_value;

    // Bind class with member function and pre-bind instance
    vm.set_function(
        "mem_f2", &helper_class::compute_value, helper_class{});

    // Bind just the member variable as a getter/setter function
    vm["var_f1"] = &helper_class::data_member;

    // Bind class with member variable and pre-bind instance
    vm.set_function(
        "var_f2", &helper_class::data_member, helper_class{});

    vm.script(R"(
    h1() -- helper function!
    h2() -- another helper function!

    -- need class instance if you don't bind it with the function
    print(mem_f1(hc)) -- 36.7
