TEST(hsa, tables)
{
    namespace hsa = ::rocprofiler::hsa;

    // Retrieve HSA API table version information
    auto ver_info = hsa::get_table_version();

    // Access various HSA API table components
    auto* core_api     = hsa::get_core_table();
    auto* amd_extension  = hsa::get_amd_ext_table();
    auto* fini_extension = hsa::get_fini_ext_table();
    auto* img_extension  = hsa::get_img_ext_table();
    auto* amd_tool_table = hsa::get_amd_tool_table();
#if ROCPROFILER_SDK_HSA_PC_SAMPLING > 0
    auto* pcs_extension = hsa::get_pc_sampling_ext_table();
#endif

    // Get full HsaApiTable instance
    auto full_table = hsa::get_table();

    //------------------------------------------------------------------------//
    //  Validate against HSA header constants
    //------------------------------------------------------------------------//
    // Verify main table version fields
    EXPECT_EQ(ver_info.major_id, HSA_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(ver_info.minor_id, sizeof(hsa::hsa_api_table_t));
    EXPECT_EQ(ver_info.step_id, HSA_API_TABLE_STEP_VERSION);

    // Verify core table version fields
    EXPECT_EQ(core_api->version.major_id, HSA_CORE_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(core_api->version.minor_id, sizeof(hsa::hsa_core_table_t));
    EXPECT_EQ(core_api->version.step_id, HSA_CORE_API_TABLE_STEP_VERSION);

    // Verify AMD extension table version fields
    EXPECT_EQ(amd_extension->version.major_id, HSA_AMD_EXT_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(amd_extension->version.minor_id, sizeof(hsa::hsa_amd_ext_table_t));
    EXPECT_EQ(amd_extension->version.step_id, HSA_AMD_EXT_API_TABLE_STEP_VERSION);

    // Verify finalizer extension table version fields
    EXPECT_EQ(fini_extension->version.major_id, HSA_FINALIZER_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(fini_extension->version.minor_id, sizeof(hsa::hsa_fini_ext_table_t));
    EXPECT_EQ(fini_extension->version.step_id, HSA_FINALIZER_API_TABLE_STEP_VERSION);

    // Verify image extension table version fields
    EXPECT_EQ(img_extension->version.major_id, HSA_IMAGE_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(img_extension->version.minor_id, sizeof(hsa::hsa_img_ext_table_t));
    EXPECT_EQ(img_extension->version.step_id, HSA_IMAGE_API_TABLE_STEP_VERSION);

    // Verify AMD tools table version fields
    EXPECT_EQ(amd_tool_table->version.major_id, HSA_TOOLS_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(amd_tool_table->version.minor_id, sizeof(hsa::hsa_amd_tool_table_t));
    EXPECT_EQ(amd_tool_table->version.step_id, HSA_TOOLS_API_TABLE_STEP_VERSION);

#if ROCPROFILER_SDK_HSA_PC_SAMPLING > 0
    // Verify PC sampling extension table version fields
    EXPECT_EQ(pcs_extension->version.major_id, HSA_PC_SAMPLING_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(pcs_extension->version.minor_id, sizeof(hsa::hsa_pc_sampling_ext_table_t));
    EXPECT_EQ(pcs_extension->version.step_id, HSA_PC_SAMPLING_API_TABLE_STEP_VERSION);
#endif

    //------------------------------------------------------------------------//
    //  Cross-check between different retrieval methods
    //------------------------------------------------------------------------//
    // Ensure get_table_version() matches the version in full_table
    EXPECT_EQ(full_table.version.major_id, ver_info.major_id);
    EXPECT_EQ(full_table.version.minor_id, ver_info.minor_id);
    EXPECT_EQ(full_table.version.step_id, ver_info.step_id);

    // Ensure all table pointers are consistent across retrieval methods
    EXPECT_EQ(full_table.core_, core_api);
    EXPECT_EQ(full_table.amd_ext_, amd_extension);
    EXPECT_EQ(full_table.finalizer_ext_, fini_extension);
    EXPECT_EQ(full_table.image_ext_, img_extension);
}

