namespace {

struct FusionOption {
  BasicBlock *PH;
  BasicBlock *HDR;
  BasicBlock *ExitPred;
  BasicBlock *ExitSucc;
  BasicBlock *LTH;
  Loop *L;
  SmallVector<Instruction *, 16> LoadOps;
  SmallVector<Instruction *, 16> StoreOps;
  bool Active;
  BranchInst *GuardBranch;
  TTI::PeelingPreferences PP;
  bool CanPeel;
  bool HasPeeled;
  DominatorTree &DT;
  const PostDominatorTree *PDT;
  OptimizationRemarkEmitter &ORE;

  FusionOption(Loop *L, DominatorTree &DT, const PostDominatorTree *PDT,
               OptimizationRemarkEmitter &ORE, TTI::PeelingPreferences PP)
      : PH(L->getLoopPreheader()), HDR(L->getHeader()),
        ExitPred(L->getExitingBlock()), ExitSucc(L->getExitBlock()),
        LTH(L->getLoopLatch()), L(L), Active(true),
        GuardBranch(L->getLoopGuardBranch()), PP(PP),
        CanPeel(canPeel(L)), HasPeeled(false), DT(DT), PDT(PDT), ORE(ORE) {
    for (BasicBlock *BB : L->blocks()) {
      if (BB->hasAddressTaken()) {
        deactivate();
        reportFailure(AddressTakenBB);
        return;
      }
      for (Instruction &I : *BB) {
        if (I.mayThrow()) {
          deactivate();
          reportFailure(MayThrowException);
          return;
        }
        if (StoreInst *SI = dyn_cast<StoreInst>(&I)) {
          if (SI->isVolatile()) {
            deactivate();
            reportFailure(ContainsVolatileAccess);
            return;
          }
        }
        if (LoadInst *LI = dyn_cast<LoadInst>(&I)) {
          if (LI->isVolatile()) {
            deactivate();
            reportFailure(ContainsVolatileAccess);
            return;
          }
        }
        if (I.mayWriteToMemory())
          StoreOps.push_back(&I);
        if (I.mayReadFromMemory())
          LoadOps.push_back(&I);
      }
    }
  }

  bool isActive() const {
    return PH && HDR && ExitPred && ExitSucc && LTH && L &&
           !L->isInvalid() && Active;
  }

  void verifyConsistency() const {
    assert(isActive() && "Option is not active!");
    assert(!L->isInvalid() && "Loop is invalid!");
    assert(PH == L->getLoopPreheader() && "Preheader mismatch");
    assert(HDR == L->getHeader() && "Header mismatch");
    assert(ExitPred == L->getExitingBlock() && "Exiting block mismatch");
    assert(ExitSucc == L->getExitBlock() && "Exit block mismatch");
    assert(LTH == L->getLoopLatch() && "Latch mismatch");
  }

  BasicBlock *getEntryPoint() const {
    if (GuardBranch)
      return GuardBranch->getParent();
    else
      return PH;
  }

  void refreshAfterPeeling() {
    PH = L->getLoopPreheader();
    HDR = L->getHeader();
    ExitPred = L->getExitingBlock();
    ExitSucc = L->getExitBlock();
    LTH = L->getLoopLatch();
    verifyConsistency();
  }

  BasicBlock *getExternalSuccessor() const {
    assert(GuardBranch && "Only valid on guarded loops.");
    assert(GuardBranch->isConditional() &&
           "Expecting guard to be a conditional branch.");
    if (HasPeeled)
      return GuardBranch->getSuccessor(1);
    return (GuardBranch->getSuccessor(0) == PH)
               ? GuardBranch->getSuccessor(1)
               : GuardBranch->getSuccessor(0);
  }

#if !defined(NDEBUG) || defined(LLVM_ENABLE_DUMP)
  LLVM_DUMP_METHOD void dump() const {
    dbgs() << "\tGuardBranch: ";
    if (GuardBranch)
      dbgs() << *GuardBranch;
    else
      dbgs() << "nullptr";
    dbgs() << "\n"
           << (GuardBranch ? GuardBranch->getName() : "nullptr") << "\n"
           << "\tPreheader: " << (PH ? PH->getName() : "nullptr") << "\n"
           << "\tHeader: " << (HDR ? HDR->getName() : "nullptr") << "\n"
           << "\tExitingBB: "
           << (ExitPred ? ExitPred->getName() : "nullptr") << "\n"
           << "\tExitBB: " << (ExitSucc ? ExitSucc->getName() : "nullptr")
           << "\n"
           << "\tLatch: " << (LTH ? LTH->getName() : "nullptr") << "\n"
           << "\tEntryBlock: "
           << (getEntryPoint() ? getEntryPoint()->getName() : "nullptr")
           << "\n";
  }
#endif

  bool isSuitableForFusion(ScalarEvolution &SE) const {
    if (!isActive()) {
      LLVM_DEBUG(dbgs() << "FC has invalid CFG requirements!\n");
      if (!PH)
        ++BadPreheader;
      if (!HDR)
        ++BadHeader;
      if (!ExitPred)
        ++BadExitingBlock;
      if (!ExitSucc)
        ++BadExitBlock;
      if (!LTH)
        ++BadLatch;
      if (L->isInvalid())
        ++InvalidLoopStructure;
      return false;
    }

    if (!SE.hasLoopInvariantBackedgeTakenCount(L)) {
      LLVM_DEBUG(dbgs() << "Loop " << L->getName()
                        << " iteration count not computable!\n");
      return reportFailure(UnknownIterationCount);
    }

    if (!L->isLoopSimplifyForm()) {
      LLVM_DEBUG(dbgs() << "Loop " << L->getName()
                        << " is not in simplified form!\n");
      return reportFailure(NotInSimplifiedForm);
    }

    if (!L->isRotatedForm()) {
      LLVM_DEBUG(dbgs() << "Loop " << L->getName() << " is not rotated!\n");
      return reportFailure(NotRotatedLoop);
    }

    return true;
  }

private:
  void deactivate() {
    StoreOps.clear();
    LoadOps.clear();
    Active = false;
  }

  bool reportFailure(llvm::Statistic &Stat) const {
    using namespace ore;
    assert(L && PH && "Fusion option not initialized properly!");
#if LLVM_ENABLE_STATS
    ++Stat;
    ORE.emit(OptimizationRemarkAnalysis(DEBUG_TYPE, Stat.getName(),
                                        L->getStartLoc(), PH)
             << "[" << PH->getParent()->getName() << "]: "
             << "Loop is not a candidate for fusion: " << Stat.getDesc());
#endif
    return false;
  }
};

struct FusionOrderComparator {
  bool operator()(const FusionOption &A, const FusionOption &B) const {
    const DominatorTree *DT = &(A.DT);
    BasicBlock *AEntry = A.getEntryPoint();
    BasicBlock *BEntry = B.getEntryPoint();

    assert(DT && A.PDT && "Expecting valid dominator tree");

    if (DT->dominates(BEntry, AEntry)) {
      assert(A.PDT->dominates(AEntry, BEntry));
      return false;
    }

    if (DT->dominates(AEntry, BEntry)) {
      assert(A.PDT->dominates(BEntry, AEntry));
      return true;
    }

    bool WrongOrder =
        nonStrictlyPostDominate(AEntry, BEntry, DT, A.PDT);
    bool RightOrder =
        nonStrictlyPostDominate(BEntry, AEntry, DT, A.PDT);

    if (WrongOrder && RightOrder) {
      DomTreeNode *ANode = A.PDT->getNode(AEntry);
      DomTreeNode *BNode = A.PDT->getNode(BEntry);
      return ANode->getLevel() > BNode->getLevel();
    } else if (WrongOrder)
      return false;
    else if (RightOrder)
      return true;

    llvm_unreachable(
        "No dominance relationship between these fusion options!");
  }
};

using LoopList = SmallVector<Loop *, 4>;
using FusionGroup = std::set<FusionOption, FusionOrderComparator>;
using FusionGroupCollection = SmallVector<FusionGroup, 4>;

#if !defined(NDEBUG)
static llvm::raw_ostream &operator<<(llvm::raw_ostream &OS,
                                     const FusionOption &FO) {
  if (FO.isActive())
    OS << FO.PH->getName();
  else
    OS << "<Inactive>";
  return OS;
}

static llvm::raw_ostream &operator<<(llvm::raw_ostream &OS,
                                     const FusionGroup &Group) {
  for (const FusionOption &FO : Group)
    OS << FO << '\n';
  return OS;
}

static void
displayFusionOptions(const FusionGroupCollection &Options) {
  dbgs() << "Fusion Options: \n";
  for (const auto &Group : Options) {
    dbgs() << "*** Fusion Option Group ***\n";
    dbgs() << Group;
    dbgs() << "****************************\n";
  }
}
#endif

struct LoopHierarchy {
  using LevelLoopsTy = SmallVector<LoopList, 4>;
  using iterator = LevelLoopsTy::iterator;
  using const_iterator = LevelLoopsTy::const_iterator;

  LoopHierarchy(LoopInfo &LI) : Depth(1) {
    if (!LI.empty())
      Levels.emplace_back(LoopList(LI.rbegin(), LI.rend()));
  }

  bool isRemovedLoop(const Loop *L) const { return Removed.count(L); }
  void removeLoop(const Loop *L) { Removed.insert(L); }

  void descend() {
    LevelLoopsTy NextLevel;
    for (const LoopList &LL : *this)
      for (Loop *L : LL)
        if (!isRemovedLoop(L) && L->begin() != L->end())
          NextLevel.emplace_back(LoopList(L->begin(), L->end()));
    Levels = NextLevel;
    Removed.clear();
    Depth++;
  }

  bool empty() const { return size() == 0; }
  size_t size() const { return Levels.size() - Removed.size(); }
  unsigned getDepth() const { return Depth; }
  iterator begin() { return Levels.begin(); }
  iterator end() { return Levels.end(); }
  const_iterator begin() const { return Levels.begin(); }
  const_iterator end() const { return Levels.end(); }

private:
  SmallPtrSet<const Loop *, 8> Removed;
  unsigned Depth;
  LevelLoopsTy Levels;
};

#ifndef NDEBUG
static void printLoopList(const LoopList &LL) {
  dbgs() << "****************************\n";
  for (auto *L : LL)
    printLoop(*L, dbgs());
  dbgs() << "****************************\n";
}
#endif

struct LoopMerger {
private:
  FusionGroupCollection FusionGroups;
  LoopHierarchy LH;
  DomTreeUpdater DTU;
  LoopInfo &LI;
  DominatorTree &DT;
  DependenceInfo &DI;
  ScalarEvolution &SE;
  PostDominatorTree &PDT;
  OptimizationRemarkEmitter &ORE;
  AssumptionCache &AC;
  const TargetTransformInfo &TTI;

public:
  LoopMerger(LoopInfo &LI, DominatorTree &DT, DependenceInfo &DI,
             ScalarEvolution &SE, PostDominatorTree &PDT,
             OptimizationRemarkEmitter &ORE, const DataLayout &DL,
             AssumptionCache &AC, const TargetTransformInfo &TTI)
      : LH(LI), DTU(DT, PDT, DomTreeUpdater::UpdateStrategy::Lazy), LI(LI),
        DT(DT), DI(DI), SE(SE), PDT(PDT), ORE(ORE), AC(AC), TTI(TTI) {}

  bool mergeLoops(Function &F) {
#ifndef NDEBUG
    if (DetailedDebugOutput) {
      LI.print(dbgs());
    }
#endif
    LLVM_DEBUG(dbgs() << "Performing Loop Fusion on function " << F.getName()
                      << "\n");
    bool Modified = false;

    while (!LH.empty()) {
      LLVM_DEBUG(dbgs() << "Got " << LH.size() << " loop sets for depth "
                        << LH.getDepth() << "\n";);
      for (const LoopList &LL : LH) {
        assert(LL.size() > 0 && "Empty loop set was build!");
        if (LL.size() == 1)
          continue;

#ifndef NDEBUG
        if (DetailedDebugOutput) {
          LLVM_DEBUG({
            dbgs() << "  Visit loop set (#" << LL.size() << "):\n";
            printLoopList(LL);
          });
        }
#endif

        gatherFusionOptions(LL);
        Modified |= attemptFusion();
      }

      LLVM_DEBUG(dbgs() << "Descend one level!\n");
      LH.descend();
      FusionGroups.clear();
    }

    if (Modified)
      LLVM_DEBUG(dbgs() << "Function after Loop Fusion: \n"; F.dump(););

#ifndef NDEBUG
    assert(DT.verify());
    assert(PDT.verify());
    LI.verify(DT);
    SE.verify();
#endif

    LLVM_DEBUG(dbgs() << "Loop Fusion complete\n");
    return Modified;
  }

private:
  bool isControlFlowEquivalent(const FusionOption &FO0,
                               const FusionOption &FO1) const {
    assert(FO0.PH && FO1.PH && "Expecting valid preheaders");
    return ::isControlFlowEquivalent(*FO0.getEntryPoint(), *FO1.getEntryPoint(),
                                     DT, PDT);
  }

  void gatherFusionOptions(const LoopList &LL) {
    for (Loop *L : LL) {
      TTI::PeelingPreferences PP =
          gatherPeelingPreferences(L, SE, TTI, std::nullopt, std::nullopt);
      FusionOption CurrOpt(L, DT, &PDT, ORE, PP);
      if (!CurrOpt.isSuitableForFusion(SE))
        continue;

      bool FoundGroup = false;
      for (auto &CurrGroup : FusionGroups) {
        if (isControlFlowEquivalent(*CurrGroup.begin(), CurrOpt)) {
          CurrGroup.insert(CurrOpt);
          FoundGroup = true;
#ifndef NDEBUG
          if (DetailedDebugOutput)
            LLVM_DEBUG(dbgs() << "Adding " << CurrOpt
                              << " to existing group\n");
#endif
          break;
        }
      }

      if (!FoundGroup) {
#ifndef NDEBUG
        if (DetailedDebugOutput)
          LLVM_DEBUG(dbgs() << "Adding " << CurrOpt << " to new group\n");
#endif
        FusionGroup NewGroup;
        NewGroup.insert(CurrOpt);
        FusionGroups.push_back(NewGroup);
      }

      CandidateCount++;
    }
  }

  bool isBeneficialMerge(const FusionOption &FO0,
                         const FusionOption &FO1) {
    return true;
  }

  std::pair<bool, std::optional<unsigned>>
  haveSameIterationCounts(const FusionOption &FO0,
                          const FusionOption &FO1) const {
    const SCEV *Iter0 = SE.getBackedgeTakenCount(FO0.L);
    if (isa<SCEVCouldNotCompute>(Iter0)) {
      UncalculableTripCount++;
      LLVM_DEBUG(dbgs() << "Iteration count of first loop could not be computed!");
      return {false, std::nullopt};
    }

    const SCEV *Iter1 = SE.getBackedgeTakenCount(FO1.L);
    if (isa<SCEVCouldNotCompute>(Iter1)) {
      UncalculableTripCount++;
      LLVM_DEBUG(dbgs() << "Iteration count of second loop could not be computed!");
      return {false, std::nullopt};
    }

    LLVM_DEBUG(dbgs() << "\tIteration counts: " << *Iter0 << " & "
                      << *Iter1 << " are "
                      << (Iter0 == Iter1 ? "identical" : "different")
                      << "\n");

    if (Iter0 == Iter1)
      return {true, 0};

    LLVM_DEBUG(dbgs() << "The loops do not have the same iteration count, "
                         "determining the difference between counts\n");

    const unsigned IC0 = SE.getSmallConstantTripCount(FO0.L);
    const unsigned IC1 = SE.getSmallConstantTripCount(FO1.L);

    if (IC0 == 0 || IC1 == 0) {
      LLVM_DEBUG(dbgs() << "Loop(s) do not have a single exit point or do not "
                           "have a constant number of iterations. Peeling "
                           "is not benefical\n");
      return {false, std::nullopt};
    }

    std::optional<unsigned> Diff;
    int Delta = IC0 - IC1;
    if (Delta > 0)
      Diff = Delta;
    else {
      LLVM_DEBUG(
          dbgs() << "Difference is less than 0. FC1 (second loop) has more "
                    "iterations than the first one. Currently not supported\n");
    }

    LLVM_DEBUG(dbgs() << "Difference in loop iteration count is: " << Diff
                      << "\n");
    return {false, Diff};
  }

  void peelFusionOption(FusionOption &FO0, const FusionOption &FO1,
                        unsigned PeelCount) {
    assert(FO0.CanPeel && "Should be able to peel loop");
    LLVM_DEBUG(dbgs() << "Attempting to peel first " << PeelCount
                      << " iterations of the first loop. \n");
    ValueToValueMapTy VMap;
    FO0.HasPeeled = peelLoop(FO0.L, PeelCount, &LI, &SE, DT, &AC, true, VMap);
    if (FO0.HasPeeled) {
      LLVM_DEBUG(dbgs() << "Done Peeling\n");
#ifndef NDEBUG
      auto SameIterCount = haveSameIterationCounts(FO0, FO1);
      assert(SameIterCount.first && *SameIterCount.second == 0 &&
             "Loops should have identical iteration counts after peeling");
#endif
      FO0.PP.PeelCount += PeelCount;
      PDT.recalculate(*FO0.PH->getParent());
      FO0.refreshAfterPeeling();

      BasicBlock *BB =
          FO0.GuardBranch ? FO0.ExitSucc->getUniqueSuccessor() : FO1.PH;
      if (BB) {
        SmallVector<DominatorTree::UpdateType, 8> TreeUpdates;
        SmallVector<Instruction *, 8> WorkList;
        for (BasicBlock *Pred : predecessors(BB)) {
          if (Pred != FO0.ExitSucc) {
            WorkList.emplace_back(Pred->getTerminator());
            TreeUpdates.emplace_back(
                DominatorTree::UpdateType(DominatorTree::Delete, Pred, BB));
          }
        }

        for (Instruction *CurrentBranch : WorkList) {
          BasicBlock *Succ = CurrentBranch->getSuccessor(0);
          if (Succ == BB)
            Succ = CurrentBranch->getSuccessor(1);
          ReplaceInstWithInst(CurrentBranch, BranchInst::Create(Succ));
        }

        DTU.applyUpdates(TreeUpdates);
        DTU.flush();
      }

      LLVM_DEBUG(
          dbgs() << "Sucessfully peeled " << FO0.PP.PeelCount
                 << " iterations from the first loop.\n"
                    "Both Loops have the same number of iterations now.\n");
    }
  }

  bool attemptFusion() {
    bool Merged = false;
    LLVM_DEBUG(displayFusionOptions(FusionGroups));
    for (auto &Group : FusionGroups) {
      if (Group.size() < 2)
        continue;

      LLVM_DEBUG(dbgs() << "Attempting fusion on Group:\n"
                        << Group << "\n");

      for (auto FO0 = Group.begin(); FO0 != Group.end(); ++FO0) {
        assert(!LH.isRemovedLoop(FO0->L) &&
               "Should not have removed loops in Group!");

        auto FO1 = FO0;
        for (++FO1; FO1 != Group.end(); ++FO1) {
          assert(!LH.isRemovedLoop(FO1->L) &&
                 "Should not have removed loops in Group!");

          LLVM_DEBUG(dbgs() << "Attempting to fuse option \n"; FO0->dump();
                     dbgs() << " with\n"; FO1->dump(); dbgs() << "\n");

          FO0->verifyConsistency();
          FO1->verifyConsistency();

          std::pair<bool, std::optional<unsigned>> IterResult =
              haveSameIterationCounts(*FO0, *FO1);
          bool SameIter = IterResult.first;
          std::optional<unsigned> IterDiff = IterResult.second;

          if (FO0->CanPeel && !SameIter && IterDiff) {
            if (*IterDiff > MaxPeelIterations) {
              LLVM_DEBUG(dbgs()
                         << "Difference in loop iteration counts: " << *IterDiff
                         << " is greater than maximum peel count specificed: "
                         << MaxPeelIterations << "\n");
            } else {
              SameIter = true;
            }
          }

          if (!SameIter) {
            LLVM_DEBUG(dbgs() << "Fusion options do not have identical iteration "
                                 "counts. Not fusing.\n");
            reportLoopFusion<OptimizationRemarkMissed>(*FO0, *FO1,
                                                       DifferentIterationCounts);
            continue;
          }

          if (!areContiguous(*FO0, *FO1)) {
            LLVM_DEBUG(dbgs()
                       << "Fusion options are not adjacent. Not fusing.\n");
            reportLoopFusion<OptimizationRemarkMissed>(*FO0, *FO1, NonContiguous);
            continue;
          }

          if ((!FO0->GuardBranch && FO1->GuardBranch) ||
              (FO0->GuardBranch && !FO1->GuardBranch)) {
            LLVM_DEBUG(dbgs() << "The one of option is guarded while the "
                                 "another one is not. Not fusing.\n");
            reportLoopFusion<OptimizationRemarkMissed>(
                *FO0, *FO1, OnlySecondIsGuarded);
            continue;
          }

          if (FO0->GuardBranch && FO1->GuardBranch &&
              !haveSameGuards(*FO0, *FO1) && !IterDiff) {
            LLVM_DEBUG(dbgs() << "Fusion options do not have identical "
                                 "guards. Not Fusing.\n");
            reportLoopFusion<OptimizationRemarkMissed>(*FO0, *FO1,
                                                       NonIdenticalGuardConditions);
            continue;
          }

          if (FO0->GuardBranch) {
            assert(FO1->GuardBranch && "Expecting valid FO1 guard branch");
            if (!isSafeToMoveBefore(*FO0.ExitSucc,
                                    *FO1.ExitSucc->getFirstNonPHIOrDbg(), DT,
                                    &PDT, &DI)) {
              LLVM_DEBUG(dbgs() << "Fusion option contains unsafe "
                                   "instructions in exit block. Not fusing.\n");
              reportLoopFusion<OptimizationRemarkMissed>(*FO0, *FO1,
                                                         NonEmptyExitBlockWithInstructions);
              continue;
            }

            if (!isSafeToMoveBefore(
                    *FO1.GuardBranch->getParent(),
                    *FO0.GuardBranch->getParent()->getTerminator(), DT, &PDT,
                    &DI)) {
              LLVM_DEBUG(dbgs()
                         << "Fusion option contains unsafe "
                            "instructions in guard block. Not fusing.\n");
              reportLoopFusion<OptimizationRemarkMissed>(*FO0, *FO1,
                                                         NonEmptyGuardBlockWithInstructions);
              continue;
            }
          }

          if (!dependenciesAllowMerge(*FO0, *FO1)) {
            LLVM_DEBUG(dbgs() << "Memory dependencies do not allow fusion!\n");
            reportLoopFusion<OptimizationRemarkMissed>(*FO0, *FO1,
                                                       ForbiddenDependencies);
            continue;
          }

          SmallVector<Instruction *, 4> SafeToHoist;
          SmallVector<Instruction *, 4> SafeToSink;

          if (!isEmptyPreheader(*FO1)) {
            LLVM_DEBUG(dbgs() << "Fusion option does not have empty "
                                 "preheader.\n");
            if (!collectMovablePreheaderInsts(*FO0, *FO1, SafeToHoist,
                                              SafeToSink)) {
              LLVM_DEBUG(dbgs() << "Could not hoist/sink all instructions in "
                                   "Fusion Option Pre-header.\n"
                                << "Not Fusing.\n");
              reportLoopFusion<OptimizationRemarkMissed>(*FO0, *FO1,
                                                         NonEmptyPreheaderWithInstructions);
              continue;
            }
          }

          bool Profitable = isBeneficialMerge(*FO0, *FO1);
          LLVM_DEBUG(dbgs()
                     << "\tFusion appears to be "
                     << (Profitable ? "" : "un") << "profitable!\n");

          if (!Profitable) {
            reportLoopFusion<OptimizationRemarkMissed>(*FO0, *FO1,
                                                       FusionUnprofitable);
            continue;
          }

          movePreheaderInsts(*FO0, *FO1, SafeToHoist, SafeToSink);

          LLVM_DEBUG(dbgs() << "\tFusion is performed: " << *FO0 << " and "
                            << *FO1 << "\n");

          FusionOption FO0Copy = *FO0;
          bool Peel = IterDiff && *IterDiff > 0;
          if (Peel)
            peelFusionOption(FO0Copy, *FO1, *IterDiff);

          reportLoopFusion<OptimizationRemark>((Peel ? FO0Copy : *FO0), *FO1,
                                               TotalFusedLoops);

          FusionOption MergedOption(
              performFusion((Peel ? FO0Copy : *FO0), *FO1), DT, &PDT, ORE,
              FO0Copy.PP);
          MergedOption.verifyConsistency();
          assert(MergedOption.isSuitableForFusion(SE) &&
                 "Merged option should be suitable for fusion!");

          LH.removeLoop(FO1->L);
          Group.erase(FO0);
          Group.erase(FO1);
          auto InsertPos = Group.insert(MergedOption);
          assert(InsertPos.second &&
                 "Unable to insert TargetOption in Group!");

          FO0 = FO1 = InsertPos.first;

          LLVM_DEBUG(dbgs() << "Group (after fusion): " << Group
                            << "\n");
          Merged = true;
        }
      }
    }
    return Merged;
  }

  bool canHoistInst(Instruction &I,
                    const SmallVector<Instruction *, 4> &Hoisted,
                    const SmallVector<Instruction *, 4> &Blocked,
                    const FusionOption &FO0) const {
    const BasicBlock *Target = FO0.PH->getSingleSuccessor();
    assert(Target && "Expected single successor for loop preheader.");

    for (Use &Op : I.operands()) {
      if (auto *OpInst = dyn_cast<Instruction>(Op)) {
        bool OpHoisted = is_contained(Hoisted, OpInst);
        if (!(OpHoisted || DT.dominates(OpInst, Target))) {
          return false;
        }
      }
    }

    if (isa<PHINode>(I))
      return false;

    if (!I.mayReadOrWriteMemory())
      return true;

    LLVM_DEBUG(dbgs() << "Checking if this mem inst can be hoisted.\n");

    for (Instruction *BlockedInst : Blocked) {
      if (auto D = DI.depends(&I, BlockedInst, true)) {
        if (D->isFlow() || D->isAnti() || D->isOutput()) {
          LLVM_DEBUG(dbgs() << "Inst depends on an instruction in FO0's "
                               "preheader that is not being hoisted.\n");
          return false;
        }
      }
    }

    for (Instruction *LoadInst : FO0.LoadOps) {
      if (auto D = DI.depends(LoadInst, &I, true)) {
        if (D->isAnti()) {
          LLVM_DEBUG(dbgs() << "Inst depends on a read instruction in FO0.\n");
          return false;
        }
      }
    }

    for (Instruction *StoreInst : FO0.StoreOps) {
      if (auto D = DI.depends(StoreInst, &I, true)) {
        if (D->isFlow() || D->isOutput()) {
          LLVM_DEBUG(dbgs() << "Inst depends on a write instruction in FO0.\n");
          return false;
        }
      }
    }

    return true;
  }

  bool canSinkInst(Instruction &I, const FusionOption &FO1) const {
    for (User *U : I.users()) {
      if (auto *UI{dyn_cast<Instruction>(U)}) {
        if (FO1.L->contains(UI)) {
          return false;
        }
      }
    }

    if (!I.mayReadOrWriteMemory())
      return true;

    for (Instruction *LoadInst : FO1.LoadOps) {
      if (auto D = DI.depends(&I, LoadInst, true)) {
        if (D->isFlow()) {
          LLVM_DEBUG(dbgs() << "Inst depends on a read instruction in FO1.\n");
          return false;
        }
      }
    }

    for (Instruction *StoreInst : FO1.StoreOps) {
      if (auto D = DI.depends(&I, StoreInst, true)) {
        if (D->isOutput() || D->isAnti()) {
          LLVM_DEBUG(dbgs() << "Inst depends on a write instruction in FO1.\n");
          return false;
        }
      }
    }

    return true;
  }

  bool collectMovablePreheaderInsts(
      const FusionOption &FO0, const FusionOption &FO1,
      SmallVector<Instruction *, 4> &SafeToHoist,
      SmallVector<Instruction *, 4> &SafeToSink) const {
    BasicBlock *FO1PH = FO1.PH;
    SmallVector<Instruction *, 4> NotHoisting;

    for (Instruction &I : *FO1PH) {
      if (&I == FO1PH->getTerminator())
        continue;

      if (I.mayThrow() || !I.willReturn()) {
        LLVM_DEBUG(dbgs() << "Inst: " << I << " may throw or won't return.\n");
        return false;
      }

      LLVM_DEBUG(dbgs() << "Checking Inst: " << I << "\n");

      if (I.isAtomic() || I.isVolatile()) {
        LLVM_DEBUG(
            dbgs() << "\tInstruction is volatile or atomic. Cannot move it.\n");
        return false;
      }

      if (canHoistInst(I, SafeToHoist, NotHoisting, FO0)) {
        SafeToHoist.push_back(&I);
        LLVM_DEBUG(dbgs() << "\tSafe to hoist.\n");
      } else {
        LLVM_DEBUG(dbgs() << "\tCould not hoist. Trying to sink...\n");
        NotHoisting.push_back(&I);
        if (canSinkInst(I, FO1)) {
          SafeToSink.push_back(&I);
          LLVM_DEBUG(dbgs() << "\tSafe to sink.\n");
        } else {
          LLVM_DEBUG(dbgs() << "\tCould not sink.\n");
          return false;
        }
      }
    }

    LLVM_DEBUG(
        dbgs() << "All preheader instructions could be sunk or hoisted!\n");
    return true;
  }

  class AddRecLoopReplacer : public SCEVRewriteVisitor<AddRecLoopReplacer> {
  public:
    AddRecLoopReplacer(ScalarEvolution &SE, const Loop &OldL, const Loop &NewL,
                       bool UseMax = true)
        : SCEVRewriteVisitor(SE), Valid(true), UseMax(UseMax), OldL(OldL),
          NewL(NewL) {}

    const SCEV *visitAddRecExpr(const SCEVAddRecExpr *Expr) {
      const Loop *ExprL = Expr->getLoop();
      SmallVector<const SCEV *, 2> Operands;
      if (ExprL == &OldL) {
        append_range(Operands, Expr->operands());
        return SE.getAddRecExpr(Operands, &NewL, Expr->getNoWrapFlags());
      }
      if (OldL.contains(ExprL)) {
        bool Pos = SE.isKnownPositive(Expr->getStepRecurrence(SE));
        if (!UseMax || !Pos || !Expr->isAffine()) {
          Valid = false;
          return Expr;
        }
        return visit(Expr->getStart());
      }
      for (const SCEV *Op : Expr->operands())
        Operands.push_back(visit(Op));
      return SE.getAddRecExpr(Operands, ExprL, Expr->getNoWrapFlags());
    }

    bool wasValidSCEV() const { return Valid; }

  private:
    bool Valid, UseMax;
    const Loop &OldL, &NewL;
  };

