PreservedAnalyses KCFIPass::run(Function &Func, FunctionAnalysisManager &AM) {
  Module &M = *Func.getParent();
  if (!M.getModuleFlag("kcfi"))
    return PreservedAnalyses::all();

  SmallVector<CallInst *> TargetCalls;
  for (auto &Instr : instructions(Func)) {
    if (auto *CallInstr = dyn_cast<CallInst>(&Instr))
      if (CallInstr->getOperandBundle(LLVMContext::OB_kcfi))
        TargetCalls.push_back(CallInstr);
  }

  if (TargetCalls.empty())
    return PreservedAnalyses::all();

  LLVMContext &Ctx = M.getContext();

  if (Func.hasFnAttribute("patchable-function-prefix"))
    Ctx.diagnose(
        DiagnosticInfoKCFI("-fpatchable-function-entry=N,M, where M>0 is not "
                           "compatible with -fsanitize=kcfi on this target"));

  IntegerType *Int32Ty = Type::getInt32Ty(Ctx);
  MDNode *LowProbabilityWeights =
      MDBuilder(Ctx).createBranchWeights(1, (1U << 20) - 1);

  Triple TargetTriple(M.getTargetTriple());

  for (CallInst *CI : TargetCalls) {
    const uint32_t ExpectedHashValue =
        cast<ConstantInt>(CI->getOperandBundle(LLVMContext::OB_kcfi)->Inputs[0])
            ->getZExtValue();

    CallBase *NewCall =
        CallBase::removeOperandBundle(CI, LLVMContext::OB_kcfi, CI);
    assert(NewCall != CI);

    NewCall->copyMetadata(*CI);
    CI->replaceAllUsesWith(NewCall);
    CI->eraseFromParent();

    if (!NewCall->isIndirectCall())
      continue;

    IRBuilder<> Builder(NewCall);
    Value *CalleePtr = NewCall->getCalledOperand();

    if (TargetTriple.isARM() || TargetTriple.isThumb()) {
      CalleePtr = Builder.CreateIntToPtr(
          Builder.CreateAnd(Builder.CreatePtrToInt(CalleePtr, Int32Ty),
                            ConstantInt::get(Int32Ty, -2)),
          CalleePtr->getType());
    }

    Value *HashAddr = Builder.CreateConstInBoundsGEP1_32(Int32Ty, CalleePtr, -1);
    Value *Condition = Builder.CreateICmpNE(
        Builder.CreateLoad(Int32Ty, HashAddr),
        ConstantInt::get(Int32Ty, ExpectedHashValue));

    Instruction *ThenTerm =
        SplitBlockAndInsertIfThen(Condition, NewCall, false, LowProbabilityWeights);
    Builder.SetInsertPoint(ThenTerm);
    Builder.CreateCall(Intrinsic::getDeclaration(&M, Intrinsic::debugtrap));

    ++NumKCFIChecks;
  }

  return PreservedAnalyses::none();
}

