void UIScene_SettingsUIMenu::handleInput(int padIdx, int keyCode, bool isRepeat, bool isPressed, bool isReleased, bool &handled)
{
    ui.AnimateKeyPress(padIdx, keyCode, isRepeat, isPressed, isReleased);

    switch (keyCode)
    {
    case ACTION_MENU_CANCEL:
        if (isPressed)
        {
            // Commit checkbox states to game settings
            app.SetGameSettings(padIdx, eGameSetting_DisplayHUD, m_checkboxDisplayHUD.IsChecked() ? 1 : 0);
            app.SetGameSettings(padIdx, eGameSetting_DisplayHand, m_checkboxDisplayHand.IsChecked() ? 1 : 0);
            app.SetGameSettings(padIdx, eGameSetting_DisplaySplitscreenGamertags, m_checkboxShowSplitscreenGamertags.IsChecked() ? 1 : 0);
            app.SetGameSettings(padIdx, eGameSetting_DeathMessages, m_checkboxDisplayDeathMessages.IsChecked() ? 1 : 0);
            app.SetGameSettings(padIdx, eGameSetting_AnimatedCharacter, m_checkboxDisplayAnimatedCharacter.IsChecked() ? 1 : 0);

            // Check if split-screen orientation changed
            int newSplitMode = m_checkboxSplitscreen.IsChecked() ? 1 : 0;
            if (app.GetGameSettings(padIdx, eGameSetting_SplitScreenVertical) != newSplitMode)
            {
                app.SetGameSettings(padIdx, eGameSetting_SplitScreenVertical, newSplitMode);

                // Close scenes appropriately based on player count
                if (app.GetLocalPlayerCount() == 2)
                    ui.CloseAllPlayersScenes();
                else
                    navigateBack();
            }
            else
            {
                navigateBack();
            }
            handled = true;
        }
        break;

    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
        sendInputToMovie(keyCode, isRepeat, isPressed, isReleased);
        break;

    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_LEFT:
    case ACTION_MENU_RIGHT:
        sendInputToMovie(keyCode, isRepeat, isPressed, isReleased);
        break;
    }
}

void UIScene_SettingsUIMenu::handleSliderMove(F64 sliderId, F64 newValue)
{
    WCHAR buffer[256];
    int val = static_cast<int>(newValue);

    switch (static_cast<int>(sliderId))
    {
    case eControl_UISize:
        m_sliderUISize.handleSliderMove(val);
        swprintf(buffer, 256, L"%ls: %d", app.GetString(IDS_SLIDER_UISIZE), val);
        m_sliderUISize.setLabel(buffer);

        if (val != app.GetGameSettings(m_iPad, eGameSetting_UISize) + 1)
        {
            app.SetGameSettings(m_iPad, eGameSetting_UISize, val - 1);
            ui.UpdateSelectedItemPos(m_iPad);
        }
        break;

    case eControl_UISizeSplitscreen:
        m_sliderUISizeSplitscreen.handleSliderMove(val);
        swprintf(buffer, 256, L"%ls: %d", app.GetString(IDS_SLIDER_UISIZESPLITSCREEN), val);
        m_sliderUISizeSplitscreen.setLabel(buffer);

        if (val != app.GetGameSettings(m_iPad, eGameSetting_UISizeSplitscreen) + 1)
        {
            app.SetGameSettings(m_iPad, eGameSetting_UISizeSplitscreen, val - 1);
            ui.UpdateSelectedItemPos(m_iPad);
        }
        break;
    }
}

