void FDisplayClusterVrpnKeyboardInputDevice::PreUpdate()
{
	// Synchronize previous button states before processing new data
	for (auto iter = DeviceData.CreateIterator(); iter; ++iter)
	{
		iter->Value.PreviousState = iter->Value.CurrentState;
	}
}

void FDisplayClusterVrpnKeyboardInputDevice::Update()
{
	if (Implementation)
	{
		UE_LOG(LogDisplayClusterInputVRPN, Verbose, TEXT("Refreshing device: %s"), *GetIdentifier());
		Implementation->mainloop();
	}
}

bool FDisplayClusterVrpnKeyboardInputDevice::Initialize()
{
	// Create the VRPN device interface
	Implementation.Reset(new vrpn_Button_Remote(TCHAR_TO_UTF8(*NetworkAddress)));

	// Attach event callback
	if (Implementation->register_change_handler(this, &FDisplayClusterVrpnKeyboardInputDevice::OnButtonEvent) != 0)
	{
		UE_LOG(LogDisplayClusterInputVRPN, Error, TEXT("%s - failed to register VRPN event handler"), *ToString());
		return false;
	}

	// Perform base setup
	return FDisplayClusterVrpnKeyboardInputDataHolder::Initialize();
}

////////////////////////////////////////////////////////////////////////////////////////////////
// Internal handlers
////////////////////////////////////////////////////////////////////////////////////////////////

void VRPN_CALLBACK FDisplayClusterVrpnKeyboardInputDevice::OnButtonEvent(void *Context, vrpn_BUTTONCB const* EventData)
{
	auto DeviceInstance = static_cast<FDisplayClusterVrpnKeyboardInputDevice*>(Context);

	FButtonData* Entry = DeviceInstance->DeviceData.Find(EventData->button);
	if (!Entry)
	{
		Entry = &DeviceInstance->DeviceData.Add(EventData->button);
		// Initialize old state explicitly
		Entry->PreviousState = false;
	}

	//@note: A single update cycle may involve multiple transitions (e.g., 0→1→0). 
	//       In such cases, only the final state is recorded, potentially missing intermediate changes.
	//       This is acceptable under normal usage conditions where rapid toggling does not occur.
	//       Such behavior usually indicates contact bounce or hardware noise rather than intentional input.
	//
	// Convert VRPN's integer state representation to boolean (0=released, 1=pressed).
	Entry->CurrentState = (EventData->state != 0);

	UE_LOG(LogDisplayClusterInputVRPN, VeryVerbose, TEXT("Keyboard %s:%d - %d"), *DeviceInstance->GetIdentifier(), EventData->button, EventData->state);
}

#include "synth/SampleZone.h"
#include "obj/Object.h"
