// Constructor for SampleZone with default parameters
SampleZone::SampleZone(Hmx::Object *owner)
    : mSample(owner), mVolume(1.0f), mPan(0.5f), mCenterNote(0x3C), mMinNote(12),
      mMaxNote(0x60), mMinVel(10), mMaxVel(0x70), mFXCore(kFXCoreMono) {}

// Serialize the sample zone data to binary stream
void SampleZone::Save(BinStream &bs) const {
    bs << mSample;
    bs << mVolume;
    bs << mPan;
    bs << mCenterNote;
    bs << mMinNote;
    bs << mMaxNote;
    bs << mFXCore;
    bs << mADSR;
    bs << mMinVel;
    bs << mMaxVel;
}

// Deserialize the sample zone data from binary stream
void SampleZone::Load(BinStreamRev &d) {
    d >> mSample;
    d >> mVolume;
    d >> mPan;
    d >> mCenterNote;
    d >> mMinNote;
    d >> mMaxNote;

    int tempFX;
    d >> tempFX;
    mFXCore = static_cast<FXCore>(tempFX);

    d >> mADSR;

    // Handle version compatibility for velocity fields
    if (d.rev >= 3) {
        d >> mMinVel;
        d >> mMaxVel;
    }
}

// Check if given note and velocity fall within this zone's range
bool SampleZone::Includes(unsigned char note, unsigned char velocity) {
    bool noteInRange = (mMinNote <= note) && (note <= mMaxNote);
    bool velInRange = (mMinVel <= velocity) && (velocity <= mMaxVel);
    return noteInRange && velInRange;
}

// Stream output operator for SampleZone
BinStream &operator<<(BinStream &bs, const SampleZone &zone) {
    zone.Save(bs);
    return bs;
}

// Stream input operator for SampleZone
BinStreamRev &operator>>(BinStreamRev &d, SampleZone &zone) {
    zone.Load(d);
    return d;
}

#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int blackTiles, whiteTiles, costBlack, costWhite;
    if (!(cin >> blackTiles >> whiteTiles >> costBlack >> costWhite)) return 0;

    char bgColor, islandColor; // bgColor = background, islandColor = island
    int islandCount; // Number of islands of islandColor
    int holeCount;   // Number of holes of bgColor inside islandColor islands

    // Choose the cheaper color as background to minimize total cost
    if (costBlack < costWhite) {
        bgColor = '@';
        islandColor = '.';
        // Need 'whiteTiles' white islands
        // Background is black, so need 'blackTiles - 1' holes (black areas inside white islands)
        islandCount = whiteTiles;
        holeCount = blackTiles - 1;
    } else {
        bgColor = '.';
        islandColor = '@';
        // Need 'blackTiles' black islands
        // Background is white, so need 'whiteTiles - 1' holes (white areas inside black islands)
        islandCount = blackTiles;
        holeCount = whiteTiles - 1;
    }

    vector<string> resultGrid;

    if (holeCount == 0) {
        // No holes needed: create M simple disconnected islands
        // Use 2-row pattern: top row has islands with separators, bottom row is all background

        string topRow = "", bottomRow = "";

        // Start with a background separator
        topRow += bgColor;
        bottomRow += bgColor;

        for (int i = 0; i < islandCount; ++i) {
            topRow += islandColor;   // Island cell
            bottomRow += bgColor;    // Background below

            topRow += bgColor;       // Separator after island
            bottomRow += bgColor;    // Background continues
        }

        resultGrid.push_back(topRow);
        resultGrid.push_back(bottomRow);
    } else {
        // Need holes: create one complex island with all holes + remaining simple islands
        // Use 4-row pattern for connectivity

        string row0 = "", row1 = "", row2 = "", row3 = "";

        // Initial background separator column
        row0 += bgColor; row1 += bgColor; row2 += bgColor; row3 += bgColor;

        // Build one large island containing all holes
        // Pattern: 
        // Row0: all islandColor
        // Row1: alternating islandColor and bgColor (bgColor cells are holes)
        // Row2: all islandColor
        // Row3: all background

        for (int h = 0; h < 2 * holeCount + 1; ++h) {
            row0 += islandColor;
            if (h % 2 == 0) {
                row1 += islandColor;
            } else {
                row1 += bgColor;     // This is a hole
            }
            row2 += islandColor;
            row3 += bgColor;
        }

        // Add separator column after complex island
        row0 += bgColor; row1 += bgColor; row2 += bgColor; row3 += bgColor;

        // Add remaining simple islands (M-1 of them)
        for (int i = 0; i < islandCount - 1; ++i) {
            row0 += bgColor;
            row1 += islandColor;
            row2 += bgColor;
            row3 += bgColor;

            // Separator after each simple island
            row0 += bgColor; row1 += bgColor; row2 += bgColor; row3 += bgColor;
        }

        resultGrid.push_back(row0);
        resultGrid.push_back(row1);
        resultGrid.push_back(row2);
        resultGrid.push_back(row3);
    }

    cout << resultGrid.size() << " " << resultGrid[0].size() << "\n";
    for (const string& line : resultGrid) {
        cout << line << "\n";
    }

    return 0;
}

#include "dap/network.h"
