namespace {
constexpr int server_port = 19021;

bool send_message(const std::shared_ptr<dap::Writer>& writer, const std::string& message) {
  return writer->write(message.data(), message.size()) && writer->write("\0", 1);
}

std::string receive_message(const std::shared_ptr<dap::Reader>& reader) {
  char buffer_char;
  std::string result;
  while (reader->read(&buffer_char, sizeof(buffer_char)) > 0) {
    if (buffer_char == '\0') {
      return result;
    }
    result += buffer_char;
  }
  return reader->isOpen() ? "<read failed>" : "<stream closed>";
}
}  // anonymous namespace

TEST(Network, ClientServerCommunication) {
  dap::Chan<bool> completion_flag;
  auto network_server = dap::net::Server::create();

  if (!network_server->start(
          server_port,
          [&](const std::shared_ptr<dap::ReaderWriter>& rw) {
            ASSERT_EQ(receive_message(rw), "client to server");
            ASSERT_TRUE(send_message(rw, "server to client"));
            completion_flag.put(true);
          },
          [&](const char* error_msg) { FAIL() << "Server error: " << error_msg; })) {
    FAIL() << "Couldn't start server";
    return;
  }

  for (int iteration = 0; iteration < 5; iteration++) {
    auto client_connection = dap::net::connect("localhost", server_port);
    ASSERT_NE(client_connection, nullptr) << "Failed to connect client " << iteration;
    ASSERT_TRUE(send_message(client_connection, "client to server"));
    ASSERT_EQ(receive_message(client_connection), "server to client");
    completion_flag.take();
    std::this_thread::sleep_for(std::chrono::seconds(1));
  }

  network_server.reset();
}

TEST(Network, ServerRestartFunctionality) {
  dap::Chan<bool> completion_flag;
  auto on_client_connect = [&](const std::shared_ptr<dap::ReaderWriter>& rw) {
    ASSERT_EQ(receive_message(rw), "client to server");
    ASSERT_TRUE(send_message(rw, "server to client"));
    completion_flag.put(true);
  };

  auto handle_server_error = [&](const char* error_msg) { 
    FAIL() << "Server error: " << error_msg; 
  };

  auto network_server = dap::net::Server::create();

  if (!network_server->start(server_port, on_client_connect, handle_server_error)) {
    FAIL() << "Couldn't start server";
    return;
  }

  network_server->stop();
  network_server->stop();
  network_server->stop();

  if (!network_server->start(server_port, on_client_connect, handle_server_error)) {
    FAIL() << "Couldn't restart server";
    return;
  }

  auto client_connection = dap::net::connect("localhost", server_port);
  ASSERT_NE(client_connection, nullptr) << "Failed to connect";
  ASSERT_TRUE(send_message(client_connection, "client to server"));
  ASSERT_EQ(receive_message(client_connection), "server to client");
  completion_flag.take();

  network_server->stop();
  network_server->stop();
  network_server->stop();
  network_server.reset();
}

#include <iostream>
#include <vector>
#include <numeric>
#include <cmath>
#include <random>
#include <chrono>
#include <algorithm>

// Fixed constants as per problem specification
const int MAX_NODES = 100;
const int MAX_WEEKS = 500000;
int numNodes, numWeeks; // Will be set to MAX_NODES and MAX_WEEKS
std::vector<int> targetCounts;

// Random number generator
std::mt19937 randomEngine;

// Computes the total error for a given assignment
long long computeError(const std::vector<int>& assignment) {
    std::vector<int> nodeVisits(MAX_NODES, 0);
    int currentNode = 0;

    for (int week = 0; week < MAX_WEEKS; ++week) {
        nodeVisits[currentNode]++;
        int visitCount = nodeVisits[currentNode];

        if (visitCount % 2 == 1) { // odd visit
            currentNode = assignment[currentNode * 2];
        } else { // even visit
            currentNode = assignment[currentNode * 2 + 1];
        }
    }

    long long totalError = 0;
    for (int i = 0; i < MAX_NODES; ++i) {
        totalError += std::abs(nodeVisits[i] - targetCounts[i]);
    }
    return totalError;
}

int main() {
    // Enable fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Initialize RNG with high-resolution clock
    randomEngine.seed(std::chrono::high_resolution_clock::now().time_since_epoch().count());

    // Read input parameters
    std::cin >> numNodes >> numWeeks;
    targetCounts.resize(numNodes);
    for (int i = 0; i < numNodes; ++i) {
        std::cin >> targetCounts[i];
    }

    // Step 1: Generate initial solution using Largest Remainder Method
    std::vector<int> assignment(2 * numNodes);
    {
        std::vector<double> expectedDegrees(numNodes);
        for (int i = 0; i < numNodes; ++i) {
            expectedDegrees[i] = static_cast<double>(targetCounts[i]) / numWeeks * (2 * numNodes);
        }

        std::vector<int> actualDegrees(numNodes, 0);
        int currentTotal = 0;
        std::vector<std::pair<double, int>> fractionalParts;
        fractionalParts.reserve(numNodes);

        for (int i = 0; i < numNodes; ++i) {
            actualDegrees[i] = static_cast<int>(std::floor(expectedDegrees[i]));
            currentTotal += actualDegrees[i];
            fractionalParts.emplace_back(expectedDegrees[i] - actualDegrees[i], i);
        }

        std::sort(fractionalParts.rbegin(), fractionalParts.rend());
        int remainingSlots = 2 * numNodes - currentTotal;

        for (int i = 0; i < remainingSlots; ++i) {
            actualDegrees[fractionalParts[i].second]++;
        }

        std::vector<int> destinationList;
        destinationList.reserve(2 * numNodes);
        for (int i = 0; i < numNodes; ++i) {
            for (int j = 0; j < actualDegrees[i]; ++j) {
                destinationList.push_back(i);
            }
        }

        std::shuffle(destinationList.begin(), destinationList.end(), randomEngine);
        assignment = destinationList;
    }

    long long currentError = computeError(assignment);
    std::vector<int> bestAssignment = assignment;
    long long bestError = currentError;

    // Step 2: Simulated Annealing optimization
    const double timeBudget = 2.8;
    auto startTime = std::chrono::high_resolution_clock::now();

    double initialTemp = 500.0;
    double finalTemp = 0.1;

    std::uniform_int_distribution<int> moveTypeDist(0, 99);
    std::uniform_int_distribution<int> indexDist(0, 2 * numNodes - 1);
    std::uniform_int_distribution<int> valueDist(0, numNodes - 1);
    std::uniform_real_distribution<double> probabilityDist(0.0, 1.0);

    while (true) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        double elapsedSeconds = std::chrono::duration<double>(currentTime - startTime).count();
        if (elapsedSeconds > timeBudget) break;

        double temperature = initialTemp * (1.0 - elapsedSeconds / timeBudget) + finalTemp * (elapsedSeconds / timeBudget);

        std::vector<int> candidateAssignment = assignment;

        int moveChoice = moveTypeDist(randomEngine);
        int idx1, idx2;

        if (moveChoice < 90) { // Swap operation (90%)
            idx1 = indexDist(randomEngine);
            do {
                idx2 = indexDist(randomEngine);
            } while (idx1 == idx2);
            std::swap(candidateAssignment[idx1], candidateAssignment[idx2]);
        } else { // Value change operation (10%)
            idx1 = indexDist(randomEngine);
            int originalValue = candidateAssignment[idx1];
            do {
                idx2 = valueDist(randomEngine);
            } while (idx2 == originalValue);
            candidateAssignment[idx1] = idx2;
        }

        long long newError = computeError(candidateAssignment);

        double acceptanceProb = std::exp(static_cast<double>(currentError - newError) / temperature);
        if (probabilityDist(randomEngine) < acceptanceProb) {
            assignment = candidateAssignment;
            currentError = newError;

            if (currentError < bestError) {
                bestError = currentError;
                bestAssignment = assignment;
            }
        }
    }

    // Step 3: Output the best found assignment
    for (int i = 0; i < numNodes; ++i) {
        std::cout << bestAssignment[2 * i] << " " << bestAssignment[2 * i + 1] << "\n";
    }

    return 0;
}

#include "alarm.h"
