void printEvent(FILE* fh, void* handle) {
  if (handle == NULL || fh == NULL) return;
  uint8_t type = *(uint8_t *)handle;
  if (type == ncclProfileGroup) {
    struct group* g = (struct group *)handle;
    printGroupEventStart(fh, g);
    struct taskEventBase* base = taskEventQueueHead(g);
    while (base) {
      struct taskEventBase* next = base->next;
      printEvent(fh, base);
      base = next;
    }
    printGroupEventEnd(fh, g);
  } else if (type == ncclProfileColl) {
    struct collective* c = (struct collective *)handle;
    printCollectiveEventStart(fh, c);
    for (int i = 0; i < MAX_CHANNELS; i++) {
      printEvent(fh, &c->send[i]);
      printEvent(fh, &c->recv[i]);
    }
    printCollectiveEventEnd(fh, c);
  } else if (type == ncclProfileP2p) {
    struct p2p* p = (struct p2p *)handle;
    printP2pEventStart(fh, p);
    printEvent(fh, &p->op);
    printP2pEventEnd(fh, p);
  } else if (type == ncclProfileProxyOp) {
    struct proxyOp* p = (struct proxyOp *)handle;
    printProxyOpEventStart(fh, p);
    for (int i = 0; i < MAX_STEPS; i++) {
      printEvent(fh, &p->step[i]);
    }
    printProxyOpEventFinish(fh, p);
  } else if (type == ncclProfileProxyStep) {
    struct proxyStep* p = (struct proxyStep *)handle;
    printProxyStepEvent(fh, p);
  } else if (type == ncclProfileProxyCtrl) {
    struct proxyCtrl* p = (struct proxyCtrl *)handle;
    printProxyCtrlEvent(fh, p);
  }
  return;
}

#define ROTLEFT(x, n) (((x) << (n)) | ((x) >> (32 - (n))))
#define F(a, b, c) (((a) & (b)) | ((~(a)) & (c)))
#define G(a, b, c) (((a) & (c)) | ((b) & (~(c))))
#define H(a, b, c) ((a) ^ (b) ^ (c))
#define I(a, b, c) ((b) ^ ((a) | (~(c))))
#define FF(w, x, y, z, m, s, k)                                                                                         \
  {                                                                                                                     \
    (w) += F((x), (y), (z)) + (m) + (k);                                                                               \
    (w) = (x) + ROTLEFT((w), (s));                                                                                     \
  }
#define GG(w, x, y, z, m, s, k)                                                                                         \
  {                                                                                                                     \
    (w) += G((x), (y), (z)) + (m) + (k);                                                                               \
    (w) = (x) + ROTLEFT((w), (s));                                                                                     \
  }
#define HH(w, x, y, z, m, s, k)                                                                                         \
  {                                                                                                                     \
    (w) += H((x), (y), (z)) + (m) + (k);                                                                               \
    (w) = (x) + ROTLEFT((w), (s));                                                                                     \
  }
#define II(w, x, y, z, m, s, k)                                                                                         \
  {                                                                                                                     \
    (w) += I((x), (y), (z)) + (m) + (k);                                                                               \
    (w) = (x) + ROTLEFT((w), (s));                                                                                     \
  }

/******************** FUNCTION IMPLEMENTATIONS ********************/
void md5_transform(MD5_CTX* context, const unsigned char block[]) {
  MD5_WORD left_a, left_b, left_c, left_d, words[16], idx, count;
#ifndef BROKKR_BIG_ENDIAN
  // Input data is expected in big-endian order per MD5 spec, but this implementation
  // assumes little-endian host. Convert byte order on input and output.
  for (idx = 0, count = 0; idx < 16; ++idx, count += 4)
    words[idx] = (block[count]) |
                 (block[count + 1] << 8) |
                 (block[count + 2] << 16) |
                 (block[count + 3] << 24);
#endif // !BROKKR_BIG_ENDIAN

  left_a = context->state[0];
  left_b = context->state[1];
  left_c = context->state[2];
  left_d = context->state[3];

  FF(left_a, left_b, left_c, left_d, words[0], 7, 0xd76aa478);
  FF(left_d, left_a, left_b, left_c, words[1], 12, 0xe8c7b756);
  FF(left_c, left_d, left_a, left_b, words[2], 17, 0x242070db);
  FF(left_b, left_c, left_d, left_a, words[3], 22, 0xc1bdceee);
  FF(left_a, left_b, left_c, left_d, words[4], 7, 0xf57c0faf);
  FF(left_d, left_a, left_b, left_c, words[5], 12, 0x4787c62a);
  FF(left_c, left_d, left_a, left_b, words[6], 17, 0xa8304613);
  FF(left_b, left_c, left_d, left_a, words[7], 22, 0xfd469501);
  FF(left_a, left_b, left_c, left_d, words[8], 7, 0x698098d8);
  FF(left_d, left_a, left_b, left_c, words[9], 12, 0x8b44f7af);
  FF(left_c, left_d, left_a, left_b, words[10], 17, 0xffff5bb1);
  FF(left_b, left_c, left_d, left_a, words[11], 22, 0x895cd7be);
  FF(left_a, left_b, left_c, left_d, words[12], 7, 0x6b901122);
  FF(left_d, left_a, left_b, left_c, words[13], 12, 0xfd987193);
  FF(left_c, left_d, left_a, left_b, words[14], 17, 0xa679438e);
  FF(left_b, left_c, left_d, left_a, words[15], 22, 0x49b40821);

  GG(left_a, left_b, left_c, left_d, words[1], 5, 0xf61e2562);
  GG(left_d, left_a, left_b, left_c, words[6], 9, 0xc040b340);
  GG(left_c, left_d, left_a, left_b, words[11], 14, 0x265e5a51);
  GG(left_b, left_c, left_d, left_a, words[0], 20, 0xe9b6c7aa);
  GG(left_a, left_b, left_c, left_d, words[5], 5, 0xd62f105d);
  GG(left_d, left_a, left_b, left_c, words[10], 9, 0x02441453);
  GG(left_c, left_d, left_a, left_b, words[15], 14, 0xd8a1e681);
  GG(left_b, left_c, left_d, left_a, words[4], 20, 0xe7d3fbc8);
  GG(left_a, left_b, left_c, left_d, words[9], 5, 0x21e1cde6);
  GG(left_d, left_a, left_b, left_c, words[14], 9, 0xc33707d6);
  GG(left_c, left_d, left_a, left_b, words[3], 14, 0xf4d50d87);
  GG(left_b, left_c, left_d, left_a, words[8], 20, 0x455a14ed);
  GG(left_a, left_b, left_c, left_d, words[13], 5, 0xa9e3e905);
  GG(left_d, left_a, left_b, left_c, words[2], 9, 0xfcefa3f8);
  GG(left_c, left_d, left_a, left_b, words[7], 14, 0x676f02d9);
  GG(left_b, left_c, left_d, left_a, words[12], 20, 0x8d2a4c8a);

  HH(left_a, left_b, left_c, left_d, words[5], 4, 0xfffa3942);
  HH(left_d, left_a, left_b, left_c, words[8], 11, 0x8771f681);
  HH(left_c, left_d, left_a, left_b, words[11], 16, 0x6d9d6122);
  HH(left_b, left_c, left_d, left_a, words[14], 23, 0xfde5380c);
