}

void md5_init(MD5_CTX* context) {
  context->datalen = 0;
  context->bitlen = 0;
  context->state[0] = 0x67452301;
  context->state[1] = 0xEFCDAB89;
  context->state[2] = 0x98BADCFE;
  context->state[3] = 0x10325476;
}

void md5_update(MD5_CTX* context, const unsigned char input[], size_t length) {
  size_t index = 0;
  if (context->datalen) {
    size_t needed = 64 - context->datalen;
    if (length < needed) {
      memcpy(context->data + context->datalen, input, length);
      context->datalen += (MD5_WORD)length;
      return;
    }
    memcpy(context->data + context->datalen, input, needed);
    md5_transform(context, context->data);
    context->bitlen += 512;
    context->datalen = 0;
    index = needed;
  }
  for (; index + 64 <= length; index += 64) {
    md5_transform(context, input + index);
    context->bitlen += 512;
  }
  if (index < length) {
    memcpy(context->data, input + index, length - index);
    context->datalen = (MD5_WORD)(length - index);
  }
}

void md5_final(MD5_CTX* context, unsigned char digest[]) {
  size_t index;
  index = context->datalen;

  // Padding according to MD5 specification
  if (context->datalen < 56) {
    context->data[index++] = 0x80;
    while (index < 56) context->data[index++] = 0x00;
  } else {
    context->data[index++] = 0x80;
    while (index < 64) context->data[index++] = 0x00;
    md5_transform(context, context->data);
    memset(context->data, 0, 56);
  }

  // Append message length in bits
  context->bitlen += context->datalen * 8;
  context->data[56] = (unsigned char)(context->bitlen);
  context->data[57] = (unsigned char)(context->bitlen >> 8);
  context->data[58] = (unsigned char)(context->bitlen >> 16);
  context->data[59] = (unsigned char)(context->bitlen >> 24);
  context->data[60] = (unsigned char)(context->bitlen >> 32);
  context->data[61] = (unsigned char)(context->bitlen >> 40);
  context->data[62] = (unsigned char)(context->bitlen >> 48);
  context->data[63] = (unsigned char)(context->bitlen >> 56);

  md5_transform(context, context->data);

#ifndef BROKKR_BIG_ENDIAN
  // Convert internal little-endian state to big-endian output bytes
  for (index = 0; index < 4; ++index) {
    digest[index] = (context->state[0] >> (index * 8)) & 0xFF;
    digest[index + 4] = (context->state[1] >> (index * 8)) & 0xFF;
    digest[index + 8] = (context->state[2] >> (index * 8)) & 0xFF;
    digest[index + 12] = (context->state[3] >> (index * 8)) & 0xFF;
  }
#endif // !BROKKR_BIG_ENDIAN
}

