#include "benchmark/benchmark.h"
#include "spdlog/spdlog.h"
#include "spdlog/pattern_formatter.h"

void run_formatter_benchmark(benchmark::State &state, std::string fmt_string) {
    auto formatter = spdlog::details::make_unique<spdlog::pattern_formatter>(fmt_string);
    spdlog::memory_buf_t output_buffer;
    std::string log_name = "test_logger";
    const char *message_content =
        "Sample log entry: 80 characters long...........................................";
    spdlog::source_loc location{"src/module/file_handler.cpp", 456, "process_request()"};
    spdlog::details::log_msg record(location, log_name, spdlog::level::warn, message_content);

    for (auto _ : state) {
        output_buffer.clear();
        formatter->format(record, output_buffer);
        benchmark::DoNotOptimize(output_buffer);
    }
}

void run_all_formatter_tests() {
    // Test single-character format flags
    std::string all_flags = "+vtPnlLaAbBcCYDmdHIMSefFprRTXzEisg@luioO%";
    std::vector<std::string> simple_patterns;
    for (auto &symbol : all_flags) {
        auto pattern = std::string("%") + symbol;
        benchmark::RegisterBenchmark(pattern.c_str(), &run_formatter_benchmark, pattern);

        // Additional padding tests (commented out)
        // pattern = std::string("%20") + symbol;
        // benchmark::RegisterBenchmark(pattern.c_str(), &run_formatter_benchmark, pattern);
        // pattern = std::string("%=" + "20") + symbol;
        // benchmark::RegisterBenchmark(pattern.c_str(), &run_formatter_benchmark, pattern);
    }

    // Complex real-world patterns
    std::vector<std::string> complex_patterns = {
        "[%Y-%m-%d %H:%M:%S.%e] [%l] [thread:%t] %v",
        "%D %X - %n - %v",
        "[%Y/%m/%d %H:%M:%S] %^%L%$ [%n] %v",
    };

    for (auto &fmt : complex_patterns) {
        benchmark::RegisterBenchmark(fmt.c_str(), &run_formatter_benchmark, fmt)
            ->Iterations(1500000);
    }
}

int main(int argc, char **arguments) {
    spdlog::set_pattern("%^[%l]%$ %v");

    if (argc != 2) {
        spdlog::error("Usage: {} <pattern> or \"all\"", arguments[0]);
        return 1;
    }

    std::string selected_pattern = arguments[1];
    if (selected_pattern == "all") {
        run_all_formatter_tests();
    } else {
        benchmark::RegisterBenchmark(selected_pattern.c_str(), &run_formatter_benchmark, selected_pattern);
    }

    benchmark::Initialize(&argc, arguments);
    benchmark::RunSpecifiedBenchmarks();
}

