PerformanceTimer::PerformanceTimer()
{
#if !defined (__linux__)
	// Retrieve the performance counter frequency
	LARGE_INTEGER freq;
	QueryPerformanceFrequency(&freq);
	m_secondsPerTick = 1.0f / static_cast<float>(freq.QuadPart);

	Reset();
#endif
}

void PerformanceTimer::Reset()
{
#if !defined (__linux__)
	QueryPerformanceCounter(&m_startTime);
#endif
}

void PerformanceTimer::PrintElapsedTime(const std::wstring& label)
{
#if !defined (__linux__)
	LARGE_INTEGER currentTime, delta;
	QueryPerformanceCounter(&currentTime);
	delta.QuadPart = currentTime.QuadPart - m_startTime.QuadPart;
	float elapsed = m_secondsPerTick * static_cast<float>(delta.QuadPart);
	app.DebugPrintf(L"TIMER: %ls: Elapsed time %.6f\n", label.c_str(), elapsed);
#endif
}

