namespace RCCLTestGuards
{
    // Memory handle cleanup handler for NET transport
    struct NetMemHandleCleanup
    {
        ncclNet_t* netModule;
        void*      communicator;
        NetMemHandleCleanup(ncclNet_t* n = nullptr, void* c = nullptr) : netModule(n), communicator(c) {}
        void operator()(void* mhandle) const
        {
            if(mhandle && communicator && netModule)
            {
                netModule->deregMr(communicator, mhandle);
            }
        }
    };

    // Send communicator cleanup handler
    struct NetSendChannelCleanup
    {
        ncclNet_t* netModule;
        explicit NetSendChannelCleanup(ncclNet_t* n = nullptr) : netModule(n) {}
        void operator()(void* comm) const
        {
            if(comm && netModule)
                netModule->closeSend(comm);
        }
    };

    // Receive communicator cleanup handler
    struct NetRecvChannelCleanup
    {
        ncclNet_t* netModule;
        explicit NetRecvChannelCleanup(ncclNet_t* n = nullptr) : netModule(n) {}
        void operator()(void* comm) const
        {
            if(comm && netModule)
                netModule->closeRecv(comm);
        }
    };

    // Listen communicator cleanup handler
    struct NetListenChannelCleanup
    {
        ncclNet_t* netModule;
        explicit NetListenChannelCleanup(ncclNet_t* n = nullptr) : netModule(n) {}
        void operator()(void* comm) const
        {
            if(comm && netModule)
                netModule->closeListen(comm);
        }
    };

    using NetMemHandleGuard     = ResourceGuard<void*, NetMemHandleCleanup>;
    using NetSendChannelGuard   = ResourceGuard<void*, NetSendChannelCleanup>;
    using NetRecvChannelGuard   = ResourceGuard<void*, NetRecvChannelCleanup>;
    using NetListenChannelGuard = ResourceGuard<void*, NetListenChannelCleanup>;

    class NetConnectionManager
    {
    private:
        ncclNet_t* netModule_;
        void*      listenChannel_;
        void*      sendChannel_;
        void*      recvChannel_;
    public:
        explicit NetConnectionManager(ncclNet_t* net)
            : netModule_(net), listenChannel_(nullptr), sendChannel_(nullptr), recvChannel_(nullptr)
        {}
        ~NetConnectionManager()
        {
            if(recvChannel_ && netModule_)
                netModule_->closeRecv(recvChannel_);
            if(sendChannel_ && netModule_)
                netModule_->closeSend(sendChannel_);
            if(listenChannel_ && netModule_)
                netModule_->closeListen(listenChannel_);
        }

        void assignListenChannel(void* ch) { listenChannel_ = ch; }
        void assignSendChannel(void* ch)   { sendChannel_ = ch; }
        void assignRecvChannel(void* ch)   { recvChannel_ = ch; }

        void* getListenChannel() const { return listenChannel_; }
        void* getSendChannel() const   { return sendChannel_; }
        void* getRecvChannel() const   { return recvChannel_; }

        NetConnectionManager(const NetConnectionManager&)            = delete;
        NetConnectionManager& operator=(const NetConnectionManager&) = delete;
        NetConnectionManager(NetConnectionManager&&)                 = delete;
        NetConnectionManager& operator=(NetConnectionManager&&)      = delete;
    };

    inline NetMemHandleGuard makeNetMemHandleGuard(void* mhandle, ncclNet_t* net, void* comm)
    {
        return NetMemHandleGuard(mhandle, NetMemHandleCleanup(net, comm));
    }

    inline NetSendChannelGuard makeNetSendChannelGuard(void* comm, ncclNet_t* net)
    {
        return NetSendChannelGuard(comm, NetSendChannelCleanup(net));
    }

    inline NetRecvChannelGuard makeNetRecvChannelGuard(void* comm, ncclNet_t* net)
    {
        return NetRecvChannelGuard(comm, NetRecvChannelCleanup(net));
    }

    inline NetListenChannelGuard makeNetListenChannelGuard(void* comm, ncclNet_t* net)
    {
        return NetListenChannelGuard(comm, NetListenChannelCleanup(net));
    }
} // namespace RCCLTestGuards

namespace
{
    // Buffer configuration constants
    inline constexpr size_t kBufferSizeStandard = 8192;

    // Network transport constraints
    inline constexpr int kMinNodesForNetwork   = 3; 
    inline constexpr int kExactRanksForNetwork = 2; 

    // Data pattern generation parameters
    inline constexpr int kPatternScaleFactor     = 50;
    inline constexpr int kByteValueRange         = 128;
} // namespace

class NetworkMPITransportTest : public TransportTestBase
{
protected:
    void SetUp() override
    {
        TransportTestBase::SetUp();
        if(config.global_rank == 0)
        {
            TEST_INFO("Network transport setup phase finished");
        }
    }

    void TearDown() override
    {
        if(config.global_rank == 0)
        {
            TEST_INFO("Network transport teardown phase finished");
        }
        TransportTestBase::TearDown();
    }

public:
    // Test ncclNetGraphRegisterBuffer
    void executeGraphBufferRegistration()
    {
        if(config.global_rank == 0)
        {
            TEST_INFO("Executing ncclNetGraphRegisterBuffer test...");
        }

        ASSERT_NE(comm_handle, nullptr) << "Rank " << config.global_rank << ": communicator invalid";

        void* tx_buffer = nullptr;
        void* rx_buffer = nullptr;
        allocateAndInitBuffersGuarded(&tx_buffer, &rx_buffer, kBufferSizeStandard, kBufferSizeStandard);

        void* tx_reg_handle = nullptr;
        void* rx_reg_handle = nullptr;
        preRegisterBuffersGuarded(tx_buffer,
                                  rx_buffer,
                                  kBufferSizeStandard,
                                  kBufferSizeStandard,
                                  &tx_reg_handle,
                                  &rx_reg_handle);

        int                                                       registration_flag{};
        void*                                                     reg_handle{};
        ncclIntruQueue<ncclCommCallback, &ncclCommCallback::next> cleanup_list{};
        int                                                       cleanup_count{};

        ncclConnector* tx_conn_array[1] = {&tx_connector};
        auto result = ncclNetGraphRegisterBuffer(
            reinterpret_cast<ncclComm*>(getActiveCommunicator()),
            tx_buffer,
            kBufferSizeStandard,
            tx_conn_array,
            1,
            &registration_flag,
            &reg_handle,
            &cleanup_list,
            &cleanup_count
        );

        EXPECT_EQ(ncclSuccess, result)
            << "Rank " << config.global_rank
            << ": Graph buffer registration failed: " << ncclGetErrorString(result);

        if(config.global_rank == 0)
        {
            TEST_INFO("    Registration result: %s", ncclGetErrorString(result));
            TEST_INFO("    Flag value: %d", registration_flag);
            TEST_INFO("    Handle address: %p", reg_handle);
            TEST_INFO("    Cleanup entries: %d", cleanup_count);
        }

        if(config.global_rank == 0)
        {
            TEST_INFO("Graph buffer registration test completed");
        }
    }

    // Test ncclNetLocalRegisterBuffer
    void executeLocalBufferRegistration()
    {
        if(config.global_rank == 0)
        {
            TEST_INFO("Executing ncclNetLocalRegisterBuffer test...");
            TEST_INFO("This API internally calls ncclNetLocalRegisterBuffer "
                      "and ncclNetLocalRegisterBuffer");
        }

        ASSERT_NE(comm_handle, nullptr) << "Rank " << config.global_rank << ": communicator invalid";

        void* tx_buffer = nullptr;
        void* rx_buffer = nullptr;
        allocateAndInitBuffersGuarded(&tx_buffer, &rx_buffer, kBufferSizeStandard, kBufferSizeStandard);

        void* tx_reg_handle = nullptr;
        void* rx_reg_handle = nullptr;
        preRegisterBuffersGuarded(tx_buffer,
                                  rx_buffer,
                                  kBufferSizeStandard,
                                  kBufferSizeStandard,
                                  &tx_reg_handle,
                                  &rx_reg_handle);

        int   registration_flag{};
        void* reg_handle{};
        ncclConnector* tx_conn_array[1] = {&tx_connector};
        auto result = ncclNetLocalRegisterBuffer(
            reinterpret_cast<ncclComm*>(getActiveCommunicator()),
            tx_buffer,
            kBufferSizeStandard,
            tx_conn_array,
            1,
            &registration_flag,
            &reg_handle
        );

        EXPECT_EQ(ncclSuccess, result)
            << "Rank " << config.global_rank
            << ": Local buffer registration failed: " << ncclGetErrorString(result);

        if(config.global_rank == 0)
        {
            TEST_INFO("    Registration result: %s", ncclGetErrorString(result));
            TEST_INFO("    Flag value: %d", registration_flag);
            TEST_INFO("    Handle address: %p", reg_handle);
        }
    }

    // Test various buffer sizes with data transfer
    void executeVariableSizeTransfer()
    {
        if(config.global_rank == 0)
        {
            TEST_INFO("Testing variable buffer sizes (aligned/unaligned) with network transfer...");
        }

        ASSERT_NE(comm_handle, nullptr) << "Rank " << config.global_rank << ": communicator invalid";

        std::vector<size_t> test_sizes = {
            2, 5, 11, 17, 31, 64, 129, 257, 512, 1023,
            2048, 2049, 4096, 4097, 8192, 8193, 16384, 16385,
            32768, 32769, 65536, 65537, 131072, 131073, 262144, 262145,
            524288, 524289, 1048576, 1048577
        };

        int         peer_rank = (config.global_rank == 0) ? 1 : 0;
        hipStream_t stream    = getActiveStream();
        ASSERT_NE(stream, nullptr) << "Rank " << config.global_rank << ": Stream unavailable";

        for(size_t size : test_sizes)
        {
            if(config.global_rank == 0)
            {
                TEST_INFO("  Executing transfer test for size: %zu bytes", size);
            }

            void* tx_buffer = nullptr;
            void* rx_buffer = nullptr;
            auto [txGuard, rxGuard]
                = allocateAndInitBuffersGuarded(&tx_buffer, &rx_buffer, size, size, false);

            ASSERT_NE(tx_buffer, nullptr) << "Rank " << config.global_rank
                                          << ": TX buffer allocation failed at size " << size;
            ASSERT_NE(rx_buffer, nullptr) << "Rank " << config.global_rank
                                          << ": RX buffer allocation failed at size " << size;

            uint8_t* tx_data = static_cast<uint8_t*>(tx_buffer);
            for(size_t idx = 0; idx < size; idx++)
            {
                tx_data[idx] = static_cast<uint8_t>(
                    (config.global_rank * kPatternScaleFactor + idx) % kByteValueRange);
            }

            uint8_t* rx_data = static_cast<uint8_t*>(rx_buffer);
            for(size_t idx = 0; idx < size; idx++)
            {
                rx_data[idx] = 0xFE;
            }

            ASSERT_MPI_SUCCESS(ncclGroupStart());
            ASSERT_MPI_SUCCESS(
                ncclSend(tx_buffer, size, ncclInt8, peer_rank, getActiveCommunicator(), stream));
            ASSERT_MPI_SUCCESS(
                ncclRecv(rx_buffer, size, ncclInt8, peer_rank, getActiveCommunicator(), stream));
            ASSERT_MPI_SUCCESS(ncclGroupEnd());

            ASSERT_MPI_EQ(hipSuccess, hipStreamSynchronize(stream));

            int       error_count           = 0;
            const int max_error_messages    = 3;
            for(size_t idx = 0; idx < size && error_count < max_error_messages; idx++)
            {
                uint8_t expected = static_cast<uint8_t>((peer_rank * kPatternScaleFactor + idx)
                                                        % kByteValueRange);
                if(rx_data[idx] != expected)
                {
                    TEST_WARN("Size %zu - Mismatch at index %zu: expected %u, got %u",
                              size,
                              idx,
                              expected,
                              rx_data[idx]);
                    error_count++;
                }
            }

            EXPECT_EQ(0, error_count) << "Rank " << config.global_rank
                                      << ": Data corruption detected at size " << size;
            if(config.global_rank == 0 && error_count == 0)
            {
                TEST_INFO("  Size %zu - Transfer verified successfully", size);
            }
        }
    }
};

