    FFBEngineTestAccess::SetSessionPeakTorque(engine, 10.0);
    FFBEngineTestAccess::SetSmoothedStructuralMult(engine, 0.1);

    VehicleScoringInfoV01 info;
    memset(&info, 0, sizeof(info));
    info.mIsPlayer = true;
    info.mControl = 0;
    info.mInGarageStall = true;

    double vehicleSpeed = 0.0;
    TelemInfoV01 telemetry = CreateBasicTestTelemetry(vehicleSpeed, 0.0);
