    double outputForce = engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, ffbEnabled);
    std::cout << "  Output Force (expected zero): " << outputForce << std::endl;
    ASSERT_NEAR(outputForce, 0.0, 1e-7);
}

TEST_CASE(test_issue_185_fix_soft_lock_alt, "Internal") {
    std::cout << "Verification Test: Issue #185 Fix (Soft Lock Behavior)" << std::endl;
    FFBEngine engine;
    InitializeEngine(engine);
    engine.m_gain = 1.0f;
    engine.m_min_force = 0.05f;
    engine.m_wheelbase_max_nm = 100.0f;
    engine.m_target_rim_nm = 100.0f;

    FFBEngineTestAccess::SetSessionPeakTorque(engine, 100.0);
    FFBEngineTestAccess::SetSmoothedStructuralMult(engine, 0.01);

    VehicleScoringInfoV01 info;
    memset(&info, 0, sizeof(info));
    info.mIsPlayer = true;
    info.mControl = 0;
    info.mInGarageStall = true;

    double vehicleSpeed = 0.0;
    TelemInfoV01 telemetry = CreateBasicTestTelemetry(vehicleSpeed, 0.0);

    bool ffbEnabled = engine.IsFFBAllowed(info, 5);

    // Simulate soft lock condition: 10% oversteer → stiffness 20 * 0.1 * 50 = 100 Nm
    telemetry.mUnfilteredSteering = 1.1;
    engine.m_soft_lock_enabled = true;
    engine.m_soft_lock_stiffness = 20.0f;

    double outputForce = engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, ffbEnabled);
    double absForce = std::abs(outputForce);
    std::cout << "  Soft Lock Force (100Nm): " << outputForce << " (|force|: " << absForce << ")" << std::endl;

    // Normalized force = 100 / 100 = 1.0
    ASSERT_NEAR(absForce, 1.0, 0.01);
}

TEST_CASE(test_issue_235_garage_noise_alt, "Internal") {
    std::cout << "Verification Test: Issue #235 (Garage Noise Suppression)" << std::endl;
    FFBEngine engine;
    InitializeEngine(engine);
    engine.m_gain = 1.0f;
    engine.m_min_force = 0.05f;
    engine.m_steering_shaft_gain = 1.0f;
    engine.m_wheelbase_max_nm = 10.0f;
    engine.m_target_rim_nm = 10.0f;
    engine.m_soft_lock_enabled = true;
    engine.m_soft_lock_stiffness = 20.0f;

    FFBEngineTestAccess::SetSessionPeakTorque(engine, 10.0);
    FFBEngineTestAccess::SetSmoothedStructuralMult(engine, 0.1);

    VehicleScoringInfoV01 info;
    memset(&info, 0, sizeof(info));
    info.mIsPlayer = true;
    info.mControl = 0;
    info.mInGarageStall = true;

    double vehicleSpeed = 0.0;
    TelemInfoV01 telemetry = CreateBasicTestTelemetry(vehicleSpeed, 0.0);

    // Scenario A: Minimal steering jitter — should be suppressed
    telemetry.mUnfilteredSteering = 0.001;
    bool ffbEnabled = engine.IsFFBAllowed(info, 5);
    double forceA = engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, ffbEnabled);
    std::cout << "  Force with 0.1%% steering noise: " << forceA << std::endl;
    ASSERT_EQ(forceA, 0.0);

    // Scenario B: Actual rack limit reached
    telemetry.mUnfilteredSteering = 1.1;
    double forceB = engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, ffbEnabled);
    std::cout << "  Force at 10%% excess steering: " << forceB << std::endl;
    ASSERT_GT(std::abs(forceB), 0.5);

    // Scenario C: Transition state reset
    engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, true);   // active driving
    engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, false);  // garage transition

    double smoothedVel = FFBEngineTestAccess::GetSteeringVelocitySmoothed(engine);
    std::cout << "  Steering velocity after transition reset: " << smoothedVel << std::endl;
    ASSERT_EQ(smoothedVel, 0.0);
}

