#include "TuringTest.h"
#include "ArcManager.h"
using namespace turing::test;
using namespace db;

class ArcManagerTest : public TuringTest {
protected:
    void setup() override {
    }
    void cleanup() override {
    }
};

struct TestData {
    size_t fieldX {0};
    size_t fieldY {0};
};

TEST_F(ArcManagerTest, noEntries) {
    ArcManager<TestData> container;
    EXPECT_EQ(container.count(), 0);
    const size_t removedCount = container.purge();
    EXPECT_EQ(removedCount, 0);
}

TEST_F(ArcManagerTest, removeEverything) {
    ArcManager<TestData> container;
    {
        WeakArc<TestData> ptrA = container.generate(1, 2);
        WeakArc<TestData> ptrB = container.generate(2, 3);
        WeakArc<TestData> ptrC = container.generate(4, 5);
        // Local weak references go out of scope here
        // The container will release the objects during purge()
    }
    EXPECT_EQ(container.count(), 3);
    const size_t removedCount = container.purge();
    EXPECT_EQ(removedCount, 3);
    EXPECT_EQ(container.count(), 0);
}

TEST_F(ArcManagerTest, removeSome) {
    ArcManager<TestData> container;
    WeakArc<TestData> ptrA = container.generate(1, 2);
    {
        WeakArc<TestData> ptrB = container.generate(2, 3);
        WeakArc<TestData> ptrC = container.generate(4, 5);
        // ptrB and ptrC go out of scope here
        // The container will delete them on purge()
    }
    EXPECT_EQ(container.count(), 3);
    const size_t removedCount = container.purge();
    EXPECT_EQ(removedCount, 2);
    EXPECT_EQ(container.count(), 1);
}

