#include <catch2/catch_test_macros.hpp>
#include <thread>
#include <chrono>
#include <iostream>
#include <Gorgon/Utils/Logging.h>

TEST_CASE("Console Logging Verification", "[Logger]") {

    Gorgon::Utils::Logger logobj("Module Test", true, true);

    std::stringstream buffer;
    logobj.InitializeStream(buffer);

    logobj << "Hi " << 10;

    std::this_thread::sleep_for(std::chrono::seconds(1));

    logobj << "x" << std::endl << "y";

    logobj.SetSection("Updated");
    logobj.SetMarkDate(false);
    logobj.Log("Another entry! ");

    buffer.seekg(0, std::ios::beg);

    std::string datestr, timestr;
    buffer >> datestr; // date part
    buffer >> timestr; // time part

    Gorgon::Time::Date timestamp(datestr + "T" + timestr), current = Gorgon::Time::Date::Now();

    REQUIRE((current - timestamp) < 2);

    buffer >> datestr; // section-1
    REQUIRE(datestr == "Module");
    buffer >> datestr; // section-2
    REQUIRE(datestr == "Test");

    buffer >> datestr; // message-1
    REQUIRE(datestr == "Hi");
    buffer >> datestr; // message-2
    REQUIRE(datestr == "10");

    buffer >> datestr >> datestr >> datestr >> datestr >> datestr;
    REQUIRE(datestr == "x");
    char ch;
    buffer.read(&ch, 1);
    REQUIRE((ch == '\n' || ch == '\r'));

    buffer >> datestr; // y

    buffer >> datestr >> datestr;
    REQUIRE(datestr == "Updated");
    buffer >> datestr;
    REQUIRE(datestr == "Error!");

    buffer.str("");

    logobj.SetMarkTime(false);
    logobj << "Sample2";
    buffer >> datestr;
    REQUIRE(datestr == "Updated");
    buffer >> datestr;
    REQUIRE(datestr == "Sample2");

    logobj.DisableColor();
    REQUIRE(logobj.IsColorEnabled() == false);


    logobj.Log("End", Gorgon::Utils::Logger::Success);
    buffer >> datestr;
    REQUIRE(datestr == "Updated");
    buffer >> datestr;
    REQUIRE(datestr == "Success:");
    buffer >> datestr;
    REQUIRE(datestr == "End");
}

#include <fstream>
#include <iostream>
#include <cstdio>
#include <cstdlib>

int main() {
    // Function to create and write to file
    auto createFile = []() {
        std::ofstream outputFile;
        char buffer[100];
        char choice;

        outputFile.open("datafile.txt");
        if (!outputFile.is_open()) {
            std::cout << "Error: Cannot open file for writing" << std::endl;
            std::cin.get();
            std::exit(1);
        }

        do {
            std::cout << "Enter text to store: ";
            std::cin.ignore();
            std::cin.getline(buffer, 100);
            outputFile << buffer << std::endl;
            std::cout << "Continue entering text? (y/n): ";
            std::cin >> choice;
        } while (choice == 'y' || choice == 'Y');

        outputFile.close();
    };

    // Function to read and display file contents
    auto readFile = []() {
        std::ifstream inputFile;
        char character;

        std::cout << "File contents:" << std::endl;
        inputFile.open("datafile.txt");
        if (!inputFile.is_open()) {
            std::cout << "Error: Cannot open file for reading" << std::endl;
            std::cin.get();
            std::exit(1);
        }

        while (inputFile.get(character)) {
            std::cout.put(character);
        }

        inputFile.close();
    };

    // Execute operations
    createFile();
    readFile();

    return 0;
}

