static char* messageLines[DebugUI::StatusLines];
static char* historyLines[DebugUI::LogLines];
static int activeMessageIndex = 0;

DebugUI::DebugUI() {
    // Allocate memory for log history entries
    for (int idx = 0; idx < LogLines; ++idx) {
        historyLines[idx] = (char*)malloc(LineLength);
        memset(historyLines[idx], 0x0, LineLength);
    }

    // Allocate memory for status message entries
    for (int idx = 0; idx < StatusLines; ++idx) {
        messageLines[idx] = (char*)malloc(LineLength);
        memset(messageLines[idx], 0x0, LineLength);
    }

    RenderData = Iron::Drawlist::New();
    auto fontManager = ReCraftCore::GetInstance()->GetAssetManager();
    RenderData->SetFont(fontManager->Get<Iron::Font>("font"));
}

DebugUI::~DebugUI() {
    // Free all log history memory
    for (int i = 0; i < LogLines; ++i) {
        free(historyLines[i]);
    }

    // Free all status message memory
    for (int i = 0; i < StatusLines; ++i) {
        free(messageLines[i]);
    }

    RenderData.reset();
}

void DebugUI::Text(const char* format, ...) {
    if (activeMessageIndex >= StatusLines) {
        return;
    }

    va_list arguments;
    va_start(arguments, format);
    vsprintf(messageLines[activeMessageIndex++], format, arguments);
    va_end(arguments);
}

void DebugUI::Log(const char* format, ...) {
    char* oldestEntry = historyLines[LogLines - 1];

    // Shift all log entries down by one position
    for (int pos = LogLines - 1; pos > 0; --pos) {
        historyLines[pos] = historyLines[pos - 1];
    }

    // Place new entry at the front
    historyLines[0] = oldestEntry;

    va_list arguments;
    va_start(arguments, format);
    vsprintf(historyLines[0], format, arguments);
    va_end(arguments);
}

void DebugUI::Draw() {
    RenderData->SetFontScale(0.5f);
    int verticalOffset = (320 / 4) * 3;

    // Render log history
    for (auto& entry : historyLines) {
        int lineHeight = 14;
        RenderData->DrawText(Amy::fvec2(0, verticalOffset), entry, 0xffffffff);
        verticalOffset += lineHeight;
        if (verticalOffset >= 320) {
            break;
        }
    }

    // Render status messages
    verticalOffset = 0;
    for (auto& msg : messageLines) {
        int lineHeight = 14;
        RenderData->DrawText(Amy::fvec2(0, verticalOffset), msg, 0xffffffff);
        verticalOffset += lineHeight;
        memset(msg, 0x0, LineLength);
    }

    activeMessageIndex = 0;
}

