#include "ocs2_oc/oc_data/PerformanceIndex.h"
#include <iomanip>
#include <ocs2_core/misc/Numerics.h>

namespace ocs2 {

PerformanceIndex& PerformanceIndex::operator+=(const PerformanceIndex& other) {
  merit += other.merit;
  cost += other.cost;
  dualFeasibilitiesSSE += other.dualFeasibilitiesSSE;
  dynamicsViolationSSE += other.dynamicsViolationSSE;
  equalityConstraintsSSE += other.equalityConstraintsSSE;
  inequalityConstraintsSSE += other.inequalityConstraintsSSE;
  equalityLagrangian += other.equalityLagrangian;
  inequalityLagrangian += other.inequalityLagrangian;
  return *this;
}

PerformanceIndex& PerformanceIndex::operator*=(const scalar_t factor) {
  merit *= factor;
  cost *= factor;
  dualFeasibilitiesSSE *= factor;
  dynamicsViolationSSE *= factor;
  equalityConstraintsSSE *= factor;
  inequalityConstraintsSSE *= factor;
  equalityLagrangian *= factor;
  inequalityLagrangian *= factor;
  return *this;
}

bool PerformanceIndex::isApprox(const PerformanceIndex& reference, const scalar_t tolerance) const {
  return numerics::almost_eq(merit, reference.merit, tolerance) &&
         numerics::almost_eq(cost, reference.cost, tolerance) &&
         numerics::almost_eq(dualFeasibilitiesSSE, reference.dualFeasibilitiesSSE, tolerance) &&
         numerics::almost_eq(dynamicsViolationSSE, reference.dynamicsViolationSSE, tolerance) &&
         numerics::almost_eq(equalityConstraintsSSE, reference.equalityConstraintsSSE, tolerance) &&
         numerics::almost_eq(inequalityConstraintsSSE, reference.inequalityConstraintsSSE, tolerance) &&
         numerics::almost_eq(equalityLagrangian, reference.equalityLagrangian, tolerance) &&
         numerics::almost_eq(inequalityLagrangian, reference.inequalityLagrangian, tolerance);
}

void swap(PerformanceIndex& first, PerformanceIndex& second) {
  using std::swap;
  swap(first.merit, second.merit);
  swap(first.cost, second.cost);
  swap(first.dualFeasibilitiesSSE, second.dualFeasibilitiesSSE);
  swap(first.dynamicsViolationSSE, second.dynamicsViolationSSE);
  swap(first.equalityConstraintsSSE, second.equalityConstraintsSSE);
  swap(first.inequalityConstraintsSSE, second.inequalityConstraintsSSE);
  swap(first.equalityLagrangian, second.equalityLagrangian);
  swap(first.inequalityLagrangian, second.inequalityLagrangian);
}

PerformanceIndex toPerformanceIndex(const Metrics& metrics) {
  PerformanceIndex result;
  result.merit = 0.0;  // solver will populate this
  result.cost = metrics.cost;
  result.dualFeasibilitiesSSE = 0.0;  // solver responsibility
  result.dynamicsViolationSSE = getEqConstraintsSSE(metrics.dynamicsViolation);
  result.equalityConstraintsSSE =
      getEqConstraintsSSE(metrics.stateEqConstraint) + getEqConstraintsSSE(metrics.stateInputEqConstraint);
  result.inequalityConstraintsSSE =
      getIneqConstraintsSSE(metrics.stateIneqConstraint) + getIneqConstraintsSSE(metrics.stateInputIneqConstraint);
  result.equalityLagrangian =
      sumPenalties(metrics.stateEqLagrangian) + sumPenalties(metrics.stateInputEqLagrangian);
  result.inequalityLagrangian =
      sumPenalties(metrics.stateIneqLagrangian) + sumPenalties(metrics.stateInputIneqLagrangian);
  return result;
}

PerformanceIndex toPerformanceIndex(const Metrics& metrics, const scalar_t dt) {
  auto index = toPerformanceIndex(metrics);
  // cost scaling omitted as already accounted for in multiple_shooting::computeIntermediateMetrics()
  index.dualFeasibilitiesSSE *= dt;
  index.dynamicsViolationSSE *= dt;
  index.equalityConstraintsSSE *= dt;
  index.inequalityConstraintsSSE *= dt;
  return index;
}

std::ostream& operator<<(std::ostream& out, const PerformanceIndex& perf) {
  constexpr size_t fieldWidth = 12;
  const auto indent = out.width();
  out << std::left;
  out << std::setw(indent) << "";
  out << "Rollout Merit:              " << std::setw(fieldWidth) << perf.merit;
  out << "Rollout Cost:               " << std::setw(fieldWidth) << perf.cost << '\n';
  out << std::setw(indent) << "";
  out << "Dual feasibilities SSE:     " << std::setw(fieldWidth) << perf.dualFeasibilitiesSSE;
  out << "Dynamics violation SSE:     " << std::setw(fieldWidth) << perf.dynamicsViolationSSE << '\n';
  out << std::setw(indent) << "";
  out << "Equality constraints SSE:   " << std::setw(fieldWidth) << perf.equalityConstraintsSSE;
  out << "Inequality constraints SSE: " << std::setw(fieldWidth) << perf.inequalityConstraintsSSE << '\n';
  out << std::setw(indent) << "";
  out << "Equality Lagrangian:        " << std::setw(fieldWidth) << perf.equalityLagrangian;
  out << "Inequality Lagrangian:      " << std::setw(fieldWidth) << perf.inequalityLagrangian;
  return out;
}

}  // namespace ocs2

#include "FuzzerDefs.h"
#if LIBFUZZER_APPLE
#include "FuzzerIO.h"
#include <mutex>
#include <signal.h>
#include <spawn.h>
#include <sys/wait.h>

// Declaration for environ since it's missing a header on macOS
extern "C" char **environ;

namespace fuzzer {

static std::mutex SignalControlMutex;

// Tracks active threads using ExecuteCommand; protected by SignalControlMutex
static int RunningThreadCount = 0;

// Stores original signal dispositions for restoration
static struct sigaction SavedSigIntHandler;
static struct sigaction SavedSigQuitHandler;
static sigset_t PreviousSignalMask;

// Thread-safe implementation of system() that avoids the mutex issue in libc
int ExecuteCommand(const std::string &CmdLine) {
    posix_spawnattr_t SpawnAttrs;
    if (posix_spawnattr_init(&SpawnAttrs))
        return -1;

    // Setup signal handling for first concurrent user
    {
        std::lock_guard<std::mutex> Guard(SignalControlMutex);
        if (RunningThreadCount == 0) {
            static struct sigaction IgnoreAction;
            sigset_t BlockSet;
            memset(&IgnoreAction, 0, sizeof(IgnoreAction));
            IgnoreAction.sa_handler = SIG_IGN;

            if (sigaction(SIGINT, &IgnoreAction, &SavedSigIntHandler) == -1) {
                Printf("Failed to ignore SIGINT\n");
                (void)posix_spawnattr_destroy(&SpawnAttrs);
                return -1;
            }

            if (sigaction(SIGQUIT, &IgnoreAction, &SavedSigQuitHandler) == -1) {
                Printf("Failed to ignore SIGQUIT\n");
                (void)sigaction(SIGINT, &SavedSigIntHandler, NULL);
                (void)posix_spawnattr_destroy(&SpawnAttrs);
                return -1;
            }

            (void)sigemptyset(&BlockSet);
            (void)sigaddset(&BlockSet, SIGCHLD);
            if (sigprocmask(SIG_BLOCK, &BlockSet, &PreviousSignalMask) == -1) {
                Printf("Failed to block SIGCHLD\n");
                (void)sigaction(SIGQUIT, &SavedSigQuitHandler, NULL);
                (void)sigaction(SIGINT, &SavedSigIntHandler, NULL);
                (void)posix_spawnattr_destroy(&SpawnAttrs);
                return -1;
            }
        }
        ++RunningThreadCount;
    }

    // Ensure cleanup happens regardless of exit path
    auto CleanupGuard = [](const posix_spawnattr_t& attrs) {
        (void)posix_spawnattr_destroy(const_cast<pid_spawnattr_t*>(&attrs));
    };

    // Configure child process signal behavior
    sigset_t DefaultSignals;
    (void)sigemptyset(&DefaultSignals);
    (void)sigaddset(&DefaultSignals, SIGQUIT);
    (void)sigaddset(&DefaultSignals, SIGINT);
    (void)posix_spawnattr_setsigdefault(&SpawnAttrs, &DefaultSignals);

    // Restore original signal mask in child
    (void)posix_spawnattr_setsigmask(&SpawnAttrs, &PreviousSignalMask);

    const short Flags = POSIX_SPAWN_SETSIGDEF | POSIX_SPAWN_SETSIGMASK;
    (void)posix_spawnattr_setflags(&SpawnAttrs, Flags);

    pid_t ChildPid;
    char **EnvVars = environ;
    const char *CmdCStr = CmdLine.c_str();
    const char *Args[] = {"sh", "-c", CmdCStr, nullptr};
    int ErrCode = 0, ExitStatus = 0;

    ErrCode = posix_spawn(&ChildPid, "/bin/sh", nullptr, &SpawnAttrs,
                          const_cast<char* const*>(Args), EnvVars);

    CleanupGuard(SpawnAttrs);

    if (!ErrCode) {
        pid_t WaitResult = ChildPid;
        do {
            WaitResult = waitpid(ChildPid, &ExitStatus, 0);
        } while (WaitResult == -1 && errno == EINTR);

        if (WaitResult == -1)
            ExitStatus = -1;
    } else if (ErrCode == ENOMEM || ErrCode == EAGAIN) {
        ExitStatus = -1;
    } else {
        ExitStatus = W_EXITCODE(127, 0);
    }

    // Restore signal handlers when last thread exits
    {
        std::lock_guard<std::mutex> Guard(SignalControlMutex);
        --RunningThreadCount;
        if (RunningThreadCount == 0) {
            bool RestoreError = false;
            if (sigaction(SIGINT, &SavedSigIntHandler, nullptr) == -1) {
                Printf("Failed to restore SIGINT handler\n");
                RestoreError = true;
            }
            if (sigaction(SIGQUIT, &SavedSigQuitHandler, nullptr) == -1) {
                Printf("Failed to restore SIGQUIT handler\n");
                RestoreError = true;
            }
            if (sigprocmask(SIG_BLOCK, &PreviousSignalMask, nullptr) == -1) {
                Printf("Failed to unblock SIGCHLD\n");
                RestoreError = true;
            }
            if (RestoreError)
                ExitStatus = -1;
        }
    }

    return ExitStatus;
}

} // namespace fuzzer
#endif // LIBFUZZER_APPLE

