#include "wf_coal_policy.hpp"
#include "util.hpp"

namespace rocshmem {

/**
 * TODO: Evaluate the balance between instruction count, LDS usage,
 * and coalescing efficiency.
 */
/**
 * Overview of the current approach:
 *   1) The method is lightweight—no shared memory (LDS) is used, and it avoids
 *      multi-round tree reductions that could overlook certain patterns.
 *   2) It detects several independent sets of coalescable threads within a wavefront.
 *      Example:
 *          Threads 0 through 8 form one group.
 *          Threads 10 through 63 form another group.
 *      This yields three distinct messages:
 *      +-----------------------+----------+-------------------------+
 *      | Thread_0 ... Thread_8 | Thread_9 | Thread_10 ... Thread_63 |
 *      +-----------------------+----------+-------------------------+
 *      |         msg_A         |  msg_B   |         msg_C           |
 *      +-----------------------+----------+-------------------------+
 *      Coalescing only applies to consecutive thread IDs; gaps break the chain.
 *      For instance, if Thread_0 and Thread_2 are individually coalescable but
 *      Thread_1 is not (per coalescability rules), then none of the three can be merged.
 *   3) Some opportunities are missed when adjacent threads have compatible addresses
 *      but differing message sizes.
 */
__device__ bool WfCoalOn::coalesce(int target_pe, const void *src_ptr, const void *dst_ptr,
                                   size_t *msg_size) {
  const uint64_t src_addr = reinterpret_cast<uint64_t>(src_ptr);
  const uint64_t dst_addr = reinterpret_cast<uint64_t>(dst_ptr);

  /**
   * Decompose 64-bit pointers into two 32-bit halves for shuffle operations.
   * Hardware shuffles operate on 32-bit registers only.
   */
  uint32_t src_lo = static_cast<uint32_t>(src_addr & 0xFFFFFFFF);
  uint32_t src_hi = static_cast<uint32_t>((src_addr >> 32) & 0xFFFFFFFF);
  uint32_t dst_lo = static_cast<uint32_t>(dst_addr & 0xFFFFFFFF);
  uint32_t dst_hi = static_cast<uint32_t>((dst_addr >> 32) & 0xFFFFFFFF);

  /**
   * Propagate packet metadata upward across neighboring lanes.
   * +-------------------------------------------------------------+
   * | Lane_0 Lane_1 ... Lane_62 Lane_63                           |
   * +-------------------------------------------------------------+
   * | Upward propagation <--------------------> Downward direction |
   * +-------------------------------------------------------------+
   *
   * Implementation derived from HIP headers (e.g., device_functions.h in ROCm 2.10).
   */
  uint64_t neighbor_src_lo = __shfl_up(src_lo, 1);
  uint64_t neighbor_src_hi = __shfl_up(src_hi, 1);
  uint64_t neighbor_dst_lo = __shfl_up(dst_lo, 1);
  uint64_t neighbor_dst_hi = __shfl_up(dst_hi, 1);
  int neighbor_pe = __shfl_up(target_pe, 1);
  size_t neighbor_msg_size = __shfl_up(static_cast<unsigned int>(*msg_size), 1);

  /**
   * Reassemble 64-bit values received from the lane below.
   */
  uint64_t neighbor_src = (neighbor_src_hi << 32) | neighbor_src_lo;
  uint64_t neighbor_dst = (neighbor_dst_hi << 32) | neighbor_dst_lo;

  /**
   * Determine active threads in this wavefront using ballot.
   * Each participating thread contributes a '1' at its lane index.
   */
  uint64_t active_mask = __ballot(1);

  /**
   * Compute wavefront ID by flattening the block and applying modulo wavefront width.
   */
  int wave_id = get_flat_block_id() % WF_SIZE;

  /**
   * If 'mergeable' is true, this thread does NOT need to transmit a message;
   * instead, its request is folded into a larger packet sent by a lower-indexed thread.
   *
   * Otherwise, this thread must issue its own message because it cannot merge with
   * the immediately preceding lane.
   */
  bool mergeable =
      (active_mask & (1LL << (wave_id - 1))) &&       // Preceding lane must be active
      (neighbor_msg_size == *msg_size) &&             // Same payload size
      ((neighbor_src + *msg_size) == src_addr) &&     // Contiguous source range
      ((neighbor_dst + *msg_size) == dst_addr) &&     // Contiguous destination range
      (target_pe == neighbor_pe) &&                   // Same target PE
      (wave_id != 0);                                 // Lane 0 never merges downward

  /**
   * Broadcast each lane's merge status to all active threads via ballot.
   * Inactive lanes contribute zeros to the mask.
   */
  uint64_t neighbor_merge_status = __ballot(mergeable);

  /**
   * Only non-mergeable lanes initiate outgoing messages.
   * They compute how many subsequent lanes can be bundled together.
   *
   * Count contiguous '1's above the current lane in neighbor_merge_status.
   * These represent higher-numbered lanes willing to merge with their predecessors.
   */
  if (!mergeable) {
    size_t bundle_size = *msg_size;

    /**
     * Discard bits corresponding to lanes at or below current lane index.
     */
    neighbor_merge_status >>= (wave_id + 1);

    /**
     * Find first zero bit after inversion—marks end of mergeable segment.
     * __ffsll returns position of least significant set bit (1-based).
     */
    unsigned int num_bundled = __ffsll(static_cast<unsigned long long>(~neighbor_merge_status));

    if (num_bundled > 0) {
      bundle_size += *msg_size * (num_bundled - 1);
    }

    *msg_size = bundle_size;
  }

  return !mergeable;
}

