    d >> mTarget;
    d >> mFactor;
    if (d.rev > 1)
        d >> mAdditionalTargets;
    if (d.rev > 2) {
        d >> mAutoWeighting;
        d >> mMinHeight >> mMaxHeight;
    }
END_LOADS

void CharIKScale::PollDeps(
    std::list<Hmx::Object *> &changedBy, std::list<Hmx::Object *> &change
) {
    change.push_back(mTarget);
    for (ObjPtrList<RndTransformable>::iterator it = mAdditionalTargets.begin();
         it != mAdditionalTargets.end();
         ++it) {
        change.push_back(*it);
    }
    changedBy.push_back(mTarget);
}

void CharIKScale::CaptureBefore() {
    if (mTarget)
        mFactor = mTarget->LocalXfm().v.z;
}

void CharIKScale::CaptureAfter() {
    if (mTarget)
        mFactor = mTarget->LocalXfm().v.z / mFactor;
}

