void SaberCheckerAPI::init() {
  std::set<CHECKER_TYPE> seen_types;
  CHECKER_TYPE last_type = CK_DUMMY;
  seen_types.insert(CK_DUMMY);

  for (const func_entry *entry = func_entries; entry->name; ++entry) {
    if (entry->type != last_type) {
      if (seen_types.count(entry->type)) {
        fputs(entry->name, stderr);
        putc('\n', stderr);
        assert(!"func_entries not grouped by type");
      }
      seen_types.insert(entry->type);
      last_type = entry->type;
    }

    if (tdAPIMap.count(entry->name)) {
      fputs(entry->name, stderr);
      putc('\n', stderr);
      assert(!"duplicate function name in func_entries");
    }

    tdAPIMap[entry->name] = entry->type;
  }
}

