#include <iostream>
#include <vector>
#include <stack>
#include <unordered_map>
using namespace std;

// LeetCode 496: Next Greater Element I - Modified version
class Solution {
public:
    vector<int> nextGreaterElement(vector<int>& findNums, vector<int>& allNums) {
        vector<int> result;
        stack<int> stk;  
        unordered_map<int, int> greaterMap;  // maps each number to its next greater element

        // Traverse allNums from right to left
        for (int idx = allNums.size() - 1; idx >= 0; idx--) {
            // Ensure stack maintains elements in decreasing order
            while (!stk.empty() && stk.top() <= allNums[idx]) {
                stk.pop();
            }

            // Determine next greater element for current value
            greaterMap[allNums[idx]] = stk.empty() ? -1 : stk.top();

            // Add current element to the stack
            stk.push(allNums[idx]);
        }

        // Construct the final answer using the map
        for (int val : findNums) {
            result.push_back(greaterMap[val]);
        }

        return result;
    }
};

