FileHeader::FileHeader()
{
    lastFile = nullptr;
    m_saveVersion = 0;
    // Original saves should retain their initial version number; this will be updated upon loading
    m_originalSaveVersion = SAVE_FILE_VERSION_NUMBER;
    m_savePlatform = SAVE_FILE_PLATFORM_LOCAL;
    m_saveEndian = m_localEndian;
}

FileHeader::~FileHeader()
{
    for (size_t idx = 0; idx < fileTable.size(); ++idx)
    {
        delete fileTable[idx];
    }
}

FileEntry* FileHeader::AddFile(const wstring& name, unsigned int length /* = 0 */)
{
    assert(name.length() < 64);

    wchar_t buffer[64];
    ZeroMemory(buffer, sizeof(wchar_t) * 64);
    size_t copyLen = min(sizeof(wchar_t) * 64, sizeof(wchar_t) * name.length());
    memcpy(buffer, name.c_str(), copyLen);

    // Check if file already exists in table
    for (size_t i = 0; i < fileTable.size(); ++i)
    {
        if (wcscmp(fileTable[i]->data.filename, buffer) == 0)
        {
            return fileTable[i];
        }
    }

    // Add new entry to table
    FileEntry* newEntry = new FileEntry(buffer, length, GetStartOfNextData());
    fileTable.push_back(newEntry);
    lastFile = newEntry;
    return lastFile;
}

void FileHeader::RemoveFile(FileEntry* file)
{
    if (!file) return;

    AdjustStartOffsets(file, file->getFileSize(), true);
    auto iter = std::find(fileTable.begin(), fileTable.end(), file);
    if (iter != fileTable.end())
    {
        fileTable.erase(iter);
    }

#ifndef _CONTENT_PACKAGE
    wprintf(L"Removed file %ls\n", file->data.filename);
#endif

    delete file;
}

void FileHeader::WriteHeader(LPVOID saveMem)
{
    unsigned int headerOffset = GetStartOfNextData();
    unsigned int headerSize = static_cast<unsigned int>(fileTable.size());

    int* basePtr = reinterpret_cast<int*>(saveMem);
#ifdef __PSVITA__
    VirtualCopyTo(basePtr, &headerOffset, sizeof(headerOffset));
#else
    *basePtr = headerOffset;
#endif

#ifdef __PSVITA__
    VirtualCopyTo(basePtr + 1, &headerSize, sizeof(headerSize));
#else
    *(basePtr + 1) = headerSize;
#endif

    short* versionPtr = reinterpret_cast<short*>(basePtr + 2);

#ifdef __PSVITA__
    VirtualCopyTo(versionPtr, &m_originalSaveVersion, sizeof(m_originalSaveVersion));
#else
    *versionPtr = m_originalSaveVersion;
#endif

    short currentVersion = SAVE_FILE_VERSION_NUMBER;

#ifdef __PSVITA__
    VirtualCopyTo(versionPtr + 1, &currentVersion, sizeof(currentVersion));
#else
    *(versionPtr + 1) = currentVersion;
#endif

#ifdef _DEBUG_FILE_HEADER
    app.DebugPrintf("Write save file with original version: %d, and current version %d\n", m_originalSaveVersion, currentVersion);
#endif

    char* writePos = reinterpret_cast<char*>(saveMem) + headerOffset;

#ifdef _DEBUG_FILE_HEADER
    app.DebugPrintf("\n\nWrite file Header: Offset = %d, Size = %d\n", headerOffset, headerSize);
#endif

    for (size_t i = 0; i < fileTable.size(); ++i)
    {
#ifdef __PSVITA__
        VirtualCopyTo(reinterpret_cast<void*>(writePos), &fileTable[i]->data, sizeof(FileEntrySaveData));
#else
        memcpy(reinterpret_cast<void*>(writePos), &fileTable[i]->data, sizeof(FileEntrySaveData));
#endif
        writePos += sizeof(FileEntrySaveData);
    }
}

void FileHeader::ReadHeader(LPVOID saveMem, ESavePlatform plat /*= SAVE_FILE_PLATFORM_LOCAL*/)
{
    unsigned int headerOffset;
    unsigned int headerSize;
    m_savePlatform = plat;

    switch (m_savePlatform)
    {
    case SAVE_FILE_PLATFORM_X360:
    case SAVE_FILE_PLATFORM_PS3:
        m_saveEndian = BIGENDIAN;
        break;
    case SAVE_FILE_PLATFORM_XBONE:
    case SAVE_FILE_PLATFORM_WIN64:
    case SAVE_FILE_PLATFORM_PS4:
    case SAVE_FILE_PLATFORM_PSVITA:
        m_saveEndian = LITTLEENDIAN;
        break;
    default:
        assert(0);
        m_savePlatform = SAVE_FILE_PLATFORM_LOCAL;
        m_saveEndian = m_localEndian;
        break;
    }

    int* basePtr = reinterpret_cast<int*>(saveMem);

#ifdef __PSVITA__
    VirtualCopyFrom(&headerOffset, basePtr, sizeof(headerOffset));
#else
    headerOffset = *basePtr;
#endif
    if (isSaveEndianDifferent()) System::ReverseULONG(&headerOffset);

#ifdef __PSVITA__
    VirtualCopyFrom(&headerSize, basePtr + 1, sizeof(headerSize));
#else
    headerSize = *(basePtr + 1);
#endif
    if (isSaveEndianDifferent()) System::ReverseULONG(&headerSize);

    short* versionPtr = reinterpret_cast<short*>(basePtr + 2);

#ifdef __PSVITA__
    VirtualCopyFrom(&m_originalSaveVersion, versionPtr, sizeof(m_originalSaveVersion));
#else
    m_originalSaveVersion = *versionPtr;
#endif
    if (isSaveEndianDifferent()) System::ReverseSHORT(&m_originalSaveVersion);

#ifdef __PSVITA__
    VirtualCopyFrom(&m_saveVersion, versionPtr + 1, sizeof(m_saveVersion));
#else
    m_saveVersion = *(versionPtr + 1);
#endif
    if (isSaveEndianDifferent()) System::ReverseSHORT(&m_saveVersion);

#ifdef _DEBUG_FILE_HEADER
    app.DebugPrintf("Read save file with original version: %d, and current version %d\n", m_originalSaveVersion, m_saveVersion);
    app.DebugPrintf("\n\nRead file Header: Offset = %d, Size = %d\n", headerOffset, headerSize);
#endif

    char* readPos = reinterpret_cast<char*>(saveMem) + headerOffset;

    switch (m_saveVersion)
    {
    case SAVE_FILE_VERSION_CHUNK_INHABITED_TIME:
    case SAVE_FILE_VERSION_COMPRESSED_CHUNK_STORAGE:
    case SAVE_FILE_VERSION_DURANGO_CHANGE_MAP_DATA_MAPPING_SIZE:
    case SAVE_FILE_VERSION_CHANGE_MAP_DATA_MAPPING_SIZE:
    case SAVE_FILE_VERSION_MOVED_STRONGHOLD:
    case SAVE_FILE_VERSION_NEW_END:
    case SAVE_FILE_VERSION_POST_LAUNCH:
    case SAVE_FILE_VERSION_LAUNCH:
        {
            FileEntrySaveData* currentEntry = reinterpret_cast<FileEntrySaveData*>(readPos);
            for (unsigned int i = 0; i < headerSize; ++i)
            {
                FileEntry* entry = new FileEntry();

#ifdef __PSVITA__
                VirtualCopyFrom(&entry->data, currentEntry, sizeof(FileEntrySaveData));
#else
                memcpy(&entry->data, currentEntry, sizeof(FileEntrySaveData));
#endif

                if (isSaveEndianDifferent())
                {
                    System::ReverseWCHARA(entry->data.filename, 64);
                    System::ReverseULONG(&entry->data.length);
                    System::ReverseULONG(&entry->data.startOffset);
                    System::ReverseULONGLONG(&entry->data.lastModifiedTime);
                }

                entry->currentFilePointer = entry->data.startOffset;
                lastFile = entry;
                fileTable.push_back(entry);

#ifdef _DEBUG_FILE_HEADER
                app.DebugPrintf("File: %ls, Start = %d, Length = %d, End = %d, Timestamp = %lld\n",
                    entry->data.filename,
                    entry->data.startOffset,
                    entry->data.length,
                    entry->data.startOffset + entry->data.length,
                    entry->data.lastModifiedTime);
#endif
                ++currentEntry;
            }
        }
        break;

    case SAVE_FILE_VERSION_PRE_LAUNCH:
        {
            unsigned int count = 0;
            while (count < headerSize)
            {
                FileEntry* entry = new FileEntry();

#ifdef __PSVITA__
                VirtualCopyFrom(&entry->data, readPos, sizeof(FileEntrySaveDataV1));
#else
                memcpy(&entry->data, readPos, sizeof(FileEntrySaveDataV1));
#endif
                entry->currentFilePointer = entry->data.startOffset;
                lastFile = entry;
                fileTable.push_back(entry);

#ifdef _DEBUG_FILE_HEADER
                app.DebugPrintf("File: %ls, Start = %d, Length = %d, End = %d\n",
                    entry->data.filename,
                    entry->data.startOffset,
                    entry->data.length,
                    entry->data.startOffset + entry->data.length);
#endif

                count += sizeof(FileEntrySaveDataV1);
                readPos += sizeof(FileEntrySaveDataV1);
            }
        }
        break;

    default:
#ifndef _CONTENT_PACKAGE
        app.DebugPrintf("**********  Invalid save version %d\n", m_saveVersion);
        __debugbreak();
#endif
        break;
    }
}

unsigned int FileHeader::GetStartOfNextData()
{
    unsigned int totalBytes = SAVE_FILE_HEADER_SIZE;
    for (size_t i = 0; i < fileTable.size(); ++i)
    {
        if (fileTable[i]->getFileSize() > 0)
        {
            totalBytes += fileTable[i]->getFileSize();
        }
    }
    return totalBytes;
}

unsigned int FileHeader::GetFileSize()
{
    return GetStartOfNextData() + (sizeof(FileEntrySaveData) * static_cast<unsigned int>(fileTable.size()));
}

void FileHeader::AdjustStartOffsets(FileEntry* file, DWORD offsetChange, bool subtract /*= false*/)
{
    bool found = false;
    for (size_t i = 0; i < fileTable.size(); ++i)
    {
        if (found)
        {
            if (subtract)
            {
                fileTable[i]->data.startOffset -= offsetChange;
                fileTable[i]->currentFilePointer -= offsetChange;
            }
            else
            {
                fileTable[i]->data.startOffset += offsetChange;
                fileTable[i]->currentFilePointer += offsetChange;
            }
        }
        else if (fileTable[i] == file)
        {
            found = true;
        }
    }
}

bool FileHeader::fileExists(const wstring& name)
{
    for (size_t i = 0; i < fileTable.size(); ++i)
    {
        if (wcscmp(fileTable[i]->data.filename, name.c_str()) == 0)
        {
            return true;
        }
    }
    return false;
}

std::vector<FileEntry*>* FileHeader::getFilesWithPrefix(const wstring& prefix)
{
    std::vector<FileEntry*>* result = nullptr;
    for (size_t i = 0; i < fileTable.size(); ++i)
