namespace hydra::horizon::filesystem {
void IFile::Save(std::string_view destination_path) const {
    // Open output file for writing in binary mode
    std::fstream output_file(
        std::string(destination_path),
        std::ios::out | std::ios::binary); // Temporary string construction

    io::IostreamStream writer_stream(output_file);

    // Open source stream for reading
    auto source_stream =
        const_cast<IFile*>(this)->Open(FileOpenFlags::Read); // Cast away constness

    std::array<u8, 0x400> temp_buffer;
    while (source_stream->GetSeek() < source_stream->GetSize()) {
        const auto remaining_bytes = source_stream->GetSize() - source_stream->GetSeek();
        const auto bytes_to_read = std::min(static_cast<u64>(temp_buffer.size()), remaining_bytes);

        std::span<u8> read_span(temp_buffer.data(), temp_buffer.data() + bytes_to_read);
        source_stream->ReadToSpan(read_span);

        writer_stream.WriteSpan(std::span<const u8>(read_span));
    }

    delete source_stream;
}
} // namespace hydra::horizon::filesystem

