#include "valdi/runtime/JavaScript/JavaScriptHeapDumpBuilder.hpp"
#include "valdi_core/cpp/Utils/Format.hpp"
#include "valdi_core/cpp/Utils/StringCache.hpp"
#include <benchmark/benchmark.h>

using namespace Valdi;

struct PerformanceTestHelper {
    std::vector<StringBox> objectNames;
    std::vector<StringBox> fieldNames;

    PerformanceTestHelper() {
        for (size_t idx = 0; idx < 25; ++idx) {
            objectNames.emplace_back(STRING_FORMAT("TestClass{}", idx));
        }
        for (size_t idx = 0; idx < 800; ++idx) {
            fieldNames.emplace_back(STRING_FORMAT("field{}", idx));
        }
    }

    void fillHeapDumpBuilder(JavaScriptHeapDumpBuilder& builder) {
        constexpr size_t totalNodes = 75000;
        constexpr size_t connectionsPerNode = 4;

        for (size_t nodeIndex = 0; nodeIndex < totalNodes; ++nodeIndex) {
            auto nodeKind =
                static_cast<JavaScriptHeapDumpNodeType>(nodeIndex % static_cast<size_t>(JavaScriptHeapDumpNodeType::COUNT));

            builder.beginNode(nodeKind, objectNames[nodeIndex % objectNames.size()], 
                             static_cast<uint64_t>(nodeIndex), 128);

            for (size_t targetIndex = nodeIndex + 1; 
                 targetIndex < totalNodes && targetIndex - nodeIndex < connectionsPerNode; 
                 ++targetIndex) {

                builder.appendEdge(JavaScriptHeapDumpEdgeType::PROPERTY,
                                   JavaScriptHeapEdgeIdentifier::named(fieldNames[targetIndex % fieldNames.size()]),
                                   static_cast<uint64_t>(targetIndex));
            }
        }
    }
};

static void ConstructHeapSnapshot(benchmark::State& state) {
    PerformanceTestHelper testHelper;
    for (auto _ : state) {
        JavaScriptHeapDumpBuilder snapshotBuilder;
        testHelper.fillHeapDumpBuilder(snapshotBuilder);
        benchmark::DoNotOptimize(snapshotBuilder.build());
    }
}
BENCHMARK(ConstructHeapSnapshot);

static void DecodeHeapSnapshot(benchmark::State& state) {
    PerformanceTestHelper testHelper;
    JavaScriptHeapDumpBuilder snapshotBuilder;
    testHelper.fillHeapDumpBuilder(snapshotBuilder);
    auto snapshotData = snapshotBuilder.build();

    for (auto _ : state) {
        SimpleExceptionTracker errorTracker;
        JavaScriptHeapDumpParser parser(snapshotData.data(), snapshotData.size(), errorTracker);

        for (const auto& record : parser.getNodes()) {
            for (const auto& link : record.getEdges()) {
                benchmark::DoNotOptimize(link.getIdentifier());
            }
        }
    }
}
BENCHMARK(DecodeHeapSnapshot);

static void CombineHeapSnapshots(benchmark::State& state) {
    PerformanceTestHelper testHelper;
    JavaScriptHeapDumpBuilder initialBuilder;
    testHelper.fillHeapDumpBuilder(initialBuilder);
    auto baseSnapshot = initialBuilder.build();

    for (auto _ : state) {
        JavaScriptHeapDumpBuilder mergedBuilder;
        SimpleExceptionTracker errorTracker;

        mergedBuilder.appendDump(baseSnapshot.data(), baseSnapshot.size(), errorTracker);
        mergedBuilder.appendDump(baseSnapshot.data(), baseSnapshot.size(), errorTracker);
        mergedBuilder.appendDump(baseSnapshot.data(), baseSnapshot.size(), errorTracker);
        mergedBuilder.appendDump(baseSnapshot.data(), baseSnapshot.size(), errorTracker);

        benchmark::DoNotOptimize(mergedBuilder.build());
    }
}
BENCHMARK(CombineHeapSnapshots);

BENCHMARK_MAIN();

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int R, H;
    cin >> R >> H; // R=75, H=1 in the official test, but we read anyway.

    // Moduli for the tests. Their sum is 30.
    vector<int> divisors = {13, 7, 5, 3, 2};

    // Send all robots at once.
    for (int d : divisors) {
        for (int rem = 0; rem < d; ++rem) {
            // Gather all positions p such that p % d == rem
            vector<int> indices;
            for (int pos = 1; pos <= 1000; ++pos) {
                if (pos % d == rem) {
                    indices.push_back(pos);
                }
            }

            // Output the query for this robot.
            cout << "? " << indices.size();
            for (int idx : indices) {
                cout << " " << idx;
            }
            cout << endl;
            cout.flush();
        }
    }

    // Wait for the results.
    cout << "@" << endl;
    cout.flush();

    int numResponses;
    cin >> numResponses;
    vector<int> answers(numResponses);
    for (int i = 0; i < numResponses; ++i) {
        cin >> answers[i];
    }

    // Decode: split responses according to the moduli.
    vector<vector<int>> valid_residues(divisors.size()); // residues with answer 1 for each modulus
    int counter = 0;
    for (int i = 0; i < divisors.size(); ++i) {
        int d = divisors[i];
        for (int rem = 0; rem < d; ++rem) {
            if (answers[counter + rem] == 1) {
                valid_residues[i].push_back(rem);
            }
        }
        counter += d;
    }

    // Precompute residues for all numbers 1..1000 for each modulus.
    vector<vector<int>> residue_table(1001, vector<int>(divisors.size()));
    for (int val = 1; val <= 1000; ++val) {
        for (int i = 0; i < divisors.size(); ++i) {
            residue_table[val][i] = val % divisors[i];
        }
    }

    // Brute-force search over all unordered pairs (x,y), x <= y.
    int first_num = -1, second_num = -1;
    for (int x = 1; x <= 1000; ++x) {
        for (int y = x; y <= 1000; ++y) {
            bool match = true;
            for (int mi = 0; mi < divisors.size(); ++mi) {
                int d = divisors[mi];
                int rx = residue_table[x][mi];
                int ry = residue_table[y][mi];

                // Check that for every residue r, (rx==r or ry==r) equals whether r is in valid_residues[mi].
                for (int r = 0; r < d; ++r) {
                    bool covered = (rx == r) || (ry == r);
                    bool expected = false;
                    for (int rr : valid_residues[mi]) {
                        if (rr == r) {
                            expected = true;
                            break;
                        }
                    }
                    if (covered != expected) {
                        match = false;
                        break;
                    }
                }
                if (!match) break;
            }
            if (match) {
                first_num = x;
                second_num = y;
                break;
            }
        }
        if (first_num != -1) break;
    }

    // Output the answer.
    cout << "! " << first_num << " " << second_num << endl;
    cout.flush();
    return 0;
}

