#include "Proton.h"
#include "Driver/GPU/CudaApi.h"
#include <map>
#include <stdexcept>
#include "pybind11/pybind11.h"
#include "pybind11/stl.h"
#include "pybind11/stl_bind.h"

using namespace proton;

void setupProtonBindings(pybind11::module &&module) {
  using policy = pybind11::return_value_policy;
  using namespace pybind11::literals;

  // Start a new session with given parameters
  module.def("start",
             [](const std::string &configPath, const std::string &contextName,
                const std::string &datasetName, const std::string &profilerType) {
               auto id = SessionManager::instance().addSession(
                   configPath, profilerType, contextName, datasetName);
               SessionManager::instance().activateSession(id);
               return id;
             });

  // Activate an existing session by ID
  module.def("activate", [](size_t id) {
    SessionManager::instance().activateSession(id);
  });

  // Deactivate a session by ID
  module.def("deactivate", [](size_t id) {
    SessionManager::instance().deactivateSession(id);
  });

  // Finalize a specific session with output format
  module.def("finalize", [](size_t id, const std::string &format) {
    auto fmtEnum = parseOutputFormat(format);
    SessionManager::instance().finalizeSession(id, fmtEnum);
  });

  // Finalize all active sessions
  module.def("finalize_all", [](const std::string &format) {
    auto fmtEnum = parseOutputFormat(format);
    SessionManager::instance().finalizeAllSessions(fmtEnum);
  });

  // Generate a new scope identifier
  module.def("record_scope", []() { return Scope::getNewScopeId(); });

  // Enter a named scope
  module.def("enter_scope", [](size_t id, const std::string &label) {
    SessionManager::instance().enterScope(Scope(id, label));
  });

  // Exit a named scope
  module.def("exit_scope", [](size_t id, const std::string &label) {
    SessionManager::instance().exitScope(Scope(id, label));
  });

  // Enter an operation scope
  module.def("enter_op", [](size_t id, const std::string &label) {
    SessionManager::instance().enterOp(Scope(id, label));
  });

  // Exit an operation scope
  module.def("exit_op", [](size_t id, const std::string &label) {
    SessionManager::instance().exitOp(Scope(id, label));
  });

  // Add metrics to a scope (aggregable)
  module.def("add_metrics",
             [](size_t id,
                const std::map<std::string, MetricValueType> &values) {
               SessionManager::instance().addMetrics(id, values,
                                                     /*aggregable=*/true);
             });

  // Set properties for a scope (non-aggregable)
  module.def("set_properties",
             [](size_t id,
                const std::map<std::string, MetricValueType> &values) {
               SessionManager::instance().addMetrics(id, values,
                                                     /*aggregable=*/false);
             });

  // Bind the metric map type for Python
  pybind11::bind_map<std::map<std::string, MetricValueType>>(module, "MetricMap");
}

// Module initialization entry point
PYBIND11_MODULE(libproton, m) {
  m.doc() = "Python interface for the Proton performance profiling library";
  setupProtonBindings(std::move(m.def_submodule("proton")));
}

