// Enable Iggy rendering support
#define _ENABLEIGGY

ConsoleUIController ui;

void ConsoleUIController::init(
    ID3D11Device*           device,
    ID3D11DeviceContext*    context,
    ID3D11RenderTargetView* renderTargetView,
    ID3D11DepthStencilView* depthStencilView,
    S32                     width,
    S32                     height
) {
#ifdef _ENABLEIGGY
    m_pRenderTargetView = renderTargetView;
    m_pDepthStencilView = depthStencilView;

    // Common initialization steps
    preInit(width, height);

    gdraw_funcs = gdraw_D3D11_CreateContext(device, context, width, height);
    if (!gdraw_funcs) {
        app.DebugPrintf("Failed to initialize GDraw!\n");
#ifndef _CONTENT_PACKAGE
        __debugbreak();
#endif
        app.FatalLoadError();
    }

    /* Configure resource caches for GDraw. Each type specifies:
       - Max number of handles (objects)
       - Max memory budget (in bytes)
       Note: For D3D, these are hints; actual memory is managed by D3D. */
    gdraw_D3D11_SetResourceLimits(
        GDRAW_D3D11_RESOURCE_vertexbuffer,
        5000,
        16 * 1024 * 1024
    );
    gdraw_D3D11_SetResourceLimits(
        GDRAW_D3D11_RESOURCE_texture,
        5000,
        128 * 1024 * 1024
    );
    gdraw_D3D11_SetResourceLimits(
        GDRAW_D3D11_RESOURCE_rendertarget,
        10,
        32 * 1024 * 1024
    );

    // Connect GDraw to Iggy
    IggySetGDraw(gdraw_funcs);

    // Use DirectSound for audio output
    IggyAudioUseDirectSound();

    // Finalize shared setup
    postInit();
#endif
}

void ConsoleUIController::render() {
#ifdef _ENABLEIGGY
    // Set up render target and depth buffer for GDraw
    gdraw_D3D11_SetTileOrigin(
        m_pRenderTargetView,
        m_pDepthStencilView,
        NULL,
        0,
        0
    );

    renderScenes();

    // Signal end of frame rendering
    gdraw_D3D11_NoMoreGDrawThisFrame();
#endif
}

void ConsoleUIController::beginIggyCustomDraw4J(
    IggyCustomDrawCallbackRegion* region,
    CustomDrawData*               customDrawData
) {
    PIXBeginNamedEvent(0, "Starting Iggy custom draw\n");
    PIXBeginNamedEvent(0, "Gdraw setup");

    // Retrieve world transform and configure rendering state
    gdraw_D3D11_BeginCustomDraw_4J(region, customDrawData->mat);

    PIXEndNamedEvent();
}

CustomDrawData* ConsoleUIController::setupCustomDraw(
    UIScene*                      scene,
    IggyCustomDrawCallbackRegion* region
) {
    CustomDrawData* customDrawData = new CustomDrawData();
    customDrawData->x0             = region->x0;
    customDrawData->x1             = region->x1;
    customDrawData->y0             = region->y0;
    customDrawData->y1             = region->y1;

    PIXBeginNamedEvent(0, "Starting Iggy custom draw\n");
    gdraw_D3D11_BeginCustomDraw_4J(region, customDrawData->mat);
    setupCustomDrawGameStateAndMatrices(scene, customDrawData);
    return customDrawData;
}

CustomDrawData*
ConsoleUIController::calculateCustomDraw(IggyCustomDrawCallbackRegion* region) {
    CustomDrawData* customDrawData = new CustomDrawData();
    customDrawData->x0             = region->x0;
    customDrawData->x1             = region->x1;
    customDrawData->y0             = region->y0;
    customDrawData->y1             = region->y1;

    gdraw_D3D11_CalculateCustomDraw_4J(region, customDrawData->mat);
    return customDrawData;
}

void ConsoleUIController::endCustomDraw(IggyCustomDrawCallbackRegion* region) {
    endCustomDrawGameStateAndMatrices();
    gdraw_D3D11_EndCustomDraw(region);
    PIXEndNamedEvent();
}

void ConsoleUIController::setTileOrigin(S32 xOffset, S32 yOffset) {
    gdraw_D3D11_SetTileOrigin(
        m_pRenderTargetView,
        m_pDepthStencilView,
        NULL,
        xOffset,
        yOffset
    );
}

GDrawTexture* ConsoleUIController::getSubstitutionTexture(int textureId) {
    // Wrap an existing D3D texture for use by Iggy/GDraw
    ID3D11ShaderResourceView* texSRV = RenderManager.TextureGetTexture(textureId);
    ID3D11Resource*           resource;
    texSRV->GetResource(&resource);
    ID3D11Texture2D*          tex2D = static_cast<ID3D11Texture2D*>(resource);
    D3D11_TEXTURE2D_DESC      desc;
    tex2D->GetDesc(&desc);

    GDrawTexture* gdrawTex = gdraw_D3D11_WrappedTextureCreate(texSRV);
    return gdrawTex;
}

void ConsoleUIController::destroySubstitutionTexture(
    void*         userData,
    GDrawTexture* handle
) {
    // Release GDraw wrapper; underlying D3D texture remains owned by app
    gdraw_D3D11_WrappedTextureDestroy(handle);
}

void ConsoleUIController::shutdown() {
#ifdef _ENABLEIGGY
    // Clean up GDraw resources — must be called after all Iggy players destroyed
    gdraw_D3D11_DestroyContext();
#endif
}

