#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int black_needed, white_needed, temp1, temp2;
    if (!(cin >> black_needed >> white_needed >> temp1 >> temp2)) return 0;

    const int ROWS = 100, COLS = 100;
    vector<string> grid(ROWS, string(COLS, '#'));

    // Top half black, bottom half white
    for (int row = 0; row < 50; ++row) {
        for (int col = 0; col < COLS; ++col) grid[row][col] = '#';
    }
    for (int row = 50; row < ROWS; ++row) {
        for (int col = 0; col < COLS; ++col) grid[row][col] = '.';
    }

    // Add white cells in black region (avoiding boundary at row 49-50)
    int white_remaining = white_needed - 1;
    for (int r = 0; r <= 48 && white_remaining > 0; r += 2) {
        for (int c = 0; c < COLS && white_remaining > 0; c += 2) {
            grid[r][c] = '.';
            --white_remaining;
        }
    }

    // Add black cells in white region (avoiding boundary at row 49-50)
    int black_remaining = black_needed - 1;
    for (int r = 52; r < ROWS && black_remaining > 0; r += 2) {
        for (int c = 0; c < COLS && black_remaining > 0; c += 2) {
            grid[r][c] = '#';
            --black_remaining;
        }
    }

    cout << ROWS << " " << COLS << "\n";
    for (int i = 0; i < ROWS; ++i) cout << grid[i] << "\n";

    return 0;
}

