namespace {
// Helper to return a static token as a string.  We wrap tokens as Python
// strings and for some reason simply wrapping the token using def_readonly
// bypasses to-Python conversion, leading to the error that there's no
// Python type for the C++ TfToken type.  So we wrap this functor instead.
class _WrapStaticTokenWrapper {
public:
    _WrapStaticTokenWrapper(const TfToken* tokenPtr) : _tokenPtr(tokenPtr) { }
    std::string operator()() const
    {
        return _tokenPtr->GetString();
    }
private:
    const TfToken* _tokenPtr;
};
template <typename U>
void
_AddTokenToClass(U& classObj, const char* propertyName, const TfToken& tokenRef)
{
    classObj.add_static_property(propertyName,
                                 boost::python::make_function(
                                     _WrapStaticTokenWrapper(&tokenRef),
                                     boost::python::return_value_policy<
                                         boost::python::return_by_value>(),
                                     boost::mpl::vector1<std::string>()));
}
} // anonymous
void wrap{{ tokensPrefix }}Tokens()
{
    boost::python::class_<{{ tokensPrefix }}TokensType, boost::noncopyable>
        cls("Tokens", boost::python::no_init);
{% for token in tokens %}
    _AddTokenToClass(cls, "{{ token.id }}", {{ tokensPrefix }}Tokens->{{ token.id }});
{% endfor %}
}

#include "globals-esm.h"
