    auto& block = builder.add_block(root);
    EXPECT_EQ(root.size(), 2);
    EXPECT_EQ(root.at(0).second.size(), 1);

    // Dead CFG Elimination
    analysis::AnalysisManager analysis_manager(builder.subject());
