namespace lbug {
namespace regex {

// ----------------------------------------------------------------------
// CEscapeString()
//    Copies 'src' to 'dest', escaping dangerous characters using
//    C-style escape sequences.  'src' and 'dest' should not overlap.
//    Returns the number of bytes written to 'dest' (not including the \0)
//    or (size_t)-1 if there was insufficient space.
// ----------------------------------------------------------------------
static size_t CEscapeString(const char* source, size_t source_length, char* destination, size_t destination_capacity) {
    const char* source_end = source + source_length;
    size_t written = 0;
    for (; source < source_end; source++) {
        if (destination_capacity - written < 2) // need room for two-character escape
            return (size_t)-1;
        unsigned char ch = *source;
        switch (ch) {
        case '\n':
            destination[written++] = '\\';
            destination[written++] = 'n';
            break;
        case '\r':
            destination[written++] = '\\';
            destination[written++] = 'r';
            break;
        case '\t':
            destination[written++] = '\\';
            destination[written++] = 't';
            break;
        case '\"':
            destination[written++] = '\\';
            destination[written++] = '\"';
            break;
        case '\'':
            destination[written++] = '\\';
            destination[written++] = '\'';
            break;
        case '\\':
            destination[written++] = '\\';
            destination[written++] = '\\';
            break;
        default:
            // Note that if we emit \xNN and the source character after that is a hex
            // digit then that digit must be escaped too to prevent it being
            // interpreted as part of the character code by C.
            if (ch < ' ' || ch > '~') {
                if (destination_capacity - written < 5) // space for four-character escape + \0
                    return (size_t)-1;
                snprintf(destination + written, 5, "\\%03o", ch);
                written += 4;
            } else {
                destination[written++] = ch;
                break;
            }
        }
    }
    if (destination_capacity - written < 1) // ensure there's room for \0
        return (size_t)-1;
    destination[written] = '\0'; // doesn't count towards return value though
    return written;
}

// ----------------------------------------------------------------------
// CEscape()
//    Copies 'src' to result, escaping dangerous characters using
//    C-style escape sequences.  'src' and 'dest' should not overlap.
// ----------------------------------------------------------------------
std::string CEscape(const StringPiece& src) {
    const size_t max_dest_len = src.size() * 4 + 1; // Maximum possible expansion
    char* buffer = new char[max_dest_len];
    const size_t bytes_written = CEscapeString(src.data(), src.size(), buffer, max_dest_len);
    std::string result = std::string(buffer, bytes_written);
    delete[] buffer;
    return result;
}

void PrefixSuccessor(std::string* prefix) {
    // We can increment the last character in the string and be done
    // unless that character is 255, in which case we have to erase the
    // last character and increment the previous character, unless that
    // is 255, etc. If the string is empty or consists entirely of
    // 255's, we just return the empty string.
    while (!prefix->empty()) {
        char& last_char = prefix->back();
        if (last_char == '\xff') { // char literal avoids signed/unsigned.
            prefix->pop_back();
        } else {
            ++last_char;
            break;
        }
    }
}

static void StringAppendV(std::string* output, const char* fmt, va_list args) {
    // First try with a small fixed size buffer
    char local_buffer[1024];
    // It's possible for methods that use a va_list to invalidate
    // the data in it upon use.  The fix is to make a copy
    // of the structure before using it and use that copy instead.
    va_list saved_args;
    va_copy(saved_args, args);
    int status = vsnprintf(local_buffer, sizeof(local_buffer), fmt, saved_args);
    va_end(saved_args);
    if ((status >= 0) && (static_cast<size_t>(status) < sizeof(local_buffer))) {
        // It fit
        output->append(local_buffer, status);
        return;
    }
    // Repeatedly increase buffer size until it fits
    int buffer_size = sizeof(local_buffer);
    while (true) {
        if (status < 0) {
            // Older behavior: just try doubling the buffer size
            buffer_size *= 2;
        } else {
            // We need exactly "status+1" characters
            buffer_size = status + 1;
        }
        char* temp_buffer = new char[buffer_size];
        // Restore the va_list before we use it again
        va_copy(saved_args, args);
        status = vsnprintf(temp_buffer, buffer_size, fmt, saved_args);
        va_end(saved_args);
        if ((status >= 0) && (status < buffer_size)) {
            // It fit
            output->append(temp_buffer, status);
            delete[] temp_buffer;
            return;
        }
        delete[] temp_buffer;
    }
}

std::string StringPrintf(const char* format, ...) {
    va_list ap;
    va_start(ap, format);
    std::string result_string;
    StringAppendV(&result_string, format, ap);
    va_end(ap);
    return result_string;
}

void SStringPrintf(std::string* output, const char* format, ...) {
    va_list ap;
    va_start(ap, format);
    output->clear();
    StringAppendV(output, format, ap);
    va_end(ap);
}

void StringAppendF(std::string* output, const char* format, ...) {
    va_list ap;
    va_start(ap, format);
    StringAppendV(output, format, ap);
    va_end(ap);
}

} // namespace regex
