namespace Gorgon::Utils {

    void CrashHandler::Backtrace() {
        void **buffer = (void**)malloc((maxDepth + offset + 2) * sizeof(void*));
        int count = backtrace(buffer, maxDepth + offset + 2);

        char **symbols = (char **)NULL;
        symbols = backtrace_symbols(buffer, count);
        auto term = StdConsole();

        auto printFrame = [&](int idx) {
            std::string entry = symbols[idx];
            auto openParen = entry.find_first_of('(');
            auto closeParen = entry.find_first_of("+)", openParen);

            std::string funcName = entry.substr(openParen + 1, closeParen - openParen - 1);

            std::string demangledName = demangle(funcName);

            int pipefd[2];
            if(pipe(pipefd)) return; // error occurred

            if(int childPid = fork()) {
                if(childPid < 0) return;
                wait(nullptr);

                close(pipefd[1]);
                char bufferLine[2048];

                auto bytesRead = read(pipefd[0], bufferLine, 2048);
                if(bytesRead <= 0) return;
                bufferLine[bytesRead] = '\0';

                close(pipefd[0]);

                std::string output = bufferLine;

                auto colonPos = output.find_first_of(':');
                auto spacePos = output.find_first_of(' ', colonPos);
                if(spacePos == output.npos) spacePos = output.length();

                std::string filepath;
                try {
                    filepath = Filesystem::Canonical(output.substr(0, colonPos));
                }
                catch(...) {
                    filepath = output.substr(0, colonPos);
                }

                int lineNumber = String::To<int>(output.substr(colonPos + 1, spacePos - colonPos - 1));
                //if(String::Trim(filepath)=="" || lineNumber==0) continue;

                // Extract directory and filename components
                std::string dirPath = Filesystem::GetDirectory(filepath);
                if(!dirPath.empty() && dirPath.back() == '/') {
                    dirPath.pop_back();
                }
                dirPath = Filesystem::GetFilename(dirPath);
                filepath = Filesystem::GetFilename(filepath);

                term.SetColor(Console::Cyan);
                if((idx - offset - 1) == 1) {
                    term.SetBold(true);
                }
                std::cout << "  [" << (idx - offset - 1) << "] ";
                term.SetBold(false);
                term.SetColor(Console::Default);
                if(!demangledName.empty()) {
                    std::cout << "In function ";
                    term.SetColor(Console::Green);
                    std::cout << demangledName << " ";
                }
                else if(!funcName.empty()) {
                    std::cout << "In function ";
                    term.SetColor(Console::Green);
                    std::cout << funcName << " ";
                }
                term.SetColor(Console::Default);
                std::cout << "at ";
                if((idx - offset - 1) == 1) {
                    term.SetColor(Console::Red);
                }
                std::cout << "..." << dirPath << "/" << filepath;
                term.SetBold();
                std::cout << ":" << lineNumber << std::endl;
                term.Reset();
            }
            else {
                errno = 0;
                char addressStr[64];
                snprintf(addressStr, sizeof(addressStr), "%p", buffer[idx]);

                close(pipefd[0]);
                dup2(pipefd[1], STDOUT_FILENO);
                dup2(pipefd[1], STDERR_FILENO);

                execlp("addr2line", "addr2line", addressStr, "-e", Filesystem::ExePath().c_str(), nullptr);

                perror("Addr2line utility not found.");

                _exit(1);
            }
        };

#ifdef UNIT_TEST
        for(int j=2; j<offset+2; j++) {
            printFrame(j);
        }
#endif			

        for(int j=offset+2; j<count; j++) {
            printFrame(j);
        }
    }

}

