MenuBackup::MenuBackup(shared_ptr<Inventory> playerInv, AbstractContainerMenu *container)
{
    snapshotMap = new unordered_map<short, ItemInstanceArray *>();
    this->inventory = playerInv;
    this->menu = container;
}

void MenuBackup::capture(short snapshotId)
{
    ItemInstanceArray *snapshot = new ItemInstanceArray( (int)menu->slots->size() + 1 );
    (*snapshot)[0] = ItemInstance::clone(inventory->getCarried());

    for (size_t idx = 0; idx < menu->slots->size(); ++idx)
    {
        (*snapshot)[idx + 1] = ItemInstance::clone(menu->slots->at(idx)->getItem());
    }

    // Using unordered_map as storage mechanism
    (*snapshotMap)[snapshotId] = snapshot;
}

// Avoid using 'delete' as function name due to language restriction
void MenuBackup::removeSnapshot(short snapshotId)
{
    // Ensure safe removal from map
    snapshotMap->erase(snapshotId);
}

void MenuBackup::restore(short snapshotId)
{
    ItemInstanceArray *snapshot = snapshotMap->at(snapshotId);
    snapshotMap->clear();

    inventory->setCarried( (*snapshot)[0] );
    for (size_t i = 0; i < menu->slots->size(); ++i)
    {
        menu->slots->at(i)->set( (*snapshot)[i + 1] );
    }
}

