void TreeCollection::addTrees(CandidateSet &candidateTrees) {
    CandidateSet::reverse_iterator iter;
    for (iter = candidateTrees.rbegin(); iter != candidateTrees.rend(); iter++) {
       treeStrings.push_back(iter->second.tree);
       scores.push_back(iter->first);
       sourceProcID.push_back(MPIHelper::getInstance().getProcessID());
    }
}

size_t TreeCollection::getNumTrees() {
    size_t count = treeStrings.size();
    ASSERT(count == scores.size());
    return count;
}

