struct LineSegment {
    double start_x, start_y, end_x, end_y;
    double delta_x, delta_y, length;
    double min_x, max_x;

    // precomputed values for rectangle part (conditions 1 and 2)
    double coeff_t, const_t_low, const_t_high;     // for condition 1 (t in [0,1])
    double coeff_band, intercept_low, intercept_high; // for condition 2 (|B| <= brush_radius*length)
