        length = sqrt(delta_x * delta_x + delta_y * delta_y);
        min_x = min(start_x, end_x) - brush_radius;
        max_x = max(start_x, end_x) + brush_radius;

        if (length < TOLERANCE) {
            is_single_point = true;
            return;
        }
        is_single_point = false;
    }
};

