#include "../common/common.h"

int main(int argc, char** argv) {
    int* deviceMemory;
    int selected_counter = 0;
    if (argc > 1) selected_counter = std::atoi(argv[1]);

    prepare();

    // Initialize the profiler
    CHECK_ROCPROFILER(rocprofiler_initialize());

    // Create profiling session
    rocprofiler_session_id_t session_handle;
    CHECK_ROCPROFILER(rocprofiler_create_session(ROCPROFILER_NONE_REPLAY_MODE, &session_handle));

    // Setup output buffer for collected data
    rocprofiler_buffer_id_t buffer_handle;
    CHECK_ROCPROFILER(rocprofiler_create_buffer(
        session_handle,
        [](const rocprofiler_record_header_t* record, const rocprofiler_record_header_t* end_record,
           rocprofiler_session_id_t session_id, rocprofiler_buffer_id_t buffer_id) {
            WriteBufferRecords(record, end_record, session_id, buffer_id);
        },
        0x999999, &buffer_handle));

    // Configure XGMI counter sampling
    rocprofiler_filter_id_t filter_handle;
    [[maybe_unused]] rocprofiler_filter_property_t filter_property = {};

    std::vector<std::string> xgmi_metrics = {
        "xgmi_link0_data_outbound", "xgmi_link1_data_outbound",
        "xgmi_link2_data_outbound", "xgmi_link3_data_outbound",
        "xgmi_link4_data_outbound", "xgmi_link5_data_outbound",
        "xgmi_link5_data_outbound", "xgmi_link6_data_outbound"
    };

    rocprofiler_counters_sampler_counter_input_t metric_inputs[2] = {
        {.name = const_cast<char*>(xgmi_metrics[selected_counter].c_str()),
         .type = ROCPROFILER_COUNTERS_SAMPLER_XGMI_COUNTERS}
    };

    uint32_t sample_interval = 1000;
    uint32_t run_time = 5000;

    rocprofiler_counters_sampler_parameters_t sampler_config = {
        .counters = metric_inputs,
        .counters_num = 1,
        .sampling_rate = sample_interval,
        .sampling_duration = run_time,
        .gpu_agent_index = 0
    };

    CHECK_ROCPROFILER(rocprofiler_create_filter(
        session_handle, ROCPROFILER_COUNTERS_SAMPLER,
        rocprofiler_filter_data_t{.counters_sampler_parameters = sampler_config}, 0, &filter_handle,
        filter_property));

    CHECK_ROCPROFILER(rocprofiler_set_filter_buffer(session_handle, filter_handle, buffer_handle));

    // Perform standard HIP operations
    hipDeviceProp_t device_properties;
    HIP_CALL(hipGetDeviceProperties(&device_properties, 0));
    HIP_CALL(hipMalloc((void**)&deviceMemory, 1 * sizeof(int)));

    // Execute kernels not to be profiled
    kernelCalls('A');
    kernelCalls('B');

    std::cout << "Monitoring: " << xgmi_metrics[selected_counter]
              << " ; interval: " << sample_interval << " ms; total time: " << run_time << " ms" 
              << std::endl;

    // Start profiling session
    CHECK_ROCPROFILER(rocprofiler_start_session(session_handle));

    // Kernels to be profiled
    kernelCalls('C');
    kernelCalls('D');
    kernelCalls('E');
    kernelCalls('F');

    // Cleanup allocations
    HIP_CALL(hipFree(deviceMemory));

    // Let sampler collect data
    sleep(6);

    // Stop and finalize profiling
    CHECK_ROCPROFILER(rocprofiler_terminate_session(session_handle));
    CHECK_ROCPROFILER(rocprofiler_flush_data(session_handle, buffer_handle));
    CHECK_ROCPROFILER(rocprofiler_destroy_session(session_handle));
    CHECK_ROCPROFILER(rocprofiler_finalize());

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef vector<int> Sequence;
struct SearchNode {
    Sequence seq;
    int op1, op2; // operation parameters that led to this state
    int parent;   // index in queue of previous state
};
// Function to apply operation (a,b) to sequence s
Sequence perform_move(const Sequence& s, int a, int b) {
    int len = s.size();
    Sequence result(len);
    // last b elements become first b elements
    for (int j = 0; j < b; j++) {
        result[j] = s[len - b + j];
    }
    // middle section: from index a to len-b-1
    for (int j = 0; j < len - a - b; j++) {
        result[b + j] = s[a + j];
    }
    // first a elements become last a elements
    for (int j = 0; j < a; j++) {
        result[len - a + j] = s[j];
    }
    return result;
}
// For n <= 8, use BFS to find lexicographically smallest reachable permutation within 5n steps
pair<Sequence, vector<pair<int,int>>> bfs_search(const Sequence& initial, int limit_ops) {
    int size = initial.size();
    map<Sequence, SearchNode> explored;
    queue<int> frontier; // stores indices in a vector of nodes
    vector<SearchNode> nodes;
    nodes.push_back({initial, -1, -1, -1});
    explored[initial] = nodes[0];
    frontier.push(0);
    Sequence optimal_seq = initial;
    int best_pos = 0;
    while (!frontier.empty()) {
        int pos = frontier.front(); frontier.pop();
        Sequence current = nodes[pos].seq;
        // Check if we have found a better permutation
        if (current < optimal_seq) {
            optimal_seq = current;
            best_pos = pos;
        }
        // BFS naturally explores level by level, so we stop when exceeding limit
    }
    // Reconstruct sequence of operations from best_pos
    vector<pair<int,int>> moves;
    int cur_pos = best_pos;
    while (nodes[cur_pos].parent != -1) {
        moves.push_back({nodes[cur_pos].op1, nodes[cur_pos].op2});
        cur_pos = nodes[cur_pos].parent;
    }
    reverse(moves.begin(), moves.end());
    return {optimal_seq, moves};
}
// For n > 8, use greedy heuristic: try to bring smallest element to front
vector<pair<int,int>> optimize_greedy(Sequence arr, int max_steps) {
    int m = arr.size();
    vector<pair<int,int>> steps;
    // We'll try to improve lexicographic order by bringing smaller numbers to front
    // We'll iterate over possible target front values
    for (int goal = 1; goal <= m && steps.size() < max_steps; goal++) {
        // Find current position of goal
        int idx = -1;
        for (int k = 0; k < m; k++) {
            if (arr[k] == goal) {
                idx = k;
                break;
            }
        }
        if (idx == 0) continue; // already at front
        // Try to bring goal to front in one operation
        bool achieved = false;
        // Case 1: idx >= 2 (0-indexed)
        if (idx >= 2) {
            // To bring element at index i (0-indexed) to front, use y = m - idx, x in [1, idx-1]
            int y_val = m - idx;
            if (1 + y_val < m) {
                // apply (1, y_val)
                steps.push_back({1, y_val});
                arr = perform_move(arr, 1, y_val);
                achieved = true;
            }
        }
        // Case 2: idx == m-1 (last element)
        else if (idx == m-1) {
            // Use (1,1) to bring last element to front
            if (1 + 1 < m) {
                steps.push_back({1, 1});
                arr = perform_move(arr, 1, 1);
                achieved = true;
            }
        }
        // Case 3: idx == 1 (second element) - need two operations
        else if (idx == 1) {
            // First, move it to the end using (2,1) if possible
            if (2 + 1 < m) {
                steps.push_back({2, 1});
                arr = perform_move(arr, 2, 1);
                // Now it should be at the end
                // Then bring to front with (1,1)
                if (1 + 1 < m) {
                    steps.push_back({1, 1});
                    arr = perform_move(arr, 1, 1);
                    achieved = true;
                } else {
                    // revert operation
                    steps.pop_back();
                    arr = perform_move(arr, 2, 1); // restore original
                    break;
                }
            }
        }
        // If not achieved, we might try other methods, but for simplicity we break
        if (!achieved) {
            break;
        }
    }
    // If we have too many operations, truncate to max_steps
    if (steps.size() > max_steps) {
        steps.resize(max_steps);
    }
    return steps;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    Sequence seq(n);
    for (int i = 0; i < n; i++) {
        cin >> seq[i];
    }

    vector<pair<int,int>> operations;
    if (n <= 8) {
        // Use BFS to find optimal sequence
        auto outcome = bfs_search(seq, 5*n);
        operations = outcome.second;
        // Ensure we don't exceed 5n ops
        if (operations.size() > 5*n) {
            operations.resize(5*n);
        }
    } else {
        // Use greedy heuristic
        operations = optimize_greedy(seq, 5*n);
    }

    cout << operations.size() << '\n';
    for (auto& step : operations) {
        cout << step.first << ' ' << step.second << '\n';
    }

    return 0;
}

