//////////////////////////////////////////////////////////////////////////////
// Load and parse JSON from a file
//////////////////////////////////////////////////////////////////////////////
static void FileToParse(benchmark::State& state, const char* path)
{
    while (state.KeepRunning())
    {
        state.PauseTiming();
        auto* input_stream = new std::ifstream(path);
        auto* parsed_json = new json();
        state.ResumeTiming();
        *parsed_json = json::parse(*input_stream);
        state.PauseTiming();
        delete input_stream;
        delete parsed_json;
        state.ResumeTiming();
    }
    std::ifstream data_file(path, std::ios::binary | std::ios::ate);
    state.SetBytesProcessed(state.iterations() * data_file.tellg());
}
