template <class T> static void verify_equal(const T & expected_val, const T & actual_val) {
  if (expected_val != actual_val) {
      std::cerr << "Expected: " << expected_val << std::endl;
      std::cerr << "Actual: " << actual_val << std::endl;
      std::cerr << std::flush;
      throw std::runtime_error("Assertion error");
  }
}

static void validate_json_recovery() {
  auto try_parse = [](const std::string & text) {
      std::cerr << "# Processing: " << text << '\n';
      std::string::const_iterator pos = text.begin();
      const auto limit = text.end();
      common_json result;
      std::string recovery_tag = "$llama.cpp.json$";
      if (common_json_parse(pos, limit, recovery_tag, result)) {
          auto serialized = result.json.dump();
          std::cerr << "Parsed: " << serialized << '\n';
          std::cerr << "Marker: " << result.healing_marker.json_dump_marker << '\n';
          std::string output;
          if (!result.healing_marker.json_dump_marker.empty()) {
              auto idx = serialized.find(result.healing_marker.json_dump_marker);
              if (idx == std::string::npos) {
                  throw std::runtime_error("Cannot locate marker in output " + serialized + " (marker: " + result.healing_marker.json_dump_marker + ")");
              }
              output = serialized.substr(0, idx);
          } else {
            output = serialized;
          }
          std::cerr << "Output: " << output << '\n';
          if (string_starts_with(text, output)) {
            std::cerr << "Error detected!\n";
          }
        //   return serialized;
      } else {
        throw std::runtime_error("Parsing failed: " + text);
      }
  };

  auto try_parse_all = [&](const std::string & text) {
      for (size_t len = 1; len < text.length(); len++) {
          try_parse(text.substr(0, len));
      }
  };

  try_parse_all("{\"x\": \"y\"}");
  try_parse_all("{\"test\": 5, \"data\\\"info\": [3]}");
  try_parse_all("[{\"id\": \"value\"}]");

  auto run_test = [&](const std::vector<std::string> & cases, const std::string & expected_output, const std::string & expected_marker) {
      for (const auto & input : cases) {
        common_json out;
        verify_equal(true, common_json_parse(input, "$bar", out));
        verify_equal<std::string>(expected_output, out.json.dump(/* indent */ -1, /* indent_char */ ' ', /* ensure_ascii */ true));
        verify_equal<std::string>(expected_marker, out.healing_marker.json_dump_marker);
      }
  };

  // No recovery required:
  run_test(
    {
      R"([{"x":"y"}, "end"])",
    },
    R"([{"x":"y"},"end"])",
    ""
  );

  // Incomplete literals cannot be recovered:
  run_test(
    {
      R"([5)",
      R"([fals)",
      R"([n)",
      R"([nul)",
      R"([45.7)",
    },
    R"(["$bar"])",
    R"("$bar)"
  );

  run_test(
    {
      R"({"val": 5)",
      R"({"val": fals)",
      R"({"val": n)",
      R"({"val": nul)",
      R"({"val": 67.8)",
    },
    R"({"val":"$bar"})",
    R"("$bar)"
  );

  run_test(
    {
      R"({)",
    },
    R"({"$bar":1})",
    R"("$bar)"
  );

  run_test(
    {
      R"([)",
    },
    R"(["$bar"])",
    R"("$bar)"
  );

  // Recovery after complete literal
  run_test(
    {
      R"(5 )",
    },
    R"(5)",
    ""
  );

  run_test(
    {
      R"(false)",
      R"(false )",
    },
    R"(false)",
    ""
  );

  run_test(
    {
      R"(null)",
      R"(null )",
    },
    R"(null)",
    ""
  );

  run_test(
    {
      R"([5 )",
    },
    R"([5,"$bar"])",
    R"(,"$bar)"
  );

  run_test(
    {
      R"([{} )",
    },
    R"([{},"$bar"])",
    R"(,"$bar)"
  );

  run_test(
    {
      R"([false)",
    },
    // TODO: detect the true/false/null literal was complete
    R"(["$bar"])",
    R"("$bar)"
  );

  run_test(
    {
      R"([false )",
    },
    R"([false,"$bar"])",
    R"(,"$bar)"
  );

  run_test(
    {
      R"([false,)",
    },
    R"([false,"$bar"])",
    R"("$bar)"
  );

  // Test nesting
  run_test(
    {
      R"([{"val": [{"key": [{)",
    },
    R"([{"val":[{"key":[{"$bar":1}]}]}])",
    R"("$bar)"
  );

  run_test(
    {
      R"([{"val": [{"key": [)",
    },
    R"([{"val":[{"key":["$bar"]}]}])",
    R"("$bar)"
  );

  run_test(
    {
      R"([{"val": "y"})",
      R"([{"val": "y"} )",
    },
    R"([{"val":"y"},"$bar"])",
    R"(,"$bar)"
  );

  run_test(
    {
      R"([{"val": "y"},)",
      R"([{"val": "y"}, )",
    },
    R"([{"val":"y"},"$bar"])",
    R"("$bar)"
  );

  run_test(
    {
      R"({ "func)",
    },
    R"({"func$bar":1})",
    R"($bar)"
  );

  run_test(
    {
      R"({ "func\)",
    },
    R"({"func\\$bar":1})",
    R"(\$bar)"
  );

  run_test(
    {
      R"({ "name")",
    },
    R"({"name":"$bar"})",
    R"(:"$bar)"
  );

  run_test(
    {
      R"({ "field")",
    },
    R"({"field":"$bar"})",
    R"(:"$bar)"
  );

  // Test unicode escape sequences
  run_test(
    {
      R"({"a":"\u)",
    },
    R"({"a":"\u0000$bar"})",
    R"(0000$bar)"
  );

  run_test(
    {
      R"({"a":"\u00)",
    },
    R"({"a":"\u0000$bar"})",
    R"(00$bar)"
  );

  run_test(
    {
      R"({"a":"\ud300)",
    },
    R"({"a":"\ud300$bar"})",
    R"($bar)"
  );

  run_test(
    {
      R"({"a":"\ud800)",
    },
    R"({"a":"\ud800\udc00$bar"})",
    R"(\udc00$bar)"
  );

  run_test(
    {
      R"({"a":"\ud800\)",
    },
    R"({"a":"\ud800\udc00$bar"})",
    R"(udc00$bar)"
  );

  run_test(
    {
      R"({"a":"\ud800\u)",
    },
    R"({"a":"\ud800\udc00$bar"})",
    R"(dc00$bar)"
  );

  run_test(
    {
      R"({"a":"\ud800\udc00)",
    },
    R"({"a":"\ud800\udc00$bar"})",
    R"($bar)"
  );
}

int main() {
    validate_json_recovery();
    std::cerr << "All validations successful.\n";
    return 0;
}

