using namespace llvm;

/// -stats - Command line flag to enable statistics collection during transformations.
///
static bool StatsEnabled;
static bool OutputAsJSON;
static bool ForceEnable;
static bool ShowOnShutdown;

void llvm::initStatisticOptions() {
  static cl::opt<bool, true> registerStatsFlag{
      "stats",
      cl::desc("Enable statistics output from program (available with Asserts)"),
      cl::location(StatsEnabled), cl::Hidden};
  static cl::opt<bool, true> registerJSONOutput{
      "stats-json", cl::desc("Display statistics in JSON format"),
      cl::location(OutputAsJSON), cl::Hidden};
}

namespace {
/// This class is used in a ManagedStatic to ensure lazy initialization and
/// cleanup upon program termination via llvm_shutdown.
/// It collects and manages all registered statistics for later output.
class StatisticRegistry {
  std::vector<TrackingStatistic *> RegisteredStats;
  friend void llvm::PrintStatistics();
  friend void llvm::PrintStatistics(raw_ostream &OS);
  friend void llvm::PrintStatisticsJSON(raw_ostream &OS);

  /// Sort statistics by debug type, name, and description.
  void sort();

public:
  using const_iterator = std::vector<TrackingStatistic *>::const_iterator;
  StatisticRegistry();
  ~StatisticRegistry();
  void registerStatistic(TrackingStatistic *S) { RegisteredStats.push_back(S); }
  const_iterator begin() const { return RegisteredStats.begin(); }
  const_iterator end() const { return RegisteredStats.end(); }
  iterator_range<const_iterator> statistics() const {
    return {begin(), end()};
  }
  void clearAndReset();
};
} // end anonymous namespace

static ManagedStatic<StatisticRegistry> StatRegistry;
static ManagedStatic<sys::SmartMutex<true>> StatMutex;

/// Called the first time a statistic is updated — registers it for later output.
void TrackingStatistic::RegisterStatistic() {
  if (!Initialized.load(std::memory_order_relaxed)) {
    sys::SmartMutex<true> &Mutex = *StatMutex;
    StatisticRegistry &SR = *StatRegistry;
    sys::SmartScopedLock<true> Writer(Mutex);

    // Re-check after acquiring lock to avoid duplicate registration.
    if (Initialized.load(std::memory_order_relaxed))
      return;

    if (StatsEnabled || ForceEnable)
      SR.registerStatistic(this);

    Initialized.store(true, std::memory_order_release);
  }
}

StatisticRegistry::StatisticRegistry() {
  TimerGroup::constructForStatistics();
}

StatisticRegistry::~StatisticRegistry() {
  if (StatsEnabled || ShowOnShutdown)
    llvm::PrintStatistics();
}

void llvm::EnableStatistics(bool PrintOnShutdown) {
  ForceEnable = true;
  ShowOnShutdown = PrintOnShutdown;
}

bool llvm::AreStatisticsEnabled() { return ForceEnable || StatsEnabled; }

void StatisticRegistry::sort() {
  llvm::stable_sort(
      RegisteredStats, [](const TrackingStatistic *A, const TrackingStatistic *B) {
        if (int cmp = std::strcmp(A->getDebugType(), B->getDebugType()))
          return cmp < 0;
        if (int cmp = std::strcmp(A->getName(), B->getName()))
          return cmp < 0;
        return std::strcmp(A->getDesc(), B->getDesc()) < 0;
      });
}

void StatisticRegistry::clearAndReset() {
  sys::SmartScopedLock<true> Writer(*StatMutex);
  for (auto *stat : RegisteredStats) {
    stat->Initialized = false;
    stat->Value = 0;
  }
  RegisteredStats.clear();
}

void llvm::PrintStatistics(raw_ostream &OS) {
  StatisticRegistry &Registry = *StatRegistry;
  unsigned MaxValWidth = 0, MaxTypeWidth = 0;

  for (TrackingStatistic *stat : Registry.RegisteredStats) {
    MaxValWidth = std::max(MaxValWidth, (unsigned)utostr(stat->getValue()).size());
    MaxTypeWidth = std::max(MaxTypeWidth, (unsigned)std::strlen(stat->getDebugType()));
  }

  Registry.sort();

  OS << "===" << std::string(73, '-') << "===\n"
     << "                          ... Statistics Collected ...\n"
     << "===" << std::string(73, '-') << "===\n\n";

  for (TrackingStatistic *stat : Registry.RegisteredStats)
    OS << format("%*" PRIu64 " %-*s - %s\n", MaxValWidth, stat->getValue(),
                 MaxTypeWidth, stat->getDebugType(), stat->getDesc());

  OS << '\n';
  OS.flush();
}

void llvm::PrintStatisticsJSON(raw_ostream &OS) {
  sys::SmartScopedLock<true> Reader(*StatMutex);
  StatisticRegistry &Registry = *StatRegistry;
  Registry.sort();

  OS << "{\n";
  const char *separator = "";
  for (const TrackingStatistic *stat : Registry.RegisteredStats) {
    OS << separator;
    assert(yaml::needsQuotes(stat->getDebugType()) == yaml::QuotingType::None &&
           "Statistic group/type name is simple.");
    assert(yaml::needsQuotes(stat->getName()) == yaml::QuotingType::None &&
           "Statistic name is simple");
    OS << "\t\"" << stat->getDebugType() << '.' << stat->getName() << "\": "
       << stat->getValue();
    separator = ",\n";
  }

  TimerGroup::printAllJSONValues(OS, separator);
  OS << "\n}\n";
  OS.flush();
}

void llvm::PrintStatistics() {
#if LLVM_ENABLE_STATS
  sys::SmartScopedLock<true> Reader(*StatMutex);
  StatisticRegistry &Registry = *StatRegistry;
  if (Registry.RegisteredStats.empty()) return;

  std::unique_ptr<raw_ostream> OutStream = CreateInfoOutputFile();
  if (OutputAsJSON)
    PrintStatisticsJSON(*OutStream);
  else
    PrintStatistics(*OutStream);
#else
  if (StatsEnabled) {
    std::unique_ptr<raw_ostream> OutStream = CreateInfoOutputFile();
    (*OutStream) << "Statistics are disabled.  "
                 << "Build with asserts or with -DLLVM_FORCE_ENABLE_STATS\n";
  }
#endif
}

std::vector<std::pair<StringRef, uint64_t>> llvm::GetStatistics() {
  sys::SmartScopedLock<true> Reader(*StatMutex);
  std::vector<std::pair<StringRef, uint64_t>> result;
  for (const auto &stat : StatRegistry->statistics())
    result.emplace_back(stat->getName(), stat->getValue());
  return result;
}

void llvm::ResetStatistics() {
  StatRegistry->clearAndReset();
}

