#include "gtest/gtest.h"
#include "core/demangler.hpp"
#include <cstring>
#include <string>

struct mock_demangle_backend
{
    static inline int invocation_counter = 0;
    static char* perform_demangling(const char* _input_name, char*, size_t*, int* _status)
    {
        ++invocation_counter;
        if(std::string(_input_name).find("ERROR") != std::string::npos)
        {
            *_status = -1;
            return nullptr;
        }
        std::string transformed = "unmangled_" + std::string(_input_name);
        char*       buffer      = static_cast<char*>(std::malloc(transformed.size() + 1));
        memcpy(buffer, transformed.c_str(), transformed.size() + 1);
        *_status = 0;
        return buffer;
    }
};

class demangle_test_suite : public ::testing::Test
{
protected:
    void SetUp() override { mock_demangle_backend::invocation_counter = 0; }
};

TEST_F(demangle_test_suite, basic_success_case)
{
    rocprofsys::utility::demangler<mock_demangle_backend> handler;
    std::string output = handler.demangle("symbol");
    EXPECT_EQ(output, "unmangled_symbol");
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1);
}

TEST_F(demangle_test_suite, failure_returns_original_input)
{
    rocprofsys::utility::demangler<mock_demangle_backend> handler;
    std::string output = handler.demangle("symbol_ERROR");
    EXPECT_EQ(output, "symbol_ERROR");
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1);
}

TEST_F(demangle_test_suite, empty_input_yields_empty_output)
{
    rocprofsys::utility::demangler<mock_demangle_backend> handler;
    std::string output = handler.demangle("");
    EXPECT_TRUE(output.empty());
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 0);
}

TEST_F(demangle_test_suite, repeated_calls_use_cached_result)
{
    rocprofsys::utility::demangler<mock_demangle_backend> handler;
    std::string first  = handler.demangle("symbol");
    std::string second = handler.demangle("symbol");
    std::string third  = handler.demangle("symbol");
    EXPECT_EQ(first, "unmangled_symbol");
    EXPECT_EQ(first, second);
    EXPECT_EQ(second, third);
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1);
}

TEST_F(demangle_test_suite, distinct_inputs_are_cached_independently)
{
    rocprofsys::utility::demangler<mock_demangle_backend> handler;
    std::string val1          = handler.demangle("symbolA");
    std::string val2          = handler.demangle("symbolB");
    std::string val1_reused   = handler.demangle("symbolA");
    EXPECT_EQ(val1, "unmangled_symbolA");
    EXPECT_EQ(val2, "unmangled_symbolB");
    EXPECT_EQ(val1, val1_reused);
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 2);
}

TEST_F(demangle_test_suite, string_view_support)
{
    rocprofsys::utility::demangler<mock_demangle_backend> handler;
    std::string input_str = "symbol";
    std::string_view input_sv{ input_str };
    std::string output = handler.demangle(input_sv);
    EXPECT_EQ(output, "unmangled_symbol");
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1);
}

TEST_F(demangle_test_suite, template_based_demangle)
{
    rocprofsys::utility::demangler<mock_demangle_backend> handler;
    std::string output = handler.demangle<int>();
    EXPECT_NE(output.find("unmangled_"), std::string::npos);
    EXPECT_FALSE(output.empty());
}

TEST_F(demangle_test_suite, failed_demangles_are_cached_as_well)
{
    rocprofsys::utility::demangler<mock_demangle_backend> handler;
    std::string first  = handler.demangle("ERROR");
    std::string second = handler.demangle("ERROR");
    EXPECT_EQ(first, "ERROR");
    EXPECT_EQ(first, second);
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1);
}

TEST_F(demangle_test_suite, separate_instances_maintain_independent_caches)
{
    rocprofsys::utility::demangler<mock_demangle_backend> handler1;
    rocprofsys::utility::demangler<mock_demangle_backend> handler2;
    handler1.demangle("symbol");
    handler2.demangle("symbol");
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 2);
}

