xpu_result_t DefaultXpuApi::setDevice(int dev_id) {
  try {
    ::c10::xpu::set_device(dev_id);
    return XPU_SUCCESS;
  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to set XPU device to " << dev_id << ": "
                  << err.what();
    return XPU_ERROR_INVALID_VALUE;
  }
}

xpu_result_t DefaultXpuApi::getDeviceProperties(
    xpuDeviceProp* prop,
    int dev_id) {
  if (!prop) {
    return XPU_ERROR_INVALID_VALUE;
  }
  try {
    sycl::device sycl_dev = ::c10::xpu::get_raw_device(dev_id);
    // Retrieve device name
    std::string dev_name = sycl_dev.get_info<sycl::info::device::name>();
    strncpy(prop->name, dev_name.c_str(), 255);
    prop->name[255] = '\0';
    // Retrieve memory info
    prop->totalGlobalMem =
        sycl_dev.get_info<sycl::info::device::global_mem_size>();
    if (!sycl_dev.has(sycl::aspect::ext_intel_free_memory)) [[unlikely]] {
      TC_LOG(WARNING)
          << "Free memory queries are unsupported on this SYCL device; using total global memory as the free-memory estimate.";
    }
    // Retrieve compute capabilities
    auto max_work_group_sz =
        sycl_dev.get_info<sycl::info::device::max_work_group_size>();
    auto max_work_item_sz =
        sycl_dev.get_info<sycl::info::device::max_work_item_sizes<3>>();
    auto max_compute_units =
        sycl_dev.get_info<sycl::info::device::max_compute_units>();
    prop->multiProcessorCount = max_compute_units;
    prop->maxThreadsPerBlock = max_work_group_sz;
    prop->maxThreadsDim[0] = max_work_item_sz[0];
    prop->maxThreadsDim[1] = max_work_item_sz[1];
    prop->maxThreadsDim[2] = max_work_item_sz[2];
    return XPU_SUCCESS;
  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to get XPU device properties for device " << dev_id
                  << ": " << err.what();
    return XPU_ERROR_INVALID_VALUE;
  }
}

xpu_result_t DefaultXpuApi::memGetInfo(size_t* free_mem, size_t* total_mem) {
  if (!free_mem || !total_mem) {
    return XPU_ERROR_INVALID_VALUE;
  }
  try {
    int dev_id = ::c10::xpu::current_device();
    sycl::device& sycl_dev = ::c10::xpu::get_raw_device(dev_id);
    *total_mem = sycl_dev.get_info<sycl::info::device::global_mem_size>();
    if (sycl_dev.has(sycl::aspect::ext_intel_free_memory)) [[likely]] {
      *free_mem =
          sycl_dev.get_info<sycl::ext::intel::info::device::free_memory>();
    } else [[unlikely]] {
      *free_mem = *total_mem;
    }
    return XPU_SUCCESS;
  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to get XPU memory info: " << err.what();
    return XPU_ERROR_INVALID_VALUE;
  }
}

xpu_result_t DefaultXpuApi::getDeviceCount(int* count_ptr) {
  if (!count_ptr) {
    return XPU_ERROR_INVALID_VALUE;
  }
  try {
    *count_ptr = ::c10::xpu::device_count();
    return XPU_SUCCESS;
  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to get XPU device count: " << err.what();
    return XPU_ERROR_INVALID_VALUE;
  }
}

xpu_result_t DefaultXpuApi::streamCreateWithPriority(
    xpuStream_t& stream_handle,
