  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to create XPU stream with priority " << priority_level
                  << ": " << err.what();
    return XPU_ERROR_INVALID_VALUE;
  }
}

xpu_result_t DefaultXpuApi::streamDestroy(
    [[maybe_unused]] const xpuStream_t& stream_handle) {
