  if (!p_capture_status) {
    return XPU_ERROR_INVALID_VALUE;
  }
  // XPU/SYCL doesn't support stream capture
  *p_capture_status = xpuStreamCaptureStatusNone;
  return XPU_ERROR_UNSUPPORTED;
