xpu_result_t DefaultXpuApi::malloc(void** dev_ptr, size_t size_bytes) {
  if (!dev_ptr) {
    return XPU_ERROR_INVALID_VALUE;
  }
  if (size_bytes == 0) {
    *dev_ptr = nullptr;
    return XPU_SUCCESS;
  }
  try {
    // Use SYCL's malloc_device
    sycl::context& ctx = ::c10::xpu::get_device_context();
    int dev_id = ::c10::xpu::current_device();
    sycl::device& dev = ::c10::xpu::get_raw_device(dev_id);
    *dev_ptr = sycl::malloc_device(size_bytes, dev, ctx);
    if (!*dev_ptr) {
      return XPU_ERROR_OUT_OF_MEMORY;
    }
    return XPU_SUCCESS;
  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to allocate " << size_bytes
                  << " bytes on XPU: " << err.what();
    return XPU_ERROR_OUT_OF_MEMORY;
  }
}

xpu_result_t DefaultXpuApi::free(void* dev_ptr) {
  if (!dev_ptr) {
    return XPU_SUCCESS;
  }
  try {
    sycl::context& ctx = ::c10::xpu::get_device_context();
    sycl::free(dev_ptr, ctx);
    return XPU_SUCCESS;
  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to free XPU memory: " << err.what();
    return XPU_ERROR_INVALID_VALUE;
  }
}

xpu_result_t DefaultXpuApi::memcpyAsync(
    void* dst_ptr,
    const void* src_ptr,
    size_t num_bytes,
    const xpuStream_t& stream_handle) {
  if (!dst_ptr || !src_ptr) {
    return XPU_ERROR_INVALID_VALUE;
  }
  if (num_bytes == 0) {
    return XPU_SUCCESS;
  }
  try {
    stream_handle.queue().memcpy(dst_ptr, src_ptr, num_bytes);
    return XPU_SUCCESS;
  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to perform asynchronous memory copy on XPU: "
                  << err.what();
    return XPU_ERROR_INVALID_VALUE;
  }
}

xpu_result_t DefaultXpuApi::eventCreate(xpuEvent_t& event_obj) {
  try {
    event_obj = ::at::xpu::XPUEvent(false); // No timing
    return XPU_SUCCESS;
  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to create XPU event: " << err.what();
    return XPU_ERROR_INVALID_VALUE;
  }
}

xpu_result_t DefaultXpuApi::eventCreateWithFlags(
    xpuEvent_t& event_obj,
    unsigned int flags_val) {
  try {
    bool enable_timing = (flags_val & 0x1) != 0;
    event_obj = ::at::xpu::XPUEvent(enable_timing);
    return XPU_SUCCESS;
  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to create XPU event with flags " << flags_val << ": "
                  << err.what();
    return XPU_ERROR_INVALID_VALUE;
  }
}

xpu_result_t DefaultXpuApi::eventDestroy(
    [[maybe_unused]] const xpuEvent_t& event_obj) {
  // Event is RAII, nothing to do
  return XPU_SUCCESS;
}

xpu_result_t DefaultXpuApi::eventRecord(
    xpuEvent_t& event_obj,
    const xpuStream_t& stream_handle) {
  try {
    event_obj.record(stream_handle);
    return XPU_SUCCESS;
  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to record XPU event: " << err.what();
    return XPU_ERROR_INVALID_HANDLE;
  }
}

xpu_result_t DefaultXpuApi::eventQuery(const xpuEvent_t& event_obj) {
  try {
    bool is_complete = event_obj.query();
    return is_complete ? XPU_SUCCESS : XPU_ERROR_NOT_READY;
  } catch (const std::exception& err) {
    TC_LOG(ERROR) << "Failed to query XPU event: " << err.what();
    return XPU_ERROR_INVALID_HANDLE;
  }
}

