struct Operation {
    int left, right, direction;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if (!(cin >> size)) return 0;

    vector<int> values(size + 1), indexMap(size + 1);
    for (int idx = 1; idx <= size; ++idx) {
        cin >> values[idx];
        indexMap[values[idx]] = idx;
    }

    int mode = 2;
    vector<Operation> operations;
    operations.reserve(size * size / 2);

    for (int target = 1; target <= size; ++target) {
        int currentPos = indexMap[target];
        while (currentPos > target) {
            // Perform left shift on segment [currentPos-1, currentPos]
            operations.push_back({currentPos - 1, currentPos, 0});

            int val1 = values[currentPos - 1], val2 = values[currentPos];
            swap(values[currentPos - 1], values[currentPos]);
            indexMap[val1] = currentPos;
            indexMap[val2] = currentPos - 1;
            --currentPos;
        }
    }

    cout << mode << " " << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.left << " " << op.right << " " << op.direction << "\n";
    }

    return 0;
}

