// Generates an array of random floating-point values in the range [0, 1]
float*
generate_random_values(int count)
{
    float* values = (float*) malloc(sizeof(float) * count);
    assert(values != NULL);
    for(int idx = 0; idx < count; idx++)
    {
        values[idx] = (rand() / (float) RAND_MAX);
    }
    return values;
}

int
main(int argc, char** argv)
{
    if(argc != 2)
    {
        fprintf(stderr, "Usage: stddev num_elements_per_process\n");
        exit(1);
    }

    int elements_per_rank = atoi(argv[1]);

    MPI_Init(NULL, NULL);

    int my_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);

    int num_ranks;
    MPI_Comm_size(MPI_COMM_WORLD, &num_ranks);

    // Initialize random seed uniquely per process
    srand(time(NULL) * my_rank);

    float* random_data = generate_random_values(elements_per_rank);

    // Compute local sum
    float local_total = 0.0f;
    for(int j = 0; j < elements_per_rank; j++)
    {
        local_total += random_data[j];
    }

    // Gather all local sums to compute global mean
    float global_total;
    MPI_Allreduce(&local_total, &global_total, 1, MPI_FLOAT, MPI_SUM, MPI_COMM_WORLD);
    float average = global_total / (elements_per_rank * num_ranks);

    // Compute local sum of squared deviations from mean
    float local_sq_deviation = 0.0f;
    for(int k = 0; k < elements_per_rank; k++)
    {
        float diff = random_data[k] - average;
        local_sq_deviation += diff * diff;
    }

    // Reduce squared deviations to root process
    float global_sq_deviation;
    MPI_Reduce(&local_sq_deviation, &global_sq_deviation, 1, MPI_FLOAT, MPI_SUM, 0, MPI_COMM_WORLD);

    // Calculate and output standard deviation on root
    if(my_rank == 0)
    {
        float variance = global_sq_deviation / (elements_per_rank * num_ranks);
        float std_dev = sqrt(variance);
        printf("Mean - %f, Standard deviation = %f\n", average, std_dev);
    }

    // Cleanup
    free(random_data);
    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();
}

