#include "libm.h"
/* k is such that k*ln2 has minimal relative error and x - kln2 > log(DBL_MIN) */
static const int shift = 2043;
static const double shift_ln2 = 0x1.62066151add8bp+10;
/* exp(x)/2 for x >= log(DBL_MAX), slightly better than 0.5*exp(x/2)*exp(x/2) */
double __expo2(double value, double sign_factor)
{
	double scale_val;
	/* note that shift is odd and scale_val*scale_val overflows */
	INSERT_WORDS(scale_val, (uint32_t)(0x3ff + shift/2) << 20, 0);
	/* exp(value - shift ln2) * 2**(shift-1) */
	/* in directed rounding correct sign before rounding or overflow is important */
	return exp(value - shift_ln2) * (sign_factor * scale_val) * scale_val;
}

#include <iostream>
#include <iomanip>
#include <cmath>

// Assume necessary headers like <Teuchos_RCP.hpp>, <Teuchos_ParameterList.hpp>,
// <MeshManager_Brick.hpp>, <Intrepid2_Basis_HCURL_HEX_I1_FEM.hpp>,
// <Intrepid2_DefaultCubatureFactory.hpp>, <ROL_Ptr.hpp>, <Kokkos_Core.hpp>,
// <shards_CellTopology.hpp>, etc., are included elsewhere.

int main() {
  int errorFlag = 0;
  std::ostream* outStream = &std::cout;

  try {
    // Load parameter list from XML file
    std::string config_file = "input_05.xml";
    Teuchos::RCP<Teuchos::ParameterList> params
      = Teuchos::rcp( new Teuchos::ParameterList() );
    Teuchos::updateParametersFromXmlFile( config_file, params.ptr() );

    // Initialize mesh and DOF manager
    MeshManager_Brick<double, Kokkos::DefaultExecutionSpace> meshmgr(*params);
    auto nodeCoords = meshmgr.getNodes();
    auto connectivity = meshmgr.getCellToNodeMap();

    *outStream << "Total nodes: " << meshmgr.getNumNodes() << "\n";
    *outStream << "Total cells: " << meshmgr.getNumCells() << "\n";
    *outStream << "Total edges: " << meshmgr.getNumEdges() << "\n";

    ROL::Ptr<MeshManager<double, Kokkos::DefaultExecutionSpace>> meshPtr
      = ROL::makePtrFromRef(meshmgr);

    // Define basis and cubature
    using RealType = double;
    using DeviceType = Kokkos::DefaultExecutionSpace;
    using BasisPtr = ROL::Ptr<Intrepid2::Basis<DeviceType, RealType, RealType>>;

    BasisPtr hcurl_basis
      = ROL::makePtr<Intrepid2::Basis_HCURL_HEX_I1_FEM<DeviceType, RealType, RealType>>();

    shards::CellTopology cellTopo = hcurl_basis->getBaseCellTopology();
    Intrepid2::DefaultCubatureFactory factory;
    int polyOrder = 4;  // Cubature degree
    ROL::Ptr<Intrepid2::Cubature<DeviceType, RealType, RealType>> cub
      = factory.create<DeviceType, RealType, RealType>(cellTopo, polyOrder);

    // Populate cell node coordinates
    auto numCells = meshmgr.getNumCells();
    auto nodePerCell = cellTopo.getNodeCount();
    auto spaceDim = cellTopo.getDimension();

    Kokkos::View<RealType***, DeviceType> elemCoords("elemCoords", numCells, nodePerCell, spaceDim);
    for (int c=0; c<numCells; ++c) {
      for (unsigned n=0; n<nodePerCell; ++n) {
        for (unsigned d=0; d<spaceDim; ++d) {
          elemCoords(c,n,d) = nodeCoords(connectivity(c,n), d);
        }
      }
    }

    // Construct finite element object
    FE_CURL<RealType, DeviceType> feObj(elemCoords, hcurl_basis, cub);

    // Prepare views for evaluation
    auto numPoints = cub->getNumPoints();
    auto dim = cub->getDimension();
    Kokkos::View<RealType***, DeviceType> valsA("valsA", numCells, numPoints, dim);
    Kokkos::View<RealType***, DeviceType> valsB("valsB", numCells, numPoints, dim);
    Kokkos::View<RealType***, DeviceType> curlsA("curlsA", numCells, numPoints, dim);
    Kokkos::View<RealType***, DeviceType> curlsB("curlsB", numCells, numPoints, dim);
    Kokkos::View<RealType**, DeviceType> coeffsA("coeffsA", numCells, hcurl_basis->getCardinality());
    Kokkos::View<RealType**, DeviceType> coeffsB("coeffsB", numCells, hcurl_basis->getCardinality());
    Kokkos::View<RealType*, DeviceType> integrals("integrals", numCells);

    // Set coefficients and evaluate
    Kokkos::deep_copy(coeffsA, static_cast<RealType>(0));
    Kokkos::deep_copy(coeffsB, static_cast<RealType>(0));
    for (int c=0; c<numCells; ++c) {
      coeffsA(c,0) = static_cast<RealType>(1);
      coeffsB(c,0) = static_cast<RealType>(1);
    }

    feObj.evaluateValue(valsA, coeffsA);
    feObj.evaluateValue(valsB, coeffsB);
    feObj.computeIntegral(integrals, valsA, valsB);

    RealType valVal(0);
    for (int c=0; c<numCells; ++c) {
      valVal += integrals(c);
    }

    if (std::abs(valVal - static_cast<RealType>(4)/static_cast<RealType>(9)) > std::sqrt(ROL::ROL_EPSILON<RealType>())) {
      errorFlag = -1;
    }

    // Curl evaluations
    feObj.evaluateCurl(curlsA, coeffsA);
    feObj.evaluateCurl(curlsB, coeffsB);
    feObj.computeIntegral(integrals, curlsA, curlsB);

    RealType curlCurl(0);
    for (int c=0; c<numCells; ++c) {
      curlCurl += integrals(c);
    }

    if (std::abs(curlCurl - static_cast<RealType>(8)/static_cast<RealType>(3)) > std::sqrt(ROL::ROL_EPSILON<RealType>())) {
      errorFlag = -1;
    }

    *outStream << std::setprecision(14)
               << "\nvalueIntegral=" << valVal
               << "   curlIntegral=" << curlCurl << "\n";

  } catch (const std::logic_error& e) {
    *outStream << "Exception caught: " << e.what() << "\n";
    errorFlag = -1000;
  }

  if (errorFlag != 0) {
    std::cout << "End Result: TEST FAILED\n";
  } else {
    std::cout << "End Result: TEST PASSED\n";
  }

  return 0;
}

