#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long L;
    if (!(cin >> N >> L)) return 0;

    vector<long long> times(N);
    for (int i = 0; i < N; ++i) cin >> times[i];

    int totalEdges = 2 * N;

    // Adjust times for initial week at node 0
    vector<long long> adjustedTimes = times;
    if (adjustedTimes[0] > 0) adjustedTimes[0] -= 1;

    double weightFactor = (double)(L - 1) / (double)totalEdges;
    vector<double> rawCounts(N);
    vector<int> counts(N);
    vector<double> remainders(N);

    for (int i = 0; i < N; ++i) {
        rawCounts[i] = weightFactor > 0 ? (double)adjustedTimes[i] / weightFactor : 1.0;
        double floored = floor(rawCounts[i]);
        counts[i] = max(1, (int)floored);
        remainders[i] = rawCounts[i] - floored;
    }

    int currentSum = 0;
    for (int i = 0; i < N; ++i) currentSum += counts[i];

    if (currentSum < totalEdges) {
        vector<int> indices(N);
        iota(indices.begin(), indices.end(), 0);
        sort(indices.begin(), indices.end(), [&](int x, int y) {
            return remainders[x] > remainders[y];
        });

        int deficit = totalEdges - currentSum;
        int idx = 0;
        while (deficit > 0) {
            int pos = indices[idx % N];
            counts[pos]++;
            idx++;
            deficit--;
        }
    } else if (currentSum > totalEdges) {
        vector<int> indices(N);
        iota(indices.begin(), indices.end(), 0);
        sort(indices.begin(), indices.end(), [&](int x, int y) {
            return remainders[x] < remainders[y];
        });

        int excess = currentSum - totalEdges;
        int idx = 0;
        while (excess > 0) {
            int pos = indices[idx % N];
            if (counts[pos] > 1) {
                counts[pos]--;
                excess--;
            }
            idx++;
        }
    }

    // Build ring structure: a[i] is the next node in the cycle
    vector<int> outgoingA(N);
    for (int i = 0; i < N; ++i) {
        outgoingA[i] = (i + 1) % N;
    }

    // Determine additional incoming edges needed beyond the ring
    vector<int> extraIncoming(N);
    int sumExtra = 0;
    for (int i = 0; i < N; ++i) {
        extraIncoming[i] = max(0, counts[i] - 1);
        sumExtra += extraIncoming[i];
    }

    if (sumExtra != N) {
        vector<int> indices(N);
        iota(indices.begin(), indices.end(), 0);

        if (sumExtra < N) {
            sort(indices.begin(), indices.end(), [&](int x, int y) {
                return times[x] > times[y];
            });
            int toAdd = N - sumExtra;
            int idx = 0;
            while (toAdd > 0) {
                int pos = indices[idx % N];
                extraIncoming[pos]++;
                idx++;
                toAdd--;
            }
        } else {
            sort(indices.begin(), indices.end(), [&](int x, int y) {
                return times[x] < times[y];
            });
            int toRemove = sumExtra - N;
            int idx = 0;
            while (toRemove > 0) {
                int pos = indices[idx % N];
                if (extraIncoming[pos] > 0) {
                    extraIncoming[pos]--;
                    toRemove--;
                }
                idx++;
            }
        }
        sumExtra = N;
    }

    // Assign extra incoming edges
    vector<int> outgoingB(N);
    int cursor = 0;
    for (int i = 0; i < N; ++i) {
        while (cursor < N && extraIncoming[cursor] == 0) cursor++;
        if (cursor >= N) {
            cursor = 0;
            while (cursor < N && extraIncoming[cursor] == 0) cursor++;
        }
        if (cursor >= N) {
            outgoingB[i] = (i + 1) % N;
        } else {
            outgoingB[i] = cursor;
            extraIncoming[cursor]--;
        }
    }

    for (int i = 0; i < N; ++i) {
        cout << outgoingA[i] << " " << outgoingB[i] << "\n";
    }

    return 0;
}

