#include "CodeGenTarget.h"
#include "TableGenBackends.h"
#include "WebAssemblyDisassemblerEmitter.h"
#include "X86DisassemblerTables.h"
#include "X86RecognizableInstr.h"
#include "llvm/TableGen/Error.h"
#include "llvm/TableGen/Record.h"
#include "llvm/TableGen/TableGenBackend.h"

using namespace llvm;
using namespace llvm::X86Disassembler;

/// Disassembler table generation logic for multiple architectures.
/// X86-specific disassembler implementation details follow.
///
/// *** IF YOU'RE INVESTIGATING A "Primary decode conflict", SEE THE SECTION
///     NEAR THE END OF THIS COMMENT BLOCK!
///
/// This module is responsible for constructing the tables used by the X86
/// disassembler at runtime. These tables are generated from LLVM's target
/// description files (.td) and are described in detail below:
///
/// - CONTEXTS_SYM: Maps attribute masks to instruction contexts. Many
///   instructions decode identically regardless of certain prefixes or modes,
///   so this mapping reduces redundancy and saves space.
/// - Opcode hierarchy tables (ONEBYTE_SYM, TWOBYTE_SYM, THREEBYTE38_SYM, etc.)
///   form a trie-like structure guiding the decoder step-by-step toward an
///   instruction UID — a unique 16-bit identifier per instruction.
/// - INSTRUCTIONS_SYM: Stores operand metadata and decoding info for each UID.
///
/// When conflicts arise during table construction (setTableFields(),
/// X86DisassemblerTables.cpp), they are resolved using these rules:
///
/// - Native-context instructions take precedence over non-native ones.
/// - Among non-native instructions, the more specific context wins
///   (determined via outranks() in X86DisassemblerTables.cpp).
/// - If both have native context → fatal error: primary decode conflict.
///
/// *** HOW TO FIX "Primary decode conflict" ERRORS
///
/// In order of likelihood, typical fixes include:
///
/// (1) Exclude one conflicting instruction via filter() in
///     X86RecognizableInstr.cpp — most common fix. Verify against Intel docs
///     before proceeding.
/// (2) Correct opcode definitions in .td files (e.g., X86.td) if they’re
///     inaccurate.
/// (3) Adjust required context attributes or introduce new contexts in
///     include/llvm/Support/X86DisassemblerDecoderCommon.h — rare.
///
/// Key files involved:
/// - DisassemblerEmitter.cpp: Main entry point; orchestrates instruction processing.
/// - X86DisassemblerTables.h/.cpp: Table management and emission logic.
/// - X86ModRMFilters.h: Filters for valid ModR/M encodings.
/// - X86RecognizableInstr.h/.cpp: Per-instruction translation logic.
static void EmitDisassembler(RecordKeeper &Data, raw_ostream &Out) {
  CodeGenTarget Arch(Data);
  emitSourceFileHeader(" * " + Arch.getName().str() + " Disassembler", Out);

  // Special handling for architectures with custom disassemblers
  if (Arch.getName() == "X86") {
    DisassemblerTables Tables;
    ArrayRef<const CodeGenInstruction*> instrList =
      Arch.getInstructionsByEnumValue();
    for (size_t idx = 0, total = instrList.size(); idx != total; ++idx)
      RecognizableInstr::processInstr(Tables, *instrList[idx], idx);

    if (Tables.hasConflicts()) {
      PrintError(Arch.getTargetRecord()->getLoc(), "Primary decode conflict");
      return;
    }
    Tables.emit(Out);
    return;
  }

  if (Arch.getName() == "WebAssembly") {
    emitWebAssemblyDisassemblerTables(Out, Arch.getInstructionsByEnumValue());
    return;
  }

  std::string PredicatePrefix = Arch.getName().str();
  if (PredicatePrefix == "Thumb")
    PredicatePrefix = "ARM";

  EmitDecoder(Data, Out, PredicatePrefix);
}

static TableGen::Emitter::Opt GenDisassembler("gen-disassembler",
                                              EmitDisassembler,
                                              "Generate disassembler tables");

