class AdvanceSearchTableViewTest : public PlainTestSuite {
  Q_OBJECT
 public:
 private slots:
  void test_1() {
    // Prepare test data: three entries with varying attributes
    QList<FsNodeEntry> testEntries{
        {"document1.txt", false, "alice wonderland"},
        {"document2.txt", true, "Alice WONDERLAND"},
        {"subdirectory", true, ""},
    };

    TDir tempDir;
    QCOMPARE(tempDir.createEntries(testEntries), static_cast<int>(testEntries.size()));
    QString basePath = tempDir.path();
    QVERIFY(QFileInfo(basePath).isDir());

    AdvanceSearchModel dataModel;
    dataModel.initFilter(QDir::Filter::Dirs | QDir::Filter::Files | QDir::Filter::NoDotAndDotDot);
    dataModel.initIteratorFlag(QDirIterator::IteratorFlag::Subdirectories);
    dataModel.setRootPath(basePath);

    SearchProxyModel proxyModel;
    proxyModel.initSearchMode(SearchTools::SearchModeE::NORMAL);
    proxyModel.initNameFilterDisables(false);  // bGrayorHide: hide
    proxyModel.initFileNameFiltersCaseSensitive(Qt::CaseSensitivity::CaseInsensitive);
    proxyModel.initFileContentsCaseSensitive(Qt::CaseSensitivity::CaseInsensitive);

    AdvanceSearchTableView view{&dataModel, &proxyModel};
    dataModel.setRootPath(basePath);

    // Test 1: Filtering works correctly
    proxyModel.startFilterWhenTextChanged("document", "ALICE");
    QCOMPARE(proxyModel.rowCount(), 2); // Expected to match two files

    { // Test 2: Copy/cut operations on selected items
      view.selectAll();
      QModelIndexList selectedRows = view.selectionModel()->selectedRows(0);
      QCOMPARE(selectedRows.size(), 2);

      auto mimeData = MimeDataHelper::GetMimeDataMemberFromSearchModel(dataModel, proxyModel, selectedRows);
      QCOMPARE(mimeData.texts.size(), 2);
      QCOMPARE(mimeData.urls.size(), 2);
      QCOMPARE(mimeData.srcIndexes.size(), 2);

      const QString expectedPaths = mimeData.texts.join('\n');
      QCOMPARE(expectedPaths.count("document1.txt"), 1);
      QCOMPARE(expectedPaths.count("document2.txt"), 1);
      QCOMPARE(expectedPaths.count("\n"), 1);

      // Perform cut operation
      QVERIFY(MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(dataModel, mimeData.srcIndexes, Qt::DropAction::MoveAction));
      QCOMPARE(dataModel.mCutIndexes.isEmpty(), false);
      QCOMPARE(dataModel.mCopyIndexes.isEmpty(), true);

      // Perform copy operation
      QVERIFY(MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(dataModel, mimeData.srcIndexes, Qt::DropAction::CopyAction));
      QCOMPARE(dataModel.mCutIndexes.isEmpty(), true);
      QCOMPARE(dataModel.mCopyIndexes.isEmpty(), false);

      // Attempt unsupported action (LinkAction)
      QVERIFY(!MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(dataModel, mimeData.srcIndexes, Qt::DropAction::LinkAction));
      QCOMPARE(dataModel.mCutIndexes.isEmpty(), true);
      QCOMPARE(dataModel.mCopyIndexes.isEmpty(), false);
    }

    // Test 3: Delete functionality
    view.clearSelection();

    QSignalSpy trashSignalSpy(FileOpActs::GetInst().MOVE_TO_TRASHBIN,
                              &QAction::triggered);

    // No selection -> no action triggered
    QKeyEvent deletePress{QEvent::KeyPress, Qt::Key_Delete, Qt::NoModifier, QString(), false, 1};
    view.keyPressEvent(&deletePress);
    QCOMPARE(trashSignalSpy.count(), 0);

    // Select all and press delete
    view.selectAll();
    view.keyPressEvent(&deletePress);
    QCOMPARE(trashSignalSpy.count(), 1);
  }
};

