#include <search.h>
#include <string.h>

// Linear search implementation - finds or inserts element
void *linear_search(const void *target, void *array, size_t *count, size_t element_size,
	int (*compare_func)(const void *, const void *))
{
	char (*elements)[element_size] = (char *)array;
	size_t num_elements = *count;
	size_t index;

	// Search for existing element
	for (index = 0; index < num_elements; index++) {
		if (compare_func(target, elements[index]) == 0) {
			return elements[index];
		}
	}

	// Element not found, add it
	*count = num_elements + 1;
	return memcpy(elements[num_elements], target, element_size);
}

// Linear find implementation - only searches without insertion
void *linear_find(const void *target, const void *array, size_t *count,
	size_t element_size, int (*compare_func)(const void *, const void *))
{
	const char (*elements)[element_size] = (const char *)array;
	size_t num_elements = *count;
	size_t index;

	for (index = 0; index < num_elements; index++) {
		if (compare_func(target, elements[index]) == 0) {
			return (void *)elements[index];
		}
	}

	return NULL;
}

