// Compiler selects appropriate overload depending on whether object is const or not
struct B {
    void g() {
        cout << "Non-const g()" << endl;
    }
    void g() const {
        cout << "Const g()" << endl;
    }
};

void process1(B& b) {
    b.g(); // Calls non-const version
}

void process2(const B& b) {
    b.g(); // Calls const version
}

int main() {
    B instance;
    instance.g(); // Non-const g()

    const B constInstance;
    constInstance.g(); // Const g()

    process1(instance);
    process2(instance);

    return 0;
}

