constexpr GLuint BUFFER_NUM = 32;
constexpr GLsizeiptr BUFFER_CAPACITY = 1024 * 1024;

static void BM_GenerateAndDeleteBuffers(benchmark::State& state) {
    GLuint count = static_cast<GLuint>(state.range(0));
    int loopCount = static_cast<int>(state.range(1));
    std::vector<GLuint> bufferList(count);

    for (auto _ : state) {
        for (int j = 0; j < loopCount; j++) {
            GenBuffers(count, bufferList.data());
            DeleteBuffers(count, bufferList.data());
        }
    }
    state.SetItemsProcessed(state.iterations() * loopCount * count);
}

BENCHMARK(BM_GenerateAndDeleteBuffers)
    ->Args({128, 5})
    ->Args({1024, 10})
    ->Args({1536, 16})
    ->Args({2048, 32})
    ->Unit(benchmark::kMillisecond)
    ->UseRealTime();

static void BM_CreateBufferObjectsAndBindBuffer(benchmark::State& state) {
    GLuint bufferArray[BUFFER_NUM];
    GenBuffers(BUFFER_NUM, bufferArray);

    for (auto _ : state) {
        for (GLuint idx = 0; idx < BUFFER_NUM; idx++) {
            GLenum usageType = (idx % 2 == 0) ? GL_ARRAY_BUFFER : GL_UNIFORM_BUFFER;
            BindBuffer(usageType, bufferArray[idx]);
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_NUM);
    DeleteBuffers(BUFFER_NUM, bufferArray);
}

BENCHMARK(BM_CreateBufferObjectsAndBindBuffer)->Unit(benchmark::kMillisecond)->UseRealTime();

static void BM_DeleteBufferObjects(benchmark::State& state) {
    Initialize();
    std::vector<GLuint> bufferVec(BUFFER_NUM);

    for (auto _ : state) {
        state.PauseTiming();
        GenBuffers(BUFFER_NUM, bufferVec.data());

        for (GLuint k = 0; k < BUFFER_NUM; k++) {
            GLenum usageType = (k % 2 == 0) ? GL_ARRAY_BUFFER : GL_UNIFORM_BUFFER;
            BindBuffer(usageType, bufferVec[k]);
        }

        state.ResumeTiming();
        DeleteBuffers(BUFFER_NUM, bufferVec.data());
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_NUM);
}

BENCHMARK(BM_DeleteBufferObjects)->Unit(benchmark::kMillisecond)->UseRealTime();

static void BM_UpdateData(benchmark::State& state) {
    GLuint bufferArray[BUFFER_NUM];
    GenBuffers(BUFFER_NUM, bufferArray);

    for (GLuint i = 0; i < BUFFER_NUM; i++)
        BindBuffer(GL_ARRAY_BUFFER, bufferArray[i]);

    std::vector<char> fillData(BUFFER_CAPACITY, 0);

    for (auto _ : state) {
        for (GLuint j = 0; j < BUFFER_NUM; j++) {
            BindBuffer(GL_ARRAY_BUFFER, bufferArray[j]);
            BufferData(GL_ARRAY_BUFFER, BUFFER_CAPACITY, fillData.data(), GL_STATIC_DRAW);
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_NUM);
    DeleteBuffers(BUFFER_NUM, bufferArray);
}

BENCHMARK(BM_UpdateData)->Unit(benchmark::kMillisecond)->UseRealTime();

static void BM_MapBuffer(benchmark::State& state) {
    GLuint bufferArray[BUFFER_NUM];
    GenBuffers(BUFFER_NUM, bufferArray);

    for (GLuint i = 0; i < BUFFER_NUM; i++)
        BindBuffer(GL_ARRAY_BUFFER, bufferArray[i]);

    std::vector<char> tempData(BUFFER_CAPACITY, 0);

    for (auto _ : state) {
        for (GLuint j = 0; j < BUFFER_NUM; j++) {
            BindBuffer(GL_ARRAY_BUFFER, bufferArray[j]);
            BufferData(GL_ARRAY_BUFFER, BUFFER_CAPACITY, tempData.data(), GL_DYNAMIC_DRAW);

            void* mappedPtr = MapBuffer(GL_ARRAY_BUFFER, GL_WRITE_ONLY);
            if (mappedPtr) {
                memset(mappedPtr, 1, BUFFER_CAPACITY);
                UnmapBuffer(GL_ARRAY_BUFFER);
            }
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_NUM);
    DeleteBuffers(BUFFER_NUM, bufferArray);
}

BENCHMARK(BM_MapBuffer)->Unit(benchmark::kMillisecond)->UseRealTime();

static void BM_CopyBufferSubData(benchmark::State& state) {
    GLuint bufferArray[BUFFER_NUM];
    GenBuffers(BUFFER_NUM, bufferArray);

    std::vector<char> dummyData(BUFFER_CAPACITY, 0);

    for (GLuint i = 0; i < BUFFER_NUM; i++) {
        GLenum bufferTarget = (i % 2 == 0) ? GL_COPY_READ_BUFFER : GL_COPY_WRITE_BUFFER;
        BindBuffer(bufferTarget, bufferArray[i]);
        BufferData(bufferTarget, BUFFER_CAPACITY, dummyData.data(), GL_STATIC_DRAW);
    }

    for (auto _ : state) {
        for (GLuint i = 0; i < BUFFER_NUM; i += 2) {
            BindBuffer(GL_COPY_READ_BUFFER, bufferArray[i]);
            BindBuffer(GL_COPY_WRITE_BUFFER, bufferArray[i + 1]);
            CopyBufferSubData(GL_COPY_READ_BUFFER, GL_COPY_WRITE_BUFFER, 0, 0, BUFFER_CAPACITY);
        }
    }

    state.SetItemsProcessed(state.iterations() * (BUFFER_NUM / 2));
    DeleteBuffers(BUFFER_NUM, bufferArray);
}

BENCHMARK(BM_CopyBufferSubData)->Unit(benchmark::kMillisecond)->UseRealTime();

static void BM_UpdateDataPartially(benchmark::State& state) {
    std::vector<GLuint> bufferList(BUFFER_NUM);
    std::vector<char> partialData(BUFFER_CAPACITY / 10, 1);

    GenBuffers(BUFFER_NUM, bufferList.data());

    for (GLuint i = 0; i < BUFFER_NUM; i++) {
        BindBuffer(GL_ARRAY_BUFFER, bufferList[i]);
        BufferData(GL_ARRAY_BUFFER, BUFFER_CAPACITY, nullptr, GL_DYNAMIC_DRAW);
    }

    for (auto _ : state) {
        for (GLuint i = 0; i < BUFFER_NUM; i++) {
            BindBuffer(GL_ARRAY_BUFFER, bufferList[i]);
            BufferSubData(GL_ARRAY_BUFFER, BUFFER_CAPACITY / 2, partialData.size(), partialData.data());
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_NUM);
    DeleteBuffers(BUFFER_NUM, bufferList.data());
}

BENCHMARK(BM_UpdateDataPartially)->Unit(benchmark::kMillisecond)->UseRealTime();

int main(int argc, char** argv) {
    Initialize();
    benchmark ::MaybeReenterWithoutASLR(argc, argv);

    char arg0_default[] = "benchmark";
    char* args_default = reinterpret_cast<char*>(arg0_default);

    if (!argv) {
        argc = 1;
        argv = &args_default;
    }

    ::benchmark ::Initialize(&argc, argv);
    if (::benchmark ::ReportUnrecognizedArguments(argc, argv)) return 1;
    ::benchmark ::RunSpecifiedBenchmarks();
    ::benchmark ::Shutdown();
    return 0;
}

