using namespace llvm;

/// Locate KV in array using binary search.
template <typename T>
static const T *Search(StringRef Key, ArrayRef<T> Table) {
  // Perform binary search on the array
  auto It = llvm::lower_bound(Table, Key);
  // If not found then return NULL
  if (It == Table.end() || StringRef(It->Key) != Key) return nullptr;
  // Return the found array item
  return It;
}

/// For each feature that is (transitively) implied by this feature, set it.
static void PropagateFeatures(FeatureBitset &Set, const FeatureBitset &Implies,
                              ArrayRef<SubtargetFeatureKV> Features) {
  // Combine the Implies bits into Set outside the loop. This allows the Implies for CPUs
  // which might imply features not in Features to use this approach.
  Set |= Implies;
  for (const SubtargetFeatureKV &Item : Features)
    if (Implies.test(Item.Value))
      PropagateFeatures(Set, Item.Implies.getAsBitset(), Features);
}

/// For each feature that (transitively) implies this feature, clear it.
static void RemoveImpliedFeatures(FeatureBitset &Set, unsigned Id,
                                  ArrayRef<SubtargetFeatureKV> Features) {
  for (const SubtargetFeatureKV &Item : Features) {
    if (Item.Implies.getAsBitset().test(Id)) {
      Set.reset(Item.Value);
      RemoveImpliedFeatures(Set, Item.Value, Features);
    }
  }
}

static void ProcessFeatureFlag(FeatureBitset &Set, StringRef Feature,
                               ArrayRef<SubtargetFeatureKV> Features) {
  assert(SubtargetFeatures::hasFlag(Feature) &&
         "Feature flags should start with '+' or '-'");
  // Locate feature in table.
  const SubtargetFeatureKV *Entry =
      Search(SubtargetFeatures::StripFlag(Feature), Features);
  // If there is a match
  if (Entry) {
    // Enable/disable feature in Set
    if (SubtargetFeatures::isEnabled(Feature)) {
      Set.set(Entry->Value);
      // For each feature that this implies, propagate it.
      PropagateFeatures(Set, Entry->Implies.getAsBitset(), Features);
    } else {
      Set.reset(Entry->Value);
      // For each feature that implies this, remove it.
      RemoveImpliedFeatures(Set, Entry->Value, Features);
    }
  } else {
    errs() << "'" << Feature << "' is not a recognized feature for this target"
           << " (ignoring feature)\n";
  }
}

/// Return the length of the longest entry in the table.
template <typename T>
static size_t GetMaxKeyLength(ArrayRef<T> Table) {
  size_t MaxLen = 0;
  for (auto &Item : Table)
    MaxLen = std::max(MaxLen, std::strlen(Item.Key));
  return MaxLen;
}

/// Display help for feature and mcpu choices.
static void ShowHelp(ArrayRef<SubtargetSubTypeKV> CPUTable,
                     ArrayRef<SubtargetFeatureKV> FeatTable) {
  // the static variable ensures that the help information only gets
  // printed once even though a target machine creates multiple subtargets
  static bool Printed = false;
  if (Printed) {
    return;
  }
  // Determine the length of the longest CPU and Feature entries.
  unsigned MaxCPULen  = GetMaxKeyLength(CPUTable);
  unsigned MaxFeatLen = GetMaxKeyLength(FeatTable);
  // Print the CPU table.
  errs() << "Available CPUs for this target:\n\n";
  for (auto &CPU : CPUTable)
    errs() << format("  %-*s - Select the %s processor.\n", MaxCPULen, CPU.Key,
                     CPU.Key);
  errs() << '\n';
  // Print the Feature table.
  errs() << "Available features for this target:\n\n";
  for (auto &Feature : FeatTable)
    errs() << format("  %-*s - %s.\n", MaxFeatLen, Feature.Key, Feature.Desc);
  errs() << '\n';
  errs() << "Use +feature to enable a feature, or -feature to disable it.\n"
            "For example, llc -mcpu=mycpu -mattr=+feature1,-feature2\n";
  Printed = true;
}

/// Display help for mcpu choices only
static void ShowCPUHelp(ArrayRef<SubtargetSubTypeKV> CPUTable) {
  // the static variable ensures that the help information only gets
  // printed once even though a target machine creates multiple subtargets
  static bool Printed = false;
  if (Printed) {
    return;
  }
  // Print the CPU table.
  errs() << "Available CPUs for this target:\n\n";
  for (auto &CPU : CPUTable)
    errs() << "\t" << CPU.Key << "\n";
  errs() << '\n';
  errs() << "Use -mcpu or -mtune to specify the target's processor.\n"
            "For example, clang --target=aarch64-unknown-linux-gnu "
            "-mcpu=cortex-a35\n";
  Printed = true;
}

static FeatureBitset CollectFeatures(StringRef CPU, StringRef TuneCPU, StringRef FS,
                                     ArrayRef<SubtargetSubTypeKV> ProcDesc,
                                     ArrayRef<SubtargetFeatureKV> ProcFeatures) {
  SubtargetFeatures UserFeatures(FS);
  if (ProcDesc.empty() || ProcFeatures.empty())
    return FeatureBitset();
  assert(llvm::is_sorted(ProcDesc) && "CPU table is not sorted");
  assert(llvm::is_sorted(ProcFeatures) && "CPU features table is not sorted");
  // Resulting bits
  FeatureBitset Bits;
  // Check if help is needed
  if (CPU == "help")
    ShowHelp(ProcDesc, ProcFeatures);
  // Find CPU entry if CPU name is specified.
  else if (!CPU.empty()) {
    const SubtargetSubTypeKV *CPUEntry = Search(CPU, ProcDesc);
    // If there is a match
    if (CPUEntry) {
      // Set the features implied by this CPU feature, if any.
      PropagateFeatures(Bits, CPUEntry->Implies.getAsBitset(), ProcFeatures);
    } else {
      errs() << "'" << CPU << "' is not a recognized processor for this target"
             << " (ignoring processor)\n";
    }
  }
  if (!TuneCPU.empty()) {
    const SubtargetSubTypeKV *CPUEntry = Search(TuneCPU, ProcDesc);
    // If there is a match
    if (CPUEntry) {
      // Set the features implied by this CPU feature, if any.
      PropagateFeatures(Bits, CPUEntry->TuneImplies.getAsBitset(), ProcFeatures);
    } else if (TuneCPU != CPU) {
      errs() << "'" << TuneCPU << "' is not a recognized processor for this "
             << "target (ignoring processor)\n";
    }
  }
  // Iterate through each feature
  for (const std::string &Feature : UserFeatures.getFeatures()) {
    // Check for help
    if (Feature == "+help")
      ShowHelp(ProcDesc, ProcFeatures);
    else if (Feature == "+cpuhelp")
      ShowCPUHelp(ProcDesc);
    else
      ProcessFeatureFlag(Bits, Feature, ProcFeatures);
  }
  return Bits;
}

void MCSubtargetInfo::InitMCProcessorInfo(StringRef CPU, StringRef TuneCPU,
                                          StringRef FS) {
  FeatureBits = CollectFeatures(CPU, TuneCPU, FS, ProcDesc, ProcFeatures);
  FeatureString = std::string(FS);
  if (!TuneCPU.empty())
    CPUSchedModel = &getSchedModelForCPU(TuneCPU);
  else
    CPUSchedModel = &MCSchedModel::Default;
}

void MCSubtargetInfo::setDefaultFeatures(StringRef CPU, StringRef TuneCPU,
                                         StringRef FS) {
  FeatureBits = CollectFeatures(CPU, TuneCPU, FS, ProcDesc, ProcFeatures);
  FeatureString = std::string(FS);
}

MCSubtargetInfo::MCSubtargetInfo(const Triple &TT, StringRef C, StringRef TC,
                                 StringRef FS, ArrayRef<SubtargetFeatureKV> PF,
                                 ArrayRef<SubtargetSubTypeKV> PD,
                                 const MCWriteProcResEntry *WPR,
                                 const MCWriteLatencyEntry *WL,
                                 const MCReadAdvanceEntry *RA,
                                 const InstrStage *IS, const unsigned *OC,
                                 const unsigned *FP)
    : TargetTriple(TT), CPU(std::string(C)), TuneCPU(std::string(TC)),
      ProcFeatures(PF), ProcDesc(PD), WriteProcResTable(WPR),
      WriteLatencyTable(WL), ReadAdvanceTable(RA), Stages(IS),
      OperandCycles(OC), ForwardingPaths(FP) {
  InitMCProcessorInfo(CPU, TuneCPU, FS);
}

FeatureBitset MCSubtargetInfo::ToggleFeature(uint64_t FB) {
  FeatureBits.flip(FB);
  return FeatureBits;
}

FeatureBitset MCSubtargetInfo::ToggleFeature(const FeatureBitset &FB) {
  FeatureBits ^= FB;
  return FeatureBits;
}

FeatureBitset MCSubtargetInfo::SetFeatureBitsTransitively(
  const FeatureBitset &FB) {
  PropagateFeatures(FeatureBits, FB, ProcFeatures);
  return FeatureBits;
}

FeatureBitset MCSubtargetInfo::ClearFeatureBitsTransitively(
  const FeatureBitset &FB) {
  for (unsigned I = 0, E = FB.size(); I < E; I++) {
    if (FB[I]) {
      FeatureBits.reset(I);
      RemoveImpliedFeatures(FeatureBits, I, ProcFeatures);
    }
  }
  return FeatureBits;
}

FeatureBitset MCSubtargetInfo::ToggleFeature(StringRef Feature) {
  // Locate feature in table.
  const SubtargetFeatureKV *Entry =
      Search(SubtargetFeatures::StripFlag(Feature), ProcFeatures);
  // If there is a match
  if (Entry) {
    if (FeatureBits.test(Entry->Value)) {
      FeatureBits.reset(Entry->Value);
      // For each feature that implies this, remove it.
      RemoveImpliedFeatures(FeatureBits, Entry->Value, ProcFeatures);
    } else {
      FeatureBits.set(Entry->Value);
      // For each feature that this implies, propagate it.
      PropagateFeatures(FeatureBits, Entry->Implies.getAsBitset(),
                        ProcFeatures);
    }
  } else {
    errs() << "'" << Feature << "' is not a recognized feature for this target"
           << " (ignoring feature)\n";
  }
  return FeatureBits;
}

FeatureBitset MCSubtargetInfo::ApplyFeatureFlag(StringRef FS) {
  ::ProcessFeatureFlag(FeatureBits, FS, ProcFeatures);
  return FeatureBits;
}

bool MCSubtargetInfo::checkFeatures(StringRef FS) const {
  SubtargetFeatures T(FS);
  FeatureBitset Set, All;
  for (std::string F : T.getFeatures()) {
    ::ProcessFeatureFlag(Set, F, ProcFeatures);
    if (F[0] == '-')
      F[0] = '+';
    ::ProcessFeatureFlag(All, F, ProcFeatures);
  }
  return (FeatureBits & All) == Set;
}

const MCSchedModel &MCSubtargetInfo::getSchedModelForCPU(StringRef CPU) const {
  assert(llvm::is_sorted(ProcDesc) &&
         "Processor machine model table is not sorted");
  // Locate entry
  const SubtargetSubTypeKV *CPUEntry = Search(CPU, ProcDesc);
  if (!CPUEntry) {
    if (CPU != "help") // Don't error if the user asked for help.
      errs() << "'" << CPU
             << "' is not a recognized processor for this target"
             << " (ignoring processor)\n";
    return MCSchedModel::Default;
  }
  assert(CPUEntry->SchedModel && "Missing processor SchedModel value");
  return *CPUEntry->SchedModel;
}

InstrItineraryData
MCSubtargetInfo::getInstrItineraryForCPU(StringRef CPU) const {
  const MCSchedModel &SchedModel = getSchedModelForCPU(CPU);
  return InstrItineraryData(SchedModel, Stages, OperandCycles, ForwardingPaths);
}

void MCSubtargetInfo::initInstrItins(InstrItineraryData &InstrItins) const {
  InstrItins = InstrItineraryData(getSchedModel(), Stages, OperandCycles,
                                  ForwardingPaths);
}

