#include "testlib.h"
#include <bits/stdc++.h>

int main(int argc, char ** argv) {
    registerInteraction(argc, argv);
    std::cout.setf(std::ios::fixed);
    std::cout.precision(20);

    int size = inf.readInt();
    println(size);

    std::vector<int> coeffsA(size);
    for (int idx = 0; idx < size; idx++) {
        coeffsA[idx] = inf.readInt();
    }

    std::vector<int> coeffsB(size);
    for (int idx = 0; idx < size; idx++) {
        coeffsB[idx] = inf.readInt();
    }

    for (int queryCount = 0; queryCount <= 10000; queryCount++) {
        std::string action = ouf.readToken();

        if (action == "?") {
            long double varX = ouf.readDouble();
            if (!std::isfinite(varX) || varX < -1e12 || varX > 1e12) {
                quitf(_wa, "Invalid query: element %.4f is out of range [-1000000000000, 1000000000000]", varX);
            }

            long double varY = ouf.readDouble();
            if (!std::isfinite(varY) || varY < -1e12 || varY > 1e12) {
                quitf(_wa, "Invalid query: element %.4f is out of range [-1000000000000, 1000000000000]", varY);
            }

            long double total = 0;
            for (int index = 0; index < size; index++) {
                total += std::abs(coeffsA[index] * varX - varY + coeffsB[index]) / 
                         std::sqrt(coeffsA[index] * coeffsA[index] + 1);
            }
            std::cout << total << std::endl;
        } 
        else if (action == "!") {
            std::vector<int> guessA(size);
            for (int index = 0; index < size; index++) {
                guessA[index] = ouf.readInt();
            }

            std::vector<int> guessB(size);
            for (int index = 0; index < size; index++) {
                guessB[index] = ouf.readInt();
            }

            std::vector<int> order(size);
            std::iota(order.begin(), order.end(), 0);
            std::sort(order.begin(), order.end(), [&](int i, int j) -> bool {
                return std::make_pair(guessA[i], guessB[i]) < std::make_pair(guessA[j], guessB[j]);
            });

            bool correct = true;
            for (int index = 0; index < size; index++) {
                if (guessA[order[index]] != coeffsA[index] || 
                    guessB[order[index]] != coeffsB[index]) {
                    correct = false;
                    break;
                }
            }

            if (!correct) {
                quitp(0., "Wrong guess. Ratio: 0.0000");
            }

            double score = queryCount <= 402 ? 1 : 1 - .7 * (queryCount - 402) / (10000 - 402);
            double unbounded_score = 1 - .7 * (queryCount - 402) / (10000 - 402);
            if (score < 0) score = 0.0;

            quitp(score, "Correct guess. Ratio: %.4f, RatioUnbounded: %.4f", score, unbounded_score);
        } 
        else {
            quitf(_wa, "Invalid action type: expected ? or !, but got %s", action.c_str());
        }
    }

    quitp(0., "Too many queries. Ratio: 0.0000");
    return 0;
}

