unsigned int Opaque::safe_pred(const unsigned int value) {
  if (value <= 0) {
    throw std::logic_error("absurd case");
  } else {
    unsigned int result = value - 1;
    return result;
  }
}

unsigned int Opaque::pred_of_succ(const unsigned int input) {
  return safe_pred((std::move(input) + 1));
}

bool Opaque::nat_eq_dec(const unsigned int n_val, const unsigned int x_val) {
  if (n_val <= 0) {
    if (x_val <= 0) {
      return true;
    } else {
      unsigned int temp_x = x_val - 1;
      return false;
    }
  } else {
    unsigned int n_prev = n_val - 1;
    if (x_val <= 0) {
      return false;
    } else {
      unsigned int x_prev = x_val - 1;
      if (nat_eq_dec(n_prev, x_prev)) {
        return true;
      } else {
        return false;
      }
    }
  }
}

bool Opaque::are_equal(const unsigned int first, const unsigned int second) {
  if (nat_eq_dec(first, second)) {
    return true;
  } else {
    return false;
  }
}

