PrinterWebViewPanel::PrinterWebViewPanel(wxWindow *parent) 
    : wxPanel(parent, wxID_ANY, wxDefaultPosition, wxDefaultSize)
{
    m_layout = new wxBoxSizer(wxVERTICAL);
    SetSizer(m_layout);
    // Initialize webview component
    InitializeWebView();
}

PrinterWebViewPanel::~PrinterWebViewPanel()
{
    // wxWebView destructor handles cleanup as it's a child of this panel
}

void PrinterWebViewPanel::InitializeWebView()
{
    if (m_initialized)
        return;

    m_webview = WebView::webview_new();
    if (m_webview)
    {
        WebView::webview_create(m_webview, this, wxString(""), std::vector<std::string>{});
        m_layout->Add(m_webview, 1, wxEXPAND);
        m_initialized = true;
        Layout();
    }
    else
    {
        BOOST_LOG_TRIVIAL(error) << "PrinterWebViewPanel: Webview creation failed";
    }
}

void PrinterWebViewPanel::NavigateTo(const wxString &url)
{
    if (!m_webview || url.empty())
        return;

    m_target_url = url;
    m_pending_reload = true;

    wxString secured_url = ConstructAuthenticatedURL(url);

    BOOST_LOG_TRIVIAL(info) << "PrinterWebViewPanel: Navigating to URL: " << url.ToStdString();
    m_webview->LoadURL(secured_url);
}

wxString PrinterWebViewPanel::ConstructAuthenticatedURL(const wxString &url)
{
    if (!m_username.empty() && !m_secret.empty())
    {
        wxURI uri(url);
        wxString protocol = uri.GetScheme();
        if (protocol.empty())
            protocol = "http";

        wxString host = uri.GetServer();
        wxString resource_path = uri.GetPath();
        wxString port_part;

        if (uri.HasPort())
            port_part = wxString::Format(":%d", uri.GetPort());

        return wxString::Format("%s://%s:%s@%s%s%s", 
                                protocol, 
                                from_u8(m_username), 
                                from_u8(m_secret), 
                                host, 
                                port_part,
                                resource_path);
    }

    return url;
}

void PrinterWebViewPanel::SetAPIKey(const std::string &key)
{
    m_api_token = key;
    // Note: wxWebView lacks native support for global header injection.
    // Some printer UIs may function without explicit API key headers.
}

void PrinterWebViewPanel::SetLoginInfo(const std::string &user, const std::string &password)
{
    m_username = user;
    m_secret = password;
}

void PrinterWebViewPanel::RefreshView()
{
    if (m_webview)
    {
        if (!m_target_url.empty())
        {
            NavigateTo(m_target_url);
        }
        else
        {
            m_webview->Reload();
        }
    }
}

bool PrinterWebViewPanel::IsReady() const
{
    return m_initialized && m_webview != nullptr;
}

wxString PrinterWebViewPanel::GetActiveURL() const
{
    return m_target_url;
}

void PrinterWebViewPanel::OnBecameVisible()
{
    if (m_pending_reload && m_webview && !m_target_url.empty())
    {
        m_pending_reload = false;
        CallAfter(
            [this]()
            {
                if (m_webview && !m_target_url.empty())
                {
                    wxString auth_url = ConstructAuthenticatedURL(m_target_url);
                    m_webview->LoadURL(auth_url);
                }
            });
    }
}

