int main() {
    pugi::xml_document doc;
    if (!doc.load_file("xgconsole.xml")) return -1;

// tag::code[]
    // Prepare XPath variables for conditional node selection
    pugi::xpath_variable_set variables;
    variables.add("remote", pugi::xpath_type_boolean);
    pugi::xpath_query compiled_query("/Profile/Tools/Tool[@AllowRemote = string($remote)]", &variables);

    // Evaluate query with remote=true
    variables.set("remote", true);
    pugi::xpath_node_set remote_tools = compiled_query.evaluate_node_set(doc);

    // Evaluate query with remote=false
    variables.set("remote", false);
    pugi::xpath_node_set local_tools = compiled_query.evaluate_node_set(doc);

    std::cout << "Remote tool: ";
    remote_tools[2].node().print(std::cout);
    std::cout << "Local tool: ";
    local_tools[0].node().print(std::cout);

    // Direct usage of variables in select_nodes call
    pugi::xpath_node_set immediate_local_tools = doc.select_nodes("/Profile/Tools/Tool[@AllowRemote = string($remote)]", &variables);
    std::cout << "Local tool imm: ";
    immediate_local_tools[0].node().print(std::cout);
// end::code[]
}

