static void verifyPersonCountStar(Connection* conn) {
    auto queryResult = conn->query("MATCH (a:person) RETURN COUNT(*)");
    ASSERT_TRUE(queryResult->hasNext());
    auto row = queryResult->getNext();
    ASSERT_EQ(row->getValue(0)->getValue<int64_t>(), 8);
    ASSERT_FALSE(queryResult->hasNext());
}

TEST_F(ApiTest, BasicConnect) {
    verifyPersonCountStar(conn.get());
}

