#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Represents an interval [leftBound, rightBound] containing 'count' candidates
// 'prevCount' tracks how many candidates exist before leftBound
struct Interval {
    int leftBound;
    int rightBound;
    int count; 
    int prevCount; 
};

// Outputs the answer and terminates execution
void reportAnswer(int pos) {
    cout << "! " << pos << endl;
    exit(0);
}

// Executes a query request and returns results
pair<int, int> makeQuery(int position) {
    cout << "? " << position << endl;
    int leftCount, rightCount;
    if (!(cin >> leftCount >> rightCount)) exit(0);
    if (leftCount == -1) exit(0); // Should not occur per problem constraints
    return {leftCount, rightCount};
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if (!(cin >> size)) return 0;

    int min_cost = 2e9; 
    vector<Interval> intervals;

    // First query at the middle position
    int center = (size - 1) / 2;
    pair<int, int> result = makeQuery(center);
    int current_cost = result.first + result.second;

    if (current_cost == 0) reportAnswer(center);
    min_cost = current_cost;

    // Set up initial intervals based on first query
    // result.first: candidates in [0, center-1]
    // result.second: candidates in [center+1, size-1]
    if (result.first > 0) intervals.push_back({0, center - 1, result.first, 0});
    if (result.second > 0) intervals.push_back({center + 1, size - 1, result.second, result.first});

    while (!intervals.empty()) {
        Interval current = intervals.back();
        intervals.pop_back();

        if (current.leftBound > current.rightBound) continue;

        int mid = (current.leftBound + current.rightBound) / 2;
        pair<int, int> q = makeQuery(mid);
        int cost_at_mid = q.first + q.second;

        if (cost_at_mid == 0) reportAnswer(mid);

        if (cost_at_mid < min_cost) {
            // Found a better solution - update reference point
            min_cost = cost_at_mid;
            intervals.clear();

            // New candidates are those better than mid
            if (q.first > 0) intervals.push_back({0, mid - 1, q.first, 0});
            if (q.second > 0) intervals.push_back({mid + 1, size - 1, q.second, q.first});
        } else {
            // Current position is not better than best known

            // Count candidates in left subinterval [leftBound, mid-1]
            int left_candidates = q.first - current.prevCount;

            // Count candidates in right subinterval [mid+1, rightBound]
            int right_candidates = current.count - left_candidates;

            // Add valid sub-intervals to process
            if (left_candidates > 0) {
                intervals.push_back({current.leftBound, mid - 1, left_candidates, current.prevCount});
            }
            if (right_candidates > 0) {
                // Offset for right interval: previous count plus left candidates
                intervals.push_back({mid + 1, current.rightBound, right_candidates, q.first});
            }
        }
    }

    // Safety fallback - should never reach here due to problem guarantees
    return 0;
}

