namespace double_conversion {

// Computes the normalized exponent by shifting until the hidden bit is set
static int NormalizeExp(uint64_t sig, int exp) {
  DOUBLE_CONVERSION_ASSERT(sig != 0);
  while ((sig & Double::kHiddenBit) == 0) {
    sig <<= 1;
    exp -= 1;
  }
  return exp;
}

// Forward declarations:
// Approximates k such that 10^(k-1) <= value < 10^k
static int PredictExponent(int norm_exp);
// Initializes scaled start values as numerator/denominator ratio
static void SetupStartValues(uint64_t significand,
                             int exponent,
                             bool closer_below,
                             int predicted_power,
                             bool compute_deltas,
                             Bignum* num,
                             Bignum* den,
                             Bignum* delta_lo,
                             Bignum* delta_hi);
// Adjusts scale so that result lies between 1 and 10
static void ScaleToRange1To10(int predicted_power, bool parity_even,
                              int* dec_point,
                              Bignum* num, Bignum* den,
                              Bignum* delta_lo, Bignum* delta_hi);
// Produces digits from left to right until shortest valid decimal form found
static void EmitShortestDecimal(Bignum* num, Bignum* den,
                                Bignum* delta_lo, Bignum* delta_hi,
                                bool even,
                                Vector<char> out_buf, int* out_len);
// Generates fixed number of digits after decimal point
static void ConvertToFixed(int digits_needed, int* dec_point,
                           Bignum* num, Bignum* den,
                           Vector<char> out_buf, int* out_len);
// Emits exactly 'cnt' digits with rounding at the end
static void EmitCountedDigits(int cnt, int* dec_point,
                              Bignum* num, Bignum* den,
                              Vector<char> out_buf, int* out_len);

void BignumDtoa(double val, BignumDtoaMode mode, int requested_digits,
                Vector<char> buffer, int* len, int* decimal_point) {
  DOUBLE_CONVERSION_ASSERT(val > 0);
  DOUBLE_CONVERSION_ASSERT(!Double(val).IsSpecial());
  uint64_t sig;
  int exp;
  bool closer_below;

  if (mode == BIGNUM_DTOA_SHORTEST_SINGLE) {
    float f = static_cast<float>(val);
    DOUBLE_CONVERSION_ASSERT(f == val);
    sig = Single(f).Significand();
    exp = Single(f).Exponent();
    closer_below = Single(f).LowerBoundaryIsCloser();
  } else {
    sig = Double(val).Significand();
    exp = Double(val).Exponent();
    closer_below = Double(val).LowerBoundaryIsCloser();
  }

  bool need_deltas = (mode == BIGNUM_DTOA_SHORTEST || mode == BIGNUM_DTOA_SHORTEST_SINGLE);
  bool parity_even = (sig & 1) == 0;
  int norm_exp = NormalizeExp(sig, exp);
  int pred_pow = PredictExponent(norm_exp);

  // Early exit for Fixed mode when value is too small
  if (mode == BIGNUM_DTOA_FIXED && -pred_pow - 1 > requested_digits) {
    buffer[0] = '\0';
    *len = 0;
    *decimal_point = -requested_digits;
    return;
  }

  Bignum num, den, del_lo, del_hi;
  DOUBLE_CONVERSION_ASSERT(Bignum::kMaxSignificantBits >= 324*4);

  SetupStartValues(sig, exp, closer_below, pred_pow, need_deltas,
                   &num, &den, &del_lo, &del_hi);

  ScaleToRange1To10(pred_pow, parity_even, decimal_point,
                    &num, &den, &del_lo, &del_hi);

  switch (mode) {
    case BIGNUM_DTOA_SHORTEST:
    case BIGNUM_DTOA_SHORTEST_SINGLE:
      EmitShortestDecimal(&num, &den, &del_lo, &del_hi, parity_even, buffer, len);
      break;
    case BIGNUM_DTOA_FIXED:
      ConvertToFixed(requested_digits, decimal_point, &num, &den, buffer, len);
      break;
    case BIGNUM_DTOA_PRECISION:
      EmitCountedDigits(requested_digits, decimal_point, &num, &den, buffer, len);
      break;
    default:
      DOUBLE_CONVERSION_UNREACHABLE();
  }
  buffer[*len] = '\0';
}

// Generates shortest decimal representation by comparing with boundaries
static void EmitShortestDecimal(Bignum* num, Bignum* den,
                                Bignum* del_lo, Bignum* del_hi,
                                bool even,
                                Vector<char> buf, int* len) {
  if (Bignum::Equal(*del_lo, *del_hi)) {
    del_hi = del_lo;
  }
  *len = 0;

  for (;;) {
    uint16_t digit = num->DivideModuloIntBignum(*den);
    DOUBLE_CONVERSION_ASSERT(digit <= 9);
    buf[(*len)++] = static_cast<char>(digit + '0');

    bool below_lo, above_hi;
    if (even) {
      below_lo = Bignum::LessEqual(*num, *del_lo);
    } else {
      below_lo = Bignum::Less(*num, *del_lo);
    }
    if (even) {
      above_hi = Bignum::PlusCompare(*num, *del_hi, *den) >= 0;
    } else {
      above_hi = Bignum::PlusCompare(*num, *del_hi, *den) > 0;
    }

    if (!below_lo && !above_hi) {
      num->Times10();
      del_lo->Times10();
      if (del_lo != del_hi) del_hi->Times10();
    } else if (below_lo && above_hi) {
      int cmp = Bignum::PlusCompare(*num, *num, *den);
      if (cmp < 0) {
        // Round down
      } else if (cmp > 0) {
        DOUBLE_CONVERSION_ASSERT(buf[(*len)-1] != '9');
        buf[(*len)-1]++;
      } else {
        // Halfway case: round to even
        if (((buf[(*len)-1] - '0') % 2) == 0) {
          // Do nothing
        } else {
          DOUBLE_CONVERSION_ASSERT(buf[(*len)-1] != '9');
          buf[(*len)-1]++;
        }
      }
      return;
    } else if (below_lo) {
      return; // Round down
    } else {
      DOUBLE_CONVERSION_ASSERT(buf[(*len)-1] != '9');
      buf[(*len)-1]++;
      return; // Round up
    }
  }
}

// Converts ratio to fixed number of fractional digits
static void EmitCountedDigits(int count, int* dec_point,
                              Bignum* num, Bignum* den,
                              Vector<char> buf, int* len) {
  DOUBLE_CONVERSION_ASSERT(count >= 0);
  for (int i = 0; i < count - 1; ++i) {
    uint16_t digit = num->DivideModuloIntBignum(*den);
    DOUBLE_CONVERSION_ASSERT(digit <= 9);
    buf[i] = static_cast<char>(digit + '0');
    num->Times10();
  }

  uint16_t last_digit = num->DivideModuloIntBignum(*den);
  if (Bignum::PlusCompare(*num, *num, *den) >= 0) {
    last_digit++;
  }
  DOUBLE_CONVERSION_ASSERT(last_digit <= 10);
  buf[count - 1] = static_cast<char>(last_digit + '0');

  // Handle carry propagation
  for (int i = count - 1; i > 0; --i) {
    if (buf[i] != '0' + 10) break;
    buf[i] = '0';
    buf[i - 1]++;
  }
  if (buf[0] == '0' + 10) {
    buf[0] = '1';
    (*dec_point)++;
  }
  *len = count;
}

// Generates requested digits after decimal point, omitting trailing zeros
static void ConvertToFixed(int needed_digits, int* dec_point,
                           Bignum* num, Bignum* den,
                           Vector<char> buf, int* len) {
  if (-(*dec_point) > needed_digits) {
    *dec_point = -needed_digits;
    *len = 0;
    return;
  } else if (-(*dec_point) == needed_digits) {
    DOUBLE_CONVERSION_ASSERT(*dec_point == -needed_digits);
    den->Times10();
    if (Bignum::PlusCompare(*num, *num, *den) >= 0) {
      buf[0] = '1';
      *len = 1;
      (*dec_point)++;
    } else {
      *len = 0;
    }
    return;
  } else {
    int total_digits = (*dec_point) + needed_digits;
    EmitCountedDigits(total_digits, dec_point, num, den, buf, len);
  }
}

// Estimates power of ten using logarithmic approximation
static int PredictExponent(int exponent) {
  const double kInvLog10 = 0.30102999566398114;
  const int kSigSize = Double::kSignificandSize;
  double estimate = ceil((exponent + kSigSize - 1) * kInvLog10 - 1e-10);
  return static_cast<int>(estimate);
}

// Helper functions for initial setup based on exponent sign
static void SetupPosExp(uint64_t sig, int exp,
                        int pred_pow, bool need_deltas,
                        Bignum* num, Bignum* den,
                        Bignum* del_lo, Bignum* del_hi) {
  DOUBLE_CONVERSION_ASSERT(pred_pow >= 0);
  num->AssignUInt64(sig);
  num->ShiftLeft(exp);
  den->AssignPowerUInt16(10, pred_pow);
  if (need_deltas) {
    den->ShiftLeft(1);
    num->ShiftLeft(1);
    del_hi->AssignUInt16(1);
    del_hi->ShiftLeft(exp);
    del_lo->AssignUInt16(1);
    del_lo->ShiftLeft(exp);
  }
}

static void SetupNegExpPosPow(uint64_t sig, int exp,
                              int pred_pow, bool need_deltas,
                              Bignum* num, Bignum* den,
                              Bignum* del_lo, Bignum* del_hi) {
  num->AssignUInt64(sig);
  den->AssignPowerUInt16(10, pred_pow);
  den->ShiftLeft(-exp);
  if (need_deltas) {
    den->ShiftLeft(1);
    num->ShiftLeft(1);
    del_hi->AssignUInt16(1);
    del_lo->AssignUInt16(1);
  }
}

static void SetupNegExpNegPow(uint64_t sig, int exp,
                              int pred_pow, bool need_deltas,
                              Bignum* num, Bignum* den,
                              Bignum* del_lo, Bignum* del_hi) {
  Bignum* tmp_pow = num;
  tmp_pow->AssignPowerUInt16(10, -pred_pow);
  if (need_deltas) {
    del_hi->AssignBignum(*tmp_pow);
    del_lo->AssignBignum(*tmp_pow);
  }
  num->MultiplyByUInt64(sig);
  den->AssignUInt16(1);
  den->ShiftLeft(-exp);
  if (need_deltas) {
    num->ShiftLeft(1);
    den->ShiftLeft(1);
  }
}

// Main initialization dispatcher
static void SetupStartValues(uint64_t sig, int exp,
                             bool closer_below, int pred_pow,
                             bool need_deltas,
                             Bignum* num, Bignum* den,
                             Bignum* del_lo, Bignum* del_hi) {
  if (exp >= 0) {
    SetupPosExp(sig, exp, pred_pow, need_deltas, num, den, del_lo, del_hi);
  } else if (pred_pow >= 0) {
    SetupNegExpPosPow(sig, exp, pred_pow, need_deltas, num, den, del_lo, del_hi);
  } else {
    SetupNegExpNegPow(sig, exp, pred_pow, need_deltas, num, den, del_lo, del_hi);
  }
  if (need_deltas && closer_below) {
    den->ShiftLeft(1);
    num->ShiftLeft(1);
    del_hi->ShiftLeft(1);
  }
}

// Scales numerator/denominator into [1,10) range
static void ScaleToRange1To10(int pred_pow, bool even,
                              int* dec_point,
                              Bignum* num, Bignum* den,
                              Bignum* del_lo, Bignum* del_hi) {
  bool in_range;
  if (even) {
    in_range = Bignum::PlusCompare(*num, *del_hi, *den) >= 0;
  } else {
    in_range = Bignum::PlusCompare(*num, *del_hi, *den) > 0;
  }

  if (in_range) {
    *dec_point = pred_pow + 1;
  } else {
    *dec_point = pred_pow;
    num->Times10();
    if (Bignum::Equal(*del_lo, *del_hi)) {
      del_lo->Times10();
      del_hi->AssignBignum(*del_lo);
    } else {
      del_lo->Times10();
      del_hi->Times10();
    }
  }
}

