#include <asio.hpp>
#include <boost/bind.hpp>
#include <boost/shared_ptr.hpp>
#include <cmath>
#include <cstdlib>
#include <exception>
#include <iostream>
#include <set>
#include "protocol.hpp"

using asio::ip::tcp;
using asio::ip::udp;

typedef boost::shared_ptr<tcp::socket> tcp_socket_ptr;
typedef boost::shared_ptr<asio::steady_timer> timer_ptr;
typedef boost::shared_ptr<control_request> control_request_ptr;

class data_server
{
public:
  // Initialize the server to listen for incoming management connections.
  data_server(asio::io_context& context, unsigned short listening_port)
    : manager_acceptor_(context, tcp::endpoint(tcp::v4(), listening_port)),
      generator_timer_(context),
      broadcast_socket_(context, udp::endpoint(udp::v4(), 0)),
      frame_counter_(1)
  {
    // Prepare to accept a new management connection.
    tcp_socket_ptr client_socket(
        new tcp::socket(manager_acceptor_.get_executor().context()));
    manager_acceptor_.async_accept(*client_socket,
        boost::bind(&data_server::on_accept, this,
          asio::placeholders::error, client_socket));

    // Configure the timer responsible for producing outgoing frames.
    generator_timer_.expires_after(asio::chrono::milliseconds(100));
    generator_timer_.async_wait(boost::bind(&data_server::on_timer, this));
  }

  // Manage a newly established management connection.
  void on_accept(const asio::error_code& error, tcp_socket_ptr socket)
  {
    if (!error)
    {
      // Begin reading a management request from the client.
      control_request_ptr msg(new control_request);
      asio::async_read(*socket, msg->to_buffers(),
          boost::bind(&data_server::on_management_request, this,
            asio::placeholders::error, socket, msg));
    }

    // Ready to accept another management connection.
    tcp_socket_ptr next_client_socket(
        new tcp::socket(manager_acceptor_.get_executor().context()));
    manager_acceptor_.async_accept(*next_client_socket,
        boost::bind(&data_server::on_accept, this,
          asio::placeholders::error, next_client_socket));
  }

  // Process a management request.
  void on_management_request(const asio::error_code& error,
      tcp_socket_ptr socket, control_request_ptr request)
  {
    if (!error)
    {
      // Simulate network delay before processing the request.
      timer_ptr processing_delay(
          new asio::steady_timer(manager_acceptor_.get_executor().context()));
      processing_delay->expires_after(asio::chrono::seconds(2));
      processing_delay->async_wait(
          boost::bind(&data_server::on_delay_complete, this,
            socket, request, processing_delay));
    }
  }

  void on_delay_complete(tcp_socket_ptr socket,
      control_request_ptr request, timer_ptr /*delay*/)
  {
    // Identify the client's address for subscription management.
    asio::error_code ec;
    tcp::endpoint client_endpoint = socket->remote_endpoint(ec);
    if (!ec)
    {
      // Remove previous subscription if present.
      if (unsigned short previous_port = request->old_port())
      {
        udp::endpoint old_subscription(client_endpoint.address(), previous_port);
        active_subscribers_.erase(old_subscription);
        std::cout << "Unsubscribed " << old_subscription << std::endl;
      }

      // Register new subscription if requested.
      if (unsigned short new_port = request->new_port())
      {
        udp::endpoint new_subscription(client_endpoint.address(), new_port);
        active_subscribers_.insert(new_subscription);
        std::cout << "Subscribed " << new_subscription << std::endl;
      }
    }

    // Continue listening for more requests on this connection.
    control_request_ptr next_request(new control_request);
    asio::async_read(*socket, next_request->to_buffers(),
        boost::bind(&data_server::on_management_request, this,
          asio::placeholders::error, socket, next_request));
  }

  // Invoked when the data generation timer fires.
  void on_timer()
  {
    // Synthesize payload data.
    double angle = frame_counter_ * 0.2;
    double value = std::sin(angle);
    int position = static_cast<int>((value + 1.0) * (frame::payload_size / 2));
    std::string data;
    for (int i = 0; i < frame::payload_size; ++i)
      data += (i == position ? 'X' : '-');

    // Build the frame to distribute.
    frame packet(frame_counter_++, data);

    // Dispatch frame to all registered subscribers using synchronous UDP sends.
    for (std::set<udp::endpoint>::iterator it = active_subscribers_.begin();
         it != active_subscribers_.end(); ++it)
    {
      asio::error_code ignore;
      broadcast_socket_.send_to(packet.to_buffers(), *it, 0, ignore);
    }

    // Schedule the next data generation cycle.
    generator_timer_.expires_after(asio::chrono::milliseconds(100));
    generator_timer_.async_wait(boost::bind(&data_server::on_timer, this));
  }

private:
  // Acceptor for incoming management connections.
  tcp::acceptor manager_acceptor_;

  // Timer for periodic data generation.
  asio::steady_timer generator_timer_;

  // UDP socket for broadcasting frames.
  udp::socket broadcast_socket_;

  // Counter for frame numbering.
  unsigned long frame_counter_;

  // Collection of active subscriber endpoints.
  std::set<udp::endpoint> active_subscribers_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: server <port>\n";
      return 1;
    }

    asio::io_context service;
    using namespace std; // For atoi.
    data_server instance(service, atoi(argv[1]));
    service.run();
  }
  catch (std::exception& err)
  {
    std::cerr << "Error: " << err.what() << std::endl;
  }
  return 0;
}

