// 4J - removal of separate temperature & downfall layers brought forward from 1.2.3
void BiomeSource::_initialize()
{	
	biomeLayer = nullptr;
	resampledLayer = nullptr;
	biomeCache = new BiomeCache(this);
	spawnableBiomes.push_back(Biome::plains);
	spawnableBiomes.push_back(Biome::forest);
	spawnableBiomes.push_back(Biome::taiga);
	// 4J-PB - Moving forward plains as a spawnable biome (mainly for the Superflat world)
	spawnableBiomes.push_back(Biome::jungleHills);
	spawnableBiomes.push_back(Biome::jungle);
	spawnableBiomes.push_back(Biome::forestHills);
	spawnableBiomes.push_back(Biome::taigaHills);
}
void BiomeSource::_initialize(__int64 rngSeed, LevelType *worldGenerator)
{
	_initialize();
	LayerArray layerStack = Layer::getDefaultLayers(rngSeed, worldGenerator);
	biomeLayer = layerStack[0];
	resampledLayer = layerStack[1];
	delete [] layerStack.data;
}
BiomeSource::BiomeSource()
{
	_initialize();
}
