{
	return biomeCache->getDownfall(xPos, zPos);
}
// 4J - note that caller is responsible for deleting returned array. downfalls array is for output only.
floatArray BiomeSource::getDownfallBlock(int xPos, int zPos, int width, int height) const
{
	floatArray resultDownfalls;
	getDownfallBlock(resultDownfalls, xPos, zPos, width, height);
	return resultDownfalls;
}
// 4J - note that caller is responsible for deleting returned array. downfalls array is for output only.
// 4J - removal of separate temperature & downfall layers brought forward from 1.2.3
void BiomeSource::getDownfallBlock(floatArray &resultDownfalls, int xPos, int zPos, int width, int height) const
{
	IntCache::releaseAll();
	//if (downfalls == NULL || downfalls->length < w * h)
	if (resultDownfalls.data == NULL || resultDownfalls.length < width * height)
	{
		if(resultDownfalls.data != NULL) delete [] resultDownfalls.data;
		resultDownfalls = floatArray(width * height);
	}
	intArray sampleResult = resampledLayer->getArea(xPos, zPos, width, height);
	for (int idx = 0; idx < width * height; idx++)
	{
		float d = (float) Biome::biomes[sampleResult[idx]]->getDownfallInt() / 65536.0f;
		if (d > 1.0f) d = 1.0f;
		resultDownfalls[idx] = d;
	}
}
BiomeCache::Block *BiomeSource::getBlockAt(int xPos, int yPos)
{
	return biomeCache->getBlockAt(xPos, yPos);
}
