// Constants for Elite Screens protocol timing
const uint16_t kEliteScreensBitHigh = 470;
const uint16_t kEliteScreensBitLow = 1214;
const uint16_t kEliteScreensInterGap = 29200;

#if SEND_ELITESCREENS
/// Transmit an Elite Screens infrared message.
/// Status: BETA / Likely functional.
/// @param[in] payload The data word to be transmitted.
/// @param[in] bitCount Number of bits in the payload.
/// @param[in] repeatCount How many times to repeat the transmission.
void IRsend::sendElitescreens(uint64_t payload, uint16_t bitCount, uint16_t repeatCount) {
  // Uses fixed-time bit encoding without header
  sendGeneric(0, 0,
              kEliteScreensBitHigh, kEliteScreensBitLow,
              kEliteScreensBitLow, kEliteScreensBitHigh,
              0, kEliteScreensInterGap,
              payload, bitCount, 38000, true, repeatCount, 50);
}
#endif

#if DECODE_ELITESCREENS
/// Decode a received Elite Screens infrared message.
/// Status: STABLE / Verified working.
/// @param[in,out] results Pointer to storage for decoded results.
/// @param[in] startIdx Position in raw buffer where decoding should begin.
/// @param[in] expectedBits Expected number of data bits.
/// @param[in] enforceStrict Whether to require exact bit count match.
/// @return True if decoding succeeded, false otherwise.
bool IRrecv::decodeElitescreens(decode_results *results, uint16_t startIdx,
                                const uint16_t expectedBits, const bool enforceStrict) {
  // Validate bit count if strict mode is enabled
  if (enforceStrict && expectedBits != kEliteScreensBits) return false;

  uint64_t decodedData = 0;

  // Parse data field with constant bit timing and no header/footer
  if (!matchGenericConstBitTime(results->rawbuf + startIdx, &decodedData,
                                results->rawlen - startIdx, expectedBits,
                                // Header (none)
                                0, 0,
                                // Data bits
                                kEliteScreensBitHigh, kEliteScreensBitLow,
                                // Footer (none)
                                0, kEliteScreensInterGap, true)) 
    return false;

  // Store decoded information
  results->decode_type = decode_type_t::ELITESCREENS;
  results->bits = expectedBits;
  results->value = decodedData;
  results->address = 0;
  results->command = 0;
  results->repeat = false;
  return true;
}
#endif

