#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <cmath>
using namespace std;

// Simulates the text wrapping process: returns how many lines are needed
// to display words with lengths in 'a' given line width 'W'.
// Returns 0 if any word length exceeds W.
int wrap_lines(const vector<int>& word_lengths, int max_width) {
    int line_count = 1;
    long long current_line_length = 0;

    for (int len : word_lengths) {
        if (len > max_width) return 0;

        if (current_line_length + len <= max_width) {
            current_line_length += len;
        } else {
            line_count++;
            current_line_length = len;
        }
    }
    return line_count;
}

void process_case() {
    const int N = 100000;

    // First query: all words of length 1
    cout << "? " << N;
    for (int i = 0; i < N; ++i) cout << " 1";
    cout << "\n";

    int result1;
    cin >> result1;

    // Handle termination or invalid input
    if (result1 == 0 || result1 == -1) exit(0);

    // Compute bounds for possible W values based on first result
    // k1 = ceil(N / W) => W ∈ [ceil(N/k1), floor((N-1)/(k1-1))] for k1 > 1
    int lower_bound = (N + result1 - 1) / result1;
    int upper_bound;

    if (result1 == 1) {
        upper_bound = 100000;
    } else {
        upper_bound = (N - 1) / (result1 - 1);
    }

    // Clamp to problem constraints
    if (upper_bound > 100000) upper_bound = 100000;
    if (lower_bound > upper_bound) lower_bound = upper_bound;

    // If only one possible value remains, output it directly
    if (lower_bound == upper_bound) {
        cout << "! " << lower_bound << "\n";
        return;
    }

    // Second query: use randomized word lengths in [1, lower_bound]
    mt19937 rng_engine(42); 
    vector<int> lengths(N);
    for (int idx = 0; idx < N; ++idx) {
        lengths[idx] = (rng_engine() % lower_bound) + 1;
    }

    cout << "? " << N;
    for (int idx = 0; idx < N; ++idx) {
        cout << " " << lengths[idx];
    }
    cout << "\n";

    int result2;
    cin >> result2;
    if (result2 == -1) exit(0);

    // Binary search for correct W in [lower_bound, upper_bound]
    // The function wrap_lines is monotonic non-increasing in W
    int final_answer = upper_bound;
    int left = lower_bound, right = upper_bound;

    while (left <= right) {
        int candidate = left + (right - left) / 2;
        int simulated = wrap_lines(lengths, candidate);

        if (simulated == result2) {
            final_answer = candidate;
            break;
        } else if (simulated < result2) {
            // Too few lines means candidate width is too large
            right = candidate - 1;
        } else {
            // Too many lines means candidate width is too small
            left = candidate + 1;
        }
    }

    cout << "! " << final_answer << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            process_case();
        }
    }

    return 0;
}

