    throw std::length_error(msg);
}
/// Report that current vector has reached its maximum possible capacity.
/// Throws std::length_error
void
report_no_more_growth_possible(size_t max_val)
{
    std::string msg =
        "small_vector growth blocked — already at maximum capacity " + std::to_string(max_val);
    throw std::length_error(msg);
}
template <typename IndexT>
size_t
compute_new_capacity(size_t needed, size_t /*elem_size*/, size_t current_capacity)
{
    constexpr size_t max_representable = std::numeric_limits<IndexT>::max();
    // Validate requested capacity fits within index type limits
    if(needed > max_representable) report_capacity_exceeded(needed, max_representable);
    // Guard against overflow when trying to grow an already-maximal vector
    if(current_capacity == max_representable) report_no_more_growth_possible(max_representable);
    // Heuristic: double current capacity and add one to ensure growth
    size_t proposed = (2 * current_capacity) + 1;
    return std::clamp(proposed, needed, max_representable);
}
}  // namespace
template <typename IndexT>
void*
small_vector_base<IndexT>::remap_storage(void*      src_ptr,
                                         size_t     element_width,
                                         size_t     new_slot_count,
                                         size_t     used_slots)
{
    void* dst_ptr = ::malloc(new_slot_count * element_width);
    if(used_slots != 0u) memcpy(dst_ptr, src_ptr, used_slots * element_width);
    free(src_ptr);
    return dst_ptr;
}
// Note: Inlining may impact performance negatively.
template <typename IndexT>
void*
small_vector_base<IndexT>::allocate_expanded(void*   base_addr,
                                             size_t  min_slots,
                                             size_t  elem_size,
                                             size_t& out_capacity)
{
    out_capacity = compute_new_capacity<IndexT>(min_slots, elem_size, this->capacity());
    void* new_buffer = ::malloc(out_capacity * elem_size);
    if(new_buffer == base_addr) new_buffer = remap_storage(new_buffer, elem_size, out_capacity);
    return new_buffer;
}
// Note: Moving this into a header could degrade performance.
template <typename IndexT>
void
small_vector_base<IndexT>::expand_storage(void* inline_storage, size_t min_slots, size_t elem_size)
{
    size_t new_cap = compute_new_capacity<IndexT>(min_slots, elem_size, this->capacity());
    void*  new_mem;
    if(this->m_begin_x == inline_storage)
    {
        new_mem = ::malloc(new_cap * elem_size);
        if(new_mem == inline_storage) new_mem = remap_storage(new_mem, elem_size, new_cap);
        memcpy(new_mem, this->m_begin_x, size() * elem_size);
    }
    else
    {
        new_mem = ::realloc(this->m_begin_x, new_cap * elem_size);
        if(new_mem == inline_storage)
            new_mem = remap_storage(new_mem, elem_size, new_cap, size());
    }
    this->m_begin_x  = new_mem;
    this->m_capacity = new_cap;
}
