#include "../backend/src/QuantumRegister.hpp"
#include <benchmark/benchmark.h>
#include <iostream>

// Benchmark for Hadamard Gate operation to evaluate memory bandwidth usage
static void BM_HadamardOperation(benchmark::State &state) {
  int qubit_count = state.range(0);

  // Initialization: Allocate memory once before the timing loop to exclude
  // allocation overhead from measurements.
  // Note: 28 qubits require 2^28 * 16 bytes ≈ 4 GB of RAM.
  try {
    QuantumRegister reg(qubit_count);

    for (auto _ : state) {
      // Execute the memory-bound operation
      reg.applyHadamard(0);

      // Ensure compiler doesn't optimize away the computation
      benchmark::DoNotOptimize(reg.getStateVector().data());
      benchmark::ClobberMemory();
    }

    // Compute bandwidth metrics for reporting
    // Memory access pattern: Read each element once, write once → 2 × size
    // Each complex amplitude is 16 bytes (double real + double imag)
    // Total data volume = 2 × (2^N) × 16 bytes
    double data_bytes = static_cast<double>(1ULL << qubit_count) * 16.0 * 2.0;
    state.SetBytesProcessed(static_cast<int64_t>(state.iterations()) *
                            static_cast<int64_t>(data_bytes));

  } catch (const std::exception &err) {
    state.SkipWithError("Insufficient memory or allocation failure");
  }
}

// Register benchmarks for different system sizes:
// 20 qubits → 16 MB, 25 qubits → 512 MB, 28 qubits → 4 GB
BENCHMARK(BM_HadamardOperation)
    ->Arg(20)
    ->Arg(25)
    ->Arg(28)
    ->Unit(benchmark::kMillisecond);

BENCHMARK_MAIN();

#include <iostream>
#include <vector>
using namespace std;

class Solution {
public:
    void generateSubsequences(vector<int>& inputArray, vector<int>& currentSubset, int index, vector<vector<int>>& allSubsequences) {
        if (index == inputArray.size()) {
            allSubsequences.push_back(currentSubset);
            return;
        }

        // Include the current element in the subset
        currentSubset.push_back(inputArray[index]);
        generateSubsequences(inputArray, currentSubset, index + 1, allSubsequences);

        // Exclude the current element from the subset
        currentSubset.pop_back();
        generateSubsequences(inputArray, currentSubset, index + 1, allSubsequences);
    }

    vector<vector<int>> findSubsets(vector<int>& elements) {
        vector<vector<int>> resultSubsets;

        vector<int> tempSubset;

        generateSubsequences(elements, tempSubset, 0, resultSubsets);

        return resultSubsets;
    }
};

int main() {
    Solution solver;
    vector<int> numbers = {1, 2, 3};
    vector<vector<int>> output = solver.findSubsets(numbers);

    for (int idx = 0; idx < output.size(); idx++) {
        cout << "{ ";
        for (int pos = 0; pos < output[idx].size(); pos++) {
            cout << output[idx][pos] << " ";
        }
        cout << "}" << endl;
    }

    return 0;
}

