    // Function to load and validate public IP addresses
    static auto ip_address_validator(std::optional<quic::Address>& target, std::string option_name)
    {
        return [&target, option_name = std::move(option_name)](std::string ip_str) {
            try
            {
                quic::Address addr{ip_str, target ? target->port() : uint16_t{8080}};
                if (!addr.is_ipv4())
                    throw std::invalid_argument{"IP must be an IPv4 address"};
                if (!addr.is_public_ip())
                    throw std::invalid_argument{"IP is not publicly accessible"};
                target = std::move(addr);
            }
            catch (const std::exception& e)
            {
                throw std::invalid_argument{"Invalid {}: {}"_format(option_name, e.what())};
            }
        };
    }

