    {
        return [&target, option_name = std::move(option_name)](uint16_t port) {
            if (port == 0)
                throw std::invalid_argument{"{} cannot be zero"_format(option_name)};
            if (!target)
                target.emplace();
            target->set_port(port);
        };
    }

