                    try
                    {
                        std::string input = arg.substr(colon_pos + 1);
                        if (input.find(":") != std::string::npos)  // ipv6
                            range_spec = parse_ipv6_range(input, 128);
                        else
                            range_spec = parse_ipv4_range(input, 32);
                    }
                    catch (const std::exception& e)
                    {
                        throw std::invalid_argument{"[exit]:reserved-block invalid IP range: {}"_format(e.what())};
                    }
                    arg.resize(colon_pos);
                }
                if (is_valid_sns(arg))
                    sns_ranges[arg].push_back(std::move(range_spec));
                else
                {
                    try
                    {
                        ranges[NetworkAddress{arg}].push_back(std::move(range_spec));
                    }
                    catch (const std::exception& e)
                    {
                        throw std::invalid_argument{"[exit]:reserved-block invalid address: {}"_format(arg)};
                    }
                }
            });

        config_def.define_option<std::string>(
            "exit",
            "routed-block",
            FullClientOnly,
            MultiValue,
            Comment{
                "Advertise that this exit node routes traffic to specified IP ranges. Defaults to ALL",
                "public ranges if omitted. Can be set to 'public' for internet routing.",
                "Examples:",
                "    routed-block=10.0.0.0/16",
                "    routed-block=public",
                "to advertise routing to both public internet and 10.0.x.y addresses.",
                "",
                "Note: This doesn't configure actual network routing; that must be done separately.",
            },
            [this](std::string arg) {
                if (arg == "public")
                    exit_policy.ranges.push_back(ipv4{0} / 0);
                else
                {
                    try
                    {
                        if (arg.find(':') != std::string::npos)
                            exit_policy.ranges_v6.push_back(parse_ipv6_range(arg, 128));
                        else
                            exit_policy.ranges.push_back(parse_ipv4_range(arg, 32));
                    }
                    catch (const std::exception& e)
                    {
                        throw std::invalid_argument{"[exit]:routed-block invalid range '{}': {}"_format(arg, e.what())};
                    }
                }
            });
    }

    void NetworkConfig::define_config_options(ConfigDefinition& config_def)
    {
        config_def.add_section_comments(
            "network",
            {
                "Network device and communication settings.",
            });

        config_def.define_option<bool>(
            "network",
            "preserve-profiles",
            Default{config_def.type != config::Type::EmbeddedClient},
            Hidden,
            assignment_acceptor(save_profiles));

        config_def.define_option<bool>("network", "profile-mode", Default{true}, Hidden, assignment_acceptor(enable_profiling));

        config_def.define_option<std::filesystem::path>(
            "network",
            "private-key-file",
            ClientOnly,
            [this, base_path = config_def.conf_dir](std::filesystem::path arg) {
                if (arg.empty())
                {
                    keyfile.reset();
                    return;
                }
                if (arg.is_relative())
                    arg = base_path / arg;
                if (!exists(arg))
                    throw std::invalid_argument{"cannot load key file {}: file missing"_format(arg)};
                log::info(logger, "Client configured to use private key file {}", arg);
                keyfile.emplace(std::move(arg));
            },
            Comment{
                "Path to persistent private key for network identity. Without this, a new random",
                "address is generated on each Session Router restart.",
                "",
                "Use session-router-config to generate such a key file.",
            });

        config_def.define_option<std::string>(
            "network",
            "auth-method",
            FullClientOnly,
            Comment{
                "Set endpoint authentication method.",
                "none/whitelist/lmq/file",
            },
            [this](std::string arg) {
                if (arg == "file")
                    auth_type = auth::AuthType::FILE;
                else if (arg == "lmq" || arg == "omq" || arg == "zmq")
                    auth_type = auth::AuthType::OMQ;
                else if (arg == "whitelist")
                    auth_type = auth::AuthType::WHITELIST;
                else if (arg == "" || arg == "none")
                    auth_type = auth::AuthType::NONE;
                else
                    throw std::invalid_argument{"invalid [network]:auth-method value: '{}'"_format(arg)};
            });

        config_def.define_option<std::string>(
            "network",
            "omq-auth-server",
            FullClientOnly,
            assignment_acceptor(auth_endpoint),
            Comment{
                "OMQ endpoint for authenticating new sessions",
                "ipc:///var/lib/session-router/auth.socket",
                "tcp://127.0.0.1:5555",
            });

        config_def.define_option<std::string>(
            "network",
            "omq-auth-function",
            FullClientOnly,
            Default{"session-router.auth"},
            Comment{
                "OMQ function called for authenticating new sessions",
                "session-router.auth",
            },
            [this](std::string arg) {
                if (arg.empty())
                    return;
                auth_method = std::move(arg);
            });

        config_def.define_option<std::string>(
            "network",
            "access-whitelist",
            FullClientOnly,
            MultiValue,
            Comment{
                "Manually add remote endpoints by PUBKEY.{} address to access whitelist."_format(CLIENT_TLD),
            },
            [this](std::string arg) {
                try
                {
                    auth_whitelist.insert(NetworkAddress{arg});
                }
                catch (const std::exception& e)
                {
                    throw std::invalid_argument{
                        "[network]:access-whitelist: invalid .{} address '{}': {}"_format(CLIENT_TLD, arg, e.what())};
                }
            });

        config_def.define_option<std::filesystem::path>(
            "network",
            "auth-database",
            FullClientOnly,
            MultiValue,
            Comment{
                "Read authentication tokens from file for endpoint authentication",
                "Can be specified multiple times",
            },
            [this, base_path = config_def.conf_dir](std::filesystem::path arg) {
                if (!arg.empty() && arg.is_relative())
                    arg = base_path / arg;
                if (not exists(arg))
                    throw std::invalid_argument{"cannot load auth database {}: file missing"_format(arg)};
                auth_files.push_back(std::move(arg));
            });

        config_def.define_option<std::string>(
            "network",
            "auth-database-format",
            FullClientOnly,
            Comment{
                "Interpretation of auth database contents.",
#ifdef SROUTER_HAVE_CRYPT
                "Possible values: hash, plaintext",
#else
                "Possible values: plaintext",
#endif
            },
            [this](std::string arg) {
                if (arg == "plain" || arg == "plaintext")
                    auth_file_type = auth::AuthFileType::PLAIN;
                else if (arg == "hashed" || arg == "hashes" || arg == "hash")
                {
#ifndef SROUTER_HAVE_CRYPT
                    throw std::invalid_argument{"Hashed auth databases not supported in this build"};
#endif
                    auth_file_type = auth::AuthFileType::HASHES;
                }
                else
                    throw std::invalid_argument{"Invalid auth database type '{}'"_format(arg)};
            });

        config_def.define_option<std::string>(
            "network",
            "static-auth",
            FullClientOnly,
            MultiValue,
            Comment{
                "Manually add static authentication codes for endpoint authentication",
                "Can be specified multiple times",
            },
            [this](std::string arg) { auth_static_tokens.emplace(std::move(arg)); });

        config_def.define_option<bool>(
            "network",
            "publish-service",
            FullClientOnly,
            Default{true},
            assignment_acceptor(is_reachable),
            Comment{
                "Determines whether we publish our service's ClientContact to the network (client default: TRUE)",
            });

        config_def.define_option<bool>(
            "network",
            "automatic-routing",
            FullClientOnly,
            Default{true},
            Comment{
                "Enable/disable automatic route configuration.",
                "When enabled and using an exit, Session Router automatically configures OS routes",
                "to send public internet traffic through the exit node.",
                "Enabled by default but can be disabled for manual exit routing."},
            assignment_acceptor(enable_route_poker));

        config_def.define_option<bool>(
            "network",
            "drop-unmatched",
            FullClientOnly,
            Default{true},
            Comment{
                "Enable/disable route configuration blackholes.",
                "When enabled Session Router drops IPv4/IPv6 traffic (in exit mode) not covered",
                "by exit configuration. Enabled by default."},
            assignment_acceptor(blackhole_routes));

        config_def.define_option<std::string>(
            "network",
            "interface-name",
            NotEmbedded,
            Comment{
                "Interface name for Session Router traffic. If unset, Session Router looks for free names",
                "matching 'sr-tunN', starting at N=0 (e.g. sr-tun0, sr-tun1, ...) for clients; relays default",
                "to sr-tun@XXXXXXXX where XXXXXXXX is first 8 hex digits of Session node pubkey.",
#ifdef __linux__
                "",
                "On Linux, use '%d' in name as pattern for OS to choose unused interface name",
#endif
            },
            assignment_acceptor(_if_name));

        config_def.define_option<std::string>(
            "network",
            "local-address",
            NotEmbedded,
            MultiValue,
            Comment{
                "Private IP and netmask for mapping Session Router traffic to local addresses.",
                "",
                "The IPs (one IPv4, one IPv6) here will be accessed by remote Session Router clients",
                "trying to connect to this instance, while remaining IPs in the range are used",
                "for sending traffic to remote peers.",
                "",
                "Example: 172.16.0.1/16 uses 172.16.0.1 for this instance and 172.16.x.y for remotes.",
                "For IPv6, fd2e:7365:7368::1/64 uses fd2e:7365:7368::1 for this instance.",
                "(These two ranges are defaults if not specified and available).",
                "",
                "This option can be given twice: once for IPv4 and once for IPv6. Omitted ones",
                "will auto-select unused private ranges (/16 for IPv4, /64 for IPv6).",
                "",
                "Zero-address with custom netmask enables auto-detection with custom size:",
                "\"0.0.0.0/10\" auto-detects unused /10 IPv4 range, \"::/56\" looks for unused /56 IPv6.",
                "",
                "If running network daemons for others to connect to (e.g., HTTP), specify explicit",
                "IPv4/IPv6 addresses here and configure servers (like nginx) to listen on them.",
                "If only using Session Router to reach remotes, leave blank for auto-selection.",
            },
            [this](std::string arg) {
                try
                {
                    auto ip_net = parse_ip_net(arg, 16, 64);
                    std::visit(
                        []<typename IPNet>(IPNet& in) {
                            if (in.ip != IPNet{}.ip && in.ip == in.to_range().ip)
                            {
                                if (auto next = in.ip.next_ip(); next and in.contains(*next))
                                {
                                    log::warning(
                                        logger,
                                        "Invalid host IP '{}' in [network]:local-address (network zero address invalid); using '{}' instead",
                                        in.ip,
                                        *next);
                                    in.ip = std::move(*next);
                                }
                            }
                        },
                        ip_net);
                    if (auto* in4 = std::get_if<ipv4_net>(&ip_net))
                    {
                        if (_local_ip_net)
                            throw std::runtime_error{"cannot specify multiple IPv4 addresses"};
                        if (in4->ip == in4->broadcast())
                            throw std::runtime_error{"Cannot bind to IPv4 broadcast address"};
                        _local_ip_net = std::move(*in4);
                    }
                    else
                    {
                        if (_local_ipv6_net)
                            throw std::runtime_error{"cannot specify multiple IPv6 addresses"};
                        auto& n = std::get<ipv6_net>(ip_net);
                        if (n.mask > 64)
                            throw std::runtime_error{"local IPv6 net mask must be /64 or smaller"};
                        _local_ipv6_net = std::move(n);
                    }
                }
                catch (const std::exception& e)
                {
                    throw std::invalid_argument{"[network]:local-address invalid '{}': {}"_format(arg, e.what())};
                }
            });

        config_def.define_option<std::string>(
            "network",
            "fixed-mapping",
            FullClientOnly,
            MultiValue,
            Comment{
                "Map remote `.{}` or `.{}` address to always use fixed local IPv4, IPv6, or both"_format(
                    CLIENT_TLD, RELAY_TLD),
                "(comma-separated). Example:",
                "    fixed-mapping=kcpyawm9se7trdbzncimdi5t7st4p5mh9i1mg7gkpuubi4k4ku1y.{}:172.16.0.42,fd2e:7365:7368::42"_format(
                    RELAY_TLD),
                "    fixed-mapping=55fxrybf3jtausbnmxpgwcsz9t8qkf5pr8t5f4xyto4omjrkorpy.{}:fd2e:7365:7368::deca:f20"_format(
                    RELAY_TLD),
                "reserves given IPv4/IPv6 addresses for indicated pubkeys.",
                "",
                "Session Router addresses not explicitly mapped use next available IP for IPv4,",
                "or pubkey-derived address with fallback for IPv6.",
                "",
                "Given IPs must be within ranges configured by local-address=, and ONS addresses",
                "are not allowed."},
            [this](std::string arg) {
                if (arg.empty())
                    return;
                const auto colon_pos = arg.find(":");
                if (colon_pos == std::string::npos)
                    throw std::invalid_argument{
                        "[network]:fixed-mapping invalid entry '{}': expected 'ADDR:IP' or 'ADDR:IP,IP'"_format(arg)};
                auto addr_arg = std::string_view{arg}.substr(0, colon_pos);
                auto ips = split(std::string_view{arg}.substr(colon_pos + 1), ",", true);
                if (ips.size() < 1 || ips.size() > 2)
                    throw std::invalid_argument{
                        "[network]:fixed-mapping invalid entry '{}': expected single IPv4, IPv6, or both"_format(arg)};
                try
                {
                    NetworkAddress raddr{addr_arg};
                    for (const auto& ip : ips)
                    {
                        std::string ip_arg{ip};
                        bool inserted;
                        if (ip_arg.find(':') != std::string_view::npos)
                            inserted = _reserved_local_ipv6.emplace(raddr, ip_arg).second;
                        else
                            inserted = _reserved_local_ipv4.emplace(raddr, ip_arg).second;
                        if (!inserted)
                            throw std::invalid_argument{"Duplicate entry for pubkey"};
                    }
                }
                catch (const std::exception& e)
                {
                    throw std::invalid_argument{"[network]:fixed-mapping invalid '{}': {}"_format(arg, e.what())};
                }
            });

        config_def.add_options_validator([this] {
            if (!_reserved_local_ipv4.empty())
            {
                if (ipv4_autoselect())
                    throw std::invalid_argument{"[network]:fixed-mapping requires IPv4 range in [network]:local-address"};
                for (const auto& [netaddr, ip] : _reserved_local_ipv4)
                    if (!_local_ip_net->contains(ip))
                        throw std::invalid_argument{
                            "Invalid [network]:fixed-mapping: {} outside configured IPv4 range {}"_format(
                                ip, *_local_ip_net)};
            }
            if (!_reserved_local_ipv6.empty())
            {
                if (ipv6_autoselect())
                    throw std::invalid_argument{"[network]:fixed-mapping requires IPv6 range in [network]:local-address"};
                for (const auto& [netaddr, ip] : _reserved_local_ipv6)
                    if (!_local_ipv6_net->contains(ip))
                        throw std::invalid_argument{
                            "Invalid [network]:fixed-mapping: {} outside configured IPv6 range {}"_format(
                                ip, *_local_ipv6_net)};
            }
        });

        config_def.define_option<int>(
            "network",
            "expired-cache-size",
            NotEmbedded,
            Default{config_def.type == config::Type::Relay ? 100 : 1000},
            Comment{
                "Controls how many recently expired connection addresses to remember: if a connection",
                "closes or expires, assigned addresses are remembered and reused if reestablished",
                "while still in cache. This sets maximum number of such addresses Session Router remembers.",
                "",
                "Cache does not persist across restarts: use fixed-mapping= for persistent addresses.",
            });

        config_def.define_option<std::string>(
            "network",
            "srv-records",
            FullClientOnly,
            MultiValue,
            Comment{
                "Specify SRV Records for services hosted on the SNApp for protocols using SRV",
                "records for service discovery. Each line specifies one SRV record as:",
                "    srv=_service._protocol priority weight port target.{}"_format(CLIENT_TLD),
                "and can be specified multiple times. If `target.sesh` is set to",
                "`localhost.sesh` it will be replaced with this Session Router's address.",
                "",
                "See https://docs.oxen.io/products-built-on-oxen/session-router/snapps/hosting-snapps",
                "for more info on DNS SRV record configuration.",
            },
            [this](std::string arg) {
                auto maybe_srv = dns::SRVData::from_srv_string(arg);
                if (not maybe_srv)
                    throw std::invalid_argument{"Invalid SRV Record string: {}"_format(arg)};
                srv_records.push_back(std::move(*maybe_srv));
            });
    }

    void DnsConfig::define_config_options(ConfigDefinition& config_def)
    {
        config_def.add_section_comments(
            "dns",
            {
                "DNS configuration settings",
            });

        constexpr std::array DefaultDNSBind{
#ifdef __linux__
#ifdef WITH_SYSTEMD
            Default{"127.0.0.1:0"},
#endif
            Default{"127.3.2.1"},
#else
            Default{"127.0.0.1"},
#endif
        };

        config_def.define_option<std::string>(
            "dns",
            "listen-address",
            FullClientOnly,
            DefaultDNSBind,
            MultiValue,
            Comment{
                "Address(es) on which to listen for DNS requests. Either IP address (uses default port 53)",
                "or IP followed by `:port' for custom port. IPv6 addresses surrounded with '[' and ']'.",
                "",
                "Can be specified multiple times to bind to multiple addresses.",
                "",
                "Set to empty string to disable DNS listener entirely if no outbound connections needed",
                "(WARNING: disabling prevents new outbound connections!).",
            },
            [this](const std::string& arg) {
                if (not arg.empty())
                    _listen_addrs.push_back(quic::Address::parse(arg, DEFAULT_DNS_PORT));
            });

        config_def.define_option<std::string>(
            "dns",
            "upstream-servers",
            FullClientOnly,
            MultiValue,
            std::array{
                Default{"9.9.9.9"}, Default{"149.112.112.112"}, Default{"[2620:fe::fe]"}, Default{"[2620:fe::9]"}},
            Comment{
                "Upstream resolver(s) for non-Session Router addresses.",
                "Multiple values accepted. Set to empty to disable upstream DNS resolution",
                "for advanced setups.",
                "",
                "Defaults to Quad9 public DNS servers (https://quad9.net) if not specified.",
            },
            [this](const std::string& arg) {
                if (not arg.empty())
                    _upstream_dns.push_back(quic::Address::parse(arg, DEFAULT_DNS_PORT));
            });

        config_def.define_option<std::string>(
            "dns",
            "unbound-options",
            FullClientOnly,
            MultiValue,
            Comment{
                "Supply custom options to libunbound for resolving non-.sesh/.snode addresses.",
                "",
                "Format: `unbound-options=option-name: value`",
                "Example: unbound-options=cache-max-ttl: 3600",
                "",
                "Can be specified multiple times for multiple options.",
                "",
                "See https://unbound.docs.nlnetlabs.nl/en/latest/manpages/unbound.conf.html",
                "for all supported unbound options.",
            },
            [this](std::string option) {
                auto pos = option.find(':');
                if (pos == std::string::npos)
                    throw std::invalid_argument{
                        "Invalid unbound option '{}': must be formatted as `option: value`"_format(option)};
                auto key = std::string_view{option}.substr(0, pos);
                auto value = std::string_view{option}.substr(pos + 1);
                for (auto* s : {&key, &value})
                {
                    while (s->starts_with(' '))
                        s->remove_prefix(1);
                    while (s->ends_with(' '))
                        s->remove_suffix(1);
                }
                if (key.empty() || value.empty())
                    throw std::invalid_argument{
                        "Invalid unbound option '{}': key and/or value cannot be empty"_format(option)};
                unbound_opts.emplace_back("{}:"_format(key), std::string{value});
            });

        config_def.define_option<std::string>(
            "dns",
            "hosts-file",
            FullClientOnly,
            Default{"SYSTEM"s},
            Comment{
                "Configures unbound to use given hosts files for address resolution.",
                "Used for custom addresses or client-side DNS filtering. If omitted or set",
                "to 'SYSTEM' then system default (/etc/hosts or WINDIR/etc/hosts on Windows)",
                "will be used. Set to empty string to skip hosts file.",
            },
            [this, base_path = config_def.conf_dir](std::string p) {
                if (p.empty())
                    unbound_hosts.reset();
                else if (p == "SYSTEM")
                    unbound_hosts.emplace("SYSTEM");
                else
                {
                    std::filesystem::path path{p};
                    if (path.is_relative())
                        path = base_path / path;
                    if (!exists(path))
                        throw std::invalid_argument{"[dns]:hosts-file file '{}' does not exist"_format(path)};
                    unbound_hosts = std::move(path);
                }
            });

        config_def.define_option<bool>(
            "dns",
            "skip-resolvconf",
            FullClientOnly,
            Comment{
                "Set to 1 to disable resolvconf configuration of Session Router DNS.",
                "(Not used directly by Session Router itself, but by init scripts",
                "on systems using resolveconf)",
            });
    }

    void LinksConfig::define_config_options(ConfigDefinition& config_def)
    {
        config_def.add_section_comments(
            "bind",
            {
                "Specify IP for Session Router incoming/outgoing connections.",
                "Usually left blank for simple setups, but required for relays with multiple IPs",
                "or relays listening on private IPs with forwarded public traffic.",
            });

        auto parse_link_address = [](std::string_view arg) {
            quic::Address a = quic::Address::parse(arg, 0);
            if (a.is_loopback())
                throw std::invalid_argument{"Invalid listen address: {} is loopback"_format(arg)};
            if (a.is_ipv6() && a.is_any_addr())
                a = quic::Address{ipv4{0, 0, 0, 0}, a.port()};
            else if (a.is_ipv6() && a.is_ipv4_mapped_ipv6())
                a.unmap_ipv4_from_ipv6();
            else if (a.is_ipv6())
                throw std::invalid_argument{"Invalid listen address: IPv6 not currently supported"};
            return a;
        };

        config_def.define_option<std::string>(
            "bind",
            "listen",
            config_def.type == config::Type::Relay
              ? Comment{
                "IP and/or port for Session Router to bind to for inbound/outbound connections.",
                "",
                "If IP omitted, Session Router searches for local interface with public IP (exits if none found).",
                "If port omitted, defaults to 1190.",
                "",
                "Examples:",
                "    listen=15.5.29.5:1099",
                "    listen=10.0.2.2",
                "    listen=:1234",
                "",
                "Private range IP requires [router]:external-ip/-port to specify reachable public IP.",
                }
              : Comment{
                "IP and/or port for Session Router to use for relay connections.",
                "",
                "Defaults to ':1091' (port 1091 on any available address).",
                "",
                "Examples:",
                "    listen=15.5.29.5:1099 -- specific IP and port",
                "    listen=10.0.2.2 -- specific IP, default port (1191)",
                "    listen=:1234 -- any IP, port 1234",
            },
            [this, parse_link_address](const std::string& arg) {
                if (listen_addr)
                    throw std::runtime_error{
                        "Multiple listen addresses found. Delete extra [bind]:inbound and [bind]:IP, use only [bind]:listen"};
                listen_addr = parse_link_address(arg);
            });
    }

    void ApiConfig::define_config_options(ConfigDefinition& config_def)
    {
        config_def.add_section_comments(
            "api",
            {
                "JSON API configuration",
            });

        constexpr std::array DefaultRPCBind{
            Default{"tcp://127.0.0.1:1190"},
#ifndef _WIN32
            Default{"ipc://rpc.sock"},
#endif
        };

        config_def.define_option<bool>(
            "api",
            "enabled",
            NotEmbedded,
            Default{config_def.type == config::Type::FullClient},
            assignment_acceptor(enable_rpc_server),
            Comment{
                "Enables/disables OMQ JSON API. Enabled for clients by default, disabled for relays.",
            });

        config_def.define_option<std::string>(
            "api",
            "bind-address",
            NotEmbedded,
            DefaultRPCBind,
            MultiValue,
            [this, first = true](std::string arg) mutable {
                if (first)
                {
                    rpc_bind_addrs.clear();
                    first = false;
                }
                if (arg.find("://") == std::string::npos)
                {
                    arg = "tcp://" + arg;
                }
                rpc_bind_addrs.push_back(std::move(arg));
            },
            Comment{
                "IP addresses and ports to bind to.",
                "Localhost-only recommended for security.",
            });
    }

    void OxendConfig::define_config_options(ConfigDefinition& config_def)
    {
        config_def.add_section_comments(
            "oxend",
            {
                "Settings for communicating with oxend when running as Service Node relay",
            });

        config_def.define_option<bool>(
            "oxend",
            "disable-tests",
            Default{false},
            Hidden,
            RelayOnly,
            Comment{"Development option: set to true to disable reachability testing on testnet"},
            assignment_acceptor(disable_testing));

