#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned long long target_value;
    if (!(cin >> target_value)) return 0;

    // Constructive solution inspired by Codeforces patterns
    // Create a grid pattern that can represent numbers up to large values
    // Using a 65x65 matrix for extended coverage beyond 2^60
    int grid_size = 65;
    vector<vector<int>> matrix(grid_size, vector<int>(grid_size, 0));

    // Build snake-like pattern: alternate row directions
    for (int row_idx = 0; row_idx < grid_size; ++row_idx) {
        if (row_idx % 2 == 0) {
            for (int col_idx = 0; col_idx <= row_idx; ++col_idx) {
                matrix[row_idx][col_idx] = 1;
            }
        } else {
            for (int col_idx = 0; col_idx <= row_idx; ++col_idx) {
                matrix[row_idx][grid_size - 1 - col_idx] = 1;
            }
        }
    }

    // Add rightmost column as destination path
    for (int row_idx = 0; row_idx < grid_size; ++row_idx) {
        matrix[row_idx][grid_size - 1] = 1;
    }

    // For each bit position, if set in input, add horizontal connection
    for (int row_idx = 0; row_idx < grid_size; ++row_idx) {
        if (((target_value >> row_idx) & 1ULL) == 0) continue;

        if (row_idx % 2 == 0) {
            // Even rows: fill from diagonal position to right edge
            for (int col_idx = row_idx; col_idx < grid_size; ++col_idx) {
                matrix[row_idx][col_idx] = 1;
            }
        } else {
            // Odd rows: fill from mirrored diagonal position to right edge
            for (int col_idx = grid_size - 1 - row_idx; col_idx < grid_size; ++col_idx) {
                matrix[row_idx][col_idx] = 1;
            }
        }
    }

    cout << grid_size << "\n";
    for (int row_idx = 0; row_idx < grid_size; ++row_idx) {
        for (int col_idx = 0; col_idx < grid_size; ++col_idx) {
            if (col_idx) cout << ' ';
            cout << matrix[row_idx][col_idx];
        }
        cout << "\n";
    }

    return 0;
}

