#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cmath>
#include <map>

// Fixed board size as per problem constraints
const int BOARD_SIZE = 20;

struct Piece {
    int identifier;
    int row, col;
};

struct Action {
    char direction;
    int position;
    int depth;
    int expense;
    std::vector<int> pieces_affected; // IDs of Pieces removed by this action.
};

struct Step {
    char dir;
    int idx;
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int placeholder;
    std::cin >> placeholder; // Read board size (unused, fixed at 20)

    std::vector<std::string> grid(BOARD_SIZE);
    std::vector<Piece> pieces;
    std::map<std::pair<int, int>, int> piece_lookup;

    for (int i = 0; i < BOARD_SIZE; ++i) {
        std::cin >> grid[i];
        for (int j = 0; j < BOARD_SIZE; ++j) {
            if (grid[i][j] == 'x') {
                int pid = pieces.size();
                pieces.push_back({pid, i, j});
                piece_lookup[{i, j}] = pid;
            }
        }
    }

    int total_pieces = pieces.size();
    std::vector<Action> actions;

    // Generate all valid 'Up' actions
    for (int col = 0; col < BOARD_SIZE; ++col) {
        std::vector<int> path_pieces;
        for (int row = 0; row < BOARD_SIZE; ++row) {
            if (grid[row][col] == 'o') break;
            if (grid[row][col] == 'x') path_pieces.push_back(piece_lookup.at({row, col}));
            if (!path_pieces.empty()) 
                actions.push_back({'U', col, row, 2 * (row + 1), path_pieces});
        }
    }

    // Generate all valid 'Down' actions
    for (int col = 0; col < BOARD_SIZE; ++col) {
        std::vector<int> path_pieces;
        for (int row = BOARD_SIZE - 1; row >= 0; --row) {
            if (grid[row][col] == 'o') break;
            if (grid[row][col] == 'x') path_pieces.push_back(piece_lookup.at({row, col}));
            if (!path_pieces.empty()) 
                actions.push_back({'D', col, row, 2 * (BOARD_SIZE - row), path_pieces});
        }
    }

    // Generate all valid 'Left' actions
    for (int row = 0; row < BOARD_SIZE; ++row) {
        std::vector<int> path_pieces;
        for (int col = 0; col < BOARD_SIZE; ++col) {
            if (grid[row][col] == 'o') break;
            if (grid[row][col] == 'x') path_pieces.push_back(piece_lookup.at({row, col}));
            if (!path_pieces.empty()) 
                actions.push_back({'L', row, col, 2 * (col + 1), path_pieces});
        }
    }

    // Generate all valid 'Right' actions
    for (int row = 0; row < BOARD_SIZE; ++row) {
        std::vector<int> path_pieces;
        for (int col = BOARD_SIZE - 1; col >= 0; --col) {
            if (grid[row][col] == 'o') break;
            if (grid[row][col] == 'x') path_pieces.push_back(piece_lookup.at({row, col}));
            if (!path_pieces.empty()) 
                actions.push_back({'R', row, col, 2 * (BOARD_SIZE - col), path_pieces});
        }
    }

    std::vector<bool> status(total_pieces, false);
    int cleared_count = 0;
    std::vector<Step> sequence;

    while (cleared_count < total_pieces) {
        double best_score = -1.0;
        int selected_idx = -1;

        for (int i = 0; i < actions.size(); ++i) {
            int gain = 0;
            for (int pid : actions[i].pieces_affected) {
                if (!status[pid]) {
                    gain++;
                }
            }
            if (gain == 0) continue;

            double value = (double)gain / std::sqrt(actions[i].expense);
            if (value > best_score || 
               (value == best_score && actions[i].expense < actions[selected_idx].expense)) {
                best_score = value;
                selected_idx = i;
            }
        }

        if (selected_idx == -1) break;

        Action& chosen = actions[selected_idx];
        if (chosen.direction == 'U') {
            for (int step = 0; step < chosen.depth / 2; ++step) 
                sequence.push_back({'U', chosen.position});
            for (int step = 0; step < chosen.depth / 2; ++step) 
                sequence.push_back({'D', chosen.position});
        } else if (chosen.direction == 'D') {
            for (int step = 0; step < (BOARD_SIZE - chosen.depth/2); ++step) 
                sequence.push_back({'D', chosen.position});
            for (int step = 0; step < (BOARD_SIZE - chosen.depth/2); ++step) 
                sequence.push_back({'U', chosen.position});
        } else if (chosen.direction == 'L') {
            for (int step = 0; step < chosen.depth / 2; ++step) 
                sequence.push_back({'L', chosen.position});
            for (int step = 0; step < chosen.depth / 2; ++step) 
                sequence.push_back({'R', chosen.position});
        } else if (chosen.direction == 'R') {
            for (int step = 0; step < (BOARD_SIZE - chosen.depth/2); ++step) 
                sequence.push_back({'R', chosen.position});
            for (int step = 0; step < (BOARD_SIZE - chosen.depth/2); ++step) 
                sequence.push_back({'L', chosen.position});
        }

        for (int pid : chosen.pieces_affected) {
            if (!status[pid]) {
                status[pid] = true;
                cleared_count++;
            }
        }
    }

    for (const auto& move : sequence) {
        std::cout << move.dir << " " << move.idx << "\n";
    }

    return 0;
}

