#include "ConcertServerSequencerManager.h"
#include "IConcertSession.h"
#include "ConcertSyncServerLiveSession.h"

FConcertServerSequencerManager::FConcertServerSequencerManager(const TSharedRef<FConcertSyncServerLiveSession>& InActiveSession)
{
	AttachSession(InActiveSession);
}

FConcertServerSequencerManager::~FConcertServerSequencerManager()
{
	DetachSession();
}

void FConcertServerSequencerManager::AttachSession(const TSharedRef<FConcertSyncServerLiveSession>& InActiveSession)
{
	check(InActiveSession->IsValidSession());
	DetachSession();
	ActiveSession = InActiveSession;
	ActiveSession->GetSession().OnSessionClientChanged().AddRaw(this, &FConcertServerSequencerManager::OnSessionClientStatusUpdated);
	ActiveSession->GetSession().RegisterCustomEventHandler<FConcertSequencerCloseEvent>(this, &FConcertServerSequencerManager::OnSequencerClosed);
	ActiveSession->GetSession().RegisterCustomEventHandler<FConcertSequencerStateEvent>(this, &FConcertServerSequencerManager::OnSequencerStateChanged);
	ActiveSession->GetSession().RegisterCustomEventHandler<FConcertSequencerOpenEvent>(this, &FConcertServerSequencerManager::OnSequencerOpened);
}

void FConcertServerSequencerManager::DetachSession()
{
	if (ActiveSession)
	{
		ActiveSession->GetSession().OnSessionClientChanged().RemoveAll(this);
		ActiveSession->GetSession().UnregisterCustomEventHandler<FConcertSequencerOpenEvent>(this);
		ActiveSession->GetSession().UnregisterCustomEventHandler<FConcertSequencerCloseEvent>(this);
		ActiveSession->GetSession().UnregisterCustomEventHandler<FConcertSequencerStateEvent>(this);
		ActiveSession.Reset();
	}
}

void FConcertServerSequencerManager::OnSequencerStateChanged(const FConcertSessionContext& EventContext, const FConcertSequencerStateEvent& Event)
{
	// Create or update the Sequencer state 
	FConcertOpenSequencerState& StateRef = OpenSequencers.FindOrAdd(*Event.State.SequenceObjectPath);
	StateRef.ClientEndpointIds.AddUnique(EventContext.SourceEndpointId);
	StateRef.State = Event.State;

	// Relay the message to other connected clients
	TArray<FGuid> TargetClients = ActiveSession->GetSession().GetSessionClientEndpointIds();
	TargetClients.Remove(EventContext.SourceEndpointId);
	ActiveSession->GetSession().SendCustomEvent(Event, TargetClients, EConcertMessageFlags::ReliableOrdered | EConcertMessageFlags::UniqueId);
}

void FConcertServerSequencerManager::OnSequencerOpened(const FConcertSessionContext& EventContext, const FConcertSequencerOpenEvent& Event)
{
	// Create or update the Sequencer state 
	FConcertOpenSequencerState& StateRef = OpenSequencers.FindOrAdd(*Event.SequenceObjectPath);
	StateRef.ClientEndpointIds.AddUnique(EventContext.SourceEndpointId);
	StateRef.State.SequenceObjectPath = Event.SequenceObjectPath;

	// Relay the message to other connected clients
	TArray<FGuid> TargetClients = ActiveSession->GetSession().GetSessionClientEndpointIds();
	TargetClients.Remove(EventContext.SourceEndpointId);
	ActiveSession->GetSession().SendCustomEvent(Event, TargetClients, EConcertMessageFlags::ReliableOrdered | EConcertMessageFlags::UniqueId);
}

void FConcertServerSequencerManager::OnSequencerClosed(const FConcertSessionContext& EventContext, const FConcertSequencerCloseEvent& Event)
{
	FConcertOpenSequencerState* FoundState = OpenSequencers.Find(*Event.SequenceObjectPath);
	if (FoundState)
	{
		FoundState->ClientEndpointIds.Remove(EventContext.SourceEndpointId);
		if (FoundState->ClientEndpointIds.Num() == 0)
		{
			// Notify remaining clients about the closure
			FConcertSequencerCloseEvent FinalClose;
			FinalClose.bMasterClose = false;
			FinalClose.SequenceObjectPath = Event.SequenceObjectPath;
			ActiveSession->GetSession().SendCustomEvent(FinalClose, ActiveSession->GetSession().GetSessionClientEndpointIds(), EConcertMessageFlags::ReliableOrdered | EConcertMessageFlags::UniqueId);
			OpenSequencers.Remove(*Event.SequenceObjectPath);
		}
		// If master closed it, propagate that info
		else if (Event.bMasterClose)
		{
			ActiveSession->GetSession().SendCustomEvent(Event, ActiveSession->GetSession().GetSessionClientEndpointIds(), EConcertMessageFlags::ReliableOrdered | EConcertMessageFlags::UniqueId);
		}
	}
}

void FConcertServerSequencerManager::OnSessionClientStatusUpdated(IConcertServerSession& SessionRef, EConcertClientStatus ClientStatus, const FConcertSessionClientInfo& ClientInfo)
{
	check(&SessionRef == &ActiveSession->GetSession());

	// Clean up client references from all open sequences on disconnect
	if (ClientStatus == EConcertClientStatus::Disconnected)
	{
		for (auto It = OpenSequencers.CreateIterator(); It; ++It)
		{
			It->Value.ClientEndpointIds.Remove(ClientInfo.ClientEndpointId);
			if (It->Value.ClientEndpointIds.Num() == 0)
			{
				// Notify remaining clients
				FConcertSequencerCloseEvent CloseNotification;
				CloseNotification.SequenceObjectPath = It->Key.ToString();
				ActiveSession->GetSession().SendCustomEvent(CloseNotification, ActiveSession->GetSession().GetSessionClientEndpointIds(), EConcertMessageFlags::ReliableOrdered | EConcertMessageFlags::UniqueId);
				It.RemoveCurrent();
			}
		}
	}
	// Send current sequencer states to newly connected client
	else
	{
		FConcertSequencerStateSyncEvent SyncPayload;
		for (const auto& Entry : OpenSequencers)
		{
			SyncPayload.SequencerStates.Add(Entry.Value.State);
		}
		ActiveSession->GetSession().SendCustomEvent(SyncPayload, ClientInfo.ClientEndpointId, EConcertMessageFlags::ReliableOrdered);
	}
}

