// Verify mixed arithmetic and logical operations
void verify_arith_bool_logic(SMTParser::ParserPtr& parser) {
    std::vector<std::string> formulas = {
        // Arithmetic within boolean conditions
        "(and (> ar_x 0) (< ar_y 10))",

        // Boolean operators with comparison expressions
        "(or (= ar_x ar_y) (and (> ar_x 0) (< ar_y 0)))",

        // Implication involving arithmetic relations
        "(=> (>= ar_x 0) (>= (+ ar_x ar_y) ar_y))",

        // Ite combining boolean and arithmetic constructs
        "(ite (> ar_x 0) (+ ar_x ar_y) (- ar_x ar_y))",

        // Complex formula integrating multiple theories
        "(and (= (+ ar_x ar_y) ar_z) (or (> ar_x 0) (< ar_y 0)))"
    };

    std::cout << "=== Validating Arithmetic and Boolean Logic Integration ===" << std::endl;

    try {
        // Introduce variables
        parser->mkVarInt("ar_x");
        parser->mkVarInt("ar_y");
        parser->mkVarInt("ar_z");

        for (const auto& expr : formulas) {
            std::cout << "Formula: " << expr << std::endl;
            std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(expr);
            assert(evaluation && !evaluation->isErr());
            std::cout << "  Output: " << parser->toString(evaluation) << std::endl;
            std::cout << std::endl;
        }
    } catch (const std::exception& e) {
        std::cout << "Error during variable setup: " << e.what() << std::endl;
    }
}

// Validate interaction between arrays and arithmetic
void validate_array_arith_integration(SMTParser::ParserPtr& parser) {
    std::vector<std::string> formulas = {
        // Array indexing using arithmetic expressions
        "(select aa_arr (+ idx_i 1))",

        // Store operation with arithmetic operands
        "(store aa_arr (* 2 idx_i) (+ idx_j 5))",

        // Array equality involving stores and arithmetic
        "(= (store aa_arr idx_i (+ idx_j 1)) (store aa_arr idx_i (+ 1 idx_j)))",

        // Arrays used in arithmetic comparisons
        "(> (select aa_arr idx_i) (select aa_arr idx_j))",

        // Arithmetic constraints on array components
        "(forall ((idx_k Int)) (=> (and (>= idx_k 0) (< idx_k 10)) (>= (select aa_arr idx_k) 0)))"
    };

    std::cout << "=== Validating Array and Arithmetic Integration ===" << std::endl;

    try {
        // Setup variables and array
        std::shared_ptr<SMTParser::Sort> int_sort = SMTParser::SortManager::INT_SORT;
        parser->mkArray("aa_arr", int_sort, int_sort);
        parser->mkVarInt("idx_i");
        parser->mkVarInt("idx_j");
        parser->mkVarInt("idx_k");

        for (const auto& expr : formulas) {
            std::cout << "Formula: " << expr << std::endl;
            std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(expr);
            assert(evaluation && !evaluation->isErr());
            std::cout << "  Output: " << parser->toString(evaluation) << std::endl;
            std::cout << std::endl;
        }
    } catch (const std::exception& e) {
        std::cout << "Error during setup: " << e.what() << std::endl;
    }
}

// Validate bitvector operations combined with other theories
void validate_bitvector_integration(SMTParser::ParserPtr& parser) {
    std::vector<std::string> formulas = {
        // Bitvector in boolean context
        "(= #b1010 #b1010)",

        // Bitvector operations yielding boolean results
        "(bvult #b1010 #b1100)",

        // Conversion from bitvector to natural number
        "(= (bv2nat #b1010) 10)",

        // Bitvector used as array index
        "(select bv_arr #b1010)",

        // Complex expression combining bitvectors with other theories
        "(and (bvult bv_var1 bv_var2) (= (select bv_arr bv_var1) #b0101))"
    };

    std::cout << "=== Validating Bitvector Integration ===" << std::endl;

    try {
        // Setup variables
        std::shared_ptr<SMTParser::Sort> bv4_sort = parser->mkBVSort(4);
        parser->mkVarBv("bv_var1", 4);
        parser->mkVarBv("bv_var2", 4);

        // Declare array from BV to BV
        parser->mkArray("bv_arr", bv4_sort, bv4_sort);

        for (const auto& expr : formulas) {
            std::cout << "Formula: " << expr << std::endl;
            std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(expr);
            assert(evaluation && !evaluation->isErr());
