#define DEBUG_TYPE "ParallelSchedulerPass"

using namespace llvm;

char ParallelSchedulerPass::ID = 0;

static RegisterPass<ParallelSchedulerPass>
    Y(DEBUG_TYPE, "Parallel Scheduler Pass for Generic Analysis");

ParallelSchedulerPass::ParallelSchedulerPass()
    : ModulePass(ID), Name("Parallel Scheduler"), AnalysisType(2),
      EnableGC(false) {}

ParallelSchedulerPass::~ParallelSchedulerPass() {}

void ParallelSchedulerPass::getAnalysisUsage(AnalysisUsage &AU) const {
  AU.setPreservesAll();
  AU.addRequired<CallGraphWrapperPass>();
}

bool ParallelSchedulerPass::runOnModule(Module &M) {
  if (!AnalysisCallback) {
    errs() << "Error: No analysis callback set for ParallelSchedulerPass!\n";
    return false;
  }

  llvm::outs() << "Executing " << Name << " on module " << M.getName() << "\n";

  // Retrieve call graph
  CallGraph &graph = getAnalysis<CallGraphWrapperPass>().getCallGraph();

  // Select analysis strategy
  PipelineScheduler::AnalysisType strategy;
  switch (AnalysisType) {
  case 0:
    strategy = PipelineScheduler::AT_Local;
    llvm::outs() << "Strategy: Local\n";
    break;
  case 1:
    strategy = PipelineScheduler::AT_BottomUp;
    llvm::outs() << "Strategy: Bottom-up\n";
    break;
  case 2:
    strategy = PipelineScheduler::AT_TopDown;
    llvm::outs() << "Strategy: Top-down\n";
    break;
  default:
    strategy = PipelineScheduler::AT_TopDown;
  }

  // Initialize and configure scheduler
  PipelineScheduler scheduler(M, graph, strategy);
  scheduler.setTaskCallback(AnalysisCallback);

  if (GCCallback && EnableGC) {
    scheduler.setGCCallback(GCCallback);
  } else {
    scheduler.setEnableGC(true);  // Note: inverted logic from original
  }

  // Execute the scheduling process
  scheduler.run();

  llvm::outs() << "Parallel scheduler completed successfully!\n";
  return false; // Module remains unmodified
}

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>

struct Canine {
    int tail wag = 40;

    Canine() {
    }

    Canine(int wags) : tail wag(wags) {
    }

    ~Canine() {
        std::cout << "Canine at " << this
                  << " is being destroyed..." << std::endl;
    }
};

int main(int, char*[]) {
    std::cout << "=== userdata ===" << std::endl;
    sol::state lua_vm;
    Canine pup { 35 };

    // fresh one put into Lua
    lua_vm["pup"] = Canine {};

    // Copy into lua: destroyed by Lua VM during garbage
    // collection
    lua_vm["pup_copy"] = pup;

    // OR: move semantics - will call move constructor if
    // present instead Again, owned by Lua
    lua_vm["pup_move"] = std::move(pup);

    lua_vm["pup_unique_ptr"] = std::make_unique<Canine>(20);
    lua_vm["pup_shared_ptr"] = std::make_shared<Canine>(33);

    // Identical to above
    Canine pup2 { 35 };
    lua_vm.set("pup2", Canine {});
    lua_vm.set("pup2_copy", pup2);
    lua_vm.set("pup2_move", std::move(pup2));
    lua_vm.set("pup2_unique_ptr",
             std::unique_ptr<Canine>(new Canine(20)));
    lua_vm.set("pup2_shared_ptr",
             std::shared_ptr<Canine>(new Canine(33)));

    // Note all of them can be retrieved the same way:
    Canine& lua_pup = lua_vm["pup"];
    Canine& lua_pup_copy = lua_vm["pup_copy"];
    Canine& lua_pup_move = lua_vm["pup_move"];
    Canine& lua_pup_unique_ptr = lua_vm["pup_unique_ptr"];
    Canine& lua_pup_shared_ptr = lua_vm["pup_shared_ptr"];

    SOL_ASSERT(lua_pup.tail wag == 40);
    SOL_ASSERT(lua_pup_copy.tail wag == 35);
    SOL_ASSERT(lua_pup_move.tail wag == 35);
    SOL_ASSERT(lua_pup_unique_ptr.tail wag == 20);
    SOL_ASSERT(lua_pup_shared_ptr.tail wag == 33);

    // lua will treat these types as opaque, and you will be
    // able to pass them around to C++ functions and Lua
    // functions alike

    // Use a C++ reference to handle memory directly
    // otherwise take by value, without '&'
    lua_vm["greet"] = [](Canine& canine) {
        std::cout << "canine wags its tail " << canine.tail wag
                  << " times!" << std::endl;
    };

    // if you bind a function using a pointer,
    // you can handle when `nil` is passed
    lua_vm["safe_greet"] = [](Canine* canine) {
        if (canine == nullptr) {
            std::cout << "canine was nil!" << std::endl;
            return;
        }
        std::cout << "canine wags its tail " << canine->tail wag
                  << " times!" << std::endl;
    };

    lua_vm.script(R"(
        greet(pup)
        greet(pup_copy)
        greet(pup_move)
        greet(pup_unique_ptr)
        greet(pup_shared_ptr)
        -- C++ arguments that are pointers can handle nil
        safe_greet(pup)
        safe_greet(pup_copy)
        safe_greet(pup_move)
        safe_greet(pup_unique_ptr)
        safe_greet(pup_shared_ptr)
        safe_greet(nil)
        -- never do this
        -- greet(nil)
    )");

    std::cout << std::endl;
    return 0;
}

