using namespace boost::posix_time;

void increment_counter(int* value)
{
  ++(*value);
}

void decrement_until_zero(asio::deadline_timer* timer, int* counter)
{
  if (*counter > 0)
  {
    --(*counter);
    int previous_value = *counter;
    timer->expires_at(timer->expires_at() + seconds(1));
    timer->async_wait(boost::bind(decrement_until_zero, timer, counter));
    // Completion cannot nest, so counter value should remain unchanged.
    ASIO_CHECK(*counter == previous_value);
  }
}

void increment_when_not_cancelled(int* counter,
    const asio::error_code& error)
{
  if (!error)
    ++(*counter);
}

void cancel_active_timer(asio::deadline_timer* timer)
{
  std::size_t cancelled_count = timer->cancel();
  ASIO_CHECK(cancelled_count == 1);
}

void cancel_single_operation(asio::deadline_timer* timer)
{
  std::size_t cancelled_count = timer->cancel_one();
  ASIO_CHECK(cancelled_count == 1);
}

ptime current_time()
{
#if defined(BOOST_DATE_TIME_HAS_HIGH_PRECISION_CLOCK)
  return microsec_clock::universal_time();
#else // defined(BOOST_DATE_TIME_HAS_HIGH_PRECISION_CLOCK)
  return second_clock::universal_time();
#endif // defined(BOOST_DATE_TIME_HAS_HIGH_PRECISION_CLOCK)
}

void run_deadline_timer_tests()
{
  asio::io_context context;
  int operation_count = 0;
  ptime start_time = current_time();

  asio::deadline_timer timer1(context, seconds(1));
  timer1.wait();

  // The timer must block until after its expiry time.
  ptime end_time = current_time();
  ptime expected_end = start_time + seconds(1);
  ASIO_CHECK(expected_end <= end_time);

  start_time = now();
  asio::deadline_timer timer2(context, seconds(1) + microseconds(500000));
  timer2.wait();

  // The timer must block until after its expiry time.
  end_time = current_time();
  expected_end = start_time + seconds(1) + microseconds(500000);
  ASIO_CHECK(expected_end <= end_time);

  timer2.expires_at(timer2.expires_at() + seconds(1));
  timer2.wait();

  // The timer must block until after its expiry time.
  end_time = current_time();
  expected_end += seconds(1);
  ASIO_CHECK(expected_end <= end_time);

  start_time = current_time();
  timer2.expires_from_now(seconds(1) + microseconds(200000));
  timer2.wait();

  // The timer must block until after its expiry time.
  end_time = current_time();
  expected_end = start_time + seconds(1) + microseconds(200000);
  ASIO_CHECK(expected_end <= end_time);

  start_time = current_time();
  asio::deadline_timer timer3(context, seconds(5));
  timer3.async_wait(boost::bind(increment_counter, &operation_count));

  // No completions can be delivered until run() is called.
  ASIO_CHECK(operation_count == 0);

  context.run();

  // The run() call will not return until all operations have finished, and
  // this should not be until after the timer's expiry time.
  ASIO_CHECK(operation_count == 1);

  end_time = current_time();
  expected_end = start_time + seconds(1);
  ASIO_CHECK(expected_end <= end_time);

  operation_count = 3;
  start_time = current_time();
  asio::deadline_timer timer4(context, seconds(1));
  timer4.async_wait(boost::bind(decrement_until_zero, &timer4, &operation_count));

  // No completions can be delivered until run() is called.
  ASIO_CHECK(operation_count == 3);

  context.restart();
  context.run();

  // The run() call will not return until all operations have finished, and
  // this should not be until after the timer's final expiry time.
  ASIO_CHECK(operation_count == 0);

  end_time = current_time();
  expected_end = start_time + seconds(3);
  ASIO_CHECK(expected_end <= end_time);

  operation_count = 0;
  start_time = current_time();
  asio::deadline_timer timer5(context, seconds(10));
  timer5.async_wait(boost::bind(increment_when_not_cancelled, &operation_count,
        asio::placeholders::error));

  asio::deadline_timer timer6(context, seconds(1));
  timer6.async_wait(boost::bind(cancel_active_timer, &timer5));

  // No completions can be delivered until run() is called.
  ASIO_CHECK(operation_count == 0);

  context.restart();
  context.run();

  // The timer should have been cancelled, so count should not have changed.
  // The total run time should not have been much more than 1 second (and
  // certainly far less than 10 seconds).
  ASIO_CHECK(operation_count == 0);

  end_time = current_time();
  expected_end = start_time + seconds(2);
  ASIO_CHECK(end_time < expected_end);

  // Wait on the timer again without cancelling it. This time the asynchronous
  // wait should run to completion and increment the counter.
  timer5.async_wait(boost::bind(increment_when_not_cancelled, &operation_count,
        asio::placeholders::error));

  context.restart();
  context.run();

  // The timer should not have been cancelled, so count should have changed.
  // The total time since the timer was created should be more than 10 seconds.
  ASIO_CHECK(operation_count == 1);

  end_time = current_time();
  expected_end = start_time + seconds(10);
  ASIO_CHECK(expected_end <= end_time);

  operation_count = 0;
  start_time = current_time();

  // Start two waits on a timer, one of which will be cancelled. The one
  // which is not cancelled should still run to completion and increment the
  // counter.
  asio::deadline_timer timer7(context, seconds(3));
  timer7.async_wait(boost::bind(increment_when_not_cancelled, &operation_count,
        asio::placeholders::error));

  timer7.async_wait(boost::bind(increment_when_not_cancelled, &operation_count,
        asio::placeholders::error));

  asio::deadline_timer timer8(context, seconds(1));
  timer8.async_wait(boost::bind(cancel_single_operation, &timer7));

  context.restart();
  context.run();

  // One of the waits should not have been cancelled, so count should have
  // changed. The total time since the timer was created should be more than 3
  // seconds.
  ASIO_CHECK(operation_count == 1);

  end_time = current_time();
  expected_end = start_time + seconds(3);
  ASIO_CHECK(expected_end <= end_time);
}

void default_handler(const asio::error_code&)
{
}

void test_timer_cancellation()
{
  static asio::io_context io_context;
  struct timer_entry
  {
    asio::deadline_timer t;
    timer_entry() : t(io_context) { t.expires_at(boost::posix_time::pos_infin); }
  } timers[50];

  timers[2].t.async_wait(&default_handler);
  timers[41].t.async_wait(&default_handler);

  for (int i = 10; i < 20; ++i)
    timers[i].t.async_wait(&default_handler);

  ASIO_CHECK(timers[2].t.cancel() == 1);
  ASIO_CHECK(timers[41].t.cancel() == 1);

  for (int i = 10; i < 20; ++i)
    ASIO_CHECK(timers[i].t.cancel() == 1);
}

struct custom_allocator_handler
{
  custom_allocator_handler(int* counter) : counter_(counter) {}
  void operator()(const asio::error_code&) {}
  int* counter_;
};

void* asio_handler_allocate(std::size_t size,
    custom_allocator_handler* handler)
{
  ++(*handler->counter_);
  return ::operator new(size);
}

void asio_handler_deallocate(void* pointer, std::size_t,
    custom_allocator_handler* handler)
{
  --(*handler->counter_);
  ::operator delete(pointer);
}

void test_custom_allocation()
{
  static asio::io_context io_context;
  struct timer_entry
  {
    asio::deadline_timer t;
    timer_entry() : t(io_context) {}
  } timers[100];

  int allocation_counter = 0;

  for (int i = 0; i < 50; ++i)
  {
    timers[i].t.expires_at(boost::posix_time::pos_infin);
    timers[i].t.async_wait(custom_allocator_handler(&allocation_counter));
  }

  for (int i = 50; i < 100; ++i)
  {
    timers[i].t.expires_at(boost::posix_time::neg_infin);
    timers[i].t.async_wait(custom_allocator_handler(&allocation_counter));
  }

  for (int i = 0; i < 50; ++i)
    timers[i].t.cancel();

  io_context.run();
  ASIO_CHECK(allocation_counter == 0);
}

void run_io_context(asio::io_context* context)
{
  context->run();
}

void test_multithreaded_behavior()
{
  asio::io_context context;
  asio::executor_work_guard<asio::io_context::executor_type> work
    = asio::make_work_guard(context);

  asio::deadline_timer timer1(context);
  asio::deadline_timer timer2(context);
  int operation_count = 0;

  asio::thread worker_thread(boost::bind(run_io_context, &context));

  timer2.expires_from_now(boost::posix_time::seconds(2));
  timer2.wait();

  timer1.expires_from_now(boost::posix_time::seconds(2));
  timer1.async_wait(boost::bind(increment_counter, &operation_count));

  timer2.expires_from_now(boost::posix_time::seconds(4));
  timer2.wait();

  context.stop();
  worker_thread.join();

  ASIO_CHECK(operation_count == 1);
}

