#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <random>
#include <chrono>
#include <numeric>
using namespace std;

// Clause representation: two literals per clause
struct Clause {
    int lit1, lit2;
};

int num_vars, num_clauses;
vector<Clause> clause_list;
vector<vector<int>> var_occurrence; // For each variable, list of clause indices it appears in

// Current solution state
vector<int> current_solution;      // Variable assignments (1-based)
vector<int> clause_satisfaction;   // Number of satisfied literals per clause
int satisfied_clauses_count = 0;   // Total number of currently satisfied clauses

// Best solution discovered
vector<int> best_solution;
int highest_satisfied = -1;

// Check if a literal evaluates to true under given assignment
inline bool literal_is_true(int lit, const vector<int>& assign) {
    int var = abs(lit);
    int value = assign[var];
    return (lit > 0) ? (value == 1) : (value == 0);
}

// Recompute all clause satisfaction from scratch
void recompute_state() {
    satisfied_clauses_count = 0;
    for (int idx = 0; idx < num_clauses; ++idx) {
        int satisfied_literals = literal_is_true(clause_list[idx].lit1, current_solution) +
                                 literal_is_true(clause_list[idx].lit2, current_solution);
        clause_satisfaction[idx] = satisfied_literals;
        if (satisfied_literals > 0) satisfied_clauses_count++;
    }
}

// Determine how flipping variable `var` affects the number of satisfied clauses
inline int evaluate_flip(int var) {
    int delta = 0;
    int old_val = current_solution[var];
    int new_val = 1 - old_val;

    for (int c_index : var_occurrence[var]) {
        int current_sat = clause_satisfaction[c_index];
        int l1 = clause_list[c_index].lit1;
        int l2 = clause_list[c_index].lit2;

        int old_contrib = 0, new_contrib = 0;

        if (abs(l1) == var) {
            old_contrib += (l1 > 0 ? old_val : 1 - old_val);
            new_contrib += (l1 > 0 ? new_val : 1 - new_val);
        }
        if (abs(l2) == var) {
            old_contrib += (l2 > 0 ? old_val : 1 - old_val);
            new_contrib += (l2 > 0 ? new_val : 1 - new_val);
        }

        int updated_sat = current_sat - old_contrib + new_contrib;

        if (current_sat == 0 && updated_sat > 0) delta++;
        else if (current_sat > 0 && updated_sat == 0) delta--;
    }
    return delta;
}

// Perform variable flip and update internal state
inline void perform_flip(int var) {
    int old_val = current_solution[var];
    int new_val = 1 - old_val;
    current_solution[var] = new_val;

    for (int c_index : var_occurrence[var]) {
        int current_sat = clause_satisfaction[c_index];
        int l1 = clause_list[c_index].lit1;
        int l2 = clause_list[c_index].lit2;

        int old_contrib = 0, new_contrib = 0;

        if (abs(l1) == var) {
            old_contrib += (l1 > 0 ? old_val : 1 - old_val);
            new_contrib += (l1 > 0 ? new_val : 1 - new_val);
        }
        if (abs(l2) == var) {
            old_contrib += (l2 > 0 ? old_val : 1 - old_val);
            new_contrib += (l2 > 0 ? new_val : 1 - new_val);
        }

        int new_sat = current_sat - old_contrib + new_contrib;

        if (current_sat == 0 && new_sat > 0) satisfied_clauses_count++;
        else if (current_sat > 0 && new_sat == 0) satisfied_clauses_count--;

        clause_satisfaction[c_index] = new_sat;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> num_vars >> num_clauses)) return 0;

    clause_list.resize(num_clauses);
    var_occurrence.resize(num_vars + 1);

    for (int i = 0; i < num_clauses; ++i) {
        cin >> clause_list[i].lit1 >> clause_list[i].lit2;
        var_occurrence[abs(clause_list[i].lit1)].push_back(i);
        if (abs(clause_list[i].lit2) != abs(clause_list[i].lit1)) {
            var_occurrence[abs(clause_list[i].lit2)].push_back(i);
        }
    }

    // Handle case with no clauses
    if (num_clauses == 0) {
        for (int i = 1; i <= num_vars; ++i) 
            cout << 0 << (i == num_vars ? "" : " ");
        cout << "\n";
        return 0;
    }

    current_solution.resize(num_vars + 1);
    clause_satisfaction.resize(num_clauses);
    best_solution.resize(num_vars + 1);

    // Initialize random number generator
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

    // Generate initial random assignment
    for (int i = 1; i <= num_vars; ++i) 
        current_solution[i] = rng() % 2;

    recompute_state();

    best_solution = current_solution;
    highest_satisfied = satisfied_clauses_count;

    auto start = chrono::steady_clock::now();

    // Prepare variable list for randomized traversal
    vector<int> variables(num_vars);
    iota(variables.begin(), variables.end(), 1);

    // Main optimization loop
    while (true) {
        auto now = chrono::steady_clock::now();
        if (chrono::duration<double>(now - start).count() > 0.95) break;

        // Local search phase
        bool improved = true;
        while (improved) {
            improved = false;
            shuffle(variables.begin(), variables.end(), rng);

            for (int v : variables) {
                if (evaluate_flip(v) > 0) {
                    perform_flip(v);
                    improved = true;

                    if (satisfied_clauses_count > highest_satisfied) {
                        highest_satisfied = satisfied_clauses_count;
                        best_solution = current_solution;
                    }
                }
            }
        }

        if (highest_satisfied == num_clauses) break;

        // Perturbation / restart strategy
        if (rng() % 100 < 10) {
            // Full random restart
            for (int i = 1; i <= num_vars; ++i) 
                current_solution[i] = rng() % 2;
            recompute_state();
        } else {
            // Partial perturbation: flip few variables
            int flips = 1 + rng() % max(1, num_vars / 20);
            for (int i = 0; i < flips; ++i) {
                int idx = 1 + rng() % num_vars;
                perform_flip(idx);
            }
        }
    }

    // Output best found assignment
    for (int i = 1; i <= num_vars; ++i) {
        cout << best_solution[i] << (i == num_vars ? "" : " ");
    }
    cout << "\n";

    return 0;
}

#include "BufferProcessor.hpp"
#include "Buffer.hpp"
#include "MayaFlux/Journal/Archivist.hpp"

namespace MayaFlux::Buffers {

void BufferProcessor::handle_buffer(const std::shared_ptr<Buffer>& buf)
{
    if (!buf->attempt_acquire_for_processing()) {
        MF_RT_ERROR(Journal::Component::Buffers, Journal::Context::BufferProcessing,
            "Buffer is currently processed by another handler, skipping current operation");
        return;
    }
    m_in_progress.fetch_add(1, std::memory_order_acquire);
    try {
        process_callback(buf);
    } catch (...) {
        buf->finish_processing();
        m_in_progress.fetch_sub(1, std::memory_order_release);
        throw;
    }
    buf->finish_processing();
    m_in_progress.fetch_sub(1, std::memory_order_release);
}

void BufferProcessor::handle_non_owning_buffer(const std::shared_ptr<Buffer>& buf)
{
    m_in_progress.fetch_add(1, std::memory_order_acquire);
    try {
        process_callback(buf);
    } catch (...) {
        m_in_progress.fetch_sub(1, std::memory_order_release);
        throw;
    }
    m_in_progress.fetch_sub(1, std::memory_order_release);
}

