#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int blackCount, whiteCount, temp1, temp2;
    if (!(cin >> blackCount >> whiteCount >> temp1 >> temp2)) return 0;

    // Special case: 1D optimal arrangement when counts differ by at most 1
    if (abs(blackCount - whiteCount) <= 1) {
        int rows = 1, cols = blackCount + whiteCount;
        cout << rows << " " << cols << "\n";

        bool firstIsBlack = (blackCount >= whiteCount);
        int placedBlack = 0, placedWhite = 0;

        for (int idx = 0; idx < cols; ++idx) {
            bool shouldPlaceBlack = ((idx % 2 == 0) ? firstIsBlack : !firstIsBlack);

            if (shouldPlaceBlack) {
                if (placedBlack < blackCount) {
                    cout << '@';
                    placedBlack++;
                } else {
                    cout << '.';
                    placedWhite++;
                }
            } else {
                if (placedWhite < whiteCount) {
                    cout << '.';
                    placedWhite++;
                } else {
                    cout << '@';
                    placedBlack++;
                }
            }
        }
        cout << "\n";
        return 0;
    }

    // General construction using 5 rows:
    // Top 2 rows: white background with black islands on row 0 at even columns
    // Middle row (row 2): black separator with one white cell to connect a white island
    // Bottom 2 rows: black background with white islands on row 3 at even columns

    int width = max(2 * blackCount - 1, 2 * whiteCount - 1);
    int height = 5;
    vector<string> grid(height, string(width, '@'));

    // Initialize top two rows as white
    for (int col = 0; col < width; ++col) {
        grid[0][col] = '.';
        grid[1][col] = '.';
    }

    // Place black islands in upper section (row 0 at even columns)
    for (int i = 0; i < blackCount; ++i) {
        int column = 2 * i;
        grid[0][column] = '@';

        // Ensure adjacent separator columns remain white
        if (column + 1 < width) {
            grid[0][column + 1] = '.';
            grid[1][column + 1] = '.';
        }
    }

    // Place white islands in lower section (row 3 at even columns)
    for (int i = 0; i < whiteCount; ++i) {
        int column = 2 * i;
        grid[3][column] = '.';
        // Separator columns (odd) remain black by default
    }

    // Connect one black island to the black base (row 1)
    int connCol1;
    if (blackCount == 1) {
        connCol1 = 0;  // Use the only black island's column
    } else {
        connCol1 = 2 * (blackCount - 1);  // Rightmost black island
    }
    grid[1][connCol1] = '@';

    // Connect one white island to upper white base via row 2
    int connCol2;
    if (blackCount == 1) {
        connCol2 = (whiteCount >= 2 ? 2 : 0);
    } else {
        connCol2 = 0;  // Leftmost white island

        if (connCol2 == connCol1) {
            if (whiteCount >= 2) {
                connCol2 = 2;
            } else {
                // Expand grid to accommodate separate connection point
                int oldWidth = width;
                width += 2;

                for (int r = 0; r < height; ++r) {
                    grid[r].resize(width, '@');
                }

                grid[0].replace(oldWidth, 2, "..");
                grid[1].replace(oldWidth, 2, "..");

                connCol2 = oldWidth;
                grid[3][connCol2] = '.';
            }
        }
    }

    // Safety check for bounds
    if (connCol2 >= width) {
        connCol2 = (whiteCount >= 1 ? 2 * (whiteCount - 1) : 0);
        if (connCol2 >= width) connCol2 = 0;
    }

    // Create white passage in middle row for white island connectivity
    grid[2][connCol2] = '.';

    // Output result
    cout << height << " " << width << "\n";
    for (int r = 0; r < height; ++r) {
        cout << grid[r] << "\n";
    }

    return 0;
}

