#include <stdio.h>
#include <ogg.h>
#include "codec.h"
#include "codec_internal.h"
#include "registry.h"
#include "misc.h"
#include "os.h"

int vorbis_synthesis(vorbis_block *block, ogg_packet *packet) {
  vorbis_dsp_state     *dsp = block->vd;
  private_state        *backend = dsp->backend_state;
  vorbis_info          *info = dsp->vi;
  codec_setup_info     *setup = info->codec_setup;
  oggpack_buffer       *buffer = &block->opb;
  int                   kind, current_mode, j;

  /* Prepare decoding */
  _vorbis_block_ripcord(block);
  oggpack_readinit(buffer, packet->packet, packet->bytes);

  /* Verify packet type */
  if (oggpack_read(buffer, 1) != 0) {
    return OV_ENOTAUDIO;
  }

  /* Extract mode and window settings */
  current_mode = oggpack_read(buffer, backend->modebits);
  if (current_mode == -1) return OV_EBADPACKET;

  block->mode = current_mode;
  block->W = setup->mode_param[current_mode]->blockflag;

  if (block->W) {
    block->lW = oggpack_read(buffer, 1);
    block->nW = oggpack_read(buffer, 1);
    if (block->nW == -1) return OV_EBADPACKET;
  } else {
    block->lW = 0;
    block->nW = 0;
  }

  /* Additional metadata assignment */
  block->granulepos = packet->granulepos;
  block->sequence   = packet->packetno;
  block->eofflag    = packet->e_o_s;

  /* Allocate PCM storage */
  block->pcmend = setup->blocksizes[block->W];
  block->pcm = _vorbis_block_alloc(block, sizeof(*block->pcm) * info->channels);
  for (j = 0; j < info->channels; ++j) {
    block->pcm[j] = _vorbis_block_alloc(block, block->pcmend * sizeof(*block->pcm[j]));
  }

  /* Map mapping function and invoke inverse */
  kind = setup->map_type[setup->mode_param[current_mode]->mapping];
  return (_mapping_P[kind]->inverse(block, setup->map_param[setup->mode_param[current_mode]->mapping]));
}

/* Track PCM position without decoding — useful for fast-forward */
int vorbis_synthesis_trackonly(vorbis_block *block, ogg_packet *packet) {
  vorbis_dsp_state     *dsp = block->vd;
  private_state        *backend = dsp->backend_state;
  vorbis_info          *info = dsp->vi;
  codec_setup_info     *setup = info->codec_setup;
  oggpack_buffer       *buffer = &block->opb;
  int                   current_mode;

  _vorbis_block_ripcord(block);
  oggpack_readinit(buffer, packet->packet, packet->bytes);

  if (oggpack_read(buffer, 1) != 0) {
    return OV_ENOTAUDIO;
  }

  current_mode = oggpack_read(buffer, backend->modebits);
  if (current_mode == -1) return OV_EBADPACKET;

  block->mode = current_mode;
  block->W = setup->mode_param[current_mode]->blockflag;

  if (block->W) {
    block->lW = oggpack_read(buffer, 1);
    block->nW = oggpack_read(buffer, 1);
    if (block->nW == -1) return OV_EBADPACKET;
  } else {
    block->lW = 0;
    block->nW = 0;
  }

  block->granulepos = packet->granulepos;
  block->sequence   = packet->packetno;
  block->eofflag    = packet->e_o_s;

  block->pcmend = 0;
  block->pcm    = NULL;

  return 0;
}

long vorbis_packet_blocksize(vorbis_info *info, ogg_packet *packet) {
  codec_setup_info     *setup = info->codec_setup;
  oggpack_buffer       buffer;
  int                  current_mode;

  oggpack_readinit(&buffer, packet->packet, packet->bytes);

  if (oggpack_read(&buffer, 1) != 0) {
    return OV_ENOTAUDIO;
  }

  {
    int bitcount = 0;
    int count = setup->modes;
    while (count > 1) {
      bitcount++;
      count >>= 1;
    }
    current_mode = oggpack_read(&buffer, bitcount);
  }

  if (current_mode == -1) return OV_EBADPACKET;
  return setup->blocksizes[setup->mode_param[current_mode]->blockflag];
}

int vorbis_synthesis_halfrate(vorbis_info *info, int enable) {
  codec_setup_info *setup = info->codec_setup;

  if (setup->blocksizes[0] <= 64 && enable) return -1;
  setup->halfrate_flag = (enable ? 1 : 0);
  return 0;
}

int vorbis_synthesis_halfrate_p(vorbis_info *info) {
  codec_setup_info *setup = info->codec_setup;
  return setup->halfrate_flag;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <numeric>
#include <algorithm>

// Disjoint Set Union with union-by-size and path compression
struct DSU {
    std::vector<int> parent;
    std::vector<int> size;
    int num_components;

    DSU(int n) {
        parent.resize(n);
        std::iota(parent.begin(), parent.end(), 0);
        size.assign(n, 1);
        num_components = n;
    }

    DSU(const DSU& other) = default;

    int find(int x) {
        if (parent[x] == x)
            return x;
        return parent[x] = find(parent[x]);
    }

    void merge(int a, int b) {
        int root_a = find(a);
        int root_b = find(b);
        if (root_a != root_b) {
            if (size[root_a] < size[root_b]) 
                std::swap(root_a, root_b);
            parent[root_b] = root_a;
            size[root_a] += size[root_b];
            num_components--;
        }
    }
};

struct Coordinate {
    int x, y;
};

struct Connection {
    int node1, node2;
    int dist; // Rounded Euclidean distance
};

// Edge in the component graph
struct GraphEdge {
    int comp1, comp2; // component roots
    double weight;    // estimated weight

    bool operator<(const GraphEdge& other) const {
        return weight < other.weight;
    }
};

double calculate_distance(const Coordinate& pt1, const Coordinate& pt2) {
    long long diff_x = pt1.x - pt2.x;
    long long diff_y = pt1.y - pt2.y;
    return std::sqrt(static_cast<double>(diff_x * diff_x + diff_y * diff_y));
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    const int TOTAL_POINTS = 400;
    const int TOTAL_CONNECTIONS = 1995;

    std::vector<Coordinate> points(TOTAL_POINTS);
    for (int idx = 0; idx < TOTAL_POINTS; ++idx) {
        std::cin >> points[idx].x >> points[idx].y;
    }

    std::vector<Connection> connections(TOTAL_CONNECTIONS);
    for (int idx = 0; idx < TOTAL_CONNECTIONS; ++idx) {
        std::cin >> connections[idx].node1 >> connections[idx].node2;
        connections[idx].dist = static_cast<int>(std::round(calculate_distance(points[connections[idx].node1], points[connections[idx].node2])));
    }

    DSU dsu(TOTAL_POINTS);

    for (int step = 0; step < TOTAL_CONNECTIONS; ++step) {
        int threshold;
        std::cin >> threshold;

        int u = connections[step].node1;
        int v = connections[step].node2;
        int root_u = dsu.find(u);
        int root_v = dsu.find(v);

        if (root_u == root_v) {
            std::cout << 0 << '\n';
            continue;
        }

        // Dynamically adjust beta based on progress
        double progress = static_cast<double>(step) / (TOTAL_CONNECTIONS - 1);
        double beta = 1.4 + 1.6 * progress * progress;

        std::vector<GraphEdge> candidate_edges;
        if (step < TOTAL_CONNECTIONS - 1) {
            candidate_edges.reserve(TOTAL_CONNECTIONS - 1 - step);
        }

        for (int next_idx = step + 1; next_idx < TOTAL_CONNECTIONS; ++next_idx) {
            int ru = dsu.find(connections[next_idx].node1);
            int rv = dsu.find(connections[next_idx].node2);
            if (ru != rv) {
                candidate_edges.push_back({ru, rv, beta * connections[next_idx].dist});
            }
        }

        std::sort(candidate_edges.begin(), candidate_edges.end());

        double min_path_weight = 1e18; // Effectively infinity

        if (!candidate_edges.empty()) {
            DSU temp_dsu = dsu;
            for (const auto& edge : candidate_edges) {
                if (temp_dsu.find(edge.comp1) != temp_dsu.find(edge.comp2)) {
                    temp_dsu.merge(edge.comp1, edge.comp2);
                    if (temp_dsu.find(root_u) == temp_dsu.find(root_v)) {
                        min_path_weight = edge.weight;
                        break;
                    }
                }
            }
        }

        if (static_cast<double>(threshold) < min_path_weight) {
            std::cout << 1 << '\n';
            dsu.merge(u, v);
        } else {
            std::cout << 0 << '\n';
        }
    }

    return 0;
}

