// Message identifier for button press event
const uint32 kButtonPress = 'btnp';

class CounterWindow : public BWindow
{
public:
	CounterWindow(BRect frame)
		:
		BWindow(frame, "Counter Example", B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE),
		fClickCount(0)
	{
		// Main container view
		BRect area = Bounds();
		BView* container = new BView(area, "container", B_FOLLOW_ALL, B_WILL_DRAW);
		container->SetViewColor(240, 240, 240);
		AddChild(container);

		// Interactive button
		BRect buttonBounds(30, 25, 130, 55);
		BButton* actionButton = new BButton(buttonBounds, "trigger", "Press Me", 
		                                    new BMessage(kButtonPress));
		container->AddChild(actionButton);

		// Status display
		BRect textBounds(30, 70, 290, 90);
		fDisplay = new BStringView(textBounds, "status", "Press the button");
		fDisplay->SetFont(be_plain_font);
		container->AddChild(fDisplay);
	}

	virtual ~CounterWindow()
	{
	}

	virtual bool QuitRequested()
	{
		be_app->PostMessage(B_QUIT_REQUESTED);
		return true;
	}

	void MessageReceived(BMessage* msg) override
	{
		switch (msg->what) {
			case kButtonPress:
				fClickCount++;
				{
					BString displayText;
					displayText.SetToFormat("Pressed %d time%s", 
					                        fClickCount, 
					                        fClickCount == 1 ? "" : "s");
					fDisplay->SetText(displayText.String());
				}
				break;
			default:
				BWindow::MessageReceived(msg);
		}
	}
private:
	BStringView* fDisplay;
	int32 fClickCount;
};

class CounterApplication : public BApplication
{
public:
	CounterApplication()
		:
		BApplication("application/x-vnd.example-counterapp")
	{
	}

	virtual void ReadyToRun()
	{
		BRect windowRect(120, 120, 340, 220);
		CounterWindow* win = new CounterWindow(windowRect);
		win->Show();
	}
};

// Entry point
int main()
{
	CounterApplication app;
	app.Run();
	return 0;
}

