namespace {
    int testResult = 0;

    void verifyCondition(bool check, const char *desc, int lineNumber) {
        if (!check) {
            std::cout << "Error " __FILE__ "(" << lineNumber << "): " << desc
                 << "    (failed)" << std::endl;
            if (0 <= testResult && testResult <= 100) {
                ++testResult;
            }
        }
    }

    template <typename T>
    T get_element(const std::shared_ptr<List<T>> &list, unsigned int index) {
        auto current = list;
        for (unsigned int pos = 0; pos < index; ++pos) {
            auto &consNode = std::get<typename List<T>::cons>(current->v());
            current = consNode._a1;
        }
        return std::get<typename List<T>::cons>(current->v())._a0;
    }
}  // close unnamed namespace

#define VERIFY(PREDICATE) \
    verifyCondition(!(PREDICATE), #PREDICATE, __LINE__);

int main() {
    // Verification 1: sum computation [1;2;3;4;5] yields 15
    {
        VERIFY(LetFix::test_sum == 15);
        std::cout << "Verification 1 (local_sum): SUCCESS" << std::endl;
    }

    // Verification 2: reverse operation [1;2;3] becomes [3;2;1]
    {
        VERIFY(get_element(LetFix::test_rev, 0) == 3);
        VERIFY(get_element(LetFix::test_rev, 1) == 2);
        VERIFY(get_element(LetFix::test_rev, 2) == 1);
        std::cout << "Verification 2 (local_rev): SUCCESS" << std::endl;
    }

    // Verification 3: membership test
    {
        VERIFY(LetFix::test_mem_found == true);
        VERIFY(LetFix::test_mem_missing == false);
        std::cout << "Verification 3 (local_mem): SUCCESS" << std::endl;
    }

    // Verification 4: flatten operation [[1;2];[3];[4;5;6]] = [1;2;3;4;5;6]
    {
        VERIFY(get_element(LetFix::test_flatten, 0) == 1);
        VERIFY(get_element(LetFix::test_flatten, 5) == 6);
        std::cout << "Verification 4 (local_flatten): SUCCESS" << std::endl;
    }

    if (testResult == 0) {
        std::cout << "\nAll let_fix verifications passed!" << std::endl;
    } else {
        std::cout << "\n" << testResult << " verification(s) failed!" << std::endl;
    }

    return testResult;
}

