//----------------------------------------------------------------------------------
// Processes button press events.
//----------------------------------------------------------------------------------
HRESULT CScene_Death::OnButtonPressed(HXUIOBJ hObjPressed, XUINotifyPress* pNotifyPressData, BOOL& rfHandled)
{
	if(m_inputBlocked) return S_OK;
	// This assumes all buttons can only be pressed with the A button
	ui.AnimateControllerInput(pNotifyPressData->UserIndex, VK_PAD_A);
	unsigned int btnIndex=0;
	while((btnIndex<BUTTONS_DEATH_MAX) && (m_Options[btnIndex]!=hObjPressed)) btnIndex++;
	Minecraft *gameInstance=Minecraft::GetInstance();
	// Determine which button was pressed,
	// and call the appropriate function.	
	switch(btnIndex)
	{
	case OPTION_DEATH_EXITGAME:		
		{
			// 4J-PB - fix for #8333 - BLOCKER: If player decides to exit game, then cancels the exit player becomes stuck at game over screen
			//m_inputBlocked = true;
			// Check if it's the trial version
			if(ProfileManager.IsFullVersion())
			{	
				UINT messageIDs[3];

				// is it the primary player exiting?
				if(pNotifyPressData->UserIndex==ProfileManager.GetPrimaryPad())
				{
					int sessionDuration = -1;
					if( gameInstance->localplayers[pNotifyPressData->UserIndex] != NULL )
					{
						sessionDuration = (int)gameInstance->localplayers[pNotifyPressData->UserIndex]->getSessionTimer();
					}
					TelemetryManager->RecordLevelExit(pNotifyPressData->UserIndex, eSen_LevelExitStatus_Failed);

					if(StorageManager.GetSaveDisabled())
					{
						messageIDs[0]=IDS_CONFIRM_CANCEL;
						messageIDs[1]=IDS_CONFIRM_OK;
						StorageManager.RequestMessageBox(IDS_EXIT_GAME, IDS_CONFIRM_EXIT_GAME_PROGRESS_LOST, messageIDs, 2, pNotifyPressData->UserIndex,&UIScene_PauseMenu::ExitGameDialogReturned,this, app.GetStringTable());
					}
					else
					{
						if( g_NetworkManager.IsHost() )
						{	
							messageIDs[0]=IDS_CONFIRM_CANCEL;
							messageIDs[1]=IDS_EXIT_GAME_SAVE;
							messageIDs[2]=IDS_EXIT_GAME_NO_SAVE;
							StorageManager.RequestMessageBox(IDS_EXIT_GAME, IDS_CONFIRM_EXIT_GAME, messageIDs, 3, pNotifyPressData->UserIndex,&UIScene_PauseMenu::ExitGameSaveDialogReturned,this, app.GetStringTable());
						}
						else
						{
							messageIDs[0]=IDS_CONFIRM_CANCEL;
							messageIDs[1]=IDS_CONFIRM_OK;
							StorageManager.RequestMessageBox(IDS_EXIT_GAME, IDS_CONFIRM_EXIT_GAME, messageIDs, 2, pNotifyPressData->UserIndex,&UIScene_PauseMenu::ExitGameDialogReturned,this, app.GetStringTable());
						}
					}
				}
				else
				{
					TelemetryManager->RecordLevelExit(pNotifyPressData->UserIndex, eSen_LevelExitStatus_Failed);

					// just exit the player
					app.SetAction(pNotifyPressData->UserIndex,eAppAction_ExitPlayer);
				}		
			}
			else
			{
				// is it the primary player exiting?
				if(pNotifyPressData->UserIndex==ProfileManager.GetPrimaryPad())
				{
					TelemetryManager->RecordLevelExit(pNotifyPressData->UserIndex, eSen_LevelExitStatus_Failed);

					// adjust the trial time played
					CXuiSceneBase::ReduceTrialTimerValue();
					// exit the level
					UINT messageIDs[2];
					messageIDs[0]=IDS_CONFIRM_CANCEL;
					messageIDs[1]=IDS_CONFIRM_OK;
					StorageManager.RequestMessageBox(IDS_EXIT_GAME, IDS_CONFIRM_EXIT_GAME_PROGRESS_LOST, messageIDs, 2, pNotifyPressData->UserIndex,&UIScene_PauseMenu::ExitGameDialogReturned,this, app.GetStringTable());
				}
				else
				{
					TelemetryManager->RecordLevelExit(pNotifyPressData->UserIndex, eSen_LevelExitStatus_Failed);
					// just exit the player
					app.SetAction(pNotifyPressData->UserIndex,eAppAction_ExitPlayer);
				}
			}
		}
		break;
	case OPTION_DEATH_RESPAWN:
		{
			m_inputBlocked = true;
			app.SetAction(pNotifyPressData->UserIndex,eAppAction_Respawn);
		}
		break;
	default:
		break;
	}
	return S_OK;
}
