int CScene_Death::RespawnWorkerThread( void* lpParameter )
{
	AABB::UseDefaultThreadStorage();
	Vec3::UseDefaultThreadStorage();
	Compression::UseDefaultThreadStorage();
	size_t controllerIndex=(size_t)lpParameter;
	Minecraft *gameInstance=Minecraft::GetInstance();
	gameInstance->localplayers[controllerIndex]->respawn();
	app.SetGameStarted(true);
	gameInstance->gameRenderer->EnableUpdateThread();

	// If we are online, then we should wait here until the respawn is done
	// If we are offline, this should release straight away
	//WaitForSingleObject( gameInstance->m_hPlayerRespawned, INFINITE );
	while(gameInstance->localplayers[controllerIndex]->GetPlayerRespawned()==false)
	{
		Sleep(50);
	}
	return S_OK;
}
