// The height of one row of slots
//#define ROW_HEIGHT 42.0f - comes from the pointer height in the xui
// The number of container rows that are visible in the Xui file at it's default size
#define CONTAINER_DEFAULT_ROWS 3
//--------------------------------------------------------------------------------------
// Name: CXuiSceneContainer::OnInit
// Desc: Message handler for XM_INIT
//--------------------------------------------------------------------------------------
HRESULT CXuiSceneContainer::OnInit( XUIMessageInit* pInitData, BOOL& bHandled )
{
	D3DXVECTOR3 position;
	MapChildControls();
	Minecraft *gameInstance = Minecraft::GetInstance();
	ContainerScreenInput* initParams = (ContainerScreenInput*)pInitData->pvInitData;

	XuiControlSetText(m_ChestText,app.GetString(initParams->container->getName()));
	ContainerMenu* menuInstance = new ContainerMenu( initParams->inventory, initParams->container );
	shared_ptr<Container> currentContainer = initParams->container;
	m_iPad=initParams->iPad;
	m_bSplitscreen=initParams->bSplitscreen;
#ifdef _XBOX
	if( gameInstance->localgameModes[initParams->iPad] != NULL )
	{
		TutorialMode *currentMode = (TutorialMode *)gameInstance->localgameModes[initParams->iPad];
		m_previousTutorialState = currentMode->getTutorial()->getCurrentState();
		currentMode->getTutorial()->changeTutorialState(e_Tutorial_State_Container_Menu, this);
	}
#endif
	// if we are in splitscreen, then we need to figure out if we want to move this scene
	int totalRows = currentContainer->getContainerSize() / 9;
	// use the pointer size in the xui to set the row height
	float pointerWidth, pointerHeight;
	if(m_bSplitscreen)
	{
		app.AdjustSplitscreenScene(m_hObj,&m_OriginalPosition,m_iPad);
	}
	m_pointerControl->GetBounds(&pointerWidth, &pointerHeight);
	// Adjust the height to show the correct number of container rows
	float sceneHeight, sceneWidth;
	this->GetBounds( &sceneWidth, &sceneHeight );	
	int rowAdjustment = CONTAINER_DEFAULT_ROWS - totalRows;
	//height = height - (rowDiff * ROW_HEIGHT);
	sceneHeight = sceneHeight - (rowAdjustment * pointerHeight);
	this->SetBounds( sceneWidth, sceneHeight );
	// Update the position after the height change so that we are still centred
	D3DXVECTOR3 newPos;
	this->GetPosition( &newPos );
	newPos.y = newPos.y + ( (rowAdjustment * pointerHeight) / 2 );
	// Make sure that the y offset is even for SD modes, as the y in xui coordinates will end up being scaled by a factor of 1.5
	// to get it into actual back buffer coordinates, and we need those to remain whole numbers to avoid issues with point sampling
	if(!RenderManager.IsHiDef())
	{
		int iY = (int)(newPos.y);
		iY &= 0xfffffffe;
		newPos.y = (float)iY;
	}
	this->SetPosition( &newPos );
	InitDataAssociations(initParams->iPad, menuInstance);
	CXuiSceneAbstractContainer::Initialize( initParams->iPad, menuInstance, true, currentContainer->getContainerSize(), eSectionContainerUsing, eSectionContainerMax );
	delete initParams;
	return S_OK;
}
HRESULT CXuiSceneContainer::OnDestroy()
{
	Minecraft *gameInstance = Minecraft::GetInstance();
#ifdef _XBOX
	if( gameInstance->localgameModes[m_iPad] != NULL )
	{
		TutorialMode *currentMode = (TutorialMode *)gameInstance->localgameModes[m_iPad];
		if(currentMode != NULL) currentMode->getTutorial()->changeTutorialState(m_previousTutorialState);
	}
#endif
	// 4J Stu - Fix for #11302 - TCR 001: Network Connectivity: Host crashed after being killed by the client while accessing a chest during burst packet loss.
	// We need to make sure that we call closeContainer() anytime this menu is closed, even if it is forced to close by some other reason (like the player dying)	
	if(Minecraft::GetInstance()->localplayers[m_iPad] != NULL) Minecraft::GetInstance()->localplayers[m_iPad]->closeContainer();
	return S_OK;
}
CXuiControl* CXuiSceneContainer::GetSectionControl( ESceneSection eSection )
{
	switch( eSection )
	{
		case eSectionContainerChest:
			return (CXuiControl *)m_containerControl;
			break;
		case eSectionContainerInventory:
			return (CXuiControl *)m_inventoryControl;
			break;
		case eSectionContainerUsing:
			return (CXuiControl *)m_useRowControl;
			break;
		default:
			assert( false );
			break;
	}
	return NULL;
}
CXuiCtrlSlotList* CXuiSceneContainer::GetSectionSlotList( ESceneSection eSection )
{
	switch( eSection )
	{
		case eSectionContainerChest:
			return m_containerControl;
			break;
		case eSectionContainerInventory:
			return m_inventoryControl;
			break;
		case eSectionContainerUsing:
			return m_useRowControl;
			break;
		default:
			assert( false );
			break;
	}
	return NULL;
}
