namespace BANCHO::Api {

static void process_api_response(const Packet &msg) {
    switch(msg.id) {
        case RequestType::GET_BEATMAPSET_INFO: {
            Downloader::handle_beatmapset_info(msg);
            break;
        }
        case RequestType::GET_MAP_LEADERBOARD: {
            BANCHO::Leaderboard::handle_leaderboard_data(msg);
            break;
        }
        case RequestType::GET_REPLAY: {
            if(msg.size == 0) {
                ui->getNotificationOverlay()->addToast(US_("Unable to retrieve replay"), ERROR_TOAST);
                break;
            }
            assert(msg.extra && "process_api_response(GET_REPLAY) received malformed packet");
            assert(reinterpret_cast<uintptr_t>(msg.extra) % alignof(FinishedScore) == 0 &&
                   "process_api_response(GET_REPLAY) misaligned payload");

#ifdef __GNUC__
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wcast-align"
#endif
            auto *score = reinterpret_cast<FinishedScore *>(msg.extra);
#ifdef __GNUC__
#pragma GCC diagnostic pop
#endif

            auto replay_file =
                fmt::format(NEOMOD_REPLAYS_PATH "/{:s}/{:d}.replay.lzma", score->server, score->unixTimestamp);

            debugLog("Storing replay at {}...", replay_file);
            io->write(replay_file, msg.memory, msg.size, [recorded = *score](bool result) {
                if(result) {
                    LegacyReplay::load_and_watch(recorded);
                } else {
                    ui->getNotificationOverlay()->addToast(US_("Failed to store replay"), ERROR_TOAST);
                }
            });
            break;
        }
        case RequestType::MARK_AS_READ: {
            // no action required
            break;
        }
        default: {
            debugLog("No handler for API response code {:d}!", msg.id);
        }
    }
}

void dispatch_request(const Request &req) {
    if(!BanchoState::is_online()) {
        debugLog("Cannot issue API request of type {:d} while offline.",
                 static_cast<unsigned int>(req.type));
        free(req.extra);
        return;
    }

    Mc::Net::RequestOptions opts{
        .user_agent = "osu!",
        .timeout = 60,
        .connect_timeout = 5,
    };

    auto full_url = fmt::format("osu.{:s}{:s}", BanchoState::endpoint, req.path);
    networkHandler->httpRequestAsync(full_url, std::move(opts), [req](Mc::Net::Response resp) {
        if(resp.success) {
            Packet reply;
            reply.id = req.type;
            reply.extra = req.extra;
            reply.extra_int = req.extra_int;
            reply.size = resp.body.length();
            reply.memory = (u8 *)resp.body.data();
            process_api_response(reply);
        }
        free(req.extra);
    });
}

void add_auth_to_url(std::string &url, std::string user_field, std::string pass_field) {
    std::string username, password;
    if(BanchoState::is_oauth) {
        username = "$token";
        password = BanchoState::cho_token;
    } else {
        username = BanchoState::get_username();
        password = BanchoState::pw_md5.string();
    }
    url.append(fmt::format("&{:s}={:s}&{:s}={:s}", user_field, username, pass_field, password));
}

