#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
#include <random>
using namespace std;

int total_nodes;
int query_counter = 0;

int submit_query(const string& input_str) {
    if (query_counter >= 3500) return 0; // Should not happen based on logic
    cout << "? " << input_str << endl;
    query_counter++;
    int response;
    cin >> response;
    return response;
}

int evaluate_set(const vector<int>& elements, int n) {
    string pattern(n, '0');
    for (int val : elements) {
        pattern[val - 1] = '1';
    }
    return submit_query(pattern);
}

// Global collections
vector<int> visited_set;
vector<int> active_candidates;
vector<int> deferred_nodes;

// Check if node v connects to visited_set
// Returns true if connection confirmed, false otherwise
bool check_connection(int v, int current_value) {
    // Create set: visited_set U {v}
    vector<int> temp_set = visited_set;
    temp_set.push_back(v);
    int value_with_v = evaluate_set(temp_set, total_nodes);

    // If v connects to visited_set, value_with_v = current_value - 1 + new_connections
    // new_connections >= 0, so diff = value_with_v - current_value = new - 1 >= -1
    // If v does NOT connect, value_with_v = current_value + new_connections. diff = new >= 0.
    // So if diff == -1, definitely connected.
    // If diff >= 0, ambiguous case.

    return (value_with_v - current_value) == -1;
}

// Locate a connecting node in candidates using binary search approach
// Returns -1 if no neighbor found
int locate_connection(const vector<int>& candidates, int current_value) {
    if (candidates.empty()) return -1;
    if (candidates.size() == 1) {
        int candidate = candidates[0];
        if (check_connection(candidate, current_value)) return candidate;
        else return -1;
    }

    int mid = candidates.size() / 2;
    vector<int> left_part(candidates.begin(), candidates.begin() + mid);
    vector<int> right_part(candidates.begin() + mid, candidates.end());

    // Query set: visited_set + (active_candidates \ left_part)
    vector<int> query_set = visited_set;

    // Add all in active_candidates that are NOT in left_part
    vector<bool> is_in_left(total_nodes + 1, false);
    for (int val : left_part) is_in_left[val] = true;

    for (int val : active_candidates) {
        if (!is_in_left[val]) query_set.push_back(val);
    }

    // Also include deferred nodes
    for (int val : deferred_nodes) {
        if (!is_in_left[val]) query_set.push_back(val); // Note: deferred_nodes and active_candidates are disjoint
    }

    int result = evaluate_set(query_set, total_nodes);
    if (result == 0) {
        // No edges into left_part. Connection must be in right_part.
        return locate_connection(right_part, current_value);
    } else {
        // left_part might have connection. Try left first.
        int found = locate_connection(left_part, current_value);
        if (found != -1) return found;
        // If failed in left, try right
        return locate_connection(right_part, current_value);
    }
}

void process_case() {
    cin >> total_nodes;
    query_counter = 0;
    visited_set.clear();
    active_candidates.clear();
    deferred_nodes.clear();

    visited_set.push_back(1);
    for (int i = 2; i <= total_nodes; ++i) active_candidates.push_back(i);

    while (!active_candidates.empty() || !deferred_nodes.empty()) {
        int f_visited = evaluate_set(visited_set, total_nodes);
        if (f_visited == 0) {
            cout << "! 0" << endl;
            return;
        }

        // If active_candidates empty but deferred_nodes not, restore deferred_nodes
        if (active_candidates.empty()) {
            active_candidates = deferred_nodes;
            deferred_nodes.clear();
        }

        // Try to find a connection in active_candidates
        // Randomize active_candidates to avoid worst-case scenarios
        static mt19937 generator(42);
        shuffle(active_candidates.begin(), active_candidates.end(), generator);

        int node = locate_connection(active_candidates, f_visited);
        if (node != -1) {
            // Found and verified connection
            visited_set.push_back(node);

            // Remove node from active_candidates
            vector<int> next_active;
            for (int x : active_candidates) if (x != node) next_active.push_back(x);
            active_candidates = next_active;

            // Restore deferred_nodes to active_candidates as topology may have changed
            active_candidates.insert(active_candidates.end(), deferred_nodes.begin(), deferred_nodes.end());
            deferred_nodes.clear();
        } else {
            // All candidates failed verification - likely due to interference
            // Move one node from active_candidates to deferred_nodes and retry

            if (!active_candidates.empty()) {
                int remove_index = active_candidates.size() - 1;
                deferred_nodes.push_back(active_candidates[remove_index]);
                active_candidates.pop_back();
            } else {
                // Should be handled by restoring deferred_nodes
            }
        }
    }

    cout << "! 1" << endl;
}

int main() {
    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            process_case();
        }
    }
    return 0;
}

