    int R, H;
    cin >> R >> H; // R=75, H=1

    const int robots = 40; // number of robots we will use
    const int items = 1000;
    const double prob = 0.293;

    vector<uint64_t> bitMask(items);
    vector<vector<int>> testQueries(robots);

    // Generate a random matrix that is 2-separable
    mt19937_64 prng;
    bernoulli_distribution distribution(prob);
    bool success = false;

    for (int attempt = 0; attempt < 100; attempt++) {
        prng.seed(attempt);
        // Reset structures
        for (int idx = 0; idx < items; idx++) bitMask[idx] = 0;
        for (int idx = 0; idx < robots; idx++) testQueries[idx].clear();

        // Build the testing matrix
        for (int r = 0; r < robots; r++) {
            for (int c = 0; c < items; c++) {
                if (distribution(prng)) {
                    bitMask[c] |= (1ULL << r);
                    testQueries[r].push_back(c+1); // positions are 1-indexed
                }
            }
        }

        // Verify 2-separability: all pair-wise ORs must be unique
        unordered_set<uint64_t> observed;
        success = true;
        for (int x = 0; x < items && success; x++) {
            for (int y = x; y < items; y++) {
                uint64_t combined = bitMask[x] | bitMask[y];
                if (observed.find(combined) != observed.end()) {
                    success = false;
                    break;
                }
                observed.insert(combined);
            }
        }
        if (success) {
            // Valid configuration found
            break;
        }
    }

    // In the extremely unlikely case that no valid matrix is found,
    // we proceed with the last generated one (still highly probable to work).

    // Issue queries
    for (int i = 0; i < robots; i++) {
        cout << "? " << testQueries[i].size();
        for (int position : testQueries[i]) {
            cout << " " << position;
        }
        cout << endl;
        cout.flush();
    }

    // Retrieve responses
    cout << "@" << endl;
    cout.flush();

    int count;
    cin >> count;
    vector<int> answers(count);
    for (int i = 0; i < count; i++) {
        cin >> answers[i];
    }

    // Construct result mask from answers
    uint64_t outputMask = 0;
    for (int i = 0; i < robots; i++) {
        if (answers[i] == 1) {
            outputMask |= (1ULL << i);
        }
    }

    // Search for matching pair in precomputed masks
    int first = -1, second = -1;
    for (int i = 0; i < items; i++) {
        for (int j = i; j < items; j++) {
            if ((bitMask[i] | bitMask[j]) == outputMask) {
                first = i+1;
                second = j+1;
                break;
            }
        }
        if (first != -1) break;
    }

    // Print final answer
    cout << "! " << first << " " << second << endl;
    cout.flush();

    return 0;
}

#include <iostream>
