#include <chrono>
using namespace std;

int sizeN;
vector<int> perm; // Stores the permutation, 1-based. 0 means unknown.
vector<int> known_positions; // Stores indices where perm is known.

int query(const vector<int>& q) {
    cout << "0";
    for (int val : q) {
        cout << " " << val;
    }
    cout << endl;
    int result;
    cin >> result;
    return result;
}

void submit(const vector<int>& answer) {
    cout << "1";
    for (int i = 0; i < sizeN; ++i) {
        cout << " " << answer[i];
    }
    cout << endl;
    exit(0);
}

// Locate position of target_val among possible positions.
// filler_val is used for positions not currently being tested.
// Assumed that filler_val does not conflict with any actual values in the test set.
int find_position(int target_val, vector<int>& possible, int filler_val) {
    int left = 0, right = possible.size() - 1;
    while (left < right) {
        int middle = left + (right - left) / 2;
        vector<int> query_vec(sizeN);

        // Fill default values first
        for (int idx = 1; idx <= sizeN; ++idx) {
            if (perm[idx] != 0) 
                query_vec[idx-1] = perm[idx];
            else 
                query_vec[idx-1] = filler_val;
        }

        // Override selected range with target_val
        for (int i = left; i <= middle; ++i) {
            query_vec[possible[i]-1] = target_val;
        }

        int score = query(query_vec);

        // Compute expected score from already known entries
        int baseline = 0;
        for (int pos : known_positions) {
            baseline++;
        }

        // If actual score exceeds expected, target_val must be in the left half
        if (score > baseline) {
            right = middle;
        } else {
            left = middle + 1;
        }
    }
    return possible[left];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> sizeN)) return 0;

    perm.assign(sizeN + 1, 0);

    if (sizeN == 1) {
        submit({1});
    }

    // Phase 1: Determine positions of 1 and 2
    vector<int> all_indices(sizeN);
    iota(all_indices.begin(), all_indices.end(), 1);

    mt19937 engine(chrono::steady_clock::now().time_since_epoch().count());

    vector<int> groupA, groupB;
    while (true) {
        shuffle(all_indices.begin(), all_indices.end(), engine);
        int split_point = sizeN / 2;
        groupA.clear(); 
        groupB.clear();
        vector<int> query_vec(sizeN);

        for (int i = 0; i < sizeN; ++i) {
            if (i < split_point) {
                groupA.push_back(all_indices[i]);
                query_vec[all_indices[i]-1] = 1;
            } else {
                groupB.push_back(all_indices[i]);
                query_vec[all_indices[i]-1] = 2;
            }
        }

        int match_count = query(query_vec);
        if (match_count == 2) {
            // 1 in groupA, 2 in groupB
            break;
        } else if (match_count == 0) {
            // 1 in groupB, 2 in groupA
            swap(groupA, groupB);
            break;
        }
        // match_count == 1: retry with new shuffle
    }

    int index_of_one = find_position(1, groupA, 2);
    perm[index_of_one] = 1;
    known_positions.push_back(index_of_one);

    int index_of_two = find_position(2, groupB, 1);
    perm[index_of_two] = 2;
    known_positions.push_back(index_of_two);

    // Phase 2: Find remaining numbers 3 through sizeN
    vector<int> remaining;
    for (int i = 1; i <= sizeN; ++i) {
        if (perm[i] == 0) 
            remaining.push_back(i);
    }

    for (int num = 3; num <= sizeN; ++num) {
        if (remaining.size() == 1) {
            perm[remaining[0]] = num;
            known_positions.push_back(remaining[0]);
            remaining.clear();
            break;
        }

        int found_index = find_position(num, remaining, 1);
        perm[found_index] = num;
        known_positions.push_back(found_index);

        for (int j = 0; j < remaining.size(); ++j) {
            if (remaining[j] == found_index) {
                remaining.erase(remaining.begin() + j);
                break;
            }
        }
    }

    vector<int> final_perm;
    for (int i = 1; i <= sizeN; ++i) 
        final_perm.push_back(perm[i]);

    submit(final_perm);

    return 0;
}

