__host__ void IpcOnImpl::ipcHostInit(int proc_id, const HEAP_BASES_T &symmetric_heap_bases,
                                     MPI_Comm comm_thread) {
  /*
   * Create an MPI communicator restricted to local processes.
   */
  MPI_Comm local_shm_comm;
  mpilib_ftable_.Comm_split_type(comm_thread, MPI_COMM_TYPE_SHARED, 0, MPI_INFO_NULL,
                                 &local_shm_comm);

  /*
   * Determine count of local processes.
   */
  int num_local_procs;
  mpilib_ftable_.Comm_size(local_shm_comm, &num_local_procs);
  shm_size = num_local_procs;

  /*
   * Identify this process’s rank among local peers.
   */
  mpilib_ftable_.Comm_rank(local_shm_comm, &shm_rank);

  /*
   * Allocate host-side storage for IPC handles.
   */
  HIPAllocator *mem_alloc = get_default_allocator();
  HIPIpcHandleVec *handle_array = mem_alloc->AllocateIpcHandleVec(shm_size);

  /*
   * Acquire IPC handle for current process’s symmetric heap.
   */
  char *my_heap_base = symmetric_heap_bases[proc_id];
  CHECK_HIP(mem_alloc->GetIpcHandle(my_heap_base, handle_array->GetHandleVecElem(shm_rank)));

  /*
   * Perform all-to-all exchange of IPC handles among local ranks.
   */
  size_t handle_byte_size = mem_alloc->GetIpcHandleSize();
  mpilib_ftable_.Allgather(MPI_IN_PLACE, handle_byte_size, MPI_CHAR,
                           handle_array->GetHandleVecElem(0), handle_byte_size, MPI_CHAR, local_shm_comm);

  /*
   * Allocate device memory for IPC base addresses.
   */
  char **device_ipc_bases;
  CHECK_HIP(hipMalloc(reinterpret_cast<void **>(&device_ipc_bases),
                      shm_size * sizeof(char *)));

  /*
   * Populate device array with IPC base addresses.
   */
  for (int idx = 0; idx < shm_size; ++idx) {
    if (idx != shm_rank) {
      void **raw_handle_ptr = reinterpret_cast<void **>(&device_ipc_bases[idx]);
      CHECK_HIP(mem_alloc->OpenIpcHandle(raw_handle_ptr, handle_array->GetHandleVecElem(idx)));
    } else {
      device_ipc_bases[idx] = my_heap_base;
    }
  }

  /*
   * Assign initialized device array to member variable.
   */
  ipc_bases = device_ipc_bases;

  /*
   * Release host-side buffer used during handle exchange.
   */
  delete handle_array;

  /*
   * Warn about deprecated environment variables.
   */
  if (envvar::ro::disable_ipc || envvar::disable_ipc) {
    if (0 == proc_id) {
      printf("ROCSHMEM_RO_DISABLE_IPC and RO_DISABLE_IPC environment variables have been deprecated.\n"
             "  Please use ROCSHMEM_DISABLE_MIXED_IPC as a replacement.\n");
    }
  }

  auto mixed_ipc_disabled = envvar::disable_mixed_ipc || envvar::ro::disable_ipc || envvar::disable_ipc;
  if (!mixed_ipc_disabled) {
    CHECK_HIP(hipMalloc(reinterpret_cast<void**>(&pes_with_ipc_avail), shm_size * sizeof(int)));

    MPI_Group thread_group;
    MPI_Group shm_group;
    mpilib_ftable_.Comm_group(comm_thread, &thread_group);
    mpilib_ftable_.Comm_group(local_shm_comm, &shm_group);

    int *rank_mapping = new int[shm_size];
    for (int r = 0; r < shm_size; ++r)
      rank_mapping[r] = r;

    mpilib_ftable_.Group_translate_ranks(shm_group, shm_size, rank_mapping, thread_group, pes_with_ipc_avail);
    delete[] rank_mapping;

    mpilib_ftable_.Group_free(&shm_group);
    mpilib_ftable_.Group_free(&thread_group);
  }

  mpilib_ftable_.Comm_free(&local_shm_comm);
}

__host__ void IpcOnImpl::ipcHostInit(int proc_id, const HEAP_BASES_T &symmetric_heap_bases,
                                     TcpBootstrap *bootstr) {
  shm_size = bootstr->getNranksPerNode();
  auto local_proc_list = bootstr->getLocalRanks();
  shm_rank = std::find(local_proc_list.begin(), local_proc_list.end(), proc_id) - local_proc_list.begin();

  /*
   * Allocate host-side storage for IPC handles.
   */
  HIPAllocator *mem_alloc = get_default_allocator();
  HIPIpcHandleVec *handle_array = mem_alloc->AllocateIpcHandleVec(shm_size);

  /*
   * Acquire IPC handle for current process’s symmetric heap.
   */
  char *my_heap_base = symmetric_heap_bases[proc_id];
  CHECK_HIP(mem_alloc->GetIpcHandle(my_heap_base, handle_array->GetHandleVecElem(shm_rank)));

  /*
   * Perform all-to-all exchange of IPC handles among local ranks.
   */
  size_t handle_byte_size = mem_alloc->GetIpcHandleSize();
  bootstr->groupAllGather(handle_array->GetHandleVecElem(0), handle_byte_size, local_proc_list);

  /*
   * Allocate device memory for IPC base addresses.
   */
  char **device_ipc_bases;
  CHECK_HIP(hipMalloc(reinterpret_cast<void **>(&device_ipc_bases),
                      shm_size * sizeof(char *)));

  /*
   * Populate device array with IPC base addresses.
   */
  for (int idx = 0; idx < shm_size; ++idx) {
    if (idx != shm_rank) {
      void **raw_handle_ptr = reinterpret_cast<void **>(&device_ipc_bases[idx]);
      CHECK_HIP(mem_alloc->OpenIpcHandle(raw_handle_ptr, handle_array->GetHandleVecElem(idx)));
    } else {
      device_ipc_bases[idx] = my_heap_base;
    }
  }

  /*
   * Assign initialized device array to member variable.
   */
  ipc_bases = device_ipc_bases;

  /*
   * Release host-side buffer used during handle exchange.
   */
  delete handle_array;

  /*
   * Warn about deprecated environment variables.
   */
  if (envvar::ro::disable_ipc || envvar::disable_ipc) {
    if (0 == proc_id) {
      printf("ROCSHMEM_RO_DISABLE_IPC and RO_DISABLE_IPC environment variables have been deprecated.\n"
             "  Please use ROCSHMEM_DISABLE_MIXED_IPC as a replacement.\n");
    }
  }

  auto mixed_ipc_disabled = envvar::disable_mixed_ipc || envvar::ro::disable_ipc || envvar::disable_ipc;
  if (!mixed_ipc_disabled) {
    CHECK_HIP(hipMalloc(reinterpret_cast<void**>(&pes_with_ipc_avail), shm_size * sizeof(int)));
    std::copy(local_proc_list.begin(), local_proc_list.end(), pes_with_ipc_avail);
  }
}

__host__ void IpcOnImpl::ipcHostStop() {
  HIPAllocator *mem_alloc = get_default_allocator();
  for (int idx = 0; idx < shm_size; ++idx) {
    if (idx != shm_rank) {
      CHECK_HIP(mem_alloc->CloseIpcHandle(ipc_bases[idx]));
    }
  }
  CHECK_HIP(hipFree(ipc_bases));
  if (nullptr != pes_with_ipc_avail) {
    CHECK_HIP(hipFree(pes_with_ipc_avail));
  }
}

