TEST(std_test, head_for_each_if) {
  /* typical scenario */
  {
    std::vector<int> input = {0, 7, 28, 1, 2, 5, 7, 9, 1, 3, 65,
                              0, 0, 0,  1, 2, 3, 0, 4, 0, 0, 1};
    /* build min heap */
    std::make_heap(input.begin(), input.end(), std::greater<int>());
    const std::vector<int> expected_values(7, 0);
    std::vector<int> collected_values;
    std::vector<const int*> address_references;
    irstd::heap::ForEachIf(
      input.begin(), input.end(), [](int val) { return 0 == val; },
      [&collected_values, &address_references](const int& value) {
        collected_values.push_back(value);
        address_references.push_back(&value);
      });
    address_references.erase(std::unique(address_references.begin(), address_references.end()), address_references.end());
    ASSERT_EQ(expected_values, collected_values);
    /* verify uniqueness of elements */
    ASSERT_EQ(collected_values.size(), address_references.size());
  }
}

TEST(std_test, heap_for_each_top) {
  /* typical scenario */
  {
    std::vector<int> input_data = {0, 7, 28, 1, 2, 5, 7, 9, 1, 3, 65,
                                   0, 0, 0,  1, 2, 3, 0, 4, 0, 0, 1};
    /* construct min heap */
    std::make_heap(input_data.begin(), input_data.end(), std::greater<int>());
    const std::vector<int> expected_result(7, 0);
    std::vector<int> actual_result;
    std::vector<const int*> ptr_refs;
    irstd::heap::ForEachTop(input_data.begin(), input_data.end(),
                            [&actual_result, &ptr_refs](const int& item) {
                              actual_result.push_back(item);
                              ptr_refs.push_back(&item);
                            });
    ptr_refs.erase(std::unique(ptr_refs.begin(), ptr_refs.end()), ptr_refs.end());
    ASSERT_EQ(expected_result, actual_result);
    /* ensure distinct element references */
    ASSERT_EQ(actual_result.size(), ptr_refs.size());
  }

  /* empty container case */
  {
    const std::vector<int> empty_input;
    std::vector<int> empty_result;
    std::vector<const int*> empty_refs;
    irstd::heap::ForEachTop(empty_input.begin(), empty_input.end(),
                            [&empty_result, &empty_refs](const int& item) {
                              empty_result.push_back(item);
                              empty_refs.push_back(&item);
                            });
    empty_refs.erase(std::unique(empty_refs.begin(), empty_refs.end()), empty_refs.end());
    ASSERT_EQ(empty_input, empty_result);
    ASSERT_EQ(empty_result.size(), empty_refs.size());
  }

  /* all elements equal */
  {
    const std::vector<int> uniform_input(15, 1);
    std::vector<int> uniform_result;
    std::vector<const int*> uniform_refs;
    irstd::heap::ForEachTop(uniform_input.begin(), uniform_input.end(),
                            [&uniform_result, &uniform_refs](const int& item) {
                              uniform_result.push_back(item);
                              uniform_refs.push_back(&item);
                            });
    uniform_refs.erase(std::unique(uniform_refs.begin(), uniform_refs.end()), uniform_refs.end());
    ASSERT_EQ(uniform_input, uniform_result);
    ASSERT_EQ(uniform_result.size(), uniform_refs.size());
  }
}

TEST(std_test, ALL_EQUAL) {
  /* all same values */
  {
    const std::vector<int> identical_elements(10, 0);
    ASSERT_TRUE(irstd::AllEqual(identical_elements.begin(), identical_elements.end()));
  }

  /* empty container */
  {
    const std::vector<int> empty_container;
    ASSERT_TRUE(irstd::AllEqual(empty_container.begin(), empty_container.end()));
  }

  /* mixed values */
  {
    const std::vector<int> varied_elements{0, 4, 1, 3, 4, 1, 2, 51, 21, 32};
    ASSERT_FALSE(irstd::AllEqual(varied_elements.begin(), varied_elements.end()));
  }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int size;
    cin >> size;

    if (size == 1) {
        cout << 1 << " " << 1 << endl;
        cout.flush();
        return 0;
    }

    vector<int> base_perm(size + 1);
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
    bool found = false;
    int attempts = 0;

    while (!found && attempts < 100) {
        vector<int> candidate(size);
        iota(candidate.begin(), candidate.end(), 1);
        shuffle(candidate.begin(), candidate.end(), rng);

        cout << 0;
        for (int val : candidate) cout << " " << val;
        cout << endl;
        cout.flush();

        int response;
        cin >> response;

        if (response == 0) {
            found = true;
            for (int idx = 1; idx <= size; idx++) {
                base_perm[idx] = candidate[idx - 1];
            }
        }
        attempts++;
    }

    vector<int> result(size + 1, 0);
    int discovered = 0;

    for (int value = 1; value <= size; value++) {
        vector<int> available;
        for (int pos = 1; pos <= size; pos++) {
            if (result[pos] == 0) available.push_back(pos);
        }

        int left = 0, right = available.size() - 1;
        while (left < right) {
            int mid = (left + right) / 2;
            vector<int> subset;
            for (int k = left; k <= mid; k++) subset.push_back(available[k]);

            vector<int> temp(size + 1);
            for (int i = 1; i <= size; i++) temp[i] = base_perm[i];
            for (int position : subset) temp[position] = value;

            cout << 0;
            for (int i = 1; i <= size; i++) cout << " " << temp[i];
            cout << endl;
            cout.flush();

            int res;
            cin >> res;
            int count_diff = res - discovered;

            if (count_diff == 1) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        int position = available[left];
        result[position] = value;
        base_perm[position] = value;
        discovered++;
    }

    cout << 1;
    for (int i = 1; i <= size; i++) cout << " " << result[i];
    cout << endl;
    cout.flush();

    return 0;
}

