        values.reserve(sizeN * sizeN);

        // Read the n x n matrix
        for (int row = 0; row < sizeN; ++row) {
            for (int col = 0; col < sizeN; ++col) {
                int inputVal;
                cin >> inputVal;
                values.push_back(inputVal);
            }
        }

        // Sort all values in ascending order
        sort(values.begin(), values.end());

        cout << '!';
        int valueCount = (int)values.size();

        // Output the first m values (or last value if m exceeds size)
        for (long long idx = 0; idx < targetCount; ++idx) {
            int currentVal = (idx < valueCount) ? values[(size_t)idx] : values.back();
            cout << ' ' << currentVal;
        }
        cout << '\n';
        cout.flush();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <ctime>
using namespace std;

// Edge representation for graph connections
struct Connection {
    int from, to;
};

// Global configuration variables
int vertexCount, edgeCount;
vector<Connection> edgeList;
vector<vector<int>> adjacency; // adjacency[u] holds indices of edges incident to u
vector<int> optimalAssignment; // Best feasible vertex cover found so far
int optimalSize;               // Size (cardinality) of the best solution

void findSolution() {
    // Time budget constraint (targeting under 2.0 seconds)
    double maxTime = 1.9;
    clock_t startTime = clock();

    // Random number generator with fixed seed for reproducibility
    mt19937 randomGen(1337);

    // Initialize with trivial full vertex cover
    optimalAssignment.assign(vertexCount + 1, 1);
    optimalSize = vertexCount;

    // Precompute initial degrees for efficiency
    vector<int> initialDegrees(vertexCount + 1, 0);
    for (const auto& conn : edgeList) {
        initialDegrees[conn.from]++;
        initialDegrees[conn.to]++;
    }

    // Reusable buffers for iterative computation
    vector<int> currentAssignment(vertexCount + 1);
    vector<int> dynamicDegrees(vertexCount + 1);
    vector<int> edgeStatus(edgeCount);          // 0: uncovered, 1: covered
    vector<int> uncoveredList(edgeCount);       // Active uncovered edge indices
    vector<int> positionMap(edgeCount);         // Maps edge index -> position in uncoveredList
    vector<int> coverageCounts(edgeCount);      // Number of selected endpoints per edge
    vector<int> candidateVertices;              // Current solution vertices
    candidateVertices.reserve(vertexCount);

    // Main optimization loop with time limit
    while (true) {
        // Check if time budget exceeded
        double elapsed = (double)(clock() - startTime) / CLOCKS_PER_SEC;
        if (elapsed > maxTime) break;

        // --- Reset state for new iteration ---
        fill(currentAssignment.begin(), currentAssignment.end(), 0);
        dynamicDegrees = initialDegrees;

        // Reset uncovered edge tracking
        for (int i = 0; i < edgeCount; ++i) {
            uncoveredList[i] = i;
            positionMap[i] = i;
            edgeStatus[i] = 0;
        }
        int remainingEdges = edgeCount;
        int currentCoverSize = 0;

        // --- Greedy construction phase ---
        while (remainingEdges > 0) {
            // Select random uncovered edge
            int randomIndex = randomGen() % remainingEdges;
            int edgeIndex = uncoveredList[randomIndex];

            int u = edgeList[edgeIndex].from;
            int v = edgeList[edgeIndex].to;

            // Choose endpoint with higher dynamic degree (tie-break randomly)
            int selectedVertex = -1;
            if (dynamicDegrees[u] > dynamicDegrees[v]) 
                selectedVertex = u;
            else if (dynamicDegrees[v] > dynamicDegrees[u]) 
                selectedVertex = v;
            else 
                selectedVertex = (randomGen() & 1) ? u : v;

            // Add vertex to current solution
            currentAssignment[selectedVertex] = 1;
            currentCoverSize++;

            // Update status of incident edges
            for (int incidentEdge : adjacency[selectedVertex]) {
                if (edgeStatus[incidentEdge] == 1) continue;

                edgeStatus[incidentEdge] = 1;

                // Efficient removal from uncovered list (O(1))
                int pos = positionMap[incidentEdge];
                int lastEdge = uncoveredList[remainingEdges - 1];

                uncoveredList[pos] = lastEdge;
                positionMap[lastEdge] = pos;

                remainingEdges--;

                // Decrease neighbor's dynamic degree
                int neighbor = (edgeList[incidentEdge].from == selectedVertex) 
                             ? edgeList[incidentEdge].to 
                             : edgeList[incidentEdge].from;
                dynamicDegrees[neighbor]--;
            }
        }

        // --- Local improvement: remove redundant vertices ---
        fill(coverageCounts.begin(), coverageCounts.end(), 0);
        candidateVertices.clear();

        // Compute coverage counts and collect solution vertices
        for (int i = 1; i <= vertexCount; ++i) {
            if (currentAssignment[i]) {
                candidateVertices.push_back(i);
                for (int eIdx : adjacency[i]) {
                    coverageCounts[eIdx]++;
                }
            }
        }

        // Randomize processing order for exploration
        shuffle(candidateVertices.begin(), candidateVertices.end(), randomGen);

        for (int vertex : candidateVertices) {
            bool canRemove = true;

            // Check if all incident edges have alternative coverage
            for (int eIdx : adjacency[vertex]) {
                if (coverageCounts[eIdx] < 2) {
                    canRemove = false;
                    break;
                }
            }

            if (canRemove) {
                currentAssignment[vertex] = 0;
                currentCoverSize--;

                // Update coverage counts
                for (int eIdx : adjacency[vertex]) {
                    coverageCounts[eIdx]--;
                }
            }
        }

        // --- Update global best solution ---
        if (currentCoverSize < optimalSize) {
            optimalSize = currentCoverSize;
            optimalAssignment = currentAssignment;
        }
    }
}

int main() {
    // Enable fast I/O
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (cin >> vertexCount >> edgeCount) {
        adjacency.resize(vertexCount + 1);
        edgeList.reserve(edgeCount);

        for (int i = 0; i < edgeCount; ++i) {
            int u, v;
            cin >> u >> v;
            edgeList.push_back({u, v});
            adjacency[u].push_back(i);
            adjacency[v].push_back(i);
        }

        findSolution();

        // Output final vertex cover assignment
        for (int i = 1; i <= vertexCount; ++i) {
            cout << optimalAssignment[i] << "\n";
        }
    }

    return 0;
}

