#include "draw_rectangular_marquee.h"
#include "gl.h"
#include "glu.h"
#include "../material_colors.h"

IGL_INLINE void igl::opengl2::draw_rectangular_marquee(
  const int start_x,
  const int start_y,
  const int end_x,
  const int end_y)
{
  using namespace std;

  int lighting_enabled;
  glGetIntegerv(GL_LIGHTING, &lighting_enabled);

  int stipple_enabled;
  glGetIntegerv(GL_LINE_STIPPLE, &stipple_enabled);

  double line_width;
  glGetDoublev(GL_LINE_WIDTH, &line_width);

  glDisable(GL_LIGHTING);

  // Screen space for this viewport
  GLint viewport_data[4];
  glGetIntegerv(GL_VIEWPORT, viewport_data);

  const int view_width = viewport_data[2];
  const int view_height = viewport_data[3];

  glMatrixMode(GL_PROJECTION);
  glPushMatrix();
  glLoadIdentity();
  gluOrtho2D(0, view_width, 0, view_height);

  glMatrixMode(GL_MODELVIEW);
  glPushMatrix();
  glLoadIdentity();

  glEnable(GL_LINE_STIPPLE);
  glLineStipple(3, 0x5555);
  glLineWidth(1.0);
  glColor4f(0.3, 0.3, 0.3, 1.0);

  glBegin(GL_LINE_STRIP);
  glVertex2d(start_x, start_y);
  glVertex2d(end_x, start_y);
  glVertex2d(end_x, end_y);
  glVertex2d(start_x, end_y);
  glVertex2d(start_x, start_y);
  glEnd();

  glPopMatrix();
  glMatrixMode(GL_PROJECTION);
  glPopMatrix();
  glMatrixMode(GL_MODELVIEW);

  glLineWidth(line_width);

  (stipple_enabled ? glEnable(GL_LINE_STIPPLE) : glDisable(GL_LINE_STIPPLE));
  (lighting_enabled ? glEnable(GL_LIGHTING) : glDisable(GL_LIGHTING));
}

