void CreateTestFile(const std::string &archivePath)
{
    AbcA::MetaData md;
    md.setUnique("name", "arkive");
    Alembic::AbcCoreOgawa::WriteArchive aw;
    AbcA::ArchiveWriterPtr archive = aw(archivePath, md);

    AbcA::ObjectWriterPtr root = archive->getTop();
    AbcA::ObjectWriterPtr deepestChild;

    {
        md.set("name", "objLevel1");
        AbcA::ObjectWriterPtr level1 = root->createChild(
            AbcA::ObjectHeader("level1", md));

        md.set("name", "objLevel2");
        AbcA::ObjectWriterPtr level2 = level1->createChild(
            AbcA::ObjectHeader("level2", md));

        md.set("name", "objLevel3");
        deepestChild = level2->createChild(
            AbcA::ObjectHeader("level3", md));
    }

    AbcA::CompoundPropertyWriterPtr props = deepestChild->getProperties();

    const AbcA::TimeSamplingType cyclicType(2, 2.0);
    const size_t sampleCount = 50;
    const Dimensions dims(sampleCount);
    const AbcA::DataType int32Type(Alembic::Util::kInt32POD, 1);

    // First array property
    AbcA::PropertyHeader header1("intArrayProp1", AbcA::kArrayProperty,
                                 AbcA::MetaData(), int32Type, cyclicType);
    AbcA::ArrayPropertyWriterPtr arrProp1 = props->createArrayProperty(header1);

    std::vector<Alembic::Util::int32_t> data0;
    for (size_t i = 0; i < sampleCount; ++i)
        data0.push_back(static_cast<int32_t>(i));
    AbcA::ArraySample samp0((const void*)&data0[0], int32Type, dims);
    arrProp1->setSample(0, 0.0, samp0);

    std::vector<Alembic::Util::int32_t> data1;
    for (size_t i = 0; i < 30; ++i)
        data1.push_back(static_cast<int32_t>(i + 1));
    AbcA::ArraySample samp1((const void*)&data1[0], int32Type, Dimensions(30));
    arrProp1->setSample(1, 1.0, samp1);

    std::vector<Alembic::Util::int32_t> data2;
    for (size_t i = 0; i < sampleCount; ++i)
        data2.push_back(static_cast<int32_t>(i + 2));
    AbcA::ArraySample samp2((const void*)&data2[0], int32Type, dims);
    arrProp1->setSample(2, 2.0, samp2);

    std::vector<Alembic::Util::int32_t> data3;
    for (size_t i = 0; i < sampleCount; ++i)
        data3.push_back(static_cast<int32_t>(i + 3));
    AbcA::ArraySample samp3((const void*)&data3[0], int32Type, dims);
    arrProp1->setSample(3, 3.0, samp3);

    std::vector<Alembic::Util::int32_t> data4;
    for (size_t i = 0; i < sampleCount; ++i)
        data4.push_back(static_cast<int32_t>(i + 4));
    AbcA::ArraySample samp4((const void*)&data4[0], int32Type, dims);
    arrProp1->setSample(4, 4.0, samp4);

    std::vector<Alembic::Util::int32_t> data5;
    for (size_t i = 0; i < 2; ++i)
        data5.push_back(static_cast<int32_t>(i + 5));
    AbcA::ArraySample samp5((const void*)&data5[0], int32Type, Dimensions(2));
    arrProp1->setSample(5, 5.0, samp5);

    std::vector<Alembic::Util::int32_t> data6;
    for (size_t i = 0; i < 78; ++i)
        data6.push_back(static_cast<int32_t>(i + 6));
    AbcA::ArraySample samp6((const void*)&data6[0], int32Type, Dimensions(78));
    arrProp1->setSample(6, 6.0, samp6);

    // Second array property with acyclic time sampling
    AbcA::PropertyHeader header2("intArrayProp2", AbcA::kArrayProperty,
                                 AbcA::MetaData(), int32Type,
                                 AbcA::TimeSamplingType(
                                     AbcA::TimeSamplingType::kAcyclic));
    AbcA::ArrayPropertyWriterPtr arrProp2 = props->createArrayProperty(header2);

    std::vector<int32_t> secData0;
    for (size_t i = 0; i < 2; ++i)
        secData0.push_back(static_cast<int32_t>(i));
    AbcA::ArraySample secSamp0((const void*)&secData0[0], int32Type, Dimensions(2));
    arrProp2->setSample(0, 0.0, secSamp0);

    std::vector<int32_t> secData1;
    for (size_t i = 0; i < 10; ++i)
        secData1.push_back(static_cast<int32_t>(i + 1));
    AbcA::ArraySample secSamp1((const void*)&secData1[0], int32Type, Dimensions(10));
    arrProp2->setSample(1, 0.5, secSamp1);

    std::vector<int32_t> secData2;
    for (size_t i = 0; i < 23; ++i)
        secData2.push_back(static_cast<int32_t>(i + 2));
    AbcA::ArraySample secSamp2((const void*)&secData2[0], int32Type, Dimensions(23));
    arrProp2->setSample(2, 2.3, secSamp2);

    // Scalar property
