    float32_t scalarValue = 42.0f;
    scalarProp->setSample(0, 0.0, (const void*)&scalarValue);
}

//-*****************************************************************************
void LoadTestFile(const std::string &archivePath)
{
    Alembic::AbcCoreOgawa::ReadArchive ar;
    AbcA::ArchiveReaderPtr archive = ar(archivePath);

    AbcA::CompoundPropertyReaderPtr props;
    AbcA::ObjectReaderPtr currentObj = archive->getTop();

    while (true)
    {
        if (currentObj->getNumChildren() == 0)
        {
            std::cout << "Reached deepest object: " << currentObj->getFullName()
                      << std::endl;
            props = currentObj->getProperties();
            std::cout << "Properties count: " << props->getNumProperties()
                      << std::endl;
            break;
        }
        currentObj = currentObj->getChild(0);
    }

    AbcA::ScalarPropertyReaderPtr scalarProp;
    AbcA::ArrayPropertyReaderPtr arrayProp1;
    AbcA::ArrayPropertyReaderPtr arrayProp2;

    for (size_t i = 0; i < props->getNumProperties(); ++i)
    {
        AbcA::BasePropertyReaderPtr baseProp = props->getProperty(i);
        std::cout << "Found property: " << baseProp->getName() << std::endl;

        if (baseProp->isScalar())
        {
            scalarProp = baseProp->asScalarPtr();
            std::cout << "Scalar samples: " << scalarProp->getNumSamples()
                      << std::endl;
        }

        if (baseProp->isArray() && baseProp->getName() == "intArrayProp2")
        {
            arrayProp2 = baseProp->asArrayPtr();
            std::cout << "Array 2 samples: " << arrayProp2->getNumSamples()
                      << std::endl;
        }

        if (baseProp->isArray() && baseProp->getName() == "intArrayProp1")
        {
            arrayProp1 = baseProp->asArrayPtr();
            std::cout << "Array 1 samples: " << arrayProp1->getNumSamples()
                      << std::endl;
        }
    }

    // Read scalar property
    for (size_t i = 0; i < scalarProp->getNumSamples(); ++i)
    {
        float32_t val = 0.0f;
        scalarProp->getSample(i, (void*)&val);
        TESTING_ASSERT(val == 42.0f);
        std::cout << scalarProp->getName() << " at sample " << i << ": " << val
                  << std::endl << std::endl;
    }

    // Read first array property (cyclic)
    AbcA::ArraySamplePtr sample;
    std::cout << "FIRST ARRAY PROPERTY (Cyclic)" << std::endl;
    for (size_t i = 0; i < arrayProp1->getNumSamples(); ++i)
    {
        arrayProp1->getSample(i, sample);
        const AbcA::TimeSampling ts = arrayProp1->getTimeSampling();
        size_t pointCount = sample->getDimensions().numPoints();
        TESTING_ASSERT((AbcA::chrono_t)i == ts.getSampleTime(i));

        std::cout << "Sample " << i << ", time " << ts.getSampleTime(i)
                  << ", points: " << pointCount << std::endl;

        int32_t* values = (int32_t*)(sample->getData());
        for (size_t j = 0; j < pointCount; ++j)
        {
            TESTING_ASSERT(values[j] == static_cast<int32_t>(i + j));
            std::cout << j << ": " << values[j] << ", ";
        }
        std::cout << std::endl << std::endl;
        sample->reset();
    }

    // Read second array property (acyclic)
    std::cout << "SECOND ARRAY PROPERTY (Acyclic)" << std::endl;
    for (size_t i = 0; i < arrayProp2->getNumSamples(); ++i)
    {
        arrayProp2->getSample(i, sample);
        const AbcA::TimeSampling ts = arrayProp2->getTimeSampling();
        size_t pointCount = sample->getDimensions().numPoints();

        std::cout << "Sample " << i << ", time " << ts.getSampleTime(i)
                  << ", points: " << pointCount << std::endl
                  << "Values: ";

        int32_t* values = (int32_t*)(sample->getData());
        for (size_t j = 0; j < pointCount; ++j)
        {
            TESTING_ASSERT(values[j] == static_cast<int32_t>(i + j));
            std::cout << j << ": " << values[j] << ", ";
        }
        std::cout << std::endl << std::endl;
        sample->reset();
    }
}

//-*****************************************************************************
int main(int, char**)
{
    const std::string archiveName("test_output.abc");
    CreateTestFile(archiveName);
    LoadTestFile(archiveName);
    return 0;
}

