/// @file
/// @brief Arris "Manchester code" based protocol.
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595
// Supports:
//   Brand: Arris,  Model: VIP1113M Set-top box
//   Brand: Arris,  Model: 120A V1.0 A18 remote
const uint8_t kArrisProtocolOverhead = 2;
const uint16_t kArrisProtocolHalfPeriod = 320;  // uSeconds
const uint16_t kArrisProtocolHeaderMark = 8 * kArrisProtocolHalfPeriod;  // uSeconds
const uint16_t kArrisProtocolHeaderSpace = 6 * kArrisProtocolHalfPeriod;  // uSeconds
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595#issuecomment-913755841
// aka. 77184 uSeconds.
const uint32_t kArrisProtocolGap = 102144 - ((8 + 6 + kArrisProtocolBits * 2) *
                                             kArrisProtocolHalfPeriod);  // uSeconds
const uint32_t kArrisProtocolReleaseToggle = 0x800008;
const uint8_t kArrisProtocolChecksumWidth = 4;
const uint8_t kArrisProtocolCommandWidth = 19;
const uint8_t kArrisProtocolReleasePosition = kArrisProtocolChecksumWidth + kArrisProtocolCommandWidth;
using irutils::sumNibbles;
#if SEND_ARRIS
/// Send an Arris Manchester Code formatted message.
/// Status: STABLE / Confirmed working.
/// @param[in] message The data payload to be transmitted.
/// @param[in] bitCount The number of bits in the message payload.
/// @param[in] repeats The number of times the command should be repeated.
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595
void IRsend::sendArris(const uint64_t message, const uint16_t bitCount,
                       const uint16_t repeats) {
  enableIROut(38);
  for (uint16_t repetition = 0; repetition <= repeats; repetition++) {
    // Header sequence start
    mark(kArrisProtocolHeaderMark);
    space(kArrisProtocolHeaderSpace);
    // Data transmission with Manchester encoding
    sendManchester(kArrisProtocolHalfPeriod * 2, 0, kArrisProtocolHalfPeriod,
                   0, kArrisProtocolGap, message, bitCount);
  }
}
/// Toggle the release indicator bit in an Arris protocol message.
/// Used to differentiate between button press and button release events.
/// @param[in] originalMessage The existing Arris protocol message.
/// @return A modified message with the release bit inverted.
uint32_t IRsend::toggleArrisRelease(const uint32_t originalMessage) {
  return originalMessage ^ kArrisProtocolReleaseToggle;
}
/// Construct a complete 32-bit Arris protocol message from components.
/// @param[in] commandCode The command identifier value.
/// @param[in] isReleaseEvent True if this represents a button release event.
/// @return A fully encoded 32-bit Arris protocol message ready for transmission.
/// @note Bit layout: header(32) + release_bit + command + checksum.
uint32_t IRsend::encodeArris(const uint32_t commandCode, const bool isReleaseEvent) {
  uint32_t encodedMessage = 0x10000000;
  irutils::setBits(&encodedMessage, kArrisProtocolChecksumWidth, kArrisProtocolCommandWidth, commandCode);
  irutils::setBit(&encodedMessage, kArrisProtocolReleasePosition, isReleaseEvent);
  return encodedMessage + sumNibbles(encodedMessage);
}
#endif  // SEND_ARRIS
#if DECODE_ARRIS
/// Decode an Arris Manchester-encoded infrared signal.
/// Status: STABLE / Confirmed working.
/// @param[in,out] decodeResults Pointer to storage for decoded results.
/// @param[in] startIndex Position in raw buffer where decoding should begin.
/// @param[in] expectedBits Number of data bits expected in the message.
/// @param[in] enforceStrictMode Whether to enforce strict protocol compliance.
/// @return true if decoding succeeded, false otherwise.
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595
bool IRrecv::decodeArris(decode_results *decodeResults, uint16_t startIndex,
                         const uint16_t expectedBits, const bool enforceStrictMode) {
  if (decodeResults->rawlen < expectedBits + kArrisProtocolOverhead - startIndex)
    return false;  // Signal too short for valid protocol match.
  // Protocol validation
  if (enforceStrictMode && expectedBits != kArrisProtocolBits)
    return false;  // Bit count doesn't match specification.
  // Parse header portion
  if (!matchMark(decodeResults->rawbuf[startIndex++], kArrisProtocolHeaderMark)) return false;
  if (!matchSpace(decodeResults->rawbuf[startIndex++], kArrisProtocolHeaderSpace)) return false;
  // Extract data payload using Manchester decoding
  uint64_t decodedData = 0;
  if (!matchManchester(decodeResults->rawbuf + startIndex, &decodedData,
                       decodeResults->rawlen - startIndex, expectedBits,
                       kArrisProtocolHalfPeriod * 2, 0,
                       kArrisProtocolHalfPeriod, 0, 0,
                       false, kUseDefTol, kMarkExcess, true, false))
    return false;
  // Checksum verification when strict mode enabled
  if (enforceStrictMode)
    if (GETBITS32(decodedData, 0, kArrisProtocolChecksumWidth) !=
        sumNibbles(decodedData >> kArrisProtocolChecksumWidth))
      return false;
  // Store successful decode results
  decodeResults->decode_type = decode_type_t::ARRIS;
  decodeResults->bits = expectedBits;
  decodeResults->value = decodedData;
  // Extract and store control information
  decodeResults->address = static_cast<bool>(GETBIT32(decodedData, kArrisProtocolReleasePosition));
  // Extract command portion excluding checksum bits
  decodeResults->command = GETBITS32(decodedData, kArrisProtocolChecksumWidth, kArrisProtocolCommandWidth);
  return true;
}
#endif  // DECODE_ARRIS

