class MorphologyFx final : public TStandardRasterFx {
  FX_PLUGIN_DECLARATION(MorphologyFx)
  TRasterFxPort m_source;
  TIntEnumParamP m_shape;
  TDoubleParamP m_size;
public:
  MorphologyFx() : m_shape(new TIntEnumParam(0, "Box")), m_size(0.0) {
    addInputPort("Input", m_source);
    bindParam(this, "shape", m_shape);
    m_shape->addItem(1, "Disk");
    m_size->setMeasureName("fxLength");
    bindParam(this, "size", m_size);
  }
  bool doGetBBox(double frame, TRectD &bbox,
                 const TRenderSettings &info) override;
  void doDryCompute(TRectD &rect, double frame,
                    const TRenderSettings &ri) override;
  void doCompute(TTile &tile, double frame, const TRenderSettings &ri) override;
  int getMemoryRequirement(const TRectD &rect, double frame,
                           const TRenderSettings &info) override;
  bool canHandle(const TRenderSettings &info, double frame) override {
    return isAlmostIsotropic(info.m_affine);
  }
};
//-------------------------------------------------------------------
bool MorphologyFx::doGetBBox(double frame, TRectD &bbox,
                             const TRenderSettings &info) {
  // Note: info.m_affine MUST NOT BE CONSIDERED in doGetBBox's
  // implementation
  // Get the source bbox without applied affines.
  if (!m_source.getFx()) return false;
  bool result = m_source->doGetBBox(frame, bbox, info);
  bbox = bbox.enlarge(tceil(m_size->getValue(frame)));
  return result;
}
//-------------------------------------------------------------------
void MorphologyFx::doCompute(TTile &tile, double frame,
                             const TRenderSettings &info) {
  if (!m_source.isConnected()) return;
  double radius = m_size->getValue(frame) * sqrt(info.m_affine.det());
  bool expand   = (radius >= 0.0);
  TRop::ErodilateMaskType mode = TRop::ErodilateMaskType(m_shape->getValue());
  if (expand) {
    // Relatively straightforward - forward the request to compute input tile
    m_source->compute(tile, frame, info);
    // Then apply TRop::erodilate with scale-adjusted radius
    const TRasterP &ras = tile.getRaster();
    TRop::erodilate(ras, ras, radius, mode);
  } else {
    // For erosion, we need input enlarged by the radius value
    int radI = tceil(fabs(radius));
    const TDimension &tileSize = tile.getRaster()->getSize();
    const TRectD &expandedRect =
        TRectD(tile.m_pos, TDimensionD(tileSize.lx, tileSize.ly)).enlarge(radI);
    TDimension expandedSize(tround(expandedRect.getLx()),
                            tround(expandedRect.getLy()));
    TTile srcTile;
    m_source->allocateAndCompute(srcTile, expandedRect.getP00(), expandedSize,
                                 tile.getRaster(), frame, info);
    const TRasterP &srcRas = srcTile.getRaster();
    TRop::erodilate(srcRas, srcRas, radius, mode);
    tile.getRaster()->copy(srcRas, -TPoint(radI, radI));
  }
}
//-------------------------------------------------------------------
void MorphologyFx::doDryCompute(TRectD &rect, double frame,
                                const TRenderSettings &info) {
  if (!m_source.isConnected()) return;
  double radius = m_size->getValue(frame) * sqrt(info.m_affine.det());
  bool expand   = (radius >= 0.0);
  if (expand)
    m_source->dryCompute(rect, frame, info);
  else {
    int radI = tceil(fabs(radius));
    TRectD expandedRect(rect.enlarge(radI));
    m_source->dryCompute(expandedRect, frame, info);
  }
}
//------------------------------------------------------------------
int MorphologyFx::getMemoryRequirement(const TRectD &rect, double frame,
                                       const TRenderSettings &info) {
  return (m_shape->getValue() == 0) ? TRasterFx::memorySize(rect, 8)
                                    :              // One additional greymaps
               2 * TRasterFx::memorySize(rect, 8);  // Two additional greymaps
}
//------------------------------------------------------------------
FX_PLUGIN_IDENTIFIER(MorphologyFx, "morphologyFx");

