typedef struct __attribute__((aligned(16))) {
    uint64_t low_part;
    uint64_t high_part;
} uint128_struct;

template<>
inline bool compare_and_swap_128(volatile uint128_struct *target, 
                                 const uint128_struct& expected, 
                                 const uint128_struct& desired) {
    uint64_t exp_lo = expected.low_part;
    uint64_t exp_hi = expected.high_part;
    uint64_t new_lo = desired.low_part;
    uint64_t new_hi = desired.high_part;
    unsigned char success_flag = 0;

    __asm__ __volatile__ (
        "lock cmpxchg16b %2\n\t"
        "setz %0\n\t"
        : "=q" (success_flag), "+m" (*target)
        : "a" (exp_lo), "d" (exp_hi), "b" (new_lo), "c" (new_hi)
        : "cc", "memory"
    );

    return static_cast<bool>(success_flag);
}

#include <immintrin.h> // For AVX intrinsics

// Reorder function with SIMD optimization for contiguous non-zero elements
void reorder(float* output, const float* input, size_t length) {
    size_t idx = 0;
    while (idx < length) {
        // Check if we have at least 8 elements remaining and all are non-zero
        bool all_nonzero = true;
        for (int j = 0; j < 8; ++j) {
            if (idx + j >= length || input[idx + j] == 0.0f) {
                all_nonzero = false;
                break;
            }
        }

        if (all_nonzero) {
            // Load 8 floats using unaligned load
            __m256 simd_vec = _mm256_loadu_ps(&input[idx]);
            // Store 8 floats to output using unaligned store
            _mm256_storeu_ps(&output[idx], simd_vec);
            idx += 8;
        } else {
            // Process single element when condition not met
            output[idx] = input[idx];
            idx++;
        }
    }
}

#include <immintrin.h>

// Performs complex conjugate multiplication using AVX intrinsics
// Each cfloat is represented as two consecutive floats: [real, imag]
void avx_vcmulcc(cfloat* out, const cfloat* in1, const cfloat* in2, int n) {
    for (int idx = 0; idx < n; idx += 8) {
        // Load 8 complex numbers (16 floats total) from each input array
        __m256 vec_in1 = _mm256_loadu_ps(reinterpret_cast<const float*>(in1 + idx));
        __m256 vec_in2 = _mm256_loadu_ps(reinterpret_cast<const float*>(in2 + idx));

        // Extract real and imaginary parts using permutation
        // Real part: [r1, i1, r2, i2, r3, i3, r4, i4] -> [r1, r2, r3, r4, i1, i2, i3, i4]
        __m256 reals1 = _mm256_permute_ps(vec_in1, _MM_SHUFFLE(2, 0, 2, 0));
        __m256 imags1 = _mm256_permute_ps(vec_in1, _MM_SHUFFLE(3, 1, 3, 1));

        __m256 reals2 = _mm256_permute_ps(vec_in2, _MM_SHUFFLE(2, 0, 2, 0));
        __m256 imags2 = _mm256_permute_ps(vec_in2, _MM_SHUFFLE(3, 1, 3, 1));

        // Apply complex conjugate to first operand: (a - bj)
        imags1 = _mm256_sub_ps(_mm256_setzero_ps(), imags1);

        // Compute (a + bj)(c + dj) where b is conjugated: (a - bj)(c + dj)
        // = (ac + bd) + j(ad - bc)
        __m256 ac = _mm256_mul_ps(reals1, reals2);
        __m256 bd = _mm256_mul_ps(imags1, imags2);
        __m256 ad = _mm256_mul_ps(reals1, imags2);
        __m256 bc = _mm256_mul_ps(imags1, reals2);

        __m256 result_real = _mm256_add_ps(ac, bd);
        __m256 result_imag = _mm256_sub_ps(ad, bc);

        // Interleave real and imaginary parts back into [r1, i1, r2, i2, ...]
        __m256 result = _mm256_unpacklo_ps(result_real, result_imag);
        __m256 result_high = _mm256_unpackhi_ps(result_real, result_imag);
        __m256 final_result = _mm256_permute2f128_ps(result, result_high, 0x20);

        _mm256_storeu_ps(reinterpret_cast<float*>(out + idx), final_result);
    }
}

