// Determine if a number is prime using optimized checking
bool checkPrime(int value) {
    // Handle edge cases: numbers less than 2 are not prime
    if (value < 2) return false;

    // Special handling for small primes
    if (value == 2 || value == 3) return true;

    // Eliminate multiples of 2 and 3 early
    if (value % 2 == 0 || value % 3 == 0) return false;

    // Check divisors of the form 6k ± 1 up to sqrt(value)
    int limit = static_cast<int>(std::sqrt(value));
    for (int divisor = 5; divisor <= limit; divisor += 6) {
        if (value % divisor == 0 || value % (divisor + 2) == 0)
            return false;
    }

    return true;
}

// Find the smallest prime strictly greater than the given number
int findNextPrime(int current) {
    int candidate = current + 1;

    while (!checkPrime(candidate)) {
        candidate++;
    }

    return candidate;
}

int main() {
    int userNumber;

    std::cout << "Enter a number: ";
    std::cin >> userNumber;

    int result = findNextPrime(userNumber);
    std::cout << "The next prime number after " << userNumber << " is " << result << std::endl;

    return 0;
}

