// Function to find the longest palindromic substring
std::string findLongestPalindrome(std::string str) {
    if (str.empty()) return "";

    int length = str.length();
    int beginIndex = 0;
    int maxLength = 1;

    // Lambda function to expand around a center and return palindrome length
    auto checkPalindrome = [&](int left, int right) {
        while (left >= 0 && right < length && str[left] == str[right]) {
            left--;
            right++;
        }
        return right - left - 1;
    };

    for (int index = 0; index < length; ++index) {
        int oddLength = checkPalindrome(index, index);         // Center at one character
        int evenLength = checkPalindrome(index, index + 1);   // Center between two characters
        int currentMax = (oddLength > evenLength) ? oddLength : evenLength;

        if (currentMax > maxLength) {
            maxLength = currentMax;
            beginIndex = index - (currentMax - 1) / 2;
        }
    }

    return str.substr(beginIndex, maxLength);
}

int main() {
    std::string text = "abaxyzzyxf";
    std::string palindrome = findLongestPalindrome(text);
    std::cout << "The longest palindromic substring is: " << palindrome << std::endl;
    return 0;
}

