// Enumerate and display network computers using Windows Shell API
void DisplayNetworkResources()
{
    HRESULT hr = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
    if (FAILED(hr)) return;

    IShellItem* pFolderItem = nullptr;
    hr = SHGetKnownFolderItem(FOLDERID_NetworkFolder, KF_FLAG_DEFAULT, nullptr, IID_IShellItem, reinterpret_cast<void**>(&pFolderItem));

    if (SUCCEEDED(hr) && pFolderItem)
    {
        IEnumShellItems* pItemEnumerator = nullptr;
        hr = pFolderItem->BindToHandler(nullptr, BHID_EnumItems, IID_IEnumShellItems, reinterpret_cast<void**>(&pItemEnumerator));

        if (SUCCEEDED(hr) && pItemEnumerator)
        {
            IShellItem* pCurrentItem = nullptr;
            while (pItemEnumerator->Next(1, &pCurrentItem, nullptr) == S_OK)
            {
                LPWSTR displayName = nullptr;
                if (SUCCEEDED(pCurrentItem->GetDisplayName(SIGDN_NORMALDISPLAY, &displayName)) && displayName)
                {
                    std::wcout << L"Machine: " << displayName << std::endl;
                    CoTaskMemFree(displayName);
                }
                pCurrentItem->Release();
            }
            pItemEnumerator->Release();
        }
        pFolderItem->Release();
    }

    CoUninitialize();
}

int main()
{
    DisplayNetworkResources();
    return 0;
}

