namespace types {
    struct uint128_t {
        std::uint64_t low;
        std::uint64_t high;
    };
}

template<>
inline bool compare_and_swap(volatile types::uint128_t *target, types::uint128_t expected, types::uint128_t desired)
{
    std::uint64_t exp_low = expected.low;
    std::uint64_t exp_high = expected.high;
    std::uint64_t new_low = desired.low;
    std::uint64_t new_high = desired.high;
    unsigned char success_flag = 0;

    __asm__ __volatile__ (
        "lock; cmpxchg16b %2\n\t"
        "setz %0\n\t"
        : "=q"(success_flag), "+m"(*target)
        : "a"(exp_low), "d"(exp_high), "b"(new_low), "c"(new_high)
        : "memory", "cc"
    );

    return static_cast<bool>(success_flag);
}

