#include <cryptopp/hex.h>
#include <cryptopp/files.h>

// Verify an ECDSA signature using SHA-256 and P-192 curve
bool CheckECDSASignature(const CryptoPP::ECDSA<CryptoPP::ECP, CryptoPP::SHA256>::PublicKey& publicKey,
                         const std::string& originalMessage,
                         const std::string& encodedSignature) {
    // Split the signature into two equal parts: r and s components
    size_t halfLength = encodedSignature.length() / 2;
    std::string rComponentHex = encodedSignature.substr(0, halfLength);
    std::string sComponentHex = encodedSignature.substr(halfLength);

    // Decode hexadecimal representation to binary for r and s
    std::string rBinary, sBinary;
    CryptoPP::HexDecoder rDecoder(new CryptoPP::StringSink(rBinary));
    rDecoder.Put(reinterpret_cast<const CryptoPP::byte*>(rComponentHex.data()), rComponentHex.size());
    rDecoder.MessageEnd();

    CryptoPP::HexDecoder sDecoder(new CryptoPP::StringSink(sBinary));
    sDecoder.Put(reinterpret_cast<const CryptoPP::byte*>(sComponentHex.data()), sComponentHex.size());
    sDecoder.MessageEnd();

    // Create verifier object with provided public key
    CryptoPP::ECDSA<CryptoPP::ECP, CryptoPP::SHA256>::Verifier verifier(publicKey);

    // Perform signature verification
    bool isValid = verifier.VerifyMessage(
        reinterpret_cast<const CryptoPP::byte*>(originalMessage.data()),
        originalMessage.size(),
        reinterpret_cast<const CryptoPP::byte*>(rBinary.data()),
        rBinary.size(),
        reinterpret_cast<const CryptoPP::byte*>(sBinary.data()),
        sBinary.size()
    );

    return isValid;
}

