using Eigen::MatrixXd;

extern "C" {
    PHP_FUNCTION(matrix_multiply) {
        double *matrixA_data, *matrixB_data;
        int rowsA, colsA, rowsB, colsB;

        if (zend_parse_parameters(ZEND_NUM_ARGS(), "ddiiii", &matrixA_data, &matrixB_data, &rowsA, &colsA, &rowsB, &colsB) == FAILURE) {
            RETURN_NULL();
        }

        // Construct matrices from raw data
        MatrixXd A(rowsA, colsA);
        MatrixXd B(rowsB, colsB);

        for (int r = 0; r < rowsA; ++r) {
            for (int c = 0; c < colsA; ++c) {
                A(r, c) = matrixA_data[r * colsA + c];
            }
        }

        for (int r = 0; r < rowsB; ++r) {
            for (int c = 0; c < colsB; ++c) {
                B(r, c) = matrixB_data[r * colsB + c];
            }
        }

        // Perform matrix multiplication
        MatrixXd product = A * B;

        // Allocate memory for result array
        size_t total_elements = product.rows() * product.cols();
        double *output_data = static_cast<double*>(emalloc(total_elements * sizeof(double)));

        for (size_t idx = 0; idx < total_elements; ++idx) {
            int row = idx / product.cols();
            int col = idx % product.cols();
            output_data[idx] = product(row, col);
        }

        // Return as PHP array of doubles
        array_init(return_value);
        for (size_t i = 0; i < total_elements; ++i) {
            add_next_index_double(return_value, output_data[i]);
        }
        efree(output_data);
    }
}

