// Renders a stylized tree at specified position with given dimensions
void renderTree(float posX, float posY, float trunkHeight, float foliageSize) {
    // Render the trunk using quadrilaterals
    glBegin(GL_QUADS);
    glColor3f(0.5f, 0.25f, 0.0f);  // Brown color for trunk
    glVertex3f(posX - 0.4f, posY, 0.0f);
    glVertex3f(posX + 0.4f, posY, 0.0f);
    glVertex3f(posX + 0.4f, posY + trunkHeight, 0.0f);
    glVertex3f(posX - 0.4f, posY + trunkHeight, 0.0f);
    glEnd();

    // Generate random foliage points around the top of the trunk
    static std::random_device rd;
    static std::mt19937 engine(rd());
    static std::uniform_real_distribution<> distribution(-1.0, 1.0);

    for (int leafIndex = 0; leafIndex < 80; ++leafIndex) {
        float theta = distribution(engine) * 3.14159265f * 2.0f;
        float radialDist = distribution(engine) * foliageSize;

        float leafX = posX + radialDist * std::cos(theta) * 1.5f;
        float leafY = posY + trunkHeight + radialDist * std::sin(theta) * 1.5f;

        glBegin(GL_TRIANGLES);
        glColor3f(0.0f, 1.0f, 0.0f);  // Green color for leaves
        glVertex3f(leafX, leafY, 0.0f);
        glVertex3f(leafX + 0.08f, leafY + 0.08f, 0.0f);
        glVertex3f(leafX - 0.08f, leafY + 0.08f, 0.0f);
        glEnd();
    }
}

