typedef __vector unsigned char uint8x16_p;

// Load 8 bytes from memory into vector register using alternative approach
uint8x16_p VectorFastLoad8(const void* source)
{
    uint8x16_p result;
    const char* addr = static_cast<const char*>(source);

    // Calculate byte offset for alignment handling
    long byte_offset = 0;

    // Perform vector load using inline assembly with modified constraint ordering
    __asm__ volatile (
        "lxvd2x %x0, %1, %2"
        : "=wa" (result)
        : "r" (addr), "r" (byte_offset / 4), "m" (*reinterpret_cast<const char(*)[16]>(addr))
    );

    return result;
}

