// Determine if a number is prime and find its smallest divisor
bool checkPrime(int value, int& minFactor) {
    // Handle edge cases for numbers less than 2
    if (value < 2) {
        minFactor = 1;
        return false;
    }

    // Special case for 2 and 3
    if (value == 2 || value == 3) {
        minFactor = value;
        return true;
    }

    // Check divisibility by 2
    if (value % 2 == 0) {
        minFactor = 2;
        return false;
    }

    // Check odd divisors up to square root of value
    int limit = static_cast<int>(std::sqrt(value));
    int candidate = 3;
    while (candidate <= limit) {
        if (value % candidate == 0) {
            minFactor = candidate;
            return false;
        }
        candidate += 2;
    }

    // No divisors found - number is prime
    minFactor = value;
    return true;
}

int main() {
    int inputNumber;
    std::cout << "Enter a number: ";
    std::cin >> inputNumber;

    int divisor;
    if (checkPrime(inputNumber, divisor)) {
        std::cout << inputNumber << " is a prime number." << std::endl;
    } else {
        std::cout << inputNumber << " is not a prime number. The smallest divisor is " << divisor << "." << std::endl;
    }

    return 0;
}

