using namespace std;

// Find the longest substring with distinct characters and count unique chars
pair<int, int> findLongestDistinctSubstring(const string& input) {
    if (input.empty()) return {0, 0};

    unordered_map<char, int> positionMap;
    int bestLength = 0;
    int bestUniqueCount = 0;
    int windowStart = 0;

    for (int windowEnd = 0; windowEnd < input.length(); ++windowEnd) {
        char currentChar = input[windowEnd];

        // If character exists in map and is within current window
        if (positionMap.count(currentChar) > 0 && positionMap[currentChar] >= windowStart) {
            windowStart = positionMap[currentChar] + 1;
        }

        positionMap[currentChar] = windowEnd;

        int currentWindowLength = windowEnd - windowStart + 1;
        int currentDistinctChars = positionMap.size();

        if (currentWindowLength > bestLength) {
            bestLength = currentWindowLength;
            bestUniqueCount = currentDistinctChars;
        }
    }

    return {bestLength, bestUniqueCount};
}

int main() {
    string testString = "pwwkew";
    pair<int, int> outcome = findLongestDistinctSubstring(testString);

    cout << "The length of the longest substring without repeating characters is " << outcome.first << '\n';
    cout << "The number of unique characters in that substring is " << outcome.second << '\n';

    return 0;
}

#include <Python.h>
#include <numpy/arrayobject.h>

// Wrapper function to interface with the FMM algorithm
static PyObject* FMM(PyObject* self, PyObject* args)
{
    PyObject *model_obj;
    PyObject *time_obj;
    PyObject *accepted_obj;
    PyObject *lat_obj;
    PyObject *lon_obj;
    PyObject *h_obj;
    int count;

    // Parse input arguments: six numpy arrays and an integer count
    if (!PyArg_ParseTuple(args, "OOOOOOi", &model_obj, &time_obj, &accepted_obj, &lat_obj, &lon_obj, &h_obj, &count))
    {
        return NULL;  // Return NULL on parsing failure
    }

    // Initialize the NumPy C API if not already done
    import_array();

    // Convert Python objects to NumPy arrays with appropriate types and memory layout
    PyArrayObject *model = (PyArrayObject *)PyArray_FROM_OTF(model_obj, NPY_FLOAT, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *time  = (PyArrayObject *)PyArray_FROM_OTF(time_obj,  NPY_FLOAT, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *accepted = (PyArrayObject *)PyArray_FROM_OTF(accepted_obj, NPY_BOOL, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *lat   = (PyArrayObject *)PyArray_FROM_OTF(lat_obj,   NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *lon   = (PyArrayObject *)PyArray_FROM_OTF(lon_obj,   NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *h     = (PyArrayObject *)PyArray_FROM_OTF(h_obj,     NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);

    // Validate that all arrays were successfully created
    if (!model || !time || !accepted || !lat || !lon || !h) {
        Py_XDECREF(model); Py_XDECREF(time); Py_XDECREF(accepted);
        Py_XDECREF(lat); Py_XDECREF(lon); Py_XDECREF(h);
        return NULL;  // Return NULL on conversion error
    }

    // Extract raw data pointers from the arrays
    float   *MODEL_DATA = static_cast<float*>(PyArray_DATA(model));
    float   *TIME_DATA  = static_cast<float*>(PyArray_DATA(time));
    bool    *ACCEPTED_DATA = static_cast<bool*>(PyArray_DATA(accepted));
    double  *LAT_DATA   = static_cast<double*>(PyArray_DATA(lat));
    double  *LON_DATA   = static_cast<double*>(PyArray_DATA(lon));
    double  *H_DATA     = static_cast<double*>(PyArray_DATA(h));

    // Invoke the core FMM computation routine
    _FMM(MODEL_DATA, TIME_DATA, ACCEPTED_DATA, LAT_DATA, LON_DATA, H_DATA, count);

    // Clean up reference counts for the temporary array objects
    Py_DECREF(model);
    Py_DECREF(time);
    Py_DECREF(accepted);
    Py_DECREF(lat);
    Py_DECREF(lon);
    Py_DECREF(h);

    Py_RETURN_NONE;  // Indicate successful execution
}

