// Find maximum subarray sum and its indices using modified Kadane's algorithm
int main() {
    vector<int> arr = {-2, -3, 4, -1, -2, 1, 5, -3};

    int maxSum = INT_MIN;
    int currentSum = 0;
    int leftIndex = 0;
    int bestLeft = 0;
    int bestRight = 0;
    bool hasPositive = false;
    int largestNegative = INT_MIN;

    for (int right = 0; right < arr.size(); ++right) {
        currentSum += arr[right];

        // Track the largest negative number in case all elements are negative
        if (!hasPositive && arr[right] > largestNegative) {
            largestNegative = arr[right];
        }

        // Update global maximum and indices when we find a better sum
        if (currentSum > maxSum) {
            maxSum = currentSum;
            bestLeft = leftIndex;
            bestRight = right;
            hasPositive = true;
        }

        // Reset current sum and left pointer when sum becomes negative
        if (currentSum < 0) {
            currentSum = 0;
            leftIndex = right + 1;
        }
    }

    if (!hasPositive) {
        cout << "All numbers are negative, the maximum element is: " << largestNegative << endl;
        return 0;
    }

    cout << "The maximum subarray sum is: " << maxSum << endl;
    cout << "The starting index of the subarray is: " << bestLeft << endl;
    cout << "The ending index of the subarray is: " << bestRight << endl;

    return 0;
}

