// Computes the sum of integers from 0 to n-1 using a while loop instead of for-loop
unsigned long long computeSum(unsigned long long limit)
{
    unsigned long long total = 0;
    unsigned long long counter = 0;

    while (counter < limit)
    {
        total += counter;
        counter++;
    }

    return total;
}

int main()
{
    LARGE_INTEGER frequency, startTime, endTime;

    QueryPerformanceFrequency(&frequency);
    QueryPerformanceCounter(&startTime);

    // Call the modified function with the same argument
    computeSum(1000000000ULL);

    QueryPerformanceCounter(&endTime);

    double elapsedMs = static_cast<double>(endTime.QuadPart - startTime.QuadPart) / frequency.QuadPart * 1000.0;

    printf("Delta: %f\n", elapsedMs);

    return 0;
}

