int main() {
    int n, m;
    cin >> n >> m;

    // Handle negative numbers by converting to positive
    if (n < 0) {
        n = -n;  // Equivalent to abs(n)
    }

    // Find the nearest multiple of m that is greater than or equal to the original n
    // For positive n: round down to nearest multiple of m
    // For negative n (now positive): round up to nearest multiple of m
    int remainder = n % m;
    if (remainder == 0) {
        cout << n << endl;
    } else {
        if (n >= 0) {
            cout << n - remainder << endl;
        } else {
            cout << n + (m - remainder) << endl;
        }
    }

    return 0;
}

