// Constants for computation limits
const unsigned int MAX_ITERATIONS = 40000;
const unsigned int DATA_SIZE = 10000;

int main() {
    // Initialize data arrays with zeros
    vector<double> inputSignal(DATA_SIZE, 0.0);
    vector<double> outputSignal(DATA_SIZE, 0.0);
    vector<double> cosCoeffs(MAX_ITERATIONS, 0.0);
    vector<double> sinCoeffs(MAX_ITERATIONS, 0.0);

    // Precompute intermediate trigonometric differences
    vector<double> cosDiff(DATA_SIZE - 1);
    vector<double> sinDiff(DATA_SIZE - 1);

    // Start timing the computation
    auto startTime = high_resolution_clock::now();

    // Outer loop over harmonic indices
    for (unsigned int harmonic = 1; harmonic <= MAX_ITERATIONS; ++harmonic) {
        // Compute cosine and sine differences for current harmonic
        for (unsigned int idx = 1; idx < DATA_SIZE; ++idx) {
            double anglePrev = harmonic * inputSignal[idx - 1];
            double angleCurr = harmonic * inputSignal[idx];

            cosDiff[idx - 1] = cos(anglePrev) - cos(angleCurr);
            sinDiff[idx - 1] = sin(anglePrev) - sin(angleCurr);
        }

        // Accumulate weighted differences into coefficient arrays
        for (unsigned int idx = 1; idx < DATA_SIZE; ++idx) {
            cosCoeffs[harmonic - 1] += outputSignal[idx - 1] * cosDiff[idx - 1];
            sinCoeffs[harmonic - 1] += outputSignal[idx - 1] * sinDiff[idx - 1];
        }
    }

    // Stop timing and compute duration
    auto endTime = high_resolution_clock::now();
    auto elapsed = duration_cast<milliseconds>(endTime - startTime);

    cout << "Time: " << elapsed.count() << " milliseconds" << endl;

    return 0;
}

