// Function to print Fibonacci sequence up to n terms
void displayFibonacci(int count) {
    long long prev = 0, curr = 1, temp;

    if (count <= 0) {
        std::cout << "Please enter a positive integer." << std::endl;
        return;
    }

    std::cout << "Fibonacci Series up to " << count << " numbers:" << std::endl;

    int termIndex = 1;
    while (termIndex <= count) {
        if (termIndex == 1) {
            std::cout << prev;
            if (count > 1) std::cout << ", ";
            termIndex++;
            continue;
        }
        if (termIndex == 2) {
            std::cout << curr;
            if (count > 2) std::cout << ", ";
            termIndex++;
            continue;
        }

        temp = prev + curr;
        prev = curr;
        curr = temp;

        std::cout << curr;
        if (termIndex < count) std::cout << ", ";

        termIndex++;
    }
    std::cout << std::endl;
}

int main() {
    int terms;
    std::cout << "Enter the number of terms: ";
    std::cin >> terms;
    displayFibonacci(terms);
    return 0;
}

