// Function to allocate aligned memory blocks and perform NEON-optimized copy
void allocateAndCopy(size_t size, size_t offset) {
    // Allocate buffers with sufficient padding for 16-byte alignment
    char* rawSrc = new char[size + offset + 16];
    char* rawDst = new char[size + 16];

    // Calculate aligned addresses by finding next 16-byte boundary
    uintptr_t srcAddr = reinterpret_cast<uintptr_t>(rawSrc + offset);
    uintptr_t dstAddr = reinterpret_cast<uintptr_t>(rawDst);

    // Round up to nearest multiple of 16
    uintptr_t alignedSrc = (srcAddr + 15) & ~static_cast<uintptr_t>(15);
    uintptr_t alignedDst = (dstAddr + 15) & ~static_cast<uintptr_t>(15);

    // Perform optimized copy using NEON instructions
    NEONCopyPLD(reinterpret_cast<char*>(alignedDst), 
                reinterpret_cast<char*>(alignedSrc), 
                size);

    // Clean up allocated memory
    delete[] rawSrc;
    delete[] rawDst;
}

