// 128-bit unsigned integer implementation using two 64-bit parts
class uint128_t {
private:
    unsigned long long upper;
    unsigned long long lower;

public:
    // Constructors
    uint128_t() : upper(0), lower(0) {}
    uint128_t(unsigned long long value) : upper(0), lower(value) {}
    uint128_t(unsigned long long highPart, unsigned long long lowPart) 
        : upper(highPart), low(lowPart) {}

    // Addition operator
    uint128_t operator+(const uint128_t& rhs) const {
        unsigned long long sumLower = lower + rhs.lower;
        unsigned long long carry = (sumLower < lower) ? 1ULL : 0ULL;
        unsigned long long sumUpper = upper + rhs.upper + carry;
        return uint128_t(sumUpper, sumLower);
    }

    // Subtraction operator
    uint128_t operator-(const uint128_t& rhs) const {
        unsigned long long diffLower = lower - rhs.lower;
        unsigned long long borrow = (diffLower > lower) ? 1ULL : 0ULL;
        unsigned long long diffUpper = upper - rhs.upper - borrow;
        return uint128_t(diffUpper, diffLower);
    }

    // Multiplication operator
    uint128_t operator*(const uint128_t& rhs) const {
        unsigned long long a = upper, b = lower;
        unsigned long long c = rhs.upper, d = rhs.lower;

        unsigned long long ac = a * c;
        unsigned long long bd = b * d;
        unsigned long long ad = a * d;
        unsigned long long bc = b * c;

        unsigned long long midSum = ad + bc;
        unsigned long long midHigh = (midSum < ad) ? 1ULL : 0ULL; // overflow check
        midHigh += midSum >> 64;
        unsigned long long midLow = midSum & 0xFFFFFFFFFFFFFFFFULL;

        unsigned long long resultLow = bd + midLow;
        unsigned long long finalCarry = (resultLow < bd) ? 1ULL : 0ULL;
        unsigned long long resultHigh = ac + midHigh + finalCarry;

        return uint128_t(resultHigh, resultLow);
    }

    // Division operator (simplified implementation)
    uint128_t operator/(const uint128_t& divisor) const {
        if (divisor.upper == 0 && divisor.lower == 0) {
            return uint128_t(); // Return zero for division by zero
        }

        uint128_t dividend = *this;
        uint128_t quotient(0);

        for (int i = 0; i < 128; ++i) {
            quotient = quotient + quotient;

            if ((dividend.upper >> 63) & 1) {
                quotient.lower |= 1;
            }

            dividend = dividend << 1;

            if (dividend >= divisor) {
                dividend = dividend - divisor;
                quotient.lower |= 1;
            }
        }

        return quotient;
    }

    // Equality comparison
    bool operator==(const uint128_t& other) const {
        return upper == other.upper && lower == other.lower;
    }

    // Inequality comparison
    bool operator!=(const uint128_t& other) const {
        return !(*this == other);
    }

    // Less than comparison
    bool operator<(const uint128_t& other) const {
        if (upper != other.upper) {
            return upper < other.upper;
        }
        return lower < other.lower;
    }

    // Greater than comparison
    bool operator>(const uint128_t& other) const {
        return other < *this;
    }

    // Less than or equal comparison
    bool operator<=(const uint128_t& other) const {
        return !(*this > other);
    }

    // Greater than or equal comparison
    bool operator>=(const uint128_t& other) const {
        return !(*this < other);
    }

    // Left shift operator
    uint128_t operator<<(int shift) const {
        if (shift == 0) {
            return *this;
        }
        if (shift >= 64) {
            return uint128_t(lower << (shift - 64), 0);
        }
        unsigned long long newUpper = (upper << shift) | (lower >> (64 - shift));
        unsigned long long newLower = lower << shift;
        return uint128_t(newUpper, newLower);
    }

    // Conversion to string representation
    std::string toString() const {
        std::stringstream stream;
        stream << "0x" << std::hex << upper << std::hex << lower;
        return stream.str();
    }
};

#include <cstdint>

// Computes the floor of the base-2 logarithm of a positive integer
static inline int log2_floor(int value) {
#if defined(__x86_64__) || defined(__i386__)
    // Use bit scan reverse instruction for x86/x86_64
    if (value <= 0) return -1;
    int result;
    asm volatile ("bsr %1, %0" : "=r"(result) : "r"(value));
    return result;
#elif defined(__arm__) || defined(__aarch64__)
    // Use count leading zeros for ARM/AArch64 architectures
    if (value <= 0) return -1;
    unsigned int clz_result;
    asm volatile ("clz %0, %1" : "=r"(clz_result) : "r"(value));
    return 31 - static_cast<int>(clz_result);
#else
    // Generic C++ implementation using bit shifting
    if (value <= 0) return -1;
    int exponent = 0;
    while ((value >>= 1) > 0) {
        ++exponent;
    }
    return exponent;
#endif
}

