// Function to process bitmap pixel data for resizing operations
int Resize::ResizeImage(HBITMAP hBitmap) {
    // Obtain the desktop device context for compatibility checks
    HDC screenDC = GetDC(NULL);

    // Create a memory device context compatible with the screen
    HDC workingDC = CreateCompatibleDC(screenDC);

    // Store the original bitmap selection and replace with our target bitmap
    HBITMAP previousBitmap = (HBITMAP)SelectObject(workingDC, hBitmap);

    // Retrieve bitmap properties
    BITMAP bitmapDetails;
    GetObject(hBitmap, sizeof(BITMAP), &bitmapDetails);

    // Attempt direct access to bitmap bits
    void* rawBits = bitmapDetails.bmBits;

    // If direct access fails, fall back to DIB conversion method
    if (rawBits == nullptr) {
        BITMAPINFO infoHeader;
        ZeroMemory(&infoHeader, sizeof(BITMAPINFO));
        infoHeader.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
        infoHeader.bmiHeader.biWidth = bitmapDetails.bmWidth;
        infoHeader.bmiHeader.biHeight = bitmapDetails.bmHeight;
        infoHeader.bmiHeader.biPlanes = 1;
        infoHeader.bmiHeader.biBitCount = bitmapDetails.bmBitsPixel;
        infoHeader.bmiHeader.biCompression = BI_RGB;

        size_t bufferSize = static_cast<size_t>(bitmapDetails.bmWidth) * 
                           bitmapDetails.bmHeight * 
                           (bitmapDetails.bmBitsPixel / 8);

        unsigned char* tempBuffer = new unsigned char[bufferSize];
        GetDIBits(workingDC, hBitmap, 0, bitmapDetails.bmHeight, tempBuffer, &infoHeader, DIB_RGB_COLORS);
        rawBits = tempBuffer;
    }

    // Process the bitmap data as needed (placeholder for actual resizing logic)
    // Example: Access first pixel's RGB components
    // printf("First pixel: %02X %02X %02X\n", 
    //        ((unsigned char*)rawBits)[0], 
    //        ((unsigned char*)rawBits)[1], 
    //        ((unsigned char*)rawBits)[2]);

    // Cleanup allocated resources properly
    SelectObject(workingDC, previousBitmap);
    DeleteDC(workingDC);
    ReleaseDC(NULL, screenDC);

    return 0;
}

