// Cross-platform timestamp counter reader using rdtsc instruction
#if defined(_MSC_VER)
    // Microsoft Visual C++ compiler
    #include <intrin.h>
    inline unsigned long long get_timestamp() {
        return static_cast<unsigned long long>(_rdtsc());
    }
#elif defined(__GNUC__) || defined(__clang__)
    // GCC or Clang compilers
    inline unsigned long long get_timestamp() {
        uint64_t low, high;
        __asm__ volatile ("rdtsc" : "=a" (low), "=d" (high));
        return (high << 32) | low;
    }
#else
    #error "Unsupported compiler for timestamp reading"
#endif

// Wrapper function to retrieve current cycle count
unsigned long long get_cc_time() {
    return get_timestamp();
}

