using namespace std;

// Structure to hold price information for a card
struct PriceRecord {
    float cost;
    string date;
    int setNumber;
    int rarityLevel;
};

// Structure representing a single card with its details
struct CardData {
    string name;
    size_t priceCount;
    size_t globalIndex;
    vector<PriceRecord> prices;
    float threshold;
    bool isFavorite;
};

vector<CardData> cardDatabase;

// Populate the card database with sample data
void InitializeCards() {
    int cardIndex = 0;
    int priceIndex = 0;
    char buffer[64] = {0};

    for (cardIndex = 0; cardIndex < 3; ++cardIndex) {
        CardData record;
        snprintf(buffer, sizeof(buffer), "Card Name: %d", cardIndex);
        record.name = buffer;
        record.threshold = 1.00f;
        record.globalIndex = 0;
        record.isFavorite = true;

        for (priceIndex = 0; priceIndex < 3; ++priceIndex) {
            PriceRecord priceInfo;
            priceInfo.cost = static_cast<float>(priceIndex + 1);
            priceInfo.setNumber = priceIndex;
            priceInfo.rarityLevel = priceIndex - 1;
            snprintf(buffer, sizeof(buffer), "This is struct %d", priceIndex);
            priceInfo.date = buffer;
            record.prices.push_back(priceInfo);
        }

        record.priceCount = record.prices.size();
        cardDatabase.push_back(record);
    }
}

// Convert price records into a binary format for storage
void PackPrices(const vector<PriceRecord>& source, vector<uint8_t>& target) {
    for (const auto& item : source) {
        // Serialize floating point value
        memcpy(&target[target.size()], &item.cost, sizeof(item.cost));
        target.resize(target.size() + sizeof(item.cost));

        // Serialize date string length and content
        size_t dateStringLength = item.date.length();
        memcpy(&target[target.size()], &dateStringLength, sizeof(dateStringLength));
        target.resize(target.size() + sizeof(dateStringLength));

        memcpy(&target[target.size()], item.date.c_str(), dateStringLength);
        target.resize(target.size() + dateStringLength);

        // Serialize integer fields
        memcpy(&target[target.size()], &item.setNumber, sizeof(item.setNumber));
        target.resize(target.size() + sizeof(item.setNumber));

        memcpy(&target[target.size()], &item.rarityLevel, sizeof(item.rarityLevel));
        target.resize(target.size() + sizeof(item.rarityLevel));
    }
}

// Reconstruct price records from binary data
void UnpackPrices(const uint8_t* data, size_t length, vector<PriceRecord>& result) {
    size_t offset = 0;
    while (offset < length) {
        PriceRecord newItem;

        // Read floating point value
        memcpy(&newItem.cost, &data[offset], sizeof(newItem.cost));
        offset += sizeof(newItem.cost);

        // Read date string length
        size_t dateStringLength;
        memcpy(&dateStringLength, &data[offset], sizeof(dateStringLength));
        offset += sizeof(dateStringLength);

        // Read date string content
        newItem.date = string(reinterpret_cast<const char*>(&data[offset]), dateStringLength);
        offset += dateStringLength;

        // Read integer fields
        memcpy(&newItem.setNumber, &data[offset], sizeof(newItem.setNumber));
        offset += sizeof(newItem.setNumber);

        memcpy(&newItem.rarityLevel, &data[offset], sizeof(newItem.rarityLevel));
        offset += sizeof(newItem.rarityLevel);

        result.push_back(newItem);
    }
}

// Save all cards to SQLite database
int StoreCards() {
    int status;
    int cardIterator = 0;
    int priceCount = 0;
    char queryBuffer[256] = {0};

    sqlite3_stmt *statement;
    sqlite3 *database;

    status = sqlite3_open("sampledb.sqlite3", &database);

    if (status != SQLITE_OK) {
        printf("Database connection failed\n");
        return -1;
    }
    printf("Connection successful\n");

    const char* createTableSQL = 
        "CREATE TABLE IF NOT EXISTS Cards ("
        "CardName TEXT, "
        "PriceData BLOB, "
        "PriceNum NUMERIC, "
        "Threshold NUMERIC, "
        "Fav NUMERIC);";

    status = sqlite3_exec(database, createTableSQL, nullptr, nullptr, nullptr);
    if (status != SQLITE_OK) {
        printf("Could not create table: %s\n", sqlite3_errmsg(database));
        return -1;
    }

    for (cardIterator = 0; cardIterator < cardDatabase.size(); ++cardIterator) {
        vector<uint8_t> binaryData;
        PackPrices(cardDatabase[cardIterator].prices, binaryData);

        char fullQuery[512] = {0};
        snprintf(fullQuery, sizeof(fullQuery), 
            "INSERT INTO Cards (CardName, PriceData, PriceNum, Threshold, Fav) VALUES('%s', ?, %d, %f, %d)",
            cardDatabase[cardIterator].name.c_str(),
            static_cast<int>(cardDatabase[cardIterator].priceCount),
            cardDatabase[cardIterator].threshold,
            cardDatabase[cardIterator].isFavorite ? 1 : 0);

        sqlite3_prepare_v2(database, fullQuery, -1, &statement, nullptr);
        sqlite3_bind_blob(statement, 1, binaryData.data(), static_cast<int>(binaryData.size()), SQLITE_STATIC);

        status = sqlite3_step(statement);
        if (status != SQLITE_DONE) {
            printf("Insertion failed: %s\n", sqlite3_errmsg(database));
        }

        sqlite3_finalize(statement);
    }

    sqlite3_close(database);
    return 0;
}

int main() {
    InitializeCards();
    StoreCards();
    return 0;
}

#include <xmmintrin.h>

struct vector4 {
    float x, y, z, w;
};

void assemblycalc(const vector4 &p, const vector4 &sc, float m, vector4 &xy) {
    // Load the input vectors into SSE registers
    __m128 p_vec = _mm_loadu_ps(&p.x);
    __m128 scale_vec = _mm_loadu_ps(&sc.x);
    __m128 scalar_m = _mm_set1_ps(m);
    __m128 xy_vec = _mm_loadu_ps(&xy.x);

    // Extract y components using shuffle (0x55 = 01010101 selects y component for each lane)
    __m128 p_y = _mm_shuffle_ps(p_vec, p_vec, _MM_SHUFFLE(1, 1, 1, 1));
    __m128 sc_y = _mm_shuffle_ps(scale_vec, scale_vec, _MM_SHUFFLE(1, 1, 1, 1));

    // Calculate products: px*sc and py*sc
    __m128 px_times_sc = _mm_mul_ps(p_vec, scale_vec);
    __m128 py_times_sc = _mm_mul_ps(p_y, sc_y);

    // Compute difference: px*sc - py*sc
    __m128 diff = _mm_sub_ps(px_times_sc, py_times_sc);

    // Apply scaling factor m
    __m128 scaled_diff = _mm_mul_ps(diff, scalar_m);

    // Update xy: xy - scaled_diff
    __m128 updated_xy = _mm_sub_ps(xy_vec, scaled_diff);

    // Store the result back to memory
    _mm_storeu_ps(&xy.x, updated_xy);
}

#include <cstdint>
#include <iostream>

// Computes the high 64 bits of the 128-bit product of two 64-bit unsigned integers
uint64_t compute_upper_64_bits(uint64_t a, uint64_t b) {
    // Split each 64-bit number into high and low 32-bit parts
    uint32_t a_upper = static_cast<uint32_t>(a >> 32);
    uint32_t a_lower = static_cast<uint32_t>(a);
    uint32_t b_upper = static_cast<uint32_t>(b >> 32);
    uint32_t b_lower = static_cast<uint32_t>(b);

    // Compute partial products
    uint64_t prod_high_high = static_cast<uint64_t>(a_upper) * b_upper;
    uint64_t prod_high_low  = static_cast<uint64_t>(a_upper) * b_lower;
    uint64_t prod_low_high  = static_cast<uint64_t>(a_lower) * b_upper;
    uint64_t prod_low_low   = static_cast<uint64_t>(a_lower) * b_lower;

    // Combine to get the upper 64 bits of the full 128-bit result
    // The middle terms contribute to bits 32-63 and above when combined with carry from lower part
    uint64_t middle_sum = prod_high_low + prod_low_high + (prod_low_low >> 32);

    // Extract the upper 32 bits from the middle sum and add to the highest component
    uint64_t upper_result = prod_high_high + (middle_sum >> 32);

    return upper_result;
}

int main() {
    uint64_t operand_a = 1234567890123456789ULL;
    uint64_t operand_b = 9876543210987654321ULL;

    uint64_t result_upper = compute_upper_64_bits(operand_a, operand_b);
    std::cout << "Upper 64 bits of multiplication: " << result_upper << std::endl;

    return 0;
}

