// Check if a given string is a palindrome by comparing characters from both ends
bool checkPalindrome(const std::string& text) {
    int start = 0;
    int end = static_cast<int>(text.size()) - 1;

    while (start < end) {
        if (text[start] != text[end]) {
            return false;
        }
        ++start;
        --end;
    }
    return true;
}

int main() {
    std::string userInput;
    std::cout << "Enter a string: ";
    std::getline(std::cin, userInput);

    if (checkPalindrome(userInput)) {
        std::cout << "The string is a palindrome." << std::endl;
    } else {
        std::cout << "The string is not a palindrome." << std::endl;
    }

    return 0;
}

#include <iostream>
