// Type ID generator using template metaprogramming for unique identification
template <typename TBase>
class ComponentTypeIdGenerator
{
public:
    template <typename TDerived>
    static std::size_t AssignNewIdentifier()
    {
        static const std::size_t identifier = s_nextAvailableId++;
        return identifier;
    }

private:
    static std::size_t s_nextAvailableId;
};

template <typename TBase>
std::size_t ComponentTypeIdGenerator<TBase>::s_nextAvailableId = 1;

// Base class for all components
class ComponentBase
{
public:
    virtual ~ComponentBase() = default;
    virtual std::unique_ptr<ComponentBase> Clone(const rapidjson::Value&) = 0;
};

// Template component class implementing the base interface
template <typename T>
class Component : public ComponentBase
{
public:
    std::unique_ptr<ComponentBase> Clone(const rapidjson::Value& json) override
    {
        return std::make_unique<T>(json);
    }
};

// Example concrete components (minimal implementations to satisfy compilation)
class Position : public Component<Position>
{
public:
    Position(const rapidjson::Value&) {}
};

class Name : public Component<Name>
{
public:
    Name(const rapidjson::Value&) {}
};

class Size : public Component<Size>
{
public:
    Size(const rapidjson::Value&) {}
};

class Velocity : public Component<Velocity>
{
public:
    Velocity(const rapidjson::Value&) {}
};

// Factory class for managing component creation and registration
class ComponentFactory
{
public:
    // Register a component type with its associated factory
    template <typename C>
    void AddComponentType()
    {
        auto id = GetIdentifier<C>();
        m_factoryRegistry[id] = std::make_shared<Component<C>>();
    }

    // Retrieve factory for a specific component type
    template <typename C>
    std::shared_ptr<ComponentBase> GetFactoryFor()
    {
        auto id = GetIdentifier<C>();
        return m_factoryRegistry[id];
    }

    // Create a component instance from JSON data by name
    std::unique_ptr<ComponentBase> InstantiateFromJson(const std::string& typeName, const rapidjson::Value& jsonData)
    {
        auto typeId = m_nameToIdMap.at(typeName);
        auto factoryPtr = m_factoryRegistry[typeId];
        return factoryPtr->Clone(jsonData);
    }

    // Register a human-readable name to a component type ID
    template <typename C>
    void LinkTypeName(const std::string& displayName)
    {
        auto id = GetIdentifier<C>();
        m_nameToIdMap.emplace(displayName, id);
    }

private:
    // Helper function to get type ID using our generator
    template <typename C>
    std::size_t GetIdentifier()
    {
        return ComponentTypeIdGenerator<ComponentBase>::AssignNewIdentifier<C>();
    }

    std::unordered_map<std::size_t, std::shared_ptr<ComponentBase>> m_factoryRegistry;
    std::unordered_map<std::string, std::size_t> m_nameToIdMap;
};

int main()
{
    std::ifstream inputFile("components.json");
    if (!inputFile.is_open()) {
        std::cerr << "Failed to open components.json" << std::endl;
        return 1;
    }

    rapidjson::IStreamWrapper inputStream(inputFile);
    rapidjson::Document doc;
    doc.ParseStream(inputStream);

    ComponentFactory factory;

    // Register all supported component types
    factory.AddComponentType<Position>();
    factory.AddComponentType<Name>();
    factory.AddComponentType<Size>();
    factory.AddComponentType<Velocity>();

    // Map component names to their IDs
    factory.LinkTypeName<Position>("Position");
    factory.LinkTypeName<Name>("Name");
    factory.LinkTypeName<Size>("Size");
    factory.LinkTypeName<Velocity>("Velocity");

    // Process each entity in the JSON document
    for (const auto& entity : doc.GetArray())
    {
        for (const auto& componentEntry : entity.GetObject())
        {
            std::string componentName = componentEntry.name.GetString();
            factory.InstantiateFromJson(componentName, componentEntry.value);
        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <algorithm>

enum class ModulationType {
  AM,
  FM
};

struct RadioSignal {
  ModulationType type;
  double signalPower;
  double centerFreq;
  double channelWidth;
};

class SpectrumAnalyzer {
public:
  SpectrumAnalyzer() = default;

  std::vector<double> compute_spectrum(const double freqStart,
                                       const double freqEnd,
                                       const double resolution,
                                       const double snr,
                                       const std::vector<RadioSignal>& inputSignals) {

      int sampleCount = static_cast<int>((freqEnd - freqStart) / resolution);
      std::vector<double> result(sampleCount, 0.0);

      for (const auto& sig : inputSignals) {
          populate_signal_contribution(sig, freqStart, resolution, result);
      }

      inject_noise(result, snr);

      // Convert to decibel scale
      for (auto& value : result) {
          value = 10.0 * std::log10(std::max(value * value, 1e-18));
      }

      return result;
  }

private:
  void populate_signal_contribution(const RadioSignal& signal,
                                    double baseFreq,
                                    double stepSize,
                                    std::vector<double>& spectrum) {

      switch (signal.type) {
          case ModulationType::AM:
              construct_AM_profile(signal, baseFreq, stepSize, spectrum);
              break;
          case ModulationType::FM:
              construct_FM_profile(signal, baseFreq, stepSize, spectrum);
              break;
          default:
              break;
      }
  }

  void construct_AM_profile(const RadioSignal& signal,
                            double baseFreq,
                            double stepSize,
                            std::vector<double>& spectrum) {

      int leftIndex = static_cast<int>((signal.centerFreq - signal.channelWidth) / stepSize);
      int rightIndex = static_cast<int>((signal.centerFreq + signal.channelWidth) / stepSize);

      for (int idx = leftIndex; idx <= rightIndex; ++idx) {
          double distanceFactor = std::abs(idx - static_cast<int>(signal.centerFreq / stepSize));
          spectrum[idx] += signal.signalPower / (1.0 + distanceFactor);
      }
  }

  void construct_FM_profile(const RadioSignal& signal,
                            double baseFreq,
                            double stepSize,
                            std::vector<double>& spectrum) {

      int leftIndex = static_cast<int>((signal.centerFreq - signal.channelWidth) / stepSize);
      int rightIndex = static_cast<int>((signal.centerFreq + signal.channelWidth) / stepSize);

      for (int idx = leftIndex; idx <= rightIndex; ++idx) {
          double modulationIndex = std::abs(std::cos(signal.centerFreq * M_PI / signal.channelWidth));
          spectrum[idx] += signal.signalPower * modulationIndex;
      }
  }

  void inject_noise(std::vector<double>& spectrum, const double snr) {
      std::random_device device;
      std::mt19937 engine(device());
      std::normal_distribution<double> normalDist(0.0, 1.0);

      double totalPower = 0.0;
      for (const auto& val : spectrum) {
          totalPower += val * val;
      }

      double noiseVariance = totalPower / (spectrum.size() * snr);

      for (auto& val : spectrum) {
          val += std::sqrt(noiseVariance) * normalDist(engine);
      }
  }
};

int main() {
  SpectrumAnalyzer analyzer;
  std::vector<RadioSignal> signals = {
      {ModulationType::AM, 1.0, 100.0, 10.0},
      {ModulationType::FM, 2.0, 500.0, 20.0}
  };

  auto spectrumData = analyzer.compute_spectrum(0.0, 1000.0, 2.0, 10.0, signals);

  for (const auto& value : spectrumData) {
      std::cout << value << std::endl;
  }

  return 0;
}

#include <iostream>
using namespace std;

// Definition for singly-linked list node
struct Node {
    int data;
    Node* link;
    Node(int val) : data(val), link(nullptr) {}
};

// Function to sum two numbers stored in reverse order as linked lists
Node* sumLinkedLists(Node* first, Node* second) {
    Node* sentinel = new Node(0);
    Node* traverse = sentinel;
    int overflow = 0;

    while (first != nullptr || second != nullptr) {
        int a = (first != nullptr) ? first->data : 0;
        int b = (second != nullptr) ? second->data : 0;
        int total = overflow + a + b;
        overflow = total / 10;

        traverse->link = new Node(total % 10);
        traverse = traverse->link;

        if (first != nullptr) first = first->link;
        if (second != nullptr) second = second->link;
    }

    if (overflow > 0) {
        traverse->link = new Node(overflow);
    }

    Node* output = sentinel->link;
    delete sentinel;
    return output;
}

// Utility function to display the linked list contents
void showList(Node* head) {
    while (head != nullptr) {
        cout << head->data << " ";
        head = head->link;
    }
    cout << endl;
}

// Entry point for testing the sumLinkedLists function
int main() {
    // Build first number: 2 -> 4 -> 3 (342 in reverse)
    Node* num1 = new Node(2);
    num1->link = new Node(4);
    num1->link->link = new Node(3);

    // Build second number: 5 -> 6 -> 4 (465 in reverse)
    Node* num2 = new Node(5);
    num2->link = new Node(6);
    num2->link->link = new Node(4);

    // Compute the sum
    Node* result = sumLinkedLists(num1, num2);

    // Display the result
    showList(result);

    // Free allocated memory for input lists and result
    while (num1 != nullptr) {
        Node* temp = num1;
        num1 = num1->link;
        delete temp;
    }
    while (num2 != nullptr) {
        Node* temp = num2;
        num2 = num2->link;
        delete temp;
    }
    while (result != nullptr) {
        Node* temp = result;
        result = result->link;
        delete temp;
    }

    return 0;
}

