        NULL // Default security attributes
    );

    if (serverPipe == INVALID_HANDLE_VALUE) {
        _ftprintf(stderr, _T("Error: Unable to create named pipe.\n"));
        return -1;
    }

    _tprintf(_T("Server initialized. Awaiting client connection...\n"));

    // Wait for a client to connect
    if (!ConnectNamedPipe(serverPipe, NULL)) {
        DWORD error = GetLastError();
        if (error != ERROR_PIPE_CONNECTED) {
            _tprintf(_T("Error: Connection failed (Error code: %lu).\n"), error);
            CloseHandle(serverPipe);
            return -1;
        }
    }

    _tprintf(_T("Client successfully connected.\n"));

    // Buffer for incoming data
    char buffer[512];
    DWORD bytesRead = 0;

    // Main communication loop
    while (true) {
        bytesRead = 0;

        // Ensure valid read size before processing
        do {
            if (!ReadFile(serverPipe, buffer, sizeof(buffer) - 1, &bytesRead, NULL)) {
                DWORD err = GetLastError();
                if (err == ERROR_BROKEN_PIPE || err == ERROR_NO_DATA) {
                    _tprintf(_T("Client disconnected.\n"));
                    goto reconnect;
                }
                _tprintf(_T("Read error (code %lu). Attempting recovery...\n"), err);
                goto reconnect;
            }

            if (bytesRead == 0) {
                _tprintf(_T("Connection lost during read.\n"));
                goto reconnect;
            }
        } while (bytesRead == 0 || bytesRead > 511);

        // Null-terminate the received string for safe printing
        buffer[bytesRead] = '\0';
        _tprintf(_T("Message received: %s\n"), buffer);
        continue;

    reconnect:
        // Reinitialize pipe for new connections
        CloseHandle(serverPipe);

        serverPipe = CreateNamedPipe(
            pipePath,
            PIPE_ACCESS_DUPLEX | FILE_FLAG_OVERLAPPED,
            PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT,
            1,
            1024,
            1024,
            120000,
            NULL
        );

        if (serverPipe == INVALID_HANDLE_VALUE) {
            _tprintf(_T("Critical failure: Cannot reinitialize pipe.\n"));
            return -1;
        }

        if (!ConnectNamedPipe(serverPipe, NULL)) {
            DWORD err = GetLastError();
            if (err != ERROR_PIPE_CONNECTED) {
                _tprintf(_T("Reconnection attempt failed (code %lu).\n"), err);
                CloseHandle(serverPipe);
                return -1;
            }
        }

        _tprintf(_T("New client connected after reconnection.\n"));
    }

    // Cleanup (unreachable in current logic due to infinite loop)
    CloseHandle(serverPipe);
    return 0;
}

