// Function to neutralize SetUnhandledExceptionFilter by replacing its implementation
bool BypassUnhandledExceptionFilter()
{
    // Machine code for: XOR RAX, RAX; RET (returns NULL immediately)
    const unsigned char PatchCode[5] = { 0x48, 0x33, 0xC0, 0xC3 };

    // Get handle to kernel32.dll
    HMODULE hKernel32 = GetModuleHandle(_T("kernel32.dll"));
    if (!hKernel32)
        return false;

    // Locate the address of SetUnhandledExceptionFilter
    BYTE* pFunction = (BYTE*)GetProcAddress(hKernel32, "SetUnhandledExceptionFilter");
    if (!pFunction)
        return false;

    // Overwrite the function with our patch
    if (!ModifyMemoryProtection(pFunction, PatchCode, sizeof(PatchCode)))
        return false;

    // Ensure CPU instruction cache is invalidated
    FlushInstructionCache(GetCurrentProcess(), pFunction, sizeof(PatchCode));

    return true;
}

// Helper function to safely write to executable memory
static bool ModifyMemoryProtection(BYTE* pDestination, const BYTE* pSourceData, DWORD dwLength)
{
    // Validate inputs
    if (!pDestination || !pSourceData || dwLength == 0)
        return false;
    if (IsBadReadPtr(pSourceData, dwLength))
        return false;

    // Change memory protection to allow writing
    DWORD previousProtection;
    if (!VirtualProtect(pDestination, dwLength, PAGE_EXECUTE_READWRITE, &previousProtection))
        return false;

    // Perform the actual copy
    memcpy(pDestination, pSourceData, dwLength);

    // Restore original memory protection
    DWORD dummy;
    VirtualProtect(pDestination, dwLength, previousProtection, &dummy);

    return true;
}

