int main() {
    CURL *handle = nullptr;
    FILE *input_file = nullptr;
    CURLcode result = CURLE_OK;

    // Initialize the CURL global environment
    curl_global_init(CURL_GLOBAL_ALL);
    handle = curl_easy_init();

    if (handle) {
        // Open the file in binary read mode
        input_file = fopen("path_to_your_file", "rb");
        if (input_file) {
            // Configure the transfer options
            curl_easy_setopt(handle, CURLOPT_URL, "http://yourserver.com/upload");
            curl_easy_setopt(handle, CURLOPT_READFUNCTION, data_provider);
            curl_easy_setopt(handle, CURLOPT_READDATA, input_file);
            curl_easy_setopt(handle, CURLOPT_UPLOAD, 1L);

            // Prepare custom headers for range specification
            struct curl_slist *headers = nullptr;
            headers = curl_slist_append(headers, "Content-Range: bytes 0-4999/100000");
            curl_easy_setopt(handle, CURLOPT_HTTPHEADER, headers);

            // Execute the upload operation
            result = curl_easy_perform(handle);

            // Handle any errors during transfer
            if (result != CURLE_OK) {
                std::cerr << "Transfer failed: " << curl_easy_strerror(result) << std::endl;
