        }

        // Release CURL resources
        curl_easy_cleanup(handle);
    }

    // Terminate CURL global state
    curl_global_cleanup();
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <limits>

struct Point {
    double x, y;
};

// Calculate Euclidean distance between two points
double dist(const Point& a, const Point& b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return std::sqrt(dx * dx + dy * dy);
}

// Find minimum distance in the strip around the dividing line
double minStripDist(std::vector<Point>& strip, double currentMin) {
    double best = currentMin;
    size_t len = strip.size();

    for (size_t i = 0; i < len; ++i) {
        // Only check points within current minimum distance vertically
        for (size_t k = i + 1; k < len && (strip[k].y - strip[i].y) < best; ++k) {
            double tempDist = dist(strip[i], strip[k]);
            if (tempDist < best) {
                best = tempDist;
            }
        }
    }
    return best;
}

// Recursive function to find closest pair using divide and conquer
double findClosest(std::vector<Point>& sortedX, std::vector<Point>& sortedY) {
    size_t count = sortedX.size();

    // Base case: small number of points
    if (count <= 3) {
        double minD = std::numeric_limits<double>::max();
        for (size_t i = 0; i < count; ++i) {
            for (size_t j = i + 1; j < count; ++j) {
                double d = dist(sortedX[i], sortedX[j]);
                if (d < minD) {
                    minD = d;
                }
            }
        }
        return minD;
    }

    // Divide points into two halves
    size_t midIdx = count / 2;
    Point midPoint = sortedX[midIdx];

    std::vector<Point> leftX(sortedX.begin(), sortedX.begin() + midIdx);
    std::vector<Point> rightX(sortedX.begin() + midIdx, sortedX.end());

    std::vector<Point> leftY, rightY;
    for (const auto& pt : sortedY) {
        if (pt.x <= midPoint.x) {
            leftY.push_back(pt);
        } else {
            rightY.push_back(pt);
        }
    }

    // Recursively find minimum distances in both halves
    double leftMin = findClosest(leftX, leftY);
    double rightMin = findClosest(rightX, rightY);
    double minSoFar = std::min(leftMin, rightMin);

    // Build strip of points within minSoFar distance from dividing line
    std::vector<Point> strip;
    for (const auto& pt : sortedY) {
        if (std::abs(pt.x - midPoint.x) < minSoFar) {
            strip.push_back(pt);
        }
    }

    // Check points in the strip
    return std::min(minSoFar, minStripDist(strip, minSoFar));
}

// Main function to prepare data and compute closest pair
void computeMinDistance(std::vector<Point>& pts) {
    std::vector<Point> byX = pts;
    std::vector<Point> byY = pts;

    std::sort(byX.begin(), byX.end(), [](const Point& p1, const Point& p2) {
        return p1.x < p2.x;
    });

    std::sort(byY.begin(), byY.end(), [](const Point& p1, const Point& p2) {
        return p1.y < p2.y;
    });

    double result = findClosest(byX, byY);
    std::cout << "The minimum distance is: " << result << std::endl;
}

int main() {
    std::vector<Point> samplePoints = {
        {2, 3}, {12, 30}, {40, 50}, {5, 1}, {12, 10}, {3, 4}
    };

    computeMinDistance(samplePoints);

    return 0;
}

#include <iostream>
#include <vector>

// Sort the vector using an optimized bubble sort algorithm
void bubbleSort(std::vector<int> &arr) {
    int n = arr.size();
    bool isSwapped;

    // Outer loop for each pass through the array
    for (int i = 0; i < n - 1; ++i) {
        isSwapped = false;

        // Inner loop for comparing adjacent elements
        for (int k = 0; k < n - i - 1; ++k) {
            if (arr[k] > arr[k + 1]) {
                // Swap elements if they are in wrong order
                int temp = arr[k];
                arr[k] = arr[k + 1];
                arr[k + 1] = temp;
                isSwapped = true;
            }
        }

        // If no swapping occurred, array is already sorted
        if (!isSwapped) {
            break;
        }
    }
}

