using namespace Microsoft::WRL;
using namespace D2D1;

class Direct2DRenderingHost : public HwndHost
{
public:
    Direct2DRenderingHost() : m_windowHandle(nullptr), m_factory(nullptr), m_renderTarget(nullptr) {}

    ~Direct2DRenderingHost()
    {
        if (m_renderTarget) m_renderTarget->Release();
        if (m_factory) m_factory->Release();
    }

    // Create the underlying Win32 window
    HWND CreateNativeWindow(HWND parent, HINSTANCE hInstance)
    {
        WNDCLASS wc = {0};
        wc.lpfnWndProc = DefWindowProc;
        wc.hInstance = hInstance;
        wc.lpszClassName = L"Direct2DRenderingHostClass";
        RegisterClass(&wc);

        return CreateWindow(
            L"Direct2DRenderingHostClass", 
            L"Direct2DRenderingHost", 
            WS_CHILD | WS_VISIBLE, 
            0, 0, 0, 0, 
            parent, 
            nullptr, 
            hInstance, 
            nullptr
        );
    }

    // Initialize and construct the host window
    HRESULT BuildWindowCore(HWND hwndParent)
    {
        m_windowHandle = CreateNativeWindow(hwndParent, GetModuleHandle(nullptr));

        // Configure Direct2D factory with optional debug support
        D2D1_FACTORY_OPTIONS factoryOptions = {};
#if defined(_DEBUG)
        factoryOptions.debugLevel = D2D1_DEBUG_LEVEL_INFORMATION;
#endif

        D2D1CreateFactory(
            D2D1_FACTORY_TYPE_SINGLE_THREADED, 
            factoryOptions, 
            &m_factory
        );

        return S_OK;
    }

    // Clean up and destroy the hosted window
    void DestroyWindowCore()
    {
        if (m_windowHandle)
        {
            DestroyWindow(m_windowHandle);
            m_windowHandle = nullptr;
        }
    }

    // Retrieve the internal window handle
    HWND GetWindowHandle() const
    {
        return m_windowHandle;
    }

    // Set up the render target based on current client area
    void InitializeRenderTarget()
    {
        if (m_windowHandle && m_factory)
        {
            RECT clientRect;
            GetClientRect(m_windowHandle, &clientRect);

            D2D1_SIZE_U dimensions = D2D1::SizeU(
                clientRect.right - clientRect.left,
                clientRect.bottom - clientRect.top
            );

            m_factory->CreateHwndRenderTarget(
                D2D1::RenderTargetProperties(),
                D2D1::HwndRenderTargetProperties(m_windowHandle, dimensions),
                &m_renderTarget
            );
        }
    }

    // Perform rendering operations
    void DrawContent()
    {
        if (m_renderTarget)
        {
            m_renderTarget->BeginDraw();

            // Clear background to sky blue
            m_renderTarget->Clear(D2D1::ColorF(D2D1::ColorF::SkyBlue));

            // Draw a red rectangle at top-left corner
            D2D1_RECT_F rectangle = D2D1::RectF(0.0f, 0.0f, 100.0f, 100.0f);
            ComPtr<ID2D1SolidColorBrush> brush;
            m_renderTarget->CreateSolidColorBrush(D2D1::ColorF(D2D1::ColorF::Red), &brush);
            m_renderTarget->FillRectangle(rectangle, brush.Get());

            m_renderTarget->EndDraw();
        }
    }

    // Process window messages
    LRESULT HandleMessage(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
    {
        switch (message)
        {
        case WM_PAINT:
            DrawContent();
            ValidateRect(m_windowHandle, nullptr);
            return 0;

        case WM_SIZE:
            if (m_renderTarget)
            {
                RECT rc;
                GetClientRect(m_windowHandle, &rc);
                D2D1_SIZE_U size = D2D1::SizeU(rc.right - rc.left, rc.bottom - rc.top);
                m_renderTarget->Resize(size);
            }
            return 0;

        case WM_DESTROY:
            PostQuitMessage(0);
            return 0;
        }

        return DefWindowProc(hwnd, message, wParam, lParam);
    }

private:
    HWND m_windowHandle;
    ComPtr<ID2D1Factory> m_factory;
    ComPtr<ID2D1HwndRenderTarget> m_renderTarget;
};

#include <iostream>
#include <ctime>

int main(int argc, char* argv[]) {
    // Allocate memory for arrays of varying sizes
    int* smallArray1 = new int[16384];   // 2^14 elements
    int* smallArray2 = new int[32768];   // 2^15 elements
    int* smallArray3 = new int[65536];   // 2^16 elements

    // Initialize small arrays to zero
    for (int idx = 0; idx < 16384; ++idx) smallArray1[idx] = 0;
    for (int idx = 0; idx < 32768; ++idx) smallArray2[idx] = 0;
    for (int idx = 0; idx < 65536; ++idx) smallArray3[idx] = 0;

    // Allocate memory for large arrays
    int* largeArray1 = new int[16777216]; // 2^24 elements
    int* largeArray2 = new int[33554432]; // 2^25 elements
    int* largeArray3 = new int[67108864]; // 2^26 elements

    // Initialize large arrays to zero
    for (int idx = 0; idx < 16777216; ++idx) largeArray1[idx] = 0;
    for (int idx = 0; idx < 33554432; ++idx) largeArray2[idx] = 0;
    for (int idx = 0; idx < 67108864; ++idx) largeArray3[idx] = 0;

    int limit;
    std::cout << "Until: ";
    std::cin >> limit;

    // Variables to accumulate values
    int counter1 = 0, counter2 = 0, counter3 = 0;
    int counter4 = 0, counter5 = 0, counter6 = 0;

    // First timing block: increment and store in small arrays
    clock_t begin = clock();
    for (int j = 0; j < limit; ++j) {
        counter1++;
        counter2++;
        counter3++;
    }
    smallArray1[1] = counter1;
    smallArray2[1] = counter2;
    smallArray3[1] = counter3;
    clock_t end = clock();

    double elapsed_time = static_cast<double>(end - begin) / CLOCKS_PER_SEC;
    std::cout << "Time: " << elapsed_time << " sec.\n";

    // Second timing block: increment and store in large arrays
    begin = clock();
    for (int k = 0; k < limit; ++k) {
        counter4++;
        counter5++;
        counter6++;
    }
    largeArray1[1] = counter4;
    largeArray2[1] = counter5;
    largeArray3[1] = counter6;
    end = clock();

    elapsed_time = static_cast<double>(end - begin) / CLOCKS_PER_SEC;
    std::cout << "Time: " << elapsed_time << " sec.\n";

    // Free allocated memory
    delete[] smallArray1;
    delete[] smallArray2;
    delete[] smallArray3;
    delete[] largeArray1;
    delete[] largeArray2;
    delete[] largeArray3;

    // Pause before exit (platform-independent)
    std::cin.get();
    return 0;
}

