#include <iostream>
#include <fstream>
#include <vector>
#include <string>

std::vector<uint8_t> applyXorCipher(const std::vector<uint8_t>& input, const std::string& key) {
    std::vector<uint8_t> result = input;
    size_t keyLength = key.length();

    for (size_t position = 0; position < input.size(); ++position) {
        result[position] ^= static_cast<uint8_t>(key[position % keyLength]);
    }

    return result;
}

std::vector<uint8_t> revertXorCipher(const std::vector<uint8_t>& encrypted, const std::string& key) {
    return applyXorCipher(encrypted, key); // XOR operation is its own inverse
}

void processFile(const std::string& sourcePath, const std::string& destinationPath, const std::string& secretKey) {
    std::ifstream inputStream(sourcePath, std::ios::binary);
    std::ofstream outputStream(destinationPath, std::ios::binary);

    if (!inputStream.is_open() || !outputStream.is_open()) {
        std::cerr << "Failed to open required files." << std::endl;
        return;
    }

    const size_t bufferSize = 1024;
    std::vector<uint8_t> tempBuffer(bufferSize);

    while (inputStream.read(reinterpret_cast<char*>(tempBuffer.data()), bufferSize)) {
        size_t actualBytesRead = inputStream.gcount();
        std::vector<uint8_t> processedBuffer = applyXorCipher(tempBuffer, secretKey);
        outputStream.write(reinterpret_cast<const char*>(processedBuffer.data()), actualBytesRead);
    }

    inputStream.close();
    outputStream.close();
}

void decryptFile(const std::string& encryptedPath, const std::string& decryptedPath, const std::string& secretKey) {
    processFile(encryptedPath, decryptedPath, secretKey); // XOR decryption uses the same function as encryption
}

#include <iostream>
using namespace std;

// Define the structure for the node
struct Node {
    int data;
    Node* next;
};

// Function to check if the linked list is circular
bool isCircular(Node* head) {
    // Handle empty list case
    if (head == nullptr) {
        return false; // An empty list is not considered circular
    }

    Node* current = head;
    Node* runner = head;

    // Use Floyd's cycle detection algorithm (tortoise and hare)
    while (runner != nullptr && runner->next != nullptr) {
        current = current->next;          // Move one step at a time
        runner = runner->next->next;      // Move two steps at a time

        // If they meet, there's a cycle
        if (current == runner) {
            return true;
        }
    }

    // If we reach here, no cycle was found
    return false;
}

// Function to create a new node
Node* createNode(int value) {
    Node* newNode = new Node();
    newNode->data = value;
    newNode->next = nullptr;
    return newNode;
}

// Function to create a circular linked list for testing
Node* buildCircularList() {
    Node* first = createNode(1);
    Node* second = createNode(2);
    Node* third = createNode(3);
    Node* fourth = createNode(4);

    first->next = second;
    second->next = third;
    third->next = fourth;
    fourth->next = first; // Complete the circle

    return first;
}

// Function to create a linear (non-circular) linked list for testing
Node* buildLinearList() {
    Node* first = createNode(1);
    Node* second = createNode(2);
    Node* third = createNode(3);
    Node* fourth = createNode(4);

    first->next = second;
    second->next = third;
    third->next = fourth;
    fourth->next = nullptr; // End of list

    return first;
}

