    Node* linearStructure = buildLinearList();

    cout << "Is the circular list circular? " << (isCircular(circularStructure) ? "Yes" : "No") << endl;
    cout << "Is the linear list circular? " << (isCircular(linearStructure) ? "Yes" : "No") << endl;

    return 0;
}

