std::mutex print_mutex; // Mutex for thread-safe output operations

// Partition function using Hoare's scheme with median-of-three pivot selection
int partition(std::vector<int>& data, int start, int end) {
    int mid = start + (end - start) / 2;
    // Median-of-three pivot selection
    if (data[start] > data[mid]) std::swap(data[start], data[mid]);
    if (data[mid] > data[end]) std::swap(data[mid], data[end]);
    if (data[start] > data[mid]) std::swap(data[start], data[mid]);

    int pivot_value = data[mid];
    int left_index = start - 1;
    int right_index = end + 1;

    while (true) {
        do {
            left_index++;
        } while (data[left_index] < pivot_value);

        do {
            right_index--;
        } while (data[right_index] > pivot_value);

        if (left_index >= right_index) return right_index;

        std::swap(data[left_index], data[right_index]);
    }
}

// Sequential sorting implementation
void sequential_sort(std::vector<int>& data, int begin, int finish) {
    if (begin < finish) {
        int split_point = partition(data, begin, finish);
        sequential_sort(data, begin, split_point);
        sequential_sort(data, split_point + 1, finish);
    }
}

// Parallel sorting implementation with work-stealing approach
void concurrent_sort(std::vector<int>& data, int begin, int finish, int cutoff) {
    // Use sequential sort when subarray size is below threshold
    if (finish - begin < cutoff) {
        sequential_sort(data, begin, finish);
        return;
    }

    int split_point = partition(data, begin, finish);

    // Launch parallel tasks for larger partitions
    std::future<void> left_task;
    if (begin < split_point) {
        left_task = std::async(std::launch::async, 
                              [&data, begin, split_point, cutoff]() {
                                  concurrent_sort(data, begin, split_point, cutoff);
                              });
    }

    // Process right side either in new thread or current thread
    if (split_point + 1 < finish) {
        if (left_task.valid()) {
            concurrent_sort(data, split_point + 1, finish, cutoff);
            left_task.get();
        } else {
            concurrent_sort(data, split_point + 1, finish, cutoff);
        }
    }
}

int main() {
    std::vector<int> numbers = {3, 6, 8, 10, 1, 2, 1};
    int cutoff_size = 4; // Threshold for switching to sequential sort

    // Print original array
    std::cout << "Initial sequence: ";
    for (const int& value : numbers) {
        std::cout << value << " ";
    }
    std::cout << std::endl;

    // Perform parallel sorting
    concurrent_sort(numbers, 0, static_cast<int>(numbers.size()) - 1, cutoff_size);

    // Print sorted array
    std::cout << "Ordered sequence: ";
    for (const int& value : numbers) {
        std::cout << value << " ";
    }
    std::cout << std::endl;

    return 0;
}

