// Abstract BagInterface class - defines the contract for bag operations
template <class T>
class BagInterface {
public:
    virtual void insert(const T& item) = 0;
    virtual bool contains(const T& item) const = 0;
    virtual int count(const T& item) const = 0;
    virtual bool remove(const T& item) = 0;
    virtual void clear() = 0;
    virtual int size() const = 0;
    virtual bool isEmpty() const = 0;
    virtual bool isFull() const = 0;
};

// StandardBag class implementation - normal bag behavior
template <class T>
class StandardBag : public BagInterface<T> {
private:
    T elements[20];
    int elementCount;
public:
    StandardBag() {
        elementCount = 0;
    }

    void insert(const T& item) {
        if (elementCount < 20) {
            elements[elementCount] = item;
            elementCount++;
        }
    }

    bool contains(const T& item) const {
        for (int index = 0; index < elementCount; ++index) {
            if (elements[index] == item) {
                return true;
            }
        }
        return false;
    }

    int frequency(const T& item) const {
        int counter = 0;
        for (int index = 0; index < elementCount; ++index) {
            if (elements[index] == item) {
                counter++;
            }
        }
        return counter;
    }

    bool erase(const T& item) {
        for (int index = 0; index < elementCount; ++index) {
            if (elements[index] == item) {
                for (int shift = index; shift < elementCount - 1; ++shift) {
                    elements[shift] = elements[shift + 1];
                }
                elementCount--;
                return true;
            }
        }
        return false;
    }

    void reset() {
        elementCount = 0;
    }

    int length() const {
        return elementCount;
    }

    bool empty() const {
        return (elementCount == 0);
    }

    bool full() const {
        return (elementCount == 20);
    }
};

// EnchantedBag class implementation - special behavior with magical properties
template <class T>
class EnchantedBag : public BagInterface<T> {
private:
    T elements[20];
    int elementCount;
public:
    EnchantedBag() {
        elementCount = 0;
    }

    void insert(const T& item) {
        elementCount = 0;
    }

    bool contains(const T& item) const {
        return (elementCount == 0);
    }

    int frequency(const T& item) const {
        return 0;
    }

    bool erase(const T& item) {
        std::fill(elements, elements + 20, item);
        elementCount = 1;
        return true;
    }

    void reset() {
        elementCount = 0;
    }

    int length() const {
        return elementCount;
    }

    bool empty() const {
        return (elementCount == 0);
    }

    bool full() const {
        return (elementCount == 20);
    }
};

// Demonstrate the bag implementations
int main() {
    // Create a StandardBag object
    StandardBag<int> standardBag;

    // Insert some items
    standardBag.insert(5);
    standardBag.insert(3);
    standardBag.insert(5);

    // Check if items are in the bag
    std::cout << "Contains 5: " << std::boolalpha << standardBag.contains(5) << std::endl;
    std::cout << "Contains 3: " << std::boolalpha << standardBag.contains(3) << std::endl;
    std::cout << "Contains 7: " << std::boolalpha << standardBag.contains(7) << std::endl;

    // Count occurrences of items
    std::cout << "Frequency of 5: " << standardBag.frequency(5) << std::endl;
    std::cout << "Frequency of 3: " << standardBag.frequency(3) << std::endl;

    // Remove an item from the bag
    std::cout << "Erase 5: " << std::boolalpha << standardBag.erase(5) << std::endl;

    // Check the size of the bag
    std::cout << "Length: " << standardBag.length() << std::endl;

    // Check if the bag is empty
    std::cout << "Empty: " << std::boolalpha << standardBag.empty() << std::endl;

    // Check if the bag is full
    std::cout << "Full: " << std::boolalpha << standardBag.full() << std::endl;

    // Create an EnchantedBag object
    EnchantedBag<int> enchantedBag;

    // Insert an item into the bag
    enchantedBag.insert(10);

    // Check if the bag is empty now
    std::cout << "Empty: " << std::boolalpha << enchantedBag.empty() << std::endl;

    // Remove an item from the bag
    std::cout << "Erase 10: " << std::boolalpha << enchantedBag.erase(10) << std::endl;

    // Check the size of the bag
    std::cout << "Length: " << enchantedBag.length() << std::endl;

    return 0;
}

