class TicTacToeGame {
public:
    TicTacToeGame() : grid({{'.', '.', '.'}, {'.', '.', '.'}, {'.', '.', '.'}}), activePlayer('X') {}

    void displayGrid() const {
        for (const auto& line : grid) {
            for (char position : line) {
                std::cout << position << " ";
            }
            std::cout << "\n";
        }
    }

    bool attemptMove(int r, int c) {
        if (r < 0 || r > 2 || c < 0 || c > 2 || grid[r][c] != '.') {
            return false; // Move not allowed
        }
        grid[r][c] = activePlayer;
        switchTurn();
        return true;
    }

    char evaluateGameState() const {
        // Evaluate rows and columns
        for (int idx = 0; idx < 3; ++idx) {
            if (grid[idx][0] == grid[idx][1] && grid[idx][1] == grid[idx][2] && grid[idx][0] != '.') {
                return grid[idx][0];
            }
            if (grid[0][idx] == grid[1][idx] && grid[1][idx] == grid[2][idx] && grid[0][idx] != '.') {
                return grid[0][idx];
            }
        }

        // Evaluate diagonals
        if (grid[0][0] == grid[1][1] && grid[1][1] == grid[2][2] && grid[0][0] != '.') {
            return grid[0][0];
        }
        if (grid[0][2] == grid[1][1] && grid[1][1] == grid[2][0] && grid[0][2] != '.') {
            return grid[0][2];
        }

        // Check for tie
        for (const auto& line : grid) {
            for (char spot : line) {
                if (spot == '.') {
                    return '.'; // Game still in progress
                }
            }
        }

        return 'T'; // Tie
    }

    char getActivePlayer() const {
        return activePlayer;
    }

private:
    std::array<std::array<char, 3>, 3> grid;
    char activePlayer;

    void switchTurn() {
        activePlayer = (activePlayer == 'X') ? 'O' : 'X';
    }
};

int main() {
    TicTacToeGame match;
    match.displayGrid();

    while (true) {
        int row, column;
        std::cout << "Player " << match.getActivePlayer() << ", enter your coordinates (row column): ";
        std::cin >> row >> column;

        if (match.attemptMove(row, column)) {
            match.displayGrid();
            char result = match.evaluateGameState();
            if (result == 'X' || result == 'O') {
                std::cout << "Player " << result << " has won!" << std::endl;
                break;
            } else if (result == 'T') {
                std::cout << "The game ended in a tie!" << std::endl;
                break;
            }
        } else {
            std::cout << "Invalid input, please try again." << std::endl;
        }
    }

    return 0;
}

