// Custom smart pointer implementation with reference counting
template <typename T>
class SmartPointer {
public:
    explicit SmartPointer(T* raw_ptr = nullptr) : data_(raw_ptr), count_(nullptr) {
        if (raw_ptr != nullptr) {
            count_ = new std::size_t(1);
        }
    }

    SmartPointer(const SmartPointer& other) : data_(other.data_), count_(other.count_) {
        if (count_ != nullptr) {
            ++(*count_);
        }
    }

    SmartPointer& operator=(const SmartPointer& other) {
        if (this != &other) {
            cleanup();
            data_ = other.data_;
            count_ = other.count_;
            if (count_ != nullptr) {
                ++(*count_);
            }
        }
        return *this;
    }

    ~SmartPointer() {
        cleanup();
    }

    T* access() const {
        return data_;
    }

    T& dereference() const {
        return *data_;
    }

    T* member_access() const {
        return data_;
    }

    std::size_t reference_count() const {
        return (count_ != nullptr) ? *count_ : 0;
    }

private:
    void cleanup() {
        if (count_ != nullptr && --(*count_) == 0) {
            delete data_;
            delete count_;
        }
        data_ = nullptr;
        count_ = nullptr;
    }

    T* data_;
    std::size_t* count_;
};

int main() {
    SmartPointer<int> ptr(new int(42));
    std::cout << ptr.dereference() << " (" << ptr.reference_count() << " references)" << std::endl;
    return 0;
}

