typedef unsigned long U32;

extern "C" __declspec(dllexport) int ReadFile(LPSTR Path, U32** DataPtr, U32* Count)
{
    FILE *fileHandle;
    U32 *buffer;
    CString filePath(Path);
    long fileSize;

    // Open file in binary read mode
    fileHandle = fopen(filePath, "rb");
    if (fileHandle == nullptr) {
        return 0;
    }

    // Determine file size by seeking to end
    fseek(fileHandle, 0L, SEEK_END);
    fileSize = ftell(fileHandle);
    rewind(fileHandle);

    // Validate that file size is divisible by sizeof(U32)
    if (fileSize % sizeof(U32) != 0) {
        fclose(fileHandle);
        return -3; // Invalid file size alignment
    }

    // Allocate memory for the entire file content
    buffer = (U32 *)malloc(fileSize);
    if (buffer == nullptr) {
        fclose(fileHandle);
        return -1;
    }

    // Read all data into buffer
    size_t elementsRead = fread(buffer, sizeof(U32), fileSize / sizeof(U32), fileHandle);
    if (elementsRead == 0) {
        fclose(fileHandle);
        free(buffer);
        return -2;
    }

    // Return results via output parameters
    *Count = static_cast<U32>(elementsRead);
    *DataPtr = buffer;
    fclose(fileHandle);
    return 1;
}

