// Helper function to allocate and initialize device memory for image data
void setupTextureAndArray(unsigned char* hostImage, int imgWidth, int imgHeight, 
                          cudaArray*& cuMem, texture<unsigned char, 2, cudaReadModeElementType>& tex) {
    cudaChannelFormatDesc desc = cudaCreateChannelDesc(8, 8, 8, 0, cudaChannelFormatKindUnsigned);
    cudaMallocArray(&cuMem, &desc, imgWidth, imgHeight);

    cudaMemcpy2DToArray(cuMem, 0, 0, hostImage, imgWidth * 3, imgWidth * 3, imgHeight, cudaMemcpyHostToDevice);

    cudaBindTextureToArray(tex, cuMem, desc);
}

// Kernel: reads from texture and writes processed pixel data to device memory
__global__ void applyFilterKernel(unsigned char* devResult, int rows, int cols) {
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    if (x < cols && y < rows) {
        // Sample each channel using texture coordinates (note: texture stores interleaved RGB)
        unsigned char r = tex2D(tex, x, y); // Red
        unsigned char g = tex2D(tex, x, y + 0.5f); // Green — offset by half-pixel row (not ideal but avoids index math)
        unsigned char b = tex2D(tex, x, y + 1.0f); // Blue — full row offset

        // Compute linear index manually for output buffer
        int idx = (y * cols + x) * 3;
        devResult[idx]     = r;
        devResult[idx + 1] = g;
        devResult[idx + 2] = b;
    }
}

int main() {
    const int width = 640;
    const int height = 480;

    // Simulate host image allocation (in real usage, this would come from OpenCV or file)
    unsigned char* h_img = new unsigned char[width * height * 3];
    for (int i = 0; i < width * height * 3; ++i) {
        h_img[i] = static_cast<unsigned char>(i % 256); // dummy pattern
    }

    // Device allocations
    unsigned char* d_result = nullptr;
    cudaMalloc(&d_result, width * height * 3 * sizeof(unsigned char));

    // Texture setup
    cudaArray* cuArray = nullptr;
    texture<unsigned char, 2, cudaReadModeElementType> tex;
    tex.normalized = false;
    tex.filterMode = cudaFilterModePoint;
    tex.addressMode[0] = cudaAddressModeClamp;
    tex.addressMode[1] = cudaAddressModeClamp;

    setupTextureAndArray(h_img, width, height, cuArray, tex);

    // Launch configuration
    dim3 blockDims(16, 16);
    dim3 gridDims((width + blockDims.x - 1) / blockDims.x,
                  (height + blockDims.y - 1) / blockDims.y);

    // Execute kernel
    applyFilterKernel<<<gridDims, blockDims>>>(d_result, height, width);
    cudaDeviceSynchronize();

    // Retrieve result
    unsigned char* resultHost = new unsigned char[width * height * 3];
    cudaMemcpy(resultHost, d_result, width * height * 3 * sizeof(unsigned char), cudaMemcpyDeviceToHost);

    // Cleanup resources
    cudaFree(d_result);
    cudaUnbindTexture(tex);
    cudaFreeArray(cuArray);
    delete[] h_img;
    delete[] resultHost;

    return 0;
}

