// Compute quaternion product using alternative variable naming and structure
std::array<double, 4> compute_quaternion_product(const std::array<double, 4>& first, const std::array<double, 4>& second) {
    double a0 = first[0], a1 = first[1], a2 = first[2], a3 = first[3];
    double b0 = second[0], b1 = second[1], b2 = second[2], b3 = second[3];

    double res_w = a0 * b0 - a1 * b1 - a2 * b2 - a3 * b3;
    double res_x = a0 * b1 + a1 * b0 + a2 * b3 - a3 * b2;
    double res_y = a0 * b2 - a1 * b3 + a2 * b0 + a3 * b1;
    double res_z = a0 * b3 + a1 * b2 - a2 * b1 + a3 * b0;

    return {res_w, res_x, res_y, res_z};
}

int main() {
    std::array<double, 4> qA = {0.98, 0.08, 0.17, -0.01};
    std::array<double, 4> qB = {0.70, 0.70, 0.0, 0.0};

    std::array<double, 4> output = compute_quaternion_product(qA, qB);

    for (size_t i = 0; i < output.size(); ++i) {
        std::cout << output[i];
        if (i < output.size() - 1) std::cout << " ";
    }
    std::cout << std::endl;

    return 0;
}

