    }
}

// Continuously check for the target process and restart if missing
void WatchAndRestart(const std::string& targetExe)
{
    while (true)
    {
        bool found = false;
        HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);

        if (hSnap != INVALID_HANDLE_VALUE)
        {
            PROCESSENTRY32 entry = {0};
            entry.dwSize = sizeof(PROCESSENTRY32);

            if (Process32First(hSnap, &entry))
            {
                do
                {
                    if (_stricmp(entry.szExeFile, targetExe.c_str()) == 0)
                    {
                        found = true;
                        break;
                    }
                } while (Process32Next(hSnap, &entry));
            }

            CloseHandle(hSnap);
        }

        // If not found, launch it again
        if (!found)
        {
            LaunchApplication(targetExe);
        }

        // Wait before next check
        std::this_thread::sleep_for(std::chrono::seconds(5));
    }
}

int main()
{
    std::string appName = "YourExecutableName.exe";
    WatchAndRestart(appName);
    return 0;
}

