using namespace std;

struct City {
    int id;
    double x, y;
};

double calculateDistance(const City& pointA, const City& pointB) {
    double deltaX = pointA.x - pointB.x;
    double deltaY = pointA.y - pointB.y;
    return sqrt(deltaX * deltaX + deltaY * deltaY);
}

double computeTourLength(const vector<City>& citySequence, const vector<int>& order) {
    double total = 0.0;
    int size = citySequence.size();
    for (int i = 0; i < size; ++i) {
        int nextIndex = (i + 1) % size;
        total += calculateDistance(citySequence[order[i]], citySequence[order[nextIndex]]);
    }
    return total;
}

vector<vector<double>> buildDistanceTable(const vector<City>& locations) {
    int count = locations.size();
    vector<vector<double>> matrix(count, vector<double>(count));
    for (int row = 0; row < count; ++row) {
        for (int col = 0; col < count; ++col) {
            matrix[row][col] = calculateDistance(locations[row], locations[col]);
        }
    }
    return matrix;
}

vector<int> combinePaths(const vector<int>& route1, const vector<int>& route2) {
    int length = route1.size();
    uniform_int_distribution<int> distribution(0, length - 1);
    int begin = distribution(default_random_engine(time(0)));
    int finish = distribution(default_random_engine(time(0)));

    if (begin > finish) swap(begin, finish);

    vector<int> offspring(length, -1);
    for (int pos = begin; pos <= finish; ++pos) {
        offspring[pos] = route1[pos];
    }

    int index = 0;
    for (int gene : route2) {
        if (find(offspring.begin(), offspring.end(), gene) == offspring.end()) {
            while (offspring[index] != -1) index++;
            offspring[index] = gene;
        }
    }
    return offspring;
}

void perturbPath(vector<int>& route, double changeProbability) {
    default_random_engine generator(time(0));
    uniform_real_distribution<double> probabilityCheck(0.0, 1.0);

    for (size_t position = 0; position < route.size(); ++position) {
        if (probabilityCheck(generator) < changeProbability) {
            uniform_int_distribution<int> indexDistribution(0, route.size() - 1);
            int swapPosition = indexDistribution(generator);
            swap(route[position], route[swapPosition]);
        }
    }
}

vector<int> runGeneticSearch(const vector<City>& locations, int populationCount, 
                            double mutationChance, int cycleCount) {
    int cityCount = locations.size();
    vector<vector<int>> currentGeneration(populationCount, vector<int>(cityCount));

    // Initialize population with random permutations
    for (int individual = 0; individual < populationCount; ++individual) {
        for (int cityIndex = 0; cityIndex < cityCount; ++cityIndex) {
            currentGeneration[individual][cityIndex] = cityIndex;
        }
        shuffle(currentGeneration[individual].begin(), currentGeneration[individual].end(),
                default_random_engine(time(0)));
    }

    vector<pair<double, vector<int>>> evaluationResults;

    // Evolve over generations
    for (int generation = 0; generation < cycleCount; ++generation) {
        evaluationResults.clear();

        // Evaluate fitness of each individual
        for (const auto& path : currentGeneration) {
            double tourCost = computeTourLength(locations, path);
            evaluationResults.push_back({tourCost, path});
        }

        // Sort by fitness (shortest distance first)
        sort(evaluationResults.begin(), evaluationResults.end());

        // Select top half for breeding
        vector<vector<int>> breedingPool;
        for (int i = 0; i < populationCount / 2; ++i) {
            breedingPool.push_back(evaluationResults[i].second);
        }

        // Create new generation through crossover and mutation
        while (breedingPool.size() < populationCount) {
            uniform_int_distribution<int> selectIndex(0, breedingPool.size() - 1);
            int parentA = selectIndex(default_random_engine(time(0)));
            int parentB = selectIndex(default_random_engine(time(0)));

            vector<int> child = combinePaths(breedingPool[parentA], breedingPool[parentB]);
            perturbPath(child, mutationChance);
            breedingPool.push_back(child);
        }

        currentGeneration = breedingPool;
    }

    return evaluationResults[0].second;
}

int main() {
    vector<City> urbanCenters = {{0, 0, 0}, {1, 1, 2}, {2, 3, 1}, {3, 5, 5}, {4, 6, 2}};
    int populationSize = 100;
    double mutationFrequency = 0.01;
    int evolutionarySteps = 1000;

    vector<int> optimalRoute = runGeneticSearch(urbanCenters, populationSize, 
                                               mutationFrequency, evolutionarySteps);

    cout << "Optimal Route: ";
    for (int cityIndex : optimalRoute) {
        cout << urbanCenters[cityIndex].id << " ";
    }
    cout << "\nTotal Distance: " << computeTourLength(urbanCenters, optimalRoute) << endl;

    return 0;
}

