// Function to create and populate a SAFEARRAY of bytes
HRESULT __stdcall TestSafeArray(SAFEARRAY** ppData)
{
    if (ppData == nullptr)
        return E_POINTER;

    // Create a SAFEARRAY of unsigned 1-byte integers (VT_UI1) with bounds [0, 4]
    SAFEARRAY* psa = SafeArrayCreateVector(VT_UI1, 0, 5);
    if (psa == nullptr)
    {
        return E_OUTOFMEMORY;
    }

    // Prepare data to copy into the array
    const BYTE initialData[] = { 1u, 2u, 3u, 4u, 5u };

    // Safely access the array memory and copy data
    HRESULT hr = SafeArrayLock(psa);
    if (FAILED(hr))
    {
        SafeArrayDestroy(psa);
        return hr;
    }

    try {
        memcpy(psa->pvData, initialData, sizeof(initialData));
    }
    catch (...) {
        SafeArrayUnlock(psa);
        SafeArrayDestroy(psa);
        return E_FAIL;
    }

    SafeArrayUnlock(psa);

    *ppData = psa;
    return S_OK;
}

#include <iostream>
using namespace std;

// Structure representing a node in the Binary Search Tree
struct TreeNode {
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;
};

// Creates and returns a new tree node with the specified value
TreeNode* createNode(int value) {
    TreeNode* newNode = new TreeNode();
    newNode->value = value;
    newNode->leftChild = newNode->rightChild = nullptr;
    return newNode;
}

// Inserts a value into the BST, maintaining BST properties
TreeNode* addValue(TreeNode* currentRoot, int newValue) {
    if (currentRoot == nullptr) 
        return createNode(newValue);

    if (newValue < currentRoot->value)
        currentRoot->leftChild = addValue(currentRoot->leftChild, newValue);
    else
        currentRoot->rightChild = addValue(currentRoot->rightChild, newValue);

    return currentRoot;
}

// Locates the inorder successor of a given node in the BST
TreeNode* locateInorderSuccessor(TreeNode* searchRoot, TreeNode* targetNode) {
    TreeNode* potentialSuccessor = nullptr;

    while (searchRoot != nullptr) {
        if (targetNode->value < searchRoot->value) {
            potentialSuccessor = searchRoot;
            searchRoot = searchRoot->leftChild;
        } else if (targetNode->value > searchRoot->value) {
            searchRoot = searchRoot->rightChild;
        } else {
            break;
        }
    }

    // If the node has a right subtree, find the leftmost node in it
    if (searchRoot != nullptr && searchRoot->rightChild != nullptr) {
        TreeNode* temp = searchRoot->rightChild;
        while (temp->leftChild != nullptr) {
            temp = temp->leftChild;
        }
        potentialSuccessor = temp;
    }

    return potentialSuccessor;
}

// Locates the inorder predecessor of a given node in the BST
TreeNode* locateInorderPredecessor(TreeNode* searchRoot, TreeNode* targetNode) {
    TreeNode* potentialPredecessor = nullptr;

    while (searchRoot != nullptr) {
        if (targetNode->value > searchRoot->value) {
            potentialPredecessor = searchRoot;
            searchRoot = searchRoot->rightChild;
        } else if (targetNode->value < searchRoot->value) {
            searchRoot = searchRoot->leftChild;
        } else {
            break;
        }
    }

    // If the node has a left subtree, find the rightmost node in it
    if (searchRoot != nullptr && searchRoot->leftChild != nullptr) {
        TreeNode* temp = searchRoot->leftChild;
        while (temp->rightChild != nullptr) {
            temp = temp->rightChild;
        }
        potentialPredecessor = temp;
    }

    return potentialPredecessor;
}

// Displays the inorder predecessor and successor for a given key
void displayResults(TreeNode* root, int searchKey) {
    TreeNode* currentNode = root;

    // Search for the node with the given key
    while (currentNode != nullptr && currentNode->value != searchKey) {
        if (searchKey < currentNode->value)
            currentNode = currentNode->leftChild;
        else
            currentNode = currentNode->rightChild;
    }

    if (currentNode == nullptr) {
        cout << "Node with key " << searchKey << " not found in the BST." << endl;
        return;
    }

    TreeNode* pred = locateInorderPredecessor(root, currentNode);
    TreeNode* succ = locateInorderSuccessor(root, currentNode);

    if (pred != nullptr)
        cout << "Inorder Predecessor of " << searchKey << " is " << pred->value << endl;
    else
        cout << "No inorder predecessor for " << searchKey << endl;

    if (succ != nullptr)
        cout << "Inorder Successor of " << searchKey << " is " << succ->value << endl;
    else
        cout << "No inorder successor for " << searchKey << endl;
}

// Entry point to demonstrate BST operations
int main() {
    TreeNode* bstRoot = nullptr;

    // Build the BST with sample values
    bstRoot = addValue(bstRoot, 20);
    addValue(bstRoot, 8);
    addValue(bstRoot, 22);
    addValue(bstRoot, 4);
    addValue(bstRoot, 12);
    addValue(bstRoot, 10);
    addValue(bstRoot, 14);

    int target = 12;
    displayResults(bstRoot, target);

    return 0;
}

