#include <boost/variant.hpp>
#include <vector>
#include <cstring>

// Union to hold different data types
union MixedData {
    int integerVal;
    char* textVal;

    MixedData() : integerVal(0) {}
    ~MixedData() {
        if (textVal != nullptr) {
            delete[] textVal;
            textVal = nullptr;
        }
    }
};

// Structure representing a variant type container
struct VariantRecord {
    int kind; // 0: integer, 1: string
    MixedData value;
};

// Exported function to generate report data
extern "C" __declspec(dllexport) void GenerateReport(int* totalItems, VariantRecord** resultArray) {
    // Prepare internal data using boost::variant
    std::vector<boost::variant<int, std::string>> rawData = {
        789, "Foo", 101, "Bar"
    };

    *totalItems = static_cast<int>(rawData.size());
    *resultArray = new VariantRecord[rawData.size()];

    for (size_t index = 0; index < rawData.size(); ++index) {
        if (rawData[index].which() == 0) {
            (*resultArray)[index].kind = 0;
            (*resultArray)[index].value.integerVal = boost::get<int>(rawData[index]);
        } else if (rawData[index].which() == 1) {
            (*resultArray)[index].kind = 1;
            std::string tempStr = boost::get<std::string>(rawData[index]);
            (*resultArray)[index].value.textVal = new char[tempStr.length() + 1];
            std::strcpy((*resultArray)[index].value.textVal, tempStr.c_str());
        }
    }
}

// Exported function to release allocated memory
extern "C" __declspec(dllexport) void ReleaseReport(int itemCount, VariantRecord* resultArray) {
    for (int i = 0; i < itemCount; ++i) {
        if (resultArray[i].kind == 1 && resultArray[i].value.textVal != nullptr) {
            delete[] resultArray[i].value.textVal;
            resultArray[i].value.textVal = nullptr;
        }
    }
    delete[] resultArray;
}

