#include <iostream>
#include <stack>
#include <sstream>
#include <cctype>
#include <cmath>

// Function to perform arithmetic operations
int compute(int operand1, int operand2, char operation) {
    switch (operation) {
        case '+': return operand1 + operand2;
        case '-': return operand1 - operand2;
        case '*': return operand1 * operand2;
        case '/': return operand1 / operand2;
        case '^': return static_cast<int>(std::pow(operand1, operand2));
    }
    return 0;
}

// Determine operator precedence level
int getPrecedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    if (op == '^') return 3;
    return 0;
}

// Evaluate arithmetic expression with proper operator precedence
int calculateExpression(std::string expr) {
    std::stack<int> numbers;
    std::stack<char> operators;
    std::istringstream stream(expr);
    std::string currentToken;

    while (stream >> currentToken) {
        // Check if token is a number (first character is digit)
        if (std::isdigit(currentToken[0])) {
            numbers.push(std::stoi(currentToken));
        } 
        // Handle opening parenthesis
        else if (currentToken == "(") {
            operators.push('(');
        } 
        // Handle closing parenthesis
        else if (currentToken == ")") {
            while (!operators.empty() && operators.top() != '(') {
                int second = numbers.top(); numbers.pop();
                int first = numbers.top(); numbers.pop();
                char op = operators.top(); operators.pop();
                numbers.push(compute(first, second, op));
            }
            if (!operators.empty()) {
                operators.pop(); // Remove the '('
            }
        } 
        // Handle operators
        else {
            char currentOp = currentToken[0];
            while (!operators.empty() && 
                   getPrecedence(operators.top()) >= getPrecedence(currentOp)) {
                int second = numbers.top(); numbers.pop();
                int first = numbers.top(); numbers.pop();
                char op = operators.top(); operators.pop();
                numbers.push(compute(first, second, op));
            }
            operators.push(currentOp);
        }
    }

    // Process remaining operators
    while (!operators.empty()) {
        int second = numbers.top(); numbers.pop();
        int first = numbers.top(); numbers.pop();
        char op = operators.top(); operators.pop();
        numbers.push(compute(first, second, op));
    }

    return numbers.top();
}

int main() {
    std::string mathExpression = "1 + 2 * (3 + 4) - 5";
    std::cout << "Result: " << calculateExpression(mathExpression) << std::endl;
    return 0;
}

