// Split a string by a given delimiter character
std::vector<std::string> splitString(const std::string& input, char sep) {
    std::vector<std::string> result;
    std::string current;

    for (size_t i = 0; i < input.length(); ++i) {
        if (input[i] == sep) {
            if (!current.empty() || i > 0) {
                result.push_back(current);
                current.clear();
            }
        } else {
            current += input[i];
        }
    }

    // Add the last token if exists
    if (!current.empty()) {
        result.push_back(current);
    }

    return result;
}

