#include <string>
#include <vector>

std::vector<std::string> extractIntegers(const std::string& text) {
    std::regex digitPattern("\\d+");
    std::vector<std::string> result;

    auto begin = std::sregex_iterator(text.begin(), text.end(), digitPattern);
    auto end = std::sregex_iterator();

    for (auto iter = begin; iter != end; ++iter) {
        std::smatch match = *iter;
        std::string currentNumber = match.str();
        size_t startPos = match.position();
        size_t endPos = startPos + currentNumber.length();

        bool isValid = true;

        // Check character before the number
        if (startPos > 0) {
            char prevChar = text[startPos - 1];
            if (prevChar == '.' || prevChar == ',') {
                isValid = false;
            }
        }

        // Check character after the number
        if (endPos < text.length()) {
            char nextChar = text[endPos];
            if (nextChar == '.' || nextChar == ',') {
                isValid = false;
            }
        }

        if (isValid) {
            result.push_back(currentNumber);
        }
    }

    return result;
}

