#include <opencv2/opencv.hpp>

// Constants
constexpr double PI_VAL = 3.14159265358979323846;
constexpr int MAX_KSIZE = 31;

// Generate normalized 1D Gaussian kernel
void CreateGaussianKernel1D(double* kernel, int size, double stddev) {
    int radius = size / 2;
    double total = 0.0;

    for (int offset = -radius; offset <= radius; ++offset) {
        int pos = offset + radius;
        double exponent = -0.5 * (offset * offset) / (stddev * stddev);
        kernel[pos] = std::exp(exponent) / (std::sqrt(2.0 * PI_VAL) * stddev);
        total += kernel[pos];
    }

    // Normalize so that kernel sums to 1
    for (int i = 0; i < size; ++i) {
        kernel[i] /= total;
    }
}

// Apply 1D Gaussian convolution along rows or columns (with mirrored borders)
void ConvolveWithGaussian1D(const cv::Mat& input, cv::Mat& output, int kernelSize, const double* kernel) {
    int halfWidth = kernelSize / 2;

    for (int row = 0; row < input.rows; ++row) {
        for (int col = 0; col < input.cols; ++col) {
            double accumB = 0.0, accumG = 0.0, accumR = 0.0;

            for (int dx = -halfWidth; dx <= halfWidth; ++dx) {
                int srcCol = col + dx;

                // Mirror boundary handling
                if (srcCol < 0) {
                    srcCol = -srcCol;
                } else if (srcCol >= input.cols) {
                    srcCol = input.cols - 1 - (srcCol - input.cols);
                }

                double weight = kernel[dx + halfWidth];

                if (input.channels() == 3) {
                    cv::Vec3b pixel = input.at<cv::Vec3b>(row, srcCol);
                    accumB += weight * static_cast<double>(pixel[0]);
                    accumG += weight * static_cast<double>(pixel[1]);
                    accumR += weight * static_cast<double>(pixel[2]);
                } else {
                    accumB += weight * static_cast<double>(input.at<uchar>(row, srcCol));
                }
            }

            if (input.channels() == 3) {
                cv::Vec3b result{
                    static_cast<uchar>(std::max(0.0, std::min(255.0, accumB))),
                    static_cast<uchar>(std::max(0.0, std::min(255.0, accumG))),
                    static_cast<uchar>(std::max(0.0, std::min(255.0, accumR)))
                };
                output.at<cv::Vec3b>(row, col) = result;
            } else {
                output.at<uchar>(row, col) = static_cast<uchar>(
                    std::max(0.0, std::min(255.0, accumB))
                );
            }
        }
    }
}

// Perform separable 2D Gaussian blur using two 1D passes
void GaussianBlurSeparable(const cv::Mat& src, cv::Mat& dst, int ksize, double sigma) {
    if (ksize > MAX_KSIZE || ksize <= 0) {
        std::cerr << "Invalid kernel size: must be between 1 and " << MAX_KSIZE << std::endl;
        return;
    }

    auto start = std::clock();

    // Allocate and populate kernel
    double* gaussianKernel = new double[ksize];
    CreateGaussianKernel1D(gaussianKernel, ksize, sigma);

    cv::Mat intermediate;
    src.copyTo(intermediate);

    // First pass: horizontal convolution
    ConvolveWithGaussian1D(src, dst, ksize, gaussianKernel);

    // Second pass: vertical convolution via transpose trick
    cv::transpose(dst, intermediate);
    cv::transpose(src, dst); // reuse dst as temporary storage

    ConvolveWithGaussian1D(intermediate, dst, ksize, gaussianKernel);
    cv::transpose(dst, intermediate);

    // Cleanup
    delete[] gaussianKernel;

    auto end = std::clock();
    std::cout << "Separable Gaussian blur time: " << (end - start) / CLOCKS_PER_SEC << " seconds" << std::endl;
}

