#include <OgreVector3.h>
#include <OgreEntity.h>

// Convert a vector from source entity's local space to destination entity's local space
Ogre::Vector3 TFormVector(const Ogre::Vector3& inputVec, const Ogre::Entity* srcNode, const Ogre::Entity* dstNode) {
    // Handle null entities by falling back to world space operations
    Ogre::Vector3 result = inputVec;

    // Apply source transformation if available
    if (srcNode != nullptr) {
        const Ogre::Node* srcParent = srcNode->getParentNode();
        if (srcParent != nullptr) {
            Ogre::Matrix4 srcMatrix = srcParent->_getFullTransform();
            result = srcMatrix * result;
        }
    }

    // Apply inverse destination transformation if available
    if (dstNode != nullptr) {
        const Ogre::Node* dstParent = dstNode->getParentNode();
        if (dstParent != nullptr) {
            Ogre::Matrix4 dstMatrix = dstParent->_getFullTransform().inverse();
            result = dstMatrix * result;
        }
    }

    return result;
}

