// Determine if AVX-512 is available on the current CPU
bool has_avx512_support() {
    // Use CPUID leaf 7 to check for AVX-512 Foundation (F) support
    return (std::get_cpuid(7).ebx & (1 << 16)) != 0;
}

// AVX-2 based population count using lookup table approach
uint64_t bit_count_AVX2(const uint8_t* buffer, const size_t len) {
    const __m256i nibble_table = _mm256_setr_epi8(
        0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4,
        0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4
    );
    const __m256i low_nibble_mask = _mm256_set1_epi8(0x0f);
    __m256i global_sum = _mm256_setzero_si256();

    #define PROCESS_BLOCK { \
        const __m256i input = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(buffer + idx)); \
        const __m256i lower = _mm256_and_si256(input, low_nibble_mask); \
        const __m256i upper = _mm256_and_si256(_mm256_srli_epi16(input, 4), low_nibble_mask); \
        const __m256i cnt_lo = _mm256_shuffle_epi8(nibble_table, lower); \
        const __m256i cnt_hi = _mm256_shuffle_epi8(nibble_table, upper); \
        temp_acc = _mm256_add_epi8(temp_acc, cnt_lo); \
        temp_acc = _mm256_add_epi8(temp_acc, cnt_hi); \
        idx += 32; \
    }

    size_t idx = 0;
    while (idx + 8 * 32 <= len) {
        __m256i temp_acc = _mm256_setzero_si256();
        PROCESS_BLOCK PROCESS_BLOCK PROCESS_BLOCK PROCESS_BLOCK
        PROCESS_BLOCK PROCESS_BLOCK PROCESS_BLOCK PROCESS_BLOCK
        global_sum = _mm256_add_epi64(global_sum, _mm256_sad_epu8(temp_acc, _mm256_setzero_si256()));
    }

    __m256i temp_acc = _mm256_setzero_si256();
    while (idx + 32 <= len) {
        PROCESS_BLOCK;
    }

    global_sum = _mm256_add_epi64(global_sum, _mm256_sad_epu8(temp_acc, _mm256_setzero_si256()));

    #undef PROCESS_BLOCK

    uint64_t total = 0;
    total += static_cast<uint64_t>(_mm256_extract_epi64(global_sum, 0));
    total += static_cast<uint64_t>(_mm256_extract_epi64(global_sum, 1));
    total += static_cast<uint64_t>(_mm256_extract_epi64(global_sum, 2));
    total += static_cast<uint64_t>(_mm256_extract_epi64(global_sum, 3));

    // Handle remaining bytes with scalar popcount
    for (; idx < len; ++idx) {
        total += __builtin_popcount(static_cast<unsigned>(buffer[idx]));
    }

    return total;
}

// AVX-512 optimized population count using native instruction
uint64_t bit_count_AVX512(const uint8_t* buffer, const size_t length) {
    const size_t full_blocks = length / 64;
    const uint8_t* limit = buffer + length;

    __m512i running_total = _mm512_setzero_si512();
    for (size_t block = 0; block < full_blocks; ++block, buffer += 64) {
        const __m512i chunk = _mm512_loadu_si512(reinterpret_cast<const __m512i*>(buffer));
        const __m512i counts = _mm512_popcnt_epi64(chunk);
        running_total = _mm512_add_epi64(running_total, counts);
    }

    alignas(64) uint64_t lane_counts[8];
    _mm512_store_si512(reinterpret_cast<__m512i*>(lane_counts), running_total);

    uint64_t sum = 0;
    for (int i = 0; i < 8; ++i) {
        sum += lane_counts[i];
    }

    // Process remaining 8-byte chunks
    while (buffer + 8 <= limit) {
        sum += _mm_popcnt_u64(*reinterpret_cast<const uint64_t*>(buffer));
        buffer += 8;
    }

    // Handle final leftover bytes
    while (buffer < limit) {
        sum += __builtin_popcount(*buffer++);
    }

    return sum;
}

// Public interface: automatically selects best available implementation
uint64_t count_ones(void* mem, size_t bytes) {
    if (has_avx512_support()) {
        return bit_count_AVX512(static_cast<const uint8_t*>(mem), bytes);
    } else {
        return bit_count_AVX2(static_cast<const uint8_t*>(mem), bytes);
    }
}

