using namespace std;

const int MAX_DIST = numeric_limits<int>::max();

// Custom comparator for min-heap based on distance
struct DistanceGreater {
    bool operator()(const pair<int, int>& left, const pair<int, int>& right) const {
        return left.second > right.second;
    }
};

// Modified Dijkstra's algorithm to find shortest path
vector<int> findShortestRoute(const vector<vector<pair<int, int>>>& adjacencyList, int source, int destination) {
    int nodeCount = adjacencyList.size();
    vector<int> distances(nodeCount, MAX_DIST);
    vector<int> predecessors(nodeCount, -1);

    // Priority queue: (distance, node)
    priority_queue<pair<int, int>, vector<pair<int, int>>, DistanceGreater> frontier;

    distances[source] = 0;
    frontier.emplace(source, 0);

    while (!frontier.empty()) {
        auto [currentNode, currentDist] = frontier.top();
        frontier.pop();

        // Skip if we've already found a better path
        if (currentDist > distances[currentNode]) continue;

        // Explore all neighbors
        for (const auto& edge : adjacencyList[currentNode]) {
            int nextNode = edge.first;
            int edgeWeight = edge.second;

            int newDistance = distances[currentNode] + edgeWeight;
            if (newDistance < distances[nextNode]) {
                distances[nextNode] = newDistance;
                predecessors[nextNode] = currentNode;
                frontier.emplace(nextNode, newDistance);
            }
        }
    }

    // Reconstruct the path from destination to source
    vector<int> route;
    for (int node = destination; node != -1; node = predecessors[node]) {
        route.push_back(node);
    }
    reverse(route.begin(), route.end());

    return route;
}

int main() {
    // Graph representation using adjacency list
    // Nodes are labeled 0 through 4
    vector<vector<pair<int, int>>> cityNetwork = {
        {{1, 10}, {2, 5}},   // Connections from city 0
        {{2, 2},  {3, 1}},   // Connections from city 1
        {{3, 4}},            // Connections from city 2
        {{4, 7}},            // Connections from city 3
        {}                   // City 4 has no outgoing connections
    };

    int origin = 0;
    int destination = 4;

    vector<int> optimalPath = findShortestRoute(cityNetwork, origin, destination);

    if (optimalPath.empty()) {
        cout << "No route exists from city " << origin << " to city " << destination << endl;
    } else {
        cout << "Optimal route from city " << origin << " to city " << destination << ": ";
        for (int city : optimalPath) {
            cout << city << " ";
        }
        cout << endl;
    }

    return 0;
}

