bool isVowel(char c) {
    c = std::tolower(static_cast<unsigned char>(c));
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
}

// Create a new string without vowels from the input
std::string filterOutVowels(const std::string& source) {
    std::string filtered;
    for (size_t i = 0; i < source.length(); ++i) {
        if (!isVowel(source[i])) {
            filtered += source[i];
        }
    }
    return filtered;
}

