public ref class MyWrapper
{
public:
    static Result Foo([Out] IntPtr% session, ObjectCallback callback, UInt64 turnKey, String^ serverAddress, String^ userId, String^ password)
    {
        // Pin managed strings to prevent garbage collection during conversion
        cli::pin_ptr<const wchar_t> wServer = PtrToStringChars(serverAddress);
        cli::pin_ptr<const wchar_t> wUser = PtrToStringChars(userId);
        cli::pin_ptr<const wchar_t> wPass = PtrToStringChars(password);

        // Convert wide character strings to UTF-8 C-style strings
        const char* utf8Server = ToUtf8(wServer);
        const char* utf8User = ToUtf8(wUser);
        const char* utf8Pass = ToUtf8(wPass);

        // Call the native function
        Result result = xcFoo(&session, callback, turnKey, utf8Server, utf8User, utf8Pass);

        // Clean up allocated memory for converted strings
        delete[] utf8Server;
        delete[] utf8User;
        delete[] utf8Pass;

        return result;
    }

private:
    static const char* ToUtf8(const wchar_t* wideStr)
    {
        // Determine required buffer size for UTF-8 conversion
        int bufSize = WideCharToMultiByte(CP_UTF8, 0, wideStr, -1, nullptr, 0, nullptr, nullptr);

        // Allocate buffer for UTF-8 string (+1 for null terminator)
        char* utf8Buffer = new char[bufSize];

        // Perform actual conversion
        WideCharToMultiByte(CP_UTF8, 0, wideStr, -1, utf8Buffer, bufSize, nullptr, nullptr);

        return utf8Buffer;
    }
};

