// Atomically acquire a lock by spinning until it becomes zero
static inline void testAcquireLock(volatile unsigned int *lock) {
    unsigned int acquired = 0;
    unsigned int attempt = 1;

    __asm__ volatile(
        "spin%=:                          \n\t" // "%=" creates unique label
        "LDREX %[acq], [%[lk]]            \n\t" // load lock value exclusively
        "CMP %[acq], #0                   \n\t" // check if lock is free (0)
        "ITT EQ                           \n\t" // enable conditional execution
        "STREXEQ %[acq], %[att], [%[lk]]  \n\t" // try to store 1 if lock was 0
        "CMPEQ %[acq], #0                 \n\t" // verify store succeeded
        "BNE spin%=                       \n\t" // retry if store failed or lock not free
        "DMB                              \n\t" // memory barrier after acquiring
        : [lk] "+m"(*lock), [acq] "=l"(acquired), [att] "=l"(attempt)
        :
        : "memory");
}

