    unsigned char program[] = {
        0x48, 0xc7, 0xc0, 0x01, 0x00, 0x00, 0x00,  // mov rax, 1 (sys_write)
        0x48, 0xc7, 0xc7, 0x01, 0x00, 0x00, 0x00,  // mov rdi, 1 (stdout fd)
        0x48, 0xc7, 0xc6, 0x01, 0x00, 0x00, 0x00,  // mov rsi, &message
        0x48, 0xc7, 0xc2, 0x01, 0x00, 0x00, 0x00,  // mov rdx, 1 (length)
        0x0f, 0x05,                                // syscall
        0x48, 0xc7, 0xc0, 0x3c, 0x00, 0x00, 0x00,  // mov rax, 60 (sys_exit)
        0x48, 0x31, 0xff,                          // xor rdi, rdi (exit code 0)
        0x0f, 0x05                                 // syscall
    };

    size_t code_size = sizeof(program);
    void *exec_mem = create_executable_region(code_size);
    if (!exec_mem) {
        return 1;
    }

    inject_bytes_into_region(code_size, program, exec_mem);
    ExecutableRoutine run_code = reinterpret_cast<ExecutableRoutine>(exec_mem);
    run_code();

    return 0;
}

#include "ComponentManager.h"

void ComponentManager::TransferComponentData(size_t compTypeId, Archetype* sourceArchetype, Archetype* destinationArchetype, size_t sourceIndex, size_t destIndex, size_t entityPosition) {
    MoveComponentData(compTypeId, sourceArchetype, destinationArchetype, sourceIndex, destIndex, entityPosition, destinationArchetype->entityIds.size());
}

void ComponentManager::SwapComponentData(size_t compTypeId, Archetype* archetype, size_t targetIndex, size_t entityIndex) {
    const size_t finalEntity = archetype->entityIds.size() - 1;

    MoveComponentData(compTypeId, archetype, archetype, targetIndex, targetIndex, finalEntity, entityIndex);
}

void ComponentManager::RemoveAndAllocateComponentData(size_t compTypeId, Archetype* sourceArchetype, Archetype* destinationArchetype, size_t sourceIndex, size_t destIndex, size_t entityIndex) {
    const ComponentBase* componentInfo = GetComponentBase(compTypeId);
    const std::size_t componentByteSize = componentInfo->GetSize();

    size_t currentCapacity = FindCurrentSize(compTypeId, destinationArchetype, destIndex);

    const size_t lastEntity = sourceArchetype->entityIds.size() - 1;

    // Transfer data from source to destination
    componentInfo->MoveData(&sourceArchetype->componentData[sourceIndex][entityIndex * componentByteSize],
        &destinationArchetype->componentData[destIndex][currentCapacity]);

    // If not moving the last element, move the last element to the position being vacated
    if (entityIndex != lastEntity) {
        componentInfo->MoveData(&sourceArchetype->componentData[sourceIndex][lastEntity * componentByteSize],
            &sourceArchetype->componentData[sourceIndex][entityIndex * componentByteSize]);
    }

    // Clean up the now-empty slot at the end
    componentInfo->DestroyData(&sourceArchetype->componentData[sourceIndex][lastEntity * componentByteSize]);
}

size_t ComponentManager::FindCurrentSize(size_t compTypeId, Archetype* archetype, size_t slotIndex) {
    const ComponentBase* componentInfo = GetComponentBase(compTypeId);
    const std::size_t& componentSize = componentInfo->GetSize();

    std::size_t totalBytes = archetype->entityIds.size() * componentSize;
    std::size_t requiredBytes = totalBytes + componentSize;

    // Expand storage if necessary
    if (requiredBytes > archetype->componentDataSize[slotIndex]) {
        ExpandMemory(compTypeId, componentSize, archetype, slotIndex);
    }

    return totalBytes;
}

void ComponentManager::ExpandMemory(size_t compTypeId, const size_t componentSize, Archetype* archetype, size_t slotIndex) {
    const ComponentBase* componentInfo = GetComponentBase(compTypeId);
    const std::size_t baseComponentSize = componentInfo->GetSize();

    // Double the allocated capacity and add extra space
    archetype->componentDataSize[slotIndex] *= 2;
    archetype->componentDataSize[slotIndex] += componentSize;

    unsigned char* newStorage = new unsigned char[archetype->componentDataSize[slotIndex]];

    // Copy all existing components to the new memory block
    for (auto i = 0; i < archetype->entityIds.size(); ++i) {
        componentInfo->MoveData(&archetype->componentData[slotIndex][i * baseComponentSize],
            &newStorage[i * baseComponentSize]);
        componentInfo->DestroyData(&archetype->componentData[slotIndex][i * baseComponentSize]);
    }

    delete[] archetype->componentData[slotIndex];
    archetype->componentData[slotIndex] = newStorage;
}

void ComponentManager::MoveComponentData(size_t compTypeId, Archetype* sourceArchetype, Archetype* destArchetype, size_t sourceIndex, size_t destIndex, size_t sourceEntityPos, size_t destEntityPos) {
    const ComponentBase* componentInfo = GetComponentBase(compTypeId);
    const std::size_t componentByteSize = componentInfo->GetSize();

    componentInfo->MoveData(&sourceArchetype->componentData[sourceIndex][sourceEntityPos * componentByteSize],
        &destArchetype->componentData[destIndex][destEntityPos * componentByteSize]);

    componentInfo->DestroyData(&sourceArchetype->componentData[sourceIndex][sourceEntityPos * componentByteSize]);
}

