using namespace std;

// Determine operator priority level
int getPriority(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Transform infix notation to postfix notation
string convertToPostfix(string inputExpr) {
    stack<char> operatorStack;
    string result = "";

    for (int i = 0; i < inputExpr.length(); ++i) {
        char currentChar = inputExpr[i];

        if (isalpha(currentChar) || isdigit(currentChar)) {
            // Operand: append directly to result
            result += currentChar;
        } else if (currentChar == '(') {
            // Opening parenthesis: push to stack
            operatorStack.push(currentChar);
        } else if (currentChar == ')') {
            // Closing parenthesis: pop until matching opening parenthesis
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                result += operatorStack.top();
                operatorStack.pop();
            }
            if (!operatorStack.empty()) {
                operatorStack.pop(); // Remove the opening parenthesis
            }
        } else {
            // Operator: handle precedence
            while (!operatorStack.empty() && 
                   getPriority(operatorStack.top()) >= getPriority(currentChar)) {
                result += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(currentChar);
        }
    }

    // Append any remaining operators in the stack
    while (!operatorStack.empty()) {
        result += operatorStack.top();
        operatorStack.pop();
    }

    return result;
}

int main() {
    string expression;
    cout << "Enter an infix expression: ";
    cin >> expression;

    string output = convertToPostfix(expression);
    cout << "Postfix expression: " << output << endl;

    return 0;
}

