std::string fizzBuzz(int n) {
    bool divisibleBy3 = (n % 3 == 0);
    bool divisibleBy5 = (n % 5 == 0);

    if (divisibleBy3 && divisibleBy5) {
        return "FizzBuzz";
    } else if (divisibleBy3) {
        return "Fizz";
    } else if (divisibleBy5) {
        return "Buzz";
    } else {
        return std::to_string(n);
    }
}

