using namespace std;

// Count palindromic substrings using dynamic programming
int countPalindromicSubstrings(const string& input) {
    int length = input.length();
    vector<vector<bool>> isPalindrome(length, vector<bool>(length, false));
    int total = 0;

    // Check all possible substring lengths
    for (int subLen = 1; subLen <= length; ++subLen) {
        for (int start = 0; start <= length - subLen; ++start) {
            int end = start + subLen - 1;

            if (subLen == 1) {
                isPalindrome[start][end] = true;
            } else if (subLen == 2) {
                isPalindrome[start][end] = (input[start] == input[end]);
            } else {
                isPalindrome[start][end] = (input[start] == input[end]) && isPalindrome[start + 1][end - 1];
            }

            if (isPalindrome[start][end]) {
                total++;
            }
        }
    }

    return total;
}

int main() {
    string text;
    cout << "Enter a string: ";
    cin >> text;
    int palindromes = countPalindromicSubstrings(text);
    cout << "Number of palindromic substrings: " << palindromes << endl;
    return 0;
}

