// Global variable for the edit control handle
HWND g_hInputField = NULL;

// Custom window procedure to handle messages
LRESULT CALLBACK MainWndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_CREATE:
        {
            // Create a child edit control with auto-scrolling
            g_hInputField = CreateWindowEx(0, TEXT("EDIT"), TEXT(""),
                                           WS_CHILD | WS_VISIBLE | ES_AUTOHSCROLL,
                                           20, 20, 250, 30,
                                           hwnd, (HMENU)1001,
                                           (HINSTANCE)GetWindowLongPtr(hwnd, GWLP_HINSTANCE),
                                           NULL);
        }
        break;

    case WM_COMMAND:
        {
            WORD id = LOWORD(wParam);
            WORD notification = HIWORD(wParam);

            // Check if the edit control content changed
            if (id == 1001 && notification == EN_CHANGE)
            {
                char textBuffer[512];
                GetWindowTextA(g_hInputField, textBuffer, sizeof(textBuffer));
                MessageBoxA(hwnd, textBuffer, "Input Updated", MB_OK | MB_ICONINFORMATION);
            }
        }
        break;

    case WM_CLOSE:
    case WM_DESTROY:
        PostQuitMessage(0);
        return 0;

    default:
        return DefWindowProcW(hwnd, message, wParam, lParam);
    }

    return 0;
}

// Entry point for Windows GUI application
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd)
{
    WNDCLASSEX wcex = {0};
    wcex.cbSize        = sizeof(WNDCLASSEX);
    wcex.style         = CS_HREDRAW | CS_VREDRAW;
    wcex.lpfnWndProc   = MainWndProc;
    wcex.cbClsExtra    = 0;
    wcex.cbWndExtra    = 0;
    wcex.hInstance     = hInstance;
    wcex.hIcon         = LoadIconW(NULL, IDI_APPLICATION);
    wcex.hCursor       = LoadCursorW(NULL, IDC_ARROW);
    wcex.hbrBackground = (HBRUSH)(COLOR_BTNFACE + 1);
    wcex.lpszMenuName  = NULL;
    wcex.lpszClassName = L"SampleAppClass";
    wcex.hIconSm       = LoadIconW(NULL, IDI_APPLICATION);

    if (!RegisterClassExW(&wcex))
    {
        MessageBoxW(NULL, L"Failed to register window class.", L"Error", MB_ICONERROR | MB_OK);
        return 1;
    }

    HWND hWnd = CreateWindowExW(0, L"SampleAppClass", L"Windows Input Monitor",
                                WS_OVERLAPPEDWINDOW,
                                CW_USEDEFAULT, 0, CW_USEDEFAULT, 0,
                                NULL, NULL, hInstance, NULL);

    if (!hWnd)
    {
        MessageBoxW(NULL, L"Failed to create main window.", L"Error", MB_ICONERROR | MB_OK);
        return 1;
    }

    ShowWindow(hWnd, nShowCmd);
    UpdateWindow(hWnd);

    // Message loop
    MSG message;
    while (GetMessageW(&message, NULL, 0, 0))
    {
        TranslateMessage(&message);
        DispatchMessageW(&message);
    }

    return (int)message.wParam;
}

