// Functor to extract minimum value and its global index from a column
struct min_with_index_functor
{
    int num_rows;

    min_with_index_functor(int n) : num_rows(n) {}

    __host__ __device__
    thrust::tuple<int, int> operator()(const thrust::tuple<int, int>& a, const thrust::tuple<int, int>& b)
    {
        if (thrust::get<0>(a) <= thrust::get<0>(b))
            return a;
        else
            return b;
    }
};

int main()
{
    // Input vectors
    thrust::host_vector<int> h_vec1 = {3, 6, 9};
    thrust::host_vector<int> h_vec2 = {1, 5, 7};
    thrust::host_vector<int> h_vec3 = {2, 4, 8};

    // Calculate dimensions
    int num_cols = h_vec1.size();
    int num_rows = 3; // Since we have 3 input vectors

    // Create flattened device vector directly
    thrust::device_vector<int> d_data(num_rows * num_cols);

    // Fill data in column-major order for easier column access
    auto fill_func = [num_cols, num_rows] __host__ __device__ (int idx, int val) {
        int row = idx / num_cols;
        int col = idx % num_cols;
        return val;
    };

    // Transfer data with proper ordering
    for (int i = 0; i < num_rows; ++i) {
        for (int j = 0; j < num_cols; ++j) {
            if (i == 0) d_data[j * num_rows + i] = h_vec1[j];
            else if (i == 1) d_data[j * num_rows + i] = h_vec2[j];
            else d_data[j * num_rows + i] = h_vec3[j];
        }
    }

    // Prepare output containers
    thrust::device_vector<int> d_min_values(num_cols);
    thrust::device_vector<int> d_min_indices(num_cols);

    // Process each column independently using transform
    auto process_column = [d_data_ptr = thrust::raw_pointer_cast(d_data.data()), 
                          num_rows, num_cols] __host__ __device__ (int col_idx) {
        int min_val = d_data_ptr[col_idx * num_rows];
        int min_idx = 0;

        for (int row = 1; row < num_rows; ++row) {
            int current_val = d_data_ptr[col_idx * num_rows + row];
            if (current_val < min_val) {
                min_val = current_val;
                min_idx = row;
            }
        }

        return thrust::make_tuple(min_idx, min_val);
    };

    thrust::device_vector<thrust::tuple<int, int>> d_results(num_cols);
    thrust::transform(thrust::counting_iterator<int>(0),
                     thrust::counting_iterator<int>(num_cols),
                     d_results.begin(),
                     process_column);

    // Copy results back to host
    thrust::host_vector<thrust::tuple<int, int>> h_results = d_results;

    // Print results
    for (int i = 0; i < num_cols; ++i) {
        std::cout << "Column " << i << ": Min value = " << thrust::get<1>(h_results[i]) 
                  << ", Index = " << thrust::get<0>(h_results[i]) << std::endl;
    }

    return 0;
}

