#include <cuda_runtime.h>
#include <iostream>

// Define constants for block size and kernel parameters
#define TILE_DIM 16
#define FILTER_SIZE 3
#define HALF_FILTER (FILTER_SIZE / 2)

// Constant memory for the Laplacian edge detection kernel
__constant__ float filter_coeffs[FILTER_SIZE * FILTER_SIZE] = {
    0, -1, 0,
    -1, 4, -1,
    0, -1, 0
};

// CUDA kernel for 2D convolution with shared memory tiling
__global__ void apply_filter(const float* src, float* dst, int img_width, int img_height) {
    // Shared memory buffer with halo region for boundary handling
    __shared__ float tile[TILE_DIM + 2 * HALF_FILTER][TILE_DIM + 2 * HALF_FILTER];

    int grid_x = blockIdx.x;
    int grid_y = blockIdx.y;
    int thread_x = threadIdx.x;
    int thread_y = threadIdx.y;

    // Compute global coordinates in the image
    int y_global = grid_y * TILE_DIM + thread_y;
    int x_global = grid_x * TILE_DIM + thread_x;

    // Load central region into shared memory
    if (y_global < img_height && x_global < img_width) {
        tile[thread_y + HALF_FILTER][thread_x + HALF_FILTER] = src[y_global * img_width + x_global];
    }

    // Handle top and bottom boundaries (vertical padding)
    if (y_global < HALF_FILTER) {
        tile[thread_y][thread_x + HALF_FILTER] = (y_global == 0) ? 0.0f : src[(y_global - 1) * img_width + x_global];
    }
    if (y_global >= img_height - HALF_FILTER) {
        tile[thread_y + 2 * HALF_FILTER][thread_x + HALF_FILTER] = (y_global == img_height - 1) ? 0.0f : src[(y_global + 1) * img_width + x_global];
    }

    // Handle left and right boundaries (horizontal padding)
    if (x_global < HALF_FILTER) {
        tile[thread_y + HALF_FILTER][thread_x] = (x_global == 0) ? 0.0f : src[y_global * img_width + (x_global - 1)];
    }
    if (x_global >= img_width - HALF_FILTER) {
        tile[thread_y + HALF_FILTER][thread_x + 2 * HALF_FILTER] = (x_global == img_width - 1) ? 0.0f : src[y_global * img_width + (x_global + 1)];
    }

    // Ensure all threads have loaded data before computation
    __syncthreads();

    // Perform convolution using shared memory
    float result = 0.0f;
    for (int ky = 0; ky < FILTER_SIZE; ++ky) {
        for (int kx = 0; kx < FILTER_SIZE; ++kx) {
            result += tile[thread_y + HALF_FILTER + ky - HALF_FILTER][thread_x + HALF_FILTER + kx - HALF_FILTER] *
                      filter_coeffs[ky * FILTER_SIZE + kx];
        }
    }

    // Store result to global memory if within bounds
    if (y_global < img_height && x_global < img_width) {
        dst[y_global * img_width + x_global] = result;
    }
}

int main() {
    const int width = 500;
    const int height = 500;
    const int total_elements = width * height;
    const size_t bytes = total_elements * sizeof(float);

    // Allocate host memory
    float* h_data_in = new float[total_elements];
    float* h_data_out = new float[total_elements];

    // Allocate device memory
    float* d_data_in;
    float* d_data_out;
    cudaMalloc(&d_data_in, bytes);
    cudaMalloc(&d_data_out, bytes);

    // Initialize input data with constant value
    for (int idx = 0; idx < total_elements; ++idx) {
        h_data_in[idx] = 1.0f;
    }

    // Copy input data to device
    cudaMemcpy(d_data_in, h_data_in, bytes, cudaMemcpyHostToDevice);

    // Configure execution configuration
    dim3 threads_per_block(TILE_DIM, TILE_DIM);
    dim3 num_blocks((width + TILE_DIM - 1) / TILE_DIM, (height + TILE_DIM - 1) / TILE_DIM);

    // Launch kernel
    apply_filter<<<num_blocks, threads_per_block>>>(d_data_in, d_data_out, width, height);

    // Copy results back to host
    cudaMemcpy(h_data_out, d_data_out, bytes, cudaMemcpyDeviceToHost);

    // Cleanup resources
    cudaFree(d_data_in);
    cudaFree(d_data_out);
    delete[] h_data_in;
    delete[] h_data_out;

    return 0;
}

