#include <iostream>
#include <vector>
using namespace std;

// Generate Fibonacci sequence up to n elements
vector<int> generateFibonacci(int count) {
    vector<int> result;
    if (count <= 0) return result;

    result.push_back(0);
    if (count == 1) return result;

    result.push_back(1);

    int index = 2;
    while (index < count) {
        int nextValue = result[index - 1] + result[index - 2];
        result.push_back(nextValue);
        index++;
    }

