// Function to find the minimum and maximum values in a vector
std::pair<int, int> locateExtremes(const std::vector<int>& data) {
    if (data.empty()) {
        return {0, 0};  // Return zeros for empty input
    }

    int smallest = data[0];
    int largest = data[0];

    for (size_t idx = 0; idx < data.size(); ++idx) {
        int current = data[idx];
        if (current < smallest) {
            smallest = current;
        }
        if (current > largest) {
            largest = current;
        }
    }

    return {smallest, largest};
}

int main() {
    std::vector<int> numbers = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};
    auto [minValue, maxValue] = locateExtremes(numbers);
    std::cout << "Minimum: " << minValue << ", Maximum: " << maxValue << std::endl;
    return 0;
}

