    float val1 = 1.0f, val2 = 2.0f, val3 = 3.0f, val4 = 4.0f;
    float val5 = 5.0f, val6 = 6.0f, val7 = 7.0f, val8 = 8.0f;

    // Populate the aligned arrays with scalar values
    firstVec[0] = val1; firstVec[1] = val2; firstVec[2] = val3; firstVec[3] = val4;
    secondVec[0] = val5; secondVec[1] = val6; secondVec[2] = val7; secondVec[3] = val8;

    // Load 128-bit vectors from memory into SSE registers
    __m128 regA = _mm_load_ps(firstVec);
    __m128 regB = _mm_load_ps(secondVec);

    // Perform element-wise floating-point multiplication
    __m128 regResult = _mm_mul_ps(regA, regB);

    // Store the computed result back to memory
    _mm_store_ps(outputVec, regResult);

    // Output the resulting components
    std::cout << "Result: " << outputVec[0] << ", " << outputVec[1] << ", " 
              << outputVec[2] << ", " << outputVec[3] << std::endl;

