#include <iostream>
using namespace std;

// Node structure for singly linked list
struct SinglyNode {
    int value;
    SinglyNode* link;
};

// Node structure for doubly linked list
struct DoublyNode {
    int value;
    DoublyNode* forward;
    DoublyNode* backward;
};

// Allocate and initialize a new node for the singly linked list
SinglyNode* allocateSinglyNode(int val) {
    SinglyNode* node = new SinglyNode();
    node->value = val;
    node->link = nullptr;
    return node;
}

// Allocate and initialize a new node for the doubly linked list
DoublyNode* allocateDoublyNode(int val) {
    DoublyNode* node = new DoublyNode();
    node->value = val;
    node->forward = nullptr;
    node->backward = nullptr;
    return node;
}

// Transform a singly linked list into a doubly linked list
DoublyNode* transformToDoubly(SinglyNode* start) {
    if (start == nullptr) {
        return nullptr;
    }

    DoublyNode* doublyStart = nullptr;
    DoublyNode* traverseDoubly = nullptr;
    SinglyNode* traverseSingly = start;

    while (traverseSingly != nullptr) {
        DoublyNode* newNode = allocateDoublyNode(traverseSingly->value);

        if (doublyStart == nullptr) {
            doublyStart = newNode;
            traverseDoubly = newNode;
        } else {
            traverseDoubly->forward = newNode;
            newNode->backward = traverseDoubly;
            traverseDoubly = newNode;
        }

        traverseSingly = traverseSingly->link;
    }

    return doublyStart;
}

// Display the doubly linked list from head to tail
void displayForward(DoublyNode* start) {
    DoublyNode* current = start;
    while (current != nullptr) {
        cout << current->value << " ";
        current = current->forward;
    }
    cout << endl;
}

// Display the doubly linked list from tail to head
void displayBackward(DoublyNode* start) {
    if (start == nullptr) {
        return;
    }

    DoublyNode* current = start;
    while (current->forward != nullptr) {
        current = current->forward;
    }

    while (current != nullptr) {
        cout << current->value << " ";
        current = current->backward;
    }
    cout << endl;
}

int main() {
    // Build a singly linked list: 1 -> 2 -> 3 -> 4
    SinglyNode* head = allocateSinglyNode(1);
    head->link = allocateSinglyNode(2);
    head->link->link = allocateSinglyNode(3);
    head->link->link->link = allocateSinglyNode(4);

    // Convert to doubly linked list
    DoublyNode* doublyHead = transformToDoubly(head);

    // Output results
    cout << "Doubly Linked List: ";
    displayForward(doublyHead);

    cout << "Doubly Linked List in Reverse: ";
    displayBackward(doublyHead);

    return 0;
}

