// Helper function to compute the sum of squares of digits
int sumOfSquares(int n) {
    int result = 0;
    while (n > 0) {
        int digit = n % 10;
        result += digit * digit;
        n /= 10;
    }
    return result;
}

// Check if a number is happy using Floyd's cycle detection
bool isHappy(int n) {
    int slow = n;
    int fast = n;

    do {
        slow = sumOfSquares(slow);           // Move one step
        fast = sumOfSquares(sumOfSquares(fast)); // Move two steps
    } while (fast != 1 && slow != fast);

    return fast == 1;
}

int main() {
    int limit = 10000;
    for (int i = 1; i <= limit; ++i) {
        if (isHappy(i)) {
            std::cout << i << " ";
        }
    }
    std::cout << std::endl;
    return 0;
}

