using namespace std;
using namespace cv;

const int PORT_NUM = 50007;

int main() {
    // Create TCP socket for incoming connections
    int listeningSocket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);

    if (listeningSocket == -1) {
        cerr << "Failed to create socket" << endl;
        return 1;
    }

    // Prepare server address structure
    sockaddr_in serverAddress;
    memset(&serverAddress, 0, sizeof(serverAddress));
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(PORT_NUM);
    serverAddress.sin_addr.s_addr = INADDR_ANY;

    // Bind socket to address
    if (bind(listeningSocket, reinterpret_cast<sockaddr*>(&serverAddress), 
             sizeof(serverAddress)) == -1) {
        perror("Binding failed");
        close(listeningSocket);
        return 1;
    }

    // Start listening for connections
    if (listen(listeningSocket, 10) == -1) {
        perror("Listen failed");
        close(listeningSocket);
        return 1;
    }

    cout << "Server listening on port " << PORT_NUM << "..." << endl;

    // Accept incoming connection
    sockaddr_in clientAddress;
    socklen_t clientSize = sizeof(clientAddress);

    int connectionSocket = accept(listeningSocket, 
                                  reinterpret_cast<sockaddr*>(&clientAddress), 
                                  &clientSize);

    if (connectionSocket == -1) {
        perror("Accept failed");
        close(listeningSocket);
        return 1;
    }

    cout << "Client connected from " << inet_ntoa(clientAddress.sin_addr) << endl;

    // Read file size first
    char sizeData[64] = {0};
    ssize_t bytesReceived = recv(connectionSocket, sizeData, sizeof(sizeData)-1, 0);

    if (bytesReceived <= 0) {
        perror("Failed to receive file size");
        close(connectionSocket);
        close(listeningSocket);
        return 1;
    }

    long totalFileSize = stol(string(sizeData));
    cout << "Receiving file of size: " << totalFileSize << " bytes" << endl;

    // Open output file for writing
    FILE* fileWriter = fopen("received_image.jpg", "wb");
    if (!fileWriter) {
        perror("Failed to create output file");
        close(connectionSocket);
        close(listeningSocket);
        return 1;
    }

    // Receive file data in chunks
    long bytesReceivedSoFar = 0;
    const int CHUNK_SIZE = 2048;

    while (bytesReceivedSoFar < totalFileSize) {
        char chunk[CHUNK_SIZE];
        int remaining = totalFileSize - bytesReceivedSoFar;
        int currentChunkSize = min(CHUNK_SIZE, remaining);

        bytesReceived = recv(connectionSocket, chunk, currentChunkSize, 0);

        if (bytesReceived <= 0) {
            perror("Connection error during file transfer");
            fclose(fileWriter);
            close(connectionSocket);
            close(listeningSocket);
            return 1;
        }

        fwrite(chunk, 1, bytesReceived, fileWriter);
        bytesReceivedSoFar += bytesReceived;

        // Progress indicator
        cout << "\rProgress: " << (100 * bytesReceivedSoFar / totalFileSize) << "%";
        fflush(stdout);
    }

    fclose(fileWriter);
    cout << "\nFile received successfully!" << endl;

    // Cleanup
    close(connectionSocket);
    close(listeningSocket);

    return 0;
}

