// Main complex number class
class ComplexNumber {
private:
    RealComponent realPart;
    ImaginaryComponent imagPart;

public:
    ComplexNumber(const RealComponent& r, const ImaginaryComponent& i) 
        : realPart(r), imagPart(i) {}

    // Basic arithmetic
    ComplexNumber add(const ComplexNumber& other) const {
        return ComplexNumber(realPart.add(other.realPart), 
                            imagPart.add(other.imagPart));
    }

    ComplexNumber subtract(const ComplexNumber& other) const {
        return ComplexNumber(realPart.subtract(other.realPart), 
                            imagPart.subtract(other.imagPart));
    }

    ComplexNumber multiply(const ComplexNumber& other) const {
        double newReal = (realPart.retrieveValue() * other.realPart.retrieveValue()) - 
                        (imagPart.retrieveValue() * other.imagPart.retrieveValue());
        double newImag = (realPart.retrieveValue() * other.imagPart.retrieveValue()) + 
                        (imagPart.retrieveValue() * other.realPart.retrieveValue());
        return ComplexNumber(RealComponent(newReal), ImaginaryComponent(newImag));
    }

    ComplexNumber divide(const ComplexNumber& other) const {
        double denominator = (other.realPart.retrieveValue() * other.realPart.retrieveValue()) + 
                            (other.imagPart.retrieveValue() * other.imagPart.retrieveValue());
        double newReal = ((realPart.retrieveValue() * other.realPart.retrieveValue()) + 
                         (imagPart.retrieveValue() * other.imagPart.retrieveValue())) / denominator;
        double newImag = ((imagPart.retrieveValue() * other.realPart.retrieveValue()) - 
                         (realPart.retrieveValue() * other.imagPart.retrieveValue())) / denominator;
        return ComplexNumber(RealComponent(newReal), ImaginaryComponent(newImag));
    }

    // Advanced operations
    double magnitude() const {
        return std::sqrt((realPart.retrieveValue() * realPart.retrieveValue()) + 
                        (imagPart.retrieveValue() * imagPart.retrieveValue()));
    }

    ComplexNumber squareRoot() const {
        double mag = magnitude();
        double realVal = std::sqrt((realPart.retrieveValue() + mag) / 2.0);
        double imagVal = std::sqrt((-realPart.retrieveValue() + mag) / 2.0);
        return ComplexNumber(RealComponent(realVal), ImaginaryComponent(imagVal));
    }

    // Accessors
    RealComponent getReal() const {
        return realPart;
    }

    ImaginaryComponent getImaginary() const {
        return imagPart;
    }
};

int main() {
    // Create sample complex numbers
    RealComponent r1(2.5);
    RealComponent r2(3.7);
    ImaginaryComponent i1(1.2);
    ImaginaryComponent i2(0.8);

    ComplexNumber num1(r1, i1);
    ComplexNumber num2(r2, i2);

    // Perform calculations
    ComplexNumber resultSum = num1.add(num2);
    ComplexNumber resultDiff = num1.subtract(num2);
    ComplexNumber resultProd = num1.multiply(num2);
    ComplexNumber resultQuot = num1.divide(num2);

    // Output results
    std::cout << "Sum: " << resultSum.getReal().retrieveValue() << " + " 
              << resultSum.getImaginary().retrieveValue() << "i" << std::endl;
    std::cout << "Difference: " << resultDiff.getReal().retrieveValue() << " + " 
              << resultDiff.getImaginary().retrieveValue() << "i" << std::endl;
    std::cout << "Product: " << resultProd.getReal().retrieveValue() << " + " 
              << resultProd.getImaginary().retrieveValue() << "i" << std::endl;
    std::cout << "Quotient: " << resultQuot.getReal().retrieveValue() << " + " 
              << resultQuot.getImaginary().retrieveValue() << "i" << std::endl;

    // Calculate modulus and square root
    double modValue = num1.magnitude();
    ComplexNumber sqrtResult = num1.squareRoot();

    std::cout << "Modulus of first number: " << modValue << std::endl;
    std::cout << "Square root of first number: " << sqrtResult.getReal().retrieveValue() << " + " 
              << sqrtResult.getImaginary().retrieveValue() << "i" << std::endl;

    return 0;
}

