    Node* left;
    Node* right;
    Node* next;

    Node() : val(0), left(NULL), right(NULL), next(NULL) {}

    Node(int _val) : val(_val), left(NULL), right(NULL), next(NULL) {}

    Node(int _val, Node* _left, Node* _right, Node* _next)
        : val(_val), left(_left), right(_right), next(_next) {}
};
*/

class Solution {
public:
    Node* connect(Node* root) {
        if (!root) return root;

        Node* levelStart = root;

        while (levelStart != nullptr) {
            Node* traverseNode = levelStart;
            Node* helper = new Node(0); // Sentinel node to simplify linking
            Node* tail = helper;

            while (traverseNode != nullptr) {
                if (traverseNode->left != nullptr) {
                    tail->next = traverseNode->left;
                    tail = tail->next;
                }
                if (traverseNode->right != nullptr) {
                    tail->next = traverseNode->right;
                    tail = tail->next;
                }
                traverseNode = traverseNode->next;
            }

            levelStart = helper->next; // Proceed to the next level
            delete helper; // Release memory allocated for sentinel
        }

        return root;
    }
};

