// Check if a number is prime using an alternative approach
bool checkPrime(int value) {
    if (value <= 1) return false; // Numbers less than or equal to 1 are not prime
    if (value == 2) return true;  // 2 is the only even prime number
    if (value % 2 == 0) return false; // Exclude even numbers greater than 2

    // Check odd divisors up to sqrt(value)
    int divisor = 3;
    while (divisor * divisor <= value) {
        if (value % divisor == 0) return false;
        divisor += 2; // Only check odd numbers
    }
    return true;
}

int main() {
