// Function to store data in Ignite cache using a composite key
void storeData(Ignite& ignite, int32_t id, int32_t affinityKey, const int8_t* data, size_t dataSize) {
    // Retrieve the binary cache instance
    IgniteCache<CompositeKey, ByteArray> cache = ignite.GetCache<CompositeKey, ByteArray>("myCacheBinaryCpp");

    // Construct the composite key from provided identifiers
    CompositeKey compositeKey;
    compositeKey.id = id;
    compositeKey.affinityKey = affinityKey;

    // Create the value byte array from input data
    ByteArray payload(dataSize, data);

    // Insert or update the entry in the cache
    cache.Put(compositeKey, payload);
}

