unsigned f1(unsigned a, unsigned b) {
    // Compute sum with overflow detection
    unsigned temp_sum = a + b;
    unsigned overflow_detected = (temp_sum < a); // true if overflow occurred

    // Add 1 if overflow occurred (equivalent to adc with carry)
    unsigned final_result = temp_sum + overflow_detected;

