namespace py = pybind11;

class Foo {
public:
    Foo() : a(5) {}

    int a;
};

class Bar {
public:
    Bar() {
        auto foo1 = std::make_shared<Foo>();
        auto foo2 = std::make_shared<Foo>();
        foos.emplace_back(foo1);
        foos.emplace_back(foo2);
    }

    std::vector<std::shared_ptr<Foo>> foos;
};

PYBIND11_MODULE(pybug, m) {
    py::class_<Foo, std::shared_ptr<Foo>> foo_class(m, "Foo", py::dynamic_attr());
    foo_class
        .def(py::init<>())
        .def_readwrite("a", &Foo::a);

    py::class_<Bar> bar_class(m, "Bar");
    bar_class
        .def(py::init<>())
        .def_property_readonly("foos", [](Bar &b) {
            static std::unordered_map<std::shared_ptr<Foo>, py::object> obj_cache;
            py::list result_list;

            for (const auto &foo_ptr : b.foos) {
                auto cache_iter = obj_cache.find(foo_ptr);
                if (cache_iter == obj_cache.end()) {
                    py::object converted_obj = py::cast(foo_ptr, py::return_value_policy::reference);
                    obj_cache[foo_ptr] = converted_obj;
                    result_list.append(converted_obj);
                } else {
                    result_list.append(cache_iter->second);
                }
            }

            return result_list;
        });
}

