// Retrieve image from Android device using system picker
void imagePickerAndroid::buscaImagem()
{
    QAndroidJniObject intentAction = QAndroidJniObject::fromString("android.intent.action.GET_CONTENT");
    QAndroidJniObject intentObj("android/content/Intent");

    if (intentAction.isValid() && intentObj.isValid())
    {
        intentObj.callObjectMethod("setAction", "(Ljava/lang/String;)Landroid/content/Intent;", intentAction.object<jstring>());
        intentObj.callObjectMethod("setType", "(Ljava/lang/String;)Landroid/content/Intent;", QAndroidJniObject::fromString("image/*").object<jstring>());

        QtAndroid::startActivity(intentObj.object<jobject>(), 101, this);
        qDebug() << "Request initiated successfully";
    }
    else
    {
        qDebug() << "Failed to initialize intent objects";
    }
}

// Process the result returned after image selection
void imagePickerAndroid::handleActivityResult(int requestCode, int result, const QAndroidJniObject &resultData)
{
    jint successCode = QAndroidJniObject::getStaticField<jint>("android/app/Activity", "RESULT_OK");

    if (requestCode == 101 && result == successCode) {
        QAndroidJniObject imageUri = resultData.callObjectMethod("getData", "()Landroid/net/Uri;");

        if (imageUri.isValid()) {
            QAndroidJniObject resolver = QtAndroid::androidActivity().callObjectMethod("getContentResolver", "()Landroid/content/ContentResolver;");
            QAndroidJniObject columnKey = QAndroidJniObject::fromString("_data");

            // Prepare arguments for query method
            jobjectArray stringArray = QAndroidJniObject::fromString("_data").object<jobjectArray>();

            QAndroidJniObject cursor = resolver.callObjectMethod("query", 
                "(Landroid/net/Uri;[Ljava/lang/String;Ljava/lang/String;[Ljava/lang/String;Ljava/lang/String;)Landroid/database/Cursor;",
                imageUri.object<jobject>(),
                stringArray,
                nullptr,
                nullptr,
                nullptr);

            if (cursor.isValid()) {
                jint index = cursor.callMethod<jint>("getColumnIndexOrThrow", "(Ljava/lang/String;)I", columnKey.object<jstring>());
                cursor.callMethod<jboolean>("moveToFirst", "()Z");

                QAndroidJniObject pathValue = cursor.callObjectMethod("getString", "(I)Ljava/lang/String;", index);
                QString fullPath = pathValue.toString();

                cursor.callMethod<void>("close", "()V");

                emit imagemCaminhoSignal(fullPath);
                qDebug() << "Selected image path:" << fullPath;
            } else {
                qDebug() << "Unable to retrieve cursor";
            }
        } else {
            qDebug() << "Returned URI is invalid";
        }
    } else {
        qDebug() << "Incorrect request or result code";
    }
}

