// Find the maximum value in a vector of integers
int findMaximum(const std::vector<int>& values) {
    if (values.empty()) {  // Handle empty vector case
        return INT_MIN;  // Return the smallest possible integer
    }
    int currentMax = values[0];  // Start with the first element as maximum
    for (size_t i = 1; i < values.size(); ++i) {
        if (values[i] > currentMax) {
            currentMax = values[i];
        }
    }
    return currentMax;
}

int main() {
    std::vector<int> data = {3, 5, 1, 8, 2, 9, 4};
    std::cout << findMaximum(data) << std::endl;  // Output: 9
    return 0;
}

