    std::vector<std::string> activeVersions;

    HKEY hKey;
    if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, TEXT("SOFTWARE\\Microsoft\\.NETFramework"), 0, KEY_READ, &hKey) == ERROR_SUCCESS)
    {
        for (const auto& ver : knownVersions)
        {
            char pathBuffer[MAX_PATH] = {};
            DWORD bufferSize = MAX_PATH;

            // Construct registry value name by appending "\\InstallPath"
            std::string regValueName = ver + "\\InstallPath";
            if (RegQueryValueExA(hKey, regValueName.c_str(), nullptr, nullptr, 
                                 reinterpret_cast<LPBYTE>(pathBuffer), &bufferSize) == ERROR_SUCCESS)
            {
                if (pathBuffer[0] != '\0')
                {
                    activeVersions.push_back(ver);
                }
            }
        }
        RegCloseKey(hKey);
    }

    return activeVersions;
}

