// Check if character is an arithmetic operator
bool isArithmeticOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/' || c == '^';
}

// Determine operator precedence level
int getPrecedenceLevel(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        case '^':
            return 3;
        default:
            return 0;
    }
}

// Transform infix notation to postfix notation
std::string convertInfixToPostfix(const std::string& inputExpression) {
    std::stack<char> operatorStack;
    std::string outputString;

    for (char currentChar : inputExpression) {
        if (std::isdigit(currentChar)) {
            outputString += currentChar;
        } else if (isArithmeticOperator(currentChar)) {
            while (!operatorStack.empty() && 
                   getPrecedenceLevel(operatorStack.top()) >= getPrecedenceLevel(currentChar)) {
                outputString += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(currentChar);
        } else if (currentChar == '(') {
            operatorStack.push(currentChar);
        } else if (currentChar == ')') {
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                outputString += operatorStack.top();
                operatorStack.pop();
            }
            if (operatorStack.empty() || operatorStack.top() != '(') {
                throw std::runtime_error("Parentheses mismatch detected");
            }
            operatorStack.pop();
        }
    }

    while (!operatorStack.empty()) {
        if (operatorStack.top() == '(') {
            throw std::runtime_error("Parentheses mismatch detected");
        }
        outputString += operatorStack.top();
        operatorStack.pop();
    }

    return outputString;
}

// Compute the result of a postfix expression
double calculatePostfixResult(const std::string& postfixExpression) {
    std::stack<double> evaluationStack;

    for (char token : postfixExpression) {
        if (std::isdigit(token)) {
            evaluationStack.push(token - '0');
        } else if (isArithmeticOperator(token)) {
            if (evaluationStack.size() < 2) {
                throw std::runtime_error("Malformed expression");
            }

            double operandTwo = evaluationStack.top(); evaluationStack.pop();
            double operandOne = evaluationStack.top(); evaluationStack.pop();

            switch (token) {
                case '+': evaluationStack.push(operandOne + operandTwo); break;
                case '-': evaluationStack.push(operandOne - operandTwo); break;
                case '*': evaluationStack.push(operandOne * operandTwo); break;
                case '/': 
                    if (operandTwo == 0.0) throw std::runtime_error("Division by zero");
                    evaluationStack.push(operandOne / operandTwo); 
                    break;
                case '^': evaluationStack.push(std::pow(operandOne, operandTwo)); break;
            }
        }
    }

    if (evaluationStack.size() != 1) {
        throw std::runtime_error("Malformed expression");
    }

    return evaluationStack.top();
}

// Main function to evaluate mathematical expressions from string input
double processMathematicalExpression(const std::string& input) {
    std::string postfixForm = convertInfixToPostfix(input);
    return calculatePostfixResult(postfixForm);
}

int main() {
    std::string mathExpression = "3 + 5 * (2 - 4)";
    try {
        double computedValue = processMathematicalExpression(mathExpression);
        std::cout << "Computed Value: " << computedValue << std::endl;
    } catch (const std::exception& error) {
        std::cerr << "Exception caught: " << error.what() << std::endl;
    }
    return 0;
}

#include <openssl/aes.h>
