#include <openssl/bio.h>
#include <openssl/buffer.h>
#include <string>
#include <iostream>

// Encode binary data to Base64 format
std::string encode_to_base64(const unsigned char* input, size_t size) {
    BIO *b64_bio, *mem_bio;
    BUF_MEM *buffer_memory;

    b64_bio = BIO_new(BIO_f_base64());
    mem_bio = BIO_new(BIO_s_mem());
    b64_bio = BIO_push(b64_bio, mem_bio);

    BIO_set_flags(b64_bio, BIO_FLAGS_BASE64_NO_NL); // No line breaks in output
    BIO_write(b64_bio, input, static_cast<int>(size));
    BIO_flush(b64_bio);
    BIO_get_mem_ptr(b64_bio, &buffer_memory);

    std::string encoded(buffer_memory->data, buffer_memory->length);

    BIO_free_all(b64_bio);
    return encoded;
}

int main() {
    std::string secret_key = "REDACTED_CREDENTIAL"; // 16-byte AES-128 key
    std::string init_vector = "0123456789abcdef"; // 16-byte IV for CBC mode
    std::string original_text = "Hello, World!";

    unsigned char aes_key[AES_BLOCK_SIZE];
    unsigned char aes_iv[AES_BLOCK_SIZE];

    // Copy string contents into fixed-size buffers
    for (int i = 0; i < AES_BLOCK_SIZE; ++i) {
        aes_key[i] = static_cast<unsigned char>(secret_key[i]);
        aes_iv[i] = static_cast<unsigned char>(init_vector[i]);
    }

    EVP_CIPHER_CTX *encrypt_context = EVP_CIPHER_CTX_new();
    unsigned char encrypted_data[256];
    int partial_len, total_len = 0;

    // Initialize encryption with AES-128-CBC
    EVP_EncryptInit_ex(encrypt_context, EVP_aes_128_cbc(), nullptr, aes_key, aes_iv);

    // Perform encryption of the plaintext
    EVP_EncryptUpdate(encrypt_context, encrypted_data, &partial_len, 
                      reinterpret_cast<const unsigned char*>(original_text.c_str()), 
                      static_cast<int>(original_text.length()));
    total_len = partial_len;

    // Finalize encryption (handle padding)
    EVP_EncryptFinal_ex(encrypt_context, encrypted_data + total_len, &partial_len);
    total_len += partial_len;

    EVP_CIPHER_CTX_free(encrypt_context);

    // Convert raw ciphertext to Base64 for display
    std::string base64_result = encode_to_base64(encrypted_data, total_len);

    std::cout << "Encrypted: " << base64_result << std::endl;

    return 0;
}

