// Recursive template function to compute dot product using tail recursion
template<int N>
double dot_product(double x[], double y[]) {
    return x[N-1] * y[N-1] + dot_product<N-1>(x, y);
}

// Base case specialization for N=1
template<>
double dot_product<1>(double x[], double y[]) {
    return x[0] * y[0];
}

