typedef uint64_t xmm2q __attribute__ ((vector_size (16)));

// Lookup table for converting 2-bit values to XMM masks
static const uint16_t BIT_MASK_TABLE[4] = { 0x0000, 0x0080, 0x8000, 0x8080 };

xmm2q mask2b(uint64_t input_mask) {
    assert(input_mask < 4);

#ifdef USE_ASM
    xmm2q result;
    asm("vpmovsxbq (%1,%2,2), %0" 
        : "=x" (result) 
        : "r" (BIT_MASK_TABLE), "r" (input_mask));
    return result;
#else
    // Convert the selected 16-bit value to an XMM register and then widen to 64-bit elements
    uint16_t* table_ptr = const_cast<uint16_t*>(BIT_MASK_TABLE);
    return (xmm2q) _mm_cvtepi8_epi64(*reinterpret_cast<__m128i*>(&table_ptr[input_mask]));
#endif
}

