// Helper function to compute ceiling division
int ceilDiv(int numerator, int denominator) {
    return (numerator + denominator - 1) / denominator;
}

// CUDA kernel: computes acos of input values, sets -1 where input is divisible by 90
__global__ void processImage(const float* __restrict__ input,
                             float* __restrict__ output,
                             size_t inputStrideBytes,
                             size_t outputStrideBytes,
                             int width,
                             int height) {
    // Compute global thread indices
    int y = blockIdx.y * blockDim.y + threadIdx.y;
    int x = blockIdx.x * blockDim.x + threadIdx.x;

    // Bounds check
    if (y >= height || x >= width) return;

    // Convert byte strides to element counts
    const size_t inputStrideElems = inputStrideBytes / sizeof(float);
    const size_t outputStrideElems = outputStrideBytes / sizeof(float);

    // Compute row pointers in elements
    const float* srcRow = input + y * inputStrideElems;
    float* dstRow = output + y * outputStrideElems;

    float value = srcRow[x];

    // Check divisibility by 90 using integer cast
    if (static_cast<int>(value) % 90 == 0) {
        dstRow[x] = -1.0f;
    } else {
        dstRow[x] = acosf(value);
    }
}

// Host wrapper function
extern "C" {
void process(const float* src, float* dst,
             size_t srcStride, size_t dstStride,
             int cols, int rows) {
    // Define block dimensions (32x8 threads)
    dim3 blockSize(32, 8);

    // Calculate grid dimensions with ceiling division
    dim3 gridSize(ceilDiv(cols, blockSize.x),
                  ceilDiv(rows, blockSize.y));

    std::cout << "Launching CUDA kernel...\n";
    processImage<<<gridSize, blockSize>>>(src, dst, srcStride, dstStride, cols, rows);

    // Ensure kernel completion and error checking
    cudaDeviceSynchronize();
    std::cout << "Kernel execution completed.\n";
}
}

