void ICategoryNode::iterate(ICategoryHandler& handler) const {
    // Early exit if there are no children to process
    if (m_children == nullptr) {
        return;
    }

    // Use index-based iteration through the child nodes
    Uint32 index = 0;
    while (index < m_children.size()) {
