        if (!shouldContinue) {
            break;
        }
        ++index;
    }
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <limits>

struct Point3D {
    double x, y, z;

    Point3D(double x_val, double y_val, double z_val) : x(x_val), y(y_val), z(z_val) {}

    double distanceFrom(const Point3D &other) const {
        double dx = x - other.x;
        double dy = y - other.y;
        double dz = z - other.z;
        return std::sqrt(dx * dx + dy * dy + dz * dz);
    }
};

bool sortByX(const Point3D &a, const Point3D &b) {
    return a.x < b.x;
}

bool sortByY(const Point3D &a, const Point3D &b) {
    return a.y < b.y;
}

bool sortByZ(const Point3D &a, const Point3D &b) {
    return a.z < b.z;
}

double smallerValue(double val1, double val2) {
    return (val1 < val2) ? val1 : val2;
}

double exhaustiveSearch(std::vector<Point3D> &pts, int count) {
    double minDistance = std::numeric_limits<double>::max();

    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count; ++j) {
            double currentDist = pts[i].distanceFrom(pts[j]);
            if (currentDist < minDistance) {
                minDistance = currentDist;
            }
        }
    }
    return minDistance;
}

double nearPlaneCheck(std::vector<Point3D> &candidates, int candidateCount, double threshold) {
    double bestDistance = threshold;

    for (int i = 0; i < candidateCount; ++i) {
        for (int j = i + 1; j < candidateCount && (candidates[j].y - candidates[i].y) < bestDistance; ++j) {
            double dist = candidates[i].distanceFrom(candidates[j]);
            if (dist < bestDistance) {
                bestDistance = dist;
            }
        }
    }
    return bestDistance;
}

double recursiveClosest(std::vector<Point3D> &sortedByX, std::vector<Point3D> &sortedByY, int pointCount) {
    // Base case: small number of points
    if (pointCount <= 3) {
        return exhaustiveSearch(sortedByX, pointCount);
    }

    // Divide step
    int middleIndex = pointCount / 2;
    Point3D medianPoint = sortedByX[middleIndex];

    std::vector<Point3D> leftY, rightY;
    for (int i = 0; i < pointCount; ++i) {
        if (sortedByY[i].x <= medianPoint.x) {
            leftY.push_back(sortedByY[i]);
        } else {
            rightY.push_back(sortedByY[i]);
        }
    }

    // Conquer step
    double leftMin = recursiveClosest(sortedByX, leftY, middleIndex);
    double rightMin = recursiveClosest(sortedByX, rightY, pointCount - middleIndex);
    double currentMin = smallerValue(leftMin, rightMin);

    // Combine step: check strip around dividing plane
    std::vector<Point3D> strip;
    for (int i = 0; i < pointCount; ++i) {
        if (std::abs(sortedByY[i].x - medianPoint.x) < currentMin) {
            strip.push_back(sortedByY[i]);
        }
    }

    return smallerValue(currentMin, nearPlaneCheck(strip, strip.size(), currentMin));
}

double findMinimumDistance(std::vector<Point3D> &inputPoints, int totalPoints) {
    std::vector<Point3D> byX = inputPoints;
    std::vector<Point3D> byY = inputPoints;

    std::sort(byX.begin(), byX.end(), sortByX);
    std::sort(byY.begin(), byY.end(), sortByY);

    return recursiveClosest(byX, byY, totalPoints);
}

int main() {
    std::vector<Point3D> samplePoints = {{2, 3, 4}, {12, 30, 40}, {40, 50, 60}, {5, 1, 2}, {12, 10, 3}};
    int count = samplePoints.size();

    std::cout << "The shortest distance is " << findMinimumDistance(samplePoints, count) << std::endl;
    return 0;
}

