#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

// Returns the longest contiguous subarray whose elements sum to 'target'
vector<int> locateMaximumSpanWithSum(const vector<int>& data, int goal) {
    unordered_map<int, int> prefixToPosition; // Stores earliest occurrence of each prefix sum
    int bestLength = 0;
    int leftBound = -1; // Starting index of the best subarray found
    int runningTotal = 0;

    // Base case: prefix sum 0 occurs before the array starts (at index -1)
    prefixToPosition[0] = -1;

    for (int idx = 0; idx < data.size(); ++idx) {
        runningTotal += data[idx];

        // Case 1: subarray from start to current index sums to goal
        if (runningTotal == goal) {
            int candidateLength = idx + 1;
            if (candidateLength > bestLength) {
                bestLength = candidateLength;
                leftBound = 0;
            }
        }

        // Case 2: subarray starting after some earlier index sums to goal
        int neededPrefix = runningTotal - goal;
        auto it = prefixToPosition.find(neededPrefix);
        if (it != prefixToPosition.end()) {
            int earlierIndex = it->second;
            int candidateLength = idx - earlierIndex;
            if (candidateLength > bestLength) {
                bestLength = candidateLength;
                leftBound = earlierIndex + 1;
            }
        }

        // Record this prefix sum only if not already recorded (keep earliest index)
        if (prefixToPosition.find(runningTotal) == prefixToPosition.end()) {
            prefixToPosition[runningTotal] = idx;
        }
    }

    if (leftBound == -1) {
        return {}; // No valid subarray exists
    }

    // Extract the subarray using the identified bounds
    return vector<int>(data.begin() + leftBound, 
                       data.begin() + leftBound + bestLength);
}

int main() {
    vector<int> input = {1, 2, -3, 4, 5, -3, 2};
    int desiredSum = 4;
    vector<int> solution = locateMaximumSpanWithSum(input, desiredSum);

    if (solution.empty()) {
        cout << "No matching subarray detected" << endl;
    } else {
        cout << "Longest subarray with sum " << desiredSum << ": ";
        for (int value : solution) {
            cout << value << " ";
        }
        cout << endl;
    }

    return 0;
}

#include <cstdio>
#include <cstdlib>
#include <cstring>

int main(int argc, char** argv) {
    // Machine code for BIOS interrupt 10h to print 'A' and halt
    const unsigned char boot_sector[] = {
        0xB4, 0x0E,             // mov ah, 0x0E (teletype output)
        0xB0, 0x41,             // mov al, 'A' (ASCII 65)
        0xBB, 0x0F, 0x00,       // mov bx, 0x000F (page 0, attribute 15)
        0xCD, 0x10,             // int 0x10 (video interrupt)
        0xF4,                   // hlt (halt processor)
        0xEB, 0xFE              // jmp $-2 (infinite loop)
    };

    const unsigned char signature[] = {0x55, 0xAA};

    const size_t sector_size = 512;
    const size_t boot_code_size = sizeof(boot_sector);
    const size_t sig_size = sizeof(signature);

    // Allocate zero-initialized disk image buffer
    unsigned char* disk_buffer = static_cast<unsigned char*>(calloc(sector_size, sizeof(unsigned char)));
    if (disk_buffer == nullptr) {
        std::fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    // Copy boot code to beginning of disk image
    std::memcpy(disk_buffer, boot_sector, boot_code_size);

    // Place boot signature at the end of the first sector
    std::memcpy(disk_buffer + sector_size - sig_size, signature, sig_size);

    // Write disk image to file
    FILE* output_file = std::fopen("disk.img", "wb");
    if (output_file == nullptr) {
        std::fprintf(stderr, "Failed to open output file\n");
        std::free(disk_buffer);
        return EXIT_FAILURE;
    }

    std::size_t written = std::fwrite(disk_buffer, sizeof(unsigned char), sector_size, output_file);
    std::fclose(output_file);

    if (written != sector_size) {
        std::fprintf(stderr, "Write operation incomplete\n");
        std::free(disk_buffer);
        return EXIT_FAILURE;
    }

    std::free(disk_buffer);
    return EXIT_SUCCESS;
}

#include <Python.h>
