#include "MyClass.h"

int main() {
    MyClass instance("In C++");
    std::cout << "Instance label: \"" << instance.getLabel() << "\"\n";

    Py_Initialize();

    // Prepare Python path to include current working directory
    const std::string module_name = "passmetopythonDemo";
    PyObject* mod_name_obj = PyUnicode_DecodeFSDefault(module_name.c_str());

    // Add current directory to sys.path using std::filesystem for robustness
    std::string current_dir = std::filesystem::current_path().string();
    std::string path_cmd = "import sys; sys.path.insert(0, '" + current_dir + "')";
    PyRun_SimpleString(path_cmd.c_str());

    PyObject* imported_module = PyImport_Import(mod_name_obj);
    Py_DECREF(mod_name_obj);

    if (!imported_module) {
        std::cerr << "Failed to import module '" << module_name << "'.\n";
        PyErr_Print();
        Py_Finalize();
        return 1;
    }

    // Retrieve 'execute' function from the module
    PyObject* func_obj = PyObject_GetAttrString(imported_module, "execute");

    if (func_obj && PyCallable_Check(func_obj)) {
        // Build argument tuple: one element — a capsule wrapping the C++ object
        PyObject* args_tuple = PyTuple_New(1);
        PyObject* capsule = PyCapsule_New(&instance, "MyClass", nullptr);
        PyTuple_SetItem(args_tuple, 0, capsule);  // Steals reference to capsule

        std::cout << "\nInvoking Python function with MyClass argument\n";
        PyObject* result = PyObject_CallObject(func_obj, args_tuple);
        Py_DECREF(args_tuple);

        if (!result) {
            std::cerr << "Error occurred during Python function invocation.\n";
            PyErr_Print();
        } else {
            std::cout << "Python function executed successfully.\n";
            Py_XDECREF(result);
        }
    } else {
        std::cerr << "Could not retrieve callable 'execute' from module '" << module_name << "'.\n";
        if (PyErr_Occurred()) PyErr_Print();
    }

    Py_XDECREF(func_obj);
    Py_DECREF(imported_module);
    Py_Finalize();

    return 0;
}

