std::map<std::string, std::string> combineStringMaps(const std::map<std::string, std::string>& firstMap, const std::map<std::string, std::string>& secondMap) {
    std::map<std::string, std::string> combinedResult;

    // Insert all elements from the first map
    for (auto it = firstMap.begin(); it != firstMap.end(); ++it) {
        combinedResult[it->first] = it->second;
    }

    // Process elements from the second map - merge if key exists
    for (auto it = secondMap.begin(); it != secondMap.end(); ++it) {
        auto existing = combinedResult.find(it->first);
        if (existing != combinedResult.end()) {
            // If key exists in both, concatenate values
            combinedResult[it->first] = existing->second + it->second;
        } else {
            // Otherwise just insert
            combinedResult[it->first] = it->second;
        }
    }

    return combinedResult;
}

#include <windows.h>
#include <stdio.h>

// Server implementation using named pipes with message-based communication
void NamedPipeServer()
{
    HANDLE hPipe;
    char recvBuffer[1024];
    DWORD bytesRead, bytesWritten;

    while (true)
    {
        // Create a new named pipe instance for each connection attempt
        hPipe = CreateNamedPipe(
            TEXT("\\\\.\\pipe\\testpipe"),
            PIPE_ACCESS_DUPLEX,
            PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT,
            1,
            16 * 1024,
            16 * 1024,
            0,
            NULL);

        if (hPipe == INVALID_HANDLE_VALUE)
        {
            fprintf(stderr, "Failed to create named pipe: error %lu\n", GetLastError());
            return;
        }

        // Wait for a client to connect
        if (ConnectNamedPipe(hPipe, NULL) != FALSE)
        {
            // Process messages from the client
            while (ReadFile(hPipe, recvBuffer, sizeof(recvBuffer) - 1, &bytesRead, NULL) != FALSE)
            {
                recvBuffer[bytesRead] = '\0';
                printf("Received from client: %s\n", recvBuffer);

                const char* reply = "Message received";
                WriteFile(hPipe, reply, (DWORD)strlen(reply), &bytesWritten, NULL);
            }
        }
        else
        {
            fprintf(stderr, "Connection failed: error %lu\n", GetLastError());
        }

        // Clean up the current pipe handle before next iteration
        CloseHandle(hPipe);
    }
}

int main()
{
    NamedPipeServer();
    return 0;
}

#include <iostream>
