// Definition for a binary tree node
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

// Helper function to locate the lowest common ancestor of two values in a binary tree
TreeNode* getLowestCommonAncestor(TreeNode* node, int value1, int value2) {
    if (node == nullptr) return nullptr;

    // If current node contains one of the target values, return it
    if (node->val == value1 || node->val == value2) {
        return node;
    }

    // Recursively search in left and right subtrees
    TreeNode* leftResult = getLowestCommonAncestor(node->left, value1, value2);
    TreeNode* rightResult = getLowestCommonAncestor(node->right, value1, value2);

    // If both sides found a result, this node is their common ancestor
    if (leftResult != nullptr && rightResult != nullptr) {
        return node;
    }

    // Otherwise, return whichever side has a result (or nullptr if none)
    return (leftResult != nullptr) ? leftResult : rightResult;
}

// Constructs a sample binary tree for testing
TreeNode* createSampleTree() {
    TreeNode* root = new TreeNode(1);
    root->left = new TreeNode(2);
    root->right = new TreeNode(3);
    root->left->left = new TreeNode(4);
    root->left->right = new TreeNode(5);
    root->right->left = new TreeNode(6);
    root->right->right = new TreeNode(7);
    return root;
}

