#include <winsock2.h>
#include <windows.h>
#include <iostream>

#pragma comment(lib, "ws2_32.lib")

// Callback functions for I/O operations
void HandleIncomingData(SOCKET sock, DWORD receivedBytes);
void HandleSendCompletion(SOCKET sock, DWORD sentBytes);

int main() {
    // Initialize Winsock library
    WSADATA wsaData;
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
        std::cerr << "Error: Unable to initialize Winsock" << std::endl;
        return 1;
    }

    // Create TCP socket for client communication
    SOCKET clientSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (clientSocket == INVALID_SOCKET) {
        std::cerr << "Error: Socket creation failed" << std::endl;
        WSACleanup();
        return 1;
    }

    // Configure server connection parameters
    sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(12345);
    serverAddress.sin_addr.s_addr = inet_addr("127.0.0.1");

    // Attempt to connect to the server
    if (connect(clientSocket, (sockaddr*)&serverAddress, sizeof(serverAddress)) == SOCKET_ERROR) {
        std::cerr << "Error: Connection to server failed" << std::endl;
        closesocket(clientSocket);
        WSACleanup();
        return 1;
    }

    // Prepare overlapped structure and buffer for asynchronous receive
    WSABUF inputBuffer;
    char bufferData[1024];
    inputBuffer.buf = bufferData;
    inputBuffer.len = sizeof(bufferData);

    DWORD transferredBytes;
    DWORD operationFlags = 0;
    WSAOVERLAPPED recvOverlap = {0};
    recvOverlap.hEvent = WSACreateEvent();

    // Start asynchronous receive operation
    if (WSARecv(clientSocket, &inputBuffer, 1, &transferredBytes, &operationFlags, &recvOverlap, NULL) == SOCKET_ERROR) {
        if (WSAGetLastError() != WSA_IO_PENDING) {
            std::cerr << "Error: Initial receive operation failed" << std::endl;
            WSACloseEvent(recvOverlap.hEvent);
            closesocket(clientSocket);
            WSACleanup();
            return 1;
        }
    }

    // Set up event monitoring for read and write completion
    HANDLE eventArray[2];
    eventArray[0] = recvOverlap.hEvent;
    eventArray[1] = CreateEvent(NULL, TRUE, FALSE, NULL);

    // Main event loop for handling asynchronous operations
    while (true) {
        DWORD waitResult = WaitForMultipleObjects(2, eventArray, FALSE, INFINITE);

        switch (waitResult) {
            case WAIT_OBJECT_0:
                // Read operation completed
                if (WSAGetOverlappedResult(clientSocket, &recvOverlap, &transferredBytes, FALSE, &operationFlags)) {
                    HandleIncomingData(clientSocket, transferredBytes);
                } else {
                    std::cerr << "Error: Read operation encountered an issue" << std::endl;
                }

                // Restart the asynchronous receive operation
                if (WSARecv(clientSocket, &inputBuffer, 1, &transferredBytes, &operationFlags, &recvOverlap, NULL) == SOCKET_ERROR) {
                    if (WSAGetLastError() != WSA_IO_PENDING) {
                        std::cerr << "Error: Could not restart receive operation" << std::endl;
                        break;
                    }
                }
                break;

            case WAIT_OBJECT_0 + 1:
                // Write operation completed
                HandleSendCompletion(clientSocket, transferredBytes);
                break;

            default:
                std::cerr << "Error: Event waiting mechanism failed" << std::endl;
                break;
        }
    }

    // Cleanup resources before exit
    WSACloseEvent(recvOverlap.hEvent);
    CloseHandle(eventArray[1]);
    closesocket(clientSocket);
    WSACleanup();

    return 0;
}

