using namespace std;

// Function to find subarray pairs with maximum alternating sum
vector<pair<int,int>> findMaxAlternatingSubarray(vector<int> inputArray, int *maxSum) {
    int n = inputArray.size();

    // Create transformed array with alternating signs: -a[0], +a[1], -a[2], +a[3], ...
    vector<int> transformed(n);
    for (int i = 0; i < n; i++) {
        transformed[i] = ((i % 2 == 0) ? -1 : 1) * inputArray[i];
    }

    // Apply modified Kadane's algorithm to find maximum subarray sum
    vector<int> dp(n);
    vector<int> startPos(n);

    dp[0] = transformed[0];
    startPos[0] = 1;  // 1-indexed starting position

    int currentMax = dp[0];
    int maxPosition = 0;

    for (int i = 1; i < n; ++i) {
        if (dp[i - 1] > 0) {
            dp[i] = dp[i - 1] + transformed[i];
            startPos[i] = startPos[i - 1];
        } else {
            dp[i] = transformed[i];
            startPos[i] = i + 1;
        }

        if (dp[i] > currentMax) {
            currentMax = dp[i];
            maxPosition = i;
        }
    }

    // Extract the result range
    int finalEnd = maxPosition + 1;   // Convert to 1-indexed end position
    int finalStart = startPos[maxPosition];  // Start position from tracking array

    // Generate all prefix pairs from start to end positions
    vector<pair<int, int>> outputPairs;
    *maxSum = currentMax;

    for (int pos = finalStart; pos <= finalEnd; ++pos) {
        outputPairs.push_back(make_pair(finalStart, pos));
    }

    return outputPairs;
}

int main() {
    vector<int> data = {-4, 6, -7, 2, 2};
    int bestValue;
    vector<pair<int,int>> solution = findMaxAlternatingSubarray(data, &bestValue);

    cout << "Result Pairs: ";
    for (auto p : solution) {
        cout << "(" << p.first << "," << p.second << "),";
    }
    cout << " max_sum = " << bestValue << endl;

    return 0;
}

