#include <iostream>
#include <vector>
#include <string>

// Find the longest common substring between two strings
std::string findMaxCommonSubstr(const std::string& str1, const std::string& str2) {
    int len1 = str1.size();
    int len2 = str2.size();

    // Create a 2D table initialized with zeros
    std::vector<std::vector<int>> table(len1 + 1, std::vector<int>(len2 + 1, 0));

    int maxLen = 0;
    int lastIdx = -1;

    // Build the DP table
    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (str1[i - 1] == str2[j - 1]) {
                table[i][j] = table[i - 1][j - 1] + 1;

                if (table[i][j] > maxLen) {
                    maxLen = table[i][j];
                    lastIdx = i - 1;
                }
            } else {
                table[i][j] = 0;
            }
        }
    }

    // Return the substring if found
    if (maxLen > 0) {
        return str1.substr(lastIdx - maxLen + 1, maxLen);
    }

    return "";
}

int main() {
    std::string text1 = "ABABC";
    std::string text2 = "BABC";
    std::string commonPart = findMaxCommonSubstr(text1, text2);
    std::cout << "Longest Common Substring: " << commonPart << std::endl;
    return 0;
}

