#include <Ogre.h>

// Transform a vector from one scene node's coordinate system to another
Ogre::Vector3 TFormVector(const Ogre::Vector3& inputVec, Ogre::SceneNode* originNode, Ogre::SceneNode* targetNode) {
    Ogre::Vector3 result = inputVec;

    // Handle source node transformation components
    Ogre::Vector3 srcPos;
    Ogre::Quaternion srcRot;

    if (originNode != nullptr) {
        srcPos = originNode->_getDerivedPosition();
        srcRot = originNode->_getDerivedOrientation();
    } else {
        srcPos = Ogre::Vector3::ZERO;
        srcRot = Ogre::Quaternion::IDENTITY;
    }

    // Handle destination node transformation components
    Ogre::Vector3 dstPos;
    Ogre::Quaternion dstRot;

    if (targetNode != nullptr) {
        dstPos = targetNode->_getDerivedPosition();
        dstRot = targetNode->_getDerivedOrientation();
    } else {
        dstPos = Ogre::Vector3::ZERO;
        dstRot = Ogre::Quaternion::IDENTITY;
    }

    // Step 1: Convert input vector to source node's local space
    result = srcRot.Inverse() * (inputVec - srcPos);

    // Step 2: Apply rotation to align with destination node's orientation
    result = dstRot * result;

    // Step 3: Translate to destination node's position in world space
    result = dstPos + result;

    return result;
}

