#include <cstdlib>
#include <ctime>

using namespace std;

// Compute greatest common divisor using Euclidean algorithm
unsigned long long computeGCD(unsigned long long x, unsigned long long y) {
    while (y != 0) {
        unsigned long long temp = y;
        y = x % y;
        x = temp;
    }
    return x;
}

// Pollard's Rho factorization algorithm
unsigned long long findFactor(unsigned long long number) {
    // Handle even numbers directly
    if (number % 2 == 0) return 2;

    // Initialize variables for cycle detection
    unsigned long long slow = 2, fast = 2, divisor = 1;
    unsigned long long constant = (unsigned long long)rand() % (number - 1) + 1;

    // Floyd's cycle-finding approach
    while (divisor == 1) {
        slow = (slow * slow + constant) % number;
        fast = (fast * fast + constant) % number;
        fast = (fast * fast + constant) % number; // Move fast twice

        divisor = computeGCD(abs(slow - fast), number);

        // If we hit the number itself, retry with new constant
        if (divisor == number) return findFactor(number);
    }

    return divisor;
}

// Recursive function to print prime factors
void decompose(unsigned long long value) {
    if (value == 1) return;

    // Check for factor of 2 first
    if (value % 2 == 0) {
        cout << 2 << " ";
        decompose(value / 2);
        return;
    }

    // Find a non-trivial factor using Pollard's Rho
    unsigned long long primeFactor = findFactor(value);

    // If the factor is the number itself, it's prime
    if (primeFactor == value) {
        cout << value << " ";
    } else {
        // Recursively factorize both parts
        decompose(primeFactor);
        decompose(value / primeFactor);
    }
}

int main() {
    srand(static_cast<unsigned>(time(0))); // Seed random generator

    unsigned long long target = 9999;
    cout << "Prime factors of " << target << ": ";
    decompose(target);
    cout << endl;

    return 0;
}

#include <cuda_runtime.h>
#include <iostream>

// Kernel to read from texture and write to global memory
__global__ void textureReadKernel(cudaTextureObject_t texObj, float *output, int cols, int rows) {
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    if (col < cols && row < rows) {
        // Read using texture coordinates (x=col, y=row)
        float pixelVal = tex2D<float>(texObj, col, row);
        output[row * cols + col] = pixelVal;
    }
}

int main() {
    // Device pointers and texture object
    float *deviceInput = nullptr;
    cudaTextureObject_t textureObject = 0;
    float *deviceOutput = nullptr;

    // Define image dimensions
    const int imgWidth = 256;
    const int imgHeight = 256;

    // Allocate memory on device
    size_t bytes = imgWidth * imgHeight * sizeof(float);
    cudaMalloc(&deviceInput, bytes);
    cudaMalloc(&deviceOutput, bytes);

    // Initialize input data to zero
    cudaMemset(deviceInput, 0, bytes);

    // Setup resource descriptor for linear memory
    cudaResourceDesc resDesc = {};
    resDesc.resType = cudaResourceTypeLinear;
    resDesc.res.linear.devPtr = deviceInput;
    resDesc.res.linear.desc = cudaCreateChannelDesc<float>();
    resDesc.res.linear.sizeInBytes = bytes;

    // Setup texture descriptor
    cudaTextureDesc texDesc = {};
    texDesc.readMode = cudaReadModeElementType;
    texDesc.addressMode[0] = cudaAddressModeClamp;
    texDesc.addressMode[1] = cudaAddressModeClamp;
    texDesc.filterMode = cudaFilterModeLinear;
    texDesc.normalizedCoords = 0;

    // Create texture object
    cudaCreateTextureObject(&textureObject, &resDesc, &texDesc, nullptr);

    // Configure kernel launch parameters
    dim3 threadsPerBlock(16, 16);
    dim3 numBlocks((imgWidth + threadsPerBlock.x - 1) / threadsPerBlock.x,
                   (imgHeight + threadsPerBlock.y - 1) / threadsPerBlock.y);

    // Launch the kernel
    textureReadKernel<<<numBlocks, threadsPerBlock>>>(textureObject, deviceOutput, imgWidth, imgHeight);
    cudaDeviceSynchronize();

    // Transfer results back to host
    float *hostResult = new float[imgWidth * imgHeight];
    cudaMemcpy(hostResult, deviceOutput, bytes, cudaMemcpyDeviceToHost);

    // Cleanup resources
    cudaDestroyTextureObject(textureObject);
    cudaFree(deviceInput);
    cudaFree(deviceOutput);
    delete[] hostResult;

    return 0;
}

