// Recursively list files in a directory and its subdirectories
void TraverseDirectory(const std::string& dirPath) {
    WIN32_FIND_DATAA findData;
    std::string searchPattern = dirPath + "\\*";
    HANDLE hSearch = FindFirstFileA(searchPattern.c_str(), &findData);

    if (hSearch != INVALID_HANDLE_VALUE) {
        do {
            // Skip current and parent directory entries
            if (strcmp(findData.cFileName, ".") == 0 || strcmp(findData.cFileName, "..") == 0) {
                continue;
            }

            std::string fullPath = dirPath + "\\" + findData.cFileName;

            // If it's a file, print the full path
            if (!(findData.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)) {
                std::cout << fullPath << std::endl;
            } 
            // If it's a directory, recurse into it
            else {
                TraverseDirectory(fullPath);
            }
        } while (FindNextFileA(hSearch, &findData));

        FindClose(hSearch);
    }
}

int main() {
    std::string targetPath = "C:\\Users\\Public\\Documents";
    TraverseDirectory(targetPath);
    return 0;
}

