#include <iostream>
#include <unordered_map>
#include <list>
#include <memory>

template <typename T>
class DoublyLinkedCacheList {
private:
    struct ElementNode {
        T data;
        std::shared_ptr<ElementNode> backward;
        std::shared_ptr<ElementNode> forward;
    };

    std::shared_ptr<ElementNode> start;
    std::shared_ptr<ElementNode> end;
    std::unordered_map<T, std::shared_ptr<ElementNode>> lookup;
    std::list<T> recentUsage;

public:
    DoublyLinkedCacheList() : start(nullptr), end(nullptr) {}

    // Add element to the beginning of the list
    void addFirst(const T& item) {
        auto newNode = std::make_shared<ElementNode>(ElementNode{item, nullptr, start});
        if (start) {
            start->backward = newNode;
        } else {
            end = newNode;
        }
        start = newNode;
        lookup[item] = newNode;
        recentUsage.push_front(item);
    }

    // Add element to the end of the list
    void addLast(const T& item) {
        auto newNode = std::make_shared<ElementNode>(ElementNode{item, end, nullptr});
        if (end) {
            end->forward = newNode;
        } else {
            start = newNode;
        }
        end = newNode;
        lookup[item] = newNode;
        recentUsage.push_front(item);
    }

    // Remove the first element
    void removeFirst() {
        if (!start) return;
        auto removed = start;
        start = start->forward;
        if (start) {
            start->backward = nullptr;
        } else {
            end = nullptr;
        }
        lookup.erase(removed->data);
        recentUsage.remove(removed->data);
    }

    // Remove the last element
    void removeLast() {
        if (!end) return;
        auto removed = end;
        end = end->backward;
        if (end) {
            end->forward = nullptr;
        } else {
            start = nullptr;
        }
        lookup.erase(removed->data);
        recentUsage.remove(removed->data);
    }

    // Search for an element by value
    std::shared_ptr<ElementNode> search(const T& item) {
        auto iter = lookup.find(item);
        if (iter != lookup.end()) {
            recentUsage.push_front(item);
            return iter->second;
        }
        return nullptr;
    }

    // Display all elements in order
    void show() const {
        auto current = start;
        while (current) {
            std::cout << current->data << " ";
            current = current->forward;
        }
        std::cout << std::endl;
    }
};

int main() {
    DoublyLinkedCacheList<int> dlist;
    dlist.addFirst(1);
    dlist.addFirst(2);
    dlist.addLast(3);
    dlist.addLast(4);

    dlist.show(); // Output: 2 1 3 4

    dlist.removeFirst();
    dlist.removeLast();

    dlist.show(); // Output: 1 3

    auto foundNode = dlist.search(3);
    if (foundNode) {
        std::cout << "Found value: " << foundNode->data << std::endl; // Output: Found value: 3
    }

    return 0;
}

#include <coroutine>
#include <iostream>
#include <string>

// Generator template for producing values one at a time
template <typename T>
struct char_producer {
    struct promise_impl;
    using handle_type = std::coroutine_handle<promise_impl>;

    struct promise_impl {
        T stored_char;

        auto get_return_object() { 
            return char_producer{handle_type::from_promise(*this)}; 
        }

        auto initial_suspend() { 
            return std::suspend_always{}; 
        }

        auto final_suspend() noexcept { 
            return std::suspend_always{}; 
        }

        void unhandled_exception() { 
            std::terminate(); 
        }

        auto yield_value(T val) {
            stored_char = val;
            return std::suspend_always{};
        }
    };

    bool advance() {
        if (handle && !handle.done()) {
            handle.resume();
            return !handle.done();
        }
        return false;
    }

    T current() const { 
        return handle.promise().stored_char; 
    }

    char_producer(char_producer const&) = delete;
    char_producer(char_producer&& other) 
        : handle(other.handle) {
        other.handle = nullptr;
    }

    ~char_producer() {
        if (handle) handle.destroy();
    }

private:
    explicit char_producer(handle_type h) : handle(h) {}
    handle_type handle;
};

