            return !coro_handle.done();
        }
        return false;
    }

    char get_current_char() const {
        return coro_handle.promise().current_char;
    }

private:
    std::coroutine_handle<internal_state> coro_handle;

    // Internal helper to store current character during suspension
    struct internal_state_with_char : internal_state {
        char current_char;
    };

    doubled_chars_generator(std::coroutine_handle<internal_state> h) 
        : coro_handle(h) {}

    friend struct internal_state;
};

// Function to generate doubled characters from input string
doubled_chars_generator produce_doubled(const std::string& input) {
    std::string text = input;
    char doubled_char;

    for (;;) {
        co_await std::suspend_always{};

        for (auto iter = text.begin(); iter != text.end(); ++iter) {
            doubled_char = static_cast<char>(*iter * 2);
            co_yield doubled_char;
        }
    }
}

int main() {
    doubled_chars_generator generator_instance = produce_doubled("");

    // First test case
    generator_instance.coro_handle.promise().assign_input("hello world");

    while (generator_instance.step_forward()) {
        std::cout << generator_instance.get_current_char() << ' ';
    }
    std::cout << std::endl;

    // Second test case
    generator_instance.coro_handle.promise().assign_input("abc");

    while (generator_instance.step_forward()) {
        std::cout << generator_instance.get_current_char() << ' ';
    }
    std::cout << std::endl;

    return 0;
}

