// Constants for RTP configuration
constexpr int MAX_RTP_PACKET_SIZE = 1378;
constexpr int H264_RTP_TYPE = 98;
constexpr int AAC_RTP_TYPE = 100;

// Target encoding parameters
constexpr int VIDEO_BITRATE_TARGET = 2'000'000;
constexpr int VIDEO_FRAMES_PER_SEC = 25;
constexpr int AUDIO_SAMPLE_RATE_TARGET = 44100;
constexpr int AUDIO_CHANNEL_COUNT = 2;
constexpr int AUDIO_SAMPLE_DEPTH_BITS = 16;

// Helper: send packet via RTP stream
void transmit_rtp_data(AVFormatContext* rtp_ctx, AVPacket* raw_pkt, int stream_id);

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <input_file> <port>" << std::endl;
        return EXIT_FAILURE;
    }

    const char* input_path = argv[1];
    int dest_port = std::stoi(argv[2]);

    // Initialize FFmpeg subsystems
    av_register_all();
    avformat_network_init();

    AVFormatContext* input_fmt = nullptr;
    if (avformat_open_input(&input_fmt, input_path, nullptr, nullptr) < 0) {
        std::cerr << "Failed to open input file: " << input_path << std::endl;
        return EXIT_FAILURE;
    }

    if (avformat_find_stream_info(input_fmt, nullptr) < 0) {
        std::cerr << "Could not retrieve stream information" << std::endl;
        avformat_close_input(&input_fmt);
        return EXIT_FAILURE;
    }

    // Locate video and audio streams
    int vid_idx = -1, aud_idx = -1;
    AVStream* vstream = nullptr, * astream = nullptr;
    for (unsigned i = 0; i < input_fmt->nb_streams; ++i) {
        AVCodecParameters* par = input_fmt->streams[i]->codecpar;
        if (par->codec_type == AVMEDIA_TYPE_VIDEO) {
            vid_idx = i;
            vstream = input_fmt->streams[i];
        } else if (par->codec_type == AVMEDIA_TYPE_AUDIO) {
            aud_idx = i;
            astream = input_fmt->streams[i];
        }
    }

    if (vid_idx == -1 || aud_idx == -1) {
        std::cerr << "Input must contain both video and audio streams" << std::endl;
        avformat_close_input(&input_fmt);
        return EXIT_FAILURE;
    }

    // Open decoders
    AVCodec* vdec = avcodec_find_decoder(vstream->codecpar->codec_id);
    if (!vdec) {
        std::cerr << "Video decoder not found" << std::endl;
        avformat_close_input(&input_fmt);
        return EXIT_FAILURE;
    }

    AVCodecContext* vctx = avcodec_alloc_context3(vdec);
    if (avcodec_parameters_to_context(vctx, vstream->codecpar) < 0 ||
        avcodec_open2(vctx, vdec, nullptr) < 0) {
        std::cerr << "Failed to initialize video decoder" << std::endl;
        avcodec_free_context(&vctx);
        avformat_close_input(&input_fmt);
        return EXIT_FAILURE;
    }

    AVCodec* adec = avcodec_find_decoder(astream->codecpar->codec_id);
    if (!adec) {
        std::cerr << "Audio decoder not found" << std::endl;
        avcodec_free_context(&vctx);
        avformat_close_input(&input_fmt);
        return EXIT_FAILURE;
    }

    AVCodecContext* actx = avcodec_alloc_context3(adec);
    if (avcodec_parameters_to_context(actx, astream->codecpar) < 0 ||
        avcodec_open2(actx, adec, nullptr) < 0) {
        std::cerr << "Failed to initialize audio decoder" << std::endl;
        avcodec_free_context(&vctx);
        avcodec_free_context(&actx);
        avformat_close_input(&input_fmt);
        return EXIT_FAILURE;
    }

    // Prepare RTP output context
    char rtp_uri[1024];
    snprintf(rtp_uri, sizeof(rtp_uri), "rtp://localhost:%d?pkt_size=%d", dest_port, MAX_RTP_PACKET_SIZE);

    AVFormatContext* rtp_out = nullptr;
    if (avformat_alloc_output_context2(&rtp_out, nullptr, "rtp", rtp_uri) < 0 || !rtp_out) {
        std::cerr << "RTP output context creation failed" << std::endl;
        avcodec_free_context(&vctx);
        avcodec_free_context(&actx);
        avformat_close_input(&input_fmt);
        return EXIT_FAILURE;
    }

    // Add video stream to RTP output
    AVStream* rtp_vst = avformat_new_stream(rtp_out, nullptr);
    if (!rtp_vst) {
        std::cerr << "Failed to create RTP video stream" << std::endl;
        avformat_free_context(rtp_out);
        avcodec_free_context(&vctx);
        avcodec_free_context(&actx);
        avformat_close_input(&input_fmt);
        return EXIT_FAILURE;
    }

    rtp_vst->codecpar->codec_id = AV_CODEC_ID_H264;
    rtp_vst->codecpar->bit_rate = VIDEO_BITRATE_TARGET;
    rtp_vst->codecpar->width = vctx->width;
    rtp_vst->codecpar->height = vctx->height;
    rtp_vst->codecpar->format = vctx->pix_fmt;
    rtp_vst->time_base = vctx->time_base;
    rtp_vst->codecpar->codec_type = AVMEDIA_TYPE_VIDEO;

    // Add audio stream to RTP output
    AVStream* rtp_ast = avformat_new_stream(rtp_out, nullptr);
    if (!rtp_ast) {
        std::cerr << "Failed to create RTP audio stream" << std::endl;
        avformat_free_context(rtp_out);
        avcodec_free_context(&vctx);
        avcodec_free_context(&actx);
        avformat_close_input(&input_fmt);
        return EXIT_FAILURE;
    }

    rtp_ast->codecpar->codec_id = AV_CODEC_ID_AAC;
    rtp_ast->codecpar->sample_rate = AUDIO_SAMPLE_RATE_TARGET;
    rtp_ast->codecpar->channels = AUDIO_CHANNEL_COUNT;
    rtp_ast->codecpar->channel_layout = av_get_default_channel_layout(AUDIO_CHANNEL_COUNT);
    rtp_ast->codecpar->format = AV_SAMPLE_FMT_FLTP;
    rtp_ast->time_base = astream->time_base;
    rtp_ast->codecpar->codec_type = AVMEDIA_TYPE_AUDIO;

    // Open output IO
    if (avio_open(&rtp_out->pb, rtp_uri, AVIO_FLAG_WRITE) < 0) {
        std::cerr << "Could not open RTP output URL" << std::endl;
        avformat_free_context(rtp_out);
        avcodec_free_context(&vctx);
        avcodec_free_context(&actx);
        avformat_close_input(&input_fmt);
        return EXIT_FAILURE;
    }

    // Write header
    AVDictionary* opts = nullptr;
    av_dict_set(&opts, "sdp_file", "output.sdp", 0);
    if (avformat_write_header(rtp_out, &opts) < 0) {
        std::cerr << "Error writing RTP header" << std::endl;
        av_dict_free(&opts);
        avio_closep(&rtp_out->pb);
        avformat_free_context(rtp_out);
        avcodec_free_context(&vctx);
        avcodec_free_context(&actx);
        avformat_close_input(&input_fmt);
        return EXIT_FAILURE;
    }
    av_dict_free(&opts);

    // Decode loop
    AVFrame* frame = av_frame_alloc();
    AVPacket pkt;
    av_init_packet(&pkt);
    pkt.data = nullptr;
    pkt.size = 0;

    double frame_interval = 1.0 / VIDEO_FRAMES_PER_SEC;

    while (av_read_frame(input_fmt, &pkt) >= 0) {
        if (pkt.stream_index == vid_idx) {
            transmit_rtp_data(rtp_out, &pkt, 0);
        } else if (pkt.stream_index == aud_idx) {
            transmit_rtp_data(rtp_out, &pkt, 1);
        }
        av_packet_unref(&pkt);

        std::this_thread::sleep_for(std::chrono::duration<double>(frame_interval));
    }

    av_write_trailer(rtp_out);

    // Cleanup
    avformat_free_context(rtp_out);
    avcodec_free_context(&vctx);
    avcodec_free_context(&actx);
    avformat_close_input(&input_fmt);
    av_frame_free(&frame);

    return EXIT_SUCCESS;
}

void transmit_rtp_data(AVFormatContext* rtp_ctx, AVPacket* raw_pkt, int stream_id) {
    const int HEADER_OVERHEAD = 12;
    const int max_payload = MAX_RTP_PACKET_SIZE - HEADER_OVERHEAD;

    uint8_t* data_ptr = raw_pkt->data;
    int bytes_left = raw_pkt->size;

    while (bytes_left > 0) {
        int chunk_size = std::min(max_payload, bytes_left);

        AVPacket rtp_pkt;
        av_init_packet(&rtp_pkt);
        rtp_pkt.data = data_ptr;
        rtp_pkt.size = chunk_size;
        rtp_pkt.stream_index = stream_id;

        av_interleaved_write_frame(rtp_ctx, &rtp_pkt);
        av_packet_unref(&rtp_pkt);

        data_ptr += chunk_size;
        bytes_left -= chunk_size;
    }
}

