// Check if a number is prime
bool checkPrime(int value) {
    if (value < 2)
        return false;
    for (int j = 2; j * j <= value; ++j) {
        if (value % j == 0)
            return false;
    }
    return true;
}

// Compute the product of all digits in a number
int multiplyDigits(int x) {
    int result = 1;
    while (x > 0) {
        result *= x % 10;
        x /= 10;
    }
    return result;
}

// Find the smallest prime in the list and return the product of its digits
int getDigitProductOfSmallestPrime(vector<int>& data) {
    vector<int> primes;

    // Collect all prime numbers from the input list
    for (int element : data) {
        if (checkPrime(element)) {
            primes.push_back(element);
        }
    }

    // If no primes found, return -1
    if (primes.empty())
        return -1;

    // Find the minimum prime
    int smallestPrime = *min_element(primes.begin(), primes.end());

    // Return the product of its digits
    return multiplyDigits(smallestPrime);
}

int main() {
    vector<int> inputList = {0, 3, 2, 1, 3, 5, 7, 4, 5, 5, 5, 2, 181, 32, 4, 32, 3, 2, 32, 324, 4, 3};
    int answer = getDigitProductOfSmallestPrime(inputList);
    cout << "The product of the digits of the smallest prime number is: " << answer << endl;
    return 0;
}

#include <cuda_runtime.h>
#include <iostream>

// Kernel function to double each element in the array
__global__ void doubleElements(float *array, int length) {
    int position = blockIdx.x * blockDim.x + threadIdx.x;
    if (position < length) {
        array[position] *= 2.0f;
    }
}

int main() {
    const int totalElements = 1024 * 1024;
    int byteCount = totalElements * sizeof(float);

    float *hostMemory = nullptr;
    float *deviceMemA = nullptr;
    float *deviceMemB = nullptr;

    // Allocate pinned host memory and device memory
    cudaMallocHost(&hostMemory, byteCount);
    cudaMalloc(&deviceMemA, byteCount);
    cudaMalloc(&deviceMemB, byteCount);

    // Initialize host data
    for (int index = 0; index < totalElements; ++index) {
        hostMemory[index] = static_cast<float>(index);
    }

    // Create two CUDA streams for concurrent execution
    cudaStream_t streamA, streamB;
    cudaStreamCreate(&streamA);
    cudaStreamCreate(&streamB);

    // First stream: copy data and process on deviceMemA
    cudaMemcpyAsync(deviceMemA, hostMemory, byteCount, cudaMemcpyHostToDevice, streamA);
    doubleElements<<<(totalElements + 255) / 256, 256, 0, streamA>>>(deviceMemA, totalElements);

    // Second stream: copy data and process on deviceMemB
    cudaMemcpyAsync(deviceMemB, hostMemory, byteCount, cudaMemcpyHostToDevice, streamB);
    doubleElements<<<(totalElements + 255) / 256, 256, 0, streamB>>>(deviceMemB, totalElements);

    // Copy results back to host (note: second copy overwrites first)
    cudaMemcpyAsync(hostMemory, deviceMemA, byteCount, cudaMemcpyDeviceToHost, streamA);
    cudaMemcpyAsync(hostMemory, deviceMemB, byteCount, cudaMemcpyDeviceToHost, streamB);

    // Wait for both streams to complete
    cudaStreamSynchronize(streamA);
    cudaStreamSynchronize(streamB);

    // Clean up resources
    cudaFreeHost(hostMemory);
    cudaFree(deviceMemA);
    cudaFree(deviceMemB);

    cudaStreamDestroy(streamA);
    cudaStreamDestroy(streamB);

    return 0;
}

