// Calculate the time interval in seconds from current time to prayer time
long timeDifferenceInSeconds(const char* prayerTime, int currentHour, int currentMinute) {
  // Extract hour and minute components from the prayer time string
  char hourStr[3];
  char minStr[3];
  extractHourMinute(prayerTime, hourStr, minStr);

  // Convert string representations to integer values
  int prayerHr = std::atoi(hourStr);
  int prayerMin = std::atoi(minStr);

  // Calculate total minutes elapsed since midnight for both times
  long currentMinutes = currentHour * 60 + currentMinute;
  long prayerMinutes = prayerHr * 60 + prayerMin;

  // Find the difference in minutes and convert to seconds
  long diffInMinutes = prayerMinutes - currentMinutes;
  return diffInMinutes * 60;
}

#include <QObject>
#include <QList>
#include <QQmlListProperty>

class MyObject : public QObject {
    Q_OBJECT
    Q_PROPERTY(QQmlListProperty<int> keys READ getKeys NOTIFY keysChanged)

public:
    explicit MyObject(QObject *parent = nullptr) : QObject(parent) {}

    QQmlListProperty<int> getKeys() {
        return QQmlListProperty<int>(this, this, &MyObject::addKey, &MyObject::getKeyCount, &MyObject::getKeyAt, &MyObject::removeAllKeys);
    }

signals:
    void keysChanged();

private:
    QList<int> m_keys;

    static void addKey(QQmlListProperty<int> *property, int key) {
        MyObject *obj = qobject_cast<MyObject *>(property->contextObject);
        if (obj) {
            obj->m_keys.append(key);
            emit obj->keysChanged();
        }
    }

    static int getKeyCount(QQmlListProperty<int> *property) {
        MyObject *obj = qobject_cast<MyObject *>(property->contextObject);
        return obj ? obj->m_keys.size() : 0;
    }

    static int getKeyAt(QQmlListProperty<int> *property, int index) {
        MyObject *obj = qobject_cast<MyObject *>(property->contextObject);
        return obj && index >= 0 && index < obj->m_keys.size() ? obj->m_keys.at(index) : 0;
    }

    static void removeAllKeys(QQmlListProperty<int> *property) {
        MyObject *obj = qobject_cast<MyObject *>(property->contextObject);
        if (obj) {
            obj->m_keys.clear();
            emit obj->keysChanged();
        }
    }
};

