#include <algorithm>

// Compute the edit distance between two strings using dynamic programming
int computeEditDistance(const std::string& source, const std::string& target) {
    int lenSrc = source.length();
    int lenTar = target.length();

    // Create a 2D table to store distances
    std::vector<std::vector<int>> distTable(lenSrc + 1, std::vector<int>(lenTar + 1, 0));

    // Initialize base cases: transforming empty string to other string
    for (int i = 0; i <= lenSrc; ++i) {
        distTable[i][0] = i;
    }
    for (int j = 0; j <= lenTar; ++j) {
        distTable[0][j] = j;
    }

    // Fill the table using bottom-up approach
    for (int i = 1; i <= lenSrc; ++i) {
        for (int j = 1; j <= lenTar; ++j) {
            if (source[i - 1] == target[j - 1]) {
                // Characters match, no operation needed
                distTable[i][j] = distTable[i - 1][j - 1];
            } else {
                // Take minimum of three operations: insert, delete, replace
                int minPrev = std::min(distTable[i - 1][j],    // deletion
                                       std::min(distTable[i][j - 1],   // insertion
                                                distTable[i - 1][j - 1])); // replacement
                distTable[i][j] = 1 + minPrev;
            }
        }
    }

    return distTable[lenSrc][lenTar];
}

int main() {
    std::string firstString = "kitten";
    std::string secondString = "sitting";
    int result = computeEditDistance(firstString, secondString);
    std::cout << "Levenshtein Distance: " << result << std::endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int findLongestAlternatingSubseq(vector<int>& arr) {
    int size = arr.size();
    if (size <= 1) {
        return size;
    }

    // altInc[i] = length of longest alternating subsequence ending at i with last step going up
    // altDec[i] = length of longest alternating subsequence ending at i with last step going down
    vector<int> altInc(size, 1);
    vector<int> altDec(size, 1);

    int best = 1;
    int idx = 1;

    while (idx < size) {
        int prev = 0;
        while (prev < idx) {
            if (arr[idx] > arr[prev]) {
                altInc[idx] = max(altInc[idx], altDec[prev] + 1);
            } else if (arr[idx] < arr[prev]) {
                altDec[idx] = max(altDec[idx], altInc[prev] + 1);
            }
            prev++;
        }
        if (altInc[idx] > best) {
            best = altInc[idx];
        }
        if (altDec[idx] > best) {
            best = altDec[idx];
        }
        idx++;
    }

    return best;
}

