const int GRID_SIZE = 9;

// Display the Sudoku board
void displayBoard(char board[GRID_SIZE][GRID_SIZE]) {
    for (int row = 0; row < GRID_SIZE; ++row) {
        for (int col = 0; col < GRID_SIZE; ++col) {
            cout << board[row][col] << " ";
        }
        cout << endl;
    }
}

// Verify if placing 'digit' at position (r, c) is valid
bool isValidPlacement(char board[GRID_SIZE][GRID_SIZE], int r, int c, char digit) {
    // Check row constraint
    for (int i = 0; i < GRID_SIZE; ++i) {
        if (board[r][i] == digit) {
            return false;
        }
    }

    // Check column constraint
    for (int i = 0; i < GRID_SIZE; ++i) {
        if (board[i][c] == digit) {
            return false;
        }
    }

    // Check 3x3 subgrid constraint
    int startRow = (r / 3) * 3;
    int startCol = (c / 3) * 3;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (board[startRow + i][startCol + j] == digit) {
                return false;
            }
        }
    }

    return true;
}

// Solve Sudoku using backtracking
bool solveSudoku(char board[GRID_SIZE][GRID_SIZE]) {
    int r = -1, c = -1;
    bool foundEmpty = false;

    // Locate the first empty cell ('.')
    for (r = 0; r < GRID_SIZE; ++r) {
        for (c = 0; c < GRID_SIZE; ++c) {
            if (board[r][c] == '.') {
                foundEmpty = true;
                break;
            }
        }
        if (foundEmpty) break;
    }

    // If no empty cell remains, puzzle is solved
    if (!foundEmpty) {
        return true;
    }

    // Try digits '1' through '9'
    for (char digit = '1'; digit <= '9'; ++digit) {
        if (isValidPlacement(board, r, c, digit)) {
            board[r][c] = digit;

            if (solveSudoku(board)) {
                return true;
            }

            // Backtrack if solution not found
            board[r][c] = '.';
        }
    }

    return false;
}

int main() {
    char board[GRID_SIZE][GRID_SIZE] = {
        {'5', '3', '.', '.', '7', '.', '.', '.', '.'},
        {'6', '.', '.', '1', '9', '5', '.', '.', '.'},
        {'.', '9', '8', '.', '.', '.', '.', '6', '.'},
        {'8', '.', '.', '.', '6', '.', '.', '.', '3'},
        {'4', '.', '.', '8', '.', '3', '.', '.', '1'},
        {'7', '.', '.', '.', '2', '.', '.', '.', '6'},
        {'.', '6', '.', '.', '.', '.', '2', '8', '.'},
        {'.', '.', '.', '4', '1', '9', '.', '.', '5'},
        {'.', '.', '.', '.', '8', '.', '.', '7', '9'}
    };

    if (solveSudoku(board)) {
        cout << "Sudoku solution:" << endl;
        displayBoard(board);
    } else {
        cout << "No solution exists." << endl;
    }

