struct DataStruct
{
    unsigned char* data;
    int len;
};

extern "C" DLLAPI int API_ReadFile(const wchar_t* filename, DataStruct** outData)
{
    // Open file in binary mode using alternative approach
    FILE* handle = nullptr;
    #ifdef _WIN32
        _wfopen_s(&handle, filename, L"rb");
    #else
        // For non-Windows platforms, convert wide string to narrow
        // This is a simplified conversion - production code would need proper encoding handling
        char path[1024];
        swprintf(path, 1024, L"%s", filename); // Note: this may not work for all locales
        handle = fopen(path, "rb");
    #endif

    if (handle == nullptr)
    {
        return -1; // Failed to open file
    }

    // Determine file size using alternative method
    fseek(handle, 0, SEEK_END);
    long size = ftell(handle);
    rewind(handle); // Reset file position to beginning

    // Allocate output structure and data buffer
    *outData = new DataStruct();
    (*outData)->data = new unsigned char[size];
    (*outData)->len = static_cast<int>(size);

    // Read file contents
    size_t actualRead = fread((*outData)->data, sizeof(unsigned char), size, handle);
    fclose(handle);

    // Validate read operation
    if (actualRead != static_cast<size_t>(size))
    {
        delete[] (*outData)->data;
        delete *outData;
        return -2; // Incomplete read
    }

    return 0; // File successfully loaded
}

extern "C" DLLAPI void API_FreeData(DataStruct* data)
{
    if (data != nullptr)
    {
        // Clean up allocated resources
        delete[] data->data;
        delete data;
    }
}

#include <windows.h>
#include <tlhelp32.h>

BOOL InjectDLL(DWORD dwProcessId, const char* szDllPath) {
    // Open the target process with full access rights
    HANDLE hProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, dwProcessId);
    if (hProcess == NULL) {
        return FALSE;
    }

    // Allocate memory in the remote process for the DLL path string
    SIZE_T nLength = strlen(szDllPath) + 1;
    LPVOID pRemoteBuffer = VirtualAllocEx(hProcess, NULL, nLength, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (pRemoteBuffer == NULL) {
        CloseHandle(hProcess);
        return FALSE;
    }

    // Write the DLL path into the allocated memory of the remote process
    if (!WriteProcessMemory(hProcess, pRemoteBuffer, (LPVOID)szDllPath, nLength, NULL)) {
        VirtualFreeEx(hProcess, pRemoteBuffer, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return FALSE;
    }

    // Get the address of LoadLibraryA from kernel32.dll
    HMODULE hKernel32 = GetModuleHandleA("kernel32.dll");
    if (hKernel32 == NULL) {
        VirtualFreeEx(hProcess, pRemoteBuffer, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return FALSE;
    }

    FARPROC pLoadLibraryA = GetProcAddress(hKernel32, "LoadLibraryA");
    if (pLoadLibraryA == NULL) {
        VirtualFreeEx(hProcess, pRemoteBuffer, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return FALSE;
    }

    // Create a remote thread to execute LoadLibraryA with the DLL path as argument
    HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0, 
        (LPTHREAD_START_ROUTINE)pLoadLibraryA, 
        pRemoteBuffer, 0, NULL);
    if (hThread == NULL) {
        VirtualFreeEx(hProcess, pRemoteBuffer, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return FALSE;
    }

    // Wait for the remote thread to complete
    WaitForSingleObject(hThread, INFINITE);

    // Retrieve the exit code of the remote thread (return value of LoadLibraryA)
    DWORD dwExitCode = 0;
    GetExitCodeThread(hThread, &dwExitCode);

    // Clean up resources
    CloseHandle(hThread);
    VirtualFreeEx(hProcess, pRemoteBuffer, 0, MEM_RELEASE);
    CloseHandle(hProcess);

    // Return TRUE if LoadLibraryA succeeded (non-zero exit code)
    return (dwExitCode != 0);
}

