// Compute the nth Fibonacci number using iterative approach
int fibonacci(int position) {
    if (position == 0) return 0;
    if (position == 1) return 1;

    int prev = 0, curr = 1, next;
    for (int index = 2; index <= position; ++index) {
        next = prev + curr;
        prev = curr;
        curr = next;
    }
    return curr;
}

int main() {
    int n = 10;
    std::cout << "Fibonacci number at position " << n << " is " << fibonacci(n) << std::endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

// Function to solve 0/1 Knapsack problem using dynamic programming (bottom-up approach)
int solveKnapsack(int capacity, vector<int>& weights, vector<int>& values, int itemCount) {
    // Create a 2D DP table where dp[i][w] represents the maximum value 
    // achievable with first i items and capacity w
    vector<vector<int>> dp(itemCount + 1, vector<int>(capacity + 1, 0));

    // Fill the DP table iteratively
    for (int item = 1; item <= itemCount; ++item) {
        for (int currentWeight = 0; currentWeight <= capacity; ++currentWeight) {
            // Base case: no items or zero capacity gives zero value
            if (item == 0 || currentWeight == 0) {
                dp[item][currentWeight] = 0;
            }
            // If current item's weight is within the remaining capacity
            else if (weights[item - 1] <= currentWeight) {
                // Choose maximum between including and excluding the current item
                int includeItem = values[item - 1] + dp[item - 1][currentWeight - weights[item - 1]];
                int excludeItem = dp[item - 1][currentWeight];
                dp[item][currentWeight] = max(includeItem, excludeItem);
            }
            // If current item cannot be included due to weight constraint
            else {
                dp[item][currentWeight] = dp[item - 1][currentWeight];
            }
        }
    }

    // Return the maximum value achievable with all items and given capacity
    return dp[itemCount][capacity];
}

int main() {
    // Given problem instance
    vector<int> profits = {60, 100, 120};
    vector<int> sizes = {10, 20, 30};
    int maxCapacity = 50;
    int totalItems = profits.size();

    // Compute and display the optimal solution
    cout << "Maximum profit in 0/1 Knapsack: " << solveKnapsack(maxCapacity, sizes, profits, totalItems) << endl;

    return 0;
}

