// Game constants
const int SCREEN_WIDTH = 800;
const int SCREEN_HEIGHT = 600;
const float PADDLE_VELOCITY = 5.0f;
const float BALL_DIAMETER = 20.0f; // diameter instead of radius
const float BASE_BALL_SPEED = 3.0f;

// Paddle class for player control
class Paddle {
public:
    sf::RectangleShape rect;
    float moveSpeed;

    Paddle(float startX, float startY, float width, float height, float velocity) {
        rect.setPosition(startX, startY);
        rect.setSize({width, height});
        rect.setFillColor(sf::Color::White);
        moveSpeed = velocity;
    }

    void goUp() {
        sf::Vector2f currentPos = rect.getPosition();
        if (currentPos.y > 0.0f) {
            rect.move(0.0f, -moveSpeed);
        }
    }

    void goDown() {
        sf::Vector2f currentPos = rect.getPosition();
        if (currentPos.y + rect.getSize().y < SCREEN_HEIGHT) {
            rect.move(0.0f, moveSpeed);
        }
    }
};

// Ball class with movement and collision logic
class Ball {
public:
    sf::CircleShape circle;
    sf::Vector2f velocityDirection;
    float travelSpeed;

    Ball(float centerX, float centerY, float radius) {
        circle.setRadius(radius);
        circle.setOrigin(radius, radius); // center the origin
        circle.setPosition(centerX, centerY);
        circle.setFillColor(sf::Color::White);
        velocityDirection = {1.0f, 1.0f};
        travelSpeed = BASE_BALL_SPEED;
    }

    void moveAndBounce() {
        sf::Vector2f currentPos = circle.getPosition();
        currentPos += velocityDirection * travelSpeed;

        // Check horizontal boundaries (left/right walls)
        if (currentPos.x <= 0.0f || currentPos.x >= SCREEN_WIDTH) {
            velocityDirection.x = -velocityDirection.x;
        }

        // Check vertical boundaries (top/bottom walls)
        if (currentPos.y <= 0.0f || currentPos.y >= SCREEN_HEIGHT) {
            velocityDirection.y = -velocityDirection.y;
        }

        circle.setPosition(currentPos);
    }
};

int main() {
    sf::RenderWindow gameWindow(sf::VideoMode(SCREEN_WIDTH, SCREEN_HEIGHT), "Pong");

    // Initialize game objects
    Paddle leftPlayer(30.0f, SCREEN_HEIGHT / 2.0f - 50.0f, 20.0f, 100.0f, PADDLE_VELOCITY);
    Paddle rightPlayer(SCREEN_WIDTH - 90.0f, SCREEN_HEIGHT / 2.0f - 50.0f, 20.0f, 100.0f, PADDLE_VELOCITY);
    Ball gameBall(SCREEN_WIDTH / 2.0f, SCREEN_HEIGHT / 2.0f, BALL_DIAMETER / 2.0f);

    while (gameWindow.isOpen()) {
        sf::Event inputEvent;
        while (gameWindow.pollEvent(inputEvent)) {
            if (inputEvent.type == sf::Event::Closed) {
                gameWindow.close();
            }
        }

        // Player 1 controls (W/S keys)
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::W)) {
            leftPlayer.goUp();
        }
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::S)) {
            leftPlayer.goDown();
        }

        // Simple AI for Player 2
        float ballY = gameBall.circle.getPosition().y;
        float paddleCenterY = rightPlayer.rect.getPosition().y + rightPlayer.rect.getSize().y / 2.0f;

        if (ballY > paddleCenterY + 10.0f) {
            rightPlayer.goDown();
        } else if (ballY < paddleCenterY - 10.0f) {
            rightPlayer.goUp();
        }

        // Update ball position
        gameBall.moveAndBounce();

        // Render frame
        gameWindow.clear(sf::Color::Black);
        gameWindow.draw(leftPlayer.rect);
        gameWindow.draw(rightPlayer.rect);
        gameWindow.draw(gameBall.circle);
        gameWindow.display();
    }

    return 0;
}

#include <algorithm>
#include <cmath>

// Redefine the node structure with slightly different naming
struct TreeNode {
    int value;
    int depth;
    TreeNode* smaller;
    TreeNode* larger;
};

// Retrieve the depth of a given tree node
int getDepth(TreeNode* node) {
    if (node == nullptr)
        return 0;
    return node->depth;
}

// Construct a fresh tree node with specified value
TreeNode* createNode(int value) {
    TreeNode* newNodePtr = new TreeNode();
    newNodePtr->value = value;
    newNodePtr->smaller = nullptr;
    newNodePtr->larger = nullptr;
    newNodePtr->depth = 1; // Newly inserted nodes start at leaf level
    return newNodePtr;
}

// Perform right rotation on subtree rooted at 'pivot'
TreeNode* rotateRight(TreeNode* pivot) {
    TreeNode* root = pivot->smaller;
    TreeNode* subtree = root->larger;

    // Reconnect subtrees after rotation
    root->larger = pivot;
    pivot->smaller = subtree;

    // Recalculate depths for affected nodes
    pivot->depth = 1 + std::max(getDepth(pivot->smaller), getDepth(pivot->larger));
    root->depth = 1 + std::max(getDepth(root->smaller), getDepth(root->larger));

    return root;
}

// Perform left rotation on subtree rooted at 'pivot'
TreeNode* rotateLeft(TreeNode* pivot) {
    TreeNode* root = pivot->larger;
    TreeNode* subtree = root->smaller;

    // Reconnect subtrees after rotation
    root->smaller = pivot;
    pivot->larger = subtree;

    // Recalculate depths for affected nodes
    pivot->depth = 1 + std::max(getDepth(pivot->smaller), getDepth(pivot->larger));
    root->depth = 1 + std::max(getDepth(root->smaller), getDepth(root->larger));

    return root;
}

// Compute balance factor: height(left) - height(right)
int getBalanceFactor(TreeNode* node) {
    if (node == nullptr)
        return 0;
    return getDepth(node->smaller) - getDepth(node->larger);
}

// Insert a value into AVL tree and maintain balance
TreeNode* addValue(TreeNode* root, int value) {
    // Standard BST insertion logic
    if (root == nullptr)
        return createNode(value);

    if (value < root->value)
        root->smaller = addValue(root->smaller, value);
    else if (value > root->value)
        root->larger = addValue(root->larger, value);
    else // Duplicate values not permitted
        return root;

    // Update current node's depth based on children
    root->depth = 1 + std::max(getDepth(root->smaller), getDepth(root->larger));

    // Check balance and perform rotations if needed
    int bf = getBalanceFactor(root);

    // Four possible imbalance cases

    // Left-Left imbalance
    if (bf > 1 && value < root->smaller->value)
        return rotateRight(root);

    // Right-Right imbalance
    if (bf < -1 && value > root->larger->value)
        return rotateLeft(root);

    // Left-Right imbalance
    if (bf > 1 && value > root->smaller->value) {
        root->smaller = rotateLeft(root->smaller);
        return rotateRight(root);
    }

    // Right-Left imbalance
    if (bf < -1 && value < root->larger->value) {
        root->larger = rotateRight(root->larger);
        return rotateLeft(root);
    }

    // Return unchanged node if balanced
    return root;
}

