using namespace std;

const int GRID_SIZE = 9;

// Display the Sudoku board
void displayBoard(int board[GRID_SIZE][GRID_SIZE]) {
    for (int r = 0; r < GRID_SIZE; ++r) {
        for (int c = 0; c < GRID_SIZE; ++c)
            cout << board[r][c] << " ";
        cout << "\n";
    }
}

// Verify if placing 'value' at position (row, col) is valid
bool isValidPlacement(int board[GRID_SIZE][GRID_SIZE], int row, int col, int value) {
    // Check row for duplicates
    for (int k = 0; k < GRID_SIZE; ++k)
        if (board[row][k] == value)
            return false;

    // Check column for duplicates
    for (int k = 0; k < GRID_SIZE; ++k)
        if (board[k][col] == value)
            return false;

    // Check 3x3 subgrid for duplicates
    int baseRow = row - (row % 3);
    int baseCol = col - (col % 3);
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j)
            if (board[baseRow + i][baseCol + j] == value)
                return false;

    return true;
}

// Solve Sudoku using recursive backtracking
bool solveSudoku(int board[GRID_SIZE][GRID_SIZE]) {
    int r, c;
    bool foundEmpty = false;

    // Find first empty cell (represented by 0)
    for (r = 0; r < GRID_SIZE; ++r) {
        for (c = 0; c < GRID_SIZE; ++c) {
            if (board[r][c] == 0) {
                foundEmpty = true;
                break;
            }
        }
        if (foundEmpty) break;
    }

    // If no empty cells remain, puzzle is solved
    if (!foundEmpty) return true;

    // Try numbers 1 through 9 in the empty cell
    for (int num = 1; num <= 9; ++num) {
        if (isValidPlacement(board, r, c, num)) {
            board[r][c] = num;
            if (solveSudoku(board))
                return true;
            board[r][c] = 0; // Backtrack
        }
    }

    return false;
}

int main() {
    int puzzle[GRID_SIZE][GRID_SIZE];

    // Input Sudoku puzzle
    cout << "Enter the Sudoku puzzle (use 0 for blank cells):\n";
    for (int r = 0; r < GRID_SIZE; ++r)
        for (int c = 0; c < GRID_SIZE; ++c)
            cin >> puzzle[r][c];

    // Attempt to solve and output result
    if (solveSudoku(puzzle)) {
        cout << "Solved Sudoku:\n";
        displayBoard(puzzle);
    } else {
        cout << "No solution possible.\n";
    }

    return 0;
}

