// Find the index of the maximum element in a vector
int locateMaxIndex(const std::vector<int>& data) {
    if (data.empty()) {
        return -1; // Indicate empty container with -1
    }

    int bestIndex = 0;
    int currentIndex = 1;

    while (currentIndex < static_cast<int>(data.size())) {
        if (data[currentIndex] > data[bestIndex]) {
            bestIndex = currentIndex;
        }
        currentIndex++;
    }

    return bestIndex;
}

int main() {
    std::vector<int> values = {10, 20, 30, 40, 50};
    int position = locateMaxIndex(values);
    std::cout << "Position of the largest value: " << position << std::endl;
    return 0;
}

