// Finite State Machine implementation for string recognition
class Automaton {
public:
    int start_state;
    set<int> final_states;
    unordered_map<int, unordered_map<char, int>> state_transitions;

    // Check if the input string is accepted by the automaton
    bool recognize(const string& sequence) {
        int current = start_state;
        for (char ch : sequence) {
            auto it = state_transitions.find(current);
            if (it == state_transitions.end() || it->second.find(ch) == it->second.end()) {
                return false; // Transition not defined for current state and character
            }
            current = state_transitions[current][ch];
        }
        return final_states.count(current) > 0;
    }
};

