#include <cuda_runtime.h>

// CUDA Kernel: computes value based on thread indices
__global__ void compute3DIndices(float *deviceArray, int width, int height, int depth) {
    int posX = blockIdx.x * blockDim.x + threadIdx.x;
    int posY = blockIdx.y * blockDim.y + threadIdx.y;
    int posZ = blockIdx.z * blockDim.z + threadIdx.z;

    if (posX < width && posY < height && posZ < depth) {
        // Compute linear index and assign sum of coordinates
        int idx = posZ * width * height + posY * width + posX;
        deviceArray[idx] = static_cast<float>(posX + posY + posZ);
    }
}

int main() {
    // Define dimensions
    int dimX = 2, dimY = 2, dimZ = 2;
    int totalElements = dimX * dimY * dimZ;
    int bytes = totalElements * sizeof(float);

    // Allocate host buffer
    float *hostData = (float *)malloc(bytes);

    // Allocate device memory
    float *devicePtr;
    cudaMalloc((void **)&devicePtr, bytes);

    // Transfer initial data (zeroed by default)
    cudaMemcpy(devicePtr, hostData, bytes, cudaMemcpyHostToDevice);

    // Configure execution configuration
    dim3 blockSize(16, 16, 16);
    dim3 gridSize((dimX + blockSize.x - 1) / blockSize.x,
                  (dimY + blockSize.y - 1) / blockSize.y,
                  (dimZ + blockSize.z - 1) / blockSize.z);

    // Launch kernel
    compute3DIndices<<<gridSize, blockSize>>>(devicePtr, dimX, dimY, dimZ);

    // Retrieve results to host
    cudaMemcpy(hostData, devicePtr, bytes, cudaMemcpyDeviceToHost);

    // Output results in nested loop format
    for (int k = 0; k < dimZ; ++k) {
        for (int j = 0; j < dimY; ++j) {
            for (int i = 0; i < dimX; ++i) {
                std::cout << "hostData[" << k << "][" << j << "][" << i << "] = "
                          << hostData[k * dimX * dimY + j * dimX + i] << std::endl;
            }
        }
    }

    // Cleanup resources
    free(hostData);
    cudaFree(devicePtr);

    return 0;
}

