// MQTT server configuration
const char* broker_addr = "your_MQTT_broker";
const uint16_t broker_port = 1883;
const char* mqtt_username = "your_MQTT_user";
const char* mqtt_token = "your_MQTT_password";

// Topic names for sensor data
const char* topic_temp = "home/air_quality/temperature";
const char* topic_hum = "home/air_quality/humidity";
const char* topic_pres = "home/air_quality/pressure";
const char* topic_co2_val = "home/air_quality/co2";

// Sensor objects
Adafruit_BME280 bme_sensor;
MH_Z19 co2_sensor(Serial2);

WiFiClient esp_client;
PubSubClient mqtt_client(esp_client);

void initialize_system() {
  Serial.begin(115200);

  // Connect to Wi-Fi network
  WiFi.begin(wifi_ssid, wifi_pass);
  while (WiFi.status() != WL_CONNECTED) {
    delay(1000);
    Serial.println("Establishing Wi-Fi connection...");
  }
  Serial.println("Wi-Fi connected successfully");

  // Configure and connect to MQTT broker
  mqtt_client.setServer(broker_addr, broker_port);
  mqtt_client.setCallback(message_handler);

  while (!mqtt_client.connected()) {
    Serial.println("Connecting to MQTT broker...");
    if (mqtt_client.connect("ESP32_Client", mqtt_username, mqtt_token)) {
      Serial.println("MQTT broker connection established");
    } else {
      Serial.print("Connection failed. Error code: ");
      Serial.println(mqtt_client.state());
      delay(2000);
    }
  }

  // Initialize BME280 sensor
  if (!bme_sensor.begin(0x76)) {
    Serial.println("BME280 sensor not detected. Verify hardware connections.");
    while (true);
  }
}

void loop() {
  if (!mqtt_client.connected()) {
    reconnect_to_mqtt();
  }
  mqtt_client.loop();

  // Acquire sensor readings
  float temp_reading = bme_sensor.readTemperature();
  float hum_reading = bme_sensor.readHumidity();
  float pres_reading = bme_sensor.readPressure() / 100.0F;
  int co2_reading = co2_sensor.getCO2();

  // Send data via MQTT
  mqtt_client.publish(topic_temp, String(temp_reading).c_str());
  mqtt_client.publish(topic_hum, String(hum_reading).c_str());
  mqtt_client.publish(topic_pres, String(pres_reading).c_str());
  mqtt_client.publish(topic_co2_val, String(co2_reading).c_str());

  delay(5000); // Wait before next measurement cycle
}

void reconnect_to_mqtt() {
  while (!mqtt_client.connected()) {
    Serial.println("Attempting to reconnect to MQTT...");
    if (mqtt_client.connect("ESP32_Client", mqtt_username, mqtt_token)) {
      Serial.println("Reconnected to MQTT successfully");
    } else {
      Serial.print("Reconnection failed. Status: ");
      Serial.println(mqtt_client.state());
      delay(2000);
    }
  }
}

void message_handler(char* topic_name, byte* payload_data, unsigned int payload_len) {
  Serial.print("Received message on topic [");
  Serial.print(topic_name);
  Serial.print("]: ");
  for (unsigned int idx = 0; idx < payload_len; idx++) {
    Serial.print((char)payload_data[idx]);
  }
  Serial.println();
}

