// Helper function to exchange two elements in the array if needed based on sorting direction
__device__ void exchangeElements(int *data, int pos1, int pos2, int sortDirection) {
    // For ascending (direction=1): swap if left > right
    // For descending (direction=0): swap if left < right
    bool shouldSwap = false;
    if (sortDirection == 1 && data[pos1] > data[pos2]) {
        shouldSwap = true;
    } else if (sortDirection == 0 && data[pos1] < data[pos2]) {
        shouldSwap = true;
    }

    if (shouldSwap) {
        int temp = data[pos1];
        data[pos1] = data[pos2];
        data[pos2] = temp;
    }
}

// Device kernel: performs one stage of bitonic merging
__global__ void mergeBitonicSequence(int *buffer, int totalSize, int subsequenceLength, int orderType) {
    int index = threadIdx.x + blockIdx.x * blockDim.x;
    int halfStep = subsequenceLength / 2;

    // Only process elements that belong to appropriate halves based on direction
    if (index < totalSize && (index / subsequenceLength) % 2 == orderType) {
        // Compare and possibly swap with corresponding element in the other half
        if ((index / halfStep) % 2 == 0) {
            exchangeElements(buffer, index, index + halfStep, orderType);
        }
    }
}

// Device kernel: builds a bitonic sequence by recursively merging smaller sequences
__global__ void buildBitonicSequence(int *data, int size, int currentLength, int sortDir) {
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    int gap = currentLength / 2;

    if (idx < size) {
        // Iterate through all comparison steps within this level
        for (int step = gap; step > 0; step /= 2) {
            int partnerIdx = idx ^ step;

            // Ensure we only compare each pair once
            if (partnerIdx > idx) {
                // Determine comparison direction based on position in bitonic structure
                if ((idx & currentLength) == 0) {
                    exchangeElements(data, idx, partnerIdx, sortDir);
                } else {
                    exchangeElements(data, idx, partnerIdx, !sortDir);
                }
            }

            __syncthreads(); // Synchronize threads to maintain correctness
        }
    }
}

// Host function to perform parallel bitonic sort using CUDA
void parallelBitonicSort(int *inputArray, int n) {
    int *gpuBuffer;
    int bytes = n * sizeof(int);

    // Allocate memory on GPU and copy input data
    cudaMalloc((void**)&gpuBuffer, bytes);
    cudaMemcpy(gpuBuffer, inputArray, bytes, cudaMemcpyHostToDevice);

    // Configure grid and block dimensions
    int blockSize = 256;
    int gridSize = (n + blockSize - 1) / blockSize;
    dim3 gridDim(gridSize, 1, 1);
    dim3 blockDim(blockSize, 1, 1);

    // Perform bitonic sort by expanding sorted subsequences
    for (int seqLen = 2; seqLen <= n; seqLen *= 2) {
        for (int dir = 1; dir >= 0; dir--) {
            buildBitonicSequence<<<gridDim, blockDim>>>(gpuBuffer, n, seqLen, dir);
        }
    }

    // Copy result back to host
    cudaMemcpy(inputArray, gpuBuffer, bytes, cudaMemcpyDeviceToHost);
    cudaFree(gpuBuffer);
}

// Sequential version of bitonic sort
void sequentialBitonicSort(int *arr, int n) {
    for (int len = 2; len <= n; len *= 2) {
        for (int dir = 1; dir >= 0; dir--) {
            for (int i = 0; i < n; i++) {
                if ((i & len) == 0) {
                    for (int j = 0; j < len / 2; j++) {
                        int partner = i ^ (j << 1);
                        if (partner < n) {
                            exchangeElements(arr, i, partner, dir);
                        }
                    }
                }
            }
        }
    }
}

int main() {
    int size = 16;
    int data[size] = {12, 9, 15, 6, 10, 8, 5, 13, 7, 11, 14, 4, 1, 3, 2, 0};

    printf("Original Array:\n");
    for (int i = 0; i < size; i++) {
        printf("%d ", data[i]);
    }

    printf("\n\n");

    // Sort using sequential implementation
    sequentialBitonicSort(data, size);

    printf("Sequential Sorted Array:\n");
    for (int i = 0; i < size; i++) {
        printf("%d ", data[i]);
    }

    printf("\n\n");

    // Reset array for parallel sort (since it's already sorted)
    int resetData[size] = {12, 9, 15, 6, 10, 8, 5, 13, 7, 11, 14, 4, 1, 3, 2, 0};
    parallelBitonicSort(resetData, size);

    printf("Parallel Sorted Array:\n");
    for (int i = 0; i < size; i++) {
        printf("%d ", resetData[i]);
    }

    printf("\n");

    return 0;
}

