// Precomputed masks for 2, 4, 8, 16, 32 bit repeating patterns
const uint64_t masks[] = {
    0xAAAAAAAAAAAAAAAA,  // 0101010101010101010101010101010101010101010101010101010101010101
    0xCCCCCCCCCCCCCCCC,  // 0011001100110011001100110011001100110011001100110011001100110011
    0xF0F0F0F0F0F0F0F0,  // 0000111100001111000011110000111100001111000011110000111100001111
    0xFF00FF00FF00FF00,  // 0000000011111111000000001111111100000000111111110000000011111111
    0xFFFF0000FFFF0000   // 0000000000000000111111111111111100000000000000001111111111111111
};

// Function to check if the 128-bit block matches a repeating pattern
bool hasRepeatingPattern(uint64_t data[2], int period, int& offset) {
    uint64_t patternMask = masks[period / 2];
    uint64_t fullBlock = (data[1] << 64) | data[0];

    for (int pos = 0; pos < period; ++pos) {
        uint64_t rotatedMask = (patternMask >> pos) | (patternMask << (128 - pos));
        uint64_t shiftedBlock = fullBlock >> pos;

        if ((fullBlock & rotatedMask) == (fullBlock & shiftedBlock)) {
            offset = pos;
            return true;
        }
    }
    return false;
}

// Main function to identify the repeating pattern and its shift
std::pair<int, int> detectPattern(uint64_t data[2]) {
    const int candidatePeriods[] = {2, 4, 8, 16, 32};
    int position = 0;

    for (int len : candidatePeriods) {
        if (hasRepeatingPattern(data, len, position)) {
            return {len, position};
        }
    }

    return {-1, -1}; // No matching pattern found
}

int main() {
    uint64_t data[2] = {0x00001111000011110000111100001111, 0x00001111000011110000111100001111};

    auto [length, offset] = detectPattern(data);

    if (length != -1) {
        std::cout << "Pattern length: " << length << ", Shift: " << offset << std::endl;
    } else {
        std::cout << "No matching pattern found." << std::endl;
    }

    return 0;
}

#include <functional>

template<typename T>
struct compare_entries {
    bool operator()(const T& first, const T& second) const {
        if (first._cost == second._cost) {
            return first._id < second._id;
        }
        return second._cost < first._cost;
    }
};

#include <SuperpoweredFilter.h>
#include <SuperpoweredShortInt.h>

extern "C" {

extern Superpowered::Filter *filter;
extern bool bIsPlaying;

long Java_com_yourpackage_AudioProcessor_audioProcessingCallback(JNIEnv *env, jobject thiz, jshortArray input, jshortArray output, jint sampleCount, jlong userData) {
    if (!bIsPlaying) return 0;

    jshort *inputData = env->GetShortArrayElements(input, nullptr);
    jshort *outputData = env->GetShortArrayElements(output, nullptr);

    float *audioBuffer = new float[sampleCount];
    SuperpoweredShortInt::shortToFloat(inputData, audioBuffer, sampleCount);

    filter->process(audioBuffer, audioBuffer, sampleCount);

    SuperpoweredShortInt::floatToShort(audioBuffer, outputData, sampleCount);

    env->ReleaseShortArrayElements(input, inputData, 0);
    env->ReleaseShortArrayElements(output, outputData, 0);

    delete[] audioBuffer;

    return 0;
}

