#define SCREEN_WIDTH 800
#define SCREEN_HEIGHT 600

// Structure to hold screen capture information
struct ScreenCaptureBuffer
{
    unsigned int width;
    unsigned int height;
    unsigned int rowPitch;
    unsigned char* pixelData;
};

// Global Direct3D and imaging components
HWND mainHwnd = nullptr;
ComPtr<ID3D11Device> d3dDevice = nullptr;
ComPtr<ID3D11DeviceContext> immediateContext = nullptr;
ComPtr<IDXGISwapChain> swapChain = nullptr;
ComPtr<ID3D11RenderTargetView> renderTargetView = nullptr;
ComPtr<ID3D11Texture2D> captureTexture = nullptr;
ComPtr<ID3D11Texture2D> stagingTexture = nullptr;
ComPtr<ID3D11ShaderResourceView> shaderResourceView = nullptr;
ComPtr<ID3D11SamplerState> samplerState = nullptr;
ComPtr<IWICImagingFactory> wicFactory = nullptr;

// Function declarations
LRESULT CALLBACK MainWndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam);
void SetupDirect3D(HWND hwnd);
void AcquireScreen(ScreenCaptureBuffer& buffer);
void TransferToTexture(const ScreenCaptureBuffer& buffer);
void ExportTextureAsPng(LPCWSTR filePath);
