// Define output and input parameter typemaps for SWIG
%apply int *OUTPUT { int *result };
%apply int *INPUT { int *x, int *y };

// Custom typemap for three integer array pointers (a, b, c)
%typemap(in) (int *a, int *b, int *c) {
    // Check if the input is a numpy array
    if (!PyArray_Check($input)) {
        PyErr_SetString(PyExc_TypeError, "Expected a numpy array");
        return NULL;
    }

    // Get the first array (a)
    PyArrayObject *arr_a = (PyArrayObject *)$input;

    // Get the second array (b) from next input argument
    PyArrayObject *arr_b = (PyArrayObject *)$2_input;

    // Get the third array (c) from third input argument
    PyArrayObject *arr_c = (PyArrayObject *)$3_input;

    // Validate data type: must be 32-bit integers
    if (PyArray_TYPE(arr_a) != NPY_INT32 || 
        PyArray_TYPE(arr_b) != NPY_INT32 || 
        PyArray_TYPE(arr_c) != NPY_INT32) {
        PyErr_SetString(PyExc_TypeError, "All arrays must be of int32 type");
        return NULL;
    }

    // Ensure all arrays are one-dimensional
    if (PyArray_NDIM(arr_a) != 1 || 
        PyArray_NDIM(arr_b) != 1 || 
        PyArray_NDIM(arr_c) != 1) {
        PyErr_SetString(PyExc_TypeError, "All arrays must be one-dimensional");
        return NULL;
    }

    // Check that all arrays have identical lengths
    npy_intp len_a = PyArray_DIM(arr_a, 0);
    npy_intp len_b = PyArray_DIM(arr_b, 0);
    npy_intp len_c = PyArray_DIM(arr_c, 0);

    if (len_a != len_b || len_a != len_c) {
        PyErr_SetString(PyExc_ValueError, "Input arrays must have the same size");
        return NULL;
    }

    // Assign raw data pointers to output parameters
    $1 = (int *)PyArray_DATA(arr_a);
    $2 = (int *)PyArray_DATA(arr_b);
    $3 = (int *)PyArray_DATA(arr_c);
}

