// Find the maximum value in an integer array
int findMaximumValue(int values[], int length) {
    if (length <= 0) {
        return INT_MIN;  // Return the smallest possible integer for empty or invalid input
    }
    int maxVal = values[0];
    int index = 1;
    while (index < length) {
        if (values[index] > maxVal) {
            maxVal = values[index];
        }
        index++;
    }
    return maxVal;
}

int main() {
    int data[] = {3, 5, 1, 8, 2};
    int count = sizeof(data) / sizeof(data[0]);
    std::cout << "The largest number is: " << findMaximumValue(data, count) << std::endl;
    return 0;
}

