template<class C, typename... Args>
C* ECS::AddComponent(const uint32_t entityId, Args&&... args) {
    const auto componentTypeId = Component<C>::GetTypeID();

    if (componentMasks[entityId].HasComponent(componentTypeId)) {
        return nullptr; // Entity already possesses this component type
    }

    componentMasks[entityId].AddComponent(componentTypeId);
    Archetype* targetArchetype = nullptr;
    C* createdComponent = nullptr;

    Record& entityRecord = entityArchetypeMap[entityId];
    Archetype* previousArchetype = entityRecord.archetype;

    targetArchetype = LocateOrConstructArchetype(entityId);

    if (previousArchetype) {
        TransferEntityToNewArchetype(targetArchetype, previousArchetype, entityId, std::forward<Args>(args)...);
    } else {
        InitializeFirstComponentForEntity(targetArchetype, entityId, componentTypeId, entityRecord, std::forward<Args>(args)...);
    }

    return createdComponent;
}

