#include <iostream>
#include <vector>
#include <algorithm>

// Perform in-place quicksort on the given vector using a different pivot selection strategy
void sortArray(std::vector<int>& data, int start, int end) {
    if (start >= end) return;

    // Choose middle element as pivot (same logic but renamed variables)
    int mid = start + (end - start) / 2;
    int pivotValue = data[mid];

    int low = start;
    int high = end;

    // Partitioning phase with modified loop structure
    while (low <= high) {
        // Move left pointer until finding an element >= pivot
        while (data[low] < pivotValue) {
            low++;
        }

        // Move right pointer until finding an element <= pivot
        while (data[high] > pivotValue) {
            high--;
        }

        // Swap elements and move pointers if needed
        if (low <= high) {
            std::swap(data[low], data[high]);
            low++;
            high--;
        }
    }

    // Recursively sort the left partition
    if (start < high) {
        sortArray(data, start, high);
    }

    // Recursively sort the right partition
    if (low < end) {
        sortArray(data, low, end);
    }
}

int main() {
    std::vector<int> numbers = {3, 6, 8, 10, 1, 2, 1};
    sortArray(numbers, 0, static_cast<int>(numbers.size()) - 1);

    for (int value : numbers) {
        std::cout << value << " ";
    }

    return 0;
}

