// Helper function to calculate byte offset for component data
size_t GetComponentOffset(size_t elementIndex, size_t elementSize) {
    return elementIndex * elementSize;
}

class ComponentDataHandler {
public:
    // Relocate component instance from source to destination archetype
    static void TransferComponentData(const ComponentBase* componentBase, Archetype* sourceArch, Archetype* destArch, size_t srcPos, size_t destPos) {
        size_t componentByteSize = componentBase->GetSize();
        size_t destCurrentCapacity = destArch->entityIds.size() * componentByteSize;

        // Transfer the component data from source to destination
        componentBase->MoveData(&sourceArch->componentData[srcPos], &destArch->componentData[destPos]);

        // Clean up the source component data
        componentBase->DestroyData(&sourceArch->componentData[srcPos]);
    }

    // Exchange two component instances within the same archetype
    static void SwapComponentData(const ComponentBase* componentBase, Archetype* archetype, size_t baseOffset, size_t posA, size_t posB) {
        size_t componentByteSize = componentBase->GetSize();

        // Calculate actual memory positions using byte offsets
        char* addrA = &archetype->componentData[baseOffset] + GetComponentOffset(posA, componentByteSize);
        char* addrB = &archetype->componentData[baseOffset] + GetComponentOffset(posB, componentByteSize);

        // Move data from position A to position B
        componentBase->MoveData(addrA, addrB);

        // Destroy the original data at position A
        componentBase->DestroyData(addrA);
    }

    // Handle component removal with optional swap and allocation
    static void RemoveAndAllocateComponentData(const ComponentBase* componentBase, 
                                              Archetype* sourceArchetype, 
                                              Archetype* targetArchetype, 
                                              size_t srcIndex, 
                                              size_t tgtIndex, 
                                              size_t lastEntityPos, 
                                              size_t currentEntityPos) {
        size_t componentByteSize = componentBase->GetSize();
        size_t targetCurrentSize = targetArchetype->entityIds.size() * componentByteSize;

        // Compute source and destination addresses
        char* srcAddr = &sourceArchetype->componentData[srcIndex] + GetComponentOffset(currentEntityPos, componentByteSize);
        char* tgtAddr = &targetArchetype->componentData[tgtIndex] + targetCurrentSize;

        // Move component data to new location
        componentBase->MoveData(srcAddr, tgtAddr);

        // If not moving the last element, move the last element to fill the gap
        if (currentEntityPos != lastEntityPos) {
            char* replacementSrc = &sourceArchetype->componentData[srcIndex] + GetComponentOffset(lastEntityPos, componentByteSize);
            char* replacementDst = &sourceArchetype->componentData[srcIndex] + GetComponentOffset(currentEntityPos, componentByteSize);

            componentBase->MoveData(replacementSrc, replacementDst);
        }

        // Clean up the moved/removed component data
        char* cleanupAddr = &sourceArchetype->componentData[srcIndex] + GetComponentOffset(lastEntityPos, componentByteSize);
        componentBase->DestroyData(cleanupAddr);
    }
};

