std::string disassemble_bytes(const uint8_t* code, size_t length, uint64_t baseAddr) {
    csh cs_handle;
    cs_insn* instructions;
    size_t instruction_count;
    std::string result;

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &cs_handle) == CS_ERR_OK) {
        // Disassemble as many instructions as possible within the provided byte range
        instruction_count = cs_disasm(cs_handle, code, length, baseAddr, 0, &instructions);

        if (instruction_count > 0) {
            for (size_t idx = 0; idx < instruction_count; ++idx) {
                char line[1024];
                snprintf(line, sizeof(line), "0x%" PRIx64 ":\t%s\t\t%s\n", 
                         instructions[idx].address, 
                         instructions[idx].mnemonic, 
                         instructions[idx].op_str);
                result += line;
            }
            cs_free(instructions, instruction_count);
        } else {
            result = "ERROR: Unable to disassemble provided byte sequence!\n";
        }

        cs_close(&cs_handle);
    } else {
        result = "ERROR: Could not initialize Capstone disassembler!\n";
    }

    return result;
}

