#include <cstddef>

void backsolve(const int* __restrict__ Lp,
               const int* __restrict__ Li,
               const double* __restrict__ Lx,
               const int n,
               double* __restrict__ x) {
    // Process rows in groups of 4 for loop unrolling optimization
    int i = n - 1;
    while (i >= 3) {
        // Process row i
        for (int j = Lp[i]; j < Lp[i + 1]; ++j) {
            x[i] -= Lx[j] * x[Li[j]];
        }

        // Process row i-1
        for (int j = Lp[i - 1]; j < Lp[i]; ++j) {
            x[i - 1] -= Lx[j] * x[Li[j]];
        }

        // Process row i-2
        for (int j = Lp[i - 2]; j < Lp[i - 1]; ++j) {
            x[i - 2] -= Lx[j] * x[Li[j]];
        }

        // Process row i-3
        for (int j = Lp[i - 3]; j < Lp[i - 2]; ++j) {
            x[i - 3] -= Lx[j] * x[Li[j]];
        }

        i -= 4;
    }

    // Handle remaining rows (0 to 3 elements)
    for (int k = (n % 4) - 1; k >= 0; --k) {
        for (int j = Lp[k]; j < Lp[k + 1]; ++j) {
            x[k] -= Lx[j] * x[Li[j]];
        }
    }
}

