// Allocate memory with read-write-execute permissions for JIT execution
void* setup_runtime_region(size_t bytes) {
    void* region = mmap(
        nullptr,
        bytes,
        PROT_READ | PROT_WRITE | PROT_EXEC,
        MAP_PRIVATE | MAP_ANONYMOUS,
        -1,
        0
    );
    if (region == MAP_FAILED) {
        std::cerr << "Memory mapping failed: " << strerror(errno) << std::endl;
        return nullptr;
    }
    return region;
}

// Copy raw bytecode into the allocated executable region
bool populate_code_buffer(void* target, const unsigned char* source, size_t len) {
    if (!target || !source) return false;
    std::memcpy(target, source, len);
    return true;
}

int main() {
    // Open the binary file containing native machine instructions
    int handle = ::open("test.bin", O_RDONLY);
    if (handle < 0) {
        std::perror("Failed to open test.bin");
        return EXIT_FAILURE;
    }

    // Query file size using fstat
    struct stat info{};
    if (::fstat(handle, &info) != 0) {
        std::perror("Failed to get file size");
        ::close(handle);
        return EXIT_FAILURE;
    }

    // Determine length and allocate buffer
    size_t instruction_count = static_cast<size_t>(info.st_size);
    unsigned char buffer[instruction_count];

    // Read entire file contents
    ssize_t actual_read = ::read(handle, buffer, instruction_count);
    ::close(handle);
    if (actual_read != static_cast<ssize_t>(instruction_count)) {
        std::perror("Incomplete read from file");
        return EXIT_FAILURE;
    }

    // Prepare runtime memory for execution
    void* exec_space = setup_runtime_region(instruction_count);
    if (!exec_space) {
        std::cerr << "Unable to allocate executable memory" << std::endl;
        return EXIT_FAILURE;
    }

    // Transfer code into executable region
    if (!populate_code_buffer(exec_space, buffer, instruction_count)) {
        std::cerr << "Code copy operation failed" << std::endl;
        munmap(exec_space, instruction_count);
        return EXIT_FAILURE;
    }

    // Cast to function pointer and invoke
    using ExecutableRoutine = void (*)();
    ExecutableRoutine runner = reinterpret_cast<ExecutableRoutine>(exec_space);
    runner();

    // Release resources
    munmap(exec_space, instruction_count);

    return EXIT_SUCCESS;
}

