// Find the maximum value in a vector of integers
std::optional<int> getMaxValue(const std::vector<int>& values) {
    if (values.empty()) {
        return std::nullopt; // Return empty optional for empty input
    }

    int currentMax = values[0];
    size_t index = 1;

    while (index < values.size()) {
        if (values[index] > currentMax) {
            currentMax = values[index];
        }
        ++index;
    }

    return currentMax;
}

