#include <iostream>

// Define the structure for the BST node
struct Node {
    int data;
    Node* leftChild;
    Node* rightChild;
    Node(int val) : data(val), leftChild(nullptr), rightChild(nullptr) {}
};

// Function to insert a new node into the BST (iterative approach)
Node* addNode(Node* current, int value) {
    if (current == nullptr) {
        return new Node(value);
    }

    Node* temp = current;
    while (true) {
        if (value < temp->data) {
            if (temp->leftChild == nullptr) {
                temp->leftChild = new Node(value);
                break;
            } else {
                temp = temp->leftChild;
            }
        } else if (value > temp->data) {
            if (temp->rightChild == nullptr) {
                temp->rightChild = new Node(value);
                break;
            } else {
                temp = temp->rightChild;
            }
        } else {
            // Duplicate values not inserted in this implementation
            break;
        }
    }
    return current;
}

// Function to perform post-order traversal and print the elements
void displayPostOrder(Node* node) {
    if (node == nullptr) {
        return;
    }
    displayPostOrder(node->leftChild);   // Traverse left subtree
    displayPostOrder(node->rightChild);  // Traverse right subtree
    std::cout << node->data << " ";      // Visit root node
}

// Main function to test the BST and post-order traversal
int main() {
    Node* root = nullptr;

    // Insert elements into the BST
    root = addNode(root, 50);
    root = addNode(root, 30);
    root = addNode(root, 20);
    root = addNode(root, 40);
    root = addNode(root, 70);
    root = addNode(root, 60);
    root = addNode(root, 80);

    // Perform post-order traversal and print the elements
    std::cout << "Post-Order Traversal: ";
    displayPostOrder(root);
    std::cout << std::endl;

    return 0;
}

