#include <iostream>
#include <functional>

template <typename Func>
class ScopeGuard {
    Func cleanup_func_;
    bool dismissed_;

public:
    explicit ScopeGuard(Func func) 
        : cleanup_func_(std::move(func)), dismissed_(false) {}

    ~ScopeGuard() {
        if (!dismissed_) {
            try {
                cleanup_func_();
            } catch (...) {
                std::terminate();
            }
        }
    }

    void dismiss() { dismissed_ = true; }

    // Prevent copying
    ScopeGuard(const ScopeGuard&) = delete;
    ScopeGuard& operator=(const ScopeGuard&) = delete;

    // Allow moving
    ScopeGuard(ScopeGuard&& other) noexcept 
        : cleanup_func_(std::move(other.cleanup_func_)), 
          dismissed_(other.dismissed_) {
        other.dismissed_ = true;
    }

    ScopeGuard& operator=(ScopeGuard&& other) noexcept {
        if (this != &other) {
            if (!dismissed_) {
                try {
                    cleanup_func_();
                } catch (...) {
                    std::terminate();
                }
            }
            cleanup_func_ = std::move(other.cleanup_func_);
            dismissed_ = other.dismissed_;
            other.dismissed_ = true;
        }
        return *this;
    }
};

int main() {
    ScopeGuard outer_guard([]{ std::cout << "world!"; });
    ScopeGuard inner_guard([]{ std::cout << "Hello, "; });

    int condition = 1 + 1;
    if (condition == 2)
        return -1;

    ScopeGuard skipped_guard([]{ std::cout << "Blam"; });
}

