// Function signature (same as original)
Eigen::MatrixXd f(const std::vector<std::vector<std::vector<double>>>& lines);

// Alternative wrapper implementation using different loop structure
std::vector<std::vector<double>> f_wrapper(const std::vector<std::vector<std::vector<double>>>& lines) {
    Eigen::MatrixXd result = f(lines);

    // Initialize result container with appropriate dimensions
    std::vector<std::vector<double>> jsResult;
    jsResult.reserve(result.rows());

    for (int i = 0; i < result.rows(); ++i) {
        std::vector<double> row;
        row.reserve(result.cols());
        for (int j = 0; j < result.cols(); ++j) {
            row.push_back(result(i, j));
        }
        jsResult.push_back(row);
    }

    return jsResult;
}

