// Derive key and initialization vector from password and salt using MD5
void generateCryptoParams(const std::string& passwd, const std::string& slt, std::string& outKey, std::string& outIv)
{
    Poco::Crypto::CipherFactory& factory = Poco::Crypto::CipherFactory::defaultFactory();
    Poco::Crypto::CipherKey keyGen("md5", passwd, slt, 1);

    outKey = keyGen.key();
    outIv = keyGen.iv();
