int main()
{
    std::string inputFile = "encrypted_file";
    std::string userPassword = "your_password";

    std::ifstream inputStream(inputFile, std::ios::binary);
    if (!inputStream)
    {
        std::cerr << "Unable to open input file." << std::endl;
        return 1;
    }

    std::string content((std::istreambuf_iterator<char>(inputStream)), std::istreambuf_iterator<char>());
    inputStream.close();

    // Verify the file has the expected magic header
    if (content.substr(0, 8) != "Salted__")
    {
        std::cerr << "File does not appear to be in the expected format." << std::endl;
        return 1;
    }

    // Extract salt and encrypted payload
    std::string saltValue = content.substr(8, 8);
    std::string cipherText = content.substr(16);

    std::string derivedKey, derivedIv;
    generateCryptoParams(userPassword, saltValue, derivedKey, derivedIv);

    Poco::Crypto::CipherFactory& factory = Poco::Crypto::CipherFactory::defaultFactory();
    Poco::Crypto::CipherKey cipherKey("aes-128-cbc", derivedKey, derivedIv);
    Poco::AutoPtr<Poco::Crypto::Cipher> decryptor = factory.createCipher(cipherKey);

    std::string plainText = decryptor->decryptString(cipherText, Poco::Crypto::Cipher::ENC_BASE64);

    std::cout << "Decrypted content: " << plainText << std::endl;

