extern JavaVM* vm; // Ensure this is properly initialized in your code

#define LOG_INFO(...) __android_log_print(ANDROID_LOG_INFO, "AACRNative", __VA_ARGS__)
#define LOG_ERROR(...) __android_log_print(ANDROID_LOG_ERROR, "AACRNative", __VA_ARGS__)

// Callback invoked on crash to notify Java layer
bool breakpad_callback(const google_breakpad::MinidumpDescriptor& descriptor, void* context, bool succeeded) {
    JNIEnv* jniEnv = nullptr;
    jint attachStatus = vm->GetEnv(reinterpret_cast<void**>(&jniEnv), JNI_VERSION_1_6);

    bool wasAttached = false;

    if (attachStatus == JNI_EDETACHED) {
        if (isDebug)
            LOG_INFO("Attaching native thread to JVM...");
        if (JNI_OK != vm->AttachCurrentThread(&jniEnv, nullptr)) {
            if (isDebug)
                LOG_INFO("Failed to attach thread");
            return false;
        }
        wasAttached = true;
    } else if (attachStatus != JNI_OK) {
        if (isDebug)
            LOG_INFO("Unable to retrieve JNI environment");
        return false;
    }

    if (isDebug)
        LOG_INFO("Processing crash dump...");

    // Locate Java exception handler class
    jclass handlerClassLocal = jniEnv->FindClass("com/abc/Myclass");
    if (!handlerClassLocal) {
        LOG_ERROR("Java class 'com/abc/Myclass' not found");
        if (wasAttached)
            vm->DetachCurrentThread();
        return false;
    }

    jclass handlerClassGlobal = static_cast<jclass>(jniEnv->NewGlobalRef(handlerClassLocal));
    jniEnv->DeleteLocalRef(handlerClassLocal);

    if (!handlerClassGlobal) {
        LOG_ERROR("Failed to create global reference for handler class");
        if (wasAttached)
            vm->DetachCurrentThread();
        return false;
    }

    // Resolve the static method
    jmethodID handlerMethod = jniEnv->GetStaticMethodID(handlerClassGlobal, "handleException", "()V");
    if (!handlerMethod) {
        LOG_ERROR("Method 'handleException()' not found in class");
        jniEnv->DeleteGlobalRef(handlerClassGlobal);
        if (wasAttached)
            vm->DetachCurrentThread();
        return false;
    }

    // Invoke the Java handler
    jniEnv->CallStaticVoidMethod(handlerClassGlobal, handlerMethod);

    // Handle any exceptions thrown by Java code
    if (jniEnv->ExceptionCheck()) {
        if (isDebug)
            LOG_INFO("Java exception occurred during handling");
        jniEnv->ExceptionDescribe();
        jniEnv->ExceptionClear();
    }

    if (isDebug)
        LOG_INFO("Crash notification sent to Java");

    // Cleanup references
    jniEnv->DeleteGlobalRef(handlerClassGlobal);

    // Detach thread only if we attached it ourselves
    if (wasAttached) {
        vm->DetachCurrentThread();
    }

    return true;
}

#include <iostream>
#include <climits> // For INT_MIN

// Find the maximum value in an integer array
int findMax(int arr[], int size) {
    if (size <= 0) {
        std::cerr << "Array size must be positive." << std::endl;
        return INT_MIN; // Return the smallest possible integer as an error indicator
    }

    int currentMax = arr[0]; // Initialize with the first element
    int index = 1; // Start checking from the second element

    while (index < size) {
        if (arr[index] > currentMax) {
            currentMax = arr[index]; // Update currentMax if a larger value is found
        }
        index++;
    }

    return currentMax;
}

