// Insert folder hierarchy from a given path into the database
void addFolder(const std::string& inputPath) {
    std::vector<std::string> segments;
    boost::split(segments, inputPath, boost::is_any_of("\\/"));

    int currentParentId = -1;
    for (const auto& segment : segments) {
        if (segment.empty()) continue;  // Skip empty segments (e.g., from leading/trailing slashes)

        std::string sqlStatement;
        if (currentParentId == -1) {
            // Root-level folder: no parent, level 0
            sqlStatement = "INSERT INTO folders (parent_id, name, path, level) VALUES (NULL, '" + segment + "', '" + segment + "', 0);";
        } else {
            // Nested folder: reference parent ID and compute full path and level
            sqlStatement = "INSERT INTO folders (parent_id, name, path, level) SELECT id, '" + segment + "', path || '/' || '" + segment + "', level + 1 FROM folders WHERE id = " + std::to_string(currentParentId) + ";";
        }

        currentParentId = executeInsert(sqlStatement);
    }
}

