int main() {
    // Create shared memory for image data transfer
    const char* mem_name = "/image_buffer";
    int mem_fd = shm_open(mem_name, O_CREAT | O_RDWR, 0666);
    if (mem_fd == -1) {
        perror("shm_open failed");
        return 1;
    }

    // Define image dimensions and allocate space
    const int width = 640;
    const int height = 480;
    const int channels = 3;
    const size_t total_bytes = static_cast<size_t>(width) * height * channels;

    if (ftruncate(mem_fd, total_bytes) == -1) {
        perror("ftruncate failed");
        close(mem_fd);
        return 1;
    }

    // Map shared memory into process address space
    void* buffer = mmap(nullptr, total_bytes, PROT_WRITE, MAP_SHARED, mem_fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap failed");
        close(mem_fd);
        return 1;
    }

    // Initialize OpenCV matrix using shared memory
    cv::Mat frame(height, width, CV_8UC3, buffer);

    // Initialize camera capture
    cv::VideoCapture camera(0);
    if (!camera.isOpened()) {
        std::cerr << "Failed to open camera" << std::endl;
        munmap(buffer, total_bytes);
        close(mem_fd);
        return 1;
    }

    // Capture one frame
    camera >> frame;

    // Cleanup resources
    munmap(buffer, total_bytes);
    close(mem_fd);

    return 0;
}

