#include <iostream>
#include <array>
#include <chrono>
#include <immintrin.h>

int main() {
    long long accumulator = 0;
    std::array<int, 1024> buffer;
    int* dataPtr = buffer.data();

    // Initialize the array with values 0 to 1023
    for(int idx = 0; idx < 1024; ++idx) {
        dataPtr[idx] = idx;
    }

    auto beginTime = std::chrono::high_resolution_clock::now();

    // Perform computation 10 million times
    for(int outerLoop = 0; outerLoop < 1024 * 1024 * 10; ++outerLoop) {
        __m256i vectorSum = _mm256_setzero_si256();

        // Process 8 elements at a time using AVX
        for(int innerIdx = 0; innerIdx < 1024; innerIdx += 8) {
            __m256i chunk = _mm256_loadu_si256(reinterpret_cast<__m256i*>(dataPtr + innerIdx));
            vectorSum = _mm256_add_epi32(vectorSum, chunk);
        }

        // Extract and combine partial sums from the vector register
        long long partial1 = _mm256_extract_epi64(vectorSum, 0);
        long long partial2 = _mm256_extract_epi64(vectorSum, 1);
        long long partial3 = _mm256_extract_epi64(vectorSum, 2);
        long long partial4 = _mm256_extract_epi64(vectorSum, 3);

        accumulator += (partial1 + partial2 + partial3 + partial4);
    }

    auto endTime = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::micro> duration = endTime - beginTime;

    std::cout << "Unrestricted: " << duration.count() << " us, Value = " << accumulator << std::endl;

    return 0;
}

