    Vec3f operator*(float scalar) const {
        return {r * scalar, g * scalar, b * scalar};
    }
    Vec3f operator+(const Vec3f& other) const {
        return {r + other.r, g + other.g, b + other.b};
    }
};

Vec3f convertToVec3(const Color& color) {
    return {color.r, color.g, color.b};
}

Vec3f bilinearInterpolation(const Color* pixelCache, int y1, int y2, int x1, int x2, float x, float y, int width) {
#ifdef USE_SIMD
    // Load the four corner pixels as SIMD vectors
    __m128 top_left  = _mm_loadu_ps((float*)&pixelCache[y1 * width + x1]);
    __m128 bottom_left = _mm_loadu_ps((float*)&pixelCache[y2 * width + x1]);
    __m128 bottom_right = _mm_loadu_ps((float*)&pixelCache[y2 * width + x2]);
    __m128 top_right = _mm_loadu_ps((float*)&pixelCache[y1 * width + x2]);

    // Compute interpolation weights
    float weight_top_left   = (x2 - x) * (y2 - y);
    float weight_bottom_left = (x - x1) * (y2 - y);
    float weight_top_right  = (x2 - x) * (y - y1);
    float weight_bottom_right = (x - x1) * (y - y1);

    // Broadcast weights to SIMD registers
    __m128 w_tl = _mm_set1_ps(weight_top_left);
    __m128 w_bl = _mm_set1_ps(weight_bottom_left);
    __m128 w_tr = _mm_set1_ps(weight_top_right);
    __m128 w_br = _mm_set1_ps(weight_bottom_right);

    // Perform weighted sum: TL*w_tl + BL*w_bl + TR*w_tr + BR*w_br
    __m128 partial1 = _mm_add_ps(_mm_mul_ps(top_left, w_tl), 
                                 _mm_mul_ps(bottom_left, w_bl));
    __m128 partial2 = _mm_add_ps(_mm_mul_ps(top_right, w_tr), 
                                 _mm_mul_ps(bottom_right, w_br));
    __m128 final_result = _mm_add_ps(partial1, partial2);

    // Store result into Vec3f structure
    Vec3f interpolated_color;
    _mm_storeu_ps((float*)&interpolated_color, final_result);
    return interpolated_color;
#else
    // Scalar implementation using helper function
    const Vec3f tl = convertToVec3(pixelCache[y1 * width + x1]);
    const Vec3f bl = convertToVec3(pixelCache[y2 * width + x1]);
    const Vec3f br = convertToVec3(pixelCache[y2 * width + x2]);
    const Vec3f tr = convertToVec3(pixelCache[y1 * width + x2]);

    // Compute weighted sum with same coefficients but reordered terms
    const Vec3f result =
        tl * ((x2 - x) * (y2 - y)) +
        bl * ((x - x1) * (y2 - y)) +
        tr * ((x2 - x) * (y - y1)) +
        br * ((x - x1) * (y - y1));

    return result;
#endif
}

