#include <iostream>
#include <emmintrin.h>  // SSE2 intrinsics

// Compute minimum and maximum values in an array using SIMD operations
void computeRangeSSE(const int* arr, size_t len, int& minOut, int& maxOut) {
    if (len == 0) return;

    // Initialize vectors with the first element
    __m128i currentMin = _mm_set1_epi32(arr[0]);
    __m128i currentMax = _mm_set1_epi32(arr[0]);

    // Process elements in chunks of 4
    for (size_t idx = 0; idx < len; idx += 4) {
        // Load 4 integers into a vector (unaligned load)
        __m128i chunk = _mm_loadu_si128(reinterpret_cast<const __m128i*>(arr + idx));

        // Update running min and max
        currentMin = _mm_min_epi32(currentMin, chunk);
        currentMax = _mm_max_epi32(currentMax, chunk);
    }

    // Reduce within the vector to get single min and max values
    currentMin = _mm_min_epi32(currentMin, _mm_shuffle_epi32(currentMin, _MM_SHUFFLE(0,0,3,2)));
    currentMin = _mm_min_epi32(currentMin, _mm_shuffle_epi32(currentMin, _MM_SHUFFLE(0,0,0,1)));

    currentMax = _mm_max_epi32(currentMax, _mm_shuffle_epi32(currentMax, _MM_SHUFFLE(0,0,3,2)));
    currentMax = _mm_max_epi32(currentMax, _mm_shuffle_epi32(currentMax, _MM_SHUFFLE(0,0,0,1)));

    // Extract scalar values from the low lanes
    minOut = _mm_cvtsi128_si32(currentMin);
    maxOut = _mm_cvtsi128_si32(currentMax);
}

int main() {
    int sampleData[] = {10, 20, 30, 40, 50, 60, 70, 80};
    int lowerBound, upperBound;

    computeRangeSSE(sampleData, 8, lowerBound, upperBound);

    std::cout << "Minimum: " << lowerBound << ", Maximum: " << upperBound << std::endl;

    return 0;
}

