// Helper: Flip image vertically by copying rows in reverse order
static void FlipImageVertically(uint8* dest, const uint8* src, int width, int height, int bytesPerRow) {
    for (int y = 0; y < height; ++y) {
        const uint8* srcRow = src + y * bytesPerRow;
        uint8* destRow = dest + (height - 1 - y) * bytesPerRow;
        // Manual row copy instead of memcpy for variation
        for (int x = 0; x < bytesPerRow; ++x) {
            destRow[x] = srcRow[x];
        }
    }
}

uint8* Gfx::ScreenshotBuffer(int& deviceWidth, int& deviceHeight, int& dataLength) {
    // Query device dimensions
    deviceWidth = IwGxGetDeviceWidth();
    deviceHeight = IwGxGetDeviceHeight();

    // Compute buffer size: RGBA format = 4 bytes per pixel
    int bytesPerRow = deviceWidth * 4;
    dataLength = bytesPerRow * deviceHeight;

    // Ensure byte alignment for pixel operations
    glPixelStorei(GL_UNPACK_ALIGNMENT, 1);
    glPixelStorei(GL_PACK_ALIGNMENT, 1);

    // Allocate temporary buffer for raw pixel data
    std::vector<uint8> tempBuffer(dataLength);

    // Read pixels from framebuffer
    glReadPixels(0, 0, deviceWidth, deviceHeight, GL_RGBA, GL_UNSIGNED_BYTE, tempBuffer.data());

    // Check for OpenGL errors
    GLenum error = glGetError();
    if (error != GL_NO_ERROR) {
        IwTrace(GFX, (IwString("OpenGL error: 0x%04x"), error));
    }

    // Allocate final flipped buffer
    uint8* resultBuffer = new uint8[dataLength];
    FlipImageVertically(resultBuffer, tempBuffer.data(), deviceWidth, deviceHeight, bytesPerRow);

    // Return ownership of dynamically allocated buffer
    return resultBuffer;
}

void Gfx::ScreenshotImage(CIwImage* img, uint8*& pbuffer) {
    int width, height, totalBytes;
    pbuffer = ScreenshotBuffer(width, height, totalBytes);

    // Configure image properties
    img->SetFormat(CIwImage::ABGR_8888);
    img->SetWidth(width);
    img->SetHeight(height);
    img->SetBuffers(pbuffer, totalBytes, 0, 0);
}

