// Renamed function for shader compilation
unsigned int buildShader(const char* sourceCode, unsigned int shaderType) {
    unsigned int shaderID = glCreateShader(shaderType);
    glShaderSource(shaderID, 1, &sourceCode, nullptr);
    glCompileShader(shaderID);

    int success;
    glGetShaderiv(shaderID, GL_COMPILE_STATUS, &success);
    if (success == GL_FALSE) {
        int logLength;
        glGetShaderiv(shaderID, GL_INFO_LOG_LENGTH, &logLength);
        char* errorLog = (char*)malloc(logLength * sizeof(char));
        glGetShaderInfoLog(shaderID, logLength, &logLength, errorLog);
        std::cerr << "Shader compilation failed: " 
                  << (shaderType == GL_VERTEX_SHADER ? "vertex" : "fragment") 
                  << " shader\n" << errorLog << std::endl;
        free(errorLog);
        glDeleteShader(shaderID);
        return 0;
    }
    return shaderID;
}

// Function to create shader program with updated logic flow
unsigned int generateShaderProgram(const char* vsSource, const char* fsSource) {
    unsigned int program = glCreateProgram();
    unsigned int vertexShader = buildShader(vsSource, GL_VERTEX_SHADER);
    unsigned int fragmentShader = buildShader(fsSource, GL_FRAGMENT_SHADER);

    glAttachShader(program, vertexShader);
    glAttachShader(program, fragmentShader);
    glLinkProgram(program);
    glValidateProgram(program);

    glDeleteShader(vertexShader);
    glDeleteShader(fragmentShader);

    return program;
}

int main() {
    // Initialize GLFW with error checking
    if (!glfwInit()) {
        std::cerr << "Error: Failed to initialize GLFW" << std::endl;
        return -1;
    }

    // Create window with OpenGL context
    GLFWwindow* renderWindow = glfwCreateWindow(800, 600, "Modified 3D Cube", nullptr, nullptr);
    if (!renderWindow) {
        std::cerr << "Error: Failed to create rendering window" << std::endl;
        glfwTerminate();
        return -1;
    }

    // Set up OpenGL context
    glfwMakeContextCurrent(renderWindow);

    // Initialize GLAD with proper loader
    if (!gladLoadGLLoader((GLADloadproc)glfwGetProcAddress)) {
        std::cerr << "Error: Failed to initialize GLAD" << std::endl;
        return -1;
    }

    // Enable depth testing for 3D rendering
    glEnable(GL_DEPTH_TEST);

    // Generate VAO
    unsigned int vao;
    glGenVertexArrays(1, &vao);
    glBindVertexArray(vao);

    // Generate and populate VBO
    unsigned int vbo;
    glGenBuffers(1, &vbo);
    glBindBuffer(GL_ARRAY_BUFFER, vbo);
    glBufferData(GL_ARRAY_BUFFER, sizeof(cubeVertices), cubeVertices, GL_STATIC_DRAW);

    // Generate and populate EBO
    unsigned int ebo;
    glGenBuffers(1, &ebo);
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, ebo);
    glBufferData(GL_ELEMENT_ARRAY_BUFFER, sizeof(cubeIndices), cubeIndices, GL_STATIC_DRAW);

    // Configure vertex attributes
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 6 * sizeof(float), (void*)0);
    glEnableVertexAttribArray(0);
    glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, 6 * sizeof(float), (void*)(3 * sizeof(float)));
    glEnableVertexAttribArray(1);

    // Create shader program
    unsigned int shaderProgram = generateShaderProgram(vertexShaderSource, fragmentShaderSource);
    glUseProgram(shaderProgram);

    // Main rendering loop
    while (!glfwWindowShouldClose(renderWindow)) {
        // Handle input
        if (glfwGetKey(renderWindow, GLFW_KEY_ESCAPE) == GLFW_PRESS) {
            glfwSetWindowShouldClose(renderWindow, true);
        }

