        // Update window
        glfwSwapBuffers(renderWindow);
        glfwPollEvents();
    }

    // Cleanup resources
    glDeleteVertexArrays(1, &vao);
    glDeleteBuffers(1, &vbo);
    glDeleteBuffers(1, &ebo);
    glDeleteProgram(shaderProgram);

    // Terminate GLFW
    glfwTerminate();
    return 0;
}

