// Compute sliding window medians using a multiset for efficient insertions/deletions
vector<double> computeSlidingMedian(vector<int>& input, int windowSize) {
    // Initialize the window with the first 'windowSize' elements
    multiset<double> currentWindow(input.begin(), input.begin() + windowSize);
    vector<double> medianList;

    // Lambda to compute median from the current window
    auto calculateMedian = [&currentWindow, windowSize]() -> double {
        auto midIt = currentWindow.begin();
        advance(midIt, windowSize / 2);

        if (windowSize % 2 == 0) {
            // Even-sized window: average of two middle elements
            return (*midIt + *prev(midIt)) / 2.0;
        } else {
            // Odd-sized window: middle element
            return *midIt;
        }
    };

    // Add the first window's median
    medianList.push_back(calculateMedian());

    // Slide the window across the array
    for (int i = windowSize; i < input.size(); ++i) {
        // Remove the element leaving the window (oldest element)
        auto itToRemove = currentWindow.find(input[i - windowSize]);
        currentWindow.erase(itToRemove);

        // Insert the new element entering the window
        currentWindow.insert(static_cast<double>(input[i]));

        // Add the updated median
        medianList.push_back(calculateMedian());
    }

    return medianList;
}

int main() {
    vector<int> data = {1, 3, -1, -3, 5, 3, 6, 7};
    int k = 3;
    vector<double> expectedOutput = {1, -1, -1, 3, 5, 6};
    vector<double> actualOutput = computeSlidingMedian(data, k);

    assert(actualOutput == expectedOutput);
    cout << "All tests passed successfully!" << endl;

    return 0;
}

