std::vector<char> base64_decode(const std::string& encoded_string) {
    int length = encoded_string.length();
    int pos = 0;
    int index = 0;
    int input_pos = 0;
    unsigned char buffer_4[4], buffer_3[3];
    std::vector<char> result;

    while (length-- && (encoded_string[input_pos] != '=') && std::isalnum(encoded_string[input_pos])) {
        unsigned char current_char = static_cast<unsigned char>(encoded_string[input_pos]);
        int decoded_value;

        if (current_char >= 'A' && current_char <= 'Z')
            decoded_value = current_char - 'A';
        else if (current_char >= 'a' && current_char <= 'z')
            decoded_value = current_char - 'a' + 26;
        else if (current_char >= '0' && current_char <= '9')
            decoded_value = current_char - '0' + 52;
        else if (current_char == '+')
            decoded_value = 62;
        else
            decoded_value = 63;

        buffer_4[index++] = static_cast<unsigned char>(decoded_value);

        if (index == 4) {
            buffer_3[0] = (buffer_4[0] << 2) | ((buffer_4[1] & 0x30) >> 4);
            buffer_3[1] = ((buffer_4[1] & 0x0F) << 4) | ((buffer_4[2] & 0x3C) >> 2);
            buffer_3[2] = ((buffer_4[2] & 0x03) << 6) | buffer_4[3];

            for (int k = 0; k < 3; ++k)
                result.push_back(static_cast<char>(buffer_3[k]));

            index = 0;
        }

        input_pos++;
    }

    if (index > 0) {
        for (int fill = index; fill < 4; ++fill)
            buffer_4[fill] = 0;

        buffer_3[0] = (buffer_4[0] << 2) | ((buffer_4[1] & 0x30) >> 4);
        buffer_3[1] = ((buffer_4[1] & 0x0F) << 4) | ((buffer_4[2] & 0x3C) >> 2);
        buffer_3[2] = ((buffer_4[2] & 0x03) << 6) | buffer_4[3];

        for (int out_idx = 0; out_idx < index - 1; ++out_idx)
            result.push_back(static_cast<char>(buffer_3[out_idx]));
    }

    return result;
}

#include <QCoreApplication>
#include <QByteArray>
#include <QDebug>

quint16 computeCRC16(QByteArray input)
{
    quint16 crc = 0xFFFF; // Starting value as per standard CRC-16/CCITT-FALSE

    for (int idx = 0; idx < input.length(); ++idx) {
        quint8 byteVal = static_cast<quint8>(input.at(idx));
        crc ^= (static_cast<quint16>(byteVal) << 8);

        for (int bit = 0; bit < 8; ++bit) {
            if (crc & 0x8000) {
                crc = ((crc << 1) | 1) ^ 0x1021;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);

    QByteArray message("Hello World");
    quint16 result = computeCRC16(message);

    qDebug() << "CRC: 0x" << QString::number(result, 16).toUpper();

    return app.exec();
}

