class FullbandSpectrumSynthesizer {
public:
  FullbandSpectrumSynthesizer(double lowFreq, double highFreq, double samplingRate, double ambientNoise, double qualityFactor, std::vector<RadioSignal> sources) 
    : m_lowFreq(lowFreq), m_highFreq(highFreq), m_samplingRate(samplingRate), m_ambientNoise(ambientNoise), m_qualityFactor(qualityFactor), m_sources(sources) {}

  std::vector<double> synthesize() {
    const size_t binCount = 1024;
    std::vector<double> frequencies(binCount);
    double deltaF = m_samplingRate / binCount;

    for (size_t idx = 0; idx < binCount; ++idx) {
      frequencies[idx] = m_lowFreq + idx * deltaF;
    }

    std::vector<double> spectrum(binCount, m_ambientNoise);

    for (const auto& src : m_sources) {
      std::vector<double> component = buildSignalProfile(src, frequencies, binCount);
      for (size_t i = 0; i < binCount; ++i) {
        spectrum[i] += component[i];
      }
    }

    return spectrum;
  }

private:
  double m_lowFreq;
  double m_highFreq;
  double m_samplingRate;
  double m_ambientNoise;
  double m_qualityFactor;
  std::vector<RadioSignal> m_sources;

  std::vector<double> buildSignalProfile(const RadioSignal& src, const std::vector<double>& freqs, size_t bins) {
    std::vector<double> profile(bins, 0.0);
    double halfBW = src.channelBandwidth / 2.0;

    for (size_t k = 0; k < bins; ++k) {
      double currentFreq = freqs[k];
      if (currentFreq >= src.carrierFreq - halfBW && currentFreq <= src.carrierFreq + halfBW) {
        double rawPower = convertdBmToWatt(src.transmitPower);
        double noiseLevel = rawPower / convertdBToLinear(m_qualityFactor);

        std::complex<double> signalComponent = createSignalComplex(rawPower, currentFreq);
        std::complex<double> noiseComponent = createNoiseComponent(noiseLevel);
        std::complex<double> combined = signalComponent + noiseComponent;

        double magnitude = std::abs(combined);
        double powerInW = magnitude * magnitude;
        double psd_dBm = convertWattTodBm(powerInW / m_samplingRate) - 30.0;

        profile[k] = psd_dBm;
      }
    }
    return profile;
  }

  std::complex<double> createSignalComplex(double power, double frequency) {
    static std::mt19937 rng(std::random_device{}());
    static std::uniform_real_distribution<double> phaseDist(0.0, 2.0 * M_PI);

    double amplitude = std::sqrt(power);
    double phase = phaseDist(rng);
    double angle = 2.0 * M_PI * frequency / m_samplingRate + phase;

    return std::complex<double>(amplitude * std::cos(angle), amplitude * std::sin(angle));
  }

  std::complex<double> createNoiseComponent(double noisePower) {
    static std::mt19937 rng(std::random_device{}());
    static std::normal_distribution<double> noiseDist(0.0, std::sqrt(noisePower));

    double realPart = noiseDist(rng);
    double imagPart = noiseDist(rng);
    return std::complex<double>(realPart, imagPart);
  }

  double convertdBmToWatt(double dBm) {
    return std::pow(10.0, (dBm - 30.0) / 10.0);
  }

  double convertWattTodBm(double watt) {
    return 10.0 * std::log10(watt * 1000.0);
  }

  double convertdBToLinear(double dB) {
    return std::pow(10.0, dB / 10.0);
  }
};

