template<typename T>
inline bool isPowerOfTwo(const T value) {
    if (value == 0) {
        return false;
    }

    // Check if exactly one bit is set by verifying that 
    // the number AND (number - 1) equals zero
    T reduced = value & (value - static_cast<T>(1));
    return reduced == 0;
}

#include <iostream>
#include <string>
#include <stack>
#include <cctype>
#include <stdexcept>

class ArithmeticEvaluator {
public:
    ArithmeticEvaluator(const std::string& input) : expr(input) {}

    double compute() {
        if (expr.empty()) {
            throw std::invalid_argument("Input expression is empty");
        }
        return parseRange(0, expr.length() - 1);
    }

private:
    std::string expr;

    double parseRange(int left, int right) {
        std::stack<double> values;
        char lastOp = '+';
        int tempValue = 0;

        for (int idx = left; idx <= right; ++idx) {
            if (std::isdigit(expr[idx])) {
                tempValue = tempValue * 10 + (expr[idx] - '0');
            } else if (expr[idx] == '(') {
                int balance = 1;
                int endIdx = idx + 1;
                while (balance != 0 && endIdx <= right) {
                    if (expr[endIdx] == '(') balance++;
                    else if (expr[endIdx] == ')') balance--;
                    endIdx++;
                }
                tempValue = static_cast<int>(parseRange(idx + 1, endIdx - 2));
                idx = endIdx - 1;
            }

            bool isEndOfToken = (!std::isdigit(expr[idx]) && !std::isspace(expr[idx])) || (idx == right);
            if (isEndOfToken) {
                processOperation(values, lastOp, tempValue);
                tempValue = 0;
                if (isSupportedOperator(expr[idx])) {
                    lastOp = expr[idx];
                }
            }
        }

        double result = 0;
        while (!values.empty()) {
            result += values.top();
            values.pop();
        }
        return result;
    }

    void processOperation(std::stack<double>& stack, char operation, double operand) {
        switch (operation) {
            case '+': stack.push(operand); break;
            case '-': stack.push(-operand); break;
            case '*': stack.top() *= operand; break;
            case '/':
                if (operand == 0.0) throw std::runtime_error("Division by zero detected");
                stack.top() /= operand;
                break;
            default: throw std::invalid_argument("Unsupported arithmetic operator");
        }
    }

    bool isSupportedOperator(char symbol) {
        return symbol == '+' || symbol == '-' || symbol == '*' || symbol == '/';
    }
};

int main() {
    try {
        ArithmeticEvaluator evaluator("3 + 5 * (10 - 4) / 2");
        std::cout << "Computed Result: " << evaluator.compute() << std::endl;
    } catch (const std::exception& error) {
        std::cerr << "Exception caught: " << error.what() << std::endl;
    }
    return 0;
}

