// Alternative type trait implementation for functor detection
template <typename T>
struct has_fmap_method : std::false_type {};

// Specialized version for List types
template <typename Element>
struct has_fmap_method<List<Element>> : std::true_type {};

// Generic mapper function that works with any type supporting fmap
template <typename MapperFunc, typename Container>
auto transform(MapperFunc func, Container& container) {
    static_assert(has_fmap_method<Container>::value, "Container must support mapping operation");
    return container.map(func);
}

// Custom List container with mapping capability
template <typename T>
class Sequence {
private:
    std::vector<T> elements;
public:
    explicit Sequence(int size) : elements(size) {}
    Sequence(const Sequence& source) : elements(source.elements) {}
    ~Sequence() = default;

    T& at(int index) { return elements[index]; }
    const T& at(int index) const { return elements[index]; }

    // Mapping function with different naming
    template <typename U>
    Sequence<U> map(std::function<U(T)> operation) {
        Sequence<U> output(elements.size());
        for (int idx = 0; idx < static_cast<int>(elements.size()); ++idx) {
            output.at(idx) = operation(elements[idx]);
        }
        return output;
    }
};

