#include <Python.h>
#include <string>
#include <iostream>

int main() {
    PyObject *module = nullptr;
    PyObject *func = nullptr;
    PyObject *result = nullptr;

    // Disable bytecode generation for cleaner execution
    setenv("PYTHONDONTWRITEBYTECODE", "1", 1);

    // Initialize Python interpreter
    Py_Initialize();

    // Helper lambda to load and call function from a given path
    auto loadAndCallFunction = [](const std::string& folderPath) -> bool {
        // Convert wide string path to narrow string
        std::wstring wPath(folderPath.begin(), folderPath.end());
        std::string narrowPath(wPath.begin(), wPath.end());

        // Get sys.path object
        PyObject* sysPath = PySys_GetObject(const_cast<char*>("path"));
        if (!sysPath) return false;

        // Append the folder path to Python's module search path
        PyList_Append(sysPath, PyUnicode_FromString(narrowPath.c_str()));

        // Load the module named 'python_function'
        PyObject* moduleName = PyUnicode_FromString("python_function");
        PyObject* loadedModule = PyImport_Import(moduleName);
        Py_DECREF(moduleName);

        if (!loadedModule) {
            PyErr_Print();
            return false;
        }

        // Get dictionary of module and retrieve 'function' callable
        PyObject* moduleDict = PyModule_GetDict(loadedModule); // borrowed reference
        PyObject* callable = PyDict_GetItemString(moduleDict, "function"); // borrowed reference

        if (callable && PyCallable_Check(callable)) {
            // Call the function with no arguments
            result = PyObject_CallFunctionObjArgs(callable, NULL);
            if (result) {
                Py_DECREF(result);
            } else {
                PyErr_Print();
            }
            Py_XDECREF(result);
            Py_DECREF(loadedModule);
            return true;
        } else {
            std::cerr << "Function 'function' not found or not callable in module." << std::endl;
            Py_DECREF(loadedModule);
            return false;
        }
    };

    // First attempt: load from Folder 1
    loadAndCallFunction("./Folder 1");

    // Second attempt: load from Folder 2
    loadAndCallFunction("./Folder 2");

    // Finalize Python interpreter
    Py_Finalize();

    return 0;
}

