#include <iostream>
#include <vector>
#include <cuda_runtime.h>

struct Vector3D {
    float x, y, z;
};

struct Entity {
    Vector3D pos;
    Vector3D vel;
};

int main() {
    int numEntities = 1024; // Example size — in real code, this might come from input
    float dt = 0.016f;      // time step

    // Allocate host-side entities
    std::vector<Entity> entities(numEntities);

    // Prepare flattened arrays for GPU transfer
    std::vector<float> host_pos_x(numEntities), host_pos_y(numEntities), host_pos_z(numEntities);
    std::vector<float> host_vel_x(numEntities), host_vel_y(numEntities), host_vel_z(numEntities);

    // Populate flattened arrays from structured data
    auto unpackToFlat = [&](const std::vector<Entity>& src,
                            std::vector<float>& px, std::vector<float>& py, std::vector<float>& pz,
                            std::vector<float>& vx, std::vector<float>& vy, std::vector<float>& vz) {
        for (size_t i = 0; i < src.size(); ++i) {
            px[i] = src[i].pos.x;
            py[i] = src[i].pos.y;
            pz[i] = src[i].pos.z;
            vx[i] = src[i].vel.x;
            vy[i] = src[i].vel.y;
            vz[i] = src[i].vel.z;
        }
    };

    unpackToFlat(entities, host_pos_x, host_pos_y, host_pos_z,
                 host_vel_x, host_vel_y, host_vel_z);

    // Device pointers
    float *d_px, *d_py, *d_pz;
    float *d_vx, *d_vy, *d_vz;

    size_t bytes = numEntities * sizeof(float);

    cudaMalloc(&d_px, bytes);
    cudaMalloc(&d_py, bytes);
    cudaMalloc(&d_pz, bytes);
    cudaMalloc(&d_vx, bytes);
    cudaMalloc(&d_vy, bytes);
    cudaMalloc(&d_vz, bytes);

    // Copy to device
    cudaMemcpy(d_px, host_pos_x.data(), bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(d_py, host_pos_y.data(), bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(d_pz, host_pos_z.data(), bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(d_vx, host_vel_x.data(), bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(d_vy, host_vel_y.data(), bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(d_vz, host_vel_z.data(), bytes, cudaMemcpyHostToDevice);

    // Kernel: update positions using velocities
    auto updateKernel = [] __global__(float* pos_x, float* pos_y, float* pos_z,
                                      float* vel_x, float* vel_y, float* vel_z,
                                      int count, float step) {
        int idx = blockIdx.x * blockDim.x + threadIdx.x;
        if (idx < count) {
            pos_x[idx] += vel_x[idx] * step;
            pos_y[idx] += vel_y[idx] * step;
            pos_z[idx] += vel_z[idx] * step;
        }
    };

    // Launch configuration
    int threadsPerBlock = 128;
    int blocksPerGrid = (numEntities + threadsPerBlock - 1) / threadsPerBlock;

    updateKernel<<<blocksPerGrid, threadsPerBlock>>>(
        d_px, d_py, d_pz,
        d_vx, d_vy, d_vz,
        numEntities, dt
    );

    // Synchronize before copying back
    cudaDeviceSynchronize();

    // Copy updated positions back
    cudaMemcpy(host_pos_x.data(), d_px, bytes, cudaMemcpyDeviceToHost);
    cudaMemcpy(host_pos_y.data(), d_py, bytes, cudaMemcpyDeviceToHost);
    cudaMemcpy(host_pos_z.data(), d_pz, bytes, cudaMemcpyDeviceToHost);

    // Reconstruct entity positions
    for (int i = 0; i < numEntities; ++i) {
        entities[i].pos.x = host_pos_x[i];
        entities[i].pos.y = host_pos_y[i];
        entities[i].pos.z = host_pos_z[i];
    }

    // Cleanup GPU memory
    cudaFree(d_px); cudaFree(d_py); cudaFree(d_pz);
    cudaFree(d_vx); cudaFree(d_vy); cudaFree(d_vz);

    return 0;
}

#include <thrust/host_vector.h>
#include <thrust/device_vector.h>
#include <thrust/sort.h>
#include <thrust/equal_range.h>
#include <thrust/transform.h>
#include <thrust/iterator/counting_iterator.h>
#include <thrust/copy.h>
#include <iostream>

// Functor to determine if a value exists at the position returned by lower_bound
struct check_existence {
    const thrust::device_ptr<int> sorted_data;
    const int size;

    check_existence(thrust::device_ptr<int> data, int len) : sorted_data(data), size(len) {}

    __device__ bool operator()(int pos, int target) const {
        // If pos is within bounds and the element at pos equals target, it's present
        return (pos < size && sorted_data[pos] == target);
    }
};

int main() {
    // Input sequences
    thrust::host_vector<int> base_list = {1, 2, 3, 5, 7, 8, 10};
    thrust::host_vector<int> query_list = {1, 3, 4, 8, 10, 11};

    // Move to device memory
    thrust::device_vector<int> sorted_base = base_list;
    thrust::device_vector<int> queries = query_list;

    // Prepare storage for results
    thrust::device_vector<int> indices(queries.size());
    thrust::device_vector<bool> found_flags(queries.size());

    // Use equal_range to get [first, last) range where value would be inserted
    // Since we only need lower bound, we'll use equal_range but take .first
    auto first_it = thrust::equal_range(sorted_base.begin(), sorted_base.end(), queries.begin(), queries.end()).first;
    thrust::copy(first_it, first_it + queries.size(), indices.begin());

    // Determine presence: compare the candidate at index with actual query value
    thrust::transform(
        indices.begin(), indices.end(),
        queries.begin(),
        found_flags.begin(),
        check_existence(sorted_base.data(), sorted_base.size())
    );

    // Transfer back to host for output
    thrust::host_vector<int> result_indices = indices;
    thrust::host_vector<bool> result_flags = found_flags;

    for (size_t idx = 0; idx < queries.size(); ++idx) {
        std::cout << "Value " << queries[idx]
                  << " is found at position " << result_indices[idx]
                  << " (present: " << (result_flags[idx] ? "true" : "false") << ")" << std::endl;
    }

    return 0;
}

#include <QHttpMultiPart>
#include <QHttpPart>
#include <QNetworkRequest>
#include <QNetworkAccessManager>
#include <QUrl>
#include <QDebug>

void Share::upload(const QByteArray &data) {
    QHttpMultiPart *multipart = new QHttpMultiPart(QHttpMultiPart::FormDataType);

    // Prepare text field part
    QHttpPart textfield;
    textfield.setHeader(QNetworkRequest::ContentDispositionHeader, QVariant("form-data; name=\"text\""));
    textfield.setBody("Screenshot.png");

    // Prepare image field part
    QHttpPart imagefield;
    imagefield.setHeader(QNetworkRequest::ContentTypeHeader, QVariant("image/png"));
    imagefield.setHeader(QNetworkRequest::ContentDispositionHeader, QVariant("form-data; name=\"image\"; filename=\"Screenshot.png\""));
    imagefield.setBody(data);

    // Append parts to multipart
    multipart->append(textfield);
    multipart->append(imagefield);

    // Setup network request
    QNetworkRequest req(QUrl("http://localhost:8000/api/upload"));
    QNetworkAccessManager *netmanager = new QNetworkAccessManager(this);

    // Connect signal for reply handling
    connect(netmanager, &QNetworkAccessManager::finished, this, &Share::reply_finished);

    // Send POST request with multipart data
    netmanager->post(req, multipart);

    qDebug() << QString::fromLatin1(data);
}

#include <immintrin.h>
#include <algorithm>
#include <array>
#include <inttypes.h>

typedef std::array<uint8_t, 3> Vec3B;
typedef std::array<int32_t, 3> Vec3I;

Vec3B v3bSpread(Vec3B const& source, Vec3B dest, int32_t drop) {
    // Convert uint8_t arrays to int32_t arrays
    Vec3I intSource = {static_cast<int32_t>(source[0]), 
                       static_cast<int32_t>(source[1]), 
                       static_cast<int32_t>(source[2])};
    Vec3I intDest = {static_cast<int32_t>(dest[0]), 
                     static_cast<int32_t>(dest[1]), 
                     static_cast<int32_t>(dest[2])};

    // Find maximum value among the three components manually
    int32_t maxVal = intSource[0];
    for (int i = 1; i < 3; ++i) {
        if (intSource[i] > maxVal) {
            maxVal = intSource[i];
        }
    }

    // Calculate spread for each component
    Vec3I result;
    for (int i = 0; i < 3; ++i) {
        int32_t numerator = intSource[i];
        int32_t quotient = (maxVal != 0) ? (numerator / maxVal) : 0;
        int32_t product = quotient * drop;
        result[i] = numerator - product;

        // Clamp to destination value (take maximum)
        if (result[i] < intDest[i]) {
            result[i] = intDest[i];
        }
    }

    // Store back to destination array
    dest[0] = static_cast<uint8_t>(result[0]);
    dest[1] = static_cast<uint8_t>(result[1]);
    dest[2] = static_cast<uint8_t>(result[2]);

