// Helper function to write data in chunks to file stream
void writeChunked(const unsigned char *buffer, size_t totalLen, FILE *outStream) {
    size_t chunkSize;

    for (size_t remaining = totalLen; remaining > 0; remaining -= chunkSize, buffer += chunkSize) {
        chunkSize = remaining;
        if (chunkSize > 1024)
            chunkSize = 1024;

        size_t actuallyWritten = fwrite(buffer, 1, chunkSize, outStream);
        if (actuallyWritten != chunkSize && ferror(outStream)) {
            throw std::runtime_error("Error writing to output stream");
        }
        fflush(outStream);
    }
}

int main(int argc, char **argv) {
    // Validate command line arguments
    if (argc < 5) {
        std::cerr << "Usage: " << argv[0] << " totalbytes bytechunk height width" << std::endl;
        return 1;
    }

    // Parse input parameters from command line
    long totalBytes = std::stol(argv[argc-4]);
    long chunkSize = std::stol(argv[argc-3]);
    long imageHeight = std::stol(argv[argc-2]);
    long imageWidth = std::stol(argv[argc-1]);
    long dataOffset = totalBytes / sizeof(double) / 2;

    // Allocate and populate data buffer
    std::vector<double> inputData(totalBytes / sizeof(double));
    int bufferIndex = 0;
    size_t bytesReadTotal = 0;

    // Read input data in chunks from stdin
    while (bytesReadTotal < static_cast<size_t>(totalBytes)) {
        size_t currentChunk = fread(&inputData[bufferIndex], 1, chunkSize, stdin);
        if (currentChunk != static_cast<size_t>(chunkSize) && ferror(stdin)) {
            throw std::runtime_error("Error reading from standard input");
        }
        bufferIndex += static_cast<int>(currentChunk / sizeof(double));
        bytesReadTotal += currentChunk;
    }

    // Process data using MutualInformation class
    MutualInformation miCalculator;
    miCalculator.Initialize(inputData.data(), imageHeight, imageWidth, dataOffset);
    miCalculator.calculateMutualInformation();

    // Get results and prepare for output
    std::vector<double> resultData = miCalculator.getResults();
    size_t outputCount = 0;
    bufferIndex = 0;

    // Write output in chunks to stdout
    while (outputCount < static_cast<size_t>(totalBytes / 2)) {
        size_t writtenBytes = 0;
        try {
            writtenBytes = resultData.size() - bufferIndex < chunkSize / sizeof(double) 
                ? (resultData.size() - bufferIndex) * sizeof(double) 
                : chunkSize;
            writeChunked(reinterpret_cast<const unsigned char*>(&resultData[bufferIndex]), writtenBytes, stdout);
        } catch (...) {
            throw std::runtime_error("Error writing to standard output");
        }

        outputCount += writtenBytes;
        bufferIndex += static_cast<int>(writtenBytes / sizeof(double));
    }

    return 0;
}

#include <iostream>
