int PixyInterpreter::acquire_image_buffer(unsigned char *output_buffer, int buffer_capacity) {
    unsigned int frame_block_size = 8;          
    unsigned char *image_data;                
    int32_t status_code, pixel_format;
    int8_t display_flags;
    int operation_result;
    uint16_t image_width, image_height;
    uint32_t total_pixels;

    // Halt camera operations first
    operation_result = pixy_command("stop", END_OUT_ARGS, &status_code, END_IN_ARGS);  
    std::printf("Camera halted - result %d, status %d\n", operation_result, status_code);

    status_code = 0;
    operation_result = pixy_command("cam_getFrame", 0x01, 0x21, 0x02, 0, 0x02, 0, 0x02, 320, 0x02, 200, 0, 
                                   &status_code, &pixel_format, &display_flags, &image_width, &image_height, 
                                   &total_pixels, &image_data, 0);

    std::printf("Image acquisition - result %d, status %d\n", operation_result, status_code); 
    std::printf("Dimensions: width=%d height=%d, pixel count=%d\n", image_width, image_height, total_pixels);  

    if (operation_result != 0) return operation_result;

    // Verify buffer capacity before copying
    if (total_pixels > static_cast<uint32_t>(buffer_capacity)) {
        std::printf("Error: Image data exceeds available buffer space.\n");
        return -1;
    }

    // Transfer image data to caller's buffer
    std::memcpy(output_buffer, image_data, total_pixels);

    // Display central 8x8 pixel block for verification
    unsigned int row_idx, col_idx, pixel_index, center_offset;

    center_offset = (image_height / 2) * image_width + image_width / 2;
    for (row_idx = 0; row_idx < frame_block_size; row_idx++) {
        for (col_idx = 0; col_idx < frame_block_size; col_idx++) {
            pixel_index = row_idx * image_width + col_idx + center_offset;
            std::printf(" %02x", output_buffer[pixel_index]);
        }
        std::printf("\n");
    }

    // Restart camera operations
    operation_result = pixy_command("run", END_OUT_ARGS, &status_code, END_IN_ARGS);
    std::printf("Camera resumed - result %d, status %d\n", operation_result, status_code);

    return static_cast<int>(total_pixels);
}

