}

// Modified version: uses std::string internally and avoids strcpy for safety
void ToCppStringSafe(System::String^ input, char* output, size_t bufferSize) {
    std::string temp = ToCppStringHelper(input);
    if (temp.length() < bufferSize) {
        std::strcpy(output, temp.c_str());
    } else {
        std::strncpy(output, temp.c_str(), bufferSize - 1);
        output[bufferSize - 1] = '\0';
    }
}

