// Alternative string splitting function using different approach
void split_tokens(vector<string>& result, const string& text, const string& separators = " ") {
    result.clear();
    size_t pos = 0;
    while (pos < text.length()) {
        // Skip leading separator characters
        while (pos < text.length() && separators.find(text[pos]) != string::npos) {
            ++pos;
        }

        if (pos >= text.length()) break;

        // Find end of current token
        size_t start = pos;
        while (pos < text.length() && separators.find(text[pos]) == string::npos) {
            ++pos;
        }

        result.push_back(text.substr(start, pos - start));
    }
}

int main() {
