// Check if a number is prime (returns false for numbers <= 1)
bool checkPrime(int value) {
    if (value <= 1) return false;
    for (int divisor = 2; divisor * divisor <= value; divisor++) {
        if (value % divisor == 0) return false;
    }
    return true;
}

int main() {
    int primesFound = 0;     // Counter for prime numbers identified
    int currentNum = 2;      // Current number being tested for primality
    double total = 0;        // Accumulated sum of prime numbers
    double meanValue;        // Current average of primes found

    do {
        if (checkPrime(currentNum)) {
            primesFound++;
            total += currentNum;
            meanValue = total / primesFound;
            cout << "Prime number " << primesFound << ": " << currentNum << endl;
            cout << "Running average: " << meanValue << endl;
        }
        currentNum++;
    } while (primesFound < 6);

    return 0;
}

