class AsyncWork {
public:
    struct handler {
        AsyncWork get_return_object() { 
            return AsyncWork{std::coroutine_handle<handler>::from_promise(*this)}; 
        }
        std::suspend_never yield_value() { return {}; }
        std::suspend_never initial_suspend() { return {}; }
        std::suspend_never final_suspend() noexcept { return {}; }
        void return_void() {}
        void unhandled_exception() { std::terminate(); }
    };

    bool finished() const { return m_coro.done(); }
    void run() { m_coro.resume(); }
    void suspend_now() { m_coro.promise().m_should_suspend = true; }

private:
    std::coroutine_handle<handler> m_coro;

    AsyncWork(std::coroutine_handle<handler> coro) : m_coro(coro) {}
    ~AsyncWork() { if (m_coro) m_coro.destroy(); }

    friend struct handler;
};

AsyncWork process_task() {
    for (;;) {
        std::cout << "Async task executing\n";
        co_await std::suspend_always{};
        std::cout << "Async task continuing\n";
    }
}

int main() {
