// Perform matrix multiplication using optimized loop order (i-k-j)
void matrixMultiplyCPU(float* A, float* B, float* C, int N) {
    for (int i = 0; i < N; ++i) {
        for (int k = 0; k < N; ++k) {
            float a_ik = A[i * N + k];
            for (int j = 0; j < N; ++j) {
                C[i * N + j] += a_ik * B[k * N + j];
            }
        }
    }
}

int main() {
    int N = 1024;
    std::vector<float> A(N * N, 1.0f);
    std::vector<float> B(N * N, 1.0f);
    std::vector<float> C(N * N, 0.0f);

    auto begin_time = std::chrono::high_resolution_clock::now();
    matrixMultiplyCPU(A.data(), B.data(), C.data(), N);
    auto end_time = std::chrono::high_resolution_clock::now();

    std::chrono::duration<double> elapsed = end_time - begin_time;
    std::cout << "CPU Time: " << elapsed.count() << " seconds" << std::endl;

    return 0;
}

