#define CUDA_CHECK(call) \
    do { \
        cudaError_t status = call; \
        if (status != cudaSuccess) { \
            std::cerr << "CUDA error: " << cudaGetErrorString(status) \
                      << " in file " << __FILE__ << ", line " << __LINE__ << std::endl; \
            std::exit(EXIT_FAILURE); \
        } \
    } while (0)

#define MATRIX_DIM 1024
#define THREAD_BLOCK 16

__global__ void matrixMultiplyKernel(const float* __restrict__ A, 
                                     const float* __restrict__ B, 
                                     float* __restrict__ C, 
                                     int dimension, 
                                     int* atomicCounter) {
    int y = blockIdx.y * blockDim.y + threadIdx.y;
    int x = blockIdx.x * blockDim.x + threadIdx.x;

    if (y < dimension && x < dimension) {
        float accumulator = 0.0f;
        for (int k = 0; k < dimension; ++k) {
            accumulator += A[y * dimension + k] * B[k * dimension + x];
        }
        C[y * dimension + x] = accumulator;

        atomicAdd(atomicCounter, 1);
    }
}

void showProgress(int completed, int total) {
    int percentage = (completed * 100) / total;
    printf("Progress: %d.%02d %%\r", percentage / 100, percentage % 100);
    fflush(stdout);
}

int main() {
    float *hostA, *hostB, *hostC, *deviceA, *deviceB, *deviceC;
    int *hostProgress, *deviceProgress;
    size_t matrixBytes = MATRIX_DIM * MATRIX_DIM * sizeof(float);
    size_t counterBytes = sizeof(int);

    // Allocate host memory
    hostA = static_cast<float*>(malloc(matrixBytes));
    hostB = static_cast<float*>(malloc(matrixBytes));
    hostC = static_cast<float*>(malloc(matrixBytes));
    hostProgress = static_cast<int*>(malloc(counterBytes));

    // Initialize matrices with constant values
    for (size_t i = 0; i < MATRIX_DIM * MATRIX_DIM; ++i) {
        hostA[i] = 1.0f;
        hostB[i] = 1.0f;
        hostC[i] = 0.0f;
    }

    // Allocate device memory
    CUDA_CHECK(cudaMalloc(&deviceA, matrixBytes));
    CUDA_CHECK(cudaMalloc(&deviceB, matrixBytes));
    CUDA_CHECK(cudaMalloc(&deviceC, matrixBytes));
    CUDA_CHECK(cudaMalloc(&deviceProgress, counterBytes));

    // Transfer initial data to GPU
    CUDA_CHECK(cudaMemcpy(deviceA, hostA, matrixBytes, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(deviceB, hostB, matrixBytes, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(deviceProgress, hostProgress, counterBytes, cudaMemcpyHostToDevice));

    // Configure execution parameters
    dim3 threadsPerBlock(THREAD_BLOCK, THREAD_BLOCK);
    dim3 blocksPerGrid((MATRIX_DIM + THREAD_BLOCK - 1) / THREAD_BLOCK,
                       (MATRIX_DIM + THREAD_BLOCK - 1) / THREAD_BLOCK);

    // Create CUDA stream for asynchronous operations
    cudaStream_t computeStream;
    CUDA_CHECK(cudaStreamCreate(&computeStream));

    int totalWork = MATRIX_DIM * MATRIX_DIM;
    int updateStep = totalWork / 100;

    // Launch kernel multiple times to simulate progress updates
    for (int processed = 0; processed < totalWork; processed += updateStep) {
        matrixMultiplyKernel<<<blocksPerGrid, threadsPerBlock, 0, computeStream>>>(
            deviceA, deviceB, deviceC, MATRIX_DIM, deviceProgress);
        CUDA_CHECK(cudaStreamSynchronize(computeStream));

        CUDA_CHECK(cudaMemcpy(hostProgress, deviceProgress, counterBytes, cudaMemcpyDeviceToHost));
        showProgress(*hostProgress, totalWork);
    }

    // Ensure final computation is complete
    CUDA_CHECK(cudaStreamSynchronize(computeStream));

    // Retrieve final results
    CUDA_CHECK(cudaMemcpy(hostC, deviceC, matrixBytes, cudaMemcpyDeviceToHost));

    // Cleanup resources
    free(hostA);
    free(hostB);
    free(hostC);
    free(hostProgress);
    CUDA_CHECK(cudaFree(deviceA));
    CUDA_CHECK(cudaFree(deviceB));
    CUDA_CHECK(cudaFree(deviceC));
    CUDA_CHECK(cudaFree(deviceProgress));
    CUDA_CHECK(cudaStreamDestroy(computeStream));

    return 0;
}

