// Find the maximum element in a vector of integers
int findMaximum(const std::vector<int>& data) {
    if (data.empty()) {
        return INT_MIN;  // Return the smallest possible integer for empty input
    }
    int current_max = data[0];
    size_t index = 1;
    while (index < data.size()) {
        if (data[index] > current_max) {
            current_max = data[index];
        }
        index++;
    }
    return current_max;
}

