__global__ void calc(int total, float *values, float *newvalues) {
    // Calculate global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Boundary check with adjusted condition
    if (idx >= total || idx < 0) return;

    // Process only valid indices
    if (idx < total - 1) {
        // Load current value once
        float base_val = values[idx];

        // Reverse the loop direction for inner processing
        for (int j = total - 1; j > idx; j--) {
            // Compute difference and square in single expression
            float diff = values[j] - base_val;
            float squared = diff * diff;

            // Check condition and perform atomic operation
            if (squared < 10.0f) {
                atomicExch(&newvalues[j], squared);
            }
        }
    }
}

#include <cstdint>
#include <iostream>

// Computes the high 64 bits of the 128-bit product of two 64-bit unsigned integers
uint64_t compute_upper_product(uint64_t a, uint64_t b) {
    // Split inputs into high and low 32-bit parts
    uint32_t a_lo = static_cast<uint32_t>(a);
    uint32_t a_hi = static_cast<uint32_t>(a >> 32);
    uint32_t b_lo = static_cast<uint32_t>(b);
    uint32_t b_hi = static_cast<uint32_t>(b >> 32);

    // Compute partial products
    uint64_t p0 = static_cast<uint64_t>(a_lo) * b_lo;
    uint64_t p3 = static_cast<uint64_t>(a_hi) * b_hi;
    uint64_t p1 = static_cast<uint64_t>(a_hi) * b_lo;
    uint64_t p2 = static_cast<uint64_t>(a_lo) * b_hi;

    // Combine cross terms and handle carries
    uint64_t mid_sum = p1 + p2;
    uint64_t carry_from_low = (p0 >> 32) + (mid_sum & 0xFFFFFFFF00000000ULL ? 
        ((mid_sum >> 32) & 0xFFFFFFFFU) : (mid_sum >> 32));

    // Assemble final result: high part includes p3, shifted cross terms, and carry
    return p3 + (mid_sum << 32) + (carry_from_low >> 32);
}

int main() {
    uint64_t operand_a = 1234567890123456789ULL;
    uint64_t operand_b = 9876543210987654321ULL;
    uint64_t upper_component = compute_upper_product(operand_a, operand_b);

    std::cout << "Upper component of multiplication: " << upper_component << std::endl;
    return 0;
}

