#include <thrust/device_vector.h>
#include <thrust/scan.h>

// Kernel to compute the sum of children for each node and update node value
__global__ void aggregate_children_kernel(int* values, int* adjacency, int total_nodes) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid < total_nodes) {
        int current_val = values[tid];
        int child_count = adjacency[tid * 2];
        int* child_list = &adjacency[tid * 2 + 1];

        int child_sum = 0;
        for (int j = 0; j < child_count; ++j) {
            child_sum += values[child_list[j]];
        }

        values[tid] = current_val + child_sum;
    }
}

// Wrapper function that performs bottom-up aggregation followed by prefix sum
void bottom_up_aggregation(int* host_values, int* host_adjacency, int node_count) {
    // Transfer data to device
    thrust::device_vector<int> d_values(host_values, host_values + node_count);
    thrust::device_vector<int> d_adjacency(host_adjacency, host_adjacency + node_count * 2);

    // Launch kernel with appropriate grid/block configuration
    const int block_size = 256;
    int grid_size = (node_count + block_size - 1) / block_size;

    aggregate_children_kernel<<<grid_size, block_size>>>(
        thrust::raw_pointer_cast(d_values.data()),
        thrust::raw_pointer_cast(d_adjacency.data()),
        node_count
    );

    // Perform inclusive scan on updated values
    thrust::inclusive_scan(d_values.begin(), d_values.end(), d_values.begin());

    // Copy results back to host
    thrust::copy(d_values.begin(), d_values.end(), host_values);
}

