constexpr int arraySize = 5;

__global__ void initializeArray(int* data) {
    cudaError_t status = cudaMemsetAsync(data, 0xFF, arraySize * sizeof(int), 0);
    if (status != cudaSuccess) {
        std::fprintf(stderr, "CUDA error in cudaMemsetAsync: %s\n", cudaGetErrorString(status));
    }
}

int main() {
    cudaError_t result;
    int hostArray[arraySize] = {12, 12, 12, 12, 12};
    int* deviceArray = nullptr;

    // Set CUDA device
    result = cudaSetDevice(0);
    if (result != cudaSuccess) {
        std::fprintf(stderr, "Failed to set CUDA device! Check for a compatible GPU.\n");
        goto cleanup;
    }

    // Allocate memory on device
    result = cudaMalloc(reinterpret_cast<void**>(&deviceArray), arraySize * sizeof(int));
    if (result != cudaSuccess) {
        std::fprintf(stderr, "Memory allocation on device failed!\n");
        goto cleanup;
    }

    // Copy data from host to device
    result = cudaMemcpy(deviceArray, hostArray, arraySize * sizeof(int), cudaMemcpyHostToDevice);
    if (result != cudaSuccess) {
        std::fprintf(stderr, "Host-to-device copy failed!\n");
        goto cleanup;
    }

    // Launch kernel with single thread
    initializeArray<<<1, 1>>>(deviceArray);

    // Check for kernel launch errors
    result = cudaGetLastError();
    if (result != cudaSuccess) {
        std::fprintf(stderr, "Kernel execution failed: %s\n", cudaGetErrorString(result));
        goto cleanup;
    }

    // Ensure kernel completion
    result = cudaDeviceSynchronize();
    if (result != cudaSuccess) {
        std::fprintf(stderr, "Device synchronization error after kernel launch: %s\n", cudaGetErrorString(result));
        goto cleanup;
    }

    // Copy results back to host
    result = cudaMemcpy(hostArray, deviceArray, arraySize * sizeof(int), cudaMemcpyDeviceToHost);
    if (result != cudaSuccess) {
        std::fprintf(stderr, "Device-to-host copy failed!\n");
        goto cleanup;
    }

    // Cleanup resources
    cudaFree(deviceArray);
    result = cudaDeviceReset();
    if (result != cudaSuccess) {
        std::fprintf(stderr, "Device reset failed!\n");
        goto cleanup;
    }

    // Output final state
    std::printf("CUDA status: %d\n", result);
    std::printf("{%d,%d,%d,%d,%d}\n", hostArray[0], hostArray[1], hostArray[2], hostArray[3], hostArray[4]);
    return 0;

cleanup:
    if (deviceArray != nullptr) {
        cudaFree(deviceArray);
    }
    cudaDeviceReset();
    return 1;
}

