// Structure to hold 2D coordinates
struct coordinate  
{  
    double x_coord, y_coord;  
};

__global__ void updateCoordinates(coordinate* device_coords)  
{  
    // Only the first thread in the grid performs the update
    if (threadIdx.x == 0 && threadIdx.y == 0 && blockIdx.x == 0 && blockIdx.y == 0)
    {  
        device_coords->x_coord = 100.0;  
        device_coords->y_coord = 100.0;    
    }
}  

int main()  
{  
    // Allocate host memory for a single coordinate
    coordinate *host_coords = (coordinate*)malloc(sizeof(coordinate));  
    host_coords->x_coord = 10.0;   
    host_coords->y_coord = 10.0;    

    // Allocate device memory
    coordinate *device_coords;  
    cudaMalloc((void**)&device_coords, sizeof(coordinate));  

    // Copy data from host to device
    cudaMemcpy(device_coords, host_coords, sizeof(coordinate), cudaMemcpyHostToDevice);  

    // Define execution configuration: 16x16 threads per block, 1x1 blocks
    dim3 threadsPerBlock(16, 16);  
    dim3 blocksPerGrid(1, 1);  

    // Launch kernel with specified configuration
    updateCoordinates<<<blocksPerGrid, threadsPerBlock>>>(device_coords);  

    // Wait for GPU operations to complete before copying back results
    cudaDeviceSynchronize();  

    // Copy updated data back to host
    cudaMemcpy(host_coords, device_coords, sizeof(coordinate), cudaMemcpyDeviceToHost);    
    std::cout << host_coords->x_coord << " " << host_coords->y_coord << std::endl;

