// Custom subclass procedure to manage tooltip display on mouse movement
LRESULT CALLBACK TooltipSubclassProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam, 
                                     UINT_PTR subclassId, DWORD_PTR refData) {
    static HWND tooltipWindow = nullptr;

    switch (message) {
        case WM_MOUSEMOVE:
        case WM_NCMOUSEMOVE: {
            // Initialize tooltip only once when first needed
            if (!tooltipWindow) {
                tooltipWindow = CreateWindowEx(0, TOOLTIPS_CLASS, nullptr, 
                                              WS_POPUP | TTS_ALWAYSTIP,
                                              CW_USEDEFAULT, CW_USEDEFAULT, 
                                              CW_USEDEFAULT, CW_USEDEFAULT,
                                              hwnd, nullptr, GetModuleHandle(nullptr), nullptr);

                if (tooltipWindow) {
                    TOOLINFO toolInfo = {0};
                    toolInfo.cbSize = sizeof(TOOLINFO);
                    toolInfo.uFlags = TTF_IDISHWND | TTF_SUBCLASS;
                    toolInfo.uId = reinterpret_cast<UINT_PTR>(hwnd);
                    toolInfo.hwnd = hwnd;
                    toolInfo.lpszText = L"Your custom tooltip text";
                    SendMessage(tooltipWindow, TTM_ADDTOOL, 0, reinterpret_cast<LPARAM>(&toolInfo));
                }
            }
            break;
        }

        case WM_DESTROY: {
            // Clean up tooltip window during destruction
            if (tooltipWindow) {
                DestroyWindow(tooltipWindow);
                tooltipWindow = nullptr;
            }
            break;
        }
    }

    // Pass unhandled messages to the default subclass implementation
    return DefSubclassProc(hwnd, message, wParam, lParam);
}

// Helper function to apply subclassing to a target window
void AttachTooltipSubclass(HWND targetWindow) {
    SetWindowSubclass(targetWindow, TooltipSubclassProc, 0, 0);
}

// Entry point demonstrating usage
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow) {
    // Locate the target window by class and title
    HWND targetHwnd = FindWindow(L"TargetWindowClass", L"TargetWindowName");

    if (targetHwnd) {
        AttachTooltipSubclass(targetHwnd);
    }

    // Standard message loop for application execution
    MSG message;
    while (GetMessage(&message, nullptr, 0, 0)) {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }

    return static_cast<int>(message.wParam);
}

