// Count rows in the matrix whose elements sum to zero
int countZeroSumRows(const std::vector<std::vector<int>>& matrix) {
    int count = 0;

    for (const auto& row : matrix) {
        // Calculate row sum using manual accumulation instead of std::reduce
        int rowSum = 0;
        for (int element : row) {
            rowSum += element;
        }

        if (rowSum == 0) {
            ++count;
        }
    }

    return count;
}

