#include <emmintrin.h> // For SSE2
#include <omp.h>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <sys/time.h>

void blendOverlays(const uint8_t* baseImage, const uint8_t* overlayData, uint8_t* outputBuffer, int imgWidth, int imgHeight) {
    int totalPixels = imgWidth * imgHeight;
    int alignedPixels = totalPixels - (totalPixels % 16); // Process in blocks of 16 pixels

    __m128i nullVec = _mm_setzero_si128(); // Vector of zero bytes

    #pragma omp parallel for
    for (int idx = 0; idx < alignedPixels; idx += 16) {
        // Load four consecutive RGBA vectors (each 16 bytes)
        __m128i rgbaBlock0 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(overlayData + idx * 4));
        __m128i rgbaBlock1 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(overlayData + idx * 4 + 16));
        __m128i rgbaBlock2 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(overlayData + idx * 4 + 32));
        __m128i rgbaBlock3 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(overlayData + idx * 4 + 48));

        // Extract alpha channels from each block
        __m128i alpha0 = _mm_shuffle_epi32(rgbaBlock0, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alpha1 = _mm_shuffle_epi32(rgbaBlock1, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alpha2 = _mm_shuffle_epi32(rgbaBlock2, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alpha3 = _mm_shuffle_epi32(rgbaBlock3, _MM_SHUFFLE(3, 3, 3, 3));

        // Create masks: 0xFF where alpha == 0, 0x00 otherwise
        __m128i mask0 = _mm_cmpeq_epi8(alpha0, nullVec);
        __m128i mask1 = _mm_cmpeq_epi8(alpha1, nullVec);
        __m128i mask2 = _mm_cmpeq_epi8(alpha2, nullVec);
        __m128i mask3 = _mm_cmpeq_epi8(alpha3, nullVec);

        // Load corresponding RGB source data (3 bytes per pixel)
        __m128i srcBlock0 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(baseImage + idx * 3));
        __m128i srcBlock1 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(baseImage + idx * 3 + 16));
        __m128i srcBlock2 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(baseImage + idx * 3 + 32));
        __m128i srcBlock3 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(baseImage + idx * 3 + 48));

        // Blend: use overlay if alpha != 0, else use source
        __m128i result0 = _mm_or_si128(
            _mm_andnot_si128(mask0, rgbaBlock0),
            _mm_and_si128(mask0, srcBlock0)
        );
        __m128i result1 = _mm_or_si128(
            _mm_andnot_si128(mask1, rgbaBlock1),
            _mm_and_si128(mask1, srcBlock1)
        );
        __m128i result2 = _mm_or_si128(
            _mm_andnot_si128(mask2, rgbaBlock2),
            _mm_and_si128(mask2, srcBlock2)
        );
        __m128i result3 = _mm_or_si128(
            _mm_andnot_si128(mask3, rgbaBlock3),
            _mm_and_si128(mask3, srcBlock3)
        );

        // Store results to destination buffer
        _mm_storeu_si128(reinterpret_cast<__m128i*>(outputBuffer + idx * 3), result0);
        _mm_storeu_si128(reinterpret_cast<__m128i*>(outputBuffer + idx * 3 + 16), result1);
        _mm_storeu_si128(reinterpret_cast<__m128i*>(outputBuffer + idx * 3 + 32), result2);
        _mm_storeu_si128(reinterpret_cast<__m128i*>(outputBuffer + idx * 3 + 48), result3);
    }

    // Handle remaining pixels that don't fit into 16-pixel chunks
    for (int p = alignedPixels; p < totalPixels; ++p) {
        if (overlayData[p * 4 + 3] == 0) {
            outputBuffer[p * 3]     = baseImage[p * 3];
            outputBuffer[p * 3 + 1] = baseImage[p * 3 + 1];
            outputBuffer[p * 3 + 2] = baseImage[p * 3 + 2];
        } else {
            outputBuffer[p * 3]     = overlayData[p * 4];
            outputBuffer[p * 3 + 1] = overlayData[p * 4 + 1];
            outputBuffer[p * 3 + 2] = overlayData[p * 4 + 2];
        }
    }
}

uint64_t getCurrentTimeMicros() {
    timeval currentTime;
    gettimeofday(&currentTime, nullptr);
    return static_cast<uint64_t>(currentTime.tv_sec) * 1000000ULL + 
           static_cast<uint64_t>(currentTime.tv_usec);
}

int main(int argc, char** argv) {
    const int SCREEN_WIDTH = 1920;
    const int SCREEN_HEIGHT = 1080;
    size_t rgbSize = SCREEN_WIDTH * SCREEN_HEIGHT * 3;

    uint8_t* overlayBuffer = new uint8_t[SCREEN_WIDTH * SCREEN_HEIGHT * 4];
    uint8_t* inputBuffer   = new uint8_t[rgbSize];
    uint8_t* outputBuffer  = new uint8_t[rgbSize];

    uint64_t startTime = getCurrentTimeMicros();

    for (int iter = 0; iter < 1000; ++iter) {
        blendOverlays(inputBuffer, overlayBuffer, outputBuffer, SCREEN_WIDTH, SCREEN_HEIGHT);
    }

    printf("elapsed: %lu ms\n", (getCurrentTimeMicros() - startTime) / 1000);

    delete[] overlayBuffer;
    delete[] inputBuffer;
    delete[] outputBuffer;

    return 0;
}

#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <nlohmann/json.hpp>
#include <fstream>
#include <sstream>

using json = nlohmann::json;

// Constants for temperature adjustments
const double ALTITUDE_FACTOR = -0.6; // per 100 meters
const std::map<std::string, double> TIME_CORRECTION = {
    {"morning", -2.0},
    {"midday", 0.0},
    {"evening", -1.0},
    {"late_night", -3.0}
};
const std::map<std::string, double> SEASONAL_FACTOR = {
    {"cold_season", -5.0},
    {"early_spring", 0.0},
    {"warm_season", 5.0},
    {"fall", 0.0}
};

// Compute adjustment based on altitude (in meters)
double computeAltitudeEffect(double heightInMeters) {
    return (heightInMeters / 100.0) * ALTITUDE_FACTOR;
}

// Get time-of-day correction factor
double getTimeCorrection(const std::string& period) {
    auto iter = TIME_CORRECTION.find(period);
    return (iter != TIME_CORRECTION.end()) ? iter->second : 0.0;
}

// Get seasonal correction factor
double getSeasonalEffect(const std::string& seasonName) {
    auto iter = SEASONAL_FACTOR.find(seasonName);
    return (iter != SEASONAL_FACTOR.end()) ? iter->second : 0.0;
}

// Convert Celsius to Fahrenheit with environmental adjustments
double convertTo Fahrheit(double baseCelsius, double elevation, 
                         const std::string& timeOfDay, const std::string& season) {
    double correction = computeAltitudeEffect(elevation) + 
                        getTimeCorrection(timeOfDay) + 
                        getSeasonalEffect(season);
    double adjustedTemp = baseCelsius + correction;
    return adjustedTemp * 9.0 / 5.0 + 32.0;
}

// Process temperature data and output in requested format
json handleTemperatureProcessing(const json& input, const std::string& format) {
    json outputArray = json::array();

    for (const auto& item : input) {
        double tempC = item.value("temp_c", 0.0);
        double elev = item.value("elevation", 0.0);
        std::string period = item.value("time_period", "midday");
        std::string season = item.value("season_type", "early_spring");

        double tempF = convertToFahrheit(tempC, elev, period, season);

        outputArray.push_back({
            {"place", item["location"]},
            {"celsius", tempC},
            {"fahrenheit", tempF},
            {"altitude", elev},
            {"time_of_day", period},
            {"season", season}
        });
    }

    if (format == "json") {
        return outputArray;
    } else if (format == "csv") {
        std::ofstream csvFile("results.csv");
        csvFile << "place,celsius,fahrenheit,altitude,time_of_day,season\n";
        for (const auto& record : outputArray) {
            csvFile << record["place"].get<std::string>() << ","
                    << record["celsius"].get<double>() << ","
                    << record["fahrenheit"].get<double>() << ","
                    << record["altitude"].get<double>() << ","
                    << record["time_of_day"].get<std::string>() << ","
                    << record["season"].get<std::string>() << "\n";
        }
        csvFile.close();
        return json::array();
    } else {
        return outputArray;
    }
}

int main() {
    json dataset = {
        {{"location", "New York"}, {"temp_c", 20.0}, {"elevation", 10.0}, {"time_period", "midday"}, {"season_type", "warm_season"}},
        {{"location", "Los Angeles"}, {"temp_c", 25.0}, {"elevation", 50.0}, {"time_period", "evening"}, {"season_type", "early_spring"}},
        {{"location", "Denver"}, {"temp_c", 15.0}, {"elevation", 1600.0}, {"time_period", "late_night"}, {"season_type", "cold_season"}}
    };

    json result = handleTemperatureProcessing(dataset, "json");
    std::cout << result.dump(4) << std::endl;

    return 0;
}

