#include <iostream>
#include <chrono>
#include <vector>
#include <random>
#include <algorithm>

// Constants for benchmark configuration
const size_t LOOP_COUNT = 10000000;
const size_t BUFFER_LENGTH = 1024 * 1024; // 1MB
const size_t MEMORY_ALIGNMENT = 16;

// Initialize buffer with test data
void initializeBuffer(std::vector<uint8_t>& buffer) {
    for (size_t pos = 0; pos < BUFFER_LENGTH; pos += MEMORY_ALIGNMENT) {
        buffer[pos] = static_cast<uint8_t>(pos % 256);
    }
}

// Measure performance of aligned memory access pattern
void measureAlignedMemoryAccess(std::vector<uint8_t>& buffer) {
    auto startTime = std::chrono::high_resolution_clock::now();

    for (size_t iteration = 0; iteration < LOOP_COUNT; ++iteration) {
        size_t offset = (iteration * 16) % (BUFFER_LENGTH - MEMORY_ALIGNMENT);
        uint32_t result = *reinterpret_cast<uint32_t*>(buffer.data() + offset);
        // Prevent compiler optimization by using the result
        std::cout << (result & 0xFF) << std::flush;
    }

    auto endTime = std::chrono::high_resolution_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(endTime - startTime).count();
    std::cout << "Aligned access took " << elapsed << " microseconds" << std::endl;
}

// Measure performance of unaligned memory access pattern
void measureUnalignedMemoryAccess(std::vector<uint8_t>& buffer) {
    auto startTime = std::chrono::high_resolution_clock::now();

    for (size_t iteration = 0; iteration < LOOP_COUNT; ++iteration) {
        size_t offset = (iteration * 15) % (BUFFER_LENGTH - MEMORY_ALIGNMENT); // Unaligned
        uint32_t result = *reinterpret_cast<uint32_t*>(buffer.data() + offset);
        // Prevent compiler optimization by using the result
        std::cout << (result & 0xFF) << std::flush;
    }

    auto endTime = std::chrono::high_resolution_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(endTime - startTime).count();
    std::cout << "Unaligned access took " << elapsed << " microseconds" << std::endl;
}

int main() {
    std::vector<uint8_t> buffer(BUFFER_LENGTH, 0);
    initializeBuffer(buffer);

    measureAlignedMemoryAccess(buffer);
    measureUnalignedMemoryAccess(buffer);

    return 0;
}

