// Find the longest string in a vector of strings
std::string findLongestString(const std::vector<std::string>& words) {
    if (words.empty()) {
        return ""; // Return empty string for empty input
    }

    std::string longest = words[0];
    size_t index = 1;

    while (index < words.size()) {
        if (words[index].length() > longest.length()) {
            longest = words[index];
        }
        ++index;
    }

    return longest;
}

int main() {
    std::vector<std::string> words = {"apple", "banana", "cherry", "date"};
    std::string result = findLongestString(words);
    std::cout << "The longest string is: " << result << std::endl;
    return 0;
}

