// Helper to delete dynamically allocated memory for unsigned char*
struct ByteArrayDeleter {
    void operator()(unsigned char* ptr) const noexcept {
        delete[] ptr;
    }
};

using UniqueByteArray = std::unique_ptr<unsigned char[], ByteArrayDeleter>;

// AssembleCode: assemble raw assembly string into machine code bytes via temporary files and NASM
bool AssembleCode(const char* asmCode, unsigned char** outBytes, size_t* outSize) {
    if (!asmCode || !outBytes || !outSize) {
        return false;
    }

    // Use unique_ptr for automatic cleanup on scope exit
    struct FileCloser {
        FILE* fp;
        FileCloser(FILE* f) : fp(f) {}
        ~FileCloser() { if (fp) std::fclose(fp); }
    };

    // Step 1: Write assembly source to temporary file
    const char* tempAsmPath = "temp.asm";
    {
        std::ofstream asmStream(tempAsmPath);
        if (!asmStream) {
            return false;
        }
        asmStream << asmCode;
        if (!asmStream.good()) {
            return false;
        }
    } // File automatically closed here

    // Step 2: Invoke NASM to assemble to object file
    const char* tempObjPath = "temp.obj";
    std::string command = "nasm -f win32 \"" + std::string(tempAsmPath) + "\" -o \"" + std::string(tempObjPath) + "\"";
    int ret = std::system(command.c_str());
    if (ret != 0) {
        // Optional: log error or inspect errno
        return false;
    }

    // Step 3: Read object file into memory
    FILE* objFile = std::fopen(tempObjPath, "rb");
    if (!objFile) {
        return false;
    }
    FileCloser objCloser(objFile);

    // Get file size
    if (std::fseek(objFile, 0, SEEK_END) != 0) {
        return false;
    }
    long fileSize = std::ftell(objFile);
    if (fileSize < 0) {
        return false;
    }
    std::rewind(objFile);

    // Allocate buffer and read contents
    UniqueByteArray buffer(new unsigned char[static_cast<size_t>(fileSize)]);
    size_t bytesRead = std::fread(buffer.get(), sizeof(unsigned char), static_cast<size_t>(fileSize), objFile);
    if (bytesRead != static_cast<size_t>(fileSize)) {
        return false;
    }

    // Transfer ownership to caller
    *outBytes = buffer.release();
    *outSize = static_cast<size_t>(fileSize);

    return true;
}

