#include <iostream>
#include <vector>
#include <mshtml.h>

#ifdef MYDOMTRAVERSAL_EXPORTS
#define MYDOMTRAVERSAL_API __declspec(dllexport)
#else
#define MYDOMTRAVERSAL_API __declspec(dllimport)
#endif

extern "C" MYDOMTRAVERSAL_API void TraverseDOM(IHTMLDocument2* pDoc);

// Helper function to process a single node (text extraction and printing)
void ProcessTextNode(IHTMLDOMNode* pNode) {
    if (!pNode) return;

    BSTR nodeText = nullptr;
    if (SUCCEEDED(pNode->get_nodeValue(&nodeText)) && nodeText != nullptr) {
        wprintf(L"Text Node: %s\n", nodeText);
        SysFreeString(nodeText);
    }
}

// Iterative DOM traversal using a stack (avoids recursion depth issues)
void TraverseDOM(IHTMLDocument2* pDoc) {
    if (!pDoc) return;

    IHTMLElementCollection* pBody = nullptr;
    if (FAILED(pDoc->get_body(&pBody)) || !pBody) return;

    long count = 0;
    if (FAILED(pBody->get_length(&count)) || count <= 0) {
        pBody->Release();
        return;
    }

    std::vector<IHTMLDOMNode*> nodeStack;
    for (long idx = 0; idx < count; ++idx) {
        IHTMLDOMNode* item = nullptr;
        if (SUCCEEDED(pBody->item(idx, &item)) && item) {
            nodeStack.push_back(item);
        }
    }

    while (!nodeStack.empty()) {
        IHTMLDOMNode* current = nodeStack.back();
        nodeStack.pop_back();

        // Process current node's text content
        ProcessTextNode(current);

        // Push children onto stack in reverse order so first child is processed next
        IHTMLDOMNode* child = nullptr;
        if (SUCCEEDED(current->get_firstChild(&child)) && child) {
            std::vector<IHTMLDOMNode*> siblings;
            while (child) {
                siblings.push_back(child);
                IHTMLDOMNode* next = nullptr;
                if (FAILED(child->get_nextSibling(&next)) || !next) break;
                child->Release();
                child = next;
            }

            // Reverse push to maintain left-to-right processing order
            for (auto it = siblings.rbegin(); it != siblings.rend(); ++it) {
                nodeStack.push_back(*it);
            }
        }

        current->Release();
    }

    pBody->Release();
}

#include <vector>
#include <pybind11/pybind11.h>
#include <pybind11/numpy.h>

namespace py = pybind11;

class Matrix3D {
public:
    std::vector<std::vector<std::vector<double>>> elements;
    int dim_x, dim_y, dim_z;

    // Constructor
    Matrix3D(int x, int y, int z) : elements(x), dim_x(x), dim_y(y), dim_z(z) {
        for (int i = 0; i < x; ++i) {
            elements[i].resize(y, std::vector<double>(z, 0.0));
        }
    }

    // Overloaded operator() for element access (with bounds checking alternative)
    double& at(int i, int j, int k) {
        return elements[i][j][k];
    }

    const double& at(int i, int j, int k) const {
        return elements[i][j][k];
    }

    // Function to convert Matrix3D to a NumPy array
    py::array_t<double> to_numpy_array() const {
        py::array_t<double> np_array({dim_x, dim_y, dim_z});
        auto buffer = np_array.mutable_unchecked<3>();

        for (int i = 0; i < dim_x; ++i) {
            for (int j = 0; j < dim_y; ++j) {
                for (int k = 0; k < dim_z; ++k) {
                    buffer(i, j, k) = elements[i][j][k];
                }
            }
        }
        return np_array;
    }

    // Function to convert a NumPy array to Matrix3D
    static Matrix3D from_numpy_array(const py::array_t<double>& np_array) {
        auto buffer = np_array.unchecked<3>();
        Matrix3D result(buffer.shape(0), buffer.shape(1), buffer.shape(2));

        for (int i = 0; i < buffer.shape(0); ++i) {
            for (int j = 0; j < buffer.shape(1); ++j) {
                for (int k = 0; k < buffer.shape(2); ++k) {
                    result.elements[i][j][k] = buffer(i, j, k);
                }
            }
        }
        return result;
    }
};

#include <v8.h>
#include <iostream>

using v8::Context;
using v8::FunctionCallbackInfo;
using v8::Isolate;
using v8::Local;
using v8::Number;
using v8::Object;
using v8::ObjectTemplate;
using v8::String;
using v8::Value;

// Modified Point class with additional methods for encapsulation
class Coordinate {
public:
    Coordinate(int x_val, int y_val) : x_coord(x_val), y_coord(y_val) {}

    int get_x() const { return x_coord; }
    void assign_x(int new_x) { x_coord = new_x; }

    int get_y() const { return y_coord; }
    void assign_y(int new_y) { y_coord = new_y; }

private:
    int x_coord;
    int y_coord;
};

// Getter for x-coordinate
void RetrieveXCoordinate(Local<String> prop, const PropertyCallbackInfo<Value>& info) {
    Coordinate* coord = static_cast<Coordinate*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    info.GetReturnValue().Set(Number::New(info.GetIsolate(), coord->get_x()));
}

// Setter for x-coordinate
void AssignXCoordinate(Local<String> prop, Local<Value> val, const PropertyCallbackInfo<void>& info) {
    Coordinate* coord = static_cast<Coordinate*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    coord->assign_x(val->NumberValue(info.GetIsolate()->GetCurrentContext()).ToChecked());
}

// Getter for y-coordinate
void RetrieveYCoordinate(Local<String> prop, const PropertyCallbackInfo<Value>& info) {
    Coordinate* coord = static_cast<Coordinate*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    info.GetReturnValue().Set(Number::New(info.GetIsolate(), coord->get_y()));
}

// Setter for y-coordinate
void AssignYCoordinate(Local<String> prop, Local<Value> val, const PropertyCallbackInfo<void>& info) {
    Coordinate* coord = static_cast<Coordinate*>(info.Holder()->GetAlignedPointerFromInternalField(0));
    coord->assign_y(val->NumberValue(info.GetIsolate()->GetCurrentContext()).ToChecked());
}

int main() {
    // Initialize V8 runtime environment
    v8::V8::InitializeICUDefaultLocation("");
    v8::V8::InitializeExternalStartupData("");
    std::unique_ptr<v8::Platform> platform = v8::platform::NewDefaultPlatform();
    v8::V8::InitializePlatform(platform.get());
    v8::V8::Initialize();

    // Create and configure isolate
    Isolate* isolate = Isolate::New();
    {
        Isolate::Scope isolate_scope(isolate);
        HandleScope handle_scope(isolate);
        Local<Context> context = Context::New(isolate);
        Context::Scope context_scope(context);

        // Setup object template for coordinate wrapper
        Local<ObjectTemplate> coord_template = ObjectTemplate::New(isolate);
        coord_template->SetInternalFieldCount(1);  // Reserve space for C++ pointer

        // Register property accessors
        coord_template->SetAccessor(String::NewFromUtf8(isolate, "x").ToLocalChecked(), 
                                   RetrieveXCoordinate, AssignXCoordinate);
        coord_template->SetAccessor(String::NewFromUtf8(isolate, "y").ToLocalChecked(), 
                                   RetrieveYCoordinate, AssignYCoordinate);

        // Instantiate C++ object
        Coordinate* coord = new Coordinate(10, 20);

        // Bind C++ object to JS object
        Local<Object> coord_obj = coord_template->NewInstance(context).ToLocalChecked();
        coord_obj->SetAlignedPointerInInternalField(0, coord);

        // Expose to global scope
        context->Global()->Set(context, String::NewFromUtf8(isolate, "point").ToLocalChecked(), 
                              coord_obj).Check();

        // Execute JavaScript expression
        Local<String> script_source = String::NewFromUtf8(isolate, 
            "point.x = point.y * 2; console.log(point.x);").ToLocalChecked();
        Local<Script> compiled_script = Script::Compile(context, script_source).ToLocalChecked();
        Local<Value> execution_result = compiled_script->Run(context).ToLocalChecked();

        // Release resources
        delete coord;
    }

    // Cleanup V8 resources
    isolate->Dispose();
    v8::V8::Dispose();
    v8::V8::ShutdownPlatform();
    return 0;
}

