void aricoder::initialize() {
    // Precompute the reciprocal of s->scale
    int i = 0;
    while (i < num_symbols) {
        symbols[i].reciprocal = ((1 << 30) / symbols[i].scale);
        ++i;
    }
}

void aricoder::encode(symbol* s) {
    unsigned int range = (chigh - clow + 1);
    cstep = (range * s->reciprocal) >> 30;

    unsigned int new_clow = clow + (cstep * s->low_count);
    chigh = clow + (cstep * s->high_count) - 1;
    clow = new_clow;

    // Handle overflow cases
    while ((clow >= CODER_LIMIT050) || (chigh < CODER_LIMIT050)) {
        if (chigh < CODER_LIMIT050) {
            write_zero();
            write_nrbits_as_one();
        } else {
            write_one();
            clow &= (CODER_LIMIT050 - 1);
            chigh &= (CODER_LIMIT050 - 1);
            write_nrbits_as_zeros();
        }
        clow <<= 1;
        chigh = (chigh << 1) | 1;
    }

    // Handle mid-range normalization
    while ((clow >= CODER_LIMIT025) && (chigh < CODER_LIMIT075)) {
        ++nrbits;
        clow &= (CODER_LIMIT025 - 1);
        chigh ^= (CODER_LIMIT025 | CODER_LIMIT050);
        clow <<= 1;
        chigh = (chigh << 1) | 1;
    }
}

#include <Python.h>
