// Reallocate memory buffer with zero-initialization for the newly added portion
void* adjust_buffer_size(void* current_buffer, Py_ssize_t current_length, Py_ssize_t target_length) {
    void* updated_buffer = PyMem_Realloc(current_buffer, target_length);
    if (updated_buffer == nullptr) {
        // Memory allocation failed; return null to indicate error
        return nullptr;
    }

    // Initialize the newly allocated region to zero if expansion occurred
    if (target_length > current_length) {
        std::memset(static_cast<char*>(updated_buffer) + current_length, 0, 
                    static_cast<size_t>(target_length - current_length));
    }

    return updated_buffer;
}

