#include <iostream>
#include <limits>

struct ListNode {
    int data;
    ListNode* previous;
    ListNode* next;

    ListNode(int val) : data(val), previous(nullptr), next(nullptr) {}
};

class BidirectionalList {
private:
    ListNode* start;
    ListNode* end;
    ListNode* smallest;
    ListNode* largest;

public:
    BidirectionalList() : start(nullptr), end(nullptr), smallest(nullptr), largest(nullptr) {}

    void addElement(int value) {
        ListNode* newNode = new ListNode(value);

        if (start == nullptr) {
            start = end = smallest = largest = newNode;
        } else {
            newNode->previous = end;
            end->next = newNode;
            end = newNode;

            if (value < smallest->data) {
                smallest = newNode;
            }
            if (value > largest->data) {
                largest = newNode;
            }
        }
    }

    void deleteElement(int value) {
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data == value) {
                if (current->previous) {
                    current->previous->next = current->next;
                } else {
                    start = current->next;
                }

                if (current->next) {
                    current->next->previous = current->previous;
                } else {
                    end = current->previous;
                }

                if (smallest == current) {
                    smallest = locateSmallest();
                }
                if (largest == current) {
                    largest = locateLargest();
                }

                delete current;
                return;
            }
            current = current->next;
        }
    }

    int findMinimum() const {
        return smallest ? smallest->data : std::numeric_limits<int>::max();
    }

    int findMaximum() const {
        return largest ? largest->data : std::numeric_limits<int>::min();
    }

private:
    ListNode* locateSmallest() const {
        ListNode* minNode = start;
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data < minNode->data) {
                minNode = current;
            }
            current = current->next;
        }
        return minNode;
    }

    ListNode* locateLargest() const {
        ListNode* maxNode = start;
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data > maxNode->data) {
                maxNode = current;
            }
            current = current->next;
        }
        return maxNode;
    }
};

int main() {
    BidirectionalList list;
    list.addElement(10);
    list.addElement(5);
    list.addElement(15);
    list.addElement(3);

    std::cout << "Minimum: " << list.findMinimum() << std::endl; // Output: Minimum: 3
    std::cout << "Maximum: " << list.findMaximum() << std::endl; // Output: Maximum: 15

    list.deleteElement(15);
    std::cout << "Maximum after deleting 15: " << list.findMaximum() << std::endl; // Output: Maximum: 10

    return 0;
}

