using namespace rapidjson;

// Function type for loading components onto an entity
using ComponentLoaderCallback = std::function<void(EntityId, const Value&)>;

// Map to store registered component loader functions by name
static std::unordered_map<std::string, ComponentLoaderCallback> componentRegistry;

void ImportScene(const std::string& path) {
    FILE* file = std::fopen(path.c_str(), "r");
    if (!file) {
        std::cerr << "Failed to open scene file: " << path << std::endl;
        return;
    }

    char buffer[65536];
    FileReadStream stream(file, buffer, sizeof(buffer));

    Document doc;
    doc.ParseStream<0, UTF8<>, FileReadStream>(stream);
    std::fclose(file);

    if (doc.HasParseError()) {
        std::cerr << "JSON parsing error in scene file '" << path << "': " 
                  << doc.GetParseError() << std::endl;
        return;
    }

    // Process entities array if present
    if (doc.HasMember("entities") && doc["entities"].IsArray()) {
        const Value& entities = doc["entities"];

        for (SizeType index = 0; index < entities.Size(); ++index) {
            const Value& entityJson = entities[index];

            EntityId newEntity = ECS::CreateEntity();

            // Iterate through all registered loaders and apply matching components
            for (const auto& entry : componentRegistry) {
                const std::string& componentName = entry.first;

                if (entityJson.HasMember(componentName.c_str())) {
                    entry.second(newEntity, entityJson[componentName.c_str()]);
                }
            }
        }
    }
}

#include <iostream>
#include <sqlite3.h>

int main() {
    sqlite3* databaseHandle = nullptr;
    char* errorMsg = nullptr;
    int resultCode;
    const char* query;

    // Open the SQLite database file
    resultCode = sqlite3_open("database.db", &databaseHandle);

    if (resultCode != SQLITE_OK) {
        std::cout << "Unable to open database: " << sqlite3_errmsg(databaseHandle) << std::endl;
        sqlite3_close(databaseHandle);
        return 1;
    }

    // Remove existing table if present
    resultCode = sqlite3_exec(databaseHandle, "DROP TABLE IF EXISTS test", nullptr, nullptr, &errorMsg);

    if (resultCode != SQLITE_OK && errorMsg != nullptr) {
        std::cout << "Database error: " << errorMsg << std::endl;
        sqlite3_free(errorMsg);
        errorMsg = nullptr;
    }

    // Define and execute table creation statement
    query = "CREATE TABLE test (PID INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT)";
    resultCode = sqlite3_exec(databaseHandle, query, nullptr, nullptr, &errorMsg);

    if (resultCode != SQLITE_OK) {
        if (errorMsg != nullptr) {
            std::cout << "Table creation failed: " << errorMsg << std::endl;
            sqlite3_free(errorMsg);
            errorMsg = nullptr;
        }
        sqlite3_close(databaseHandle);
        return 1;
    } else {
        // Insert sample records into the table
        query = "INSERT INTO test (Name) VALUES ('John')";
        resultCode = sqlite3_exec(databaseHandle, query, nullptr, nullptr, &errorMsg);

        query = "INSERT INTO test (Name) VALUES ('Smith')";
        resultCode = sqlite3_exec(databaseHandle, query, nullptr, nullptr, &errorMsg);
    }

    // Clean up by dropping the table before exiting
    resultCode = sqlite3_exec(databaseHandle, "DROP TABLE IF EXISTS test", nullptr, nullptr, &errorMsg);

    if (resultCode != SQLITE_OK && errorMsg != nullptr) {
        std::cout << "Cleanup error: " << errorMsg << std::endl;
        sqlite3_free(errorMsg);
    }

    // Close the database connection
    sqlite3_close(databaseHandle);
    return 0;
}

#include <iostream>
#include <vector>
#include <string>

std::string convert(std::string s, int rows, int cols, char fillChar = 'X') {
    // Create matrix using dynamic allocation instead of vector
    char** grid = new char*[rows];
    for (int i = 0; i < rows; ++i) {
        grid[i] = new char[cols];
        for (int j = 0; j < cols; ++j) {
            grid[i][j] = fillChar;
        }
    }

    // Movement directions: right, down, left, up
    int dirX[] = {0, 1, 0, -1};
    int dirY[] = {1, 0, -1, 0};

    int curRow = 0, curCol = 0;
    int currentDir = 0;
    int pos = 0;

    // Fill the grid in spiral pattern
    while (pos < s.length()) {
        grid[curRow][curCol] = s[pos++];

        // Determine next position
        int nextR = curRow + dirX[currentDir];
        int nextC = curCol + dirY[currentDir];

        // Check if we need to turn
        if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols || grid[nextR][nextC] != fillChar) {
            currentDir = (currentDir + 1) % 4;
            nextR = curRow + dirX[currentDir];
            nextC = curCol + dirY[currentDir];
        }

        curRow = nextR;
        curCol = nextC;
    }

    // Read in spiral order
    std::string output = "";
    int visited[rows][cols];
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            visited[i][j] = 0;
        }
    }

    curRow = 0;
    curCol = 0;
    currentDir = 0;

    while (true) {
        output += grid[curRow][curCol];
        visited[curRow][curCol] = 1;

        int nextR = curRow + dirX[currentDir];
        int nextC = curCol + dirY[currentDir];

        // If next position is invalid or already visited, change direction
        if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols || visited[nextR][nextC]) {
            currentDir = (currentDir + 1) % 4;
            nextR = curRow + dirX[currentDir];
            nextC = curCol + dirY[currentDir];

            // If still invalid after turning, we're done
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols || visited[nextR][nextC]) {
                break;
            }
        }

        curRow = nextR;
        curCol = nextC;
    }

    // Clean up memory
    for (int i = 0; i < rows; ++i) {
        delete[] grid[i];
    }
    delete[] grid;

    return output;
}

int main() {
    std::string s1 = "HELLOPROGRAMMING";
    int rows1 = 5, cols1 = 4;
    std::cout << convert(s1, rows1, cols1) << std::endl;

    std::string s2 = "HELLOPROGRAMMING";
    int rows2 = 4, cols2 = 4;
    std::cout << convert(s2, rows2, cols2) << std::endl;

    std::string s3 = "A";
    int rows3 = 1, cols3 = 1;
    std::cout << convert(s3, rows3, cols3) << std::endl;

    std::string s4 = "HELLO";
    int rows4 = 3, cols4 = 3;
    std::cout << convert(s4, rows4, cols4, 'X') << std::endl;

    return 0;
}

