#pragma comment(lib, "wininet.lib")

// Custom error codes for different failure points
#define ERR_FILE_OPEN         10
#define ERR_MEMORY_ALLOC      11
#define ERR_FILE_READ         12
#define ERR_INET_INIT         13
#define ERR_INET_CONNECT      14
#define ERR_HTTP_REQ          15
#define ERR_HTTP_SEND         16

using namespace std;

int main() {
    // Configuration variables
    static const char* localFilename = "test.txt";
    static const char* fullPath      = "C:\\wamp\\www\\post\\test.txt";
    static const char* mimeType      = "text/plain";
    static const char* boundary      = "--BOUNDARY---";
    static const char* formFieldName = "file";
    static const char* serverAddr    = "localhost";
    static const char* requestPath   = "/post/upload.php";

    char headers[1024] = {0};
    char* fileData     = nullptr;
    char* fullRequest  = nullptr;
    FILE* fileHandle   = nullptr;
    long fileSize      = 0;
    size_t bytesRead   = 0;

    // Open the file in binary mode
    fileHandle = fopen(fullPath, "rb");
    if (!fileHandle) {
        cout << "ERR_FILE_OPEN" << endl;
        return ERR_FILE_OPEN;
    }
    cout << "FILE_OPENED" << endl;

    // Determine file size
    fseek(fileHandle, 0, SEEK_END);
    fileSize = ftell(fileHandle);
    rewind(fileHandle);

    // Allocate memory for file content
    fileData = new char[fileSize + 1];
    if (!fileData) {
        cout << "ERR_MEMORY_ALLOC" << endl;
        fclose(fileHandle);
        return ERR_MEMORY_ALLOC;
    }
    cout << "MEMORY_ALLOCATED\t\"" << fileSize << "\"\n";

    // Read entire file into buffer
    bytesRead = fread(fileData, sizeof(char), fileSize, fileHandle);
    if (bytesRead != static_cast<size_t>(fileSize)) {
        cout << "ERR_FILE_READ" << endl;
        delete[] fileData;
        fclose(fileHandle);
        return ERR_FILE_READ;
    }
    cout << "FILE_READ_OK" << endl;

    fileData[fileSize] = '\0';
    fclose(fileHandle);
    cout << "FILE_CLOSED" << endl;

    // Allocate space for full HTTP request (file + headers)
    fullRequest = new char[fileSize + 2048];
    if (!fullRequest) {
        cout << "ERR_MEMORY_ALLOC" << endl;
        delete[] fileData;
        return ERR_MEMORY_ALLOC;
    }

    // Build multipart headers and body manually
    sprintf(headers, "Content-Type: multipart/form-data; boundary=%s\r\n", boundary);
    sprintf(fullRequest, "%s--%s\r\nContent-Disposition: form-data; name=\"%s\"; filename=\"%s\"\r\n", 
            boundary, formFieldName, localFilename);
    sprintf(fullRequest, "%sContent-Type: %s\r\n\r\n%s\r\n--%s--\r\n", 
            fullRequest, mimeType, fileData, boundary);

    // Compute total length of the request body
    int totalLength = static_cast<int>(strlen(fullRequest));

    // Initialize WinINet session
    HINTERNET hSession = InternetOpen("WININET_UPLOAD_CLIENT", 
                                      INTERNET_OPEN_TYPE_PRECONFIG, 
                                      nullptr, nullptr, 0);
    if (!hSession) {
        cout << "ERR_INET_INIT" << endl;
        delete[] fileData;
        delete[] fullRequest;
        return ERR_INET_INIT;
    }
    cout << "INTERNET_SESSION_CREATED" << endl;

    // Connect to HTTP server
    HINTERNET hConnect = InternetConnect(hSession, serverAddr, 
                                         INTERNET_DEFAULT_HTTP_PORT,
                                         nullptr, nullptr, 
                                         INTERNET_SERVICE_HTTP, 0, 1);
    if (!hConnect) {
        cout << "ERR_INET_CONNECT" << endl;
        InternetCloseHandle(hSession);
        delete[] fileData;
        delete[] fullRequest;
        return ERR_INET_CONNECT;
    }
    cout << "HTTP_CONNECTION_ESTABLISHED" << endl;

    // Create HTTP POST request
    HINTERNET hRequest = HttpOpenRequest(hConnect, "POST", requestPath, 
                                         nullptr, nullptr, nullptr, 
                                         INTERNET_FLAG_RELOAD, 1);
    if (!hRequest) {
        cout << "ERR_HTTP_REQ" << endl;
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        delete[] fileData;
        delete[] fullRequest;
        return ERR_HTTP_REQ;
    }
    cout << "HTTP_REQUEST_CREATED" << endl;

    // Append Content-Length header
    char lenHeader[64];
    sprintf(lenHeader, "Content-Length: %d\r\n", totalLength);
    strcat(headers, lenHeader);

    // Send the request with body
    BOOL success = HttpSendRequest(hRequest, headers, static_cast<DWORD>(strlen(headers)), 
                                   fullRequest, totalLength);
    if (!success) {
        cout << "ERR_HTTP_SEND" << endl;
        InternetCloseHandle(hRequest);
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        delete[] fileData;
        delete[] fullRequest;
        return ERR_HTTP_SEND;
    }
    cout << "REQUEST_SENT_SUCCESSFULLY" << endl;

    // Cleanup handles and memory
    InternetCloseHandle(hRequest);
    InternetCloseHandle(hConnect);
    InternetCloseHandle(hSession);
    delete[] fileData;
    delete[] fullRequest;

    cin.get(); // Wait for user input before exit
    return 0;
}

#include <pybind11/pybind11.h>

namespace bar {
    class Bar {
    public:
        void bar_method() { /* ... */ }
    };
}

void register_bar_Bar(pybind11::module m) {
    pybind11::class_<bar::Bar, std::shared_ptr<bar::Bar>> bar_class(m, "Bar");
    bar_class.def("bar_method", &bar::Bar::bar_method);

    bar_class.def_static("create_from_capsule", [](pybind11::object capsule_obj) {
        PyObject* capsule = capsule_obj.ptr();
        void* raw_ptr = PyCapsule_GetPointer(capsule, "bar_in_capsule");
        auto* shared_ptr = static_cast<std::shared_ptr<bar::Bar>*>(raw_ptr);
        return *shared_ptr;
    });

    bar_class.def_static("convert_to_capsule", [](std::shared_ptr<bar::Bar>& instance) {
        auto* new_shared = new std::shared_ptr<bar::Bar>(instance);
        pybind11::capsule capsule(new_shared, "bar_in_capsule", [](void* ptr) {
            delete static_cast<std::shared_ptr<bar::Bar>*>(ptr);
        });
        return capsule;
    });
}

#include <iostream>
#include <string>
#include <vector>
#include <cctype>

enum class TokenType {
    IF,
    ELSE,
    FUNCTION,
    IDENTIFIER,
    NUMBER,
    STRING,
    OPERATOR,
    EOF_TOKEN
};

struct Token {
    TokenType type;
    std::string value;
};

class Lexer {
public:
    Lexer(const std::string& source) : text(source), index(0) {}

    Token advance() {
        skipSpaces();
        if (index >= text.length()) {
            return {TokenType::EOF_TOKEN, ""};
        }

        char ch = text[index];
        if (std::isalpha(ch)) {
            return parseIdentifier();
        } else if (std::isdigit(ch)) {
            return parseNumber();
        } else if (ch == '"') {
            return parseStringLiteral();
        } else {
            return parseOperator();
        }
    }

private:
    std::string text;
    size_t index;

    void skipSpaces() {
        while (index < text.length() && std::isspace(text[index])) {
            index++;
        }
    }

    Token parseIdentifier() {
        size_t begin = index;
        while (index < text.length() && std::isalnum(text[index])) {
            index++;
        }
        std::string tokenText = text.substr(begin, index - begin);

        if (tokenText == "if") {
            return {TokenType::IF, tokenText};
        } else if (tokenText == "else") {
            return {TokenType::ELSE, tokenText};
        } else if (tokenText == "function") {
            return {TokenType::FUNCTION, tokenText};
        } else {
            return {TokenType::IDENTIFIER, tokenText};
        }
    }

    Token parseNumber() {
        size_t begin = index;
        while (index < text.length() && std::isdigit(text[index])) {
            index++;
        }
        return {TokenType::NUMBER, text.substr(begin, index - begin)};
    }

    Token parseStringLiteral() {
        index++; // Skip opening double quote
        size_t start = index;
        while (index < text.length() && text[index] != '"') {
            index++;
        }
        std::string content = text.substr(start, index - start);
        index++; // Skip closing double quote
        return {TokenType::STRING, content};
    }

    Token parseOperator() {
        std::string op(1, text[index]);
        index++;
        return {TokenType::OPERATOR, op};
    }
};

