    __m128d a = _mm_set_pd(6.0, 5.0);

    // Set mask: bits 1 and 2 are set (counting from LSB), 
    // meaning elements at positions 1 and 2 will be taken from 'a'
    __mmask8 mask = 0b0110;

    // Perform masked expand operation:
    // - Elements where mask bit is 0 come from src (compressed)
    // - Elements where mask bit is 1 come from a (expanded)
    __m128d result = _mm_mask_expand_pd(src, mask, a);

