uint8x16_t oddeven(uint8x16_t a) {
    // Extract all 16 bytes into separate variables
    uint8_t b0 = vgetq_lane_u8(a, 0);
    uint8_t b1 = vgetq_lane_u8(a, 1);
    uint8_t b2 = vgetq_lane_u8(a, 2);
    uint8_t b3 = vgetq_lane_u8(a, 3);
    uint8_t b4 = vgetq_lane_u8(a, 4);
    uint8_t b5 = vgetq_lane_u8(a, 5);
    uint8_t b6 = vgetq_lane_u8(a, 6);
    uint8_t b7 = vgetq_lane_u8(a, 7);
    uint8_t b8 = vgetq_lane_u8(a, 8);
    uint8_t b9 = vgetq_lane_u8(a, 9);
    uint8_t b10 = vgetq_lane_u8(a, 10);
    uint8_t b11 = vgetq_lane_u8(a, 11);
    uint8_t b12 = vgetq_lane_u8(a, 12);
    uint8_t b13 = vgetq_lane_u8(a, 13);
    uint8_t b14 = vgetq_lane_u8(a, 14);
    uint8_t b15 = vgetq_lane_u8(a, 15);

    // Reorganize: place even-indexed bytes first, then odd-indexed bytes
    uint8_t evens[8] = {b0, b2, b4, b6, b8, b10, b12, b14};
    uint8_t odds[8] = {b1, b3, b5, b7, b9, b11, b13, b15};

    // Create new vectors from the organized bytes
    uint8x8_t even_vec = vld1_u8(evens);
    uint8x8_t odd_vec = vld1_u8(odds);

    // Combine to form the final 128-bit result
    return vcombine_u8(even_vec, odd_vec);
}

