    size_t position = 0;

    while (position < length) {
        char temp_sum = digits[position] + rhs_digits[position];

        if (carry) {
            temp_sum += 1;
            if (temp_sum > 15) {
                temp_sum -= 16;
                carry = 1;
            } else {
                carry = 0;
            }
        } else {
