// Kernel using 24-bit unsigned multiplication
__global__ void kernel_umul24_v2(unsigned int *output, unsigned int val1, unsigned int val2) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    output[tid] = __umul24(val1, val2);
}

// Kernel using standard 32-bit unsigned multiplication
__global__ void kernel_mul_v2(unsigned int *output, unsigned int val1, unsigned int val2) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    output[tid] = val1 * val2;
}

int main() {
    const int ELEMENT_COUNT = 1 << 20; // 1 million elements
    unsigned int *device_output_umul24, *device_output_mul;
    unsigned int operand_a = 12345;
    unsigned int operand_b = 67890;

    cudaMalloc(&device_output_umul24, ELEMENT_COUNT * sizeof(unsigned int));
    cudaMalloc(&device_output_mul, ELEMENT_COUNT * sizeof(unsigned int));

    // Measure performance of __umul24 kernel
    auto timing_start = std::chrono::high_resolution_clock::now();
    kernel_umul24_v2<<<(ELEMENT_COUNT + 255) / 256, 256>>>(device_output_umul24, operand_a, operand_b);
    cudaDeviceSynchronize();
    auto timing_end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed_umul24 = timing_end - timing_start;
    std::cout << "Execution time with __umul24: " << elapsed_umul24.count() << " seconds" << std::endl;

    // Measure performance of standard multiplication kernel
    timing_start = std::chrono::high_resolution_clock::now();
    kernel_mul_v2<<<(ELEMENT_COUNT + 255) / 256, 256>>>(device_output_mul, operand_a, operand_b);
    cudaDeviceSynchronize();
    timing_end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed_mul = timing_end - timing_start;
    std::cout << "Execution time with standard multiply: " << elapsed_mul.count() << " seconds" << std::endl;

    cudaFree(device_output_umul24);
    cudaFree(device_output_mul);

    return 0;
}

