#include <cuda_runtime.h>
#include <opencv2/opencv.hpp>

// Kernel function to convert Bayer pattern to RGB using a different indexing approach
__global__ void demosaicKernel(const unsigned char* input, unsigned char* output, int cols, int rows) {
    int u = blockIdx.x * blockDim.x + threadIdx.x;
    int v = blockIdx.y * blockDim.y + threadIdx.y;

    if (u >= cols || v >= rows) return;

    int pixelPos = v * cols + u;
    int rgbPos = pixelPos * 3;

    // Determine the color at this position based on even/odd pattern (GRBG)
    bool isEvenCol = (u % 2 == 0);
    bool isEvenRow = (v % 2 == 0);

    if (isEvenCol && isEvenRow) {
        // Green pixel
        output[rgbPos] = input[pixelPos];

        // Interpolate Red: average of right and bottom-right neighbors
        int redVal = input[pixelPos + 1];
        if (u < cols - 1 && v < rows - 1) {
            redVal = (input[pixelPos + 1] + input[pixelPos + cols + 1]) / 2;
        }
        output[rgbPos + 1] = static_cast<unsigned char>(redVal);

        // Interpolate Blue: average of bottom and bottom-right neighbors
        int blueVal = input[pixelPos + cols];
        if (v < rows - 1) {
            blueVal = (input[pixelPos + cols] + input[pixelPos + cols + 1]) / 2;
        }
        output[rgbPos + 2] = static_cast<unsigned char>(blueVal);
    } 
    else if (!isEvenCol && isEvenRow) {
        // Blue pixel
        int redVal = input[pixelPos + cols];
        if (v < rows - 1) {
            redVal = (input[pixelPos + cols] + input[pixelPos + cols - 1]) / 2;
        }
        output[rgbPos] = static_cast<unsigned char>(redVal);

        int greenVal = input[pixelPos];
        if (u > 0 && v < rows - 1) {
            greenVal = (input[pixelPos + cols] + input[pixelPos + cols - 1] + 
                       input[pixelPos - cols] + input[pixelPos - cols - 1]) / 4;
        }
        output[rgbPos + 1] = static_cast<unsigned char>(greenVal);

        output[rgbPos + 2] = input[pixelPos];
    } 
    else if (isEvenCol && !isEvenRow) {
        // Red pixel
        int redVal = input[pixelPos];
        if (u < cols - 1) {
            redVal = (input[pixelPos + 1] + input[pixelPos + cols - 1]) / 2;
        }
        output[rgbPos] = static_cast<unsigned char>(redVal);

        int greenVal = input[pixelPos];
        if (u < cols - 1 && v < rows - 1) {
            greenVal = (input[pixelPos + cols] + input[pixelPos + cols + 1] + 
                       input[pixelPos - cols] + input[pixelPos - cols + 1]) / 4;
        }
        output[rgbPos + 1] = static_cast<unsigned char>(greenVal);

        output[rgbPos + 2] = input[pixelPos];
    } 
    else {
        // Green pixel in second row of pattern
        output[rgbPos] = input[pixelPos];

        int greenRedVal = input[pixelPos - 1];
        if (u > 0) {
            greenRedVal = (input[pixelPos - 1] + input[pixelPos + cols - 1]) / 2;
        }
        output[rgbPos + 1] = static_cast<unsigned char>(greenRedVal);

        int blueVal = input[pixelPos - cols];
        if (v > 0) {
            blueVal = (input[pixelPos - cols] + input[pixelPos - cols - 1]) / 2;
        }
        output[rgbPos + 2] = static_cast<unsigned char>(blueVal);
    }
}

// Host function to manage GPU memory and kernel launch
void processBayerToRGB(const cv::Mat& source, cv::Mat& result) {
    int width = source.cols;
    int height = source.rows;

    size_t bayerSize = source.total() * source.elemSize();
    size_t rgbSize = width * height * 3;

    unsigned char *deviceInput, *deviceOutput;
    cudaMalloc(&deviceInput, bayerSize);
    cudaMalloc(&deviceOutput, rgbSize);

    cudaMemcpy(deviceInput, source.data, bayerSize, cudaMemcpyHostToDevice);

    dim3 threadsPerBlock(16, 16);
    dim3 numBlocks((width + threadsPerBlock.x - 1) / threadsPerBlock.x,
                   (height + threadsPerBlock.y - 1) / threadsPerBlock.y);

    demosaicKernel<<<numBlocks, threadsPerBlock>>>(deviceInput, deviceOutput, width, height);

    result.create(height, width, CV_8UC3);
    cudaMemcpy(result.data, deviceOutput, rgbSize, cudaMemcpyDeviceToHost);

    cudaFree(deviceInput);
    cudaFree(deviceOutput);
}

int main() {
    cv::Mat rawImage = cv::imread("bayer.png", cv::IMREAD_GRAYSCALE);
    cv::Mat colorImage;

    processBayerToRGB(rawImage, colorImage);

    cv::imwrite("rgb_output.png", colorImage);

    return 0;
}

#include <vector>
#include <iostream>
using namespace std;

// Merge two sorted arrays with duplicate removal
void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
    int idx1 = m - 1; // Last valid element in nums1
    int idx2 = n - 1; // Last element in nums2
    int targetIdx = m + n - 1; // Position to fill in merged array

    // Process elements from the end of both arrays
    while (idx1 >= 0 && idx2 >= 0) {
        if (nums1[idx1] > nums2[idx2]) {
            nums1[targetIdx] = nums1[idx1];
            // Skip duplicates in nums1
            while (idx1 > 0 && nums1[idx1] == nums1[idx1 - 1]) {
                idx1--;
            }
            idx1--;
        } else if (nums1[idx1] < nums2[idx2]) {
            nums1[targetIdx] = nums2[idx2];
            // Skip duplicates in nums2
            while (idx2 > 0 && nums2[idx2] == nums2[idx2 - 1]) {
                idx2--;
            }
            idx2--;
        } else {
            // Equal elements: add once and skip duplicates in both
            nums1[targetIdx] = nums1[idx1];
            targetIdx--;

            // Skip duplicates in nums1
            while (idx1 > 0 && nums1[idx1] == nums1[idx1 - 1]) {
                idx1--;
            }
            idx1--;

            // Skip duplicates in nums2
            while (idx2 > 0 && nums2[idx2] == nums2[idx2 - 1]) {
                idx2--;
            }
            idx2--;
        }
        targetIdx--;
    }

    // Copy remaining elements from nums2 if any
    while (idx2 >= 0) {
        nums1[targetIdx] = nums2[idx2];
        // Skip duplicates in nums2
        while (idx2 > 0 && nums2[idx2] == nums2[idx2 - 1]) {
            idx2--;
        }
        idx2--;
        targetIdx--;
    }

    // Ensure correct size after merging
    nums1.resize(m + n);
}

// Example usage
int main() {
    vector<int> nums1 = {1, 2, 3, 0, 0, 0};
    int m = 3;
    vector<int> nums2 = {2, 5, 6};
    int n = 3;

    merge(nums1, m, nums2, n);

    for (int num : nums1) {
        cout << num << " ";
    }
    return 0;
}

#include <iostream>
