using namespace std;

template<typename T, int MAX_SIZE>
class StaticArray {
private:
    T elements[MAX_SIZE];
    int count = 0;

public:
    void reset() {
        count = 0;
    }

    bool add(const T& value) {
        if (count >= MAX_SIZE) {
            return false;
        }
        elements[count++] = value;
        return true;
    }

    bool get(int position, T& result) const {
        if (position < 0 || position >= count) {
            return false;
        }
        result = elements[position];
        return true;
    }

    void display() const {
        for (int i = 0; i < count; ++i) {
            cout << elements[i] << " ";
        }
        cout << endl;
    }

    void order() {
        std::sort(elements, elements + count);
    }
};

#include <iostream>
#include <sstream>
#include <vector>
#include <string>

class IRGenerator {
public:
    std::string produceAssembly(Node* n) {
        std::string result = "";
        std::string intermediate = translateToIR(n);
        result = convertToAsm(intermediate);
        return result;
    }

private:
    std::string translateToIR(Node* n) {
        if (n->type == Node::IF) {
            std::string ir = "";
            ir += translateToIR(n->getChild(0));  // Evaluate condition first
            ir += "branch ";
            ir += n->getChild(0)->value;  // Use the condition value directly
            ir += " .then" + std::to_string(labelCounter++) + "\n";
            ir += "jump .else" + std::to_string(labelCounter - 1) + "\n";
            ir += ".then" + std::to_string(labelCounter - 1) + ":\n";
            ir += translateToIR(n->getChild(1));  // True branch body
            ir += ".else" + std::to_string(labelCounter - 1) + ":\n";
            return ir;
        }
        // Additional node types would be handled here similarly
        return "";
    }

    std::string convertToAsm(const std::string& irCode) {
        std::string asmOutput = "";
        std::vector<std::string> lines = tokenize(irCode, '\n');

        for (const auto& line : lines) {
            if (line.find("branch") != std::string::npos) {
                asmOutput += "compare ...\n";
                asmOutput += "jnz .then" + getLabel(line) + "\n";
                asmOutput += "jmp .else" + getLabel(line) + "\n";
            } else if (line.find("jump") != std::string::npos) {
                asmOutput += "jmp " + getLabel(line) + "\n";
            } else if (line.find(".then") != std::string::npos || line.find(".else") != std::string::npos) {
                asmOutput += line + ":\n";
            } else {
                asmOutput += line + "\n";
            }
        }
        return asmOutput;
    }

    std::vector<std::string> tokenize(const std::string& input, char sep) {
        std::vector<std::string> parts;
        std::string part;
        std::istringstream stream(input);
        while (std::getline(stream, part, sep)) {
            parts.push_back(part);
        }
        return parts;
    }

    std::string getLabel(const std::string& instruction) {
        // Locate and extract the label suffix from the instruction
        size_t pos = instruction.rfind(' ');
        if (pos != std::string::npos) {
            return instruction.substr(pos + 1);
        }
        return "";
    }

    int labelCounter = 0;
};

#include <iostream>
#include <vector>
#include <unordered_set>

// Find all pairs in the input vector that sum to 10
std::vector<std::pair<int, int>> locateComplements(const std::vector<int>& values) {
    std::unordered_set<int> visited;
    std::vector<std::pair<int, int>> results;

    for (int value : values) {
        int complement = 10 - value;
        if (visited.count(complement) > 0) {
            results.emplace_back(value, complement);
        }
        visited.insert(value);
    }

    return results;
}

int main() {
    std::vector<int> data = {1, 2, 3, 4, 5, 6, 7, 8, 9};
    auto matches = locateComplements(data);

    for (const auto& match : matches) {
        std::cout << "(" << match.first << ", " << match.second << ")" << std::endl;
    }

    return 0;
}

