#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
#define SCREEN_ADDR 0x3C
#define WIFI_CHANNEL 1
#define MAX_BUFFER 1024

Adafruit_SSD1306 oled(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// Circular buffer variables
uint8_t rxBuffer[MAX_BUFFER];
size_t writeIdx = 0;
size_t readIdx = 0;
size_t packetCount = 0;

void InitializeESPNow() {
  WiFi.disconnect();
  if (esp_now_init() == ESP_OK) {
    Serial.println("ESP-NOW initialized successfully");
  } else {
    Serial.println("ESP-NOW initialization failed");
    ESP.restart();
  }
}

void SetupAccessPoint() {
  const char apSSID[] = "Slave_1";
  if (!WiFi.softAP(apSSID, "Slave_1_Password", WIFI_CHANNEL, 0)) {
    Serial.println("Failed to configure Access Point");
    ESP.restart();
  } else {
    Serial.print("Access Point configured: ");
    Serial.println(apSSID);
    Serial.print("Channel: ");
    Serial.println(WiFi.channel());
  }
}

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_AP);
  SetupAccessPoint();
  InitializeESPNow();
  esp_now_register_recv_cb([](const uint8_t *mac, const uint8_t *data, int len) {
    OnDataReceived(mac, data, len);
  });

  if (!oled.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDR)) {
    Serial.println(F("OLED display initialization failed"));
    for (;;); // Halt execution
  }
  oled.clearDisplay();
}

void OnDataReceived(const uint8_t *mac_addr, const uint8_t *payload, int length) {
  char macAddress[18];
  sprintf(macAddress, "%02x:%02x:%02x:%02x:%02x:%02x",
          mac_addr[0], mac_addr[1], mac_addr[2], mac_addr[3], mac_addr[4], mac_addr[5]);

  Serial.print("Received from device: ");
  Serial.println(macAddress);
  Serial.println();

  // Store incoming bytes in circular buffer
  for (int idx = 0; idx < length; idx++) {
    writeIdx = (writeIdx + 1) % MAX_BUFFER;
    rxBuffer[writeIdx] = payload[idx];

    // Handle buffer overflow by advancing read index
    if (writeIdx == readIdx) {
      readIdx = (readIdx + 1) % MAX_BUFFER;
    }

    packetCount++;
  }

  // Print received data in hex format
  Serial.println("Received data buffer contents:");
  for (size_t i = 0; i < packetCount; i++) {
    Serial.print(rxBuffer[i], HEX);
    Serial.print(" ");
    if ((i + 1) % 16 == 0) {
      Serial.println();
    }
  }

  // Send data via I2C to OLED
  Wire.beginTransmission(SCREEN_ADDR);
  for (size_t j = 0; j < packetCount; j++) {
    Wire.write(rxBuffer[j]);
  }
  Wire.endTransmission();

  // Clear the buffer count for next transmission
  packetCount = 0;
}

