LRESULT CALLBACK MainWndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
    // Initialize static variables only once
    static MARGINS extendedMargins = {-1};
    static HBRUSH customBrush = CreateSolidBrush(RGB(245, 245, 245));

    switch (msg) {
        case WM_NCCALCSIZE:
            if (wParam == TRUE) {
                // Modify non-client area sizing to extend title bar
                NCCALCSIZE_PARAMS* sizeParams = reinterpret_cast<NCCALCSIZE_PARAMS*>(lParam);
                sizeParams->rgrc[0].top += 35; // Increase top padding for custom title bar
                return WVR_REDRAW;
            }
            break;

        case WM_NCPAINT:
            {
                HRGN region = reinterpret_cast<HRGN>(wParam);
                HDC hdc = GetWindowDC(hwnd);
                RECT windowRect;
                GetWindowRect(hwnd, &windowRect);

                // Define custom title bar area
                RECT titleBarRect = {windowRect.left, windowRect.top, windowRect.right, windowRect.top + 35};

                // Draw custom background
                FillRect(hdc, &titleBarRect, customBrush);

                // Draw a decorative button on the right side of title bar
                const int buttonSize = 40;
                RECT buttonRect = {
                    titleBarRect.right - buttonSize - 10,
                    titleBarRect.top + 5,
                    titleBarRect.right - 10,
                    titleBarRect.bottom - 5
                };

                HBRUSH buttonBackground = CreateSolidBrush(RGB(70, 130, 180));
                FillRect(hdc, &buttonRect, buttonBackground);
                DeleteObject(buttonBackground);

                // Add subtle glow effect around the button
                for (int radius = 1; radius <= 8; ++radius) {
                    COLORREF glowColor = RGB(255, 255, 255 - radius * 25);
                    HBRUSH glowBrush = CreateSolidBrush(glowColor);
                    RECT glowRect = {
                        buttonRect.left - radius,
                        buttonRect.top - radius,
                        buttonRect.right + radius,
                        buttonRect.bottom + radius
                    };
                    FrameRect(hdc, &glowRect, glowBrush);
                    DeleteObject(glowBrush);
                }

                ReleaseDC(hwnd, hdc);
            }
            return 0;

        case WM_NCLBUTTONDOWN:
            // Detect click in custom button area (approximate coordinates)
            if (LOWORD(lParam) >= 760 && LOWORD(lParam) <= 800 &&
                HIWORD(lParam) >= 0 && HIWORD(lParam) <= 35) {
                MessageBoxW(hwnd, L"Custom Action Triggered!", L"Notification", MB_ICONINFORMATION | MB_OK);
                return 0;
            }
            break;

        case WM_CREATE:
            // Extend window frame into client area for glass effect
            DwmExtendFrameIntoClientArea(hwnd, &extendedMargins);
            break;

        case WM_DESTROY:
            PostQuitMessage(0);
            break;

        default:
            return DefWindowProcW(hwnd, msg, wParam, lParam);
    }

    return 0;
}

#include <unordered_set>

// Count the number of distinct elements in the array
int count_unique(int array[], int n) 
{ 
    std::unordered_set<int> unique_values; 
    int distinct_count = 0; 

    for (int index = 0; index < n; ++index) { 
        if (unique_values.find(array[index]) == unique_values.end()) { 
            unique_values.insert(array[index]); 
            ++distinct_count; 
        } 
    } 

    return distinct_count; 
}

