#include <cmath>
#include <algorithm>
#include <stdexcept>

// Compute the arithmetic mean of a dataset
double computeAverage(const std::vector<int>& values) {
    if (values.empty()) return 0.0;
    double total = 0.0;
    for (int val : values) {
        total += val;
    }
    return total / static_cast<double>(values.size());
}

// Compute population variance
double computeVariance(const std::vector<int>& values) {
    if (values.empty()) return 0.0;
    double avg = computeAverage(values);
    double squaredDiffSum = 0.0;
    for (int val : values) {
        double diff = val - avg;
        squaredDiffSum += diff * diff;
    }
    return squaredDiffSum / static_cast<double>(values.size());
}

// Compute population standard deviation
double computeStdDev(const std::vector<int>& values) {
    return std::sqrt(computeVariance(values));
}

// Compute quantile using linear interpolation-free method
double computeQuantile(const std::vector<int>& values, double percentile) {
    if (values.empty()) return 0.0;
    std::vector<int> sortedValues = values;
    std::sort(sortedValues.begin(), sortedValues.end());
    int size = sortedValues.size();
    int pos = static_cast<int>(std::round((size - 1) * percentile));
    return static_cast<double>(sortedValues[pos]);
}

// Compute interquartile range (IQR)
double computeIQR(const std::vector<int>& values) {
    if (values.empty()) return 0.0;
    double q1 = computeQuantile(values, 0.25);
    double q3 = computeQuantile(values, 0.75);
    return q3 - q1;
}

int main() {
    std::vector<int> dataset = {1, 3, 5, 7, 9, 11, 13};

    try {
        if (dataset.empty()) {
            throw std::invalid_argument("Dataset is empty");
        }

        double stdDevValue = computeStdDev(dataset);
        double iqrValue = computeIQR(dataset);

        std::cout << "Standard Deviation: " << stdDevValue << std::endl;
        std::cout << "Interquartile Range: " << iqrValue << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}

