#include <iostream>
#include <cmath>

using namespace std;

const int GRID_SIZE = 8;
char grid[GRID_SIZE][GRID_SIZE];

void setup_grid() {
    for (int row = 0; row < GRID_SIZE; ++row) {
        for (int col = 0; col < GRID_SIZE; ++col) {
            if (row == 1) grid[row][col] = 'P'; // White pawn
            else if (row == 6) grid[row][col] = 'p'; // Red pawn
            else grid[row][col] = '.';
        }
    }
}

bool can_move(int from_row, int from_col, int to_row, int to_col) {
    // Check boundaries
    if (to_row < 0 || to_row >= GRID_SIZE || to_col < 0 || to_col >= GRID_SIZE) 
        return false;

    char piece = grid[from_row][from_col];

    // Validate white pawn movement (moves upward: decreasing row index)
    if (piece == 'P') {
        // Must move exactly one row forward (up)
        if (from_row - to_row != 1) return false;
        // Cannot capture diagonally unless there's an enemy piece
        if (abs(from_col - to_col) > 1) return false;
        // Cannot move straight into an occupied square
        if (from_col == to_col && grid[to_row][to_col] != '.') return false;
    }

    // Validate red pawn movement (moves downward: increasing row index)
    if (piece == 'p') {
        // Must move exactly one row forward (down)
        if (to_row - from_row != 1) return false;
        // Cannot capture diagonally unless there's an enemy piece
        if (abs(from_col - to_col) > 1) return false;
        // Cannot move straight into an occupied square
        if (from_col == to_col && grid[to_row][to_col] != '.') return false;
    }

    return true;
}

void execute_move(int from_row, int from_col, int to_row, int to_col) {
    if (can_move(from_row, from_col, to_row, to_col)) {
        grid[to_row][to_col] = grid[from_row][from_col];
        grid[from_row][from_col] = '.';
    }
}

void display_grid() {
    for (int r = 0; r < GRID_SIZE; ++r) {
        for (int c = 0; c < GRID_SIZE; ++c) {
            cout << grid[r][c] << " ";
        }
        cout << endl;
    }
}

int main() {
    int start_row, start_col, end_row, end_col;
    setup_grid();
    display_grid();

    while (true) {
        cin >> start_row >> start_col >> end_row >> end_col;
        execute_move(start_row, start_col, end_row, end_col);
        display_grid();
    }

    return 0;
}

#include <portaudio.h>
#include <cmath>
#include <iostream>

#define AUDIO_SAMPLE_RATE (44100)
#define AUDIO_BUFFER_SIZE (64)
#define TONE_LENGTH (2.0) // duration in seconds

struct AudioContext {
    double toneFrequency;
    double currentPhase;
};

int audioCallback(const void* /*input*/, void* outputBuffer,
                  unsigned long frameCount,
                  const PaStreamCallbackTimeInfo* /*timeInfo*/,
                  PaStreamCallbackFlags /*statusFlags*/,
                  void* userData)
{
    AudioContext* context = static_cast<AudioContext*>(userData);
    float* audioOutput = static_cast<float*>(outputBuffer);

    for (unsigned long i = 0; i < frameCount; ++i)
    {
        *audioOutput++ = 0.5f * std::sin(context->currentPhase);
        context->currentPhase += 2.0 * M_PI * context->toneFrequency / AUDIO_SAMPLE_RATE;

        // Keep phase within [0, 2π) range
        if (context->currentPhase >= 2.0 * M_PI)
            context->currentPhase -= 2.0 * M_PI;
    }

    return paContinue;
}

int main()
{
    PaError errorCode = paNoError;
    PaStream* audioStream = nullptr;
    AudioContext audioData;

    // Initialize PortAudio system
    errorCode = Pa_Initialize();
    if (errorCode != paNoError)
        goto cleanupOnError;

    // Set up audio parameters: A4 note (440 Hz)
    audioData.toneFrequency = 440.0;
    audioData.currentPhase = 0.0;

    // Open default audio stream
    errorCode = Pa_OpenDefaultStream(&audioStream, 0, 1, paFloat32,
                                     AUDIO_SAMPLE_RATE, AUDIO_BUFFER_SIZE,
                                     audioCallback, &audioData);
    if (errorCode != paNoError)
        goto cleanupOnError;

    // Start audio playback
    errorCode = Pa_StartStream(audioStream);
    if (errorCode != paNoError)
        goto cleanupOnError;

    // Wait for specified duration
    Pa_Sleep(static_cast<int>(TONE_LENGTH * 1000));

    // Stop and close the stream
    errorCode = Pa_StopStream(audioStream);
    if (errorCode != paNoError)
        goto cleanupOnError;

    errorCode = Pa_CloseStream(audioStream);
    if (errorCode != paNoError)
        goto cleanupOnError;

    Pa_Terminate();
    return 0;

cleanupOnError:
    Pa_Terminate();
    std::cerr << "PortAudio error encountered:\n";
    std::cerr << "Error code: " << errorCode << "\n";
    std::cerr << "Description: " << Pa_GetErrorText(errorCode) << "\n";
    return -1;
}

