#include <iostream>
#include <unordered_map>
using namespace std;

struct ListNode {
    int value;
    ListNode* forward;
    ListNode* backward;

    ListNode(int val) : value(val), forward(nullptr), backward(nullptr) {}
};

class BidirectionalList {
    ListNode* head;
    ListNode* tail;
    unordered_map<int, ListNode*> lookup_table;

public:
    BidirectionalList() : head(nullptr), tail(nullptr) {}

    void addElement(int val) {
        ListNode* newNode = new ListNode(val);

        if (tail != nullptr) {
            tail->forward = newNode;
            newNode->backward = tail;
        } else {
            head = newNode;
        }

        tail = newNode;
        lookup_table[val] = newNode;
    }

    bool contains(int val) {
        return lookup_table.find(val) != lookup_table.end();
    }

    void eraseElement(int val) {
        auto it = lookup_table.find(val);
        if (it == lookup_table.end()) {
            return;
        }

        ListNode* current = it->second;

        if (current->backward != nullptr) {
            current->backward->forward = current->forward;
        } else {
            head = current->forward;
        }

        if (current->forward != nullptr) {
            current->forward->backward = current->backward;
        } else {
            tail = current->backward;
        }

        delete current;
        lookup_table.erase(it);
    }
};

int main() {
    BidirectionalList list;
    list.addElement(10);
    list.addElement(20);
    list.addElement(30);

    cout << (list.contains(20) ? "20 Found\n" : "20 Not found\n");
    cout << (list.contains(40) ? "40 Found\n" : "40 Not found\n");

    list.eraseElement(20);

    cout << (list.contains(20) ? "20 Found\n" : "20 Not found\n");

    return 0;
}

#include <cub/cub.cuh>

template <typename T>
__global__ void segmentedScanKernel(T *d_input, T *d_output, int segmentCount, int itemsPerSegment) {
    // Shared memory for block scan operations
    __shared__ typename cub::BlockScan<T, 256>::TempStorage temp_storage[4]; // Multiple instances for different blocks

    int blockId = blockIdx.x;
    int threadId = threadIdx.x;

    // Pointers to current segment's data
    T *currentInput = d_input + blockId * itemsPerSegment;
    T *currentOutput = d_output + blockId * itemsPerSegment;

    // Initialize thread data
    T inputValue = (threadId < itemsPerSegment) ? currentInput[threadId] : T(0);
    T inclusiveResult;

    // Use BlockScan to compute prefix sum within the block
    cub::BlockScan<T, 256> blockScan(temp_storage[blockId % 4]);
    blockScan.InclusiveSum(inputValue, inclusiveResult);

    // Store results only for valid threads
    if (threadId < itemsPerSegment) {
        currentOutput[threadId] = inclusiveResult;
    }
}

int main() {
    // Configuration parameters
    const int numSegments = 100;
    const int segmentLength = 1024;
    const int totalElements = numSegments * segmentLength;

    // Device memory allocation
    float *deviceInput, *deviceOutput;
    cudaMalloc(&deviceInput, totalElements * sizeof(float));
    cudaMalloc(&deviceOutput, totalElements * sizeof(float));

    // Assume deviceInput is initialized with appropriate values here

    // Kernel launch configuration
    dim3 threadsPerBlock(256);
    dim3 blocksPerGrid(numSegments);

    // Launch kernel
    segmentedScanKernel<<<blocksPerGrid, threadsPerBlock>>>(deviceInput, deviceOutput, numSegments, segmentLength);

    // Synchronize and copy results back
    float *hostOutput = new float[totalElements];
    cudaMemcpy(hostOutput, deviceOutput, totalElements * sizeof(float), cudaMemcpyDeviceToHost);

    // Cleanup resources
    cudaFree(deviceInput);
    cudaFree(deviceOutput);
    delete[] hostOutput;

    return 0;
}

#include <cuda_runtime.h>
#include <iostream>

extern "C" {
    void cudaMultiply(int* a, int* b, int* c, int size) {
        int* dev_a = nullptr;
        int* dev_b = nullptr;
        int* dev_c = nullptr;

        cudaMalloc(&dev_a, size * sizeof(int));
        cudaMalloc(&dev_b, size * sizeof(int));
        cudaMalloc(&dev_c, size * sizeof(int));

        cudaMemcpy(dev_a, a, size * sizeof(int), cudaMemcpyHostToDevice);
        cudaMemcpy(dev_b, b, size * sizeof(int), cudaMemcpyHostToDevice);

        const int threadsPerBlock = 256;
        const int blocksPerGrid = (size + threadsPerBlock - 1) / threadsPerBlock;

        multiply<<<blocksPerGrid, threadsPerBlock>>>(dev_a, dev_b, dev_c, size);

        cudaMemcpy(c, dev_c, size * sizeof(int), cudaMemcpyDeviceToHost);

        cudaFree(dev_a);
        cudaFree(dev_b);
        cudaFree(dev_c);
    }

    __global__ void multiply(int* input1, int* input2, int* output, int length) {
        int position = blockIdx.x * blockDim.x + threadIdx.x;
        if (position < length) {
            output[position] = input1[position] * input2[position];
        }
    }
}

#include <windows.h>
