// Retrieve available serial port names from Windows registry
std::vector<std::string> getSerialPorts() {
    HKEY hKey;
    LONG status = RegOpenKeyEx(HKEY_LOCAL_MACHINE, TEXT("HARDWARE\\DEVICEMAP\\SERIALCOMM"), 0, KEY_READ, &hKey);
    if (status != ERROR_SUCCESS) {
        return {};
    }

    std::vector<std::string> ports;
    char nameBuffer[1024];
    char dataBuffer[1024];
    DWORD nameLength = 1024;
    DWORD dataLength = 1024;
    DWORD type;

    int index = 0;
    while (true) {
        nameLength = 1024;
        dataLength = 1024;

        status = RegEnumValue(hKey, index++, 
                              nameBuffer, &nameLength,
                              nullptr, &type,
                              reinterpret_cast<BYTE*>(dataBuffer), &dataLength);

        if (status != ERROR_SUCCESS) {
            break;
        }

        if (type == REG_SZ) {
            ports.emplace_back(dataBuffer);
        }
    }

    RegCloseKey(hKey);
    return ports;
}

int main() {
    std::vector<std::string> serialPorts = getSerialPorts();
    for (const std::string& port : serialPorts) {
        std::cout << port << '\n';
    }
    return 0;
}

#include <limits.h> // For CHAR_BIT
#include <stdint.h> // For uint32_t

// Compute floor(log2(x)) for positive integers
static inline int log2(int x) {
#if defined(__x86_64__) || defined(__i386__)
    // Use bit scan reverse instruction on x86/x86_64
    int result;
    __asm__ volatile (
        "bsr %1, %0"
        : "=r"(result)
        : "r"(x)
    );
    return result;
#elif defined(__arm__) || defined(__aarch64__)
    // Use built-in count leading zeros for ARM architectures
    return 31 - __builtin_clz(static_cast<unsigned int>(x));
#else
    // Generic implementation using bit shifting
    int exponent = 0;
    int value = x;
    while (value > 1) {
        value >>= 1;
        exponent++;
    }
    return exponent;
#endif
}

#include <iostream>
#include <string>
#include <stdexcept>

class CalendarDate {
private:
    int dayValue;
    int monthValue;
    int yearValue;

public:
    // Constructor with validation
    CalendarDate(int d, int m, int y) : dayValue(d), monthValue(m), yearValue(y) {
        if (d < 1 || d > 31) throw std::invalid_argument("Day must be between 1 and 31");
        if (m < 1 || m > 12) throw std::invalid_argument("Month must be between 1 and 12");
        if (y < 0) throw std::invalid_argument("Year cannot be negative");
    }

    // Accessor methods
    int getDay() const { return dayValue; }
    int getMonth() const { return monthValue; }
    int getYear() const { return yearValue; }

    // Equality operator
    bool operator==(const CalendarDate& other) const {
        return (dayValue == other.dayValue && 
                monthValue == other.monthValue && 
                yearValue == other.yearValue);
    }

    // Less-than operator using lexicographical comparison
    bool operator<(const CalendarDate& other) const {
        if (yearValue != other.yearValue) 
            return yearValue < other.yearValue;
        if (monthValue != other.monthValue) 
            return monthValue < other.monthValue;
        return dayValue < other.dayValue;
    }

    // Greater-than operator defined via other operators
    bool operator>(const CalendarDate& other) const {
        return other < *this && !(*this == other);
    }

    // Less-than-or-equal operator
    bool operator<=(const CalendarDate& other) const {
        return (*this < other) || (*this == other);
    }

    // Greater-than-or-equal operator
    bool operator>=(const CalendarDate& other) const {
        return (*this > other) || (*this == other);
    }

    // Convert date to string format
    std::string asString() const {
        return std::to_string(dayValue) + "/" + 
               std::to_string(monthValue) + "/" + 
               std::to_string(yearValue);
    }
};

int main() {
    try {
        CalendarDate firstDate(10, 10, 2020);
        CalendarDate secondDate(10, 11, 2020);

        std::cout << "First Date: " << firstDate.asString() << std::endl;
        std::cout << "Second Date: " << secondDate.asString() << std::endl;

        if (firstDate == secondDate) {
            std::cout << "Both dates are identical." << std::endl;
        } else if (firstDate < secondDate) {
            std::cout << "First Date comes before Second Date." << std::endl;
        } else {
            std::cout << "First Date comes after Second Date." << std::endl;
        }
    } catch (const std::invalid_argument& error) {
        std::cerr << "Validation failed: " << error.what() << std::endl;
    }

    return 0;
}

