#include <cuda_runtime.h>

// CUDA kernel to convert RGBA image to grayscale using weighted sum
__global__
void rgba_to_greyscale(const uchar4* const rgbaImage,
                       unsigned char* const greyImage,
                       int numRows, int numCols)
{
    // Calculate global thread coordinates
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    // Check bounds to avoid out-of-bounds memory access
    if (col >= numCols || row >= numRows) {
        return;
    }

    // Compute linear index for 2D pixel position
    int pixelIndex = row * numCols + col;

    // Load RGBA pixel data
    uchar4 pixel = rgbaImage[pixelIndex];

    // Apply standard luminance coefficients to compute grayscale value
    float intensity = 0.299f * pixel.x + 0.587f * pixel.y + 0.114f * pixel.z;

    // Store result as unsigned char
    greyImage[pixelIndex] = static_cast<unsigned char>(intensity);
}

// Host function to launch the CUDA kernel
void your_rgba_to_greyscale(const uchar4 * const h_rgbaImage,
                            uchar4 * const d_rgbaImage,
                            unsigned char* const d_greyImage,
                            size_t numRows,
                            size_t numCols)
{
    // Define block dimensions (16x16 threads per block)
    const dim3 threadsPerBlock(16, 16, 1);

    // Calculate grid dimensions with ceiling division to cover entire image
    const dim3 blocksPerGrid((static_cast<int>(numCols) + threadsPerBlock.x - 1) / threadsPerBlock.x,
                             (static_cast<int>(numRows) + threadsPerBlock.y - 1) / threadsPerBlock.y,
                             1);

    // Launch kernel with computed grid and block dimensions
    rgba_to_greyscale<<<blocksPerGrid, threadsPerBlock>>>(
        d_rgbaImage,
        d_greyImage,
        static_cast<int>(numRows),
        static_cast<int>(numCols)
    );

    // Ensure all kernel operations complete before proceeding
    cudaDeviceSynchronize();

    // Check for any CUDA errors during kernel execution
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        // In a real application, you might want to handle this more explicitly
        // For now, just re-throw the error
        throw std::runtime_error(cudaGetErrorString(err));
    }
}

