// Wrapper struct to manage host context lifecycle
struct ManagedContext {
    hostfxr_handle ctx = nullptr;

    ~ManagedContext() {
        if (ctx) {
            hostfxr_close(ctx);
        }
    }

    bool initialize(const char* host_path, const char* config_path) {
        return hostfxr_initialize_for_runtime_config(
            host_path,
            config_path,
            nullptr,
            &ctx
        ) == 0 && ctx != nullptr;
    }

    bool get_delegate(const char* signature, void** delegate) {
        return hostfxr_runtime_info_get_runtime_delegate(
            ctx,
            signature,
            delegate
        ) == 0 && *delegate != nullptr;
    }

    bool load_function(const char* assembly, const char* type, const char* method, void** func_ptr) {
        return hostfxr_runtime_info_load_assembly_and_get_function_pointer(
            ctx,
            assembly,
            type,
            method,
            func_ptr
        ) == 0 && *func_ptr != nullptr;
    }
};

// Entry point: invoke C# method using hostfxr
void invoke_csharp_method(const char* dllPath, const char* className, const char* methodName, const char* inputArg)
{
    ManagedContext context;

    // Step 1: Initialize runtime
    if (!context.initialize("path/to/hostfxr.dll", "path/to/app.runtimeconfig.json")) {
        std::cerr << "Failed to initialize .NET runtime." << std::endl;
        return;
    }

    // Step 2: Load function pointer for target method
    void* methodPtr = nullptr;
    if (!context.load_function(dllPath, className, methodName, &methodPtr)) {
        std::cerr << "Failed to load C# method '" << methodName << "' from assembly." << std::endl;
        return;
    }

    // Step 3: Cast and invoke
    using MethodSignature = std::string(*)(const std::string&);
    auto method = reinterpret_cast<MethodSignature>(methodPtr);

    try {
        std::string result = method(inputArg);
        std::cout << result << std::endl;
    } catch (...) {
        std::cerr << "Exception thrown during C# method invocation." << std::endl;
    }
}

