#include <Arduino.h>

// Pin assignments for the four LEDs
const int LED_PINS[] = {3, 5, 6, 9};

// Current brightness levels for each LED (0-255)
byte ledBrightness[4] = {0, 0, 0, 0};

// Direction of brightness change: 1 for increasing, -1 for decreasing
int brightnessChangeDir[4] = {1, 1, 1, 1};

// Timestamps for state transitions
unsigned long glowPhaseStart[4] = {0, 0, 0, 0};
unsigned long fadePhaseStart[4] = {0, 0, 0, 0};

// Current system time
unsigned long currentTime;

// Configuration constants for timing ranges
const unsigned long GLOW_TIME_MIN = 400UL;
const unsigned long GLOW_TIME_MAX = 600UL;

const unsigned long FADE_TIME_MIN = 400UL;
const unsigned long FADE_TIME_MAX = 600UL;

void setup() {
  // Initialize LED pins as outputs
  for (int idx = 0; idx < 4; ++idx) {
    pinMode(LED_PINS[idx], OUTPUT);
  }

  // Seed random number generator with analog noise
  randomSeed(analogRead(A0));
}

void loop() {
  currentTime = millis(); // Capture current time

  for (int k = 0; k < 4; ++k) {
    // Determine if currently in glow phase
    if ((currentTime - glowPhaseStart[k]) < random(GLOW_TIME_MIN, GLOW_TIME_MAX)) {
      // Adjust brightness by step size (5) in current direction
      ledBrightness[k] += 5 * brightnessChangeDir[k];

      // Handle boundary conditions and reverse direction when needed
      if (ledBrightness[k] >= 255 || ledBrightness[k] <= 0) {
        brightnessChangeDir[k] *= -1;
        ledBrightness[k] = constrain(ledBrightness[k], 0, 255);
      }

      // Apply PWM output to LED
      analogWrite(LED_PINS[k], ledBrightness[k]);

    } else if ((currentTime - fadePhaseStart[k]) > random(FADE_TIME_MIN, FADE_TIME_MAX)) {
      // Transition to glow phase after fade completes
      glowPhaseStart[k] = currentTime;
      brightnessChangeDir[k] = 1;

    } else {
      // Perform decay (fade-out) phase
      if (ledBrightness[k] > 0) {
        ledBrightness[k] -= 5;
        analogWrite(LED_PINS[k], ledBrightness[k]);
      } else {
        // Mark start of decay period once brightness reaches zero
        fadePhaseStart[k] = currentTime;
      }
    }
  }
}

