// Helper structure to represent an instruction in a tree-like control flow
struct InstNode {
    uint64_t inst_addr;
    uint8_t* raw_bytes;
    size_t byte_count;
    std::vector<InstNode*> successors;

    InstNode(uint64_t addr, uint8_t* data, size_t len)
        : inst_addr(addr), raw_bytes(data), byte_count(len) {}

    ~InstNode() {
        delete[] raw_bytes;
        for (auto succ : successors) {
            delete succ;
        }
    }

    void append_successor(InstNode* node) {
        successors.push_back(node);
    }
};

class ControlFlowTree {
private:
    InstNode* head;

public:
    ControlFlowTree() : head(nullptr) {}

    ~ControlFlowTree() {
        if (head) {
            delete head;
        }
    }

    void insert_instruction(uint64_t addr, uint8_t* bytes, size_t len, InstNode* target_parent = nullptr) {
        InstNode* new_node = new InstNode(addr, bytes, len);
        if (target_parent) {
            target_parent->append_successor(new_node);
        } else {
            head = new_node;
        }
    }

    InstNode* locate_instruction_by_address(uint64_t target_addr) {
        return search_node(head, target_addr);
    }

private:
    InstNode* search_node(InstNode* current, uint64_t target_addr) {
        if (!current) {
            return nullptr;
        }
        if (current->inst_addr == target_addr) {
            return current;
        }
        for (auto child : current->successors) {
            InstNode* found = search_node(child, target_addr);
            if (found) {
                return found;
            }
        }
        return nullptr;
    }
};

