// Custom task class for executing database operations in threads
class DbOperation : public QRunnable {
public:
    DbOperation(const QString &sql, const QVariantList &values)
        : m_sqlStatement(sql), m_values(values) {}

    void run() override {
        QMutexLocker lock(&s_mutex);
        QSqlDatabase connection = QSqlDatabase::database("worker_connection");

        if (!connection.isOpen()) {
            connection = QSqlDatabase::addDatabase("QSQLITE", "worker_connection");
            connection.setDatabaseName("path/to/your/database.db");
            if (!connection.open()) {
                qWarning() << "Failed to open database:" << connection.lastError().text();
                return;
            }
        }

        QSqlQuery query(connection);
        query.prepare(m_sqlStatement);
        for (const QVariant &value : m_values) {
            query.addBindValue(value);
        }
        if (!query.exec()) {
            qWarning() << "SQL execution failed:" << query.lastError().text();
        }
    }

private:
    QString m_sqlStatement;
    QVariantList m_values;
    static QMutex s_mutex;
};

QMutex DbOperation::s_mutex;

int main(int argc, char *argv[]) {
    QCoreApplication app(argc, argv);

    QThreadPool threadPool;
    threadPool.setMaxThreadCount(4); // Configure maximum concurrent threads

    // Create and schedule database tasks
    DbOperation *insertTask1 = new DbOperation(
        "INSERT INTO table_name (column1, column2) VALUES (?, ?)", 
        { "value1", "value2" }
    );
    DbOperation *insertTask2 = new DbOperation(
        "INSERT INTO table_name (column1, column2) VALUES (?, ?)", 
        { "value3", "value4" }
    );

    threadPool.start(insertTask1);
    threadPool.start(insertTask2);

    // Ensure all scheduled tasks finish before exiting
    threadPool.waitForDone();

    return app.exec();
}

