// Compute greatest common divisor using modified Euclidean algorithm
int computeGCD(int x, int y) {
    // Ensure positive values for consistent results
    if (x < 0) x = -x;
    if (y < 0) y = -y;

    // Handle edge cases
    if (x == 0) return y;
    if (y == 0) return x;

    int remainder = 0;
    while (y != 0) {
        remainder = x % y;
        x = y;
        y = remainder;
    }
    return x;
}

// Determine if two integers are relatively prime (coprime)
bool checkCoprime(int first, int second) {
    return computeGCD(first, second) == 1;
}

#include <windows.h>

// Counts the number of stack frames starting from a given frame pointer
int GetCallDepth(DWORD64 initialFrame = 0)
{
    DWORD64 returnAddress;
    int depth = 0;
    DWORD64 currentFrame;
    PDWORD64 framePtr, prevFramePtr;

    if (!initialFrame) // No initial frame provided; use current stack frame
    {
        __asm
        {
            mov rcx, rbp
            mov currentFrame, rcx
        }
    }
    else
    {
        currentFrame = initialFrame;
    }

    framePtr = (PDWORD64)currentFrame;
    do
    {
        returnAddress = framePtr[1];
        prevFramePtr = framePtr;
        framePtr = (PDWORD64)framePtr[0]; // Move to next higher stack frame

        // Validate alignment: frame pointer must be 8-byte aligned
        if (reinterpret_cast<DWORD64>(framePtr) & 7)
            break;

        // Ensure frames are growing upward (valid stack order)
        if (framePtr <= prevFramePtr)
            break;

        // Check memory accessibility before reading
        if (IsBadWritePtr(framePtr, sizeof(QWORD) * 2))
            break;

        depth++;
    } while (true);

    return depth;
}

