// Determine the median of three integers using alternative comparison logic
int getMiddleValue(int x, int y, int z) {
    // Check if y is between x and z (inclusive)
    if ((y >= x && y <= z) || (y <= x && y >= z)) {
        return y;
    }
    // Check if z is between x and y (inclusive)
    else if ((z >= x && z <= y) || (z <= x && z >= y)) {
        return z;
    }
    // Otherwise, x must be the median
    else {
        return x;
    }
}

