#include <iostream>
#include <string>
#include <unordered_map>
#include <variant>
#include <optional>
#include <vector>

enum class TokenType {
    NUMBER,
    VARIABLE,
    OPERATOR,
    PARENTHESIS,
};

struct Token {
    TokenType type;
    std::variant<int, std::string> value;
};

class ExpressionEvaluator {
public:
    ExpressionEvaluator(const std::string& expr, const std::unordered_map<std::string, int>& known_values)
        : expression_(expr), known_values_(known_values) {}

    std::optional<bool> compute() {
        std::vector<Token> tokens = parse_expression(expression_);
        return process_tokens(tokens);
    }

private:
    std::vector<Token> parse_expression(const std::string& expr) {
        std::vector<Token> result;
        std::string buffer;

        for (char character : expr) {
            if (std::isspace(character)) {
                continue;
            }

            if (character == '(' || character == ')' || character == '&' || character == '|' || character == '>') {
                if (!buffer.empty()) {
                    TokenType token_type = (buffer[0] == '(' || buffer[0] == ')') ? TokenType::PARENTHESIS : TokenType::VARIABLE;
                    result.emplace_back(Token{token_type, buffer});
                    buffer.clear();
                }
                result.emplace_back(Token{TokenType::OPERATOR, std::string(1, character)});
            } else {
                buffer += character;
            }
        }

        if (!buffer.empty()) {
            TokenType token_type = (buffer[0] == '(' || buffer[0] == ')') ? TokenType::PARENTHESIS : TokenType::VARIABLE;
            result.emplace_back(Token{token_type, buffer});
        }

        return result;
    }

    std::optional<bool> process_tokens(std::vector<Token>& tokens) {
        // Replace variables with their values or boolean literals
        for (size_t index = 0; index < tokens.size(); ++index) {
            if (std::holds_alternative<std::string>(tokens[index].value)) {
                const std::string& var_name = std::get<std::string>(tokens[index].value);

                auto it = known_values_.find(var_name);
                if (it != known_values_.end()) {
                    tokens[index] = {TokenType::NUMBER, it->second};
                } else if (var_name == "true") {
                    tokens[index] = {TokenType::NUMBER, 1};
                } else if (var_name == "false") {
                    tokens[index] = {TokenType::NUMBER, 0};
                }
            }
        }

        // Check if any variables remain unresolved
        for (const auto& token : tokens) {
            if (std::get_if<std::string>(&token.value)) {
                return std::nullopt;
            }
        }

        return evaluate_logical_expression(tokens);
    }

    std::optional<bool> evaluate_logical_expression(const std::vector<Token>& tokens) {
        std::vector<std::optional<bool>> evaluation_stack;

        for (const auto& token : tokens) {
            if (token.type == TokenType::NUMBER) {
                evaluation_stack.push_back(std::get<int>(token.value) != 0);
            } else if (token.type == TokenType::OPERATOR) {
                char operation = std::get<std::string>(token.value)[0];

                if (operation == '>') {
                    if (evaluation_stack.size() < 2) return std::nullopt;
                    auto right_operand = evaluation_stack.back(); evaluation_stack.pop_back();
                    auto left_operand = evaluation_stack.back(); evaluation_stack.pop_back();
                    evaluation_stack.push_back(left_operand && right_operand);
                } else if (operation == '&') {
                    if (evaluation_stack.size() < 2) return std::nullopt;
                    auto right_operand = evaluation_stack.back(); evaluation_stack.pop_back();
                    auto left_operand = evaluation_stack.back(); evaluation_stack.pop_back();
                    evaluation_stack.push_back(left_operand && right_operand);
                } else if (operation == '|') {
                    if (evaluation_stack.size() < 2) return std::nullopt;
                    auto right_operand = evaluation_stack.back(); evaluation_stack.pop_back();
                    auto left_operand = evaluation_stack.back(); evaluation_stack.pop_back();
                    evaluation_stack.push_back(left_operand || right_operand);
                }
            }
        }

        if (evaluation_stack.size() != 1) return std::nullopt;
        return evaluation_stack.front();
    }

private:
    std::string expression_;
    std::unordered_map<std::string, int> known_values_;
};

int main() {
    std::string logical_expression = "((A>0) && (B>5 || C > 10))";
    std::unordered_map<std::string, int> variable_values = {{"A", -1}};

    ExpressionEvaluator evaluator(logical_expression, variable_values);
    auto computed_result = evaluator.compute();

    if (computed_result) {
        std::cout << "Expression evaluates to: " << std::boolalpha << *computed_result << std::endl;
    } else {
        std::cout << "Expression cannot be fully evaluated with the given values." << std::endl;
    }

    return 0;
}

