    npy_intp* dimensions = PyArray_DIMS(arr);
    cv::Mat result(dimensions[0], dimensions[1], CV_64F, PyArray_DATA(arr));
    return result;
}

// Demonstrate calling scikit-learn from C++ via Boost.Python
void execute_sklearn_workflow() {
    // Set up Python environment access
    boost::python::object main_mod = boost::python::import("__main__");
    boost::python::dict global_ns = boost::python::extract<boost::python::dict>(main_mod.attr("__dict__"));

    // Load required modules
    boost::python::object sklearn_pkg = boost::python::import("sklearn");
    boost::python::object data_loader = sklearn_pkg.attr("datasets");
    boost::python::object estimator_module = sklearn_pkg.attr("linear_model");

    // Fetch and prepare dataset
    boost::python::object iris_dataset = data_loader.attr("load_iris")();
    boost::python::object features = iris_dataset.attr("data");
    boost::python::object labels = iris_dataset.attr("target");

    // Initialize and train model
    boost::python::object classifier = estimator_module.attr("LogisticRegression")();
    classifier.attr("fit")(features, labels);

    // Generate predictions
    boost::python::object raw_predictions = classifier.attr("predict")(features);
    boost::python::list pred_list = boost::python::extract<boost::python::list>(raw_predictions);

    // Transfer predictions to native C++ container
    std::vector<int> local_results;
    int count = boost::python::len(pred_list);
    for (int idx = 0; idx < count; ++idx) {
        local_results.push_back(boost::python::extract<int>(pred_list[idx]));
    }

    // Output results
    for (const auto& val : local_results) {
        std::cout << val << " ";
    }
    std::cout << "\n";
}

