// High-resolution timer function
double get_time() {
    struct timeval tv;
    gettimeofday(&tv, nullptr);
    return static_cast<double>(tv.tv_sec) + tv.tv_usec / 1000000.0;
}

// Vectorized computation using SSE instructions
void compute_vector(double base_add, double base_mul, long long operations) {
    // Initialize SIMD registers with starting values
    __m128d add_val = _mm_set1_pd(base_add);
    __m128d mul_val = _mm_set1_pd(base_mul);

    // Pair of accumulator vectors for sum operations
    __m128d acc1 = _mm_set_pd(0.3, -0.3);
    __m128d acc2 = _mm_set_pd(0.4, -0.4);

    // Pair of multiplier vectors
    __m128d mult1 = _mm_set_pd(2.0, 2.1);
    __m128d mult2 = _mm_set_pd(2.2, 2.3);

    // Calculate number of iterations: each loop performs 8 floating-point ops
    int iterations = static_cast<int>(operations / 8);

    // Main computational loop
    for (int i = 0; i < iterations; ++i) {
        // Update multipliers by multiplying with base multiplier
        mult1 = _mm_mul_pd(mult1, mul_val);
        mult2 = _mm_mul_pd(mult2, mul_val);

        // Update accumulators by adding base addend
        acc1 = _mm_add_pd(acc1, add_val);
        acc2 = _mm_add_pd(acc2, add_val);
    }

    // Extract results from SIMD registers to scalar memory
    double temp1[2], temp2[2];
    _mm_storeu_pd(temp1, acc1);
    _mm_storeu_pd(temp2, acc2);

    // Combine partial results into final scalar value
    double final_result = temp1[0] + temp1[1] + temp2[0] + temp2[1];

    std::cout << "Result: " << final_result << std::endl;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <num>\n";
        std::cerr << "Number of operations: <num> millions\n";
        return EXIT_FAILURE;
    }

    long long count = static_cast<long long>(atoll(argv[1])) * 1000000;
    if (count <= 0) {
        count = 1000000; // Default to 1 million operations
    }

    const double pi_val = M_PI;
    const double increment = 1.0 + 1e-8;

    // Start timing
    double start_time = get_time();
    compute_vector(pi_val, increment, count);

    // Stop timing and compute performance metrics
    double elapsed = get_time() - start_time;
    double gflops = static_cast<double>(count) / elapsed / 1e9;

    std::cout << "compute_vector: " << elapsed << " s, " 
              << gflops << " Gflops" << std::endl;

    return EXIT_SUCCESS;
}

