// Main function to demonstrate asynchronous CUDA operations with streams
int main() {
    float *hostPtrA, *hostPtrB, *devicePtrA, *devicePtrB;

    const int arraySize = 1000;
    size_t memoryBytes = arraySize * sizeof(float);

    cudaStream_t streamA, streamB;

    // Allocate pinned host memory for two arrays
    cudaMallocHost((void**)&hostPtrA, memoryBytes);
    cudaMallocHost((void**)&hostPtrB, memoryBytes);

    // Initialize the first host array with values 0 to n-1
    for (int idx = 0; idx < arraySize; ++idx) {
        hostPtrA[idx] = static_cast<float>(idx);
    }

    // Allocate device memory for input and output arrays
    cudaMalloc<float>(&devicePtrA, memoryBytes);
    cudaMalloc<float>(&devicePtrB, memoryBytes);

    // Define kernel launch configuration
    dim3 threadsPerBlock(16);
    dim3 blocksPerGrid((arraySize + threadsPerBlock.x - 1) / threadsPerBlock.x);

    // Create two CUDA streams for asynchronous execution
    cudaStreamCreate(&streamA);
    cudaStreamCreate(&streamB);

    // Asynchronously copy data from host to device using streamA
    cudaMemcpyAsync(devicePtrA, hostPtrA, memoryBytes, cudaMemcpyHostToDevice, streamA);

    // Launch kernel using streamB to process data
    kernel_increment<<<blocksPerGrid, threadsPerBlock, 0, streamB>>>(devicePtrA, devicePtrB, arraySize);

    // Asynchronously copy result back to host using streamA
    cudaMemcpyAsync(hostPtrB, devicePtrB, memoryBytes, cudaMemcpyDeviceToHost, streamA);

    // Check for errors after kernel launch and copies
    printf("Status: %s\n", cudaGetErrorString(cudaGetLastError()));

    // Ensure all operations complete before cleanup
    cudaDeviceSynchronize();

    // Final error check after synchronization
    printf("Status: %s\n", cudaGetErrorString(cudaGetLastError()));

    // Destroy streams and free resources
    cudaStreamDestroy(streamA);
    cudaStreamDestroy(streamB);

    cudaFree(devicePtrA);
    cudaFree(devicePtrB);

    // Free pinned host memory
    cudaFreeHost(hostPtrA);
    cudaFreeHost(hostPtrB);

    return 0;
}

