#include <vector>
#include <memory>

struct Coordinate {
    float horizontal, vertical;
};

struct BoundingBox {
    float left, top;  // Top-left corner coordinates
    float extentX, extentY;

    bool encloses(const Coordinate& pt) const {
        return pt.horizontal >= left && pt.horizontal <= left + extentX &&
               pt.vertical >= top && pt.vertical <= top + extentY;
    }

    bool overlaps(const BoundingBox& other) const {
        return left < other.left + other.extentX && left + extentX > other.left &&
               top < other.top + other.extentY && top + extentY > other.top;
    }
};

class SpatialPartitionNode {
public:
    SpatialPartitionNode(const BoundingBox& area, int maxPoints)
        : boundary(area), limit(maxPoints), split(false) {}

    void addPoint(const Coordinate& pt);
    void divideRegion();
    std::vector<Coordinate> getPointsIn(const BoundingBox& region);

private:
    BoundingBox boundary;
    int limit;
    bool split;
    std::vector<Coordinate> dataPoints;
    std::unique_ptr<SpatialPartitionNode> upperLeft, upperRight, lowerLeft, lowerRight;
};

void SpatialPartitionNode::addPoint(const Coordinate& pt) {
    if (!boundary.encloses(pt)) {
        return;  // Point lies outside this node's area
    }

    if (dataPoints.size() < static_cast<size_t>(limit)) {
        dataPoints.push_back(pt);
    } else {
        if (!split) {
            divideRegion();
        }

        upperLeft->addPoint(pt);
        upperRight->addPoint(pt);
        lowerLeft->addPoint(pt);
        lowerRight->addPoint(pt);
    }
}

void SpatialPartitionNode::divideRegion() {
    float halfWidth = boundary.extentX / 2.0f;
    float halfHeight = boundary.extentY / 2.0f;
    float originX = boundary.left;
    float originY = boundary.top;

    upperLeft = std::make_unique<SpatialPartitionNode>(
        BoundingBox{originX, originY, halfWidth, halfHeight}, limit);
    upperRight = std::make_unique<SpatialPartitionNode>(
        BoundingBox{originX + halfWidth, originY, halfWidth, halfHeight}, limit);
    lowerLeft = std::make_unique<SpatialPartitionNode>(
        BoundingBox{originX, originY + halfHeight, halfWidth, halfHeight}, limit);
    lowerRight = std::make_unique<SpatialPartitionNode>(
        BoundingBox{originX + halfWidth, originY + halfHeight, halfWidth, halfHeight}, limit);

    split = true;
}

std::vector<Coordinate> SpatialPartitionNode::getPointsIn(const BoundingBox& region) {
    std::vector<Coordinate> result;

    if (!boundary.overlaps(region)) {
        return result;
    }

    for (const auto& coord : dataPoints) {
        if (region.encloses(coord)) {
            result.push_back(coord);
        }
    }

    if (split) {
        auto leftUpper = upperLeft->getPointsIn(region);
        auto rightUpper = upperRight->getPointsIn(region);
        auto leftLower = lowerLeft->getPointsIn(region);
        auto rightLower = lowerRight->getPointsIn(region);

        result.insert(result.end(), leftUpper.begin(), leftUpper.end());
        result.insert(result.end(), rightUpper.begin(), rightUpper.end());
        result.insert(result.end(), leftLower.begin(), leftLower.end());
        result.insert(result.end(), rightLower.begin(), rightLower.end());
    }

    return result;
}

#include <immintrin.h>

// Compute vectorized sum using AVX2 intrinsics with modified control flow
void compute_vector_sum(double* v, double* m_f, int i, int j, double& d2v) {
    __m256d vec_plus, vec_minus, permuted_plus, permuted_minus, combined, scaled;

    // Load values from memory with unaligned addresses
    vec_plus = _mm256_loadu_pd(&v[i + j]);
    vec_minus = _mm256_loadu_pd(&v[i - j]);

    // Apply permutation to swap pairs of elements (0x5 = 0101 binary)
    permuted_plus = _mm256_permute_pd(vec_plus, 0x5);
    permuted_minus = _mm256_permute_pd(vec_minus, 0x5);

    // Combine the two permuted vectors via addition
    combined = _mm256_add_pd(permuted_plus, permuted_minus);

    // Scale the combined result by m_f[j] and accumulate into d2v
    scaled = _mm256_mul_pd(_mm256_set1_pd(m_f[j]), combined);
    d2v += _mm256_cvtsd_f64(_mm256_hadd_pd(scaled, _mm256_setzero_pd())) * 0.5;
}

#include <iostream>
