#include <typeindex>

// Base class for all event data
class EventData
{
public:
    virtual ~EventData() = default;
};

// Template class to wrap specific event data
template <typename T>
class TypedEvent : public EventData
{
public:
    T value;

    explicit TypedEvent(const T& val)
        : value{val} {}
};

// Central event management system
class EventDispatcher
{
public:
    // Register a callback for a specific event type
    template <typename T>
    void AddListener(std::function<void(const T&)> handler)
    {
        auto key = std::type_index(typeid(TypedEvent<T>));
        m_subscribers[key].emplace_back([handler](const EventData *eventPtr) {
            const auto typedEvent = static_cast<const TypedEvent<T> *>(eventPtr);
            handler(typedEvent->value);
        });
    }

    // Send an event of specific type with given data
    template <typename T>
    void Trigger(const T& payload)
    {
        auto key = std::type_index(typeid(TypedEvent<T>));
        auto it = m_subscribers.find(key);
        if (it == m_subscribers.end())
            return;

        const auto& handlers = it->second;
        for (const auto& handler : handlers)
        {
            handler(&TypedEvent<T>(payload));
        }
    }

private:
    std::unordered_map<std::type_index, std::vector<std::function<void(const EventData *)>>> m_subscribers;
};

int main()
{
    EventDispatcher dispatcher;

    // Subscribe to integer events
    dispatcher.AddListener<int>([](const int &value) {
        std::cout << "Int event received: " << value << std::endl;
    });

    // Subscribe to floating-point events
    dispatcher.AddListener<float>([](const float &value) {
        std::cout << "Float event received: " << value << std::endl;
    });

    // Dispatch events
    dispatcher.Trigger<int>(100);
    dispatcher.Trigger<float>(2.718f);

    return 0;
}

