// Generate the first n Fibonacci numbers using an iterative approach
std::vector<int> generateFibonacci(int count) {
    std::vector<int> result;

    // Handle edge cases
    if (count <= 0) {
        return result;
    }

    // First Fibonacci number
    result.push_back(0);

    // Second Fibonacci number if needed
    if (count > 1) {
        result.push_back(1);
    }

    // Generate remaining Fibonacci numbers
    int index = 2;
    while (index < count) {
        int nextValue = result[index - 1] + result[index - 2];
        result.push_back(nextValue);
        index++;
    }

    return result;
}

int main() {
    int n = 10;
    std::vector<int> fibNumbers = generateFibonacci(n);

    for (int i = 0; i < fibNumbers.size(); i++) {
        std::cout << fibNumbers[i] << " ";
    }

    return 0;
}

