#include <iostream>
#include <vector>

using namespace std;

int main() {
    int rows, cols;
    cin >> rows >> cols;

    vector<vector<char>> grid(rows, vector<char>(cols));
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            cin >> grid[r][c];
        }
    }

    int isolatedCount = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 'O') {
                int neighbors = 0;

                // Check upper neighbor
                if (r > 0 && grid[r - 1][c] == 'O') {
                    neighbors++;
                }

                // Check lower neighbor
                if (r < rows - 1 && grid[r + 1][c] == 'O') {
                    neighbors++;
                }

                // Check left neighbor
                if (c > 0 && grid[r][c - 1] == 'O') {
                    neighbors++;
                }

                // Check right neighbor
                if (c < cols - 1 && grid[r][c + 1] == 'O') {
                    neighbors++;
                }

                // Count as isolated if at most one adjacent 'O'
                if (neighbors <= 1) {
                    isolatedCount++;
                }
            }
        }
    }

    cout << isolatedCount << endl;

    return 0;
}

