// Display metadata of each column in the result set
void showFieldDetails(const QSqlQuery &result) {
    QSqlRecord meta = result.record();
    for (int index = 0; index < meta.count(); ++index) {
        QString fieldName = meta.fieldName(index);
        QVariant::Type fieldType = meta.field(index).type();
        QTextStream(stdout) << "Field: " << fieldName 
                            << ", Data Type: " << QVariant::typeToName(fieldType) << "\n";
    }
}

// Establish database connection using provided credentials
bool initializeConnection(const QString &driverName, const QString &dbName, 
                          const QString &serverAddress, const QString &loginUser, 
                          const QString &loginPass) {
    QSqlDatabase conn = QSqlDatabase::addDatabase(driverName);
    conn.setHostName(serverAddress);
    conn.setDatabaseName(dbName);
    conn.setUserName(loginUser);
    conn.setPassword(loginPass);

    if (!conn.open()) {
        QTextStream(stderr) << "Connection error: " << conn.lastError().text() << "\n";
        return false;
    }
    return true;
}

int main(int argc, char *argv[]) {
    QCoreApplication app(argc, argv);

    // Configuration values for database access
    QString driver = "QPSQL";       // Use "QMYSQL" for MySQL, "QODBC" for SQL Server
    QString host = "localhost";
    QString name = "your_database_name";
    QString username = "your_username";
    QString passwd = "your_password";

    if (!initializeConnection(driver, name, host, username, passwd)) {
        return -1;
    }

    QSqlDatabase db = QSqlDatabase::database();
    QSqlQuery query(db);

    // Construct appropriate query based on the database type
    if (driver == "QPSQL") {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_name = :table LIMIT 0");
    } else if (driver == "QMYSQL") {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = :table LIMIT 0");
    } else if (driver == "QODBC") {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_catalog = ? AND table_name = ? LIMIT 0");
        query.addBindValue(name);
        query.addBindValue("your_table_name");
    }

    // Bind table name parameter
    query.bindValue(":table", "your_table_name");

    // Execute the query and handle errors
    if (!query.exec()) {
        QTextStream(stderr) << "SQL execution failed: " << query.lastError().text() << "\n";
        return -1;
    }

    // Output column metadata
    showFieldDetails(query);

    return app.exec();
}

