#include <cstdint>

void decompressByUnpacking0(uint8_t *out, uint8_t *in, uint32_t length) {
    static uint8_t decode_table[4096];
    static const uint8_t short_lookup[8] = { 0, 1, 2, 0, 3, 0, 0, 0 };

    if (decode_table[0] == 0) {    
        /* populate the decoding table */
        for (uint32_t idx = 0; idx < 4096; ++idx) {
            decode_table[idx] = (short_lookup[(idx >> 0) & 7] << 0) +
                                (short_lookup[(idx >> 3) & 7] << 2) +
                                (short_lookup[(idx >> 6) & 7] << 4) +
                                (short_lookup[(idx >> 9) & 7] << 6);
        }
    }

    uint8_t remaining_byte = 0;
    while (length >= 4) {
        length -= 4;
        uint8_t byte_val = *in++;
        out[0] = decode_table[byte_val] >> 9;
        out[1] = (decode_table[byte_val] >> 6) & 7;
        out[2] = (decode_table[byte_val] >> 3) & 7;
        out[3] = decode_table[byte_val] & 7;
        out += 4;
    }

    switch (length) {
        case 3:
            remaining_byte = *in;
            out[2] = short_lookup[remaining_byte >> 4];
            out[1] = short_lookup[(remaining_byte >> 2) & 3];
            [[fallthrough]];
        case 2:
            remaining_byte = *in;
            out[1] = short_lookup[(remaining_byte >> 2) & 3];
            out[0] = short_lookup[remaining_byte & 3];
            [[fallthrough]];
        case 1:
            out[0] = short_lookup[*in];
            break;
    }
}

int medianOfThree(vector<int> &arr, int l, int r) {
    int mid = l + (r - l) / 2;

    // Find the median by comparing all three values
    int a = arr[l], b = arr[mid], c = arr[r];
    int median;

    if ((a <= b && b <= c) || (c <= b && b <= a)) {
        median = b;
    } else if ((b <= a && a <= c) || (c <= a && a <= b)) {
        median = a;
    } else {
        median = c;
    }

    // Swap the median element to position r
    if (median == arr[mid]) {
        swap(arr[mid], arr[r]);
    } else if (median == arr[l]) {
        swap(arr[l], arr[r]);
    }

    return median;
}

