class Researcher {
public:
    Researcher(const std::string& firstName, const std::string& lastName)
        : firstName(firstName), lastName(lastName) {}

    // Mutators
    void setFirstName(const std::string& firstName) { this->firstName = firstName; }
    void setLastName(const std::string& lastName) { this->lastName = lastName; }
    void recordScore(double score) { scores.push_back(score); }
    void publish(const Publication& pub) { publications.push_back(pub); }

    // Accessors
    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    double calculateAverageScore() const {
        if (scores.empty()) return 0.0;
        double total = 0.0;
        for (double score : scores) {
            total += score;
        }
        return total / scores.size();
    }
    const std::vector<Publication>& getPublications() const { return publications; }

    // Helper functions
    void displayPublications() const {
        for (const Publication& pub : publications) {
            std::cout << "Title: " << pub.getName() << ", Venue: " << pub.getPublicationName()
                      << ", Year: " << pub.getReleaseYear() << ", Influence: " << pub.getInfluenceMetric() << std::endl;
        }
    }

private:
    std::string firstName;
    std::string lastName;
    std::vector<double> scores;
    std::vector<Publication> publications;
};

