enum class TokenType {
    NUMBER,
    OPERATOR,
    FUNCTION,
    LEFT_PAREN,
    RIGHT_PAREN,
    END
};

struct Token {
    TokenType type;
    std::string value;
};

std::vector<Token> parseExpression(const std::string& expr) {
    std::vector<Token> result;
    std::string currentNumber;

    for (size_t pos = 0; pos < expr.length(); ++pos) {
        char ch = expr[pos];

        // Handle numeric characters and decimal points
        if (std::isdigit(ch) || ch == '.') {
            currentNumber += ch;
        } else {
            // Save any accumulated number
            if (!currentNumber.empty()) {
                result.push_back({TokenType::NUMBER, currentNumber});
                currentNumber.clear();
            }

            // Handle function names (alphabetic sequences)
            if (std::isalpha(ch)) {
                std::string functionName;
                while (pos < expr.length() && std::isalpha(expr[pos])) {
                    functionName += expr[pos];
                    ++pos;
                }
                result.push_back({TokenType::FUNCTION, functionName});
                --pos; // Back up one position since the outer loop will increment
            } 
            // Handle parentheses
            else if (ch == '(') {
                result.push_back({TokenType::LEFT_PAREN, "("});
            } else if (ch == ')') {
                result.push_back({TokenType::RIGHT_PAREN, ")"});
            } 
            // Handle operators
            else if (ch == '+' || ch == '-' || ch == '*' || ch == '/' || ch == '^') {
                result.push_back({TokenType::OPERATOR, std::string(1, ch)});
            } 
            // Skip whitespace, but throw error for other invalid characters
            else if (!std::isspace(ch)) {
                throw std::runtime_error("Unexpected character encountered: " + std::string(1, ch));
            }
        }
    }

    // Add any remaining number at the end of expression
    if (!currentNumber.empty()) {
        result.push_back({TokenType::NUMBER, currentNumber});
    }

    // Mark end of token stream
    result.push_back({TokenType::END, ""});
    return result;
}

