// Generate the first n Fibonacci numbers
std::vector<int> generateFibonacci(int count) {
    std::vector<int> result;

    if (count <= 0) {
        return result;
    }

    // Handle special cases for small counts
    if (count == 1) {
        result.push_back(0);
        return result;
    }

    // Initialize with first two Fibonacci numbers
    result.push_back(0);
    result.push_back(1);

    // If only two requested, return early
    if (count == 2) {
        return result;
    }

    // Generate remaining Fibonacci numbers
    for (int index = 2; index < count; ++index) {
        int nextNumber = result[index - 1] + result[index - 2];
        result.push_back(nextNumber);
    }

    return result;
}

int main() {
    int n = 10;
    std::vector<int> fibNumbers = generateFibonacci(n);

    // Print all Fibonacci numbers in the sequence
    for (int value : fibNumbers) {
        std::cout << value << " ";
    }

    return 0;
}

#include <iostream>
#include <chrono>
#include <vector>

// Generate a sequence of integers from start to end-1
template <typename T>
std::vector<T> generate_sequence(T begin, T finish) {
    std::vector<T> result;
    // Calculate the number of elements needed
    auto count = static_cast<size_t>(finish - begin);
    result.reserve(count);  // Optimize memory allocation

    // Fill the vector using a while loop instead of for
    T current = begin;
    size_t index = 0;
    while (index < count) {
        result.push_back(current);
        ++current;
        ++index;
    }

    return result;
}

int main() {
    // Record start time with high-resolution clock
    auto begin_time = std::chrono::high_resolution_clock::now();

    // Generate numbers from 0 to 1023
    std::vector<int> numbers = generate_sequence(0, 1024);

    // Record end time and calculate duration
    auto finish_time = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> duration = finish_time - begin_time;

    std::cout << "elapsed time: " << duration.count() << "s\n";
}

