#include "imgui.h"
#include "imgui_impl_sdl3.h"
#include "imgui_impl_sdlrenderer3.h"
#include <stdio.h>
#include <SDL3/SDL.h>
#if defined(IMGUI_IMPL_OPENGL_ES2)
#include <SDL3/SDL_opengles2.h>
#else
#include <SDL3/SDL_opengl.h>
#endif

// Main application entry point
int main(int, char**)
{
    // Initialize SDL subsystems
    if (!SDL_Init(SDL_INIT_VIDEO | SDL_INIT_GAMEPAD))
    {
        fprintf(stderr, "Failed to initialize SDL: %s\n", SDL_GetError());
        return -1;
    }

    // Create the main application window
    Uint32 window_flags = SDL_WINDOW_OPENGL | SDL_WINDOW_RESIZABLE | SDL_WINDOW_HIDDEN;
    SDL_Window* app_window = SDL_CreateWindow("Dear ImGui SDL3 + SDL_Renderer Demo", 1280, 720, window_flags);
    if (app_window == nullptr)
    {
        fprintf(stderr, "Failed to create window: %s\n", SDL_GetError());
        SDL_Quit();
        return -1;
    }

    // Setup rendering context
    SDL_Renderer* graphics_renderer = SDL_CreateRenderer(app_window, nullptr);
    if (graphics_renderer == nullptr)
    {
        fprintf(stderr, "Failed to create renderer: %s\n", SDL_GetError());
        SDL_DestroyWindow(app_window);
        SDL_Quit();
        return -1;
    }

    SDL_SetRenderVSync(graphics_renderer, 1);
    SDL_SetWindowPosition(app_window, SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED);
    SDL_ShowWindow(app_window);

    // Initialize Dear ImGui
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& imgui_io = ImGui::GetIO(); (void)imgui_io;

    // Enable input controls
    imgui_io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard;
    imgui_io.ConfigFlags |= ImGuiConfigFlags_NavEnableGamepad;

    // Apply dark color scheme
    ImGui::StyleColorsDark();

    // Initialize backend components
    ImGui_ImplSDL3_InitForSDLRenderer(app_window, graphics_renderer);
    ImGui_ImplSDLRenderer3_Init(graphics_renderer);

    // Font configuration (commented out as in original)
    // io.Fonts->AddFontDefault();
    // ... other font loading examples ...

    // Application state variables
    bool is_demo_visible = true;
    bool is_secondary_window_visible = false;
    ImVec4 background_color = ImVec4(0.45f, 0.55f, 0.60f, 1.00f);

    // Main execution loop
    bool should_exit = false;
#ifdef __EMSCRIPTEN__
    imgui_io.IniFilename = nullptr;
    EMSCRIPTEN_MAINLOOP_BEGIN
#else
    while (!should_exit)
#endif
    {
        // Event handling
        SDL_Event pending_event;
        while (SDL_PollEvent(&pending_event))
        {
            ImGui_ImplSDL3_ProcessEvent(&pending_event);

            if (pending_event.type == SDL_EVENT_QUIT)
                should_exit = true;

            if (pending_event.type == SDL_EVENT_WINDOW_CLOSE_REQUESTED &&
                pending_event.window.windowID == SDL_GetWindowID(app_window))
                should_exit = true;
        }

        // Skip rendering when minimized to save resources
        if (SDL_GetWindowFlags(app_window) & SDL_WINDOW_MINIMIZED)
        {
            SDL_Delay(10);
            continue;
        }

        // Prepare new frame
        ImGui_ImplSDLRenderer3_NewFrame();
        ImGui_ImplSDL3_NewFrame();
        ImGui::NewFrame();

        // Demo window implementation
        if (is_demo_visible)
            ImGui::ShowDemoWindow(&is_demo_visible);

        // Primary custom window
        {
            static float animation_value = 0.0f;
            static int interaction_counter = 0;

            ImGui::Begin("Hello, world!");
            ImGui::Text("This is some useful text.");
            ImGui::Checkbox("Show Demo Window", &is_demo_visible);
            ImGui::Checkbox("Show Secondary Window", &is_secondary_window_visible);
            ImGui::SliderFloat("Animation Control", &animation_value, 0.0f, 1.0f);
            ImGui::ColorEdit3("Background Color", (float*)&background_color);

            if (ImGui::Button("Increment Counter"))
                interaction_counter++;

            ImGui::SameLine();
            ImGui::Text("Counter Value: %d", interaction_counter);
            ImGui::Text("Performance: %.3f ms/frame (%.1f FPS)", 
                       1000.0f / imgui_io.Framerate, imgui_io.Framerate);
            ImGui::End();
        }

        // Secondary optional window
        if (is_secondary_window_visible)
        {
            ImGui::Begin("Additional Panel", &is_secondary_window_visible);
            ImGui::Text("Greetings from the secondary window!");

            if (ImGui::Button("Dismiss This Window"))
                is_secondary_window_visible = false;

            ImGui::End();
        }

        // Render frame
        ImGui::Render();

        SDL_SetRenderDrawColorFloat(graphics_renderer, 
                                   background_color.x, background_color.y, 
                                   background_color.z, background_color.w);
        SDL_RenderClear(graphics_renderer);
        ImGui_ImplSDLRenderer3_RenderDrawData(ImGui::GetDrawData(), graphics_renderer);
        SDL_RenderPresent(graphics_renderer);
    }

#ifdef __EMSCRIPTEN__
    EMSCRIPTEN_MAINLOOP_END;
#endif

    // Cleanup resources
    ImGui_ImplSDLRenderer3_Shutdown();
    ImGui_ImplSDL3_Shutdown();
    ImGui::DestroyContext();
    SDL_DestroyRenderer(graphics_renderer);
    SDL_DestroyWindow(app_window);
    SDL_Quit();

    return 0;
}

