// Test 4: Collective Matching Logic
int test_collective_matching() {
    const char* match_config =
        "allreduce,0,65536,tree,simple,8,1,-1,-1,-1\n"
        "broadcast,0,32768,ring,ll128,4,-1,-1,-1,-1\n";

    generate_test_file("match_test.conf", match_config);
    setenv("NCCL_TUNER_CONFIG_FILE", "match_test.conf", 1);

    void* ctx = nullptr;
    pluginInit(8, 1, mock_logger, &ctx);

    float costs[NCCL_NUM_ALGORITHMS][NCCL_NUM_PROTOCOLS];
    float* cost_ptrs[NCCL_NUM_ALGORITHMS];
    for (int i = 0; i < NCCL_NUM_ALGORITHMS; ++i) {
        cost_ptrs[i] = costs[i];
        for (int j = 0; j < NCCL_NUM_PROTOCOLS; ++j) {
            costs[i][j] = 1.0f;
        }
    }

    int channels = 0;
    ncclResult_t res = pluginGetCollInfo(ctx, ncclFuncAllReduce, 32768, 1,
                                         cost_ptrs, NCCL_NUM_ALGORITHMS, NCCL_NUM_PROTOCOLS,
                                         0, &channels);
    VERIFY_CHECK(res == ncclSuccess, "GetCollInfo should work");
    VERIFY_CHECK(costs[NCCL_ALGO_TREE][NCCL_PROTO_SIMPLE] == 0.0f, "Tree/Simple should be 0");
    VERIFY_CHECK(channels == 8, "Channels should be 8");

    pluginDestroy(ctx);
    unlink("match_test.conf");
    unsetenv("NCCL_TUNER_CONFIG_FILE");
    TEST_SUCCESS();
}

