    void* ctx = nullptr;
    ncclResult_t res = pluginInit(8, 2, mock_logger, &ctx);
    VERIFY_CHECK(res == ncclSuccess, "Empty config init");

    pluginDestroy(ctx);
    unlink(empty_file);
    unsetenv("NCCL_TUNER_CONFIG_FILE");
    TEST_SUCCESS();
}

// Test Registry
typedef struct {
    const char* name;
    int (*func)();
    const char* desc;
} TestCase;

TestCase tests[] = {
    {"init", test_plugin_init, "Plugin init"},
    {"valid-config", test_config_parsing_valid, "Valid config parsing"},
    {"invalid-config", test_config_parsing_invalid, "Invalid config handling"},
    {"collective", test_collective_matching, "Collective matching"},
    {"size-match", test_size_matching, "Size range matching"},
    {"topology", test_topology_matching, "Topology matching"},
    {"default-channels", test_default_channels, "Default channels"},
    {"regbuff", test_regbuff_matching, "Registered buffer matching"},
    {"pipeops", test_pipeops_matching, "Pipeline ops matching"},
    {"fallback", test_no_match_fallback, "Fallback behavior"},
    {"large-config", test_large_config, "Large config files"},
    {"stress-config", test_very_large_config_stress, "Stress test"},
    {"empty-config", test_empty_config, "Empty config handling"},
    {nullptr, nullptr, nullptr}
};

void print_help(const char* prog) {
    std::cout << "Usage: " << prog << " [test_name ...]\n\n";
    std::cout << "Available tests:\n";
    for (int i = 0; tests[i].name != nullptr; ++i) {
        std::cout << "  " << tests[i].name << " - " << tests[i].desc << "\n";
    }
}

int find_and_run(const char* name) {
    for (int i = 0; tests[i].name != nullptr; ++i) {
        if (strcmp(tests[i].name, name) == 0) {
            return tests[i].func();
        }
    }
    return 0;
}

int main(int argc, char* argv[]) {
    int passed = 0, total = 0;

    if (argc > 1 && (strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0)) {
        print_help(argv[0]);
        return 0;
    }

    std::cout << "Running NCCL Tuner Plugin Unit Tests\n";
    std::cout << "=====================================\n";

    if (argc == 1) {
        for (int i = 0; tests[i].name != nullptr; ++i) {
            total++;
            passed += tests[i].func();
        }
    } else {
        for (int arg = 1; arg < argc; ++arg) {
            int result = find_and_run(argv[arg]);
            if (result) {
                total++;
                passed += result;
            } else {
                std::cout << "ERROR: Unknown test '" << argv[arg] << "'\n";
                return 1;
            }
        }
    }

    std::cout << "\n=====================================\n";
    std::cout << "Test Results: " << passed << "/" << total << " tests passed\n";
    if (passed == total) {
        std::cout << "All tests PASSED!\n";
        return 0;
    } else {
        std::cout << "Some tests FAILED!\n";
        return 1;
    }
}

