void EnderDragonRenderer::setupRotations(
    std::shared_ptr<Mob> _mob,
    float                bob,
    float                bodyRot,
    float                interp
) {
    std::shared_ptr<EnderDragon> mob =
        std::dynamic_pointer_cast<EnderDragon>(_mob);

    double      latencyPos[3];
    doubleArray posData = doubleArray(latencyPos, 3);
    mob->getLatencyPos(posData, 7, interp);
    float yawRot = latencyPos[0];

    float tiltAngle = mob->getTilt(interp);
    glRotatef(-yawRot, 0, 1, 0);
    glRotatef(tiltAngle, 1, 0, 0);
    glTranslatef(0, 0, 1);

    if (mob->deathTime > 0) {
        float progress = (mob->deathTime + interp - 1) / 20.0f * 1.6f;
        float fallFactor = sqrt(progress);
        if (fallFactor > 1.0f) fallFactor = 1.0f;
        glRotatef(fallFactor * getFlipDegrees(mob), 0, 0, 1);
    }
}

void EnderDragonRenderer::renderModel(
    std::shared_ptr<Entity> _mob,
    float                   walkAnim,
    float                   walkSpeed,
    float                   bobbing,
    float                   headYawDiff,
    float                   headPitch,
    float                   scaleFactor
) {
    std::shared_ptr<EnderDragon> mob =
        std::dynamic_pointer_cast<EnderDragon>(_mob);

    if (mob->dragonDeathTime > 0) {
        float deathProgress = (mob->dragonDeathTime / 200.0f);
        glDepthFunc(GL_LEQUAL);
        glEnable(GL_ALPHA_TEST);
        glAlphaFunc(GL_GREATER, deathProgress);
        bindTexture(
            mob->customTextureUrl,
            TN_MOB_ENDERDRAGON_SHUFFLE
        );
        model->render(
            mob,
            walkAnim,
            walkSpeed,
            bobbing,
            headYawDiff,
            headPitch,
            scaleFactor,
            true
        );
        glAlphaFunc(GL_GREATER, 0.1f);
        glDepthFunc(GL_EQUAL);
    }

    bindTexture(mob->customTextureUrl, mob->getTexture());
    model->render(mob, walkAnim, walkSpeed, bobbing, headYawDiff, headPitch, scaleFactor, true);

    if (mob->hurtTime > 0) {
        glDepthFunc(GL_EQUAL);
        glDisable(GL_TEXTURE_2D);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
        glColor4f(1, 0, 0, 0.5f);

#ifdef __PSVITA__
        model->render(
            mob,
            walkAnim,
            walkSpeed,
            bobbing,
            headYawDiff,
            headPitch,
            scaleFactor,
            true
        );
#else
        model->render(
            mob,
            walkAnim,
            walkSpeed,
            bobbing,
            headYawDiff,
            headPitch,
            scaleFactor,
            false
        );
#endif

        glEnable(GL_TEXTURE_2D);
        glDisable(GL_BLEND);
        glDepthFunc(GL_LEQUAL);
    }
}

void EnderDragonRenderer::render(
    std::shared_ptr<Entity> _mob,
    double                  posX,
    double                  posY,
    double                  posZ,
    float                   rotY,
    float                   interp
) {
    std::shared_ptr<EnderDragon> mob =
        std::dynamic_pointer_cast<EnderDragon>(_mob);
    EnderDragonRenderer::bossInstance = mob;

    if (currentModel != DragonModel::MODEL_ID) {
        model        = new DragonModel(0);
        currentModel = DragonModel::MODEL_ID;
    }

    MobRenderer::render(mob, posX, posY, posZ, rotY, interp);

    if (mob->nearestCrystal != NULL) {
        float timeVal = mob->nearestCrystal->time + interp;
        float heightFactor = sin(timeVal * 0.2f) / 2 + 0.5f;
        heightFactor = (heightFactor * heightFactor + heightFactor) * 0.2f;

        float dx = static_cast<float>(mob->nearestCrystal->x - mob->x
                           - (mob->xo - mob->x) * (1 - interp));
        float dy = static_cast<float>(heightFactor + mob->nearestCrystal->y - 1 - mob->y
                           - (mob->yo - mob->y) * (1 - interp));
        float dz = static_cast<float>(mob->nearestCrystal->z - mob->z
                           - (mob->zo - mob->z) * (1 - interp));

        float horizDist = sqrt(dx * dx + dz * dz);
        float fullDist  = sqrt(dx * dx + dy * dy + dz * dz);

        glColor4f(1, 1, 1, 1);
        glPushMatrix();
        glTranslatef(static_cast<float>(posX), static_cast<float>(posY) + 2, static_cast<float>(posZ));
        glRotatef(static_cast<float>(-atan2(dz, dx)) * 180.0f / M_PI - 90.0f, 0, 1, 0);
        glRotatef(static_cast<float>(-atan2(horizDist, dy)) * 180.0f / M_PI - 90.0f, 1, 0, 0);

        static float beamRotation = 0.0f;
        glRotatef(beamRotation, 0, 0, 1);
        beamRotation += 0.5f;
        if (beamRotation >= 360.0f) {
            beamRotation = 0.0f;
        }

        Tesselator* t = Tesselator::getInstance();
        Lighting::turnOff();
        glDisable(GL_CULL_FACE);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_DST_ALPHA);
        bindTexture(TN_MOB_ENDERDRAGON_BEAM);
        glShadeModel(GL_SMOOTH);

        float texV0 = 0.0f - (mob->tickCount + interp) * 0.005f;
        float texV1 = fullDist / 32.0f - (mob->tickCount + interp) * 0.005f;

        t->begin(GL_TRIANGLE_STRIP);
        int segments = 8;
        for (int idx = 0; idx <= segments; idx++) {
            double angle = (idx % segments) * M_PI * 2 / segments;
            float s = sin(idx % segments * M_PI * 2 / segments) * 0.75f;
            float c = cos(idx % segments * M_PI * 2 / segments) * 0.75f;
            float u = (idx % segments) * 1.0f / segments;

            t->vertexUV(s * 0.2f, c * 0.2f, 0, u, texV1);
            t->vertexUV(s, c, fullDist, u, texV0);
        }
        t->end();

        glEnable(GL_CULL_FACE);
        glShadeModel(GL_FLAT);
        glDisable(GL_BLEND);
        glPopMatrix();
        Lighting::turnOn();
    }
}

void EnderDragonRenderer::additionalRendering(
    std::shared_ptr<Mob> _mob,
    float                interp
) {
    std::shared_ptr<EnderDragon> mob =
        std::dynamic_pointer_cast<EnderDragon>(_mob);
    MobRenderer::additionalRendering(mob, interp);

    Tesselator* t = Tesselator::getInstance();
    if (mob->dragonDeathTime > 0) {
        Lighting::turnOff();
        float deathProgress = ((mob->dragonDeathTime + interp) / 200.0f);
        float overDrive = 0;
        if (deathProgress > 0.8f) {
            overDrive = (deathProgress - 0.8f) / 0.2f;
        }

        Random randomGen(432);
        glDisable(GL_TEXTURE_2D);
        glShadeModel(GL_SMOOTH);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_ONE);
        glDisable(GL_ALPHA_TEST);
        glEnable(GL_CULL_FACE);
        glDepthMask(false);

        glPushMatrix();
        glTranslatef(0, -1, -2);

        int particleCount = static_cast<int>((deathProgress + deathProgress * deathProgress) / 2 * 60);
        for (int i = 0; i < particleCount; i++) {
            glRotatef(randomGen.nextFloat() * 360, 1, 0, 0);
            glRotatef(randomGen.nextFloat() * 360, 0, 1, 0);
            glRotatef(randomGen.nextFloat() * 360, 0, 0, 1);
            glRotatef(randomGen.nextFloat() * 360, 1, 0, 0);
            glRotatef(randomGen.nextFloat() * 360, 0, 1, 0);
            glRotatef(randomGen.nextFloat() * 360 + deathProgress * 90, 0, 0, 1);

            t->begin(GL_TRIANGLE_FAN);
            float dist = randomGen.nextFloat() * 20 + 5 + overDrive * 10;
            float width = randomGen.nextFloat() * 2 + 1 + overDrive * 2;

            t->color(0xffffff, static_cast<int>(255 * (1 - overDrive)));
            t->vertex(0, 0, 0);
            t->color(0xff00ff, 0);
            t->vertex(-0.866 * width, dist, -0.5f * width);
            t->vertex(+0.866 * width, dist, -0.5f * width);
            t->vertex(0, dist, 1 * width);
            t->vertex(-0.866 * width, dist, -0.5f * width);
            t->end();
        }

        glPopMatrix();
        glDepthMask(true);
        glDisable(GL_CULL_FACE);
        glDisable(GL_BLEND);
        glShadeModel(GL_FLAT);
        glColor4f(1, 1, 1, 1);
        glEnable(GL_TEXTURE_2D);
        glEnable(GL_ALPHA_TEST);
        Lighting::turnOn();
    }
}

int EnderDragonRenderer::prepareArmor(
    std::shared_ptr<Mob> _mob,
    int                  layer,
    float                interp
) {
    std::shared_ptr<EnderDragon> mob =
        std::dynamic_pointer_cast<EnderDragon>(_mob);

    if (layer == 1) {
        glDepthFunc(GL_LEQUAL);
    }

    if (layer != 0) return -1;

    bindTexture(TN_MOB_ENDERDRAGON_ENDEREYES);
    float brightness = 1;
    glEnable(GL_BLEND);

#ifdef _XBOX
    glDisable(GL_ALPHA_TEST);
#endif

    glBlendFunc(GL_ONE, GL_ONE);
    glDisable(GL_LIGHTING);
    glDepthFunc(GL_EQUAL);

    if (SharedConstants::TEXTURE_LIGHTING) {
        int col = 0xf0f0;
        int u   = col % 65536;
        int v   = col / 65536;
        glMultiTexCoord2f(GL_TEXTURE1, u / 1.0f, v / 1.0f);
        glColor4f(1, 1, 1, 1);
    }

    glEnable(GL_LIGHTING);
    glColor4f(1, 1, 1, brightness);
    return 1;
}

