#include <cstdint>
#include <cstdio>
#include "ckernel.h"
#include "llk_defs.h"

// Renamed global variables for clarity/obfuscation
std::uint32_t unpack_config_ctx          = 0;
std::uint32_t pack_sync_tile_dst_addr    = 0;
std::uint32_t math_sync_tile_dst_pos     = 0;

#ifdef LLK_TRISC_UNPACK
#include "experimental/llk_unpack_AB_sub_bcast_col_custom.h"
#include "llk_unpack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Configure unpacker hardware with derived face count
    std::uint32_t face_count = 4;
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        fmts.unpack_A_src, fmts.unpack_B_src, fmts.unpack_A_dst, fmts.unpack_B_dst,
        FACE_R_DIM, FACE_R_DIM, face_count, face_count);

    // Initialize custom broadcast column unpacking
    _llk_unpack_AB_sub_bcast_col_init_custom_<BROADCAST_TYPE>();

    // Execute custom broadcast column unpack operation
    _llk_unpack_AB_sub_bcast_col_custom_<BROADCAST_TYPE>(
        L1_ADDRESS(params->buffer_A[0]), 
        L1_ADDRESS(params->buffer_B[0]), 
        CT_DIM);
}
#endif

#ifdef LLK_TRISC_MATH
#include "experimental/llk_math_eltwise_binary_custom.h"
#include "llk_math_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Initialize synchronization and configuration for math operations
    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(fmts.math, fmts.math);

    // Setup element-wise binary operation with fidelity settings
    _llk_math_eltwise_binary_init_custom_<ELTWISE_BINARY_OP, BROADCAST_TYPE, MATH_FIDELITY>(4, 0);

    // Wait until destination buffer is ready
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Perform custom binary op with reuse
    _llk_math_eltwise_binary_bcast_reuse_custom_(CT_DIM);

    // Signal completion of destination section
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Determine tile size constant
    const std::uint32_t tile_size_bytes = 16 * 16 * 4;

#ifdef ARCH_BLACKHOLE
    // Blackhole-specific pack config
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(fmts.pack_src, fmts.pack_dst, tile_size_bytes);
#else
    // Generic pack config
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(fmts.pack_src, fmts.pack_dst, tile_size_bytes);
#endif

    // Initialize packer state
    _llk_pack_init_<false, false>(fmts.pack_dst);

#ifdef ARCH_BLACKHOLE
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_dest_init_<DstSync::SyncHalf, false, false>();
#endif

    // Ensure math has completed before packing
    _llk_packer_wait_for_math_done_();

    // Pack each tile sequentially using index-based loop
    int tile_idx = 0;
    while (tile_idx < params->TILE_CNT) {
        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
            tile_idx, 
            L1_ADDRESS(params->buffer_Res[tile_idx])
        );
        ++tile_idx;
    }

    // Finalize destination section
    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

