// ----- Background Task Handler -----
class TaskProcessor : public BHandler {
public:
    TaskProcessor(const char* label) : BHandler(label) {}

    virtual void MessageReceived(BMessage* msg) override {
        switch (msg->what) {
            case MSG_INITIATE_TASK: {
                int32 taskId;
                BMessenger responder;
                if (msg->FindInt32("taskId", &taskId) == B_OK &&
                    msg->FindMessenger("callback", &responder) == B_OK) {

                    // Send initial progress update
                    BMessage progress(MSG_TASK_PROGRESS);
                    progress.AddInt32("taskId", taskId);
                    progress.AddInt32("progress", 50); // Midway status
                    responder.SendMessage(&progress);

                    // Simulate work with delay
                    snooze(3000000); // 3 seconds

                    // Send completion notification
                    BMessage done(MSG_TASK_COMPLETE);
                    done.AddInt32("taskId", taskId);
                    done.AddInt32("result", 1); // Success indicator
                    responder.SendMessage(&done);
                }
                break;
            }
            default:
                BHandler::MessageReceived(msg);
        }
    }
};

// ----- Background Processing Thread -----
class BackgroundThread : public BLooper {
public:
    BackgroundThread() : BLooper("BackgroundThread") {
        fProcessor = new TaskProcessor("TaskProcessor");
        AddHandler(fProcessor);
    }

    BHandler* GetHandler() { return fProcessor; }

private:
    TaskProcessor* fProcessor;
};

// ----- Main Application Window -----
class MainWindow : public BWindow {
public:
    MainWindow(BRect frame)
        : BWindow(frame, "BLooper & BHandler GUI Example",
                  B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE)
    {
        // Create main view
        BView* mainView = new BView(Bounds(), "mainView",
                                    B_FOLLOW_ALL, B_WILL_DRAW);
        mainView->SetViewColor(ui_color(B_PANEL_BACKGROUND_COLOR));
        AddChild(mainView);

        // Log display area
        fLogDisplay = new BStringView(BRect(10, 60, Bounds().Width()-10, Bounds().Height()-10),
                                      "logDisplay", "", B_FOLLOW_ALL_SIDES);
        mainView->AddChild(fLogDisplay);

        // Start button
        fStartButton = new BButton(BRect(10, 10, 150, 35), "startBtn", "Begin",
                                   new BMessage(MSG_INITIATE_TASK));
        mainView->AddChild(fStartButton);

        // Initialize background worker
        fWorkerThread = new BackgroundThread();
        fWorkerThread->Run();

        // Reset task counters
        fTotalTasks = 3;
        fFinishedTasks = 0;
    }

    virtual void MessageReceived(BMessage* msg) override {
        switch (msg->what) {
            case MSG_INITIATE_TASK:
                LaunchTasks();
                break;
            case MSG_TASK_PROGRESS: {
                int32 taskId, progress;
                if (msg->FindInt32("taskId", &taskId) == B_OK &&
                    msg->FindInt32("progress", &progress) == B_OK) {
                    BString entry;
                    entry << "[Worker] Task " << taskId << " is in progress...";
                    UpdateLog(entry);
                }
                break;
            }
            case MSG_TASK_COMPLETE: {
                int32 taskId, result;
                if (msg->FindInt32("taskId", &taskId) == B_OK &&
                    msg->FindInt32("result", &result) == B_OK) {
                    BString entry;
                    entry << "[Worker] Task " << taskId << " completed.";
                    UpdateLog(entry);
                    fFinishedTasks++;

                    if (fFinishedTasks == fTotalTasks) {
                        UpdateLog("[Main] All tasks finished successfully!");
                    }
                }
                break;
            }
            default:
                BWindow::MessageReceived(msg);
        }
    }

private:
    void LaunchTasks() {
        fFinishedTasks = 0;
        UpdateLog("[Main] -----------------");
        UpdateLog("[Main] Initiating tasks...");

        for (int i = 1; i <= fTotalTasks; i++) {
            BMessage request(MSG_INITIATE_TASK);
            request.AddInt32("taskId", i);
            request.AddMessenger("callback", BMessenger(this));

            BMessenger(fWorkerThread->GetHandler()).SendMessage(&request);

            BString entry;
            entry << "[Main] Dispatched task " << i << " to background...";
            UpdateLog(entry);
        }
    }

    void UpdateLog(const BString& line) {
        fLogBuffer << line << "\n";
        fLogDisplay->SetText(fLogBuffer.String());
    }

private:
    BackgroundThread* fWorkerThread;
    BStringView* fLogDisplay;
    BButton* fStartButton;
    BString fLogBuffer;
    int fTotalTasks;
    int fFinishedTasks;
};

// ----- Application Entry Point -----
class BackgroundApp : public BApplication {
public:
    BackgroundApp() : BApplication("application/x-vnd.Haiku.BackgroundApp") {}

    virtual void ReadyToRun() override {
        BWindow* window = new MainWindow(BRect(100, 100, 500, 300));
        window->Show();
    }
};

int main() {
    BackgroundApp app;
    app.Run();
    return 0;
}

