// Type conversion setup for Triton to TritonGPU lowering
TritonGPUTypeConverter::TritonGPUTypeConverter(MLIRContext *ctx,
                                               int warpCount,
                                               int threadsPerWarp,
                                               int ctaCount)
    : context(ctx), numWarps(warpCount), threadsPerWarp(threadsPerWarp),
      numCTAs(ctaCount) {

  // Identity conversion for non-tensor types
  addConversion([](Type t) { return t; });

  // Tensor type conversion with layout assignment
  addConversion([this](RankedTensorType tensorTy) -> RankedTensorType {
    if (tensorTy.getEncoding())
      return tensorTy; // Already has encoding

    auto shape = tensorTy.getShape();
    auto enc = getDefaultBlockedEncoding(
        this->context, shape, this->numWarps, this->threadsPerWarp, this->numCTAs);
    return RankedTensorType::get(shape, tensorTy.getElementType(), enc);
  });

  // Pointer type conversion: propagate layout to pointee tensor
  addConversion([this](triton::PointerType ptrTy) -> triton::PointerType {
    auto elemTy = ptrTy.getPointeeType();
    auto tensorTy = dyn_cast<RankedTensorType>(elemTy);
    if (!tensorTy)
      return ptrTy;

    auto newElemTy = convertType(tensorTy);
    return triton::PointerType::get(newElemTy, ptrTy.getAddressSpace());
  });

  //
  // Materialization handlers
  //

  // Argument materialization — not expected in this pass
  addArgumentMaterialization([&](OpBuilder &builder,
                                 RankedTensorType ty,
                                 ValueRange inputs,
                                 Location loc) -> Value {
    llvm_unreachable("Argument rematerialization should not occur during Triton→TritonGPU lowering");
    return Value{};
  });

  // Source materialization — also not expected
  addSourceMaterialization([&](OpBuilder &builder,
                               RankedTensorType ty,
                               ValueRange inputs,
                               Location loc) -> Value {
    llvm_unreachable("Source rematerialization should not occur during Triton→TritonGPU lowering");
    return Value{};
  });

  // Target materialization: insert ConvertLayoutOp where needed
  addTargetMaterialization([&](OpBuilder &builder,
                               RankedTensorType desiredTy,
                               ValueRange operands,
                               Location loc) {
    auto convOp = builder.create<triton::gpu::ConvertLayoutOp>(
        loc, desiredTy, operands.front());
    return convOp.getResult();
  });
}

// Conversion target definition for TritonGPU pass
TritonGPUConversionTarget::TritonGPUConversionTarget(
    MLIRContext &ctx, TritonGPUTypeConverter &converter)
    : ConversionTarget(ctx) {

  // Legal dialects
  addLegalDialect<triton::gpu::TritonGPUDialect>();

  // Explicitly illegal SCF ops
  addIllegalOp<scf::ExecuteRegionOp, scf::ParallelOp, scf::ReduceOp,
               scf::ReduceReturnOp>();

  // Dynamically legal dialects (check region legality via type converter)
  addDynamicallyLegalDialect<arith::ArithDialect, math::MathDialect,
                             triton::TritonDialect, cf::ControlFlowDialect,
                             scf::SCFDialect>([&](Operation *op) {
    bool allRegionsLegal = true;
    for (auto &region : op->getRegions()) {
      allRegionsLegal &= converter.isLegal(&region);
    }
    return allRegionsLegal && converter.isLegal(op);
  });

  // Special handling for DotOp layout requirements
  addDynamicallyLegalOp<triton::DotOp>([](triton::DotOp dot) -> bool {
    auto A = cast<RankedTensorType>(dot.getA().getType());
    auto B = cast<RankedTensorType>(dot.getB().getType());

    auto AEnc = A.getEncoding();
    auto BEnc = B.getEncoding();

    bool validA = AEnc && isa<triton::gpu::DotOperandEncodingAttr>(AEnc);
    bool validB = BEnc && isa<triton::gpu::DotOperandEncodingAttr>(BEnc);

    return validA && validB;
  });
}

