#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;

    const int ROWS_TOP = 50;
    const int COLS = 100;
    const int TOTAL_ROWS = 2 * ROWS_TOP + 1;

    vector<string> canvas(TOTAL_ROWS, string(COLS, '.'));

    // Choose separator character based on cost comparison
    char divider = (x <= y) ? '@' : '.';

    // Fill top region with white cells ('.')
    for (int r = 0; r < ROWS_TOP; ++r) {
        fill(canvas[r].begin(), canvas[r].end(), '.');
    }

    // Set separator row
    fill(canvas[ROWS_TOP].begin(), canvas[ROWS_TOP].end(), divider);

    // Fill bottom region with black cells ('@')
    for (int r = ROWS_TOP + 1; r < TOTAL_ROWS; ++r) {
        fill(canvas[r].begin(), canvas[r].end(), '@');
    }

    // Add black islands in the upper white section
    int blackIslandsNeeded = b - 1;
    for (int r = 0; r < ROWS_TOP && blackIslandsNeeded > 0; ++r) {
        // Skip last row of top section if separator is also '@'
        if (divider == '@' && r == ROWS_TOP - 1) continue;

        if (r % 2 == 1) {
            for (int c = 1; c < COLS && blackIslandsNeeded > 0; c += 2) {
                canvas[r][c] = '@';
                --blackIslandsNeeded;
            }
        }
    }

    // Add white islands in the lower black section
    int whiteIslandsNeeded = w - 1;
    for (int r = ROWS_TOP + 1; r < TOTAL_ROWS && whiteIslandsNeeded > 0; ++r) {
        // Skip first row of bottom section if separator is also '.'
        if (divider == '.' && r == ROWS_TOP + 1) continue;

        if (r % 2 == 1) {
            for (int c = 1; c < COLS && whiteIslandsNeeded > 0; c += 2) {
                canvas[r][c] = '.';
                --whiteIslandsNeeded;
            }
        }
    }

    cout << TOTAL_ROWS << " " << COLS << "\n";
    for (const auto& row : canvas) {
        cout << row << "\n";
    }

    return 0;
}

