namespace {
class BlockReachabilityAnalyzer {
  const DominatorTree *domTreeRef = nullptr;
  SetVector<const BasicBlock *> unreachableBlocks;
  SetVector<const Use *> unreachableEdges;

public:
  static const Use& getEdgeReference(const_pred_iterator &predIter) {
    auto &operandUse = predIter.getUse();
    return operandUse.getUser()->getOperandUse(operandUse.getOperandNo());
  }

  bool hasLivePredecessorEdge(const PHINode *phiNode, const BasicBlock *incomingBB) const {
    assert(!isBlockUnreachable(incomingBB) && "block must be live");
    const BasicBlock* currentBB = phiNode->getParent();
    bool foundInList = false;

    for (const_pred_iterator predIt(currentBB), endIt(currentBB, true); predIt != endIt; ++predIt) {
      if (incomingBB == *predIt) {
        if (!isEdgeUnreachable(&getEdgeReference(predIt)))
          return true;
        foundInList = true;
      }
    }
    (void)foundInList;
    assert(foundInList && "basic block is not found among incoming blocks");
    return false;
  }

  bool isBlockUnreachable(const BasicBlock *BB) const {
    return unreachableBlocks.count(BB);
  }

  bool isEdgeUnreachable(const Use *edgeUse) const {
    assert(cast<Instruction>(edgeUse->getUser())->isTerminator() &&
           "edge must be operand of terminator");
    assert(cast_or_null<BasicBlock>(edgeUse->get()) &&
           "edge must refer to basic block");
    assert(!isBlockUnreachable(cast<Instruction>(edgeUse->getUser())->getParent()) &&
           "isEdgeUnreachable() must be applied to edge from live block");
    return unreachableEdges.count(edgeUse);
  }

  bool hasAnyLivePredecessors(const BasicBlock *BB) const {
    for (const_pred_iterator predIt(BB), endIt(BB, true); predIt != endIt; ++predIt) {
      auto &operandUse = predIt.getUse();
      const Use &edge = operandUse.getUser()->getOperandUse(operandUse.getOperandNo());
      if (!isBlockUnreachable(*predIt) && !isEdgeUnreachable(&edge))
        return true;
    }
    return false;
  }

  void analyzeFunction(const Function &func, const DominatorTree &dt) {
    domTreeRef = &dt;

    for (const BasicBlock &bb : func)
      if (!dt.isReachableFromEntry(&bb))
        unreachableBlocks.insert(&bb);

    ReversePostOrderTraversal<const Function *> rpoTraversal(&func);
    for (const BasicBlock *bb : rpoTraversal) {
      const Instruction *termInst = bb->getTerminator();
      assert(termInst && "blocks must be well formed");

      const BranchInst *branch = dyn_cast<BranchInst>(termInst);
      if (!branch || !branch->isConditional() || !isa<Constant>(branch->getCondition()))
        continue;

      if (branch->getSuccessor(0) == branch->getSuccessor(1))
        continue;

      ConstantInt *condConst = dyn_cast<ConstantInt>(branch->getCondition());
      if (!condConst)
        continue;

      addUnreachableEdge(branch->getOperandUse(condConst->getZExtValue() ? 1 : 2));
    }
  }

protected:
  void markBlockUnreachable(const BasicBlock *bb) {
    SmallVector<const BasicBlock *, 4> newlyUnreachable;
    SmallSetVector<const BasicBlock *, 4> dominanceFrontier;
    newlyUnreachable.push_back(bb);

    while (!newlyUnreachable.empty()) {
      const BasicBlock *current = newlyUnreachable.pop_back_val();
      if (isBlockUnreachable(current))
        continue;

      SmallVector<BasicBlock *, 8> dominatedBlocks;
      domTreeRef->getDescendants(const_cast<BasicBlock*>(current), dominatedBlocks);

      unreachableBlocks.insert(dominatedBlocks.begin(), dominatedBlocks.end());

      for (BasicBlock *block : dominatedBlocks)
        for (BasicBlock *successor : successors(block))
          if (!isBlockUnreachable(successor) && !hasAnyLivePredecessors(successor))
            newlyUnreachable.push_back(successor);
    }
  }

  void addUnreachableEdge(const Use &unreachableEdge) {
    if (!unreachableEdges.insert(&unreachableEdge))
      return;

    BasicBlock *targetBB = cast_or_null<BasicBlock>(unreachableEdge.get());
    if (hasAnyLivePredecessors(targetBB))
      return;

    markBlockUnreachable(targetBB);
  }
};
} // namespace

static void VerifyFunction(const Function &F, const DominatorTree &DT,
                          const BlockReachabilityAnalyzer &BRA);

namespace llvm {
PreservedAnalyses SafepointIRVerificationPass::run(Function &F,
                                                   FunctionAnalysisManager &AM) {
  const auto &domTree = AM.getResult<DominatorTreeAnalysis>(F);
  BlockReachabilityAnalyzer BRA;
  BRA.analyzeFunction(F, domTree);
  VerifyFunction(F, domTree, BRA);
  return PreservedAnalyses::all();
}
