namespace {
struct SafepointIRChecker : public FunctionPass {
  static char ID;
  SafepointIRChecker() : FunctionPass(ID) {
    initializeSafepointIRCheckerPass(*PassRegistry::getPassRegistry());
  }

  bool runOnFunction(Function &F) override {
    auto &domTree = getAnalysis<DominatorTreeWrapperPass>().getDomTree();
    BlockReachabilityAnalyzer BRA;
    BRA.analyzeFunction(F, domTree);
    VerifyFunction(F, domTree, BRA);
    return false;
  }

  void getAnalysisUsage(AnalysisUsage &AU) const override {
    AU.addRequiredID(DominatorTreeWrapperPass::ID);
    AU.setPreservesAll();
  }

  StringRef getPassName() const override { return "safepoint instruction checker"; }
};
} // namespace

void llvm::verifySafepointIR(Function &F) {
  SafepointIRChecker pass;
  pass.runOnFunction(F);
}

