static bool isGCPointerType(Type *T) {
  if (auto *PT = dyn_cast<PointerType>(T))
    return (1 == PT->getAddressSpace());
  return false;
}

static bool containsGCPtrType(Type *Ty) {
  if (isGCPointerType(Ty))
    return true;
  if (VectorType *VT = dyn_cast<VectorType>(Ty))
    return isGCPointerType(VT->getScalarType());
  if (ArrayType *AT = dyn_cast<ArrayType>(Ty))
    return containsGCPtrType(AT->getElementType());
  if (StructType *ST = dyn_cast<StructType>(Ty))
    return llvm::any_of(ST->elements(), containsGCPtrType);
  return false;
}

template<typename IteratorTy>
static void PrintValueSet(raw_ostream &OS, IteratorTy Begin, IteratorTy End) {
  OS << "[ ";
  while (Begin != End) {
    OS << **Begin << " ";
    ++Begin;
  }
  OS << "]";
}

using AvailableValueSet = DenseSet<const Value *>;

struct BasicBlockData {
  AvailableValueSet IncomingValues;
  AvailableValueSet OutgoingValues;
  AvailableValueSet LocalContribution;
  bool Cleared = false;
};

enum PointerBaseType {
  NonConstantPointer = 1,
  ExclusivelyNullPointer,
  ExclusivelySomeConstantPointer
};

static enum PointerBaseType getBaseTypeInfo(const Value *Val) {
  SmallVector<const Value *, 32> worklist;
  DenseSet<const Value *> visited;
  bool isExclusivelyDerivedFromNull = true;
  worklist.push_back(Val);

  while(!worklist.empty()) {
    const Value *current = worklist.pop_back_val();
    if (!visited.insert(current).second)
      continue;

    if (const auto *castInst = dyn_cast<CastInst>(current)) {
      worklist.push_back(castInst->stripPointerCasts());
      continue;
    }

    if (const auto *gep = dyn_cast<GetElementPtrInst>(current)) {
      worklist.push_back(gep->getPointerOperand());
      continue;
    }

    if (const auto *phiNode = dyn_cast<PHINode>(current)) {
      append_range(worklist, phiNode->incoming_values());
      continue;
    }

    if (const auto *selectInst = dyn_cast<SelectInst>(current)) {
      worklist.push_back(selectInst->getTrueValue());
      worklist.push_back(selectInst->getFalseValue());
      continue;
    }

    if (const auto *gcRelocate = dyn_cast<GCRelocateInst>(current)) {
      worklist.push_back(gcRelocate->getDerivedPtr());
      continue;
    }

    if (const auto *freeze = dyn_cast<FreezeInst>(current)) {
      worklist.push_back(freeze->getOperand(0));
      continue;
    }

    if (isa<Constant>(current)) {
      if (current != Constant::getNullValue(current->getType()))
        isExclusivelyDerivedFromNull = false;
      continue;
    }

    return PointerBaseType::NonConstantPointer;
  }

  return isExclusivelyDerivedFromNull ? PointerBaseType::ExclusivelyNullPointer
                                      : PointerBaseType::ExclusivelySomeConstantPointer;
}

static bool isNotExclusivelyConstantDerived(const Value *V) {
  return getBaseTypeInfo(V) == PointerBaseType::NonConstantPointer;
}

class InstructionValidator;

class GCPointerAnalyzer {
  const Function &functionRef;
  const BlockReachabilityAnalyzer &reachabilityAnalyzer;
  SpecificBumpPtrAllocator<BasicBlockData> allocator;
  DenseMap<const BasicBlock *, BasicBlockData *> blockDataMap;
  DenseSet<const Instruction *> validUnrelocatedDefinitions;
  DenseSet<const Value *> poisonedDefinitions;

public:
  GCPointerAnalyzer(const Function &F, const DominatorTree &DT,
                   const BlockReachabilityAnalyzer &BRA) : functionRef(F), reachabilityAnalyzer(BRA) {
    for (const BasicBlock &bb : F)
      if (!BRA.isBlockUnreachable(&bb)) {
        BasicBlockData *bbd = new (allocator.Allocate()) BasicBlockData;
        for (const auto &inst : bb)
          processInstruction(inst, bbd->Cleared, bbd->LocalContribution);
        blockDataMap[&bb] = bbd;
      }

    for (auto &entry : blockDataMap) {
      computeDominatingDefinitions(entry.first, entry.second->IncomingValues, DT);
      updateBlockState(entry.first, *entry.second, true);
    }

    propagateStates();
  }

  bool hasLiveIncomingEdge(const PHINode *PN, const BasicBlock *InBB) const {
    return reachabilityAnalyzer.hasLivePredecessorEdge(PN, InBB);
  }

  BasicBlockData *getBlockData(const BasicBlock *BB) {
    return blockDataMap.lookup(BB);
  }

  const BasicBlockData *getBlockData(const BasicBlock *BB) const {
    return const_cast<GCPointerAnalyzer *>(this)->getBlockData(BB);
  }

  bool isValuePoisoned(const Value *V) const { return poisonedDefinitions.count(V); }

  static void validateFunction(GCPointerAnalyzer &&analyzer,
                              InstructionValidator &validator) {
    ReversePostOrderTraversal<const Function *> rpo(&analyzer.functionRef);
    for (const BasicBlock *bb : rpo) {
      BasicBlockData *bbd = analyzer.getBlockData(bb);
      if (!bbd)
        continue;

      AvailableValueSet &availableSet = bbd->IncomingValues;
      for (const Instruction &inst : *bb) {
        if (analyzer.canSkipInstruction(&inst))
          continue;

        validator.validateInstruction(&analyzer, inst, availableSet);
        bool cleared = false;
        processInstruction(inst, cleared, availableSet);
        (void)cleared;
      }
    }
  }

  bool isBlockMapped(const BasicBlock *BB) const { return blockDataMap.contains(BB); }

private:
  bool canSkipInstruction(const Instruction *I) const {
    return validUnrelocatedDefinitions.count(I) || poisonedDefinitions.count(I);
  }

  void propagateStates() {
    SetVector<const BasicBlock *> worklist;
    for (auto &entry : blockDataMap)
      worklist.insert(entry.first);

    while (!worklist.empty()) {
      const BasicBlock *bb = worklist.pop_back_val();
      BasicBlockData *bbd = getBlockData(bb);
      if (!bbd)
        continue;

      size_t oldInCount = bbd->IncomingValues.size();

      for (const_pred_iterator predIt(bb), endIt(bb, true); predIt != endIt; ++predIt) {
        const BasicBlock *predBB = *predIt;
        BasicBlockData *predBBD = getBlockData(predBB);
        if (predBBD && !reachabilityAnalyzer.isEdgeUnreachable(&BlockReachabilityAnalyzer::getEdgeReference(predIt)))
          set_intersect(bbd->IncomingValues, predBBD->OutgoingValues);
      }

      assert(oldInCount >= bbd->IncomingValues.size() && "invariant!");
      bool inputsChanged = oldInCount != bbd->IncomingValues.size();
      bool contributionChanged =
          removeValidUnrelocatedDefs(bb, bbd, bbd->LocalContribution);

      if (!inputsChanged && !contributionChanged)
        continue;

      size_t oldOutCount = bbd->OutgoingValues.size();
      updateBlockState(bb, *bbd, contributionChanged);
      if (oldOutCount != bbd->OutgoingValues.size()) {
        assert(oldOutCount > bbd->OutgoingValues.size() && "invariant!");
        for (succ_iterator succIt = succ_begin(bb), endIt = succ_end(bb); succIt != endIt; ++succIt)
          worklist.insert(*succIt);
      }
    }
  }

  bool removeValidUnrelocatedDefs(const BasicBlock *BB,
                                  const BasicBlockData *bbd,
                                  AvailableValueSet &contribution) {
    assert(&bbd->LocalContribution == &contribution &&
           "Passed contribution should be from the passed BasicBlockData!");

    AvailableValueSet availableSet = bbd->IncomingValues;
    bool contributionChanged = false;

    for (const Instruction &inst : *BB) {
      bool validUnrelocatedDef = false;
      bool poisonedDef = false;

      if (const PHINode *phi = dyn_cast<PHINode>(&inst)) {
        if (containsGCPtrType(phi->getType())) {
          bool hasRelocatedInputs = false;
          bool hasUnrelocatedInputs = false;

          for (unsigned i = 0, e = phi->getNumIncomingValues(); i != e; ++i) {
            const BasicBlock *inBB = phi->getIncomingBlock(i);
            if (!isBlockMapped(inBB) ||
                !reachabilityAnalyzer.hasLivePredecessorEdge(phi, inBB))
              continue;

            const Value *inValue = phi->getIncomingValue(i);
            if (isNotExclusivelyConstantDerived(inValue)) {
              if (isValuePoisoned(inValue)) {
                hasRelocatedInputs = true;
                hasUnrelocatedInputs = true;
                break;
              }

              if (blockDataMap[inBB]->OutgoingValues.count(inValue))
                hasRelocatedInputs = true;
              else
                hasUnrelocatedInputs = true;
            }
          }

          if (hasUnrelocatedInputs) {
            if (hasRelocatedInputs)
              poisonedDef = true;
            else
              validUnrelocatedDef = true;
          }
        }
      } else if ((isa<GetElementPtrInst>(inst) || isa<BitCastInst>(inst)) &&
                 containsGCPtrType(inst.getType())) {
        for (const Value *op : inst.operands())
          if (containsGCPtrType(op->getType()) &&
              isNotExclusivelyConstantDerived(op) && !availableSet.count(op)) {
            if (isValuePoisoned(op))
              poisonedDef = true;
            else
              validUnrelocatedDef = true;
            break;
          }
      }

      assert(!(validUnrelocatedDef && poisonedDef) &&
             "Value cannot be both unrelocated and poisoned!");

      if (validUnrelocatedDef) {
        contribution.erase(&inst);
        poisonedDefinitions.erase(&inst);
        validUnrelocatedDefinitions.insert(&inst);
        LLVM_DEBUG(dbgs() << "Removing urelocated " << inst
                          << " from Contribution of " << BB->getName() << "\n");
        contributionChanged = true;
      } else if (poisonedDef) {
        contribution.erase(&inst);
        poisonedDefinitions.insert(&inst);
        LLVM_DEBUG(dbgs() << "Removing poisoned " << inst << " from Contribution of "
                          << BB->getName() << "\n");
        contributionChanged = true;
      } else {
        bool cleared = false;
        processInstruction(inst, cleared, availableSet);
        (void)cleared;
      }
    }
    return contributionChanged;
  }

  void computeDominatingDefinitions(const BasicBlock *BB, AvailableValueSet &result,
                                   const DominatorTree &DT) {
    DomTreeNode *dtNode = DT[const_cast<BasicBlock *>(BB)];
    assert(dtNode && "Unreachable blocks are ignored");

    while (dtNode->getIDom()) {
      dtNode = dtNode->getIDom();
      auto bbd = getBlockData(dtNode->getBlock());
      assert(bbd && "immediate dominator cannot be dead for a live block");
      const auto &defs = bbd->LocalContribution;
      result.insert(defs.begin(), defs.end());
      if (bbd->Cleared)
        return;
    }

    for (const Argument &arg : BB->getParent()->args())
      if (containsGCPtrType(arg.getType()))
        result.insert(&arg);
  }

  static void updateBlockState(const BasicBlock *BB, BasicBlockData &bbd,
                               bool contributionChanged) {
    const AvailableValueSet &availableIn = bbd.IncomingValues;
    AvailableValueSet &availableOut = bbd.OutgoingValues;

    if (bbd.Cleared) {
      if (contributionChanged)
        availableOut = bbd.LocalContribution;
    } else {
      AvailableValueSet temp = bbd.LocalContribution;
      set_union(temp, availableIn);
      availableOut = std::move(temp);
    }

    LLVM_DEBUG(dbgs() << "Updated block " << BB->getName() << " from ";
               PrintValueSet(dbgs(), availableIn.begin(), availableIn.end());
               dbgs() << " to ";
               PrintValueSet(dbgs(), availableOut.begin(), availableOut.end());
               dbgs() << "\n";);
  }

  static void processInstruction(const Instruction &inst, bool &cleared,
                                AvailableValueSet &available) {
    if (isa<GCStatepointInst>(inst)) {
      cleared = true;
      available.clear();
    } else if (containsGCPtrType(inst.getType()))
      available.insert(&inst);
  }
};

class InstructionValidator {
  bool anyInvalidUses = false;

public:
  void validateInstruction(const GCPointerAnalyzer *analyzer, const Instruction &inst,
                          const AvailableValueSet &availableSet) {
    if (const PHINode *phi = dyn_cast<PHINode>(&inst)) {
      if (containsGCPtrType(phi->getType()))
        for (unsigned i = 0, e = phi->getNumIncomingValues(); i != e; ++i) {
          const BasicBlock *inBB = phi->getIncomingBlock(i);
          const BasicBlockData *inBBD = analyzer->getBlockData(inBB);
          if (!inBBD ||
              !analyzer->hasLiveIncomingEdge(phi, inBB))
            continue;

          const Value *inValue = phi->getIncomingValue(i);
          if (isNotExclusivelyConstantDerived(inValue) &&
              !inBBD->OutgoingValues.count(inValue))
            reportInvalidUse(*inValue, *phi);
        }
    } else if (isa<CmpInst>(inst) &&
               containsGCPtrType(inst.getOperand(0)->getType())) {
      Value *lhs = inst.getOperand(0), *rhs = inst.getOperand(1);
      enum PointerBaseType baseTyLHS = getBaseTypeInfo(lhs),
                    baseTyRHS = getBaseTypeInfo(rhs);

      auto hasValidUnrelocatedUse = [&availableSet, analyzer, baseTyLHS, baseTyRHS,
                                    &lhs, &rhs] () {
        if (availableSet.count(lhs) || availableSet.count(rhs))
          return false;

        if ((baseTyLHS == PointerBaseType::ExclusivelySomeConstantPointer &&
             baseTyRHS == PointerBaseType::NonConstantPointer) ||
            (baseTyLHS == PointerBaseType::NonConstantPointer &&
             baseTyRHS == PointerBaseType::ExclusivelySomeConstantPointer))
          return false;

        if ((analyzer->isValuePoisoned(lhs) && baseTyRHS != ExclusivelyNullPointer) ||
            (analyzer->isValuePoisoned(rhs) && baseTyLHS != ExclusivelyNullPointer))
            return false;

        return true;
      };

      if (!hasValidUnrelocatedUse()) {
        if (baseTyLHS == PointerBaseType::NonConstantPointer && !availableSet.count(lhs))
          reportInvalidUse(*lhs, inst);
        if (baseTyRHS == PointerBaseType::NonConstantPointer && !availableSet.count(rhs))
          reportInvalidUse(*rhs, inst);
      }
    } else {
      for (const Value *op : inst.operands())
        if (containsGCPtrType(op->getType()) &&
            isNotExclusivelyConstantDerived(op) && !availableSet.count(op))
          reportInvalidUse(*op, inst);
    }
  }

  bool hasAnyInvalidUses() const { return anyInvalidUses; }

private:
  void reportInvalidUse(const Value &val, const Instruction &inst) {
    errs() << "Illegal use of unrelocated value found!\n";
    errs() << "Def: " << val << "\n";
    errs() << "Use: " << inst << "\n";
    if (!PrintOnly)
      abort();
    anyInvalidUses = true;
  }
};

static void VerifyFunction(const Function &F, const DominatorTree &DT,
                          const BlockReachabilityAnalyzer &BRA) {
  LLVM_DEBUG(dbgs() << "Verifying gc pointers in function: " << F.getName()
                    << "\n");
  if (PrintOnly)
    dbgs() << "Verifying gc pointers in function: " << F.getName() << "\n";

  GCPointerAnalyzer analyzer(F, DT, BRA);
  InstructionValidator validator;
  GCPointerAnalyzer::validateFunction(std::move(analyzer), validator);

  if (PrintOnly && !validator.hasAnyInvalidUses()) {
    dbgs() << "No illegal uses found by SafepointIRVerifier in: " << F.getName()
           << "\n";
  }
}

