// Helper: check if a pass should be excluded from timing
static bool isExcludedPass(StringRef PassName) {
  static const char* ExcludedNames[] = {
    "PassManager", "PassAdaptor", "AnalysisManagerProxy",
    "ModuleInlinerWrapperPass", "DevirtSCCRepeatedPass"
  };
  for (auto &name : ExcludedNames) {
    if (PassName == name)
      return true;
  }
  return false;
}

namespace legacy {

class PassTimerController {
public:
  using TimerPtr = std::unique_ptr<Timer>;
  using TimerList = std::vector<TimerPtr>;
  using IDCounterMap = StringMap<unsigned>;
  using InstanceTimerMap = DenseMap<void*, TimerPtr>;

private:
  IDCounterMap InstanceCounts;
  InstanceTimerMap TimersForInstances;
  TimerGroup GlobalTimerGroup;

public:
  PassTimerController() : GlobalTimerGroup("pass", "Pass execution timing report") {}

  ~PassTimerController() {
    TimersForInstances.clear(); // Triggers TimerGroup destructor at end
  }

  static void initializeIfEnabled() {
    if (!TimePassesIsEnabled || !TheInstance)
      TheInstance = std::make_unique<PassTimerController>();
  }

  static void printTimings(raw_ostream *OS = nullptr) {
    if (TheInstance)
      TheInstance->GlobalTimerGroup.print(OS ? *OS : *CreateInfoOutputFile(), true);
  }

  Timer* acquireTimer(Pass* P, void* instanceID) {
    init();
    sys::SmartScopedLock<true> guard(*getMutex());

    auto& existing = TheInstance->TimersForInstances[instanceID];
    if (!existing) {
      StringRef name = P->getPassName();
      StringRef arg;
      if (const PassInfo* info = Pass::lookupPassInfo(P->getPassID()))
        arg = info->getPassArgument();

      std::string desc = arg.empty() ? name.str() : arg.str();
      unsigned count = ++TheInstance->InstanceCounts[arg.empty() ? name : arg];
      if (count > 1)
        desc = formatv("{0} #{1}", desc, count).str();

      existing.reset(new Timer(arg.empty() ? name : arg, desc, TheInstance->GlobalTimerGroup));
    }
    return existing.get();
  }

private:
  static PassTimerController* TheInstance;
  static ManagedStatic<sys::SmartMutex<true>> s_mutex;

  static void init() {
    if (!TimePassesIsEnabled || TheInstance)
      return;
    initializeIfEnabled();
  }

  static sys::SmartMutex<true>* getMutex() { return &*s_mutex; }
};

PassTimerController* PassTimerController::TheInstance = nullptr;
ManagedStatic<sys::SmartMutex<true>> PassTimerController::s_mutex;

} // namespace legacy

// Public API wrapper
Timer* getPassTimer(Pass* P) {
  legacy::PassTimerController::init();
  if (legacy::PassTimerController::TheInstance)
    return legacy::PassTimerController::TheInstance->acquireTimer(P, P);
  return nullptr;
}

void reportAndResetTimings(raw_ostream* OS) {
  legacy::PassTimerController::printTimings(OS);
}

// New Pass Manager Timing Handler
class PassTimerCollector {
public:
  using TimerPtr = std::unique_ptr<Timer>;
  using TimerVec = std::vector<TimerPtr>;
  using TimerMap = StringMap<TimerVec>;

private:
  TimerGroup PassTimerGroup;
  TimerGroup AnalysisTimerGroup;
  TimerMap RegisteredTimers;
  raw_ostream* OutputStream = nullptr;

  bool EnabledFlag;
  bool PerRunMode;

  TimerVec& ensureTimers(StringRef ID) {
    return RegisteredTimers.try_emplace(ID, TimerVec{}).first->second;
  }

  Timer& obtainTimer(StringRef ID, bool isPass) {
    TimerGroup& tg = isPass ? PassTimerGroup : AnalysisTimerGroup;
    TimerVec& vec = ensureTimers(ID);

    if (!PerRunMode) {
      if (vec.empty())
        vec.emplace_back(std::make_unique<Timer>(ID, ID, tg));
      return *vec.front();
    }

    unsigned idx = vec.size() + 1;
    std::string fullDesc = formatv("{0} #{1}", ID, idx).str();
    Timer* t = new Timer(ID, fullDesc, tg);
    vec.emplace_back(t);
    return *t;
  }

  void flushTimings() {
    std::unique_ptr<raw_ostream> created;
    raw_ostream* os = OutputStream;
    if (!os) {
      created = CreateInfoOutputFile();
      os = created.get();
    }
    PassTimerGroup.print(*os, true);
    AnalysisTimerGroup.print(*os, true);
  }

public:
  PassTimerCollector(bool enabled, bool perRun)
    : PassTimerGroup("pass", "Pass execution timing report"),
      AnalysisTimerGroup("analysis", "Analysis execution timing report"),
      EnabledFlag(enabled), PerRunMode(perRun) {}

  PassTimerCollector()
    : PassTimerCollector(TimePassesIsEnabled, TimePassesPerRun) {}

  void setOutputStream(raw_ostream& out) { OutputStream = &out; }

  void emitReport() {
    if (!EnabledFlag) return;
    flushTimings();
  }

  LLVM_DUMP_METHOD void dump() const {
    dbgs() << "Dumping timers for " << getTypeName<PassTimerCollector>() << ":\n\tRunning:\n";
    for (const auto& pair : RegisteredTimers) {
      StringRef id = pair.getKey();
      const TimerVec& timers = pair.getValue();
      for (size_t i = 0; i < timers.size(); ++i) {
        const Timer* t = timers[i].get();
        if (t && t->isRunning())
          dbgs() << "\tTimer " << t << " for " << id << " (#" << i << ")\n";
      }
    }
    dbgs() << "\tTriggered:\n";
    for (const auto& pair : RegisteredTimers) {
      StringRef id = pair.getKey();
      const TimerVec& timers = pair.getValue();
      for (size_t i = 0; i < timers.size(); ++i) {
        const Timer* t = timers[i].get();
        if (t && t->hasTriggered() && !t->isRunning())
          dbgs() << "\tTimer " << t << " for " << id << " (#" << i << ")\n";
      }
    }
  }

  void startPassTimer(StringRef name) {
    if (isExcludedPass(name)) return;

    if (!PassStack.empty()) {
      Timer* prev = PassStack.back();
      if (prev->isRunning()) prev->stopTimer();
    }

    Timer& t = obtainTimer(name, /*isPass=*/true);
    PassStack.push_back(&t);
    t.startTimer();
  }

  void stopPassTimer(StringRef name) {
    if (isExcludedPass(name)) return;

    if (PassStack.empty()) return;
    Timer* t = PassStack.pop_back_val();
    if (t && t->isRunning()) t->stopTimer();

    if (!PassStack.empty()) {
      Timer* prev = PassStack.back();
      if (!prev->isRunning()) prev->startTimer();
    }
  }

  void startAnalysisTimer(StringRef name) {
    if (!AnalysisStack.empty()) {
      Timer* prev = AnalysisStack.back();
      if (prev->isRunning()) prev->stopTimer();
    }

    Timer& t = obtainTimer(name, /*isPass=*/false);
    AnalysisStack.push_back(&t);
    if (!t.isRunning()) t.startTimer();
  }

  void stopAnalysisTimer(StringRef name) {
    if (AnalysisStack.empty()) return;
    Timer* t = AnalysisStack.pop_back_val();
    if (t && t->isRunning()) t->stopTimer();

    if (!AnalysisStack.empty()) {
      Timer* prev = AnalysisStack.back();
      if (!prev->isRunning()) prev->startTimer();
    }
  }

  void installCallbacks(PassInstrumentationCallbacks& callbacks) {
    if (!EnabledFlag) return;

    callbacks.registerBeforeNonSkippedPassCallback(
        [this](StringRef p, Any) { this->startPassTimer(p); });

    callbacks.registerAfterPassCallback(
        [this](StringRef p, Any, const PreservedAnalyses&) {
          this->stopPassTimer(p);
        });

    callbacks.registerAfterPassInvalidatedCallback(
        [this](StringRef p, const PreservedAnalyses&) {
          this->stopPassTimer(p);
        });

    callbacks.registerBeforeAnalysisCallback(
        [this](StringRef p, Any) { this->startAnalysisTimer(p); });

    callbacks.registerAfterAnalysisCallback(
        [this](StringRef p, Any) { this->stopAnalysisTimer(p); });
  }

private:
  std::vector<Timer*> PassStack;
  std::vector<Timer*> AnalysisStack;
};

