#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to represent a node with its distance from root
struct TreeNode {
    int nodeId;
    long long distance;
};

// Comparison function for sorting nodes by distance from root
bool sortByDistance(const TreeNode& x, const TreeNode& y) {
    return x.distance < y.distance;
}

int totalNodes;
vector<long long> distances;
vector<int> parentNodes;
vector<vector<int>> childLists;
vector<int> subtreeSizes;
vector<TreeNode> sortedTreeNodes;

// Function to ask query and get distance between two nodes
long long askDistance(int u, int v) {
    cout << "? " << u << " " << v << endl;
    long long result;
    cin >> result;
    return result;
}

// Update subtree sizes along the path from node u to root
void updateSubtreeCounts(int node) {
    while (node != -1) {
        subtreeSizes[node]++;
        node = parentNodes[node];
    }
}

// Find ancestor of 'node' that has exactly 'targetDepth'
int findAncestorByDepth(int node, long long targetDepth) {
    int current = node;
    while (current != -1) {
        if (distances[current] == targetDepth) {
            return current;
        }
        if (distances[current] < targetDepth) {
            break; // Overshot the target depth
        }
        current = parentNodes[current];
    }
    return -1;
}

void solve() {
    cin >> totalNodes;

    // Special case: single node tree
    if (totalNodes == 1) {
        cout << "! " << endl;
        return;
    }

    distances.assign(totalNodes + 1, 0);

    // Step 1: Query distances from root (node 1) to all other nodes
    for (int i = 2; i <= totalNodes; ++i) {
        distances[i] = askDistance(1, i);
    }

    // Prepare list of nodes with their distances for sorting
    sortedTreeNodes.resize(totalNodes);
    for (int i = 1; i <= totalNodes; ++i) {
        sortedTreeNodes[i - 1] = {i, distances[i]};
    }

    // Step 2: Sort nodes by increasing distance from root
    sort(sortedTreeNodes.begin(), sortedTreeNodes.end(), sortByDistance);

    // Step 3: Build tree incrementally
    parentNodes.assign(totalNodes + 1, -1);
    childLists.assign(totalNodes + 1, vector<int>());
    subtreeSizes.assign(totalNodes + 1, 1);

    // Process each node (starting from second, since first is root)
    for (int idx = 1; idx < totalNodes; ++idx) {
        int newNode = sortedTreeNodes[idx].nodeId;
        long long newDist = sortedTreeNodes[idx].distance;

        int candidateParent = 1;
        vector<int> possibleChildren = childLists[candidateParent];

        while (true) {
            if (possibleChildren.empty()) {
                // Attach directly as child of current candidate
                parentNodes[newNode] = candidateParent;
                childLists[candidateParent].push_back(newNode);
                updateSubtreeCounts(candidateParent);
                break;
            }

            // Find child with largest subtree (heavy child heuristic)
            int bestChild = -1;
            int maxSubtreeSize = -1;
            int bestIndex = -1;

            for (size_t k = 0; k < possibleChildren.size(); ++k) {
                int child = possibleChildren[k];
                if (subtreeSizes[child] > maxSubtreeSize) {
                    maxSubtreeSize = subtreeSizes[child];
                    bestChild = child;
                    bestIndex = k;
                }
            }

            // Descend to deepest leaf in heavy child's subtree
            int leafNode = bestChild;
            while (!childLists[leafNode].empty()) {
                int nextBest = -1;
                int nextMaxSize = -1;
                for (int grandchild : childLists[leafNode]) {
                    if (subtreeSizes[grandchild] > nextMaxSize) {
                        nextMaxSize = subtreeSizes[grandchild];
                        nextBest = grandchild;
                    }
                }
                leafNode = nextBest;
            }

            // Query distance between new node and leaf node
            long long distNewToLeaf = askDistance(newNode, leafNode);

            // Compute LCA distance using formula: d(lca) = (d(u) + d(v) - d(u,v)) / 2
            long long lcaDistance = (newDist + distances[leafNode] - distNewToLeaf) / 2;

            // Locate LCA node in existing tree
            int lcaNode = findAncestorByDepth(leafNode, lcaDistance);

            if (lcaNode == candidateParent) {
                // LCA is current candidate — remove this branch from candidates
                possibleChildren[bestIndex] = possibleChildren.back();
                possibleChildren.pop_back();
            } else {
                // LCA is deeper — move search down to LCA
                int childOnPathToLeaf = leafNode;
                if (childOnPathToLeaf != lcaNode) {
                    while (parentNodes[childOnPathToLeaf] != lcaNode) {
                        childOnPathToLeaf = parentNodes[childOnPathToLeaf];
                    }
                } else {
                    // Special case: LCA is the leaf itself → attach here
                    parentNodes[newNode] = leafNode;
                    childLists[leafNode].push_back(newNode);
                    updateSubtreeCounts(leafNode);
                    break;
                }

                candidateParent = lcaNode;
                possibleChildren = childLists[candidateParent];

                // Remove the branch leading to leaf from candidates
                for (size_t k = 0; k < possibleChildren.size(); ++k) {
                    if (possibleChildren[k] == childOnPathToLeaf) {
                        possibleChildren[k] = possibleChildren.back();
                        possibleChildren.pop_back();
                        break;
                    }
                }
            }
        }
    }

    // Output final tree structure
    cout << "!";
    for (int i = 2; i <= totalNodes; ++i) {
        long long edgeWeight = distances[i] - distances[parentNodes[i]];
        cout << " " << parentNodes[i] << " " << i << " " << edgeWeight;
    }
    cout << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            solve();
        }
    }

    return 0;
}

