void HamScrollSpeedIndicator::PreLoad(BinStream &bs) {
    LOAD_REVS(bs);
    ASSERT_REVS(2, 0)
    RndDir::PreLoad(bs);
    BinStreamRev revData(bs, bs.PopRev(this));
    bs.PushRev(packRevs(revData.altRev, revData.rev), this);
}

void HamScrollSpeedIndicator::PostLoad(BinStream &bs) {
    BinStreamRev revData(bs, bs.PopRev(this));
    RndDir::PostLoad(bs);

    const int minorVersion = revData.rev & 0xffff;
    if (minorVersion >= 1) {
        bs >> mEnterAnim;
        bs >> mExitAnim;
        bs >> mIndicatorAnim;
    }
    if (minorVersion >= 2) {
        bs >> mSlowScrollThresholdFrame;
        bs >> mFastScrollThresholdFrame;
    }
}

