using namespace std;

// --- Type Definitions ---
using i64 = long long;
using u64 = unsigned long long;
using ld  = long double;
template<class T> using vec = vector<T>;
template<class T> using vvec = vector<vector<T>>;
using pii = pair<int, int>;
using pll = pair<i64, i64>;

// --- Constants ---
constexpr i64 INF64 = 4e18;
constexpr int INF32 = 2e9;
constexpr i64 MOD   = 1'000'000'007LL;
constexpr i64 MOD9  = 998'244'353LL;
constexpr ld PI     = 3.14159265358979323846;

// --- Random Number Generator ---
mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

// --- Macros ---
#define all(x) (x).begin(), (x).end()
#define rall(x) (x).rbegin(), (x).rend()
#define sz(x) ((int)(x).size())
#define pb push_back
#define eb emplace_back
#define fi first
#define se second

inline i64 gcd(i64 a, i64 b) { return std::gcd(a, b); }
inline i64 lcm(i64 a, i64 b) { return (a / std::gcd(a, b)) * b; }

inline i64 modpow(i64 base, i64 exp, i64 mod = MOD) {
    i64 res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

void solve() {
    i64 n, k;
    cin >> n >> k;

    vec<i64> factors;

    // Factorize n by trial division up to sqrt(n)
    // Collect at most k-1 smallest prime factors
    for (i64 d = 2; d * d <= n && sz(factors) < k - 1; ++d) {
        while (n % d == 0 && sz(factors) < k - 1) {
            factors.pb(d);
            n /= d;
        }
    }

    // Check feasibility: need exactly k factors, each >= 2
    // If we have fewer than k-1 factors or remaining n is 1, impossible
    if (sz(factors) < k - 1 || n == 1) {
        cout << -1 << '\n';
        return;
    }

    // Last factor is the remaining part of n
    factors.pb(n);

    // Output the result
    for (size_t i = 0; i < sz(factors); ++i) {
        if (i > 0) cout << " ";
        cout << factors[i];
    }
    cout << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(10);

    solve();

    return 0;
}

