// Determine the installation prefix by locating the shared library
// containing the anchor function via dynamic linking
std::filesystem::path get_install_prefix() {
  Dl_info dl_info;
  // Resolve the address of the anchor function to find its library path
  dladdr(reinterpret_cast<void*>(&anchor::example_models_location_anchor), &dl_info);

  // Normalize the full path to the shared library
  auto lib_path = std::filesystem::path(dl_info.dli_fname).lexically_normal();

  // Navigate up two directories: from lib/roboplan_example_models/... to install root
  return lib_path.parent_path().parent_path();
}

// Construct the package share directory path
std::filesystem::path get_package_share_dir() {
  return get_install_prefix() / "share";
}

// Build the full path to the models directory
std::filesystem::path get_package_models_dir() {
  return get_package_share_dir() / "roboplan_example_models" / "models";
}

