#include <iostream>
#include <nlohmann/json_fwd.hpp>
#include <string>
#include <sstream>
#include <sdfg/analysis/analysis.h>
#include <sdfg/builder/structured_sdfg_builder.h>
#include <sdfg/codegen/code_generators/c_code_generator.h>
#include <sdfg/codegen/dispatchers/node_dispatcher_registry.h>
#include <sdfg/codegen/instrumentation/arg_capture_plan.h>
#include <sdfg/codegen/instrumentation/instrumentation_plan.h>
#include <sdfg/passes/dataflow/tensor_to_pointer_conversion.h>
#include <sdfg/passes/pipeline.h>
#include <sdfg/serializer/json_serializer.h>

int main(int argc, char* argv[]) {
    // Initialize default dispatchers and serializers for SDFG processing
    sdfg::codegen::register_default_dispatchers();
    sdfg::serializer::register_default_serializers();

    // Read JSON input from standard input into a string stream
    std::stringstream input_buffer;
    std::string line;
    while (std::getline(std::cin, line)) {
        input_buffer << line << "\n";
    }

    // Parse the accumulated JSON content
    nlohmann::json json_data = nlohmann::json::parse(input_buffer);

    // Deserialize the SDFG from parsed JSON
    sdfg::serializer::JSONSerializer deserializer;
    auto sdfg_ptr = deserializer.deserialize(json_data);

    // Set up builder and analysis infrastructure
    sdfg::builder::StructuredSDFGBuilder sdfg_builder(*sdfg_ptr);
    sdfg::analysis::AnalysisManager analysis_mgr(sdfg_builder.subject());

    // Apply expansion pipeline (e.g., library node expansion)
    sdfg::passes::Pipeline expand_pass = sdfg::passes::Pipeline::expansion();
    expand_pass.run(sdfg_builder, analysis_mgr);

    // Convert tensor references to pointer-based representations
    sdfg::passes::TensorToPointerConversionPass tensor_conversion;
    tensor_conversion.run(sdfg_builder, analysis_mgr);

    // Configure instrumentation and argument capture plans (none in this case)
    auto instr_plan = sdfg::codegen::InstrumentationPlan::none(sdfg_builder.subject());
    auto arg_plan = sdfg::codegen::ArgCapturePlan::none(sdfg_builder.subject());

    // Generate C code using the configured components
    sdfg::codegen::CCodeGenerator code_gen(
        sdfg_builder.subject(), 
        analysis_mgr, 
        *instr_plan, 
        *arg_plan
    );

    if (!code_gen.generate()) {
        std::cerr << "Failed to generate C code from SDFG" << std::endl;
        return 1;
    }

    // Output generated C code: includes, globals, function definition, and main body
    std::cout << code_gen.includes().str()
              << code_gen.globals().str()
              << code_gen.function_definition() << " {\n"
              << code_gen.main().str() << "}\n";

    return 0;
}

