  for (int i = 0; i < 3; ++i) {
    total += matrix[indices[i]][1];
  }
  return total;
}

int main() {
  int i;
  // Initialize array with ternary operator, same logic but different variable naming
  for (i = 0; i < 10; ++i) {
    values[i] = (nd_int() ? 3 : 5);
  }  

  // Variable renaming and assumption block preserved
  int selected_index = nd_int();
  __CRAB_assume(selected_index >= 0);
  __CRAB_assume(selected_index < 10);
  int extracted_value = values[selected_index];
  __CRAB_assert(extracted_value >= 0);
  __CRAB_assert(extracted_value <= 5);

  // Modify table2 element as before
  data_array2[5][1] = nd_int();  // *

  // Call modified functions
  int computed_val1 = process_data(data_array1);
  __CRAB_assert(computed_val1 <= 400);

  int computed_val2 = aggregate_data(data_array2);
  __CRAB_assert(computed_val2 == 90); // it's not true because of *

  return extracted_value + computed_val1 + computed_val2;
