#include <iostream>
#include <vector>
#include <bitset>
#include <random>
#include <cassert>
#include <algorithm>

using namespace std;

// Constants for matrix dimensions
const int ROWS = 75;
const int COLS = 1000;

int main() {
    // Initialize data structures:
    // - cols[j] represents the j-th column as a bitset of row bits
    // - query_rows[i] stores which columns have a '1' in row i
    vector<bitset<ROWS>> cols(COLS);
    vector<vector<int>> query_rows(ROWS);

    // Use fixed seed for reproducibility
    mt19937_64 rng(123456789ULL);
    bernoulli_distribution coin_flip(0.5);

    // Fill the matrix deterministically
    for (int r = 0; r < ROWS; ++r) {
        for (int c = 0; c < COLS; ++c) {
            if (coin_flip(rng)) {
                cols[c].set(r);
                query_rows[r].push_back(c);
            }
        }
    }

    // Send queries: one per row, listing columns where that row has 1s
    for (int r = 0; r < ROWS; ++r) {
        cout << "? " << query_rows[r].size();
        for (int col_index : query_rows[r]) {
            cout << " " << col_index + 1;  // Convert to 1-based indexing
        }
        cout << endl;
        cout.flush();
    }

    // Signal end of queries
    cout << "@" << endl;
    cout.flush();

    // Read responses
    int response_count;
    cin >> response_count;
    assert(response_count == ROWS);

    vector<bool> received_results(ROWS);
    for (int r = 0; r < ROWS; ++r) {
        int val;
        cin >> val;
        received_results[r] = (val != 0);
    }

    // Reconstruct target bitset from results
    bitset<ROWS> target_pattern;
    for (int r = 0; r < ROWS; ++r) {
        if (received_results[r]) {
            target_pattern.set(r);
        }
    }

    // Search for two columns whose bitwise OR equals the target pattern
    bool found = false;
    for (int c1 = 0; c1 < COLS && !found; ++c1) {
        for (int c2 = c1; c2 < COLS; ++c2) {
            bitset<ROWS> combined = cols[c1] | cols[c2];
            if (combined == target_pattern) {
                cout << "! " << c1 + 1 << " " << c2 + 1 << endl;
                cout.flush();
                found = true;
                break;
            }
        }
    }

    // Safety fallback (should not occur with proper input)
    if (!found) {
        cout << "! 1 1" << endl;
        cout.flush();
    }

    return 0;
}

