namespace vb {
namespace aarch64 {

///
/// @brief Determines if the given 64-bit value consists of a contiguous block of 1-bits starting at bit 0
///
/// @param val Input value to examine
/// @return true if value is non-zero and has the form 2^k - 1 (i.e., all lower k bits set)
static bool isContiguousMask_64(uint64_t const val) VB_NOEXCEPT {
    return (val != 0U) && ((val & (val + 1U)) == 0U);
}

///
/// @brief Determines if the given 64-bit value contains a contiguous block of 1-bits (any position)
///
/// The ones may be shifted left by some amount; not necessarily aligned to LSB.
///
/// @param val Input value to examine
/// @return true if value can be transformed into a contiguous mask via rotation
static bool isRotatedMask_64(uint64_t const val) VB_NOEXCEPT {
    if (val == 0U) return false;
    uint64_t adjusted = (val - 1U) | val;
    return isContiguousMask_64(adjusted);
}

bool processLogicalImmediate(uint64_t imm, bool const is64, uint64_t &encoded) VB_NOEXCEPT {
    uint64_t const maxVal{is64 ? UINT64_MAX : 0xFFFFFFFFU};

    // Special cases: zero and all-ones cannot be encoded using this scheme
    if ((imm == 0U) || (imm >= maxVal)) {
        return false;
    }

    // Determine element size (64 or 32 bits initially)
    uint64_t elemWidth{is64 ? 64U : 32U};

    // First pass: find smallest power-of-two partition where halves differ
    while (elemWidth > 2U) {
        elemWidth >>= 1U;
        uint64_t const halfMask{(1ULL << elemWidth) - 1ULL};
        uint64_t lowPart = imm & halfMask;
        uint64_t highPart = (imm >> elemWidth) & halfMask;

        if (lowPart != highPart) {
            elemWidth <<= 1U; // restore previous size
            break;
        }
    }

    // Mask off to single element width
    uint64_t const fullMask{(elemWidth == 64U) ? UINT64_MAX : ((1ULL << elemWidth) - 1ULL)};
    uint64_t elemValue = imm & fullMask;

    // Compute I (rotation offset) and CTO (count trailing ones)
    uint64_t I_val, CTO_val;

    if (isRotatedMask_64(elemValue)) {
        // Count leading zeros in reversed direction
        I_val = static_cast<uint64_t>(__builtin_ctzll(elemValue));
        assert(I_val < 64 && "ctzll on zero undefined");
        CTO_val = static_cast<uint64_t>(__builtin_ctzll(~(elemValue >> I_val)));
    } else {
        uint64_t inverted = ~elemValue | ~fullMask;
        if (!isRotatedMask_64(inverted)) {
            return false;
        }

        uint64_t CLZ_inv = static_cast<uint64_t>(__builtin_clzll(inverted));
        I_val = 64ULL - CLZ_inv;
        uint64_t CTZ_inv = static_cast<uint64_t>(__builtin_ctzll(inverted));
        CTO_val = (CLZ_inv + CTZ_inv) - (64ULL - elemWidth);
    }

    // Compute Immr: number of right rotations needed to bring canonical form to target
    assert(elemWidth > I_val && "I should be less than element width");
    uint64_t const Immr{((elemWidth - I_val) & (elemWidth - 1U))};

    // Build NImms field
    uint64_t N_field_mask{~(elemWidth - 1ULL) << 1ULL};
    uint64_t NImms_val{N_field_mask | (CTO_val - 1ULL)};

    // Extract N bit (bit 6 of NImms, then invert)
    uint64_t const N_bit{(((NImms_val >> 6U) & 1ULL) ^ 1ULL) << 12U};

    // Final encoding: combine fields
    encoded = N_bit | (Immr << 6U) | (NImms_val & 0x3FULL);
    return true;
}

} // namespace aarch64
} // namespace vb
#endif

