// Forward declarations
class CrashRecoveryContext;

// Thread-local storage for active recovery context
#if defined(LLVM_ENABLE_THREADS) && LLVM_ENABLE_THREADS != 0
using TLSContext = std::thread_local_ptr<CrashRecoveryContext>;
#else
static CrashRecoveryContext* CurrentContext = nullptr;
#endif

// RAII wrapper for crash recovery context activation
class RecoveryGuard {
public:
    explicit RecoveryGuard(CrashRecoveryContext* ctx);
    ~RecoveryGuard();
private:
    CrashRecoveryContext* prev_;
};

// Base cleanup interface
class CleanupBase {
public:
    virtual ~CleanupBase() = default;
    virtual void performCleanup() = 0;
    bool fired = false;
    CleanupBase* next = nullptr;
    CleanupBase* prev = nullptr;
};

// Template cleanup adapter
template<typename F>
class CleanupFn final : public CleanupBase {
public:
    explicit CleanupFn(F&& f) : fn_(std::forward<F>(f)) {}
    void performCleanup() override { fn_(); }
private:
    F fn_;
};

// Internal state for crash recovery
struct RecoveryState {
    std::jmp_buf buffer;
    bool validBuffer = false;
    bool triggered = false;
    int exitCode = 0;
    uintptr_t contextData = 0;
    CrashRecoveryContext* owner = nullptr;
};

// Main crash recovery context class
class CrashRecoveryContext {
public:
    CrashRecoveryContext();
    ~CrashRecoveryContext();

    bool runSafely(std::function<void()> const& fn);
    static CrashRecoveryContext* getCurrent();
    static void enable();
    static void disable();
    static bool isCrash(int code);
    static bool throwIfCrash(int code);

    template<typename F>
    void registerCleanup(F&& f) {
        auto* c = new CleanupFn<F>(std::forward<F>(f));
        linkCleanup(c);
    }

    void unregisterCleanup(CleanupBase* c);

private:
    friend class RecoveryGuard;

    void triggerRecovery(int code, uintptr_t ctx);
    void executeCleanups();

    static void installHandlers();
    static void uninstallHandlers();

    static std::mutex& getMutex();
    static bool enabled_;

    CleanupBase* head_ = nullptr;
    RecoveryState* state_ = nullptr;

    void linkCleanup(CleanupBase* c);
    void unlinkCleanup(CleanupBase* c);
};

// Implementation details below

#if defined(LLVM_ENABLE_THREADS) && LLVM_ENABLE_THREADS != 0
TLSContext tls_context;
#endif

RecoveryGuard::RecoveryGuard(CrashRecoveryContext* ctx) {
#if defined(LLVM_ENABLE_THREADS) && LLVM_ENABLE_THREADS != 0
    prev_ = tls_context.load();
    tls_context.store(ctx);
#else
    prev_ = CurrentContext;
    CurrentContext = ctx;
#endif
}

RecoveryGuard::~RecoveryGuard() {
#if defined(LLVM_ENABLE_THREADS) && LLVM_ENABLE_THREADS != 0
    tls_context.store(prev_);
#else
    CurrentContext = prev_;
#endif
}

void CrashRecoveryContext::linkCleanup(CleanupBase* c) {
    if (!head_) return;
    head_->prev = c;
    c->next = head_;
    head_ = c;
}

void CrashRecoveryContext::unlinkCleanup(CleanupBase* c) {
    if (!c) return;
    if (c == head_) {
        head_ = c->next;
        if (head_) head_->prev = nullptr;
    } else {
        if (c->prev) c->prev->next = c->next;
        if (c->next) c->next->prev = c->prev;
    }
    delete c;
}

CrashRecoveryContext::CrashRecoveryContext() {
    state_ = new RecoveryState{ .owner = this };
}

CrashRecoveryContext::~CrashRecoveryContext() {
    executeCleanups();
    delete state_;
}

void CrashRecoveryContext::executeCleanups() {
    CleanupBase* cur = head_;
    while (cur) {
        CleanupBase* tmp = cur;
        cur = cur->next;
        if (!tmp->fired) {
            tmp->fired = true;
            tmp->performCleanup();
        }
    }
}

void CrashRecoveryContext::triggerRecovery(int code, uintptr_t ctx) {
    assert(!state_->triggered && "Already triggered!");
    state_->triggered = true;
    state_->exitCode = code;
    state_->contextData = ctx;

    if (state_->validBuffer) {
        longjmp(state_->buffer, 1);
    }
}

bool CrashRecoveryContext::runSafely(std::function<void()> const& fn) {
    if (!enabled_) {
        fn();
        return true;
    }

    RecoveryGuard guard(this);
    state_->validBuffer = true;

    int result = setjmp(state_->buffer);
    if (result != 0) {
        return false;
    }

    try {
        fn();
    } catch (...) {
        // Simulate crash behavior in non-signal environments
        triggerRecovery(1, 0);
    }

    return true;
}

CrashRecoveryContext* CrashRecoveryContext::getCurrent() {
#if defined(LLVM_ENABLE_THREADS) && LLVM_ENABLE_THREADS != 0
    return tls_context.load();
#else
    return CurrentContext;
#endif
}

void CrashRecoveryContext::enable() {
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);
    if (enabled_) return;
    enabled_ = true;
    installHandlers();
}

void CrashRecoveryContext::disable() {
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);
    if (!enabled_) return;
    enabled_ = false;
    uninstallHandlers();
}

bool CrashRecoveryContext::isCrash(int code) {
#if defined(_WIN32)
    unsigned severity = (code >> 30) & 3;
    return severity == 3 || severity == 2; // error or critical
#else
    return code > 128;
#endif
}

bool CrashRecoveryContext::throwIfCrash(int code) {
    if (!isCrash(code)) return false;
#if defined(_WIN32)
    RaiseException(code, 0, 0, nullptr);
#else
    raise(code - 128);
#endif
    return true;
}

void CrashRecoveryContext::unregisterCleanup(CleanupBase* c) {
    unlinkCleanup(c);
}

// Platform-specific handlers

#if defined(_MSC_VER)

static int sehFilter(EXCEPTION_POINTERS* exp) {
    auto* ctx = getCurrent();
    if (!ctx) {
        disable();
        return EXCEPTION_CONTINUE_SEARCH;
    }
    int code = static_cast<int>(exp->ExceptionRecord->ExceptionCode);
    if ((code & 0xF0000000) == 0xE0000000)
        code &= ~0xF0000000;
    ctx->triggerRecovery(code, reinterpret_cast<uintptr_t>(exp));
    return EXCEPTION_EXECUTE_HANDLER;
}

void CrashRecoveryContext::installHandlers() {}
void CrashRecoveryContext::uninstallHandlers() {}

#elif defined(_WIN32)

static LONG CALLBACK vehHandler(EXCEPTION_POINTERS* exp) {
    constexpr ULONG DbgPrintWideC = 0x4001000A;
    switch (exp->ExceptionRecord->ExceptionCode) {
        case DBG_PRINTEXCEPTION_C:
        case DbgPrintWideC:
        case 0x406D1388:
            return EXCEPTION_CONTINUE_EXECUTION;
    }

    auto* ctx = getCurrent();
    if (!ctx) {
        disable();
        return EXCEPTION_CONTINUE_SEARCH;
    }

    int code = static_cast<int>(exp->ExceptionRecord->ExceptionCode);
    if ((code & 0xF0000000) == 0xE0000000)
        code &= ~0xF0000000;

    ctx->triggerRecovery(code, reinterpret_cast<uintptr_t>(exp));
    llvm_unreachable("Should not reach here");
}

static void* sVehHandle = nullptr;

void CrashRecoveryContext::installHandlers() {
    sVehHandle = AddVectoredExceptionHandler(1, vehHandler);
}

void CrashRecoveryContext::uninstallHandlers() {
    if (sVehHandle) {
        RemoveVectoredExceptionHandler(sVehHandle);
        sVehHandle = nullptr;
    }
}

#else // POSIX

static std::vector<int> const signals = { SIGABRT, SIGBUS, SIGFPE, SIGILL, SIGSEGV, SIGTRAP };

static void sigHandler(int sig) {
    auto* ctx = getCurrent();
    if (!ctx) {
        disable();
        raise(sig);
        return;
    }

    sigset_t mask;
    sigemptyset(&mask);
    sigaddset(&mask, sig);
    sigprocmask(SIG_UNBLOCK, &mask, nullptr);

    int code = 128 + sig;
    if (sig == SIGPIPE) code = 141; // EX_IOERR approx
    ctx->triggerRecovery(code, sig);
}

void CrashRecoveryContext::installHandlers() {
    struct sigaction sa{};
    sa.sa_handler = sigHandler;
    for (int sig : signals) {
        sigaction(sig, &sa, nullptr);
    }
}

void CrashRecoveryContext::uninstallHandlers() {
    for (int sig : signals) {
        signal(sig, SIG_DFL);
    }
}

#endif

bool CrashRecoveryContext::enabled_ = false;

} // namespace detail

using detail::CrashRecoveryContext;

} // namespace llvm

