ZoneIo::ZoneIo(HANDLE channel, __int64 position)
{
    this->channel = channel;
    this->currentPosition = position;
}

void ZoneIo::write(byteArray data, int length)
{
    ByteBuffer* tempBuffer = ByteBuffer::wrap(data);
    // Temporarily adjust buffer state for writing
    tempBuffer->order(ZonedChunkStorage::BYTEORDER);
    tempBuffer->limit(length);
    tempBuffer->position(0);
    write(tempBuffer, length);
    delete tempBuffer;
}

void ZoneIo::write(ByteBuffer* buffer, int size)
{
    DWORD bytesActuallyWritten = 0;

    // Move file pointer to current logical position
    LONG highPart = static_cast<LONG>(currentPosition >> 32);
    SetFilePointer(channel, static_cast<LONG>(currentPosition & 0xFFFFFFFF), &highPart, FILE_BEGIN);

    // Perform the actual write operation
    WriteFile(channel, buffer->getBuffer(), size, &bytesActuallyWritten, nullptr);

    // Update internal position tracker
    currentPosition += size;
}

ByteBuffer* ZoneIo::read(int requestedSize)
{
    DWORD bytesRead = 0;

    // Allocate new byte array and wrap it in a ByteBuffer
    byteArray bufferData = byteArray(requestedSize);
    ByteBuffer* resultBuffer = ByteBuffer::wrap(bufferData);

    // Configure buffer for reading
    resultBuffer->order(ZonedChunkStorage::BYTEORDER);
    resultBuffer->limit(requestedSize);
    resultBuffer->position(0);

    // Move file pointer and perform read
    LONG highPart = static_cast<LONG>(currentPosition >> 32);
    SetFilePointer(channel, static_cast<LONG>(currentPosition & 0xFFFFFFFF), &highPart, FILE_BEGIN);

    ReadFile(channel, resultBuffer->getBuffer(), requestedSize, &bytesRead, nullptr);

    // Update position after successful read
    currentPosition += requestedSize;

    return resultBuffer;
}

