// Helper function to find the first ancestor that does not allow caching
TFx *TPassiveCacheManager::getNotAllowingAncestor(TFx *fx) {
  int outputPortCount = fx->getOutputConnectionCount();

  // Iterate through all output connections
  for (int i = 0; i < outputPortCount; ++i) {
    TFxPort *port = fx->getOutputConnection(i);
    TRasterFx *downstreamFx = static_cast<TRasterFx *>(port->getOwnerFx());

    // Find which input port of downstreamFx is connected
    int inputPortIndex = -1;
    int inputPortCount = downstreamFx->getInputPortCount();
    for (int j = 0; j < inputPortCount; ++j) {
      if (downstreamFx->getInputPort(j) == port) {
        inputPortIndex = j;
        break;
      }
    }

    if (inputPortIndex >= 0 && !downstreamFx->allowUserCacheOnPort(inputPortIndex))
      return downstreamFx;

    TFx *recursiveResult = getNotAllowingAncestor(downstreamFx);
    if (recursiveResult)
      return recursiveResult;
  }

  return nullptr;
}

//*****************************************************************************************
//    Custom Table Container Implementation
//*****************************************************************************************
template <typename RowKey, typename ColKey, typename Val>
class CacheTable {
public:
  using Row = std::map<ColKey, Val>;
private:
  std::map<RowKey, Row> m_data;
  friend class FullIterator;
  friend class ColumnIterator;
public:
  class FullIterator {
  protected:
    CacheTable *m_owner;
    typename std::map<RowKey, Row>::iterator m_rowIter;
    typename Row::iterator m_colIter;

    FullIterator(CacheTable *owner) : m_owner(owner) {}

    void normalize() {
      while (m_rowIter != m_owner->m_data.end() && m_colIter == m_rowIter->second.end()) {
        ++m_rowIter;
        if (m_rowIter != m_owner->m_data.end())
          m_colIter = m_rowIter->second.begin();
      }
    }

  public:
    FullIterator(CacheTable *owner, bool begin = true) : m_owner(owner) {
      if (begin) {
        m_rowIter = m_owner->m_data.begin();
        if (m_rowIter != m_owner->m_data.end())
          m_colIter = m_rowIter->second.begin();
        normalize();
      }
    }

    const RowKey &rowKey() const { return m_rowIter->first; }
    const ColKey &colKey() const { return m_colIter->first; }

    FullIterator& operator++() {
      ++m_colIter;
      normalize();
      return *this;
    }

    operator bool() const { return m_rowIter != m_owner->m_data.end(); }
    Val &operator*() { return m_colIter->second; }
    Val *operator->() { return &m_colIter->second; }

    bool operator==(const FullIterator &other) const {
      return m_colIter == other.m_colIter;
    }

    bool operator!=(const FullIterator &other) const {
      return !(*this == other);
    }
  };

  class ColumnIterator : public FullIterator {
    ColKey m_columnKey;
  public:
    ColumnIterator(CacheTable *owner, const ColKey &key) : FullIterator(owner, false), m_columnKey(key) {
      FullIterator::m_rowIter = owner->m_data.begin();
      while (FullIterator::m_rowIter != owner->m_data.end()) {
        FullIterator::m_colIter = FullIterator::m_rowIter->second.find(m_columnKey);
        if (FullIterator::m_colIter != FullIterator::m_rowIter->second.end())
          break;
        ++FullIterator::m_rowIter;
      }
    }

    ColumnIterator& operator++() override {
      ++FullIterator::m_rowIter;
      while (FullIterator::m_rowIter != FullIterator::m_owner->m_data.end()) {
        FullIterator::m_colIter = FullIterator::m_rowIter->second.find(m_columnKey);
        if (FullIterator::m_colIter != FullIterator::m_rowIter->second.end())
          break;
        ++FullIterator::m_rowIter;
      }
      return *this;
    }
  };

  class RowRangeIterator : public FullIterator {
  public:
    RowRangeIterator(CacheTable *owner, const RowKey &key) : FullIterator(owner, false) {
      FullIterator::m_rowIter = owner->m_data.find(key);
      if (FullIterator::m_rowIter != owner->m_data.end())
        FullIterator::m_colIter = FullIterator::m_rowIter->second.begin();
    }

    RowRangeIterator& operator++() override {
      ++FullIterator::m_colIter;
      return *this;
    }

    operator bool() const override {
      return FullIterator::m_rowIter != FullIterator::m_owner->m_data.end() &&
             FullIterator::m_colIter != FullIterator::m_rowIter->second.end();
    }
  };

public:
  CacheTable() = default;
  ~CacheTable() = default;

  std::map<RowKey, Row> &internalMap() { return m_data; }

  FullIterator begin() { return FullIterator(this); }
  RowRangeIterator rowBegin(const RowKey &r) { return RowRangeIterator(this, r); }
  ColumnIterator colBegin(const ColKey &c) { return ColumnIterator(this, c); }

  Val &at(const RowKey &r, const ColKey &c) { return m_data[r][c]; }

  FullIterator add(const RowKey &r, const ColKey &c, const Val &value) {
    FullIterator it(this, false);
    auto rowPair = m_data.emplace(r, Row{});
    it.m_rowIter = rowPair.first;
    auto colPair = it.m_rowIter->second.emplace(c, value);
    it.m_colIter = colPair.first;
    return it;
  }

  FullIterator remove(const FullIterator &it) {
    FullIterator nextIt(it);
    ++nextIt;
    it.m_rowIter->second.erase(it.m_colIter);
    if (it.m_rowIter->second.empty()) {
      m_data.erase(it.m_rowIter);
    }
    return nextIt;
  }

  void removeColumn(const ColKey &c) {
    ColumnIterator it(this, c);
    while (it) {
      auto currentRow = it.m_rowIter;
      currentRow->second.erase(it.m_colIter);
      ++it;
      if (currentRow->second.empty())
        m_data.erase(currentRow);
    }
  }

  void removeRow(const RowKey &r) { m_data.erase(r); }
  void clear() { m_data.clear(); }
};

//---------------------------------------------------------------------------
// Resource wrapper with lock management
struct CachedResourceGuard {
  TCacheResourceP m_resource;

  explicit CachedResourceGuard(const TCacheResourceP &res) : m_resource(res) {
    if (m_resource) m_resource->addLock();
  }

  CachedResourceGuard(const CachedResourceGuard &other) : m_resource(other.m_resource) {
    if (m_resource) m_resource->addLock();
  }

  ~CachedResourceGuard() {
    if (m_resource) m_resource->releaseLock();
  }

  CachedResourceGuard &operator=(const CachedResourceGuard &src) {
    if (src.m_resource) src.m_resource->addLock();
    if (m_resource) m_resource->releaseLock();
    m_resource = src.m_resource;
    return *this;
  }

  explicit operator bool() const { return static_cast<bool>(m_resource); }

  bool operator<(const CachedResourceGuard &other) const {
    return m_resource.getPointer() < other.m_resource.getPointer();
  }

  TCacheResource *operator->() const { return m_resource.getPointer(); }
  TCacheResource &operator*() const { return *m_resource.getPointer(); }
};

using ResourceSet = std::set<CachedResourceGuard>;
using ResourcesMap = CacheTable<std::string, int, ResourceSet>;

