TPassiveCacheManager::TPassiveCacheManager()
#ifdef USE_SQLITE_HDPOOL
    : m_currentStorageMode(ON_DISK)
#else
    : m_currentStorageMode(IN_MEMORY)
#endif
    , m_active(true)
    , m_descriptorCallback(nullptr)
    , m_mutex(QMutex::Recursive)
    , m_resourceHolder(new ResourcesContainer) {
  reset();
}

TPassiveCacheManager::~TPassiveCacheManager() {
  delete m_resourceHolder;
}

TPassiveCacheManager *TPassiveCacheManager::instance() {
  static TPassiveCacheManager singletonInstance;
  return &singletonInstance;
}

void TPassiveCacheManager::setContextName(unsigned long renderId,
                                          const std::string &name) {
  QMutexLocker lock(&m_mutex);

  auto it = m_contextNames.find(name);
  if (it == m_contextNames.end())
    it = m_contextNames.emplace(name, 0).first;

  it->second = !it->second;
  m_contextIdsByRenderId[renderId] =
      name + "%" + std::to_string(it->second);
}

std::string TPassiveCacheManager::getContextName() {
  QMutexLocker lock(&m_mutex);

  auto it = m_contextIdsByRenderId.find(TRenderer::renderId());
  if (it == m_contextIdsByRenderId.end())
    return "";
  return it->second;
}

void TPassiveCacheManager::setEnabled(bool enabled) { m_active = enabled; }
bool TPassiveCacheManager::isEnabled() const { return m_active; }

void TPassiveCacheManager::setStorageMode(StorageFlag mode) {
  m_currentStorageMode = mode;
}

TPassiveCacheManager::StorageFlag TPassiveCacheManager::getStorageMode() const {
  return m_currentStorageMode;
}

void TPassiveCacheManager::setTreeDescriptor(TreeDescriptor callback) {
  m_descriptorCallback = callback;
}

int TPassiveCacheManager::generateNewCacheId() {
  return ++m_lastCacheId;
}

int TPassiveCacheManager::updateCacheId(int id) {
  if (m_updatingIds)
    m_lastCacheId = std::max(m_lastCacheId, id);
  else
    id = generateNewCacheId();
  return id;
}

void TPassiveCacheManager::onSceneLoaded() {
  m_updatingIds = false;

#ifndef USE_SQLITE_HDPOOL
  for (auto &data : m_fxInfoList) {
    if (data.m_fx)
      (*m_descriptorCallback)(data.m_treeDesc, data.m_fx);
  }
#endif
}

void TPassiveCacheManager::ensureFxDataExists(int &index) {
  if (index >= 0) return;
  QMutexLocker lock(&m_mutex);
  m_fxInfoList.emplace_back();
  index = static_cast<int>(m_fxInfoList.size()) - 1;
}

int TPassiveCacheManager::registerCachedFx(TFx *fx, int cacheId) {
  int &idx = fx->getAttributes()->passiveCacheDataIdx();
  ensureFxDataExists(idx);
  FxData &data = m_fxInfoList[idx];
  data.m_fx = fx;
  data.m_cacheFlag = m_currentStorageMode;
  data.m_cacheIdentifier = updateCacheId(cacheId);
  return idx;
}

void TPassiveCacheManager::reset() {
  m_updatingIds = true;
  m_lastCacheId = 0;
  m_fxInfoList.clear();
  m_resourceHolder->getTable().clear();
}

bool TPassiveCacheManager::isCachingEnabled(TFx *fx) {
  int idx = fx->getAttributes()->passiveCacheDataIdx();
  if (idx < 0) return false;
  assert(idx < static_cast<int>(m_fxInfoList.size()));
  QMutexLocker lock(&m_mutex);
  return m_fxInfoList[idx].m_cacheFlag > 0;
}

int TPassiveCacheManager::getCacheId(TFx *fx) {
  int idx = fx->getAttributes()->passiveCacheDataIdx();
  if (idx < 0) return 0;
  assert(idx < static_cast<int>(m_fxInfoList.size()));
  return m_fxInfoList[idx].m_cacheIdentifier;
}

TPassiveCacheManager::StorageFlag TPassiveCacheManager::getStorageModeForFx(TFx *fx) {
  int idx = fx->getAttributes()->passiveCacheDataIdx();
  if (idx < 0) return NONE;
  QMutexLocker lock(&m_mutex);
  return static_cast<StorageFlag>(m_fxInfoList[idx].m_cacheFlag);
}

void TPassiveCacheManager::activateCache(TFx *fx) {
  int &idx = fx->getAttributes()->passiveCacheDataIdx();
  ensureFxDataExists(idx);
  FxData &data = m_fxInfoList[idx];
  QMutexLocker lock(&m_mutex);

#ifdef DIAGNOSTICS
  DIAGNOSTICS_STR("#activity.txt | " + QTime::currentTime().toString() + " " +
                  QString("Enable Cache"));
#endif

  StorageFlag flag = getStorageMode();
  if (flag != NONE) {
    UCHAR &storedFlag = data.m_cacheFlag;
    UCHAR previousFlag = storedFlag;
    storedFlag |= static_cast<UCHAR>(flag);

    if (data.m_cacheIdentifier == 0)
      data.m_cacheIdentifier = generateNewCacheId();

    if ((storedFlag & ON_DISK) && !(previousFlag & ON_DISK)) {
      ResourcesMap::ColumnIterator it =
          m_resourceHolder->getTable().colBegin(data.m_cacheIdentifier);
      for (; it; ++it) {
        for (auto &resource : *it)
          resource->enableBackup();
      }
    }

#ifndef USE_SQLITE_HDPOOL
    if ((storedFlag & IN_MEMORY) && !(previousFlag & IN_MEMORY)) {
      data.m_fx = fx;
      (*m_descriptorCallback)(data.m_treeDesc, data.m_fx);
    }
#endif
  }
}

void TPassiveCacheManager::deactivateCache(TFx *fx) {
  int idx = fx->getAttributes()->passiveCacheDataIdx();
  if (idx < 0) return;
  FxData &data = m_fxInfoList[idx];
  QMutexLocker lock(&m_mutex);

#ifdef DIAGNOSTICS
  DIAGNOSTICS_STR("#activity.txt | " + QTime::currentTime().toString() + " " +
                  QString("Disable Cache"));
#endif

  StorageFlag flag = getStorageMode();
  if (flag != NONE) {
    UCHAR &storedFlag = data.m_cacheFlag;
    UCHAR previousFlag = storedFlag;
    storedFlag &= ~static_cast<UCHAR>(flag);

    if ((previousFlag & IN_MEMORY) && !(storedFlag & IN_MEMORY)) {
      m_resourceHolder->getTable().removeColumn(data.m_cacheIdentifier);
      data.m_fx.reset();
      data.m_treeDesc.clear();
    }

#ifdef USE_SQLITE_HDPOOL
    if ((previousFlag & ON_DISK) && !(storedFlag & ON_DISK))
      TCacheResourcePool::instance()->releaseReferences(
          "P" + QString::number(data.m_cacheIdentifier));
#endif
  }
}

void TPassiveCacheManager::toggleCacheState(TFx *fx) {
  int &idx = fx->getAttributes()->passiveCacheDataIdx();
  ensureFxDataExists(idx);
  FxData &data = m_fxInfoList[idx];
  QMutexLocker lock(&m_mutex);

  StorageFlag flag = getStorageMode();
  if (flag != NONE) {
    UCHAR &storedFlag = data.m_cacheFlag;
    UCHAR previousFlag = storedFlag;
    storedFlag ^= static_cast<UCHAR>(flag);

#ifdef DIAGNOSTICS
    DIAGNOSTICS_STR("#activity.txt | " + QTime::currentTime().toString() + " " +
                    QString("Toggle Cache (now ") +
                    ((storedFlag & IN_MEMORY) ? "enabled)" : "disabled)"));
#endif

    if (data.m_cacheIdentifier == 0)
      data.m_cacheIdentifier = generateNewCacheId();

    if ((storedFlag & ON_DISK) && !(previousFlag & ON_DISK)) {
      ResourcesMap::ColumnIterator it =
          m_resourceHolder->getTable().colBegin(data.m_cacheIdentifier);
      for (; it; ++it) {
        for (auto &resource : *it)
          resource->enableBackup();
      }
    }

    if ((previousFlag & IN_MEMORY) && !(storedFlag & IN_MEMORY)) {
      m_resourceHolder->getTable().removeColumn(data.m_cacheIdentifier);
      data.m_fx.reset();
      data.m_treeDesc.clear();
    }

#ifndef USE_SQLITE_HDPOOL
    if ((storedFlag & IN_MEMORY) && !(previousFlag & IN_MEMORY)) {
      data.m_fx = fx;
      (*m_descriptorCallback)(data.m_treeDesc, data.m_fx);
    }
#endif

#ifdef USE_SQLITE_HDPOOL
    if ((previousFlag & ON_DISK) && !(storedFlag & ON_DISK))
      TCacheResourcePool::instance()->releaseReferences(
          "P" + QString::number(data.m_cacheIdentifier));
#endif
  }
}

void TPassiveCacheManager::invalidateLevel(const std::string &levelName) {
  QMutexLocker lock(&m_mutex);

  ResourcesMap &table = m_resourceHolder->getTable();
  ResourcesMap::FullIterator it(table.begin());
  while (it) {
    ResourceSet &resources = *it;
    auto jt = resources.begin();
    while (jt != resources.end()) {
      if ((*jt)->getName().find(levelName) != std::string::npos) {
        jt = resources.erase(jt);
      } else {
        ++jt;
      }
    }

    if (resources.empty()) {
      it = table.remove(it);
    } else {
      ++it;
    }
  }

#ifdef USE_SQLITE_HDPOOL
  m_invalidatedLevels.insert(levelName);
#endif
}

void TPassiveCacheManager::forceInvalidateAll() {
#ifdef USE_SQLITE_HDPOOL
  TCacheResourcePool *pool = TCacheResourcePool::instance();
  for (const auto &level : m_invalidatedLevels)
    pool->clearKeyword(level);
  m_invalidatedLevels.clear();
#endif
}

void TPassiveCacheManager::onFxChanged(const TFxP &fx) {
#ifndef USE_SQLITE_HDPOOL
  std::string currentDesc;
  (*m_descriptorCallback)(currentDesc, fx);

  for (auto &data : m_fxInfoList) {
    if (!data.m_fx) continue;
    if (data.m_treeDesc.find(currentDesc) != std::string::npos)
      m_resourceHolder->getTable().removeColumn(data.m_cacheIdentifier);
  }
#endif
}

void TPassiveCacheManager::onXsheetStructureChanged() {
#ifndef USE_SQLITE_HDPOOL
#ifdef DIAGNOSTICS
  DIAGNOSTICS_STR("#activity.txt | " + QTime::currentTime().toString() +
                  " XSheet structure changed");
#endif

  for (auto &data : m_fxInfoList) {
    if (!data.m_fx) continue;
    std::string newDesc;
    (*m_descriptorCallback)(newDesc, data.m_fx);
    if (data.m_treeDesc != newDesc) {
      m_resourceHolder->getTable().removeColumn(data.m_cacheIdentifier);
      data.m_treeDesc = newDesc;
    }
  }
#endif
}

void TPassiveCacheManager::acquireResource(TCacheResourceP &resource,
                                           const std::string &alias,
                                           const TFxP &fx,
                                           double frame,
                                           const TRenderSettings &rs,
                                           ResourceDeclaration *resData) {
  if (!(m_active && fx && rs.m_userCachable)) return;
  StorageFlag flag = getStorageModeForFx(fx.getPointer());
  if (flag == NONE) return;

  std::string contextName = getContextName();
  if (contextName.empty()) return;

  if (!resource)
    resource = TCacheResourceP(alias, true);

#ifdef USE_SQLITE_HDPOOL
  if (flag & ON_DISK) {
    resource->enableBackup();
    int cacheId = m_fxInfoList[fx->getAttributes()->passiveCacheDataIdx()].m_cacheIdentifier;
    TCacheResourcePool::instance()->addReference(resource, "P" + QString::number(cacheId));
  }
#endif

  if (flag & IN_MEMORY) {
    QMutexLocker lock(&m_mutex);
    int cacheId = m_fxInfoList[fx->getAttributes()->passiveCacheDataIdx()].m_cacheIdentifier;
    m_resourceHolder->getTable().add(contextName, cacheId, ResourceSet{CachedResourceGuard(resource)});
  }
}

void TPassiveCacheManager::removeContextsWithPrefix(const std::string &prefix) {
  QMutexLocker lock(&m_mutex);

#ifdef DIAGNOSTICS
  DIAGNOSTICS_STR("#activity.txt | " + QTime::currentTime().toString() +
                  " Release Context Name (" + QString::fromStdString(prefix) +
                  ")");
#endif

  std::string prefixPlusOne = prefix;
  prefixPlusOne[prefix.size() - 1]++;

  {
    auto start = m_contextNames.lower_bound(prefix);
    auto end = m_contextNames.lower_bound(prefixPlusOne);
    m_contextNames.erase(start, end);
  }

  ResourcesMap &table = m_resourceHolder->getTable();
  auto rows = &table.internalMap();
  auto startIt = rows->lower_bound(prefix);
  auto endIt = rows->lower_bound(prefixPlusOne);

  std::string tempName("T");
  for (auto iter = startIt; iter != endIt; ++iter) {
    ResourcesMap::RowRangeIterator rowIt(&table, iter->first);
    for (; rowIt; ++rowIt)
      table.add(tempName, rowIt.colKey(), ResourceSet{*rowIt});
  }

  if (endIt == rows->end())
    rows->erase(startIt, rows->lower_bound(prefixPlusOne));
  else
    rows->erase(startIt, ++rows->lower_bound(prefixPlusOne));
}

void TPassiveCacheManager::cleanupOldResources() {
  QMutexLocker lock(&m_mutex);

  std::string currentContext = getContextName();
  if (currentContext.empty()) return;

  char &lastChar = currentContext.back();
  lastChar = '0' + !(lastChar - '0');

  m_resourceHolder->getTable().removeRow(currentContext);
  m_resourceHolder->getTable().removeRow("T");
}

void TPassiveCacheManager::onRenderInstanceStart(unsigned long renderId) {
  TFxCacheManagerDelegate::onRenderInstanceStart(renderId);
#ifdef USE_SQLITE_HDPOOL
  forceInvalidateAll();
#endif
}

void TPassiveCacheManager::onRenderInstanceEnd(unsigned long renderId) {
  QMutexLocker lock(&m_mutex);
  cleanupOldResources();
  m_contextIdsByRenderId.erase(renderId);
}

void TPassiveCacheManager::onRenderStatusEnd(int renderStatus) {
  if (renderStatus == TRenderer::TESTRUN)
    cleanupOldResources();
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to record a swap operation between two positions
struct Operation {
    int fromRow, fromCol;
    int toRow, toCol;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    const int ROWS = 30;
    vector<vector<int>> pyramid(ROWS);

    // Read input pyramid data
    for (int row = 0; row < ROWS; ++row) {
        pyramid[row].reserve(row + 1);
        for (int col = 0; col <= row; ++col) {
            int value;
            cin >> value;
            pyramid[row].push_back(value);
        }
    }

    vector<Operation> swaps;
    // Pre-allocate space for operations (safe upper bound)
    swaps.reserve(10000);

    // Build min-heap property from bottom to top
    // Start from second-last row and move upward
    for (int r = ROWS - 2; r >= 0; --r) {
        for (int c = 0; c <= r; ++c) {
            int currentRow = r;
            int currentCol = c;

            // Sift down the element at (currentRow, currentCol)
            while (currentRow < ROWS - 1) {
                int childRow = currentRow + 1;
                int leftChildCol = currentCol;
                int rightChildCol = currentCol + 1;

                int parentVal = pyramid[currentRow][currentCol];
                int leftVal = pyramid[childRow][leftChildCol];
                int rightVal = pyramid[childRow][rightChildCol];

                // Check if heap property is satisfied: parent <= both children
                if (parentVal <= leftVal && parentVal <= rightVal) {
                    break;
                }

                // Determine which child is smaller for swapping
                if (leftVal <= rightVal) {
                    // Swap with left child
                    swaps.push_back({currentRow, currentCol, childRow, leftChildCol});
                    swap(pyramid[currentRow][currentCol], pyramid[childRow][leftChildCol]);

                    // Move down to the left child position
                    currentRow = childRow;
                    currentCol = leftChildCol;
                } else {
                    // Swap with right child
                    swaps.push_back({currentRow, currentCol, childRow, rightChildCol});
                    swap(pyramid[currentRow][currentCol], pyramid[childRow][rightChildCol]);

                    // Move down to the right child position
                    currentRow = childRow;
                    currentCol = rightChildCol;
                }
            }
        }
    }

    // Output number of swaps followed by each swap operation
    cout << swaps.size() << "\n";
    for (const auto& op : swaps) {
        cout << op.fromRow << " " << op.fromCol << " " 
             << op.toRow << " " << op.toCol << "\n";
    }

    return 0;
}

