// Structure to hold spatial hash references (renamed for variety)
struct ParticleIndex {
    uint32_t bucket;
    int particleId;
};

class OptimizedGridSimulator : public Simulator {
private:
    // Adjusted thread count for potential hardware variations
    int threads = 16;

    // Spatial Hashing Constants (same values, different naming)
    static constexpr int BUCKET_COUNT = 16384; 
    static constexpr int BUCKET_MASK = BUCKET_COUNT - 1;

    // Data buffers with renamed variables
    std::vector<ParticleIndex> indices;
    std::vector<int> bucketBegin;
    std::vector<int> bucketEnd;

    // Reordered buffer for better cache usage
    std::vector<Particle> orderedParticles;

public:
    void init(int particleCount, StepParameters params) override {
        omp_set_num_threads(threads);

        indices.resize(particleCount);
        orderedParticles.resize(particleCount);

        bucketBegin.resize(BUCKET_COUNT);
        bucketEnd.resize(BUCKET_COUNT);
    }

    void simulateStep(std::vector<Particle> &particles,
                      std::vector<Particle> &newParticles,
                      StepParameters params) override {
        int count = static_cast<int>(particles.size());

        // Ensure buffers match current particle count
        if (static_cast<int>(indices.size()) != count) {
            indices.resize(count);
            orderedParticles.resize(count);
        }

        // Use finer grid spacing: half the interaction radius
        float gridSize = params.cullRadius * 0.5f;
        float invGridSize = 1.0f / gridSize;

        // Phase 1: Compute bucket assignments in parallel
        #pragma omp parallel for
        for (int idx = 0; idx < count; ++idx) {
            // Compute grid coordinates using floor for negative coords
            int cellX = static_cast<int>(std::floor(particles[idx].position.x * invGridSize));
            int cellY = static_cast<int>(std::floor(particles[idx].position.y * invGridSize));

            // Combine coordinates into hash using distinct primes
            uint32_t h = ((cellX * 73856093) ^ (cellY * 19349663)) & BUCKET_MASK;

            indices[idx] = {h, idx};
        }

        // Phase 2: Sort by bucket index (serial sort is acceptable here)
        std::sort(indices.begin(), indices.end(), 
                  [](const ParticleIndex& lhs, const ParticleIndex& rhs) {
                      return lhs.bucket < rhs.bucket;
                  });

        // Phase 3: Prepare reordered particle array and bucket boundaries
        std::fill(bucketBegin.begin(), bucketBegin.end(), -1);

        // Parallel copy into ordered buffer
        #pragma omp parallel 
        {
            #pragma omp for
            for (int i = 0; i < count; ++i) {
                orderedParticles[i] = particles[indices[i].particleId];
            }
        }

        // Sequential pass to set bucket start/end positions
        for (int i = 0; i < count; ++i) {
            uint32_t b = indices[i].bucket;
            if (bucketBegin[b] == -1) bucketBegin[b] = i;
            bucketEnd[b] = i + 1;
        }

        float cullRadiusSq = params.cullRadius * params.cullRadius;

        // Phase 4: Force computation with optimized neighbor search
        #pragma omp parallel for schedule(dynamic, 32)
        for (int pIdx = 0; pIdx < count; ++pIdx) {
            const Particle& current = particles[pIdx];
            Vec2 netForce = {0.0f, 0.0f};

            // Determine grid cell of current particle
            int cellX = static_cast<int>(std::floor(current.position.x * invGridSize));
            int cellY = static_cast<int>(std::floor(current.position.y * invGridSize));

            // Examine 5x5 neighborhood of cells
            for (int offsetY = -2; offsetY <= 2; ++offsetY) {
                for (int offsetX = -2; offsetX <= 2; ++offsetX) {
                    uint32_t bucket = (((cellX + offsetX) * 73856093) ^ 
                                      ((cellY + offsetY) * 19349663)) & BUCKET_MASK;

                    int begin = bucketBegin[bucket];
                    if (begin == -1) continue;
                    int end = bucketEnd[bucket];

                    for (int j = begin; j < end; ++j) {
                        // Skip self-interaction
                        if (indices[j].particleId == pIdx) continue;

                        // Access neighbor particle from ordered buffer
                        const Particle& neighbor = orderedParticles[j];

                        // Compute relative position
                        float dx = current.position.x - neighbor.position.x;
                        float dy = current.position.y - neighbor.position.y;
                        float distSq = dx*dx + dy*dy;

                        // Apply force only if within interaction radius
                        if (distSq < cullRadiusSq) {
                            netForce += computeForce(current, neighbor, params.cullRadius);
                        }
                    }
                }
            }

            // Update particle state
            newParticles[pIdx] = updateParticle(current, netForce, params.deltaTime);
        }
    }
};

// Factory function to create simulator instance
Simulator* createSimulator() {
    return new OptimizedGridSimulator();
}

