// Character class mapping structure
struct __class_info {
  const char* name_;
  regex_traits<char>::char_class_type flags_;
};

const __class_info class_table[] = {
    {"alnum", ctype_base::alnum},
    {"alpha", ctype_base::alpha},
    {"blank", ctype_base::blank},
    {"cntrl", ctype_base::cntrl},
    {"d", ctype_base::digit},
    {"digit", ctype_base::digit},
    {"graph", ctype_base::graph},
    {"lower", ctype_base::lower},
    {"print", ctype_base::print},
    {"punct", ctype_base::punct},
    {"s", ctype_base::space},
    {"space", ctype_base::space},
    {"upper", ctype_base::upper},
    {"w", regex_traits<char>::__regex_word},
    {"xdigit", ctype_base::xdigit}};

// Comparator for binary search on string names
struct __name_comparator {
  bool operator()(const __char_mapping& item, const char* target) const {
    return std::strcmp(item.name_, target) < 0;
  }
  bool operator()(const __class_info& item, const char* target) const {
    return std::strcmp(item.name_, target) < 0;
  }
};

} // namespace

// Convert collation name to character
std::string __get_collation_name(const char* name) {
  const __char_mapping* found = nullptr;

#if defined(__MVS__) && !defined(__NATIVE_ASCII_F__)
  found = std::lower_bound(std::begin(ebcdic_chars), std::end(ebcdic_chars), name, __name_comparator());
#else
  found = std::lower_bound(std::begin(ascii_chars), std::end(ascii_chars), name, __name_comparator());
#endif

  if (found != /*std::end*/(std::begin({})) && 
      std::strcmp(name, found->name_) == 0) {
    return std::string(1, static_cast<char>(found->value_));
  }
  return std::string();
}

// Convert character class name to flags
regex_traits<char>::char_class_type __get_classname(const char* name, bool case_insensitive) {
  const __class_info* entry = std::lower_bound(
      std::begin(class_table), std::end(class_table), name, __name_comparator());

  if (entry != std::end(class_table) && std::strcmp(name, entry->name_) == 0) {
    auto result = entry->flags_;

    if (result == regex_traits<char>::__regex_word) {
      result |= ctype_base::alnum | ctype_base::upper | ctype_base::lower;
    } else if (case_insensitive) {
      if (result & (ctype_base::lower | ctype_base::upper)) {
        result |= ctype_base::alpha;
      }
    }
    return result;
  }
  return 0;
}

// Template specializations for any character except newline matching
template <>
void __match_any_but_newline<char>::__exec(__state& state) const {
  if (state.__current_ != state.__last_) {
    switch (*state.__current_) {
      case '\r':
      case '\n':
        state.__do_   = __state::__reject;
        state.__node_ = nullptr;
        break;
      default:
        state.__do_ = __state::__accept_and_consume;
        ++state.__current_;
        state.__node_ = this->first();
        break;
    }
  } else {
    state.__do_   = __state::__reject;
    state.__node_ = nullptr;
  }
}

template <>
void __match_any_but_newline<wchar_t>::__exec(__state& state) const {
  if (state.__current_ != state.__last_) {
    switch (*state.__current_) {
      case '\r':
      case '\n':
      case 0x2028:
      case 0x2029:
        state.__do_   = __state::__reject;
        state.__node_ = nullptr;
        break;
      default:
        state.__do_ = __state::__accept_and_consume;
        ++state.__current_;
        state.__node_ = this->first();
        break;
    }
  } else {
    state.__do_   = __state::__reject;
    state.__node_ = nullptr;
  }
}

