#include <iostream>
#include <vector>
#include <bitset>
#include <algorithm>
#include <cstdio>
#include <ctime>
using namespace std;

// Constants and configuration
const int MAX_VERTICES = 1005;
int vertexCount, edgeCount;
bitset<MAX_VERTICES> adjacency[MAX_VERTICES];

// Current and best clique storage
vector<int> currentClique;
vector<int> optimalClique;
int maxCliqueSize = 0;

// Timing control
clock_t startTime;
const double MAX_TIME = 1.95; // Slightly under 2 seconds

// Helper arrays for greedy coloring
static int colorUsage[MAX_VERTICES];
static int colorMarker = 0;

/**
 * Recursive search for maximum clique using pruning strategies
 * candidateSet: bitset of vertices that can still be added to the clique
 */
void search(bitset<MAX_VERTICES> candidateSet) {
    // Time limit check
    if ((double)(clock() - startTime) / CLOCKS_PER_SEC > MAX_TIME) return;

    int remaining = candidateSet.count();

    // Base case: no more candidates
    if (remaining == 0) {
        if (currentClique.size() > maxCliqueSize) {
            maxCliqueSize = currentClique.size();
            optimalClique = currentClique;
        }
        return;
    }

    // Pruning 1: Upper bound based on remaining candidates
    if (currentClique.size() + remaining <= maxCliqueSize) return;

    // Extract candidate vertices into a list
    vector<int> candidates;
    candidates.reserve(remaining);
    for (int v = 1; v <= vertexCount; ++v) {
        if (candidateSet[v]) candidates.push_back(v);
    }

    // Greedy coloring heuristic for upper bound estimation
    vector<int> assignedColors(vertexCount + 1, 0);
    int usedColors = 0;

    for (int vertex : candidates) {
        colorMarker++;

        // Mark colors used by neighbors already colored
        for (int neighbor : candidates) {
            if (neighbor == vertex) continue;
            if (assignedColors[neighbor] != 0 && adjacency[vertex][neighbor]) {
                colorUsage[assignedColors[neighbor]] = colorMarker;
            }
        }

        // Find first available color
        int color = 1;
        while (colorUsage[color] == colorMarker) color++;
        assignedColors[vertex] = color;
        if (color > usedColors) usedColors = color;
    }

    // Pruning 2: Coloring-based bound
    if (currentClique.size() + usedColors <= maxCliqueSize) return;

    // Sort candidates by color (ascending)
    sort(candidates.begin(), candidates.end(), [&](int a, int b) {
        return assignedColors[a] < assignedColors[b];
    });

    // Process candidates in reverse order (higher colors first)
    for (int idx = (int)candidates.size() - 1; idx >= 0; --idx) {
        // Periodic time check
        if ((double)(clock() - startTime) / CLOCKS_PER_SEC > MAX_TIME) return;

        int vertex = candidates[idx];
        int colorClass = assignedColors[vertex];

        // Pruning 3: Color class bound
        if (currentClique.size() + colorClass <= maxCliqueSize) break;

        // Include current vertex in clique
        currentClique.push_back(vertex);
        candidateSet[vertex] = false;

        // Recurse with only common neighbors
        search(candidateSet & adjacency[vertex]);

        // Backtrack
        currentClique.pop_back();
    }
}

int main() {
    // Input reading
    if (scanf("%d %d", &vertexCount, &edgeCount) != 2) return 0;

    for (int i = 0; i < edgeCount; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (u >= 1 && u <= vertexCount && v >= 1 && v <= vertexCount) {
            adjacency[u][v] = true;
            adjacency[v][u] = true;
        }
    }

    startTime = clock();

    // Initialize candidate set with all vertices
    bitset<MAX_VERTICES> initialCandidates;
    for (int i = 1; i <= vertexCount; ++i) {
        initialCandidates.set(i);
    }

    search(initialCandidates);

    // Output result: mark which vertices are in the maximum clique
    vector<int> output(vertexCount + 1, 0);
    for (int v : optimalClique) {
        output[v] = 1;
    }

    for (int i = 1; i <= vertexCount; ++i) {
        printf("%d\n", output[i]);
    }

    return 0;
}

