// Simulate block update cost calculation (returns estimated byte count)
int WaterLevelChunk::setBlocksAndData(
    byteArray data,
    int x0, int y0, int z0,
    int x1, int y1, int z1,
    int flags,
    bool includeLighting /* = true */
) {
    int dx = x1 - x0;
    int dy = y1 - y0;
    int dz = z1 - z0;
    int volume = dx * dy * dz;

    if (includeLighting) {
        return volume + (volume / 2) * 3;
    } else {
        return volume + (volume / 2);
    }
}

