// Generate deterministic random seed based on chunk position and input seed
Random* WaterLevelChunk::getRandom(std::int64_t seedOffset) {
    std::int64_t baseSeed = level->getSeed();
    std::int64_t combined = baseSeed
        + x * x * 4987142LL
        + x * 5947611LL
        + z * z * 4392871LL
        + z * 389711LL
        ^ seedOffset;
    return new Random(combined);
}

