MenuBackup::MenuBackup(shared_ptr<Inventory> inv, AbstractContainerMenu *container)
{
    backupStore = new std::unordered_map<short, ItemInstanceArray*>();
    playerInv = inv;
    uiMenu = container;
}

void MenuBackup::record(short snapshotId)
{
    ItemInstanceArray* snapshot = new ItemInstanceArray(static_cast<int>(uiMenu->slots.size()) + 1);
    snapshot[0] = ItemInstance::copy(playerInv->getCarried());

    for (size_t idx = 0; idx < uiMenu->slots.size(); ++idx) {
        snapshot[idx + 1] = ItemInstance::copy(uiMenu->slots[idx]->getItem());
    }

    // Using unordered_map as storage mechanism
    backupStore->operator[](snapshotId) = snapshot;
}

void MenuBackup::removeRecord(short snapshotId)
{
    // Erase specific entry from the map
    auto it = backupStore->find(snapshotId);
    if (it != backupStore->end()) {
        delete it->second;
        backupStore->erase(it);
    }
}

void MenuBackup::restore(short snapshotId)
{
    ItemInstanceArray* snapshot = backupStore->at(snapshotId);

    // Clear current state before restoring
    backupStore->clear();

    playerInv->setCarried(snapshot[0]);

    for (size_t slotIndex = 0; slotIndex < uiMenu->slots.size(); ++slotIndex) {
        uiMenu->slots[slotIndex]->set(snapshot[slotIndex + 1]);
    }
}

