namespace {
// Helper function to compute number of slices for circle drawing
int calculateCircleSegments(double radius, double pixelSize = 1.0) {
    if (radius <= 0) return 4;

    double angleStep;
    double ratio = pixelSize * 0.5 / radius;

    // Clamp ratio to avoid numerical issues
    if (fabs(1.0 - ratio) <= 1.0) {
        angleStep = acos(1.0 - ratio);
    } else {
        angleStep = M_PI_4; // Default to 45 degrees
    }

    if (angleStep == 0.0) angleStep = M_PI_4;

    int segments = static_cast<int>(M_2PI / angleStep);
    return (segments > 0) ? segments : 4;
}

// Alternative implementation using geometric progression for smoother rendering
int estimateSlices(double radius, double tolerance = 0.5) {
    if (radius <= 0) return 4;

    // Use a simpler estimation based on circumference and desired precision
    double circumference = 2.0 * M_PI * radius;
    int slices = static_cast<int>(circumference / tolerance);
    return std::max(4, slices);
}
} // unnamed namespace

double tglGetPixelSize2() {
    double modelview[16];
    glMatrixMode(GL_MODELVIEW);
    glGetDoublev(GL_MODELVIEW_MATRIX, modelview);

    // Compute determinant of 2x2 transformation matrix
    double det = fabs(modelview[0] * modelview[5] - modelview[1] * modelview[4]);
    if (det < TConsts::epsilon) det = TConsts::epsilon;

    return 1.0 / det;
}

TRectD tglGetBounds() {
    TAffine4 modelviewMatrix;
    TAffine4 projectionMatrix;

    glGetDoublev(GL_MODELVIEW_MATRIX, modelviewMatrix.a);
    glGetDoublev(GL_PROJECTION_MATRIX, projectionMatrix.a);

    TAffine4 combined = projectionMatrix * modelviewMatrix;
    return combined.get2d().inv() * TRectD(-1.0, -1.0, 1.0, 1.0);
}

double tglGetTextWidth(const std::string &text, void *font) {
    const double charWidthFactor = 0.07;
    double totalWidth = 0.0;

    for (size_t i = 0; i < text.length(); ++i) {
        totalWidth += glutStrokeWidth(font, text[i]);
    }

    return totalWidth * charWidthFactor;
}

