void tglDrawSegment(const TPointD &start, const TPointD &end) {
    glBegin(GL_LINES);
    tglVertex(start);
    tglVertex(end);
    glEnd();
}

void tglDrawCircle(const TPointD &center, double radius) {
    if (radius <= 0) return;

    double pixelSize = sqrt(tglGetPixelSize2());
    int segments = std::max(4, calculateCircleSegments(radius, pixelSize));

    double angleStep = M_2PI / static_cast<double>(segments);
    double cosStep = cos(angleStep);
    double sinStep = sin(angleStep);

    glPushMatrix();
    glTranslated(center.x, center.y, 0.0);

    glBegin(GL_LINE_STRIP);

    // Start at (radius, 0)
    double x = radius;
    double y = 0.0;
    glVertex2d(x, y);

    // Generate points using rotation matrix
    for (int i = segments - 1; i > 0; --i) {
        double newX = x * cosStep - y * sinStep;
        y = x * sinStep + y * cosStep;
        x = newX;
        glVertex2d(x, y);
    }

    // Close the circle
    glVertex2d(radius, 0.0);
    glEnd();

    glPopMatrix();
}

void tglDrawDisk(const TPointD &center, double radius) {
    if (radius <= 0) return;

    int slices = 60;
    double pixelSize = 1.0;

    // Adjust slice count based on radius if needed
    if (slices <= 0) {
        slices = calculateCircleSegments(radius, pixelSize) >> 1;
    }

    glPushMatrix();
    glTranslated(center.x, center.y, 0.0);

    GLUquadric *quadric = gluNewQuadric();
    gluDisk(quadric, 0.0, radius, slices, 1);
    gluDeleteQuadric(quadric);

    glPopMatrix();
}

void tglDrawRect(const TRectD &rectangle) {
    glBegin(GL_LINE_LOOP);
    tglVertex(rectangle.getP00());
    tglVertex(rectangle.getP10());
    tglVertex(rectangle.getP11());
    tglVertex(rectangle.getP01());
    glEnd();
}

void tglFillRect(const TRectD &rectangle) {
    glBegin(GL_POLYGON);
    tglVertex(rectangle.getP00());
    tglVertex(rectangle.getP10());
    tglVertex(rectangle.getP11());
    tglVertex(rectangle.getP01());
    glEnd();
}

void tglRgbOnlyColorMask() {
    tglMultColorMask(GL_TRUE, GL_TRUE, GL_TRUE, GL_FALSE);
    tglEnableBlending(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
}

void tglAlphaOnlyColorMask() {
    tglMultColorMask(GL_FALSE, GL_FALSE, GL_FALSE, GL_TRUE);
    tglEnableBlending(GL_ONE, GL_ONE_MINUS_SRC_ALPHA);
}

void tglEnableBlending(GLenum srcFactor, GLenum dstFactor) {
    glEnable(GL_BLEND);
    glBlendFunc(srcFactor, dstFactor);
}

void tglEnableLineSmooth(bool enable, double lineWidth) {
    if (enable) {
        glHint(GL_LINE_SMOOTH_HINT, GL_NICEST);
        glEnable(GL_LINE_SMOOTH);
        glLineWidth(lineWidth);
    } else {
        glDisable(GL_LINE_SMOOTH);
    }
}

void tglEnablePointSmooth(double pointSize) {
    glEnable(GL_BLEND);
    glEnable(GL_POINT_SMOOTH);
    glHint(GL_POINT_SMOOTH_HINT, GL_NICEST);
    glPointSize(pointSize);
}

void tglGetColorMask(GLboolean &red, GLboolean &green, GLboolean &blue, GLboolean &alpha) {
    GLboolean channels[4];
    glGetBooleanv(GL_COLOR_WRITEMASK, &channels[0]);

    red = channels[0];
    green = channels[1];
    blue = channels[2];
    alpha = channels[3];
}

void tglMultColorMask(GLboolean red, GLboolean green, GLboolean blue, GLboolean alpha) {
    GLboolean currentMask[4];
    glGetBooleanv(GL_COLOR_WRITEMASK, &currentMask[0]);

    glColorMask(
        red && currentMask[0],
        green && currentMask[1],
        blue && currentMask[2],
        alpha && currentMask[3]
    );
}

