namespace {
class GlFontManager {
    GlFontManager();
public:
    ~GlFontManager();
    static GlFontManager *getInstance();
    bool setFont(void *font = GLUT_BITMAP_TIMES_ROMAN_10);
    void drawText(std::wstring wtext);
private:
    static GlFontManager *instance;
    std::map<void *, double> fontHeights;
    void *currentFont;
    GLuint displayListBase;
};

GlFontManager *GlFontManager::instance = nullptr;

GlFontManager::GlFontManager() : currentFont(nullptr), displayListBase(0) {
    // Initialize known fonts with their heights
    fontHeights.insert(std::make_pair(GLUT_BITMAP_8_BY_13, 13.0));
    fontHeights.insert(std::make_pair(GLUT_BITMAP_9_BY_15, 15.0));
    fontHeights.insert(std::make_pair(GLUT_BITMAP_TIMES_ROMAN_10, 10.0));
    fontHeights.insert(std::make_pair(GLUT_BITMAP_TIMES_ROMAN_24, 24.0));
    fontHeights.insert(std::make_pair(GLUT_BITMAP_HELVETICA_10, 10.0));
    fontHeights.insert(std::make_pair(GLUT_BITMAP_HELVETICA_12, 12.0));
    fontHeights.insert(std::make_pair(GLUT_BITMAP_HELVETICA_18, 18.0));

    bool success = setFont();
    assert(success);
}

GlFontManager::~GlFontManager() {
    instance = nullptr;
}

GlFontManager *GlFontManager::getInstance() {
    if (!instance) {
        instance = new GlFontManager();
    }
    return instance;
}

bool GlFontManager::setFont(void *font) {
    auto it = fontHeights.find(font);
    if (it != fontHeights.end()) {
        currentFont = font;

        glPushAttrib(GL_ALL_ATTRIB_BITS);
        glPushMatrix();

        displayListBase = glGenLists(256);
        glListBase(displayListBase);

        for (int i = 0; i < 256; ++i) {
            glNewList(displayListBase + i, GL_COMPILE);
            glutStrokeCharacter(GLUT_STROKE_ROMAN, i);
            glEndList();
        }

        glPopAttrib();
        glPopMatrix();

        return true;
    }

    return false;
}

void GlFontManager::drawText(std::wstring wtext) {
    if (!currentFont) return;

    std::string text = ::to_string(wtext);
    const char *cstr = text.c_str();

    glListBase(displayListBase);
    glCallLists(static_cast<GLuint>(strlen(cstr)), GL_BYTE, cstr);
}
