#include <iostream>
#include <vector>
#include <string>
using namespace std;

// Modified version: uses iterative backtracking with explicit direction handling
void explorePaths(vector<vector<int>>& grid, int row, int col, string currentPath, vector<string>& results) {
    // Boundary and validity checks
    if (row < 0 || col < 0 || row >= grid.size() || col >= grid[0].size()) {
        return;
    }

    // Check if current cell is blocked or already visited
    if (grid[row][col] == 0 || grid[row][col] == -2) {
        return;
    }

    // Reached destination
    if (row == grid.size() - 1 && col == grid[0].size() - 1) {
        results.push_back(currentPath);
        return;
    }

    // Mark as visited temporarily
    grid[row][col] = -2;

    // Explore all four directions in a specific order
    // Down
    explorePaths(grid, row + 1, col, currentPath + "D", results);
    // Left
    explorePaths(grid, row, col - 1, currentPath + "L", results);
    // Right
    explorePaths(grid, row, col + 1, currentPath + "R", results);
    // Up
    explorePaths(grid, row - 1, col, currentPath + "U", results);

    // Backtrack: restore original value
    grid[row][col] = 1;
}

// Wrapper function to initiate path finding
vector<string> discoverAllRoutes(vector<vector<int>>& matrix) {
    vector<string> allPaths;
    string route = "";
    explorePaths(matrix, 0, 0, route, allPaths);
    return allPaths;
}

int main() {
    // Test case with modified representation but same logical structure
    vector<vector<int>> maze = {{1, 0, 0, 0}, 
                                {1, 1, 0, 1}, 
                                {1, 1, 0, 0}, 
                                {0, 1, 1, 1}};

    vector<string> paths = discoverAllRoutes(maze);

    // Output each found path
    for (const string& path : paths) {
        cout << path << '\n';
    }

    return 0;
}

