// Helper: Safely convert arbitrary integral type to unsigned int vector
static std::vector<unsigned int> normalize_indices(const void* data, size_t count, size_t elem_size) {
    std::vector<unsigned int> result;
    if (!data || count == 0) return result;

    result.reserve(count);
    const char* src = static_cast<const char*>(data);

    for (size_t i = 0; i < count; ++i) {
        unsigned int val = 0;
        switch (elem_size) {
            case sizeof(int):         val = static_cast<unsigned int>(*reinterpret_cast<const int*>(src)); break;
            case sizeof(std::int64_t): val = static_cast<unsigned int>(*reinterpret_cast<const std::int64_t*>(src)); break;
            case sizeof(std::uint64_t):val = static_cast<unsigned int>(*reinterpret_cast<const std::uint64_t*>(src)); break;
            case sizeof(unsigned int): val = *reinterpret_cast<const unsigned int*>(src); break;
            default: break;
        }
        result.push_back(val);
        src += elem_size;
    }
    return result;
}

class ElementBufferObject {
public:
    ElementBufferObject() : handle_(0) {}
    ~ElementBufferObject() { release(); }

    void create_and_upload(const void* data, GLsizei byte_size) {
        release();
        glGenBuffers(1, &handle_);
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, handle_);
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, byte_size, data, GL_STATIC_DRAW);
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, 0);
    }

    GLuint id() const { return handle_; }
    bool valid() const { return handle_ != 0; }

private:
    void release() {
        if (handle_) {
            glDeleteBuffers(1, &handle_);
            handle_ = 0;
        }
    }

    GLuint handle_;
};

