#include <iostream>
#include <vector>
#include <algorithm>

// Assign ranks to original indices based on sorted pairs (value, original_index)
void assign_ranks(const std::vector<std::pair<int, int>>& sorted_data, std::vector<int>& ranks) {
    for (size_t idx = 0; idx < sorted_data.size(); ++idx) {
        ranks[sorted_data[idx].second] = static_cast<int>(idx);
    }
}

void process() {
    int size;
    std::cin >> size;

    // Read distance matrix d
    std::vector<std::vector<int>> dist(size, std::vector<int>(size));
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            std::cin >> dist[i][j];
        }
    }

    // Read flow matrix f
    std::vector<std::vector<int>> flow(size, std::vector<int>(size));
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            std::cin >> flow[i][j];
        }
    }

    // Compute out-degree and in-degree for each facility and location
    std::vector<std::pair<int, int>> facility_out(size), facility_in(size);
    std::vector<std::pair<int, int>> location_out(size), location_in(size);

    for (int node = 0; node < size; ++node) {
        int out_flow = 0, in_flow = 0;
        int out_dist = 0, in_dist = 0;

        for (int neighbor = 0; neighbor < size; ++neighbor) {
            out_flow += flow[node][neighbor];
            in_flow += flow[neighbor][node];
            out_dist += dist[node][neighbor];
            in_dist += dist[neighbor][node];
        }

        facility_out[node] = {out_flow, node};
        facility_in[node] = {in_flow, node};
        location_out[node] = {out_dist, node};
        location_in[node] = {in_dist, node};
    }

    // Sort facilities by out/in degree descending (higher degrees first)
    std::sort(facility_out.begin(), facility_out.end(), 
              [](const auto& a, const auto& b) { return a.first > b.first; });
    std::sort(facility_in.begin(), facility_in.end(),
              [](const auto& a, const auto& b) { return a.first > b.first; });

    // Sort locations by out/in degree ascending (lower degrees first)
    std::sort(location_out.begin(), location_out.end());
    std::sort(location_in.begin(), location_in.end());

    // Get rank assignments for each facility and location
    std::vector<int> rank_fac_out(size), rank_fac_in(size);
    std::vector<int> rank_loc_out(size), rank_loc_in(size);

    assign_ranks(facility_out, rank_fac_out);
    assign_ranks(facility_in, rank_fac_in);
    assign_ranks(location_out, rank_loc_out);
    assign_ranks(location_in, rank_loc_in);

    // Combine ranks into total scores for facilities and locations
    std::vector<std::pair<int, int>> fac_scores(size);
    std::vector<std::pair<int, int>> loc_scores(size);

    for (int i = 0; i < size; ++i) {
        fac_scores[i] = {rank_fac_out[i] + rank_fac_in[i], i};
        loc_scores[i] = {rank_loc_out[i] + rank_loc_in[i], i};
    }

    // Sort by combined score (ascending - lower is better/more critical)
    std::sort(fac_scores.begin(), fac_scores.end());
    std::sort(loc_scores.begin(), loc_scores.end());

    // Build mapping: facility -> location based on matched ranks
    std::vector<int> assignment(size);
    for (int pos = 0; pos < size; ++pos) {
        int fac_id = fac_scores[pos].second;
        int loc_id = loc_scores[pos].second;
        assignment[fac_id] = loc_id;
    }

    // Output result in 1-based indexing
    for (int i = 0; i < size; ++i) {
        std::cout << assignment[i] + 1;
        if (i < size - 1) std::cout << " ";
    }
    std::cout << "\n";
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    process();
    return 0;
}

