      stateInequalityConstraintPtr(std::make_unique<StateConstraintCollection>()),
      preJumpInequalityConstraintPtr(std::make_unique<StateConstraintCollection>()),
      finalInequalityConstraintPtr(std::make_unique<StateConstraintCollection>()),
      /* Augmented Lagrangian terms */
      equalityLagrangianPtr(std::make_unique<StateInputAugmentedLagrangianCollection>()),
      stateEqualityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      inequalityLagrangianPtr(std::make_unique<StateInputAugmentedLagrangianCollection>()),
      stateInequalityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      preJumpEqualityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      preJumpInequalityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      finalEqualityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      finalInequalityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      /* Shared utilities */
      preComputationPtr(std::make_unique<PreComputation>()),
      targetTrajectoriesPtr(nullptr) {}

OptimalControlProblem::OptimalControlProblem(const OptimalControlProblem& other)
    : /* Clone all cost-related objects */
      costPtr(other.costPtr ? other.costPtr->clone() : nullptr),
      stateCostPtr(other.stateCostPtr ? other.stateCostPtr->clone() : nullptr),
      preJumpCostPtr(other.preJumpCostPtr ? other.preJumpCostPtr->clone() : nullptr),
      finalCostPtr(other.finalCostPtr ? other.finalCostPtr->clone() : nullptr),
      /* Clone soft constraints */
      softConstraintPtr(other.softConstraintPtr ? other.softConstraintPtr->clone() : nullptr),
      stateSoftConstraintPtr(other.stateSoftConstraintPtr ? other.stateSoftConstraintPtr->clone() : nullptr),
      preJumpSoftConstraintPtr(other.preJumpSoftConstraintPtr ? other.preJumpSoftConstraintPtr->clone() : nullptr),
      finalSoftConstraintPtr(other.finalSoftConstraintPtr ? other.finalSoftConstraintPtr->clone() : nullptr),
      /* Clone equality constraints */
      equalityConstraintPtr(other.equalityConstraintPtr ? other.equalityConstraintPtr->clone() : nullptr),
      stateEqualityConstraintPtr(other.stateEqualityConstraintPtr ? other.stateEqualityConstraintPtr->clone() : nullptr),
      preJumpEqualityConstraintPtr(other.preJumpEqualityConstraintPtr ? other.preJumpEqualityConstraintPtr->clone() : nullptr),
      finalEqualityConstraintPtr(other.finalEqualityConstraintPtr ? other.finalEqualityConstraintPtr->clone() : nullptr),
      /* Clone inequality constraints */
      inequalityConstraintPtr(other.inequalityConstraintPtr ? other.inequalityConstraintPtr->clone() : nullptr),
      stateInequalityConstraintPtr(other.stateInequalityConstraintPtr ? other.stateInequalityConstraintPtr->clone() : nullptr),
      preJumpInequalityConstraintPtr(other.preJumpInequalityConstraintPtr ? other.preJumpInequalityConstraintPtr->clone() : nullptr),
      finalInequalityConstraintPtr(other.finalInequalityConstraintPtr ? other.finalInequalityConstraintPtr->clone() : nullptr),
      /* Clone Lagrangians */
      equalityLagrangianPtr(other.equalityLagrangianPtr ? other.equalityLagrangianPtr->clone() : nullptr),
      stateEqualityLagrangianPtr(other.stateEqualityLagrangianPtr ? other.stateEqualityLagrangianPtr->clone() : nullptr),
      inequalityLagrangianPtr(other.inequalityLagrangianPtr ? other.inequalityLagrangianPtr->clone() : nullptr),
      stateInequalityLagrangianPtr(other.stateInequalityLagrangianPtr ? other.stateInequalityLagrangianPtr->clone() : nullptr),
      preJumpEqualityLagrangianPtr(other.preJumpEqualityLagrangianPtr ? other.preJumpEqualityLagrangianPtr->clone() : nullptr),
      preJumpInequalityLagrangianPtr(other.preJumpInequalityLagrangianPtr ? other.preJumpInequalityLagrangianPtr->clone() : nullptr),
      finalEqualityLagrangianPtr(other.finalEqualityLagrangianPtr ? other.finalEqualityLagrangianPtr->clone() : nullptr),
      finalInequalityLagrangianPtr(other.finalInequalityLagrangianPtr ? other.finalInequalityLagrangianPtr->clone() : nullptr),
      /* Clone pre-computation module */
      preComputationPtr(other.preComputationPtr ? other.preComputationPtr->clone() : nullptr),
      /* Copy dynamics if present */
      dynamicsPtr(other.dynamicsPtr ? other.dynamicsPtr->clone() : nullptr),
      /* Copy pointer to target trajectories */
      targetTrajectoriesPtr(other.targetTrajectoriesPtr) {}

OptimalControlProblem& OptimalControlProblem::operator=(const OptimalControlProblem& rhs) {
  if (this != &rhs) {
    OptimalControlProblem temp(rhs);
    swap(temp);
  }
  return *this;
}

void OptimalControlProblem::swap(OptimalControlProblem& other) noexcept {
  using std::swap;

  // Swap cost components
  swap(costPtr, other.costPtr);
  swap(stateCostPtr, other.stateCostPtr);
  swap(preJumpCostPtr, other.preJumpCostPtr);
  swap(finalCostPtr, other.finalCostPtr);

  // Swap soft constraints
  swap(softConstraintPtr, other.softConstraintPtr);
  swap(stateSoftConstraintPtr, other.stateSoftConstraintPtr);
  swap(preJumpSoftConstraintPtr, other.preJumpSoftConstraintPtr);
  swap(finalSoftConstraintPtr, other.finalSoftConstraintPtr);

  // Swap equality constraints
  swap(equalityConstraintPtr, other.equalityConstraintPtr);
  swap(stateEqualityConstraintPtr, other.stateEqualityConstraintPtr);
  swap(preJumpEqualityConstraintPtr, other.preJumpEqualityConstraintPtr);
  swap(finalEqualityConstraintPtr, other.finalEqualityConstraintPtr);

  // Swap inequality constraints
  swap(inequalityConstraintPtr, other.inequalityConstraintPtr);
  swap(stateInequalityConstraintPtr, other.stateInequalityConstraintPtr);
  swap(preJumpInequalityConstraintPtr, other.preJumpInequalityConstraintPtr);
  swap(finalInequalityConstraintPtr, other.finalInequalityConstraintPtr);

  // Swap Lagrangian collections
  swap(equalityLagrangianPtr, other.equalityLagrangianPtr);
  swap(stateEqualityLagrangianPtr, other.stateEqualityLagrangianPtr);
  swap(inequalityLagrangianPtr, other.inequalityLagrangianPtr);
  swap(stateInequalityLagrangianPtr, other.stateInequalityLagrangianPtr);
  swap(preJumpEqualityLagrangianPtr, other.preJumpEqualityLagrangianPtr);
  swap(preJumpInequalityLagrangianPtr, other.preJumpInequalityLagrangianPtr);
  swap(finalEqualityLagrangianPtr, other.finalEqualityLagrangianPtr);
  swap(finalInequalityLagrangianPtr, other.finalInequalityLagrangianPtr);

  // Swap dynamics and utility modules
  swap(dynamicsPtr, other.dynamicsPtr);
  swap(preComputationPtr, other.preComputationPtr);
  swap(targetTrajectoriesPtr, other.targetTrajectoriesPtr);
}

