// Maximum packet size: "<" + name + "> " + message (based on constants)
const unsigned int ChatPacket::MAX_LENGTH =
    SharedConstants::maxChatLength + Player::MAX_NAME_LENGTH + 3;

ChatPacket::ChatPacket() {
    m_messageType = e_ChatCustom;
}

// Alternate constructor for chat packets with optional custom data and extra message
ChatPacket::ChatPacket(
    const std::wstring& message,
    EChatPacketMessage  type /*= e_ChatCustom*/,
    int                 customData /*= -1*/,
    const std::wstring& additionalMessage /*= L""*/
) {
    m_messageType = type;

    // Store custom integer argument if valid
    if (customData != -1) {
        m_intArgs.emplace_back(customData);
    }

    // Add primary message only if non-empty or additional message exists
    if (!message.empty() || !additionalMessage.empty()) {
        m_stringArgs.emplace_back(message);
    }

    // Append secondary message if present
    if (!additionalMessage.empty()) {
        m_stringArgs.emplace_back(additionalMessage);
    }
}

// Deserialize packet from input stream
void ChatPacket::read(DataInputStream* dis) {
    m_messageType = static_cast<EChatPacketMessage>(dis->readShort());

    short packedCounts = dis->readShort();

    // Extract string and int counts from packed byte
    int stringCount = (packedCounts >> 4) & 0x0F;
    int intCount    = packedCounts & 0x0F;

    // Read string arguments
    for (int i = 0; i < stringCount; ++i) {
        m_stringArgs.push_back(readUtf(dis, MAX_LENGTH));
    }

    // Read integer arguments
    for (int i = 0; i < intCount; ++i) {
        m_intArgs.push_back(dis->readInt());
    }
}

// Serialize packet to output stream
void ChatPacket::write(DataOutputStream* dos) {
    dos->writeShort(m_messageType);

    // Pack argument counts into a single short
    short packedCounts = 0;
    packedCounts |= (static_cast<short>(m_stringArgs.size()) & 0x0F) << 4;
    packedCounts |= (static_cast<short>(m_intArgs.size()) & 0x0F);

    dos->writeShort(packedCounts);

    // Write all string arguments
    for (size_t i = 0; i < m_stringArgs.size(); ++i) {
        writeUtf(m_stringArgs[i], dos);
    }

    // Write all integer arguments
    for (size_t i = 0; i < m_intArgs.size(); ++i) {
        dos->writeInt(m_intArgs[i]);
    }
}

// Dispatch packet to appropriate handler
void ChatPacket::handle(PacketListener* listener) {
    listener->handleChat(shared_from_this());
}

// Compute approximate serialized size of the packet
int ChatPacket::getEstimatedSize() const {
    size_t totalStringChars = 0;
    for (const auto& str : m_stringArgs) {
        totalStringChars += str.length();
    }

    return sizeof(EChatPacketMessage) +          // message type
           sizeof(short) +                       // packed arg counts
           static_cast<int>(totalStringChars) +  // UTF-16 characters (approx bytes)
           (m_intArgs.size() * sizeof(int));     // integer args
}

