class tst_VersionNegotiation : public QObject
{
    Q_OBJECT
private slots:
    void setUp();
    void tearDown();
    // Version negotiation tests
    void baselineVersionAgreement();
    void explicitVersionSelection_data();
    void explicitVersionSelection();
    void fallbackOnInvalidProtocol();
private:
    QMcpServer* m_backendServer = nullptr;
    QMcpClient* m_endpointClient = nullptr;
    QTemporaryFile m_tempStorage;

    // Helper utilities
    QtMcp::ProtocolVersion establishConnection();
    QMcpServerSession* fetchActiveSession();
};

void tst_VersionNegotiation::setUp()
{
    // Initialize server with SSE transport
    m_backendServer = new QMcpServer("sse", this);
    // Define supported protocol versions
    const auto supportedVersions = {
        QtMcp::ProtocolVersion::v2025_03_26,
        QtMcp::ProtocolVersion::v2024_11_05
    };
    m_backendServer->setSupportedProtocolVersions(supportedVersions);
    m_backendServer->setProtocolVersion(QtMcp::ProtocolVersion::v2025_03_26); // Prefer latest

    // Launch server on local address
    m_backendServer->start("127.0.0.1:10101");

    // Configure client
    m_endpointClient = new QMcpClient("sse", this);
    m_endpointClient->start("http://localhost:10101");
}

void tst_VersionNegotiation::tearDown()
{
    if (m_endpointClient) {
        delete m_endpointClient;
        m_endpointClient = nullptr;
    }
    if (m_backendServer) {
        delete m_backendServer;
        m_backendServer = nullptr;
    }
}

QtMcp::ProtocolVersion tst_VersionNegotiation::establishConnection()
{
    QSignalSpy startupSignal(m_endpointClient, &QMcpClient::started);
    if (!startupSignal.wait(5000))
        return QtMcp::ProtocolVersion::Latest;

    QMcpInitializeRequest initReq;
    auto params = initReq.params();
    // Convert current client version to string for request
    params.setProtocolVersion(QtMcp::protocolVersionToString(m_endpointClient->protocolVersion()));
    initReq.setParams(params);

    QEventLoop runner;
    QtMcp::ProtocolVersion negotiatedVersion = QtMcp::ProtocolVersion::Unknown;

    m_endpointClient->request(initReq, [&negotiatedVersion, &runner](const QMcpInitializeResult& res, const QMcpJSONRPCErrorError* err) {
        if (err) {
            qWarning() << "Init failed:" << err->message();
        } else {
            negotiatedVersion = res.protocolVersion();
        }
        runner.exit();
    });

    QTimer::singleShot(5000, &runner, &QEventLoop::exit);
    runner.exec();

    return negotiatedVersion;
}

QMcpServerSession* tst_VersionNegotiation::fetchActiveSession()
{
    const auto activeList = m_backendServer->sessions();
    return activeList.isEmpty() ? nullptr : activeList.first();
}

void tst_VersionNegotiation::baselineVersionAgreement()
{
    const auto actualVersion = establishConnection();
    QMcpServerSession* session = fetchActiveSession();
    QVERIFY(session != nullptr);
    QCOMPARE(session->protocolVersion(), actualVersion);
}

void tst_VersionNegotiation::explicitVersionSelection_data()
{
    QTest::addColumn<QtMcp::ProtocolVersion>("targetVersion");
    QTest::addColumn<QtMcp::ProtocolVersion>("expectedOutcome");
    QTest::newRow("Target latest") << QtMcp::ProtocolVersion::v2025_03_26 << QtMcp::ProtocolVersion::v2025_03_26;
    QTest::newRow("Target legacy") << QtMcp::ProtocolVersion::v2024_11_05 << QtMcp::ProtocolVersion::v2024_11_05;
}

void tst_VersionNegotiation::explicitVersionSelection()
{
    QFETCH(QtMcp::ProtocolVersion, targetVersion);
    QFETCH(QtMcp::ProtocolVersion, expectedOutcome);

    m_endpointClient->setProtocolVersion(targetVersion);
    const auto result = establishConnection();
    QCOMPARE(result, expectedOutcome);

    QMcpServerSession* session = fetchActiveSession();
    QVERIFY(session != nullptr);
    QCOMPARE(session->protocolVersion(), expectedOutcome);
}

void tst_VersionNegotiation::fallbackOnInvalidProtocol()
{
    // Attempt to set an unsupported version via invalid string
    const auto invalidVerStr = "9999-99-99";
    m_endpointClient->setProtocolVersion(QtMcp::stringToProtocolVersion(invalidVerStr));

    const auto fallbackResult = establishConnection();
    QCOMPARE(fallbackResult, QtMcp::ProtocolVersion::v2025_03_26);

    QMcpServerSession* session = fetchActiveSession();
    QVERIFY(session != nullptr);
    QCOMPARE(session->protocolVersion(), fallbackResult);
}

QTEST_MAIN(tst_VersionNegotiation)
