#include "test.h"
using namespace async;

TEST_CASE("async::Buffers") {
    SECTION("Standard") {
        Buffers<char> bufferManager;
        *bufferManager.init({});
        auto testData = "Hi!"_tv;

        // Writer: populate buffer with test data
        auto buffer = *bufferManager.writerPop();
        buffer.cursor.copy<char>(testData);
        buffer.cursor += testData.size();
        REQUIRE(buffer.writerSizeUsed() == testData.size());
        bufferManager.writerPush(_mv(buffer));

        // Ensure partial buffering is flushed
        bufferManager.flush(false);

        // Reader: consume data one character at a time to test caching
        Text result;
        while (result.size() < testData.size()) {
            buffer = *bufferManager.readerPop();
            REQUIRE(buffer.readerSizeAvail() == testData.size() - result.size());
            result += *buffer.cursor++;
            bufferManager.readerPush(_mv(buffer));
        }
        REQUIRE(result == testData);
    }

    SECTION("Custom Context") {
        Buffers<char, std::allocator<char>, int> ctxBufferManager;
        *ctxBufferManager.init({});
        auto testData = "Hi!"_tv;

        // Launch reader task to verify context retention across buffers
        auto readerTask = async::work::submit(_location, "Reader", [&] {
            int expectedCtx = 0;
            while (auto buffer = ctxBufferManager.readerPop()) {
                Text output;
                ASSERTD_MSG(buffer->ctx == expectedCtx, 
                           "Context mismatch: expected ", expectedCtx, 
                           " but got ", buffer->ctx);

                output.resize(buffer->readerSizeAvail());
                _copyTo(output, buffer->cursor);
                ctxBufferManager.readerPush(_mv(buffer), true);
                expectedCtx++;
                ASSERTD_MSG(output == testData, 
                           "Content mismatch: expected '", testData, 
                           "' but got '", output, "'");
            }
        });

        // Writer: produce multiple buffers with incrementing context values
        for (int i = 0; i < 5; ++i) {
            auto buffer = *ctxBufferManager.writerPop();
            buffer.ctx = i;
            buffer.cursor.copy<char>(testData);
            buffer.cursor += testData.size();
            REQUIRE(buffer.writerSizeUsed() == testData.size());
            ctxBufferManager.writerPush(_mv(buffer), true);
        }

        // Signal writer completion and wait for reader
        ctxBufferManager.flush();
    }
}

