void CritParticle::tick()
{
    int index = 0;
    while (index < 16)
    {
        double offsetX = random->nextFloat() * 2.0 - 1.0;
        double offsetY = random->nextFloat() * 2.0 - 1.0;
        double offsetZ = random->nextFloat() * 2.0 - 1.0;

        // Skip if outside unit sphere
        if (offsetX * offsetX + offsetY * offsetY + offsetZ * offsetZ > 1.0)
        {
            ++index;
            continue;
        }

        double posX = targetActor->x + offsetX * targetActor->bbWidth / 4.0;
        double posY = targetActor->bb->y0 + targetActor->bbHeight / 2.0 + offsetY * targetActor->bbHeight / 4.0;
        double posZ = targetActor->z + offsetZ * targetActor->bbWidth / 4.0;

        level->addParticle(particleKind, posX, posY, posZ, offsetX, offsetY + 0.2, offsetZ);

        ++index;
    }

    currentAge++;
    if (currentAge >= maxLifetime)
    {
        remove();
    }
}

