export module Karm.Core:async.base;
import :base.base;
import :meta.traits;

// Based on https://github.com/managarm/libasync
// Copyright 2016-2020 [redacted]

namespace Karm::Async {

export struct Immediate {};
export constexpr Immediate IMMEDIATE{};

export struct Deferred {};
export constexpr Deferred DEFERRED{};

export struct DispatchPolicy {
    constexpr DispatchPolicy(Immediate) {}
    constexpr DispatchPolicy(Deferred) {}
};

// Helper alias for checking if a type models an operation
template <typename Op>
concept OperationLike = requires(Op op) {
    { op.start() } -> Meta::Same<bool>;
};

// Helper alias for checking if a type models a receiver
template <typename Recv, typename Val>
concept ReceiverLike = requires(Recv r, Val v) {
    { r.recv(IMMEDIATE, v) };
    { r.recv(DEFERRED, v) };
};

// Null receiver: accepts any value and discards it
export template <typename T>
struct VoidReceiver {
    template <typename U>
    void recv(auto, U&&) noexcept {}
};

static_assert(ReceiverLike<VoidReceiver<int>, int>);

// Sender concept: must be able to connect to a Null receiver
export template <typename Sndr>
concept SenderLike = requires(Sndr s) {
    { s.connect(VoidReceiver<typename Sndr::InnerType>{}) } -> OperationLike;
};

// Alias for the operation type resulting from connecting a sender to a receiver
export template <SenderLike S, ReceiverLike<typename S::InnerType> R>
using ConnectResult = decltype(Meta::declval<S>().connect(Meta::declval<R>()));

} // namespace Karm::Async

