/******************************************************************************/
/* Tracking mechanism for active TSD instances in nominal mode. */
typedef ql_head(tsd_t) tsd_active_set_t;
static tsd_active_set_t tsd_active_list = ql_head_initializer(tsd_active_list);
static malloc_mutex_t tsd_active_list_lock;
/* Counter for enabled slow-path features across all threads. */
static atomic_u32_t tsd_slow_feature_count = ATOMIC_INIT(0);

static bool
tsd_is_in_active_set(tsd_t *thread_data) {
	tsd_t *cursor;
	bool match_found = false;

	malloc_mutex_lock(TSDN_NULL, &tsd_active_list_lock);
	ql_foreach(cursor, &tsd_active_list, TSD_MANGLE(thread_link)) {
		if (thread_data == cursor) {
			match_found = true;
			break;
		}
	}
	malloc_mutex_unlock(TSDN_NULL, &tsd_active_list_lock);
	return match_found;
}

static void
tsd_insert_active(tsd_t *thread_data) {
	assert(!tsd_is_in_active_set(thread_data));
	assert(tsd_state_get(thread_data) <= tsd_state_nominal_max);
	ql_elm_new(thread_data, TSD_MANGLE(thread_link));
	malloc_mutex_lock(tsd_tsdn(thread_data), &tsd_active_list_lock);
	ql_tail_insert(&tsd_active_list, thread_data, TSD_MANGLE(thread_link));
	malloc_mutex_unlock(tsd_tsdn(thread_data), &tsd_active_list_lock);
}

static void
tsd_remove_active(tsd_t *thread_data) {
	assert(tsd_is_in_active_set(thread_data));
	assert(tsd_state_get(thread_data) <= tsd_state_nominal_max);
	malloc_mutex_lock(tsd_tsdn(thread_data), &tsd_active_list_lock);
	ql_remove(&tsd_active_list, thread_data, TSD_MANGLE(thread_link));
	malloc_mutex_unlock(tsd_tsdn(thread_data), &tsd_active_list_lock);
}

static void
tsd_broadcast_update(tsdn_t *ctx) {
	atomic_fence(ATOMIC_RELEASE);
	malloc_mutex_lock(ctx, &tsd_active_list_lock);
	tsd_t *iter;
	ql_foreach(iter, &tsd_active_list, TSD_MANGLE(thread_link)) {
		assert(tsd_atomic_load(&iter->state, ATOMIC_RELAXED)
		    <= tsd_state_nominal_max);
		tsd_atomic_store(&iter->state,
		    tsd_state_nominal_refresh, ATOMIC_RELAXED);
		atomic_fence(ATOMIC_SEQ_CST);
		te_fast_threshold_adjust_non_nominal(iter);
	}
	malloc_mutex_unlock(ctx, &tsd_active_list_lock);
}

void
tsd_slow_feature_enable(tsdn_t *ctx) {
	atomic_fetch_add_u32(&tsd_slow_feature_count, 1, ATOMIC_RELAXED);
	tsd_broadcast_update(ctx);
}

void tsd_slow_feature_disable(tsdn_t *ctx) {
	atomic_fetch_sub_u32(&tsd_slow_feature_count, 1, ATOMIC_RELAXED);
	tsd_broadcast_update(ctx);
}

static bool
tsd_local_needs_slow(tsd_t *data) {
	return !tsd_tcache_enabled_get(data)
	    || tsd_reentrancy_level_get(data) > 0;
}

bool
tsd_any_thread_slow(void) {
	return atomic_load_u32(&tsd_slow_feature_count, ATOMIC_RELAXED) > 0;
}

/******************************************************************************/
static uint8_t
tsd_determine_state(tsd_t *data) {
	if (!tsd_nominal(data)) {
		return tsd_state_get(data);
	}

	if (malloc_slow || tsd_local_needs_slow(data) || tsd_any_thread_slow()) {
		return tsd_state_nominal_slow;
	} else {
		return tsd_state_nominal;
	}
}

void
tsd_state_refresh(tsd_t *data) {
	uint8_t previous;
	do {
		uint8_t current = tsd_determine_state(data);
		previous = tsd_atomic_exchange(&data->state, current,
		    ATOMIC_ACQUIRE);
	} while (previous == tsd_state_nominal_refresh);
	te_fast_threshold_adjust(data);
}

void
tsd_state_change(tsd_t *data, uint8_t new_val) {
	assert(new_val != tsd_state_nominal_refresh);
	uint8_t old_val = tsd_atomic_load(&data->state, ATOMIC_RELAXED);
	if (old_val > tsd_state_nominal_max) {
		assert(!tsd_is_in_active_set(data));
		tsd_atomic_store(&data->state, new_val, ATOMIC_RELAXED);
		if (new_val <= tsd_state_nominal_max) {
			tsd_insert_active(data);
		}
	} else {
		assert(tsd_is_in_active_set(data));
		if (new_val > tsd_state_nominal_max) {
			tsd_remove_active(data);
			tsd_atomic_store(&data->state, new_val,
			    ATOMIC_RELAXED);
		} else {
			tsd_state_refresh(data);
		}
	}
	te_fast_threshold_adjust(data);
}

static void
tsd_seed_prng(tsd_t *data) {
	*tsd_prng_statep_get(data) = config_debug ? 0 :
	    (uint64_t)(uintptr_t)data;
}

static bool
tsd_setup_data(tsd_t *data) {
	rtree_ctx_data_init(tsd_rtree_ctxp_get_unsafe(data));
	tsd_seed_prng(data);
	tsd_te_init(data);
	tsd_san_init(data);
	return tsd_tcache_enabled_data_init(data);
}

static void
assert_tsd_cleanup_complete(tsd_t *data) {
	assert(!tsd_nominal(data));
	assert(!tsd_is_in_active_set(data));
	assert(*tsd_arenap_get_unsafe(data) == NULL);
	assert(*tsd_iarenap_get_unsafe(data) == NULL);
	assert(*tsd_tcache_enabledp_get_unsafe(data) == false);
	assert(*tsd_prof_tdatap_get_unsafe(data) == NULL);
}

static bool
tsd_setup_no_cleanup(tsd_t *data) {
	assert(tsd_state_get(data) == tsd_state_reincarnated ||
	    tsd_state_get(data) == tsd_state_minimal_initialized);
	rtree_ctx_data_init(tsd_rtree_ctxp_get_unsafe(data));
	*tsd_tcache_enabledp_get_unsafe(data) = false;
	*tsd_reentrancy_levelp_get(data) = 1;
	tsd_seed_prng(data);
	tsd_te_init(data);
	tsd_san_init(data);
	assert_tsd_cleanup_complete(data);
	return false;
}

tsd_t *
tsd_acquire_slow(tsd_t *data, bool minimal) {
	assert(!tsd_fast(data));
	if (tsd_state_get(data) == tsd_state_nominal_slow) {
	} else if (tsd_state_get(data) == tsd_state_nominal_refresh) {
		tsd_state_refresh(data);
	} else if (tsd_state_get(data) == tsd_state_uninitialized) {
		if (!minimal) {
			if (tsd_global_init_status) {
				tsd_state_change(data, tsd_state_nominal);
				tsd_state_refresh(data);
				tsd_set(data);
				tsd_setup_data(data);
			}
		} else {
			tsd_state_change(data, tsd_state_minimal_initialized);
			tsd_set(data);
			tsd_setup_no_cleanup(data);
			*tsd_min_init_state_nfetchedp_get(data) = 1;
		}
	} else if (tsd_state_get(data) == tsd_state_minimal_initialized) {
		uint8_t *access_count = tsd_min_init_state_nfetchedp_get(data);
		assert(*access_count >= 1);
		(*access_count)++;
		if (!minimal || *access_count == TSD_MIN_INIT_STATE_MAX_FETCHED) {
			tsd_state_change(data, tsd_state_nominal);
			assert(*tsd_reentrancy_levelp_get(data) >= 1);
			(*tsd_reentrancy_levelp_get(data))--;
			tsd_state_refresh(data);
			tsd_setup_data(data);
		} else {
			assert_tsd_cleanup_complete(data);
		}
	} else if (tsd_state_get(data) == tsd_state_purgatory) {
		tsd_state_change(data, tsd_state_reincarnated);
		tsd_set(data);
		tsd_setup_no_cleanup(data);
	} else {
		assert(tsd_state_get(data) == tsd_state_reincarnated);
	}
	return data;
}

void *
malloc_tsd_alloc(size_t needed) {
	return a0malloc(CACHELINE_CEILING(needed));
}

void
malloc_tsd_free(void *wrapper) {
	a0dalloc(wrapper);
}

#if defined(JEMALLOC_MALLOC_THREAD_CLEANUP) || defined(_WIN32)
static unsigned cleanup_count;
static malloc_tsd_cleanup_t cleanup_funcs[MALLOC_TSD_CLEANUPS_MAX];
#ifndef _WIN32
JEMALLOC_EXPORT
#endif
void
_thread_cleanup(void) {
	bool need_retry[MALLOC_TSD_CLEANUPS_MAX], retry_needed;
	unsigned i;
	for (i = 0; i < cleanup_count; i++) {
		need_retry[i] = true;
	}
	do {
		retry_needed = false;
		for (i = 0; i < cleanup_count; i++) {
			if (need_retry[i]) {
				need_retry[i] = cleanup_funcs[i]();
				if (need_retry[i]) {
					retry_needed = true;
				}
			}
		}
	} while (retry_needed);
}
#ifndef _WIN32
JEMALLOC_EXPORT
#endif
void
_malloc_tsd_destructor_register(bool (*f)(void)) {
	assert(cleanup_count < MALLOC_TSD_CLEANUPS_MAX);
	cleanup_funcs[cleanup_count] = f;
	cleanup_count++;
}
#endif

static void
tsd_perform_cleanup(tsd_t *data) {
	prof_tdata_cleanup(data);
	iarena_cleanup(data);
	arena_cleanup(data);
	tcache_cleanup(data);
	witnesses_cleanup(witness_tsdp_get_unsafe(data));
	*tsd_reentrancy_levelp_get(data) = 1;
}

void
tsd_destructor(void *arg) {
	tsd_t *data = (tsd_t *)arg;
	switch (tsd_state_get(data)) {
	case tsd_state_uninitialized:
		break;
	case tsd_state_minimal_initialized:
	case tsd_state_reincarnated:
		assert_tsd_cleanup_complete(data);
		JEMALLOC_FALLTHROUGH;
	case tsd_state_nominal:
	case tsd_state_nominal_slow:
		tsd_perform_cleanup(data);
		tsd_state_change(data, tsd_state_purgatory);
		tsd_set(data);
		break;
	case tsd_state_purgatory:
		break;
	default:
		not_reached();
	}
#ifdef JEMALLOC_JET
	test_callback_t test_callback = *tsd_test_callbackp_get_unsafe(data);
	int *payload = tsd_test_datap_get_unsafe(data);
	if (test_callback != NULL) {
		test_callback(payload);
	}
#endif
}

tsd_t *
malloc_tsd_init0(void) {
	tsd_t *result;
#if defined(JEMALLOC_MALLOC_THREAD_CLEANUP) || defined(_WIN32)
	cleanup_count = 0;
#endif
	if (malloc_mutex_init(&tsd_active_list_lock, "tsd_active_list_lock",
	    WITNESS_RANK_OMIT, malloc_mutex_rank_exclusive)) {
		return NULL;
	}
	if (tsd_init0()) {
		return NULL;
	}
	result = tsd_acquire();
	return result;
}

void
malloc_tsd_init1(void) {
	tsd_init1();
	tsd_t *data = tsd_acquire();
	tsd_state_refresh(data);
}

