#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

// Irreducible polynomials for GF(2^k) for k = 1 to 15 (same as original)
const int polys[] = {
    0, 
    3,      // 1: x + 1
    7,      // 2: x^2 + x + 1
    11,     // 3: x^3 + x + 1
    19,     // 4: x^4 + x + 1
    37,     // 5: x^5 + x^2 + 1
    67,     // 6: x^6 + x + 1
    131,    // 7: x^7 + x + 1
    283,    // 8: x^8 + x^4 + x^3 + x + 1
    515,    // 9: x^9 + x + 1
    1033,   // 10: x^10 + x^3 + 1
    2053,   // 11: x^11 + x^2 + 1
    4105,   // 12: x^12 + x^3 + 1
    8219,   // 13: x^13 + x^4 + x^3 + x + 1
    16427,  // 14: x^14 + x^5 + x^3 + x + 1
    32771   // 15: x^15 + x + 1
};

// Modified multiplication in GF(2^k) modulo p using different loop structure
int gf_mul_v2(int a, int b, int k, int p) {
    int res = 0;
    int bit_pos = 0;
    while (b > 0) {
        if (b & 1) {
            res ^= a;
        }
        bool carry = (a >> (k - 1)) & 1;
        a <<= 1;
        if (carry) {
            a ^= p;
        }
        a &= ((1 << k) - 1);
        b >>= 1;
        bit_pos++;
    }
    return res;
}

// Compute a^3 in GF(2^k) using the modified multiplication function
int gf_pow3_v2(int a, int k, int p) {
    int a2 = gf_mul_v2(a, a, k, p);
    return gf_mul_v2(a2, a, k, p);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> best_S;

    // Algebraic construction: S = { x*2^k + x^3 } for x in GF(2^k)
    // Using alternative variable names and slightly adjusted logic
    for (int deg = 1; deg <= 15; ++deg) {
        // Early termination condition with relaxed threshold
        if ((1 << deg) > n + 150 && deg > 6) break;

        vector<int> candidate_set;
        int modulus = polys[deg];

        int field_size = 1 << deg;
        int upper_bound_x = (n >> deg) + 3;
        if (upper_bound_x > field_size) upper_bound_x = field_size;

        for (int elem = 1; elem < upper_bound_x; ++elem) {
            int cube_val = gf_pow3_v2(elem, deg, modulus);
            long long constructed_val = ((long long)elem << deg) ^ cube_val;

            if (constructed_val >= 1 && constructed_val <= n) {
                candidate_set.push_back(static_cast<int>(constructed_val));
            }
        }

        if (candidate_set.size() > best_S.size()) {
            best_S = candidate_set;
        }
    }

    // Greedy approach for small n values with improved naming
    if (n < 500) {
        vector<int> greedy_set;
        greedy_set.push_back(1);
        vector<bool> xor_tracker(2048, false); // Tracks used XOR differences

        for (int candidate = 2; candidate <= n; ++candidate) {
            bool valid = true;
            for (int existing : greedy_set) {
                int diff = candidate ^ existing;
                if (diff < 2048 && xor_tracker[diff]) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                for (int existing : greedy_set) {
                    int diff = candidate ^ existing;
                    if (diff < 2048) xor_tracker[diff] = true;
                }
                greedy_set.push_back(candidate);
            }
        }

        if (greedy_set.size() > best_S.size()) {
            best_S = greedy_set;
        }
    }

    cout << best_S.size() << "\n";
    for (size_t idx = 0; idx < best_S.size(); ++idx) {
        cout << best_S[idx];
        if (idx != best_S.size() - 1) cout << " ";
    }
    cout << "\n";

    return 0;
}

#include "arcball.h"
#include <cmath>

// Static member definition
double ArcBall::s_sphereRadius = 0.7;

ArcBall::ArcBall()
{
    // Initialize quaternion to zero rotation
    m_Quat.a  = 1.0;
    m_Quat.qx = m_Quat.qy = m_Quat.qz = 0.0;

    // Set initial orientation using Euler angles (roll-pitch-yaw)
    Quaternion qInit;
    qInit.fromEulerAngles(ROLL, PITCH, YAW);

    // Apply additional yaw offset (-30 degrees around Z-axis)
    Quaternion qYawOffset(-30.0, Vector3d(0.0, 0.0, 1.0));
    m_Quat = qYawOffset * qInit;

    // Store initial state for drag operations
    m_Start.set(0.0, 0.0, 1.0);
    m_Current = m_Start;
    m_QuatStart = m_Quat;
}

void ArcBall::applyRotation(Quaternion const &rot, bool invertOrder)
{
    if (invertOrder) {
        // Post-multiply: current * new
        m_Quat = m_Quat * rot;
    } else {
        // Pre-multiply: new * current
        m_Quat = rot * m_Quat;
    }
}

/** Update current rotation based on mouse movement */
void ArcBall::move(double mx, double my)
{
    // Map viewport coordinates to sphere surface point
    getSpherePoint(mx, my, m_Current);

    // Skip update if movement is negligible
    if ((m_Current - m_Start).norm() < 1e-8) return;

    // Compute rotation axis as cross product of start and current vectors
    Vector3d axis = m_Start.cross(m_Current);
    double lenSq = axis.normSquared();

    // Avoid division by zero or near-zero magnitudes
    if (lenSq < 1e-16) return;

    // Normalize axis
    axis /= std::sqrt(lenSq);

    // Compute angle between vectors using dot product
    double cosTheta = m_Start.dot(m_Current);
    // Clamp to avoid numerical issues with acos
    cosTheta = std::max(-1.0, std::min(1.0, cosTheta));
    double theta = std::acos(cosTheta);

    // Construct incremental rotation quaternion
    Quaternion deltaRot;
    deltaRot.fromAxisAngle(theta, axis);

    // Apply incremental rotation relative to original orientation
    m_Quat = deltaRot * m_QuatStart;
}

void ArcBall::rotateCrossPoint(float &angleDeg, float &rx, float &ry, float &rz)
{
    // Reference direction: X-axis
    Vector3d refDir(1.0, 0.0, 0.0);

    // Dot product gives cosine of angle between refDir and current vector
    double dotVal = refDir.dot(m_Current);
    // Clamp for safety
    dotVal = std::max(-1.0, std::min(1.0, dotVal));

    // Use half-angle identity: cos(theta/2) = sqrt((1 + cos(theta)) / 2)
    double cosHalf = std::sqrt(std::max(0.0, (1.0 + dotVal) * 0.5));
    double thetaRad = 2.0 * std::acos(cosHalf);
    angleDeg = static_cast<float>(thetaRad * 180.0 / M_PI);

    // Rotation axis is perpendicular to both refDir and m_Current
    Vector3d rotAxis = refDir.cross(m_Current);
    double axisLen = rotAxis.norm();
    if (axisLen > 1e-12) {
        rotAxis /= axisLen;
    } else {
        // Degenerate case: vectors are parallel; choose arbitrary orthogonal axis
        rotAxis.set(0.0, 1.0, 0.0);
    }

    rx = static_cast<float>(rotAxis.x());
    ry = static_cast<float>(rotAxis.y());
    rz = static_cast<float>(rotAxis.z());
}

void ArcBall::setQuat(double w, double x, double y, double z)
{
    m_Quat.a  = w;
    m_Quat.qx = x;
    m_Quat.qy = y;
    m_Quat.qz = z;
}

void ArcBall::start(double mx, double my)
{
    // Capture starting point on sphere
    getSpherePoint(mx, my, m_Start);
    m_Current = m_Start;
    // Save current orientation before dragging begins
    m_QuatStart = m_Quat;
}

/** Convert 2D viewport coords to 3D point on unit sphere */
void ArcBall::getSpherePoint(double vx, double vy, Vector3d &pt)
{
    double r2 = s_sphereRadius * s_sphereRadius;
    double distSq = vx * vx + vy * vy;

    if (distSq <= r2) {
        pt.set(vx, vy, std::sqrt(r2 - distSq));
    } else {
        // Project outside points radially onto sphere boundary (z=0)
        pt.set(vx, vy, 0.0);
    }

    pt.normalize();
}

