namespace {
class BlobAllocator {
public:
  size_t position() const { return CurrentOffset; }

  size_t reserveSpace(size_t Bytes,
                      std::function<void(raw_ostream &)> Writer) {
    size_t Pos = CurrentOffset;
    CurrentOffset += Bytes;
    WriteTasks.push_back(std::move(Writer));
    return Pos;
  }

  size_t storeRawBytes(ArrayRef<uint8_t> Input) {
    return reserveSpace(Input.size(), [Input](raw_ostream &OS) {
      OS << toStringRef(Input);
    });
  }

  size_t storeRawBytes(yaml::BinaryRef Input) {
    return reserveSpace(Input.binary_size(), [Input](raw_ostream &OS) {
      Input.writeAsBinary(OS);
    });
  }

  template <typename T>
  size_t storeVector(ArrayRef<T> Elements) {
    return storeRawBytes({reinterpret_cast<const uint8_t *>(Elements.data()),
                          sizeof(T) * Elements.size()});
  }

  template <typename T, typename RangeType>
  std::pair<size_t, MutableArrayRef<T>>
  createAndStoreArray(const iterator_range<RangeType> &Items);

  template <typename T>
  size_t storeInstance(const T &Value) {
    return storeVector(ArrayRef(Value));
  }

  template <typename T, typename... Args>
  std::pair<size_t, T *> createNewInstance(Args &&... Values) {
    T *Instance = new (Storage.Allocate<T>()) T(std::forward<Args>(Values)...);
    return {storeInstance(*Instance), Instance};
  }

  size_t storeWideString(StringRef Text);

  void emitToStream(raw_ostream &OS) const;

private:
  size_t CurrentOffset = 0;
  BumpPtrAllocator Storage;
  std::vector<std::function<void(raw_ostream &)>> WriteTasks;
};
} // namespace

template <typename T, typename RangeType>
std::pair<size_t, MutableArrayRef<T>>
BlobAllocator::createAndStoreArray(const iterator_range<RangeType> &Items) {
  size_t Count = std::distance(Items.begin(), Items.end());
  MutableArrayRef<T> Buffer(Storage.Allocate<T>(Count), Count);
  std::uninitialized_copy(Items.begin(), Items.end(), Buffer.begin());
  return {storeVector(Buffer), Buffer};
}

size_t BlobAllocator::storeWideString(StringRef Text) {
  SmallVector<UTF16, 32> WideBuffer;
  bool Success = convertUTF8ToUTF16String(Text, WideBuffer);
  assert(Success && "Non-UTF8 string provided!");
  (void)Success;

  WideBuffer.push_back(0); // Null terminator not included in length
  size_t ByteSize = 2 * (WideBuffer.size() - 1);
  size_t LengthOffset = createNewInstance<support::ulittle32_t>(ByteSize).first;
  createAndStoreArray<support::ulittle16_t>(make_range(WideBuffer.begin(), WideBuffer.end()));
  return LengthOffset;
}

void BlobAllocator::emitToStream(raw_ostream &OS) const {
  size_t StartPos = OS.tell();
  for (const auto &Task : WriteTasks)
    Task(OS);
  assert(OS.tell() == StartPos + CurrentOffset &&
         "Mismatch in expected vs actual byte count.");
  (void)StartPos;
}

static LocationDescriptor assignLocation(BlobAllocator &Context, yaml::BinaryRef Content) {
  return {support::ulittle32_t(Content.binary_size()),
          support::ulittle32_t(Context.storeRawBytes(Content))};
}

static size_t assignLocation(BlobAllocator &Context, MinidumpYAML::ExceptionStream &E) {
  Context.storeInstance(E.MDExceptionStream);
  size_t EndPosition = Context.position();

  E.MDExceptionStream.ThreadContext = assignLocation(Context, E.ThreadContext);
  return EndPosition;
}

static void assignLocation(BlobAllocator &Context, MemoryListStream::entry_type &Range) {
  Range.Entry.Memory = assignLocation(Context, Range.Content);
}

static void assignLocation(BlobAllocator &Context, ModuleListStream::entry_type &M) {
  M.Entry.ModuleNameRVA = Context.storeWideString(M.Name);
  M.Entry.CvRecord = assignLocation(Context, M.CvRecord);
  M.Entry.MiscRecord = assignLocation(Context, M.MiscRecord);
}

static void assignLocation(BlobAllocator &Context, ThreadListStream::entry_type &T) {
  T.Entry.Stack.Memory = assignLocation(Context, T.Stack);
  T.Entry.Context = assignLocation(Context, T.Context);
}

template <typename EntryT>
static size_t assignLocation(BlobAllocator &Context,
                             MinidumpYAML::detail::ListStream<EntryT> &S) {
  Context.createNewObject<support::ulittle32_t>(S.Entries.size());
  for (auto &Item : S.Entries)
    Context.storeInstance(Item.Entry);

  size_t FinalOffset = Context.position();
  for (auto &Item : S.Entries)
    assignLocation(Context, Item);
  return FinalOffset;
}

static Directory assignLocation(BlobAllocator &Context, Stream &S) {
  Directory Result;
  Result.Type = S.Type;
  Result.Location.RVA = Context.position();
  std::optional<size_t> DataEnd;

  switch (S.Kind) {
  case Stream::StreamKind::Exception:
    DataEnd = assignLocation(Context, cast<MinidumpYAML::ExceptionStream>(S));
    break;
  case Stream::StreamKind::MemoryInfoList: {
    MemoryInfoListStream &InfoList = cast<MemoryInfoListStream>(S);
    Context.createNewObject<minidump::MemoryInfoListHeader>(
        sizeof(minidump::MemoryInfoListHeader), sizeof(minidump::MemoryInfo),
        InfoList.Infos.size());
    Context.storeVector(ArrayRef(InfoList.Infos));
    break;
  }
  case Stream::StreamKind::MemoryList:
    DataEnd = assignLocation(Context, cast<MemoryListStream>(S));
    break;
  case Stream::StreamKind::ModuleList:
    DataEnd = assignLocation(Context, cast<ModuleListStream>(S));
    break;
  case Stream::StreamKind::RawContent: {
    RawContentStream &Raw = cast<RawContentStream>(S);
    Context.reserveSpace(Raw.Size, [&Raw](raw_ostream &OS) {
      Raw.Content.writeAsBinary(OS);
      assert(Raw.Content.binary_size() <= Raw.Size);
      OS << std::string(Raw.Size - Raw.Content.binary_size(), '\0');
    });
    break;
  }
  case Stream::StreamKind::SystemInfo: {
    SystemInfoStream &SysInfo = cast<SystemInfoStream>(S);
    Context.storeInstance(SysInfo.Info);
    DataEnd = Context.position();
    SysInfo.Info.CSDVersionRVA = Context.storeWideString(SysInfo.CSDVersion);
    break;
  }
  case Stream::StreamKind::TextContent:
    Context.storeVector(arrayRefFromStringRef(cast<TextContentStream>(S).Text));
    break;
  case Stream::StreamKind::ThreadList:
    DataEnd = assignLocation(Context, cast<ThreadListStream>(S));
    break;
  }

  Result.Location.DataSize =
      DataEnd.value_or(Context.position()) - Result.Location.RVA;
  return Result;
}

namespace llvm {
namespace yaml {
bool yaml2minidump(MinidumpYAML::Object &Obj, raw_ostream &Out,
                   ErrorHandler /*EH*/) {
  BlobAllocator Context;
  Context.storeInstance(Obj.Header);

  std::vector<Directory> DirectoryTable(Obj.Streams.size());
  Obj.Header.StreamDirectoryRVA = Context.storeVector(ArrayRef(DirectoryTable));
  Obj.Header.NumberOfStreams = DirectoryTable.size();

  for (const auto &[Index, Stream] : enumerate(Obj.Streams))
    DirectoryTable[Index] = assignLocation(Context, *Stream);

  Context.emitToStream(Out);
  return true;
}
} // namespace yaml
} // namespace llvm

