#include "superkmeans/hierarchical_superkmeans.h"
#include "superkmeans/superkmeans.h"

int main(int argc, char* argv[]) {
    std::string dataset_name = (argc > 1) ? std::string(argv[1]) : std::string("yahoo");

    auto param_iter = bench_utils::DATASET_PARAMS.find(dataset_name);
    if (param_iter == bench_utils::DATASET_PARAMS.end()) {
        std::cerr << "Unknown dataset '" << dataset_name << "'\n";
        return 1;
    }

    const size_t num_points = param_iter->second.first;
    const size_t dim = param_iter->second.second;
    const size_t cluster_count = 40000; // bench_utils::get_default_n_clusters(num_points);
    int max_iterations = 5;
    float sample_ratio = 1.0f;

    std::string data_file = bench_utils::get_data_path(dataset_name);
    const size_t thread_limit = omp_get_max_threads();
    omp_set_num_threads(thread_limit);

    std::cout << "=== Assign Benchmark ===" << std::endl;
    std::cout << "Dataset: " << dataset_name << " (n=" << num_points << ", d=" << dim << ")\n";
    std::cout << "cluster_count=" << cluster_count << " max_iterations=" << max_iterations
              << " sample_ratio=" << sample_ratio << "\n";

    std::vector<float> point_data;
    try {
        point_data.reserve(num_points * dim);
    } catch (const std::bad_alloc& err) {
        std::cerr << "Memory allocation failed for " << (num_points * dim) << " floats: " << err.what() << "\n";
        return 1;
    }

    std::ifstream input_stream(data_file, std::ios::binary);
    if (!input_stream) {
        std::cerr << "Could not open file: " << data_file << std::endl;
        return 1;
    }
    input_stream.read(reinterpret_cast<char*>(point_data.data()), num_points * dim * sizeof(float));
    input_stream.close();

    // Configure hierarchical super k-means
    skmeans::HierarchicalSuperKMeansConfig setup;
    setup.iters_mesoclustering = 3;
    setup.iters_fineclustering = 5;
    setup.iters_refinement = 0;
    setup.verbose = false;
    setup.n_threads = thread_limit;
    setup.unrotate_centroids = true;
    setup.early_termination = false;
    setup.sampling_fraction = sample_ratio;
    setup.use_blas_only = false;

    bool is_spherical = false;
    for (const auto& angular_ds : bench_utils::ANGULAR_DATASETS) {
        if (angular_ds == dataset_name) {
            is_spherical = true;
            break;
        }
    }
    if (is_spherical) {
        std::cout << "Using spherical k-means" << std::endl;
        setup.angular = true;
    }

    skmeans::HierarchicalSuperKMeans<skmeans::Quantization::f32, skmeans::DistanceFunction::l2>
        clusterer(cluster_count, dim, setup);

    bench_utils::TicToc training_timer;
    training_timer.Tic();
    auto centroid_matrix = clusterer.Train(point_data.data(), num_points);
    training_timer.Toc();
    std::cout << "\nTraining completed in " << training_timer.GetMilliseconds() << " ms" << std::endl;

    // Fast assignment path
    bench_utils::TicToc fast_assign_timer;
    fast_assign_timer.Tic();
    auto fast_labels = clusterer.FastAssign(point_data.data(), centroid_matrix.data(), num_points, cluster_count);
    fast_assign_timer.Toc();
    double fast_duration = fast_assign_timer.GetMilliseconds();
    std::cout << "\nFastAssign: " << fast_duration << " ms" << std::endl;

    // Brute-force assignment path
    bench_utils::TicToc brute_force_timer;
    brute_force_timer.Tic();
    auto brute_labels = clusterer.Assign(point_data.data(), centroid_matrix.data(), num_points, cluster_count);
    brute_force_timer.Toc();
    double brute_duration = brute_force_timer.GetMilliseconds();
    std::cout << "Assign:     " << brute_duration << " ms" << std::endl;

    // Comparison
    double ratio = brute_duration / fast_duration;
    size_t agreement_count = 0;
    for (size_t idx = 0; idx < num_points; ++idx) {
        if (fast_labels[idx] == brute_labels[idx]) {
            ++agreement_count;
        }
    }
    double match_rate = 100.0 * static_cast<double>(agreement_count) / static_cast<double>(num_points);

    std::cout << "\nSpeedup: " << ratio << "x" << std::endl;
    std::cout << "Agreement: " << match_rate << "% (" << agreement_count << "/" << num_points << ")" << std::endl;

    return 0;
}

