#include <vector>
using namespace std;

int countCoinCombinations(const vector<int>& coins, int target) {
    int count = 0;

    // Use iterative approach with nested loops for small number of coin types
    // For general case, use recursion but with different structure
    if (coins.empty()) return 0;

    // Helper lambda using iterative DFS with explicit stack
    auto dfs = [&](auto&& self, int idx, int current_sum) -> void {
        if (current_sum == target) {
            count++;
            return;
        }
        if (current_sum > target || idx >= coins.size()) {
            return;
        }

        // Option 1: Use current coin and stay at same index (can reuse)
        self(self, idx, current_sum + coins[idx]);
        // Option 2: Skip current coin and move to next
        self(self, idx + 1, current_sum);
    };

    dfs(dfs, 0, 0);
    return count;
}

#include <thread>
#include <small_gicp/points/point_cloud.hpp>
#include <small_gicp/ann/kdtree.hpp>
#include <small_gicp/ann/kdtree_omp.hpp>
#include <small_gicp/util/downsampling.hpp>
#include <small_gicp/benchmark/benchmark.hpp>
#ifdef BUILD_WITH_TBB
#include <small_gicp/ann/kdtree_tbb.hpp>
#endif

int main(int argc, char** argv) {
  using namespace small_gicp;

  if (argc < 2) {
    std::cout << "USAGE: kdtree_benchmark <dataset_path>" << std::endl;
    std::cout << "OPTIONS:" << std::endl;
    std::cout << "  --num_threads <value> (default: 4)" << std::endl;
    std::cout << "  --num_trials <value> (default: 100)" << std::endl;
    std::cout << "  --method <str> (small|omp|tbb)" << std::endl;
    return 0;
  }

  const std::string dataset_path = argv[1];
  int num_threads = 4;
  size_t num_repetitions = 100;
  std::string backend = "small";

  // Parse command-line arguments
  int idx = 2;
  while (idx < argc) {
    const std::string token = argv[idx];
    if (token == "--num_threads") {
      if (++idx >= argc) break;
      num_threads = std::stoi(argv[idx]);
    } else if (token == "--num_trials") {
      if (++idx >= argc) break;
      num_repetitions = static_cast<size_t>(std::stoi(argv[idx]));
    } else if (token == "--method") {
      if (++idx >= argc) break;
      backend = argv[idx];
    } else if (!token.empty() && token[0] == '-' && token[1] == '-') {
      std::cerr << "Unknown option: " << token << std::endl;
      return 1;
    }
    ++idx;
  }

  std::cout << "dataset_path=" << dataset_path << std::endl;
  std::cout << "num_threads=" << num_threads << std::endl;
  std::cout << "num_trials=" << num_repetitions << std::endl;
  std::cout << "method=" << backend << std::endl;

#ifdef BUILD_WITH_TBB
  tbb::global_control tbb_limit(tbb::global_control::max_allowed_parallelism, num_threads);
#endif

  KittiDataset kitti(dataset_path, 1);
  auto input_cloud = std::make_shared<PointCloud>(kitti.points[0]);
  std::cout << "num_raw_points=" << input_cloud->size() << std::endl;

  // Binary search to find voxel grid resolution that yields ~target_num_points
  auto compute_voxel_resolution = [&](size_t target_count) -> double {
    double low_res = 0.1;
    size_t low_count = voxelgrid_sampling(*input_cloud, low_res)->size();

    double high_res = 1.0;
    size_t high_count = voxelgrid_sampling(*input_cloud, high_res)->size();

    // Expand bounds if needed
    while (low_count < target_count && low_res > 1e-6) {
      low_res *= 0.1;
      low_count = voxelgrid_sampling(*input_cloud, low_res)->size();
    }
    while (high_count > target_count && high_res < 1e6) {
      high_res *= 10.0;
      high_count = voxelgrid_sampling(*input_cloud, high_res)->size();
    }

    // Refine via bisection
    for (int iter = 0; iter < 20; ++iter) {
      double mid_res = (low_res + high_res) * 0.5;
      size_t mid_count = voxelgrid_sampling(*input_cloud, mid_res)->size();

      double relative_error = std::abs(1.0 - static_cast<double>(mid_count) / target_count);
      if (relative_error < 0.001) {
        return mid_res;
      }

      if (mid_count > target_count) {
        low_res = mid_res;
        low_count = mid_count;
      } else {
        high_res = mid_res;
        high_count = mid_count;
      }
    }

    return (low_res + high_res) * 0.5;
  };

  std::cout << "---" << std::endl;

  std::vector<double> resolutions_list;
  std::vector<PointCloud::Ptr> sampled_clouds;

  for (double ratio = 1.0; ratio > 0.05; ratio -= 0.1) {
    const size_t target_points = static_cast<size_t>(input_cloud->size() * ratio);
    const double res = compute_voxel_resolution(target_points);
    resolutions_list.push_back(res);
    sampled_clouds.push_back(voxelgrid_sampling(*input_cloud, res));

    std::cout << "downsampling_resolution=" << res << std::endl;
    std::cout << "num_points=" << sampled_clouds.back()->size() << std::endl;
  }

  std::cout << "---" << std::endl;

  // Warm-up phase: ensure JIT/compiler optimizations stabilize
  auto start_warmup = std::chrono::steady_clock::now();
  while (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - start_warmup).count() < 1) {
    auto temp_cloud = voxelgrid_sampling(*input_cloud, 0.1);
    if (backend == "small") {
      UnsafeKdTree<PointCloud> tree(*temp_cloud);
    } else if (backend == "omp") {
      UnsafeKdTree<PointCloud> tree(*temp_cloud, KdTreeBuilderOMP(num_threads));
    }
#ifdef BUILD_WITH_TBB
    else if (backend == "tbb") {
      UnsafeKdTree<PointCloud> tree(*temp_cloud, KdTreeBuilderTBB());
    }
#endif
  }

  Stopwatch timer;
  if (backend == "small") {
    for (size_t i = 0; i < resolutions_list.size(); ++i) {
      if (num_threads != 1) {
        break;
      }
      BenchmarkStats builder_times(true);
      timer.start();
      for (size_t rep = 0; rep < num_repetitions; ++rep) {
        UnsafeKdTree<PointCloud> tree(*sampled_clouds[i]);
        timer.lap();
        builder_times.record(timer.msec());
      }
      std::cout << "kdtree_build_time=" << builder_times.summary() << " [msec]" << std::endl;
    }
  } else if (backend == "omp") {
    for (size_t i = 0; i < resolutions_list.size(); ++i) {
      BenchmarkStats omp_stats(true);
      timer.start();
      for (size_t rep = 0; rep < num_repetitions; ++rep) {
        UnsafeKdTree<PointCloud> tree(*sampled_clouds[i], KdTreeBuilderOMP(num_threads));
        timer.lap();
        omp_stats.record(timer.msec());
      }
      std::cout << "kdtree_omp_time=" << omp_stats.summary() << " [msec]" << std::endl;
    }
  }
#ifdef BUILD_WITH_TBB
  else if (backend == "tbb") {
    for (size_t i = 0; i < resolutions_list.size(); ++i) {
      BenchmarkStats tbb_stats(true);
      timer.start();
      for (size_t rep = 0; rep < num_repetitions; ++rep) {
        UnsafeKdTree<PointCloud> tree(*sampled_clouds[i], KdTreeBuilderTBB());
        timer.lap();
        tbb_stats.record(timer.msec());
      }
      std::cout << "kdtree_tbb_time=" << tbb_stats.summary() << " [msec]" << std::endl;
    }
  }
#endif

  return 0;
}

#include <cctype>
#include <cassert>

// Adjust numeric formatting to ensure locale-independent decimal representation
static void upb_FixLocale(char* p) {
  /* printf() may produce locale-specific output (e.g., commas for decimals);
   * this function normalizes such outputs to JSON-compatible format by
   * replacing commas with periods. */
  while (*p != '\0') {
    if (*p == ',') {
      *p = '.';
    }
    ++p;
  }
}

void _upb_EncodeRoundTripDouble(double val, char* buf, size_t size) {
  assert(size >= kUpb_RoundTripBufferSize);

  // First attempt with standard precision
  snprintf(buf, size, "%.*g", DBL_DIG, val);

  // Verify round-trip correctness; if not exact, increase precision
  if (strtod(buf, nullptr) != val) {
    snprintf(buf, size, "%.*g", DBL_DIG + 2, val);
    assert(strtod(buf, nullptr) == val);
  }

  // Ensure consistent decimal separator
  upb_FixLocale(buf);
}

void _upb_EncodeRoundTripFloat(float val, char* buf, size_t size) {
  assert(size >= kUpb_RoundTripBufferSize);

  // Initial encoding using float-specific precision
  snprintf(buf, size, "%.*g", FLT_DIG, val);

  // Validate precision; extend if needed
  if (strtof(buf, nullptr) != val) {
    snprintf(buf, size, "%.*g", FLT_DIG + 3, val);
    assert(strtof(buf, nullptr) == val);
  }

  // Normalize locale-dependent formatting
  upb_FixLocale(buf);
}

