#include <bits/stdc++.h>
using namespace std;

struct Firm {
    int x, y, r, original_index;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Firm> firms(n);

    for (int i = 0; i < n; ++i) {
        cin >> firms[i].x >> firms[i].y >> firms[i].r;
        firms[i].original_index = i;
    }

    // Sort by y-coordinate ascending
    sort(firms.begin(), firms.end(), [](const Firm& a, const Firm& b) {
        return a.y < b.y;
    });

    // Compute cumulative ideal positions (in ten-thousandths)
    vector<double> cumulative(n + 1, 0.0);
    for (int i = 0; i < n; ++i) {
        cumulative[i + 1] = cumulative[i] + static_cast<double>(firms[i].r) / 10000.0;
    }

    // Determine boundary positions
    vector<int> boundaries(n + 1);
    boundaries[0] = 0;

    for (int k = 1; k < n; ++k) {
        int min_val = firms[k - 1].y + 1;
        int max_val = firms[k].y;
        double target = cumulative[k];
        int candidate = static_cast<int>(round(target));
        boundaries[k] = max(min_val, min(max_val, candidate));
    }

    boundaries[n] = 10000;

    // Prepare output arrays
    vector<int> A(n), B(n), C(n), D(n);

    for (int idx = 0; idx < n; ++idx) {
        int orig_pos = firms[idx].original_index;
        int lower_bound = boundaries[idx];
        int upper_bound = boundaries[idx + 1];

        A[orig_pos] = 0;
        B[orig_pos] = lower_bound;
        C[orig_pos] = 10000;
        D[orig_pos] = upper_bound;
    }

    // Output results in original order
    for (int i = 0; i < n; ++i) {
        cout << A[i] << " " << B[i] << " " << C[i] << " " << D[i] << "\n";
    }

    return 0;
}

