#ifdef HAVE_MPI
    OED_SplitComm<int, Teuchos::MpiComm<int>> splitcomm(1);
    dcomm = splitcomm.getDesignComm();
    ocomm = splitcomm.getSampleComm();
#else
    dcomm = ROL::makePtr<Teuchos::SerialComm<int>>();
    ocomm = Tpetra::getDefaultComm();
#endif

    int drank = dcomm->getRank();
    int orank = ocomm->getRank();
    bool iprint = shouldPrint(argc, drank, orank);
    auto outStream = ROL::makeStreamPtr(std::cout, iprint);

    int errorFlag = 0;

    try {
        RealT tolerance(1e-8);

        // Load parameters from XML
        auto parlist = ROL::getParametersFromXmlFile("input.xml");

        // Extract configuration values
        int numSpeakers = 8;
        bool checkDeriv = parlist->sublist("Problem").get("Check Derivatives", false);
        int verbosity   = parlist->sublist("General").get("Print Verbosity", 0);
        bool alPrint    = parlist->sublist("Step").sublist("Augmented Lagrangian")
                            .get("Print Intermediate Optimization History", false);

        // Adjust verbosity for non-root ranks
        if (!iprint) {
            verbosity = 0;
            alPrint = false;
        }
        parlist->sublist("General").set("Print Verbosity", verbosity);
        parlist->sublist("Step").sublist("Augmented Lagrangian")
            .set("Print Intermediate Optimization History", alPrint);

        // Initialize PDE and constraint
        auto meshMgr = ROL::makePtr<MeshReader<RealT, DeviceT>>(*parlist);
        auto pde     = ROL::makePtr<PDE_Helmholtz_OCT<RealT, DeviceT>>(*parlist);
        auto con     = ROL::makePtr<Linear_PDE_Constraint<RealT, DeviceT>>(
                          pde, meshMgr, dcomm, *parlist, *outStream);
        auto assembler = con->getAssembler();
        con->printMeshData(*outStream);

        // Create vectors
        auto u_ptr = assembler->createStateVector();
        auto r_ptr = assembler->createResidualVector();
        auto up    = ROL::makePtr<PDE_PrimalSimVector<RealT, DeviceT>>(u_ptr, pde, assembler, *parlist);
        auto rp    = ROL::makePtr<PDE_DualSimVector<RealT, DeviceT>>(r_ptr, pde, assembler, *parlist);
        auto zp    = ROL::makePtr<ROL::StdVector<RealT>>(numSpeakers);

        // Observation model
        auto qoi = ROL::makePtr<QoI_Helmholtz_Observation<RealT, DeviceT>>(pde->getFE(), *parlist);
        auto obs = ROL::makePtr<PDE_Objective<RealT, DeviceT>>(qoi, assembler);

        // Derivative checks
        if (checkDeriv) {
            up->randomize(); zp->randomize();
            auto dup = up->clone(); dup->randomize();
            auto dzp = zp->clone(); dzp->randomize();
            ROL::Vector_SimOpt<RealT> uz(up, zp), duz(dup, dzp);
            std::vector<RealT> dummyParams(2, 0.0);
            obs->setParameter(dummyParams);

            *outStream << "\n\nCheck Jacobian_1 of PDE Constraint\n";
            con->checkApplyJacobian_1(*up, *zp, *dup, *rp, true, *outStream);
            *outStream << "\n\nCheck Jacobian_2 of PDE Constraint\n";
            con->checkApplyJacobian_2(*up, *zp, *dzp, *rp, true, *outStream);
            *outStream << "\n\nCheck Gradient of Full Objective Function\n";
            obs->checkGradient(uz, duz, true, *outStream);
            *outStream << "\n\nCheck Hessian of Full Objective Function\n";
            obs->checkHessVec(uz, duz, true, *outStream);
        }

        // Solve for each speaker state
        *outStream << std::endl << "Begin: PDE Solves" << std::endl;
        std::vector<ROL::Ptr<ROL::Vector<RealT>>> states(numSpeakers);
        for (int idx = 0; idx < numSpeakers; ++idx) {
            std::clock_t start_time = std::clock();
            con->solve(*rp, *up, *zp->basis(idx), tolerance);
            states[idx] = up->clone();
            states[idx]->set(*up);

            std::ostringstream fname;
            fname << "state_" << idx << ".txt";
            con->outputTpetraVector(u_ptr, fname.str());

            RealT elapsed = static_cast<RealT>(std::clock() - start_time) / CLOCKS_PER_SEC;
            *outStream << "  Solve " << idx << " time:      " << elapsed << std::endl;
        }
        *outStream << "End: PDE Solves" << std::endl << std::endl;

        // Build reduced objective
        auto theta = ROL::makePtr<ROL::StdVector<RealT>>(numSpeakers, 1.0);
        auto model = ROL::makePtr<ROL::Reduced_Objective_SimOpt<RealT>>(
                        obs, con, up, theta, up, false);

        // Setup sampling
        std::string pd_file = parlist->sublist("Problem").sublist("Design")
                                .get("Points File", "points_5000.txt");
        std::string wd_file = parlist->sublist("Problem").sublist("Design")
                                .get("Weights File", "weights_5000.txt");
        int numDesignSamples = parlist->sublist("Problem").sublist("Design")
                                .get("Number of Samples", 5000);

        std::string po_file = parlist->sublist("Problem").sublist("Objective")
                                .get("Points File", "points_200.txt");
        std::string wo_file = parlist->sublist("Problem").sublist("Objective")
                                .get("Weights File", "weights_200.txt");
        int numObsSamples = parlist->sublist("Problem").sublist("Objective")
                                .get("Number of Samples", 200);

        *outStream << std::endl;
        *outStream << "  Design Points File:     " << pd_file << std::endl;
        *outStream << "  Design Weights File:    " << wd_file << std::endl;
        *outStream << "  Objective Points File:  " << po_file << std::endl;
        *outStream << "  Objective Weights File: " << wo_file << std::endl;
        *outStream << std::endl;

        auto dbman = ROL::makePtr<ROL::StdTeuchosBatchManager<RealT, int>>(dcomm);
        auto obman = ROL::makePtr<ROL::StdTeuchosBatchManager<RealT, int>>(ocomm);
        auto dsampler = ROL::makePtr<ROL::UserInputGenerator<RealT>>(pd_file, wd_file, numDesignSamples, 2, dbman);
        auto osampler = ROL::makePtr<ROL::UserInputGenerator<RealT>>(po_file, wo_file, numObsSamples, 2, obman);

        // Regression and noise model
        bool homoscedastic = parlist->sublist("Problem").get("Homoscedastic Noise", true);
        std::string regType = parlist->sublist("Problem").get("Regression Type", "Least Squares");
        auto regressionType = ROL::OED::StringToRegressionType(regType);
        auto noiseModel = ROL::makePtr<Helmholtz_Noise<RealT>>();
        auto momentOp = ROL::makePtr<ROL::OED::StdMomentOperator<RealT>>(
                            regressionType, homoscedastic, noiseModel);
        auto factory = ROL::makePtr<ROL::OED::Factory<RealT>>(
                            model, dsampler, theta, momentOp, *parlist);

        obman->barrier();

        // Optional factor output
        bool printFactors = parlist->sublist("Problem").get("Print Factors", false);
        if (printFactors) {
            std::ofstream fact_d, noise_d, fact_o, noise_o;
            std::stringstream factName_d, noiseName_d, factName_o, noiseName_o;
            ROL::Ptr<ROL::Vector<RealT>> factorVec = zp->dual().clone();
            std::vector<RealT> point;

            // Design-space factors
            factName_d << "factors_des_" << dsampler->batchID() << ".txt";
            noiseName_d << "noise_des_" << dsampler->batchID() << ".txt";
            fact_d.open(factName_d.str());
            noise_d.open(noiseName_d.str());
            fact_d << std::scientific << std::setprecision(15);
            noise_d << std::scientific << std::setprecision(15);

            auto factors = factory->getFactors(theta);
            for (int i = 0; i < dsampler->numMySamples(); ++i) {
                point = dsampler->getMyPoint(i);
                factors->evaluate(*factorVec, point);
                for (int j = 0; j < numSpeakers; ++j) {
                    fact_d << std::right << std::setw(25)
                           << (*dynamic_cast<ROL::StdVector<RealT>*>(factorVec.get())->getVector())[j];
                }
                fact_d << std::endl;
                for (int j = 0; j < 2; ++j)
                    noise_d << std::right << std::setw(25) << point[j];
                noise_d << std::right << std::setw(25) << noiseModel->evaluate(point) << std::endl;
            }
            fact_d.close();
            noise_d.close();

            // Observation-space factors
            factName_o << "factors_opt_" << osampler->batchID() << ".txt";
            noiseName_o << "noise_opt_" << osampler->batchID() << ".txt";
            fact_o.open(factName_o.str());
            noise_o.open(noiseName_o.str());
            fact_o << std::scientific << std::setprecision(15);
            noise_o << std::scientific << std::setprecision(15);

            for (int i = 0; i < osampler->numMySamples(); ++i) {
                point = osampler->getMyPoint(i);
                factors->evaluate(*factorVec, point);
                for (int j = 0; j < numSpeakers; ++j) {
                    fact_o << std::right << std::setw(25)
                           << (*dynamic_cast<ROL::StdVector<RealT>*>(factorVec.get())->getVector())[j];
                }
                fact_o << std::endl;
                for (int j = 0; j < 2; ++j)
                    noise_o << std::right << std::setw(25) << point[j];
                noise_o << std::right << std::setw(25) << noiseModel->evaluate(point) << std::endl;
            }
            fact_o.close();
            noise_o.close();
        }

        // Solve OED problem
        std::string optType = parlist->sublist("OED").get("Optimality Type", "A");
        bool useUniformGuess = parlist->sublist("Problem").get("Uniform Initial Guess", false);
        solve<RealT>(factory, dsampler, osampler, *parlist, optType, *outStream, useUniformGuess, checkDeriv);

        // Final summary
        Teuchos::TimeMonitor::summarize();
    }
    catch (const std::logic_error& err) {
        std::cout << "Design MPI Rank = " << drank
                  << "  Objective MPI Rank = " << orank
                  << std::endl << err.what() << std::endl;
        errorFlag = -1000;
    }

    if (errorFlag != 0) {
        std::cout << "End Result: TEST FAILED\n";
    } else {
        std::cout << "End Result: TEST PASSED\n";
    }

    return 0;
}

