using namespace aeronet;

// Helper to extract extension from filename in a case-insensitive manner
static std::string ExtractExtension(const std::string& filename) {
  auto dotPos = filename.find_last_of('.');
  if (dotPos == std::string::npos || dotPos == filename.size() - 1) {
    return "";
  }
  std::string ext = filename.substr(dotPos + 1);
  std::transform(ext.begin(), ext.end(), ext.begin(),
                 [](unsigned char c) { return std::tolower(c); });
  return ext;
}

TEST(MIMEMappings, ContainsKnownExtension) {
  // Verify several standard extensions map correctly
  std::string file1 = "file.html";
  std::string ext1 = ExtractExtension(file1);
  auto idx1 = DetermineMIMETypeIdx(file1);
  EXPECT_NE(idx1, kUnknownMIMEMappingIdx);
  if (idx1 != kUnknownMIMEMappingIdx) {
    EXPECT_STREQ(kMIMEMappings[idx1].mimeType, "text/html");
  }

  std::string file2 = "image.jpeg";
  std::string ext2 = ExtractExtension(file2);
  auto idx2 = DetermineMIMETypeIdx(file2);
  EXPECT_NE(idx2, kUnknownMIMEMappingIdx);
  if (idx2 != kUnknownMIMEMappingIdx) {
    EXPECT_STREQ(kMIMEMappings[idx2].mimeType, "image/jpeg");
  }

  std::string file3 = "script.js";
  std::string ext3 = ExtractExtension(file3);
  auto idx3 = DetermineMIMETypeIdx(file3);
  EXPECT_NE(idx3, kUnknownMIMEMappingIdx);
  if (idx3 != kUnknownMIMEMappingIdx) {
    EXPECT_STREQ(kMIMEMappings[idx3].mimeType, "text/javascript");
  }
}

TEST(MIMEMappings, UnknownExtension) {
  EXPECT_EQ(DetermineMIMETypeIdx("file.unknownext"), kUnknownMIMEMappingIdx);
  EXPECT_EQ(DetermineMIMETypeIdx("file.00a"), kUnknownMIMEMappingIdx);
  EXPECT_EQ(DetermineMIMETypeIdx("file.zzz"), kUnknownMIMEMappingIdx);
}

TEST(MIMEMappings, CaseInsensitiveExtensions) {
  std::string upperCase = "UPPER.HTML";
  std::string lowerCase = "upper.html";
  auto idxU = DetermineMIMETypeIdx(upperCase);
  auto idxL = DetermineMIMETypeIdx(lowerCase);
  EXPECT_EQ(idxU, idxL);
}

TEST(MIMEMappings, MultiDotFilenames) {
  std::string path = "archive.tar.gz";
  auto idx = DetermineMIMETypeIdx(path);
  EXPECT_NE(idx, kUnknownMIMEMappingIdx);
  if (idx != kUnknownMIMEMappingIdx) {
    EXPECT_STREQ(kMIMEMappings[idx].mimeType, "application/gzip");
  }
}

TEST(MIMEMappings, SortedAndUnique) {
  constexpr std::size_t count = sizeof(kMIMEMappings) / sizeof(kMIMEMappings[0]);
  for (std::size_t i = 1; i < count; ++i) {
    const char* prevExt = kMIMEMappings[i - 1].extension;
    const char* curExt = kMIMEMappings[i].extension;
    EXPECT_STRNE(prevExt, curExt) << "Duplicate extension at index " << i;
    EXPECT_LT(std::string(prevExt), std::string(curExt))
        << "Mappings not sorted at index " << (i - 1);
  }
}

TEST(MIMEMappingsTest, CommonExtensions) {
  EXPECT_STREQ(DetermineMIMETypeStr("sample.md"), "text/markdown");
  EXPECT_STREQ(DetermineMIMETypeStr("archive.tar.gz"), "application/gzip");
  EXPECT_STREQ(DetermineMIMETypeStr("index.HTML"), "text/html");
  EXPECT_STREQ(DetermineMIMETypeStr("UPPER.TXT"), "text/plain");
}

TEST(MIMEMappingsTest, EdgeCases) {
  // No dot → unknown
  EXPECT_TRUE(DetermineMIMETypeStr("file").empty());
  // Trailing dot → unknown
  EXPECT_TRUE(DetermineMIMETypeStr("file.").empty());
  // Hidden files without extension part → unknown
  EXPECT_TRUE(DetermineMIMETypeStr(".bashrc").empty());
}

TEST(MIMEMappingsTest, MaxExtensionLengthBehavior) {
  // Find longest extension in table
  std::size_t maxLen = 0;
  const char* longestExt = nullptr;
  const char* longestMimeType = nullptr;

  for (std::size_t i = 0; i < sizeof(kMIMEMappings) / sizeof(kMIMEMappings[0]); ++i) {
    std::size_t len = std::strlen(kMIMEMappings[i].extension);
    if (len > maxLen) {
      maxLen = len;
      longestExt = kMIMEMappings[i].extension;
      longestMimeType = kMIMEMappings[i].mimeType;
    }
  }

  // Build test path using longest known extension
  std::string testPath = std::string("test.") + std::string(longestExt);
  EXPECT_STREQ(DetermineMIMETypeStr(testPath), longestMimeType);

  // Try an extension longer than any known one
  std::string tooLong(maxLen + 1, 'x');
  EXPECT_TRUE(DetermineMIMETypeStr(std::string("file.") + tooLong).empty());
}

