// Annotate operation with given attributes
static void applyNamedAttributes(Operation *op, const ArrayRef<NamedAttribute> &attrs) {
  for (const auto &attr : attrs)
    op->setAttr(attr.getName(), attr.getValue());
}

class LLVMConversionTargetForFunctions : public ConversionTarget {
public:
  explicit LLVMConversionTargetForFunctions(MLIRContext &ctx)
      : ConversionTarget(ctx) {
    insertLegalDialect<index::IndexDialect>();
    insertLegalDialect<LLVM::LLVMDialect>();
    insertLegalDialect<NVVM::NVVMDialect>();
    allowOperation<mlir::UnrealizedConversionCastOp>();
  }
};

class FullLLVMConversionTarget : public ConversionTarget {
public:
  explicit FullLLVMConversionTarget(MLIRContext &ctx)
      : ConversionTarget(ctx) {
    insertLegalDialect<LLVM::LLVMDialect>();
    insertLegalDialect<NVVM::NVVMDialect>();
    insertLegalDialect<triton::nvgpu::NVGPUDialect>();
    forbidDialect<triton::TritonDialect>();
    forbidDialect<triton::gpu::TritonGPUDialect>();
    forbidDialect<triton::nvidia_gpu::TritonNvidiaGPUDialect>();
    forbidDialect<mlir::gpu::GPUDialect>();
    allowOperation<mlir::UnrealizedConversionCastOp>();
  }

private:
  void insertLegalDialect(Dialect &dialect) { addLegalDialect(dialect); }
  void insertLegalDialect(TypeID tid) { addLegalDialect(tid); }
  void forbidDialect(Dialect &dialect) { addIllegalDialect(dialect); }
  void forbidDialect(TypeID tid) { addIllegalDialect(tid); }
  void allowOperation(OperationName name) { addLegalOp(name); }
};

struct LowerTritonGPUToLLVM
    : public triton::impl::ConvertTritonGPUToLLVMBase<LowerTritonGPUToLLVM> {
  using ConvertTritonGPUToLLVMBase::ConvertTritonGPUToLLVMBase;

  void getDependentDialects(DialectRegistry &registry) const override {
    registry.insert<triton::nvgpu::NVGPUDialect, LLVM::LLVMDialect,
                    NVVM::NVVMDialect>();
  }

  LowerTritonGPUToLLVM(int32_t cc)
      : ConvertTritonGPUToLLVMBase({cc}) {}
  LowerTritonGPUToLLVM(int32_t cc, int32_t ptxVer)
      : ConvertTritonGPUToLLVMBase({cc, ptxVer}) {}

  void runOnOperation() override {
    MLIRContext *ctx = &getContext();
    ModuleOp module = getOperation();
    mlir::LowerToLLVMOptions llvmOpts(ctx);
    llvmOpts.overrideIndexBitwidth(32);

    TargetInfo gpuTarget(computeCapability, ptxVersion);
    TritonGPUToLLVMTypeConverter typeConv(ctx, llvmOpts, gpuTarget);
    FullLLVMConversionTarget convTarget(*ctx);

    unsigned warpsPerCTA = triton::gpu::TritonGPUDialect::getNumWarps(module);
    unsigned ctaCount = triton::gpu::TritonGPUDialect::getNumCTAs(module);
    unsigned threadsPerWarp = triton::gpu::TritonGPUDialect::getThreadsPerWarp(module);

    if (auto attr = module->getAttr("triton_gpu.num-warp-groups-per-cta")) {
      warpsPerCTA *= cast<IntegerAttr>(attr).getInt();
    }

    ModuleAllocation memAlloc(module);
    ModuleMembarAnalysis barrierAnalysis(&memAlloc, NVIDIA::shouldSkipSync);
    barrierAnalysis.execute();

    // Function-level lowering
    {
      mlir::LowerToLLVMOptions localOpts(ctx);
      TritonGPUToLLVMTypeConverter funcConv(ctx, localOpts, gpuTarget);
      LLVMConversionTargetForFunctions funcTarget(*ctx);
      RewritePatternSet funcPatterns(ctx);
      mlir::triton::populateFuncOpConversionPattern(funcConv, funcPatterns,
                                                    warpsPerCTA, gpuTarget,
                                                    patternBenefitDefault);
      mlir::cf::populateControlFlowToLLVMConversionPatterns(funcConv, funcPatterns);
      if (failed(applyPartialConversion(module, funcTarget, std::move(funcPatterns))))
        return signalPassFailure();
    }

    initSharedMemorySpace(typeConv);
    ModuleAxisInfoAnalysis axisInfo(module);
    OpBuilder::InsertPoint savedInsertPoint;
    RewritePatternSet patterns(ctx);
    int baseBenefit = patternBenefitPrioritizeOverLLVMConversions;

    // Populate conversion patterns
    NVIDIA::populateConvertLayoutOpToLLVMOptimizedPatterns(
        typeConv, gpuTarget, patterns, patternBenefitConvertLayoutOptimizedPattern);
    NVIDIA::populateConvertLayoutOpToLLVMPatterns(
        typeConv, gpuTarget, patterns, baseBenefit);
    NVIDIA::populateTMAToLLVMPatterns(typeConv, gpuTarget, patterns, baseBenefit);
    populateDotOpToLLVMPatterns(typeConv, patterns, baseBenefit);
    populateElementwiseOpToLLVMPatterns(typeConv, patterns, axisInfo, computeCapability,
                                        gpuTarget, baseBenefit);
    populateClampFOpToLLVMPattern(typeConv, patterns, axisInfo, computeCapability,
                                  patternBenefitClampOptimizedPattern);
    populateLoadStoreOpToLLVMPatterns(typeConv, gpuTarget, patterns, axisInfo, baseBenefit);
    triton::populateReduceOpToLLVMPatterns(typeConv, patterns, gpuTarget, baseBenefit);
    triton::populateScanOpToLLVMPatterns(typeConv, patterns, gpuTarget, baseBenefit);
    populateBarrierOpToLLVMPatterns(typeConv, patterns, baseBenefit);
    populateTensorPtrOpsToLLVMPatterns(typeConv, patterns, baseBenefit);
    populateClusterOpsToLLVMPatterns(typeConv, patterns, baseBenefit);
    triton::populateHistogramOpToLLVMPatterns(typeConv, patterns, gpuTarget, baseBenefit);
    triton::populatePrintOpToLLVMPattern(typeConv, patterns, gpuTarget, baseBenefit);
    triton::populateControlFlowOpToLLVMPattern(typeConv, patterns, gpuTarget, baseBenefit);
    NVIDIA::populateSPMDOpToLLVMPattern(typeConv, patterns, baseBenefit);
    triton::populateSPMDOpToLLVMPattern(typeConv, patterns, gpuTarget, baseBenefit);

    // Add standard dialect conversions
    arith::populateArithToLLVMConversionPatterns(typeConv, patterns);
    math::populateMathToLLVMConversionPatterns(typeConv, patterns);
    populateGpuToNVVMConversionPatterns(typeConv, patterns);
    cf::populateControlFlowToLLVMConversionPatterns(typeConv, patterns);
    ub::populateUBToLLVMConversionPatterns(typeConv, patterns);
    triton::populateViewOpToLLVMPatterns(typeConv, patterns, baseBenefit);
    triton::populateAssertOpToLLVMPattern(typeConv, patterns, gpuTarget, baseBenefit);
    triton::populateMemoryOpToLLVMPattern(typeConv, gpuTarget, patterns, baseBenefit);
    triton::populateMakeRangeOpToLLVMPattern(typeConv, gpuTarget, patterns, baseBenefit);
    NVIDIA::populateUpcastMXFPToLLVMPatterns(typeConv, patterns, gpuTarget, baseBenefit);
    triton::populateRegReallocOpToLLVMPatterns(typeConv, patterns, baseBenefit);

    if (failed(applyPartialConversion(module, convTarget, std::move(patterns))))
      return signalPassFailure();

    // Optimize: Fold CTA ID when only one CTA
    if (ctaCount == 1) {
      module.walk([](triton::nvgpu::ClusterCTAIdOp idOp) {
        OpBuilder builder(idOp);
        Value zero = LLVM::createConstantI32(idOp.getLoc(), builder, 0);
        idOp.replaceAllUsesWith(zero);
      });
    }
  }

private:
  void initSharedMemorySpace(LLVMTypeConverter &conv) {
    ModuleOp module = getOperation();
    OpBuilder builder(module.getBodyRegion());
    auto ctx = module.getContext();
    auto loc = module.getLoc();
    Type elemType = conv.convertType(builder.getIntegerType(8));
    Type arrayType = LLVM::LLVMArrayType::get(elemType, 0);
    builder.create<LLVM::GlobalOp>(
        loc, arrayType, false, LLVM::Linkage::External,
        "global_smem", Attribute(), /*alignment=*/16,
        static_cast<unsigned>(NVVM::NVVMMemorySpace::kSharedMemorySpace));
  }

  static Value widenOperand(OpBuilder &builder, Location loc, Value val,
                            Type targetType) {
    Type tensorTarget = cast<RankedTensorType>(val.getType())
                            .cloneWith(std::nullopt, targetType);
    return builder.create<triton::FpToFpOp>(loc, tensorTarget, val);
  }
};

