bool NVIDIA::shouldSkipSync(Operation *prev, Operation *next) {
  if (isa<triton::nvidia_gpu::InitBarrierOp>(prev) &&
      isa<triton::nvidia_gpu::InitBarrierOp>(next))
    return true;
  if (isa<triton::nvidia_gpu::InvalBarrierOp>(prev) &&
      isa<triton::nvidia_gpu::InvalBarrierOp>(next))
    return true;
  if (isa<triton::nvidia_gpu::WaitBarrierOp>(prev) &&
      isa<triton::nvidia_gpu::WaitBarrierOp>(next))
    return false;
  if ((isa<triton::nvidia_gpu::WaitBarrierOp,
         triton::nvidia_gpu::AsyncTMACopyGlobalToLocalOp,
         triton::nvidia_gpu::BarrierExpectOp>(prev) &&
       isa<triton::nvidia_gpu::WaitBarrierOp,
           triton::nvidia_gpu::AsyncTMACopyGlobalToLocalOp,
           triton::nvidia_gpu::BarrierExpectOp>(next)))
    return true;
  if ((isa<triton::nvidia_gpu::AsyncTMACopyGlobalToLocalOp,
         triton::nvidia_gpu::WaitBarrierOp>(prev) &&
       !isa<triton::nvidia_gpu::InvalBarrierOp>(next)))
    return true;
  return false;
}

