// Lightweight callback using function pointer only — optimized for speed
template<typename Result, typename... Parameters>
struct DirectInvoker {
    using FunctionSignature = Result(*)(Parameters...);
    FunctionSignature handler = nullptr;

    DirectInvoker() = default;
    explicit DirectInvoker(FunctionSignature f) : handler(f) {}

    Result invoke(Parameters... params) const {
        return handler(params...);
    }

    bool is_null() const { return handler == nullptr; }
};

// Generic wrapper that stores any callable type (including lambdas with captures)
template<typename Callable>
class AnyCallable {
    Callable stored_callable;

public:
    template<typename F>
    explicit AnyCallable(F&& c) : stored_callable(std::forward<F>(c)) {}

    template<typename... Args>
    auto operator()(Args&&... arguments) 
        -> decltype(std::declval<Callable>()(std::forward<Args>(arguments)...)) {
        return stored_callable(std::forward<Args>(arguments)...);
    }
};

// Standalone functions for demonstration
int combine_values(int first, int second) {
    return first + second;
}

void display_text(const char* text) {
    std::cout << "Output: " << text << std::endl;
}

// Demonstrate direct function-pointer-based callbacks
void demonstrate_direct_invocation() {
    std::cout << "=== DirectInvoker Demo ===" << std::endl;

    DirectInvoker<int, int, int> invoker1{combine_values};
    std::cout << "invoker1(7, 8) = " << invoker1.invoke(7, 8) << std::endl;

    DirectInvoker<void, const char*> invoker2{display_text};
    invoker2.invoke("Greetings from DirectInvoker!");
}

// Demonstrate generic callable wrapper with compile-time type knowledge
void demonstrate_any_callable() {
    std::cout << "\n=== AnyCallable Demo ===" << std::endl;

    // Lambda without capture
    auto double_value = [](int value) { return value * 2; };
    AnyCallable<decltype(double_value)> wrapper1{double_value};
    std::cout << "wrapper1(21) = " << wrapper1(21) << std::endl;  // 42

    // Lambda with capture by value
    int factor = 5;
    auto scaled_multiply = [factor](int x) { return x * factor; };
    AnyCallable<decltype(scaled_multiply)> wrapper2{scaled_multiply};
    std::cout << "wrapper2(9) = " << wrapper2(9) << std::endl;  // 45
}

// Mixed usage: choose optimal strategy per scenario
void demonstrate_mixed_approach() {
    std::cout << "\n=== Hybrid Strategy Demo ===" << std::endl;

    // Use DirectInvoker when no state needed
    DirectInvoker<int, int, int> fast_path{combine_values};

    // Use AnyCallable when capturing context
    int bias = 200;
    auto biased_add = [bias](int n) { return n + bias; };
    AnyCallable<decltype(biased_add)> contextful{biased_add};

    std::cout << "fast_path(10, 20) = " << fast_path.invoke(10, 20) << std::endl;
    std::cout << "contextful(30) = " << contextful(30) << std::endl;
}

// Memory footprint comparison
void demonstrate_memory_overhead() {
    std::cout << "\n=== Storage Overhead Analysis ===" << std::endl;

    std::cout << "sizeof(DirectInvoker<int(int,int)>) = "
              << sizeof(DirectInvoker<int, int, int>) << " bytes" << std::endl;

    auto simple_lambda = [](double d) { return d / 2.0; };
    std::cout << "sizeof(AnyCallable<decltype(simple_lambda)>) = "
              << sizeof(AnyCallable<decltype(simple_lambda)>) << " bytes" << std::endl;

    std::cout << "sizeof(std::function<double(double)>) = "
              << sizeof(std::function<double(double)>) << " bytes" << std::endl;
}

int main() {
    demonstrate_direct_invocation();
    demonstrate_any_callable();
    demonstrate_mixed_approach();
    demonstrate_memory_overhead();

    std::cout << "\n=== Design Guidance ===" << std::endl;
    std::cout << "- DirectInvoker: ideal for hot paths where no closure state is required" << std::endl;
    std::cout << "- AnyCallable: best when you need to store arbitrary callables at compile time" << std::endl;
    std::cout << "- std::function: suited for runtime polymorphism or heterogeneous storage" << std::endl;
    std::cout << "- Select based on performance requirements and context needs" << std::endl;

    return 0;
}

