#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    cin >> n >> m;

    vector<vector<int>> adj(n + 1);
    vector<int> degree(n + 1, 0);

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
        degree[u]++;
        degree[v]++;
    }

    // Create vertex ordering: sort by descending degree, then ascending vertex index
    vector<int> vertices(n);
    iota(vertices.begin(), vertices.end(), 1);

    sort(vertices.begin(), vertices.end(), [&](int x, int y) {
        if (degree[x] != degree[y]) 
            return degree[x] > degree[y];
        return x < y;
    });

    // Greedy coloring with 3 colors
    vector<int> assignedColor(n + 1, 0);

    for (int vertex : vertices) {
        // Track which colors are used by neighbors
        vector<int> neighborColors(4, 0);  // indices 1-3 used

        for (int neighbor : adj[vertex]) {
            int c = assignedColor[neighbor];
            if (c >= 1 && c <= 3) {
                neighborColors[c]++;
            }
        }

        // Choose the color with minimum conflict count (prefer smaller index on tie)
        int chosenColor = 1;
        int minConflict = neighborColors[1];

        for (int color = 2; color <= 3; color++) {
            if (neighborColors[color] < minConflict) {
                minConflict = neighborColors[color];
                chosenColor = color;
            }
        }

        assignedColor[vertex] = chosenColor;
    }

    // Output the coloring
    for (int i = 1; i <= n; i++) {
        if (i > 1) cout << " ";
        cout << assignedColor[i];
    }
    cout << '\n';

    return 0;
}

