namespace sampleprofutil {

// Determine whether a callsite should be considered hot based on its execution frequency.
//
// This function evaluates if a callsite's total sample count exceeds the threshold
// defined by ProfileSummaryInfo, taking into account special handling for profiles
// marked as accurate for symbols in a provided list.
bool callsiteIsHot(const FunctionSamples *CallsiteFS, ProfileSummaryInfo *PSI,
                   bool ProfAccForSymsInList) {
  if (!CallsiteFS)
    return false; // Callsite was not inlined originally

  assert(PSI && "ProfileSummaryInfo must be available");
  uint64_t CallsiteTotalSamples = CallsiteFS->getTotalSamples();

  if (ProfAccForSymsInList)
    return !PSI->isColdCount(CallsiteTotalSamples);
  else
    return PSI->isHotCount(CallsiteTotalSamples);
}

// Mark a specific sample record (identified by line offset and discriminator)
// as used and update coverage statistics accordingly.
//
// Returns true if this is the first time the record is being marked as used.
bool SampleCoverageTracker::markSamplesUsed(const FunctionSamples *FS,
                                            uint32_t LineOffset,
                                            uint32_t Discriminator,
                                            uint64_t Samples) {
  LineLocation Loc(LineOffset, Discriminator);
  unsigned &Count = SampleCoverage[FS][Loc];
  bool FirstTime = (++Count == 1);
  if (FirstTime)
    TotalUsedSamples += Samples;
  return FirstTime;
}

// Count how many unique sample records were applied from a given profile.
//
// Excludes records from cold inlined callsites.
unsigned
SampleCoverageTracker::countUsedRecords(const FunctionSamples *FS,
                                        ProfileSummaryInfo *PSI) const {
  auto I = SampleCoverage.find(FS);
  unsigned Count = (I != SampleCoverage.end()) ? I->second.size() : 0;

  // Recursively include counts from hot inlined callsites
  for (const auto &CallsiteMap : FS->getCallsiteSamples())
    for (const auto &DiscriminatorEntry : CallsiteMap.second) {
      const FunctionSamples *CalleeSamples = &DiscriminatorEntry.second;
      if (callsiteIsHot(CalleeSamples, PSI, ProfAccForSymsInList))
        Count += countUsedRecords(CalleeSamples, PSI);
    }

  return Count;
}

// Count total number of sample records present in the function body.
//
// Does not include records from cold inlined callsites.
unsigned
SampleCoverageTracker::countBodyRecords(const FunctionSamples *FS,
                                        ProfileSummaryInfo *PSI) const {
  unsigned Count = FS->getBodySamples().size();

  // Add counts from hot inlined callsites only
  for (const auto &CallsiteMap : FS->getCallsiteSamples())
    for (const auto &DiscriminatorEntry : CallsiteMap.second) {
      const FunctionSamples *CalleeSamples = &DiscriminatorEntry.second;
      if (callsiteIsHot(CalleeSamples, PSI, ProfAccForSymsInList))
        Count += countBodyRecords(CalleeSamples, PSI);
    }

  return Count;
}

// Compute total number of sample values collected in the function body.
//
// Excludes samples from cold inlined callsites.
uint64_t
SampleCoverageTracker::countBodySamples(const FunctionSamples *FS,
                                        ProfileSummaryInfo *PSI) const {
  uint64_t Total = 0;

  // Sum up body samples
  for (const auto &BodySample : FS->getBodySamples())
    Total += BodySample.second.getSamples();

  // Include samples from hot inlined callsites only
  for (const auto &CallsiteMap : FS->getCallsiteSamples())
    for (const auto &DiscriminatorEntry : CallsiteMap.second) {
      const FunctionSamples *CalleeSamples = &DiscriminatorEntry.second;
      if (callsiteIsHot(CalleeSamples, PSI, ProfAccForSymsInList))
        Total += countBodySamples(CalleeSamples, PSI);
    }

  return Total;
}

// Calculate coverage percentage given used and total record counts.
//
// Returns an integer between 0 and 100 representing the percentage of
// records that were successfully applied.
unsigned SampleCoverageTracker::computeCoverage(unsigned Used,
                                                unsigned Total) const {
  assert(Used <= Total &&
         "Number of used records cannot exceed total available records");

  return Total > 0 ? (Used * 100) / Total : 100;
}

// Create a module-level global variable indicating FSDiscriminators are in use.
void createFSDiscriminatorVariable(Module *M) {
  const char *VarName = "__llvm_fs_discriminator__";

  if (M->getGlobalVariable(VarName))
    return;

  auto &Ctx = M->getContext();
  auto *GV = new GlobalVariable(*M, Type::getInt1Ty(Ctx), /*isConstant=*/true,
                                GlobalValue::WeakODRLinkage,
                                ConstantInt::getTrue(Ctx), VarName);

  appendToUsed(*M, {GV});
}

