	: TutorialTask( tutorial, descId, preCompletionEnabled, constraints, showMinTime, allowFade, taskReminders ),
	tileId( tileId )
{
	useLocation = false;
}

// Check if the task has been successfully completed
bool UseTileTask::isCompleted()
{
	return bIsCompleted;
}

// Handle item usage event and determine if it satisfies the task condition
void UseTileTask::useItemOn(Level *level, shared_ptr<ItemInstance> item, int posX, int posY, int posZ, bool onlyCheck)
{
	if (onlyCheck) return;

	// Skip processing if pre-completion is disabled and task hasn't been activated yet
	if (!enablePreCompletion && !bHasBeenActivated) return;

	// Determine if current position matches target or if location is irrelevant
	if (!useLocation || (posX == x && posY == y && posZ == z))
	{
		int currentTile = level->getTile(posX, posY, posZ);
		if (currentTile == tileId)
			bIsCompleted = true;
	}
}

