struct vessel {
    int ammo = 20;
    int health = 100;

    bool fire() {
        if (ammo > 0) {
            --ammo;
            return true; // Weapon successfully discharged
        }
        return false; // No ammunition available
    }

    bool take_damage(int amount) {
        health -= amount;
        return health <= 0; // Check if the vessel has been destroyed
    }
};

