#include <bits/stdc++.h>
using namespace std;

int main() {
    int t;
    cin >> t;
    while (t--) {
        // Send first query: 100000 words each of length 1
        cout << "? 100000";
        for (int idx = 0; idx < 100000; ++idx) {
            cout << " 1";
        }
        cout << endl;

        int response1;
        cin >> response1;
        if (response1 == -1) return 0;

        const int totalWords = 100000;
        int minLen, maxLen;

        if (response1 == 1) {
            minLen = maxLen = totalWords;
        } else if (response1 == totalWords) {
            minLen = maxLen = 1;
        } else {
            // Compute lower bound: ceil(totalWords / response1)
            minLen = (totalWords + response1 - 1) / response1;
            // Compute upper bound: floor((totalWords - 1) / (response1 - 1))
            maxLen = (totalWords - 1) / (response1 - 1);
        }

        if (minLen == maxLen) {
            cout << "! " << minLen << endl;
            continue;
        }

        // Second query: one word with length minLen + 1
        cout << "? 1 " << minLen + 1 << endl;
        int response2;
        cin >> response2;
        if (response2 == -1) return 0;

        if (response2 == 0) {
            // The maximum word length is less than minLen+1, so it must be minLen
            cout << "! " << minLen << endl;
        } else {
            // The maximum word length is at least minLen+1; assume it's minLen+1
            cout << "! " << minLen + 1 << endl;
        }
    }
    return 0;
}

#include <iostream>
#include <type_traits>
#include <functional>
#include <string>

// Custom callable struct that multiplies two integers and returns a double
struct ProductCalculator {
    double compute(int first, int second) const {
        return static_cast<double>(first) * second;
    }
};

// Simple addition function
int sum_values(int x, int y) {
    return x + y;
}

void demonstrate_type_deduction() {
    std::cout << "=== Compile-Time Type Deduction ===" << std::endl;

    // Deduce the return type of ProductCalculator::compute
    using ReturnType1 = std::invoke_result_t<decltype(&ProductCalculator::compute), ProductCalculator, int, int>;
    static_assert(std::is_same_v<ReturnType1, double>);
    std::cout << "ProductCalculator::compute yields double" << std::endl;

    // Deduce the return type of sum_values
    using ReturnType2 = std::invoke_result_t<decltype(sum_values), int, int>;
    static_assert(std::is_same_v<ReturnType2, int>);
    std::cout << "sum_values yields int" << std::endl;

    // Deduce the return type of a lambda returning 42
    using ReturnType3 = std::invoke_result_t<decltype([]() { return 42; })>;
    static_assert(std::is_same_v<ReturnType3, int>);
    std::cout << "Lambda expression yields int" << std::endl;
}

// Generic wrapper to invoke functions with type-aware output
template<typename Callable, typename... Parameters>
auto execute_and_report(Callable&& func, Parameters&&... params)
    -> std::invoke_result_t<Callable, Parameters...>
{
    using ValueType = std::invoke_result_t<Callable, Parameters...>;

    if constexpr (std::is_void_v<ValueType>) {
        std::invoke(std::forward<Callable>(func), std::forward<Parameters>(params)...);
        std::cout << "(no return value)" << std::endl;
    } else {
        ValueType value = std::invoke(std::forward<Callable>(func), std::forward<Parameters>(params)...);
        std::cout << "output: " << value << std::endl;
        return value;
    }
}

void demonstrate_generic_dispatch() {
    std::cout << "\n=== Generic Dispatch Demo ===" << std::endl;

    ProductCalculator calc;

    std::cout << "Executing ProductCalculator: ";
    execute_and_report(calc, 5, 6);

    std::cout << "Executing sum_values: ";
    execute_and_report(sum_values, 15, 25);

    std::cout << "Executing void lambda: ";
    execute_and_report([]() { std::cout << "Action performed!"; });
}

// SFINAE-based safe invocation with compile-time checks
template<typename Func, typename... Args>
auto guarded_invoke(Func&& func, Args&&... args)
    -> std::enable_if_t<std::is_invocable_v<Func, Args...>,
                       std::invoke_result_t<Func, Args...>>
{
    return std::invoke(std::forward<Func>(func), std::forward<Args>(args)...);
}

// Overload for handling invocable vs non-invocable cases
template<typename Func, typename... Args>
auto try_invoke_or_notify(Func&& func, Args&&... args)
    -> std::enable_if_t<std::is_invocable_v<Func, Args...>, bool>
{
    using ResultType = std::invoke_result_t<Func, Args...>;
    if constexpr (!std::is_void_v<ResultType>) {
        auto outcome = std::invoke(std::forward<Func>(func), std::forward<Args>(args)...);
        std::cout << "Computed: " << outcome << std::endl;
    }
    return true;
}

template<typename Func, typename... Args>
auto try_invoke_or_notify(Func&&, Args&&...)
    -> std::enable_if_t<!std::is_invocable_v<Func, Args...>, bool>
{
    std::cout << "Failure: provided arguments are incompatible" << std::endl;
    return false;
}

void demonstrate_sfinae_approach() {
    std::cout << "\n=== SFINAE-Based Handling ===" << std::endl;

    auto double_up = [](int n) { return n * 2; };

    std::cout << "Valid invocation: ";
    try_invoke_or_notify(double_up, 17);

    std::cout << "Invalid invocation: ";
    try_invoke_or_notify(double_up, "invalid input");
}

// Compile-time predicate for checking if a callable returns int
template<typename Func, typename... Args>
constexpr bool returns_int_check_v =
    std::is_invocable_r_v<int, Func, Args...>;

void demonstrate_type_validation() {
    std::cout << "\n=== Compile-Time Type Validation ===" << std::endl;

    auto int_producer = [](int val) { return val; };
    auto float_producer = [](int val) { return 1.0f * val; };

    std::cout << "Lambda returning int matches expected signature: "
              << returns_int_check_v<decltype(int_producer), int> << std::endl;

    std::cout << "Lambda returning float matches expected signature: "
              << returns_int_check_v<decltype(float_producer), int> << std::endl;
}

int main() {
    demonstrate_type_deduction();
    demonstrate_generic_dispatch();
    demonstrate_sfinae_approach();
    demonstrate_type_validation();

    return 0;
}

