void CgLiveStacks::releaseMemory() {
  // Free memory used by value numbering info; actual VNInfo instances do not require destruction.
  VNInfoAllocator.reset();
  S2IMap.clear();
  S2RCMap.clear();
}

bool CgLiveStacks::runOnCgFunction(CgFunction &func) {
  TRI = func.getSubtarget().getRegisterInfo();
  // TODO: Currently no analysis is performed; register allocation is expected to supply needed data.
  func.LSS = this;
  return false;
}

CgLiveInterval &
CgLiveStacks::getOrCreateInterval(int slot, const TargetRegisterClass *regClass) {
  assert(slot >= 0 && "Spill slot index must be non-negative");

  SS2IntervalMap::iterator iter = S2IMap.find(slot);
  if (iter == S2IMap.end()) {
    // Create new interval for this slot
    auto emplaceResult = S2IMap.emplace(
        std::piecewise_construct,
        std::forward_as_tuple(slot),
        std::forward_as_tuple(Register::index2StackSlot(slot), 0.0f)
    );
    iter = emplaceResult.first;
    S2RCMap.insert(std::make_pair(slot, regClass));
  } else {
    // Refine the register class using intersection (common subclass)
    const TargetRegisterClass *prevRC = S2RCMap[slot];
    S2RCMap[slot] = TRI->getCommonSubClass(prevRC, regClass);
  }

  return iter->second;
}

/// dump - Output interval information to the given stream.
void CgLiveStacks::print(raw_ostream &out) const {
  out << "********** INTERVALS **********\n";
  for (const_iterator it = begin(), endIt = end(); it != endIt; ++it) {
    it->second.print(out);
    int slotIdx = it->first;
    const TargetRegisterClass *rc = getIntervalRegClass(slotIdx);
    if (rc)
      out << " [" << TRI->getRegClassName(rc) << "]\n";
    else
      out << " [Unknown]\n";
  }
}

#include <cstddef>
