// Assume idx_t, real_t, ikv_t, rkv_t, uvw_t are defined elsewhere
// For completeness, minimal stubs (not part of original):
typedef long idx_t;
typedef double real_t;

struct ikv_t {
    idx_t key;
    idx_t val;
};

struct rkv_t {
    real_t key;
    idx_t val;
};

struct uvw_t {
    real_t u, v, w;
};

// Helper swap function
template<typename T>
inline void my_swap(T& a, T& b) {
    T tmp = std::move(a);
    a = std::move(b);
    b = tmp;
}

// Generic partition function for quicksort
template<typename T, typename Compare>
idx_t my_partition(T* arr, idx_t low, idx_t high, Compare comp) {
    T pivot = arr[high];
    idx_t i = low - 1;
    for (idx_t j = low; j < high; ++j) {
        if (comp(arr[j], pivot)) {
            ++i;
            my_swap(arr[i], arr[j]);
        }
    }
    my_swap(arr[i + 1], arr[high]);
    return i + 1;
}

// Generic recursive quicksort
template<typename T, typename Compare>
void my_quicksort_impl(T* arr, idx_t low, idx_t high, Compare comp) {
    if (low < high) {
        idx_t pi = my_partition(arr, low, high, comp);
        my_quicksort_impl(arr, low, pi - 1, comp);
        my_quicksort_impl(arr, pi + 1, high, comp);
    }
}

// Wrapper for array-based quicksort
template<typename T, typename Compare>
void my_qsort_array(T* base, size_t n, Compare comp) {
    if (n > 1) {
        my_quicksort_impl(base, static_cast<idx_t>(0), static_cast<idx_t>(n - 1), comp);
    }
}

// Sorting routines — rewritten without GK_MKQSORT macros
void isorti(size_t n, idx_t *base)
{
    auto less = [](const idx_t* a, const idx_t* b) { return *a < *b; };
    my_qsort_array(base, n, less);
}

void isortd(size_t n, idx_t *base)
{
    auto greater = [](const idx_t* a, const idx_t* b) { return *a > *b; };
    my_qsort_array(base, n, greater);
}

void rsorti(size_t n, real_t *base)
{
    auto less = [](const real_t* a, const real_t* b) { return *a < *b; };
    my_qsort_array(base, n, less);
}

void rsortd(size_t n, real_t *base)
{
    auto greater = [](const real_t* a, const real_t* b) { return *a > *b; };
    my_qsort_array(base, n, greater);
}

void ikvsorti(size_t n, ikv_t *base)
{
    auto less = [](const ikv_t& a, const ikv_t& b) { return a.key < b.key; };
    my_qsort_array(base, n, less);
}

void ikvsortii(size_t n, ikv_t *base)
{
    auto less = [](const ikv_t& a, const ikv_t& b) {
        return (a.key < b.key) || (a.key == b.key && a.val < b.val);
    };
    my_qsort_array(base, n, less);
}

void ikvsortd(size_t n, ikv_t *base)
{
    auto greater = [](const ikv_t& a, const ikv_t& b) { return a.key > b.key; };
    my_qsort_array(base, n, greater);
}

void rkvsorti(size_t n, rkv_t *base)
{
    auto less = [](const rkv_t& a, const rkv_t& b) { return a.key < b.key; };
    my_qsort_array(base, n, less);
}

void rkvsortd(size_t n, rkv_t *base)
{
    auto greater = [](const rkv_t& a, const rkv_t& b) { return a.key > b.key; };
    my_qsort_array(base, n, greater);
}

void uvwsorti(size_t n, uvw_t *base)
{
    auto less = [](const uvw_t& a, const uvw_t& b) {
        return (a.u < b.u) || (a.u == b.u && a.v < b.v);
    };
    my_qsort_array(base, n, less);
}

