//--------------------------------------------------------------------------
// Custom plugin context for tracing instructions with a different approach
struct instruction_tracer_t : public plugmod_t, public event_listener_t
{
  int traced_instructions = 0;
  const int max_instructions = 20;

  ~instruction_tracer_t()
  {
    // Event listeners are automatically cleaned up on module unload
  }

  virtual bool idaapi run(size_t) override;
  virtual ssize_t idaapi on_event(ssize_t code, va_list va) override;
};

//--------------------------------------------------------------------------
// Event handler implementation with modified control flow and variable naming
ssize_t idaapi instruction_tracer_t::on_event(ssize_t code, va_list va)
{
  switch (code)
  {
    case dbg_process_start:
      // Reset the trace counter when process starts
      traced_instructions = 0;
      break;

    case dbg_run_to:
      msg("tracer: execution reached entry point\n");
      enable_insn_trace(true);
      request_continue_process();
      run_requests();
      break;

    case dbg_trace:
      {
        /*thid_t thread_id =*/ va_arg(va, thid_t);
        ea_t current_address = va_arg(va, ea_t);
        msg("[%d] tracing instruction at: %a\n", traced_instructions, current_address);

        if (traced_instructions >= max_instructions)
        {
          disable_step_trace();
          suspend_process();
          msg("process suspended after tracing %d instructions\n", max_instructions);
        }
        else
        {
          traced_instructions++;
        }
      }
      break;

    case dbg_process_exit:
      unhook_event_listener(HT_DBG, this);
      break;
  }
  return 0;
}

//--------------------------------------------------------------------------
// Modified run method with alternative initialization sequence
bool idaapi instruction_tracer_t::run(size_t)
{
  if (!hook_event_listener(HT_DBG, this))
  {
    warning("Failed to attach debugger event listener");
    return true;
  }

  if (dbg == nullptr)
    load_debugger("win32", false);

  // Start debugging from the program's entry point
  if (!run_to(inf_get_start_ea()))
  {
    unhook_event_listener(HT_DBG, this);
  }

  return true;
}

//--------------------------------------------------------------------------
// Plugin initialization function with alternate condition checking
static plugmod_t *idaapi init()
{
  // Only support x86 PE executables
  if (PH.id != PLFM_386 || inf_get_filetype() != f_PE)
    return nullptr;

  return new instruction_tracer_t;
}

