//-----------------------------------------------------------------
/// @details
///		Starts up the endpoint and performs validation checks to ensure
///		all required configuration is present
///	@param[in]	modeToOpen
///		The requested open mode for the endpoint
///	@returns
///		Status code indicating success or failure
//-----------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseEndpoint<LvlT>::beginEndpoint(OPEN_MODE modeToOpen_) noexcept {
    // Validate based on operational mode
    switch (config.serviceMode) {
        default:
        case SERVICE_MODE::SOURCE:
            // In source mode, scanning and rendering are used; storePath not needed
            break;
        case SERVICE_MODE::TARGET:
            // Target mode requires a valid store path regardless of format
            if (!config.storePath)
                return APERR(Ec::InvalidParam, "Missing storePath");
            break;
    }

    // Extract optional settings from config parameters
    if (auto err = config.parameters.lookupAssign("skipRemovableDrives", m_excludeExternalDrives))
        return err;
    if (auto err = config.parameters.lookupAssign("ignoreSymbolicLinks", m_excludeSymlinks))
        return err;

    // Delegate to base class initialization
    return Parent::beginEndpoint(modeToOpen_);
}

//-----------------------------------------------------------------
/// @details
///		Constructs a static, immutable configuration key string
//-----------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseEndpoint<LvlT>::getConfigSubKey(Text &outKey) noexcept {
    // Derive key from store path — deterministic and unchanging
    outKey = static_cast<TextView>(config.storePath);
    return {};
}

template <log::Lvl LvlT>
Error IBaseInstance<LvlT>::getPermissions(Entry &targetEntry) noexcept {
    // Initialize permission processing
    if (auto res = permissions.beginPerm(targetEntry, m_endpoint.permissionInfo, m_endpoint))
        return res;
    return {};
}

template <log::Lvl LvlT>
ErrorOr<std::list<Text>> IBaseInstance<LvlT>::outputPermissions() noexcept {
    // Generate formatted permission list using current context
    return permissions.outputPermissions(m_endpoint.permissionInfo, m_endpoint);
}

