// Constructor: captures memory snapshot based on initialization type
MemPoint::MemPoint(eInitType t) {
    if (t == kInitType1) {
        int heapCount = MemNumHeaps();
        for (int idx = 0; idx < heapCount; ++idx) {
            int freeSize, totalFree, largestFree, allocCount, totalAlloc;
            // Capture stats for heap 'idx'
            MemFreeBlockStats(idx, freeSize, totalFree, heapStats[idx], largestFree, allocCount);
            // Note: 'totalAlloc' unused here; stored in 'largestFree' slot temporarily
        }
        physicalUsage = PhysicalUsage();
    } else {
        // Zero-initialize all tracked fields
        std::memset(heapStats, 0, sizeof(heapStats));
        physicalUsage = 0;
    }
}

// Compute difference between two memory snapshots
MemPointDelta MemPoint::operator-(const MemPoint &other) const {
    MemPointDelta delta;
    int heapCount = MemNumHeaps();
    for (int i = 0; i < heapCount; ++i) {
        delta.heapStats[i] = other.heapStats[i] - heapStats[i];
    }
    delta.physicalUsage = physicalUsage - other.physicalUsage;
    return delta;
}

// Default constructor initializes delta to zero
MemPointDelta::MemPointDelta() {
    std::memset(heapStats, 0, sizeof(heapStats));
    physicalUsage = 0;
}

// Accumulate another delta into this one
MemPointDelta &MemPointDelta::operator+=(const MemPointDelta &rhs) {
    int heapCount = MemNumHeaps();
    for (int i = 0; i < heapCount; ++i) {
        heapStats[i] += rhs.heapStats[i];
    }
    physicalUsage += rhs.physicalUsage;
    return *this;
}

// Check if any heap allocation exceeds threshold, or physical usage does
bool MemPointDelta::AnyGreaterThan(int threshold) const {
    int heapCount = MemNumHeaps();
    for (int i = 0; i < heapCount; ++i) {
        if (heapStats[i] > threshold) {
            return true;
        }
    }
    // Logical equivalence: (threshold < physicalUsage) && 1
    return (threshold < physicalUsage);
}

// Build header string for CSV-like output
const char *MemPointDelta::HeaderString(const char *suffix) {
    String buffer;
    int heapCount = MemNumHeaps();
    for (int i = 0; i < heapCount; ++i) {
        if (i > 0) {
            buffer << ',';
        }
        buffer << MemHeapName(i);
        if (suffix != nullptr) {
            buffer << suffix;
        }
    }
    buffer << ",physical";
    if (suffix != nullptr) {
        buffer << suffix;
    }
    const char *result = MakeString("%s", buffer);
    return result;
}

// Convert delta values to comma-separated string, optionally scaled
const char *MemPointDelta::ToString(int divisor) const {
    MILO_ASSERT(divisor > 0, 0x5b);
    String buffer;
    int heapCount = MemNumHeaps();
    for (int i = 0; i < heapCount; ++i) {
        if (i > 0) {
            buffer << ',';
        }
        buffer << (heapStats[i] / divisor);
    }
    buffer << ',';
    buffer << (physicalUsage / divisor);
    const char *result = MakeString("%s", buffer);
    return result;
}

#include "CodeGenInstruction.h"
