using namespace llvm;

namespace {
class X86MnemonicTablesEmitter {
  CodeGenTarget m_target;
public:
  explicit X86MnemonicTablesEmitter(RecordKeeper &records) : m_target(records) {}

  void emit(raw_ostream &outStream);
};

void X86MnemonicTablesEmitter::emit(raw_ostream &outStream) {
  emitSourceFileHeader("X86 Mnemonic tables", outStream);
  outStream << "namespace llvm {\nnamespace X86 {\n\n";

  Record *asmWriterDef = m_target.getAsmWriter();
  unsigned variantId = asmWriterDef->getValueAsInt("Variant");

  // Map mnemonics to their corresponding instruction definitions
  StringMap<SmallVector<const CodeGenInstruction *, /*Capacity=*/0>> mnemonicMap;

  ArrayRef<const CodeGenInstruction *> allInstructions = 
      m_target.getInstructionsByEnumValue();

  for (const CodeGenInstruction *inst : allInstructions) {
    const Record *def = inst->TheDef;

    // Only consider X86 instructions
    if (!def->isSubClassOf("X86Inst"))
      continue;

    X86Disassembler::RecognizableInstrBase ri(*inst);
    if (!ri.shouldBeEmitted())
      continue;

    // Skip non-parsable or prefix-only instructions
    if (def->getValueAsString("AsmVariantName") == "NonParsable" ||
        ri.Form == X86Local::PrefixByte)
      continue;

    std::string mnemonic = X86Disassembler::getMnemonic(inst, variantId);
    mnemonicMap[mnemonic].push_back(inst);
  }

  // Emit header declarations
  outStream << "#ifdef GET_X86_MNEMONIC_TABLES_H\n";
  outStream << "#undef GET_X86_MNEMONIC_TABLES_H\n\n";

  for (const auto &entry : mnemonicMap)
    outStream << "bool is" << entry.getKey() << "(unsigned Opcode);\n";

  outStream << "#endif // GET_X86_MNEMONIC_TABLES_H\n\n";

  // Emit implementation
  outStream << "#ifdef GET_X86_MNEMONIC_TABLES_CPP\n";
  outStream << "#undef GET_X86_MNEMONIC_TABLES_CPP\n\n";

  for (const auto &entry : mnemonicMap) {
    StringRef mnemonic = entry.getKey();
    const auto &instructions = entry.getValue();

    outStream << "bool is" << mnemonic << "(unsigned Opcode) {\n";
    if (instructions.size() == 1u) {
      const CodeGenInstruction *cgInst = instructions.front();
      outStream << "\treturn Opcode == " << cgInst->TheDef->getName() << ";\n}\n\n";
    } else {
      outStream << "\tswitch (Opcode) {\n";
      for (const CodeGenInstruction *cgInst : instructions) {
        outStream << "\tcase " << cgInst->TheDef->getName() << ":\n";
      }
      outStream << "\t\treturn true;\n\t}\n\treturn false;\n}\n\n";
    }
  }

  outStream << "#endif // GET_X86_MNEMONIC_TABLES_CPP\n\n";
  outStream << "} // end namespace X86\n} // end namespace llvm";
}
} // anonymous namespace

static TableGen::Emitter::OptClass<X86MnemonicTablesEmitter>
    X("gen-x86-mnemonic-tables", "Generate X86 mnemonic tables");

