	BaseServerParameters = UnitEnv->GetDefaultServerParameters();
}

void UFTextCrash::ExecuteClientUnitTest()
{
	// Wait until we receive the NUTActor from the server
	if (UnitNUTActor.IsValid())
	{
		// Construct an empty FText and transmit it to the server — this should provoke an assertion on the server side
		FText EmptyText = FText::GetEmpty();
		UnitNUTActor->ServerReceiveText(EmptyText);

		// If the exploit attempt did not succeed, the subsequent log entry will be 'ExploitFailLog',
		// as this message is emitted in the same execution path as the RPC call above
		// (and would only appear if the prior RPC was successfully processed).
		SendGenericExploitFailLog();
	}
}

void UFTextCrash::NotifyProcessLog(TWeakPtr<FUnitTestProcess> InProcess, const TArray<FString>& InLogLines)
{
	Super::NotifyProcessLog(InProcess, InLogLines);
	if (InProcess.HasSameObject(ServerHandle.Pin().Get()))
	{
		const FString CrashIndicator = TEXT("Unhandled Exception: EXCEPTION_ACCESS_VIOLATION reading address");
		for (const FString& LogLine : InLogLines)
		{
			if (LogLine.Contains(CrashIndicator))
			{
				VerificationState = EUnitTestVerification::VerifiedNotFixed;
				break;
			}
			else if (LogLine.Contains(GetGenericExploitFailLog()))
			{
				VerificationState = EUnitTestVerification::VerifiedFixed;
				break;
			}
		}
	}
}

#include "ttsafe.h"

#ifdef H5_HAVE_THREADSAFE

#define OUTPUT_FILE_NAME      "ttsafe_dcreate.h5"
#define CONCURRENT_TASK_COUNT 16

// Thread execution context structure
struct worker_context {
    int task_index;
    hid_t file_handle;
    const char* dataset_label;
};

// Explicitly named datasets to avoid auto-generation
const char* DATASET_LABELS[CONCURRENT_TASK_COUNT] = {
    "zero",     "one",      "two",       "three",    "four",
    "five",     "six",      "seven",     "eight",    "nine",
    "ten",      "eleven",   "twelve",    "thirteen", "fourteen",
    "fifteen"
};

worker_context worker_info[CONCURRENT_TASK_COUNT];

/*
 * Helper: Launches a worker thread and stores its handle
 */
static void launch_worker(H5TS_thread_t* thread_handle,
                          int idx,
                          hid_t file_id,
                          const char* label) {
    worker_info[idx].task_index = idx;
    worker_info[idx].file_handle = file_id;
    worker_info[idx].dataset_label = label;
    *thread_handle = H5TS_create_thread(tts_dcreate_creator, NULL, &worker_info[idx]);
}

/*
 * Main test routine: creates multiple datasets concurrently in a thread-safe manner
 */
void tts_dcreate(void) {
    H5TS_thread_t worker_handles[CONCURRENT_TASK_COUNT];
    hid_t file_id = -1;
    int value_read;
    int loop_idx;

    // Initialize thread attributes for global scheduling
    H5TS_attr_t attr;
    H5TS_attr_init(&attr);

#ifdef H5_HAVE_SYSTEM_SCOPE_THREADS
    H5TS_attr_setscope(&attr, H5TS_SCOPE_SYSTEM);
#endif

    // Open or create the HDF5 file
    file_id = H5Fcreate(OUTPUT_FILE_NAME, H5F_ACC_TRUNC, H5P_DEFAULT, H5P_DEFAULT);
    assert(file_id >= 0);

    // Spawn all threads to create datasets concurrently
    loop_idx = 0;
    while (loop_idx < CONCURRENT_TASK_COUNT) {
        launch_worker(&worker_handles[loop_idx], loop_idx, file_id, DATASET_LABELS[loop_idx]);
        ++loop_idx;
    }

    // Wait for all threads to complete
    loop_idx = 0;
    while (loop_idx < CONCURRENT_TASK_COUNT) {
        H5TS_wait_for_thread(worker_handles[loop_idx]);
        ++loop_idx;
    }

    // Verify correctness by reading back each dataset
    loop_idx = 0;
    while (loop_idx < CONCURRENT_TASK_COUNT) {
        hid_t dset_id = H5Dopen2(file_id, DATASET_LABELS[loop_idx], H5P_DEFAULT);
        if (dset_id < 0) {
            TestErrPrintf("Dataset '%s' not found — test failed\n", DATASET_LABELS[loop_idx]);
            H5Fclose(file_id);
            return;
        }

        herr_t status = H5Dread(dset_id, H5T_NATIVE_INT, H5S_ALL, H5S_ALL, H5P_DEFAULT, &value_read);
        assert(status >= 0);

        if (value_read != loop_idx) {
            TestErrPrintf("Incorrect value %d for dataset '%s' — test failed\n",
                          value_read, DATASET_LABELS[loop_idx]);
            H5Dclose(dset_id);
            H5Fclose(file_id);
            return;
        }

        status = H5Dclose(dset_id);
        assert(status >= 0);
        ++loop_idx;
    }

    // Cleanup resources
    status = H5Fclose(file_id);
    assert(status >= 0);
    H5TS_attr_destroy(&attr);
}

/*
 * Worker function executed by each thread:
 * Creates one dataset, writes its index as data, then closes resources.
 */
void* tts_dcreate_creator(void* arg) {
    hid_t space_id = -1, dset_id = -1;
    hsize_t dims[] = {1};
    struct worker_context ctx;

    memcpy(&ctx, arg, sizeof(struct worker_context));

    // Create dataspace
    space_id = H5Screate_simple(1, dims, NULL);
    assert(space_id >= 0);

    // Create dataset
    dset_id = H5Dcreate2(ctx.file_handle, ctx.dataset_label,
                         H5T_NATIVE_INT, space_id, H5P_DEFAULT, H5P_DEFAULT, H5P_DEFAULT);
    assert(dset_id >= 0);

    // Write dataset value (the task index)
    herr_t ret = H5Dwrite(dset_id, H5T_NATIVE_INT, H5S_ALL, H5S_ALL,
                          H5P_DEFAULT, &ctx.task_index);
    assert(ret >= 0);

    // Release resources
    ret = H5Dclose(dset_id);
    assert(ret >= 0);
    ret = H5Sclose(space_id);
    assert(ret >= 0);

    return NULL;
}

/*
 * Cleanup: remove the generated file after test completion
 */
void cleanup_dcreate(void) {
    HDunlink(OUTPUT_FILE_NAME);
}

#endif /* H5_HAVE_THREADSAFE */

