char LPPassManager::ID = 0;

LPPassManager::LPPassManager() : FunctionPass(ID) {
  LI = nullptr;
  ActiveLoop = nullptr;
}

// Add loop to the processing queue maintaining proper nesting order
void LPPassManager::enqueueLoop(Loop &L) {
  if (L.isOutermost()) {
    // Top-level loop goes at front of queue
    ProcessingQueue.push_front(&L);
    return;
  }

  // Insert after parent loop in queue
  for (auto It = ProcessingQueue.begin(); It != ProcessingQueue.end(); ++It) {
    if (*It == L.getParentLoop()) {
      ++It;
      ProcessingQueue.insert(It, 1, &L);
      return;
    }
  }
}

// Recursively add loops to queue in depth-first order
static void buildProcessingQueue(Loop *LP, std::deque<Loop *> &PQ) {
  PQ.push_back(LP);
  for (Loop *Child : reverse(*LP))
    buildProcessingQueue(Child, PQ);
}

/// Analysis preservation policy
void LPPassManager::getAnalysisUsage(AnalysisUsage &Info) const {
  Info.addRequired<LoopInfoWrapperPass>();
  Info.addRequired<DominatorTreeWrapperPass>();
  Info.setPreservesAll();
}

// Handle deletion of loop during pass execution
void LPPassManager::markLoopAsDeleted(Loop &L) {
  assert((&L == ActiveLoop || ActiveLoop->contains(&L)) &&
         "Cannot delete loop outside current loop tree!");
  assert(ProcessingQueue.back() == ActiveLoop && 
         "Loop queue invariant violated!");

  llvm::erase(ProcessingQueue, &L);
  if (&L == ActiveLoop) {
    LoopDeletedFlag = true;
    ProcessingQueue.push_back(&L); // Maintain queue integrity
  }
}

// Execute all scheduled passes on loops in function
bool LPPassManager::runOnFunction(Function &Func) {
  auto &LIWP = getAnalysis<LoopInfoWrapperPass>();
  LI = &LIWP.getLoopInfo();
  Module &Mod = *Func.getParent();

  bool Modified = false;

  // Inherit analysis from higher-level managers
  populateInheritedAnalysis(TPM->activeStack);

  // Build processing queue in forward program order
  for (Loop *L : reverse(*LI))
    buildProcessingQueue(L, ProcessingQueue);

  if (ProcessingQueue.empty())
    return false; // No loops to process

  // Initialize all passes for each loop
  for (Loop *L : ProcessingQueue) {
    for (unsigned Idx = 0; Idx < getNumContainedPasses(); ++Idx) {
      LoopPass *Pass = getContainedPass(Idx);
      Modified |= Pass->doInitialization(L, *this);
    }
  }

  // Process loops one by one
  unsigned InitialInstrCount, CurrentFuncSize = 0;
  StringMap<std::pair<unsigned, unsigned>> FuncToInstrMap;
  bool EmitInstrRemark = Mod.shouldEmitInstrCountChangedRemark();

  if (EmitInstrRemark) {
    InitialInstrCount = initSizeRemarkInfo(Mod, FuncToInstrMap);
    CurrentFuncSize = Func.getInstructionCount();
  }

  while (!ProcessingQueue.empty()) {
    LoopDeletedFlag = false;
    ActiveLoop = ProcessingQueue.back();

    // Run all passes on current loop
    for (unsigned Idx = 0; Idx < getNumContainedPasses(); ++Idx) {
      LoopPass *Pass = getContainedPass(Idx);
      llvm::TimeTraceScope LoopScope("RunLoopPass", Pass->getPassName());

      dumpPassInfo(Pass, EXECUTION_MSG, ON_LOOP_MSG,
                   ActiveLoop->getHeader()->getName());
      dumpRequiredSet(Pass);
      initializeAnalysisImpl(Pass);

      bool LocalModified = false;
      {
        PassManagerPrettyStackEntry StackEntry(Pass, *ActiveLoop->getHeader());
        TimeRegion Timer(getPassTimer(Pass));

#ifdef EXPENSIVE_CHECKS
        uint64_t OriginalHash = Pass->structuralHash(Func);
#endif

        LocalModified = Pass->runOnLoop(ActiveLoop, *this);

#ifdef EXPENSIVE_CHECKS
        if (!LocalModified && (OriginalHash != Pass->structuralHash(Func))) {
          llvm::errs() << "Pass modifies its input without reporting: "
                       << Pass->getPassName() << "\n";
          llvm_unreachable("Pass modifies its input without reporting");
        }
#endif

        Modified |= LocalModified;

        if (EmitInstrRemark) {
          unsigned NewSize = Func.getInstructionCount();
          if (NewSize != CurrentFuncSize) {
            int64_t Change = static_cast<int64_t>(NewSize) -
                            static_cast<int64_t>(CurrentFuncSize);
            emitInstrCountChangedRemark(Pass, Mod, Change, InitialInstrCount,
                                       FuncToInstrMap, &Func);
            InitialInstrCount += Change;
            CurrentFuncSize = NewSize;
          }
        }
      }

      if (LocalModified)
        dumpPassInfo(Pass, MODIFICATION_MSG, ON_LOOP_MSG,
                     LoopDeletedFlag ? "<deleted loop>"
                                     : ActiveLoop->getName());

      dumpPreservedSet(Pass);

      if (!LoopDeletedFlag) {
        // Verify loop integrity
        {
          TimeRegion Timer(getPassTimer(&LIWP));
          ActiveLoop->verifyLoop();
        }

        verifyPreservedAnalysis(Pass);
        Func.getContext().yield();
      }

      if (LocalModified) {
        removeNotPreservedAnalysis(Pass);
      }

      recordAvailableAnalysis(Pass);
      removeDeadPasses(Pass,
                      LoopDeletedFlag ? "<deleted>"
                                      : ActiveLoop->getHeader()->getName(),
                      ON_LOOP_MSG);

      if (LoopDeletedFlag)
        break; // Skip remaining passes for deleted loop
    }

    // Cleanup deleted loop's passes
    if (LoopDeletedFlag) {
      for (unsigned Idx = 0; Idx < getNumContainedPasses(); ++Idx) {
        Pass *P = getContainedPass(Idx);
        freePass(P, "<deleted>", ON_LOOP_MSG);
      }
    }

    ProcessingQueue.pop_back();
  }

  // Finalize all passes
  for (unsigned Idx = 0; Idx < getNumContainedPasses(); ++Idx) {
    LoopPass *Pass = getContainedPass(Idx);
    Modified |= Pass->doFinalization();
  }

  return Modified;
}

// Print pass manager hierarchy
void LPPassManager::dumpPassStructure(unsigned Depth) {
  errs().indent(Depth*2) << "Loop Pass Manager\n";
  for (unsigned Idx = 0; Idx < getNumContainedPasses(); ++Idx) {
    Pass *P = getContainedPass(Idx);
    P->dumpPassStructure(Depth + 1);
    dumpLastUses(P, Depth+1);
  }
}

