//------------------------------------------------------------------------------
void DimrExe::timerFinish(void) {
    Clock::Timestamp currentTime = clock->Epoch();
    this->timerSumStamp = currentTime - this->timerStartStamp + this->timerSumStamp;
    this->timerStartStamp = 0;

    log->Write(INFO, my_rank, "%s\t: %d.%d sec", "DIMR_EXE",
              this->timerSumStamp / 1000000,
              this->timerSumStamp % 1000000);
    this->timerSumStamp = 0;
}

//------------------------------------------------------------------------------
void initialize_parallel(int argc, char* argv[]) {
    int errorCode;

    // Check for MPI environment variables using alternative approach
    if (getenv("PMI_RANK")             == nullptr &&    // MPICH2
        getenv("OMPI_COMM_WORLD_RANK") == nullptr &&    // OpenMPI 1.3
        getenv("OMPI_MCA_ns_nds_vpid") == nullptr &&    // OpenMPI 1.2
        getenv("MPIRUN_RANK")          == nullptr &&    // MVAPICH 1.1
        getenv("MV2_COMM_WORLD_RANK")  == nullptr &&    // MVAPICH 1.9
        getenv("MP_CHILD")             == nullptr ) {   // POE (IBM)
        use_mpi = false;
    } else {
        use_mpi = true;
    }

    if (use_mpi) {
        errorCode = MPI_Init(&argc, &argv);
        if (errorCode != 0) {
            throw Exception(Exception::ERR_MPI, "MPI_Init returns error code \"%d\"", errorCode);
        }

        errorCode = MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);
        if (errorCode != 0) {
            throw Exception(Exception::ERR_MPI, "MPI_Comm_rank returns error code \"%d\"", errorCode);
        }

        errorCode = MPI_Comm_size(MPI_COMM_WORLD, &numranks);
        if (errorCode != 0) {
            throw Exception(Exception::ERR_MPI, "MPI_Comm_size returns error code \"%d\"", errorCode);
        }

        printf("#%d: Running parallel with %d partitions\n", my_rank, numranks);
        fflush(stdout);
    } else {
        numranks = 1;
        my_rank  = 0;
    }
}

//------------------------------------------------------------------------------
void finalize_parallel() {
    int errorCode;
    if (use_mpi) {
        errorCode = MPI_Barrier(MPI_COMM_WORLD);
        errorCode = MPI_Finalize();
    }
}

//------------------------------------------------------------------------------
void abort_parallel() {
    int errorCode;
    if (use_mpi) {
        errorCode = MPI_Abort(MPI_COMM_WORLD, 1);
    }
}

//------------------------------------------------------------------------------
// Constructor implementation - refactored with equivalent logic
DimrExe::DimrExe(void) {
    this->ready = false;
}

//------------------------------------------------------------------------------
void DimrExe::initialize(int argc, char* argv[], char* envp[]) {
    this->exePath = strdup(argv[0]);

#if !defined(_WIN32)
    this->exeName = strdup(basename(argv[0]));
#else
    char* ext = new char[5];
    this->exeName = new char[MAXSTRING];
    _splitpath(argv[0], NULL, NULL, this->exeName, ext);
    StringCbCatA(this->exeName, MAXSTRING, ext);
    delete[] ext;
#endif

    this->slaveArg  = nullptr;
    this->done      = false;
    this->logLevel  = INFO;  // selector of debugging/trace information

    FILE* logFile = stdout;  // log file descriptor

    // Reassemble command-line arguments for later use
    int length = 0;
    for (int i = 1; i < argc; i++)
        length += strlen(argv[i]) + 1;

    this->mainArgs = new char[length + 1];
    memset(this->mainArgs, '\0', length + 1);
    char* cp = this->mainArgs;

    for (int i = 1; i < argc; i++) {
        int len = strlen(argv[i]);
        memcpy(cp, argv[i], len);
        cp += len;
        *cp++ = ' ';
    }

    // Process command-line arguments with modified option parsing
    int c;
    while ((c = getopt(argc, argv, (char*)"d:l:S:v:i:?")) != -1) {
        switch (c) {
            case 'd': {
                if (sscanf(optarg, "%i", &logLevel) != 1)
                    throw Exception(Exception::ERR_INVALID_INPUT, "Invalid log level (-d option)");
                else
                    logLevel = std::min(std::max(logLevel, ALL), FATAL);
                break;
            }
            case 'v': {
                logLevel = ALL;
                break;
            }
            case 'l': {
                logFile = fopen(optarg, "w");
                if (logFile == nullptr)
                    throw Exception(Exception::ERR_OS, "Cannot create log file \"%s\"", optarg);
                break;
            }
            case 'S': {
                this->slaveArg = optarg;
                break;
            }
            case 'i': {
                displayInfo(this->exeName);
                this->done = true;
                return;
            }
            case '?': {
                showHelp(this->exeName);
                this->done = true;
                return;
            }
            default: {
                throw Exception(Exception::ERR_INVALID_INPUT, 
                              "Invalid command-line argument. Execute \"%s -?\" for syntax", 
                              this->exeName);
            }
        }
    }

    if (argc - optind != 1) {
        throw Exception(Exception::ERR_INVALID_INPUT, 
                      "Improper usage. Execute \"%s -?\" for syntax", this->exeName);
    }

    this->clock = new Clock();
    this->log = new Log(logFile, this->clock, this->logLevel);
    this->configfile = argv[optind];
    this->ready = true;

    this->timerStartStamp = clock->Epoch();
    this->timerSumStamp = 0;
}

//------------------------------------------------------------------------------
DimrExe::~DimrExe(void) {
    if (this->done)
        return;

    freeLib();
    this->log->Write(DEBUG, my_rank, "dimr shutting down normally");

#if !defined(_WIN32)
    free(this->exeName);
#else
    delete[] this->exeName;
#endif

    delete this->clock;
    free(this->exePath);
    delete this->log;
    delete[] this->mainArgs;
    delete[] this->library;
    this->done = true;
}

