// EmbossEffect: Applies an emboss filter using gradient-based lighting simulation
class EmbossEffect final : public TStandardRasterFx {
  FX_PLUGIN_DECLARATION(EmbossEffect)

  TRasterFxPort m_sourceInput;
  TDoubleParamP m_lightIntensity;
  TDoubleParamP m_lightElevationAngle;
  TDoubleParamP m_lightAzimuthAngle;
  TDoubleParamP m_filterRadius;

public:
  EmbossEffect()
      : m_lightIntensity(0.5),
        m_lightElevationAngle(45.0),
        m_lightAzimuthAngle(90.0),
        m_filterRadius(1.0) {
    m_filterRadius->setMeasureName("fxLength");
    bindParam(this, "intensity", m_lightIntensity);
    bindParam(this, "elevation", m_lightElevationAngle);
    bindParam(this, "direction", m_lightAzimuthAngle);
    bindParam(this, "radius", m_filterRadius);

    addInputPort("Source", m_sourceInput);

    // Set parameter ranges
    m_lightIntensity->setValueRange(0.0, 1.0, 0.1);
    m_lightElevationAngle->setValueRange(0.0, 360.0);
    m_lightAzimuthAngle->setValueRange(0.0, 360.0);
    m_filterRadius->setValueRange(0.0, 10.0);
  }

  ~EmbossEffect() = default;

  bool doGetBBox(double frame, TRectD &boundingBox,
                 const TRenderSettings &renderInfo) override {
    if (!m_sourceInput.isConnected()) {
      boundingBox = TRectD();
      return false;
    }
    return m_sourceInput->doGetBBox(frame, boundingBox, renderInfo);
  }

  void transform(double frame, int port, const TRectD &outputRect,
                 const TRenderSettings &outputInfo, TRectD &inputRect,
                 TRenderSettings &inputInfo) override;

  void doCompute(TTile &tile, double frame, const TRenderSettings &ri) override;

  int getMemoryRequirement(const TRectD &rect, double frame,
                           const TRenderSettings &info) override;

  bool canHandle(const TRenderSettings &info, double frame) override {
    return isAlmostIsotropic(info.m_affine);
  }
};

// Helper: Compute weighted differences in vertical/horizontal directions
template <typename GRAY>
inline void accumulateGradients(const GRAY *centerPixel, int wrap,
                                double radiusFrac, double &nsSum, double &ewSum,
                                int maxOffset) {
  nsSum = ewSum = 0.0;
  for (int offset = 1; offset <= maxOffset; ++offset) {
    double weight = (offset == maxOffset) ? radiusFrac : 1.0;
    // Vertical gradient: north-south difference
    nsSum += weight * (GRAY::from(*(centerPixel + offset * wrap)).value -
                       GRAY::from(*(centerPixel - offset * wrap)).value);
    // Horizontal gradient: east-west difference
    ewSum += weight * (GRAY::from(*(centerPixel + offset)).value -
                       GRAY::from(*(centerPixel - offset)).value);
  }
}

// Core emboss computation for both 8-bit and 16-bit pixel types
template <typename PIXEL, typename PIXELGRAY, typename CHANNEL_TYPE>
void applyEmbossEffect(TRasterPT<PIXEL> dst, TRasterPT<PIXEL> src,
                       double azimuthRad, double elevationRad,
                       double intensity, double radius) {
  // Light direction vector components (scaled to channel max)
  const double scale = PIXEL::maxChannelValue;
  const double lx = cos(azimuthRad) * cos(elevationRad) * scale;
  const double ly = sin(azimuthRad) * cos(elevationRad) * scale;
  const double lz = sin(elevationRad) * scale;
  const double nzBase = (6.0 * scale) * (1.0 - intensity);
  const double nz2 = nzBase * nzBase;

  const int border = static_cast<int>(radius);
  const double fractionalPart = radius - border;
  const int wrap = src->getWrap();

  src->lock();
  dst->lock();

  for (int y = border; y < src->getLy() - border; ++y) {
    PIXEL *outRow = dst->pixels(y - border);
    PIXEL *inRow  = src->pixels(y) + border;
    PIXEL *endOut = outRow + dst->getLx();

    while (outRow < endOut) {
      double gradNS = 0.0, gradEW = 0.0;

      // Accumulate gradients over integer and fractional offsets
      if (border > 0) {
        accumulateGradients(inRow, wrap, 1.0, gradNS, gradEW, border - 1);
      }
      if (fractionalPart > 0.0 && border > 0) {
        double nsFrac = 0.0, ewFrac = 0.0;
        accumulateGradients(inRow, wrap, fractionalPart, nsFrac, ewFrac, border);
        gradNS += nsFrac;
        gradEW += ewFrac;
      }

      // Normalize by radius
      const double nx = gradEW / radius;
      const double ny = gradNS / radius;

      double resultVal;
      if (nx == 0.0 && ny == 0.0) {
        resultVal = lz;  // Flat surface → only ambient light
      } else {
        const double dotProduct = nx * lx + ny * ly + nzBase * lz;
        if (dotProduct <= 0.0) {
          resultVal = 0.0;
        } else {
          const double magnitude = sqrt(nx * nx + ny * ny + nz2);
          resultVal = dotProduct / magnitude;
        }
      }

      // Clamp and assign output
      const auto clamped = static_cast<CHANNEL_TYPE>(
          std::max(0.0, std::min(resultVal, static_cast<double>(PIXEL::maxChannelValue))));
      outRow->r = outRow->g = outRow->b = clamped;
      outRow->m = inRow->m;
      *outRow = premultiply(*outRow);

      ++inRow;
      ++outRow;
    }
  }

  src->unlock();
  dst->unlock();
}

// Main compute method
void EmbossEffect::doCompute(TTile &tile, double frame,
                             const TRenderSettings &ri) {
  if (!m_sourceInput.isConnected()) return;

  double minR, maxR, step;
  m_filterRadius->getValueRange(minR, maxR, step);

  const double scale = sqrt(fabs(ri.m_affine.det()));
  const double radius =
      tcrop(m_filterRadius->getValue(frame) * scale, minR, maxR);
  const double azimuthDeg   = m_lightAzimuthAngle->getValue(frame);
  const double elevationDeg = m_lightElevationAngle->getValue(frame);
  const double intensity    = m_lightIntensity->getValue(frame);

  const double azimuthRad   = azimuthDeg * M_PI_180;
  const double elevationRad = elevationDeg * M_PI_180;

  const int border = static_cast<int>(ceil(radius)) + 1;

  // Expand source tile to accommodate border
  TRasterP extendedSrc =
      tile.getRaster()->create(tile.getRaster()->getLx() + 2 * border,
                               tile.getRaster()->getLy() + 2 * border);
  TTile srcTile(extendedSrc, tile.m_pos - TPointD(border, border));
  m_sourceInput->compute(srcTile, frame, ri);

  // Dispatch based on pixel depth
  if (TRaster32P r32 = tile.getRaster()) {
    applyEmbossEffect<TPixel32, TPixelGR8, UCHAR>(
        r32, TRaster32P(srcTile.getRaster()), azimuthRad, elevationRad,
        intensity, radius);
  } else if (TRaster64P r64 = tile.getRaster()) {
    applyEmbossEffect<TPixel64, TPixelGR16, USHORT>(
        r64, TRaster64P(srcTile.getRaster()), azimuthRad, elevationRad,
        intensity, radius);
  } else {
    throw TException("EmbossEffect: unsupported pixel format");
  }
}

// Adjust input rectangle for rendering bounds
void EmbossEffect::transform(double frame, int port,
                             const TRectD &outputRect,
                             const TRenderSettings &outputInfo,
                             TRectD &inputRect,
                             TRenderSettings &inputInfo) {
  inputInfo = outputInfo;
  double minR, maxR, step;
  m_filterRadius->getValueRange(minR, maxR, step);
  const double scale = sqrt(fabs(outputInfo.m_affine.det()));
  const double radius =
      tcrop(m_filterRadius->getValue(frame) * scale, minR, maxR);
  inputRect = outputRect.enlarge(static_cast<int>(ceil(radius)) + 1);
}

// Estimate memory usage including expanded region
int EmbossEffect::getMemoryRequirement(const TRectD &rect, double frame,
                                       const TRenderSettings &info) {
  double minR, maxR, step;
  m_filterRadius->getValueRange(minR, maxR, step);
  const double scale = sqrt(fabs(info.m_affine.det()));
  const double radius = m_filterRadius->getValue(frame) * scale;
  const int border = static_cast<int>(ceil(radius)) + 1;
  return TRasterFx::memorySize(rect.enlarge(border), info.m_bpp);
}

