#include "group_sum_matrix.h"
#include <cassert>

template <typename T>
IGL_INLINE void igl::group_sum_matrix(
  const Eigen::Matrix<int,Eigen::Dynamic,1> & G,
  const int k,
  Eigen::SparseMatrix<T>& A)
{
  // Determine number of vertices from input group vector
  const int vertex_count = G.size();

  // Verify that the number of groups k exceeds the maximum group index
  assert(k > G.maxCoeff());

  // Resize the sparse matrix to have k rows (groups) and n columns (vertices)
  A.resize(k, vertex_count);

  // Populate the sparse matrix: for each vertex j, set A(G(j), j) = 1
  for (int j = 0; j < vertex_count; ++j) {
    A.insert(G(j), j) = static_cast<T>(1);
  }

  // Compress the matrix to optimize storage and operations
  A.makeCompressed();
}

// Overload that automatically determines k as max_group_index + 1
template <typename T>
IGL_INLINE void igl::group_sum_matrix(
  const Eigen::Matrix<int,Eigen::Dynamic,1> & G,
  Eigen::SparseMatrix<T>& A)
{
  const int num_groups = G.maxCoeff() + 1;
  return group_sum_matrix(G, num_groups, A);
}

