#include <bits/stdc++.h>
using namespace std;

int n;
vector<int> parent_node;
vector<vector<int>> child_list;
vector<int> representative;

// Query function: asks which of a, b, c is the median in the tree
int query(int a, int b, int c) {
    cout << "0 " << a << " " << b << " " << c << endl;
    int result;
    cin >> result;
    return result;
}

// Find which subtree of node u contains x, or -1 if x is not in any subtree of u
int locate_subtree(int u, int x) {
    vector<int>& children = child_list[u];
    if (children.empty()) return -1;

    // Try each child one by one using pairwise comparison
    for (int i = 0; i < children.size(); ++i) {
        int candidate = children[i];
        // Check if x is in the subtree rooted at candidate
        int res = query(u, representative[candidate], x);
        if (res == representative[candidate]) {
            return candidate;
        }
    }

    // If no child contains x, check if x might be directly under u
    // This handles edge cases where our representation might differ
    return -1;
}

// Insert node x into the tree starting from root
void add_node(int x, int root) {
    int current = root;
    while (true) {
        int subtree = locate_subtree(current, x);
        if (subtree == -1) {
            // Attach x as a new child of current
            parent_node[x] = current;
            child_list[current].push_back(x);
            representative[x] = x;
            break;
        } else {
            current = subtree;
        }
    }
}

int main() {
    cin >> n;
    parent_node.assign(n + 1, -1);
    child_list.resize(n + 1);
    representative.resize(n + 1);

    // Process nodes in order from 1 to n
    vector<int> node_order;
    for (int i = 1; i <= n; ++i) node_order.push_back(i);

    int root_node = node_order[0];
    representative[root_node] = root_node;

    // Insert remaining nodes sequentially
    for (int i = 1; i < n; ++i) {
        add_node(node_order[i], root_node);
    }

    // Output the discovered tree structure
    cout << "1";
    for (int i = 1; i <= n; ++i) {
        if (parent_node[i] != -1) {
            cout << " " << parent_node[i] << " " << i;
        }
    }
    cout << endl;

    return 0;
}

