    int n;
    cin >> n;

    vector<int> a(n + 1), position(n + 1);
    for (int idx = 1; idx <= n; ++idx) {
        cin >> a[idx];
        position[a[idx]] = idx;
    }

    // Determine operation length constraint: 
    // For small n (<=2), only adjacent swaps allowed (x=1)
    // Otherwise, allow both length-2 and length-4 reversals (x=3)
    int mode = (n <= 2) ? 1 : 3;

    vector<pair<int, int>> operations;
    operations.reserve(200000);

    // Helper function to reverse segment [l, r] and update positions
    auto apply_reverse = [&](int left, int right) {
        while (left < right) {
            int valLeft = a[left], valRight = a[right];
            swap(a[left], a[right]);
            position[valLeft] = right;
            position[valRight] = left;
            ++left;
            --right;
        }
    };

    if (mode == 1) {
        // Handle only adjacent swaps (for n <= 2)
        for (int target = 1; target <= n; ++target) {
            while (position[target] > target) {
                int curPos = position[target];
                operations.emplace_back(curPos - 1, curPos);
                apply_reverse(curPos - 1, curPos);
            }
        }
    } else {
        // Allow both length-2 and length-4 reversals
        for (int target = 1; target <= n; ++target) {
            // First try to bring element to position using length-4 moves when possible
            while (position[target] >= target + 3) {
                int curPos = position[target];
                operations.emplace_back(curPos - 3, curPos);
                apply_reverse(curPos - 3, curPos);
            }
            // Then use adjacent swaps for remaining distance
            while (position[target] > target) {
                int curPos = position[target];
                operations.emplace_back(curPos - 1, curPos);
                apply_reverse(curPos - 1, curPos);
            }
        }
    }

    cout << mode << "\n";
    cout << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

