    free(ptr);
  }
}

void propagate_call(void *ptr, int val) {
  release_if_positive(ptr, val + 1);
}

void setup(data_block* blk) {
  // Allocate local integer
  int* local_val = static_cast<int*>(malloc(sizeof(int)));

  // Non-deterministic initialization
  int tmp = nd_int();
  if (tmp != 0) {
    *local_val = 5;
  } else {
    *local_val = 7;
  }

  // Assign to struct fields
  blk->field_a = *local_val;
  blk->field_b = nd_int();
  blk->field_c = *local_val;

  // Deallocate local storage
  free(local_val);
}

