#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

// Helper function to perform a query and return the distance between u and v
ll getDistance(int u, int v) {
    cout << "? " << u << " " << v << endl;
    cout.flush();
    ll dist;
    cin >> dist;
    return dist;
}

void solve() {
    int n;
    cin >> n;

    // Special case: only one node
    if (n == 1) {
        cout << "!" << endl;
        return;
    }

    // Distance arrays from vertex 1 and from farthest vertex B
    vector<ll> distFrom1(n + 1, 0);
    vector<ll> distFromB(n + 1, 0);

    // Query distances from vertex 1 to all others
    for (int i = 2; i <= n; ++i) {
        distFrom1[i] = getDistance(1, i);
    }
    distFrom1[1] = 0;

    // Find the farthest vertex from 1 — call it B
    int farthestVertex = 2;
    for (int i = 3; i <= n; ++i) {
        if (distFrom1[i] > distFrom1[farthestVertex]) {
            farthestVertex = i;
        }
    }

    // Query distances from B to all vertices
    for (int i = 1; i <= n; ++i) {
        if (i != farthestVertex) {
            distFromB[i] = getDistance(farthestVertex, i);
        }
    }
    distFromB[farthestVertex] = 0;

    // Length of the diameter (distance between 1 and B)
    ll diameterLength = distFrom1[farthestVertex];

    // Compute x[i] (distance along the main path from 1) and off[i] (offset/branch depth)
    vector<ll> pathDist(n + 1), branchDepth(n + 1);
    vector<int> pathVertices;

    for (int i = 1; i <= n; ++i) {
        pathDist[i] = (distFrom1[i] + diameterLength - distFromB[i]) / 2;
        branchDepth[i] = (distFrom1[i] - diameterLength + distFromB[i]) / 2;
        if (branchDepth[i] == 0) {
            pathVertices.push_back(i);
        }
    }

    // Sort path vertices by their distance from 1 (ascending)
    sort(pathVertices.begin(), pathVertices.end(),
         [&](int a, int b) { return distFrom1[a] < distFrom1[b]; });

    // Map each path distance to its corresponding vertex on the main path
    map<ll, int> distToPathNode;
    for (int v : pathVertices) {
        distToPathNode[distFrom1[v]] = v;
    }

    // Group nodes by their attachment point on the main path
    vector<vector<int>> attachments(n + 1);
    for (int i = 1; i <= n; ++i) {
        if (branchDepth[i] == 0) {
            attachments[i].push_back(i);  // itself is on the path
        } else {
            int attachPoint = distToPathNode[pathDist[i]];
            attachments[attachPoint].push_back(i);
        }
    }

    // Store edges as (u, v, weight)
    vector<tuple<int, int, ll>> resultEdges;

    // Add edges along the main path
    for (size_t idx = 0; idx + 1 < pathVertices.size(); ++idx) {
        int u = pathVertices[idx];
        int v = pathVertices[idx + 1];
        ll weight = distFrom1[v] - distFrom1[u];
        resultEdges.emplace_back(u, v, weight);
    }

    // Process each group attached to a path node
    for (int root : pathVertices) {
        auto& group = attachments[root];
        if (group.size() <= 1) continue;

        // Sort group by branch depth (non-decreasing)
        sort(group.begin(), group.end(),
             [&](int a, int b) { return branchDepth[a] < branchDepth[b]; });

        // Maintain list of already-processed nodes in this group (sorted by branch depth)
        vector<int> processedNodes = {root};

        for (int node : group) {
            if (node == root) continue;

            // Binary search to find parent among processed nodes
            int left = 0, right = processedNodes.size() - 1;
            while (left < right) {
                int mid = (left + right + 1) / 2;
                int candidate = processedNodes[mid];
                ll dist = getDistance(node, candidate);
                if (dist == branchDepth[node] - branchDepth[candidate]) {
                    left = mid;
                } else {
                    right = mid - 1;
                }
            }

            int parent = processedNodes[left];
            ll edgeWeight = branchDepth[node] - branchDepth[parent];
            resultEdges.emplace_back(parent, node, edgeWeight);

            // Insert current node into processedNodes at correct position
            processedNodes.push_back(node);
            int pos = processedNodes.size() - 1;
            while (pos > 0 && branchDepth[processedNodes[pos]] < branchDepth[processedNodes[pos - 1]]) {
                swap(processedNodes[pos], processedNodes[pos - 1]);
                --pos;
            }
        }
    }

    // Output final answer
    cout << "!";
    for (auto [u, v, w] : resultEdges) {
        cout << " " << u << " " << v << " " << w;
    }
    cout << endl;
    cout.flush();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    cin >> testCases;
    while (testCases--) {
        solve();
    }

    return 0;
}

