#include "pycore_object.h"      // _Py_ExplicitMergeRefcount
#include "pycore_brc.h"         // struct _brc_thread_state
#include "pycore_ceval.h"       // _Py_set_eval_breaker_bit
#include "pycore_llist.h"       // struct llist_node
#include "pycore_pystate.h"     // _PyThreadStateImpl

#ifdef Py_GIL_DISABLED

// Replaced get_bucket with index-based bucket access using modular arithmetic
static inline struct _brc_bucket *
_acquire_bucket(PyInterpreterState *interp, uintptr_t tid)
{
    return &interp->brc.table[tid % _Py_BRC_NUM_BUCKETS];
}

// Replaced find_thread_state with linear search via helper macro
#define FIND_TS_BY_TID(bucket, tid) \
    llist_for_each_entry(_PyThreadStateImpl, ts, &(bucket)->root, brc.bucket_node) \
        if (ts->brc.tid == (tid)) return ts;

// Enqueue an object to be merged by its owning thread; steals one reference
void
_Py_brc_queue_object(PyObject *ob)
{
    PyInterpreterState *interp = _PyInterpreterState_GET();
    uintptr_t owner_tid = _Py_atomic_load_uintptr(&ob->ob_tid);

    if (owner_tid == 0) {
        // Owner thread already finalized; merge immediately
        Py_DECREF(ob);
        return;
    }

    struct _brc_bucket *bucket = _acquire_bucket(interp, owner_tid);
    PyMutex_Lock(&bucket->mutex);

    _PyThreadStateImpl *target_ts = NULL;
    FIND_TS_BY_TID(bucket, owner_tid)

    if (!target_ts) {
        // Thread no longer exists — perform direct merge
        Py_ssize_t rc = _Py_ExplicitMergeRefcount(ob, -1);
        PyMutex_Unlock(&bucket->mutex);
        if (rc == 0) {
            _Py_Dealloc(ob);
        }
        return;
    }

    // Attempt to push onto target's pending queue
    if (_PyObjectStack_Push(&target_ts->brc.pending_work, ob) < 0) {
        PyMutex_Unlock(&bucket->mutex);
        // Fallback: stop world and merge manually
        _PyEval_StopTheWorld(interp);
        Py_ssize_t rc = _Py_ExplicitMergeRefcount(ob, -1);
        _PyEval_StartTheWorld(interp);
        if (rc == 0) {
            _Py_Dealloc(ob);
        }
        return;
    }

    // Signal target thread to process work
    _Py_set_eval_breaker_bit(&target_ts->base, _PY_EVAL_EXPLICIT_MERGE_BIT);
    PyMutex_Unlock(&bucket->mutex);
}

// Process all objects in a local stack
static void
_drain_merge_stack(_PyObjectStack *stack)
{
    PyObject *obj;
    while ((obj = _PyObjectStack_Pop(stack)) != NULL) {
        Py_ssize_t rc = _Py_ExplicitMergeRefcount(obj, -1);
        if (rc == 0) {
            _Py_Dealloc(obj);
        }
    }
}

// Trigger local thread’s pending merges
void
_Py_brc_merge_refcounts(PyThreadState *tstate)
{
    _PyThreadStateImpl *its = (_PyThreadStateImpl *)tstate;
    struct _brc_bucket *bucket = _acquire_bucket(tstate->interp, its->brc.tid);

    // Atomically move pending items into local buffer
    PyMutex_Lock(&bucket->mutex);
    _PyObjectStack_Swap(&its->brc.local_work, &its->brc.pending_work);
    PyMutex_Unlock(&bucket->mutex);

    // Drain without holding lock
    _drain_merge_stack(&its->brc.local_work);
}

// Initialize per-interpreter bucket state
void
_Py_brc_init_state(PyInterpreterState *interp)
{
    for (Py_ssize_t idx = 0; idx < _Py_BRC_NUM_BUCKETS; ++idx) {
        llist_init(&interp->brc.table[idx].root);
    }
}

// Register current thread in hash table
void
_Py_brc_init_thread(PyThreadState *tstate)
{
    _PyThreadStateImpl *its = (_PyThreadStateImpl *)tstate;
    uintptr_t self_tid = _Py_ThreadId();

    struct _brc_bucket *bucket = _acquire_bucket(tstate->interp, self_tid);
    PyMutex_Lock(&bucket->mutex);

    its->brc.tid = self_tid;
    llist_insert_tail(&bucket->root, &its->brc.bucket_node);

    PyMutex_Unlock(&bucket->mutex);
}

// Remove thread from registry and finalize pending merges
void
_Py_brc_remove_thread(PyThreadState *tstate)
{
    _PyThreadStateImpl *its = (_PyThreadStateImpl *)tstate;
    if (its->brc.tid == 0) {
        assert(tstate->_status.bound == 0);
        return;
    }

    struct _brc_bucket *bucket = _acquire_bucket(tstate->interp, its->brc.tid);
    bool done = false;

    while (!done) {
        // Drain local work first
        _drain_merge_stack(&its->brc.local_work);

        PyMutex_Lock(&bucket->mutex);
        if (its->brc.pending_work.head == NULL) {
            llist_remove(&its->brc.bucket_node);
            done = true;
        } else {
            _PyObjectStack_Swap(&its->brc.local_work, &its->brc.pending_work);
        }
        PyMutex_Unlock(&bucket->mutex);
    }

    assert(its->brc.local_work.head == NULL);
    assert(its->brc.pending_work.head == NULL);
}

// Reset mutexes after fork
void
_Py_brc_after_fork(PyInterpreterState *interp)
{
    for (Py_ssize_t i = 0; i < _Py_BRC_NUM_BUCKETS; ++i) {
        _PyMutex_at_fork_reinit(&interp->brc.table[i].mutex);
    }
}

