typedef void (*gemm_fn)(const int, const int, const int,
                        const float, const float*, const int,
                        const float*, const int,
                        const float, float*, const int);
typedef void (*syrk_fn)(const int, const int,
                        const float, const float*, const int,
                        const float, float*, const int);
typedef void (*trmm_fn)(const int, const int, const int, const int,
                        const float, const float*, const int,
                        float*, const int);
typedef void (*trsm_fn)(const int, const int, const int, const int,
                        const float, const float*, const int,
                        float*, const int);

// Dispatch table structure (avoids massive #define chains)
struct blas3_dispatch {
    gemm_fn gemm_nn, gemm_nt, gemm_tn, gemm_tt;
    syrk_fn syrk_ln, syrk_lt, syrk_un, syrk_ut;
    trmm_fn trmm_llnn, trmm_llnu, trmm_lltn, trmm_lltu,
            trmm_lunn, trmm_lunu, trmm_lutn, trmm_lutu,
            trmm_rlnn, trmm_rlnu, trmm_rltn, trmm_rltu,
            trmm_runn, trmm_runu, trmm_rutn, trmm_rutu;
    trsm_fn trsm_llnn, trsm_llnu, trsm_lltn, trsm_lltu,
            trsm_lunn, trsm_lunu, trsm_lutn, trsm_lutu,
            trsm_rlnn, trsm_rlnu, trsm_rltn, trsm_rltu,
            trsm_runn, trsm_runu, trsm_rutn, trsm_rutu;
};

// Select reference implementation at compile time
static inline blas3_dispatch get_ref_dispatch() {
    return {
        /* GEMM */
        blasfeo_ref_sgemm_nn, blasfeo_ref_sgemm_nt,
        blasfeo_ref_sgemm_tn, blasfeo_ref_sgemm_tt,
        /* SYRK */
        blasfeo_ref_ssyrk_ln, blasfeo_ref_ssyrk_lt,
        blasfeo_ref_ssyrk_un, blasfeo_ref_ssyrk_ut,
        /* TRMM */
        blasfeo_ref_strmm_llnn, blasfeo_ref_strmm_llnu, blasfeo_ref_strmm_lltn, blasfeo_ref_strmm_lltu,
        blasfeo_ref_strmm_lunn, blasfeo_ref_strmm_lunu, blasfeo_ref_strmm_lutn, blasfeo_ref_strmm_lutu,
        blasfeo_ref_strmm_rlnn, blasfeo_ref_strmm_rlnu, blasfeo_ref_strmm_rltn, blasfeo_ref_strmm_rltu,
        blasfeo_ref_strmm_runn, blasfeo_ref_strmm_runu, blasfeo_ref_strmm_rutn, blasfeo_ref_strmm_rutu,
        /* TRSM */
        blasfeo_ref_strsm_llnn, blasfeo_ref_strsm_llnu, blasfeo_ref_strsm_lltn, blasfeo_ref_strsm_lltu,
        blasfeo_ref_strsm_lunn, blasfeo_ref_strsm_lunu, blasfeo_ref_strsm_lutn, blasfeo_ref_strsm_lutu,
        blasfeo_ref_strsm_rlnn, blasfeo_ref_strsm_rlnu, blasfeo_ref_strsm_rltn, blasfeo_ref_strsm_rltu,
        blasfeo_ref_strsm_runn, blasfeo_ref_strsm_runu, blasfeo_ref_strsm_rutn, blasfeo_ref_strsm_rutu
