#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
using namespace std;

int query(const vector<int>& q) {
    cout << "?";
    for (int x : q) cout << " " << x;
    cout << endl;
    int ans;
    cin >> ans;
    if (ans == -1) exit(0);
    return ans;
}

void solve() {
    int n;
    cin >> n;
    cout << 1 << endl;

    vector<int> perm(n + 1, 0);
    vector<bool> resolved(n + 1, false);
    vector<int> unresolved;

    // Initialize unresolved nodes
    for (int i = 1; i <= n; ++i) {
        unresolved.push_back(i);
    }

    mt19937 rng(1337);

    // Phase 1: Process each node to find its image
    for (int u = 1; u <= n; ++u) {
        if (resolved[u]) continue;

        vector<int> candidates;
        for (int i = 1; i <= n; ++i) {
            if (i != u && !resolved[i]) {
                candidates.push_back(i);
            }
        }

        bool found_partner = false;

        // Try to identify partner using binary search approach
        while (!found_partner && candidates.size() > 0) {
            if (candidates.size() == 1) {
                // Only one candidate left, must be the partner
                int v = candidates[0];
                perm[u] = v;
                perm[v] = u;
                resolved[u] = true;
                resolved[v] = true;
                found_partner = true;
                break;
            }

            // Split candidates into two groups
            shuffle(candidates.begin(), candidates.end(), rng);
            int mid = candidates.size() / 2;
            vector<int> left(candidates.begin(), candidates.begin() + mid);
            vector<int> right(candidates.begin() + mid, candidates.end());

            // Build query sets
            vector<int> others;
            vector<bool> in_left(n + 1, false);
            for (int x : left) in_left[x] = true;

            for (int i = 1; i <= n; ++i) {
                if (i != u && !in_left[i]) {
                    others.push_back(i);
                }
            }

            // Query 1: [others, u, left]
            vector<int> q1 = others;
            q1.push_back(u);
            q1.insert(q1.end(), left.begin(), left.end());

            // Query 2: [others, left, u]
            vector<int> q2 = others;
            q2.insert(q2.end(), left.begin(), left.end());
            q2.push_back(u);

            int ans1 = query(q1);
            int ans2 = query(q2);
            int diff = ans1 - ans2;

            if (diff == 1) {
                // u maps to left
                candidates = left;
            } else if (diff == -1) {
                // u maps to right
                candidates = right;
            } else {
                // Ambiguous result - try again with new shuffle
                continue;
            }
        }

        if (!found_partner && candidates.size() == 0) {
            // This shouldn't happen in correct implementation
            // But handle it by finding partner among unresolved nodes
            for (int v = 1; v <= n; ++v) {
                if (v != u && !resolved[v]) {
                    perm[u] = v;
                    perm[v] = u;
                    resolved[u] = true;
                    resolved[v] = true;
                    break;
                }
            }
        }
    }

    // Output final permutation
    cout << "!";
    for (int i = 1; i <= n; ++i) {
        cout << " " << perm[i];
    }
    cout << endl;
}

int main() {
    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}

