BoatModel::BoatModel() : Model() {
    // Initialize five model parts for the boat structure
    cubes[0] = new ModelPart(this, 0, 8);
    for (int i = 1; i <= 4; ++i) {
        cubes[i] = new ModelPart(this, 0, 0);
    }

    // Define dimensions and offsets
    int width  = 24;
    int depth  = 6;
    int height = 20;
    int yOffset = 4;

    // Main hull: bottom part of the boat
    cubes[0]->addBox(static_cast<float>(-width / 2), 
                     static_cast<float>(-height / 2 + 2), 
                     -3.0f, 
                     width, 
                     height - 4, 
                     4, 
                     0);
    cubes[0]->setPos(0.0f, static_cast<float>(yOffset), 0.0f);

    // Side paddles/structures (left, right, front, back)
    float halfWidth = static_cast<float>(width / 2);
    float halfHeight = static_cast<float>(height / 2);

    // Left paddle
    cubes[1]->addBox(static_cast<float>(-width / 2 + 2), 
                     static_cast<float>(-depth - 1), 
                     -1.0f, 
                     width - 4, 
                     depth, 
                     2, 
                     0);
    cubes[1]->setPos(halfWidth - 1.0f, static_cast<float>(yOffset), 0.0f);

    // Right paddle
    cubes[2]->addBox(static_cast<float>(-width / 2 + 2), 
                     static_cast<float>(-depth - 1), 
                     -1.0f, 
                     width - 4, 
                     depth, 
                     2, 
                     0);
    cubes[2]->setPos(-halfWidth + 1.0f, static_cast<float>(yOffset), 0.0f);

    // Front paddle
    cubes[3]->addBox(static_cast<float>(-width / 2 + 2), 
                     static_cast<float>(-depth - 1), 
                     -1.0f, 
                     width - 4, 
                     depth, 
                     2, 
                     0);
    cubes[3]->setPos(0.0f, static_cast<float>(yOffset), halfHeight - 1.0f);

    // Back paddle
    cubes[4]->addBox(static_cast<float>(-width / 2 + 2), 
                     static_cast<float>(-depth - 1), 
                     -1.0f, 
                     width - 4, 
                     depth, 
                     2, 
                     0);
    cubes[4]->setPos(0.0f, static_cast<float>(yOffset), -halfHeight + 1.0f);

    // Apply rotations to orient parts correctly
    cubes[0]->xRot = PI / 2;
    cubes[1]->yRot = PI * 3 / 2;
    cubes[2]->yRot = PI / 2;
    cubes[3]->yRot = PI;
    cubes[4]->yRot = 0;

    // Precompile all parts to avoid runtime performance spikes
    float scaleFactor = 1.0f / 16.0f;
    for (int idx = 0; idx < 5; ++idx) {
        cubes[idx]->compile(scaleFactor);
    }
}

void BoatModel::render(
    std::shared_ptr<Entity> entity,
    float                   time,
    float                   r,
    float                   bob,
    float                   yRot,
    float                   xRot,
    float                   scale,
    bool                    usecompiled
) {
    // Render each cube part using a range-based loop alternative
    for (int index = 0; index < 5; ++index) {
        cubes[index]->render(scale, usecompiled);
    }
}

