// Custom memory manager for handler allocation
// Reuses a fixed-size buffer when possible; falls back to heap otherwise
class storage_pool
{
public:
  storage_pool()
    : occupied_(false)
  {
  }

  // Non-copyable
  storage_pool(const storage_pool&) = delete;
  storage_pool& operator=(const storage_pool&) = delete;

  void* request_memory(std::size_t requested_size)
  {
    if (!occupied_ && requested_size <= sizeof(buffer_space_))
    {
      occupied_ = true;
      return &buffer_space_;
    }
    else
    {
      return ::operator new(requested_size);
    }
  }

  void release_memory(void* ptr)
  {
    if (ptr == &buffer_space_)
    {
      occupied_ = false;
    }
    else
    {
      ::operator delete(ptr);
    }
  }

private:
  // Pre-allocated storage area
  typename std::aligned_storage<2048>::type buffer_space_;
  bool occupied_;
};

// Allocator type that works with the custom storage pool
template <typename T>
class pool_allocator
{
public:
  using value_type = T;

  explicit pool_allocator(storage_pool& pool)
    : pool_ref_(pool)
  {
  }

  template <typename U>
  pool_allocator(const pool_allocator<U>& other) noexcept
    : pool_ref_(other.pool_ref_)
  {
  }

  bool operator==(const pool_allocator& other) const noexcept
  {
    return &pool_ref_ == &other.pool_ref_;
  }

  bool operator!=(const pool_allocator& other) const noexcept
  {
    return &pool_ref_ != &other.pool_ref_;
  }

  T* allocate(std::size_t count) const
  {
    return static_cast<T*>(pool_ref_.request_memory(sizeof(T) * count));
  }

  void deallocate(T* pointer, std::size_t /*count*/) const
  {
    pool_ref_.release_memory(pointer);
  }

private:
  template <typename> friend class pool_allocator;
  storage_pool& pool_ref_;
};

// Handler wrapper to inject custom allocator into async operations
template <typename Handler>
class bound_handler
{
public:
  using allocator_type = pool_allocator<Handler>;

  bound_handler(storage_pool& pool, Handler h)
    : pool_(pool),
      handler_(std::move(h))
  {
  }

  allocator_type get_allocator() const noexcept
  {
    return allocator_type(pool_);
  }

  template <typename... Args>
  void operator()(Args&&... args)
  {
    handler_(std::forward<Args>(args)...);
  }

private:
  storage_pool& pool_;
  Handler handler_;
};

// Convenience function to wrap handlers with custom allocation
template <typename Handler>
inline bound_handler<Handler> bind_with_pool(
    storage_pool& pool, Handler handler)
{
  return bound_handler<Handler>(pool, std::move(handler));
}

// Session class handling client communication
class connection
  : public std::enable_shared_from_this<connection>
{
public:
  connection(tcp::socket sock)
    : socket_(std::move(sock))
  {
  }

  void begin()
  {
    fetch_data();
  }

private:
  void fetch_data()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(buffer_),
        bind_with_pool(storage_pool_,
          [this, self](std::error_code err, std::size_t bytes_transferred)
          {
            if (!err)
            {
              send_response(bytes_transferred);
            }
          }));
  }

  void send_response(std::size_t size)
  {
    auto self(shared_from_this());
    asio::async_write(socket_, asio::buffer(buffer_, size),
        bind_with_pool(storage_pool_,
          [this, self](std::error_code err, std::size_t /*bytes_sent*/)
          {
            if (!err)
            {
              fetch_data();
            }
          }));
  }

  tcp::socket socket_;
  std::array<char, 2048> buffer_;
  storage_pool storage_pool_;
};

// Server accepting incoming connections
class acceptor_service
{
public:
  acceptor_service(asio::io_context& ctx, unsigned short port_num)
    : listener_(ctx, tcp::endpoint(tcp::v4(), port_num))
  {
    initiate_accept();
  }

private:
  void initiate_accept()
  {
    listener_.async_accept(
        [this](std::error_code err, tcp::socket client_socket)
        {
          if (!err)
          {
            std::make_shared<connection>(std::move(client_socket))->begin();
          }
          initiate_accept();
        });
  }

  tcp::acceptor listener_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: server <port>\n";
      return 1;
    }

    asio::io_context context;
    acceptor_service server_instance(context, std::atoi(argv[1]));
    context.run();
  }
  catch (const std::exception& ex)
  {
    std::cerr << "Error: " << ex.what() << "\n";
    return 1;
  }

  return 0;
}

