using namespace std;

// Helper to compute min and max bloom days
pair<int, int> getBloomRange(const vector<int>& days) {
    int mn = INT_MAX;
    int mx = INT_MIN;
    for (int d : days) {
        if (d > mx) mx = d;
        if (d < mn) mn = d;
    }
    return {mn, mx};
}

// Check if we can form at least 'target' bouquets by 'day'
bool canFormBouquets(const vector<int>& bloom, int target, int flowersPer, int day) {
    int bouquetsMade = 0;
    int currentStreak = 0;

    for (int d : bloom) {
        if (d <= day) {
            ++currentStreak;
            if (currentStreak == flowersPer) {
                ++bouquetsMade;
                currentStreak = 0;
            }
        } else {
            currentStreak = 0;
        }
    }
    return bouquetsMade >= target;
}

// Optimized solution using binary search on answer space
int minimumDaysToMakeBouquets(const vector<int>& bloom, int bouquetsNeeded, int flowersPerBouquet) {
    long long requiredFlowers = 1LL * bouquetsNeeded * flowersPerBouquet;
    if (requiredFlowers > bloom.size()) return -1;

    auto [low, high] = getBloomRange(bloom);

    // Binary search for minimal feasible day
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (canFormBouquets(bloom, bouquetsNeeded, flowersPerBouquet, mid)) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    return low;
}

int main() {
    vector<int> bloomDays = {7, 7, 7, 7, 12, 7, 7};
    int m = 2, k = 3;

    int result = minimumDaysToMakeBouquets(bloomDays, m, k);
    cout << result << endl; // Expected: 12

    return 0;
}

