#include "llvm/MC/MCAsmInfoCOFF.h"
#include "llvm/MC/MCDirectives.h"

namespace llvm {

// Virtual anchor for MCAsmInfoCOFF to support RTTI
void MCAsmInfoCOFF::anchor() {}

// Constructor for Microsoft-style COFF assembly info
MCAsmInfoCOFF::MCAsmInfoCOFF() {
  // Initialize COMMDirective behavior: alignment specified in bytes only for .lcomm
  COMMDirectiveAlignmentIsInBytes = false;
  LCOMMDirectiveAlignmentType = LCOMM::ByteAlignment;

  // COFF does not support .type/.size directives
  HasDotTypeDotSizeDirective = false;

  // File directives accept a single argument (filename)
  HasSingleParameterDotFile = true;

  // Weak symbol directive format
  WeakRefDirective = "\t.weak\t";

  // Avoid using .weak when symbol is in a COMDAT group
  AvoidWeakIfComdat = true;

  // Visibility attributes are not supported in COFF
  HiddenVisibilityAttr = MCSA_Invalid;
  HiddenDeclarationVisibilityAttr = MCSA_Invalid;
  ProtectedVisibilityAttr = MCSA_Invalid;

  // Debug information support
  SupportsDebugInformation = true;
  NeedsDwarfSectionOffsetDirective = true;

  // Assembler uses arithmetic shift for right shifts (not logical)
  UseLogicalShr = false;

  // COFF standard supports associative COMDATs
  HasCOFFAssociativeComdats = true;

  // Constants can be placed in COMDAT sections, but must be declared global
  HasCOFFComdatConstants = true;
}

// Anchor for MCAsmInfoMicrosoft
void MCAsmInfoMicrosoft::anchor() {}

// Default constructor for Microsoft-specific COFF info
MCAsmInfoMicrosoft::MCAsmInfoMicrosoft() = default;

// Anchor for GNU-compatible COFF info
void MCAsmInfoGNUCOFF::anchor() {}

// Constructor for GNU-based COFF environments (MinGW/Cygwin)
MCAsmInfoGNUCOFF::MCAsmInfoGNUCOFF() {
  // Disable associative COMDATs for function-related data
  HasCOFFAssociativeComdats = false;

  // Do not emit constants into COMDAT sections under GNU toolchain
  HasCOFFComdatConstants = false;
}

} // namespace llvm

