// ByteArrayInputStream: Constructor using buffer, offset, and length
// Constructs a stream reading from buf starting at 'startIdx', up to 'maxLen' bytes.
// Sets mark position to startIdx; count is capped at buf.length.
ByteArrayInputStream::ByteArrayInputStream(byteArray buf, unsigned int startIdx, unsigned int maxLen)
	: pos(startIdx), mark(startIdx)
{
	this->buf = buf;
	unsigned int endLimit = startIdx + maxLen;
	count = (endLimit < buf.length) ? endLimit : buf.length;
}

// ByteArrayInputStream: Constructor using only buffer
// Starts reading from index 0; reads entire buffer length.
ByteArrayInputStream::ByteArrayInputStream(byteArray buf)
	: pos(0), count(buf.length), mark(0)
{
	this->buf = buf;
}

// Reads one byte. Returns value in [0,255] or -1 if no data remains.
int ByteArrayInputStream::read()
{
	if (pos >= count)
		return -1;
	return buf.data[pos++];
}

// Reads into array b, equivalent to read(b, 0, b.length).
int ByteArrayInputStream::read(byteArray b)
{
	return read(b, 0u, b.length);
}

// Reads up to 'len' bytes into b starting at 'offset'.
// Copies k = min(len, count - pos) bytes, updates pos by k, returns k.
int ByteArrayInputStream::read(byteArray b, unsigned int offset, unsigned int len)
{
	if (pos == count)
		return -1;

	unsigned int remaining = count - pos;
	unsigned int toCopy = (len < remaining) ? len : remaining;

	// Manual copy instead of XMemCpy for clarity (same effect)
	for (unsigned int i = 0; i < toCopy; ++i)
		b.data[offset + i] = buf.data[pos + i];

	pos += toCopy;
	return static_cast<int>(toCopy);
}

// No-op — closing has no effect.
void ByteArrayInputStream::close()
{
	// Intentionally empty
}

// Skips up to 'n' bytes. Actual skip amount = min(n, count - pos).
// Updates pos and returns actual skipped count.
__int64 ByteArrayInputStream::skip(__int64 n)
{
	if (n <= 0)
		return 0;

	__int64 proposedPos = pos + n;
	if (proposedPos > count)
		proposedPos = count;

	__int64 skipped = proposedPos - pos;
	pos = static_cast<unsigned int>(proposedPos);
	return skipped;
}

// Destructor: releases dynamically allocated buffer if owned.
ByteArrayInputStream::~ByteArrayInputStream()
{
	if (buf.data != nullptr)
		delete[] buf.data;
}

#include "ReduceUsingSimplifyCFG.h"
#include "llvm/Analysis/TargetTransformInfo.h"
#include "llvm/IR/Constants.h"
#include "llvm/IR/Instructions.h"
#include "llvm/Transforms/Utils/Local.h"

using namespace llvm;

// Simplify control flow by applying SimplifyCFG to selected basic blocks
static void reduceUsingSimplifyCFG(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();
  SmallVector<BasicBlock *, 16> BlocksToProcess;

  // Collect basic blocks that should be simplified (those not marked for preservation)
  for (auto &Function : Program) {
    for (auto &BasicBlock : Function) {
      if (!O.shouldKeep()) {
        BlocksToProcess.push_back(&BasicBlock);
      }
    }
  }

  TargetTransformInfo TTI(Program.getDataLayout());

  // Apply simplification to each selected block
  for (auto *BB : BlocksToProcess) {
    simplifyCFG(BB, TTI);
  }
}

void llvm::reduceUsingSimplifyCFGDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, reduceUsingSimplifyCFG, "Simplifying CFG via SimplifyCFG");
}

// Force conditional branches to constant values and simplify resulting CFG
static void reduceConditionals(Oracle &O, ReducerWorkItem &WorkItem, bool ToTrue) {
  Module &M = WorkItem.getModule();
  SmallVector<BasicBlock *, 16> BlocksNeedingUpdate;

  for (auto &F : M) {
    for (auto &BB : F) {
      auto *Term = BB.getTerminator();
      auto *BR = dyn_cast<BranchInst>(Term);

      // Skip non-conditional branches or blocks marked for preservation
      if (!BR || !BR->isConditional() || O.shouldKeep())
        continue;

      // Set condition to true or false based on direction
      if (ToTrue) {
        BR->setCondition(ConstantInt::getTrue(BR->getContext()));
      } else {
        BR->setCondition(ConstantInt::getFalse(BR->getContext()));
      }

      BlocksNeedingUpdate.push_back(&BB);
    }
  }

  TargetTransformInfo TTI(M.getDataLayout());

  // Apply CFG simplification after forcing branch conditions
  for (auto *BB : BlocksNeedingUpdate) {
    simplifyCFG(BB, TTI);
  }
}

void llvm::reduceConditionalsTrueDeltaPass(TestRunner &Test) {
  runDeltaPass(
      Test,
      [](Oracle &O, ReducerWorkItem &W) { 
        reduceConditionals(O, W, true); 
      },
      "Forcing conditional branches to true"
  );
}

void llvm::reduceConditionalsFalseDeltaPass(TestRunner &Test) {
  runDeltaPass(
      Test,
      [](Oracle &O, ReducerWorkItem &W) { 
        reduceConditionals(O, W, false); 
      },
      "Forcing conditional branches to false"
  );
}

#include "llvm/Analysis/MemoryBuiltins.h"
#include "llvm/IR/Instructions.h"
#include "llvm/IR/IntrinsicInst.h"
#include "llvm/Support/Debug.h"
#include "Optimization/PE/LLPE.h"
using namespace llvm;

// Determine whether this specialization context should be committed.
bool InlineAttempt::isEnabled() {
  // Root function: always committed.
  if (Callers.empty()) {
    return true;
  }

  // Path condition functions are symbolic and do not generate runtime code.
  if (isPathCondition) {
    return false;
  }

  // Otherwise, commit if shared or explicitly enabled.
  bool result = isShared();
  if (!result) {
    result = enabled;
  }
  return result;
}

// Loop iterations are always committed regardless of parent state.
bool PeelIteration::isEnabled() {
  return true;
}

// Peeling attempts respect their internal 'enabled' flag.
bool PeelAttempt::isEnabled() {
  return enabled;
}

// Attempt to set the commit status (enabled/disabled).
void InlineAttempt::setEnabled(bool en, bool skipStats) {
  // Root functions cannot be disabled.
  if (Callers.empty()) {
    return;
  }

  // Shared contexts cannot currently be disabled.
  if (isShared()) {
    return;
  }

  // Path conditions never commit anyway.
  if (isPathCondition) {
    return;
  }

  enabled = en;
  if (!skipStats) {
    pass->getRoot()->collectStats();
  }
}

void PeelIteration::setEnabled(bool en, bool skipStats) {
  // Not supported yet: individual iteration disabling.
  assert(false && "Cannot disable individual peel iterations");
}

void PeelAttempt::setEnabled(bool en, bool skipStats) {
  enabled = en;
}

// Check if this context commits in a *different* residual function than its parent.
bool InlineAttempt::commitsOutOfLine() {
  // If there's no parent (i.e., root main call), it must be out-of-line.
  if (isRootMainCall()) {
    return true;
  }

  for (SmallVector<ShadowInstruction *, 1>::const_iterator iter = Callers.begin(),
                                                             end = Callers.end();
       iter != end; ++iter) {
    ShadowInstruction *caller = *iter;
    FunctionRoot *parentRoot = caller->parent->IA->getFunctionRoot();

    // If this context has its own CommitF and parent has a *different* one,
    // then this context commits separately.
    if (CommitF && parentRoot->CommitF && parentRoot->CommitF != CommitF) {
      return true;
    }
  }

  return false;
}

// Peel iterations always commit in the same residual function as their parent.
bool PeelIteration::commitsOutOfLine() {
  return false;
}

// Must this function be emitted as a standalone residual function?
bool InlineAttempt::mustCommitOutOfLine() {
  // Root function must have its own residual.
  if (isRootMainCall()) {
    return true;
  }

  // Vararg functions need real va_list handling.
  if (F.isVarArg()) {
    return true;
  }

  // Shared functions require separate linkage.
  if (isShared()) {
    return true;
  }

  // User-specified split point?
  if (pass->splitFunctions.find(&F) != pass->splitFunctions.end()) {
    return true;
  }

  // Special case: failed return path + invoke callers implies OOL commitment.
  if (hasFailedReturnPath()) {
    for (uint32_t idx = 0, limit = Callers.size(); idx < limit; ++idx) {
      if (isa<InvokeInst>(Callers[idx])) {
        return true;
      }
    }
  }

  return false;
}

bool PeelIteration::mustCommitOutOfLine() {
  return false;
}

// Are all ancestor contexts enabled? Used for allocation scoping checks.
bool IntegrationAttempt::allAncestorsEnabled() {
  // First check self.
  if (!isEnabled()) {
    return false;
  }

  // Get unique parent; may be null if shared/uniquely owned.
  IntegrationAttempt *ancestor = getUniqueParent();
  if (ancestor) {
    if (!ancestor->allAncestorsEnabled()) {
      return false;
    }
  }

  return true;
}

