// Boost
#include <boost/filesystem/operations.hpp>
#include <boost/filesystem/path.hpp>

namespace ocs2 {
namespace double_integrator {

DoubleIntegratorInterface::DoubleIntegratorInterface(const std::string& taskFile, const std::string& libraryFolder, bool verbose) {
  // Validate task file path
  boost::filesystem::path taskPath(taskFile);
  if (!taskPath.empty() && boost::filesystem::exists(taskPath)) {
    std::cerr << "[DoubleIntegratorInterface] Task configuration loaded from: " << taskPath << std::endl;
  } else {
    throw std::invalid_argument("[DoubleIntegratorInterface] Task file missing: " + taskPath.string());
  }

  // Ensure output directory exists
  boost::filesystem::path libPath(libraryFolder);
  if (!boost::filesystem::exists(libPath)) {
    boost::filesystem::create_directories(libPath);
  }
  std::cerr << "[DoubleIntegratorInterface] Library output directory: " << libPath << std::endl;

  // Load system parameters
  matrix_t initVec(STATE_DIM, 1);
  matrix_t goalVec(STATE_DIM, 1);
  loadData::loadEigenMatrix(taskFile, "initialState", initVec);
  loadData::loadEigenMatrix(taskFile, "finalGoal", goalVec);
  initialState_ = initVec;
  finalGoal_ = goalVec;

  // Configure DDP/MPC solvers
  ddpSettings_ = ddp::loadSettings(taskFile, "ddp", verbose);
  mpcSettings_ = mpc::loadSettings(taskFile, "mpc", verbose);

  // Setup reference manager
  referenceManagerPtr_ = std::make_shared<ReferenceManager>();

  // Build optimal control problem
  matrix_t stateWeight(STATE_DIM, STATE_DIM);
  matrix_t inputWeight(INPUT_DIM, INPUT_DIM);
  matrix_t finalWeight(STATE_DIM, STATE_DIM);

  loadData::loadEigenMatrix(taskFile, "Q", stateWeight);
  loadData::loadEigenMatrix(taskFile, "R", inputWeight);
  loadData::loadEigenMatrix(taskFile, "Q_final", finalWeight);

  std::cerr << "State cost matrix Q:\n" << stateWeight << "\n";
  std::cerr << "Input cost matrix R:\n" << inputWeight << "\n";
  std::cerr << "Terminal cost matrix Qf:\n" << finalWeight << "\n";

  // Add quadratic costs
  problem_.costPtr->add("stage_cost", std::make_unique<QuadraticStateInputCost>(stateWeight, inputWeight));
  problem_.finalCostPtr->add("terminal_cost", std::make_unique<QuadraticStateCost>(finalWeight));

  // Define linear dynamics matrices
  matrix_t dynA(STATE_DIM, STATE_DIM);
  dynA << 0.0, 1.0,
          0.0, 0.0;
  matrix_t dynB(STATE_DIM, INPUT_DIM);
  dynB << 0.0,
          1.0;
  problem_.dynamicsPtr = std::make_unique<LinearSystemDynamics>(dynA, dynB);

  // Initialize trajectory rollout
  auto rolloutCfg = rollout::loadSettings(taskFile, "rollout", verbose);
  rolloutPtr_ = std::make_unique<TimeTriggeredRollout>(*problem_.dynamicsPtr, rolloutCfg);

  // Set up default initializer for MPC warm-start
  linearSystemInitializerPtr_ = std::make_unique<DefaultInitializer>(INPUT_DIM);
}

}  // namespace double_integrator
}  // namespace ocs2

