// Callback invoked when transit scheme state changes
void OnTransitStateChange(TransitReadManager::TransitSchemeState newState,
                          std::shared_ptr<jobject> const & jListener)
{
  JNIEnv * env = jni::GetEnv();
  jclass listenerClass = env->GetObjectClass(*jListener);
  jmethodID callbackMethod = env->GetMethodID(listenerClass, "onTransitStateChanged", "(I)V");
  env->CallVoidMethod(*jListener, callbackMethod, static_cast<jint>(newState));
}

JNIEXPORT void JNICALL Java_app_organicmaps_sdk_maplayer_subway_SubwayManager_nativeAddListener(JNIEnv * env,
                                                                                                jclass clazz,
                                                                                                jobject listener)
{
  CHECK(g_framework, ("Framework has not been initialized!"));

  // Create a global reference for the listener to ensure it remains valid across JNI calls
  std::shared_ptr<jobject> globalRef = jni::make_global_ref(listener);

  // Register the callback with the framework
  g_framework->SetTransitSchemeListener(
      [globalRef](TransitReadManager::TransitSchemeState state) {
        OnTransitStateChange(state, globalRef);
      });
}

JNIEXPORT void JNICALL Java_app_organicmaps_sdk_maplayer_subway_SubwayManager_nativeRemoveListener(JNIEnv * env,
                                                                                                   jclass clazz)
{
  CHECK(g_framework, ("Framework has not been initialized!"));

  // Clear the current listener by setting an empty function
  g_framework->SetTransitSchemeListener(TransitReadManager::TransitStateChangedFn());
}
