#include "autowakemanager.h"
#include "settings.h"
#include <QDateTime>
#include <QDebug>

AutoWakeManager::AutoWakeManager(Settings* settings, QObject* parent)
    : QObject(parent)
    , m_settings(settings)
    , m_timer(new QTimer(this))
{
    m_timer->setSingleShot(true);
    connect(m_timer, &QTimer::timeout, this, &AutoWakeManager::handleTimeout);

    connect(m_settings, &Settings::autoWakeScheduleChanged, this, [this]() {
        qDebug() << "AutoWakeManager: Schedule updated — resetting and rescheduling";
        m_triggeredDates.clear();
        reschedule();
    });
}

void AutoWakeManager::handleTimeout() {
    qDebug() << "AutoWakeManager: *** WAKE TIME REACHED ***";

    QDate today = QDate::currentDate();
    int weekdayIndex = today.dayOfWeek() % 7; // Monday=1 → index 0, Sunday=7 → index 0 (wrap-around)
    m_triggeredDates[weekdayIndex] = today;

    emit wakeRequested();
    reschedule();
}

void AutoWakeManager::reschedule() {
    m_timer->stop();

    QDateTime currentTime = QDateTime::currentDateTime();
    QVariantList weeklyPlan = m_settings->autoWakeSchedule();

    static const char* dayLabels[] = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"};

    qint64 shortestDelayMs = -1;
    int selectedDayIndex = -1;
    QTime selectedTime;

    for (int offsetDays = 0; offsetDays < 8; ++offsetDays) {
        QDate candidateDate = currentTime.date().addDays(offsetDays);
        int dow = candidateDate.dayOfWeek(); // 1=Mon ... 7=Sun
        int idx = (dow == 7) ? 0 : dow - 1; // Normalize to 0..6

        if (idx < 0 || idx >= weeklyPlan.size())
            continue;

        QVariantMap dailyConfig = weeklyPlan[idx].toMap();
        if (!dailyConfig.value("active", false).toBool())
            continue;

        int h = dailyConfig.value("hour", 7).toInt();
        int m = dailyConfig.value("minute", 0).toInt();
        QDateTime target(candidateDate, QTime(h, m, 0));

        // Skip if already passed or triggered today
        if (target <= currentTime)
            continue;
        if (m_triggeredDates.contains(idx) && m_triggeredDates[idx] == candidateDate)
            continue;

        qint64 delay = currentTime.msecsTo(target);
        if (shortestDelayMs < 0 || delay < shortestDelayMs) {
            shortestDelayMs = delay;
            selectedDayIndex = idx;
            selectedTime = QTime(h, m);
        }

        // Early exit: first valid future time is optimal due to linear scan
        break;
    }

    if (shortestDelayMs > 0) {
        qint64 totalSecs = shortestDelayMs / 1000;
        int hrs = totalSecs / 3600;
        int mins = (totalSecs % 3600) / 60;
        int secs = totalSecs % 60;

        QString durationStr;
        if (hrs > 0)
            durationStr = QString("%1h %2m").arg(hrs).arg(mins);
        else if (mins > 0)
            durationStr = QString("%1m %2s").arg(mins).arg(secs);
        else
            durationStr = QString("%1s").arg(secs);

        qDebug() << "AutoWakeManager: Next wake:" << dayLabels[selectedDayIndex]
                 << selectedTime.toString("HH:mm") << "in" << durationStr;

        m_timer->start(shortestDelayMs);
    } else {
        qDebug() << "AutoWakeManager: No active wake times configured";
    }
}

void AutoWakeManager::activate() {
    qDebug() << "AutoWakeManager: Activating";
    reschedule();
}

void AutoWakeManager::deactivate() {
    qDebug() << "AutoWakeManager: Deactivating";
    m_timer->stop();
}

