    // 205. Beetroots

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;

    // Find the partner of position 1 using binary search
    int left = 2, right = n;
    while (left < right) {
        int mid = left + (right - left) / 2;
        int segment_size = mid - left + 1;
        int batch_size = min(499, segment_size / 2);
        int boundary = left + batch_size - 1;

        vector<int> query_sequence;
        query_sequence.push_back(1); // fixed position

        for (int idx = left; idx <= boundary; idx++) {
            query_sequence.push_back(idx);
            query_sequence.push_back(1);
        }

        cout << "0 " << query_sequence.size();
        for (int val : query_sequence) cout << " " << val;
        cout << endl;
        cout.flush();

        int response;
        cin >> response;

        if (response > 0) {
            right = boundary;
        } else {
            left = boundary + 1;
        }
    }

    int partner = left;

    // Determine which is opening and which is closing
    cout << "0 2 1 " << partner << endl;
    cout.flush();

    int match_response;
    cin >> match_response;

    int open_pos, close_pos;
    if (match_response == 1) {
        open_pos = 1;
        close_pos = partner;
    } else {
        open_pos = partner;
        close_pos = 1;
    }

    // Build result string
    string result(n + 1, ' ');
    result[open_pos] = '(';
    result[close_pos] = ')';

    // Collect remaining positions to determine
    vector<int> pending_positions;
    for (int i = 1; i <= n; i++) {
        if (result[i] == ' ') {
            pending_positions.push_back(i);
        }
    }

    // Process remaining positions in groups
    int index = 0;
    while (index < pending_positions.size()) {
        int group_limit = min(9, (int)pending_positions.size() - index);
        vector<int> current_group;
        for (int j = 0; j < group_limit; j++) {
            current_group.push_back(pending_positions[index + j]);
        }

        // Generate query sequence using bit manipulation approach
        vector<int> query_pattern;
        for (int bit_idx = 0; bit_idx < group_limit; bit_idx++) {
            int count = 1 << bit_idx;
            for (int repeat = 0; repeat < count; repeat++) {
                query_pattern.push_back(current_group[bit_idx]);
                query_pattern.push_back(close_pos);
            }
            query_pattern.push_back(close_pos);
        }

        cout << "0 " << query_pattern.size();
        for (int val : query_pattern) cout << " " << val;
        cout << endl;
        cout.flush();

        int query_result;
        cin >> query_result;

        int remaining = query_result;
        for (int bit_idx = group_limit - 1; bit_idx >= 0; bit_idx--) {
            int count = 1 << bit_idx;
            int threshold = count * (count + 1) / 2;

            if (remaining >= threshold) {
                result[current_group[bit_idx]] = '(';
                remaining -= threshold;
            } else {
                result[current_group[bit_idx]] = ')';
            }
        }

        index += group_limit;
    }

    // Output final answer
    cout << "1";
    for (int i = 1; i <= n; i++) {
        cout << result[i];
    }
    cout << endl;
    cout.flush();

    return 0;
}

#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/div.h"
#include "jemalloc/internal/assert.h"

/*
 * Given n = q * d (all integers), with n and d known, we compute q = n / d.
 *
 * Using the identity for any k:
 * floor(ceil(2^k / d) * n / 2^k) = floor((2^k + r) / d * n / 2^k),
 * where r = (-2^k) mod d (i.e., r = d - (2^k mod d) when 2^k mod d != 0).
 *
 * Expanding:
 * ... = floor(n/d + (r/d)*(n/2^k)).
 *
 * Since d divides n exactly, n/d is integer, and the extra term contributes
 * only if (r/d)*(n/2^k) >= 1. Choosing k=32 ensures n/2^k < 1 (for 32-bit n),
 * and since r/d < 1, the product is < 1, so the floor gives exactly n/d.
 */
void
div_init(div_info_t *div_info, size_t d) {
	/* Division by zero is invalid. */
	assert(d != 0);
	/*
	 * If d == 1, then ceil(2^32 / 1) = 2^32, which cannot be represented
	 * in a 32-bit unsigned integer (max value is 2^32 - 1). This would
	 * cause overflow and break code generation on 32-bit platforms.
	 */
	assert(d != 1);

	uint64_t power_of_two = ((uint64_t)1 << 32);
	uint32_t multiplier = (uint32_t)(power_of_two / d);

	/*
	 * We need ceil(2^32 / d), but C division truncates toward zero.
	 * Increment the quotient unless the division was exact (i.e., d is a power of two).
	 */
	if (power_of_two % d != 0) {
		multiplier++;
	}

	div_info->magic = multiplier;
#ifdef JEMALLOC_DEBUG
	div_info->d = d;
#endif
}

