static uint32_t computeAlignedSize(uint64_t Size, Align Alignment) {
  return static_cast<uint32_t>((Size + Alignment.value() - 1) / Alignment.value() * Alignment.value());
}

uint64_t DXContainerEmitter::emitBinary(MCAssembler &Asm, const MCAsmLayout &Layout) {
  std::vector<uint64_t> PartBoundaries;
  uint64_t CurrentOffset = 0;

  // First pass: collect non-empty sections and compute part boundaries
  for (const auto &Sec : Asm) {
    uint64_t SecSize = Layout.getSectionAddressSize(&Sec);
    if (SecSize == 0)
      continue;

    assert(SecSize < UINT32_MAX && "Section too large for DXContainer");
    PartBoundaries.push_back(CurrentOffset);

    uint64_t PartSize = sizeof(dxbc::PartHeader) + SecSize;
    if (Sec.getName().equals("DXIL"))
      PartSize += sizeof(dxbc::ProgramHeader);

    CurrentOffset = computeAlignedSize(PartSize, Align(4));
  }

  assert(CurrentOffset < UINT32_MAX && "Total part size exceeds limit");

  const uint64_t HeaderSize = sizeof(dxbc::Header);
  const uint64_t OffsetTableSize = PartBoundaries.size() * sizeof(uint32_t);
  const uint64_t FirstPartLocation = HeaderSize + OffsetTableSize;
  const uint64_t TotalFileSize = FirstPartLocation + CurrentOffset;

  assert(TotalFileSize < UINT32_MAX && "File too large for DXContainer format");

  // Write DXBC header
  StreamWriter.write<char>({'D', 'X', 'B', 'C'});
  StreamWriter.OS.write_zeros(16); // Reserved hash
  StreamWriter.write<uint16_t>(1); // Major version
  StreamWriter.write<uint16_t>(0); // Minor version
  StreamWriter.write<uint32_t>(static_cast<uint32_t>(TotalFileSize));
  StreamWriter.write<uint32_t>(static_cast<uint32_t>(PartBoundaries.size()));

  // Write part offset table
  for (uint64_t Off : PartBoundaries) {
    StreamWriter.write<uint32_t>(static_cast<uint32_t>(FirstPartLocation + Off));
  }

  // Second pass: write each part
  for (const auto &Sec : Asm) {
    uint64_t SecSize = Layout.getSectionAddressSize(&Sec);
    if (SecSize == 0)
      continue;

    unsigned StartPos = StreamWriter.OS.tell();

    // Write part header
    StringRef Name = Sec.getName();
    assert(Name.size() >= 4 && "Section name must be at least 4 chars");
    StreamWriter.write<char>(ArrayRef<char>(Name.data(), 4));

    uint64_t PartSize = SecSize;
    if (Name.equals("DXIL"))
      PartSize += sizeof(dxbc::ProgramHeader);

    PartSize = computeAlignedSize(PartSize, Align(4));
    StreamWriter.write<uint32_t>(static_cast<uint32_t>(PartSize));

    if (Name.equals("DXIL")) {
      dxbc::ProgramHeader PH{};
      memset(&PH, 0, sizeof(PH));

      const Triple &Triple = Asm.getContext().getTargetTriple();
      VersionTuple VT = Triple.getOSVersion();
      PH.MajorVersion = static_cast<uint8_t>(VT.getMajor());
      if (VT.hasMinor())
        PH.MinorVersion = static_cast<uint8_t>(*VT.getMinor());
      if (Triple.hasEnvironment())
        PH.ShaderKind = static_cast<uint16_t>(Triple.getEnvironment() - Triple::Pixel);

      PH.Size = static_cast<uint32_t>(
          (SecSize + sizeof(dxbc::ProgramHeader) + 3) / 4);
      memcpy(PH.Bitcode.Magic, "DXIL", 4);
      PH.Bitcode.Offset = sizeof(dxbc::BitcodeHeader);
      PH.Bitcode.Size = static_cast<uint32_t>(SecSize);

      if (sys::IsBigEndianHost)
        PH.swapBytes();

      StreamWriter.write<char>(
          ArrayRef<char>(reinterpret_cast<char *>(&PH), sizeof(PH)));
    }

    Asm.writeSectionData(StreamWriter.OS, &Sec, Layout);

    unsigned WrittenBytes = StreamWriter.OS.tell() - StartPos;
    unsigned Padding = offsetToAlignment(WrittenBytes, Align(4));
    StreamWriter.OS.write_zeros(Padding);
  }

  return 0;
}

std::unique_ptr<MCObjectWriter> llvm::createDXContainerObjectWriter(
    std::unique_ptr<MCDXContainerTargetWriter> TW, raw_pwrite_stream &OS) {
  return std::make_unique<DXContainerEmitter>(std::move(TW), OS);
}

