int main(int argc, char* argv[]) {
    registerInteraction(argc, argv);

    int n = inf.readInt();
    println(n);

    std::vector<int> arr(n);
    for (int idx = 0; idx < n; ++idx) {
        arr[idx] = inf.readInt();
    }

    // Build prefix XOR table for range queries
    std::vector<std::vector<bool>> prefixXor(n + 1, std::vector<bool>(n + 1, false));

    // Fill base comparison matrix: prefixXor[i+1][j+1] = (arr[i] > arr[j])
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            prefixXor[i + 1][j + 1] = (arr[i] > arr[j]);
        }
    }

    // Apply row-wise prefix XOR
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= n; ++j) {
            prefixXor[i + 1][j] ^= prefixXor[i][j];
        }
    }

    // Apply column-wise prefix XOR
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j < n; ++j) {
            prefixXor[i][j + 1] ^= prefixXor[i][j];
        }
    }

    // Process up to 1999000 queries
    for (int queryCount = 0; queryCount <= 1999000; ++queryCount) {
        int actionType = ouf.readInt();

        if (actionType == 0) {
            int left = ouf.readInt();
            if (left < 1 || left > n) {
                quitf(_wa, "Invalid query: element %d is out of range [1, %d]", left, n);
            }

            int right = ouf.readInt();
            if (right < 1 || right > n) {
                quitf(_wa, "Invalid query: element %d is out of range [1, %d]", right, n);
            }

            if (left > right) {
                quitf(_wa, "Invalid query: not an interval.");
            }

            --left;
            bool result = prefixXor[right][right] ^ prefixXor[left][right] ^ 
                         prefixXor[right][left] ^ prefixXor[left][left];
            println(result ? 1 : 0);
        } 
        else if (actionType == 1) {
            std::vector<int> guessedArr(n);
            for (int i = 0; i < n; ++i) {
                guessedArr[i] = ouf.readInt();
            }

            if (guessedArr == arr) {
                double score = (std::exp(-1.0 * queryCount / 249875.0) - std::exp(-8.0)) / 
                              (1.0 - std::exp(-8.0));
                quitp(score, "Correct guess. Ratio: %.4f", score);
            } else {
                quitp(0.0, "Wrong guess. Ratio: 0.0000");
            }
        } 
        else {
            quitf(_wa, "Invalid action type: expected 0 or 1, but got %d", actionType);
        }
    }

    quitp(0.0, "Too many queries. Ratio: 0.0000");
    return 0;
}

