int global_arr[10];
int32_t helper_func1(int32_t *input) {
    int64_t temp = input[0] + input[2]; // exact: 4, abstracted as [2,40]
    int offset = nd_int();
    __CRAB_assume(offset >= 0);
    __CRAB_assume(offset <= 3);
    input[offset] = 30;
    return static_cast<int32_t>(temp);
}
int32_t helper_func2(const uint32_t matrix[6][2]) {
    return matrix[0][1] + matrix[2][1]; // always 30
}
int main() {
    int32_t local_table1[4];
    local_table1[0] = 1;
    local_table1[1] = 20;
    local_table1[2] = 3;

    uint32_t local_table2[3][2];
    local_table2[0][1] = 10;
    local_table2[2][1] = 20;

    // Initialize global array with non-deterministic values (3 or 5)
    for (int idx = 0; idx < 10; ++idx) {
        global_arr[idx] = (nd_int() ? 3 : 5);
    }

    int selector = nd_int();
    __CRAB_assume(selector >= 0);
    __CRAB_assume(selector < 10);
    int value = global_arr[selector];

    __CRAB_assert(value >= 0);   // holds: min is 3
    __CRAB_assert(value <= 5);   // holds: max is 5

    int result1 = helper_func1(local_table1);
    __CRAB_assert(result1 <= 40); // holds: original res=4, after write may be up to 40

    int mid_val = local_table1[1];
    __CRAB_assert(mid_val <= 30); // holds: set to 30 via helper_func1 if idx==1, else unchanged (≤20)

    int result2 = helper_func2(local_table2);
    __CRAB_assert(result2 == 30); // holds: 10 + 20

    return value + mid_val + result2;
}

