// Helper type alias for return value
using EnergyWavefunctionPair = std::pair<double, std::shared_ptr<Wavefunction>>;

// Trampoline class enabling Python subclassing
class PMCBaseTrampoline : public ProjectedMultiConfigurationCalculator,
                          public pybind11::trampoline_self_life_support {
 public:
  std::string algorithm_name() const override {
    PYBIND11_OVERRIDE_PURE(std::string, ProjectedMultiConfigurationCalculator,
                           name);
  }

  std::vector<std::string> known_aliases() const override {
    PYBIND11_OVERRIDE(std::vector<std::string>,
                      ProjectedMultiConfigurationCalculator, aliases);
  }

  // New internal method: replaces current settings with new instance
  void update_internal_settings(
      std::unique_ptr<Settings> updated_config) {
    this->_settings = std::move(updated_config);
  }

 protected:
  EnergyWavefunctionPair execute_impl(
      std::shared_ptr<Hamiltonian> hamiltonian,
      const std::vector<Configuration>& determinants) const override {
    PYBIND11_OVERRIDE_PURE(EnergyWavefunctionPair,
                           ProjectedMultiConfigurationCalculator,
                           _run_impl, hamiltonian, determinants);
  }
};

void bind_pmc(py::module& m) {
  // Abstract base class binding
  py::class_<ProjectedMultiConfigurationCalculator,
             PMCBaseTrampoline, py::smart_holder>
      pmc_interface(m, "ProjectedMultiConfigurationCalculator",
                    R"(
Abstract foundation for projected multi-configurational (PMC) quantum chemistry computations.
This class defines the contract for algorithms that project a given Hamiltonian onto a user-specified space of determinants.
It enables integration of high-performance solvers with external determinant selection strategies.
Input includes a Hamiltonian and a list of configurations; output is a total energy and wavefunction.
To implement your own PMC solver, subclass this interface.
Example:
    >>> import qdk_chemistry.algorithms as alg
    >>> import qdk_chemistry.data as data
    >>> class CustomPMC(alg.ProjectedMultiConfigurationCalculator):
    ...     def __init__(self):
    ...         super().__init__()
    ...     def _run_impl(self, hamiltonian: data.Hamiltonian, configurations: list[data.Configuration]) -> tuple[float, data.Wavefunction]:
    ...         # Your implementation here
    ...         return energy, wavefunction
)");

  pmc_interface.def(py::init<>(),
                    R"(
Constructs an empty PMC calculator base instance.
Typically invoked via `super().__init__()` in derived classes.
)");

  pmc_interface.def("compute", &ProjectedMultiConfigurationCalculator::run,
                    R"(
Executes the projected multi-configurational calculation.
Locks the configuration before proceeding.
Parameters:
    hamiltonian (qdk_chemistry.data.Hamiltonian): System Hamiltonian operator
    configurations (list[qdk_chemistry.data.Configuration]): Determinant basis for projection
Returns:
    tuple[float, qdk_chemistry.data.Wavefunction]: Total energy and resulting wavefunction
Raises:
    RuntimeError: On computational failure
    ValueError: For invalid inputs
)",
                    py::arg("hamiltonian"), py::arg("configurations"));

  pmc_interface.def("configuration", &ProjectedMultiConfigurationCalculator::settings,
                    R"(
Provides access to the current configuration parameters.
Returns:
    qdk_chemistry.data.Settings: Reference to active settings object
)",
                    py::return_value_policy::reference_internal);

  // Expose writable '_settings' property using lambdas instead of direct access
  pmc_interface.def_property(
      "_settings",
      [](PMCBaseTrampoline& calc) -> Settings& { return calc.settings(); },
      [](PMCBaseTrampoline& calc,
         std::unique_ptr<Settings> new_config) {
        calc.update_internal_settings(std::move(new_config));
      },
      py::return_value_policy::reference_internal,
      R"(
Internal settings container that can be substituted at runtime.
Useful when initializing subclasses with specialized Settings types.
Example:
    >>> class MyPMC(alg.ProjectedMultiConfigurationCalculator):
    ...     def __init__(self):
    ...         super().__init__()
    ...         from qdk_chemistry.data import ElectronicStructureSettings
    ...         self._settings = ElectronicStructureSettings()
)");

  pmc_interface.def("label", &ProjectedMultiConfigurationCalculator::name,
                    R"(
Returns the human-readable name of the algorithm.
Returns:
    str: Algorithm identifier
)");

  pmc_interface.def("category", &ProjectedMultiConfigurationCalculator::type_name,
                    R"(
Returns the internal type classification string.
Returns:
    str: Type descriptor used internally
)");

  // Factory binding using renamed template instantiation
  qdk::chemistry::python::bind_algorithm_factory<
      ProjectedMultiConfigurationCalculatorFactory,
      ProjectedMultiConfigurationCalculator,
      PMCBaseTrampoline>(
      m, "ProjectedMultiConfigurationCalculatorFactory");

  pmc_interface.def("__repr__", [](const ProjectedMultiConfigurationCalculator&) {
    return "<qdk_chemistry.algorithms.ProjectedMultiConfigurationCalculator>";
  });

  // Concrete Microsoft MACIS-based implementation
  py::class_<microsoft::MacisPmc, ProjectedMultiConfigurationCalculator,
             py::smart_holder>(m, "QdkMacisPmc", R"(
Concrete PMC calculator backed by Microsoft's MACIS library.
Performs Hamiltonian projection over a user-provided determinant space.
Suitable for strongly-correlated electronic structure problems where deterministic sampling is required.
Usage example:
.. code-block:: python
    import qdk_chemistry.algorithms as alg
    import qdk_chemistry.data as data
    pmc = alg.QdkMacisPmc()
    pmc.settings().set("davidson_res_tol", 1e-8)
    pmc.settings().set("davidson_max_m", 200)
    energy, wf = pmc.compute(hamiltonian, configurations)
See Also:
