class Solution {
public:
    int countOdds(int low, int high) {
        // Count odd numbers from 1 to high, subtract count from 1 to (low-1)
        int countHigh = (high + 1) / 2;
        int countLow = low / 2;
        return countHigh - countLow;
    }
};

#include "stdafx.h"
#include <helpers/wav_writer.hpp>
#include <SDK/playback_stream_capture.hpp>

namespace {
    using wav_writer = CWavWriter;
    using wav_writer_setup = wavWriterSetup_t;

    // Encapsulate shared state
    struct capture_state {
        pfc::string8 output_directory;
        wav_writer writer;
        bool is_active = false;
    } g_capture;

    class stream_capture_handler : public playback_stream_capture_callback {
    public:
        void on_chunk(const audio_chunk& chunk) override {
            PFC_ASSERT(core_api::is_main_thread());

            try {
                auto const& abort = fb2k::noAbort;

                // Finalize current writer if spec mismatched
                if (g_capture.writer.is_open() && g_capture.writer.get_spec() != chunk.get_spec()) {
                    g_capture.writer.finalize(abort);
                }

                // Start new capture if not already open and app isn’t shutting down
                if (!g_capture.writer.is_open() && !core_api::is_shutting_down()) {
                    wav_writer_setup setup;
                    setup.initialize(chunk, /*bit_depth=*/16, /*dither=*/false, /*high_res_timestamps=*/false);

                    pfc::string_formatter filename;
                    filename << "capture-" << pfc::print_guid(pfc::createGUID()) << ".wav";

                    pfc::string_formatter full_path = g_capture.output_directory;
                    full_path.add_filename(filename); // Append filename safely

                    g_capture.writer.open(full_path, setup, abort);
                }

                // Write current chunk
                g_capture.writer.write(chunk, abort);

            } catch (std::exception const& e) {
                FB2K_console_formatter() << "[Capture Error] " << e.what();
                // TODO: Add robust error recovery (disk full, permissions, etc.)
            }
        }
    };

    static stream_capture_handler s_handler;

    // Helper: finalize current recording without stopping capture
    void end_current_segment() {
        if (g_capture.writer.is_open()) {
            g_capture.writer.finalize(fb2k::noAbort);
        }
    }

    // Stop capture entirely
    void halt_capture() {
        if (g_capture.is_active) {
            g_capture.is_active = false;
            playback_stream_capture::get()->remove_callback(&s_handler);
            end_current_segment();
        }
    }

    // Initiate capture from configured directory
    void begin_capture() {
        PFC_ASSERT(!g_capture.output_directory.isEmpty());
        if (!g_capture.is_active && !core_api::is_shutting_down()) {
            g_capture.is_active = true;
            playback_stream_capture::get()->add_callback(&s_handler);
        }
    }

    // Shutdown hook
    class shutdown_hook : public initquit {
    public:
        void on_quit() override {
            PFC_ASSERT(core_api::is_shutting_down());
            halt_capture();
        }
    };

    // Play-back event listener to split files on stop
    class playback_listener : public play_callback_static {
    public:
        unsigned get_flags() override { return flag_on_playback_stop; }

        void on_playback_stop(play_control::t_stop_reason) override {
            end_current_segment();
        }

        // Unused callbacks — no-op stubs
        void on_playback_starting(play_control::t_track_command, bool) override {}
        void on_playback_new_track(metadb_handle_ptr) override {}
        void on_playback_seek(double) override {}
        void on_playback_pause(bool) override {}
        void on_playback_edited(metadb_handle_ptr) override {}
        void on_playback_dynamic_info(const file_info&) override {}
        void on_playback_dynamic_info_track(const file_info&) override {}
        void on_playback_time(double) override {}
        void on_volume_change(float) override {}
    };

    // Register services
    FB2K_SERVICE_FACTORY(shutdown_hook);
    FB2K_SERVICE_FACTORY(playback_listener);
}

// Callback invoked after folder selection dialog completes
static void handle_folder_selection(fb2k::arrayRef location) {
    if (g_capture.is_active || location.is_empty() || location->size() != 1) return;

    fsItemFolderPtr folder;
    fb2k::stringRef path_str;
    auto item = location->itemAt(0);

    if (!(path_str &= item)) {
        if (!(folder &= item)) return;
        path_str = folder->canonicalPath();
    }

    if (path_str.is_valid()) {
        g_capture.output_directory = path_str->c_str();
        begin_capture();
    }
}

void ToggleCapture() {
#ifdef _WIN32
    if (!ModalDialogPrologue()) return; // Prevent recursion during modal dialogs

    if (g_capture.is_active) {
        halt_capture();
    } else {
        const HWND main_hwnd = core_api::get_main_window();
        modal_dialog_scope scope(main_hwnd);
        if (uBrowseForFolder(main_hwnd, "Select output directory", g_capture.output_directory)) {
            begin_capture();
        }
    }
#else
    if (g_capture.is_active) {
        halt_capture();
    } else {
        auto dlg = fb2k::fileDialog::get()->setupOpenFolder();
        dlg->setTitle("Choose output folder");
        dlg->run(fb2k::fileDialogNotify::create(handle_folder_selection));
    }
#endif
}

bool IsCaptureRunning() {
    return g_capture.is_active;
}

