const wchar_t File::pathSeparator = L'\\';

#ifdef _XBOX
const std::wstring File::pathRoot = L"GAME:";
#else
const std::wstring File::pathRoot = L"";
#endif

// Creates a new File instance from a parent abstract pathname and a child
// pathname string.
File::File(const File& parent, const std::wstring& child) {
    m_abstractPathName = constructPath(parent.getPath(), child);
}

// Creates a new File instance by converting the given pathname string into an
// abstract pathname.
File::File(const std::wstring& pathname) {
    if (pathname.empty()) {
        m_abstractPathName = L"";
    } else {
        m_abstractPathName = normalizePath(pathname);
    }

#ifdef _WINDOWS64
    std::string path      = wstringtofilename(m_abstractPathName);
    std::string finalPath = StorageManager.GetMountedPath(path.c_str());
    if (finalPath.empty()) finalPath = path;
    m_abstractPathName = convStringToWstring(finalPath);
#elif defined(_DURANGO)
    std::wstring finalPath =
        StorageManager.GetMountedPath(m_abstractPathName.c_str());
    if (finalPath.empty()) finalPath = m_abstractPathName;
    m_abstractPathName = finalPath;
#endif
}

File::File(const std::wstring& parent, const std::wstring& child) {
    m_abstractPathName = pathRoot + pathSeparator + parent + pathSeparator + child;
}

// Deletes the file or directory denoted by this abstract pathname.
bool File::_delete() {
#ifdef _UNICODE
    BOOL result = DeleteFile(getPath().c_str());
#else
    BOOL result = DeleteFile(wstringtofilename(getPath()).c_str());
#endif
    return (result != 0);
}

// Creates the directory named by this abstract pathname.
bool File::mkdir() const {
#ifdef _UNICODE
    return CreateDirectory(getPath().c_str(), NULL) != 0;
#else
    return CreateDirectory(wstringtofilename(getPath()).c_str(), NULL) != 0;
#endif
}

// Creates the directory named by this abstract pathname, including any
// necessary but nonexistent parent directories.
bool File::mkdirs() const {
    std::vector<std::wstring> pathComponents = splitPath(m_abstractPathName);
    std::wstring currentPath = L"";

    for (const auto& component : pathComponents) {
        if (component == pathRoot) {
            currentPath = component;
            continue;
        }

        if (!currentPath.empty()) {
            currentPath += pathSeparator;
        }
        currentPath += component;

        // Check if directory exists and create if needed
#ifdef _UNICODE
        if (GetFileAttributes(currentPath.c_str()) == INVALID_FILE_ATTRIBUTES) {
            if (CreateDirectory(currentPath.c_str(), NULL) == 0) {
                return false;
            }
        }
#else
        std::string narrowPath = wstringtofilename(currentPath);
        if (GetFileAttributes(narrowPath.c_str()) == INVALID_FILE_ATTRIBUTES) {
            if (CreateDirectory(narrowPath.c_str(), NULL) == 0) {
                return false;
            }
        }
#endif
    }

    assert(exists());
    return true;
}

// Tests whether the file or directory denoted by this abstract pathname exists.
bool File::exists() const {
#ifdef _UNICODE
    return GetFileAttributes(getPath().c_str()) != INVALID_FILE_ATTRIBUTES;
#else
    std::string narrowPath = wstringtofilename(getPath());
    return GetFileAttributes(narrowPath.c_str()) != INVALID_FILE_ATTRIBUTES;
#endif
}

// Tests whether the file denoted by this abstract pathname is a normal file.
bool File::isFile() const { 
    return exists() && !isDirectory(); 
}

// Renames the file denoted by this abstract pathname.
bool File::renameTo(File dest) {
    std::string sourcePath = wstringtofilename(getPath());
    std::string destPath   = wstringtofilename(dest.getPath());

#ifdef _DURANGO
    __debugbreak(); // TODO
    return false;
#else
    BOOL result = MoveFile(sourcePath.c_str(), destPath.c_str());
    return (result != 0);
#endif
}

// Returns an array of abstract pathnames denoting the files in the directory.
std::vector<File*>* File::listFiles() const {
    std::vector<File*>* result = new std::vector<File*>();

    if (!isDirectory()) {
        return result;
    }

#ifdef __PS3__
    processPS3Directory(result);
#elif defined(__ORBIS__) || defined(__PSVITA__)
    processVitaDirectory(result);
#else
    processWindowsDirectory(result);
#endif

    return result;
}

// Returns an array of abstract pathnames denoting the files that satisfy the filter.
std::vector<File*>* File::listFiles(FileFilter* filter) const {
    std::vector<File*>* result = new std::vector<File*>();

    if (!isDirectory() || filter == nullptr) {
        return result;
    }

#ifdef __PS3__
    processFilteredPS3Directory(result, filter);
#elif defined(__ORBIS__) || defined(__PSVITA__)
    processFilteredVitaDirectory(result, filter);
#else
    processFilteredWindowsDirectory(result, filter);
#endif

    return result;
}

// Tests whether the file denoted by this abstract pathname is a directory.
bool File::isDirectory() const {
#ifdef _UNICODE
    DWORD attributes = GetFileAttributes(getPath().c_str());
#else
    std::string narrowPath = wstringtofilename(getPath());
    DWORD attributes = GetFileAttributes(narrowPath.c_str());
#endif

    return exists() && ((attributes & FILE_ATTRIBUTE_DIRECTORY) == FILE_ATTRIBUTE_DIRECTORY);
}

// Returns the length of the file denoted by this abstract pathname.
std::int64_t File::length() {
#ifdef __PS3__
    return getPS3FileSize();
#elif defined(__ORBIS__) || defined(__PSVITA__)
    return getVitaFileSize();
#else
    return getWindowsFileSize();
#endif
}

// Returns the time that the file was last modified.
std::int64_t File::lastModified() {
    WIN32_FILE_ATTRIBUTE_DATA fileInfoBuffer;

#ifdef _UNICODE
    BOOL result = GetFileAttributesEx(
        getPath().c_str(),
        GetFileExInfoStandard,
        &fileInfoBuffer
    );
#else
    std::string narrowPath = wstringtofilename(getPath());
    BOOL result = GetFileAttributesEx(
        narrowPath.c_str(),
        GetFileExInfoStandard,
        &fileInfoBuffer
    );
#endif

    if (result != 0 && !isDirectory()) {
        LARGE_INTEGER liLastModified;
        liLastModified.HighPart = fileInfoBuffer.ftLastWriteTime.dwHighDateTime;
        liLastModified.LowPart  = fileInfoBuffer.ftLastWriteTime.dwLowDateTime;
        return liLastModified.QuadPart;
    }

    return 0L;
}

