std::wstring File::getName() const {
    size_t separatorPos = m_abstractPathName.find_last_of(pathSeparator);
    if (separatorPos != std::wstring::npos) {
        return m_abstractPathName.substr(separatorPos + 1);
    }
    return m_abstractPathName;
}

bool File::eq_test(const File& x, const File& y) {
