}

int File::hash_fnct(const File& k) {
    int hashCode = 0;
    const std::wstring& path = k.m_abstractPathName;

    for (size_t i = 0; i < path.length(); ++i) {
        hashCode = (hashCode * 31 + path[i]) % 149;
    }

    return hashCode;
}

// Helper methods for different platforms
void File::processPS3Directory(std::vector<File*>* output) const {
    const char* lpFileName = wstringtofilename(getPath());
    char filePath[256];
    std::string mountedPath = StorageManager.GetMountedPath(lpFileName);

    if (mountedPath.length() > 0) {
        strcpy(filePath, mountedPath.c_str());
    } else if (lpFileName[0] == '/') {
        strcpy(filePath, lpFileName);
    } else {
        sprintf(filePath, "%s/%s", getUsrDirPath(), lpFileName);
    }

    int fd;
    CellFsErrno err = cellFsOpendir(filePath, &fd);
    CellFsDirectoryEntry de;
    std::uint32_t count = 0;

    err = cellFsGetDirectoryEntries(fd, &de, sizeof(CellFsDirectoryEntry), &count);

    while (count > 0) {
        if (de.attribute.st_mode & CELL_FS_S_IFREG) {
            output->push_back(new File(*this, filenametowstring(de.entry_name.d_name)));
        }

        err = cellFsGetDirectoryEntries(fd, &de, sizeof(CellFsDirectoryEntry), &count);
    }

    cellFsClose(fd);
}

void File::processVitaDirectory(std::vector<File*>* output) const {
    const char* lpFileName = wstringtofilename(getPath());
    char filePath[256];
    std::string mountedPath = StorageManager.GetMountedPath(lpFileName);

    if (mountedPath.length() > 0) {
        strcpy(filePath, mountedPath.c_str());
    } else if (lpFileName[0] == '/') {
        strcpy(filePath, lpFileName);
    } else {
        sprintf(filePath, "%s/%s", getUsrDirPath(), lpFileName);
    }

    SceFiosDH dh = SCE_FIOS_DH_INVALID;
    SceFiosBuffer buf = {0};

    SceFiosOp op = sceFiosDHOpen(NULL, &dh, filePath, buf);
    int err = sceFiosOpWait(op);

    if (err == SCE_FIOS_OK) {
        SceFiosSize size = sceFiosOpGetActualCount(op);
        char* pBuf = new char[size];
        buf.set(pBuf, static_cast<size_t>(size));
        sceFiosOpDelete(op);
        sceFiosDHClose(NULL, dh);

        err = sceFiosDHOpenSync(NULL, &dh, filePath, buf);

        if (err == SCE_FIOS_OK) {
            SceFiosDirEntry entry;
            ZeroMemory(&entry, sizeof(SceFiosDirEntry));

            err = sceFiosDHReadSync(NULL, dh, &entry);
            while (err == SCE_FIOS_OK) {
                output->push_back(new File(*this, filenametowstring(entry.fullPath + entry.offsetToName)));
                ZeroMemory(&entry, sizeof(SceFiosDirEntry));
                err = sceFiosDHReadSync(NULL, dh, &entry);
            }
        }

        sceFiosDHClose(NULL, dh);
        delete[] pBuf;
    }
}

void File::processWindowsDirectory(std::vector<File*>* output) const {
    WIN32_FIND_DATA wfd;

#ifdef _UNICODE
    WCHAR path[MAX_PATH];
    swprintf(path, MAX_PATH, L"%ls\\*", getPath().c_str());
    HANDLE hFind = FindFirstFile(path, &wfd);
#else
    char path[MAX_PATH];
    sprintf(path, "%s\\*", wstringtofilename(getPath()).c_str());
    HANDLE hFind = FindFirstFile(path, &wfd);
#endif

    if (hFind != INVALID_HANDLE_VALUE) {
        do {
            output->push_back(new File(*this, 
#ifdef _UNICODE
                wfd.cFileName
#else
                filenametowstring(wfd.cFileName)
#endif
            ));
        } while (FindNextFile(hFind, &wfd));

        FindClose(hFind);
    }
}

void File::processFilteredPS3Directory(std::vector<File*>* output, FileFilter* filter) const {
    const char* lpFileName = wstringtofilename(getPath());
    char filePath[256];
    std::string mountedPath = StorageManager.GetMountedPath(lpFileName);

    if (mountedPath.length() > 0) {
