std::int64_t File::getVitaFileSize() const {
    char filePath[256];
    const char* lpFileName = wstringtofilename(getPath());
    std::string mountedPath = StorageManager.GetMountedPath(lpFileName);

    if (mountedPath.length() > 0) {
        strcpy(filePath, mountedPath.c_str());
    } else if (lpFileName[0] == '/') {
        strcpy(filePath, lpFileName);
    } else {
        sprintf(filePath, "%s/%s", getUsrDirPath(), lpFileName);
    }

    SceFiosStat statData;
    if (sceFiosStatSync(NULL, filePath, &statData) != SCE_FIOS_OK) {
        return 0;
    }

    if (statData.statFlags & SCE_FIOS_STATUS_DIRECTORY) {
        return 0;
    }

    return statData.fileSize;
}

std::int64_t File::getWindowsFileSize() const {
    WIN32_FILE_ATTRIBUTE_DATA fileInfoBuffer;

#ifdef _UNICODE
    BOOL result = GetFileAttributesEx(
        getPath().c_str(),
        GetFileExInfoStandard,
        &fileInfoBuffer
    );
#else
    std::string narrowPath = wstringtofilename(getPath());
    BOOL result = GetFileAttributesEx(
        narrowPath.c_str(),
        GetFileExInfoStandard,
        &fileInfoBuffer
    );
#endif

    if (result != 0 && !isDirectory()) {
        LARGE_INTEGER liFileSize;
        liFileSize.HighPart = fileInfoBuffer.nFileSizeHigh;
        liFileSize.LowPart  = fileInfoBuffer.nFileSizeLow;
        return liFileSize.QuadPart;
    }

    return 0L;
}

// Helper functions for path manipulation
std::wstring File::constructPath(const std::wstring& parent, const std::wstring& child) {
    return parent + pathSeparator + child;
}

std::wstring File::normalizePath(const std::wstring& path) {
    return path;
}

std::vector<std::wstring> File::splitPath(const std::wstring& path) {
    std::vector<std::wstring> components;
    size_t start = 0;
    size_t end = path.find(pathSeparator, start);

    while (end != std::wstring::npos) {
        if (end > start) {
            components.push_back(path.substr(start, end - start));
        }
        start = end + 1;
        end = path.find(pathSeparator, start);
    }

    if (start < path.length()) {
        components.push_back(path.substr(start));
    }

    return components;
}

