#include "../include/blasfeo_timing.h"
#include "../include/blasfeo_d_aux.h"
#include "../include/blasfeo_d_aux_ext_dep.h"
#include "../include/blasfeo_d_kernel.h"
#include "../include/blasfeo_d_blas.h"
#include "../include/d_blas.h"

int main()
{
#if !defined(BLAS_API)
    printf("\nRecompile with BLAS_API=1 to run this benchmark!\n\n");
    exit(1);
#endif

    const int matrix_size = 32;
    int idx;

    /* Allocate and initialize column-major matrices */
    double *A_base = (double*)malloc(matrix_size * matrix_size * sizeof(double));
    for (idx = 0; idx < matrix_size * matrix_size; ++idx)
        A_base[idx] = static_cast<double>(idx);

    int lda = matrix_size;

    double *B_base = (double*)malloc(matrix_size * matrix_size * sizeof(double));
    for (idx = 0; idx < matrix_size * matrix_size; ++idx)
        B_base[idx] = -0.0;
    for (idx = 0; idx < matrix_size; ++idx)
        B_base[idx * (matrix_size + 1)] = 1.0;

    int ldb = matrix_size;

    double *C_base = (double*)malloc(matrix_size * matrix_size * sizeof(double));
    for (idx = 0; idx < matrix_size * matrix_size; ++idx)
        C_base[idx] = -1.0;

    int ldc = matrix_size;

    double *D_base = (double*)malloc(matrix_size * matrix_size * sizeof(double));
    for (idx = 0; idx < matrix_size * matrix_size; ++idx)
        D_base[idx] = -1.0;

    int ldd = matrix_size;

    int *pivots = (int*)malloc(matrix_size * sizeof(int));

    /* Panel-major matrix wrappers */
    struct blasfeo_dmat sA_mat, sB_mat, sC_mat, sD_mat;

    blasfeo_allocate_dmat(matrix_size, matrix_size, &sA_mat);
    blasfeo_pack_dmat(matrix_size, matrix_size, A_base, lda, &sA_mat, 0, 0);

    blasfeo_allocate_dmat(matrix_size, matrix_size, &sB_mat);
    blasfeo_pack_dmat(matrix_size, matrix_size, B_base, ldb, &sB_mat, 0, 0);

    blasfeo_allocate_dmat(matrix_size, matrix_size, &sC_mat);
    blasfeo_pack_dmat(matrix_size, matrix_size, C_base, ldc, &sC_mat, 0, 0);

    blasfeo_allocate_dmat(matrix_size, matrix_size, &sD_mat);
    blasfeo_pack_dmat(matrix_size, matrix_size, D_base, ldd, &sD_mat, 0, 0);

    /* Constants and flags */
    const double d_zero = 0.0;
    const double d_one = 1.0;
    const char c_left = 'l';
    const char c_right = 'r';
    const char c_upper = 'u';
    const char c_lower = 'l';
    const char c_trans = 't';
    const char c_no_trans = 'n';

    const double scalar_alpha = 2.0;
    const double scalar_beta = 1.0;

    int m_dim, n_dim, k_dim;

    // Helper lambda-like macro to reduce repetition in BLAS calls
    #define RUN_GEMM(transA, transB, M, N, K) \
        blasfeo_dgemm(&(transA), &(transB), &(M), &(N), &(K), &scalar_alpha, A_base, &lda, B_base, &ldb, &scalar_beta, C_base, &ldc)

    #define RUN_SYRK(uplo, trans, M, K) \
        blasfeo_dsyrk(&(uplo), &(trans), &(M), &(K), &scalar_alpha, A_base, &lda, &scalar_beta, C_base, &ldc)

    #define RUN_TRMM(side, uplo, trans, diag, M, N) \
        blasfeo_dtrmm(&(side), &(uplo), &(trans), &(diag), &(M), &(N), &scalar_alpha, A_base, &lda, C_base, &ldc)

    #define RUN_TRSM(side, uplo, trans, diag, M, N) \
        blasfeo_dtrsm(&(side), &(uplo), &(trans), &(diag), &(M), &(N), &scalar_alpha, A_base, &lda, C_base, &ldc)

    #define RUN_GETRF(M, N) \
        blasfeo_dgetrf(&(M), &(N), B_base, &ldb, pivots, &info)

    #define RUN_GETRS(trans, M, N) \
        blasfeo_dgetrs(&(trans), &(M), &(N), B_base, &ldb, pivots, D_base, &ldd, &info)

    #define RUN_POTRF(uplo, M) \
        blasfeo_dpotrf(&(uplo), &(M), B_base, &ldb, &info)

    #define RUN_POTRS(uplo, M, N) \
        blasfeo_dpotrs(&(uplo), &(M), &(N), B_base, &ldb, D_base, &ldd, &info)

    // --- BLAS API calls using column-major layout ---
    int info = 0;

    // dgemm variants
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = n_dim = k_dim = size;
        RUN_GEMM(c_no_trans, c_no_trans, m_dim, n_dim, k_dim);
        RUN_GEMM(c_no_trans, c_trans, m_dim, n_dim, k_dim);
        RUN_GEMM(c_trans, c_no_trans, m_dim, n_dim, k_dim);
        RUN_GEMM(c_trans, c_trans, m_dim, n_dim, k_dim);
    }

    // dsyrk variants
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = n_dim = k_dim = size;
        RUN_SYRK(c_lower, c_no_trans, m_dim, k_dim);
        RUN_SYRK(c_lower, c_trans, m_dim, k_dim);
        RUN_SYRK(c_upper, c_no_trans, m_dim, k_dim);
        RUN_SYRK(c_upper, c_trans, m_dim, k_dim);
    }

    // dtrmm variants
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = n_dim = size;
        for (char side : {c_left, c_right}) {
            for (char uplo : {c_lower, c_upper}) {
                for (char trans : {c_no_trans, c_trans}) {
                    for (char diag : {c_no_trans, c_upper}) {
                        RUN_TRMM(side, uplo, trans, diag, m_dim, n_dim);
                    }
                }
            }
        }
    }

    // dtrsm variants
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = n_dim = size;
        for (char side : {c_left, c_right}) {
            for (char uplo : {c_lower, c_upper}) {
                for (char trans : {c_no_trans, c_trans}) {
                    for (char diag : {c_no_trans, c_upper}) {
                        RUN_TRSM(side, uplo, trans, diag, m_dim, n_dim);
                    }
                }
            }
        }
    }

    // dgetrf
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = n_dim = size;
        RUN_GETRF(m_dim, n_dim);
    }

    // dgetrs
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = n_dim = size;
        RUN_GETRS(c_no_trans, m_dim, n_dim);
        RUN_GETRS(c_trans, m_dim, n_dim);
    }

    // dpotrf
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = size;
        RUN_POTRF(c_lower, m_dim);
        RUN_POTRF(c_upper, m_dim);
    }

    // dpotrs
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = n_dim = size;
        RUN_POTRS(c_lower, m_dim, n_dim);
        RUN_POTRS(c_upper, m_dim, n_dim);
    }

    // --- Panel-major BLAS API calls ---
    #define RUN_PANEL_GEMM(func, M, N, K) \
        func(M, N, K, scalar_alpha, &sA_mat, 0, 0, &sB_mat, 0, 0, scalar_beta, &sC_mat, 0, 0, &sD_mat, 0, 0)

    // dgemm panel versions
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = n_dim = k_dim = size;
        RUN_PANEL_GEMM(blasfeo_dgemm_nn, m_dim, n_dim, k_dim);
        RUN_PANEL_GEMM(blasfeo_dgemm_nt, m_dim, n_dim, k_dim);
        RUN_PANEL_GEMM(blasfeo_dgemm_tn, m_dim, n_dim, k_dim);
        RUN_PANEL_GEMM(blasfeo_dgemm_tt, m_dim, n_dim, k_dim);
    }

    // dsyrk panel versions
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = n_dim = k_dim = size;
        RUN_PANEL_GEMM(blasfeo_dsyrk_ln, m_dim, k_dim, 0); // simplified signature
        RUN_PANEL_GEMM(blasfeo_dsyrk_ln_mn, m_dim, n_dim, k_dim);
        RUN_PANEL_GEMM(blasfeo_dsyrk_lt, m_dim, k_dim, 0);
        RUN_PANEL_GEMM(blasfeo_dsyrk_un, m_dim, k_dim, 0);
        RUN_PANEL_GEMM(blasfeo_dsyrk_ut, m_dim, k_dim, 0);
    }

    // dgetrf panel versions
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = n_dim = size;
        blasfeo_dgetrf_np(m_dim, n_dim, &sB_mat, 0, 0, &sD_mat, 0, 0);
        blasfeo_dgetrf_rp(m_dim, n_dim, &sB_mat, 0, 0, &sD_mat, 0, 0, pivots);
    }

    // dpotrf panel versions
    for (int size : {3, 6, 9, 12, 15, 18, 21, 24}) {
        m_dim = n_dim = size;
        blasfeo_dpotrf_l(m_dim, &sB_mat, 0, 0, &sD_mat, 0, 0);
        blasfeo_dpotrf_l_mn(m_dim, n_dim, &sB_mat, 0, 0, &sD_mat, 0, 0);
    }

    // Cleanup
    blasfeo_free_dmat(&sA_mat);
    blasfeo_free_dmat(&sB_mat);
    blasfeo_free_dmat(&sC_mat);
    blasfeo_free_dmat(&sD_mat);
    free(A_base);
    free(B_base);
    free(C_base);
    free(D_base);
    free(pivots);

    printf("\nsuccess!\n\n");
    return 0;
}

#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <queue>
#include <functional>
#include <chrono>
#include <memory>

// Simplified version of the retry mechanism with different implementation
class RetryHandler {
public:
    struct RetryTask {
        std::function<void()> task;
        std::chrono::steady_clock::time_point retry_time;
        size_t id;

        bool operator>(const RetryTask& other) const {
            if (retry_time != other.retry_time) {
                return retry_time > other.retry_time;
            }
            return id > other.id; // For stable ordering when times are equal
        }
    };

private:
    std::priority_queue<RetryTask, std::vector<RetryTask>, std::greater<RetryTask>> _tasks;
    mutable std::mutex _mutex;
    std::condition_variable _cv;
    std::thread _worker_thread;
    bool _stop{false};
    size_t _task_counter{0};

public:
    RetryHandler() {
        _worker_thread = std::thread(&RetryHandler::workerLoop, this);
    }

    ~RetryHandler() {
        stop();
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(_mutex);
            _stop = true;
        }
        _cv.notify_all();
        if (_worker_thread.joinable()) {
            _worker_thread.join();
        }
    }

    void schedule(std::function<void()> task, std::chrono::steady_clock::time_point time) {
        std::lock_guard<std::mutex> lock(_mutex);
        if (_stop) {
            return;
        }
        _tasks.push({std::move(task), time, _task_counter++});
        _cv.notify_one();
    }

    void cancelAll() {
        std::lock_guard<std::mutex> lock(_mutex);
        while (!_tasks.empty()) {
            _tasks.pop();
        }
    }

private:
    void workerLoop() {
        while (true) {
            std::unique_lock<std::mutex> lock(_mutex);

            if (_tasks.empty()) {
                if (_stop) break;
                _cv.wait(lock);
                if (_stop && _tasks.empty()) break;
                continue;
            }

            auto now = std::chrono::steady_clock::now();
            auto& top = _tasks.top();

            if (top.retry_time > now) {
                _cv.wait_until(lock, top.retry_time);
                if (_stop && _tasks.empty()) break;
                continue;
            }

            auto current_task = std::move(const_cast<RetryTask&>(top));
            _tasks.pop();
            lock.unlock();

            try {
                current_task.task();
            } catch (...) {
                // Ignore exceptions during task execution
            }
        }
    }
};

// Example usage demonstrating equivalent functionality
int main() {
    RetryHandler handler;

    // Schedule some test tasks
    auto now = std::chrono::steady_clock::now();

    handler.schedule([]() {
        std::cout << "Task 1 executed" << std::endl;
    }, now + std::chrono::seconds(1));

    handler.schedule([]() {
        std::cout << "Task 2 executed" << std::endl;
    }, now + std::chrono::seconds(2));

    handler.schedule([]() {
        std::cout << "Task 3 executed" << std::endl;
    }, now + std::chrono::seconds(3));

    // Wait for all tasks to complete
    std::this_thread::sleep_for(std::chrono::seconds(4));

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Helper function to terminate execution
void terminate_program() {
    exit(0);
}

// Print a string followed by newline and flush output
void print_and_flush(const string& message) {
    cout << message << '\n';
    cout.flush();
}

// Read an integer from input or terminate if reading fails or value is -1
int read_valid_integer() {
    int value;
    if (!(cin >> value)) {
        terminate_program();
    }
    if (value == -1) {
        terminate_program();
    }
    return value;
}

// Send command to block an edge
void disable_edge(int edge_id) {
    print_and_flush("- " + to_string(edge_id));
}

// Send command to unblock an edge
void enable_edge(int edge_id) {
    print_and_flush("+ " + to_string(edge_id));
}

// Perform a single-query reachability test from node y
int check_reachability_from(int start_node) {
    print_and_flush("? 1 " + to_string(start_node));
    return read_valid_integer();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (!(cin >> test_cases)) return 0;

    while (test_cases--) {
        int num_nodes, num_edges;
        cin >> num_nodes >> num_edges;

        vector<int> source(num_edges + 1), target(num_edges + 1);
        for (int i = 1; i <= num_edges; ++i) {
            cin >> source[i] >> target[i];
        }

        // Initially disable all edges
        for (int i = 1; i <= num_edges; ++i) {
            disable_edge(i);
        }

        vector<int> is_repaired(num_edges + 1, 0);

        // For each edge, temporarily restore it and test connectivity
        for (int i = 1; i <= num_edges; ++i) {
            enable_edge(i);

            // Reset starting point to source[i]
            (void)check_reachability_from(source[i]);

            // Check if target[i] is reachable from node 1 via current state
            int connected = check_reachability_from(target[i]);
            is_repaired[i] = (connected != 0) ? 1 : 0;

            // Re-disable the edge after testing
            disable_edge(i);
        }

        // Output final answer
        ostringstream result_stream;
        result_stream << "!";
        for (int i = 1; i <= num_edges; ++i) {
            result_stream << ' ' << is_repaired[i];
        }
        print_and_flush(result_stream.str());

        // Validate response
        int judge_response = read_valid_integer();
        if (judge_response != 1) {
            terminate_program();
        }
    }

    return 0;
}

#include "aeronet/safe-cast.hpp"
