namespace aeronet {

// Test: unsigned-to-unsigned conversion with valid and out-of-range values
TEST(SafeCastTest, UnsignedToUnsigned) {
  EXPECT_EQ(SafeCast<std::uint32_t>(123), 123U);
  EXPECT_EQ(SafeCast<std::uint64_t>(123), 123ULL);

  // Attempt to cast a value just beyond uint32 max → should throw
  const std::uint64_t overflow_val = static_cast<std::uint64_t>(std::numeric_limits<std::uint32_t>::max()) + 1ULL;
  EXPECT_THROW(SafeCast<std::uint32_t>(overflow_val), std::overflow_error);
}

// Test: signed-to-unsigned — positive fits, negative throws
TEST(SafeCastTest, SignedToUnsigned) {
  EXPECT_EQ(SafeCast<std::uint32_t>(123), 123U);
  EXPECT_THROW(SafeCast<std::uint32_t>(-1), std::overflow_error);
}

// Test: shrinking signed-to-signed — positive overflow detection
TEST(SafeCastTest, SignedToSigned_ShrinkPositiveOverflow) {
  const std::int16_t src = static_cast<std::int16_t>(std::numeric_limits<std::int8_t>::max()) + 1;
  EXPECT_THROW(SafeCast<std::int8_t>(src), std::overflow_error);
}

// Test: shrinking signed-to-signed — negative values rejected (implementation detail)
TEST(SafeCastTest, SignedToSigned_NegativeValuesWhenShrinking) {
  // Casting -1 from int16 to int8 should fail due to internal unsigned comparison
  EXPECT_THROW(SafeCast<std::int8_t>(static_cast<std::int16_t>(-1)), std::overflow_error);

  // Same-size cast allows negatives that fit
  EXPECT_EQ(SafeCast<std::int32_t>(-12345), static_cast<std::int32_t>(-12345));
}

// Test: unsigned-to-signed — small fits, large overflows
TEST(SafeCastTest, UnsignedToSigned) {
  EXPECT_EQ(SafeCast<std::int32_t>(123U), 123);
  const std::uint64_t big_val = static_cast<std::uint64_t>(std::numeric_limits<std::int32_t>::max()) + 1ULL;
  EXPECT_THROW(SafeCast<std::int32_t>(big_val), std::overflow_error);
}

// Test: constexpr usage and boundary conditions
TEST(SafeCastTest, ConstexprAndEdgeCases) {
  static_assert(SafeCast<int>(42) == 42);

  // Max uint32 fits in uint64
  EXPECT_EQ(SafeCast<std::uint64_t>(std::numeric_limits<std::uint32_t>::max()),
            static_cast<std::uint64_t>(std::numeric_limits<std::uint32_t>::max()));

  // One past max uint32 overflows when casting down
  const std::uint64_t limit_plus_one = static_cast<std::uint64_t>(std::numeric_limits<std::uint32_t>::max()) + 1ULL;
  EXPECT_THROW(SafeCast<std::uint32_t>(limit_plus_one), std::overflow_error);
}

// Random number generator setup
namespace {
std::mt19937_64 prng{666UL};
std::uniform_int_distribution<int64_t> sdist(std::numeric_limits<int64_t>::min(),
                                             std::numeric_limits<int64_t>::max());
std::uniform_int_distribution<uint64_t> udist(std::numeric_limits<uint64_t>::min(),
                                              std::numeric_limits<uint64_t>::max());
}  // namespace

// Randomized tests for unsigned-to-unsigned
TEST(SafeCastTest, RandomizedUnsignedToUnsigned) {
  for (int idx = 0; idx < 1000; ++idx) {
    const uint64_t input = udist(prng);
    if (input <= std::numeric_limits<uint32_t>::max()) {
      EXPECT_EQ(SafeCast<uint32_t>(input), static_cast<uint32_t>(input));
    } else {
      EXPECT_THROW(SafeCast<uint32_t>(input), std::overflow_error);
    }
  }
}

// Randomized tests for signed-to-unsigned
TEST(SafeCastTest, RandomizedSignedToUnsigned) {
  for (int idx = 0; idx < 1000; ++idx) {
    const int64_t val = sdist(prng);
    if (val >= 0 && static_cast<uint64_t>(val) <= std::numeric_limits<uint32_t>::max()) {
      EXPECT_EQ(SafeCast<uint32_t>(val), static_cast<uint32_t>(val));
    } else {
      EXPECT_THROW(SafeCast<uint32_t>(val), std::overflow_error);
    }
  }
}

