// Default constructor and destructor
HamSupereasyData::HamSupereasyData() {}
HamSupereasyData::~HamSupereasyData() {}

// Handler table definition: inherits from Hmx::Object
BEGIN_HANDLERS(HamSupereasyData)
    HANDLE_SUPERCLASS(Hmx::Object)
END_HANDLERS

// Custom property synchronization for HamSupereasyMeasure (note: class name mismatch in input is preserved as-is)
BEGIN_CUSTOM_PROPSYNC(HamSupereasyMeasure)
    SYNC_PROP(first, o.first)
    SYNC_PROP(second, o.second)
    SYNC_PROP(preferred, o.preferred)
END_CUSTOM_PROPSYNC

// Standard property synchronization for HamSupereasyData
BEGIN_PROPSYNCS(HamSupereasyData)
    SYNC_PROP(routine, mRoutine)
    SYNC_SUPERCLASS(Hmx::Object)
END_PROPSYNCS

// Serialization logic: saves object state
BEGIN_SAVES(HamSupereasyData)
    SAVE_REVS(0, 1)
    SAVE_SUPERCLASS(Hmx::Object)

    // Write number of measures first
    size_t count = mRoutine.size();
    bs << count;

    // Serialize each measure
    for (auto&& measure : mRoutine) {
        bs << measure.first;
        bs << measure.second;
        bs << measure.preferred;
    }
END_SAVES

// Copy logic: deep copy support
BEGIN_COPYS(HamSupereasyData)
    COPY_SUPERCLASS(Hmx::Object)
    CREATE_COPY(HamSupereasyData)
    BEGIN_COPYING_MEMBERS
        COPY_MEMBER(mRoutine)
    END_COPYING_MEMBERS
END_COPYS

// Revision initialization
INIT_REVS(0, 1)

// Deserialization logic: loads object state
BEGIN_LOADS(HamSupereasyData)
    LOAD_REVS(bs)
    ASSERT_REVS(0, 1)
    LOAD_SUPERCLASS(Hmx::Object)

    // Read number of measures
    int32_t numMeasures;
    d >> numMeasures;

    // Resize vector and load each measure
    mRoutine.resize(static_cast<size_t>(numMeasures));
    for (auto& measure : mRoutine) {
        d >> measure.first;
        d >> measure.second;
        if (d.altRev > 0) {
            d >> measure.preferred;
        }
    }
END_LOADS

