using namespace std;

vector<vector<int>> generate_matrix(int N, int M, vector<int> A, vector<int> B) {
    int dimension = max(1, N);
    dimension = min(dimension, 240);

    vector<vector<int>> matrix(dimension, vector<int>(dimension, 1));

    int idx = 0;
    while (idx < dimension && idx < N) {
        matrix[idx][idx] = idx + 1;
        idx++;
    }

    return matrix;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (!(cin >> test_cases)) return 0;

    while (test_cases--) {
        int N, M;
        cin >> N >> M;

        vector<int> A(M), B(M);
        for (int i = 0; i < M; ++i) {
            cin >> A[i] >> B[i];
        }

        auto result = generate_matrix(N, M, A, B);
        int size = (int)result.size();

        cout << size << "\n";
