static volatile int Sink;

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {
    // Initialize array to track first occurrence positions of each byte value
    int8_t FirstPos[256];
    std::memset(FirstPos, -1, sizeof(FirstPos));

    // Record the first occurrence index for each byte in the input data
    for (size_t idx = 0; idx < Size; ++idx) {
        unsigned char currentByte = Data[idx];
        if (FirstPos[currentByte] == -1) {
            FirstPos[currentByte] = static_cast<int8_t>(idx);
        }
    }

    // Retrieve first occurrence positions of 'F', 'U', and 'Z'
    int posF = FirstPos[static_cast<unsigned char>('F')];
    int posU = FirstPos[static_cast<unsigned char>('U')];
    int posZ = FirstPos[static_cast<unsigned char>('Z')];

    // Check if all three characters appear in order: F before U before Z
    if (posF >= 0 && posU > posF && posZ > posU) {
        Sink++;
    }

    return 0;
}

