#include <iostream>
#include <vector>
using namespace std;

// Global variables for tree representation and HLD preprocessing
int n;
vector<vector<int>> graph;
vector<int> subtreeSize;
vector<int> parentNode;
vector<int> heavyChild;

// First DFS: compute subtree sizes and identify heavy children
void preprocess(int u, int p) {
    subtreeSize[u] = 1;
    parentNode[u] = p;
    int largestSubtree = -1;
    heavyChild[u] = -1;

    for (int v : graph[u]) {
        if (v != p) {
            preprocess(v, u);
            subtreeSize[u] += subtreeSize[v];
            if (subtreeSize[v] > largestSubtree) {
                largestSubtree = subtreeSize[v];
                heavyChild[u] = v;
            }
        }
    }
}

// Helper to send query and get response
int ask(int node) {
    cout << "? " << node << endl;
    int result;
    cin >> result;
    if (result == -1) exit(0); // Handle invalid response
    return result;
}

void processTestcase() {
    if (!(cin >> n)) return;

    // Initialize data structures
    graph.assign(n + 1, vector<int>());
    subtreeSize.assign(n + 1, 0);
    parentNode.assign(n + 1, 0);
    heavyChild.assign(n + 1, -1);

    // Read edges
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    // Preprocess heavy-light decomposition info
    preprocess(1, 0);

    int current = 1;

    while (true) {
        // Build heavy path starting from 'current'
        vector<int> path;
        int node = current;
        while (node != -1) {
            path.push_back(node);
            node = heavyChild[node];
        }

        // If only one node in path, we've narrowed it down to 'current'
        if (path.size() == 1) {
            cout << "! " << current << endl;
            return;
        }

        // Binary search on the heavy path (excluding first element)
        int left = 1;
        int right = path.size() - 1;
        int missedCount = 0;
        bool foundDeeper = false;

        while (left <= right) {
            int mid = (left + right + 1) / 2; // Upper mid for bias toward deeper nodes
            int res = ask(path[mid]);

            if (res == 1) {
                current = path[mid];
                foundDeeper = true;
                break;
            } else {
                right = mid - 1;
                missedCount++;
            }
        }

        if (!foundDeeper) {
            // Mole moved up for each failed query — backtrack accordingly
            int originalCurrent = current;
            for (int step = 0; step < missedCount; ++step) {
                if (current != 1) {
                    current = parentNode[current];
                }
            }

            // Special case: if still at root after backtracking and originally at root,
            // mole must be at root
            if (current == 1 && originalCurrent == 1) {
                cout << "! " << 1 << endl;
                return;
            }
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            processTestcase();
        }
    }

    return 0;
}

