}

LiquidCrystal::LiquidCrystal(uint8_t rs, uint8_t enable,
                             uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3,
                             uint8_t d4, uint8_t d5, uint8_t d6, uint8_t d7)
{
  init(0, rs, 255U, enable, d0, d1, d2, d3, d4, d5, d6, d7);
}

LiquidCrystal::LiquidCrystal(uint8_t rs, uint8_t rw, uint8_t enable,
                             uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3)
{
  init(1, rs, rw, enable, d0, d1, d2, d3, 0U, 0U, 0U, 0U);
}

LiquidCrystal::LiquidCrystal(uint8_t rs, uint8_t enable,
                             uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3)
{
  init(1, rs, 255U, enable, d0, d1, d2, d3, 0U, 0U, 0U, 0U);
}

void LiquidCrystal::init(uint8_t fourbitmode, uint8_t rs, uint8_t rw, uint8_t enable,
                         uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3,
                         uint8_t d4, uint8_t d5, uint8_t d6, uint8_t d7)
{
  _pin_rs = rs;
  _pin_rw = rw;
  _pin_enable = enable;

  // Initialize data pins array manually instead of loop
  _data_pins[0] = d0;
  _data_pins[1] = d1;
  _data_pins[2] = d2;
  _data_pins[3] = d3;
  if (!fourbitmode) {
    _data_pins[4] = d4;
    _data_pins[5] = d5;
    _data_pins[6] = d6;
    _data_pins[7] = d7;
  }

  if (fourbitmode) {
    _displayfunction = LCD_4BITMODE | LCD_1LINE | LCD_5x8DOTS;
  } else {
    _displayfunction = LCD_8BITMODE | LCD_1LINE | LCD_5x8DOTS;
  }

  begin(16, 1);
}

void LiquidCrystal::begin(uint8_t cols, uint8_t lines, uint8_t dotsize) {
  if (lines > 1U) {
    _displayfunction |= LCD_2LINE;
  }
  _numlines = lines;

  setRowOffsets(0x00, 0x40, 0x00 + cols, 0x40 + cols);

  if ((dotsize != LCD_5x8DOTS) && (lines == 1U)) {
    _displayfunction |= LCD_5x10DOTS;
  }

  pinMode(_pin_rs, OUTPUT);

  if (_pin_rw != 255U) {
    pinMode(_pin_rw, OUTPUT);
  }

  pinMode(_pin_enable, OUTPUT);

  // Set data pin directions — use while loop instead of for
  uint8_t numDataPins = (_displayfunction & LCD_8BITMODE) ? 8U : 4U;
  uint8_t idx = 0U;
  while (idx < numDataPins) {
    pinMode(_data_pins[idx], OUTPUT);
    ++idx;
  }

  // Wait for LCD power-up stabilization
  delayMicroseconds(50000); // 50 ms

  // Bring RS and RW low before sending commands
  digitalWrite(_pin_rs, LOW);
  digitalWrite(_pin_enable, LOW);
  if (_pin_rw != 255U) {
    digitalWrite(_pin_rw, LOW);
  }

  // Initialize display mode: 4-bit or 8-bit
  if (!(_displayfunction & LCD_8BITMODE)) {
    // Hitachi HD44780: 4-bit init sequence (Fig. 24)
    write4bits(0x03);
    delayMicroseconds(4500); // ≥4.1ms
    write4bits(0x03);
    delayMicroseconds(4500); // ≥4.1ms
    write4bits(0x03);
    delayMicroseconds(150);
    // Switch to 4-bit mode
    write4bits(0x02);
  } else {
    // Hitachi HD44780: 8-bit init sequence (Fig. 23)
    command(LCD_FUNCTIONSET | _displayfunction);
    delayMicroseconds(4500); // ≥4.1ms
    command(LCD_FUNCTIONSET | _displayfunction);
    delayMicroseconds(150);
    command(LCD_FUNCTIONSET | _displayfunction);
  }

  // Final function set
  command(LCD_FUNCTIONSET | _displayfunction);

  // Default display control: ON, no cursor, no blink
  _displaycontrol = LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF;
  display();

  // Clear display
  clear();

  // Entry mode: left-to-right, no shift
  _displaymode = LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::setRowOffsets(int row0, int row1, int row2, int row3) {
  _row_offsets[0] = row0;
  _row_offsets[1] = row1;
  _row_offsets[2] = row2;
  _row_offsets[3] = row3;
}

void LiquidCrystal::clear() {
  command(LCD_CLEARDISPLAY);
  delayMicroseconds(2000); // ≥1.52ms per spec
}

void LiquidCrystal::home() {
  command(LCD_RETURNHOME);
  delayMicroseconds(2000); // ≥1.52ms
}

void LiquidCrystal::setCursor(uint8_t col, uint8_t row) {
  const uint8_t maxLines = sizeof(_row_offsets) / sizeof(_row_offsets[0]);
  if (row >= maxLines) {
    row = maxLines - 1U;
  }
  if (row >= _numlines) {
    row = _numlines - 1U;
  }
  command(LCD_SETDDRAMADDR | (col + _row_offsets[row]));
}

void LiquidCrystal::noDisplay() {
  _displaycontrol &= ~LCD_DISPLAYON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::display() {
  _displaycontrol |= LCD_DISPLAYON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::noCursor() {
  _displaycontrol &= ~LCD_CURSORON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::cursor() {
  _displaycontrol |= LCD_CURSORON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::noBlink() {
  _displaycontrol &= ~LCD_BLINKON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::blink() {
  _displaycontrol |= LCD_BLINKON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::scrollDisplayLeft() {
  command(LCD_CURSORSHIFT | LCD_DISPLAYMOVE | LCD_MOVELEFT);
}

void LiquidCrystal::scrollDisplayRight() {
  command(LCD_CURSORSHIFT | LCD_DISPLAYMOVE | LCD_MOVERIGHT);
}

void LiquidCrystal::leftToRight() {
  _displaymode |= LCD_ENTRYLEFT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::rightToLeft() {
  _displaymode &= ~LCD_ENTRYLEFT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::autoscroll() {
  _displaymode |= LCD_ENTRYSHIFTINCREMENT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::noAutoscroll() {
  _displaymode &= ~LCD_ENTRYSHIFTINCREMENT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::createChar(uint8_t location, uint8_t charmap[]) {
  location &= 0x07; // only 8 CGRAM slots (0–7)
  command(LCD_SETCGRAMADDR | (location << 3));
  uint8_t i = 0;
  while (i < 8) {
    write(charmap[i]);
    ++i;
  }
}

inline void LiquidCrystal::command(uint8_t value) {
  send(value, LOW);
}

inline size_t LiquidCrystal::write(uint8_t value) {
  send(value, HIGH);
  return 1;
}

void LiquidCrystal::send(uint8_t value, uint8_t mode) {
  digitalWrite(_pin_rs, mode);

  if (_pin_rw != 255U) {
    digitalWrite(_pin_rw, LOW);
  }

  if (_displayfunction & LCD_8BITMODE) {
    write8bits(value);
  } else {
    write4bits(value >> 4);
    write4bits(value);
  }
}

void LiquidCrystal::pulseEnable() {
  digitalWrite(_pin_enable, LOW);
  delayMicroseconds(1);
  digitalWrite(_pin_enable, HIGH);
  delayMicroseconds(1); // pulse width >450ns
  digitalWrite(_pin_enable, LOW);
  delayMicroseconds(100); // settle time >37µs
}

void LiquidCrystal::write4bits(uint8_t value) {
  // Manual bit assignment instead of loop
  digitalWrite(_data_pins[0], (value >> 0) & 0x01);
  digitalWrite(_data_pins[1], (value >> 1) & 0x01);
  digitalWrite(_data_pins[2], (value >> 2) & 0x01);
  digitalWrite(_data_pins[3], (value >> 3) & 0x01);
  pulseEnable();
}

void LiquidCrystal::write8bits(uint8_t value) {
  // Manual bit assignment for 8-bit mode
  digitalWrite(_data_pins[0], (value >> 0) & 0x01);
  digitalWrite(_data_pins[1], (value >> 1) & 0x01);
  digitalWrite(_data_pins[2], (value >> 2) & 0x01);
  digitalWrite(_data_pins[3], (value >> 3) & 0x01);
  digitalWrite(_data_pins[4], (value >> 4) & 0x01);
  digitalWrite(_data_pins[5], (value >> 5) & 0x01);
  digitalWrite(_data_pins[6], (value >> 6) & 0x01);
  digitalWrite(_data_pins[7], (value >> 7) & 0x01);
  pulseEnable();
}

