// 1. What is this called?
//    This is a function that uses pass-by-reference parameter.
// 2. Why do we use it?
//    We use it to allow the function to modify the original variable passed in,
//    avoiding copying and enabling direct modification of the caller's variable.
// 3. What is an alternative option?
//    An alternative is pass-by-pointer (e.g., int* s) or returning a new value
//    without modifying the original (pass-by-value).

int updateScore(int & s);

int main() {
    int userScore = 10;
    // 4. What is happening in this line?
    //    The function updateScore is called with userScore passed by reference,
    //    so any changes to 's' inside the function will affect 'userScore'.
    // 5. 'userScore' is referred to as what?
    //    It's the argument (or actual parameter).
    int result = updateScore(userScore);
    cout << "Result: " << result << endl;
    cout << "Final User Score: " << userScore << endl;
    return 0;
}

// 6. 's' is referred to as what?
//    It's the formal parameter (specifically, a reference parameter).
int updateScore(int & s) {
    // 7. Implement post increment on the variable s and assign it to the output
    int output = s++;  // Post-increment: assign current value, then increment s

    // 8. Implement pre increment on the variable s
    ++s;               // Pre-increment: increment s first, then use its new value

    return output;
}

