} // namespace mlir

using namespace mlir;
using namespace mlir::hacc;

// A pass that renames functions annotated with hacc::RenameFuncAttr
struct FunctionRenamer : public impl::HACCRenameFunctionBase<FunctionRenamer> {
public:
  void runOnOperation() override;
};

void FunctionRenamer::runOnOperation() {
  auto mod = getOperation();

  // Traverse all function operations in the module
  mod.walk([&](func::FuncOp func) {
    // Check for the presence of the rename attribute
    auto attr = func->getAttrOfType<hacc::RenameFuncAttr>(hacc::RenameFuncAttr::name);
    if (!attr)
      return;

    // Extract the proposed new name
    auto targetName = attr.getTargetName();
    if (targetName.name.empty()) {
      func.emitError("empty target function name provided");
      signalPassFailure();
      return;
    }

    // Ensure no symbol conflict exists at the target name
    auto conflictingSymbol = SymbolTable::lookupNearestSymbolFrom(func, targetName);
    if (conflictingSymbol) {
      func.emitError()
          << "cannot rename to @" << targetName.getValue()
          << ": a symbol with this name already exists";
      signalPassFailure();
      return;
    }

    // Replace all references to the old symbol name with the new one
    auto oldSym = func.getSymNameAttr();
    if (failed(SymbolTable::replaceAllSymbolUses(oldSym, targetName.getAttr(), mod))) {
      func.emitError("failed to update all symbol references during rename");
      signalPassFailure();
      return;
    }

    // Apply the new name and clean up the attribute
    func.setSymName(targetName.getAttr());
    func->removeAttr(hacc::RenameFuncAttr::name);
  });
}

std::unique_ptr<Pass> mlir::hacc::createRenameFuncPass() {
  return std::make_unique<FunctionRenamer>();
}

