#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        int n = nums.size();
        int pivot = -1;

        // Step 1: Locate the rightmost position where nums[i] < nums[i+1]
        for (int idx = n - 2; idx >= 0; --idx) {
            if (nums[idx] < nums[idx + 1]) {
                pivot = idx;
                break;
            }
        }

        // If no pivot found, array is in descending order
        if (pivot == -1) {
            reverse(nums.begin(), nums.end());
        } else {
            // Step 2: Find the smallest element to the right of pivot that is larger than nums[pivot]
            for (int j = n - 1; j > pivot; --j) {
                if (nums[j] > nums[pivot]) {
                    swap(nums[j], nums[pivot]);
                    break;
                }
            }

            // Step 3: Reverse the suffix starting after the pivot
            reverse(nums.begin() + pivot + 1, nums.end());
        }
    }
};

