// Test that negative or zero parameter values are safely clamped to valid ranges
TEST_CASE(test_negative_parameter_safety, "Stability") {
    std::cout << "\nTest: Negative Parameter Safety (v0.7.16)" << std::endl;
    FFBEngine engineInstance;
    Preset customPreset("KillerPreset", false);

    // Assign invalid (negative/zero) values to simulate edge cases
    customPreset.lockup_gamma = -1.0f;
    customPreset.notch_q = -5.0f;
    customPreset.wheelbase_max_nm = -100.0f;
    customPreset.optimal_slip_angle = -0.1f;
    customPreset.optimal_slip_ratio = 0.0f;
    customPreset.slope_alpha_threshold = -0.01f;
    customPreset.slope_decay_rate = -5.0f;
    customPreset.slope_smoothing_tau = -0.04f;
    customPreset.gain = -1.0f;

    // Apply preset — internal logic must clamp all values
    customPreset.Apply(engineInstance);

    // Validate clamped minimums
    EXPECT_TRUE(engineInstance.m_lockup_gamma >= 0.1f);
    EXPECT_TRUE(engineInstance.m_notch_q >= 0.1f);
    EXPECT_TRUE(engineInstance.m_wheelbase_max_nm >= 1.0f);
    EXPECT_TRUE(engineInstance.m_optimal_slip_angle >= 0.01f);
    EXPECT_TRUE(engineInstance.m_optimal_slip_ratio >= 0.01f);
    EXPECT_TRUE(engineInstance.m_slope_alpha_threshold >= 0.001f);
    EXPECT_TRUE(engineInstance.m_slope_decay_rate >= 0.1f);
    EXPECT_TRUE(engineInstance.m_slope_smoothing_tau >= 0.001f);
    EXPECT_TRUE(engineInstance.m_gain >= 0.0f);

    // Simulate one frame of processing to ensure no crash or NaN output
    TelemInfoV01 telemetryData = CreateBasicTestTelemetry(20.0, 0.05);
    double computedForce = engineInstance.calculate_force(&telemetryData);
    EXPECT_FALSE(std::isnan(computedForce));
    EXPECT_FALSE(std::isinf(computedForce));
}

