    while (idx < iterationCount) {
        double currentForce = engineInstance.calculate_force(&telemetryData);
        EXPECT_FALSE(std::isnan(currentForce));
        EXPECT_NEAR(currentForce, initialForce, 0.0001);
        ++idx;
