// Rule characters requiring escaping in regex patterns
static constexpr char16_t const gRuleSet_rule_chars[] = u"*?+[(){}^$|\\.";

// Supported backslash escape sequences for ICU unescaping
static constexpr char16_t const gUnescapeChars[] = u"acefnrtuUx";

// Unicode patterns for common regex character classes
static constexpr char16_t const gIsWordPattern[] = u"[\\p{Alphabetic}\\p{M}\\p{Nd}\\p{Pc}\\u200c\\u200d]";
static constexpr char16_t const gIsSpacePattern[] = u"[\\p{WhiteSpace}]";

// Grapheme cluster-related Unicode sets
static constexpr char16_t const gGC_ControlPattern[] = u"[[:Zl:][:Zp:][:Cc:][:Cf:]-[:Grapheme_Extend:]]";
static constexpr char16_t const gGC_ExtendPattern[]  = u"[\\p{Grapheme_Extend}]";
static constexpr char16_t const gGC_LPattern[]       = u"[\\p{Hangul_Syllable_Type=L}]";
static constexpr char16_t const gGC_VPattern[]       = u"[\\p{Hangul_Syllable_Type=V}]";
static constexpr char16_t const gGC_TPattern[]       = u"[\\p{Hangul_Syllable_Type=T}]";
static constexpr char16_t const gGC_LVPattern[]      = u"[\\p{Hangul_Syllable_Type=LV}]";
static constexpr char16_t const gGC_LVTPattern[]     = u"[\\p{Hangul_Syllable_Type=LVT}]";

// Static instance and initialization guard
RegexStaticSets* RegexStaticSets::gStaticSets = nullptr;
UInitOnce gStaticSetsInitOnce{};

// Helper to build and freeze a UnicodeSet from a literal pattern
static inline void initUnicodeSet(UnicodeSet& set, const char16_t* pattern, UErrorCode& err) {
    set.applyPattern(UnicodeString(true, pattern, -1), err).freeze();
}

// Helper to initialize 8-bit fast bit sets
static void initFastBitSets(RegexStaticSets* sets, UErrorCode& err) {
    if (U_FAILURE(err)) return;
    for (int32_t idx = 0; idx < URX_LAST_SET; ++idx) {
        sets->fPropSets8[idx].init(&sets->fPropSets[idx]);
    }
}

// Initialize rule-specific sets used during pattern parsing
static void initRuleSets(RegexStaticSets* sets, UErrorCode& err) {
    if (U_FAILURE(err)) return;

    // Build complemented rule character set
    sets->fRuleSets[kRuleSet_rule_char - 128]
        .addAll(UnicodeString(true, gRuleSet_rule_chars, -1))
        .complement()
        .freeze();

    // Digit set: '0'–'9'
    sets->fRuleSets[kRuleSet_digit_char - 128].add(u'0', u'9').freeze();

    // ASCII letters: A–Z, a–z
    sets->fRuleSets[kRuleSet_ascii_letter - 128]
        .add(u'A', u'Z')
        .add(u'a', u'z')
        .freeze();

    // Alias for digit set
    sets->fRuleDigitsAlias = &sets->fRuleSets[kRuleSet_digit_char - 128];
}

// Initialize grapheme cluster normal set
static void initGraphemeNormalSet(RegexStaticSets* sets, UErrorCode& err) {
    if (U_FAILURE(err)) return;

    // Start with full complement, then subtract special cases
    sets->fPropSets[URX_GC_NORMAL].complement();
    sets->fPropSets[URX_GC_NORMAL].remove(0xac00, 0xd7a4);
    sets->fPropSets[URX_GC_NORMAL].removeAll(sets->fPropSets[URX_GC_CONTROL]);
    sets->fPropSets[URX_GC_NORMAL].removeAll(sets->fPropSets[URX_GC_L]);
    sets->fPropSets[URX_GC_NORMAL].removeAll(sets->fPropSets[URX_GC_V]);
    sets->fPropSets[URX_GC_NORMAL].removeAll(sets->fPropSets[URX_GC_T]);
    sets->fPropSets[URX_GC_NORMAL].freeze();
}

// Main constructor implementation — refactored into modular steps
RegexStaticSets::RegexStaticSets(UErrorCode* status) {
    UErrorCode localErr = U_ZERO_ERROR;

    // Initialize core UnicodeSets using patterns
    initUnicodeSet(fUnescapeCharSet, gUnescapeChars, localErr);
    initUnicodeSet(fPropSets[URX_ISWORD_SET], gIsWordPattern, localErr);
    initUnicodeSet(fPropSets[URX_ISSPACE_SET], gIsSpacePattern, localErr);
    initUnicodeSet(fPropSets[URX_GC_EXTEND], gGC_ExtendPattern, localErr);
    initUnicodeSet(fPropSets[URX_GC_CONTROL], gGC_ControlPattern, localErr);
    initUnicodeSet(fPropSets[URX_GC_L], gGC_LPattern, localErr);
    initUnicodeSet(fPropSets[URX_GC_V], gGC_VPattern, localErr);
    initUnicodeSet(fPropSets[URX_GC_T], gGC_TPattern, localErr);
    initUnicodeSet(fPropSets[URX_GC_LV], gGC_LVPattern, localErr);
    initUnicodeSet(fPropSets[URX_GC_LVT], gGC_LVTPattern, localErr);

    // Initialize grapheme cluster normal set
    initGraphemeNormalSet(this, localErr);

    // Initialize 8-bit fast bit sets
    initFastBitSets(this, localErr);

    // Initialize rule-specific sets
    initRuleSets(this, localErr);

    // Create empty UText for utility
    fEmptyText = utext_openUChars(nullptr, nullptr, 0, &localErr);

    // Propagate error if any occurred
    if (U_FAILURE(localErr)) {
        *status = localErr;
    } else {
        *status = U_ZERO_ERROR;
    }
}

RegexStaticSets::~RegexStaticSets() {
    fRuleDigitsAlias = nullptr;
    utext_close(fEmptyText);
}

//------------------------------------------------------------------------------
// Cleanup support for static resources
//------------------------------------------------------------------------------

U_CDECL_BEGIN

static UBool U_CALLCONV regex_cleanup() {
    delete RegexStaticSets::gStaticSets;
    RegexStaticSets::gStaticSets = nullptr;
    gStaticSetsInitOnce.reset();
    return true;
}

static void U_CALLCONV ensureStaticSets(UErrorCode& err) {
    if (U_FAILURE(err)) return;

    U_ASSERT(RegexStaticSets::gStaticSets == nullptr);
    ucln_i18n_registerCleanup(UCLN_I18N_REGEX, regex_cleanup);

    std::unique_ptr<RegexStaticSets> temp(new RegexStaticSets(&err));
    if (U_FAILURE(err)) {
        return;
    }

    // Assign only if allocation succeeded
    if (temp) {
        RegexStaticSets::gStaticSets = temp.release();
    } else {
        err = U_MEMORY_ALLOCATION_ERROR;
    }
}

U_CDECL_END

void RegexStaticSets::initGlobals(UErrorCode* status) {
    umtx_initOnce(gStaticSetsInitOnce, &ensureStaticSets, *status);
}

