// Base class with virtual destructor and functions
struct A {
public:
  virtual ~A() = default;
  void func() {}
  virtual void Vfunc() {}
};

// Derived class overriding base functions
struct B : public A {
public:
  void func() {}
  void Vfunc() override {}
};

int main() {
  // Create instance using base pointer to derived object
  A* ptr = new B;

  // Call non-virtual function (static binding)
  ptr->func();

  // Call virtual function (dynamic binding)
  ptr->Vfunc();

  // Clean up allocated memory
  delete ptr;

  return 0;
}

