static FLOAT dp1 = 1.0;

blasint CNAME(blas_arg_t *args, BLASLONG *range_m, BLASLONG *range_n, FLOAT *sa, FLOAT *sb, BLASLONG myid) {
    BLASLONG n, lda;
    FLOAT *a;
    FLOAT temp_val[2];
    BLASLONG idx;

    n      = args->n;
    a      = (FLOAT *)args->a;
    lda    = args->lda;

    if (range_n != NULL) {
        n      = range_n[1] - range_n[0];
        a     += range_n[0] * (lda + 1) * COMPSIZE;
    }

    for (idx = 0; idx < n; idx++) {
        SCAL_K(idx + 1, 0, 0,
               *(a + (idx + idx * lda) * COMPSIZE + 0), ZERO,
               a + idx * lda * COMPSIZE, 1, NULL, 0, NULL, 0);

        if (idx < n - 1) {
            temp_val[0] = DOTC_K(n - idx - 1, 
                                 a + (idx + (idx + 1) * lda) * COMPSIZE, lda,
                                 a + (idx + (idx + 1) * lda) * COMPSIZE, lda);
            GET_IMAGE(temp_val[1]);

            *(a + (idx + idx * lda) * COMPSIZE + 0) += temp_val[0];
            *(a + (idx + idx * lda) * COMPSIZE + 1)  = ZERO;

            GEMV_O(idx, n - idx - 1, 0, dp1, ZERO,
                   a + ((idx + 1) * lda) * COMPSIZE, lda,
                   a + (idx + (idx + 1) * lda) * COMPSIZE, lda,
                   a + (idx * lda) * COMPSIZE, 1, sb);
        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <chrono>
using namespace std;

int main() {
    // Optimize I/O operations for speed
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    // Build adjacency list (1-indexed)
    vector<vector<int>> graph(n + 1);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    // Best partition found: 0 or 1 for each vertex
    vector<int> best_partition(n + 1, 0);
    long long best_cut_value = -1;

    // Time management: use 0.9s as safe limit
    const double TIME_LIMIT = 0.90;
    auto start = chrono::high_resolution_clock::now();

    // Random number generator
    mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

    // Vertex ordering for random traversal
    vector<int> order(n);
    for (int i = 0; i < n; ++i) order[i] = i + 1;

    // Local search with multiple restarts
    while (true) {
        // Check time constraint
        auto now = chrono::high_resolution_clock::now();
        double elapsed = chrono::duration<double>(now - start).count();
        if (elapsed >= TIME_LIMIT) break;

        // Random initial assignment
        vector<int> current(n + 1);
        for (int i = 1; i <= n; ++i) {
            current[i] = rng() % 2;
        }

        // Refine using greedy local search
        bool changed = true;
        while (changed) {
            changed = false;
            shuffle(order.begin(), order.end(), rng);

            for (int node : order) {
                int same = 0, diff = 0;
                for (int neighbor : graph[node]) {
                    if (current[neighbor] == current[node]) {
                        same++;
                    } else {
                        diff++;
                    }
                }

                // Flip if it improves the cut
                if (same > diff) {
                    current[node] ^= 1;
                    changed = true;
                }
            }
        }

        // Compute cut size
        long long cut_size = 0;
        for (int u = 1; u <= n; ++u) {
            if (current[u] == 0) {
                for (int v : graph[u]) {
                    if (current[v] == 1) {
                        cut_size++;
                    }
                }
            }
        }

        // Update best solution
        if (cut_size > best_cut_value) {
            best_cut_value = cut_size;
            best_partition = current;
        }
    }

    // Output final partition
    for (int i = 1; i <= n; ++i) {
        cout << best_partition[i];
        if (i < n) cout << ' ';
    }
    cout << '\n';

    return 0;
}

class Solution {
public:
    bool doesAliceWin(string s) {
        int index = 0;
        while (index < s.length()) {
            char currentChar = s[index];
            if (currentChar == 'a' || currentChar == 'e' || currentChar == 'i' || 
                currentChar == 'o' || currentChar == 'u') {
                return true;
            }
            index++;
        }
        return false;
    }
};

