// Helper function to safely compute step parameters for gap closing
struct GapClosingParams {
    double StepSize;
    double Remainder;
    double VoxelSize;
    int32 Steps;
};

static GapClosingParams ComputeGapClosingSteps(
    const double InputVoxelSize,
    const double TargetGapRadius,
    const int32 MaxDilations)
{
    constexpr double MaxOffsetInVoxels = 1.5;

    // Strategy A: Use fixed per-step offset up to max allowed
    const double DefaultStep = MaxOffsetInVoxels * InputVoxelSize;
    const int32 DefaultNumSteps = FMath::FloorToInt(float(TargetGapRadius / DefaultStep));
    const double DefaultRemainder = TargetGapRadius - DefaultNumSteps * DefaultStep;

    // Strategy B: Distribute total radius evenly across iterations
    const double AltStep = (TargetGapRadius - InputVoxelSize) / MaxDilations;
    const int32 AltNumSteps = MaxDilations;
    const double AltRemainder = InputVoxelSize;

    const bool bUseDefault = !(MaxDilations < DefaultNumSteps);

    GapClosingParams Result{};
    if (bUseDefault)
    {
        Result.StepSize = DefaultStep;
        Result.Remainder = DefaultRemainder;
        Result.VoxelSize = InputVoxelSize;
        Result.Steps = DefaultNumSteps;
    }
    else
    {
        Result.StepSize = AltStep;
        Result.Remainder = AltRemainder;
        Result.VoxelSize = AltStep / MaxOffsetInVoxels;
        Result.Steps = AltNumSteps;
    }

    return Result;
}

