/**
 * Generate a new SDF with narrow band thickness of 2 that represents moving the zero crossing
 * by the specified world-space distance along the surface normal.
 *
 * @param InSDFVolume       Original signed distance field
 * @param WSOffset          Offset in world units (positive = dilation, negative = erosion)
 * @param ResultVoxelSize   Desired voxel size of output grid
 *
 * @return New SDF grid representing offset surface
 */
static openvdb::FloatGrid::Ptr OffsetSDF(const openvdb::FloatGrid::Ptr InSDFVolume, const double WSOffset, const double ResultVoxelSize)
{
    TRACE_CPUPROFILER_EVENT_SCOPE(OffsetSDF)

    const double CurrentVoxelSize = InSDFVolume->transform().voxelSize()[0];

    checkSlow(FMath::Abs(WSOffset) < 2.0 * CurrentVoxelSize);

    FMixedPolyMesh SurfaceMesh;
    {
        TRACE_CPUPROFILER_EVENT_SCOPE(OpenVDB::VolumeToMesh)
        openvdb::tools::volumeToMesh(*InSDFVolume,
                                     SurfaceMesh.Points,
                                     SurfaceMesh.Triangles,
                                     SurfaceMesh.Quads,
                                     WSOffset,
                                     0.001);
    }

    FMeshDescription RawMesh;
    FStaticMeshAttributes(RawMesh).Register();
    ProxyLOD::MixedPolyMeshToRawMesh(SurfaceMesh, RawMesh);

    openvdb::FloatGrid::Ptr OutGrid = openvdb::FloatGrid::create(*InSDFVolume);
    OutGrid->setTransform(openvdb::math::Transform::createLinearTransform(ResultVoxelSize));

    FMeshDescriptionAdapter MeshAdapter(RawMesh, OutGrid->transform());
    ProxyLOD::MeshArrayToSDFVolume(MeshAdapter, OutGrid);

    return OutGrid;
}

void ProxyLOD::CloseGaps(openvdb::FloatGrid::Ptr InOutSDFVolume, const double GapRadius, const int32 MaxDilations)
{
    if (!InOutSDFVolume || GapRadius <= InOutSDFVolume->transform().voxelSize()[0])
    {
        return;
    }

    TRACE_CPUPROFILER_EVENT_SCOPE(ProxyLOD::CloseGaps)

    const GapClosingParams Params = ComputeGapClosingSteps(
        InOutSDFVolume->transform().voxelSize()[0],
        GapRadius,
        MaxDilations);

    openvdb::FloatGrid::Ptr TempGrid = InOutSDFVolume;

    const bool bHasResidualStep = (Params.Remainder > 0.1 * InOutSDFVolume->transform().voxelSize()[0]);

    // Dilate phase
    if (bHasResidualStep)
    {
        TempGrid = OffsetSDF(TempGrid, Params.Remainder, Params.VoxelSize);
    }

    for (int32 i = 0; i < Params.Steps; ++i)
    {
        TempGrid = OffsetSDF(TempGrid, Params.StepSize, Params.VoxelSize);
    }

    // Erode phase
    for (int32 i = 0; i < Params.Steps; ++i)
    {
        TempGrid = OffsetSDF(TempGrid, -Params.StepSize, Params.VoxelSize);
    }

    if (bHasResidualStep)
    {
        TempGrid = OffsetSDF(TempGrid, -Params.Remainder, InOutSDFVolume->transform().voxelSize()[0]);
    }

    // Final fine-tuning: slight additional shrinkage to avoid overfilling gaps
    TempGrid = OffsetSDF(TempGrid, -0.5 * InOutSDFVolume->transform().voxelSize()[0],
                         InOutSDFVolume->transform().voxelSize()[0]);

    // Merge back with original using CSG union
    openvdb::tools::csgUnion(*InOutSDFVolume, *TempGrid);

    // Cleanup sparsity
    constexpr float HalfBand = 2.0f;
    openvdb::tools::pruneLevelSet(InOutSDFVolume->tree(), HalfBand, -HalfBand);
}

void ProxyLOD::RemoveClipped(openvdb::FloatGrid::Ptr InOutSDFVolume, openvdb::FloatGrid::Ptr ClippingVolume)
{
    TRACE_CPUPROFILER_EVENT_SCOPE(ProxyLOD::RemoveClipped)

    openvdb::tools::csgDifference(*InOutSDFVolume, *ClippingVolume, true);

    constexpr float HalfBand = 2.0f;
    openvdb::tools::pruneLevelSet(InOutSDFVolume->tree(), HalfBand, -HalfBand);
}

