// Convert character to index: '0'-'9' -> 0-9, 'A'-'Z' -> 10-35
inline int charToIndex(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    return c - 'A' + 10;
}

// Convert index back to character: 0-9 -> '0'-'9', 10-35 -> 'A'-'Z'
inline char indexToChar(int idx) {
    if (idx < 10) return '0' + idx;
    return 'A' + (idx - 10);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string str1, str2;
    if (!(cin >> str1 >> str2)) return 0;

    int len1 = str1.size();
    int len2 = str2.size();

    // Precompute positions for each character in str2
    vector<vector<int>> charPositions(36);
    for (int i = 0; i < len2; ++i) {
        int idx = charToIndex(str2[i]);
        charPositions[idx].push_back(i);
    }

    // Add sentinel value at end of each position list
    for (int i = 0; i < 36; ++i) {
        charPositions[i].push_back(len2 + 1);
    }

    // Track current pointer for each character's position list
    vector<int> posPtr(36, 0);

    string result;
    result.reserve(min(len1, len2));

    int lastIdx1 = -1;
    int lastIdx2 = -1;

    // Track which characters we've already considered in current iteration
    vector<int> seenInRound(36, -1);
    int roundNum = 0;

    // Greedy matching loop
    while (lastIdx1 < len1 - 1 && lastIdx2 < len2 - 1) {
        roundNum++;

        int bestCharIdx = -1;
        int bestPos1 = -1;
        int bestPos2 = -1;
        int minTotalCost = INT_MAX;

        // Search for next best match in str1
        for (int i = lastIdx1 + 1; i < len1; ++i) {
            int cost1 = i - lastIdx1;

            // Early termination if cost already too high
            if (cost1 >= minTotalCost) break;

            int cIdx = charToIndex(str1[i]);

            // Skip if already processed this character in this round
            if (seenInRound[cIdx] == roundNum) continue;
            seenInRound[cIdx] = roundNum;

            // Find next valid position in str2 after lastIdx2
            int& p = posPtr[cIdx];
            while (charPositions[cIdx][p] <= lastIdx2) {
                p++;
            }

            int pos2 = charPositions[cIdx][p];
            if (pos2 >= len2) continue;

            int cost2 = pos2 - lastIdx2;
            int totalCost = cost1 + cost2;

            // Update best candidate if this is better
            if (totalCost < minTotalCost) {
                minTotalCost = totalCost;
                bestCharIdx = cIdx;
                bestPos1 = i;
                bestPos2 = pos2;

                // Optimal case: immediate next characters match
                if (totalCost == 2) break;
            } else if (totalCost == minTotalCost) {
                // Tie-breaker: prefer more balanced progress
                int oldDiff = abs((bestPos1 - lastIdx1) - (bestPos2 - lastIdx2));
                int newDiff = abs(cost1 - cost2);
                if (newDiff < oldDiff) {
                    bestCharIdx = cIdx;
                    bestPos1 = i;
                    bestPos2 = pos2;
                }
            }
        }

        if (bestCharIdx != -1) {
            result += indexToChar(bestCharIdx);
            lastIdx1 = bestPos1;
            lastIdx2 = bestPos2;
        } else {
            break;
        }
    }

    cout << result << '\n';
    return 0;
}

#include "strip.h"
#include "ascii.h"
#include <util/string/reverse.h>

void CollapseText(const TString& source, TString& destination, size_t maxLength) {
    // First apply the base collapse operation
    Collapse(source, destination, maxLength);

    // Clean up leading/trailing whitespace
    StripInPlace(destination);

    // Check if we need truncation
    if (destination.length() >= maxLength) {
        // Reserve space for ellipsis (" ...")
        size_t truncateAt = maxLength - 4;
        destination.erase(truncateAt);

        // Reverse string to search from end (which was beginning)
        ReverseInPlace(destination);

        // Look for natural break points: space, period, comma, semicolon
        size_t breakPos = destination.find_first_of(" .,;");
        if (breakPos != TString::npos && breakPos <= 8) {
            // Remove up to and including the break character
            destination.erase(0, breakPos + 1);
        }

        // Restore original orientation
        ReverseInPlace(destination);

        // Add the ellipsis indicator
        destination.append(" ...");
    }
}

