namespace NPerforator::NLinguist::NPython {
    TMaybe<TPythonVersion> TryScanVersion(TConstArrayRef<char> data);
}

TEST(PythonVersionParsing, TryScanVersion) {
    struct TestCase {
        TString Input;
        bool ExpectSuccess;
        TPythonVersion Expected;
    };

    std::vector<TestCase> cases = {
        {"Python 3.10.0", true, {3, 10, 0}},
        {"Python 3.10.1", true, {3, 10, 1}},
        {"Python 2.7", true, {2, 7, 0}},
        {"Python 2.7.10", true, {2, 7, 10}},
        {"Python 3.8.15", true, {3, 8, 15}},
        {"Python 3.12.0", true, {3, 12, 0}},
        {"Python 3.12.1", true, {3, 12, 1}},
        {"Python 2.8.3", true, {2, 8, 3}},
        {"Python version 3.10.0, 64 bit", true, {3, 10, 0}},
        {"Version: Python 2.7.15", true, {2, 7, 15}},
        {"Python 4.0.0", false, {}},
        {"No version here", false, {}},
        {"Python v9.8.7", false, {}},
    };

    for (const auto& test : cases) {
        TMaybe<TPythonVersion> actual = TryScanVersion(
            TConstArrayRef<char>{test.Input.data(), test.Input.size()}
        );

        if (test.ExpectSuccess) {
            ASSERT_TRUE(actual.Defined()) 
                << "Expected to parse version from: '" << test.Input << "'";

            TString expStr = std::to_string(test.Expected.MajorVersion) + "." +
                             std::to_string(test.Expected.MinorVersion) + "." +
                             std::to_string(test.Expected.MicroVersion);
            TString actStr = std::to_string(actual->MajorVersion) + "." +
                             std::to_string(actual->MinorVersion) + "." +
                             std::to_string(actual->MicroVersion);

            EXPECT_EQ(actual->MajorVersion, test.Expected.MajorVersion)
                << "Major version mismatch on input '" << test.Input 
                << "' — expected " << expStr << ", got " << actStr;
            EXPECT_EQ(actual->MinorVersion, test.Expected.MinorVersion)
                << "Minor version mismatch on input '" << test.Input 
                << "' — expected " << expStr << ", got " << actStr;
            EXPECT_EQ(actual->MicroVersion, test.Expected.MicroVersion)
                << "Micro version mismatch on input '" << test.Input 
                << "' — expected " << expStr << ", got " << actStr;
        } else {
            EXPECT_FALSE(actual.Defined())
                << "Should not have parsed version from: '" << test.Input << "'";
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    // Create pillars with extra space for auxiliary pillar (index n+1)
    vector<vector<int>> towers(n + 2);
    set<int> distinct_colors;

    // Read input and collect all colors
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < m; ++j) {
            int color;
            cin >> color;
            towers[i].push_back(color);
            distinct_colors.insert(color);
        }
    }

    // Convert set to sorted list of colors
    vector<int> color_order(distinct_colors.begin(), distinct_colors.end());

    // Map each color to its target tower index (1-based)
    unordered_map<int, int> destination;
    for (int i = 0; i < n; ++i) {
        destination[color_order[i]] = i + 1;
    }

    vector<pair<int, int>> steps;
    int helper_tower = n + 1;

    // Phase 1: Move all disks from original towers to the helper tower
    for (int src = 1; src <= n; ++src) {
        while (!towers[src].empty()) {
            int disk_color = towers[src].back();
            towers[src].pop_back();
            towers[helper_tower].push_back(disk_color);
            steps.emplace_back(src, helper_tower);
        }
    }

    // Phase 2: Move disks from helper tower to their correct destinations
    while (!towers[helper_tower].empty()) {
        int disk_color = towers[helper_tower].back();
        towers[helper_tower].pop_back();
        int target_tower = destination[disk_color];
        towers[target_tower].push_back(disk_color);
        steps.emplace_back(helper_tower, target_tower);
    }

    // Output results
    cout << steps.size() << "\n";
    for (const auto& step : steps) {
        cout << step.first << " " << step.second << "\n";
    }

    return 0;
}

