// Custom exception address tracker using vector + linear probing
struct ExceptionAddressSet {
    std::vector<uintptr_t> entries;
    mutable utils::SRWLockExclusive lock;

    bool contains(uintptr_t addr) const {
        for (auto e : entries) {
            if (e == addr) return true;
        }
        return false;
    }

    void insert(uintptr_t addr) {
        if (!contains(addr)) {
            entries.push_back(addr);
        }
    }

    bool check_and_record(uintptr_t addr) {
        utils::SRWLockExclusive guard(lock);
        if (contains(addr)) {
            return true;
        }
        insert(addr);
        return false;
    }
};

ExceptionAddressSet g_exception_address_cache;

// Helper: convert wide string to UTF-8 safely
std::string WideToUtf8(const wchar_t* wstr) {
    if (!wstr) return "";
    int len = WideCharToMultiByte(CP_UTF8, 0, wstr, -1, nullptr, 0, nullptr, nullptr);
    if (len <= 0) return "";
    std::string result(len - 1, '\0');
    WideCharToMultiByte(CP_UTF8, 0, wstr, -1, &result[0], len, nullptr, nullptr);
    return result;
}

void PrintProcessInfo() {
    try {
        LogInfo("=== PROCESS INFORMATION ===");

        DWORD pid = GetCurrentProcessId();
        LogInfo("Process ID: %lu", pid);

        DWORD tid = GetCurrentThreadId();
        LogInfo("Thread ID: %lu", tid);

        wchar_t path[MAX_PATH];
        if (GetModuleFileNameW(nullptr, path, MAX_PATH)) {
            LogInfo("Process Path: %s", WideToUtf8(path).c_str());
        }

        LPSTR cmdline = GetCommandLineA();
        if (cmdline) {
            LogInfo("Command Line: %s", cmdline);
        }

        HANDLE proc = GetCurrentProcess();
        PROCESS_MEMORY_COUNTERS_EX meminfo = {};
        if (GetProcessMemoryInfo(proc, reinterpret_cast<PROCESS_MEMORY_COUNTERS*>(&meminfo), sizeof(meminfo))) {
            LogInfo("Process Memory - Working Set: %zu MB, Peak: %zu MB, Page Faults: %lu",
                    meminfo.WorkingSetSize / (1024 * 1024),
                    meminfo.PeakWorkingSetSize / (1024 * 1024),
                    meminfo.PageFaultCount);
        }

        LogInfo("=== END PROCESS INFORMATION ===");
    } catch (...) {
        LogInfo("=== PROCESS INFO ERROR ===");
        LogInfo("Exception during process info collection");
        LogInfo("=== END PROCESS INFO ERROR ===");
    }
}

void PrintSystemInfo() {
    try {
        LogInfo("=== SYSTEM INFORMATION ===");

        typedef NTSTATUS(WINAPI * RtlGetVersionPtr)(OSVERSIONINFOEXW*);
        HMODULE ntdll = GetModuleHandleW(L"ntdll.dll");
        if (ntdll) {
            RtlGetVersionPtr rtl_get_version = reinterpret_cast<RtlGetVersionPtr>(GetProcAddress(ntdll, "RtlGetVersion"));
            if (rtl_get_version) {
                OSVERSIONINFOEXW osv = {};
                osv.dwOSVersionInfoSize = sizeof(osv);
                if (rtl_get_version(&osv) == 0) {
                    std::ostringstream oss;
                    oss << "OS Version: Windows " << osv.dwMajorVersion << "." << osv.dwMinorVersion
                        << " Build " << osv.dwBuildNumber;
                    if (osv.wServicePackMajor > 0)
                        oss << " SP" << osv.wServicePackMajor;
                    LogInfo("%s", oss.str().c_str());
                }
            }
        }

        SYSTEM_INFO sysinfo = {};
        GetSystemInfo(&sysinfo);
        std::ostringstream cpu_oss;
        cpu_oss << "CPU - Cores: " << sysinfo.dwNumberOfProcessors << ", Arch: ";
        switch (sysinfo.wProcessorArchitecture) {
            case PROCESSOR_ARCHITECTURE_AMD64: cpu_oss << "x64"; break;
            case PROCESSOR_ARCHITECTURE_INTEL: cpu_oss << "x86"; break;
            case PROCESSOR_ARCHITECTURE_ARM:   cpu_oss << "ARM"; break;
            case PROCESSOR_ARCHITECTURE_ARM64: cpu_oss << "ARM64"; break;
            default: cpu_oss << "Unknown (0x" << std::hex << sysinfo.wProcessorArchitecture << ")"; break;
        }
        LogInfo("%s", cpu_oss.str().c_str());

        MEMORYSTATUSEX memstat = {};
        memstat.dwLength = sizeof(memstat);
        if (GlobalMemoryStatusEx(&memstat)) {
            LogInfo("System Memory - Total: %.2f GB, Available: %.2f GB, Load: %lu%%",
                    static_cast<double>(memstat.ullTotalPhys) / (1024.0 * 1024.0 * 1024.0),
                    static_cast<double>(memstat.ullAvailPhys) / (1024.0 * 1024.0 * 1024.0),
                    memstat.dwMemoryLoad);
        }

        time_t raw_time = time(nullptr);
        struct tm tmbuf;
        if (localtime_s(&tmbuf, &raw_time) == 0) {
            char buf[64];
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tmbuf);
            LogInfo("Crash Time: %s", buf);
        }

        LogInfo("=== END SYSTEM INFORMATION ===");
    } catch (...) {
        LogInfo("=== SYSTEM INFO ERROR ===");
        LogInfo("Exception during system info collection");
        LogInfo("=== END SYSTEM INFO ERROR ===");
    }
}

void PrintVersionInfo() {
    try {
        LogInfo("=== VERSION INFORMATION ===");
        LogInfo("%s", DISPLAY_COMMANDER_FULL_VERSION);
        LogInfo("=== END VERSION INFORMATION ===");
    } catch (...) {
        LogInfo("=== VERSION INFO ERROR ===");
        LogInfo("Exception during version info collection");
        LogInfo("=== END VERSION INFO ERROR ===");
    }
}

void PrintLoadedModules() {
    try {
        LogInfo("=== LOADED MODULES ===");

        HANDLE proc = GetCurrentProcess();
        HMODULE mods[1024];
        DWORD needed;
        if (!EnumProcessModules(proc, mods, sizeof(mods), &needed)) {
            LogInfo("Failed to enumerate modules - Error: %lu", GetLastError());
            LogInfo("=== END LOADED MODULES ===");
            return;
        }

        DWORD count = needed / sizeof(HMODULE);
        LogInfo("Total loaded modules: %lu", count);

        for (DWORD i = 0; i < count; ++i) {
            wchar_t modpath[MAX_PATH];
            if (GetModuleFileNameW(mods[i], modpath, MAX_PATH)) {
                std::string utf8path = WideToUtf8(modpath);
                MODULEINFO info = {};
                if (GetModuleInformation(proc, mods[i], &info, sizeof(info))) {
                    LogInfo("  [%lu] %s (Base: 0x%llx, Size: %lu bytes)",
                            i, utf8path.c_str(),
                            reinterpret_cast<unsigned long long>(info.lpBaseOfDll),
                            info.SizeOfImage);
                } else {
                    LogInfo("  [%lu] %s", i, utf8path.c_str());
                }
            } else {
                LogInfo("  [%lu] <Unknown Module> (Handle: 0x%p)", i, mods[i]);
            }
        }

        LogInfo("=== END LOADED MODULES ===");
    } catch (...) {
        LogInfo("=== MODULE ENUM ERROR ===");
        LogInfo("Exception during module enumeration");
        LogInfo("=== END MODULE ENUM ERROR ===");
    }
}

void LogCrashReport(PEXCEPTION_POINTERS ex, const char* header, bool log_sections) {
    LogInfo("%s", header);

    if (log_sections) {
        const char* mon = g_continuous_monitoring_section.load(std::memory_order_acquire);
        const char* rend = g_rendering_ui_section.load(std::memory_order_acquire);
        LogInfo("g_continuous_monitoring_section: %s", mon ? mon : "(null)");
        LogInfo("g_rendering_ui_section: %s", rend ? rend : "(null)");
    }

    PrintVersionInfo();
    PrintSystemInfo();
    PrintProcessInfo();

    if (ex && ex->ExceptionRecord) {
        const EXCEPTION_RECORD* rec = ex->ExceptionRecord;
        LogInfo("Exception Code: 0x%08X", rec->ExceptionCode);
        LogInfo("Exception Flags: 0x%08X", rec->ExceptionFlags);
        LogInfo("Exception Address: 0x%p", rec->ExceptionAddress);
    }

    MEMORYSTATUSEX memstat = {};
    memstat.dwLength = sizeof(memstat);
    if (GlobalMemoryStatusEx(&memstat)) {
        LogInfo("System Memory Load: %lu%%", memstat.dwMemoryLoad);
    }

    uint64_t now_ns = utils::get_real_time_ns();
    std::string detour_log = detour_call_tracker::FormatRecentDetourCalls(now_ns, 256);
    LogInfo("=== RECENT DETOUR CALLS ===");
    exit_handler::WriteMultiLineToDebugLog(detour_log, "Recent Detour Calls: <none recorded>");
    LogInfo("=== END RECENT DETOUR CALLS ===");

    std::string guards_log = detour_call_tracker::FormatUndestroyedGuards(now_ns);
    LogInfo("=== UNDESTROYED DETOUR GUARDS ===");
    exit_handler::WriteMultiLineToDebugLog(guards_log, "Undestroyed Detour Guards: 0");
    LogInfo("=== END UNDESTROYED DETOUR GUARDS ===");

    LogInfo("=== GENERATING STACK TRACE ===");
    CONTEXT* ctx = (ex && ex->ContextRecord) ? ex->ContextRecord : nullptr;
    auto trace = stack_trace::GenerateStackTrace(ctx);
    LogInfo("=== STACK TRACE ===");
    for (const auto& line : trace) {
        LogInfo("%s", line.c_str());
    }
    LogInfo("=== END STACK TRACE ===");

    PrintLoadedModules();
    display_commander::logger::FlushLogs();
}
