namespace process_exit_hooks {

std::atomic<bool> g_installed{false};
std::atomic<LPTOP_LEVEL_EXCEPTION_FILTER> g_prev_unhandled_filter{nullptr};
void* g_vectored_handle = nullptr;

void AtExitHandler() {
    exit_handler::OnHandleExit(exit_handler::ExitSource::ATEXIT, "Normal process exit via atexit");
}

LONG WINAPI UnhandledExceptionHandler(EXCEPTION_POINTERS* ex) {
    if (g_shutdown.load()) {
        return EXCEPTION_EXECUTE_HANDLER;
    }

    uintptr_t addr = 0;
    if (ex && ex->ExceptionRecord) {
        addr = reinterpret_cast<uintptr_t>(ex->ExceptionRecord->ExceptionAddress);
        if (g_exception_address_cache.check_and_record(addr)) {
            return EXCEPTION_EXECUTE_HANDLER;
        }
    }

    dbghelp_loader::LoadDbgHelp();
    LogCrashReport(ex, "=== CRASH DETECTED - DETAILED REPORT ===", false);
    return EXCEPTION_EXECUTE_HANDLER;
}

LONG WINAPI VectoredExceptionHandler(PEXCEPTION_POINTERS ex) {
    if (g_shutdown.load()) {
        return EXCEPTION_CONTINUE_SEARCH;
    }

    DWORD code = ex->ExceptionRecord->ExceptionCode;
    if (code == CONTROL_C_EXIT || code == 0x406D1388 ||
        code == DBG_PRINTEXCEPTION_C || code == DBG_PRINTEXCEPTION_WIDE_C ||
        code == STATUS_BREAKPOINT || code == 0xE0434352 || code == 0xE06D7363 ||
        ((code ^ 0xE24C4A00) <= 0xFF)) {
        return EXCEPTION_CONTINUE_SEARCH;
    }

    uintptr_t addr = 0;
    if (ex && ex->ExceptionRecord) {
        addr = reinterpret_cast<uintptr_t>(ex->ExceptionRecord->ExceptionAddress);
        if (g_exception_address_cache.check_and_record(addr)) {
            LogInfo("Vectored exception at 0x%p already logged, skipping.", (void*)addr);
            return EXCEPTION_CONTINUE_SEARCH;
        }
    }

    dbghelp_loader::LoadDbgHelp();
    LogCrashReport(ex, "=== VECTORED EXCEPTION HANDLER ===", true);
    return EXCEPTION_CONTINUE_SEARCH;
}

void Initialize() {
    bool expected = false;
    if (!g_installed.compare_exchange_strong(expected, true)) return;

    std::atexit(AtExitHandler);

    LogInfo("Installing SEH unhandled exception filter");
    g_prev_unhandled_filter = ::SetUnhandledExceptionFilter(UnhandledExceptionHandler);

    LogInfo("Installing vectored exception handler");
    g_vectored_handle = ::AddVectoredExceptionHandler(1, VectoredExceptionHandler);
    if (!g_vectored_handle) {
        LogInfo("Failed to install vectored handler");
    } else {
        LogInfo("Vectored handler installed successfully");
    }
}

void Shutdown() {
    bool expected = true;
    if (!g_installed.compare_exchange_strong(expected, false)) return;

    ::SetUnhandledExceptionFilter(g_prev_unhandled_filter);
    g_prev_unhandled_filter.store(nullptr);

    if (g_vectored_handle) {
        ::RemoveVectoredExceptionHandler(g_vectored_handle);
        g_vectored_handle = nullptr;
        LogInfo("Vectored handler removed");
    }

    {
        utils::SRWLockExclusive guard(g_exception_address_cache.lock);
        g_exception_address_cache.entries.clear();
    }
}

} // namespace process_exit_hooks

