// Perform GC lowering: replace gc intrinsics and ensure root initialization
static bool ApplyGCTransformation(Function &F, GCStrategy &S);

namespace {

/// TransformGCIntrinsics - A function pass that converts high-level GC
/// intrinsics (like gcroot, gcread, gcwrite) into basic load/store operations,
/// while preserving necessary metadata for the backend.
class TransformGCIntrinsics : public FunctionPass {
public:
  static char ID;
  TransformGCIntrinsics();
  StringRef getPassName() const override;
  void getAnalysisUsage(AnalysisUsage &AU) const override;
  bool doInitialization(Module &M) override;
  bool runOnFunction(Function &F) override;
};

/// AnalyzeGCForMachineCode - A machine-function pass to locate safe points
/// and compute stack layout information required by the garbage collector.
class AnalyzeGCForMachineCode : public MachineFunctionPass {
  GCFunctionInfo *FuncInfo = nullptr;
  const TargetInstrInfo *InstrInfo = nullptr;

  void LocateSafePoints(MachineFunction &MF);
  void ProcessCallSite(MachineBasicBlock::iterator CallInstr);
  MCSymbol *EmitLabelAt(MachineBasicBlock &MBB,
                        MachineBasicBlock::iterator Pos,
                        const DebugLoc &DL) const;
  void ComputeStackLayout(MachineFunction &MF);

public:
  static char ID;
  AnalyzeGCForMachineCode();
  void getAnalysisUsage(AnalysisUsage &AU) const override;
  bool runOnMachineFunction(MachineFunction &MF) override;
};

}

PreservedAnalyses GCTransformPass::run(Function &F,
                                       FunctionAnalysisManager &FAM) {
  auto &GCFI = FAM.getResult<GCFunctionAnalysis>(F);
  bool Modified = ApplyGCTransformation(F, GCFI.getStrategy());
  if (!Modified)
    return PreservedAnalyses::all();

  PreservedAnalyses PA;
  PA.preserve<DominatorTreeAnalysis>();
  return PA;
}

