bool TransformGCIntrinsics::doInitialization(Module &M) {
  GCModuleInfo *MI = getAnalysisIfAvailable<GCModuleInfo>();
  assert(MI && "TransformGCIntrinsics did not require GCModuleInfo!?");

  for (Function &F : M) {
    if (!F.isDeclaration() && F.hasGC()) {
      MI->getFunctionInfo(F); // Ensure GC strategy is initialized
    }
  }
  return false;
}

// Conservative check whether an instruction might introduce a safepoint
static bool MayIntroduceSafePoint(Instruction *I) {
  // Simple memory operations are assumed safe
  if (isa<AllocaInst>(I) || isa<GetElementPtrInst>(I) ||
      isa<StoreInst>(I) || isa<LoadInst>(I))
    return false;

  // gcroot intrinsic itself doesn't cause safepoints
  if (CallInst *CI = dyn_cast<CallInst>(I)) {
    if (Function *CalledF = CI->getCalledFunction()) {
      if (Intrinsic::ID IID = CalledF->getIntrinsicID()) {
        if (IID == Intrinsic::gcroot)
          return false;
      }
    }
  }

  return true;
}

// Insert null stores for uninitialized roots before first potential safepoint
static bool InitializeUnsetRoots(Function &F, ArrayRef<AllocaInst *> Roots) {
  BasicBlock &EntryBB = F.getEntryBlock();
  auto IP = EntryBB.begin();
  while (isa<AllocaInst>(IP))
    ++IP;

  SmallPtrSet<AllocaInst *, 16> AlreadyInitialized;
  for (; !MayIntroduceSafePoint(&*IP); ++IP) {
    if (StoreInst *SI = dyn_cast<StoreInst>(IP)) {
      if (AllocaInst *AI =
              dyn_cast<AllocaInst>(SI->getOperand(1)->stripPointerCasts())) {
        AlreadyInitialized.insert(AI);
      }
    }
  }

  bool Changed = false;
  for (AllocaInst *Root : Roots) {
    if (!AlreadyInitialized.count(Root)) {
      new StoreInst(
          ConstantPointerNull::get(cast<PointerType>(Root->getAllocatedType())),
          Root, Root->getNextNode());
      Changed = true;
    }
  }
  return Changed;
}

// Main transformation logic: replace GC intrinsics with basic operations
bool TransformGCIntrinsics::runOnFunction(Function &F) {
  if (!F.hasGC())
    return false;

  GCFunctionInfo &FI = getAnalysis<GCModuleInfo>().getFunctionInfo(F);
  GCStrategy &S = FI.getStrategy();
  return ApplyGCTransformation(F, S);
}

bool ApplyGCTransformation(Function &F, GCStrategy &S) {
  SmallVector<AllocaInst *, 32> Roots;
  bool Modified = false;

  for (BasicBlock &BB : F) {
    for (Instruction &I : llvm::make_early_inc_range(BB)) {
      IntrinsicInst *II = dyn_cast<IntrinsicInst>(&I);
      if (!II)
        continue;

      Function *CalledF = II->getCalledFunction();
      if (!CalledF)
        continue;

      switch (CalledF->getIntrinsicID()) {
      default:
        break;

      case Intrinsic::gcwrite: {
        Value *NewStore = new StoreInst(II->getArgOperand(0),
                                        II->getArgOperand(2), II);
        II->replaceAllUsesWith(NewStore);
        II->eraseFromParent();
        Modified = true;
        break;
      }

      case Intrinsic::gcread: {
        Value *NewLoad = new LoadInst(II->getType(), II->getArgOperand(1),
                                      "", II);
        NewLoad->takeName(II);
        II->replaceAllUsesWith(NewLoad);
        II->eraseFromParent();
        Modified = true;
        break;
      }

      case Intrinsic::gcroot: {
        AllocaInst *AI = cast<AllocaInst>(
            II->getArgOperand(0)->stripPointerCasts());
        Roots.push_back(AI);
        break;
      }
      }
    }
  }

  if (!Roots.empty())
    Modified |= InitializeUnsetRoots(F, Roots);

  return Modified;
}

