char AnalyzeGCForMachineCode::ID = 0;
char &llvm::AnalyzeGCForMachineCodeID = AnalyzeGCForMachineCode::ID;

INITIALIZE_PASS(AnalyzeGCForMachineCode, "gc-machine-analysis",
                "Machine Code Analysis for Garbage Collection", false, false)

AnalyzeGCForMachineCode::AnalyzeGCForMachineCode() : MachineFunctionPass(ID) {}

void AnalyzeGCForMachineCode::getAnalysisUsage(AnalysisUsage &AU) const {
  MachineFunctionPass::getAnalysisUsage(AU);
  AU.setPreservesAll();
  AU.addRequired<GCModuleInfo>();
}

MCSymbol *AnalyzeGCForMachineCode::EmitLabelAt(MachineBasicBlock &MBB,
                                               MachineBasicBlock::iterator Pos,
                                               const DebugLoc &DL) const {
  MCContext &Ctx = MBB.getParent()->getContext();
  MCSymbol *Sym = Ctx.createTempSymbol();
  BuildMI(MBB, Pos, DL, InstrInfo->get(TargetOpcode::GC_LABEL)).addSym(Sym);
  return Sym;
}

void AnalyzeGCForMachineCode::ProcessCallSite(MachineBasicBlock::iterator CallInstr) {
  MachineBasicBlock::iterator NextInstr = CallInstr;
  ++NextInstr;
  MCSymbol *Label = EmitLabelAt(*CallInstr->getParent(), NextInstr,
                                CallInstr->getDebugLoc());
  FuncInfo->addSafePoint(Label, CallInstr->getDebugLoc());
}

void AnalyzeGCForMachineCode::LocateSafePoints(MachineFunction &MF) {
  for (MachineBasicBlock &MBB : MF) {
    for (MachineInstr &MI : MBB) {
      if (MI.isCall()) {
        // Skip tail/sibling calls as they don't need safepoints
        if (MI.isTerminator())
          continue;
        ProcessCallSite(&MI);
      }
    }
  }
}

void AnalyzeGCForMachineCode::ComputeStackLayout(MachineFunction &MF) {
  const TargetFrameLowering *TFI = MF.getSubtarget().getFrameLowering();
  assert(TFI && "TargetFrameLowering unavailable!");

  for (auto RI = FuncInfo->roots_begin(); RI != FuncInfo->roots_end();) {
    if (MF.getFrameInfo().isDeadObjectIndex(RI->Num)) {
      RI = FuncInfo->removeStackRoot(RI);
    } else {
      Register FrameReg; // TODO: consider storing frame register in GCRoot
      auto Offset = TFI->getFrameIndexReference(MF, RI->Num, FrameReg);
      assert(!Offset.getScalable() &&
             "Scalable frame offsets not supported for GC");
      RI->StackOffset = Offset.getFixed();
      ++RI;
    }
  }
}

bool AnalyzeGCForMachineCode::runOnMachineFunction(MachineFunction &MF) {
  if (!MF.getFunction().hasGC())
    return false;

  FuncInfo = &getAnalysis<GCModuleInfo>().getFunctionInfo(MF.getFunction());
  InstrInfo = MF.getSubtarget().getInstrInfo();

  const MachineFrameInfo &MFI = MF.getFrameInfo();
  const TargetRegisterInfo *RegInfo = MF.getSubtarget().getRegisterInfo();
  bool HasDynamicFrame = MFI.hasVarSizedObjects() ||
                         RegInfo->hasStackRealignment(MF);

  FuncInfo->setFrameSize(HasDynamicFrame ? UINT64_MAX : MFI.getStackSize());

  if (FuncInfo->getStrategy().needsSafePoints())
    LocateSafePoints(MF);

  ComputeStackLayout(MF);
  return false;
}

