#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;

    const double MM = 10000.0;
    const double XX = 20001.0;

    // Initial phase: estimate slope and intercept using two points
    double y1 = -300000000.0;
    double delta_init = 10000000.0;
    double y2 = y1 + delta_init;

    cout << "? " << XX << " " << y1 << endl;
    cout.flush();
    double f1;
    cin >> f1;

    cout << "? " << XX << " " << y2 << endl;
    cout.flush();
    double f2;
    cin >> f2;

    // Estimate W from the slope between two points
    double slope_init = (f2 - f1) / delta_init;
    double W = -slope_init;
    double sum_wp = f1 + y1 * W;

    // Current linear model parameters
    double current_slope = -W;
    double intercept = sum_wp;

    int last_a = -10001;
    vector<int> a_values, b_values;

    // Thresholds for numerical stability
    const double slope_threshold = 1e-4;
    const double epsilon = 0.4;
    const double diff_threshold = 3e-5;

    for (int m = 0; m < N; ++m) {
        // Binary search to find next 'a' value where slope increases significantly
        int left = last_a + 1;
        int right = 10000;

        while (left < right) {
            int mid = (left + right) / 2;
            double test_y = mid * XX + MM;

            cout << "? " << XX << " " << test_y << endl;
            cout.flush();
            double val1;
            cin >> val1;

            double test_yp = test_y + epsilon;
            cout << "? " << XX << " " << test_yp << endl;
            cout.flush();
            double val2;
            cin >> val2;

            double local_slope = (val2 - val1) / epsilon;

            if (local_slope > current_slope + slope_threshold) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        // Validate candidate 'a'
        int candidate_a = left;
        double test_y = candidate_a * XX + MM;

        cout << "? " << XX << " " << test_y << endl;
        cout.flush();
        double val1;
        cin >> val1;

        double test_yp = test_y + epsilon;
        cout << "? " << XX << " " << test_yp << endl;
        cout.flush();
        double val2;
        cin >> val2;

        double local_slope = (val2 - val1) / epsilon;

        if (local_slope <= current_slope + slope_threshold) {
            // Skip this candidate if it doesn't meet criteria
            continue;
        }

        int a_val = candidate_a;

        // Local binary search to find precise p value
        double low_p = a_val * XX - MM;
        double high_p = a_val * XX + MM;
        int iterations = 0;
        const int max_iterations = 60;

        while ((high_p - low_p > 1e-10) && (iterations < max_iterations)) {
            iterations++;
            double mid_p = (low_p + high_p) / 2.0;

            cout << "? " << XX << " " << mid_p << endl;
            cout.flush();
            double response;
            cin >> response;

            double expected = current_slope * mid_p + intercept;
            double deviation = response - expected;

            if (deviation > diff_threshold) {
                high_p = mid_p;
            } else {
                low_p = mid_p;
            }
        }

        double approx_p = (low_p + high_p) / 2.0;

        // Convert to integer components
        long long a_component = llround(approx_p / XX);
        double remainder = approx_p - a_component * XX;
        long long b_component = llround(remainder);

        a_values.push_back(static_cast<int>(a_component));
        b_values.push_back(static_cast<int>(b_component));

        // Update model parameters based on new point
        double aa = static_cast<double>(a_component);
        double weight = 1.0 / sqrt(aa * aa + 1.0);
        double old_expected = current_slope * (a_component * XX + b_component) + intercept;

        current_slope += 2.0 * weight;
        intercept = old_expected - current_slope * (a_component * XX + b_component);

        last_a = a_component;
    }

    // Output final result
    cout << "!";
    for (int a : a_values) cout << " " << a;
    for (int b : b_values) cout << " " << b;
    cout << endl;
    cout.flush();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Connection {
    int from, via, to;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    if (n == 0) {
        cout << 0 << '\n';
        return 0;
    }

    // Compute block size with adjusted formula
    int blockSize = (n + 3) / 4;
    if (blockSize < 1) blockSize = 1;

    vector<Connection> connections;

    // Estimate capacity needed for edges
    long long estimatedCapacity = static_cast<long long>(max(0, blockSize - 1)) * (n + 1) + (n + 1);
    connections.reserve(static_cast<size_t>(estimatedCapacity));

    // Add intermediate edges: for each step d in [2, blockSize], connect i -> i+d through i+1
    for (int step = 2; step <= blockSize; ++step) {
        for (int start = 0; start + step <= n; ++start) {
            connections.push_back({start, start + 1, start + step});
        }
    }

    // Add longer edges of length 2*blockSize when possible
    int longStep = 2 * blockSize;
    if (longStep <= n) {
        for (int start = 0; start + longStep <= n; ++start) {
            connections.push_back({start, start + blockSize, start + longStep});
        }
    }

    cout << connections.size() << '\n';
    for (const auto &conn : connections) {
        cout << conn.from << ' ' << conn.via << ' ' << conn.to << '\n';
    }

    return 0;
}

