//-------------------------------------------------------------------------
/// @details
/// 	Locates the configuration mapper associated with a given protocol string.
///	@param[in] protocolName
///		The protocol identifier to search for.
///	@param[out] outMapperRef
///		Output reference to receive the address of the found mapper.
//-------------------------------------------------------------------------
ErrorOr<UrlConfig::MapperPtr> UrlConfig::getMapper(const iTextView protocolName) {
    // Attempt lookup in internal map
    auto iter = m_UrlConfig.find(protocolName);

    // If not found, return error
    if (iter == m_UrlConfig.end()) {
        return APERR(Ec::InvalidSchema, "The url protocol", protocolName,
                     "was not found");
    }

    // Return pointer to the mapped value
    return &(iter->second);
}

//-------------------------------------------------------------------------
/// @details
/// 	Retrieves capability flags for a specified protocol.
//-------------------------------------------------------------------------
Error UrlConfig::getCaps(const iTextView protocolName, uint32_t &caps) {
    // Retrieve mapper first
    auto mapperResult = getMapper(protocolName);
    if (!mapperResult) {
        return mapperResult.ccode();
    }

    // Extract capabilities safely
    caps = (*mapperResult)->capabilities;
    return {};
}

//-------------------------------------------------------------------------
/// @details
/// 	Converts a full URL into an OS-native file path by stripping protocol and prefixes.
//-------------------------------------------------------------------------
Error UrlConfig::toPath(const Url &sourceUrl, file::Path &targetPath) {
    const auto protocol = sourceUrl.protocol();

    auto mapperResult = getMapper(protocol);
    if (!mapperResult) {
        return mapperResult.ccode();
    }

    const auto& mapper = *mapperResult;
    if (!mapper->toPath) {
        return APERR(Ec::InvalidSchema, "The protocol", protocol,
                     "has no toPath conversion");
    }

    return mapper->toPath(sourceUrl, targetPath);
}

//-------------------------------------------------------------------------
/// @details
/// 	Constructs a URL from a protocol name and a native file path, applying any required prefixes.
//-------------------------------------------------------------------------
Error UrlConfig::toUrl(const iTextView protocolName, const file::Path &sourcePath,
                       Url &targetUrl) {
    auto mapperResult = getMapper(protocolName);
    if (!mapperResult) {
        return mapperResult.ccode();
    }

    const auto& mapper = *mapperResult;
    if (!mapper->toUrl) {
        return APERR(Ec::InvalidSchema, "The protocol", protocolName,
                     "has no toUrl conversion");
    }

    return mapper->toUrl(protocolName, sourcePath, targetUrl);
}

//-------------------------------------------------------------------------
/// @details
/// 	Transforms a URL into an OS-specific text path representation.
//-------------------------------------------------------------------------
Error UrlConfig::osPath(const Url &sourceUrl, Text &targetPath) {
    const auto protocol = sourceUrl.protocol();

    auto mapperResult = getMapper(protocol);
    if (!mapperResult) {
        return mapperResult.ccode();
    }

    const auto& mapper = *mapperResult;
    if (!mapper->osPath) {
        return APERR(Ec::InvalidSchema, "The protocol", protocol,
                     "has no osPath conversion");
    }

    return mapper->osPath(sourceUrl, targetPath);
}

//-------------------------------------------------------------------------
/// @details
/// 	Performs validation on a given URL using its associated protocol handler.
//-------------------------------------------------------------------------
Error UrlConfig::validate(const Url &urlToCheck) {
    const auto protocol = urlToCheck.protocol();

    auto mapperResult = getMapper(protocol);
    if (!mapperResult) {
        return mapperResult.ccode();
    }

    const auto& mapper = *mapperResult;
    if (!mapper->validate) {
        // No validator defined → assume valid
        return {};
    }

    return mapper->validate(urlToCheck);
}

