void circular_raw_ostream::write_impl(const char *Ptr, size_t Size) {
  if (BufferSize == 0) {
    TheStream->write(Ptr, Size);
    return;
  }

  // Fill the buffer cyclically, handling wrap-around as needed
  while (Size > 0) {
    size_t remainingSpace = BufferSize - static_cast<size_t>(Cur - BufferArray);
    size_t transferAmount = (Size < remainingSpace) ? Size : remainingSpace;

    std::memcpy(Cur, Ptr, transferAmount);
    Cur += transferAmount;
    Ptr += transferAmount;
    Size -= transferAmount;

    if (Cur == BufferArray + BufferSize) {
      Cur = BufferArray;
      Filled = true;
    }
  }
}

void circular_raw_ostream::flushBufferWithBanner() {
  if (BufferSize != 0) {
    // Output banner before flushing buffer contents
    TheStream->write(Banner, std::strlen(Banner));
    flushBuffer();
  }
}

