void bind_sm_channel(nb::module_& m) {
  // Bind SmChannel class with two constructor overloads via lambda-based __init__
  nb::class_<SmChannel> smChannel(m, "SmChannel");

  smChannel
      .def("__init__",
           [](SmChannel* ptr, std::shared_ptr<SmDevice2DeviceSemaphore> sem, RegisteredMemory dst, uintptr_t src) {
             new (ptr) SmChannel(sem, dst, reinterpret_cast<void*>(src));
           })
      .def("__init__",
           [](SmChannel* ptr, std::shared_ptr<SmDevice2DeviceSemaphore> sem, RegisteredMemory dst,
              uintptr_t src, uintptr_t getBuf) {
             new (ptr) SmChannel(sem, dst, reinterpret_cast<void*>(src), reinterpret_cast<void*>(getBuf));
           })
      .def("device_handle", &SmChannel::deviceHandle);

  // Bind nested DeviceHandle class
  nb::class_<SmChannel::DeviceHandle> devHandle(m, "SmChannelDeviceHandle");

  devHandle
      .def(nb::init<>())
      .def_rw("semaphore_", &SmChannel::DeviceHandle::semaphore_)
      .def_rw("src_", &SmChannel::DeviceHandle::src_)
      .def_rw("dst_", &SmChannel::DeviceHandle::dst_)
      .def_rw("getPacketBuffer_", &SmChannel::DeviceHandle::getPacketBuffer_)
      .def_prop_ro("raw", [](const SmChannel::DeviceHandle& h) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&h), sizeof(h));
      });
