#define DEBUG_TYPE "lowerinvoke"

STATISTIC(NumReplacedInvokes, "Number of invokes lowered");

namespace {

  class LowerInvokeAdapter : public FunctionPass {
  public:
    static char ID;
    LowerInvokeAdapter() : FunctionPass(ID) {
      initializeLowerInvokeAdapterPass(*PassRegistry::getPassRegistry());
    }

    bool runOnFunction(Function &func) override;
  };

}

char LowerInvokeAdapter::ID = 0;

INITIALIZE_PASS(LowerInvokeAdapter, "lowerinvoke",
                "Lower invoke/unwind to call/branch for exception-free targets",
                false, false)

static bool lowerInvokeImpl(Function &F) {
  bool modified = false;

  for (BasicBlock &block : F) {
    Instruction *term = block.getTerminator();
    if (!isa<InvokeInst>(term))
      continue;

    InvokeInst *invoke = cast<InvokeInst>(term);

    // Gather operands and bundles
    SmallVector<Value *, 16> arguments;
    for (auto arg : invoke->args())
      arguments.push_back(arg);

    SmallVector<OperandBundleDef, 1> bundles;
    invoke->getOperandBundlesAsDefs(bundles);

    // Create a regular call instruction
    CallInst *directCall = CallInst::Create(
        invoke->getFunctionType(),
        invoke->getCalledOperand(),
        arguments,
        bundles,
        "",
        invoke
    );

    directCall->takeName(invoke);
    directCall->setCallingConv(invoke->getCallingConv());
    directCall->copyAttributesFrom(invoke);
    directCall->setDebugLoc(invoke->getDebugLoc());

    // Replace all uses of the invoke with the new call
    invoke->replaceAllUsesWith(directCall);

    // Insert unconditional branch to normal destination
    BranchInst::Create(invoke->getNormalDest(), invoke);

    // Clean up PHI nodes in the unwind destination
    BasicBlock *unwindBB = invoke->getUnwindDest();
    unwindBB->removePredecessor(&block);

    // Erase the old invoke instruction
    invoke->eraseFromParent();

    ++NumReplacedInvokes;
    modified = true;
  }

  return modified;
}

bool LowerInvokeAdapter::runOnFunction(Function &F) {
  return lowerInvokeImpl(F);
}

namespace llvm {

// Export the pass ID for external use
char &LowerInvokePassID = LowerInvokeAdapter::ID;

// Factory function for legacy pass manager
FunctionPass *createLowerInvokePass() {
  return new LowerInvokeAdapter();
}

// New pass manager interface
PreservedAnalyses LowerInvokePass::run(Function &F,
                                       FunctionAnalysisManager &AM) {
  bool changed = lowerInvokeImpl(F);
  if (!changed)
    return PreservedAnalyses::all();
  return PreservedAnalyses::none();
}

