TEST_F(P2pTests, P2pSendProxyProgress_AlternativeImplementation) {
  // Initialize proxy progress tracking with alternative structure
  struct ncclProxyArgs progressArgs;
  memset(&progressArgs, 0, sizeof(progressArgs));

  progressArgs.state = ncclProxyOpReady;
  progressArgs.protocol = NCCL_PROTO_SIMPLE;
  progressArgs.nsubs = 1;
  progressArgs.chunkSteps = 1;
  progressArgs.sliceSteps = 1;

  // Setup sub-operation parameters
  progressArgs.subs[0].nsteps = 4;
  progressArgs.subs[0].connection = &connection;

  // Alternative initialization approach using direct assignment
  int stepCounter = 0;
  int totalSteps = progressArgs.subs[0].nsteps;

  // Test initial state verification
  ncclResult_t status = p2pSendProxyProgress(&proxyState, &progressArgs);
  EXPECT_EQ(status, ncclSuccess);
  EXPECT_EQ(progressArgs.state, ncclProxyOpProgress);
  EXPECT_EQ(progressArgs.subs[0].base, 0);
  EXPECT_EQ(progressArgs.subs[0].posted, 0);
  EXPECT_EQ(progressArgs.subs[0].transmitted, 0);
  EXPECT_EQ(progressArgs.subs[0].done, 0);

  // Process each step with alternative loop structure
  while (stepCounter < totalSteps) {
    // Update receive memory tail for this iteration
    proxyInfo->ceRecvMem->tail = stepCounter + 1;

    // Set up buffer size per step
    int fifoIndex = stepCounter % NCCL_STEPS;
    proxyInfo->ceRecvMem->connFifo[fifoIndex].size = 
        proxyState.buffSizes[NCCL_PROTO_SIMPLE] / NCCL_STEPS;

    // Execute first progress pass
    status = p2pSendProxyProgress(&proxyState, &progressArgs);
    EXPECT_EQ(status, ncclSuccess);

    // Synchronize stream for current operation
    hipStreamSynchronize(proxyInfo->stream);

    // Execute second progress pass to verify completion
    status = p2pSendProxyProgress(&proxyState, &progressArgs);
    EXPECT_EQ(status, ncclSuccess);

    // Verify advancement in transmission metrics
    EXPECT_GE(progressArgs.subs[0].transmitted, stepCounter + 1);
    EXPECT_GE(progressArgs.subs[0].done, stepCounter + 1);

    stepCounter++;
  }

  // Verify final state after all steps completed
  EXPECT_EQ(progressArgs.state, ncclProxyOpNone);
  EXPECT_EQ(progressArgs.subs[0].transmitted, progressArgs.subs[0].nsteps);
  EXPECT_EQ(progressArgs.subs[0].done, progressArgs.subs[0].nsteps);
  EXPECT_EQ(progressArgs.done, progressArgs.nsubs);

  // Validate shared memory receive memory tail update
  EXPECT_EQ(proxyInfo->shm->recvMem.tail,
            progressArgs.subs[0].base + progressArgs.subs[0].done);
}

