#include <iostream>
#include <vector>
#include <map>
#include <stack>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> arr(n + 1, 0); // 1-indexed array initialized to 0
    map<int, int> firstOccurrence; // Stores earliest known position of each value

    // Stack stores intervals [l, r] as pairs
    stack<pair<int, int>> intervals;
    intervals.push({1, n});

    while (!intervals.empty()) {
        auto [l, r] = intervals.top();
        intervals.pop();

        // Skip already-filled segments
        while (l <= r && arr[l] != 0) ++l;
        while (r >= l && arr[r] != 0) --r;

        if (l > r) continue;

        // Query current segment
        cout << "? " << l << " " << r << "\n";
        int val, freq;
        cin >> val >> freq;

        if (val == -1) return 0; // Error condition

        // Full segment is this value
        if (freq == r - l + 1) {
            for (int i = l; i <= r; ++i) {
                arr[i] = val;
            }
            firstOccurrence[val] = l;
            continue;
        }

        // Try anchor optimization if we've seen this value before
        if (firstOccurrence.count(val)) {
            int anchorPos = firstOccurrence[val];

            if (anchorPos < l) {
                // Value appears left of current range → must start at l
                for (int i = 0; i < freq; ++i) {
                    arr[l + i] = val;
                }
                firstOccurrence[val] = l;
                intervals.push({l + freq, r});
            } else if (anchorPos > r) {
                // Value appears right of current range → must end at r
                for (int i = 0; i < freq; ++i) {
                    arr[r - i] = val;
                }
                firstOccurrence[val] = r;
                intervals.push({l, r - freq});
            } else {
                // Anchor inside range (shouldn't happen due to trimming)
                int mid = (l + r) / 2;
                intervals.push({l, mid});
                intervals.push({mid + 1, r});
            }
        } else {
            // No anchor available → split range
            int mid = (l + r) / 2;
            intervals.push({l, mid});
            intervals.push({mid + 1, r});
        }
    }

    // Output final array
    cout << "! ";
    for (int i = 1; i <= n; ++i) {
        cout << arr[i];
        if (i < n) cout << " ";
    }
    cout << "\n";

    return 0;
}

