    scoped_printer(std::mutex& m) : mtx(m) { mtx.lock(); }
    ~scoped_printer() { mtx.unlock(); }
};

#define HIP_CHECK(CALL)                                                                            \
    do {                                                                                           \
        hipError_t err = (CALL);                                                                   \
        if (err != hipSuccess) {                                                                   \
            scoped_printer p{global_print_mutex};                                                  \
            fprintf(stderr, "%s:%d :: HIP error: %s\n", __FILE__, __LINE__, hipGetErrorString(err)); \
            throw std::runtime_error("HIP call failed");                                           \
        }                                                                                          \
    } while (0)

namespace {
using lock_guard = std::unique_lock<std::mutex>;
std::mutex global_print_mutex;

size_t num_threads      = 2;
size_t num_iterations   = 500;
size_t sync_interval    = 10;
constexpr unsigned tile_size = 32;

void validate_results(int const*, int const*, int, int);
void launch_kernel(hipStream_t, size_t, size_t, int*, int*, int, int);
} // anonymous namespace

__global__ void
transpose_tile(int* __restrict__ input,
               int* __restrict__ output,
               int width,
               int height)
{
    __shared__ int tile[tile_size][tile_size];

    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    if (x < width && y < height) {
        tile[threadIdx.y][threadIdx.x] = input[y * width + x];
    }

    __syncthreads();

    if (x < height && y < width) {
        output[y * height + x] = tile[threadIdx.x][threadIdx.y];
    }
}

void worker_thread(int rank,
                   int tid,
                   hipStream_t stream,
                   int argc,
                   char** argv)
{
    unsigned M = 4960 * 2;
    unsigned N = 4960 * 2;

    if (argc > 2) num_iterations = std::atoll(argv[2]);
    if (argc > 3) sync_interval = std::atoll(argv[3]);

    {
        scoped_printer p{global_print_mutex};
        std::cout << "[transpose][" << rank << "][" << tid << "] Matrix dims: "
                  << M << "x" << N << "\n";
    }

    std::mt19937_64 rng{static_cast<uint64_t>(std::random_device{}()) * (rank + 1) * (tid + 1)};
    std::uniform_int_distribution<int> dist{-500, 500};

    size_t bytes = sizeof(int) * M * N;
    std::vector<int> host_in(M * N), host_out(M * N);

    std::generate(host_in.begin(), host_in.end(), [&]() { return dist(rng); });
    std::fill(host_out.begin(), host_out.end(), 0);

    int* dev_in  = nullptr;
    int* dev_out = nullptr;

    HIP_CHECK(hipMalloc(&dev_in, bytes));
    HIP_CHECK(hipMalloc(&dev_out, bytes));

    HIP_CHECK(hipMemsetAsync(dev_in, 0, bytes, stream));
    HIP_CHECK(hipMemsetAsync(dev_out, 0, bytes, stream));
    HIP_CHECK(hipMemcpyAsync(dev_in, host_in.data(), bytes, hipMemcpyHostToDevice, stream));
    HIP_CHECK(hipStreamSynchronize(stream));

    dim3 grid_dim((M + tile_size - 1) / tile_size, (N + tile_size - 1) / tile_size, 1);
    dim3 block_dim(tile_size, tile_size, 1);

    auto start_time = std::chrono::high_resolution_clock::now();

    for (size_t iter = 0; iter < num_iterations; ++iter) {
        transpose_tile<<<grid_dim, block_dim, 0, stream>>>(dev_in, dev_out, M, N);
        HIP_CHECK(hipGetLastError());
        if ((iter + 1) % sync_interval == 0) {
            HIP_CHECK(hipStreamSynchronize(stream));
        }
    }

    auto end_time = std::chrono::high_resolution_clock::now();
    HIP_CHECK(hipStreamSynchronize(stream));

    HIP_CHECK(hipMemcpyAsync(host_out.data(), dev_out, bytes, hipMemcpyDeviceToHost, stream));
    HIP_CHECK(hipStreamSynchronize(stream));

    double elapsed = std::chrono::duration<double>{end_time - start_time}.count();
    double gbytes  = static_cast<double>(bytes) * num_iterations * 2.0 / (1LL << 30);
    double perf    = gbytes / elapsed;

    {
        scoped_printer p{global_print_mutex};
        std::cout << "[" << rank << "][" << tid << "] Transpose runtime: " << elapsed
                  << " s\nAverage throughput: " << perf << " GB/s\n";
    }

    validate_results(host_in.data(), host_out.data(), M, N);

    HIP_CHECK(hipFree(dev_in));
    HIP_CHECK(hipFree(dev_out));
}

void validate_results(int const* input, int const* output, int rows, int cols)
{
    constexpr int sample_count = 10;
    for (int i = 0; i < sample_count; ++i) {
        int r = rand() % rows;
        int c = rand() % cols;
        if (input[r * cols + c] != output[c * rows + r]) {
            scoped_printer p{global_print_mutex};
            std::cerr << "Mismatch at (" << r << ", " << c << "): "
                      << input[r * cols + c] << " vs " << output[c * rows + r] << "\n";
        }
    }
}

int main(int argc, char** argv)
{
    for (int i = 1; i < argc; ++i) {
        std::string arg{argv[i]};
        if (arg == "?" || arg == "-h" || arg == "--help") {
            scoped_printer p{global_print_mutex};
            std::fprintf(stderr,
                         "Usage: %s [NUM_THREADS (%zu)] [NUM_ITERATIONS (%zu)] "
                         "[SYNC_EVERY_N (%zu)]\n",
                         argv[0],
                         num_threads,
                         num_iterations,
                         sync_interval);
            std::exit(EXIT_SUCCESS);
        }
    }

    if (argc > 1) num_threads = std::atoll(argv[1]);
    if (argc > 2) num_iterations = std::atoll(argv[2]);
    if (argc > 3) sync_interval = std::atoll(argv[3]);

    {
        scoped_printer p{global_print_mutex};
        std::printf("[transpose] Threads: %zu | Iterations: %zu | Sync every %zu\n",
                    num_threads,
                    num_iterations,
                    sync_interval);
    }

    int device_count = 0;
    HIP_CHECK(hipGetDeviceCount(&device_count));
    {
        scoped_printer p{global_print_mutex};
        std::printf("[transpose] Devices detected: %d\n", device_count);
    }

    if (device_count > 0) {
        int dev_id = 0 % device_count;
        HIP_CHECK(hipSetDevice(dev_id));
        {
            scoped_printer p{global_print_mutex};
            std::printf("[transpose] Assigned to device %d\n", dev_id);
        }
    }

    std::vector<hipStream_t> streams(num_threads);
    std::vector<std::thread> workers;

    for (size_t i = 0; i < num_threads; ++i) {
        HIP_CHECK(hipStreamCreate(&streams[i]));
    }

    for (size_t t = 1; t < num_threads; ++t) {
        workers.emplace_back(worker_thread, 0, static_cast<int>(t), streams[t], argc, argv);
    }

    worker_thread(0, 0, streams[0], argc, argv);

    for (auto& th : workers) {
        th.join();
    }

    for (size_t i = 0; i < num_threads; ++i) {
        HIP_CHECK(hipStreamDestroy(streams[i]));
    }

    HIP_CHECK(hipDeviceSynchronize());
    HIP_CHECK(hipDeviceReset());

    return 0;
}

