unsigned int NatSubUnderflowSafe::sub_checked(const unsigned int _x0,
                                              const unsigned int _x1) {
  // If the subtrahend is greater than minuend, return 0 to prevent underflow
  // Otherwise perform normal subtraction
  return (_x1 > _x0) ? 0 : (_x0 - _x1);
}

unsigned int NatSubUnderflowSafe::sub_alt(const unsigned int a,
                                          const unsigned int b) {
  // Alternative implementation using standard library function for safe subtraction
  // Returns 0 if b > a, otherwise returns the difference
  return (b > a) ? 0 : (a - b);
}

