// Wrapper function for the madvise system call
int __madvise_impl(void *address, size_t length, int hint)
{
	return syscall(SYS_madvise, address, length, hint);
}

// Provide an alias so that calls to 'madvise' resolve to our implementation
weak_alias(__madvise_impl, madvise);

