DiskArrayCollection::DiskArrayCollection(FileHandle& fileHandle, ShadowFile& shadowFile,
    bool bypassShadowing)
    : fileHandle(fileHandle), shadowFile{shadowFile}, bypassShadowing{bypassShadowing},
      numHeaders{0} {
    // Initialize both read/write header stacks with one empty header page each
    headersForReadTrx.emplace_back(std::make_unique<HeaderPage>());
    headersForWriteTrx.emplace_back(std::make_unique<HeaderPage>());
    headerPagesOnDisk = 0;
}

DiskArrayCollection::DiskArrayCollection(FileHandle& fileHandle, ShadowFile& shadowFile,
    page_idx_t firstHeaderPage, bool bypassShadowing)
    : fileHandle(fileHandle), shadowFile{shadowFile}, bypassShadowing{bypassShadowing},
      numHeaders{0} {
    // Load all header pages from disk into memory using optimistic reads
    page_idx_t currentPageIdx = firstHeaderPage;
    while (currentPageIdx != INVALID_PAGE_IDX) {
        std::unique_ptr<HeaderPage> loadedPage;
        page_idx_t nextIdx = INVALID_PAGE_IDX;

        fileHandle.optimisticReadPage(currentPageIdx, [&](auto* frame) {
            auto* diskPage = reinterpret_cast<HeaderPage*>(frame);
            loadedPage = std::make_unique<HeaderPage>(*diskPage);
            nextIdx = diskPage->nextHeaderPage;
        });

        if (!loadedPage) {
            throw RuntimeException("Failed to load header page from disk.");
        }

        numHeaders += loadedPage->numHeaders;
        headersForReadTrx.push_back(std::make_unique<HeaderPage>(*loadedPage));
        headersForWriteTrx.push_back(std::move(loadedPage));

        currentPageIdx = nextIdx;
    }
    headerPagesOnDisk = headersForReadTrx.size();
}

void DiskArrayCollection::checkpoint(page_idx_t firstHeaderPage, PageAllocator& pageAllocator) {
    page_idx_t currentDiskPage = firstHeaderPage;

    for (size_t memPageIdx = 0; memPageIdx < headersForWriteTrx.size(); ++memPageIdx) {
        // Allocate new header page if needed before writing next one
        if (headersForWriteTrx[memPageIdx]->nextHeaderPage == INVALID_PAGE_IDX &&
            memPageIdx + 1 < headersForWriteTrx.size()) {
            populateNextHeaderPage(pageAllocator, memPageIdx);
        }

        // Only persist if changed or never written before
        bool needsUpdate = (memPageIdx >= headerPagesOnDisk) ||
                           (*headersForWriteTrx[memPageIdx] != *headersForReadTrx[memPageIdx]);

        if (needsUpdate) {
            ShadowUtils::updatePage(*pageAllocator.getDataFH(), currentDiskPage,
                true /*full-page write*/, shadowFile, [&](auto* targetFrame) {
                    memcpy(targetFrame, headersForWriteTrx[memPageIdx].get(), sizeof(HeaderPage));
                    if constexpr (sizeof(HeaderPage) < LBUG_PAGE_SIZE) {
                        std::fill(targetFrame + sizeof(HeaderPage),
                                  targetFrame + LBUG_PAGE_SIZE, 0);
                    }
                });
        }

        currentDiskPage = headersForWriteTrx[memPageIdx]->nextHeaderPage;
    }

    headerPagesOnDisk = headersForWriteTrx.size();
}

void DiskArrayCollection::populateNextHeaderPage(PageAllocator& pageAllocator,
    common::page_idx_t memPageIdx) {
    const page_idx_t newPage = pageAllocator.allocatePage();

    // Update both versions: write-trx and read-trx (for future checkpoint consistency)
    headersForWriteTrx[memPageIdx]->nextHeaderPage = newPage;
    headersForReadTrx[memPageIdx]->nextHeaderPage = newPage;
}

size_t DiskArrayCollection::addDiskArray() {
    const size_t arrayId = numHeaders++;
    const size_t pageSlot = numHeaders % HeaderPage::NUM_HEADERS_PER_PAGE;

    // Ensure we have enough header pages allocated in memory
    if (pageSlot >= headersForWriteTrx.size()) {
        headersForWriteTrx.emplace_back(std::make_unique<HeaderPage>());
        headersForReadTrx.emplace_back(std::make_unique<HeaderPage>());
    }

    auto& targetPage = *headersForWriteTrx[pageSlot];
    DASSERT(targetPage.numHeaders < HeaderPage::NUM_HEADERS_PER_PAGE);

    const size_t slotInPage = targetPage.numHeaders++;
    targetPage.headers[slotInPage] = DiskArrayHeader{};
    headersForReadTrx[pageSlot]->numHeaders++;

    return arrayId;
}

void DiskArrayCollection::reclaimStorage(PageAllocator& pageAllocator,
    common::page_idx_t firstHeaderPage) const {
    page_idx_t currentPage = firstHeaderPage;

    for (size_t i = 0; i < headersForReadTrx.size(); ++i) {
        if (currentPage == INVALID_PAGE_IDX) {
            break;
        }
        pageAllocator.freePage(currentPage);
        currentPage = headersForReadTrx[i]->nextHeaderPage;
    }
}

