// Command-line options — same as original, just reordered and slightly renamed
static cl::opt<std::string>
OutPath("o", cl::desc("Output filename"), cl::value_desc("filename"),
        cl::init("-"));
static cl::opt<std::string>
DepPath("d", cl::desc("Dependency filename"), cl::value_desc("filename"),
        cl::init(""));
static cl::opt<std::string>
InPath(cl::Positional, cl::desc("<input file>"), cl::init("-"));
static cl::list<std::string>
IncDirs("I", cl::desc("Directory of include files"), cl::value_desc("directory"), cl::Prefix);
static cl::list<std::string>
MacroDefs("D", cl::desc("Name of the macro to be defined"), cl::value_desc("macro name"), cl::Prefix);
static cl::opt<bool>
OnlyIfChanged("write-if-changed", cl::desc("Only write output if it changed"));
static cl::opt<bool>
TimePhases("time-phases", cl::desc("Time phases of parser and backend"));
static cl::opt<bool> SuppressUnusedTemplateWarnings(
    "no-warn-on-unused-template-args",
    cl::desc("Disable unused template argument warnings."));

// Helper: report an error message and exit
[[noreturn]] static int emitError(const char *progName, const Twine &msg) {
  errs() << progName << ": " << msg;
  errs().flush();
  ::exit(1);
}

// Helper: manage dependency file writing
struct DepWriter {
  const std::string &outputPath;
  const std::string &depPath;
  const SmallVectorImpl<std::string> &deps;

  int write(const char *argv0) {
    if (outputPath == "-")
      return emitError(argv0, "the option -d must be used together with -o\n");

    std::error_code ec;
    ToolOutputFile depFile(depPath, ec, sys::fs::OF_Text);
    if (ec)
      return emitError(argv0, "error opening " + depPath + ": " + ec.message() + "\n");

    depFile.os() << outputPath << ":";
    for (const auto &d : deps)
      depFile.os() << ' ' << d;
    depFile.os() << '\n';
    depFile.keep();
    return 0;
  }
};

int llvm::TableGenMain(const char *argv0,
                       std::function<int(raw_ostream &, RecordKeeper &)> MainFn) {
  RecordKeeper records;
  if (TimePhases)
    records.startPhaseTiming();

  // Parse input file
  records.startTimer("Parse, build records");
  auto bufferResult = MemoryBuffer::getFileOrSTDIN(InPath, /*IsText=*/true);
  if (!bufferResult) {
    return emitError(argv0, "Could not open input file '" + InPath + "': " +
                            bufferResult.getError().message() + "\n");
  }

  records.saveInputFilename(InPath);
  SrcMgr.AddNewSourceBuffer(std::move(*bufferResult), SMLoc());
  SrcMgr.setIncludeDirs(IncDirs);

  TGParser parser(SrcMgr, MacroDefs, records, SuppressUnusedTemplateWarnings);
  if (parser.ParseFile())
    return 1;

  records.stopTimer();

  // Run backend
  records.startBackendTimer("Backend overall");
  std::ostringstream oss;
  raw_os_ostream outStream(oss);

  unsigned status = 0;
  TableGen::Emitter::FnT actionFn = TableGen::Emitter::Action->getValue();
  if (actionFn)
    actionFn(records, outStream);
  else if (MainFn)
    status = MainFn(outStream, records);
  else
    return emitError(argv0, "No emitter or custom action specified.\n");

  records.stopBackendTimer();
  if (status)
    return 1;

  // Ensure dependency file is written regardless of later errors
  if (!DepPath.empty()) {
    DepWriter dw{OutPath, DepPath, parser.getDependencies()};
    if (int ret = dw.write(argv0))
      return ret;
  }

  // Prepare final output
  records.startTimer("Write output");
  bool shouldWrite = true;
  if (OnlyIfChanged) {
    if (auto existing = MemoryBuffer::getFile(OutPath, /*IsText=*/true)) {
      if (existing.get()->getBuffer() == oss.str())
        shouldWrite = false;
    }
  }

  if (shouldWrite) {
    std::error_code ec;
    ToolOutputFile outputFile(OutPath, ec, sys::fs::OF_Text);
    if (ec)
      return emitError(argv0, "error opening " + OutPath + ": " + ec.message() + "\n");

    outputFile.os() << oss.str();
    if (ErrorsPrinted == 0)
      outputFile.keep();
  }

  records.stopTimer();
  records.stopPhaseTiming();

  if (ErrorsPrinted > 0)
    return emitError(argv0, Twine(ErrorsPrinted) + " errors.\n");

  return 0;
}

#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <iostream>

// Helper functions with slightly different names and behavior
void display_message() {
    std::cout << "displaying message!" << std::endl;
}

void announce_another_message() {
    std::cout << "announcing another message!" << std::endl;
}

// Modified class with same structure but renamed members
struct data_container {
    int value = 30;
    double compute_value() {
        return 24.5;
    }
};

int main(int, char*[]) {
    std::cout << "=== function bindings (all variants) ===" << std::endl;

    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    // Insert an instance of data_container into Lua environment
    lua_vm.set("dc", data_container());

    // Bind regular functions using different syntaxes
    lua_vm["func_a"] = display_message;
    lua_vm.set_function("func_b", &announce_another_message);

    // Bind member function only
    lua_vm["mem_func_1"] = &data_container::compute_value;

    // Bind member function with pre-bound instance
    lua_vm.set_function(
        "mem_func_2", &data_container::compute_value, data_container{});

    // Bind member variable as getter/setter function
    lua_vm["var_get_1"] = &data_container::value;

    // Bind member variable with pre-bound instance for direct access
    lua_vm.set_function(
        "var_get_2", &data_container::value, data_container{});

    lua_vm.script(R"(
        func_a() -- displays message!
        func_b() -- announces another message!

        -- requires explicit instance when not bound
        print(mem_func_1(dc)) -- 24.5

        -- no instance needed: already bound internally
        print(mem_func_2()) -- 24.5

        -- needs instance for unbound variable access
        print(var_get_1(dc)) -- 30

        -- no instance required: bound at registration time
        print(var_get_2()) -- 30

        -- can assign new values via unbound accessor
        var_get_1(dc, 212)

        -- can assign new values via bound accessor
        var_get_2(254)

        print(var_get_1(dc)) -- 212
        print(var_get_2())   -- 254
    )");

    std::cout << std::endl;
    return 0;
}

