namespace {

// Helper to validate version fields against expected constants
void check_version(const char* name,
                   const auto& actual,
                   uint32_t expected_major,
                   size_t expected_minor,
                   uint32_t expected_step) {
    EXPECT_EQ(actual.major_id, expected_major) << " for " << name;
    EXPECT_EQ(actual.minor_id, expected_minor) << " for " << name;
    EXPECT_EQ(actual.step_id, expected_step) << " for " << name;
}

