TEST(hsa, tables) {
    using namespace rocprofiler::hsa;

    // Retrieve all HSA API tables
    auto ver_info = get_table_version();
    auto* core_tbl     = get_core_table();
    auto* amd_ext_tbl  = get_amd_ext_table();
    auto* fini_ext_tbl = get_fini_ext_table();
    auto* img_ext_tbl  = get_img_ext_table();
    auto* amd_tool_tbl = get_amd_tool_table();

#if ROCPROFILER_SDK_HSA_PC_SAMPLING > 0
    auto* pcs_ext_tbl = get_pc_sampling_ext_table();
#endif

    // Get full table instance
    auto full_table = get_table();

    //------------------------------------------------------------------------//
    // Validate each table's version matches HSA header definitions
    //------------------------------------------------------------------------//
    check_version("HSA API Table", ver_info,
                  HSA_API_TABLE_MAJOR_VERSION,
                  sizeof(hsa_api_table_t),
                  HSA_API_TABLE_STEP_VERSION);

    check_version("Core Table", core_tbl->version,
                  HSA_CORE_API_TABLE_MAJOR_VERSION,
                  sizeof(hsa_core_table_t),
                  HSA_CORE_API_TABLE_STEP_VERSION);

    check_version("AMD Extension Table", amd_ext_tbl->version,
                  HSA_AMD_EXT_API_TABLE_MAJOR_VERSION,
                  sizeof(hsa_amd_ext_table_t),
                  HSA_AMD_EXT_API_TABLE_STEP_VERSION);

    check_version("Finalizer Extension Table", fini_ext_tbl->version,
                  HSA_FINALIZER_API_TABLE_MAJOR_VERSION,
                  sizeof(hsa_fini_ext_table_t),
                  HSA_FINALIZER_API_TABLE_STEP_VERSION);

    check_version("Image Extension Table", img_ext_tbl->version,
                  HSA_IMAGE_API_TABLE_MAJOR_VERSION,
                  sizeof(hsa_img_ext_table_t),
                  HSA_IMAGE_API_TABLE_STEP_VERSION);

    check_version("AMD Tools Table", amd_tool_tbl->version,
                  HSA_TOOLS_API_TABLE_MAJOR_VERSION,
                  sizeof(hsa_amd_tool_table_t),
                  HSA_TOOLS_API_TABLE_STEP_VERSION);

#if ROCPROFILER_SDK_HSA_PC_SAMPLING > 0
    check_version("PC Sampling Extension Table", pcs_ext_tbl->version,
                  HSA_PC_SAMPLING_API_TABLE_MAJOR_VERSION,
                  sizeof(hsa_pc_sampling_ext_table_t),
                  HSA_PC_SAMPLING_API_TABLE_STEP_VERSION);
#endif

    //------------------------------------------------------------------------//
    // Cross-check consistency between retrieved components and full table
    //------------------------------------------------------------------------//
    EXPECT_EQ(full_table.version.major_id, ver_info.major_id);
    EXPECT_EQ(full_table.version.minor_id, ver_info.minor_id);
    EXPECT_EQ(full_table.version.step_id, ver_info.step_id);

    EXPECT_EQ(full_table.core_, core_tbl);
    EXPECT_EQ(full_table.amd_ext_, amd_ext_tbl);
    EXPECT_EQ(full_table.finalizer_ext_, fini_ext_tbl);
    EXPECT_EQ(full_table.image_ext_, img_ext_tbl);
}

