// Anchor virtual methods in base classes
void MachineModuleInfoMachO::anchor() {}
void MachineModuleInfoELF::anchor() {}
void MachineModuleInfoCOFF::anchor() {}
void MachineModuleInfoWasm::anchor() {}

// Type alias for symbol-stub pair
using SymbolStubPair = std::pair<MCSymbol *, MachineModuleInfoImpl::StubValueTy>;

// Comparison function to sort stub pairs by symbol name (lexicographically ascending)
static int compareBySymbolName(const SymbolStubPair *A, const SymbolStubPair *B) {
  return A->first->getName().compare(B->first->getName());
}

// Extract and sort stub entries from a DenseMap
MachineModuleInfoImpl::SymbolListTy MachineModuleInfoImpl::getSortedStubs(
    DenseMap<MCSymbol *, MachineModuleInfoImpl::StubValueTy> &Stubs) {
  // Initialize list with all entries from the map
  SymbolListTy Entries(Stubs.begin(), Stubs.end());

  // Sort the list using the comparison function
  array_pod_sort(Entries.begin(), Entries.end(), compareBySymbolName);

  // Clear the original map after extraction
  Stubs.clear();

  return Entries;
}

