// Helper structure to represent GUID components in little-endian format
struct GuidLayout {
  support::ulittle32_t Part1;
  support::ulittle16_t Part2;
  support::ulittle16_t Part3;
  support::ubig64_t Part4;
};

GuidAdapter::GuidAdapter(StringRef InputString)
    : FormatAdapter(ArrayRef(InputString.data(), InputString.size())) {}

GuidAdapter::GuidAdapter(ArrayRef<uint8_t> Bytes)
    : FormatAdapter(std::move(Bytes)) {}

// Format a GUID as {XXXXXXXX-XXXX-XXXX-XXXX-XXXXXXXXXXXX}
// Validates expected size and formats each component with proper padding
void GuidAdapter::format(raw_ostream &Output, StringRef /*Style*/) {
  assert(Item.size() == 16 && "GUID must be exactly 16 bytes");

  const GuidLayout *Layout = reinterpret_cast<const GuidLayout *>(Item.data());

  // Extract and format each field with uppercase hex and fixed width
  uint32_t Field1 = Layout->Part1;
  uint16_t Field2 = Layout->Part2;
  uint16_t Field3 = Layout->Part3;
  uint64_t Field4High = Layout->Part4 >> 48;
  uint64_t Field4Low = Layout->Part4 & ((1ULL << 48) - 1);

  Output << '{'
         << format_hex_no_prefix(Field1, 8, true) << '-'
         << format_hex_no_prefix(Field2, 4, true) << '-'
         << format_hex_no_prefix(Field3, 4, true) << '-'
         << format_hex_no_prefix(Field4High, 4, true) << '-'
         << format_hex_no_prefix(Field4Low, 12, true)
         << '}';
}

// Overload stream operator for GUID type
raw_ostream &llvm::codeview::operator<<(raw_ostream &OS, const GUID &Guid) {
  codeview::detail::GuidAdapter Formatter(Guid.Guid);
  Formatter.format(OS, "");
  return OS;
}

