PreservedAnalyses KCFIPass::run(Function &F, FunctionAnalysisManager &AM) {
  Module *M = F.getParent();
  if (!M->getModuleFlag("kcfi"))
    return PreservedAnalyses::all();

  // Collect all call instructions that carry a KCFI operand bundle.
  std::vector<CallInst *> targetCalls;
  for (auto &I : make_range(inst_begin(F), inst_end(F))) {
    if (CallInst *CI = dyn_cast<CallInst>(&I)) {
      if (CI->getOperandBundle(LLVMContext::OB_kcfi))
        targetCalls.push_back(CI);
    }
  }

  if (targetCalls.empty())
    return PreservedAnalyses::all();

  LLVMContext &Ctx = M->getContext();
  Triple TargetTriple(M->getTargetTriple());

  // Reject incompatible patchable-function-entry settings
  if (F.hasFnAttribute("patchable-function-prefix")) {
    Ctx.diagnose(Diagnostic_KCFI_Incompat(
        "-fpatchable-function-entry=N,M with M>0 is incompatible with -fsanitize=kcfi "
        "on this architecture"));
  }

  Type *Int32Ty = Type::getInt32Ty(Ctx);
  MDNode *ColdBranchWeights = MDBuilder(Ctx).createBranchWeights(1, 1048575);

  for (CallInst *callSite : targetCalls) {
    // Extract expected hash from operand bundle
    OperandBundleDefBasesTy OpBundles = callSite->getOperandBundles();
    uint32_t expectedHash = 0;
    for (const auto &bundle : OpBundles) {
      if (bundle.getBundleName() == LLVMContext::OB_kcfi) {
        const auto &inputs = bundle.getInputs();
        if (!inputs.empty()) {
          ConstantInt *hashVal = cast<ConstantInt>(inputs[0]);
          expectedHash = static_cast<uint32_t>(hashVal->getZExtValue());
        }
        break;
      }
    }

    // Remove the KCFI operand bundle and replace original call
    CallBase *updatedCall =
        CallBase::removeOperandBundle(callSite, LLVMContext::OB_kcfi, callSite);
    if (!updatedCall) {
      llvm_unreachable("Failed to remove KCFI operand bundle");
    }

    updatedCall->copyMetadata(*callSite);
    callSite->replaceAllUsesWith(updatedCall);
    callSite->eraseFromParent();

    // Only insert checks for indirect calls
    if (!updatedCall->isIndirectCall())
      continue;

    IRBuilder<> builder(updatedCall);
    Value *calleePtr = updatedCall->getCalledOperand();

    // For ARM/Thumb targets: mask off the LSB before hashing (alignment fix)
    if (TargetTriple.isARM() || TargetTriple.isThumb()) {
      Value *addrAsInt = builder.CreatePtrToInt(calleePtr, Int32Ty);
      Value *maskedAddr = builder.CreateAnd(addrAsInt, ConstantInt::get(Int32Ty, ~1U));
      calleePtr = builder.CreateIntToPtr(maskedAddr, calleePtr->getType());
    }

    // Compute GEP to hash location (one int32 before function pointer)
    Value *hashAddr = builder.CreateConstInBoundsGEP1_32(Int32Ty, calleePtr, -1);
    LoadInst *loadedHash = builder.CreateLoad(Int32Ty, hashAddr);

    // Compare loaded hash vs expected
    Value *mismatchTest = builder.CreateICmpNE(loadedHash,
                                               ConstantInt::get(Int32Ty, expectedHash));

    // Split basic block and insert conditional trap
    BasicBlock *originalBB = updatedCall->getParent();
    BasicBlock *checkBB = originalBB->splitBasicBlock(updatedCall, "kcfi.check");
    BasicBlock *trapBB = BasicBlock::Create(Ctx, "kcfi.trap", &F, checkBB);

    // Create conditional branch to trap block
    BranchInst *branch = BranchInst::Create(checkBB, trapBB, mismatchTest, originalBB);
    branch->setMetadata(LLVMContext::MD_prof, ColdBranchWeights);

    // Insert trap in trap block
    builder.SetInsertPoint(trapBB);
    Function *trapFn = Intrinsic::getDeclaration(M, Intrinsic::debugtrap);
    builder.CreateCall(trapFn);
    builder.CreateUnreachable();

    ++NumKCFIChecksInserted;
  }

  return PreservedAnalyses::none();
}

