void UIScene_SettingsUIMenu::handleInput(int controllerId, int inputKey, bool isRepeat, bool isPressed, bool isReleased, bool &isHandled)
{
    ui.AnimateKeyPress(controllerId, inputKey, isRepeat, isPressed, isReleased);

    switch (inputKey)
    {
    case ACTION_MENU_CANCEL:
        if (isPressed)
        {
            // Commit checkbox states to persistent settings
            app.SetGameSettings(m_iPad, eGameSetting_DisplayHUD, m_checkboxDisplayHUD.IsChecked() ? 1 : 0);
            app.SetGameSettings(m_iPad, eGameSetting_DisplayHand, m_checkboxDisplayHand.IsChecked() ? 1 : 0);
            app.SetGameSettings(m_iPad, eGameSetting_DisplaySplitscreenGamertags, m_checkboxShowSplitscreenGamertags.IsChecked() ? 1 : 0);
            app.SetGameSettings(m_iPad, eGameSetting_DeathMessages, m_checkboxDisplayDeathMessages.IsChecked() ? 1 : 0);
            app.SetGameSettings(m_iPad, eGameSetting_AnimatedCharacter, m_checkboxDisplayAnimatedCharacter.IsChecked() ? 1 : 0);

            // Check if split-screen orientation changed
            int oldSplitMode = app.GetGameSettings(m_iPad, eGameSetting_SplitScreenVertical);
            int newSplitMode = m_checkboxSplitscreen.IsChecked() ? 1 : 0;

            if (oldSplitMode != newSplitMode)
            {
                app.SetGameSettings(m_iPad, eGameSetting_SplitScreenVertical, newSplitMode);

                int playerCount = app.GetLocalPlayerCount();
                if (playerCount == 2)
                {
                    ui.CloseAllPlayersScenes();
                }
                else
                {
                    navigateBack();
                }
            }
            else
            {
                navigateBack();
            }

            isHandled = true;
        }
        break;

    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
        sendInputToMovie(inputKey, isRepeat, isPressed, isReleased);
        break;

    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_LEFT:
    case ACTION_MENU_RIGHT:
        sendInputToMovie(inputKey, isRepeat, isPressed, isReleased);
        break;
    }
}

void UIScene_SettingsUIMenu::handleSliderMove(F64 sliderIdentifier, F64 newValue)
{
    WCHAR tempBuffer[256];
    int adjustedValue = static_cast<int>(newValue);

    switch (static_cast<int>(sliderIdentifier))
    {
    case eControl_UISize:
        m_sliderUISize.handleSliderMove(adjustedValue);
        swprintf(tempBuffer, 256, L"%ls: %d", app.GetString(IDS_SLIDER_UISIZE), adjustedValue);
        m_sliderUISize.setLabel(tempBuffer);

        if (adjustedValue != app.GetGameSettings(m_iPad, eGameSetting_UISize) + 1)
        {
            app.SetGameSettings(m_iPad, eGameSetting_UISize, adjustedValue - 1);
            ui.UpdateSelectedItemPos(m_iPad);
        }
        break;

    case eControl_UISizeSplitscreen:
        m_sliderUISizeSplitscreen.handleSliderMove(adjustedValue);
        swprintf(tempBuffer, 256, L"%ls: %d", app.GetString(IDS_SLIDER_UISIZESPLITSCREEN), adjustedValue);
        m_sliderUISizeSplitscreen.setLabel(tempBuffer);

        if (adjustedValue != app.GetGameSettings(m_iPad, eGameSetting_UISizeSplitscreen) + 1)
        {
            app.SetGameSettings(m_iPad, eGameSetting_UISizeSplitscreen, adjustedValue - 1);
            ui.UpdateSelectedItemPos(m_iPad);
        }
        break;
    }
}

