//////////////////////////////////////////////////////////////////////////////////////////////
// IDisplayClusterInputDevice
//////////////////////////////////////////////////////////////////////////////////////////////

void FDisplayClusterVrpnKeyboardInputDevice::PreUpdate()
{
	// Shift current new states to old before processing new input
	TArray<int32> KeyIndices;
	DeviceData.GetKeys(KeyIndices);

	for (int32 Idx = 0; Idx < KeyIndices.Num(); ++Idx)
	{
		const int32 ButtonIndex = KeyIndices[Idx];
		FDisplayClusterVrpnKeyboardButtonState* StatePtr = DeviceData.Find(ButtonIndex);
		if (StatePtr)
		{
			StatePtr->BtnStateOld = StatePtr->BtnStateNew;
		}
	}
}

void FDisplayClusterVrpnKeyboardInputDevice::Update()
{
	if (DevImpl.IsValid())
	{
		UE_LOG(LogDisplayClusterInputVRPN, Verbose, TEXT("Updating device: %s"), *GetId());
		DevImpl->mainloop();
	}
}

bool FDisplayClusterVrpnKeyboardInputDevice::Initialize()
{
	// Create VRPN remote button handler
	const FString VrpnAddress = Address;
	DevImpl = MakeUnique<vrpn_Button_Remote>(TCHAR_TO_UTF8(*VrpnAddress));

	// Set up callback for button changes
	if (DevImpl->register_change_handler(this, &FDisplayClusterVrpnKeyboardInputDevice::HandleKeyboardDevice) != 0)
	{
		UE_LOG(LogDisplayClusterInputVRPN, Error, TEXT("%s - failed to register VRPN change handler"), *ToString());
		return false;
	}

	// Proceed with base initialization
	return FDisplayClusterVrpnKeyboardInputDataHolder::Initialize();
}

//////////////////////////////////////////////////////////////////////////////////////////////
// FDisplayClusterVrpnKeyboardInputDevice
//////////////////////////////////////////////////////////////////////////////////////////////

void VRPN_CALLBACK FDisplayClusterVrpnKeyboardInputDevice::HandleKeyboardDevice(void* UserData, vrpn_BUTTONCB const* ButtonEvent)
{
	check(UserData);
	FDisplayClusterVrpnKeyboardInputDevice* DevInstance = static_cast<FDisplayClusterVrpnKeyboardInputDevice*>(UserData);

	const int32 ButtonNum = ButtonEvent->button;
	FDisplayClusterVrpnKeyboardButtonState* EntryPtr = DevInstance->DeviceData.Find(ButtonNum);

	if (!EntryPtr)
	{
		EntryPtr = &DevInstance->DeviceData.Add(ButtonNum);
		// Initialize old state explicitly
		EntryPtr->BtnStateOld = false;
	}

	// Update new state based on VRPN integer value (0 = released, non-zero = pressed)
	EntryPtr->BtnStateNew = (ButtonEvent->state != 0);

	UE_LOG(LogDisplayClusterInputVRPN, VeryVerbose, TEXT("Keyboard %s:%d - %d"), *DevInstance->GetId(), ButtonNum, ButtonEvent->state);
}

#include "synth/SampleZone.h"
#include "obj/Object.h"
#include "synth/Stream.h"
#include "utl/BinStream.h"

SampleZone::SampleZone(Hmx::Object *owner)
    : mSample(owner), mVol(0.0f), mPanoramic(0.0f), mBaseNote(0x24), mLowNote(0),
      mHighNote(0x7f), mLowVelocity(0), mHighVelocity(0x7f), mEffectCore(kFXCoreNone) {}

void SampleZone::Store(BinStream &stream) const {
    stream << mSample;
    stream << mVol;
    stream << mPanoramic;
    stream << mBaseNote;
    stream << mLowNote;
    stream << mHighNote;
    stream << mEffectCore;
    stream << mADSR;
    stream << mLowVelocity;
    stream << mHighVelocity;
}

void SampleZone::Restore(BinStreamRev &revStream) {
    revStream >> mSample;
    revStream >> mVol;
    revStream >> mPanoramic;
    revStream >> mBaseNote;
    revStream >> mLowNote;
    revStream >> mHighNote;

    int tempFX;
    revStream >> tempFX;
    mEffectCore = static_cast<FXCore>(tempFX);

    revStream >> mADSR;

    if (revStream.rev >= 2) {
        revStream >> mLowVelocity;
        revStream >> mHighVelocity;
    }
}

bool SampleZone::WithinRange(unsigned char note, unsigned char velocity) {
    bool noteCheck = (mLowNote <= note) && (note <= mHighNote);
    bool velCheck = (mLowVelocity <= velocity) && (velocity <= mHighVelocity);
    return noteCheck && velCheck;
}

BinStream &operator<<(BinStream &bs, const SampleZone &sz) {
    sz.Store(bs);
    return bs;
}

BinStreamRev &operator>>(BinStreamRev &d, SampleZone &sz) {
    sz.Restore(d);
    return d;
}

#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;

    char bg_color, island_color;
    int island_count, hole_count;

    // Determine which color should be background based on cost
    if (x < y) {
        bg_color = '@';
        island_color = '.';
        island_count = w;
        hole_count = b - 1;
    } else {
        bg_color = '.';
        island_color = '@';
        island_count = b;
        hole_count = w - 1;
    }

    vector<string> result_grid;

    if (hole_count == 0) {
        // Simple case: no holes needed, just multiple isolated islands
        string row0 = "", row1 = "";

        // Start with background separator
        row0 += bg_color;
        row1 += bg_color;

        // Build M islands separated by background
        for (int i = 0; i < island_count; ++i) {
            row0 += island_color;
            row1 += bg_color;

            row0 += bg_color;
            row1 += bg_color;
        }

        result_grid.push_back(row0);
        result_grid.push_back(row1);
    } else {
        // Complex case: need holes inside islands
        string r0 = "", r1 = "", r2 = "", r3 = "";

        // Initial background column
        r0 += bg_color;
        r1 += bg_color;
        r2 += bg_color;
        r3 += bg_color;

        // First complex island containing all holes
        // Pattern: top row all island color, middle row alternates island/hole, bottom row all island
        for (int h = 0; h < 2 * hole_count + 1; ++h) {
            r0 += island_color;
            r1 += (h % 2 == 0) ? island_color : bg_color;
            r2 += island_color;
            r3 += bg_color;
        }

        // Background separator after complex island
        r0 += bg_color;
        r1 += bg_color;
        r2 += bg_color;
        r3 += bg_color;

        // Add remaining simple islands (island_count - 1)
        for (int i = 0; i < island_count - 1; ++i) {
            r0 += bg_color;
            r1 += island_color;
            r2 += bg_color;
            r3 += bg_color;

            // Separator column
            r0 += bg_color;
            r1 += bg_color;
            r2 += bg_color;
            r3 += bg_color;
        }

        result_grid.push_back(r0);
        result_grid.push_back(r1);
        result_grid.push_back(r2);
        result_grid.push_back(r3);
    }

    cout << result_grid.size() << " " << result_grid[0].size() << "\n";
    for (const string& line : result_grid) {
        cout << line << "\n";
    }

    return 0;
}

#include "dap/network.h"
#include "dap/io.h"
#include "chan.h"
#include "gmock/gmock.h"
#include "gtest/gtest.h"
#include <chrono>
#include <thread>

namespace {
constexpr int test_port = 19021;

// Helper function to send a null-terminated string over the writer
bool send_message(const std::shared_ptr<dap::Writer>& w, const std::string& msg) {
  return w->write(msg.data(), msg.size()) && w->write("\0", 1);
}

// Helper function to read a null-terminated string from the reader
std::string receive_message(const std::shared_ptr<dap::Reader>& r) {
  char byte;
  std::string result;
  while (r->read(&byte, sizeof(byte)) > 0) {
    if (byte == '\0') {
      break;
    }
    result += byte;
  }
  return r->isOpen() ? result : "<connection closed>";
}
}  // anonymous namespace

TEST(Network, ClientServerCommunication) {
  dap::Chan<bool> completion_flag;
  auto server_instance = dap::net::Server::create();

  if (!server_instance->start(
          test_port,
          [&](const std::shared_ptr<dap::ReaderWriter>& rw) {
            ASSERT_EQ(receive_message(rw), "client to server");
            ASSERT_TRUE(send_message(rw, "server to client"));
            completion_flag.put(true);
          },
          [&](const char* error_msg) { FAIL() << "Server encountered error: " << error_msg; })) {
    FAIL() << "Failed to initialize server";
    return;
  }

  for (int iteration = 0; iteration < 5; ++iteration) {
    auto client_connection = dap::net::connect("localhost", test_port);
    ASSERT_NE(client_connection, nullptr) << "Client connection failed at iteration " << iteration;

    ASSERT_TRUE(send_message(client_connection, "client to server"));
    ASSERT_EQ(receive_message(client_connection), "server to client");
    completion_flag.take();

    std::this_thread::sleep_for(std::chrono::seconds(1));
  }

  server_instance.reset();
}

TEST(Network, ServerRestartFunctionality) {
  dap::Chan<bool> completion_flag;

  auto handle_client = [&](const std::shared_ptr<dap::ReaderWriter>& rw) {
    ASSERT_EQ(receive_message(rw), "client to server");
    ASSERT_TRUE(send_message(rw, "server to client"));
    completion_flag.put(true);
  };

  auto handle_error = [&](const char* error_msg) { FAIL() << "Server error: " << error_msg; };

  auto server = dap::net::Server::create();

  // Initial startup
  if (!server->start(test_port, handle_client, handle_error)) {
    FAIL() << "Initial server startup failed";
    return;
  }

  // Multiple stop calls to verify idempotency
  server->stop();
  server->stop();
  server->stop();

  // Restart server after stopping
  if (!server->start(test_port, handle_client, handle_error)) {
    FAIL() << "Server restart failed";
    return;
  }

  // Test communication with restarted server
  auto client = dap::net::connect("localhost", test_port);
  ASSERT_NE(client, nullptr) << "Connection to restarted server failed";

  ASSERT_TRUE(send_message(client, "client to server"));
  ASSERT_EQ(receive_message(client), "server to client");
  completion_flag.take();

  // Clean shutdown
  server->stop();
  server->stop();
  server->stop();
  server.reset();
}

#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <chrono>
#include <algorithm>
#include <utility>

// Fixed constants as per problem specification
const int N_CONST = 100;
const int L_CONST = 500000;

int N, L; // Will be assigned N_CONST and L_CONST from input
std::vector<int> T;

// Random number generator
std::mt19937 rng;

// Compute total error between expected counts and actual simulation results
long long compute_deviation(const std::vector<int>& transition_map) {
    std::vector<int> visit_counts(N_CONST, 0);
    int current_node = 0;

    for (int week = 0; week < L_CONST; ++week) {
        visit_counts[current_node]++;
        int occurrence = visit_counts[current_node];

        if (occurrence % 2 == 1) {
            current_node = transition_map[current_node * 2];
        } else {
            current_node = transition_map[current_node * 2 + 1];
        }
    }

    long long total_deviation = 0;
    for (int i = 0; i < N_CONST; ++i) {
        total_deviation += std::abs(visit_counts[i] - T[i]);
    }
    return total_deviation;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Initialize RNG with high-resolution clock
    rng.seed(std::chrono::high_resolution_clock::now().time_since_epoch().count());

    // Read input parameters
    std::cin >> N >> L;
    T.resize(N);
    for (int i = 0; i < N; ++i) {
        std::cin >> T[i];
    }

    // Generate initial solution using Largest Remainder Method
    std::vector<int> transition_map(2 * N);
    {
        std::vector<double> ideal_distribution(N);
        for (int i = 0; i < N; ++i) {
            ideal_distribution[i] = static_cast<double>(T[i]) / L * (2 * N);
        }

        std::vector<int> degree_assignment(N, 0);
        int accumulated_degree = 0;
        std::vector<std::pair<double, int>> fractional_parts;
        fractional_parts.reserve(N);

        for (int i = 0; i < N; ++i) {
            degree_assignment[i] = static_cast<int>(std::floor(ideal_distribution[i]));
            accumulated_degree += degree_assignment[i];
            fractional_parts.emplace_back(ideal_distribution[i] - degree_assignment[i], i);
        }

        // Sort descending by fractional part to prioritize distribution
        std::sort(fractional_parts.begin(), fractional_parts.end(),
                  [](const auto& a, const auto& b) { return a.first > b.first; });

        int remaining_slots = 2 * N - accumulated_degree;
        for (int i = 0; i < remaining_slots; ++i) {
            degree_assignment[fractional_parts[i].second]++;
        }

        // Build destination list based on degrees
        std::vector<int> destinations_list;
        destinations_list.reserve(2 * N);
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < degree_assignment[i]; ++j) {
                destinations_list.push_back(i);
            }
        }

        // Shuffle destinations randomly
        std::shuffle(destinations_list.begin(), destinations_list.end(), rng);
        transition_map = destinations_list;
    }

    long long current_cost = compute_deviation(transition_map);
    std::vector<int> best_solution = transition_map;
    long long best_cost = current_cost;

    // Simulated Annealing Optimization
    double max_runtime = 2.8;
    auto start_timestamp = std::chrono::high_resolution_clock::now();

    double initial_temperature = 500.0;
    double final_temperature = 0.1;

    std::uniform_int_distribution<int> move_selector(0, 99);
    std::uniform_int_distribution<int> index_selector(0, 2 * N - 1);
    std::uniform_int_distribution<int> value_selector(0, N - 1);
    std::uniform_real_distribution<double> acceptance_prob(0.0, 1.0);

    while (true) {
        auto current_timestamp = std::chrono::high_resolution_clock::now();
        double elapsed_seconds = std::chrono::duration<double>(current_timestamp - start_timestamp).count();
        if (elapsed_seconds > max_runtime) break;

        // Linear cooling schedule
        double temperature = initial_temperature * (1.0 - elapsed_seconds / max_runtime) +
                            final_temperature * (elapsed_seconds / max_runtime);

        std::vector<int> candidate_map = transition_map;

        int operation_type = move_selector(rng);
        int idx1, idx2;

        if (operation_type < 90) { // Swap operation (90% probability)
            idx1 = index_selector(rng);
            do {
                idx2 = index_selector(rng);
            } while (idx1 == idx2);
            std::swap(candidate_map[idx1], candidate_map[idx2]);
        } else { // Value change operation (10% probability)
            idx1 = index_selector(rng);
            int original_value = candidate_map[idx1];
            do {
                idx2 = value_selector(rng);
            } while (idx2 == original_value);
            candidate_map[idx1] = idx2;
        }

        long long candidate_cost = compute_deviation(candidate_map);

        // Acceptance probability calculation
        double delta = static_cast<double>(current_cost - candidate_cost);
        double accept_chance = std::exp(delta / temperature);

        if (acceptance_prob(rng) < accept_chance) {
            transition_map = candidate_map;
            current_cost = candidate_cost;

            if (current_cost < best_cost) {
                best_cost = current_cost;
                best_solution = transition_map;
            }
        }
    }

    // Output final result
    for (int i = 0; i < N; ++i) {
        std::cout << best_solution[2 * i] << " " << best_solution[2 * i + 1] << "\n";
    }

    return 0;
}

#include "alarm.h"
#include "callbacks.h"
#include "game_functions.h"
#include "zeal.h"

void Alarm::Configure(int minutes, int seconds) {
  if (!is_active) {
    is_active = true;
    total_milliseconds = ((minutes * 60) + seconds) * 1000;
    std::ostringstream message;
    message << "[Alarm] CONFIGURED! (" << minutes << "m" << seconds << "s)" << std::endl;
    Zeal::Game::print_chat(message.str());
  } else {
    Zeal::Game::print_chat("[Alarm] Please stop the running alarm before setting a new one.");
  }
}

void Alarm::Stop(void) {
  if (is_active) {
    is_active = false;
    Zeal::Game::print_chat("[Alarm] STOPPED!");
  } else {
    Zeal::Game::print_chat("[Alarm] No active alarm to stop.");
  }
}

void Alarm::update() {
  if (is_active) {
    if (!timestamp_start) timestamp_start = GetTickCount64();
    if (GetTickCount64() - timestamp_start > total_milliseconds) {
      Zeal::Game::print_chat("[Alarm] FINISHED!");
      is_active = false;
    }
  } else {
    timestamp_start = 0;
  }
}

Alarm::Alarm(ZealService *zeal) {
  zeal->callbacks->AddGeneric([this]() { update(); });
}

