// Print start of a proxy operation event (send or receive)
__hidden void printProxyOpEventHeader(FILE* fh, struct proxyOp* event) {
  if (event->isSend) {
    int postedIdx = PROXY_OP_SEND_STATE_IDX(ncclProfilerProxyOpSendPosted);
    int remFifoWaitIdx = PROXY_OP_SEND_STATE_IDX(ncclProfilerProxyOpSendRemFifoWait);
    int transmittedIdx = PROXY_OP_SEND_STATE_IDX(ncclProfilerProxyOpSendTransmitted);
    int doneIdx = PROXY_OP_SEND_STATE_IDX(ncclProfilerProxyOpSendDone);

    fprintf(fh, "{\"name\": \"%s\", \"cat\": \"PROXY\", \"ph\": \"b\", \"id\": %d, \"pid\": %d, \"tid\": %d, \"ts\": %f, \"args\": {\"Channel\": %d, \"Peer\": %d, \"Steps\": %d, \"ChunkSize\": %d, \"transSize\": %lu, \"POSTED\": {\"step\": %d, \"ts\": %f}, \"REM_FIFO_WAIT\": {\"step\": %d, \"ts\": %f}, \"TRANSMITTED\": {\"step\": %d, \"ts\": %f}, \"DONE\": {\"step\": %d, \"ts\": %f}}},\n",
            "Send", proxyOpEventId, getpid(), 1, event->startTs, 
            event->channelId, event->peer, event->nSteps, event->chunkSize, event->transSize,
            event->states[postedIdx].steps, event->states[postedIdx].timestamp,
            event->states[remFifoWaitIdx].steps, event->states[remFifoWaitIdx].timestamp,
            event->states[transmittedIdx].steps, event->states[transmittedIdx].timestamp,
            event->states[doneIdx].steps, event->states[doneIdx].timestamp);
  } else {
    int postedIdx = PROXY_OP_RECV_STATE_IDX(ncclProfilerProxyOpRecvPosted);
    int receivedIdx = PROXY_OP_RECV_STATE_IDX(ncclProfilerProxyOpRecvReceived);
    int transmittedIdx = PROXY_OP_RECV_STATE_IDX(ncclProfilerProxyOpRecvTransmitted);
    int doneIdx = PROXY_OP_RECV_STATE_IDX(ncclProfilerProxyOpRecvDone);

    fprintf(fh, "{\"name\": \"%s\", \"cat\": \"PROXY\", \"ph\": \"b\", \"id\": %d, \"pid\": %d, \"tid\": %d, \"ts\": %f, \"args\": {\"Channel\": %d, \"Peer\": %d, \"Steps\": %d, \"ChunkSize\": %d, \"transSize\": %lu, \"POSTED\": {\"step\": %d, \"ts\": %f}, \"RECEIVED\": {\"step\": %d, \"ts\": %f}, \"TRANSMITTED\": {\"step\": %d, \"ts\": %f}, \"DONE\": {\"step\": %d, \"ts\": %f}}},\n",
            "Recv", proxyOpEventId, getpid(), 1, event->startTs,
            event->channelId, event->peer, event->nSteps, event->chunkSize, event->transSize,
            event->states[postedIdx].steps, event->states[postedIdx].timestamp,
            event->states[receivedIdx].steps, event->states[receivedIdx].timestamp,
            event->states[transmittedIdx].steps, event->states[transmittedIdx].timestamp,
            event->states[doneIdx].steps, event->states[doneIdx].timestamp);
  }
}

