// Print proxy control state transitions
__hidden void printProxyCtrlEvent(FILE* fh, struct proxyCtrl* event) {
  const char* stateStr;

  if (event->state == ncclProfilerProxyCtrlIdle || event->state == ncclProfilerProxyCtrlActive) {
    stateStr = "Idle";
  } else if (event->state == ncclProfilerProxyCtrlSleep || event->state == ncclProfilerProxyCtrlWakeup) {
    stateStr = "Sleep";
  } else if (event->state == ncclProfilerProxyCtrlAppend || event->state == ncclProfilerProxyCtrlAppendEnd) {
    stateStr = "Append";
  } else {
    stateStr = "Unknown";
  }

  if (event->state == ncclProfilerProxyCtrlAppendEnd) {
    fprintf(fh, "{\"name\": \"%s\", \"cat\": \"PROXY\", \"ph\": \"b\", \"id\": %d, \"pid\": %d, \"tid\": %d, \"ts\": %f, \"args\": {\"appended\": %d}},\n",
            stateStr, proxyCtrlEventId, getpid(), 1, event->startTs, event->appended);
  } else {
    fprintf(fh, "{\"name\": \"%s\", \"cat\": \"PROXY\", \"ph\": \"b\", \"id\": %d, \"pid\": %d, \"tid\": %d, \"ts\": %f},\n",
            stateStr, proxyCtrlEventId, getpid(), 1, event->startTs);
  }

  fprintf(fh, "{\"name\": \"%s\", \"cat\": \"PROXY\", \"ph\": \"e\", \"id\": %d, \"pid\": %d, \"tid\": %d, \"ts\": %f},\n",
          stateStr, proxyCtrlEventId++, getpid(), 1, event->stopTs);
}

// Debug output for event inspection (only compiled when DEBUG_EVENTS is defined)
void debugEvent(void* eHandle, const char* tag) {
#ifdef DEBUG_EVENTS
  char filename[64] = { 0 };
  sprintf(filename, "EventDebug-%d", getpid());
  FILE* fh = fopen(filename, "a+");
  uint8_t type = *(uint8_t *)eHandle;

  if (type == ncclProfileGroup) {
    struct group* event = (struct group *)eHandle;
    fprintf(fh, "Group event %p tag = %s {\n", event, tag);
    fprintf(fh, "  refCount          = %d\n", __atomic_load_n(&event->refCount, __ATOMIC_RELAXED));
    fprintf(fh, "  startTs           = %f\n", event->startTs);
    fprintf(fh, "  stopTs            = %f\n", event->stopTs);
    fprintf(fh, "}\n");
  } else if (type == ncclProfileColl) {
    struct collective* event = (struct collective *)eHandle;
    fprintf(fh, "Collective event %p tag = %s {\n", event, tag);
    fprintf(fh, "  refCount          = %d\n", __atomic_load_n(&event->base.refCount, __ATOMIC_RELAXED));
    fprintf(fh, "  parent            = %p\n", event->base.parent);
    for (int i = 0; i < MAX_CHANNELS; i++) {
      if (event->send[i].type == ncclProfileProxyOp) {
        fprintf(fh, "  send[%d]           = %p\n", i, &event->send[i]);
      }
      if (event->recv[i].type == ncclProfileProxyOp) {
        fprintf(fh, "  recv[%d]           = %p\n", i, &event->recv[i]);
      }
    }
    fprintf(fh, "  startTs           = %f\n", event->base.startTs);
    fprintf(fh, "  stopTs            = %f\n", event->base.stopTs);
    fprintf(fh, "}\n");
  } else if (type == ncclProfileP2p) {
    struct p2p* event = (struct p2p *)eHandle;
    fprintf(fh, "P2p event %p tag = %s {\n", event, tag);
    fprintf(fh, "  refCount          = %d\n", __atomic_load_n(&event->base.refCount, __ATOMIC_RELAXED));
    fprintf(fh, "  parent            = %p\n", event->base.parent);
    fprintf(fh, "  op                = %p\n", &event->op);
    fprintf(fh, "  startTs           = %f\n", event->base.startTs);
    fprintf(fh, "  stopTs            = %f\n", event->base.stopTs);
    fprintf(fh, "}\n");
  } else if (type == ncclProfileProxyOp) {
    struct proxyOp* event = (struct proxyOp *)eHandle;
    fprintf(fh, "ProxyOp event %p tag = %s {\n", event, tag);
    fprintf(fh, "  type              = %s\n", event->isSend ? "Send" : "Recv");
    fprintf(fh, "  channel           = %d\n", event->channelId);
    fprintf(fh, "  parent            = %p\n", event->parent);
    fprintf(fh, "  rank              = %d\n", event->rank);
    fprintf(fh, "  startTs           = %f\n", event->startTs);
    fprintf(fh, "  stopTs            = %f\n", event->stopTs);
    fprintf(fh, "}\n");
  } else if (type == ncclProfileProxyStep) {
    struct proxyStep* event = (struct proxyStep *)eHandle;
    fprintf(fh, "ProxyStep event %p tag = %s {\n", event, tag);
    fprintf(fh, "  type              = %s\n", event->isSend ? "Send" : "Recv");
    fprintf(fh, "  parent            = %p\n", event->parent);
    fprintf(fh, "  startTs           = %f\n", event->startTs);
    fprintf(fh, "  stopTs            = %f\n", event->stopTs);
    fprintf(fh, "}\n");
  }

  fclose(fh);
#endif
}

// Main event printing function that dispatches to appropriate handlers based on event type
void printEvent(FILE* fh, void* handle) {
  if (handle == NULL || fh == NULL) return;

  uint8_t type = *(uint8_t *)handle;

  if (type == ncclProfileGroup) {
    struct group* g = (struct group *)handle;
    printGroupEventHeader(fh, g);

    struct taskEventBase* base = taskEventQueueHead(g);
    while (base) {
      struct taskEventBase* next = base->next;
      printEvent(fh, base);
      base = next;
    }

    printGroupEventTrailer(fh, g);
  } else if (type == ncclProfileColl) {
    struct collective* c = (struct collective *)handle;
    printCollEventHeader(fh, c);

    for (int i = 0; i < MAX_CHANNELS; i++) {
      printEvent(fh, &c->send[i]);
      printEvent(fh, &c->recv[i]);
    }

    printCollEventTrailer(fh, c);
  } else if (type == ncclProfileP2p) {
    struct p2p* p = (struct p2p *)handle;
    printP2pEventHeader(fh, p);
    printEvent(fh, &p->op);
    printP2pEventTrailer(fh, p);
  } else if (type == ncclProfileProxyOp) {
    struct proxyOp* p = (struct proxyOp *)handle;
    printProxyOpEventHeader(fh, p);

    for (int i = 0; i < MAX_STEPS; i++) {
      printEvent(fh, &p->step[i]);
    }

    printProxyOpEventTrailer(fh, p);
  } else if (type == ncclProfileProxyStep) {
    struct proxyStep* p = (struct proxyStep *)handle;
    printProxyStepEvent(fh, p);
  } else if (type == ncclProfileProxyCtrl) {
    struct proxyCtrl* p = (struct proxyCtrl *)handle;
    printProxyCtrlEvent(fh, p);
  }
}

#include <cstring>
#include <cstddef>

// Helper macros for bitwise operations
#define ROTATE_LEFT(x, n) (((x) << (n)) | ((x) >> (32 - (n))))
#define F1(x, y, z) ((x & y) | (~x & z))
#define F2(x, y, z) ((x & z) | (y & ~z))
#define F3(x, y, z) (x ^ y ^ z)
#define F4(x, y, z) (y ^ (x | ~z))

// MD5 round functions with parameters
#define ROUND1(a, b, c, d, k, s, t) { \
    (a) += F1((b), (c), (d)) + (k) + (t); \
    (a) = ROTATE_LEFT((a), (s)); \
    (a) += (b); \
}

#define ROUND2(a, b, c, d, k, s, t) { \
    (a) += F2((b), (c), (d)) + (k) + (t); \
    (a) = ROTATE_LEFT((a), (s)); \
    (a) += (b); \
}

#define ROUND3(a, b, c, d, k, s, t) { \
    (a) += F3((b), (c), (d)) + (k) + (t); \
    (a) = ROTATE_LEFT((a), (s)); \
    (a) += (b); \
}

#define ROUND4(a, b, c, d, k, s, t) { \
    (a) += F4((b), (c), (d)) + (k) + (t); \
    (a) = ROTATE_LEFT((a), (s)); \
    (a) += (b); \
}

// MD5 context structure definition (assumed from usage)
struct MD5_CTX {
    unsigned long state[4];
    unsigned long datalen;
    unsigned long bitlen;
    unsigned char data[64];
};

typedef unsigned char MD5_BYTE;
typedef unsigned long MD5_WORD;

void md5_transform(MD5_CTX* ctx, const MD5_BYTE data[]) {
    MD5_WORD a, b, c, d, m[16];

    // Convert input bytes to 32-bit words (little-endian)
    for (int i = 0; i < 16; ++i) {
        m[i] = (MD5_WORD)data[i*4] |
               ((MD5_WORD)data[i*4+1] << 8) |
               ((MD5_WORD)data[i*4+2] << 16) |
               ((MD5_WORD)data[i*4+3] << 24);
    }

    // Initialize working variables
    a = ctx->state[0];
    b = ctx->state[1];
    c = ctx->state[2];
    d = ctx->state[3];

    // Round 1 - 16 operations
    ROUND1(a, b, c, d, m[0], 7, 0xd76aa478);
    ROUND1(d, a, b, c, m[1], 12, 0xe8c7b756);
    ROUND1(c, d, a, b, m[2], 17, 0x242070db);
    ROUND1(b, c, d, a, m[3], 22, 0xc1bdceee);
    ROUND1(a, b, c, d, m[4], 7, 0xf57c0faf);
    ROUND1(d, a, b, c, m[5], 12, 0x4787c62a);
    ROUND1(c, d, a, b, m[6], 17, 0xa8304613);
    ROUND1(b, c, d, a, m[7], 22, 0xfd469501);
    ROUND1(a, b, c, d, m[8], 7, 0x698098d8);
    ROUND1(d, a, b, c, m[9], 12, 0x8b44f7af);
    ROUND1(c, d, a, b, m[10], 17, 0xffff5bb1);
    ROUND1(b, c, d, a, m[11], 22, 0x895cd7be);
    ROUND1(a, b, c, d, m[12], 7, 0x6b901122);
    ROUND1(d, a, b, c, m[13], 12, 0xfd987193);
    ROUND1(c, d, a, b, m[14], 17, 0xa679438e);
    ROUND1(b, c, d, a, m[15], 22, 0x49b40821);

    // Round 2 - 16 operations
    ROUND2(a, b, c, d, m[1], 5, 0xf61e2562);
    ROUND2(d, a, b, c, m[6], 9, 0xc040b340);
    ROUND2(c, d, a, b, m[11], 14, 0x265e5a51);
    ROUND2(b, c, d, a, m[0], 20, 0xe9b6c7aa);
    ROUND2(a, b, c, d, m[5], 5, 0xd62f105d);
    ROUND2(d, a, b, c, m[10], 9, 0x02441453);
    ROUND2(c, d, a, b, m[15], 14, 0xd8a1e681);
    ROUND2(b, c, d, a, m[4], 20, 0xe7d3fbc8);
    ROUND2(a, b, c, d, m[9], 5, 0x21e1cde6);
    ROUND2(d, a, b, c, m[14], 9, 0xc33707d6);
    ROUND2(c, d, a, b, m[3], 14, 0xf4d50d87);
    ROUND2(b, c, d, a, m[8], 20, 0x455a14ed);
    ROUND2(a, b, c, d, m[13], 5, 0xa9e3e905);
    ROUND2(d, a, b, c, m[2], 9, 0xfcefa3f8);
    ROUND2(c, d, a, b, m[7], 14, 0x676f02d9);
    ROUND2(b, c, d, a, m[12], 20, 0x8d2a4c8a);

    // Round 3 - 16 operations
    ROUND3(a, b, c, d, m[5], 4, 0xfffa3942);
    ROUND3(d, a, b, c, m[8], 11, 0x8771f681);
    ROUND3(c, d, a, b, m[11], 16, 0x6d9d6122);
    ROUND3(b, c, d, a, m[14], 23, 0xfde5380c);
    ROUND3(a, b, c, d, m[1], 4, 0xa4beea44);
    ROUND3(d, a, b, c, m[4], 11, 0x4bdecfa9);
    ROUND3(c, d, a, b, m[7], 16, 0xf6bb4b60);
    ROUND3(b, c, d, a, m[10], 23, 0xbebfbc70);
    ROUND3(a, b, c, d, m[13], 4, 0x289b7ec6);
    ROUND3(d, a, b, c, m[0], 11, 0xeaa127fa);
    ROUND3(c, d, a, b, m[3], 16, 0xd4ef3085);
    ROUND3(b, c, d, a, m[6], 23, 0x04881d05);
    ROUND3(a, b, c, d, m[9], 4, 0xd9d4d039);
    ROUND3(d, a, b, c, m[12], 11, 0xe6db99e5);
    ROUND3(c, d, a, b, m[15], 16, 0x1fa27cf8);
    ROUND3(b, c, d, a, m[2], 23, 0xc4ac5665);

    // Round 4 - 16 operations
    ROUND4(a, b, c, d, m[0], 6, 0xf4292244);
    ROUND4(d, a, b, c, m[7], 10, 0x432aff97);
    ROUND4(c, d, a, b, m[14], 15, 0xab9423a7);
    ROUND4(b, c, d, a, m[5], 21, 0xfc93a039);
    ROUND4(a, b, c, d, m[12], 6, 0x655b59c3);
    ROUND4(d, a, b, c, m[3], 10, 0x8f0ccc92);
    ROUND4(c, d, a, b, m[10], 15, 0xffeff47d);
    ROUND4(b, c, d, a, m[1], 21, 0x85845dd1);
    ROUND4(a, b, c, d, m[8], 6, 0x6fa87e4f);
    ROUND4(d, a, b, c, m[15], 10, 0xfe2ce6e0);
    ROUND4(c, d, a, b, m[6], 15, 0xa3014314);
    ROUND4(b, c, d, a, m[13], 21, 0x4e0811a1);
    ROUND4(a, b, c, d, m[4], 6, 0xf7537e82);
    ROUND4(d, a, b, c, m[11], 10, 0xbd3af235);
    ROUND4(c, d, a, b, m[2], 15, 0x2ad7d2bb);
    ROUND4(b, c, d, a, m[9], 21, 0xeb86d391);

    // Update state
    ctx->state[0] += a;
    ctx->state[1] += b;
    ctx->state[2] += c;
    ctx->state[3] += d;
}

void md5_init(MD5_CTX* ctx) {
    ctx->datalen = 0;
    ctx->bitlen = 0;
    ctx->state[0] = 0x67452301;
    ctx->state[1] = 0xEFCDAB89;
    ctx->state[2] = 0x98BADCFE;
    ctx->state[3] = 0x10325476;
}

void md5_update(MD5_CTX* ctx, const MD5_BYTE data[], size_t len) {
    size_t i = 0;

    // Handle any remaining data in buffer
    if (ctx->datalen > 0) {
        size_t fill = 64 - ctx->datalen;
        if (len < fill) {
            memcpy(ctx->data + ctx->datalen, data, len);
            ctx->datalen += (unsigned long)len;
            return;
        }
        memcpy(ctx->data + ctx->datalen, data, fill);
        md5_transform(ctx, ctx->data);
        ctx->bitlen += 512;
        ctx->datalen = 0;
        i = fill;
    }

    // Process complete blocks
    for (; i + 64 <= len; i += 64) {
        md5_transform(ctx, data + i);
        ctx->bitlen += 512;
    }

    // Store remaining bytes
    if (i < len) {
        memcpy(ctx->data, data + i, len - i);
        ctx->datalen = (unsigned long)(len - i);
    }
}

void md5_final(MD5_CTX* ctx, MD5_BYTE hash[]) {
    size_t i = ctx->datalen;

    // Padding: append 1 bit followed by zeros
    if (ctx->datalen < 56) {
        ctx->data[i++] = 0x80;
        while (i < 56) {
            ctx->data[i++] = 0x00;
        }
    } else {
        ctx->data[i++] = 0x80;
        while (i < 64) {
            ctx->data[i++] = 0x00;
        }
        md5_transform(ctx, ctx->data);
        memset(ctx->data, 0, 56);
    }

    // Append length in bits (64-bit value)
    ctx->bitlen += ctx->datalen * 8;
    ctx->data[56] = (unsigned char)(ctx->bitlen & 0xFF);
    ctx->data[57] = (unsigned char)((ctx->bitlen >> 8) & 0xFF);
    ctx->data[58] = (unsigned char)((ctx->bitlen >> 16) & 0xFF);
    ctx->data[59] = (unsigned char)((ctx->bitlen >> 24) & 0xFF);
    ctx->data[60] = (unsigned char)((ctx->bitlen >> 32) & 0xFF);
    ctx->data[61] = (unsigned char)((ctx->bitlen >> 40) & 0xFF);
    ctx->data[62] = (unsigned char)((ctx->bitlen >> 48) & 0xFF);
    ctx->data[63] = (unsigned char)((ctx->bitlen >> 56) & 0xFF);

    md5_transform(ctx, ctx->data);

    // Output hash in little-endian format
    for (i = 0; i < 4; ++i) {
        hash[i] = (MD5_BYTE)((ctx->state[0] >> (i * 8)) & 0xFF);
        hash[i + 4] = (MD5_BYTE)((ctx->state[1] >> (i * 8)) & 0xFF);
        hash[i + 8] = (MD5_BYTE)((ctx->state[2] >> (i * 8)) & 0xFF);
        hash[i + 12] = (MD5_BYTE)((ctx->state[3] >> (i * 8)) & 0xFF);
    }
}

