#include "benchmark/benchmark.h"
#include "spdlog/spdlog.h"
#include "spdlog/pattern_formatter.h"

// Helper to generate single-flag patterns like "%+", "%v", etc.
void register_single_flag_benchmarks() {
    const char* flags = "+vtPnlLaAbBcCYDmdHIMSefFprRTXzEisg@luioO%";
    size_t num_flags = std::string(flags).length();
    for (size_t idx = 0; idx < num_flags; ++idx) {
        std::string flag_str(1, flags[idx]);
        std::string pattern = "%" + flag_str;
        benchmark::RegisterBenchmark(pattern.c_str(), [](benchmark::State& state) {
            auto formatter = spdlog::details::make_unique<spdlog::pattern_formatter>(pattern);
            spdlog::memory_buf_t buffer;
            std::string logger_name = "logger-name";
            const char* message_text =
                "Hello. This is some message with length of 80                                   ";
            spdlog::source_loc src_loc{"a/b/c/d/myfile.cpp", 123, "some_func()"};
            spdlog::details::log_msg msg(src_loc, logger_name, spdlog::level::info, message_text);

            for (auto _ : state) {
                buffer.clear();
                formatter->format(msg, buffer);
                benchmark::DoNotOptimize(buffer);
            }
        });
    }
}

// Register benchmarks for predefined complex patterns
void register_complex_pattern_benchmarks() {
    std::vector<std::string> patterns;
    patterns.push_back("[%D %X] [%l] [%n] %v");
    patterns.push_back("[%Y-%m-%d %H:%M:%S.%e] [%l] [%n] %v");
    patterns.push_back("[%Y-%m-%d %H:%M:%S.%e] [%l] [%n] [%t] %v");

    for (size_t i = 0; i < patterns.size(); ++i) {
        benchmark::RegisterBenchmark(patterns[i].c_str(), [](benchmark::State& state, const std::string& pat) {
            auto formatter = spdlog::details::make_unique<spdlog::pattern_formatter>(pat);
            spdlog::memory_buf_t buffer;
            std::string logger_name = "logger-name";
            const char* msg_text =
                "Hello. This is some message with length of 80                                   ";
            spdlog::source_loc src_loc{"a/b/c/d/myfile.cpp", 123, "some_func()"};
            spdlog::details::log_msg msg(src_loc, logger_name, spdlog::level::info, msg_text);

            for (auto _ : state) {
                buffer.clear();
                formatter->format(msg, buffer);
                benchmark::DoNotOptimize(buffer);
            }
        }, patterns[i])
        ->Iterations(2500000);
    }
}

int main(int argc, char* argv[]) {
    spdlog::set_pattern("[%^%l%$] %v");

    if (argc != 2) {
        spdlog::error("Usage: {} <pattern> (or \"all\" to benchmark all)", argv[0]);
        return 1;
    }

    std::string input_pattern = argv[1];

    if (input_pattern == "all") {
        register_single_flag_benchmarks();
        register_complex_pattern_benchmarks();
    } else {
        benchmark::RegisterBenchmark(input_pattern.c_str(), [](benchmark::State& state, const std::string& pat) {
            auto formatter = spdlog::details::make_unique<spdlog::pattern_formatter>(pat);
            spdlog::memory_buf_t buffer;
            std::string logger_name = "logger-name";
            const char* msg_text =
                "Hello. This is some message with length of 80                                   ";
            spdlog::source_loc src_loc{"a/b/c/d/myfile.cpp", 123, "some_func()"};
            spdlog::details::log_msg msg(src_loc, logger_name, spdlog::level::info, msg_text);

            for (auto _ : state) {
                buffer.clear();
                formatter->format(msg, buffer);
                benchmark::DoNotOptimize(buffer);
            }
        }, input_pattern);
    }

    benchmark::Initialize(&argc, argv);
    benchmark::RunSpecifiedBenchmarks();
    return 0;
}

