#include <cstdio>
#include <cstdlib>
#include <cstring>

// Inline replacements for min/max macros
inline int min_val(int a, int b) { return a < b ? a : b; }
inline int max_val(int a, int b) { return a > b ? a : b; }

#if defined(WIN32)
#  include <windows.h>
#elif defined(salford32)
#  include <windows.h>
#elif defined(HAVE_CONFIG_H)
#  include <dlfcn.h>
#endif

// Platform-specific symbol renaming
#if defined(WIN32)
#  define DLL_OPEN_SYMBOL   "RTC_OPEN_SHARED_LIBRARY"
#  define DLL_CLOSE_SYMBOL  "RTC_CLOSE_SHARED_LIBRARY"
#  define DLL_CALL_SYMBOL   "RTC_PERFORM_FUNCTION"
#  define CALL_CONV
#elif defined(salford32)
#  define DLL_OPEN_SYMBOL   "RTC_OPEN_SHARED_LIBRARY"
#  define DLL_CLOSE_SYMBOL  "RTC_CLOSE_SHARED_LIBRARY"
#  define DLL_CALL_SYMBOL   "RTC_PERFORM_FUNCTION"
#  define CALL_CONV __stdcall
#elif defined(HAVE_CONFIG_H)
#  define DLL_OPEN_SYMBOL   "rtc_open_shared_library_"
#  define DLL_CLOSE_SYMBOL  "rtc_close_shared_library_"
#  define DLL_CALL_SYMBOL   "rtc_perf_function_"
#  define CALL_CONV
#endif

// Handle type aliasing per platform
#if defined(WIN32) || defined(salford32)
using DllHandle = HMODULE;
#else
using DllHandle = void*;
#endif

struct SharedLibrary {
    DllHandle handle;
};

// Helper: copy Fortran-style string (null-terminated, trimmed on right)
char* dup_fstring(const char* src, long len) {
    if (!src || len <= 0) return nullptr;

    size_t real_len = std::strlen(src);
    size_t copy_len = static_cast<size_t>(min_val(static_cast<int>(len), static_cast<int>(real_len)));

    char* dst = new char[copy_len + 1];
    if (!dst) return nullptr;

    std::strncpy(dst, src, copy_len);
    dst[copy_len] = '\0';
    return dst;
}

// Remove trailing whitespace/newlines from a C-string in-place
void trim_trailing_whitespace(char* str) {
    if (!str) return;
    size_t len = std::strlen(str);
    if (len == 0) return;

    for (size_t i = len - 1; i != static_cast<size_t>(-1); --i) {
        char c = str[i];
        if (c == ' ' || c == '\n' || c == '\t') {
            str[i] = '\0';
        } else {
            break;
        }
    }
}

// Open shared library
extern "C" long CALL_CONV RTC_OPEN_SHARED_LIBRARY(long* out_handle, char* lib_path, long path_len) {
    long result = 1;
    char* normalized_path = dup_fstring(lib_path, path_len);
    if (!normalized_path) return result;

    trim_trailing_whitespace(normalized_path);

    SharedLibrary* lib = new SharedLibrary{nullptr};
    if (!lib) {
        delete[] normalized_path;
        return result;
    }

#if defined(WIN32) || defined(salford32)
    lib->handle = LoadLibraryA(normalized_path);
#elif defined(HAVE_CONFIG_H)
    lib->handle = dlopen(normalized_path, RTLD_LAZY);
#endif

    if (lib->handle != nullptr) {
        *out_handle = reinterpret_cast<long>(lib);
        result = 0;
    } else {
        delete lib;
    }

    delete[] normalized_path;
    return result;
}

// Close shared library
extern "C" long CALL_CONV RTC_CLOSE_SHARED_LIBRARY(long* handle_ptr) {
    if (!handle_ptr || !*handle_ptr) return 0;

    SharedLibrary* lib = reinterpret_cast<SharedLibrary*>(*handle_ptr);
#if defined(WIN32) || defined(salford32)
    FreeLibrary(lib->handle);
#elif defined(HAVE_CONFIG_H)
    dlclose(lib->handle);
#endif
    delete lib;
    *handle_ptr = 0;
    return 0;
}

// Function pointer typedef for the exported routine
using ProcPtr = void*(CALL_CONV*)(
    long*, long*, long*, long*, long*,
    double*, double*, double*, double*, double*, double*, double*, double*, double*, double*,
    double*, double*, double*, double*, double*, double*,
    double*, double*, double*, double*, double*,
    long*, double*,
    long*, double*,
    long*, double*, double*,
    long*, long*, double**,
    long*, double*, double*, long*,
    char**, char**, char**, char**, char**, char**, char**,
    long, long, long, long, long, long, long
);

// Perform function call into shared library
extern "C" long CALL_CONV RTC_PERFORM_FUNCTION(
    long* dll_handle,
    char* func_name,
    long* sobek_first,
    long* sobek_date,
    long* sobek_time,
    long* sobek_dt,
    long* max_sobek,
    double* h, double* q, double* sa, double* wd, double* cl, double* cw,
    double* gl, double* go, double* fa, double* qs, double* vs, double* hu,
    double* hd, double* dh, double* pd, double* pc,
    double* dbl, double* du, double* dv, double* dc, double* vr,
    long* max_rr, double* rr_h,
    long* max_rain, double* rain_h,
    long* max_d3d, double* d3d_h, double* d3d_sal,
    long* max_loc_wq, long* max_par_wq, double** wq_data,
    long* max_setpoints, double* set_c, double* set_k, long* ret_code,
    char** ids_br, char** id_d3b, char** id_pre, char** id_d3d,
    char** loc_id_wq, char** par_id_wq, char** meas_id,
    long fn_len, long ids_br_len, long id_d3b_len, long id_pre_len,
    long id_d3d_len, long loc_id_wq_len, long par_id_wq_len, long meas_id_len
) {
    long status = 1;
    char* normalized_func = dup_fstring(func_name, fn_len);
    if (!normalized_func) return status;

    trim_trailing_whitespace(normalized_func);

    SharedLibrary* lib = reinterpret_cast<SharedLibrary*>(*dll_handle);
    if (!lib) {
        delete[] normalized_func;
        return status;
    }

    ProcPtr proc = nullptr;
#if defined(WIN32) || defined(salford32)
    proc = reinterpret_cast<ProcPtr>(GetProcAddress(lib->handle, normalized_func));
#elif defined(HAVE_CONFIG_H)
    proc = reinterpret_cast<ProcPtr>(dlsym(lib->handle, normalized_func));
#endif

    if (proc != nullptr) {
        status = 0;
        // Call through the function pointer
        (*proc)(
            sobek_first, sobek_date, sobek_time, sobek_dt, max_sobek,
            h, q, sa, wd, cl, cw, gl, go, fa, qs, vs, hu, hd, dh, pd, pc,
            dbl, du, dv, dc, vr,
            max_rr, rr_h,
            max_rain, rain_h,
            max_d3d, d3d_h, d3d_sal,
            max_loc_wq, max_par_wq, wq_data,
            max_setpoints, set_c, set_k, ret_code,
            ids_br, id_d3b, id_pre, id_d3d,
            loc_id_wq, par_id_wq, meas_id,
            ids_br_len, id_d3b_len, id_pre_len,
            id_d3d_len, loc_id_wq_len, par_id_wq_len, meas_id_len
        );
    }

    delete[] normalized_func;
    return status;
}

