// Determines if there has been recent user activity based on input state.
// Considers any momentary ("Once") press or currently held button as activity.
bool hasUserActivity(const InputState& in) {
  // On Cardputer, held states are reliably reported; thus, any held condition indicates activity.
  return in.menuHeld || in.selectHeld;
