PerformanceTimer::PerformanceTimer()
{
#if !defined (__linux__)
	// Initialize timing mechanism
	LARGE_INTEGER frequency;
	QueryPerformanceFrequency(&frequency);
	m_fSecsPerTick = 1.0f / static_cast<float>(frequency.QuadPart);

	// Set initial time point
	Reset();
#endif
}

void PerformanceTimer::Reset()
{
#if !defined (__linux__)
	QueryPerformanceCounter(&m_qwStartTime);
#endif
}

void PerformanceTimer::PrintElapsedTime(const std::wstring& label)
{
#if !defined (__linux__)
	LARGE_INTEGER currentTime, delta;
	QueryPerformanceCounter(&currentTime);
	delta.QuadPart = currentTime.QuadPart - m_qwStartTime.QuadPart;

	float duration = m_fSecsPerTick * static_cast<float>(delta.QuadPart);
	app.DebugPrintf(L"TIMER: %ls: Duration %.6f seconds\n", label.c_str(), duration);
#endif
}

