namespace zen::action {

void performJITCompilation(runtime::Module &Mod) {
  const auto &Config = Mod.getRuntime()->getConfig();

  switch (Config.Mode) {
#ifdef ZEN_ENABLE_SINGLEPASS_JIT
    case common::RunMode::SinglepassMode: {
      singlepass::JITCompiler::compile(&Mod);
      break;
    }
#endif

#ifdef ZEN_ENABLE_MULTIPASS_JIT
    case common::RunMode::MultipassMode: {
      if (Config.EnableMultipassLazy) {
        auto *LazyCompiler = Mod.newLazyJITCompiler();
        LazyCompiler->precompile();
      } else {
        COMPILER::EagerJITCompiler Compiler(&Mod);
        Compiler.compile();
      }
      break;
    }
#endif

    default:
      break;
  }
}

#ifdef ZEN_ENABLE_EVM
void performEVMCompilation(runtime::EVMModule &Mod) {
  const auto &Config = Mod.getRuntime()->getConfig();

  switch (Config.Mode) {
#ifdef ZEN_ENABLE_MULTIPASS_JIT
    case common::RunMode::MultipassMode: {
      if (Config.EnableMultipassLazy) {
        ZEN_LOG_WARN("EVM backend currently lacks lazy compilation support");
      } else {
        COMPILER::EagerEVMJITCompiler Compiler(&Mod);
        Compiler.compile();
      }
      break;
    }
#endif

    default:
      ZEN_LOG_ERROR("EVM backend does not support singlepass execution mode");
      break;
  }
}
#endif // ZEN_ENABLE_EVM

