// Applies transformation: translates by vin, then multiplies with tfin
void UIListWidget::CalcXfm(const Transform &tfin, const Vector3 &vin, Transform &out) {
    out.origin.x += vin.x;
    out.origin.y += vin.y;
    out.origin.z += vin.z;
    Multiply(out, tfin, out);
}

// Assigns the parent list container
void UIListWidget::SetParentList(UIList *list) { 
    mOwnerList = list; 
}

// Retrieves appropriate color based on widget and component states
UIColor *UIListWidget::DisplayColor(
    UIListWidgetState element_state, UIComponent::State list_state
) const {
    MILO_ASSERT((0) <= (element_state) && (element_state) < (kNumUIListWidgetStates), 0x64);
    MILO_ASSERT((0) <= (list_state) && (list_state) < (UIComponent::kNumStates), 0x65);

    UIColor *result = mColors[element_state][list_state];
    if (result)
        return result;
    else if (mFallbackColor)
        return mFallbackColor;
    else
        return nullptr;
}

// Serializes object state to binary stream
void UIListWidget::Save(BinStream &bs) {
    bs << 2;
    SAVE_SUPERCLASS(Hmx::Object)
    bs << mRenderPriority << mFallbackColor << mRenderingMode;
    bs << mDisabledAlphaScale;

    int rowIdx = 0;
    while (rowIdx < kNumUIListWidgetStates) {
        int colIdx = 0;
        while (colIdx < UIComponent::kNumStates) {
            bs << mColors[rowIdx][colIdx];
            ++colIdx;
        }
        ++rowIdx;
    }
}

// Default constructor initializes member variables
UIListWidget::UIListWidget()
    : mRenderPriority(0), mDisabledAlphaScale(1), mFallbackColor(this),
      mRenderingMode(kUIListWidgetDrawAlways), mOwnerList(nullptr) {

    int i = 0;
    while (i < kNumUIListWidgetStates) {
        std::vector<ObjPtr<UIColor> > row;
        int j = 0;
        while (j < UIComponent::kNumStates) {
            row.push_back(ObjPtr<UIColor>(this));
            ++j;
        }
        mColors.push_back(row);
        ++i;
    }
}

// Sets a specific color for given widget/component state pair
void UIListWidget::SetColor(UIListWidgetState ws, UIComponent::State cs, UIColor *color) {
    MILO_ASSERT(ws < kNumUIListWidgetStates, 0x7C);
    MILO_ASSERT(cs < UIComponent::kNumStates, 0x7D);
    ObjPtr<UIColor> &target = mColors[ws][cs];
    target = color;
}

