// Renders a mesh with correct transform and color
void UIListWidget::DrawMesh(
    RndMesh *mesh,
    UIListWidgetState wstate,
    UIComponent::State cstate,
    const Transform &tf,
    Box *box
) {
    MILO_ASSERT(mesh, 0x40);
    mesh->SetWorldXfm(tf);
    if (box) {
        Box localBounds = *box;
        CalcBox(mesh, localBounds);
        box->GrowToContain(localBounds.mMin, false);
        box->GrowToContain(localBounds.mMax, false);
    } else {
        UIColor *selectedColor = DisplayColor(wstate, cstate);
        if (selectedColor) {
            RndMat *material = mesh->Mat();
            if (material)
                material->SetColor(0, 0, 0);
        }
        mesh->DrawShowing();
    }
}

