namespace RCCLTestGuards
{
    // RAII wrappers for NET resource cleanup
    struct NetMemHandleCloser
    {
        ncclNet_t* net_ptr;
        void*      comm_ptr;
        NetMemHandleCloser(ncclNet_t* n = nullptr, void* c = nullptr) : net_ptr(n), comm_ptr(c) {}
        void operator()(void* handle) const
        {
            if(handle && comm_ptr && net_ptr)
                net_ptr->deregMr(comm_ptr, handle);
        }
    };

    struct NetSenderDeleter
    {
        ncclNet_t* net_ref;
        explicit NetSenderDeleter(ncclNet_t* n = nullptr) : net_ref(n) {}
        void operator()(void* comm) const
        {
            if(comm && net_ref)
                net_ref->closeSend(comm);
        }
    };

    struct NetReceiverDeleter
    {
        ncclNet_t* net_ref;
        explicit NetReceiverDeleter(ncclNet_t* n = nullptr) : net_ref(n) {}
        void operator()(void* comm) const
        {
            if(comm && net_ref)
                net_ref->closeRecv(comm);
        }
    };

    struct NetListenerDeleter
    {
        ncclNet_t* net_ref;
        explicit NetListenerDeleter(ncclNet_t* n = nullptr) : net_ref(n) {}
        void operator()(void* comm) const
        {
            if(comm && net_ref)
                net_ref->closeListen(comm);
        }
    };

    using MemHandleGuard   = ResourceGuard<void*, NetMemHandleCloser>;
    using SendCommGuard    = ResourceGuard<void*, NetSenderDeleter>;
    using RecvCommGuard    = ResourceGuard<void*, NetReceiverDeleter>;
    using ListenCommGuard  = ResourceGuard<void*, NetListenerDeleter>;

    class ConnectionManager
    {
    private:
        ncclNet_t* net_obj;
        void* listen_handle;
        void* send_handle;
        void* recv_handle;

    public:
        explicit ConnectionManager(ncclNet_t* net) 
            : net_obj(net), listen_handle(nullptr), send_handle(nullptr), recv_handle(nullptr) {}

        ~ConnectionManager()
        {
            if(recv_handle && net_obj)
                net_obj->closeRecv(recv_handle);
            if(send_handle && net_obj)
                net_obj->closeSend(send_handle);
            if(listen_handle && net_obj)
                net_obj->closeListen(listen_handle);
        }

        void assignListen(void* h) { listen_handle = h; }
        void assignSend(void* h)    { send_handle = h; }
        void assignRecv(void* h)    { recv_handle = h; }

        void* getListen() const { return listen_handle; }
        void* getSend() const    { return send_handle; }
        void* getRecv() const    { return recv_handle; }

        // Disable copy/move semantics
        ConnectionManager(const ConnectionManager&)            = delete;
        ConnectionManager& operator=(const ConnectionManager&) = delete;
        ConnectionManager(ConnectionManager&&)                 = delete;
        ConnectionManager& operator=(ConnectionManager&&)      = delete;
    };

    inline MemHandleGuard makeMemHandleGuard(void* mhandle, ncclNet_t* net, void* comm)
    {
        return MemHandleGuard(mhandle, NetMemHandleCloser(net, comm));
    }

    inline SendCommGuard makeSendCommGuard(void* comm, ncclNet_t* net)
    {
        return SendCommGuard(comm, NetSenderDeleter(net));
    }

    inline RecvCommGuard makeRecvCommGuard(void* comm, ncclNet_t* net)
    {
        return RecvCommGuard(comm, NetReceiverDeleter(net));
    }

    inline ListenCommGuard makeListenCommGuard(void* comm, ncclNet_t* net)
    {
        return ListenCommGuard(comm, NetListenerDeleter(net));
    }
} // namespace RCCLTestGuards

