        if(config.world_rank == 0)
            TEST_INFO("Testing local buffer registration...");

        ASSERT_NE(comm_handle, nullptr) << "Rank " << config.world_rank << ": communicator invalid";

        void* sbuf = nullptr, * rbuf = nullptr;
        allocateAndInitBuffersGuarded(&sbuf, &rbuf, kDefaultBufferSize, kDefaultBufferSize);

        void* shandle = nullptr, * rhandle = nullptr;
        preRegisterBuffersGuarded(sbuf, rbuf, kDefaultBufferSize, kDefaultBufferSize,
                                  &shandle, &rhandle);

        int flag{};
        void* reg_handle{};
        ncclConnector* conn_array[1] = {&send_connector};

        auto res = ncclNetLocalRegisterBuffer(
            reinterpret_cast<ncclComm*>(getActiveCommunicator()),
            sbuf, kDefaultBufferSize, conn_array, 1,
            &flag, &reg_handle);

        EXPECT_EQ(ncclSuccess, res) << "Rank " << config.world_rank
            << ": Local registration failed: " << ncclGetErrorString(res);

        if(config.world_rank == 0)
        {
            TEST_INFO("Local registration result: %s", ncclGetErrorString(res));
            TEST_INFO("Flag: %d, Handle: %p", flag, reg_handle);
        }
    }

    void testVariousSizes()
    {
        if(config.world_rank == 0)
            TEST_INFO("Running multi-size data transfer tests...");

        ASSERT_NE(comm_handle, nullptr) << "Rank " << config.world_rank << ": communicator invalid";

        std::vector<size_t> test_sizes = {
            1, 3, 7, 15, 63,
            1024, 1025, 1536, 4096, 4097, 5000, 16384, 16385,
            65536, 65537, 100000, 262144, 262145, 500000,
            1048576, 1048577, 4194304, 4194305
        };

        int peer = (config.world_rank == 0) ? 1 : 0;
        hipStream_t stream = getActiveStream();
        ASSERT_NE(stream, nullptr) << "Rank " << config.world_rank << ": Stream null";

        for(size_t sz : test_sizes)
        {
            if(config.world_rank == 0)
                TEST_INFO("Testing size: %zu bytes", sz);

            void* sbuf = nullptr, * rbuf = nullptr;
            auto [sguard, rguard] = allocateAndInitBuffersGuarded(&sbuf, &rbuf, sz, sz, false);
            ASSERT_NE(sbuf, nullptr) << "Rank " << config.world_rank << ": Send alloc failed";
            ASSERT_NE(rbuf, nullptr) << "Rank " << config.world_rank << ": Recv alloc failed";

            uint8_t* sdata = static_cast<uint8_t*>(sbuf);
            for(size_t idx = 0; idx < sz; ++idx)
                sdata[idx] = static_cast<uint8_t>((config.world_rank * kPatternScale + idx) % kByteRange);

            uint8_t* rdata = static_cast<uint8_t*>(rbuf);
            std::fill(rdata, rdata + sz, 0xFF);

            ASSERT_MPI_SUCCESS(ncclGroupStart());
            ASSERT_MPI_SUCCESS(ncclSend(sbuf, sz, ncclInt8, peer, getActiveCommunicator(), stream));
            ASSERT_MPI_SUCCESS(ncclRecv(rbuf, sz, ncclInt8, peer, getActiveCommunicator(), stream));
            ASSERT_MPI_SUCCESS(ncclGroupEnd());

            ASSERT_MPI_EQ(hipSuccess, hipStreamSynchronize(stream));

            int mismatch_count = 0;
            const int max_print = 5;
            for(size_t idx = 0; idx < sz && mismatch_count < max_print; ++idx)
            {
                uint8_t expected = static_cast<uint8_t>((peer * kPatternScale + idx) % kByteRange);
                if(rdata[idx] != expected)
                {
                    TEST_WARN("Size %zu - Mismatch at index %zu: expected %u, got %u",
                              sz, idx, expected, rdata[idx]);
                    ++mismatch_count;
                }
            }

            EXPECT_EQ(0, mismatch_count) << "Rank " << config.world_rank
                << ": Data errors detected for size " << sz;

            if(config.world_rank == 0 && mismatch_count == 0)
                TEST_INFO("Size %zu: Transfer verified successfully", sz);
        }
    }
};

