// Reproduce original bug scenario: garage stall should suppress FFB unless torque exceeds threshold
TEST_CASE(test_issue_185_fix_repro_alt, "Internal") {
    std::cout << "[Repro] Garage FFB suppression check (Issue #185)" << std::endl;

    FFBEngine engine;
    InitializeEngine(engine);

    // Configure engine parameters as per original repro case
    engine.m_gain = 1.0f;
    engine.m_min_force = 0.05f;
    engine.m_steering_shaft_gain = 1.0f;
    engine.m_wheelbase_max_nm = 10.0f;
    engine.m_target_rim_nm = 10.0f;

    // Set internal calibration values via test accessors
    FFBEngineTestAccess::SetSessionPeakTorque(engine, 10.0);
    FFBEngineTestAccess::SetSmoothedStructuralMult(engine, 0.1); // same as 1.0 / 10.0

    VehicleScoringInfoV01 playerState = {};
    memset(&playerState, 0, sizeof(playerState));
    playerState.mIsPlayer = true;
    playerState.mControl = 0;
    playerState.mInGarageStall = true;

    double vehicleSpeed = 0.0;
    TelemInfoV01 telemetry = CreateBasicTestTelemetry(vehicleSpeed, 0.0);
    telemetry.mSteeringShaftTorque = 0.1; // small shaft torque

    bool forceEnabled = engine.IsFFBAllowed(playerState, 5);
    ASSERT_FALSE(forceEnabled); // garage stall → no FFB allowed

    double outputForce = engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, forceEnabled);
    std::cout << "  Measured force (expected zero): " << outputForce << std::endl;
    ASSERT_NEAR(outputForce, 0.0, 1e-7);
}

// Verify soft lock still works correctly when enabled in garage
TEST_CASE(test_issue_185_fix_soft_lock_alt, "Internal") {
    std::cout << "[Soft Lock] Garage soft lock activation (Issue #185)" << std::endl;

    FFBEngine engine;
    InitializeEngine(engine);

    // Higher thresholds to allow soft lock to activate without clamping
    engine.m_gain = 1.0f;
    engine.m_min_force = 0.05f;
    engine.m_wheelbase_max_nm = 100.0f;
    engine.m_target_rim_nm = 100.0f;

    FFBEngineTestAccess::SetSessionPeakTorque(engine, 100.0);
    FFBEngineTestAccess::SetSmoothedStructuralMult(engine, 0.01); // 1.0 / 100.0

    VehicleScoringInfoV01 playerState = {};
    memset(&playerState, 0, sizeof(playerState));
    playerState.mIsPlayer = true;
    playerState.mControl = 0;
    playerState.mInGarageStall = true;

    double vehicleSpeed = 0.0;
    TelemInfoV01 telemetry = CreateBasicTestTelemetry(vehicleSpeed, 0.0);

    // Simulate steering beyond limit (10% over)
    telemetry.mUnfilteredSteering = 1.1;

    engine.m_soft_lock_enabled = true;
    engine.m_soft_lock_stiffness = 20.0f;

    bool forceEnabled = engine.IsFFBAllowed(playerState, 5);
    double generatedForce = engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, forceEnabled);
    double absForce = generatedForce < 0 ? -generatedForce : generatedForce;

    std::cout << "  Soft lock force (target ~100Nm): " << generatedForce 
