    // Normalized result should be near full scale (1.0)
    ASSERT_NEAR(absForce, 1.0, 0.01);
}

// Test noise rejection in garage + transition handling (Issue #235)
TEST_CASE(test_issue_235_garage_noise_alt, "Internal") {
    std::cout << "[Noise Rejection] Garage noise filtering & state reset (Issue #235)" << std::endl;

    FFBEngine engine;
    InitializeEngine(engine);

    engine.m_gain = 1.0f;
    engine.m_min_force = 0.05f;
    engine.m_steering_shaft_gain = 1.0f;
    engine.m_wheelbase_max_nm = 10.0f;
    engine.m_target_rim_nm = 10.0f;
    engine.m_soft_lock_enabled = true;
    engine.m_soft_lock_stiffness = 20.0f;

    FFBEngineTestAccess::SetSessionPeakTorque(engine, 10.0);
    FFBEngineTestAccess::SetSmoothedStructuralMult(engine, 0.1);

    VehicleScoringInfoV01 playerState = {};
    memset(&playerState, 0, sizeof(playerState));
    playerState.mIsPlayer = true;
    playerState.mControl = 0;
    playerState.mInGarageStall = true;

    double vehicleSpeed = 0.0;
    TelemInfoV01 telemetry = CreateBasicTestTelemetry(vehicleSpeed, 0.0);

    // Scenario A: Tiny steering jitter — should be ignored
    telemetry.mUnfilteredSteering = 0.001;
    bool isFFBActive = engine.IsFFBAllowed(playerState, 5);
    double tinyJitterForce = engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, isFFBActive);
    std::cout << "  Force from 0.1% steering noise: " << tinyJitterForce << std::endl;
    ASSERT_EQ(tinyJitterForce, 0.0);

    // Scenario B: Real rack limit reached
    telemetry.mUnfilteredSteering = 1.1;
    double hardLimitForce = engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, isFFBActive);
    std::cout << "  Force at full lock: " << hardLimitForce << std::endl;
    ASSERT_GT(std::abs(hardLimitForce), 0.5);

    // Scenario C: Transition from active to inactive state
    // Simulate entering garage after driving
    engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, true);   // active mode
    engine.calculate_force(&telemetry, nullptr, nullptr, 0.0f, false);  // garage mode

    // Ensure velocity smoothing filter resets on transition
    double smoothedVel = FFBEngineTestAccess::GetSteeringVelocitySmoothed(engine);
    std::cout << "  Steering velocity after garage entry: " << smoothedVel << std::endl;
    ASSERT_EQ(smoothedVel, 0.0);
}

