#include <Alembic/Abc/All.h>
#include <Alembic/AbcCoreOgawa/All.h>
#include <Alembic/AbcMaterial/OMaterial.h>
#include <Alembic/AbcMaterial/IMaterial.h>
#include <Alembic/AbcMaterial/MaterialAssignment.h>
#include <Alembic/AbcCoreAbstract/Tests/Assert.h>
#include "PrintMaterial.h"

namespace Abc = Alembic::Abc;
namespace Mat = Alembic::AbcMaterial;

void write()
{
    // Create an Ogawa-backed archive for writing
    Abc::OArchive archive(Alembic::AbcCoreOgawa::WriteArchive(), "HasAMaterial.abc");
    Abc::OObject root(archive, Abc::kTop);

    // --- Section: Manual schema creation and compound property testing ---
    Abc::OObject obj(root, "an_object");

    // Create material schema with custom name
    Mat::OMaterialSchema matSchema(Mat::OMaterialSchema(obj.getProperties().getPtr(), ".custom_mat_prop"));
    matSchema.setShader("prman", "surface", "ambocc");

    // Add a non-material compound property
    {
        Abc::OCompoundProperty compoundProp(obj.getProperties(), "user_data_field");
        Abc::OStringProperty strProp(compoundProp, "data_value");
        strProp.set("hello");
    }

    // Manually create .material property (not via OMaterialSchema)
    {
        Abc::OCompoundProperty matCompound(obj.getProperties(), ".material");
        Abc::OStringProperty valProp(matCompound, "value");
        valProp.set("world");
    }

    // --- Section: Assignment & hasMaterial mechanism tests ---
    {
        Abc::OObject secondObj(root, "another_object");
        Mat::addMaterialAssignment(secondObj, "/some/material");

        Mat::OMaterialSchema assignedMat = Mat::addMaterial(secondObj);
        assignedMat.setShader("prman", "surface", "carpet");
    }
}

void read()
{
    Abc::IArchive archive(Alembic::AbcCoreOgawa::ReadArchive(), "HasAMaterial.abc");
    Abc::IObject obj(archive.getTop(), "an_object");

    // Check custom-named material schema
    const Abc::PropertyHeader* header1 = obj.getProperties().getPropertyHeader(".custom_mat_prop");
    if (header1 && Mat::OMaterialSchema::matches(*header1))
    {
        std::cout << ".custom_mat_prop yes.\n";
        Mat::IMaterialSchema matSchema(obj.getProperties(), ".custom_mat_prop");
        printMaterialSchema(matSchema);
    }
    else
    {
        std::cout << ".custom_mat_prop no.\n";
    }

    // Check non-material compound property
    const Abc::PropertyHeader* header2 = obj.getProperties().getPropertyHeader("user_data_field");
    if (header2)
    {
        TESTING_ASSERT(!Mat::OMaterialSchema::matches(*header2));
        if (!Mat::OMaterialSchema::matches(*header2))
        {
            std::cout << "user_data_field no.\n";
        }
        else
        {
            std::cout << "user_data_field yes.\n";
        }
    }

    // Check manually built .material property
    const Abc::PropertyHeader* header3 = obj.getProperties().getPropertyHeader(".material");
    if (header3)
    {
        TESTING_ASSERT(!Mat::OMaterialSchema::matches(*header3));
        if (!Mat::OMaterialSchema::matches(*header3))
        {
            std::cout << "manually built .material no.\n";
        }
        else
        {
            std::cout << "manually built .material yes.\n";
        }
    }

    std::cout << "-----------\n";

    // Test assignment and hasMaterial on second object
    Abc::IObject secondObj(archive.getTop(), "another_object");
    std::string assignedPath;
    bool hasPath = Mat::getMaterialAssignmentPath(secondObj, assignedPath);
    if (hasPath)
    {
        std::cout << "another_object assignment path: " << assignedPath << std::endl;
    }
    TESTING_ASSERT(hasPath && assignedPath == "/some/material");

    Mat::IMaterialSchema localMat;
    bool hasLocalMat = Mat::hasMaterial(secondObj, localMat);
    TESTING_ASSERT(hasLocalMat);
    if (hasLocalMat)
    {
        std::cout << "another_object has local material: " << std::endl;
        printMaterialSchema(localMat);
    }
}

int main(int argc, char* argv[])
{
    write();
    read();
    return 0;
}

