// Test fixture for ArcManager functionality
class ArcManagerTest : public TuringTest {
protected:
    void initialize() override {
        // Setup logic if needed
    }

    void terminate() override {
        // Cleanup logic if needed
    }
};

// Helper struct for testing ArcManager
struct MyObject {
    size_t _a {0};
    size_t _b {0};
};

// Test case: Verify initial state of ArcManager is empty
TEST_F(ArcManagerTest, empty) {
    ArcManager<MyObject> manager;
    ASSERT_EQ(manager.size(), 0u);
    const size_t removedCount = manager.cleanUp();
    EXPECT_EQ(removedCount, 0u);
}

// Test case: All weak references expire, all objects should be deleted
TEST_F(ArcManagerTest, deleteAll) {
    ArcManager<MyObject> manager;
    {
        WeakArc<MyObject> ref1 = manager.create(1, 2);
        WeakArc<MyObject> ref2 = manager.create(2, 3);
        WeakArc<MyObject> ref3 = manager.create(4, 5);
        // All weak references go out of scope here
        // Objects remain in manager until cleanUp()
    }
    EXPECT_EQ(manager.size(), 3u);
    const size_t removedCount = manager.cleanUp();
    EXPECT_EQ(removedCount, 3u);
    EXPECT_EQ(manager.size(), 0u);
}

// Test case: Only some weak references expire, only those should be deleted
TEST_F(ArcManagerTest, deleteSome) {
    ArcManager<MyObject> manager;
    WeakArc<MyObject> ref1 = manager.create(1, 2);  // This reference stays alive

    {
        WeakArc<MyObject> ref2 = manager.create(2, 3);  // These two will expire
        WeakArc<MyObject> ref3 = manager.create(4, 5);  // at end of this scope
    }

    EXPECT_EQ(manager.size(), 3u);
    const size_t removedCount = manager.cleanUp();
    EXPECT_EQ(removedCount, 2u);  // Only ref2 and ref3 should be removed
    EXPECT_EQ(manager.size(), 1u);  // ref1 still holds a valid reference
}

#include <catch2/catch_test_macros.hpp>
#define WINDOWS_LEAN_AND_MEAN
#include <catch2/catch_test_macros.hpp>
#include <thread>
#include <chrono>
#include <iostream>
#include <sstream>
#include <Gorgon/Utils/Logging.h>

TEST_CASE("Console Logging Behavior Verification", "[Logger]") {
    Gorgon::Utils::Logger logObj("Test module", true, true);

    std::ostringstream buffer;
    logObj.InitializeStream(buffer);

    logObj << "Hello " << 5;

    std::this_thread::sleep_for(std::chrono::seconds(1));

    logObj << "t" << std::endl << "a";

    logObj.SetSection("Changed");
    logObj.SetMarkDate(false);
    logObj.Log("One more log! ");

    buffer.seekg(0, std::ios::beg);

    std::string dateStr, timeStr;
    buffer >> dateStr >> timeStr;

    Gorgon::Time::Date timestamp(dateStr + "T" + timeStr);
    auto current = Gorgon::Time::Date::Now();

    REQUIRE((current - timestamp).TotalSeconds() < 2);

    // Verify section tokens
    std::string secPart1, secPart2;
    buffer >> secPart1 >> secPart2;
    REQUIRE(secPart1 == "Test");
    REQUIRE(secPart2 == "module");

    // Verify initial message parts
    std::string msg1, msg2;
    buffer >> msg1 >> msg2;
    REQUIRE(msg1 == "Hello");
    REQUIRE(msg2 == "5");

    // Skip intermediate tokens until 't'
    for (int i = 0; i < 5; ++i) {
        buffer >> msg1;
    }
    REQUIRE(msg1 == "t");

    char newlineChar;
    buffer.read(&newlineChar, 1);
    REQUIRE(newlineChar == '\n' || newlineChar == '\r');

    // Read next token after newline
    buffer >> msg1;
    REQUIRE(msg1 == "a");

    // Check section change and error prefix
    buffer >> secPart1 >> secPart2;
    REQUIRE(secPart1 == "Changed");
    buffer >> msg1;
    REQUIRE(msg1 == "Error!");

    // Clear buffer and test new logging behavior
    buffer.str("");
    logObj.SetMarkTime(false);
    logObj << "Test2";

    buffer >> secPart1 >> msg1;
    REQUIRE(secPart1 == "Changed");
    REQUIRE(msg1 == "Test2");

    // Disable color and verify
    logObj.DisableColor();
    REQUIRE(logObj.IsColorEnabled() == false);

    // Log success message
    logObj.Log("Finally", Gorgon::Utils::Logger::LogType::Success);
    buffer >> secPart1 >> msg1 >> msg2;
    REQUIRE(secPart1 == "Changed");
    REQUIRE(msg1 == "Success:");
    REQUIRE(msg2 == "Finally");
}

