namespace {
    constexpr int MaxStatusLines = DebugUI::StatusLines;
    constexpr int MaxLogLines = DebugUI::LogLines;
    constexpr int LineSize = DebugUI::LineLength;

    char* statusBuffer[MaxStatusLines];
    char* logBuffer[MaxLogLines];
    int activeStatusCount = 0;
    int currentLogIndex = 0; // points to next slot to write (circular)
}

DebugUI::DebugUI() {
    // Allocate and zero-initialize log buffers
    for (int idx = 0; idx < MaxLogLines; ++idx) {
        logBuffer[idx] = static_cast<char*>(std::malloc(LineSize));
        std::memset(logBuffer[idx], 0, LineSize);
    }

    // Allocate and zero-initialize status buffers
    for (int idx = 0; idx < MaxStatusLines; ++idx) {
        statusBuffer[idx] = static_cast<char*>(std::malloc(LineSize));
        std::memset(statusBuffer[idx], 0, LineSize);
    }

    RenderData = Iron::Drawlist::New();
    auto fontManager = ReCraftCore::GetInstance()->GetAssetManager();
    auto fontPtr = fontManager->Get<Iron::Font>("font");
    RenderData->SetFont(fontPtr);
}

DebugUI::~DebugUI() {
    // Free all allocated log lines
    for (int i = 0; i < MaxLogLines; ++i) {
        if (logBuffer[i]) {
            std::free(logBuffer[i]);
            logBuffer[i] = nullptr;
        }
    }

    // Free all allocated status lines
    for (int j = 0; j < MaxStatusLines; ++j) {
        if (statusBuffer[j]) {
            std::free(statusBuffer[j]);
            statusBuffer[j] = nullptr;
        }
    }

    RenderData.reset();
}

void DebugUI::Text(const char* format, ...) {
    if (activeStatusCount >= MaxStatusLines) {
        return;
    }

    va_list args;
    va_start(args, format);
    vsnprintf(statusBuffer[activeStatusCount], LineSize, format, args);
    va_end(args);

    ++activeStatusCount;
}

void DebugUI::Log(const char* format, ...) {
    // Circular buffer: overwrite oldest entry when full
    int writeIndex = currentLogIndex % MaxLogLines;
    char* targetLine = logBuffer[writeIndex];

    va_list args;
    va_start(args, format);
    vsnprintf(targetLine, LineSize, format, args);
    va_end(args);

    currentLogIndex = (currentLogIndex + 1) % MaxLogLines;
}

void DebugUI::Draw() {
    RenderData->SetFontScale(0.5f);

    // Draw logs starting from top-left corner
    float verticalPos = 0.0f;
    const float lineHeight = 12.0f;

    // Iterate through log lines in reverse order (newest first), up to max visible height
    int logCount = 0;
    for (int i = 0; i < MaxLogLines && verticalPos < 240.0f; ++i) {
        int readIndex = (currentLogIndex - 1 - i + MaxLogLines) % MaxLogLines;
        const char* line = logBuffer[readIndex];
        if (line && line[0] != '\0') {
            RenderData->DrawText(Amy::fvec2(0.0f, verticalPos), line, 0xffffffffu);
            verticalPos += lineHeight;
            ++logCount;
        }
    }

    // Reset vertical position for status lines
    verticalPos = 0.0f;

    // Draw status lines and clear them after rendering
    for (int k = 0; k < activeStatusCount; ++k) {
        RenderData->DrawText(Amy::fvec2(0.0f, verticalPos), statusBuffer[k], 0xffffffffu);
        verticalPos += lineHeight;

        // Clear the status line after drawing
        std::memset(statusBuffer[k], 0, LineSize);
    }

    // Reset active status count for next frame
    activeStatusCount = 0;
}

