// Async logger API stress test — adjusted decimation counts and marker usage
TEST_CASE(test_async_logger_api_boost, "Diagnostics") {
    SessionInfo session;
    session.vehicle_name = "BoostCar";
    session.track_name = "BoostTrack";
    const char* dir_path = "tmp_boost_logs/";

    // Prevent redundant start attempts
    AsyncLogger& log_system = AsyncLogger::Get();
    log_system.Start(session, dir_path);
    log_system.Start(session, dir_path); // No-op on second call

    LogFrame sample_frame{};
    std::memset(&sample_frame, 0, sizeof(sample_frame));

    // Marker-based logging bypasses decimation
    log_system.SetMarker();
    log_system.Log(sample_frame); // Logged due to marker
    sample_frame.marker = true;
    log_system.Log(sample_frame); // Explicit marker always logs

    // Decimated logging
    sample_frame.marker = false;
    for (int n = 0; n < 10; ++n) {
        log_system.Log(sample_frame);
    }

    // Buffer overflow simulation
    // DECIMATION_FACTOR = 4, BUFFER_THRESHOLD = 200 → need ~800 frames to exceed
    for (int m = 0; m < 850; ++m) {
        log_system.Log(sample_frame);
    }

    // Stop and log after shutdown
    log_system.Stop();
    log_system.Stop(); // Double stop is safe
    log_system.Log(sample_frame); // Should be ignored

    std::filesystem::remove_all("tmp_boost_logs");
}

