// Refresh Magnu strings by executing external tool if Holmes is active
DataNode RefreshMagnuStrings(DataArray *arr) {
    DataArray *loadedData = nullptr;

    if (IsHolmesActive(2)) {
        String command = MakeString("%s\\sysutl_r.exe -magnu_strings", FileSystemRoot());
        if (SystemExecute(command) == 0) {
            loadedData = DataLoadFromFile("magnu.dta", true);
        } else {
            MILO_LOG("Failed to execute sysutl");
        }
    } else {
        MILO_LOG("Holmes required for Magnu string retrieval");
    }

    if (loadedData) {
        TheLocale.ApplyMagnuStrings(loadedData);
        return static_cast<int>(loadedData->Length());
    } else {
        return 0;
    }
}

