#include <ocs2_core/misc/Numerics.h>

namespace ocs2 {

PerformanceIndex& PerformanceIndex::operator+=(const PerformanceIndex& rhs) {
  // Accumulate each field from the right-hand side operand
  merit += rhs.merit;
  cost += rhs.cost;
  dualFeasibilitiesSSE += rhs.dualFeasibilitiesSSE;
  dynamicsViolationSSE += rhs.dynamicsViolationSSE;
  equalityConstraintsSSE += rhs.equalityConstraintsSSE;
  inequalityConstraintsSSE += rhs.inequalityConstraintsSSE;
  equalityLagrangian += rhs.equalityLagrangian;
  inequalityLagrangian += rhs.inequalityLagrangian;
  return *this;
}

PerformanceIndex& PerformanceIndex::operator*=(const scalar_t factor) {
  // Scale all metrics by the given scalar factor
  merit *= factor;
  cost *= factor;
  dualFeasibilitiesSSE *= factor;
  dynamicsViolationSSE *= factor;
  equalityConstraintsSSE *= factor;
  inequalityConstraintsSSE *= factor;
  equalityLagrangian *= factor;
  inequalityLagrangian *= factor;
  return *this;
}

bool PerformanceIndex::isApprox(const PerformanceIndex& other, const scalar_t tolerance) const {
  // Compare each component using almost_eq with specified tolerance
  bool equal = true;
  equal &= numerics::almost_eq(merit, other.merit, tolerance);
  equal &= numerics::almost_eq(cost, other.cost, tolerance);
  equal &= numerics::almost_eq(dualFeasibilitiesSSE, other.dualFeasibilitiesSSE, tolerance);
  equal &= numerics::almost_eq(dynamicsViolationSSE, other.dynamicsViolationSSE, tolerance);
  equal &= numerics::almost_eq(equalityConstraintsSSE, other.equalityConstraintsSSE, tolerance);
  equal &= numerics::almost_eq(inequalityConstraintsSSE, other.inequalityConstraintsSSE, tolerance);
  equal &= numerics::almost_eq(equalityLagrangian, other.equalityLagrangian, tolerance);
  equal &= numerics::almost_eq(inequalityLagrangian, other.inequalityLagrangian, tolerance);
  return equal;
}

void swap(PerformanceIndex& first, PerformanceIndex& second) {
  // Swap corresponding members using std::swap
  std::swap(first.merit, second.merit);
  std::swap(first.cost, second.cost);
  std::swap(first.dualFeasibilitiesSSE, second.dualFeasibilitiesSSE);
  std::swap(first.dynamicsViolationSSE, second.dynamicsViolationSSE);
  std::swap(first.equalityConstraintsSSE, second.equalityConstraintsSSE);
  std::swap(first.inequalityConstraintsSSE, second.inequalityConstraintsSSE);
  std::swap(first.equalityLagrangian, second.equalityLagrangian);
  std::swap(first.inequalityLagrangian, second.inequalityLagrangian);
}

PerformanceIndex toPerformanceIndex(const Metrics& m) {
  PerformanceIndex result;
  result.merit = 0.0;  // placeholder — solver will populate later
  result.cost = m.cost;

  // Initialize constraint violations and Lagrangians
  result.dualFeasibilitiesSSE = 0.0;  // to be filled by solver
  result.dynamicsViolationSSE = getEqConstraintsSSE(m.dynamicsViolation);

  // Equality constraints: combine state and state-input equality parts
  result.equalityConstraintsSSE =
      getEqConstraintsSSE(m.stateEqConstraint) + getEqConstraintsSSE(m.stateInputEqConstraint);

  // Inequality constraints: combine state and state-input inequality parts
  result.inequalityConstraintsSSE =
      getIneqConstraintsSSE(m.stateIneqConstraint) + getIneqConstraintsSSE(m.stateInputIneqConstraint);

  // Lagrangian penalties: sum over state and state-input contributions
  result.equalityLagrangian =
      sumPenalties(m.stateEqLagrangian) + sumPenalties(m.stateInputEqLagrangian);
  result.inequalityLagrangian =
      sumPenalties(m.stateIneqLagrangian) + sumPenalties(m.stateInputIneqLagrangian);

  return result;
}

PerformanceIndex toPerformanceIndex(const Metrics& m, const scalar_t dt) {
  auto perfIdx = toPerformanceIndex(m);
  // Note: cost scaling is omitted as it's already accounted for in multiple_shooting::computeIntermediateMetrics()
  // Apply time-step scaling to SSE-based quantities
  perfIdx.dualFeasibilitiesSSE *= dt;
  perfIdx.dynamicsViolationSSE *= dt;
  perfIdx.equalityConstraintsSSE *= dt;
  perfIdx.inequalityConstraintsSSE *= dt;
  return perfIdx;
}

std::ostream& operator<<(std::ostream& out, const PerformanceIndex& perfIdx) {
  constexpr size_t tabWidth = 12;
  const auto indent = out.width();
  out << std::left;

  // First line: Merit & Cost
  out << std::setw(indent) << "";
  out << "Rollout Merit:              " << std::setw(tabWidth) << perfIdx.merit;
  out << "Rollout Cost:               " << std::setw(tabWidth) << perfIdx.cost << '\n';

  // Second line: Feasibility & Dynamics SSEs
  out << std::setw(indent) << "";
  out << "Dual feasibilities SSE:     " << std::setw(tabWidth) << perfIdx.dualFeasibilitiesSSE;
  out << "Dynamics violation SSE:     " << std::setw(tabWidth) << perfIdx.dynamicsViolationSSE << '\n';

  // Third line: Constraint SSEs
  out << std::setw(indent) << "";
  out << "Equality constraints SSE:   " << std::setw(tabWidth) << perfIdx.equalityConstraintsSSE;
  out << "Inequality constraints SSE: " << std::setw(tabWidth) << perfIdx.inequalityConstraintsSSE << '\n';

  // Fourth line: Lagrangian values
  out << std::setw(indent) << "";
  out << "Equality Lagrangian:        " << std::setw(tabWidth) << perfIdx.equalityLagrangian;
  out << "Inequality Lagrangian:      " << std::setw(tabWidth) << perfIdx.inequalityLagrangian;

  return out;
}

}  // namespace ocs2

