extern "C" char **environ;

namespace fuzzer {

static std::mutex CommandMutex;

// Track active users of the command execution functionality
static int ConcurrentCommandUsers = 0;

// Store original signal configurations for later restoration
static struct sigaction SavedSigIntHandler;
static struct sigaction SavedSigQuitHandler;
static sigset_t PreviousSignalMask;

// Thread-safe command execution on Apple platforms
int ExecuteCommand(const std::string &CmdLine) {
    posix_spawnattr_t SpawnAttrs;
    if (posix_spawnattr_init(&SpawnAttrs))
        return -1;

    // Handle signal management only when first thread enters
    {
        std::lock_guard<std::mutex> Guard(CommandMutex);
        if (ConcurrentCommandUsers == 0) {
            struct sigaction IgnoreAction;
            sigset_t BlockSet;

            memset(&IgnoreAction, 0, sizeof(IgnoreAction));
            IgnoreAction.sa_handler = SIG_IGN;

            if (sigaction(SIGINT, &IgnoreAction, &SavedSigIntHandler) == -1) {
                Printf("Unable to ignore SIGINT\n");
                (void)posix_spawnattr_destroy(&SpawnAttrs);
                return -1;
            }

            if (sigaction(SIGQUIT, &IgnoreAction, &SavedSigQuitHandler) == -1) {
                Printf("Unable to ignore SIGQUIT\n");
                (void)sigaction(SIGINT, &SavedSigIntHandler, nullptr);
                (void)posix_spawnattr_destroy(&SpawnAttrs);
                return -1;
            }

            sigemptyset(&BlockSet);
            sigaddset(&BlockSet, SIGCHLD);
            if (sigprocmask(SIG_BLOCK, &BlockSet, &PreviousSignalMask) == -1) {
                Printf("Failed to block SIGCHLD\n");
                (void)sigaction(SIGQUIT, &SavedSigQuitHandler, nullptr);
                (void)sigaction(SIGINT, &SavedSigIntHandler, nullptr);
                (void)posix_spawnattr_destroy(&SpawnAttrs);
                return -1;
            }
        }
        ++ConcurrentCommandUsers;
    }

    // Ensure cleanup happens regardless of exit path
    auto CleanupGuard = [](const posix_spawnattr_t *attrs, int *count) {
        {
            std::lock_guard<std::mutex> guard(CommandMutex);
            --(*count);
            if (*count == 0) {
                bool restoreFailed = false;
                if (sigaction(SIGINT, &SavedSigIntHandler, nullptr) == -1) {
                    Printf("Could not restore SIGINT handler\n");
                    restoreFailed = true;
                }
                if (sigaction(SIGQUIT, &SavedSigQuitHandler, nullptr) == -1) {
                    Printf("Could not restore SIGQUIT handler\n");
                    restoreFailed = true;
                }
                if (sigprocmask(SIG_SETMASK, &PreviousSignalMask, nullptr) == -1) {
                    Printf("Failed to unblock SIGCHLD\n");
                    restoreFailed = true;
                }
                if (restoreFailed)
                    return -1;
            }
        }
        return 0;
    };

    // Configure spawn attributes for proper signal handling in child
    sigset_t DefaultSignals;
    sigemptyset(&DefaultSignals);
    sigaddset(&DefaultSignals, SIGINT);
    sigaddset(&DefaultSignals, SIGQUIT);
    posix_spawnattr_setsigdefault(&SpawnAttrs, &DefaultSignals);

    posix_spawnattr_setsigmask(&SpawnAttrs, &PreviousSignalMask);

    short Flags = POSIX_SPAWN_SETSIGDEF | POSIX_SPAWN_SETSIGMASK;
    posix_spawnattr_setflags(&SpawnAttrs, Flags);

    pid_t ChildPid;
    const char *ShellPath = "/bin/sh";
    const char *Args[] = { "sh", "-c", CmdLine.c_str(), nullptr };
    int ResultCode = 0, ExitStatus = 0;

    ResultCode = posix_spawn(&ChildPid, ShellPath, nullptr, &SpawnAttrs,
                             const_cast<char *const *>(Args), environ);
    posix_spawnattr_destroy(&SpawnAttrs);

    if (ResultCode == 0) {
        pid_t WaitResult;
        do {
            WaitResult = waitpid(ChildPid, &ExitStatus, 0);
        } while (WaitResult == -1 && errno == EINTR);

        if (WaitResult == -1)
            ExitStatus = -1;
    } else if (ResultCode == ENOMEM || ResultCode == EAGAIN) {
        ExitStatus = -1;
    } else {
        ExitStatus = W_EXITCODE(127, 0);
    }

    // Perform cleanup and restore signal handlers if needed
    int cleanupResult = CleanupGuard(&SpawnAttrs, &ConcurrentCommandUsers);
    if (cleanupResult != 0 && ExitStatus >= 0)
        ExitStatus = cleanupResult;

    return ExitStatus;
}

