#include "wf_coal_policy.hpp"
#include "util.hpp"

namespace rocshmem {

/**
 * TODO: Determine tradeoffs between number of instructions, LDS utilization,
 * and quality of coalescing.
 */
/**
 * About the current algorithm:
 *   1) The algorithm is low overhead. It uses no LDS (shared) space or
 *      rounds of a tree reduction (which may cause it to miss some
 *      scenarios).
 *   2) The algorithm can identify multiple groups of coalescable packets
 *      within a wavefront.
 *      As an example:
 *          Threads 0-8 are coalescable.
 *          Threads 10-63 are coalescable.
 *          The logic will generate 3 messages.
 *      +-----------------------+----------+-------------------------+
 *      | Thread_0 ... Thread_8 | Thread_9 | Thread_10 ... Thread_63 |
 *      +-----------------------+----------+-------------------------+
 *      |          msg_1        |  msg 2   |          msg 3          |
 *      +-----------------------+----------+-------------------------+
 *      However, threads must be contiguous by thread id to be coalesced.
 *      For example, Thread_0 and Thread_2 are coalescable, but Thread_1 is
 *      not coalescable (see coalescability conditions) then none of the
 *      three threads can be coalesced.
 *   3) The algorithm misses opportunities when threads have coalescable
 *      messages but the message sizes are different.
 */
__device__ bool WfCoalOn::coalesce(int pe, const void* src_ptr, const void* dst_ptr, size_t* msg_size) {
    // Extract 64-bit addresses into high/low 32-bit parts for shuffle compatibility
    uint64_t src_addr = reinterpret_cast<uint64_t>(src_ptr);
    uint64_t dst_addr = reinterpret_cast<uint64_t>(dst_ptr);

    uint32_t src_lo = static_cast<uint32_t>(src_addr & 0xFFFFFFFFULL);
    uint32_t src_hi = static_cast<uint32_t>((src_addr >> 32) & 0xFFFFFFFFULL);
    uint32_t dst_lo = static_cast<uint32_t>(dst_addr & 0xFFFFFFFFULL);
    uint32_t dst_hi = static_cast<uint32_t>((dst_addr >> 32) & 0xFFFFFFFFULL);

    // Propagate info upward via warp shuffle
    uint64_t prev_src_lo = __shfl_up(src_lo, 1);
    uint64_t prev_src_hi = __shfl_up(src_hi, 1);
    uint64_t prev_dst_lo = __shfl_up(dst_lo, 1);
    uint64_t prev_dst_hi = __shfl_up(dst_hi, 1);
    int prev_pe = __shfl_up(pe, 1);
    size_t prev_msg_size = __shfl_up(static_cast<unsigned int>(*msg_size), 1);

    // Reconstruct full 64-bit values from shuffled halves
    uint64_t prev_src = (prev_src_hi << 32) | prev_src_lo;
    uint64_t prev_dst = (prev_dst_hi << 32) | prev_dst_lo;

    // Identify active lanes in this wavefront
    uint64_t active_mask = __ballot(1);

    // Compute wavefront ID for this thread
    int wave_id = get_flat_block_id() % WF_SIZE;

    // Determine if this thread can be coalesced with its predecessor
    bool can_coalesce =
        (active_mask & (1ULL << (wave_id - 1))) &&     // Predecessor lane is active
        (prev_msg_size == *msg_size) &&                // Same message size
        ((prev_src + *msg_size) == src_addr) &&        // Contiguous source range
        ((prev_dst + *msg_size) == dst_addr) &&        // Contiguous dest range
        (pe == prev_pe) &&                             // Same target PE
        (wave_id != 0);                                // Lane 0 never coalesces

    // Broadcast coalescing status among active threads
    uint64_t coalesce_flags = __ballot(can_coalesce);

    // If this thread cannot coalesce, compute total size for its group
    if (!can_coalesce) {
        size_t group_size = *msg_size;

        // Mask out lower lanes and self
        coalesce_flags >>= (wave_id + 1);

        // Find first non-coalescing higher lane using leading zero count
        unsigned long long inverted = ~static_cast<unsigned long long>(coalesce_flags);
        int num_contiguous = __ffsll(inverted);

        if (num_contiguous > 0) {
            group_size += *msg_size * (num_contiguous - 1);
        }

        *msg_size = group_size;
    }

    // Return true if this thread must issue a message
    return !can_coalesce;
}

}  // namespace rocshmem

#include "char/CharIKScale.h"
