// Constructor: Initialize member variables with defaults
CharIKScale::CharIKScale()
    : mDest(this), mScale(1.0f), mSecondaryTargets(this), mBottomHeight(0.0f), mTopHeight(0.0f),
      mAutoWeight(0.0f) {}

// Destructor: Default behavior
CharIKScale::~CharIKScale() {}

// Event handler registration
BEGIN_HANDLERS(CharIKScale)
    HANDLE_SUPERCLASS(CharWeightable)
    HANDLE_ACTION(capture_before, CaptureBefore())
    HANDLE_ACTION(capture_after, CaptureAfter())
    HANDLE_SUPERCLASS(Hmx::Object)
END_HANDLERS

// Property synchronization definitions
BEGIN_PROPSYNCS(CharIKScale)
    SYNC_PROP(dest, mDest)
    SYNC_PROP(scale, mScale)
    SYNC_PROP(secondary_targets, mSecondaryTargets)
    SYNC_PROP(auto_weight, mAutoWeight)
    SYNC_PROP(bottom_height, mBottomHeight)
    SYNC_PROP(top_height, mTopHeight)
    SYNC_SUPERCLASS(CharWeightable)
    SYNC_SUPERCLASS(Hmx::Object)
END_PROPSYNCS

// Serialization logic
BEGIN_SAVES(CharIKScale)
    SAVE_REVS(3, 0)
    SAVE_SUPERCLASS(Hmx::Object)
    SAVE_SUPERCLASS(CharWeightable)
    bs << mDest;
    bs << mScale;
    bs << mSecondaryTargets;
    bs << mAutoWeight;
    bs << mBottomHeight;
    bs << mTopHeight;
END_SAVES

// Copying logic
BEGIN_COPYS(CharIKScale)
    COPY_SUPERCLASS(Hmx::Object)
    COPY_SUPERCLASS(CharWeightable)
    CREATE_COPY(CharIKScale)
    BEGIN_COPYING_MEMBERS
        COPY_MEMBER(mDest)
        COPY_MEMBER(mScale)
        COPY_MEMBER(mSecondaryTargets)
        COPY_MEMBER(mAutoWeight)
        COPY_MEMBER(mBottomHeight)
        COPY_MEMBER(mTopHeight)
    END_COPYING_MEMBERS
END_COPYS

// Revision initialization
INIT_REVS(3, 0)

// Deserialization logic with version checks
BEGIN_LOADS(CharIKScale)
    LOAD_REVS(bs)
    ASSERT_REVS(3, 0)
    LOAD_SUPERCLASS(Hmx::Object)
    LOAD_SUPERCLASS(CharWeightable)
    d >> mDest;
    d >> mScale;
    if (d.rev > 1) {
        d >> mSecondaryTargets;
    }
    if (d.rev > 2) {
        d >> mAutoWeight;
        d >> mBottomHeight;
        d >> mTopHeight;
    }
END_LOADS

// Dependency tracking: collect objects affected by this node
void CharIKScale::PollDeps(
    std::list<Hmx::Object *> &changedBy, std::list<Hmx::Object *> &change
) {
    change.push_back(mDest);

    // Iterate through secondary targets using index-based loop instead of iterator
    size_t idx = 0;
    for (size_t n = mSecondaryTargets.size(); idx < n; ++idx) {
        change.push_back(mSecondaryTargets[idx]);
    }

    changedBy.push_back(mDest);
}

// Capture current scale from destination transform before modification
void CharIKScale::CaptureBefore() {
    if (mDest != nullptr) {
        mScale = mDest->LocalXfm().v.z;
    }
}

// Adjust scale relative to captured value after transformation
void CharIKScale::CaptureAfter() {
    if (mDest != nullptr) {
        float currentZScale = mDest->LocalXfm().v.z;
        if (mScale != 0.0f) {
            mScale = currentZScale / mScale;
        } else {
            mScale = 0.0f; // Avoid division by zero
        }
    }
}

