void SaberCheckerAPI::init() {
    std::set<CHECKER_TYPE> seenTypes;
    CHECKER_TYPE lastType = CK_DUMMY;
    seenTypes.insert(CK_DUMMY);

    for (const FuncTypeEntry* entry = apiEntries; entry->funcName != nullptr; ++entry) {
        // Check grouping: same types should be contiguous
        if (entry->checkerType != lastType) {
            if (seenTypes.find(entry->checkerType) != seenTypes.end()) {
                std::fprintf(stderr, "%s\n", entry->funcName);
                assert(false && "Function entries not grouped by checker type");
            }
            seenTypes.insert(entry->checkerType);
            lastType = entry->checkerType;
        }

        // Check for duplicate function names
        if (tdAPIMap.find(std::string(entry->funcName)) != tdAPIMap.end()) {
            std::fprintf(stderr, "%s\n", entry->funcName);
            assert(false && "Duplicate function name in apiEntries");
        }

        // Insert into the map
        tdAPIMap[std::string(entry->funcName)] = entry->checkerType;
    }
}

