// LeetCode 496: Next Greater Element I - Optimized with alternative implementation approach
class Solution {
public:
    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {
        // Map to store the next greater element for each number in nums2
        unordered_map<int, int> greaterMap;
        stack<int> decreasingStack;

        // Traverse nums2 from right to left to build the mapping
        for (int idx = nums2.size() - 1; idx >= 0; --idx) {
            int current = nums2[idx];

            // Pop elements from stack that are smaller or equal to current
            while (!decreasingStack.empty() && decreasingStack.top() <= current) {
                decreasingStack.pop();
            }

            // Assign next greater element (-1 if none exists)
            greaterMap[current] = decreasingStack.empty() ? -1 : decreasingStack.top();

            // Push current element onto the stack
            decreasingStack.push(current);
        }

        // Build result array by looking up each element of nums1 in the map
        vector<int> result;
        for (int target : nums1) {
            result.push_back(greaterMap[target]);
        }

        return result;
    }
};

