FileEntry* FileHeader::AppendFile(const std::wstring& filename, unsigned int size /* = 0 */)
{
    assert(filename.length() < 64);

    wchar_t buffer[64] = {0};
    size_t copyLen = std::min(sizeof(wchar_t) * 64, sizeof(wchar_t) * filename.length());
    memcpy(buffer, filename.c_str(), copyLen);

    // Check if file already exists in table
    for (size_t i = 0; i < entries.size(); ++i)
    {
        if (wcscmp(entries[i]->data.filename, buffer) == 0)
        {
            return entries[i];
        }
    }

    // Add new entry to table
    FileEntry* newEntry = new FileEntry(buffer, size, GetNextDataPosition());
    entries.push_back(newEntry);
    currentFile = newEntry;
    return currentFile;
}

void FileHeader::DeleteFile(FileEntry* target)
{
    if (target == nullptr) return;

    AdjustOffsets(target, target->getFileSize(), true);

    auto iter = std::find(entries.begin(), entries.end(), target);
    if (iter != entries.end())
    {
        entries.erase(iter);
    }

#ifndef _CONTENT_PACKAGE
    wprintf(L"Removed file %ls\n", target->data.filename);
#endif

    delete target;
}

void FileHeader::WriteHeader(LPVOID memoryBuffer)
{
    unsigned int headerLocation = GetNextDataPosition();
    unsigned int entryCount = static_cast<unsigned int>(entries.size());

    int* basePtr = static_cast<int*>(memoryBuffer);

#ifdef __PSVITA__
    VirtualCopyTo(basePtr, &headerLocation, sizeof(headerLocation));
#else
    *basePtr = headerLocation;
#endif

#ifdef __PSVITA__
    VirtualCopyTo(basePtr + 1, &entryCount, sizeof(entryCount));
#else
    *(basePtr + 1) = entryCount;
#endif

    short* versionPtr = reinterpret_cast<short*>(basePtr + 2);

#ifdef __PSVITA__
    VirtualCopyTo(versionPtr, &initialSaveVersion, sizeof(initialSaveVersion));
#else
    *versionPtr = initialSaveVersion;
#endif

    short currentVersion = SAVE_FILE_VERSION_NUMBER;
#ifdef __PSVITA__
    VirtualCopyTo(versionPtr + 1, &currentVersion, sizeof(currentVersion));
#else
    *(versionPtr + 1) = currentVersion;
#endif

#ifdef _DEBUG_FILE_HEADER
    app.DebugPrintf("Write save file with original version: %d, and current version %d\n", initialSaveVersion, currentVersion);
#endif

    char* dataPos = static_cast<char*>(memoryBuffer) + headerLocation;

#ifdef _DEBUG_FILE_HEADER
    app.DebugPrintf("\n\nWrite file Header: Offset = %d, Size = %d\n", headerLocation, entryCount);
#endif

    for (size_t i = 0; i < entries.size(); ++i)
    {
#ifdef __PSVITA__
        VirtualCopyTo(dataPos, &entries[i]->data, sizeof(FileEntrySaveData));
#else
        memcpy(dataPos, &entries[i]->data, sizeof(FileEntrySaveData));
#endif
        dataPos += sizeof(FileEntrySaveData);
    }
}

void FileHeader::ReadHeader(LPVOID memoryBuffer, ESavePlatform plat /*= SAVE_FILE_PLATFORM_LOCAL*/)
{
    unsigned int headerLocation;
    unsigned int entryCount;

    platformType = plat;
    switch(platformType)
    {
    case SAVE_FILE_PLATFORM_X360:
    case SAVE_FILE_PLATFORM_PS3:
        byteOrder = BIGENDIAN;
        break;
    case SAVE_FILE_PLATFORM_XBONE:
    case SAVE_FILE_PLATFORM_WIN64:
    case SAVE_FILE_PLATFORM_PS4:
    case SAVE_FILE_PLATFORM_PSVITA:
        byteOrder = LITTLEENDIAN;
        break;
    default:
        assert(0);
        platformType = SAVE_FILE_PLATFORM_LOCAL;
        byteOrder = localByteOrder;
        break;
    }

    int* basePtr = static_cast<int*>(memoryBuffer);

#ifdef __PSVITA__
    VirtualCopyFrom(&headerLocation, basePtr, sizeof(headerLocation));
#else
    headerLocation = *basePtr;
#endif
    if (IsByteOrderMismatch()) System::ReverseULONG(&headerLocation);

#ifdef __PSVITA__
    VirtualCopyFrom(&entryCount, basePtr + 1, sizeof(entryCount));
#else
    entryCount = *(basePtr + 1);
#endif
    if (IsByteOrderMismatch()) System::ReverseULONG(&entryCount);

    short* versionPtr = reinterpret_cast<short*>(basePtr + 2);

#ifdef __PSVITA__
    VirtualCopyFrom(&initialSaveVersion, versionPtr, sizeof(initialSaveVersion));
#else
    initialSaveVersion = *versionPtr;
#endif
    if (IsByteOrderMismatch()) System::ReverseSHORT(&initialSaveVersion);

#ifdef __PSVITA__
    VirtualCopyFrom(&saveVersion, versionPtr + 1, sizeof(saveVersion));
#else
    saveVersion = *(versionPtr + 1);
#endif
    if (IsByteOrderMismatch()) System::ReverseSHORT(&saveVersion);

#ifdef _DEBUG_FILE_HEADER
    app.DebugPrintf("Read save file with orignal version: %d, and current version %d\n", initialSaveVersion, saveVersion);
    app.DebugPrintf("\n\nRead file Header: Offset = %d, Size = %d\n", headerLocation, entryCount);
#endif

    char* dataPos = static_cast<char*>(memoryBuffer) + headerLocation;

    switch(saveVersion)
    {
    case SAVE_FILE_VERSION_CHUNK_INHABITED_TIME:
    case SAVE_FILE_VERSION_COMPRESSED_CHUNK_STORAGE:
    case SAVE_FILE_VERSION_DURANGO_CHANGE_MAP_DATA_MAPPING_SIZE:
    case SAVE_FILE_VERSION_CHANGE_MAP_DATA_MAPPING_SIZE:
    case SAVE_FILE_VERSION_MOVED_STRONGHOLD:
    case SAVE_FILE_VERSION_NEW_END:
    case SAVE_FILE_VERSION_POST_LAUNCH:
    case SAVE_FILE_VERSION_LAUNCH:
        {
            FileEntrySaveData* currentData = reinterpret_cast<FileEntrySaveData*>(dataPos);
            for(unsigned int i = 0; i < entryCount; ++i)
            {
                FileEntry* entry = new FileEntry();

#ifdef __PSVITA__
                VirtualCopyFrom(&entry->data, currentData, sizeof(FileEntrySaveData));
#else
                memcpy(&entry->data, currentData, sizeof(FileEntrySaveData));
#endif
                if(IsByteOrderMismatch())
                {
                    System::ReverseWCHARA(entry->data.filename, 64);
                    System::ReverseULONG(&entry->data.length);
                    System::ReverseULONG(&entry->data.startOffset);
                    System::ReverseULONGLONG(&entry->data.lastModifiedTime);
                }

                entry->currentFilePointer = entry->data.startOffset;
                currentFile = entry;
                entries.push_back(entry);

#ifdef _DEBUG_FILE_HEADER
                app.DebugPrintf("File: %ls, Start = %d, Length = %d, End = %d, Timestamp = %lld\n", 
                               entry->data.filename, entry->data.startOffset, entry->data.length, 
                               entry->data.startOffset + entry->data.length, entry->data.lastModifiedTime);
#endif
                ++currentData;
            }
        }
        break;

    case SAVE_FILE_VERSION_PRE_LAUNCH:
        {
            unsigned int index = 0;
            while(index < entryCount)
            {
                FileEntry* entry = new FileEntry();

#ifdef __PSVITA__
                VirtualCopyFrom(&entry->data, dataPos, sizeof(FileEntrySaveDataV1));
#else
                memcpy(&entry->data, dataPos, sizeof(FileEntrySaveDataV1));
#endif
                entry->currentFilePointer = entry->data.startOffset;
                currentFile = entry;
                entries.push_back(entry);

#ifdef _DEBUG_FILE_HEADER
                app.DebugPrintf("File: %ls, Start = %d, Length = %d, End = %d\n", 
                               entry->data.filename, entry->data.startOffset, entry->data.length, 
                               entry->data.startOffset + entry->data.length);
#endif

                index += sizeof(FileEntrySaveDataV1);
                dataPos += sizeof(FileEntrySaveDataV1);
            }
        }
        break;

    default:
#ifndef _CONTENT_PACKAGE
        app.DebugPrintf("**********  Invalid save version %d\n", saveVersion);
        __debugbreak();
#endif
        break;
    }
}

unsigned int FileHeader::GetNextDataPosition()
{
    unsigned int totalSize = SAVE_FILE_HEADER_SIZE;
    for(size_t i = 0; i < entries.size(); ++i)
    {
        if(entries[i]->getFileSize() > 0)
        {
            totalSize += entries[i]->getFileSize();
        }
    }
    return totalSize;
}

unsigned int FileHeader::GetTotalSize()
{
    return GetNextDataPosition() + (sizeof(FileEntrySaveData) * static_cast<unsigned int>(entries.size()));
}

void FileHeader::AdjustOffsets(FileEntry* target, DWORD offsetChange, bool subtract /*= false*/)
{
    bool found = false;
    for(size_t i = 0; i < entries.size(); ++i)
    {
        if(found)
        {
            if(subtract)
            {
                entries[i]->data.startOffset -= offsetChange;
                entries[i]->currentFilePointer -= offsetChange;
            }
            else
            {
                entries[i]->data.startOffset += offsetChange;
                entries[i]->currentFilePointer += offsetChange;
            }
        }
        else if(entries[i] == target)
        {
            found = true;
        }
    }
}

bool FileHeader::HasFile(const std::wstring& filename)
{
    for(size_t i = 0; i < entries.size(); ++i)
    {
        if(wcscmp(entries[i]->data.filename, filename.c_str()) == 0)
        {
            return true;
        }
    }
    return false;
}

std::vector<FileEntry*>* FileHeader::GetFilesWithPrefix(const std::wstring& prefix)
{
    std::vector<FileEntry*>* result = nullptr;

    for(size_t i = 0; i < entries.size(); ++i)
    {
        if(wcsncmp(entries[i]->data.filename, prefix.c_str(), prefix.size()) == 0)
        {
            if(result == nullptr)
            {
                result = new std::vector<FileEntry*>();
            }
            result->push_back(entries[i]);
        }
    }
    return result;
}

#if defined(__PS3__) || defined(__ORBIS__) || defined(__PSVITA__)
static bool IsHexCharacter(wchar_t wc)
{
    if(wc >= L'0' && wc <= L'9')
        return true;
    if(wc >= L'a' && wc <= L'f')
        return true;
    return false;
}

static bool IsHexString(wchar_t* ws, int size)
{
    for(int i = 0; i < size; i++)
    {
        if(!IsHexCharacter(ws[i]))
            return false;
    }
    return true;
}

static bool IsDecimalCharacter(wchar_t wc)
{
    return (wc >= L'0' && wc <= L'9');
}

static bool IsDecimalString(wchar_t* ws, int size)
{
    for(int i = 0; i < size; i++)
    {
        if(!IsDecimalCharacter(ws[i]))
            return false;
    }
    return true;
}

static wchar_t* LocateFilenameStart(wchar_t* str)
{
    wchar_t* nameStart = str;
    int length = wcslen(str);
    for(int i = 0; i < length; i++)
    {
        if(str[i] == L'/')
            nameStart = &str[i+1];
    }
    return nameStart;
}

std::wstring FileHeader::GetPlayerDataFilenameForLoad(const PlayerUID& pUID)
{
    std::wstring result = L"";
    std::vector<FileEntry*>* files = GetDatFilesWithOnlineID(pUID);

    if(!files)
    {
        files = GetDatFilesWithMacAndUserID(pUID);
    }

    if(!files)
    {
        if(pUID.isPrimaryUser())
        {
            files = GetDatFilesWithPrimaryUser();
        }
    }

    if(files)
