std::vector<FileEntry*>* FileHeader::GetValidPlayerDatFiles()
{
    std::vector<FileEntry*>* result = nullptr;

    for(size_t i = 0; i < entries.size(); ++i)
    {
        wchar_t* filenameOnly = LocateFilenameStart(entries[i]->data.filename);
        int nameLen = wcslen(filenameOnly);

        if(nameLen <= 4)
            continue;

        if(wcsncmp(&filenameOnly[nameLen-4], L".dat", 4) != 0)
            continue;

        if((wcsncmp(&filenameOnly[0], L"P_", 2) != 0) && (wcsncmp(&filenameOnly[0], L"N_", 2) != 0))
            continue;

        if(!IsHexString(&filenameOnly[2], 12))
            continue;

        if(filenameOnly[14] != L'_')
            continue;

        if(!IsDecimalString(&filenameOnly[15], 8))
            continue;

        if(result == nullptr)
        {
            result = new std::vector<FileEntry*>();
        }
        result->push_back(entries[i]);
    }

    return result;
}

std::vector<FileEntry*>* FileHeader::GetDatFilesWithOnlineID(const PlayerUID& pUID)
{
    if(!pUID.isSignedIntoPSN())
        return nullptr;

    std::vector<FileEntry*>* datFiles = GetValidPlayerDatFiles();
    if(datFiles == nullptr)
        return nullptr;

    wchar_t onlineIDW[64];
    mbstowcs(onlineIDW, pUID.getOnlineID(), 64);
    std::vector<FileEntry*>* result = nullptr;
    int onlineIDSize = wcslen(onlineIDW);

    if(onlineIDSize == 0)
        return nullptr;

    wcscat(onlineIDW, L".dat");

#ifdef __ORBIS__
    onlineIDSize = wcslen(onlineIDW);
#else
    static const int onlineIDStart = 24;
#endif

    char tempStr[128];
    for(size_t i = 0; i < datFiles->size(); ++i)
    {
        wchar_t* filenameOnly = LocateFilenameStart(datFiles->at(i)->data.filename);
        wcstombs(tempStr, filenameOnly, 128);
        app.DebugPrintf("file : %s\n", tempStr);

#ifdef __ORBIS__
        int onlineIDStart = wcslen(filenameOnly) - onlineIDSize;
        if(onlineIDStart > 0)
#else
        if(wcslen(filenameOnly) > onlineIDStart)
#endif
        {
            if(wcsncmp(&filenameOnly[onlineIDStart], onlineIDW, onlineIDSize) == 0)
            {	
                if(result == nullptr)
                {
                    result = new std::vector<FileEntry*>();
                }
                result->push_back(datFiles->at(i));
            }
        }
    }

    delete datFiles;
    if(result) std::sort(result->begin(), result->end(), FileEntry::newestFirst);
    return result;
}

