namespace hydra::horizon::filesystem {

void IFile::Save(std::string_view host_path) const {
    // Open output file for writing in binary mode
    std::fstream output_file(
        std::string(host_path),
        std::ios::out | std::ios::binary);

    io::IostreamStream writer(output_file);

    // Obtain read access to current file content
    auto* read_stream = const_cast<IFile*>(this)->Open(FileOpenFlags::Read);

    // Prepare buffer for chunked transfer
    std::array<u8, 0x800> temp_buffer;

    // Copy data in chunks until end of stream is reached
    while (read_stream->GetSeek() < read_stream->GetSize()) {
        u64 remaining_bytes = read_stream->GetSize() - read_stream->GetSeek();
        u64 bytes_to_read = std::min(static_cast<u64>(temp_buffer.size()), remaining_bytes);

        std::span<u8> read_span(temp_buffer.data(), temp_buffer.data() + bytes_to_read);
        read_stream->ReadToSpan(read_span);

        std::span<const u8> write_span(temp_buffer.data(), temp_buffer.data() + bytes_to_read);
        writer.WriteSpan(write_span);
    }

    delete read_stream;
}

