// Helper struct to generate test data for heap dump benchmarks
struct TestDataGenerator {
    std::vector<StringBox> objectNames;
    std::vector<StringBox> edgePropertyNames;

    TestDataGenerator() {
        // Generate 20 distinct object names: Object0, Object1, ..., Object19
        for (size_t idx = 0; idx < 20; ++idx) {
            objectNames.emplace_back(STRING_FORMAT("Object{}", idx));
        }

        // Generate 1000 property names: prop0, prop1, ..., prop999
        for (size_t idx = 0; idx < 1000; ++idx) {
            edgePropertyNames.emplace_back(STRING_FORMAT("prop{}", idx));
        }
    }

    // Populate a heap dump builder with synthetic data
    void fillHeapDump(JavaScriptHeapDumpBuilder& builder) {
        const size_t totalNodes = 100000;
        const size_t maxEdgesPerNode = 5;

        for (size_t nodeIndex = 0; nodeIndex < totalNodes; ++nodeIndex) {
            auto nodeKind = static_cast<JavaScriptHeapDumpNodeType>(
                nodeIndex % static_cast<size_t>(JavaScriptHeapDumpNodeType::COUNT)
            );

            builder.startNode(nodeKind, 
                              objectNames[nodeIndex % objectNames.size()], 
                              static_cast<uint64_t>(nodeIndex), 
                              42);

            // Add up to maxEdgesPerNode outgoing edges
            for (size_t targetIndex = nodeIndex + 1; 
                 targetIndex < totalNodes && (targetIndex - nodeIndex) <= maxEdgesPerNode; 
                 ++targetIndex) {

                builder.addEdge(JavaScriptHeapDumpEdgeType::PROPERTY,
                                JavaScriptHeapEdgeIdentifier::named(
                                    edgePropertyNames[targetIndex % edgePropertyNames.size()]
                                ),
                                static_cast<uint64_t>(targetIndex));
            }
        }
    }
};

// Benchmark: constructing a heap dump from scratch
static void ConstructHeapDump(benchmark::State& state) {
    TestDataGenerator generator;
    for (auto _ : state) {
        JavaScriptHeapDumpBuilder builder;
        generator.fillHeapDump(builder);
        benchmark::DoNotOptimize(builder.finalize());
    }
}
BENCHMARK(ConstructHeapDump);

// Benchmark: parsing an existing heap dump
static void DecodeHeapDump(benchmark::State& state) {
    TestDataGenerator generator;
    JavaScriptHeapDumpBuilder initialBuilder;
    generator.fillHeapDump(initialBuilder);
    auto serializedDump = initialBuilder.finalize();

    for (auto _ : state) {
        SimpleExceptionTracker errorTracker;
        JavaScriptHeapDumpParser decoder(serializedDump.data(), serializedDump.size(), errorTracker);

        for (const auto& nodeEntry : decoder.getNodes()) {
            for (const auto& connection : nodeEntry.getEdges()) {
                benchmark::DoNotOptimize(connection.getIdentifier());
            }
        }
    }
}
BENCHMARK(DecodeHeapDump);

// Benchmark: merging multiple heap dumps together
static void CombineHeapDumps(benchmark::State& state) {
    TestDataGenerator generator;
    JavaScriptHeapDumpBuilder baseBuilder;
    generator.fillHeapDump(baseBuilder);
    auto sourceDump = baseBuilder.finalize();

    for (auto _ : state) {
        JavaScriptHeapDumpBuilder merger;
        SimpleExceptionTracker tracker;

        // Append the same dump three times
        merger.appendDump(sourceDump.data(), sourceDump.size(), tracker);
        merger.appendDump(sourceDump.data(), sourceDump.size(), tracker);
        merger.appendDump(sourceDump.data(), sourceDump.size(), tracker);

        benchmark::DoNotOptimize(merger.finalize());
    }
}
BENCHMARK(CombineHeapDumps);

BENCHMARK_MAIN();

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int R, H;
    cin >> R >> H;

    // Moduli used for queries - sum to 30
    vector<int> moduli = {13, 7, 5, 3, 2};

    // Query all robots simultaneously: for each modulus m, query each residue class r in [0, m-1]
    for (int m : moduli) {
        for (int r = 0; r < m; ++r) {
            // Build list of positions p where p % m == r
            vector<int> positions;
            for (int p = 1; p <= 1000; ++p) {
                if (p % m == r) {
                    positions.push_back(p);
                }
            }

            // Output the query
            cout << "? " << positions.size();
            for (int pos : positions) {
                cout << " " << pos;
            }
            cout << endl;
            cout.flush();
        }
    }

    // Signal end of queries and read responses
    cout << "@" << endl;
    cout.flush();

    int L;
    cin >> L;
    vector<int> responses(L);
    for (int i = 0; i < L; ++i) {
        cin >> responses[i];
    }

    // Organize responses by modulus: collect residues that returned 1 for each modulus
    vector<vector<int>> positive_residues(moduli.size());
    int response_index = 0;
    for (int i = 0; i < moduli.size(); ++i) {
        int m = moduli[i];
        for (int r = 0; r < m; ++r) {
            if (responses[response_index + r] == 1) {
                positive_residues[i].push_back(r);
            }
        }
        response_index += m;
    }

    // Precompute residues for numbers 1..1000 under each modulus
    vector<vector<int>> residues(1001, vector<int>(moduli.size()));
    for (int num = 1; num <= 1000; ++num) {
        for (int mi = 0; mi < moduli.size(); ++mi) {
            residues[num][mi] = num % moduli[mi];
        }
    }

    // Search for pair (a, b), a <= b, satisfying all constraints
    int found_a = -1, found_b = -1;
    for (int x = 1; x <= 1000 && found_a == -1; ++x) {
        for (int y = x; y <= 1000; ++y) {
            bool valid_pair = true;

            // Check against each modulus
            for (int mi = 0; mi < moduli.size() && valid_pair; ++mi) {
                int m = moduli[mi];
                int rx = residues[x][mi];
                int ry = residues[y][mi];

                // For each residue r modulo m, verify coverage matches expected
                for (int r = 0; r < m; ++r) {
                    bool is_covered = (rx == r) || (ry == r);
                    bool should_be_covered = false;

                    for (int rr : positive_residues[mi]) {
                        if (rr == r) {
                            should_be_covered = true;
                            break;
                        }
                    }

                    if (is_covered != should_be_covered) {
                        valid_pair = false;
                        break;
                    }
                }
            }

            if (valid_pair) {
                found_a = x;
                found_b = y;
                break;
            }
        }
    }

    // Output final answer
    cout << "! " << found_a << " " << found_b << endl;
    cout.flush();

    return 0;
}

