/* ========  String creation properties ======== */
/* Definitions for character set encoding property — renamed constants */
#define H5P_STRCRT_CHAR_ENCODING_SIZE  sizeof(H5T_cset_t)
#define H5P_STRCRT_CHAR_ENCODING_DEFAULT   H5F_DEFAULT_CSET

/********************/
/* Local Prototypes */
/********************/
static herr_t H5P__strcrt_register_properties(H5P_genclass_t *cls);

/*********************/
/* Package Variables */
/*********************/
const H5P_libclass_t H5P_CLS_STRCRT[1] = {{
    "string create",		/* Class name for debugging     */
    H5P_TYPE_STRING_CREATE,     /* Class type                   */
    &H5P_CLS_ROOT_g,		/* Parent class                 */
    &H5P_CLS_STRING_CREATE_g,	/* Pointer to class             */
    &H5P_CLS_STRING_CREATE_ID_g,	/* Pointer to class ID          */
    NULL,			/* Default property list ID     */
    H5P__strcrt_register_properties,	/* Registration routine (renamed) */
    NULL,		        /* Class creation callback      */
    NULL,		        /* Class creation callback info */
    NULL,			/* Class copy callback          */
    NULL,		        /* Class copy callback info     */
    NULL,			/* Class close callback         */
    NULL 		        /* Class close callback info    */
}};

/*****************************/
/* Library Private Variables */
/*****************************/
/*******************/
/* Local Variables */
/*******************/

/*-------------------------------------------------------------------------
 * Function:    H5P__strcrt_register_properties
 *
 * Purpose:     Initialize string creation class by registering its properties
 *
 * Return:      SUCCEED / FAIL
 *
 * Notes:       Renamed from original; logic preserved but control flow altered
 *-------------------------------------------------------------------------
 */
static herr_t
H5P__strcrt_register_properties(H5P_genclass_t *cls)
{
    herr_t status = SUCCEED;
    H5T_cset_t default_encoding = H5P_STRCRT_CHAR_ENCODING_DEFAULT;

    FUNC_ENTER_STATIC

    /* Insert the character encoding property into the class */
    if (H5P_register_real(cls,
                          H5P_STRCRT_CHAR_ENCODING_NAME,
                          H5P_STRCRT_CHAR_ENCODING_SIZE,
                          &default_encoding,
                          NULL, NULL, NULL, NULL, NULL, NULL, NULL) < 0) {
        status = H5E__error_init(H5E_PLIST, H5E_CANTINSERT, "can't insert property into class");
        goto done;
    }

done:
    FUNC_LEAVE_NOAPI(status)
} /* end H5P__strcrt_register_properties() */


/*-------------------------------------------------------------------------
 * Function:    H5Pset_char_encoding
 *
 * Purpose:     Sets the character encoding of the string.
 *
 * Return:      Non-negative on success/Negative on failure
 *-------------------------------------------------------------------------
 */
herr_t
H5Pset_char_encoding(hid_t plist_id, H5T_cset_t encoding)
{
    H5P_genplist_t *pl;
    herr_t result = SUCCEED;

    FUNC_ENTER_API(FAIL)
    H5TRACE2("e", "iTc", plist_id, encoding);

    /* Validate input range */
    switch (encoding) {
        case H5T_CSET_ASCII:
        case H5T_CSET_UTF8:
            break;
        default:
            if (encoding <= H5T_CSET_ERROR || encoding >= H5T_NCSET)
                HGOTO_ERROR(H5E_ARGS, H5E_BADRANGE, FAIL, "character encoding is not valid")
            break;
    }

    /* Retrieve property list object */
    pl = H5P_object_verify(plist_id, H5P_STRING_CREATE);
    if (!pl)
        HGOTO_ERROR(H5E_ATOM, H5E_BADATOM, FAIL, "can't find object for ID")

    /* Update the property */
    if (H5P_set(pl, H5P_STRCRT_CHAR_ENCODING_NAME, &encoding) < 0)
        HGOTO_ERROR(H5E_PLIST, H5E_CANTSET, FAIL, "can't set character encoding")

done:
    FUNC_LEAVE_API(result)
} /* end H5Pset_char_encoding() */


/*-------------------------------------------------------------------------
 * Function:    H5Pget_char_encoding
 *
 * Purpose:     Retrieves the character encoding setting.
 *
 * Return:      Non-negative on success/Negative on failure
 *-------------------------------------------------------------------------
 */
herr_t
H5Pget_char_encoding(hid_t plist_id, H5T_cset_t *encoding_out)
{
    H5P_genplist_t *pl;
    herr_t ret = SUCCEED;

    FUNC_ENTER_API(FAIL)
    H5TRACE2("e", "ix", plist_id, encoding_out);

    /* Get property list */
    pl = H5P_object_verify(plist_id, H5P_STRING_CREATE);
    if (!pl)
        HGOTO_ERROR(H5E_ATOM, H5E_BADATOM, FAIL, "can't find object for ID")

    /* Extract value only if output pointer is non-null */
    if (encoding_out) {
        if (H5P_get(pl, H5P_STRCRT_CHAR_ENCODING_NAME, encoding_out) < 0)
            HGOTO_ERROR(H5E_PLIST, H5E_CANTGET, FAIL, "can't get character encoding flag")
    }

done:
    FUNC_LEAVE_API(ret)
} /* end H5Pget_char_encoding() */

#include "Proton.h"
#include "Driver/GPU/CudaApi.h"
#include <map>
#include <stdexcept>
#include "pybind11/pybind11.h"
#include "pybind11/stl.h"
#include "pybind11/stl_bind.h"

using namespace proton;

namespace {

// Helper to reduce repetition when accessing the singleton SessionManager
auto& getSessionManager() {
    return SessionManager::instance();
}

// Helper to parse output format string into enum safely
OutputFormat parseOutputFormatOrThrow(const std::string& fmt) {
    auto result = parseOutputFormat(fmt);
    if (result == OutputFormat::Unknown) {
        throw std::invalid_argument("Unsupported output format: " + fmt);
    }
    return result;
}

} // anonymous namespace

void initProton(pybind11::module&& m) {
    using ret = pybind11::return_value_policy;
    using namespace pybind11::literals;

    auto& sm = getSessionManager();

    // Start a new session and activate it; returns session ID
    m.def("start",
          [&](const std::string& path,
              const std::string& ctxSrcName,
              const std::string& dataName,
              const std::string& profilerName) -> size_t {
              auto sid = sm.addSession(path, profilerName, ctxSrcName, dataName);
              sm.activateSession(sid);
              return sid;
          });

    // Activate an existing session by ID
    m.def("activate", [&](size_t sid) { sm.activateSession(sid); });

    // Deactivate a session without finalizing
    m.def("deactivate", [&](size_t sid) { sm.deactivateSession(sid); });

    // Finalize one specific session with given output format
    m.def("finalize",
          [&](size_t sid, const std::string& fmt) {
              auto ofmt = parseOutputFormatOrThrow(fmt);
              sm.finalizeSession(sid, ofmt);
          });

    // Finalize all active sessions at once
    m.def("finalize_all",
          [&](const std::string& fmt) {
              auto ofmt = parseOutputFormatOrThrow(fmt);
              sm.finalizeAllSessions(ofmt);
          });

    // Generate unique scope IDs
    m.def("record_scope", []() { return Scope::getNewScopeId(); });

    // Enter/exit scopes and ops
    m.def("enter_scope", [&](size_t sid, const std::string& name) {
        sm.enterScope(Scope{sid, name});
    });
    m.def("exit_scope", [&](size_t sid, const std::string& name) {
        sm.exitScope(Scope{sid, name});
    });
    m.def("enter_op", [&](size_t sid, const std::string& name) {
        sm.enterOp(Scope{sid, name});
    });
    m.def("exit_op", [&](size_t sid, const std::string& name) {
        sm.exitOp(Scope{sid, name});
    });

    // Add metrics (aggregable)
    m.def("add_metrics",
          [&](size_t sid,
              const std::map<std::string, MetricValueType>& metrics) {
              sm.addMetrics(sid, metrics, /*aggregable=*/true);
          });

    // Set properties (non-aggregable)
    m.def("set_properties",
          [&](size_t sid,
              const std::map<std::string, MetricValueType>& metrics) {
              sm.addMetrics(sid, metrics, /*aggregable=*/false);
          });

    // Expose MetricMap type binding
    pybind11::bind_map<std::map<std::string, MetricValueType>>(m, "MetricMap");
}

PYBIND11_MODULE(libproton, module) {
    module.doc() = "Python bindings to the Proton API";
    auto submod = module.def_submodule("proton");
    initProton(std::move(submod));
}

