int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (!(cin >> testCases)) return 0;

    for (int caseNum = 0; caseNum < testCases; ++caseNum) {
        int n, m;
        if (!(cin >> n >> m)) break;

        // Read and discard all edges
        for (int i = 0; i < m; ++i) {
            int u, v;
            if (!(cin >> u >> v)) return 0;
        }

        // Output the answer: m zeros separated by spaces
        cout << "! ";
        for (int i = 0; i < m; ++i) {
            cout << 0;
            if (i != m - 1) cout << ' ';
        }
        cout << '\n';
        cout.flush();
    }

    return 0;
}

#include <cstddef>
#include "Windows64_App.h"
#include "Windows64_UIController.h"
#include "extraX64.h"
#include <4J_Render.h>
#include <gdraw_d3d11.h>

#define USE_IGGY_SYSTEM

class ConsoleUIController {
public:
    void initialize(
        ID3D11Device*           device,
        ID3D11DeviceContext*    context,
        ID3D11RenderTargetView* renderTarget,
        ID3D11DepthStencilView* depthStencil,
        S32                     width,
        S32                     height
    );

    void presentFrame();

    void startCustomDrawing(IggyCustomDrawCallbackRegion* region, CustomDrawData* data);
    CustomDrawData* prepareCustomDraw(UIScene* scene, IggyCustomDrawCallbackRegion* region);
    CustomDrawData* computeCustomDraw(IggyCustomDrawCallbackRegion* region);
    void finishCustomDrawing(IggyCustomDrawCallbackRegion* region);

    void updateTileOrigin(S32 offsetX, S32 offsetY);

    GDrawTexture* acquireReplacementTexture(int texID);
    void releaseReplacementTexture(void* userData, GDrawTexture* handle);

    void cleanup();
};

ConsoleUIController ui;

void ConsoleUIController::initialize(
    ID3D11Device*           device,
    ID3D11DeviceContext*    context,
    ID3D11RenderTargetView* renderTarget,
    ID3D11DepthStencilView* depthStencil,
    S32                     width,
    S32                     height
) {
#ifdef USE_IGGY_SYSTEM
    m_pRenderTargetView = renderTarget;
    m_pDepthStencilView = depthStencil;

    // Common setup phase 1
    preInit(width, height);

    gdraw_funcs = gdraw_D3D11_CreateContext(device, context, width, height);
    if (!gdraw_funcs) {
        app.DebugPrintf("Failed to initialize GDraw!\n");
#ifndef _CONTENT_PACKAGE
        __debugbreak();
#endif
        app.FatalLoadError();
    }

    /* Define resource limits for GDraw. These are hints for memory usage.
       Actual allocation is handled by D3D; these values just guide caching. */
    gdraw_D3D11_SetResourceLimits(GDRAW_D3D11_RESOURCE_vertexbuffer, 5000, 16 * 1024 * 1024);
    gdraw_D3D11_SetResourceLimits(GDRAW_D3D11_RESOURCE_texture,       5000, 128 * 1024 * 1024);
    gdraw_D3D11_SetResourceLimits(GDRAW_D3D11_RESOURCE_rendertarget,  10,   32 * 1024 * 1024);

    // Hook GDraw into Iggy system
    IggySetGDraw(gdraw_funcs);

    // Use default DirectSound for audio playback
    IggyAudioUseDirectSound();

    // Common setup phase 2
    postInit();
#endif
}

void ConsoleUIController::presentFrame() {
#ifdef USE_IGGY_SYSTEM
    // Set up render target and depth buffer for drawing
    gdraw_D3D11_SetTileOrigin(m_pRenderTargetView, m_pDepthStencilView, nullptr, 0, 0);

    renderScenes();

    // Finalize frame rendering
    gdraw_D3D11_NoMoreGDrawThisFrame();
#endif
}

void ConsoleUIController::startCustomDrawing(IggyCustomDrawCallbackRegion* region, CustomDrawData* data) {
    PIXBeginNamedEvent(0, "Iggy custom draw begin\n");
    PIXBeginNamedEvent(0, "GDraw configuration");

    gdraw_D3D11_BeginCustomDraw_4J(region, data->mat);

    PIXEndNamedEvent();
}

CustomDrawData* ConsoleUIController::prepareCustomDraw(UIScene* scene, IggyCustomDrawCallbackRegion* region) {
    CustomDrawData* cfg = new CustomDrawData();
    cfg->x0 = region->x0;
    cfg->x1 = region->x1;
    cfg->y0 = region->y0;
    cfg->y1 = region->y1;

    PIXBeginNamedEvent(0, "Iggy custom draw begin\n");
    gdraw_D3D11_BeginCustomDraw_4J(region, cfg->mat);
    setupCustomDrawGameStateAndMatrices(scene, cfg);

    return cfg;
}

CustomDrawData* ConsoleUIController::computeCustomDraw(IggyCustomDrawCallbackRegion* region) {
    CustomDrawData* cfg = new CustomDrawData();
    cfg->x0 = region->x0;
    cfg->x1 = region->x1;
    cfg->y0 = region->y0;
    cfg->y1 = region->y1;

    gdraw_D3D11_CalculateCustomDraw_4J(region, cfg->mat);
    return cfg;
}

void ConsoleUIController::finishCustomDrawing(IggyCustomDrawCallbackRegion* region) {
    endCustomDrawGameStateAndMatrices();
    gdraw_D3D11_EndCustomDraw(region);
    PIXEndNamedEvent();
}

void ConsoleUIController::updateTileOrigin(S32 xOff, S32 yOff) {
    gdraw_D3D11_SetTileOrigin(m_pRenderTargetView, m_pDepthStencilView, nullptr, xOff, yOff);
}

GDrawTexture* ConsoleUIController::acquireReplacementTexture(int texID) {
    ID3D11ShaderResourceView* srv = RenderManager.TextureGetTexture(texID);
    ID3D11Resource* res;
    srv->GetResource(&res);

    ID3D11Texture2D* tex2D = static_cast<ID3D11Texture2D*>(res);
    D3D11_TEXTURE2D_DESC desc;
    tex2D->GetDesc(&desc);

    GDrawTexture* gTex = gdraw_D3D11_WrappedTextureCreate(srv);
    return gTex;
}

void ConsoleUIController::releaseReplacementTexture(void* userData, GDrawTexture* handle) {
    gdraw_D3D11_WrappedTextureDestroy(handle);
}

void ConsoleUIController::cleanup() {
#ifdef USE_IGGY_SYSTEM
    gdraw_D3D11_DestroyContext();
#endif
}

