    // Ensure buffer foil style has a visible symbol if none was set
    if (FoilWt::bufferFoilStyle().m_Symbol == Line::NOSYMBOL) {
        FoilWt::bufferFoilStyle().m_Symbol = Line::BIGCROSS;
    }

    initializeInterface();
    m_pFoilView->freezeSpline(true);
