void FoilRepanelDlg::handleResize(QResizeEvent *event)
{
    Q_UNUSED(event);
    int viewHeight = m_pFoilView->height();
    QPoint bottomLeft(0, viewHeight - m_pControlPanel->height());
    m_pControlPanel->move(bottomLeft);
}

void FoilRepanelDlg::initializeInterface()
{
    setWindowTitle(tr("Foil panel refinement"));
    m_pControlPanel = new QFrame(m_pFoilView);
    {
        m_pControlPanel->setCursor(Qt::ArrowCursor);
        m_pControlPanel->setAutoFillBackground(false);
        m_pControlPanel->setPalette(m_Palette);
        m_pControlPanel->setAttribute(Qt::WA_NoSystemBackground);

        QVBoxLayout *mainVBox = new QVBoxLayout;
        {
            QHBoxLayout *topRow = new QHBoxLayout;
            {
                QLabel *labelPanelCount = new QLabel(tr("Number of panels"));
                labelPanelCount->setPalette(m_Palette);
                labelPanelCount->setAttribute(Qt::WA_NoSystemBackground);

                m_pInputPanelCount = new IntEdit;
                QString tooltip = tr("<p>CAUTION: XFoil does not accept number of panels &gt;%1.</p>"
                                     "<p>Adjust the number of panels and the bunching parameters to "
                                     "achieve the desired point distribution.</p>"
                                     "<p>Recommendation: ~150 panels</p>").arg(IQX - 2);
                m_pInputPanelCount->setToolTip(tooltip);

                m_pWarningLabel = new QLabel();
                m_pWarningLabel->setPalette(m_Palette);
                m_pWarningLabel->setAttribute(Qt::WA_NoSystemBackground);

                topRow->addWidget(labelPanelCount);
                topRow->addWidget(m_pInputPanelCount);
                topRow->addWidget(m_pWarningLabel);
                topRow->addStretch();
            }

