using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;

    const int ROWS = 100, COLS = 100;
    vector<string> grid(ROWS, string(COLS, '@'));

    // Fill bottom half with white cells
    for (int r = 50; r < ROWS; ++r) {
        fill(grid[r].begin(), grid[r].end(), '.');
    }

    // Add white islands in the top black region (avoiding the boundary at row 49-50)
    int remainingWhite = w - 1;
    for (int r = 0; r < 49 && remainingWhite > 0; r += 2) {
        for (int c = 0; c < COLS && remainingWhite > 0; c += 2) {
            grid[r][c] = '.';
            --remainingWhite;
        }
    }

    // Add black islands in the bottom white region (avoiding the boundary at row 49-50)
    int remainingBlack = b - 1;
    for (int r = 51; r < ROWS && remainingBlack > 0; r += 2) {
        for (int c = 0; c < COLS && remainingBlack > 0; c += 2) {
            grid[r][c] = '@';
            --remainingBlack;
        }
    }

    cout << ROWS << " " << COLS << "\n";
    for (const auto& row : grid) {
        cout << row << "\n";
    }

    return 0;
}

