#include "unicode/utypes.h"
#if !UCONFIG_NO_NORMALIZATION
#if !UCONFIG_NO_FORMATTING
#if !UCONFIG_NO_MF2

#include "unicode/messageformat2_data_model.h"
#include "messageformat2_macros.h"
#include "messageformat2_serializer.h"
#include "uvector.h" // U_ASSERT

U_NAMESPACE_BEGIN

namespace message2 {

using namespace data_model;

// Private helper methods for serialization

void Serializer::whitespace() {
    result += ' ';
}

void Serializer::emit(UChar32 ch) {
    result += ch;
}

void Serializer::emit(const UnicodeString& str) {
    result += str;
}

void Serializer::emit(const std::u16string_view& token) {
    result.append(token);
}

void Serializer::emit(const Literal& lit) {
    if (lit.isQuoted()) {
        emit('|');
    }

    const UnicodeString& content = lit.unquoted();
    int32_t idx = 0;
    while (idx < content.length()) {
        UChar32 c = content[idx];
        switch (c) {
            case '\\':
            case '|':
            case '{':
            case '}': {
                emit('\\');
                break;
            }
            default:
                break;
        }
        emit(c);
        ++idx;
    }

    if (lit.isQuoted()) {
        emit('|');
    }
}

void Serializer::emit(const Key& key) {
    if (key.isWildcard()) {
        emit('*');
        return;
    }
    emit(key.asLiteral());
}

void Serializer::emit(const SelectorKeys& keys) {
    const Key* arr = keys.getKeysInternal();
    int32_t count = keys.len;
    U_ASSERT(count > 0); // Should not be called for single-pattern variant

    for (int32_t i = 0; i < count; ++i) {
        if (i > 0) {
            whitespace();
        }
        emit(arr[i]);
    }
}

void Serializer::emit(const Operand& operand) {
    U_ASSERT(!operand.isNull());

    if (operand.isVariable()) {
        emit('$');
        emit(operand.asVariable());
    } else {
        emit(operand.asLiteral());
    }
}

void Serializer::emit(const OptionMap& options) {
    UErrorCode status = U_ZERO_ERROR;
    U_ASSERT(!options.bogus);

    for (int32_t i = 0; i < options.size(); ++i) {
        const Option& opt = options.getOption(i, status);
        whitespace();
        emit(opt.getName());
        emit('=');
        emit(opt.getValue());
    }
}

void Serializer::emitAttributes(const OptionMap& attrs) {
    UErrorCode status = U_ZERO_ERROR;
    U_ASSERT(!attrs.bogus);

    for (int32_t i = 0; i < attrs.size(); ++i) {
        const Option& attr = attrs.getOption(i, status);
        whitespace();
        emit('@');
        emit(attr.getName());

        const Operand& val = attr.getValue();
        if (!val.isNull()) {
            emit('=');
            emit(val);
        }
    }
}

void Serializer::emit(const Expression& expr) {
    emit('{');

    if (!expr.isFunctionCall()) {
        emit(expr.getOperand());
    } else {
        if (!expr.isStandaloneAnnotation()) {
            emit(expr.getOperand());
            whitespace();
        }

        UErrorCode status = U_ZERO_ERROR;
        const Operator* op = expr.getOperator(status);
        U_ASSERT(U_SUCCESS(status));

        emit(':');
        emit(op->getFunctionName());
        emit(op->getOptionsInternal());
    }

    emitAttributes(expr.getAttributesInternal());
    emit('}');
}

void Serializer::emit(const PatternPart& part) {
    if (part.isText()) {
        const UnicodeString& text = part.asText();
        int32_t pos = 0;
        while (pos < text.length()) {
            UChar32 c = text[pos];
            switch (c) {
                case '|':
                case '\\':
                case '{':
                case '}': {
                    emit('\\');
                    break;
                }
                default:
                    break;
            }
            emit(c);
            ++pos;
        }
        return;
    }

    if (part.isMarkup()) {
        const Markup& markup = part.asMarkup();
        emit('{');

        if (markup.isClose()) {
            emit('/');
        } else {
            emit('#');
        }

        emit(markup.getName());
        emit(markup.getOptionsInternal());
        emitAttributes(markup.getAttributesInternal());

        if (markup.isStandalone()) {
            emit('/');
        }

        emit('}');
        return;
    }

    // Must be an expression
    emit(part.contents());
}

void Serializer::emit(const Pattern& pat) {
    int32_t len = pat.numParts();
    emit("{{");
    for (int32_t i = 0; i < len; ++i) {
        emit(pat.getPart(i));
    }
    emit("}}");
}

void Serializer::serializeDeclarations() {
    const Binding* bindings = dataModel.getLocalVariablesInternal();
    U_ASSERT(dataModel.bindingsLen == 0 || bindings != nullptr);

    for (int32_t i = 0; i < dataModel.bindingsLen; ++i) {
        const Binding& b = bindings[i];
        if (b.isLocal()) {
            emit("local ");
            emit('$');
            emit(b.getVariable());
            emit('=');
        } else {
            emit("input");
        }
        emit(b.getValue());
    }
}

void Serializer::serializeSelectors() {
    U_ASSERT(!dataModel.hasPattern());

    const VariableName* selectors = dataModel.getSelectorsInternal();
    emit("match");

    for (int32_t i = 0; i < dataModel.numSelectors(); ++i) {
        whitespace();
        emit('$');
        emit(selectors[i]);
    }
}

void Serializer::serializeVariants() {
    U_ASSERT(!dataModel.hasPattern());

    const Variant* variants = dataModel.getVariantsInternal();
    whitespace();

    for (int32_t i = 0; i < dataModel.numVariants(); ++i) {
        const Variant& v = variants[i];
        emit(v.getKeys());
        emit(v.getPattern());
    }
}

// Public entry point for full serialization
void Serializer::serialize() {
    serializeDeclarations();

    if (dataModel.hasPattern()) {
        emit(dataModel.getPattern());
    } else {
        serializeSelectors();
        serializeVariants();
    }
}

