#include <iostream>
#include <cstring>
#include <cstdlib>
#include <cerrno>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <semaphore.h>

// Renamed constants and types
const int NULL_INDEX = -1;
const int MAX_REGIONS = 1024;
const int MAX_PAGES = 64;
const int MAX_CONTEXTS = 32;
const int ESM_MAGIC = 0x12345678;

// Renamed data structures
struct RegionInfo {
    char regionName[256];
    int offset;
    int pageId;
    int blockSize;
    int nextRegion;
    int prevRegion;
};

struct PageInfo {
    int shmId;
    int segmentSize;
};

struct ContextData {
    int magicNumber;
    int contextIdentifier;
    int semaphoreId;
    int allocatedRegions;
    RegionInfo regions[MAX_REGIONS];
    int regionHead;
    int holeHead;
    int freeList;
    int totalPages;
    PageInfo pages[MAX_PAGES];
    int pageSize;
};

// Global context array
struct ProcessContext {
    int contextId;
    void* pageAddresses[MAX_PAGES];
    ContextData* contextDescriptor;
    int attachedCount;
} processContexts[MAX_CONTEXTS];

int activeContexts = 0;

// Semaphore operations
static struct sembuf P_op = {0, -1, 0};
static struct sembuf V_op = {0, 1, 0};

#define P_OP(S, R) { \
    if (semop((S), &P_op, 1) != 0) { \
        std::cerr << "Semaphore P operation failed on " << (S) << ": " << strerror(errno) << std::endl; \
        return (R); \
    } \
}

#define V_OP(S, R) { \
    if (semop((S), &V_op, 1) != 0) { \
        std::cerr << "Semaphore V operation failed on " << (S) << ": " << strerror(errno) << std::endl; \
        return (R); \
    } \
}

// Memory management macros
#define DETACH_MEM(PTR, RET) { \
    if (shmdt((PTR))) { \
        std::cerr << "Failed to detach shared memory: " << strerror(errno) << std::endl; \
        return (RET); \
    } \
}

#define DESTROY_MEM(ID, RET) { \
    struct shmid_ds buffer; \
    if (shmctl((ID), IPC_RMID, &buffer) != 0) { \
        std::cerr << "Failed to destroy shared memory segment: " << strerror(errno) << std::endl; \
        return (RET); \
    } \
}

#define GET_LOCAL_ADDR(BASE, OFFSET) ((void*)((char*)(BASE) + (long)(OFFSET)))

// Function declarations
static int connectToContext(int threadId, int contextId);
static void displayContextInfo(struct shmid_ds* segment, ContextData* cd, FILE* output);
static int acquireRegionSlot(RegionInfo regions[], int* freePtr);
static void releaseRegionSlot(RegionInfo regions[], int* freePtr, int index);
static int findRegionByName(RegionInfo regions[], int* head, const char* name);
static int findHoleBySize(RegionInfo regions[], int* head, int requiredSize);
static void addRegionToList(RegionInfo regions[], int* listHead, int newReg);
static void addHoleToList(RegionInfo regions[], int* listHead, int newReg);
static void removeFromList(RegionInfo regions[], int* head, int index);

// Main functions
int createSharedContext(int threadId, int pageSize) {
    // Check context limit
    if (activeContexts >= MAX_CONTEXTS) {
        std::cerr << "Too many contexts (" << MAX_CONTEXTS << ") for process" << std::endl;
        return 0;
    }

    int contextIndex = activeContexts++;

    // Create shared memory segment for context descriptor
    int contextId = shmget(IPC_PRIVATE, sizeof(ContextData), IPC_CREAT | 0666);
    if (contextId < 0) {
        std::cerr << "Cannot create context descriptor: " << strerror(errno) << std::endl;
        return 0;
    }

    // Ensure non-zero context ID
    if (contextId == 0) {
        int altContextId = shmget(IPC_PRIVATE, sizeof(ContextData), IPC_CREAT | 0666);
        if (altContextId < 0) {
            std::cerr << "Cannot create alternative context descriptor: " << strerror(errno) << std::endl;
            return 0;
        }
        DESTROY_MEM(contextId, 0);
        contextId = altContextId;
    }

    // Attach context descriptor
    ContextData* cd = (ContextData*)shmat(contextId, NULL, 0);
    if ((long)cd == -1) {
        std::cerr << "Cannot attach context descriptor: " << strerror(errno) << std::endl;
        DESTROY_MEM(contextId, 0);
        return 0;
    }

    // Create semaphore
    int semId = semget(IPC_PRIVATE, 1, IPC_CREAT | 0666);
    if (semId < 0) {
        std::cerr << "Cannot create semaphore: " << strerror(errno) << std::endl;
        DESTROY_MEM(contextId, 0);
        return 0;
    }

    // Initialize context descriptor
    cd->magicNumber = ESM_MAGIC;
    cd->contextIdentifier = contextId;
    cd->pageSize = pageSize;
    cd->totalPages = 0;
    cd->semaphoreId = semId;
    V_OP(cd->semaphoreId, 0);

    // Initialize region descriptors
    for (int i = 0; i < MAX_REGIONS; i++) {
        RegionInfo* ri = &cd->regions[i];
        memset(ri, 0, sizeof(RegionInfo));
        ri->prevRegion = i - 1;
        ri->nextRegion = i + 1;
    }

    cd->allocatedRegions = 0;
    cd->regions[0].prevRegion = NULL_INDEX;
    cd->regions[MAX_REGIONS - 1].nextRegion = NULL_INDEX;
    cd->freeList = 0;
    cd->regionHead = NULL_INDEX;
    cd->holeHead = NULL_INDEX;

    // Initialize page table
    for (int pi = 0; pi < MAX_PAGES; pi++) {
        PageInfo* pd = &cd->pages[pi];
        memset(pd, 0, sizeof(PageInfo));
        processContexts[contextIndex].pageAddresses[pi] = NULL;
    }

    processContexts[contextIndex].contextId = contextId;
    processContexts[contextIndex].contextDescriptor = cd;
    processContexts[contextIndex].attachedCount = 0;

    return contextId;
}

int deleteSharedContext(int threadId, int ci, int contextId) {
    // Attach context if needed
    if (ci < 0) {
        ci = connectToContext(threadId, contextId);
        if (ci < 0) return -1;
    }

    ContextData* cd = (ContextData*)processContexts[ci].contextDescriptor;
    P_OP(cd->semaphoreId, -1);

    // Destroy all data pages
    for (int pi = 0; pi < cd->totalPages; pi++) {
        DETACH_MEM(processContexts[ci].pageAddresses[pi], -1);
        DESTROY_MEM(cd->pages[pi].shmId, -1);
    }

    // Destroy semaphore
    if (semctl(cd->semaphoreId, 0, IPC_RMID) != 0) {
        std::cerr << "Cannot remove semaphore (" << cd->semaphoreId << ") for context (" << contextId << "): " << strerror(errno) << std::endl;
        return -1;
    }

    // Destroy context descriptor
    DETACH_MEM(cd, -1);
    DESTROY_MEM(contextId, -1);

    // Clear context entry
    processContexts[ci].contextId = 0;
    processContexts[ci].contextDescriptor = NULL;
    processContexts[ci].attachedCount = 0;

    return 0;
}

void* allocateSharedMemory(int threadId, int ci, int contextId, const char* regionName, size_t size) {
    // Attach context if needed
    if (ci < 0) {
        ci = connectToContext(threadId, contextId);
        if (ci < 0) return NULL;
    }

    ContextData* cd = (ContextData*)processContexts[ci].contextDescriptor;
    P_OP(cd->semaphoreId, NULL);

    // Check if region already exists
    int regIndex = findRegionByName(cd->regions, &cd->regionHead, regionName);
    if (regIndex != NULL_INDEX) {
        if (size <= 0) {
            V_OP(cd->semaphoreId, NULL);
            return NULL;
        }

        // Existing region found
        if (size == 0 || size == cd->regions[regIndex].blockSize) {
            void* pageAddr = processContexts[ci].pageAddresses[cd->regions[regIndex].pageId];
            if (pageAddr == NULL) {
                V_OP(cd->semaphoreId, NULL);
                return NULL;
            }
            V_OP(cd->semaphoreId, NULL);
            return GET_LOCAL_ADDR(pageAddr, cd->regions[regIndex].offset);
        } else {
            V_OP(cd->semaphoreId, NULL);
            return NULL;
        }
    }

    // Region not found - need to allocate
    if (size <= 0) {
        V_OP(cd->semaphoreId, NULL);
        return NULL;
    }

    // Find suitable hole
    int holeIndex = findHoleBySize(cd->regions, &cd->holeHead, size);

    if (holeIndex == NULL_INDEX) {
        // No suitable hole - create new page
        if (cd->totalPages == MAX_PAGES) {
            std::cerr << "Page limit reached; increase page size" << std::endl;
            V_OP(cd->semaphoreId, NULL);
            return NULL;
        }

        holeIndex = acquireRegionSlot(cd->regions, &cd->freeList);
        if (holeIndex == NULL_INDEX) {
            std::cerr << "No region descriptors available" << std::endl;
            V_OP(cd->semaphoreId, NULL);
            return NULL;
        }

        int pageIndex = cd->totalPages++;
        cd->pages[pageIndex].segmentSize = std::max((int)size, 1024 * cd->pageSize);
        cd->pages[pageIndex].shmId = shmget(IPC_PRIVATE, cd->pages[pageIndex].segmentSize, IPC_CREAT | 0666);

        if (cd->pages[pageIndex].shmId <= 0) {
            std::cerr << "Cannot create new page: " << strerror(errno) << std::endl;
            cd->totalPages--;
            V_OP(cd->semaphoreId, NULL);
            return NULL;
        }

        void* pageAddr = shmat(cd->pages[pageIndex].shmId, NULL, 0);
        if ((long)pageAddr == -1) {
            std::cerr << "Cannot attach new page: " << strerror(errno) << std::endl;
            DESTROY_MEM(cd->pages[pageIndex].shmId, NULL);
            cd->totalPages--;
            V_OP(cd->semaphoreId, NULL);
            return NULL;
        }

        processContexts[ci].pageAddresses[pageIndex] = pageAddr;
        processContexts[ci].attachedCount++;

        cd->regions[holeIndex].pageId = pageIndex;
        cd->regions[holeIndex].offset = 0;
        cd->regions[holeIndex].blockSize = cd->pages[pageIndex].segmentSize;
    } else {
        removeFromList(cd->regions, &cd->holeHead, holeIndex);
    }

    // Split hole and allocate region
    int newRegIndex = acquireRegionSlot(cd->regions, &cd->freeList);
    if (newRegIndex == NULL_INDEX) {
        std::cerr << "Region descriptors exhausted" << std::endl;
        V_OP(cd->semaphoreId, NULL);
        return NULL;
    }

    strncpy(cd->regions[newRegIndex].regionName, regionName, 255);
    cd->regions[newRegIndex].regionName[255] = '\0';
    cd->regions[newRegIndex].blockSize = size;
    cd->regions[newRegIndex].pageId = cd->regions[holeIndex].pageId;
    cd->regions[newRegIndex].offset = cd->regions[holeIndex].offset;

    addRegionToList(cd->regions, &cd->regionHead, newRegIndex);
    cd->allocatedRegions++;

    // Update remaining hole size
    if ((cd->regions[holeIndex].blockSize -= size) > 0) {
        cd->regions[holeIndex].offset += size;
        addHoleToList(cd->regions, &cd->holeHead, holeIndex);
    } else {
        releaseRegionSlot(cd->regions, &cd->freeList, holeIndex);
    }

    // Zero memory and return address
    void* addr = GET_LOCAL_ADDR(
        processContexts[ci].pageAddresses[cd->regions[newRegIndex].pageId],
        cd->regions[newRegIndex].offset
    );
    memset(addr, 0, size);

    V_OP(cd->semaphoreId, NULL);
    return addr;
}

int freeSharedMemory(int threadId, int ci, int contextId, const char* regionName) {
    // Attach context if needed
    if (ci < 0) {
        ci = connectToContext(threadId, contextId);
        if (ci < 0) return -1;
    }

    ContextData* cd = (ContextData*)processContexts[ci].contextDescriptor;
    P_OP(cd->semaphoreId, -1);

    // Find region
    int regIndex = findRegionByName(cd->regions, &cd->regionHead, regionName);
    if (regIndex == NULL_INDEX) {
        std::cerr << "Cannot find region \"" << regionName << "\" in ESM_Free" << std::endl;
        V_OP(cd->semaphoreId, -1);
        return -1;
    }

    // Move region to holes list
    removeFromList(cd->regions, &cd->regionHead, regIndex);
    memset(cd->regions[regIndex].regionName, 0, 256);
    addHoleToList(cd->regions, &cd->holeHead, regIndex);
    cd->allocatedRegions--;

    // Coalesce adjacent holes
    // Check for holes after current
    for (int r = cd->holeHead; r != NULL_INDEX; r = cd->regions[r].nextRegion) {
        if (cd->regions[r].pageId != cd->regions[regIndex].pageId) continue;
        if (cd->regions[regIndex].offset + cd->regions[regIndex].blockSize != cd->regions[r].offset) continue;

        cd->regions[regIndex].blockSize += cd->regions[r].blockSize;
        removeFromList(cd->regions, &cd->holeHead, r);
        removeFromList(cd->regions, &cd->holeHead, regIndex);
        releaseRegionSlot(cd->regions, &cd->freeList, r);
        addHoleToList(cd->regions, &cd->holeHead, regIndex);
        break;
    }

    // Check for holes before current
    for (int r = cd->holeHead; r != NULL_INDEX; r = cd->regions[r].nextRegion) {
        if (cd->regions[r].pageId != cd->regions[regIndex].pageId) continue;
        if (cd->regions[r].offset + cd->regions[r].blockSize != cd->regions[regIndex].offset) continue;

        cd->regions[r].blockSize += cd->regions[regIndex].blockSize;
        removeFromList(cd->regions, &cd->holeHead, r);
        removeFromList(cd->regions, &cd->holeHead, regIndex);
        releaseRegionSlot(cd->regions, &cd->freeList, regIndex);
        addHoleToList(cd->regions, &cd->holeHead, r);
        break;
    }

    V_OP(cd->semaphoreId, -1);
    return 0;
}

// Internal functions
static int connectToContext(int threadId, int contextId) {
    if (activeContexts >= MAX_CONTEXTS) {
        std::cerr << "Too many contexts for process" << std::endl;
        return -1;
    }

    int contextIndex = activeContexts++;
    processContexts[contextIndex].contextId = contextId;
    processContexts[contextIndex].attachedCount = 0;

    // Attach context descriptor
    processContexts[contextIndex].contextDescriptor = (ContextData*)shmat(contextId, NULL, 0);
    if ((long)processContexts[contextIndex].contextDescriptor == -1) {
        std::cerr << "Cannot attach context descriptor: " << strerror(errno) << std::endl;
        return -1;
    }

    // Attach all pages
    ContextData* cd = processContexts[contextIndex].contextDescriptor;
    for (int pi = 0; pi < cd->totalPages; pi++) {
        processContexts[contextIndex].pageAddresses[pi] = shmat(cd->pages[pi].shmId, NULL, 0);
        if ((long)processContexts[contextIndex].pageAddresses[pi] == -1) {
            std::cerr << "Cannot attach page: " << strerror(errno) << std::endl;
            return -1;
        }
        processContexts[contextIndex].attachedCount++;
    }

    return contextIndex;
}

// Helper functions for region management
static int acquireRegionSlot(RegionInfo regions[], int* freePtr) {
    int slot = *freePtr;
    if (slot == NULL_INDEX) return NULL_INDEX;

    *freePtr = regions[slot].nextRegion;
    if (*freePtr != NULL_INDEX)
        regions[*freePtr].prevRegion = NULL_INDEX;

    regions[slot].prevRegion = NULL_INDEX;
    regions[slot].nextRegion = NULL_INDEX;
    return slot;
}

static void releaseRegionSlot(RegionInfo regions[], int* freePtr, int index) {
    memset(&regions[index], 0, sizeof(RegionInfo));
    regions[index].prevRegion = NULL_INDEX;
    regions[index].nextRegion = *freePtr;
    *freePtr = index;
}

static int findRegionByName(RegionInfo regions[], int* head, const char* name) {
    int reg = *head;
    while (reg != NULL_INDEX) {
        if (strcmp(regions[reg].regionName, name) == 0)
            break;
        reg = regions[reg].nextRegion;
    }
    return reg;
}

static int findHoleBySize(RegionInfo regions[], int* head, int requiredSize) {
    int reg = *head;
    while (reg != NULL_INDEX) {
        if (regions[reg].blockSize >= requiredSize)
            break;
        reg = regions[reg].nextRegion;
    }
    return reg;
}

static void addRegionToList(RegionInfo regions[], int* listHead, int newReg) {
    if (*listHead == NULL_INDEX) {
        *listHead = newReg;
        regions[newReg].prevRegion = NULL_INDEX;
        regions[newReg].nextRegion = NULL_INDEX;
        return;
    }

    int prevReg = NULL_INDEX;
    int reg = *listHead;

    while (reg != NULL_INDEX) {
        if (strcmp(regions[reg].regionName, regions[newReg].regionName) >= 0) {
            regions[newReg].nextRegion = reg;
            if (regions[reg].prevRegion == NULL_INDEX) {
                regions[newReg].prevRegion = NULL_INDEX;
                *listHead = newReg;
            } else {
                regions[newReg].prevRegion = regions[reg].prevRegion;
                regions[regions[reg].prevRegion].nextRegion = newReg;
            }
            regions[reg].prevRegion = newReg;
            break;
        }
        prevReg = reg;
        reg = regions[reg].nextRegion;
    }

    if (reg == NULL_INDEX) {
        regions[newReg].prevRegion = prevReg;
        regions[newReg].nextRegion = NULL_INDEX;
        regions[prevReg].nextRegion = newReg;
    }
}

static void addHoleToList(RegionInfo regions[], int* listHead, int newReg) {
    if (*listHead == NULL_INDEX) {
        *listHead = newReg;
        regions[newReg].prevRegion = NULL_INDEX;
        regions[newReg].nextRegion = NULL_INDEX;
        return;
    }

    int prevReg = NULL_INDEX;
    int reg = *listHead;

    while (reg != NULL_INDEX) {
        if (regions[reg].blockSize >= regions[newReg].blockSize) {
            regions[newReg].nextRegion = reg;
            if (regions[reg].prevRegion == NULL_INDEX) {
                regions[newReg].prevRegion = NULL_INDEX;
                *listHead = newReg;
            } else {
                regions[newReg].prevRegion = regions[reg].prevRegion;
                regions[regions[reg].prevRegion].nextRegion = newReg;
            }
            regions[reg].prevRegion = newReg;
            break;
        }
        prevReg = reg;
        reg = regions[reg].nextRegion;
    }

    if (reg == NULL_INDEX) {
        regions[newReg].prevRegion = prevReg;
        regions[newReg].nextRegion = NULL_INDEX;
        regions[prevReg].nextRegion = newReg;
    }
}

static void removeFromList(RegionInfo regions[], int* head, int index) {
    if (regions[index].prevRegion == NULL_INDEX) {
        *head = regions[index].nextRegion;
    } else {
        regions[regions[index].prevRegion].nextRegion = regions[index].nextRegion;
    }

    if (regions[index].nextRegion != NULL_INDEX)
        regions[regions[index].nextRegion].prevRegion = regions[index].prevRegion;

    regions[index].prevRegion = NULL_INDEX;
    regions[index].nextRegion = NULL_INDEX;
}

// Info function
int displayContextInfo(FILE* output) {
    int thid = -1;
#if defined(__linux__)
    struct shm_info shm_info;
    int maxId = shmctl(0, SHM_INFO, (struct shmid_ds*)&shm_info);
    if (maxId < 0) {
        std::cerr << "Cannot get shared memory info: " << strerror(errno) << std::endl;
        return -1;
    }

    for (int id = 0; id <= maxId; id++) {
        struct shmid_ds segment;
        int shmId = shmctl(id, SHM_STAT, &segment);
        if (shmId < 0) continue;

        ContextData* cd = (ContextData*)shmat(shmId, NULL, 0);
        if ((long)cd == -1) {
            std::cerr << "Cannot attach context descriptor: " << strerror(errno) << std::endl;
            return -1;
        }

        if (cd->magicNumber == ESM_MAGIC) {
            fprintf(output, "ESM Context %d\n", cd->contextIdentifier);
            fprintf(output, "\tsemaphore=%d\n", cd->semaphoreId);
            fprintf(output, "\tattaches=%d\n", (int)segment.shm_nattch);

            int holeCount = 0;
            for (int h = cd->holeHead; h != NULL_INDEX; h = cd->regions[h].nextRegion) holeCount++;
            fprintf(output, "\tholes=%d", holeCount);
            if (holeCount == 0) fprintf(output, "\n");

            holeCount = 0;
            for (int h = cd->holeHead; h != NULL_INDEX; h = cd->regions[h].nextRegion) {
                if (holeCount % 10 == 0) fprintf(output, "\n\t\t");
                fprintf(output, "%d ", cd->regions[h].blockSize);
                holeCount++;
            }
            fprintf(output, "\n\tregions=%d\n", cd->allocatedRegions);

            for (int r = cd->regionHead; r != NULL_INDEX; r = cd->regions[r].nextRegion) {
                fprintf(output, "\t\tname=\"%s\", size=%d, pagenum=%d, offset=%d\n",
                        cd->regions[r].regionName,
                        cd->regions[r].blockSize,
                        cd->regions[r].pageId,
                        cd->regions[r].offset);
            }
            fprintf(output, "\n");
        }

        if (shmdt((void*)cd) != 0)
            std::cerr << "Cannot detach context descriptor: " << strerror(errno) << std::endl;
    }
    return 0;
#else
    std::cerr << "Context info not implemented on this platform" << std::endl;
    return -1;
#endif
}

