// Helper lambda to register component metadata with common attributes
template<typename T>
void register_base_component(entt::meta_factory<T>& factory, const char* name, const char* category = "LIGHTING") {
    factory
        .type(entt::hash_v<std::remove_cvref_t<T>>())
        .custom(entt::attributes{
            entt::attribute{"name", name},
            entt::attribute{"category", category},
            entt::attribute{"pretty_name", name}
        })
        .func<&component_meta<T>::exists>("component_exists"_hs)
        .func<&component_meta<T>::add>("component_add"_hs)
        .func<&component_meta<T>::save>("component_save"_hs)
        .func<&component_meta<T>::load>("component_load"_hs)
        .func<&component_meta<T>::remove>("component_remove"_hs);
}

