DEFINE_LOG_CATEGORY(LogMicManager);

namespace Audio
{
/**
* Callback Function For the Microphone Capture for RtAudio
*/
static int32 OnAudioCaptureCallback(void *OutBuffer, void* InBuffer, uint32 InBufferFrames, double StreamTime, RtAudioStreamStatus AudioStreamStatus, void* InUserData)
{
	FAudioRecordingManager* Manager = static_cast<FAudioRecordingManager*>(InUserData);
	return Manager->OnAudioCapture(InBuffer, InBufferFrames, StreamTime, AudioStreamStatus == RTAUDIO_INPUT_OVERFLOW);
}

FAudioRecordingManager::FAudioRecordingManager()
	: NumRecordedSamples(0)
	, NumFramesToRecord(0)
	, RecordingBlockSize(0)
	, RecordingSampleRate(44100.0f)
	, NumInputChannels(1)
	, InputGain(1.0f)
	, bRecording(false)
	, bError(false)
	, NumOverflowsDetected(0)
{
}

FAudioRecordingManager::~FAudioRecordingManager()
{
	if (ADC.isStreamOpen())
	{
		ADC.abortStream();
	}
}

FAudioRecordingManager& FAudioRecordingManager::Get()
{
	static FAudioRecordingManager Instance;
	return Instance;
}

void FAudioRecordingManager::StartRecording(const FRecordingSettings& InSettings, TArray<USoundWave*>& OutSoundWaves)
{
	if (bError)
	{
		return;
	}

	StopRecording(OutSoundWaves);
	RecordingBlockSize = 1024;

	if (ADC.isStreamOpen())
	{
		try
		{
			ADC.stopStream();
			ADC.closeStream();
		}
		catch (RtAudioError& e)
		{
			FString ErrorMsg(e.what());
			bError = true;
			UE_LOG(LogMicManager, Error, TEXT("Failed to close mic stream: %s"), *ErrorMsg);
			return;
		}
	}

	UE_LOG(LogMicManager, Log, TEXT("Starting mic recording."));
	Settings = InSettings;
	InputGain = Audio::ConvertToLinear(Settings.GainDb);

	RtAudio::DeviceInfo Info = ADC.getDeviceInfo(StreamParams.deviceId);
	RecordingSampleRate = Info.preferredSampleRate;
	NumInputChannels = Info.inputChannels;

	if (NumInputChannels != 1 && NumInputChannels != 2)
	{
		UE_LOG(LogMicManager, Warning, TEXT("Only mono and stereo mic input are supported."));
		return;
	}

	if (Settings.RecordingDuration > 0.0f)
	{
		int32 ReserveSamples = static_cast<int32>(Settings.RecordingDuration * RecordingSampleRate * NumInputChannels);
		CurrentRecordedPCMData.Reserve(ReserveSamples);
		NumFramesToRecord = static_cast<int32>(RecordingSampleRate * Settings.RecordingDuration);
	}
	else
	{
		int32 ReserveSamples = 60 * static_cast<int32>(RecordingSampleRate) * NumInputChannels;
		CurrentRecordedPCMData.Reserve(ReserveSamples);
		NumFramesToRecord = INDEX_NONE;
	}

	if (NumInputChannels > 2)
	{
		Settings.bSplitChannels = true;
	}

	NumRecordedSamples = 0;
	NumOverflowsDetected = 0;
	bRecording = true;

	StreamParams.deviceId = ADC.getDefaultInputDevice();
	StreamParams.nChannels = NumInputChannels;
	StreamParams.firstChannel = 0;

	uint32 BufferFrames = FMath::Max(RecordingBlockSize, 256);
	UE_LOG(LogMicManager, Log, TEXT("Initialized mic manager: %d Hz, %d ch, block size %d"),
		(int32)RecordingSampleRate, StreamParams.nChannels, BufferFrames);

	try
	{
		ADC.openStream(nullptr, &StreamParams, RTAUDIO_SINT16, RecordingSampleRate, &BufferFrames, &OnAudioCaptureCallback, this);
	}
	catch (const RtAudioError& e)
	{
		bError = true;
		UE_LOG(LogMicManager, Error, TEXT("Failed to open mic device: %s"), e.what());
	}
	catch (const std::exception& e)
	{
		bError = true;
		UE_LOG(LogMicManager, Error, TEXT("Failed to open mic device: %s"), e.what());
	}
	catch (...)
	{
		bError = true;
		UE_LOG(LogMicManager, Error, TEXT("Failed to open mic device: unknown error"));
	}

	ADC.startStream();
}

static void SampleRateConvert(float SourceSR, float TargetSR, int32 Channels, const TArray<int16>& InputData, int32 SampleCount, TArray<int16>& OutputData)
{
	const int32 InputSampleCount = InputData.Num();
	const int32 OutputSampleCount = InputSampleCount * static_cast<int32>(TargetSR) / static_cast<int32>(SourceSR);
	OutputData.Reset(OutputSampleCount);

	const float Ratio = static_cast<float>(SourceSR) / TargetSR;
	float InterpolatedFrameIndex = 0.0f;

	const int32 FrameCount = SampleCount / Channels;
	int32 CurrentFrame = 0;

	for (;;)
	{
		int32 NextFrame = CurrentFrame + 1;
		if (CurrentFrame >= FrameCount || NextFrame >= FrameCount)
		{
			break;
		}

		for (int32 Ch = 0; Ch < Channels; ++Ch)
		{
			int32 Idx1 = CurrentFrame * Channels + Ch;
			int32 Idx2 = Idx1 + Channels;
			int16 Val1 = InputData[Idx1];
			int16 Val2 = InputData[Idx2];
			int16 NewVal = FMath::Lerp(Val1, Val2, InterpolatedFrameIndex);
			OutputData.Add(NewVal);
		}

		InterpolatedFrameIndex += Ratio;
		while (InterpolatedFrameIndex >= 1.0f)
		{
			InterpolatedFrameIndex -= 1.0f;
			++CurrentFrame;
		}
	}
}

void FAudioRecordingManager::StopRecording(TArray<USoundWave*>& OutSoundWaves)
{
	FScopeLock Lock(&CriticalSection);

	if (!bRecording)
	{
		return;
	}

	bRecording = false;
	ADC.stopStream();
	ADC.closeStream();

	if (CurrentRecordedPCMData.IsEmpty())
	{
		return;
	}

	if (NumFramesToRecord != INDEX_NONE)
	{
		NumRecordedSamples = FMath::Min(NumFramesToRecord * NumInputChannels, CurrentRecordedPCMData.Num());
	}
	else
	{
		NumRecordedSamples = CurrentRecordedPCMData.Num();
	}

	const float DurationSeconds = ((float)NumRecordedSamples / RecordingSampleRate) / (float)NumInputChannels;
	UE_LOG(LogMicManager, Log, TEXT("Stopped recording: %d samples (%.4f sec), %d overflows detected."),
		NumRecordedSamples, DurationSeconds, NumOverflowsDetected);

	TArray<int16>* FinalBuffer = nullptr;

	if (FMath::Abs(RecordingSampleRate - WAVE_FILE_SAMPLERATE) > KINDA_SMALL_NUMBER)
	{
		UE_LOG(LogMicManager, Log, TEXT("Converting sample rate from %d to %d Hz."), (int32)RecordingSampleRate, WAVE_FILE_SAMPLERATE);
		SampleRateConvert(RecordingSampleRate, (float)WAVE_FILE_SAMPLERATE, NumInputChannels, CurrentRecordedPCMData, NumRecordedSamples, ConvertedPCMData);
		NumRecordedSamples = ConvertedPCMData.Num();
		FinalBuffer = &ConvertedPCMData;
	}
	else
	{
		FinalBuffer = &CurrentRecordedPCMData;
	}

	if (!FMath::IsNearlyEqual(InputGain, 1.0f))
	{
		UE_LOG(LogMicManager, Log, TEXT("Applying gain factor: %.2f"), InputGain);
		for (int32 i = 0; i < NumRecordedSamples; ++i)
		{
			float Scaled = InputGain * (*FinalBuffer)[i];
			(*FinalBuffer)[i] = (int16)FMath::Clamp(Scaled, -32767.0f, 32767.0f);
		}
	}

	uint8* RawPtr = nullptr;
	int32 RawSize = 0;
	int32 SerializedChannels = 0;
	int32 WaveCount = 0;

	if (Settings.bSplitChannels)
	{
		WaveCount = NumInputChannels;
		SerializedChannels = 1;
		const int32 Frames = NumRecordedSamples / NumInputChannels;
		RawSize = Frames * sizeof(int16);

		DeinterleavedAudio.Empty(NumInputChannels);
		int16* InterleavedPtr = FinalBuffer->GetData();

		for (int32 Ch = 0; Ch < NumInputChannels; ++Ch)
		{
			DeinterleavedAudio.Emplace();
			FDeinterleavedAudio& ChannelData = DeinterleavedAudio.Last();
			ChannelData.PCMData.SetNum(Frames);
			int16* DeinterleavedPtr = ChannelData.PCMData.GetData();

			for (int32 Frame = 0; Frame < Frames; ++Frame)
			{
				DeinterleavedPtr[Frame] = InterleavedPtr[Ch + Frame * NumInputChannels];
			}
		}
	}
	else
	{
		WaveCount = 1;
		RawPtr = reinterpret_cast<uint8*>(FinalBuffer->GetData());
		RawSize = NumRecordedSamples * sizeof(int16);
		SerializedChannels = NumInputChannels;
	}

	for (int32 i = 0; i < WaveCount; ++i)
	{
		USoundWave* SoundWave = nullptr;
		USoundWave* ExistingWave = nullptr;
		TArray<UAudioComponent*> ComponentsToRestart;

		bool bCreatedPackage = false;

		if (Settings.Directory.Path.IsEmpty() || Settings.AssetName.IsEmpty())
		{
			SoundWave = NewObject<USoundWave>(GetTransientPackage(), *Settings.AssetName);
		}
		else
		{
			FString AssetName = Settings.AssetName;
			FString PackagePath = Settings.Directory.Path / AssetName;

			if (WaveCount > 1)
			{
				AssetName = FString::Printf(TEXT("%s_Channel_%d"), *AssetName, i);
				PackagePath = Settings.Directory.Path / AssetName;
				RawPtr = reinterpret_cast<uint8*>(DeinterleavedAudio[i].PCMData.GetData());
			}

			UPackage* Package = CreatePackage(*PackagePath);
			ExistingWave = FindObject<USoundWave>(Package, *AssetName);

			FAudioDeviceManager* DeviceManager = GEngine ? GEngine->GetAudioDeviceManager() : nullptr;
			if (DeviceManager && ExistingWave)
			{
				DeviceManager->StopSoundsUsingResource(ExistingWave, &ComponentsToRestart);
			}

			if (ExistingWave)
			{
				SoundWave = ExistingWave;
				SoundWave->FreeResources();
			}
			else
			{
				SoundWave = NewObject<USoundWave>(Package, *AssetName, RF_Public | RF_Standalone);
			}

			SerializeWaveFile(RawWaveData, RawPtr, RawSize, SerializedChannels, WAVE_FILE_SAMPLERATE);

			SoundWave->RawData.Lock(LOCK_READ_WRITE);
			void* LockedPtr = SoundWave->RawData.Realloc(RawWaveData.Num());
			FMemory::Memcpy(LockedPtr, RawWaveData.GetData(), RawWaveData.Num());
			SoundWave->RawData.Unlock();

			bCreatedPackage = true;
		}

		if (SoundWave)
		{
			SoundWave->RawPCMDataSize = RawSize;
			SoundWave->RawPCMData = (uint8*)FMemory::Malloc(SoundWave->RawPCMDataSize);
			FMemory::Memcpy(SoundWave->RawPCMData, RawPtr, RawSize);

			SoundWave->Duration = (float)(NumRecordedSamples / NumInputChannels) / WAVE_FILE_SAMPLERATE;
			SoundWave->SetSampleRate(WAVE_FILE_SAMPLERATE);
			SoundWave->NumChannels = SerializedChannels;

			if (bCreatedPackage)
			{
				FAssetRegistryModule::AssetCreated(SoundWave);
				SoundWave->MarkPackageDirty();

				for (UAudioComponent* Component : ComponentsToRestart)
				{
					Component->Play();
				}
			}

			OutSoundWaves.Add(SoundWave);
		}
	}
}

int32 FAudioRecordingManager::OnAudioCapture(void* InBuffer, uint32 InBufferFrames, double StreamTime, bool bOverflow)
{
	FScopeLock Lock(&CriticalSection);

	if (bRecording)
	{
		if (bOverflow)
		{
			++NumOverflowsDetected;
		}

		const int32 SamplesToAdd = InBufferFrames * NumInputChannels;
		int16* Buffer = static_cast<int16*>(InBuffer);
		CurrentRecordedPCMData.Append(Buffer, SamplesToAdd);
		return 0;
	}

	return 1;
}

