#include "utl/BinStream.h"
#include "utl/ChunkIDs.h"
#include "utl/Chunks.h"

namespace {

    struct CuePoint {
        CuePoint(int frame, int id) : mFrame(frame), mID(id) {}
        // total size: 0x8
        int mFrame; // offset 0x0, size 0x4
        int mID;    // offset 0x4, size 0x4
    };

    struct Label {
        Label(const String &s, int i) : mName(s), mID(i) {}
        // total size: 0x10
        class String mName; // offset 0x0, size 0xC
        int mID;            // offset 0xC, size 0x4
    };

    bool CompareCuePoints(const CuePoint &p1, const CuePoint &p2) {
        return p1.mFrame < p2.mFrame;
    }

    // Helper to find label by ID (replaces inner loop)
    const String* FindLabelByID(const std::vector<Label>& labels, int id) {
        auto it = std::find_if(labels.begin(), labels.end(),
            [id](const Label& lbl) { return lbl.mID == id; });
        return (it != labels.end()) ? &it->mName : nullptr;
    }
}

WaveFile::WaveFile(BinStream &bs) : mMarkers(), mRiffList(bs, true) {
    ReadFormat();
    ReadMarkers();
    ReadNumSamples();
}

WaveFile::~WaveFile() {}

void WaveFile::ReadFormat() {
    mRiffList.Reset();
    ChunkHeader *fmtChunk = mRiffList.Next(kWaveFormatChunkID);
    MILO_ASSERT(nullptr != fmtChunk, 0x6e);

    IDataChunk formatChunk(mRiffList);
    formatChunk >> mFormat;
    formatChunk >> mNumChannels;
    formatChunk >> mSamplesPerSec;
    formatChunk >> mAvgBytesPerSec;
    formatChunk >> mBlockAlign;
    formatChunk >> mBitsPerSample;

    MILO_ASSERT(mAvgBytesPerSec == mSamplesPerSec * mBlockAlign, 0x78);
    MILO_ASSERT(mBlockAlign == mNumChannels * mBitsPerSample / 8, 0x79);
}

void WaveFile::ReadMarkers() {
    std::vector<CuePoint> cuePoints;
    std::vector<Label> labels;

    mRiffList.Reset();

    if (!mRiffList.Next(kWaveCueChunkID))
        return;

    int numCuePoints;
    {
        IDataChunk cueDataChunk(mRiffList);
        cueDataChunk >> numCuePoints;

        int idx = 0;
        while (idx < numCuePoints) {
            int id, frame;
            cueDataChunk >> id >> frame;
            cuePoints.emplace_back(frame, id);
            cueDataChunk.Seek(0x10, BinStream::kSeekCur);
            ++idx;
        }
    }

    if (0 == numCuePoints)
        return;

    mRiffList.Reset();
    if (mRiffList.Next(kWaveAdditionalChunkID)) {
        IListChunk listChunk(mRiffList);
        int count = 0;
        while (count < numCuePoints) {
            listChunk.Next(kWaveLabelChunkID);
            IDataChunk labelData(listChunk);
            int len = labelData.Header()->Length() - 4;
            int labelId;
            labelData >> labelId;

            String name;
            name.resize(len);
            labelData.Read(name.data(), len);
            labels.emplace_back(name, labelId);
            ++count;
        }
    }

    std::sort(cuePoints.begin(), cuePoints.end(), CompareCuePoints);

    for (int k = 0; k < numCuePoints; ++k) {
        const String* pName = FindLabelByID(labels, cuePoints[k].mID);
        String finalName = pName ? *pName : String{};
        mMarkers.emplace_back(cuePoints[k].mFrame, cuePoints[k].mID, finalName);
    }
}

void WaveFile::ReadNumSamples() {
    mRiffList.Reset();
    ChunkHeader *dataChunkHeader = mRiffList.Next(kWaveDataChunkID);
    MILO_ASSERT(nullptr != dataChunkHeader, 0xEA);

    mNumSamples = dataChunkHeader->Length() / mBlockAlign;
}

IListChunk &WaveFile::PrepareToProvideData() {
    mRiffList.Reset();
    ChunkHeader *dataChunkHeader = mRiffList.Next(kWaveDataChunkID);
    MILO_ASSERT(nullptr != dataChunkHeader, 0x17e);
    return mRiffList;
}

WaveFileData::WaveFileData(WaveFile &wf)
    : IDataChunk(wf.PrepareToProvideData()), mWaveFile(wf) {}

WaveFileData::~WaveFileData() {}

