}

TEST(DeadCFGEliminationTest, AssignmentsAfterReturn) {
    builder::StructuredSDFGBuilder sbuilder("test_graph", FunctionType_CPU);
    types::Scalar i32(types::PrimitiveType::Int32);
    sbuilder.add_container("var_x", i32, true);

    auto& entry = sbuilder.subject().root();
    auto& ret_node = sbuilder.add_return(entry, "var_x", {{sdfg::symbolic::symbol("var_x"), sdfg::symbolic::integer(10)}});

    ASSERT_EQ(entry.size(), 1u);
    ASSERT_EQ(entry.at(0).second.size(), 1u);

    analysis::AnalysisManager amgr(sbuilder.subject());
    passes::DeadCFGElimination dce;
    EXPECT_TRUE(dce.run(sbuilder, amgr));

    ASSERT_EQ(entry.size(), 1u);
    EXPECT_EQ(entry.at(0).second.size(), 0u);
}

