namespace lbug {
namespace regex {

// Helper function to escape a string using C-style escape sequences
static size_t EscapeCString(const char* input, size_t input_size, char* output, size_t output_capacity) {
    const char* end = input + input_size;
    size_t written = 0;

    while (input < end) {
        // Ensure space for at least two characters (e.g., "\n")
        if (output_capacity - written < 2) {
            return static_cast<size_t>(-1);
        }

        unsigned char ch = static_cast<unsigned char>(*input++);
        switch (ch) {
            case '\n':
                output[written++] = '\\';
                output[written++] = 'n';
                break;
            case '\r':
                output[written++] = '\\';
                output[written++] = 'r';
                break;
            case '\t':
                output[written++] = '\\';
                output[written++] = 't';
                break;
            case '\"':
                output[written++] = '\\';
                output[written++] = '\"';
                break;
            case '\'':
                output[written++] = '\\';
                output[written++] = '\'';
                break;
            case '\\':
                output[written++] = '\\';
                output[written++] = '\\';
                break;
            default:
                // Handle non-printable or special characters
                if (ch < ' ' || ch > '~') {
                    // Need space for 4 chars: \XXX + null terminator
                    if (output_capacity - written < 5) {
                        return static_cast<size_t>(-1);
                    }
                    int len = snprintf(output + written, 5, "\\%03o", ch);
                    written += len; // should be 4
                } else {
                    output[written++] = ch;
                }
                break;
        }
    }

    // Ensure space for null terminator
    if (output_capacity - written < 1) {
        return static_cast<size_t>(-1);
    }
    output[written] = '\0';
    return written;
}

std::string CEscape(const StringPiece& piece) {
    // Allocate maximum possible space: each char could become up to 4 chars
    size_t max_needed = piece.size() * 4 + 1;
    char* buffer = new char[max_needed];
    size_t actual_len = EscapeCString(piece.data(), piece.size(), buffer, max_needed);
    std::string result(buffer, actual_len);
    delete[] buffer;
    return result;
}

void PrefixSuccessor(std::string* prefix) {
    // Increment the last character unless it's 0xFF, in which case we pop and recurse
    while (!prefix->empty()) {
        char& last = prefix->back();
        if (last == static_cast<char>(0xFF)) {
            prefix->pop_back();
        } else {
            ++last;
            break;
        }
    }
}

// Internal helper to format and append a variable argument list to a string
static void AppendFormattedString(std::string* target, const char* fmt, va_list args) {
    // Initial small buffer attempt
    char local_buffer[1024];
    va_list args_copy;
    va_copy(args_copy, args);

    int status = vsnprintf(local_buffer, sizeof(local_buffer), fmt, args_copy);
    va_end(args_copy);

    if (status >= 0 && static_cast<size_t>(status) < sizeof(local_buffer)) {
        target->append(local_buffer, status);
        return;
    }

    // Dynamic buffer resizing loop
    int capacity = sizeof(local_buffer);
    while (true) {
        if (status < 0) {
            capacity *= 2;
        } else {
            capacity = status + 1;
        }

        char* dynamic_buffer = new char[capacity];
        va_copy(args_copy, args);
        status = vsnprintf(dynamic_buffer, capacity, fmt, args_copy);
        va_end(args_copy);

        if (status >= 0 && status < capacity) {
            target->append(dynamic_buffer, status);
            delete[] dynamic_buffer;
            return;
        }
        delete[] dynamic_buffer;
    }
}

std::string StringPrintf(const char* format, ...) {
    va_list ap;
    va_start(ap, format);
    std::string out;
    AppendFormattedString(&out, format, ap);
    va_end(ap);
    return out;
}

void SStringPrintf(std::string* out, const char* format, ...) {
    va_list ap;
    va_start(ap, format);
    out->clear();
    AppendFormattedString(out, format, ap);
    va_end(ap);
}

void StringAppendF(std::string* out, const char* format, ...) {
    va_list ap;
    va_start(ap, format);
    AppendFormattedString(out, format, ap);
    va_end(ap);
}

} // namespace regex
