// Version detection helper to abstract hardware_interface version checks
namespace hw_version {
  constexpr bool is_at_least(int major, int minor, int patch) {
#if defined(HARDWARE_INTERFACE_VERSION_MAJOR) && \
    defined(HARDWARE_INTERFACE_VERSION_MINOR) && \
    defined(HARDWARE_INTERFACE_VERSION_PATCH)
    return (HARDWARE_INTERFACE_VERSION_MAJOR > major) ||
           (HARDWARE_INTERFACE_VERSION_MAJOR == major &&
            HARDWARE_INTERFACE_VERSION_MINOR > minor) ||
           (HARDWARE_INTERFACE_VERSION_MAJOR == major &&
            HARDWARE_INTERFACE_VERSION_MINOR == minor &&
            HARDWARE_INTERFACE_VERSION_PATCH >= patch);
#else
    // Fallback: assume newer if macros not defined (safe for modern builds)
    return true;
#endif
  }
}

