TEST(TestTopicBasedSystem, load_topic_based_system_2dof)
{
  const std::string system_description =
      R"(
  <ros2_control name="TopicBasedSystem2dof" type="system">
    <hardware>
      <plugin>topic_based_ros2_control/TopicBasedSystem</plugin>
      <param name="joint_commands_topic">/topic_based_joint_commands</param>
      <param name="joint_states_topic">/topic_based_custom_joint_states</param>
    </hardware>
    <joint name="axis1">
      <command_interface name="position"/>
      <command_interface name="velocity"/>
      <state_interface name="position"/>
      <state_interface name="velocity"/>
    </joint>
    <joint name="axis2">
      <command_interface name="position"/>
      <command_interface name="velocity"/>
      <state_interface name="position"/>
      <state_interface name="velocity"/>
    </joint>
  </ros2_control>
)";

  const std::string full_urdf = ros2_control_test_assets::urdf_head + system_description +
                                ros2_control_test_assets::urdf_tail;

  auto control_node = std::make_shared<rclcpp::Node>("test_topic_based_system_instance");

