// Main function with refactored structure
int main() {
    // Initialize Vita system
    PSVitaInit::run();
    ShutdownManager::Initialise();

    // Memory info simulation
    int freeMemoryKB = LoadSysModules();
    std::cout << "Free memory: " << freeMemoryKB << " KB" << std::endl;

    // Initialize Vita libraries
    PSVitaNPToolkit::init();

    // Storage setup
    StorageManager.Init(0, L"savegame.dat", "savePackName", 51*1000*1000, nullptr, nullptr, nullptr);
    StorageManager.ResetSaveData();
    StorageManager.SetSaveTitle(L"Default Save");
    StorageManager.SetMaxSaves(99);

    // Profile initialization
    ProfileManager.RichPresenceInit(4, 1);
    SetupAchievements();

    // UI initialization
    RenderManager.Initialise(nullptr, nullptr);
    app.loadMediaArchive();

    if (!app.ReadProductCodes()) {
        app.FatalLoadError();
    }

    app.InitTime();
    app.loadStringTable();

    // Input configuration
    ConfigureInputMappings();

    // Game initialization
    Minecraft::main();
    auto pMinecraft = Minecraft::GetInstance();

    // Gamma correction
    RenderManager.UpdateGamma(16384);

    // Trial version handling
    bool trialTimerVisible = true;
    if (!ProfileManager.IsFullVersion()) {
        app.ShowTrialTimer(true);
        trialTimerVisible = true;
    } else {
        app.ShowTrialTimer(false);
        trialTimerVisible = false;
    }

    // Main game loop
    while (ShutdownManager::ShouldRun(ShutdownManager::eMainThread)) {
        SonyVoiceChat_Vita::tick();
        RenderManager.StartFrame();

        app.UpdateTime();
        InputManager.SetGameJoypadMaps(0, 0, 0); // Dummy input tick
        ProfileManager.Tick();
        StorageManager.Tick();
        RenderManager.Tick();
        g_NetworkManager.DoWork();
        LeaderboardManager::Instance()->Tick();

        if (app.GetGameStarted()) {
            // In-game logic
        } else {
            // Menu logic
            Vec3::resetPool();
        }

        RenderManager.Present();

        // Trial timer update
        if (!ProfileManager.IsFullVersion() && app.GetGameStarted()) {
            if (app.IsAppPaused()) {
                app.UpdateTrialPausedTimer();
            }
        } else if (trialTimerVisible) {
            app.ShowTrialTimer(false);
            trialTimerVisible = false;
        }

        app.CommerceTick();
        app.AppEventTick();
        app.SaveDataTick();
        app.HandleXuiActions();
    }

    ShutdownManager::MainThreadHandleShutdown();
    return 0;
}

