namespace Gorgon::Utils {

    void CrashHandler::Backtrace() {
        const int total_slots = depth + skip + 2;
        void** addresses = static_cast<void**>(malloc(total_slots * sizeof(void*)));
        int actual_count = backtrace(addresses, total_slots);

        char** symbol_strings = backtrace_symbols(addresses, actual_count);
        StdConsole console;

        auto process_frame = [&](int idx) {
            std::string raw_line = symbol_strings[idx];
            size_t paren_open = raw_line.find('(');
            size_t plus_or_close = raw_line.find_first_of("+)", paren_open);

            if (paren_open == std::string::npos || plus_or_close == std::string::npos)
                return;

            std::string mangled_name = raw_line.substr(paren_open + 1, plus_or_close - paren_open - 1);
            std::string demangled_name = demangle(mangled_name);

            int pipe_fds[2];
            if (pipe(pipe_fds) != 0)
                return;

            pid_t child_pid = fork();
            if (child_pid > 0) {
                // Parent process
                wait(nullptr);

                close(pipe_fds[1]);
                char buffer[1024];
                ssize_t bytes_read = read(pipe_fds[0], buffer, sizeof(buffer) - 1);
                close(pipe_fds[0]);

                if (bytes_read <= 0)
                    return;

                buffer[bytes_read] = '\0';
                std::string output(buffer);

                size_t colon_pos = output.find(':');
                size_t space_after_colon = output.find(' ', colon_pos);
                if (space_after_colon == std::string::npos)
                    space_after_colon = output.length();

                std::string file_part = output.substr(0, colon_pos);
                std::string line_part = output.substr(colon_pos + 1, space_after_colon - colon_pos - 1);

                std::string canonical_path;
                try {
                    canonical_path = Filesystem::Canonical(file_part);
                } catch (...) {
                    canonical_path = file_part;
                }

                int line_number = String::To<int>(line_part);
                // Skip invalid entries silently (as original did with continue)

                std::string dir_name = Filesystem::GetDirectory(canonical_path);
                if (!dir_name.empty() && dir_name.back() == '/')
                    dir_name.pop_back();
                dir_name = Filesystem::GetFilename(dir_name);
                std::string base_file = Filesystem::GetFilename(canonical_path);

                console.SetColor(Console::Magenta);
                if ((idx - skip - 1) == 1) {
                    console.SetBold(true);
                }
                std::cout << "  [" << (idx - skip - 1) << "] ";
                console.SetBold(false);
                console.SetColor(Console::Default);

                if (!demangled_name.empty()) {
                    std::cout << "In function ";
                    console.SetColor(Console::Yellow);
                    std::cout << demangled_name << " ";
                } else if (!mangled_name.empty()) {
                    std::cout << "In function ";
                    console.SetColor(Console::Yellow);
                    std::cout << mangled_name << " ";
                }
                console.SetColor(Console::Default);
                std::cout << "at ";
                if ((idx - skip - 1) == 1) {
                    console.SetColor(Console::Red);
                }
                std::cout << "..." << dir_name << "/" << base_file;
                console.SetBold();
                std::cout << ":" << line_number << std::endl;
                console.Reset();
            } 
            else if (child_pid == 0) {
                // Child process
                close(pipe_fds[0]);
                dup2(pipe_fds[1], STDOUT_FILENO);
                dup2(pipe_fds[1], STDERR_FILENO);
                close(pipe_fds[1]);

                char addr_buf[32];
                snprintf(addr_buf, sizeof(addr_buf), "%p", addresses[idx]);

                execlp("addr2line", "addr2line", addr_buf, "-e", Filesystem::ExePath().c_str(), nullptr);

                perror("Addr2line is not installed.");
                _exit(EXIT_FAILURE);
            }
            // else fork failed — do nothing (original also ignored this case)
        };

#ifdef TEST
        for (int frame_idx = 2; frame_idx < skip + 2; ++frame_idx) {
            process_frame(frame_idx);
        }
#endif

        for (int frame_idx = skip + 2; frame_idx < actual_count; ++frame_idx) {
            process_frame(frame_idx);
        }

        free(addresses);
        free(symbol_strings);
    }

}

