MenuBackup::MenuBackup(shared_ptr<Inventory> inventory, AbstractContainerMenu *menu)
{
    backups = new unordered_map<short, ItemInstanceArray *>();
    this->inventory = inventory;
    this->menu = menu;
}

void MenuBackup::save(short changeUid)
{
    // Create a backup array sized to hold carried item + all slot items
    int totalSlots = static_cast<int>(menu->slots->size());
    ItemInstanceArray *backup = new ItemInstanceArray(totalSlots + 1);

    // Store the currently carried item at index 0
    (*backup)[0] = ItemInstance::clone(inventory->getCarried());

    // Copy each slot's item into the backup starting from index 1
    for (int i = 0; i < totalSlots; ++i) {
        (*backup)[i + 1] = ItemInstance::clone(menu->slots->at(i)->getItem());
    }

    // Store the backup under the provided UID
    (*backups)[changeUid] = backup;
}

// Cannot use delete as function name as it is a reserved keyword
void MenuBackup::deleteBackup(short changeUid)
{
    // Remove the backup entry associated with the given UID
    auto it = backups->find(changeUid);
    if (it != backups->end()) {
        delete it->second;  // Free the allocated ItemInstanceArray
        backups->erase(it);
    }
}

void MenuBackup::rollback(short changeUid)
{
    // Retrieve the backup data for the specified UID
    ItemInstanceArray *backup = backups->at(changeUid);

    // Restore carried item and all slot contents from the backup
    inventory->setCarried((*backup)[0]);
    for (unsigned int i = 0; i < menu->slots->size(); ++i) {
        menu->slots->at(i)->set((*backup)[i + 1]);
    }

    // Clear all backups after rollback (as original code did)
    backups->clear();
}

#include "TreeCollection.h"
#include "MPIHelper.h"
using namespace std;

TreeCollection::TreeCollection(vector<string>& treeData, vector<double>& scoreData, vector<int> &originRank) {
    ASSERT(treeData.size() == scoreData.size());
    this->treeStrings = treeData;
    this->scores = scoreData;
    this->sourceProcID = originRank;
}

pair<string, double> TreeCollection::getTree(int index) {
    ASSERT(treeStrings.size() == scores.size());
    return make_pair(treeStrings[index], scores[index]);
}

void TreeCollection::reset() {
    treeStrings.clear();
    scores.clear();
    sourceProcID.clear();
}

void TreeCollection::appendTrees(TreeCollection &otherTrees) {
    treeStrings.insert(treeStrings.end(), otherTrees.treeStrings.begin(), otherTrees.treeStrings.end());
    scores.insert(scores.end(), otherTrees.scores.begin(), otherTrees.scores.end());
    sourceProcID.insert(sourceProcID.end(), otherTrees.sourceProcID.begin(), otherTrees.sourceProcID.end());
}

void TreeCollection::appendTrees(CandidateSet &candidateTrees) {
    CandidateSet::iterator iter;
    // Iterate in reverse order by advancing from end to begin manually
    for (iter = candidateTrees.end(); iter != candidateTrees.begin(); ) {
        --iter;
        treeStrings.push_back(iter->second.tree);
        scores.push_back(iter->first);
        sourceProcID.push_back(MPIHelper::getInstance().getProcessID());
    }
}

size_t TreeCollection::countTrees() const {
    size_t count = treeStrings.size();
    ASSERT(count == scores.size());
    return count;
}

