// Helper function for zero comparison
inline bool IsNearZero(double value, double threshold) {
    return (std::fabs(value) <= threshold);
}

// Vector class - renamed from VectorRn
class VectorRn {
public:
    double* x;
    long length;
    static VectorRn WorkVector;

    VectorRn() : x(nullptr), length(0) {}
    VectorRn(long size) : length(size) {
        x = new double[size];
    }

    ~VectorRn() { if (x) delete[] x; }

    void SetSize(long newSize) {
        if (x) delete[] x;
        length = newSize;
        x = new double[newSize];
    }

    void SetZero() {
        for (long i = 0; i < length; ++i) x[i] = 0.0;
    }

    void Fill(double val) {
        for (long i = 0; i < length; ++i) x[i] = val;
    }

    void Set(long idx, double val) { x[idx] = val; }
    double Get(long idx) const { return x[idx]; }
    double* GetPtr() { return x; }
    const double* GetPtr(long idx) const { return x + idx; }

    double MaxAbs() const {
        double result = 0.0;
        for (long i = 0; i < length; ++i) {
            double absVal = std::fabs(x[i]);
            if (absVal > result) result = absVal;
        }
        return result;
    }

    double NormSq() const {
        double sum = 0.0;
        for (long i = 0; i < length; ++i) sum += x[i] * x[i];
        return sum;
    }

    void LoadScaled(const double* src, double scale) {
        for (long i = 0; i < length; ++i) x[i] = src[i] * scale;
    }

    void AddScaled(const VectorRn& other, double factor) {
        for (long i = 0; i < length; ++i) x[i] += other.x[i] * factor;
    }

    void SetCouple(long idx, const TPointD& pt) {
        x[2*idx] = pt.x;
        x[2*idx+1] = pt.y;
    }

    double DotProductColumn(const VectorRn& v, long colNum) const {
        double ret = 0.0;
        for (long i = 0; i < length; ++i) {
            ret += x[i] * v.x[i];
        }
        return ret;
    }

    // Operator overloads
    double& operator[](long idx) { return x[idx]; }
    const double& operator[](long idx) const { return x[idx]; }

    void operator*=(double scalar) {
        for (long i = 0; i < length; ++i) x[i] *= scalar;
    }
};

// Matrix class - renamed from MatrixRmn
class MatrixRmn {
public:
    double* x;
    long NumRows, NumCols;
    static MatrixRmn WorkMatrix;

    MatrixRmn() : x(nullptr), NumRows(0), NumCols(0) {}
    MatrixRmn(long rows, long cols) : NumRows(rows), NumCols(cols) {
        x = new double[rows * cols];
    }

    ~MatrixRmn() { if (x) delete[] x; }

    void SetSize(long rows, long cols) {
        if (x) delete[] x;
        NumRows = rows;
        NumCols = cols;
        x = new double[rows * cols];
    }

    void SetZero() {
        for (long i = 0; i < NumRows * NumCols; ++i) x[i] = 0.0;
    }

    void SetIdentity() {
        SetZero();
        long minDim = std::min(NumRows, NumCols);
        for (long i = 0; i < minDim; ++i) {
            x[i * (NumRows + 1)] = 1.0;
        }
    }

    void SetDiagonalEntries(double d) {
        long diagLen = std::min(NumRows, NumCols);
        for (long i = 0; i < diagLen; ++i) {
            x[i * (NumRows + 1)] = d;
        }
    }

    void SetDiagonalEntries(const VectorRn& d) {
        long diagLen = std::min(NumRows, NumCols);
        for (long i = 0; i < diagLen; ++i) {
            x[i * (NumRows + 1)] = d[i];
        }
    }

    void SetSuperDiagonalEntries(double d) {
        long sDiagLen = std::min(NumRows, (long)(NumCols - 1));
        for (long i = 0; i < sDiagLen; ++i) {
            x[i * (NumRows + 1) + NumRows] = d;
        }
    }

    void SetSubDiagonalEntries(double d) {
        long sDiagLen = std::min(NumRows, NumCols) - 1;
        for (long i = 0; i < sDiagLen; ++i) {
            x[i * (NumRows + 1) + 1] = d;
        }
    }

    void Set(long row, long col, double val) {
        x[row + NumRows * col] = val;
    }

    double Get(long row, long col) const {
        return x[row + NumRows * col];
    }

    double* GetColumnPtr(long col) { return x + col * NumRows; }

    void MultiplyTranspose(const VectorRn& v, VectorRn& result) const {
        for (long j = 0; j < NumCols; ++j) {
            result[j] = 0.0;
            for (long i = 0; i < NumRows; ++i) {
                result[j] += x[i + NumRows * j] * v[i];
            }
        }
    }

    void Multiply(const VectorRn& v, VectorRn& result) const {
        for (long i = 0; i < NumRows; ++i) {
            result[i] = 0.0;
            for (long j = 0; j < NumCols; ++j) {
                result[i] += x[i + NumRows * j] * v[j];
            }
        }
    }

    double FrobeniusNorm() const {
        double sum = 0.0;
        for (long i = 0; i < NumRows * NumCols; ++i) {
            sum += x[i] * x[i];
        }
        return std::sqrt(sum);
    }

    void AddToDiagonal(double d) {
        long diagLen = std::min(NumRows, NumCols);
        for (long i = 0; i < diagLen; ++i) {
            x[i * (NumRows + 1)] += d;
        }
    }

    void Solve(const VectorRn& b, VectorRn* xVec) const {
        // Simplified solver - in real implementation would use proper LU decomposition
        // This is a placeholder for the actual implementation
        for (long i = 0; i < xVec->length; ++i) {
            (*xVec)[i] = b[i];
        }
    }

    void ComputeSVD(MatrixRmn& U, VectorRn& w, MatrixRmn& V) const {
        // Placeholder for SVD computation
        // In real implementation would perform singular value decomposition
        U.SetIdentity();
        V.SetIdentity();
        for (long i = 0; i < std::min(NumRows, NumCols); ++i) {
            w[i] = 1.0;
        }
    }

    bool DebugCheckSVD(const MatrixRmn& U, const VectorRn& w, const MatrixRmn& V) const {
        return true; // Placeholder
    }

    static void TransposeMultiply(const MatrixRmn& A, const MatrixRmn& B, MatrixRmn& dst) {
        for (long i = 0; i < dst.NumRows; ++i) {
            for (long j = 0; j < dst.NumCols; ++j) {
                dst.Set(i, j, 0.0);
                for (long k = 0; k < A.NumCols; ++k) {
                    dst.Set(i, j, dst.Get(i, j) + A.Get(k, i) * B.Get(k, j));
                }
            }
        }
    }

    static void Multiply(const MatrixRmn& A, const MatrixRmn& B, MatrixRmn& dst) {
        for (long i = 0; i < dst.NumRows; ++i) {
            for (long j = 0; j < dst.NumCols; ++j) {
                dst.Set(i, j, 0.0);
                for (long k = 0; k < A.NumCols; ++k) {
                    dst.Set(i, j, dst.Get(i, j) + A.Get(i, k) * B.Get(k, j));
                }
            }
        }
    }

    void operator-=(const MatrixRmn& other) {
        for (long i = 0; i < NumRows * NumCols; ++i) {
            x[i] -= other.x[i];
        }
    }

    void SetColumn(long col, const VectorRn& vec) {
        for (long i = 0; i < NumRows; ++i) {
            x[i + NumRows * col] = vec[i];
        }
    }
};

