// Main Jacobian class
class Jacobian {
public:
    IKSkeleton* skeleton;
    int nEffector, nJoint;
    int nRow, nCol;
    std::vector<TPointD> target;

    MatrixRmn Jend, Jtarget;
    MatrixRmn U, V;
    VectorRn w, dS, dTheta, dPreTheta, dT, dSclamp, DampingLambdaSqV, diagMatIdentity;
    MatrixRmn Jnorms;

    double DampingLambda, DampingLambdaSq;

    static const double DefaultDampingLambda;
    static const double PseudoInverseThresholdFactor;
    static const double MaxAngleJtranspose;
    static const double MaxAnglePseudoinverse;
    static const double MaxAngleDLS;
    static const double MaxAngleSDLS;
    static const double BaseMaxTargetDist;

    Jacobian(IKSkeleton* s, std::vector<TPointD>& t) {
        skeleton = s;
        nEffector = s->getNumEffector();
        nJoint = s->getNodeCount() - nEffector;
        nRow = 2 * nEffector;
        nCol = nJoint;
        target = t;

        Jend.SetSize(nRow, nCol);
        Jend.SetZero();
        Jtarget.SetSize(nRow, nCol);
        Jtarget.SetZero();
        U.SetSize(nRow, nRow);
        w.SetLength(std::min(nRow, nCol));
        V.SetSize(nCol, nCol);
        dS.SetSize(nRow);
        dTheta.SetSize(nCol);
        dPreTheta.SetSize(nCol);
        dT.SetSize(nRow);
        dSclamp.SetSize(nEffector);
        Jnorms.SetSize(nEffector, nCol);
        DampingLambdaSqV.SetLength(nRow);
        diagMatIdentity.SetLength(nCol);
        Reset();
    }

    void Reset() {
        DampingLambda = DefaultDampingLambda;
        DampingLambdaSq = DampingLambda * DampingLambda;
        for (int i = 0; i < DampingLambdaSqV.length; ++i)
            DampingLambdaSqV[i] = DampingLambdaSq;
        for (int i = 0; i < diagMatIdentity.length; ++i)
            diagMatIdentity[i] = 1.0;
        dSclamp.Fill(HUGE_VAL);
    }

    void computeJacobian() {
        int numNode = skeleton->getNodeCount();
        for (int index = 0; index < numNode; ++index) {
            IKNode* n = skeleton->getNode(index);
            if (n->IsEffector()) {
                int i = n->getEffectorNum();
                const TPointD& targetPos = target[i];

                TPointD diff = targetPos;
                diff = diff - n->GetS();

                if (i < skeleton->getNumEffector() - 1) {
                    diff.x *= 100.0;
                    diff.y *= 100.0;
                }
                dS.SetCouple(i, diff);

                IKNode* m = skeleton->getParent(n);
                while (m) {
                    int j = m->getJointNum();
                    if (!m->isFrozen()) {
                        TPointD jointPos = m->GetS();
                        TPointD effectorPos = n->GetS();
                        TPointD temp = jointPos - effectorPos;

                        double tx = temp.x;
                        temp.x = temp.y;
                        temp.y = -tx;

                        if (i < skeleton->getNumEffector() - 1) {
                            temp.x *= 100.0;
                            temp.y *= 100.0;
                        }
                        Jend.Set(i, j, temp);
                    }
                    m = skeleton->getParent(m);
                }
            }
        }
    }

    void UpdateThetas() {
        for (int index = 0; index < skeleton->getNodeCount(); ++index) {
            IKNode* n = skeleton->getNode(index);
            if (n->IsJoint()) {
                int i = n->getJointNum();
                n->AddToTheta(dTheta[i]);
            }
        }
        skeleton->compute();
    }

    bool checkJointsLimit() {
        return false;
    }

    void ZeroDeltaThetas() {
        dTheta.SetZero();
    }

    void CalcDeltaThetasTranspose() {
        Jend.MultiplyTranspose(dS, dTheta);
        Jend.Multiply(dTheta, dT);

        double dotST = 0.0, normT = 0.0;
        for (int i = 0; i < dS.length; ++i) {
            dotST += dS[i] * dT[i];
            normT += dT[i] * dT[i];
        }

        double alpha = dotST / normT;
        double maxChange = dTheta.MaxAbs();
        double beta = MaxAngleJtranspose / maxChange;

        double scaleFactor = std::min(alpha, beta);
        dTheta *= scaleFactor;
    }

    void CalcDeltaThetasPseudoinverse() {
        MatrixRmn J1(2, nCol);
        for (int i = 0; i < 2; ++i)
            for (int j = 0; j < nCol; ++j)
                J1.Set(i, j, Jend.Get(i, j));

        VectorRn dS1(2);
        for (int i = 0; i < 2; ++i) dS1[i] = dS[i];

        MatrixRmn U_temp, V_temp;
        VectorRn w_temp;
        U_temp.SetSize(J1.NumRows, J1.NumRows);
        w_temp.SetLength(std::min(J1.NumRows, J1.NumCols));
        V_temp.SetSize(J1.NumCols, J1.NumCols);

        J1.ComputeSVD(U_temp, w_temp, V_temp);

        double threshold = PseudoInverseThresholdFactor * w_temp.MaxAbs();
        dTheta.SetZero();

        for (int i = 0; i < w_temp.length; ++i) {
            double dotProd = U_temp.DotProductColumn(dS1, i);
            double alpha = w_temp[i];
            if (std::fabs(alpha) > threshold) {
                alpha = 1.0 / alpha;
                for (int j = 0; j < V_temp.NumRows; ++j) {
                    dTheta[j] += V_temp.Get(j, i) * dotProd * alpha;
                }
            }
        }

        if (skeleton->getNumEffector() > 1) {
            // Task priority strategy implementation
            for (int i = 1; i < skeleton->getNumEffector(); ++i) {
                MatrixRmn Ji(2, nCol);
                for (int j = 0; j < nCol; ++j)
                    for (int k = 0; k < 2; ++k)
                        Ji.Set(k, j, Jend.Get(k + 2*i, j));

                VectorRn dSi(2);
                for (int k = 0; k < 2; ++k) dSi[k] = dS[k + 2*i];

                // Simplified projection calculation
                MatrixRmn proj(V_temp.NumRows, J1.NumCols);
                proj.SetIdentity();

                for (int j = 0; j < proj.NumCols; ++j)
                    for (int k = 0; k < proj.NumRows; ++k) {
                        double temp = proj.Get(k, j);
                        proj.Set(k, j, -temp);
                    }
                proj.AddToDiagonal(diagMatIdentity);

                MatrixRmn Jproj;
                MatrixRmn::Multiply(Ji, proj, Jproj);

                MatrixRmn U2, V2;
                VectorRn w2;
                U2.SetSize(Jproj.NumRows, Jproj.NumRows);
                w2.SetLength(std::min(Jproj.NumRows, Jproj.NumCols));
                V2.SetSize(Jproj.NumCols, Jproj.NumCols);

                Jproj.ComputeSVD(U2, w2, V2);

                double threshold2 = PseudoInverseThresholdFactor * w2.MaxAbs();
                VectorRn dTemp2(V2.NumRows);

                for (int j = 0; j < V2.NumCols; ++j) {
                    double alpha = w2[j];
                    if (std::fabs(alpha) > threshold2) {
                        for (int k = 0; k < V2.NumRows; ++k) {
                            dTemp2[k] += V2.Get(k, j) * U2.Get(k, i) * (1.0/alpha);
                        }
                    }
                }

                VectorRn dThetaCurrent;
                for (int k = 0; k < dTheta.length; ++k) dTheta[k] += dTemp2[k];
            }
        }

        double maxChange = dTheta.MaxAbs();
        if (maxChange > MaxAnglePseudoinverse) {
            dTheta *= MaxAnglePseudoinverse / maxChange;
        }
    }

    void CalcDeltaThetasDLS() {
        MatrixRmn JTJ(nCol, nCol);
        MatrixRmn::TransposeMultiply(Jend, Jend, JTJ);
        JTJ.AddToDiagonal(DampingLambdaSqV);

        VectorRn dTextra;
        JTJ.Solve(dS, &dT);
        Jend.MultiplyTranspose(dT, dTheta);

        double maxChange = dTheta.MaxAbs();
        if (maxChange > MaxAngleDLS) {
            dTheta *= MaxAngleDLS / maxChange;
        }
    }

    void CalcDeltaThetasDLSwithSVD() {
        MatrixRmn U_temp, V_temp;
        VectorRn w_temp;
        Jend.ComputeSVD(U_temp, w_temp, V_temp);

        long diagLength = w_temp.GetLength();
        dTheta.SetZero();

        for (long i = 0; i < diagLength; ++i) {
            double dotProd = U_temp.DotProductColumn(dS, i);
            double alpha = w_temp[i];
            alpha = alpha / (alpha * alpha + DampingLambdaSq);

            for (int j = 0; j < V_temp.NumRows; ++j) {
                dTheta[j] += V_temp.Get(j, i) * dotProd * alpha;
            }
        }

        double maxChange = dTheta.MaxAbs();
        if (maxChange > MaxAngleDLS) {
            dTheta *= MaxAngleDLS / maxChange;
        }
    }

    void CalcDeltaThetasSDLS() {
        MatrixRmn U_temp, V_temp;
        VectorRn w_temp;
        Jend.ComputeSVD(U_temp, w_temp, V_temp);

        int nRows = Jend.NumRows;
        int numEndEffectors = skeleton->getNumEffector();
        int nCols = Jend.NumCols;

        dTheta.SetZero();

        for (int i = 0; i < nRows; ++i) {
            double wi = w_temp[i];
            if (IsNearZero(wi, 1.0e-10)) continue;

            double alpha = 0.0;
            const double* uCol = U_temp.GetColumnPtr(i);
            for (int j = 0; j < numEndEffectors; ++j) {
                alpha += uCol[j] * dT[j];
            }

            double scale = alpha / wi;
            for (int j = 0; j < V_temp.NumRows; ++j) {
                dPreTheta[j] = V_temp.Get(j, i) * scale;
            }

            double maxVal = dPreTheta.MaxAbs();
            double rescale = (MaxAngleSDLS) / (MaxAngleSDLS + maxVal);
            dTheta.AddScaled(dPreTheta, rescale);
        }

        double maxChange = dTheta.MaxAbs();
        if (maxChange > 100 * MaxAngleSDLS) {
            dTheta *= MaxAngleSDLS / (MaxAngleSDLS + maxChange);
        }
    }

    void CalcdTClampedFromdS() {
        long len = dS.length;
        for (long i = 0; i < len; i += 2) {
            double normSq = dS[i]*dS[i] + dS[i+1]*dS[i+1];
            if (normSq > dSclamp[i/2] * dSclamp[i/2]) {
                double factor = dSclamp[i/2] / std::sqrt(normSq);
                dT[i] = dS[i] * factor;
                dT[i+1] = dS[i+1] * factor;
            } else {
                dT[i] = dS[i];
                dT[i+1] = dS[i+1];
            }
        }
    }

    void UpdatedSClampValue() {
        int numNode = skeleton->getNodeCount();
        for (int i = 0; i < numNode; ++i) {
            IKNode* n = skeleton->getNode(i);
            if (n->IsEffector()) {
                int idx = n->getEffectorNum();
                const TPointD& targetPos = target[idx];

                TPointD diff = targetPos - n->GetS();
                double currentDist = std::sqrt(diff.x*diff.x + diff.y*diff.y);
                double prevDist = std::sqrt(dS[2*idx]*dS[2*idx] + dS[2*idx+1]*dS[2*idx+1]);
                double changedDist = currentDist - prevDist;

                if (changedDist > 0.0) {
                    dSclamp[idx] = BaseMaxTargetDist + changedDist;
                } else {
                    dSclamp[idx] = BaseMaxTargetDist;
                }
            }
        }
    }
};

