class MachODebugMapParser {
public:
  MachODebugMapParser(llvm::IntrusiveRefCntPtr<llvm::vfs::FileSystem> VFS,
                      StringRef BinaryPath, ArrayRef<std::string> Archs,
                      ArrayRef<std::string> DSYMSearchPaths,
                      StringRef PathPrefix = "", StringRef VariantSuffix = "",
                      bool Verbose = false)
      : InputBinaryPath(std::string(BinaryPath)), SelectedArchs(Archs.begin(), Archs.end()),
        SearchPaths(DSYMSearchPaths.begin(), DSYMSearchPaths.end()),
        PrefixPath(std::string(PathPrefix)),
        SuffixVariant(std::string(VariantSuffix)), 
        BinaryManager(VFS, Verbose),
        ActiveDebugObject(nullptr), ShouldSkipCurrent(false) {}

  ErrorOr<std::vector<std::unique_ptr<DebugMap>>> parse();
  bool dumpStab();

private:
  std::string InputBinaryPath;
  SmallVector<StringRef, 1> SelectedArchs;
  SmallVector<StringRef, 1> SearchPaths;
  std::string PrefixPath;
  std::string SuffixVariant;

  BinaryHolder BinaryManager;
  StringMap<uint64_t> MainBinarySymbols;
  StringRef MainBinaryStringsData;

  std::unique_ptr<DebugMap> OutputMap;
  std::vector<std::string> CommonSymbolList;

  StringMap<std::optional<uint64_t>> CurrentObjSymbols;
  StringMap<std::optional<uint64_t>> AliasMapping;
  SmallSet<uint64_t, 4> ProcessedAliasValues;

  DebugMapObject *ActiveDebugObject;
  bool ShouldSkipCurrent;

  const char *CurrentFunctionName;
  uint64_t CurrentFunctionAddress;

  std::unique_ptr<DebugMap> processSingleBinary(const MachOObjectFile &MainBinary,
                                                StringRef BinaryPath);
  void processStabEntries(
      const MachOObjectFile &MainBinary,
      std::function<void(uint32_t, uint8_t, uint8_t, uint16_t, uint64_t)> Handler);
  void initializeNewDebugObject(StringRef Filename,
                                sys::TimePoint<std::chrono::seconds> Timestamp);
  void initializeNewLibraryDebugObject(StringRef Filename,
                                       sys::TimePoint<std::chrono::seconds> Timestamp);
  void clearParserState();
  uint64_t resolveMainBinarySymbol(StringRef Name);
  std::vector<StringRef> findSymbolsByAddress(uint64_t Address);
  void populateMainBinarySymbols(const MachOObjectFile &MainBinary);
  void populateCurrentObjectSymbols(const MachOObjectFile &Obj);
  void processOSOEntry(uint32_t StringIndex, uint8_t Type,
                       uint8_t SectionIndex, uint16_t Flags, uint64_t Value,
                       DenseSet<std::pair<llvm::StringRef, uint64_t>> &OSOs,
                       SmallSet<std::pair<llvm::StringRef, uint64_t>, 4> &Duplicates);
  void processSymbolEntry(uint32_t StringIndex, uint8_t Type,
                          uint8_t SectionIndex, uint16_t Flags,
                          uint64_t Value,
                          const SmallSet<std::pair<llvm::StringRef, uint64_t>, 4> &Duplicates);
  template <typename EntryType>
  void dispatchStabEntry(const EntryType &Entry,
                         std::function<void(uint32_t, uint8_t, uint8_t, uint16_t, uint64_t)> Handler) {
    Handler(Entry.n_strx, Entry.n_type, Entry.n_sect, Entry.n_desc, Entry.n_value);
  }
  void finalizeCommonSymbols();

  void printSymbolTableHeader(raw_ostream &OS, StringRef Arch);
  void printSymbolEntry(raw_ostream &OS, uint64_t Index, uint32_t StringIndex,
                        uint8_t Type, uint8_t SectionIndex, uint16_t Flags,
                        uint64_t Value);
  template <typename EntryType>
  void printSymbolEntry(raw_ostream &OS, uint64_t Index, const EntryType &Entry) {
    printSymbolEntry(OS, Index, Entry.n_strx, Entry.n_type, Entry.n_sect, 
                     Entry.n_desc, Entry.n_value);
  }
  void printOneBinarySymbols(const MachOObjectFile &MainBinary, StringRef BinaryPath);

  void reportWarning(const Twine &Msg, StringRef File = StringRef()) {
    assert(OutputMap &&
           "The debug map must be initialized before calling this function");
    WithColor::warning() << "("
                         << MachOUtils::getArchName(
                                OutputMap->getTriple().getArchName())
                         << ") " << File << " " << Msg << "\n";
  }
};

void MachODebugMapParser::clearParserState() {
  CommonSymbolList.clear();
  CurrentObjSymbols.clear();
  AliasMapping.clear();
  ProcessedAliasValues.clear();
  ActiveDebugObject = nullptr;
  ShouldSkipCurrent = false;
}

void MachODebugMapParser::finalizeCommonSymbols() {
  for (const auto &SymbolName : CommonSymbolList) {
    uint64_t SymbolAddr = resolveMainBinarySymbol(SymbolName);
    if (SymbolAddr == 0) {
      continue;
    }

    if (!ActiveDebugObject->addSymbol(SymbolName,
                                      std::nullopt /*ObjectAddress*/,
                                      SymbolAddr, 0 /*size*/)) {
      continue;
    }
  }
}

void MachODebugMapParser::initializeNewDebugObject(
    StringRef Filename, sys::TimePoint<std::chrono::seconds> Timestamp) {
  finalizeCommonSymbols();
  clearParserState();

  SmallString<80> FullPath(PrefixPath);
  sys::path::append(FullPath, Filename);

  auto ObjectEntry = BinaryManager.getObjectEntry(FullPath, Timestamp);
  if (!ObjectEntry) {
    auto Err = ObjectEntry.takeError();
    reportWarning("unable to open object file: " + toString(std::move(Err)),
                  FullPath.str());
    return;
  }

  auto Object = ObjectEntry->getObjectAs<MachOObjectFile>(OutputMap->getTriple());
  if (!Object) {
    auto Err = Object.takeError();
    reportWarning("unable to open object file: " + toString(std::move(Err)),
                  FullPath.str());
    return;
  }

  ActiveDebugObject =
      &OutputMap->addDebugMapObject(FullPath, Timestamp, MachO::N_OSO);
  populateCurrentObjectSymbols(*Object);
}

void MachODebugMapParser::initializeNewLibraryDebugObject(
    StringRef Filename, sys::TimePoint<std::chrono::seconds> Timestamp) {
  if (SearchPaths.empty()) {
    reportWarning("no dSYM search path was specified");
    return;
  }

  StringRef BaseName = sys::path::filename(Filename);
  SmallString<128> VariantName;
  SmallString<128> ProductName(BaseName);

  size_t dylibExtPos = BaseName.rfind(".dylib");
  if (dylibExtPos != StringRef::npos) {
    if (!SuffixVariant.empty()) {
      VariantName.append(BaseName.substr(0, dylibExtPos));
      VariantName.append(SuffixVariant);
      VariantName.append(".dylib");
    }
  } else {
    ProductName.append(".framework");
    if (!SuffixVariant.empty()) {
      VariantName.append(BaseName);
      VariantName.append(SuffixVariant);
    }
  }

  for (auto SearchPath : SearchPaths) {
    SmallString<256> TryPath(SearchPath);
    SmallString<256> FallbackPath(TryPath);
    SmallString<256> DsymPath(ProductName);
    DsymPath.append(".dSYM");
    sys::path::append(DsymPath, "Contents", "Resources", "DWARF");

    if (!SuffixVariant.empty()) {
      sys::path::append(TryPath, DsymPath, VariantName);
      sys::path::append(FallbackPath, DsymPath, BaseName);
    } else {
      sys::path::append(TryPath, DsymPath, BaseName);
    }

    auto ObjectEntry = BinaryManager.getObjectEntry(TryPath, Timestamp);
    if (!ObjectEntry) {
      auto Err = ObjectEntry.takeError();
      reportWarning("unable to open object file: " + toString(std::move(Err)),
                    TryPath.str());

      if (!SuffixVariant.empty()) {
        ObjectEntry = BinaryManager.getObjectEntry(FallbackPath, Timestamp);
        if (!ObjectEntry) {
          auto Err = ObjectEntry.takeError();
          reportWarning("unable to open object file: " + toString(std::move(Err)),
                        FallbackPath.str());
          continue;
        }
        TryPath.assign(FallbackPath);
      } else {
        continue;
      }
    }

    auto Object =
        ObjectEntry->getObjectAs<MachOObjectFile>(OutputMap->getTriple());
    if (!Object) {
      auto Err = Object.takeError();
      reportWarning("unable to open object file: " + toString(std::move(Err)),
                    TryPath.str());
      continue;
    }

    if (ActiveDebugObject &&
        ActiveDebugObject->getType() == MachO::N_LIB &&
        ActiveDebugObject->getObjectFilename().compare(TryPath.str()) == 0) {
      return;
    }

    finalizeCommonSymbols();
    clearParserState();
    ActiveDebugObject =
        &OutputMap->addDebugMapObject(TryPath, Timestamp, MachO::N_LIB);
    ActiveDebugObject->setInstallName(Filename);

    SmallString<256> RelocMapPath(SearchPath);
    sys::path::append(RelocMapPath, ProductName);
    RelocMapPath.append(".dSYM");
    StringRef ArchName = Triple::getArchName(OutputMap->getTriple().getArch(),
                                             OutputMap->getTriple().getSubArch());
    sys::path::append(RelocMapPath, "Contents", "Resources", "Relocations", ArchName);
    sys::path::append(RelocMapPath, BaseName);
    RelocMapPath.append(".yml");

    const auto &RelocMapPtrOrErr =
        RelocationMap::parseYAMLRelocationMap(RelocMapPath, PrefixPath);
    if (auto EC = RelocMapPtrOrErr.getError()) {
      reportWarning("cannot parse relocation map file: " + EC.message(),
                    RelocMapPath.str());
      return;
    }

    ActiveDebugObject->setRelocationMap(*RelocMapPtrOrErr->get());
    populateCurrentObjectSymbols(*Object);
    return;
  }
}

static std::string extractArchName(const object::MachOObjectFile &Obj) {
  Triple T = Obj.getArchTriple();
  return std::string(T.getArchName());
}

void MachODebugMapParser::processStabEntries(
    const MachOObjectFile &MainBinary,
    std::function<void(uint32_t, uint8_t, uint8_t, uint16_t, uint64_t)> Handler) {
  for (const SymbolRef &Symbol : MainBinary.symbols()) {
    const DataRefImpl &DRI = Symbol.getRawDataRefImpl();
    if (MainBinary.is64Bit())
      dispatchStabEntry(MainBinary.getSymbol64TableEntry(DRI), Handler);
    else
      dispatchStabEntry(MainBinary.getSymbolTableEntry(DRI), Handler);
  }
}

std::unique_ptr<DebugMap>
MachODebugMapParser::processSingleBinary(const MachOObjectFile &MainBinary,
                                         StringRef BinaryPath) {
  OutputMap = std::make_unique<DebugMap>(MainBinary.getArchTriple(), BinaryPath,
                                        MainBinary.getUuid());
  populateMainBinarySymbols(MainBinary);
  MainBinaryStringsData = MainBinary.getStringTableData();

  DenseSet<std::pair<llvm::StringRef, uint64_t>> SeenOSOs;
  SmallSet<std::pair<llvm::StringRef, uint64_t>, 4> DuplicateOSOs;

  processStabEntries(MainBinary,
                     [&](uint32_t StringIndex, uint8_t Type,
                         uint8_t SectionIndex, uint16_t Flags, uint64_t Value) {
                       processOSOEntry(StringIndex, Type, SectionIndex,
                                      Flags, Value, SeenOSOs, DuplicateOSOs);
                     });

  for (const auto &OSO : DuplicateOSOs) {
    std::string Buffer;
    llvm::raw_string_ostream OS(Buffer);
    OS << sys::TimePoint<std::chrono::seconds>(sys::toTimePoint(OSO.second));
    reportWarning("skipping debug map object with duplicate name and timestamp: " +
                  OS.str() + Twine(" ") + Twine(OSO.first));
  }

  processStabEntries(MainBinary, [&](uint32_t StringIndex, uint8_t Type,
                                     uint8_t SectionIndex, uint16_t Flags,
                                     uint64_t Value) {
    processSymbolEntry(StringIndex, Type, SectionIndex, Flags, Value,
                       DuplicateOSOs);
  });

  clearParserState();
  return std::move(OutputMap);
}

struct DarwinStabName {
  uint8_t NType;
  const char *Name;
};

static const DarwinStabName DarwinStabNames[] = {
  {MachO::N_GSYM, "N_GSYM"},   {MachO::N_FNAME, "N_FNAME"}, {MachO::N_FUN, "N_FUN"},
  {MachO::N_STSYM, "N_STSYM"}, {MachO::N_LCSYM, "N_LCSYM"}, {MachO::N_BNSYM, "N_BNSYM"},
  {MachO::N_PC, "N_PC"},       {MachO::N_AST, "N_AST"},     {MachO::N_OPT, "N_OPT"},
  {MachO::N_RSYM, "N_RSYM"},   {MachO::N_SLINE, "N_SLINE"}, {MachO::N_ENSYM, "N_ENSYM"},
  {MachO::N_SSYM, "N_SSYM"},   {MachO::N_SO, "N_SO"},       {MachO::N_OSO, "N_OSO"},
  {MachO::N_LIB, "N_LIB"},     {MachO::N_LSYM, "N_LSYM"},   {MachO::N_BINCL, "N_BINCL"},
  {MachO::N_SOL, "N_SOL"},     {MachO::N_PARAMS, "N_PARAM"},{MachO::N_VERSION, "N_VERS"},
  {MachO::N_OLEVEL, "N_OLEV"}, {MachO::N_PSYM, "N_PSYM"},   {MachO::N_EINCL, "N_EINCL"},
  {MachO::N_ENTRY, "N_ENTRY"}, {MachO::N_LBRAC, "N_LBRAC"}, {MachO::N_EXCL, "N_EXCL"},
  {MachO::N_RBRAC, "N_RBRAC"}, {MachO::N_BCOMM, "N_BCOMM"}, {MachO::N_ECOMM, "N_ECOMM"},
  {MachO::N_ECOML, "N_ECOML"}, {MachO::N_LENG, "N_LENG"},   {0, nullptr}
};

static const char *lookupDarwinStab(uint8_t NType) {
  for (unsigned i = 0; DarwinStabNames[i].Name; i++) {
    if (DarwinStabNames[i].NType == NType)
      return DarwinStabNames[i].Name;
  }
  return nullptr;
}

void MachODebugMapParser::printSymbolTableHeader(raw_ostream &OS, StringRef Arch) {
  OS << "-----------------------------------"
        "-----------------------------------\n";
  OS << "Symbol table for: '" << InputBinaryPath << "' (" << Arch.data() << ")\n";
  OS << "-----------------------------------"
        "-----------------------------------\n";
  OS << "Index    n_strx   n_type             n_sect n_desc n_value\n";
  OS << "======== -------- ------------------ ------ ------ ----------------\n";
}

void MachODebugMapParser::printSymbolEntry(raw_ostream &OS, uint64_t Index,
                                           uint32_t StringIndex, uint8_t Type,
                                           uint8_t SectionIndex, uint16_t Flags,
                                           uint64_t Value) {
  OS << '[' << format_decimal(Index, 6)
     << "] "
     << format_hex_no_prefix(StringIndex, 8)
     << ' '
     << format_hex_no_prefix(Type, 2) << " (";

  if (Type & MachO::N_STAB)
    OS << left_justify(lookupDarwinStab(Type), 13);
  else {
    if (Type & MachO::N_PEXT)
      OS << "PEXT ";
    else
      OS << "     ";

    switch (Type & MachO::N_TYPE) {
    case MachO::N_UNDF:
      OS << "UNDF";
      break;
    case MachO::N_ABS:
      OS << "ABS ";
      break;
    case MachO::N_SECT:
      OS << "SECT";
      break;
    case MachO::N_PBUD:
      OS << "PBUD";
      break;
    case MachO::N_INDR:
      OS << "INDR";
      break;
    default:
      OS << format_hex_no_prefix(Type, 2) << "    ";
      break;
    }

    if (Type & MachO::N_EXT)
      OS << " EXT";
    else
      OS << "    ";
  }

  OS << ") "
     << format_hex_no_prefix(SectionIndex, 2)
     << "     "
     << format_hex_no_prefix(Flags, 4)
     << "   "
     << format_hex_no_prefix(Value, 16);

  const char *Name = &MainBinaryStringsData.data()[StringIndex];
  if (Name && Name[0])
    OS << " '" << Name << "'";
  OS << "\n";
}

void MachODebugMapParser::printOneBinarySymbols(const MachOObjectFile &MainBinary,
                                                StringRef BinaryPath) {
  populateMainBinarySymbols(MainBinary);
  MainBinaryStringsData = MainBinary.getStringTableData();
  raw_ostream &OS(llvm::outs());
  printSymbolTableHeader(OS, extractArchName(MainBinary));

  uint64_t Idx = 0;
  for (const SymbolRef &Symbol : MainBinary.symbols()) {
    const DataRefImpl &DRI = Symbol.getRawDataRefImpl();
    if (MainBinary.is64Bit())
      printSymbolEntry(OS, Idx, MainBinary.getSymbol64TableEntry(DRI));
    else
      printSymbolEntry(OS, Idx, MainBinary.getSymbolTableEntry(DRI));
    Idx++;
  }

  OS << "\n\n";
  clearParserState();
}

bool shouldProcessArch(SmallVectorImpl<StringRef> &Archs, StringRef Arch) {
  if (Archs.empty() || is_contained(Archs, "all") || is_contained(Archs, "*"))
    return true;
  if (Arch.starts_with("arm") && Arch != "arm64" && is_contained(Archs, "arm"))
    return true;
  SmallString<16> NormalizedArch = Arch;
  if (Arch.starts_with("thumb"))
    NormalizedArch = ("arm" + Arch.substr(5)).str();
  return is_contained(Archs, NormalizedArch);
}

bool MachODebugMapParser::dumpStab() {
  auto ObjectEntry = BinaryManager.getObjectEntry(InputBinaryPath);
  if (!ObjectEntry) {
    auto Err = ObjectEntry.takeError();
    WithColor::error() << "cannot load '" << InputBinaryPath
                       << "': " << toString(std::move(Err)) << '\n';
    return false;
  }

  auto Objects = ObjectEntry->getObjectsAs<MachOObjectFile>();
  if (!Objects) {
    auto Err = Objects.takeError();
    WithColor::error() << "cannot get '" << InputBinaryPath
                       << "' as MachO file: " << toString(std::move(Err))
                       << "\n";
    return false;
  }

  for (const auto *Object : *Objects)
    if (shouldProcessArch(SelectedArchs, Object->getArchTriple().getArchName()))
      printOneBinarySymbols(*Object, InputBinaryPath);

  return true;
}

ErrorOr<std::vector<std::unique_ptr<DebugMap>>> MachODebugMapParser::parse() {
  auto ObjectEntry = BinaryManager.getObjectEntry(InputBinaryPath);
  if (!ObjectEntry) {
    return errorToErrorCode(ObjectEntry.takeError());
  }

  auto Objects = ObjectEntry->getObjectsAs<MachOObjectFile>();
  if (!Objects) {
    return errorToErrorCode(Objects.takeError());
  }

  std::vector<std::unique_ptr<DebugMap>> Results;
  for (const auto *Object : *Objects)
    if (shouldProcessArch(SelectedArchs, Object->getArchTriple().getArchName()))
      Results.push_back(processSingleBinary(*Object, InputBinaryPath));

  return std::move(Results);
}

void MachODebugMapParser::processOSOEntry(
    uint32_t StringIndex, uint8_t Type, uint8_t SectionIndex, uint16_t Flags,
    uint64_t Value, DenseSet<std::pair<llvm::StringRef, uint64_t>> &OSOs,
    SmallSet<std::pair<llvm::StringRef, uint64_t>, 4> &Duplicates) {
  if (Type != MachO::N_OSO)
    return;

  auto O = std::make_pair(llvm::StringRef(&MainBinaryStringsData.data()[StringIndex]), Value);
  if (!OSOs.insert(O).second)
    Duplicates.insert(O);
}

void MachODebugMapParser::processSymbolEntry(
    uint32_t StringIndex, uint8_t Type, uint8_t SectionIndex, uint16_t Flags,
    uint64_t Value, const SmallSet<std::pair<llvm::StringRef, uint64_t>, 4> &Duplicates) {
  if (!(Type & MachO::N_STAB))
    return;

  const char *Name = &MainBinaryStringsData.data()[StringIndex];

  if (Type == MachO::N_LIB) {
    initializeNewLibraryDebugObject(Name, sys::toTimePoint(Value));
    return;
  }

  if (Type == MachO::N_OSO) {
    if (!ActiveDebugObject ||
        ActiveDebugObject->getType() != MachO::N_LIB) {
      auto Key = std::make_pair(llvm::StringRef(Name), Value);
      if (Duplicates.count(Key)) {
        ShouldSkipCurrent = true;
        return;
      }
      initializeNewDebugObject(Name, sys::toTimePoint(Value));
    }
    return;
  }

  if (ShouldSkipCurrent)
    return;

  if (Type == MachO::N_AST) {
    SmallString<80> Path(PrefixPath);
    sys::path::append(Path, Name);
    OutputMap->addDebugMapObject(Path, sys::toTimePoint(Value), Type);
    return;
  }

  if (!ActiveDebugObject)
    return;

  uint32_t Size = 0;
  switch (Type) {
  case MachO::N_GSYM:
    Value = resolveMainBinarySymbol(Name);
    break;
  case MachO::N_FUN:
    if (Name[0] == '\0') {
      Size = Value;
      Value = CurrentFunctionAddress;
      Name = CurrentFunctionName;
      break;
    } else {
      CurrentFunctionName = Name;
      CurrentFunctionAddress = Value;
      return;
    }
  case MachO::N_STSYM:
    break;
  default:
    return;
  }

  auto ObjectSymIt = CurrentObjSymbols.find(Name);

  if (ObjectSymIt == CurrentObjSymbols.end() && Type != MachO::N_STSYM) {
    if (ProcessedAliasValues.count(Value) == 0) {
      auto Aliases = findSymbolsByAddress(Value);
      for (const auto &Alias : Aliases) {
        auto It = CurrentObjSymbols.find(Alias);
        if (It != CurrentObjSymbols.end()) {
          auto AliasValue = It->getValue();
          for (const auto &Alias : Aliases)
            AliasMapping[Alias] = AliasValue;
          break;
        }
      }
      ProcessedAliasValues.insert(Value);
    }

    auto AliasIt = AliasMapping.find(Name);
    if (AliasIt != AliasMapping.end())
      ObjectSymIt = AliasIt;
  }

  if (ObjectSymIt == CurrentObjSymbols.end()) {
    for (auto Iter = CurrentObjSymbols.begin();
         Iter != CurrentObjSymbols.end(); ++Iter) {
      llvm::StringRef SymbolName = Iter->getKey();
      auto Pos = SymbolName.rfind(".llvm.");
      if (Pos != llvm::StringRef::npos && SymbolName.substr(0, Pos) == Name) {
        ObjectSymIt = Iter;
        break;
      }
    }
  }

  if (ObjectSymIt == CurrentObjSymbols.end()) {
    reportWarning("could not find symbol '" + Twine(Name) + "' in object file '" +
                  ActiveDebugObject->getObjectFilename() + "'");
    return;
  }

  if (!ActiveDebugObject->addSymbol(Name, ObjectSymIt->getValue(), Value, Size)) {
    reportWarning(Twine("failed to insert symbol '") + Name + "' in the debug map.");
    return;
  }
}

void MachODebugMapParser::populateCurrentObjectSymbols(
    const object::MachOObjectFile &Obj) {
  CurrentObjSymbols.clear();

  for (auto Sym : Obj.symbols()) {
    uint64_t Addr = cantFail(Sym.getValue());
    Expected<StringRef> Name = Sym.getName();
    if (!Name) {
      auto Err = Name.takeError();
      reportWarning("failed to get symbol name: " + toString(std::move(Err)),
                    Obj.getFileName());
      continue;
    }

    uint32_t Flags = cantFail(Sym.getFlags());
    if (Flags & SymbolRef::SF_Absolute) {
      CurrentObjSymbols[*Name] = std::nullopt;
    } else if (Flags & SymbolRef::SF_Common) {
      CurrentObjSymbols[*Name] = std::nullopt;
      CommonSymbolList.push_back(std::string(*Name));
    } else {
      CurrentObjSymbols[*Name] = Addr;
    }
  }
}

uint64_t MachODebugMapParser::resolveMainBinarySymbol(StringRef Name) {
  auto Sym = MainBinarySymbols.find(Name);
  if (Sym == MainBinarySymbols.end())
    return 0;
  return Sym->second;
}

std::vector<StringRef>
MachODebugMapParser::findSymbolsByAddress(uint64_t Address) {
  std::vector<StringRef> Names;
  for (const auto &Entry : MainBinarySymbols) {
    if (Entry.second == Address)
      Names.push_back(Entry.first());
  }
  return Names;
}

void MachODebugMapParser::populateMainBinarySymbols(
    const MachOObjectFile &MainBinary) {
  section_iterator Section = MainBinary.section_end();
  MainBinarySymbols.clear();

  for (const auto &Sym : MainBinary.symbols()) {
    Expected<SymbolRef::Type> TypeOrErr = Sym.getType();
    if (!TypeOrErr) {
      auto Err = TypeOrErr.takeError();
      reportWarning("failed to get symbol type: " + toString(std::move(Err)),
                    MainBinary.getFileName());
      continue;
    }

    SymbolRef::Type Type = *TypeOrErr;
    if ((Type == SymbolRef::ST_Debug) || (Type == SymbolRef::ST_Unknown))
      continue;

    uint8_t SymType =
        MainBinary.getSymbolTableEntry(Sym.getRawDataRefImpl()).n_type;
    bool Extern = SymType & (MachO::N_EXT | MachO::N_PEXT);

    Expected<section_iterator> SectionOrErr = Sym.getSection();
    if (!SectionOrErr) {
      auto Err = TypeOrErr.takeError();
      reportWarning("failed to get symbol section: " + toString(std::move(Err)),
                    MainBinary.getFileName());
      continue;
    }

    Section = *SectionOrErr;
    if ((Section == MainBinary.section_end() || Section->isText()) && !Extern)
      continue;

    uint64_t Addr = cantFail(Sym.getValue());
    Expected<StringRef> NameOrErr = Sym.getName();
    if (!NameOrErr) {
      auto Err = NameOrErr.takeError();
      reportWarning("failed to get symbol name: " + toString(std::move(Err)),
                    MainBinary.getFileName());
      continue;
    }

    StringRef Name = *NameOrErr;
    if (Name.size() == 0 || Name[0] == '\0')
      continue;

    if (Extern)
      MainBinarySymbols[Name] = Addr;
    else
      MainBinarySymbols.try_emplace(Name, Addr);
  }
}

