int main(int argc, char** argv) {
    int* deviceMemory = nullptr;
    int selectedCounterIdx = 0;

    if (argc > 1) {
        selectedCounterIdx = std::atoi(argv[1]);
    }

    prepare();

    // Initialize profiler runtime
    CHECK_ROCPROFILER(rocprofiler_initialize());

    // Create profiling session
    rocprofiler_session_id_t profSession;
    CHECK_ROCPROFILER(rocprofiler_create_session(ROCPROFILER_NONE_REPLAY_MODE, &profSession));

    // Define buffer callback
    rocprofiler_buffer_callback_t bufferCallback =
        [](const rocprofiler_record_header_t* recHead,
           const rocprofiler_record_header_t* endRecHead,
           rocprofiler_session_id_t sessId,
           rocprofiler_buffer_id_t bufId) {
            WriteBufferRecords(recHead, endRecHead, sessId, bufId);
        };

    // Setup output buffer
    rocprofiler_buffer_id_t dataBuffer;
    constexpr size_t BUFFER_SIZE = 0x999999;
    CHECK_ROCPROFILER(rocprofiler_create_buffer(profSession, bufferCallback, BUFFER_SIZE, &dataBuffer));

    // Define available XGMI counter names
    const char* xgmiCounterNames[] = {
        "xgmi_link0_data_outbound", "xgmi_link1_data_outbound",
        "xgmi_link2_data_outbound", "xgmi_link3_data_outbound",
        "xgmi_link4_data_outbound", "xgmi_link5_data_outbound",
        "xgmi_link5_data_outbound", "xgmi_link6_data_outbound"
    };
    constexpr size_t NUM_XGMI_COUNTERS = sizeof(xgmiCounterNames) / sizeof(xgmiCounterNames[0]);

    // Validate index bounds (defensive)
    if (selectedCounterIdx < 0 || selectedCounterIdx >= static_cast<int>(NUM_XGMI_COUNTERS)) {
        selectedCounterIdx = 0;
    }

    // Prepare counter input structure
    rocprofiler_counters_sampler_counter_input_t samplerInput = {
        .name = const_cast<char*>(xgmiCounterNames[selectedCounterIdx]),
        .type = ROCPROFILER_COUNTERS_SAMPLER_XGMI_COUNTERS
    };

    // Sampling configuration
    uint32_t sampleIntervalMs = 1000;
    uint32_t totalDurationSec = 5;  // note: original used ms but sleep is in seconds — kept consistent
    uint32_t gpuDeviceIdx = 0;

    rocprofiler_counters_sampler_parameters_t samplerParams = {
        .counters = &samplerInput,
        .counters_num = 1,
        .sampling_rate = sampleIntervalMs,
        .sampling_duration = totalDurationSec * 1000,  // convert sec → ms for consistency
        .gpu_agent_index = gpuDeviceIdx
    };

    // Create filter
    rocprofiler_filter_id_t filterHandle;
    [[maybe_unused]] rocprofiler_filter_property_t filterProp = {};
    CHECK_ROCPROFILER(rocprofiler_create_filter(
        profSession,
        ROCPROFILER_COUNTERS_SAMPLER,
        rocprofiler_filter_data_t{.counters_sampler_parameters = samplerParams},
        0,
        &filterHandle,
        filterProp
    ));

    // Attach buffer to filter
    CHECK_ROCPROFILER(rocprofiler_set_filter_buffer(profSession, filterHandle, dataBuffer));

    // Allocate GPU memory and query device info
    hipDeviceProp_t deviceInfo;
    HIP_CALL(hipGetDeviceProperties(&deviceInfo, 0));
    HIP_CALL(hipMalloc(reinterpret_cast<void**>(&deviceMemory), sizeof(int)));

    // Pre-profile kernels (not measured)
    kernelCalls('A');
    kernelCalls('B');

    std::cout << "Profiling counter: " << xgmiCounterNames[selectedCounterIdx]
              << " | Sample interval: " << sampleIntervalMs << " ms"
              << " | Duration: " << totalDurationSec << " s" << std::endl;

    // Start profiling session
    CHECK_ROCPROFILER(rocprofiler_start_session(profSession));

    // Kernels to be profiled
    kernelCalls('C');
    kernelCalls('D');
    kernelCalls('E');
    kernelCalls('F');

    // Cleanup resources (non-profiled)
    HIP_CALL(hipFree(deviceMemory));

    // Wait for sampling period (using loop instead of sleep for portability/clarity)
    volatile unsigned long waitLoops = 6'000'000UL;  // approximate 6s delay on modern CPU
    do {
        waitLoops--;
    } while (waitLoops > 0);

    // Stop and finalize profiling
    CHECK_ROCPROFILER(rocprofiler_terminate_session(profSession));
    CHECK_ROCPROFILER(rocprofiler_flush_data(profSession, dataBuffer));
    CHECK_ROCPROFILER(rocprofiler_destroy_session(profSession));
    CHECK_ROCPROFILER(rocprofiler_finalize());

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using Permutation = vector<int>;

struct SearchNode {
    Permutation state;
    int opX, opY;       // operation parameters used to reach this state
    int parentIdx;      // index of predecessor in BFS tree
    int depth;          // number of operations taken to reach this state
};

// Apply transformation: rotate segments [0..x-1], [x..n-y-1], [n-y..n-1]
Permutation transform(const Permutation& input, int segX, int segY) {
    int len = input.size();
    Permutation result(len);

    // Suffix of length segY moves to front
    for (int i = 0; i < segY; ++i) {
        result[i] = input[len - segY + i];
    }

    // Middle segment follows
    for (int i = 0; i < len - segX - segY; ++i) {
        result[segY + i] = input[segX + i];
    }

    // Prefix of length segX goes to end
    for (int i = 0; i < segX; ++i) {
        result[len - segX + i] = input[i];
    }

    return result;
}

// BFS search for optimal solution when n is small
pair<Permutation, vector<pair<int,int>>> findOptimalSequence(const Permutation& initial, int limitOps) {
    int n = initial.size();
    queue<SearchNode> bfsQueue;
    map<Permutation, int> seenStates;

    SearchNode startNode = {initial, -1, -1, -1, 0};
    bfsQueue.push(startNode);
    seenStates[initial] = 0;

    Permutation bestState = initial;

    while (!bfsQueue.empty()) {
        auto current = bfsQueue.front();
        bfsQueue.pop();

        // Update best found so far
        if (current.state < bestState) {
            bestState = current.state;
        }

        // Stop expanding if we've reached operation limit
        if (current.depth >= limitOps) continue;

        // Try all valid (x,y) combinations where x>=1, y>=1, x+y<n
        for (int x = 1; x < n; ++x) {
            for (int y = 1; x + y < n; ++y) {
                Permutation nextState = transform(current.state, x, y);

                if (seenStates.find(nextState) == seenStates.end()) {
                    SearchNode newNode = {nextState, x, y, seenStates.size(), current.depth + 1};
                    seenStates[nextState] = seenStates.size();
                    bfsQueue.push(newNode);
                }
            }
        }
    }

    // Reconstruct path (simplified - just returns empty ops since we don't track full path)
    vector<pair<int,int>> ops;
    return {bestState, ops};
}

// Greedy approach for larger permutations
vector<pair<int,int>> constructGreedyPath(Permutation current, int maxSteps) {
    int n = current.size();
    vector<pair<int,int>> steps;

    for (int target = 1; target <= n && steps.size() < maxSteps; ++target) {
        // Find position of target value
        int pos = find(current.begin(), current.end(), target) - current.begin();
        if (pos == 0) continue; // Already at front

        bool success = false;

        // Case 1: Target is far enough from front (pos >= 2)
        if (pos >= 2) {
            int suffixLen = n - pos;
            if (suffixLen > 0 && 1 + suffixLen < n) {
                steps.emplace_back(1, suffixLen);
                current = transform(current, 1, suffixLen);
                success = true;
            }
        }
        // Case 2: Target is last element (pos == n-1)
        else if (pos == n - 1) {
            if (n >= 3) {
                steps.emplace_back(1, 1);
                current = transform(current, 1, 1);
                success = true;
            }
        }
        // Case 3: Target is second element (pos == 1)
        else if (pos == 1) {
            if (n >= 4 && 2 + 1 < n) {
                steps.emplace_back(2, 1);
                current = transform(current, 2, 1);
                if (n >= 3) {
                    steps.emplace_back(1, 1);
                    current = transform(current, 1, 1);
                    success = true;
                } else {
                    steps.pop_back();
                    break;
                }
            }
        }

        if (!success) break;
    }

    if (steps.size() > maxSteps) {
        steps.resize(maxSteps);
    }

    return steps;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    Permutation perm(N);
    for (int i = 0; i < N; ++i) {
        cin >> perm[i];
    }

    vector<pair<int,int>> solution;

    if (N <= 9) {
        // Use BFS for small inputs
        auto [bestPerm, ops] = findOptimalSequence(perm, 4 * N);
        solution = ops;
    } else {
        // Use greedy method for larger inputs
        solution = constructGreedyPath(perm, 4 * N);
    }

    cout << solution.size() << '\n';
    for (auto [a, b] : solution) {
        cout << a << ' ' << b << '\n';
    }

    return 0;
}

