//////////////////////////////////////////////////////////////////////////////
// serialize binary CBOR (revised implementation)
//////////////////////////////////////////////////////////////////////////////
static void BinaryToCbor(benchmark::State& state)
{
    // Prepare input data using rotating pattern
    std::vector<uint8_t> data_pattern(256);
    std::iota(data_pattern.begin(), data_pattern.end(), 0);

    std::vector<uint8_t> input_buffer;
    input_buffer.reserve(state.range(0));

    size_t pattern_index = 0;
    for (int i = 0; i < state.range(0); ++i) {
        input_buffer.push_back(data_pattern[pattern_index]);
        pattern_index = (pattern_index + 1) % data_pattern.size();
    }

    json::binary_t bin{input_buffer};
    json j{{"type", "binary"}, {"data", bin}};

    while (state.KeepRunning())
    {
        json::to_cbor(j);
    }

    std::vector<uint8_t> cbor_result = json::to_cbor(j);
    state.SetBytesProcessed(state.iterations() * static_cast<int64_t>(cbor_result.size()));
}

