// Helper to compare two values for equality and throw on mismatch
template <typename T>
void verify_equality(const T& expected, const T& actual) {
    if (expected != actual) {
        std::cerr << "Expected: " << expected << '\n';
        std::cerr << "Actual: " << actual << '\n';
        std::cerr.flush();
        throw std::runtime_error("Test failed");
    }
}

// Helper to parse a string using common_json_parse with a given healing marker
bool try_parse(const std::string& input, const std::string& marker, common_json& out) {
    auto it = input.begin();
    return common_json_parse(it, input.end(), marker, out);
}

// Extract result string from parsed JSON dump based on healing marker
std::string extract_result(const std::string& dump, const std::string& marker) {
    if (marker.empty()) {
        return dump;
    }
    size_t pos = dump.find(marker);
    if (pos == std::string::npos) {
        throw std::runtime_error("Failed to find magic in dump: " + dump + " (magic: " + marker + ")");
    }
    return dump.substr(0, pos);
}

// Test parsing partial strings up to each character position
void test_partial_parsing(const std::string& full_input) {
    std::cerr << "# Parsing partials of: " << full_input << '\n';
    for (size_t len = 1; len <= full_input.size(); ++len) {
        std::string prefix = full_input.substr(0, len);
        std::cerr << "# Parsing: " << prefix << '\n';

        common_json out;
        std::string healing_marker = "$llama.cpp.json$";
        if (try_parse(prefix, healing_marker, out)) {
            std::string dump = out.json.dump();
            std::cerr << "Parsed: " << dump << '\n';
            std::cerr << "Magic: " << out.healing_marker.json_dump_marker << '\n';

            std::string result = extract_result(dump, out.healing_marker.json_dump_marker);
            std::cerr << "Result: " << result << '\n';

            if (prefix.find(result) != 0) {
                std::cerr << "Failure! Prefix does not start with result.\n";
            }
        } else {
            throw std::runtime_error("Failed to parse: " + prefix);
        }
    }
}

// Unified test function for multiple inputs expecting same output
void run_test_group(const std::vector<std::string>& inputs,
                    const std::string& expected_output,
                    const std::string& expected_marker) {
    for (const auto& input : inputs) {
        common_json out;
        verify_equality(true, try_parse(input, "$foo", out));
        verify_equality(expected_output, out.json.dump(-1, ' ', true));
        verify_equality(expected_marker, out.healing_marker.json_dump_marker);
    }
}

// Main test suite
void execute_json_healing_tests() {
    // Test partial parsing on sample inputs
    test_partial_parsing("{\"a\": \"b\"}");
    test_partial_parsing("{\"hey\": 1, \"ho\\\"ha\": [1]}");
    test_partial_parsing("[{\"a\": \"b\"}]");

    // No healing needed
    run_test_group(
        {R"([{"a":"b"}, "y"])"},
        R"([{"a":"b"},"y"])",
        ""
    );

    // Partial literals cannot be healed — fallback to placeholder
    run_test_group(
        {
            R"([1)",
            R"([tru)",
            R"([n)",
            R"([nul)",
            R"([23.2)"
        },
        R"(["$foo"])",
        R"("$foo)"
    );

    run_test_group(
        {
            R"({"a": 1)",
            R"({"a": tru)",
            R"({"a": n)",
            R"({"a": nul)",
            R"({"a": 23.2)"
        },
        R"({"a":"$foo"})",
        R"("$foo)"
    );

    // Empty object/array
    run_test_group(
        {R"({)"},
        R"({"$foo":1})",
        R"("$foo)"
    );

    run_test_group(
        {R"([)"},
        R"(["$foo"])",
        R"("$foo)"
    );

    // Healing after complete literal
    run_test_group(
        {R"(1 )"},
        R"(1)",
        ""
    );

    run_test_group(
        {R"(true)", R"(true )"},
        R"(true)",
        ""
    );

    run_test_group(
        {R"(null)", R"(null )"},
        R"(null)",
        ""
    );

    // Healing after array element
    run_test_group(
        {R"([1 )"},
        R"([1,"$foo"])",
        R"(,"$foo)"
    );

    run_test_group(
        {R"([{})", R"([{} )"},
        R"([{},"$foo"])",
        R"(,"$foo)"
    );

    run_test_group(
        {R"([true)"},
        R"(["$foo"])",
        R"("$foo)"
    );

    run_test_group(
        {R"([true )"},
        R"([true,"$foo"])",
        R"(,"$foo)"
    );

    run_test_group(
        {R"([true,)"}, R"([true,"$foo"])",
        R"("$foo)"
    );

    // Nested healing tests
    run_test_group(
        {R"([{"a": [{"b": [{)})"},
        R"([{"a":[{"b":[{"$foo":1}]}]}])",
        R"("$foo)"
    );

    run_test_group(
        {R"([{"a": [{"b": [)})"},
        R"([{"a":[{"b":["$foo"]}]}])",
        R"("$foo)"
    );

    run_test_group(
        {R"([{"a": "b"})", R"([{"a": "b"} )")},
        R"([{"a":"b"},"$foo"])",
        R"(,"$foo)"
    );

    run_test_group(
        {R"([{"a": "b"},)", R"([{"a": "b"}, )")},
        R"([{"a":"b"},"$foo"])",
        R"("$foo)"
    );

    // Key healing tests
    run_test_group(
        {R"({ "code)")},
        R"({"code$foo":1})",
        R"($foo)"
    );

    run_test_group(
        {R"({ "code\)")},
        R"({"code\\$foo":1})",
        R"(\$foo)"
    );

    run_test_group(
        {R"({ "code")")},
        R"({"code":"$foo"})",
        R"(:"$foo)"
    );

    run_test_group(
        {R"({ "key")")},
        R"({"key":"$foo"})",
        R"(:"$foo)"
    );

    // Unicode escape sequence healing
    run_test_group(
        {R"({"a":"\u)")},
        R"({"a":"\u0000$foo"})",
        R"(0000$foo)"
    );

    run_test_group(
        {R"({"a":"\u00)")},
        R"({"a":"\u0000$foo"})",
        R"(00$foo)"
    );

    run_test_group(
        {R"({"a":"\ud300)")},
        R"({"a":"\ud300$foo"})",
        R"($foo)"
    );

    run_test_group(
        {R"({"a":"\ud800)")},
        R"({"a":"\ud800\udc00$foo"})",
        R"(\udc00$foo)"
    );

    run_test_group(
        {R"({"a":"\ud800\)")},
        R"({"a":"\ud800\udc00$foo"})",
        R"(udc00$foo)"
    );

    run_test_group(
        {R"({"a":"\ud800\u)")},
        R"({"a":"\ud800\udc00$foo"})",
        R"(dc00$foo)"
    );

    run_test_group(
        {R"({"a":"\ud800\udc00)")},
        R"({"a":"\ud800\udc00$foo"})",
        R"($foo)"
    );
}

int main() {
    try {
        execute_json_healing_tests();
        std::cerr << "All tests passed.\n";
        return 0;
    } catch (const std::exception& e) {
        std::cerr << "Exception caught: " << e.what() << '\n';
        return 1;
    }
}

