// Command-line flags to control statistic collection and display
static bool CollectStats = false;
static bool OutputAsJSON = false;
static bool ForceEnable = false;
static bool ShowOnShutdown = false;

void llvm::initStatisticOptions() {
  static cl::opt<bool, true> flagEnableStats{
      "stats",
      cl::desc("Enable statistics output from program (available with Asserts)"),
      cl::location(CollectStats), cl::Hidden};

  static cl::opt<bool, true> flagJsonOutput{
      "stats-json", cl::desc("Display statistics as JSON data"),
      cl::location(OutputAsJSON), cl::Hidden};
}

namespace {

// Internal container for tracking registered statistics
class StatsRegistry {
  std::vector<TrackingStatistic *> Entries;
  friend void llvm::PrintStatistics();
  friend void llvm::PrintStatistics(raw_ostream &);
  friend void llvm::PrintStatisticsJSON(raw_ostream &);

  // Reorder entries by group, name, description
  void reorder();

public:
  using const_iter = std::vector<TrackingStatistic *>::const_iterator;

  StatsRegistry() {
    TimerGroup::constructForStatistics(); // Ensure timers initialized first
  }

  ~StatsRegistry() {
    if (CollectStats || ShowOnShutdown)
      llvm::PrintStatistics();
  }

  void registerStat(TrackingStatistic *S) { Entries.push_back(S); }

  const_iter begin() const { return Entries.begin(); }
  const_iter end() const { return Entries.end(); }
  iterator_range<const_iter> items() const { return {begin(), end()}; }

  void clearAndReset();
};

} // anonymous namespace

static ManagedStatic<StatsRegistry> Registry;
static ManagedStatic<sys::SmartMutex<true>> StatMutex;

// Register a statistic on its first bump
void TrackingStatistic::RegisterStatistic() {
  if (!Initialized.load(std::memory_order_relaxed)) {
    sys::SmartMutex<true> &Mtx = *StatMutex;
    StatsRegistry &Reg = *Registry;

    sys::SmartScopedLock<true> Guard(Mtx);
    if (Initialized.load(std::memory_order_relaxed))
      return;

    if (CollectStats || ForceEnable)
      Reg.registerStat(this);

    Initialized.store(true, std::memory_order_release);
  }
}

// Sort helper: lexicographic ordering by debug type, name, description
void StatsRegistry::reorder() {
  std::stable_sort(
      Entries.begin(), Entries.end(),
      [](const TrackingStatistic *A, const TrackingStatistic *B) {
        int cmp = std::strcmp(A->getDebugType(), B->getDebugType());
        if (cmp != 0) return cmp < 0;
        cmp = std::strcmp(A->getName(), B->getName());
        if (cmp != 0) return cmp < 0;
        return std::strcmp(A->getDesc(), B->getDesc()) < 0;
      });
}

// Reset all registered statistics
void StatsRegistry::clearAndReset() {
  sys::SmartScopedLock<true> Guard(*StatMutex);
  for (auto *E : Entries) {
    E->Initialized = false;
    E->Value = 0;
  }
  Entries.clear();
}

// Public API to enable stats globally (e.g., for external tools)
void llvm::EnableStatistics(bool PrintOnShutdown) {
  ForceEnable = true;
  ShowOnShutdown = PrintOnShutdown;
}

bool llvm::AreStatisticsEnabled() {
  return ForceEnable || CollectStats;
}

// Text-mode output of statistics
void llvm::PrintStatistics(raw_ostream &OS) {
  StatsRegistry &Reg = *Registry;
  unsigned MaxValWidth = 0, MaxGroupWidth = 0;

  for (TrackingStatistic *S : Reg.Entries) {
    MaxValWidth = std::max(MaxValWidth, (unsigned)utostr(S->getValue()).size());
    MaxGroupWidth =
        std::max(MaxGroupWidth, (unsigned)std::strlen(S->getDebugType()));
  }

  Reg.reorder();

  OS << "===" << std::string(73, '-') << "===\n"
     << "                          ... Statistics Collected ...\n"
     << "===" << std::string(73, '-') << "===\n\n";

  for (TrackingStatistic *S : Reg.Entries) {
    OS << format("%*" PRIu64 " %-*s - %s\n", MaxValWidth, S->getValue(),
                 MaxGroupWidth, S->getDebugType(), S->getDesc());
  }

  OS << '\n';
  OS.flush();
}

// JSON output of statistics + timers
void llvm::PrintStatisticsJSON(raw_ostream &OS) {
  sys::SmartScopedLock<true> Guard(*StatMutex);
  StatsRegistry &Reg = *Registry;
  Reg.reorder();

  OS << "{\n";
  const char *sep = "";
  for (const TrackingStatistic *S : Reg.Entries) {
    OS << sep;
    assert(yaml::needsQuotes(S->getDebugType()) == yaml::QuotingType::None &&
           "Statistic group/type name is simple.");
    assert(yaml::needsQuotes(S->getName()) == yaml::QuotingType::None &&
           "Statistic name is simple");
    OS << "\t\"" << S->getDebugType() << '.' << S->getName() << "\": "
       << S->getValue();
    sep = ",\n";
  }

  TimerGroup::printAllJSONValues(OS, sep);
  OS << "\n}\n";
  OS.flush();
}

// Main entry point for printing statistics
void llvm::PrintStatistics() {
#if LLVM_ENABLE_STATS
  sys::SmartScopedLock<true> Guard(*StatMutex);
  StatsRegistry &Reg = *Registry;
  if (Reg.Entries.empty()) return;

  std::unique_ptr<raw_ostream> Stream = CreateInfoOutputFile();
  if (OutputAsJSON)
    PrintStatisticsJSON(*Stream);
  else
    PrintStatistics(*Stream);
#else
  if (CollectStats) {
    std::unique_ptr<raw_ostream> Stream = CreateInfoOutputFile();
    (*Stream) << "Statistics are disabled. "
              << "Build with asserts or with -DLLVM_FORCE_ENABLE_STATS\n";
  }
#endif
}

// Retrieve current statistics as key-value pairs
std::vector<std::pair<StringRef, uint64_t>> llvm::GetStatistics() {
  sys::SmartScopedLock<true> Guard(*StatMutex);
  std::vector<std::pair<StringRef, uint64_t>> Result;
  for (const auto *S : Registry->items())
    Result.emplace_back(S->getName(), S->getValue());
  return Result;
}

// Reset all statistics values and re-registration state
void llvm::ResetStatistics() {
  Registry->clearAndReset();
}

#include <iostream>

// Define unscoped enumerations (legacy C++ style)
enum Shape {
    circle, square, triangle
};

enum Vehicle {
    car,
    truck, 
    bus // This would cause a redefinition error if we had 'bus' in another unscoped enum
};

// Define scoped enumerations (C++11 and later)
enum class Direction {
    north, south, east, west
};

enum class Status {
    pending, active, completed
};

// Additional unscoped enum for demonstration
enum Season {
    spring, summer, autumn, winter
};

// Additional scoped enum for demonstration
enum class Priority {
    low, medium, high
};

int main() {
    // Using unscoped enums - values are implicitly convertible to int
    Shape shape = triangle;     // value: 2
    Vehicle vehicle = bus;      // value: 2

    // This comparison compiles but is semantically questionable:
    // both triangle and bus have the same underlying integer value (2)
    if (shape == vehicle) {
        // This block executes because both convert to int 2
        // Though logically, a shape shouldn't equal a vehicle!
    }

    // Using scoped enums - no implicit conversions
    Direction dir = Direction::east;   // value: 2
    Status stat = Status::completed;   // value: 2

    /*
    // This would cause a compile-time error:
    if (dir == stat) { ... }
    // Error: no operator== defined for comparing different enum types
    */

    // Explicit conversion required for scoped enums
    int val1 = static_cast<int>(Direction::south);  // OK: explicit cast
    int val2 = static_cast<int>(Status::active);    // OK: explicit cast

    // Demonstrating that unscoped enums can be assigned directly to int
    int x = Shape::circle;     // x = 0
    int y = Vehicle::car;      // y = 0

    // But scoped enums require explicit casting
    // int z = Direction::north; // Compilation error!
    int z = static_cast<int>(Direction::north); // Correct way

    return 0;
}

