// Alternative mock demangler implementation with modified internal logic
struct alternate_demangle_backend
{
    static inline unsigned invocation_counter = 0;

    // Returns a newly allocated C-string; caller must free
    static char* perform_demangling(const char* mangled_input, char*, size_t*, int* out_status)
    {
        ++invocation_counter;

        std::string input{ mangled_input };

        if (input.find("ERROR") != std::string::npos || input.empty())
        {
            *out_status = -1;
            return nullptr;
        }

        // Construct result manually to avoid string concatenation
        const char prefix[] = "demangled_";
        size_t prefix_len = sizeof(prefix) - 1;
        size_t input_len = input.length();
        size_t total_len = prefix_len + input_len;

        char* buffer = static_cast<char*>(std::malloc(total_len + 1));
        if (!buffer) return nullptr;

        std::memcpy(buffer, prefix, prefix_len);
        std::memcpy(buffer + prefix_len, input.c_str(), input_len);
        buffer[total_len] = '\0';

        *out_status = 0;
        return buffer;
    }
};

class demangle_test_suite : public ::testing::Test
{
protected:
    void SetUp() override { alternate_demangle_backend::invocation_counter = 0; }
};

TEST_F(demangle_test_suite, basic_success_case)
{
    rocprofsys::utility::demangler<alternate_demangle_backend> demangler_obj;
    std::string output = demangler_obj.demangle("symbol_name");
    EXPECT_EQ(output, "demangled_symbol_name");
    EXPECT_EQ(alternate_demangle_backend::invocation_counter, 1u);
}

TEST_F(demangle_test_suite, failure_fallback_preserves_original)
{
    rocprofsys::utility::demangler<alternate_demangle_backend> demangler_obj;
    std::string output = demangler_obj.demangle("broken_ERROR_symbol");
    EXPECT_EQ(output, "broken_ERROR_symbol");
    EXPECT_EQ(alternate_demangle_backend::invocation_counter, 1u);
}

TEST_F(demangle_test_suite, empty_input_skips_call)
{
    rocprofsys::utility::demangler<alternate_demangle_backend> demangler_obj;
    std::string output = demangler_obj.demangle("");
    EXPECT_TRUE(output.empty());
    EXPECT_EQ(alternate_demangle_backend::invocation_counter, 0u);
}

