namespace torch::comms {

// Helper to get current device safely
inline int getCurrentDeviceOrThrow() {
    return ::c10::xpu::current_device();
}

// Helper to retrieve SYCL device from index
inline sycl::device getRawDevice(int idx) {
    return ::c10::xpu::get_raw_device(idx);
}

// Helper to check if device supports free memory query
inline bool hasFreeMemorySupport(const sycl::device& dev) {
    return dev.has(sycl::aspect::ext_intel_free_memory);
}

// Helper to extract device name safely
inline std::string getDeviceName(const sycl::device& dev) {
    return dev.get_info<sycl::info::device::name>();
}

// Helper to fetch all relevant compute properties at once
struct DeviceComputeProps {
    size_t maxWorkGroupSize;
    std::array<size_t, 3> maxWorkItemSizes;
    uint32_t maxComputeUnits;
};

inline DeviceComputeProps getComputeProperties(const sycl::device& dev) {
    return {
        dev.get_info<sycl::info::device::max_work_group_size>(),
        dev.get_info<sycl::info::device::max_work_item_sizes<3>>(),
        static_cast<uint32_t>(dev.get_info<sycl::info::device::max_compute_units>())
    };
}

// Helper macro to reduce boilerplate error handling
#define XPU_TRY(expr) \
    do { \
        try { expr; } \
        catch (const std::exception& e) { \
            TC_LOG(ERROR) << "Exception: " << e.what(); \
            return XPU_ERROR_INVALID_VALUE; \
        } \
    } while(0)

xpu_result_t DefaultXpuApi::setDevice(int device) {
    if (device < 0) {
        TC_LOG(ERROR) << "Invalid device index: " << device;
        return XPU_ERROR_INVALID_VALUE;
    }
    try {
        ::c10::xpu::set_device(device);
        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to set XPU device to " << device << ": " << e.what();
        return XPU_ERROR_INVALID_VALUE;
    }
}

xpu_result_t DefaultXpuApi::getDeviceProperties(xpuDeviceProp* device_props, int device) {
    if (!device_props) {
        return XPU_ERROR_INVALID_VALUE;
    }

    try {
        auto dev = getRawDevice(device);
        auto nameStr = getDeviceName(dev);
        std::strncpy(device_props->name, nameStr.c_str(), 255);
        device_props->name[255] = '\0';

        device_props->totalGlobalMem = dev.get_info<sycl::info::device::global_mem_size>();

        if (!hasFreeMemorySupport(dev)) {
            TC_LOG(WARNING) << "Free memory queries unsupported on this SYCL device; falling back to total global memory.";
        }

        auto props = getComputeProperties(dev);
        device_props->multiProcessorCount = props.maxComputeUnits;
        device_props->maxThreadsPerBlock = props.maxWorkGroupSize;
        std::memcpy(device_props->maxThreadsDim, props.maxWorkItemSizes.data(), sizeof(props.maxWorkItemSizes));

        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to retrieve properties for device " << device << ": " << e.what();
        return XPU_ERROR_INVALID_VALUE;
    }
}

xpu_result_t DefaultXpuApi::memGetInfo(size_t* free, size_t* total) {
    if (!free || !total) {
        return XPU_ERROR_INVALID_VALUE;
    }

    try {
        int devIdx = getCurrentDeviceOrThrow();
        auto dev = getRawDevice(devIdx);

        *total = dev.get_info<sycl::info::device::global_mem_size>();

        if (hasFreeMemorySupport(dev)) {
            *free = dev.get_info<sycl::ext::intel::info::device::free_memory>();
        } else {
            *free = *total;
        }

        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to query XPU memory info: " << e.what();
        return XPU_ERROR_INVALID_VALUE;
    }
}

xpu_result_t DefaultXpuApi::getDeviceCount(int* count) {
    if (!count) {
        return XPU_ERROR_INVALID_VALUE;
    }

    try {
        *count = ::c10::xpu::device_count();
        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to get XPU device count: " << e.what();
        return XPU_ERROR_INVALID_VALUE;
    }
}

xpu_result_t DefaultXpuApi::streamCreateWithPriority(
    xpuStream_t& stream,
    [[maybe_unused]] unsigned int flags,
    int priority) {
    try {
        stream = ::c10::xpu::getStreamFromPool(priority);
        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to create XPU stream with priority " << priority << ": " << e.what();
        return XPU_ERROR_INVALID_VALUE;
    }
}

xpu_result_t DefaultXpuApi::streamDestroy([[maybe_unused]] const xpuStream_t& stream) {
    // Managed by PyTorch runtime; no-op
    return XPU_SUCCESS;
}

xpu_result_t DefaultXpuApi::streamWaitEvent(
    const xpuStream_t& stream,
    xpuEvent_t& event,
    [[maybe_unused]] unsigned int flags) {
    try {
        event.block(stream);
        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to synchronize stream with event: " << e.what();
        return XPU_ERROR_INVALID_HANDLE;
    }
}

xpuStream_t DefaultXpuApi::getCurrentXPUStream(int device_index) {
    return ::c10::xpu::getCurrentXPUStream(device_index);
}

xpu_result_t DefaultXpuApi::streamSynchronize(const xpuStream_t& stream) {
    try {
        stream.queue().wait_and_throw();
        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to synchronize XPU stream: " << e.what();
        return XPU_ERROR_INVALID_HANDLE;
    }
}

xpu_result_t DefaultXpuApi::streamIsCapturing(
    [[maybe_unused]] const xpuStream_t& stream,
    xpuStreamCaptureStatus* pCaptureStatus) {
    if (!pCaptureStatus) {
        return XPU_ERROR_INVALID_VALUE;
    }
    *pCaptureStatus = xpuStreamCaptureStatusNone;
    return XPU_ERROR_UNSUPPORTED;
}

xpu_result_t DefaultXpuApi::streamGetCaptureInfo(
    [[maybe_unused]] const xpuStream_t& stream,
    xpuStreamCaptureStatus* pCaptureStatus,
    unsigned long long* pId) {
    if (!pCaptureStatus) {
        return XPU_ERROR_INVALID_VALUE;
    }
    *pCaptureStatus = xpuStreamCaptureStatusNone;
    if (pId) {
        *pId = 0;
    }
    return XPU_ERROR_UNSUPPORTED;
}

xpu_result_t DefaultXpuApi::malloc(void** devPtr, size_t size) {
    if (!devPtr) {
        return XPU_ERROR_INVALID_VALUE;
    }

    if (size == 0) {
        *devPtr = nullptr;
        return XPU_SUCCESS;
    }

    try {
        sycl::context& ctx = ::c10::xpu::get_device_context();
        int devIdx = getCurrentDeviceOrThrow();
        sycl::device& dev = getRawDevice(devIdx);
        *devPtr = sycl::malloc_device(size, dev, ctx);

        if (!*devPtr) {
            return XPU_ERROR_OUT_OF_MEMORY;
        }

        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to allocate " << size << " bytes on XPU: " << e.what();
        return XPU_ERROR_OUT_OF_MEMORY;
    }
}

xpu_result_t DefaultXpuApi::free(void* devPtr) {
    if (!devPtr) {
        return XPU_SUCCESS;
    }

    try {
        sycl::context& ctx = ::c10::xpu::get_device_context();
        sycl::free(devPtr, ctx);
        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to deallocate XPU memory: " << e.what();
        return XPU_ERROR_INVALID_VALUE;
    }
}

xpu_result_t DefaultXpuApi::memcpyAsync(
    void* dst,
    const void* src,
    size_t count,
    const xpuStream_t& stream) {
    if (!dst || !src) {
        return XPU_ERROR_INVALID_VALUE;
    }

    if (count == 0) {
        return XPU_SUCCESS;
    }

    try {
        stream.queue().memcpy(dst, src, count);
        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Asynchronous memcpy failed on XPU: " << e.what();
        return XPU_ERROR_INVALID_VALUE;
    }
}

xpu_result_t DefaultXpuApi::eventCreate(xpuEvent_t& event) {
    try {
        event = ::at::xpu::XPUEvent(false); // Disable timing
        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to create XPU event: " << e.what();
        return XPU_ERROR_INVALID_VALUE;
    }
}

xpu_result_t DefaultXpuApi::eventCreateWithFlags(
    xpuEvent_t& event,
    unsigned int flags) {
    try {
        bool timingEnabled = (flags & 0x1) != 0;
        event = ::at::xpu::XPUEvent(timingEnabled);
        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to create XPU event with flags " << flags << ": " << e.what();
        return XPU_ERROR_INVALID_VALUE;
    }
}

xpu_result_t DefaultXpuApi::eventDestroy([[maybe_unused]] const xpuEvent_t& event) {
    // RAII-managed; no explicit cleanup needed
    return XPU_SUCCESS;
}

xpu_result_t DefaultXpuApi::eventRecord(xpuEvent_t& event, const xpuStream_t& stream) {
    try {
        event.record(stream);
        return XPU_SUCCESS;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to record XPU event: " << e.what();
        return XPU_ERROR_INVALID_HANDLE;
    }
}

xpu_result_t DefaultXpuApi::eventQuery(const xpuEvent_t& event) {
    try {
        bool completed = event.query();
        return completed ? XPU_SUCCESS : XPU_ERROR_NOT_READY;
    } catch (const std::exception& e) {
        TC_LOG(ERROR) << "Failed to query XPU event status: " << e.what();
        return XPU_ERROR_INVALID_HANDLE;
    }
}

