// Error String Mapping
const char* DefaultXpuApi::getErrorString(xpu_result_t err) {
    switch (err) {
        case XPU_SUCCESS:               return "success";
        case XPU_ERROR_INVALID_VALUE:   return "invalid value";
        case XPU_ERROR_NOT_READY:       return "not ready";
        case XPU_ERROR_INVALID_HANDLE:  return "invalid handle";
        case XPU_ERROR_OUT_OF_MEMORY:   return "out of memory";
        case XPU_ERROR_UNSUPPORTED:     return "unsupported feature";
        default:                        return "unknown error";
