struct Operation {
    int left, right, direction;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> arr(n + 1), position(n + 1);
    for (int idx = 1; idx <= n; ++idx) {
        cin >> arr[idx];
        position[arr[idx]] = idx;
    }

    int k = 2;
    vector<Operation> operations;
    operations.reserve(n * n / 2);

    for (int target = 1; target <= n; ++target) {
        int current_pos = position[target];
        while (current_pos > target) {
            // Perform a left shift operation on the segment [current_pos - 1, current_pos]
            operations.push_back({current_pos - 1, current_pos, 0});

            int val1 = arr[current_pos - 1];
            int val2 = arr[current_pos];

            swap(arr[current_pos - 1], arr[current_pos]);
            position[val1] = current_pos;
            position[val2] = current_pos - 1;

            --current_pos;
        }
    }

    cout << k << " " << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.left << " " << op.right << " " << op.direction << "\n";
    }

    return 0;
}

