/* k is chosen so that k*ln2 gives minimal relative error and x - k*ln2 > log(DBL_MIN) */
static const int k = 2043;
static const double kln2 = 0x1.62066151add8bp+10;

/* Computes exp(x)/2 for large x >= log(DBL_MAX), with improved accuracy over 0.5*exp(x/2)^2 */
double __expo2(double x, double sign)
{
	double scale_factor;
	/* k is odd; scale_factor*scale_factor causes overflow intentionally */
	INSERT_WORDS(scale_factor, (uint32_t)(0x3ff + k/2) << 20, 0);

	/* Compute: exp(x - k*ln2) * 2^(k-1) * sign */
	/* Using scale_factor = 2^((k-1)/2), so scale_factor*scale_factor = 2^(k-1) */
	return exp(x - kln2) * (sign * scale_factor) * scale_factor;
}

