#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long L;
    if (!(cin >> N >> L)) return 0;

    vector<long long> T(N);
    for (int i = 0; i < N; ++i) cin >> T[i];

    // Adjust first employee's time for initial week
    vector<long long> adjustedT = T;
    if (adjustedT[0] > 0) adjustedT[0] -= 1;

    const int totalEdges = 2 * N;
    double expectedRatio = (L - 1.0) / totalEdges;

    // Calculate ideal degrees and fractional parts
    vector<int> degree(N, 1);  // minimum 1 for ring structure
    vector<double> remainder(N);

    for (int i = 0; i < N; ++i) {
        double ideal = expectedRatio > 0 ? adjustedT[i] / expectedRatio : 1.0;
        degree[i] = max(1, static_cast<int>(floor(ideal)));
        remainder[i] = ideal - floor(ideal);
    }

    // Adjust degrees to match exact edge count
    int currentSum = accumulate(degree.begin(), degree.end(), 0);
    vector<int> indices(N);
    iota(indices.begin(), indices.end(), 0);

    if (currentSum < totalEdges) {
        sort(indices.begin(), indices.end(), [&](int x, int y) {
            return remainder[x] > remainder[y];
        });

        int diff = totalEdges - currentSum;
        for (int j = 0; j < diff; ++j) {
            degree[indices[j % N]]++;
        }
    } else if (currentSum > totalEdges) {
        sort(indices.begin(), indices.end(), [&](int x, int y) {
            return remainder[x] < remainder[y];
        });

        int diff = currentSum - totalEdges;
        int counter = 0;
        for (int j = 0; j < N && diff > 0; ++j) {
            int idx = indices[j];
            while (diff > 0 && degree[idx] > 1) {
                degree[idx]--;
                diff--;
                counter++;
                if (counter >= N) break;
            }
            if (counter >= N) break;
        }
    }

    // Build base ring structure (each node points to next)
    vector<int> outA(N), outB(N);
    for (int i = 0; i < N; ++i) {
        outA[i] = (i + 1) % N;
    }

    // Calculate additional edges needed beyond ring
    vector<int> extra(N);
    for (int i = 0; i < N; ++i) {
        extra[i] = max(0, degree[i] - 1);
    }

    // Ensure sum of extra equals N
    int extraSum = accumulate(extra.begin(), extra.end(), 0);
    if (extraSum != N) {
        sort(indices.begin(), indices.end(), [&](int x, int y) {
            return T[x] > T[y];
        });

        if (extraSum < N) {
            int needed = N - extraSum;
            for (int j = 0; j < needed; ++j) {
                extra[indices[j % N]]++;
            }
        } else {
            sort(indices.begin(), indices.end(), [&](int x, int y) {
                return T[x] < T[y];
            });

            int excess = extraSum - N;
            for (int j = 0; j < N && excess > 0; ++j) {
                int idx = indices[j];
                while (excess > 0 && extra[idx] > 0) {
                    extra[idx]--;
                    excess--;
                }
            }
        }
    }

    // Assign additional edges
    vector<int> target(N);
    int cursor = 0;
    for (int i = 0; i < N; ++i) {
        // Find next available target with remaining capacity
        while (cursor < N && extra[cursor] == 0) {
            cursor++;
        }
        if (cursor >= N) {
            cursor = 0;
            while (cursor < N && extra[cursor] == 0) {
                cursor++;
            }
        }
        if (cursor < N) {
            target[i] = cursor;
            extra[cursor]--;
        } else {
            target[i] = (i + 1) % N;
        }
    }

    // Output edges
    for (int i = 0; i < N; ++i) {
        cout << outA[i] << " " << target[i] << "\n";
    }

    return 0;
}

