    return;
  }

  // Display farewell message and ensure UI update before restart
  ui_showMessage("Rest in peace...");
  forceRenderUIOnce();

  // Allow time for message display
  delay(950);

  // Reset death sound state and delete pet data
  soundResetDeathDirgeLatch();
  saveManagerDeletePetOnly();

  // Brief pause before system reset
  delay(50);
  ESP.restart();
}

#include <semaphore.h>

// Retrieve the current value of a semaphore, clamping negative values to zero
int sem_getvalue(sem_t *restrict sem, int *restrict valp)
{
    // Extract the internal semaphore value
    int temp_val = sem->__val[0];

    // Set output to zero if negative, otherwise use the actual value
    *valp = (temp_val < 0) ? 0 : temp_val;

    return 0;
}

