class AdvanceSearchTableViewTest : public PlainTestSuite {
  Q_OBJECT
 public:
 private slots:
  void test_1() override {
    // Prepare test data entries
    QList<FsNodeEntry> testEntries{
        {"files 1.txt", false, "henry cavill superman"},
        {"files 2.txt", true,  "Henry Cavill SUPERMAN"},
        {"folder",      true,  ""},
    };

    TDir tempDir;
    QCOMPARE(tempDir.createEntries(testEntries), static_cast<int>(testEntries.size()));
    QString basePath = tempDir.path();
    QVERIFY(QFileInfo(basePath).isDir());

    // Setup models
    AdvanceSearchModel baseModel;
    baseModel.initFilter(QDir::Dirs | QDir::Files | QDir::NoDotAndDotDot);
    baseModel.initIteratorFlag(QDirIterator::Subdirectories);
    baseModel.setRootPath(basePath);

    SearchProxyModel proxyModel;
    proxyModel.initSearchMode(SearchTools::NORMAL);
    proxyModel.initNameFilterDisables(false); // Hide non-matching items
    proxyModel.initFileNameFiltersCaseSensitive(Qt::CaseInsensitive);
    proxyModel.initFileContentsCaseSensitive(Qt::CaseInsensitive);

    AdvanceSearchTableView view{&baseModel, &proxyModel};

    // Apply filter for matching files
    proxyModel.startFilterWhenTextChanged("files", "HENRY");
    QCOMPARE(proxyModel.rowCount(), 2);

    // Test copy/cut with selections
    view.selectAll();
    QModelIndexList selectedNames = view.selectionModel()->selectedRows(0);
    QCOMPARE(selectedNames.size(), 2);

    // Extract MIME data from model
    auto extractedData = MimeDataHelper::GetMimeDataMemberFromSearchModel(baseModel, proxyModel, selectedNames);
    QCOMPARE(extractedData.texts.size(), 2);
    QCOMPARE(extractedData.urls.size(), 2);
    QCOMPARE(extractedData.srcIndexes.size(), 2);

    // Verify expected paths in text list
    QString pathList = extractedData.texts.join('\n');
    QCOMPARE(pathList.count("files 1.txt"), 1);
    QCOMPARE(pathList.count("files 2.txt"), 1);
    QCOMPARE(pathList.count('\n'), 1);

    // Perform CUT operation
    bool cutOk = MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(
        baseModel, extractedData.srcIndexes, Qt::MoveAction);
    QVERIFY(cutOk);
    QVERIFY(!baseModel.mCutIndexes.isEmpty());
    QVERIFY(baseModel.mCopyIndexes.isEmpty());

    // Perform COPY operation
    bool copyOk = MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(
        baseModel, extractedData.srcIndexes, Qt::CopyAction);
    QVERIFY(copyOk);
    QVERIFY(baseModel.mCutIndexes.isEmpty());
    QVERIFY(!baseModel.mCopyIndexes.isEmpty());

    // Try unsupported action (LinkAction)
    bool linkOk = MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(
        baseModel, extractedData.srcIndexes, Qt::LinkAction);
    QVERIFY(!linkOk);
    QVERIFY(baseModel.mCutIndexes.isEmpty());
    QVERIFY(!baseModel.mCopyIndexes.isEmpty());

    // Clear selection and test deletion behavior
    view.clearSelection();

    FileOpActs& trashActInst = FileOpActs::GetInst();
    QSignalSpy trashSpy(trashActInst.MOVE_TO_TRASHBIN, &QAction::triggered);

    // No selection → no trigger
    QKeyEvent pressDel{QEvent::KeyPress, Qt::Key_Delete, Qt::NoModifier, QString(), false, 1};
    view.keyPressEvent(&pressDel);
    QCOMPARE(trashSpy.count(), 0);

    // Select all again → trigger once
    view.selectAll();
    view.keyPressEvent(&pressDel);
    QCOMPARE(trashSpy.count(), 1);
  }
};

