#include <search.h>
#include <string.h>

// Linear search implementation that extends the array if key is not found
void *lsearch(const void *key, void *base, size_t *nelp, size_t width,
	int (*compar)(const void *, const void *)) {

	char* elements = static_cast<char*>(base);
	size_t count = *nelp;

	// Scan through existing elements
	for (size_t idx = 0; idx < count; ++idx) {
		if (compar(key, elements + idx * width) == 0) {
			return elements + idx * width;
		}
	}

	// Key not found - add it to the end
	void* newElement = elements + count * width;
	memcpy(newElement, key, width);
	*nelp = count + 1;
	return newElement;
}

// Linear search implementation that returns null if key is not found
void *lfind(const void *key, const void *base, size_t *nelp,
	size_t width, int (*compar)(const void *, const void *)) {

	const char* elements = static_cast<const char*>(base);
	size_t count = *nelp;

	// Scan through existing elements
	for (size_t idx = 0; idx < count; ++idx) {
		if (compar(key, elements + idx * width) == 0) {
			return const_cast<char*>(elements + idx * width);
		}
	}

	return nullptr;
}

