// Demonstration of const-correct function overloading
struct B {
    void display() {
        cout << "Non-const display()" << endl;
    }
    void display() const {
        cout << "Const display()" << endl;
    }
};

void invokeNonConst(B& instance) {
    instance.display(); // Calls non-const version
}

void invokeConst(const B& instance) {
    instance.display(); // Calls const version
}

int main() {
    B object;
    object.display(); // Non-const display()

    const B constantObject;
    constantObject.display(); // Const display()

    invokeNonConst(object);
    invokeConst(object);

    return 0;
}

