Cursor::Cursor() {
    SetupVertexBuffer();
}

Cursor::~Cursor() {
    if (nullptr != m_cursorVBO) {
        linearFree(m_cursorVBO);
        m_cursorVBO = nullptr;
    }
}

void Cursor::SetupVertexBuffer() {
    constexpr size_t totalVertices = sizeof(cube_sides_lut) / sizeof(WorldVertex);
    m_cursorVBO = static_cast<WorldVertex*>(linearAlloc(sizeof(cube_sides_lut)));
    std::memcpy(m_cursorVBO, cube_sides_lut, sizeof(cube_sides_lut));

    // Initialize all vertex colors to white
    for (size_t idx = 0; idx < totalVertices; ++idx) {
        m_cursorVBO[idx].rgb[0] = 255;
        m_cursorVBO[idx].rgb[1] = 255;
        m_cursorVBO[idx].rgb[2] = 255;
    }
}

void Cursor::Draw(int shaderUniformLoc, C3D_Mtx* viewProj, World* world, mc::Vector3i blockPos, Direction faceToHighlight) {
    // Construct model transformation matrix
    C3D_Mtx modelMatrix;
    Mtx_Identity(&modelMatrix);
    Mtx_Translate(&modelMatrix, blockPos.x, blockPos.y, blockPos.z, true);

    // Compute MVP matrix
    C3D_Mtx combinedMVP;
    Mtx_Multiply(&combinedMVP, viewProj, &modelMatrix);

    // Prepare visible-face vertex buffer region
    WorldVertex* currentVtxPtr = m_cursorVBO;
    size_t activeVertexCount = 0;

    for (int faceIdx = 0; faceIdx < 6; ++faceIdx) {
        const int* delta = DirectionToOffset[faceIdx];
        mc::Vector3i neighborPos{
            blockPos.x + delta[0],
            blockPos.y + delta[1],
            blockPos.z + delta[2]
        };

        if (world->GetBlockID(neighborPos) == BlockID::Air) {
            // Copy base geometry for this face
            std::memcpy(currentVtxPtr, &cube_sides_lut[faceIdx * 6], sizeof(WorldVertex) * 6);

            // Assign brightness based on highlight status
            uint8_t intensity = (faceIdx == faceToHighlight) ? 65u : 32u;
            for (int v = 0; v < 6; ++v) {
                currentVtxPtr[v].rgb[0] = intensity;
                currentVtxPtr[v].rgb[1] = intensity;
                currentVtxPtr[v].rgb[2] = intensity;
            }

            currentVtxPtr += 6;
            activeVertexCount += 6;
        }
    }

    // Upload MVP to shader
    C3D_FVUnifMtx4x4(GPU_VERTEX_SHADER, shaderUniformLoc, &combinedMVP);

    // Configure blending: enable transparency via custom blend factors
    C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD,
                   GPU_ONE, GPU_ONE,
                   GPU_ZERO, GPU_ONE_MINUS_SRC_ALPHA);

    // Adjust depth mapping for cursor rendering
    C3D_DepthMap(true, -1.0f, 0.001f);

    // Set up texture environment (no texture sampling, use vertex color only)
    C3D_TexEnv* texEnv = C3D_GetTexEnv(0);
    C3D_TexEnvInit(texEnv);
    C3D_TexEnvSrc(texEnv, C3D_Both, GPU_PRIMARY_COLOR, GPU_PRIMARY_COLOR, GPU_PRIMARY_COLOR);
    C3D_TexEnvFunc(texEnv, C3D_Both, GPU_REPLACE);

    // Bind vertex buffer
    C3D_BufInfo* bufInfo = C3D_GetBufInfo();
    BufInfo_Init(bufInfo);
    BufInfo_Add(bufInfo, m_cursorVBO, sizeof(WorldVertex), 4, 0x3210);

    // Render geometry
    C3D_DrawArrays(GPU_TRIANGLES, 0, activeVertexCount);

    // Restore previous GPU states
    C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD,
                   GPU_SRC_ALPHA, GPU_ONE_MINUS_SRC_ALPHA,
                   GPU_SRC_ALPHA, GPU_ONE_MINUS_SRC_ALPHA);
    C3D_DepthMap(true, -1.0f, 0.0f);
}

