#include "llvm/TargetParser/SubtargetFeature.h"
#include <algorithm>
#include <cassert>
#include <cstring>
#include <optional>

using namespace llvm;

/// Locate an entry in a sorted array using binary search.
template <typename T>
static const T *locateEntry(StringRef Key, ArrayRef<T> Table) {
  auto It = llvm::lower_bound(Table, Key,
    [](const T &Item, StringRef K) { return StringRef(Item.Key) < K; });

  if (It == Table.end() || StringRef(It->Key) != Key)
    return nullptr;
  return It;
}

/// Propagate feature implications recursively: for each enabled feature, enable all implied features.
static void propagateImpliedFeatures(FeatureBitset &Bits,
                                     const FeatureBitset &DirectImplies,
                                     ArrayRef<SubtargetFeatureKV> FeatureTable) {
  Bits |= DirectImplies;
  for (const SubtargetFeatureKV &Entry : FeatureTable) {
    if (DirectImplies.test(Entry.Value)) {
      propagateImpliedFeatures(Bits, Entry.Implies.getAsBitset(), FeatureTable);
    }
  }
}

/// Revoke features that transitively imply the given feature value.
static void revokeImpliedFeatures(FeatureBitset &Bits, unsigned FeatureValue,
                                  ArrayRef<SubtargetFeatureKV> FeatureTable) {
  for (const SubtargetFeatureKV &Entry : FeatureTable) {
    if (Entry.Implies.getAsBitset().test(FeatureValue)) {
      Bits.reset(Entry.Value);
      revokeImpliedFeatures(Bits, Entry.Value, FeatureTable);
    }
  }
}

/// Apply a single feature flag (+feature or -feature).
static void processFeatureFlag(FeatureBitset &Bits, StringRef RawFeature,
                               ArrayRef<SubtargetFeatureKV> FeatureTable) {
  assert(SubtargetFeatures::hasFlag(RawFeature) &&
         "Feature flags must begin with '+' or '-'");

  StringRef FeatureName = SubtargetFeatures::StripFlag(RawFeature);
  const SubtargetFeatureKV *Match = locateEntry(FeatureName, FeatureTable);

  if (Match) {
    if (SubtargetFeatures::isEnabled(RawFeature)) {
      Bits.set(Match->Value);
      propagateImpliedFeatures(Bits, Match->Implies.getAsBitset(), FeatureTable);
    } else {
      Bits.reset(Match->Value);
      revokeImpliedFeatures(Bits, Match->Value, FeatureTable);
    }
  } else {
    errs() << "'" << RawFeature << "' is not a recognized feature for this target"
           << " (ignoring feature)\n";
  }
}

/// Compute the maximum key length across a table of entries.
template <typename T>
static size_t maxKeyLength(ArrayRef<T> Table) {
  size_t MaxLen = 0;
  for (const auto &Item : Table)
    MaxLen = std::max(MaxLen, std::strlen(Item.Key));
  return MaxLen;
}

/// Print help message listing available CPUs and features.
static void printHelp(ArrayRef<SubtargetSubTypeKV> CPUTable,
                      ArrayRef<SubtargetFeatureKV> FeatureTable) {
  static bool shown = false;
  if (shown) return;

  size_t cpuWidth = maxKeyLength(CPUTable);
  size_t featWidth = maxKeyLength(FeatureTable);

  errs() << "Available CPUs for this target:\n\n";
  for (const auto &CPU : CPUTable)
    errs() << format("  %-*s - Select the %s processor.\n",
                     static_cast<int>(cpuWidth), CPU.Key, CPU.Key);
  errs() << '\n';

  errs() << "Available features for this target:\n\n";
  for (const auto &F : FeatureTable)
    errs() << format("  %-*s - %s.\n",
                     static_cast<int>(featWidth), F.Key, F.Desc);
  errs() << '\n';
  errs() << "Use +feature to enable a feature, or -feature to disable it.\n"
            "Example: llc -mcpu=mycpu -mattr=+feature1,-feature2\n";

  shown = true;
}

/// Print only CPU names when requested via +cpuhelp.
static void printCPUsOnly(ArrayRef<SubtargetSubTypeKV> CPUTable) {
  static bool shown = false;
  if (shown) return;

  errs() << "Available CPUs for this target:\n\n";
  for (const auto &CPU : CPUTable)
    errs() << "\t" << CPU.Key << "\n";
  errs() << '\n';
  errs() << "Use -mcpu or -mtune to specify the target's processor.\n"
            "Example: clang --target=aarch64-unknown-linux-gnu -mcpu=cortex-a35\n";

  shown = true;
}

/// Construct final feature set based on CPU, tune CPU, and feature string.
static FeatureBitset buildFeatureSet(StringRef CPU, StringRef TuneCPU,
                                     StringRef FS,
                                     ArrayRef<SubtargetSubTypeKV> ProcDesc,
                                     ArrayRef<SubtargetFeatureKV> ProcFeatures) {
  SubtargetFeatures parsed(FS);
  if (ProcDesc.empty() || ProcFeatures.empty())
    return FeatureBitset{};

  assert(llvm::is_sorted(ProcDesc) && "CPU table must be sorted");
  assert(llvm::is_sorted(ProcFeatures) && "Feature table must be sorted");

  FeatureBitset result;

  // Handle CPU selection
  if (CPU == "help") {
    printHelp(ProcDesc, ProcFeatures);
  } else if (!CPU.empty()) {
    const SubtargetSubTypeKV *entry = locateEntry(CPU, ProcDesc);
    if (entry) {
      propagateImpliedFeatures(result, entry->Implies.getAsBitset(), ProcFeatures);
    } else {
      errs() << "'" << CPU << "' is not a recognized processor for this target"
             << " (ignoring processor)\n";
    }
  }

  // Handle tune CPU selection
  if (!TuneCPU.empty()) {
    const SubtargetSubTypeKV *entry = locateEntry(TuneCPU, ProcDesc);
    if (entry) {
      propagateImpliedFeatures(result, entry->TuneImplies.getAsBitset(), ProcFeatures);
    } else if (TuneCPU != CPU) {
      errs() << "'" << TuneCPU << "' is not a recognized processor for this "
             << "target (ignoring processor)\n";
    }
  }

  // Process individual feature flags
  for (const std::string &raw : parsed.getFeatures()) {
    if (raw == "+help")
      printHelp(ProcDesc, ProcFeatures);
    else if (raw == "+cpuhelp")
      printCPUsOnly(ProcDesc);
    else
      processFeatureFlag(result, raw, ProcFeatures);
  }

  return result;
}

// Public API implementations
void MCSubtargetInfo::InitMCProcessorInfo(StringRef CPU, StringRef TuneCPU,
                                          StringRef FS) {
  FeatureBits = buildFeatureSet(CPU, TuneCPU, FS, ProcDesc, ProcFeatures);
  FeatureString = std::string(FS);
  CPUSchedModel = !TuneCPU.empty()
                    ? &getSchedModelForCPU(TuneCPU)
                    : &MCSchedModel::Default;
}

void MCSubtargetInfo::setDefaultFeatures(StringRef CPU, StringRef TuneCPU,
                                         StringRef FS) {
  FeatureBits = buildFeatureSet(CPU, TuneCPU, FS, ProcDesc, ProcFeatures);
  FeatureString = std::string(FS);
}

MCSubtargetInfo::MCSubtargetInfo(const Triple &TT, StringRef C, StringRef TC,
                                 StringRef FS, ArrayRef<SubtargetFeatureKV> PF,
                                 ArrayRef<SubtargetSubTypeKV> PD,
                                 const MCWriteProcResEntry *WPR,
                                 const MCWriteLatencyEntry *WL,
                                 const MCReadAdvanceEntry *RA,
                                 const InstrStage *IS, const unsigned *OC,
                                 const unsigned *FP)
    : TargetTriple(TT), CPU(std::string(C)), TuneCPU(std::string(TC)),
      ProcFeatures(PF), ProcDesc(PD), WriteProcResTable(WPR),
      WriteLatencyTable(WL), ReadAdvanceTable(RA), Stages(IS),
      OperandCycles(OC), ForwardingPaths(FP) {
  InitMCProcessorInfo(CPU, TuneCPU, FS);
}

FeatureBitset MCSubtargetInfo::ToggleFeature(uint64_t FB) {
  FeatureBits.flip(FB);
  return FeatureBits;
}

FeatureBitset MCSubtargetInfo::ToggleFeature(const FeatureBitset &FB) {
  FeatureBits ^= FB;
  return FeatureBits;
}

FeatureBitset MCSubtargetInfo::SetFeatureBitsTransitively(
  const FeatureBitset &FB) {
  propagateImpliedFeatures(FeatureBits, FB, ProcFeatures);
  return FeatureBits;
}

FeatureBitset MCSubtargetInfo::ClearFeatureBitsTransitively(
  const FeatureBitset &FB) {
  for (unsigned idx = 0, end = FB.size(); idx < end; ++idx) {
    if (FB[idx]) {
      FeatureBits.reset(idx);
      revokeImpliedFeatures(FeatureBits, idx, ProcFeatures);
    }
  }
  return FeatureBits;
}

FeatureBitset MCSubtargetInfo::ToggleFeature(StringRef Feature) {
  StringRef name = SubtargetFeatures::StripFlag(Feature);
  const SubtargetFeatureKV *entry = locateEntry(name, ProcFeatures);

  if (entry) {
    if (FeatureBits.test(entry->Value)) {
      FeatureBits.reset(entry->Value);
      revokeImpliedFeatures(FeatureBits, entry->Value, ProcFeatures);
    } else {
      FeatureBits.set(entry->Value);
      propagateImpliedFeatures(FeatureBits, entry->Implies.getAsBitset(),
                               ProcFeatures);
    }
  } else {
    errs() << "'" << Feature << "' is not a recognized feature for this target"
           << " (ignoring feature)\n";
  }
  return FeatureBits;
}

FeatureBitset MCSubtargetInfo::ApplyFeatureFlag(StringRef FS) {
  ::processFeatureFlag(FeatureBits, FS, ProcFeatures);
  return FeatureBits;
}

bool MCSubtargetInfo::checkFeatures(StringRef FS) const {
  SubtargetFeatures parsed(FS);
  FeatureBitset required, full;

  for (const std::string &raw : parsed.getFeatures()) {
    ::processFeatureFlag(required, raw, ProcFeatures);
    std::string inverted = raw;
    if (inverted[0] == '-') inverted[0] = '+';
    ::processFeatureFlag(full, inverted, ProcFeatures);
  }

  return (FeatureBits & full) == required;
}

const MCSchedModel &MCSubtargetInfo::getSchedModelForCPU(StringRef CPU) const {
  assert(llvm::is_sorted(ProcDesc) &&
         "Processor model table must be sorted");

  const SubtargetSubTypeKV *entry = locateEntry(CPU, ProcDesc);
  if (!entry) {
    if (CPU != "help")
      errs() << "'" << CPU
             << "' is not a recognized processor for this target"
             << " (ignoring processor)\n";
    return MCSchedModel::Default;
  }

  assert(entry->SchedModel && "Missing scheduling model for CPU");
  return *entry->SchedModel;
}

InstrItineraryData
MCSubtargetInfo::getInstrItineraryForCPU(StringRef CPU) const {
  const MCSchedModel &model = getSchedModelForCPU(CPU);
  return InstrItineraryData(model, Stages, OperandCycles, ForwardingPaths);
}

void MCSubtargetInfo::initInstrItins(InstrItineraryData &out) const {
  out = InstrItineraryData(getSchedModel(), Stages, OperandCycles,
