int main(int argc, char ** argv) {
    registerInteraction(argc, argv);
    std::cout.setf(std::ios::fixed);
    std::cout.precision(20);

    int size = inf.readInt();
    println(size);

    std::vector<int> coeffs_a(size);
    for (int idx = 0; idx < size; ++idx) {
        coeffs_a[idx] = inf.readInt();
    }

    std::vector<int> coeffs_b(size);
    for (int idx = 0; idx < size; ++idx) {
        coeffs_b[idx] = inf.readInt();
    }

    int max_queries = 10000;
    for (int query_count = 0; query_count <= max_queries; ++query_count) {
        std::string action = ouf.readToken();

        if (action == "?") {
            long double x_val = ouf.readDouble();
            if (!std::isfinite(x_val) || x_val < -1e12 || x_val > 1e12) {
                quitf(_wa, "Invalid query: element %.4f is out of range [-1000000000000, 1000000000000]", x_val);
            }

            long double y_val = ouf.readDouble();
            if (!std::isfinite(y_val) || y_val < -1e12 || y_val > 1e12) {
                quitf(_wa, "Invalid query: element %.4f is out of range [-1000000000000, 1000000000000]", y_val);
            }

            long double total_distance = 0.0;
            for (int i = 0; i < size; ++i) {
                long double numerator = std::abs(static_cast<long double>(coeffs_a[i]) * x_val - y_val + coeffs_b[i]);
                long double denominator = std::sqrt(static_cast<long double>(coeffs_a[i]) * coeffs_a[i] + 1.0L);
                total_distance += numerator / denominator;
            }
            std::cout << total_distance << std::endl;
        } 
        else if (action == "!") {
            std::vector<int> guess_a(size);
            for (int i = 0; i < size; ++i) {
                guess_a[i] = ouf.readInt();
            }

            std::vector<int> guess_b(size);
            for (int i = 0; i < size; ++i) {
                guess_b[i] = ouf.readInt();
            }

            std::vector<int> indices(size);
            std::iota(indices.begin(), indices.end(), 0);

            std::sort(indices.begin(), indices.end(), [&](int idx1, int idx2) {
                return std::make_pair(guess_a[idx1], guess_b[idx1]) < 
                       std::make_pair(guess_a[idx2], guess_b[idx2]);
            });

            bool correct = true;
            for (int pos = 0; pos < size; ++pos) {
                if (guess_a[indices[pos]] != coeffs_a[pos] || 
                    guess_b[indices[pos]] != coeffs_b[pos]) {
                    quitp(0.0, "Wrong guess. Ratio: 0.0000");
                }
            }

            double score = 1.0;
            if (query_count > 402) {
                score = 1.0 - 0.7 * (query_count - 402) / (max_queries - 402);
                if (score < 0.0) score = 0.0;
            }

            double unbounded_score = 1.0 - 0.7 * (query_count - 402) / (max_queries - 402);
            if (unbounded_score < 0.0) unbounded_score = 0.0;

            quitp(score, "Correct guess. Ratio: %.4f, RatioUnbounded: %.4f", score, unbounded_score);
        } 
        else {
            quitf(_wa, "Invalid action type: expected ? or !, but got %s", action.c_str());
        }
    }

    quitp(0.0, "Too many queries. Ratio: 0.0000");
    return 0;
}

