PrinterWebViewPanel::PrinterWebViewPanel(wxWindow *parent)
    : wxPanel(parent, wxID_ANY, wxDefaultPosition, wxDefaultSize)
    , m_webview(nullptr)
    , m_webview_created(false)
    , m_needs_initial_refresh(true)
{
    InitializeLayout();
    EnsureWebViewInitialization();
}

PrinterWebViewPanel::~PrinterWebViewPanel()
{
    // WebView cleanup handled automatically via wxWidgets hierarchy
}

void PrinterWebViewPanel::InitializeLayout()
{
    auto vertical_sizer = new wxBoxSizer(wxVERTICAL);
    SetSizer(vertical_sizer);
    m_sizer = vertical_sizer;
}

void PrinterWebViewPanel::EnsureWebViewInitialization()
{
    if (m_webview_created || m_webview != nullptr)
        return;

    m_webview = WebView::webview_new();
    if (m_webview) {
        wxString empty_string = "";
        std::vector<std::string> empty_args{};
        WebView::webview_create(m_webview, this, empty_string, empty_args);
        m_sizer->Add(m_webview, 1, wxEXPAND);
        m_webview_created = true;
        Layout();
    } else {
        BOOST_LOG_TRIVIAL(error) << "PrinterWebViewPanel: Webview creation failed";
    }
}

void PrinterWebViewPanel::LoadURL(const wxString &url)
{
    if (!url.empty() && m_webview) {
        m_current_url = url;
        m_needs_initial_refresh = true;

        wxString secured_url = ComposeAuthenticatedURL(url);
        BOOST_LOG_TRIVIAL(info) << "PrinterWebViewPanel: Initiating navigation to: " << url.ToStdString();
        m_webview->LoadURL(secured_url);
    }
}

wxString PrinterWebViewPanel::ComposeAuthenticatedURL(const wxString &base_url)
{
    if (!m_user.empty() && !m_password.empty()) {
        wxURI uri(base_url);
        wxString scheme = uri.GetScheme();
        if (scheme.IsEmpty()) scheme = "http";

        wxString host = uri.GetServer();
        wxString route = uri.GetPath();
        wxString port_part;
        if (uri.HasPort()) {
            port_part = ":" + uri.GetPortAsString();
        }

        wxString user_decoded = from_u8(m_user);
        wxString pass_decoded = from_u8(m_password);

        return wxString::Format("%s://%s:%s@%s%s%s",
                                scheme, user_decoded, pass_decoded,
                                host, port_part, route);
    }
    return base_url;
}

void PrinterWebViewPanel::SetAPIKey(const std::string &key)
{
    m_api_key = key;
    // Note: wxWebView does not expose global header injection.
    // API keys may be used via query parameters or JS injection in specific cases.
}

void PrinterWebViewPanel::SetCredentials(const std::string &login, const std::string &secret)
{
    m_user = login;
    m_password = secret;
}

void PrinterWebViewPanel::Reload()
{
    if (!m_webview) return;

    if (!m_current_url.empty()) {
        LoadURL(m_current_url);
    } else {
        m_webview->Reload();
    }
}

bool PrinterWebViewPanel::IsLoaded() const
{
    return m_webview_created && (m_webview != nullptr);
}

wxString PrinterWebViewPanel::GetCurrentURL() const
{
    return m_current_url;
}

void PrinterWebViewPanel::OnBecameVisible()
{
    if (m_needs_initial_refresh && m_webview && !m_current_url.empty()) {
        m_needs_initial_refresh = false;

        CallAfter([this]() {
            if (m_webview && !m_current_url.empty()) {
                wxString authenticated = ComposeAuthenticatedURL(m_current_url);
                m_webview->LoadURL(authenticated);
            }
        });
    }
}

void PrinterWebViewPanel::sys_color_changed()
{
    // WebView rendering adapts dynamically based on system theme changes
    // No explicit action required here
}

