    // Prepare XPath variables for conditional node selection
    pugi::xpath_variable_set variableSet;
    variableSet.add("remote", pugi::xpath_type_boolean);

    // Compile XPath expression using the boolean variable
    pugi::xpath_query query("/Profile/Tools/Tool[@AllowRemote = string($remote)]", &variableSet);

    // Evaluate with remote=true
    variableSet.set("remote", true);
    pugi::xpath_node_set remoteTools = query.evaluate_node_set(doc);

    // Evaluate with remote=false
    variableSet.set("remote", false);
    pugi::xpath_node_set localTools = query.evaluate_node_set(doc);

    // Output specific nodes from each set
    std::cout << "Remote tool: ";
    remoteTools[2].node().print(std::cout);
    std::cout << "\nLocal tool: ";
    localTools[0].node().print(std::cout);

    // Alternative direct usage of select_nodes with context and variables
    pugi::xpath_node_set immediateLocalTools = doc.select_nodes(
        "/Profile/Tools/Tool[@AllowRemote = string($remote)]", 
        &variableSet
    );

    std::cout << "\nLocal tool imm: ";
    immediateLocalTools[0].node().print(std::cout);
    std::cout << std::endl;

    return 0;
}

