#include "llvm/ADT/DAGDeltaAlgorithm.h"
#include "llvm/ADT/DeltaAlgorithm.h"
#include "llvm/Support/Debug.h"
#include "llvm/Support/Format.h"
#include "llvm/Support/raw_ostream.h"
#include <algorithm>
#include <cassert>
#include <map>
#include <set>
#include <vector>

using namespace llvm;

#define DEBUG_TYPE "dag-delta-alt"

namespace {

class DAGDeltaAlgorithmImpl {
  friend class DeltaActiveSetHelper;
public:
  using ChangeID = DAGDeltaAlgorithm::change_ty;
  using ChangeSet = DAGDeltaAlgorithm::changeset_ty;
  using ChangeListSet = DAGDeltaAlgorithm::changesetlist_ty;
  using Edge = DAGDeltaAlgorithm::edge_ty;

private:
  using NodeVec = std::vector<ChangeID>;
  using NodeSet = std::set<ChangeID>;
  using NodeMapVec = std::map<ChangeID, NodeVec>;
  using NodeMapSet = std::map<ChangeID, NodeSet>;

  DAGDeltaAlgorithm &ParentDDA;
  NodeVec RootNodes;
  mutable NodeSet CachedFailures;
  NodeMapVec PredecessorLists;
  NodeMapVec SuccessorLists;
  NodeMapSet PredClosureMap;
  NodeMapSet SuccClosureMap;

  // Helper: get predecessor list begin/end iterators
  auto pred_begin(ChangeID node) -> typename NodeVec::iterator {
    assert(PredecessorLists.count(node));
    return PredecessorLists[node].begin();
  }

  auto pred_end(ChangeID node) -> typename NodeVec::iterator {
    assert(PredecessorLists.count(node));
    return PredecessorLists[node].end();
  }

  auto pred_closure_begin(ChangeID node) -> typename NodeSet::iterator {
    assert(PredClosureMap.count(node));
    return PredClosureMap[node].begin();
  }

  auto pred_closure_end(ChangeID node) -> typename NodeSet::iterator {
    assert(PredClosureMap.count(node));
    return PredClosureMap[node].end();
  }

  auto succ_begin(ChangeID node) -> typename NodeVec::iterator {
    assert(SuccessorLists.count(node));
    return SuccessorLists[node].begin();
  }

  auto succ_end(ChangeID node) -> typename NodeVec::iterator {
    assert(SuccessorLists.count(node));
    return SuccessorLists[node].end();
  }

  auto succ_closure_begin(ChangeID node) -> typename NodeSet::iterator {
    assert(SuccClosureMap.count(node));
    return SuccClosureMap[node].begin();
  }

  auto succ_closure_end(ChangeID node) -> typename NodeSet::iterator {
    assert(SuccClosureMap.count(node));
    return SuccClosureMap[node].end();
  }

  void NotifySearchStateUpdate(const ChangeSet& active,
                               const ChangeListSet& partitions,
                               const ChangeSet& mandatory) {
    ParentDDA.UpdatedSearchState(active, partitions, mandatory);
  }

  bool EvaluateTest(const ChangeSet& candidate) const {
    LLVM_DEBUG({
      for (auto id : candidate) {
        for (auto dependent : SuccessorLists.at(id)) {
          assert(candidate.count(dependent) && "Invalid changeset dependency!");
        }
      }
    });
    return ParentDDA.ExecuteOneTest(candidate);
  }

public:
  DAGDeltaAlgorithmImpl(DAGDeltaAlgorithm& parent,
                        const ChangeSet& initial,
                        const std::vector<Edge>& deps);

  ChangeSet ExecuteMinimization();

  bool QueryCachedResult(const ChangeSet& active, const ChangeSet& mandatory) const;
};

// Helper class for minimizing an active subset under required constraints
class DeltaActiveSetHelper : public DeltaAlgorithm {
  DAGDeltaAlgorithmImpl& ImplRef;
  const ChangeSet& MandatorySet;

protected:
  void UpdatedSearchState(const ChangeSet& active,
                          const ChangeListSet& partitions) override {
    ImplRef.NotifySearchStateUpdate(active, partitions, MandatorySet);
  }

  bool ExecuteOneTest(const ChangeSet& S) override {
    return ImplRef.QueryCachedResult(S, MandatorySet);
  }

public:
  DeltaActiveSetHelper(DAGDeltaAlgorithmImpl& impl, const ChangeSet& req)
      : DeltaAlgorithm(), ImplRef(impl), MandatorySet(req) {}
};

} // anonymous namespace

DAGDeltaAlgorithmImpl::DAGDeltaAlgorithmImpl(
    DAGDeltaAlgorithm& parent,
    const ChangeSet& initial,
    const std::vector<Edge>& deps)
    : ParentDDA(parent) {

  // Initialize empty lists/closures for each node
  for (auto node : initial) {
    PredecessorLists.emplace(node, NodeVec{});
    SuccessorLists.emplace(node, NodeVec{});
  }

  // Populate adjacency info from dependencies
  for (const auto& dep : deps) {
    PredecessorLists[dep.second].push_back(dep.first);
    SuccessorLists[dep.first].push_back(dep.second);
  }

  // Identify roots: nodes with no successors
  for (auto node : initial) {
    if (SuccessorLists[node].empty()) {
      RootNodes.push_back(node);
    }
  }

  // Compute successor closures via BFS from roots
  NodeVec worklist(RootNodes.begin(), RootNodes.end());
  while (!worklist.empty()) {
    auto current = worklist.back();
    worklist.pop_back();
    auto& curSuccs = SuccClosureMap[current];

    for (auto pred : PredecessorLists[current]) {
      auto& predSuccs = SuccClosureMap[pred];
      predSuccs.insert(current);
      predSuccs.insert(curSuccs.begin(), curSuccs.end());
      worklist.push_back(pred);
    }
  }

  // Build predecessor closures by transposing successor closures
  for (auto node : initial) {
    PredClosureMap.emplace(node, NodeSet{});
  }
  for (auto node : initial) {
    for (auto succ : SuccClosureMap[node]) {
      PredClosureMap[succ].insert(node);
    }
  }

  // Debug dump (refactored into lambda for clarity)
  LLVM_DEBUG({
    auto printSet = [](const ChangeSet& s) {
      llvm::errs() << "[";
      bool first = true;
      for (auto x : s) {
        if (!first) llvm::errs() << ", ";
        first = false;
        llvm::errs() << x;
      }
      llvm::errs() << "]";
    };

    llvm::errs() << "-- DAGDeltaAlgorithmImpl (alt) --\n";
    llvm::errs() << "Initial Nodes: ";
    printSet(initial);
    llvm::errs() << "\nRoots: ";
    printSet({RootNodes.begin(), RootNodes.end()});
    llvm::errs() << "\nPredecessor Closures:\n";
    for (auto node : initial) {
      llvm::errs() << format("  %-4d: [", node);
      bool first = true;
      for (auto p : PredClosureMap[node]) {
        if (!first) llvm::errs() << ", ";
        first = false;
        llvm::errs() << p;
      }
      llvm::errs() << "]\n";
    }
    llvm::errs() << "Successor Closures:\n";
    for (auto node : initial) {
      llvm::errs() << format("  %-4d: [", node);
      bool first = true;
      for (auto s : SuccClosureMap[node]) {
        if (!first) llvm::errs() << ", ";
        first = false;
        llvm::errs() << s;
      }
      llvm::errs() << "]\n";
    }
    llvm::errs() << "\n\n";
  });
}

bool DAGDeltaAlgorithmImpl::QueryCachedResult(const ChangeSet& active,
                                              const ChangeSet& mandatory) const {
  ChangeSet extended(mandatory);
  extended.insert(active.begin(), active.end());

  for (auto id : active) {
    extended.insert(PredClosureMap[id].begin(), PredClosureMap[id].end());
  }

  if (CachedFailures.count(extended)) {
    return false;
  }

  bool success = EvaluateTest(extended);
  if (!success) {
    CachedFailures.insert(extended);
  }

  return success;
}

DAGDeltaAlgorithm::changeset_ty
DAGDeltaAlgorithmImpl::ExecuteMinimization() {
  ChangeSet activeSet(RootNodes.begin(), RootNodes.end());
  ChangeSet requiredSet;

  while (!activeSet.empty()) {
    LLVM_DEBUG({
      llvm::errs() << "DAG_DD - " << activeSet.size()
                   << " active, " << requiredSet.size() << " required\n";
    });

    DeltaActiveSetHelper helper(*this, requiredSet);
    ChangeSet minimized = helper.Run(activeSet);

    requiredSet.insert(minimized.begin(), minimized.end());

    activeSet.clear();
    for (auto node : minimized) {
      std::copy(pred_begin(node), pred_end(node),
                std::inserter(activeSet, activeSet.end()));
    }
  }

  return requiredSet;
}

void DAGDeltaAlgorithm::anchor() {}

DAGDeltaAlgorithm::changeset_ty
DAGDeltaAlgorithm::Run(const changeset_ty& changes,
                       const std::vector<edge_ty>& deps) {
  return DAGDeltaAlgorithmImpl(*this, changes, deps).ExecuteMinimization();
}

