// Helper function to verify person count matches expected value (8)
static void confirmPersonCountStar(Connection* conn) {
    auto queryResult = conn->query("MATCH (a:person) RETURN COUNT(*)");
    ASSERT_TRUE(queryResult->hasNext());
    auto record = queryResult->getNext();
    ASSERT_EQ(record->getValue(0)->getValue<int64_t>(), 8);
    ASSERT_FALSE(queryResult->hasNext());
}

