// Execute long-running query that should be interrupted
static void initiateLongRunningOperation(Connection* conn) {
    auto result = conn->query(
        "UNWIND RANGE(1,100000) AS x UNWIND RANGE(1, 100000) AS y RETURN COUNT(x + y);");
    ASSERT_FALSE(result->isSuccess());
    ASSERT_EQ(result->getErrorMessage(), "Interrupted.");
}

TEST_F(ApiTest, Interrupt) {
    std::thread longRunningThread(initiateLongRunningOperation, conn.get());
    std::atomic<bool> operationCompleted{false};

    std::thread interruptionThread([&]() {
        while (!operationCompleted) {
#ifdef _WIN32
            Sleep(1000);
#else
            sleep(1 /* wait 1 second before interrupting the query */);
#endif
            conn->interrupt();
        }
    });

    longRunningThread.join();
    operationCompleted = true;
    interruptionThread.join();
}
#endif

