#include <iostream>
#include <vector>
using namespace std;

// Represents a segment [L, R] that may contain 'k' candidates
// 'leftCount' tracks how many candidates exist strictly before L (i.e., in [0, L-1])
struct Segment {
    int leftBound;
    int rightBound;
    int candidateCount;
    int leftCount;
};

void reportAnswer(int pos) {
    cout << "! " << pos << endl;
    exit(0);
}

pair<int, int> makeQuery(int position) {
    cout << "? " << position << endl;
    int leftCandidates, rightCandidates;
    if (!(cin >> leftCandidates >> rightCandidates)) {
        exit(0);
    }
    return {leftCandidates, rightCandidates};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    int minTotal = 2e9;
    vector<Segment> segments;

    // Start with middle position
    int mid = (n - 1) / 2;
    auto result = makeQuery(mid);
    int total = result.first + result.second;

    if (total == 0) {
        reportAnswer(mid);
    }

    minTotal = total;

    // Initialize segments based on first query
    if (result.first > 0) {
        segments.push_back({0, mid - 1, result.first, 0});
    }
    if (result.second > 0) {
        segments.push_back({mid + 1, n - 1, result.second, result.first});
    }

    while (!segments.empty()) {
        Segment current = segments.back();
        segments.pop_back();

        if (current.leftBound > current.rightBound) continue;

        int center = (current.leftBound + current.rightBound) / 2;
        auto queryResult = makeQuery(center);
        int currentTotal = queryResult.first + queryResult.second;

        if (currentTotal == 0) {
            reportAnswer(center);
        }

        if (currentTotal < minTotal) {
            minTotal = currentTotal;
            segments.clear();

            // Reset search to focus on better candidates around this new best
            if (queryResult.first > 0) {
                segments.push_back({0, center - 1, queryResult.first, 0});
            }
            if (queryResult.second > 0) {
                segments.push_back({center + 1, n - 1, queryResult.second, queryResult.first});
            }
        } else {
            // Current position is not better; refine the search space

            // Count of candidates in [L, center-1]
            int leftInSegment = queryResult.first - current.leftCount;

            // Remaining candidates must be in [center+1, R]
            int rightInSegment = current.candidateCount - leftInSegment;

            if (leftInSegment > 0) {
                segments.push_back({current.leftBound, center - 1, leftInSegment, current.leftCount});
            }
            if (rightInSegment > 0) {
                // Offset for right part: all candidates up to center-1
                segments.push_back({center + 1, current.rightBound, rightInSegment, queryResult.first});
            }
        }
    }

    return 0;
}

