HRESULT CScene_SettingsAll::OnInit(XUIMessageInit* pInitData, BOOL& bHandled)
{
    int controllerIndex = *(int*)pInitData->pvInitData;
    bool isLevelNull = (Minecraft::GetInstance()->level == nullptr);

    m_iPad = controllerIndex;
    MapChildControls();

    // Set button labels using localized strings
    XuiControlSetText(m_Buttons[BUTTON_ALL_OPTIONS], app.GetString(IDS_OPTIONS));
    XuiControlSetText(m_Buttons[BUTTON_ALL_AUDIO], app.GetString(IDS_AUDIO));
    XuiControlSetText(m_Buttons[BUTTON_ALL_CONTROL], app.GetString(IDS_CONTROL));
    XuiControlSetText(m_Buttons[BUTTON_ALL_GRAPHICS], app.GetString(IDS_GRAPHICS));
    XuiControlSetText(m_Buttons[BUTTON_ALL_UI], app.GetString(IDS_USER_INTERFACE));
    XuiControlSetText(m_Buttons[BUTTON_ALL_RESETTODEFAULTS], app.GetString(IDS_RESET_TO_DEFAULTS));

    // Adjust UI layout if primary pad differs from current controller index
    if (ProfileManager.GetPrimaryPad() != controllerIndex)
    {
        D3DXVECTOR3 posTemp1, posTemp2;
        m_Buttons[BUTTON_ALL_AUDIO].SetShow(FALSE);
        m_Buttons[BUTTON_ALL_AUDIO].SetEnable(FALSE);
        m_Buttons[BUTTON_ALL_GRAPHICS].SetShow(FALSE);
        m_Buttons[BUTTON_ALL_GRAPHICS].SetEnable(FALSE);

        float btnWidth, btnHeight;
        m_Buttons[BUTTON_ALL_GRAPHICS].GetPosition(&posTemp1);
        m_Buttons[BUTTON_ALL_RESETTODEFAULTS].GetBounds(&btnWidth, &btnHeight);
        m_Buttons[BUTTON_ALL_RESETTODEFAULTS].SetPosition(&posTemp1);

        m_Buttons[BUTTON_ALL_CONTROL].GetPosition(&posTemp2);
        m_Buttons[BUTTON_ALL_UI].SetPosition(&posTemp2);

        m_Buttons[BUTTON_ALL_AUDIO].GetPosition(&posTemp1);
        m_Buttons[BUTTON_ALL_CONTROL].SetPosition(&posTemp1);

        // Resize scene vertically based on new positions
        float sceneWidth, sceneHeight;
        GetBounds(&sceneWidth, &sceneHeight);
        SetBounds(sceneWidth, posTemp1.y + btnHeight);
    }

    // Configure tooltips and background/logo visibility depending on game state
    if (isLevelNull)
    {
        ui.SetTooltips(DEFAULT_XUI_MENU_USER, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
        CXuiSceneBase::ShowBackground(DEFAULT_XUI_MENU_USER, TRUE);
    }
    else
    {
        ui.SetTooltips(controllerIndex, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
        CXuiSceneBase::ShowBackground(controllerIndex, FALSE);
    }

    // Handle splitscreen vs single-player scenarios
    if (app.GetLocalPlayerCount() > 1)
    {
        app.AdjustSplitscreenScene(m_hObj, &m_OriginalPosition, controllerIndex, false);
        CXuiSceneBase::ShowLogo(controllerIndex, FALSE);
    }
    else
    {
        if (isLevelNull)
        {
            CXuiSceneBase::ShowLogo(DEFAULT_XUI_MENU_USER, TRUE);
        }
        else
        {
            CXuiSceneBase::ShowLogo(controllerIndex, TRUE);
        }
    }

    return S_OK;
}

