HRESULT CScene_SettingsAll::OnNotifyPressEx(HXUIOBJ hObjPressed, XUINotifyPress* pNotifyData, BOOL& rfHandled)
{
    ui.AnimateKeyPress(pNotifyData->UserIndex, VK_PAD_A);

    unsigned int btnIdx = 0;
    for (; btnIdx < BUTTONS_ALL_MAX; ++btnIdx)
    {
        if (m_Buttons[btnIdx] == hObjPressed)
            break;
    }

    switch (btnIdx)
    {
    case BUTTON_ALL_OPTIONS:
        app.NavigateToScene(pNotifyData->UserIndex, eUIScene_SettingsOptionsMenu);
        break;
    case BUTTON_ALL_AUDIO:
        app.NavigateToScene(pNotifyData->UserIndex, eUIScene_SettingsAudioMenu);
        break;
    case BUTTON_ALL_CONTROL:
        app.NavigateToScene(pNotifyData->UserIndex, eUIScene_SettingsControlMenu);
        break;
    case BUTTON_ALL_GRAPHICS:
        app.NavigateToScene(pNotifyData->UserIndex, eUIScene_SettingsGraphicsMenu);
        break;
    case BUTTON_ALL_UI:
        app.NavigateToScene(pNotifyData->UserIndex, eUIScene_SettingsUIMenu);
        break;
    case BUTTON_ALL_RESETTODEFAULTS:
        {
            UINT msgIds[2];
            msgIds[0] = IDS_CONFIRM_CANCEL;
            msgIds[1] = IDS_CONFIRM_OK;
            StorageManager.RequestMessageBox(
                IDS_DEFAULTS_TITLE,
                IDS_DEFAULTS_TEXT,
                msgIds,
                2,
                pNotifyData->UserIndex,
                &CScene_SettingsAll::ResetDefaultsDialogReturned,
                this,
                app.GetStringTable()
            );
        }
        break;
    }

    rfHandled = TRUE;
    return S_OK;
}

