#include "test_def.h"
#include "lwip/def.h"

#define MAGIC_UNTOUCHED_BYTE  0x7a
#define TEST_BUFSIZE          32
#define GUARD_SIZE            4

/* Setup and teardown functions */
static void
def_setup(void)
{
}

static void
def_teardown(void)
{
}

/* Verify that a memory region remains unchanged (filled with MAGIC_UNTOUCHED_BYTE) */
static void
def_check_range_untouched(const char *buf, size_t len)
{
  for (size_t idx = 0; idx < len; ++idx) {
    fail_unless(buf[idx] == static_cast<char>(MAGIC_UNTOUCHED_BYTE));
  }
}

/* Helper function to test lwip_itoa with various inputs */
static void
test_def_itoa(int value, const char *expected_str)
{
  char buffer[TEST_BUFSIZE];
  char *test_area = &buffer[GUARD_SIZE];
  size_t expected_length = strlen(expected_str);

  /* Ensure buffer is large enough for testing */
  fail_unless(expected_length + 4 < (TEST_BUFSIZE - (2 * GUARD_SIZE)));

  /* Initialize guard regions */
  memset(buffer, MAGIC_UNTOUCHED_BYTE, sizeof(buffer));

  /* Test normal case */
  lwip_itoa(test_area, expected_length + 1, value);
  def_check_range_untouched(buffer, GUARD_SIZE);
  fail_unless(test_area[expected_length] == '\0');
  fail_unless(memcmp(test_area, expected_str, expected_length) == 0);
  def_check_range_untouched(&test_area[expected_length + 1],
                            TEST_BUFSIZE - GUARD_SIZE - expected_length - 1);

  /* Test with undersized buffer */
  memset(buffer, MAGIC_UNTOUCHED_BYTE, sizeof(buffer));
  lwip_itoa(test_area, expected_length, value);
  def_check_range_untouched(buffer, GUARD_SIZE);
  def_check_range_untouched(&test_area[expected_length + 1],
                            TEST_BUFSIZE - GUARD_SIZE - expected_length - 1);

  /* Test with oversized buffer */
  memset(buffer, MAGIC_UNTOUCHED_BYTE, sizeof(buffer));
  lwip_itoa(test_area, expected_length + 4, value);
  def_check_range_untouched(buffer, GUARD_SIZE);
  fail_unless(test_area[expected_length] == '\0');
  fail_unless(memcmp(test_area, expected_str, expected_length) == 0);
  def_check_range_untouched(&test_area[expected_length + 4],
                            TEST_BUFSIZE - GUARD_SIZE - expected_length - 4);
}

/* Main test function for integer-to-string conversion */
START_TEST(test_def_lwip_itoa)
{
  LWIP_UNUSED_ARG(_i);
  test_def_itoa(0, "0");
  test_def_itoa(1, "1");
  test_def_itoa(-1, "-1");
  test_def_itoa(15, "15");
  test_def_itoa(-15, "-15");
  test_def_itoa(156, "156");
  test_def_itoa(1192, "1192");
  test_def_itoa(-156, "-156");
}
END_TEST

/* Build the test suite */
Suite *
def_suite(void)
{
  testfunc test_cases[] = {
    TESTFUNC(test_def_lwip_itoa)
  };
  return create_suite("DEF", test_cases,
                      sizeof(test_cases) / sizeof(testfunc),
                      def_setup, def_teardown);
}

#include <cassert>
#include <cmath>   // for HUGE_VAL
#include <iomanip> // for std::setprecision()
#include <iostream>
#include "proj/coordinateoperation.hpp"
#include "proj/crs.hpp"
#include "proj/io.hpp"
#include "proj/util.hpp" // for nn_dynamic_pointer_cast

using namespace NS_PROJ::crs;
using namespace NS_PROJ::io;
using namespace NS_PROJ::operation;
using namespace NS_PROJ::util;

int main(void) {
    // Initialize database context and factory setup
    auto dbCtx = DatabaseContext::create();
    auto authFactory = AuthorityFactory::create(dbCtx, std::string());

    // Configure coordinate operation context with default parameters
    auto opContext = CoordinateOperationContext::create(authFactory, nullptr, 0.0);

    // Set up EPSG-specific authority factory
    auto epsgFactory = AuthorityFactory::create(dbCtx, "EPSG");

    // Load source CRS using EPSG:4326 (WGS84 geographic coordinates)
    auto srcCRS = epsgFactory->createCoordinateReferenceSystem("4326");

    // Define target CRS via PROJ string instead of EPSG code
    auto dstCRS = NN_CHECK_THROW(nn_dynamic_pointer_cast<CRS>(
        createFromUserInput("+proj=utm +zone=31 +datum=WGS84 +type=crs", dbCtx)));

    // Generate list of possible transformations between the two CRS
    auto opsList = CoordinateOperationFactory::create()->createOperations(
        srcCRS, dstCRS, opContext);

    // Ensure at least one valid transformation exists
    assert(!opsList.empty());

    // Create thread-safe execution environment for transformation
    PJ_CONTEXT *threadCtx = proj_context_create();

    // Build transformer from the top-ranked operation
    auto transformOp = opsList[0]->coordinateTransformer(threadCtx);

    // Define input coordinates: latitude=49°, longitude=2°
    PJ_COORD inputCoord = {{
        49.0,    // latitude (degrees)
        2.0,     // longitude (degrees)
        0.0,     // z-coordinate (unused)
        HUGE_VAL // time (unused)
    }};

    // Apply transformation
    PJ_COORD result = transformOp->transform(inputCoord);

    // Output transformed UTM coordinates with fixed precision
    std::cout << std::fixed << std::setprecision(3);
    std::cout << "Easting: " << result.v[0] << std::endl;   // Expected: ~426857.988
    std::cout << "Northing: " << result.v[1] << std::endl;  // Expected: ~5427937.523

    // Cleanup resources
    proj_context_destroy(threadCtx);
    return 0;
}

