// Calculate SHA-512/256 hash using a simplified approach
int main() {
    // Initialize hash values similar to FIPS 180-4 section 5.3.6.2
    unsigned long long hash[8] = {
        0x22312194FC2BF72CULL,
        0x9F555FA3C84C64C2ULL,
        0x2393B86B6F53B151ULL,
        0x963877195940EABDULL,
        0x96283EE2A88EFFE3ULL,
        0xBE5E1E2553863992ULL,
        0x2B0199FC2C85B8AAULL,
        0x0EB72DDC81C52CA2ULL
    };

    // Process input data (simulated as "Hello, World!" for demonstration)
    const char* input = "Hello, World!";
    size_t input_len = strlen(input);

    // Create message schedule array
    unsigned long long W[80];
    unsigned int t;

    // Initialize first 16 words of W from input
    for (t = 0; t < 16 && t * 8 < input_len; t++) {
        W[t] = 0;
        for (int i = 0; i < 8 && (t * 8 + i) < input_len; i++) {
            W[t] |= ((unsigned long long)(unsigned char)input[t * 8 + i]) << (56 - i * 8);
        }
    }

    // Pad message according to SHA-512/256 specification
    if (t * 8 < input_len) {
        // Handle remaining bytes
        W[t] = 0;
        int remaining = input_len - t * 8;
        for (int i = 0; i < remaining; i++) {
            W[t] |= ((unsigned long long)(unsigned char)input[t * 8 + i]) << (56 - i * 8);
        }
        W[t] |= 0x80ULL << (56 - remaining * 8);
        t++;

        // Fill with zeros until length field
        while (t < 14) {
            W[t++] = 0;
        }
    } else {
        // Add padding bit
        W[t] = 0x80ULL << (56);
        t++;

        // Fill with zeros until length field
        while (t < 14) {
            W[t++] = 0;
        }
    }

    // Append length in bits
    unsigned long long bit_length = input_len * 8;
    W[14] = bit_length >> 32;
    W[15] = bit_length & 0xFFFFFFFFULL;

    // SHA-512/256 constants
    const unsigned long long K[80] = {
        0x428a2f98d728ae22ULL, 0x7137449123ef65cdULL, 0xb5c0fbcfec4d3b2fULL, 0xe9b5dba58189dbbcULL,
        0x3956c25bf348b538ULL, 0x59f111f1b605d019ULL, 0x923f82a4af194f9bULL, 0xab1c5ed5da6d8118ULL,
        0xd807aa98a3030242ULL, 0x12835b0145706fbeULL, 0x243185be4ee4b28cULL, 0x550c7dc3d5ffb4e2ULL,
        0x72be5d74f27b896fULL, 0x80deb1fe3b1696b1ULL, 0x9bdc06a725c71235ULL, 0xc19bf174cf692694ULL,
        0xe49b69c19ef14ad2ULL, 0xefbe4786384f25e3ULL, 0x0fc19dc68b8cd5b5ULL, 0x240ca1cc77ac9c65ULL,
        0x2de92c6f592b0275ULL, 0x4a7484aa6ea6e483ULL, 0x5cb0a9dcbd41fbd4ULL, 0x76f988da831153b5ULL,
        0x983e5152ee66dfabULL, 0xa831c66d2db43210ULL, 0xb00327c898fb213fULL, 0xbf597fc7beef0ee4ULL,
        0xc6e00bf33da88fc2ULL, 0xd5a79147930aa725ULL, 0x06ca6351e003826fULL, 0x142929670a0e6e70ULL,
        0x27b70a8546d22ffcULL, 0x2e1b21385c26c926ULL, 0x4d2c6dfc5ac42aedULL, 0x53380d139d95b3dfULL,
        0x650a73548baf63deULL, 0x766a0abb3c77b2a8ULL, 0x81c2c92e47edaee6ULL, 0x92722c851482353bULL,
        0xa2bfe8a14cf10364ULL, 0xa81a664bbc423001ULL, 0xc24b8b70d0f89791ULL, 0xc76c51a30654be30ULL,
        0xd192e819d6ef5218ULL, 0xd69906245565a910ULL, 0xf40e35855771202aULL, 0x106aa07032bbd1b8ULL,
        0x19a4c116b8d2d0c8ULL, 0x1e376c085141ab53ULL, 0x2748774cdf8eeb99ULL, 0x34b0bcb5e19b48a8ULL,
        0x391c0cb3c5c95a63ULL, 0x4ed8aa4ae3418acbULL, 0x5b9cca4f7763e373ULL, 0x682e6ff3d6b2b8a3ULL,
        0x748f82ee5defb2fcULL, 0x78a5636f43172f60ULL, 0x84c87814a1f0ab72ULL, 0x8cc702081a6439ecULL,
        0x90befffa23631e28ULL, 0xa4506cebde82bde9ULL, 0xbef9a3f7b2c67915ULL, 0xc67178f2e372532bULL,
        0xca273eceea26619cULL, 0xd186b8c721c0c207ULL, 0xeada7dd6cde0eb1eULL, 0xf57d4f7fee6ed178ULL,
        0x06f067aa72176fbaULL, 0x0a637dc5a2c898a6ULL, 0x113f9804bef90daeULL, 0x1b710b35131c471bULL,
        0x28db77f523047d84ULL, 0x32caab7b40c72493ULL, 0x3c9ebe0a15c9bebcULL, 0x431d67c49c100d4cULL,
        0x4cc5d4becb3e42b6ULL, 0x597f299cfc657e2aULL, 0x5fcb6fab3ad6faecULL, 0x6c44198c4a475817ULL
    };

    // Working variables
    unsigned long long a = hash[0], b = hash[1], c = hash[2], d = hash[3];
    unsigned long long e = hash[4], f = hash[5], g = hash[6], h = hash[7];

    // Main compression function
    for (t = 0; t < 80; t++) {
        // Helper macros for SHA-512 operations
        auto rotr64 = [](unsigned long long x, unsigned int n) -> unsigned long long {
            n %= 64;
            return (x >> n) | (x << (64 - n));
        };

        auto ch = [](unsigned long long x, unsigned long long y, unsigned long long z) -> unsigned long long {
            return (z ^ (x & (y ^ z)));
        };

        auto maj = [](unsigned long long x, unsigned long long y, unsigned long long z) -> unsigned long long {
            return ((x & y) ^ (z & (x ^ y)));
        };

        auto sigma0 = [&](unsigned long long x) { return rotr64(x, 28) ^ rotr64(x, 34) ^ rotr64(x, 39); };
        auto sigma1 = [&](unsigned long long x) { return rotr64(x, 14) ^ rotr64(x, 18) ^ rotr64(x, 41); };
        auto small_sigma0 = [&](unsigned long long x) { return rotr64(x, 1) ^ rotr64(x, 8) ^ (x >> 7); };
        auto small_sigma1 = [&](unsigned long long x) { return rotr64(x, 19) ^ rotr64(x, 61) ^ (x >> 6); };

        // Compute message schedule if needed
        if (t >= 16) {
            W[t] = small_sigma1(W[t-2]) + W[t-7] + small_sigma0(W[t-15]) + W[t-16];
        }

        // Temporary values
        unsigned long long T1 = h + sigma1(e) + ch(e, f, g) + K[t] + W[t];
        unsigned long long T2 = sigma0(a) + maj(a, b, c);

        // Update working variables
        h = g;
        g = f;
        f = e;
        e = d + T1;
        d = c;
        c = b;
        b = a;
        a = T1 + T2;
    }

    // Add compressed chunk to hash
    hash[0] += a;
    hash[1] += b;
    hash[2] += c;
    hash[3] += d;
    hash[4] += e;
    hash[5] += f;
    hash[6] += g;
    hash[7] += h;

    // Output first 32 bytes (SHA-512/256 digest)
    std::cout << "SHA-512/256 hash: ";
    for (int i = 0; i < 4; i++) {
        printf("%016llx", hash[i]);
    }
    std::cout << std::endl;

    return 0;
}

#include <asio.hpp>
#include <boost/bind.hpp>
#include <boost/shared_ptr.hpp>
#include <cmath>
#include <cstdlib>
#include <exception>
#include <iostream>
#include <set>
#include "protocol.hpp"

using asio::ip::tcp;
using asio::ip::udp;

typedef boost::shared_ptr<tcp::socket> tcp_socket_ptr;
typedef boost::shared_ptr<asio::steady_timer> timer_ptr;
typedef boost::shared_ptr<control_request> control_request_ptr;

class server
{
public:
  // Construct the server to wait for incoming control connections.
  server(asio::io_context& io_context, unsigned short port)
    : acceptor_(io_context, tcp::endpoint(tcp::v4(), port)),
      timer_(io_context),
      udp_socket_(io_context, udp::endpoint(udp::v4(), 0)),
      frame_counter_(1)
  {
    // Start waiting for a new control connection.
    tcp_socket_ptr new_socket(
        new tcp::socket(acceptor_.get_executor().context()));
    acceptor_.async_accept(*new_socket,
        boost::bind(&server::handle_new_connection, this,
          asio::placeholders::error, new_socket));

    // Initialize and start the data generation timer
    reset_timer();
  }

  void reset_timer()
  {
    timer_.expires_after(asio::chrono::milliseconds(100));
    timer_.async_wait(boost::bind(&server::handle_data_generation, this));
  }

  // Handle a new control connection.
  void handle_new_connection(const asio::error_code& ec, tcp_socket_ptr socket)
  {
    if (!ec)
    {
      // Begin receiving control request on this connection
      control_request_ptr req(new control_request);
      asio::async_read(*socket, req->to_buffers(),
          boost::bind(&server::process_control_message, this,
            asio::placeholders::error, socket, req));
    }

    // Prepare for next incoming connection
    tcp_socket_ptr next_socket(
        new tcp::socket(acceptor_.get_executor().context()));
    acceptor_.async_accept(*next_socket,
        boost::bind(&server::handle_new_connection, this,
          asio::placeholders::error, next_socket));
  }

  // Process received control request
  void process_control_message(const asio::error_code& ec,
      tcp_socket_ptr socket, control_request_ptr request)
  {
    if (!ec)
    {
      // Simulate network delay before processing
      timer_ptr delay_timer(
          new asio::steady_timer(acceptor_.get_executor().context()));
      delay_timer->expires_after(asio::chrono::seconds(2));
      delay_timer->async_wait(
          boost::bind(&server::delayed_control_processing, this,
            socket, request, delay_timer));
    }
  }

  void delayed_control_processing(tcp_socket_ptr socket,
      control_request_ptr request, timer_ptr /*delay_timer*/)
  {
    // Get client's endpoint information
    asio::error_code ec;
    tcp::endpoint client_endpoint = socket->remote_endpoint(ec);
    if (!ec)
    {
      const udp::endpoint old_subscriber(client_endpoint.address(), 
          request->old_port());
      const udp::endpoint new_subscriber(client_endpoint.address(), 
          request->new_port());

      // Remove previous subscription if exists
      if (request->old_port() != 0)
      {
        subscribers_.erase(old_subscriber);
        std::cout << "Removed subscription: " << old_subscriber << std::endl;
      }

      // Add new subscription if specified
      if (request->new_port() != 0)
      {
        subscribers_.insert(new_subscriber);
        std::cout << "Added subscription: " << new_subscriber << std::endl;
      }
    }

    // Continue listening for more requests on this connection
    control_request_ptr next_request(new control_request);
    asio::async_read(*socket, next_request->to_buffers(),
        boost::bind(&server::process_control_message, this,
          asio::placeholders::error, socket, next_request));
  }

  // Generate and broadcast frames periodically
  void handle_data_generation()
  {
    // Compute frame content based on current frame number
    double x = frame_counter_ * 0.2;
    double y = std::sin(x);
    int char_index = static_cast<int>((y + 1.0) * (frame::payload_size / 2));

    std::string payload;
    for (int i = 0; i < frame::payload_size; ++i)
      payload += (i == char_index ? '*' : '.');

    // Create and send frame
    frame f(frame_counter_++, payload);

    for (std::set<udp::endpoint>::const_iterator it = subscribers_.begin();
         it != subscribers_.end(); ++it)
    {
      asio::error_code ec;
      udp_socket_.send_to(f.to_buffers(), *it, 0, ec);
    }

    // Schedule next frame generation
    reset_timer();
  }

private:
  tcp::acceptor acceptor_;
  asio::steady_timer timer_;
  udp::socket udp_socket_;
  unsigned long frame_counter_;
  std::set<udp::endpoint> subscribers_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: server <port>\n";
      return 1;
    }

    asio::io_context io_context;
    using namespace std; // For atoi

    server s(io_context, static_cast<unsigned short>(atoi(argv[1])));
    io_context.run();
  }
  catch (const std::exception& err)
  {
    std::cerr << "Error: " << err.what() << std::endl;
    return 1;
  }

  return 0;
}

