// 4J - note that caller is responsible for deleting returned array. downfalls array is for output only.
// 4J - removal of separate temperature & downfall layers brought forward from 1.2.3
void BiomeSource::retrieveDownfall(floatArray &downfalls, int xPos, int zPos, int width, int height) const
{
	IntCache::releaseAll();

	if (downfalls.data == nullptr || static_cast<size_t>(downfalls.length) < static_cast<size_t>(width * height))
	{
		if (downfalls.data != nullptr) delete[] downfalls.data;
		downfalls = floatArray(width * height);
	}

	intArray sampleResult = refinedLayer->getArea(xPos, zPos, width, height);
	for (int idx = 0; idx < width * height; ++idx)
	{
		float d = static_cast<float>(Biome::biomes[sampleResult[idx]]->getDownfallInt()) / 65536.0f;
		if (d > 1.0f) d = 1.0f;
		downfalls[idx] = d;
	}
}

