// 4J - caller is responsible for deleting biomes array
void BiomeSource::constructBiomeBlock(BiomeArray& biomes, int xPos, int zPos, int width, int height, bool useCached) const
{
	IntCache::releaseAll();

	if (biomes.data == nullptr || static_cast<size_t>(biomes.length) < static_cast<size_t>(width * height))
	{
		if (biomes.data != nullptr) delete[] biomes.data;
		biomes = BiomeArray(width * height);
	}

	if (useCached && width == 16 && height == 16 && (xPos & 0xf) == 0 && (zPos & 0xf) == 0)
	{
		BiomeArray tempBlock = biomeCache->getBiomeBlockAt(xPos, zPos);
		System::arraycopy(tempBlock, 0, &biomes, 0, width * height);
		delete[] tempBlock.data;	// MGH - added, the caching creates this array from the indices now.
	}

	intArray sampleResult = refinedLayer->getArea(xPos, zPos, width, height);
	for (int idx = 0; idx < width * height; ++idx)
	{
		biomes[idx] = Biome::biomes[sampleResult[idx]];
	}
}

