/**
* Checks if an area around a block contains only the specified biomes.
* Useful for placing elements like towns.
* 
* This is a bit of a rough check, to make it as fast as possible. To ensure
* NO other biomes, add a margin of at least four blocks to the radius
*/
bool BiomeSource::containsOnly(int xPos, int zPos, int radius, std::vector<Biome *> permittedList)
{
	IntCache::releaseAll();
	int minX = ((xPos - radius) >> 2);
	int minZ = ((zPos - radius) >> 2);
	int maxX = ((xPos + radius) >> 2);
	int maxZ = ((zPos + radius) >> 2);
	int w = maxX - minX + 1;
	int h = maxZ - minZ + 1;

	intArray sampled = primaryLayer->getArea(minX, minZ, w, h);
	for (int idx = 0; idx < w * h; ++idx)
	{
		Biome *b = Biome::biomes[sampled[idx]];
		if (std::find(permittedList.begin(), permittedList.end(), b) == permittedList.end())
			return false;
	}
	return true;
}

/**
* Checks if an area around a block contains only the specified biome.
* Useful for placing elements like towns.
* 
* This is a bit of a rough check, to make it as fast as possible. To ensure
* NO other biomes, add a margin of at least four blocks to the radius
*/
bool BiomeSource::containsOnly(int xPos, int zPos, int radius, Biome *requiredBiome)
{
	IntCache::releaseAll();
	int minX = ((xPos - radius) >> 2);
	int minZ = ((zPos - radius) >> 2);
	int maxX = ((xPos + radius) >> 2);
	int maxZ = ((zPos + radius) >> 2);
	int w = maxX - minX;
	int h = maxZ - minZ;
	int totalSamples = w * h;

	intArray sampled = primaryLayer->getArea(minX, minZ, w, h);
	for (unsigned int idx = 0; idx < static_cast<unsigned int>(totalSamples); ++idx)
	{
		Biome *b = Biome::biomes[sampled[idx]];
		if (requiredBiome != b) return false;
	}
	return true;
}

/**
* Finds the specified biome within the radius. This will return a random
* position if several are found. This test is fairly rough.
* 
* Returns null if the biome wasn't found
*/
TilePos *BiomeSource::findBiome(int xPos, int zPos, int radius, Biome *targetBiome, Random *rng)
{
	IntCache::releaseAll();
	int minX = ((xPos - radius) >> 2);
	int minZ = ((zPos - radius) >> 2);
	int maxX = ((xPos + radius) >> 2);
	int maxZ = ((zPos + radius) >> 2);
	int w = maxX - minX + 1;
	int h = maxZ - minZ + 1;

	intArray sampled = primaryLayer->getArea(minX, minZ, w, h);
	TilePos *result = nullptr;
	int countFound = 0;
	int totalSamples = w * h;

	for (unsigned int idx = 0; idx < static_cast<unsigned int>(totalSamples); ++idx)
	{
		int xx = minX + (idx % w);
		int zz = minZ + (idx / w);
		Biome *b = Biome::biomes[sampled[idx]];
		if (b == targetBiome)
		{
			if (result == nullptr || rng->nextInt(countFound + 1) == 0)
			{
				result = new TilePos(xx, 0, zz);
				countFound++;
			}
		}
	}
	return result;
}

/**
* Finds one of the specified biomes within the radius. This will return a
* random position if several are found. This test is fairly rough.
* 
* Returns null if the biome wasn't found
*/
TilePos *BiomeSource::findBiome(int xPos, int zPos, int radius, std::vector<Biome *> allowedList, Random *rng)
{
	IntCache::releaseAll();
	int minX = ((xPos - radius) >> 2);
	int minZ = ((zPos - radius) >> 2);
	int maxX = ((xPos + radius) >> 2);
	int maxZ = ((zPos + radius) >> 2);
	int w = maxX - minX + 1;
	int h = maxZ - minZ + 1;

	MemSect(50);
	intArray sampled = primaryLayer->getArea(minX, minZ, w, h);
	TilePos *result = nullptr;
	int countFound = 0;

	for (unsigned int idx = 0; idx < static_cast<unsigned int>(w * h); ++idx)
	{
		int xx = ((minX + (idx % w)) << 2);
		int zz = ((minZ + (idx / w)) << 2);
		Biome *b = Biome::biomes[sampled[idx]];
		if (std::find(allowedList.begin(), allowedList.end(), b) != allowedList.end())
		{
			if (result == nullptr || rng->nextInt(countFound + 1) == 0)
			{
				delete result;
				result = new TilePos(xx, 0, zz);
				countFound++;
			}
		}
	}
	MemSect(0);
	return result;
}

