#if DECODE_ELITESCREENS
/// Decode a received Elite Screens infrared message.
/// Status: STABLE / Verified working.
/// @param[in,out] result Pointer to storage for decoded results.
/// @param[in] startIdx Starting position in raw buffer for decoding.
/// @param[in] expectedBits Expected number of data bits.
/// @param[in] enforceStrict Whether to enforce strict bit count validation.
/// @return true if decoding succeeded, false otherwise.
bool IRrecv::decodeElitescreens(decode_results *result, uint16_t startIdx,
                                const uint16_t expectedBits, const bool enforceStrict) {
  // Validate bit count if strict mode is enabled
  if (enforceStrict && expectedBits != kEliteScreensBits) return false;

  uint64_t decodedData = 0;

  // Attempt to match the data portion using constant-bit-time matching
  if (!matchGenericConstBitTime(
        result->rawbuf + startIdx, &decodedData,
        result->rawlen - startIdx, expectedBits,
        // Header: none
        0, 0,
        // Bit encoding: 1=long pulse/short space, 0=short pulse/long space
        kEliteScreensBitOne, kEliteScreensBitZero,
        // Footer: none
        0, kEliteScreensInterGap, true)) {
    return false;
  }

  // Populate decode results
  result->decode_type = decode_type_t::ELITESCREENS;
  result->bits = expectedBits;
  result->value = decodedData;
  result->address = 0;
  result->command = 0;
  result->repeat = false;

  return true;
}
#endif

