void ARMAssemblyOutputHandler::establishFramePointer(unsigned FrameReg, unsigned StackReg, int64_t Adjustment) {
  OutputStream << "\t.setfp\t";
  InstructionPrinter.printRegName(OutputStream, FrameReg);
  OutputStream << ", ";
  InstructionPrinter.printRegName(OutputStream, StackReg);
  if (Adjustment != 0)
    OutputStream << ", #" << Adjustment;
  OutputStream << '\n';
