void ARMAssemblyOutputHandler::updateStackPointer(unsigned Reg, int64_t Adjustment) {
  assert((Reg != ARM::SP && Reg != ARM::PC) &&
         "stack pointer or program counter cannot be used as operand");
  OutputStream << "\t.movsp\t";
  InstructionPrinter.printRegName(OutputStream, Reg);
  if (Adjustment != 0)
    OutputStream << ", #" << Adjustment;
  OutputStream << '\n';
}

