void ARMAssemblyOutputHandler::saveRegisterList(const SmallVectorImpl<unsigned> &Registers, bool IsVector) {
  assert(!Registers.empty() && "register list must not be empty");
  if (IsVector)
    OutputStream << "\t.vsave\t{";
  else
    OutputStream << "\t.save\t{";

  InstructionPrinter.printRegName(OutputStream, Registers[0]);
  for (size_t i = 1; i < Registers.size(); ++i) {
    OutputStream << ", ";
    InstructionPrinter.printRegName(OutputStream, Registers[i]);
  }
  OutputStream << "}\n";
}

