void ARMAssemblyOutputHandler::emitBuildAttribute(unsigned Attribute, unsigned Value) {
  OutputStream << "\t.eabi_attribute\t" << Attribute << ", " << Value;
  if (IsVerboseMode) {
    StringRef Name = ELFAttrs::attrTypeAsString(
        Attribute, ARMBuildAttrs::getARMAttributeTags());
    if (!Name.empty())
      OutputStream << "\t@ " << Name;
  }
  OutputStream << "\n";
}

void ARMAssemblyOutputHandler::emitStringAttribute(unsigned Attribute, StringRef String) {
  switch (Attribute) {
  case ARMBuildAttrs::CPU_name:
    OutputStream << "\t.cpu\t" << String.lower();
    break;
  default:
    OutputStream << "\t.eabi_attribute\t" << Attribute << ", \"";
    if (Attribute == ARMBuildAttrs::also_compatible_with)
      OutputStream.write_escaped(String);
    else
      OutputStream << String;
    OutputStream << "\"";
    if (IsVerboseMode) {
      StringRef Name = ELFAttrs::attrTypeAsString(
          Attribute, ARMBuildAttrs::getARMAttributeTags());
      if (!Name.empty())
        OutputStream << "\t@ " << Name;
    }
    break;
  }
  OutputStream << "\n";
}

void ARMAssemblyOutputHandler::emitMixedAttribute(unsigned Attribute, unsigned IntValue, StringRef StringValue) {
  switch (Attribute) {
  default: llvm_unreachable("unsupported multi-value attribute in assembly mode");
  case ARMBuildAttrs::compatibility:
    OutputStream << "\t.eabi_attribute\t" << Attribute << ", " << IntValue;
    if (!StringValue.empty())
      OutputStream << ", \"" << StringValue << "\"";
    if (IsVerboseMode)
      OutputStream << "\t@ "
         << ELFAttrs::attrTypeAsString(Attribute,
                                       ARMBuildAttrs::getARMAttributeTags());
    break;
  }
  OutputStream << "\n";
}

