static void printRegisterRange(formatted_raw_ostream &OS, ListSeparator &LS, int Start,
                               int End) {
  if (Start != End)
    OS << LS << "r" << Start << "-r" << End;
  else
    OS << LS << "r" << Start;
}

void ARMAssemblyOutputHandler::emitWindowsSEHSaveRegisterMask(unsigned Mask, bool Wide) {
  if (Wide)
    OutputStream << "\t.seh_save_regs_w\t";
  else
    OutputStream << "\t.seh_save_regs\t";

  ListSeparator LS;
  int Start = -1;
  OutputStream << "{";
  for (int Index = 0; Index <= 12; Index++) {
    if (Mask & (1 << Index)) {
      if (Start < 0)
        Start = Index;
    } else {
      if (Start >= 0) {
        printRegisterRange(OutputStream, LS, Start, Index - 1);
        Start = -1;
      }
    }
  }
  if (Start >= 0)
    printRegisterRange(OutputStream, LS, Start, 12);
  if (Mask & (1 << 14))
    OutputStream << LS << "lr";
  OutputStream << "}\n";
}

