}

void ARMAssemblyOutputHandler::emitWindowsSEHEpilogueStart(unsigned Condition) {
  if (Condition == ARMCC::AL)
    OutputStream << "\t.seh_startepilogue\n";
  else
    OutputStream << "\t.seh_startepilogue_cond\t"
       << ARMCondCodeToString(static_cast<ARMCC::CondCodes>(Condition)) << "\n";
}

void ARMAssemblyOutputHandler::emitWindowsSEHEpilogueEnd() {
  OutputStream << "\t.seh_endepilogue\n";
}

void ARMAssemblyOutputHandler::emitWindowsSEHCustomOpcode(unsigned Opcode) {
  int Index;
  for (Index = 3; Index > 0; Index--)
    if (Opcode & (0xffu << (8 * Index)))
      break;
  ListSeparator LS;
  OutputStream << "\t.seh_custom\t";
  for (; Index >= 0; Index--)
    OutputStream << LS << ((Opcode >> (8 * Index)) & 0xff);
  OutputStream << "\n";
}

