/// Extend the generic ELFStreamer class so that it can emit mapping symbols at
/// the appropriate points in the object files. These symbols are defined in the
/// ARM ELF ABI: infocenter.arm.com/help/topic/com.arm.../IHI0044D_aaelf.pdf.
///
/// In brief: $a, $t or $d should be emitted at the start of each contiguous
/// region of ARM code, Thumb code or data in a section. In practice, this
/// emission does not rely on explicit assembler directives but on inherent
/// properties of the directives doing the emission (e.g. ".byte" is data, "add
/// r0, r0, r0" an instruction).
///
/// As a result this system is orthogonal to the DataRegion infrastructure used
/// by MachO. Beware!
class ARMELFFormatter : public MCELFStreamer {
public:
  friend class ARMObjectFormatter;
  ARMELFFormatter(MCContext &Context, std::unique_ptr<MCAsmBackend> TAB,
                 std::unique_ptr<MCObjectWriter> OW,
                 std::unique_ptr<MCCodeEmitter> Emitter, bool IsThumb,
                 bool IsAndroid)
      : MCELFStreamer(Context, std::move(TAB), std::move(OW),
                      std::move(Emitter)),
        IsThumbMode(IsThumb), IsAndroidPlatform(IsAndroid) {
    resetExceptionState();
  }
  ~ARMELFFormatter() override = default;

  void finalizeImplementation() override;

  // ARM exception handling directives
  void emitFunctionStart();
  void emitFunctionEnd();
  void emitCannotUnwind();
  void emitPersonalityRoutine(const MCSymbol *Per);
  void emitPersonalitySelector(unsigned index);
  void emitExceptionHandlerData();
  void establishFramePointer(unsigned NewFpReg, unsigned NewSpReg, int64_t Offset = 0);
  void updateStackPointer(unsigned Reg, int64_t Offset = 0);
  void allocateStackSpace(int64_t Offset);
  void saveRegisterList(const SmallVectorImpl<unsigned> &Registers, bool IsVector);
  void emitRawUnwindOpcodes(int64_t Offset, const SmallVectorImpl<uint8_t> &Opcodes);

  void emitFill(const MCExpr &NumBytes, uint64_t FillValue,
                SMLoc Loc) override {
    emitDataMappingSymbol();
    MCObjectStreamer::emitFill(NumBytes, FillValue, Loc);
  }

  void changeSection(MCSection *Section, const MCExpr *Subsection) override {
    LastMappingSymbols[getCurrentSection().first] = std::move(LastEMSInfo);
    MCELFStreamer::changeSection(Section, Subsection);
    auto LastMappingSymbol = LastMappingSymbols.find(Section);
    if (LastMappingSymbol != LastMappingSymbols.end()) {
      LastEMSInfo = std::move(LastMappingSymbol->second);
      return;
    }
    LastEMSInfo.reset(new MappingSymbolInfo(SMLoc(), nullptr, 0));
  }

  /// This function is the one used to emit instruction data into the ELF
  /// streamer. We override it to add the appropriate mapping symbol if
  /// necessary.
  void emitInstruction(const MCInst &Inst,
                       const MCSubtargetInfo &STI) override {
    if (IsThumbMode)
      EmitThumbMappingSymbol();
    else
      EmitARMMappingSymbol();
    MCELFStreamer::emitInstruction(Inst, STI);
  }

  void outputInstruction(uint32_t Instruction, char Suffix) {
    unsigned Size;
    char Buffer[4];
    const bool LittleEndian = getContext().getAsmInfo()->isLittleEndian();
    switch (Suffix) {
    case '\0':
      Size = 4;
      assert(!IsThumbMode);
      EmitARMMappingSymbol();
      for (unsigned II = 0, IE = Size; II != IE; II++) {
        const unsigned I = LittleEndian ? (Size - II - 1) : II;
        Buffer[Size - II - 1] = uint8_t(Instruction >> I * CHAR_BIT);
      }
      break;
    case 'n':
    case 'w':
      Size = (Suffix == 'n' ? 2 : 4);
      assert(IsThumbMode);
      EmitThumbMappingSymbol();
      // Thumb wide instructions are emitted as a pair of 16-bit words of the
      // appropriate endianness.
      for (unsigned II = 0, IE = Size; II != IE; II = II + 2) {
        const unsigned I0 = LittleEndian ? II + 0 : II + 1;
        const unsigned I1 = LittleEndian ? II + 1 : II + 0;
        Buffer[Size - II - 2] = uint8_t(Instruction >> I0 * CHAR_BIT);
        Buffer[Size - II - 1] = uint8_t(Instruction >> I1 * CHAR_BIT);
      }
      break;
    default:
      llvm_unreachable("Invalid Suffix");
    }
    MCELFStreamer::emitBytes(StringRef(Buffer, Size));
  }

  /// This is one of the functions used to emit data into an ELF section, so the
  /// ARM streamer overrides it to add the appropriate mapping symbol ($d) if
  /// necessary.
  void emitBytes(StringRef Data) override {
    emitDataMappingSymbol();
    MCELFStreamer::emitBytes(Data);
  }

  void FlushPendingMappingSymbol() {
    if (!LastEMSInfo->hasInfo())
      return;
    MappingSymbolInfo *EMS = LastEMSInfo.get();
    EmitMappingSymbol("$d", EMS->Loc, EMS->F, EMS->Offset);
    EMS->resetInfo();
  }

  /// This is one of the functions used to emit data into an ELF section, so the
  /// ARM streamer overrides it to add the appropriate mapping symbol ($d) if
  /// necessary.
  void emitValueImpl(const MCExpr *Value, unsigned Size, SMLoc Loc) override {
    if (const MCSymbolRefExpr *SRE = dyn_cast_or_null<MCSymbolRefExpr>(Value)) {
      if (SRE->getKind() == MCSymbolRefExpr::VK_ARM_SBREL && !(Size == 4)) {
        getContext().reportError(Loc, "relocated expression must be 32-bit");
        return;
      }
      getOrCreateDataFragment();
    }
    emitDataMappingSymbol();
    MCELFStreamer::emitValueImpl(Value, Size, Loc);
  }

  void emitAssemblerFlag(MCAssemblerFlag Flag) override {
    MCELFStreamer::emitAssemblerFlag(Flag);
    switch (Flag) {
    case MCAF_SyntaxUnified:
      return; // no-op here.
    case MCAF_Code16:
      IsThumbMode = true;
      return; // Change to Thumb mode
    case MCAF_Code32:
      IsThumbMode = false;
      return; // Change to ARM mode
    case MCAF_Code64:
      return;
    case MCAF_SubsectionsViaSymbols:
      return;
    }
  }

  /// If a label is defined before the .type directive sets the label's type
  /// then the label can't be recorded as thumb function when the label is
  /// defined. We override emitSymbolAttribute() which is called as part of the
  /// parsing of .type so that if the symbol has already been defined we can
  /// record the label as Thumb. FIXME: there is a corner case where the state
  /// is changed in between the label definition and the .type directive, this
  /// is not expected to occur in practice and handling it would require the
  /// backend to track IsThumb for every label.
  bool emitSymbolAttribute(MCSymbol *Symbol, MCSymbolAttr Attribute) override {
    bool Val = MCELFStreamer::emitSymbolAttribute(Symbol, Attribute);
    if (!IsThumbMode)
      return Val;
    unsigned Type = cast<MCSymbolELF>(Symbol)->getType();
    if ((Type == ELF::STT_FUNC || Type == ELF::STT_GNU_IFUNC) &&
        Symbol->isDefined())
      getAssembler().setIsThumbFunc(Symbol);
    return Val;
  };

private:
  enum MappingSymbolType {
    MST_None,
    MST_ARM,
    MST_Thumb,
    MST_Data
  };

  struct MappingSymbolInfo {
    explicit MappingSymbolInfo(SMLoc Loc, MCFragment *F, uint64_t O)
        : Location(Loc), Fragment(F), Offset(O), State(MST_None) {}
    void resetInfo() {
      Fragment = nullptr;
      Offset = 0;
    }
    bool hasInfo() { return Fragment != nullptr; }
    SMLoc Location;
    MCFragment *Fragment;
    uint64_t Offset;
    MappingSymbolType State;
  };

  void emitDataMappingSymbol() {
    if (LastEMSInfo->State == MST_Data)
      return;
    else if (LastEMSInfo->State == MST_None) {
      // This is a tentative symbol, it won't really be emitted until it's
      // actually needed.
      MappingSymbolInfo *EMS = LastEMSInfo.get();
      auto *DF = dyn_cast_or_null<MCDataFragment>(getCurrentFragment());
      if (!DF)
        return;
      EMS->Location = SMLoc();
      EMS->Fragment = getCurrentFragment();
      EMS->Offset = DF->getContents().size();
      LastEMSInfo->State = MST_Data;
      return;
    }
    EmitMappingSymbol("$d");
    LastEMSInfo->State = MST_Data;
  }

  void EmitThumbMappingSymbol() {
    if (LastEMSInfo->State == MST_Thumb)
      return;
    FlushPendingMappingSymbol();
    EmitMappingSymbol("$t");
    LastEMSInfo->State = MST_Thumb;
  }

  void EmitARMMappingSymbol() {
    if (LastEMSInfo->State == MST_ARM)
      return;
    FlushPendingMappingSymbol();
    EmitMappingSymbol("$a");
    LastEMSInfo->State = MST_ARM;
  }

  void EmitMappingSymbol(StringRef Name) {
    auto *Symbol = cast<MCSymbolELF>(getContext().getOrCreateSymbol(
        Name + "." + Twine(MappingSymbolCounter++)));
    emitLabel(Symbol);
    Symbol->setType(ELF::STT_NOTYPE);
    Symbol->setBinding(ELF::STB_LOCAL);
  }

  void EmitMappingSymbol(StringRef Name, SMLoc Loc, MCFragment *F,
                         uint64_t Offset) {
    auto *Symbol = cast<MCSymbolELF>(getContext().getOrCreateSymbol(
        Name + "." + Twine(MappingSymbolCounter++)));
    emitLabelAtPos(Symbol, Loc, F, Offset);
    Symbol->setType(ELF::STT_NOTYPE);
    Symbol->setBinding(ELF::STB_LOCAL);
  }

  void emitThumbFunction(MCSymbol *Func) override {
    getAssembler().setIsThumbFunc(Func);
    emitSymbolAttribute(Func, MCSA_ELF_TypeFunction);
  }

  // Helper functions for ARM exception handling directives
  void resetExceptionState();
  // Reset state between object emissions
  void resetState() override;
  void EmitPersonalityFixup(StringRef Name);
  void FlushPendingOffset();
  void FlushUnwindOpcodes(bool NoHandlerData);
  void SwitchToEHSection(StringRef Prefix, unsigned Type, unsigned Flags,
                         SectionKind Kind, const MCSymbol &Fn);
  void SwitchToExTabSection(const MCSymbol &FnStart);
  void SwitchToExIdxSection(const MCSymbol &FnStart);
  void EmitFixup(const MCExpr *Expr, MCFixupKind Kind);

  bool IsThumbMode;
  bool IsAndroidPlatform;
  int64_t MappingSymbolCounter = 0;
  DenseMap<const MCSection *, std::unique_ptr<MappingSymbolInfo>>
      LastMappingSymbols;
  std::unique_ptr<MappingSymbolInfo> LastEMSInfo;

  // ARM Exception Handling Frame Information
  MCSymbol *ExceptionTable;
  MCSymbol *FunctionStart;
  const MCSymbol *PersonalityRoutine;
  unsigned PersonalitySelector;
  unsigned FramePointerReg; // Frame pointer register
  int64_t FramePointerOffset; // Offset: (final frame pointer) - (initial $sp)
  int64_t StackPointerOffset; // Offset: (final $sp) - (initial $sp)
  int64_t PendingOffset; // Offset: (final $sp) - (emitted $sp)
  bool UsedFramePointer;
  bool CannotUnwind;
  SmallVector<uint8_t, 64> UnwindOpcodes;
  UnwindOpcodeAssembler UnwindOpAssembler;
};

