#include <iostream>
#include <vector>
#include <random>
using namespace std;

// Simulates the line-breaking process for a given article and width
// Returns 0 if any word exceeds the width W
int simulate_lines(const vector<int>& words, int width) {
    int line_count = 1;
    long long current_width = 0;

    for (int word_len : words) {
        if (word_len > width) {
            return 0; // Invalid: word too long for given width
        }

        if (current_width + word_len <= width) {
            current_width += word_len;
        } else {
            line_count++;
            current_width = word_len;
        }
    }

    return line_count;
}

void process_case() {
    const int N = 100000;

    // First query: all words of length 1 to get initial estimate
    cout << "? " << N;
    for (int i = 0; i < N; ++i) {
        cout << " 1";
    }
    cout << "\n";

    int lines1;
    cin >> lines1;

    if (lines1 == 0 || lines1 == -1) {
        exit(0);
    }

    // Calculate bounds for possible width values
    int lower_bound, upper_bound;

    if (lines1 == 1) {
        lower_bound = N;
        upper_bound = 100000;
    } else {
        lower_bound = (N + lines1 - 1) / lines1;  // ceil(N / lines1)
        upper_bound = (N - 1) / (lines1 - 1);     // floor((N-1)/(lines1-1))
    }

    // Ensure bounds are within problem constraints
    if (lower_bound > 100000) lower_bound = 100000;
    if (upper_bound > 100000) upper_bound = 100000;
    if (lower_bound > upper_bound) lower_bound = upper_bound;

    // If bounds converge, we found the answer
    if (lower_bound == upper_bound) {
        cout << "! " << lower_bound << "\n";
        return;
    }

    // Second query: generate random-length words to refine search
    mt19937 rng(42);  // Fixed seed for reproducibility
    vector<int> word_lengths(N);

    for (int i = 0; i < N; ++i) {
        // Generate random length between 1 and lower_bound
        word_lengths[i] = (rng() % lower_bound) + 1;
    }

    // Output second query
    cout << "? " << N;
    for (int i = 0; i < N; ++i) {
        cout << " " << word_lengths[i];
    }
    cout << "\n";

    int observed_lines;
    cin >> observed_lines;

    if (observed_lines == -1) {
        exit(0);
    }

    // Binary search for exact width value
    int result = upper_bound;
    int left = lower_bound, right = upper_bound;

    while (left <= right) {
        int candidate = left + (right - left) / 2;
        int simulated = simulate_lines(word_lengths, candidate);

        if (simulated == observed_lines) {
            result = candidate;
            break;
        } else if (simulated < observed_lines) {
            // Too few lines means candidate width is too large
            right = candidate - 1;
        } else {
            // Too many lines means candidate width is too small
            left = candidate + 1;
        }
    }

    cout << "! " << result << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            process_case();
        }
    }

    return 0;
}

