[[noreturn]] void report_size_overflow(size_t requested, size_t limit) {
    std::string msg = "small_vector unable to grow. Requested capacity (" +
                      std::to_string(requested) + ") exceeds maximum size type limit (" +
                      std::to_string(limit) + ")";
    throw std::length_error(msg);
}

[[noreturn]] void report_at_maximum_capacity(size_t max_cap) {
    std::string msg = "small_vector capacity cannot increase further. Already at maximum size " +
                      std::to_string(max_cap);
    throw std::length_error(msg);
}

// Alternative growth policy: round up to next power of two if possible,
// otherwise clamp to min_size or max allowed.
template <typename SizeT>
size_t compute_new_capacity(size_t needed, size_t /*elem_size*/, size_t current_capacity) {
    constexpr size_t MAX_VAL = std::numeric_limits<SizeT>::max();

    // Early checks for overflow or impossible requests
    if (needed > MAX_VAL) report_size_overflow(needed, MAX_VAL);
    if (current_capacity == MAX_VAL) report_at_maximum_capacity(MAX_VAL);

    // Growth strategy: double capacity only if safe; else use linear growth
    size_t doubled = current_capacity << 1;  // equivalent to 2 * current_capacity
    size_t proposed = (doubled < MAX_VAL - 1) ? doubled + 1 : MAX_VAL;

    // Ensure we meet minimum requirement and do not exceed max
    size_t result = std::max(needed, proposed);
    return (result <= MAX_VAL) ? result : MAX_VAL;
}

} // anonymous namespace

template <typename SizeT>
void* small_vector_base<SizeT>::replace_allocation(void* old_ptr,
                                                   size_t elem_size,
                                                   size_t new_cap,
                                                   size_t used_count) {
    void* new_mem = std::malloc(new_cap * elem_size);
    if (new_mem && used_count > 0u) {
        std::memcpy(new_mem, old_ptr, used_count * elem_size);
    }
    std::free(old_ptr);
    return new_mem;
}

template <typename SizeT>
void* small_vector_base<SizeT>::malloc_for_grow(void* first_el,
                                                size_t min_needed,
                                                size_t elem_size,
                                                size_t& out_new_cap) {
    out_new_cap = compute_new_capacity<SizeT>(min_needed, elem_size, this->capacity());
    void* new_mem = std::malloc(out_new_cap * elem_size);
    if (new_mem == first_el) {
        new_mem = replace_allocation(new_mem, elem_size, out_new_cap, this->size());
    }
    return new_mem;
}

template <typename SizeT>
void small_vector_base<SizeT>::grow_pod(void* first_el,
                                        size_t min_needed,
                                        size_t elem_size) {
    size_t new_cap = compute_new_capacity<SizeT>(min_needed, elem_size, this->capacity());
    void* new_data = nullptr;

    if (this->m_begin_x == first_el) {
        // Inline buffer case: allocate fresh memory and copy
        new_data = std::malloc(new_cap * elem_size);
        if (new_data == first_el) {
            new_data = replace_allocation(new_data, elem_size, new_cap, this->size());
        }
        if (new_data && this->size() > 0u) {
            std::memcpy(new_data, this->m_begin_x, this->size() * elem_size);
        }
    } else {
        // Heap-allocated buffer: try realloc first
        new_data = std::realloc(this->m_begin_x, new_cap * elem_size);
        if (new_data == first_el) {
            new_data = replace_allocation(new_data, elem_size, new_cap, this->size());
        }
    }

    this->m_begin_x = new_data;
    this->m_capacity = new_cap;
}

