// Benchmark for Hadamard Gate application - memory bandwidth stress test
static void BM_HadamardMemoryStress(benchmark::State &state) {
  int qubit_count = state.range(0);

  // Initialize quantum register outside the timing loop to exclude allocation overhead
  try {
    QuantumRegister qr(qubit_count);

    for (auto _ : state) {
      // Apply Hadamard gate to first qubit - memory-bound operation
      qr.applyHadamard(0);

      // Prevent compiler optimizations and ensure memory operations are preserved
      benchmark::DoNotOptimize(qr.getStateVector().data());
      benchmark::ClobberMemory();
    }

    // Compute memory throughput metrics
    // Each state vector element is a complex<double> (16 bytes)
    // Hadamard on one qubit processes all basis states, accessing entire state vector
    // Memory traffic: read + write of full state vector => 2 * sizeof(state_vector)
    size_t state_size = static_cast<size_t>(1ULL << qubit_count);
    double total_bytes = static_cast<double>(state_size) * 16.0 * 2.0;

    state.SetBytesProcessed(static_cast<int64_t>(state.iterations()) * 
                            static_cast<int64_t>(total_bytes));
  } catch (const std::exception &e) {
    state.SkipWithError("Memory allocation failed or insufficient system memory");
  }
}

// Register benchmarks for various system sizes:
