    ->Arg(20)
    ->Arg(25)
    ->Arg(28)
    ->Unit(benchmark::kMillisecond);

BENCHMARK_MAIN();

#include <iostream>
#include <vector>
using namespace std;

class Solution {
public:
    void generateSubsets(const vector<int>& input, vector<int>& current, int index, vector<vector<int>>& result) {
        if (index == input.size()) {
            result.push_back(current);
            return;
        }

        // Include current element
        current.push_back(input[index]);
        generateSubsets(input, current, index + 1, result);

        // Exclude current element (backtrack)
        current.pop_back();
        generateSubsets(input, current, index + 1, result);
    }

    vector<vector<int>> findSubsets(vector<int>& elements) {
        vector<vector<int>> allSubsets;
        vector<int> temp;

        generateSubsets(elements, temp, 0, allSubsets);

        return allSubsets;
    }
};

int main() {
    Solution solver;
    vector<int> data = {1, 2, 3};
    vector<vector<int>> output = solver.findSubsets(data);

    for (int i = 0; i < output.size(); ++i) {
        cout << "{ ";
        for (int j = 0; j < output[i].size(); ++j) {
            cout << output[i][j] << " ";
        }
        cout << "}" << endl;
    }

    return 0;
}

