int APIENTRY wWinMain(_In_ HINSTANCE instance, _In_opt_ HINSTANCE prev,
                      _In_ wchar_t *command_line, _In_ int show_command) {
  // Attach to existing console or create a new one for debugging purposes
  if (!::AttachConsole(ATTACH_PARENT_PROCESS)) {
    if (::IsDebuggerPresent()) {
      CreateAndAttachConsole();
    }
  }

  // Set up COM for plugin and library compatibility
  ::CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);

  // Prepare Dart project and arguments
  flutter::DartProject project(L"data");
  std::vector<std::string> args = GetCommandLineArguments();
  project.set_dart_entrypoint_arguments(std::move(args));

  // Configure window dimensions and title
  FlutterWindow window(project);
  Win32Window::Point start_position(10, 10);
  Win32Window::Size window_dimensions(1280, 720);

  if (!window.Create(L"flutter_engine_bridge_example", start_position, window_dimensions)) {
    return EXIT_FAILURE;
  }

  window.SetQuitOnClose(true);

  // Message loop for Windows event handling
  ::MSG message;
  while (::GetMessage(&message, nullptr, 0, 0)) {
    ::TranslateMessage(&message);
    ::DispatchMessage(&message);
  }

  ::CoUninitialize();
  return EXIT_SUCCESS;
}

