#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <map>

// Fixed problem size as per constraints
const int GRID_SIZE = 20;

struct Piece {
    int identifier;
    int row, col;
};

struct Action {
    char direction;
    int position;
    int depth;
    int effort;
    std::vector<int> affected_pieces; // IDs of pieces removed by this action
};

struct Step {
    char dir;
    int idx;
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int placeholder;
    std::cin >> placeholder; // N is fixed at 20

    std::vector<std::string> board(GRID_SIZE);
    std::vector<Piece> pieces;
    std::map<std::pair<int, int>, int> location_map;

    for (int i = 0; i < GRID_SIZE; ++i) {
        std::cin >> board[i];
        for (int j = 0; j < GRID_SIZE; ++j) {
            if (board[i][j] == 'x') {
                int id = static_cast<int>(pieces.size());
                pieces.push_back({id, i, j});
                location_map[{i, j}] = id;
            }
        }
    }

    int total_pieces = static_cast<int>(pieces.size());
    std::vector<Action> available_actions;

    // Generate upward actions
    for (int col = 0; col < GRID_SIZE; ++col) {
        std::vector<int> path_pieces;
        for (int row = 0; row < GRID_SIZE; ++row) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') {
                path_pieces.push_back(location_map.at({row, col}));
            }
            if (!path_pieces.empty()) {
                available_actions.push_back({'U', col, row, 2 * (row + 1), path_pieces});
            }
        }
    }

    // Generate downward actions
    for (int col = 0; col < GRID_SIZE; ++col) {
        std::vector<int> path_pieces;
        for (int row = GRID_SIZE - 1; row >= 0; --row) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') {
                path_pieces.push_back(location_map.at({row, col}));
            }
            if (!path_pieces.empty()) {
                available_actions.push_back({'D', col, row, 2 * (GRID_SIZE - row), path_pieces});
            }
        }
    }

    // Generate leftward actions
    for (int row = 0; row < GRID_SIZE; ++row) {
        std::vector<int> path_pieces;
        for (int col = 0; col < GRID_SIZE; ++col) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') {
                path_pieces.push_back(location_map.at({row, col}));
            }
            if (!path_pieces.empty()) {
                available_actions.push_back({'L', row, col, 2 * (col + 1), path_pieces});
            }
        }
    }

    // Generate rightward actions
    for (int row = 0; row < GRID_SIZE; ++row) {
        std::vector<int> path_pieces;
        for (int col = GRID_SIZE - 1; col >= 0; --col) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') {
                path_pieces.push_back(location_map.at({row, col}));
            }
            if (!path_pieces.empty()) {
                available_actions.push_back({'R', row, col, 2 * (GRID_SIZE - col), path_pieces});
            }
        }
    }

    std::vector<bool> status(total_pieces, false);
    int cleared_count = 0;
    std::vector<Step> solution_sequence;

    while (cleared_count < total_pieces) {
        double best_score = -1.0;
        int optimal_action_index = -1;

        for (int idx = 0; idx < available_actions.size(); ++idx) {
            int gain = 0;
            for (int pid : available_actions[idx].affected_pieces) {
                if (!status[pid]) {
                    gain++;
                }
            }
            if (gain == 0) continue;

            double evaluation = static_cast<double>(gain) / std::sqrt(available_actions[idx].effort);
            if (evaluation > best_score || 
               (evaluation == best_score && optimal_action_index != -1 && 
                available_actions[idx].effort < available_actions[optimal_action_index].effort)) {
                best_score = evaluation;
                optimal_action_index = idx;
            }
        }

        if (optimal_action_index == -1) break;

        const auto& chosen = available_actions[optimal_action_index];

        if (chosen.direction == 'U') {
            for (int step = 0; step < chosen.depth / 2; ++step) {
                solution_sequence.push_back({'U', chosen.position});
            }
            for (int step = 0; step < chosen.depth / 2; ++step) {
                solution_sequence.push_back({'D', chosen.position});
            }
        } else if (chosen.direction == 'D') {
            for (int step = 0; step < (GRID_SIZE - chosen.depth / 2); ++step) {
                solution_sequence.push_back({'D', chosen.position});
            }
            for (int step = 0; step < (GRID_SIZE - chosen.depth / 2); ++step) {
                solution_sequence.push_back({'U', chosen.position});
            }
        } else if (chosen.direction == 'L') {
            for (int step = 0; step < chosen.depth / 2; ++step) {
                solution_sequence.push_back({'L', chosen.position});
            }
            for (int step = 0; step < chosen.depth / 2; ++step) {
                solution_sequence.push_back({'R', chosen.position});
            }
        } else if (chosen.direction == 'R') {
            for (int step = 0; step < (GRID_SIZE - chosen.depth / 2); ++step) {
                solution_sequence.push_back({'R', chosen.position});
            }
            for (int step = 0; step < (GRID_SIZE - chosen.depth / 2); ++step) {
                solution_sequence.push_back({'L', chosen.position});
            }
        }

        for (int pid : chosen.affected_pieces) {
            if (!status[pid]) {
                status[pid] = true;
                cleared_count++;
            }
        }
    }

    for (const auto& step : solution_sequence) {
        std::cout << step.dir << " " << step.idx << "\n";
    }

    return 0;
}

