namespace ros2_medkit_gateway {

TypeIntrospection::TypeIntrospection(const std::string & /* scripts_path */)
  : serializer_(std::make_shared<ros2_medkit_serialization::JsonSerializer>()) {
  // scripts_path is deprecated and ignored - we use native serialization now
}

nlohmann::json TypeIntrospection::get_type_template(const std::string & type_name) {
  try {
    return serializer_->get_defaults(type_name);
  } catch (const ros2_medkit_serialization::TypeNotFoundError & e) {
    throw std::runtime_error("Unknown type: " + type_name + " (" + e.what() + ")");
  } catch (const std::exception & e) {
    throw std::runtime_error("Failed to retrieve type template: " + std::string(e.what()));
  }
}

nlohmann::json TypeIntrospection::get_type_schema(const std::string & type_name) {
  try {
    return serializer_->get_schema(type_name);
  } catch (const ros2_medkit_serialization::TypeNotFoundError & e) {
    throw std::runtime_error("Unknown type: " + type_name + " (" + e.what() + ")");
  } catch (const std::exception & e) {
    throw std::runtime_error("Failed to retrieve type schema: " + std::string(e.what()));
  }
}

TopicTypeInfo TypeIntrospection::get_type_info(const std::string & type_name) {
  // Attempt to fetch from cache first
  {
    std::lock_guard<std::mutex> guard(cache_mutex_);
    auto iter = type_cache_.find(type_name);
    if (iter != type_cache_.end()) {
      return iter->second;
    }
  }

  // Construct new type info if not cached
  TopicTypeInfo result;
  result.name = type_name;

  // Populate default value
  try {
    result.default_value = get_type_template(type_name);
  } catch (...) {
    result.default_value = nlohmann::json::object();
  }

  // Populate schema
  try {
    result.schema = get_type_schema(type_name);
  } catch (...) {
    result.schema = nlohmann::json::object();
  }

  // Insert into cache and return (use try_emplace for thread-safety)
  {
    std::lock_guard<std::mutex> guard(cache_mutex_);
    auto [iter, inserted] = type_cache_.try_emplace(type_name, result);
    return iter->second;
  }
}

