#include "ConcertServerSequencerManager.h"
#include "IConcertSession.h"
#include "ConcertSyncServerLiveSession.h"

FConcertServerSequencerManager::FConcertServerSequencerManager(const TSharedRef<FConcertSyncServerLiveSession>& InSessionRef)
{
	EstablishSessionBinding(InSessionRef);
}

FConcertServerSequencerManager::~FConcertServerSequencerManager()
{
	ClearSessionBinding();
}

void FConcertServerSequencerManager::EstablishSessionBinding(const TSharedRef<FConcertSyncServerLiveSession>& InSessionRef)
{
	check(InSessionRef->IsValidSession());
	ClearSessionBinding();

	ActiveSession = InSessionRef;

	auto& SessionRef = ActiveSession->GetSession();
	SessionRef.OnSessionClientChanged().AddRaw(this, &FConcertServerSequencerManager::OnClientStatusChange);
	SessionRef.RegisterCustomEventHandler<FConcertSequencerOpenEvent>(this, &FConcertServerSequencerManager::OnSequencerOpened);
	SessionRef.RegisterCustomEventHandler<FConcertSequencerStateEvent>(this, &FConcertServerSequencerManager::OnSequencerStateUpdated);
	SessionRef.RegisterCustomEventHandler<FConcertSequencerCloseEvent>(this, &FConcertServerSequencerManager::OnSequencerClosed);
}

void FConcertServerSequencerManager::ClearSessionBinding()
{
	if (ActiveSession.IsValid())
	{
		auto& SessionRef = ActiveSession->GetSession();
		SessionRef.OnSessionClientChanged().RemoveAll(this);
		SessionRef.UnregisterCustomEventHandler<FConcertSequencerOpenEvent>(this);
		SessionRef.UnregisterCustomEventHandler<FConcertSequencerCloseEvent>(this);
		SessionRef.UnregisterCustomEventHandler<FConcertSequencerStateEvent>(this);
		ActiveSession.Reset();
	}
}

void FConcertServerSequencerManager::OnSequencerStateUpdated(const FConcertSessionContext& EventCtx, const FConcertSequencerStateEvent& Event)
{
	FConcertOpenSequencerState& StateRef = SequencerDataMap.FindOrAdd(*Event.State.SequenceObjectPath);
	StateRef.ClientIds.EmplaceUnique(EventCtx.SourceEndpointId);
	StateRef.CurrentState = Event.State;

	TArray<FGuid> TargetClients;
	ActiveSession->GetSession().GetSessionClientEndpointIds(TargetClients);
	TargetClients.RemoveSwap(EventCtx.SourceEndpointId);

	ActiveSession->GetSession().SendCustomEvent(Event, TargetClients, EConcertMessageFlags::ReliableOrdered | EConcertMessageFlags::UniqueId);
}

void FConcertServerSequencerManager::OnSequencerOpened(const FConcertSessionContext& EventCtx, const FConcertSequencerOpenEvent& Event)
{
	FConcertOpenSequencerState& StateRef = SequencerDataMap.FindOrAdd(*Event.SequenceObjectPath);
	StateRef.ClientIds.EmplaceUnique(EventCtx.SourceEndpointId);
	StateRef.CurrentState.SequenceObjectPath = Event.SequenceObjectPath;

	TArray<FGuid> TargetClients;
	ActiveSession->GetSession().GetSessionClientEndpointIds(TargetClients);
	TargetClients.RemoveSwap(EventCtx.SourceEndpointId);

	ActiveSession->GetSession().SendCustomEvent(Event, TargetClients, EConcertMessageFlags::ReliableOrdered | EConcertMessageFlags::UniqueId);
}

void FConcertServerSequencerManager::OnSequencerClosed(const FConcertSessionContext& EventCtx, const FConcertSequencerCloseEvent& Event)
{
	FConcertOpenSequencerState* pState = SequencerDataMap.Find(*Event.SequenceObjectPath);
	if (pState)
	{
		pState->ClientIds.Remove(EventCtx.SourceEndpointId);

		if (pState->ClientIds.IsEmpty())
		{
			FConcertSequencerCloseEvent FinalClose;
			FinalClose.bMasterClose = false;
			FinalClose.SequenceObjectPath = Event.SequenceObjectPath;

			TArray<FGuid> AllClients;
			ActiveSession->GetSession().GetSessionClientEndpointIds(AllClients);
			ActiveSession->GetSession().SendCustomEvent(FinalClose, AllClients,
				EConcertMessageFlags::ReliableOrdered | EConcertMessageFlags::UniqueId);

			SequencerDataMap.Remove(*Event.SequenceObjectPath);
		}
		else if (Event.bMasterClose)
		{
			TArray<FGuid> AllClients;
			ActiveSession->GetSession().GetSessionClientEndpointIds(AllClients);
			ActiveSession->GetSession().SendCustomEvent(Event, AllClients,
				EConcertMessageFlags::ReliableOrdered | EConcertMessageFlags::UniqueId);
		}
	}
}

void FConcertServerSequencerManager::OnClientStatusChange(IConcertServerSession& SessionRef, EConcertClientStatus Status, const FConcertSessionClientInfo& ClientInfo)
{
	check(&SessionRef == &ActiveSession->GetSession());

	if (Status == EConcertClientStatus::Disconnected)
	{
		for (auto It = SequencerDataMap.CreateIterator(); It; ++It)
		{
			It->Value.ClientIds.RemoveSwap(ClientInfo.ClientEndpointId);
			if (It->Value.ClientIds.IsEmpty())
			{
				FConcertSequencerCloseEvent CloseMsg;
				CloseMsg.SequenceObjectPath = It->Key.ToString();

				TArray<FGuid> RemainingClients;
				ActiveSession->GetSession().GetSessionClientEndpointIds(RemainingClients);
				ActiveSession->GetSession().SendCustomEvent(CloseMsg, RemainingClients,
					EConcertMessageFlags::ReliableOrdered | EConcertMessageFlags::UniqueId);

				It.RemoveCurrent();
			}
		}
	}
	else // Client connected
	{
		FConcertSequencerStateSyncEvent SyncMsg;
		for (const auto& Pair : SequencerDataMap)
		{
			SyncMsg.SequencerStates.Add(Pair.Value.CurrentState);
		}
		ActiveSession->GetSession().SendCustomEvent(SyncMsg, ClientInfo.ClientEndpointId, EConcertMessageFlags::ReliableOrdered);
	}
}

