// Evaluate expressions combining arithmetic comparisons with logical operators
void evaluate_arithmetic_boolean_mix(SMTParser::ParserPtr& p) {
    std::vector<std::string> tests = {
        "(and (> ab_x 0) (< ab_y 10))",
        "(or (= ab_x ab_y) (and (> ab_x 0) (< ab_y 0)))",
        "(=> (>= ab_x 0) (>= (+ ab_x ab_y) ab_y))",
        "(ite (> ab_x 0) (+ ab_x ab_y) (- ab_x ab_y))",
        "(and (= (+ ab_x ab_y) ab_z) (or (> ab_x 0) (< ab_y 0)))"
    };

    std::cout << "=== Arithmetic + Boolean Logic Evaluation ===" << std::endl;

    try {
        p->mkVarInt("ab_x");
        p->mkVarInt("ab_y");
        p->mkVarInt("ab_z");

        for (size_t idx = 0; idx < tests.size(); ++idx) {
            std::cout << "Input: " << tests[idx] << std::endl;
            auto node = p->mkExpr(tests[idx]);
            assert(node && !node->isErr());
            std::cout << "Output: " << p->toString(node) << "\n\n";
        }
    } catch (const std::exception& ex) {
        std::cerr << "Error during variable setup: " << ex.what() << std::endl;
    }
}

// Test interaction between array operations and integer arithmetic
void evaluate_array_arithmetic_mix(SMTParser::ParserPtr& p) {
    std::vector<std::string> cases = {
        "(select aa_a (+ aa_i 1))",
        "(store aa_a (* 2 aa_i) (+ aa_j 5))",
        "(= (store aa_a aa_i (+ aa_j 1)) (store aa_a aa_i (+ 1 aa_j)))",
        "(> (select aa_a aa_i) (select aa_a aa_j))",
        "(forall ((aa_k Int)) (=> (and (>= aa_k 0) (< aa_k 10)) (>= (select aa_a aa_k) 0)))"
    };

    std::cout << "=== Array + Arithmetic Interaction Check ===" << std::endl;

    try {
        auto intSort = SMTParser::SortManager::INT_SORT;
        p->mkArray("aa_a", intSort, intSort);
        p->mkVarInt("aa_i");
        p->mkVarInt("aa_j");
        p->mkVarInt("aa_k");

        size_t i = 0;
        while (i < cases.size()) {
            std::cout << "Formula: " << cases[i] << std::endl;
            auto res = p->mkExpr(cases[i]);
            assert(res && !res->isErr());
            std::cout << "Parsed: " << p->toString(res) << "\n\n";
            ++i;
        }
    } catch (const std::exception& e) {
        std::cerr << "Exception in setup: " << e.what() << std::endl;
    }
}

// Verify bitvector operations across different contexts
void evaluate_bitvector_scenarios(SMTParser::ParserPtr& p) {
    std::vector<std::string> scenarios = {
        "(= #b1010 #b1010)",
        "(bvult #b1010 #b1100)",
        "(= (bv2nat #b1010) 10)",
        "(select bv_a #b1010)",
        "(and (bvult bv_x bv_y) (= (select bv_a bv_x) #b0101))"
    };

    std::cout << "=== Bitvector Context Validation ===" << std::endl;

    try {
        auto fourBit = p->mkBVSort(4);
        p->mkVarBv("bv_x", 4);
        p->mkVarBv("bv_y", 4);
        p->mkArray("bv_a", fourBit, fourBit);

        for (const auto& expr : scenarios) {
            std::cout << "Expression: " << expr << std::endl;
            auto parsed = p->mkExpr(expr);
            assert(parsed && !parsed->isErr());
            std::cout << "Result: " << p->toString(parsed) << "\n\n";
        }
    } catch (const std::exception& err) {
        std::cerr << "Setup failure: " << err.what() << std::endl;
    }
}

// Examine string theory interactions with other domains
void evaluate_string_interactions(SMTParser::ParserPtr& p) {
    std::vector<std::string> inputs = {
        "(= \"hello\" \"world\")",
        "(= (str.len str_s) 5)",
        "(= (str.at str_s str_i) \"a\")",
        "(select str_a \"key\")",
        "(and (str.prefixof \"pre\" str_s) (> (str.indexof str_s \"x\" 0) (+ str_i str_j)))"
    };

    std::cout << "=== String Theory Interactions ===" << std::endl;

    try {
        auto strSort = SMTParser::SortManager::STR_SORT;
        auto intSort = SMTParser::SortManager::INT_SORT;

        p->mkVarStr("str_s");
        p->mkVarInt("str_i");
        p->mkVarInt("str_j");
        p->mkArray("str_a", strSort, intSort);

        size_t k = 0;
        do {
            std::cout << "Input: " << inputs[k] << std::endl;
            auto output = p->mkExpr(inputs[k]);
            assert(output && !output->isErr());
            std::cout << "Parsed: " << p->toString(output) << "\n\n";
            ++k;
        } while (k < inputs.size());
    } catch (const std::exception& ex) {
        std::cerr << "Declaration error: " << ex.what() << std::endl;
    }
}

// Validate quantified formulas across multiple theories
void evaluate_quantifier_cases(SMTParser::ParserPtr& p) {
    std::vector<std::string> formulas = {
        "(forall ((qt_i Int)) (=> (and (>= qt_i 0) (< qt_i 10)) (= (select qt_a qt_i) 0)))",
        "(exists ((qt_x (_ BitVec 4))) (= (bvadd qt_x #b0001) qt_y))",
        "(forall ((qt_c String)) (=> (= (str.len qt_c) 1) (str.contains qt_s qt_c)))",
        "(forall ((qt_i Int)) (exists ((qt_j Int)) (and (< qt_i qt_j) (= (select qt_a qt_i) (select qt_a qt_j)))))",
        "(exists ((qt_x Int) (qt_y Int)) (and (> qt_x 0) (< qt_y 10) (= (select qt_a qt_x) (select qt_a qt_y))))"
    };

    std::cout << "=== Quantifiers Across Theories ===" << std::endl;

    try {
        auto intSort = p->mkIntSort();
        auto bv4 = p->mkBVSort(4);
        auto strSort = p->mkStrSort();

        p->mkArray("qt_a", intSort, intSort);
        p->mkVarBv("qt_y", 4);
        p->mkVarStr("qt_s");

        for (const auto& f : formulas) {
            std::cout << "Formula: " << f << std::endl;
            auto result = p->mkExpr(f);
            assert(result && !result->isErr());
            std::cout << "Parsed: " << p->toString(result) << "\n\n";
        }
    } catch (const std::exception& e) {
        std::cerr << "Setup exception: " << e.what() << std::endl;
    }
}

// Demonstrate realistic combined-theory constraints
void evaluate_realistic_constraints(SMTParser::ParserPtr& p) {
    std::vector<std::string> examples = {
        "(and (= rw_x (+ rw_y 5)) (= rw_z (* 2 rw_x)) (> rw_z 20))",
        "(=> (and (>= rw_i 0) (< rw_i (select rw_a rw_array_length))) (>= (select rw_a rw_i) 0))",
        "(and (>= (str.len rw_password) 8) (str.contains rw_password \"A\") (not (= rw_password \"password\")))",
        "(= (bvxor (bvand rw_bv_x rw_bv_y) (bvor rw_bv_x rw_bv_y)) rw_expected)"
    };

    std::cout << "=== Real-World Combined Constraints ===" << std::endl;

    try {
        auto intSort = p->mkIntSort();
        auto bv32 = p->mkBVSort(32);
        auto strSort = p->mkStrSort();

        p->mkVarInt("rw_x");
        p->mkVarInt("rw_y");
        p->mkVarInt("rw_z");
        p->mkVarInt("rw_i");
        p->mkVarInt("rw_n");
        p->mkVarInt("rw_max_val");
        p->mkVarInt("rw_array_length");
        p->mkArray("rw_a", intSort, intSort);
        p->mkVarStr("rw_password");
        p->mkVarBv("rw_bv_x", 32);
        p->mkVarBv("rw_bv_y", 32);
        p->mkVarBv("rw_expected", 32);

        for (const auto& ex : examples) {
            std::cout << "Constraint: " << ex << std::endl;
            auto parsed = p->mkExpr(ex);
            assert(parsed && !parsed->isErr());
            std::cout << "Parsed: " << p->toString(parsed) << "\n\n";
        }
    } catch (const std::exception& e) {
        std::cerr << "Error during setup: " << e.what() << std::endl;
    }
}

int main() {
    std::cout << "======= Combined Theory Tests =======" << std::endl;

    auto parser = SMTParser::newParser();

    evaluate_arithmetic_boolean_mix(parser);
    evaluate_array_arithmetic_mix(parser);
    evaluate_bitvector_scenarios(parser);
    evaluate_string_interactions(parser);
    evaluate_quantifier_cases(parser);
    evaluate_realistic_constraints(parser);

    return 0;
}

#include "Utils/LLVM/Scheduler/ParallelSchedulerPass.h"
#include "Utils/LLVM/Scheduler/PipelineScheduler.h"
#include <llvm/Analysis/CallGraph.h>
