#define DEBUG_TYPE "ParallelSchedulerPass"

using namespace llvm;

char ParallelSchedulerPass::ID = 0;
static RegisterPass<ParallelSchedulerPass>
    Y(DEBUG_TYPE, "Parallel Scheduler Pass for Generic Analysis");

ParallelSchedulerPass::ParallelSchedulerPass()
    : ModulePass(ID), PassName("Parallel Scheduler"), SchedulerMode(1),
      UseGC(true) {}

ParallelSchedulerPass::~ParallelSchedulerPass() {}

void ParallelSchedulerPass::getAnalysisUsage(AnalysisUsage &AU) const {
  AU.setPreservesAll();
  AU.addRequired<CallGraphWrapperPass>();
}

bool ParallelSchedulerPass::runOnModule(Module &M) {
  if (!UserCallback) {
    errs() << "Error: No analysis callback set for ParallelSchedulerPass!\n";
    return false;
  }

  llvm::outs() << "Executing " << PassName << " on module " << M.getName() << "\n";

  // Retrieve call graph
  CallGraph &CallGraphRef = getAnalysis<CallGraphWrapperPass>().getCallGraph();

  // Select analysis strategy
  PipelineScheduler::StrategyType ST;
  switch (SchedulerMode) {
  case 0:
    ST = PipelineScheduler::ST_Local;
    llvm::outs() << "Strategy: Local\n";
    break;
  case 1:
    ST = PipelineScheduler::ST_BottomUp;
    llvm::outs() << "Strategy: Bottom-up\n";
    break;
  case 2:
    ST = PipelineScheduler::ST_TopDown;
    llvm::outs() << "Strategy: Top-down\n";
    break;
  default:
    ST = PipelineScheduler::ST_BottomUp;
  }

  // Initialize and configure scheduler
  PipelineScheduler Scheduler(M, CallGraphRef, ST);
  Scheduler.setTaskHandler(UserCallback);

  if (GarbageCollectionCallback && UseGC) {
    Scheduler.setGarbageCollectionHandler(GarbageCollectionCallback);
  } else {
    Scheduler.disableGarbageCollection();
  }

  // Execute scheduling
  Scheduler.execute();
  llvm::outs() << "Parallel scheduling finished successfully!\n";
  return false; // Module remains unmodified
}

#include <sol/sol.hpp>
#include <iostream>
#include <memory>

// Renamed struct with equivalent semantics
struct Canine {
    int tail_flick = 50;

    Canine() = default;

    explicit Canine(int flicks) : tail_flick(flicks) {}

    ~Canine() {
        std::cout << "Canine at " << this
                  << " is being deallocated..." << std::endl;
    }
};

int main([[maybe_unused]] int argc, [[maybe_unused]] char* argv[]) {
    std::cout << "=== userdata ===" << std::endl;

    sol::state vm;

    // Initialize local instances
    Canine pup { 30 };

    // Insert into Lua: value semantics (copy)
    vm["pup"] = Canine{};
    vm["pup_copy"] = pup;
    vm["pup_moved"] = std::move(pup);

    // Smart pointer variants
    vm["pup_unique"] = std::make_unique<Canine>(25);
    vm["pup_shared"] = std::make_shared<Canine>(31);

    // Second set via .set()
    Canine hound { 30 };
    vm.set("hound", Canine{});
    vm.set("hound_copy", hound);
    vm.set("hound_moved", std::move(hound));
    vm.set("hound_unique", std::unique_ptr<Canine>(new Canine(25)));
    vm.set("hound_shared", std::shared_ptr<Canine>(new Canine(31)));

    // Retrieve references from Lua state
    Canine& ref_pup = vm["pup"];
    Canine& ref_pup_copy = vm["pup_copy"];
    Canine& ref_pup_moved = vm["pup_moved"];
    Canine& ref_pup_unique = vm["pup_unique"];
    Canine& ref_pup_shared = vm["pup_shared"];

    // Validate tail flick counts
    static_assert(std::is_same_v<decltype(ref_pup.tail_flick), int>);
    SOL_ASSERT(ref_pup.tail_flick == 50);
    SOL_ASSERT(ref_pup_copy.tail_flick == 30);
    SOL_ASSERT(ref_pup_moved.tail_flick == 30);
    SOL_ASSERT(ref_pup_unique.tail_flick == 25);
    SOL_ASSERT(ref_pup_shared.tail_flick == 31);

    // Lambda that accepts by reference (no nil handling)
    vm["greet_dog"] = [](Canine& dog) {
        std::cout << "dog flicks its tail " << dog.tail_flick
                  << " times!" << std::endl;
    };

    // Lambda accepting pointer for optional argument support
    vm["safe_greet"] = [](Canine* dog) {
        if (!dog) {
            std::cout << "dog was nil!" << std::endl;
            return;
        }
        std::cout << "dog flicks its tail " << dog->tail_flick
                  << " times!" << std::endl;
    };

    // Execute script using renamed functions and variables
    vm.script(R"(
        greet_dog(pup)
        greet_dog(pup_copy)
        greet_dog(pup_moved)
        greet_dog(pup_unique)
        greet_dog(pup_shared)

        safe_greet(pup)
        safe_greet(pup_copy)
        safe_greet(pup_moved)
        safe_greet(pup_unique)
        safe_greet(pup_shared)
        safe_greet(nil)
        -- Do NOT call greet_dog(nil)
    )");

    std::cout << std::endl;
    return 0;
}

