// Process a single function: extract loop info, run analysis, store results
bool IRGenerator::runOnFunction(llvm::Function &F) {
  // Retrieve loop information for the current function
  auto &loopInfoWrapper = getAnalysis<llvm::LoopInfoWrapperPass>();
  const auto &loopInfo = loopInfoWrapper.getLoopInfo();

  // Perform typestate analysis on the function using loop context
  analyzer.analyze(F, loopInfo);

  // Store the resulting framework-level function representation
  auto module = F.getParent();
  framework_ir_[module].insert(analyzer.FrameworkFunction());

  return false; // Indicate that no modifications were made to the function
}

