#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <random>
#include <chrono>
#include <numeric>
using namespace std;

// Clause structure: each clause has two literals
struct Clause {
    int lit1, lit2;
};

int num_vars, num_clauses;
vector<Clause> clause_list;
vector<vector<int>> var_occurrence; // For each variable, list of clause indices where it appears

// Current solution state
vector<int> current_solution; // 1-indexed: 0 = false, 1 = true
vector<int> clause_satisfaction; // Number of satisfied literals per clause
int satisfied_clauses_count = 0;

// Best solution found so far
vector<int> best_solution;
int best_score = -1;

// Helper: check if a literal is satisfied under given assignment
inline bool literal_satisfied(int literal, const vector<int>& assign) {
    int var = abs(literal);
    int value = assign[var];
    return (literal > 0) ? (value == 1) : (value == 0);
}

// Recompute all clause satisfaction from scratch
void rebuild_state() {
    satisfied_clauses_count = 0;
    for (int i = 0; i < num_clauses; ++i) {
        int count = 0;
        if (literal_satisfied(clause_list[i].lit1, current_solution)) count++;
        if (literal_satisfied(clause_list[i].lit2, current_solution)) count++;
        clause_satisfaction[i] = count;
        if (count > 0) satisfied_clauses_count++;
    }
}

// Estimate change in satisfied clauses if variable `var` is flipped
inline int evaluate_flip(int var) {
    int delta = 0;
    int old_val = current_solution[var];
    int new_val = 1 - old_val;

    for (int c_idx : var_occurrence[var]) {
        int prev_sat = clause_satisfaction[c_idx];
        int l1 = clause_list[c_idx].lit1;
        int l2 = clause_list[c_idx].lit2;

        int old_contrib = 0, new_contrib = 0;

        if (abs(l1) == var) {
            old_contrib += (l1 > 0 ? old_val : 1 - old_val);
            new_contrib += (l1 > 0 ? new_val : 1 - new_val);
        }
        if (abs(l2) == var) {
            old_contrib += (l2 > 0 ? old_val : 1 - old_val);
            new_contrib += (l2 > 0 ? new_val : 1 - new_val);
        }

        int updated_sat = prev_sat - old_contrib + new_contrib;

        if (prev_sat == 0 && updated_sat > 0) delta++;
        else if (prev_sat > 0 && updated_sat == 0) delta--;
    }
    return delta;
}

// Apply variable flip and update internal state
inline void apply_flip(int var) {
    int old_val = current_solution[var];
    int new_val = 1 - old_val;
    current_solution[var] = new_val;

    for (int c_idx : var_occurrence[var]) {
        int prev_sat = clause_satisfaction[c_idx];
        int l1 = clause_list[c_idx].lit1;
        int l2 = clause_list[c_idx].lit2;

        int old_contrib = 0, new_contrib = 0;

        if (abs(l1) == var) {
            old_contrib += (l1 > 0 ? old_val : 1 - old_val);
            new_contrib += (l1 > 0 ? new_val : 1 - new_val);
        }
        if (abs(l2) == var) {
            old_contrib += (l2 > 0 ? old_val : 1 - old_val);
            new_contrib += (l2 > 0 ? new_val : 1 - new_val);
        }

        int updated_sat = prev_sat - old_contrib + new_contrib;

        if (prev_sat == 0 && updated_sat > 0) satisfied_clauses_count++;
        else if (prev_sat > 0 && updated_sat == 0) satisfied_clauses_count--;

        clause_satisfaction[c_idx] = updated_sat;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> num_vars >> num_clauses)) return 0;

    clause_list.resize(num_clauses);
    var_occurrence.resize(num_vars + 1);

    for (int i = 0; i < num_clauses; ++i) {
        cin >> clause_list[i].lit1 >> clause_list[i].lit2;
        int v1 = abs(clause_list[i].lit1);
        int v2 = abs(clause_list[i].lit2);

        var_occurrence[v1].push_back(i);
        if (v2 != v1) {
            var_occurrence[v2].push_back(i);
        }
    }

    // Edge case: no clauses — any assignment works
    if (num_clauses == 0) {
        for (int i = 1; i <= num_vars; ++i) {
            cout << 0 << (i == num_vars ? "" : " ");
        }
        cout << "\n";
        return 0;
    }

    current_solution.assign(num_vars + 1, 0);
    clause_satisfaction.assign(num_clauses, 0);
    best_solution.assign(num_vars + 1, 0);

    // Random number generator setup
    unsigned seed = chrono::steady_clock::now().time_since_epoch().count();
    mt19937 rng(seed);

    // Initial random assignment
    for (int i = 1; i <= num_vars; ++i) {
        current_solution[i] = rng() % 2;
    }
    rebuild_state();

    best_solution = current_solution;
    best_score = satisfied_clauses_count;

    auto start = chrono::steady_clock::now();

    vector<int> variables(num_vars);
    iota(variables.begin(), variables.end(), 1);

    while (true) {
        auto now = chrono::steady_clock::now();
        double elapsed = chrono::duration<double>(now - start).count();
        if (elapsed > 0.95) break;

        // Local search phase
        bool improved = true;
        while (improved) {
            improved = false;
            shuffle(variables.begin(), variables.end(), rng);

            for (int v : variables) {
                if (evaluate_flip(v) > 0) {
                    apply_flip(v);
                    improved = true;
                    if (satisfied_clauses_count > best_score) {
                        best_score = satisfied_clauses_count;
                        best_solution = current_solution;
                    }
                }
            }
        }

        if (best_score == num_clauses) break;

        // Perturbation / restart strategy
        if (rng() % 100 < 10) {
            // Full random restart
            for (int i = 1; i <= num_vars; ++i) {
                current_solution[i] = rng() % 2;
            }
            rebuild_state();
        } else {
            // Partial perturbation: flip a few random variables
            int flips = 1 + rng() % max(1, num_vars / 20);
            for (int i = 0; i < flips; ++i) {
                int idx = 1 + rng() % num_vars;
                apply_flip(idx);
            }
        }
    }

    // Output best assignment
    for (int i = 1; i <= num_vars; ++i) {
        cout << best_solution[i] << (i == num_vars ? "" : " ");
    }
    cout << "\n";

    return 0;
}

#include "BufferProcessor.hpp"
#include "Buffer.hpp"
#include "MayaFlux/Journal/Archivist.hpp"

namespace MayaFlux::Buffers {

void BufferProcessor::process(const std::shared_ptr<Buffer>& buffer)
{
    // Attempt to acquire processing rights; if failed, log error and exit early
    if (!buffer->try_acquire_processing()) {
        MF_RT_ERROR(Journal::Component::Buffers, Journal::Context::BufferProcessing,
            "Buffer is already being processed, skipping processor");
        return;
    }

    // Increment active processing counter atomically
    m_active_processing.fetch_add(1, std::memory_order_acquire);

    // Execute the processing logic with exception safety
    try {
        processing_function(buffer);
    } catch (...) {
        // Ensure proper cleanup on exception: release buffer and decrement counter
        buffer->release_processing();
        m_active_processing.fetch_sub(1, std::memory_order_release);
        throw;
    }

    // Normal completion: release buffer and decrement counter
    buffer->release_processing();
    m_active_processing.fetch_sub(1, std::memory_order_release);
}

void BufferProcessor::process_non_owning(const std::shared_ptr<Buffer>& buffer)
{
    // Increment active processing counter (no buffer ownership, so no acquire/release on buffer)
    m_active_processing.fetch_add(1, std::memory_order_acquire);

    try {
        processing_function(buffer);
    } catch (...) {
        // Decrement counter on exception before rethrowing
        m_active_processing.fetch_sub(1, std::memory_order_release);
        throw;
    }

    // Decrement counter after successful processing
    m_active_processing.fetch_sub(1, std::memory_order_release);
}

}

