#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int blackCount, whiteCount, temp1, temp2;
    if (!(cin >> blackCount >> whiteCount >> temp1 >> temp2)) return 0;

    // Handle the special case where counts are nearly equal
    if (abs(blackCount - whiteCount) <= 1) {
        int rows = 1;
        int cols = blackCount + whiteCount;
        cout << rows << " " << cols << "\n";

        bool firstColorIsBlack = (blackCount >= whiteCount);
        int placedBlack = 0, placedWhite = 0;

        for (int pos = 0; pos < cols; ++pos) {
            bool shouldPlaceBlack = ((pos % 2 == 0) ? firstColorIsBlack : !firstColorIsBlack);

            if (shouldPlaceBlack) {
                if (placedBlack < blackCount) {
                    cout << '@';
                    placedBlack++;
                } else {
                    cout << '.';
                    placedWhite++;
                }
            } else {
                if (placedWhite < whiteCount) {
                    cout << '.';
                    placedWhite++;
                } else {
                    cout << '@';
                    placedBlack++;
                }
            }
        }
        cout << "\n";
        return 0;
    }

    // General case: construct a 5-row grid
    int width = max(2 * blackCount - 1, 2 * whiteCount - 1);
    int height = 5;
    vector<string> grid(height, string(width, '@'));

    // Initialize top two rows as white cells
    for (int col = 0; col < width; ++col) {
        grid[0][col] = '.';
        grid[1][col] = '.';
    }

    // Place black islands in top section (row 0 at even columns)
    for (int i = 0; i < blackCount; ++i) {
        int column = 2 * i;
        grid[0][column] = '@';
        // Ensure adjacent separator columns remain white
        if (column + 1 < width) {
            grid[0][column + 1] = '.';
            grid[1][column + 1] = '.';
        }
    }

    // Place white islands in bottom section (row 3 at even columns)
    for (int i = 0; i < whiteCount; ++i) {
        int column = 2 * i;
        grid[3][column] = '.';
    }

    // Connect black islands to base by setting appropriate cell in row 1 to '@'
    int connectCol1;
    if (blackCount == 1) {
        connectCol1 = 0;
    } else {
        connectCol1 = 2 * (blackCount - 1);
    }
    grid[1][connectCol1] = '@';

    // Connect white island to upper white section via row 2
    int connectCol2;
    if (blackCount == 1) {
        connectCol2 = (whiteCount >= 2 ? 2 : 0);
    } else {
        connectCol2 = 0;
        if (connectCol2 == connectCol1) {
            if (whiteCount >= 2) {
                connectCol2 = 2;
            } else {
                // Expand grid when needed
                int oldWidth = width;
                width += 2;
                for (int r = 0; r < height; ++r) {
                    grid[r].resize(width, '@');
                }
                grid[0].replace(oldWidth, 2, "..");
                grid[1].replace(oldWidth, 2, "..");
                connectCol2 = oldWidth;
                grid[3][connectCol2] = '.';
            }
        }
    }

    // Ensure connection column is valid
    if (connectCol2 >= width) {
        connectCol2 = (whiteCount >= 1 ? 2 * (whiteCount - 1) : 0);
        if (connectCol2 >= width) connectCol2 = 0;
    }

    // Make separator cell white to connect white island
    grid[2][connectCol2] = '.';

    // Output result
    cout << height << " " << width << "\n";
    for (int row = 0; row < height; ++row) {
        cout << grid[row] << "\n";
    }

    return 0;
}

