PubAckPacket::PubAckPacket(ParsingInformation* parsingInfo, OnPubAckInternalCallback onAck)
: _parsingInfo(parsingInfo)
, _onAck(onAck)
, _state(0)
, _highByte(0)
, _packetIdValue(0) {
}

PubAckPacket::~PubAckPacket() {
}

void PubAckPacket::processVariableHeader(char* buffer, size_t size, size_t* position) {
    char current = buffer[(*position)++];

    if (_state == 0) {
        _highByte = static_cast<uint8_t>(current);
        _state = 1;
    } else {
        uint8_t lowByte = static_cast<uint8_t>(current);
        _packetIdValue = (_highByte << 8) | lowByte;

        _parsingInfo->bufferState = BufferState::NONE;
        _onAck(_packetIdValue);
    }
}

void PubAckPacket::processPayload(char*, size_t, size_t*) {
    // PUBACK packets have no payload - intentionally empty
