// Synthesize audio from an Ogg packet
int vorbis_synthesis(vorbis_block *block, ogg_packet *pkt) {
    vorbis_dsp_state     *dsp = block->vd;
    private_state        *backend = dsp->backend_state;
    vorbis_info          *info = dsp->vi;
    codec_setup_info     *setup = info->codec_setup;
    oggpack_buffer       *buf = &block->opb;
    int                   map_type, mode_idx, ch, nch = info->channels;

    // Prepare block for decoding
    _vorbis_block_ripcord(block);
    oggpack_readinit(buf, pkt->packet, pkt->bytes);

    // Validate packet type
    if (oggpack_read(buf, 1) != 0) {
        return OV_ENOTAUDIO; // Not audio data
    }

    // Decode mode index
    mode_idx = oggpack_read(buf, backend->modebits);
    if (mode_idx < 0) return OV_EBADPACKET;

    block->mode = mode_idx;
    block->W = setup->mode_param[mode_idx]->blockflag;

    // Handle window flags based on block size flag
    if (block->W) {
        block->lW = oggpack_read(buf, 1);
        block->nW = oggpack_read(buf, 1);
        if (block->nW < 0) return OV_EBADPACKET;
    } else {
        block->lW = 0;
        block->nW = 0;
    }

    // Set metadata fields
    block->granulepos = pkt->granulepos;
    block->sequence   = pkt->packetno;
    block->eofflag    = pkt->e_o_s;

    // Allocate PCM buffers
    block->pcmend = setup->blocksizes[block->W];
    block->pcm = static_cast<float**>(_vorbis_block_alloc(block, sizeof(*block->pcm) * nch));
    for (ch = 0; ch < nch; ++ch) {
        block->pcm[ch] = static_cast<float*>(_vorbis_block_alloc(block, block->pcmend * sizeof(*block->pcm[ch])));
    }

    // Dispatch to appropriate mapping inverse function
    map_type = setup->map_type[setup->mode_param[mode_idx]->mapping];
    return setup->map_param[setup->mode_param[mode_idx]->mapping]
           ? _mapping_P[map_type]->inverse(block, setup->map_param[setup->mode_param[mode_idx]->mapping])
           : -1;
}

// Track PCM position without decoding samples (fast-forward)
int vorbis_synthesis_trackonly(vorbis_block *block, ogg_packet *pkt) {
    vorbis_dsp_state     *dsp = block->vd;
    private_state        *backend = dsp->backend_state;
    vorbis_info          *info = dsp->vi;
    codec_setup_info     *setup = info->codec_setup;
    oggpack_buffer       *buf = &block->opb;
    int                   mode_idx;

    _vorbis_block_ripcord(block);
    oggpack_readinit(buf, pkt->packet, pkt->bytes);

    if (oggpack_read(buf, 1) != 0) {
        return OV_ENOTAUDIO;
    }

    mode_idx = oggpack_read(buf, backend->modebits);
    if (mode_idx < 0) return OV_EBADPACKET;

    block->mode = mode_idx;
    block->W = setup->mode_param[mode_idx]->blockflag;

    if (block->W) {
        block->lW = oggpack_read(buf, 1);
        block->nW = oggpack_read(buf, 1);
        if (block->nW < 0) return OV_EBADPACKET;
    } else {
        block->lW = 0;
        block->nW = 0;
    }

    block->granulepos = pkt->granulepos;
    block->sequence   = pkt->packetno;
    block->eofflag    = pkt->e_o_s;

    // Skip PCM allocation
    block->pcmend = 0;
    block->pcm    = nullptr;
    return 0;
}

// Compute block size directly from packet header (no full decode)
long vorbis_packet_blocksize(vorbis_info *info, ogg_packet *pkt) {
    codec_setup_info     *setup = info->codec_setup;
    oggpack_buffer        buf;
    int                   mode_idx, modebits = 0;
    int                   modes = setup->modes;

    // Compute required bits for mode index
    while (modes > 1) {
        modebits++;
        modes >>= 1;
    }

    oggpack_readinit(&buf, pkt->packet, pkt->bytes);

    if (oggpack_read(&buf, 1) != 0) {
        return OV_ENOTAUDIO;
    }

    mode_idx = oggpack_read(&buf, modebits);
    if (mode_idx < 0) return OV_EBADPACKET;

    return setup->blocksizes[setup->mode_param[mode_idx]->blockflag];
}

// Enable/disable half-sample-rate mode (MDCT downsampling)
int vorbis_synthesis_halfrate(vorbis_info *info, int enable) {
    codec_setup_info *setup = info->codec_setup;

    // Reject if smallest block too small for MDCT
    if (setup->blocksizes[0] <= 64 && enable) {
        return -1;
    }
    setup->halfrate_flag = enable ? 1 : 0;
    return 0;
}

// Query whether half-rate mode is active
int vorbis_synthesis_halfrate_p(vorbis_info *info) {
    return info->codec_setup->halfrate_flag;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <numeric>
#include <algorithm>
#include <iomanip>

// Disjoint Set Union with union-by-size and path compression
struct DSU {
    std::vector<int> parent;
    std::vector<int> size;
    int num_components;

    DSU(int n) : parent(n), size(n, 1), num_components(n) {
        std::iota(parent.begin(), parent.end(), 0);
    }

    DSU(const DSU& other) = default;

    int find_set(int x) {
        if (parent[x] != x) {
            parent[x] = find_set(parent[x]);
        }
        return parent[x];
    }

    void merge_sets(int a, int b) {
        int root_a = find_set(a);
        int root_b = find_set(b);

        if (root_a == root_b) return;

        if (size[root_a] < size[root_b]) {
            std::swap(root_a, root_b);
        }

        parent[root_b] = root_a;
        size[root_a] += size[root_b];
        --num_components;
    }
};

struct Coordinate {
    int x_coord;
    int y_coord;
};

struct Connection {
    int node1;
    int node2;
    int approx_dist; // Rounded Euclidean distance
};

// Edge in the component graph
struct ComponentLink {
    int comp_root1;
    int comp_root2;
    double weight;

    bool operator<(const ComponentLink& other) const {
        return weight < other.weight;
    }
};

double compute_distance(const Coordinate& pt1, const Coordinate& pt2) {
    long long diff_x = pt1.x_coord - pt2.x_coord;
    long long diff_y = pt1.y_coord - pt2.y_coord;
    return std::sqrt(static_cast<double>(diff_x * diff_x + diff_y * diff_y));
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    const int TOTAL_POINTS = 400;
    const int TOTAL_CONNECTIONS = 1995;

    std::vector<Coordinate> points(TOTAL_POINTS);
    for (int idx = 0; idx < TOTAL_POINTS; ++idx) {
        std::cin >> points[idx].x_coord >> points[idx].y_coord;
    }

    std::vector<Connection> connections(TOTAL_CONNECTIONS);
    for (int idx = 0; idx < TOTAL_CONNECTIONS; ++idx) {
        std::cin >> connections[idx].node1 >> connections[idx].node2;
        connections[idx].approx_dist = static_cast<int>(
            std::round(compute_distance(points[connections[idx].node1], 
                                       points[connections[idx].node2]))
        );
    }

    DSU dsu(TOTAL_POINTS);

    for (int step = 0; step < TOTAL_CONNECTIONS; ++step) {
        int threshold;
        std::cin >> threshold;

        int u_node = connections[step].node1;
        int v_node = connections[step].node2;
        int root_u = dsu.find_set(u_node);
        int root_v = dsu.find_set(v_node);

        if (root_u == root_v) {
            std::cout << "0\n";
            continue;
        }

        // Compute dynamic scaling factor based on processing progress
        double progress_ratio = static_cast<double>(step) / (TOTAL_CONNECTIONS - 1);
        double scaling_factor = 1.4 + 1.6 * progress_ratio * progress_ratio;

        std::vector<ComponentLink> candidate_links;
        if (step < TOTAL_CONNECTIONS - 1) {
            candidate_links.reserve(TOTAL_CONNECTIONS - step - 1);
        }

        for (int next_idx = step + 1; next_idx < TOTAL_CONNECTIONS; ++next_idx) {
            int comp_u = dsu.find_set(connections[next_idx].node1);
            int comp_v = dsu.find_set(connections[next_idx].node2);

            if (comp_u != comp_v) {
                candidate_links.push_back({
                    comp_u,
                    comp_v,
                    scaling_factor * connections[next_idx].approx_dist
                });
            }
        }

        std::sort(candidate_links.begin(), candidate_links.end());

        double min_path_weight = 1e18;
        if (!candidate_links.empty()) {
            DSU temp_dsu = dsu;
            for (const auto& link : candidate_links) {
                if (temp_dsu.find_set(link.comp_root1) != temp_dsu.find_set(link.comp_root2)) {
                    temp_dsu.merge_sets(link.comp_root1, link.comp_root2);

                    if (temp_dsu.find_set(root_u) == temp_dsu.find_set(root_v)) {
                        min_path_weight = link.weight;
                        break;
                    }
                }
            }
        }

        if (static_cast<double>(threshold) < min_path_weight) {
            std::cout << "1\n";
            dsu.merge_sets(u_node, v_node);
        } else {
            std::cout << "0\n";
        }
    }

    return 0;
}

