#include "let_fix.h"
#include <iostream>

namespace {
    int failureCount = 0;

    void verifyCondition(bool condition, const char* expr, int lineNumber) {
        if (!condition) {
            std::cout << "Assertion failed: " << expr 
                      << " at line " << lineNumber << std::endl;
            if (failureCount >= 0 && failureCount <= 100) {
                ++failureCount;
            }
        }
    }

    template <typename T>
    T getElementAt(const std::shared_ptr<List<T>>& list, unsigned int index) {
        auto current = list;
        for (unsigned int i = 0; i < index; ++i) {
            auto& consNode = std::get<typename List<T>::cons>(current->value());
            current = consNode._tail;
        }
        return std::get<typename List<T>::cons>(current->value())._head;
    }
} // unnamed namespace

#define VERIFY(X) \
    verifyCondition((X), #X, __LINE__)

int main() {
    // First verification block: sum of [1;2;3;4;5] should be 15
    {
        VERIFY(LetFix::test_sum == 15);
        std::cout << "First test (sum computation): SUCCESS" << std::endl;
    }

    // Second verification block: reverse of [1;2;3] should be [3;2;1]
    {
        VERIFY(getElementAt(LetFix::test_rev, 0U) == 3);
        VERIFY(getElementAt(LetFix::test_rev, 1U) == 2);
        VERIFY(getElementAt(LetFix::test_rev, 2U) == 1);
        std::cout << "Second test (list reversal): SUCCESS" << std::endl;
    }

    // Third verification block: membership tests
    {
        VERIFY(LetFix::test_mem_found == true);
        VERIFY(LetFix::test_mem_missing == false);
        std::cout << "Third test (membership check): SUCCESS" << std::endl;
    }

    // Fourth verification block: flatten nested lists [[1;2];[3];[4;5;6]] → [1;2;3;4;5;6]
    {
        VERIFY(getElementAt(LetFix::test_flatten, 0U) == 1);
        VERIFY(getElementAt(LetFix::test_flatten, 5U) == 6);
        std::cout << "Fourth test (list flattening): SUCCESS" << std::endl;
    }

    if (failureCount == 0) {
        std::cout << "\nAll let_fix tests completed successfully!" << std::endl;
    } else {
        std::cout << "\n" << failureCount << " test(s) encountered errors!" << std::endl;
    }

    return failureCount;
}

