STATISTIC(NumAggregateReconstructionsSimplified,
          "Number of aggregate reconstructions turned into reuse of the "
          "original aggregate");

// Determine if extracting a specific element from a vector operation is more 
// efficient than keeping it as a vector operation
static bool isScalarizationBeneficial(Value *VecVal, Value *ExtractIdx) {
  // If we have a constant extract index, check if the vector contains a splat
  if (auto *ConstVec = dyn_cast<Constant>(VecVal))
    return ConstVec->getSplatValue() != nullptr || isa<ConstantInt>(ExtractIdx);

  // Check for stepvector intrinsic which can be optimized
  ConstantInt *IdxConst = dyn_cast<ConstantInt>(ExtractIdx);
  if (IdxConst && match(VecVal, m_Intrinsic<Intrinsic::experimental_stepvector>())) {
    ElementCount EC = cast<VectorType>(VecVal->getType())->getElementCount();
    return IdxConst->getValue().ult(EC.getKnownMinValue());
  }

  // Insertelement operations simplify when extracting the inserted element
  if (match(VecVal, m_InsertElt(m_Value(), m_Value(), m_ConstantInt())))
    return IdxConst;

  // Single-use loads and unary operations benefit from scalarization
  if (match(VecVal, m_OneUse(m_Load(m_Value()))) ||
      match(VecVal, m_OneUse(m_UnOp())))
    return true;

  // Binary operations may benefit if either operand benefits
  Value *Op0, *Op1;
  if (match(VecVal, m_OneUse(m_BinOp(m_Value(Op0), m_Value(Op1)))))
    return isScalarizationBeneficial(Op0, ExtractIdx) || 
           isScalarizationBeneficial(Op1, ExtractIdx);

  // Comparison operations follow similar logic
  CmpInst::Predicate UnusedPred;
  if (match(VecVal, m_OneUse(m_Cmp(UnusedPred, m_Value(Op0), m_Value(Op1)))))
    return isScalarizationBeneficial(Op0, ExtractIdx) || 
           isScalarizationBeneficial(Op1, ExtractIdx);

  return false;
}

// Transform a vector PHI node into a scalar PHI when beneficial
Instruction *InstCombinerImpl::convertVectorPHIToScalar(ExtractElementInst &Ext,
                                                        PHINode *VectorPHI) {
  SmallVector<Instruction *, 2> ExtractUsers;
  Instruction *PHIOtherUser = nullptr;

  // Analyze users of the PHI node
  for (auto *User : VectorPHI->users()) {
    if (ExtractElementInst *ExtUser = dyn_cast<ExtractElementInst>(User)) {
      if (Ext.getIndexOperand() == ExtUser->getIndexOperand())
        ExtractUsers.push_back(ExtUser);
      else
        return nullptr; // Different indices not supported
    } else if (!PHIOtherUser) {
      PHIOtherUser = cast<Instruction>(User);
    } else {
      return nullptr; // Multiple non-extract users not supported
    }
  }

  if (!PHIOtherUser)
    return nullptr;

  // Verify the PHI user has exactly one use (the PHI itself) and is binary
  if (!PHIOtherUser->hasOneUse() || 
      PHIOtherUser->user_back() != VectorPHI ||
      !isa<BinaryOperator>(PHIOtherUser) ||
      !isScalarizationBeneficial(PHIOtherUser, Ext.getIndexOperand()))
    return nullptr;

  // Create new scalar PHI node
  PHINode *ScalarPHI = cast<PHINode>(InsertNewInstWith(
      PHINode::Create(Ext.getType(), VectorPHI->getNumIncomingValues(), ""), 
      VectorPHI->getIterator()));

  // Process each incoming value to the PHI
  for (unsigned i = 0; i < VectorPHI->getNumIncomingValues(); i++) {
    Value *PHIOperand = VectorPHI->getIncomingValue(i);
    BasicBlock *InBB = VectorPHI->getIncomingBlock(i);
    Value *ExtractIndex = Ext.getIndexOperand();

    if (PHIOperand == PHIOtherUser) {
      // Handle the binary operation case
      BinaryOperator *BinOp = cast<BinaryOperator>(PHIOtherUser);
      unsigned OpIdx = (BinOp->getOperand(0) == VectorPHI) ? 1 : 0;

      Value *Extracted = InsertNewInstWith(
          ExtractElementInst::Create(BinOp->getOperand(OpIdx), ExtractIndex,
                                    BinOp->getOperand(OpIdx)->getName() + ".elt"),
          BinOp->getIterator());

      Value *NewBinOp = InsertNewInstWith(
          BinaryOperator::CreateWithCopiedFlags(BinOp->getOpcode(),
                                               ScalarPHI, Extracted, BinOp), 
          BinOp->getIterator());
      ScalarPHI->addIncoming(NewBinOp, InBB);
    } else {
      // Scalarize the PHI input by extracting the element
      Instruction *NewExtract = ExtractElementInst::Create(PHIOperand, ExtractIndex, "");

      // Insert at appropriate position in predecessor block
      Instruction *Pos = dyn_cast<Instruction>(PHIOperand);
      BasicBlock::iterator InsertPos;
      if (Pos && !isa<PHINode>(Pos)) {
        InsertPos = ++Pos->getIterator();
      } else {
        InsertPos = InBB->getFirstInsertionPt();
      }
      InsertNewInstWith(NewExtract, InsertPos);
      ScalarPHI->addIncoming(NewExtract, InBB);
    }
  }

  // Replace all extract users with the new scalar PHI
  for (auto *ExtUser : ExtractUsers) {
    replaceInstUsesWith(*ExtUser, ScalarPHI);
    addToWorklist(ExtUser);
  }
  return &Ext;
}

// Optimize bitcast followed by extractelement pattern
Instruction *InstCombinerImpl::optimizeBitcastExtract(ExtractElementInst &Ext) {
  Value *Source;
  uint64_t ExtIndex;

  if (!match(Ext.getVectorOperand(), m_BitCast(m_Value(Source))) ||
      !match(Ext.getIndexOperand(), m_ConstantInt(ExtIndex)))
    return nullptr;

  ElementCount NumElts = 
      cast<VectorType>(Ext.getVectorOperandType())->getElementCount();
  Type *DestType = Ext.getType();
  unsigned DestWidth = DestType->getPrimitiveSizeInBits();
  bool IsBigEndian = DL.isBigEndian();

  // Handle scalar-to-vector bitcast extraction
  if (Source->getType()->isIntegerTy()) {
    assert(isa<FixedVectorType>(Ext.getVectorOperand()->getType()) &&
           "Expected fixed vector type for bitcast from scalar");

    // Adjust index for endianness
    if (IsBigEndian)
      ExtIndex = NumElts.getKnownMinValue() - 1 - ExtIndex;

    unsigned ShiftAmount = ExtIndex * DestWidth;

    if (!ShiftAmount || 
        (isDesirableIntType(Source->getType()->getPrimitiveSizeInBits()) &&
         Ext.getVectorOperand()->hasOneUse())) {
      if (ShiftAmount)
        Source = Builder.CreateLShr(Source, ShiftAmount, "extelt.offset");

      if (DestType->isFloatingPointTy()) {
        Type *DstIntTy = IntegerType::getIntNTy(Source->getContext(), DestWidth);
        Value *Trunc = Builder.CreateTrunc(Source, DstIntTy);
        return new BitCastInst(Trunc, DestType);
      }
      return new TruncInst(Source, DestType);
    }
  }

  // Handle vector-to-vector bitcast extraction
  if (!Source->getType()->isVectorTy())
    return nullptr;

  auto *SrcVecType = cast<VectorType>(Source->getType());
  ElementCount SrcNumElts = SrcVecType->getElementCount();

  // Same number of elements - try direct element access
  if (SrcNumElts == NumElts)
    if (Value *Elt = findScalarElement(Source, ExtIndex))
      return new BitCastInst(Elt, DestType);

  assert(SrcNumElts.isScalable() == NumElts.isScalable() &&
         "Source and destination must have same scalability");

  // Handle narrowing conversions
  if (SrcNumElts.getKnownMinValue() < NumElts.getKnownMinValue()) {
    Value *Scalar, *Vec;
    uint64_t InsIndex;

    if (!match(Source, m_InsertElt(m_Value(Vec), m_Value(Scalar),
                                  m_ConstantInt(InsIndex))))
      return nullptr;

    // Check if extract is from the inserted portion
    unsigned NarrowingRatio = 
        NumElts.getKnownMinValue() / SrcNumElts.getKnownMinValue();
    if (ExtIndex / NarrowingRatio != InsIndex) {
      // Remove insertelement if unused
      if (Source->hasOneUse() && Ext.getVectorOperand()->hasOneUse()) {
        Value *NewBC = Builder.CreateBitCast(Vec, Ext.getVectorOperandType());
        return ExtractElementInst::Create(NewBC, Ext.getIndexOperand());
      }
      return nullptr;
    }

    // Calculate which part of the scalar we're extracting based on endianness
    unsigned Chunk = ExtIndex % NarrowingRatio;
    if (IsBigEndian)
      Chunk = NarrowingRatio - 1 - Chunk;

    // Handle floating-point vectors specially
    bool NeedSrcBitcast = SrcVecType->getScalarType()->isFloatingPointTy();
    bool NeedDestBitcast = DestType->isFloatingPointTy();
    if (NeedSrcBitcast && NeedDestBitcast)
      return nullptr;

    unsigned SrcWidth = SrcVecType->getScalarSizeInBits();
    unsigned ShAmt = Chunk * DestWidth;

    if (!Source->hasOneUse() || !Ext.getVectorOperand()->hasOneUse())
      if (NeedSrcBitcast || NeedDestBitcast)
        return nullptr;

    if (NeedSrcBitcast) {
      Type *SrcIntTy = IntegerType::getIntNTy(Scalar->getContext(), SrcWidth);
      Scalar = Builder.CreateBitCast(Scalar, SrcIntTy);
    }

    if (ShAmt) {
      if (!Ext.getVectorOperand()->hasOneUse())
        return nullptr;
      Scalar = Builder.CreateLShr(Scalar, ShAmt);
    }

    if (NeedDestBitcast) {
      Type *DestIntTy = IntegerType::getIntNTy(Scalar->getContext(), DestWidth);
      return new BitCastInst(Builder.CreateTrunc(Scalar, DestIntTy), DestType);
    }
    return new TruncInst(Scalar, DestType);
  }
  return nullptr;
}

