//----------------------------------------------------------------------------------
// Handler for the button press message.
//----------------------------------------------------------------------------------
HRESULT CScene_Death::OnNotifyPressEx(HXUIOBJ hObjPressed, XUINotifyPress* pNotifyPressData, BOOL& rfHandled)
{
	if (m_bIgnoreInput) return S_OK;

	ui.AnimateKeyPress(pNotifyPressData->UserIndex, VK_PAD_A);

	Minecraft* pGameInstance = Minecraft::GetInstance();
	unsigned int btnIdx = 0U;
	for (; btnIdx < BUTTONS_DEATH_MAX; ++btnIdx)
	{
		if (m_Buttons[btnIdx] == hObjPressed)
			break;
	}

	switch (btnIdx)
	{
	case BUTTON_DEATH_EXITGAME:
	{
		// 4J-PB - fix for #8333 - BLOCKER: If player decides to exit game, then cancels the exit player becomes stuck at game over screen
		//m_bIgnoreInput = true;

		const bool isFullVersion = ProfileManager.IsFullVersion();
		const unsigned char userIndex = pNotifyPressData->UserIndex;
		const bool isPrimaryPlayer = (userIndex == ProfileManager.GetPrimaryPad());

		if (isFullVersion)
		{
			UINT uiIDA[3];
			int playTime = -1;

			if (pGameInstance->localplayers[userIndex] != nullptr)
			{
				playTime = static_cast<int>(pGameInstance->localplayers[userIndex]->getSessionTimer());
			}

			TelemetryManager->RecordLevelExit(userIndex, eSen_LevelExitStatus_Failed);

			if (StorageManager.GetSaveDisabled())
			{
				uiIDA[0] = IDS_CONFIRM_CANCEL;
				uiIDA[1] = IDS_CONFIRM_OK;
				StorageManager.RequestMessageBox(
					IDS_EXIT_GAME,
					IDS_CONFIRM_EXIT_GAME_PROGRESS_LOST,
					uiIDA, 2,
					userIndex,
					&UIScene_PauseMenu::ExitGameDialogReturned,
					this,
					app.GetStringTable()
				);
			}
			else
			{
				if (g_NetworkManager.IsHost())
				{
					uiIDA[0] = IDS_CONFIRM_CANCEL;
					uiIDA[1] = IDS_EXIT_GAME_SAVE;
					uiIDA[2] = IDS_EXIT_GAME_NO_SAVE;
					StorageManager.RequestMessageBox(
						IDS_EXIT_GAME,
						IDS_CONFIRM_EXIT_GAME,
						uiIDA, 3,
						userIndex,
						&UIScene_PauseMenu::ExitGameSaveDialogReturned,
						this,
						app.GetStringTable()
					);
				}
				else
				{
					uiIDA[0] = IDS_CONFIRM_CANCEL;
					uiIDA[1] = IDS_CONFIRM_OK;
					StorageManager.RequestMessageBox(
						IDS_EXIT_GAME,
						IDS_CONFIRM_EXIT_GAME,
						uiIDA, 2,
						userIndex,
						&UIScene_PauseMenu::ExitGameDialogReturned,
						this,
						app.GetStringTable()
					);
				}
			}
		}
		else // Trial version
		{
			if (isPrimaryPlayer)
			{
				TelemetryManager->RecordLevelExit(userIndex, eSen_LevelExitStatus_Failed);
				CXuiSceneBase::ReduceTrialTimerValue();
				UINT uiIDA[2];
				uiIDA[0] = IDS_CONFIRM_CANCEL;
				uiIDA[1] = IDS_CONFIRM_OK;
				StorageManager.RequestMessageBox(
					IDS_EXIT_GAME,
					IDS_CONFIRM_EXIT_GAME_PROGRESS_LOST,
					uiIDA, 2,
					userIndex,
					&UIScene_PauseMenu::ExitGameDialogReturned,
					this,
					app.GetStringTable()
				);
			}
			else
			{
				TelemetryManager->RecordLevelExit(userIndex, eSen_LevelExitStatus_Failed);
				app.SetAction(userIndex, eAppAction_ExitPlayer);
			}
		}
	}
	break;

	case BUTTON_DEATH_RESPAWN:
	{
		m_bIgnoreInput = true;
		app.SetAction(pNotifyPressData->UserIndex, eAppAction_Respawn);
	}
	break;

	default:
		break;
	}
	return S_OK;
}

