int CScene_Death::RespawnThreadProc(void* lpParameter)
{
	AABB::UseDefaultThreadStorage();
	Vec3::UseDefaultThreadStorage();
	Compression::UseDefaultThreadStorage();

	const size_t padIndex = reinterpret_cast<size_t>(lpParameter);
	Minecraft* pGameInstance = Minecraft::GetInstance();

	pGameInstance->localplayers[padIndex]->respawn();
	app.SetGameStarted(true);
	pGameInstance->gameRenderer->EnableUpdateThread();

	// Poll until respawn completes
	for (int waitCount = 0; !pGameInstance->localplayers[padIndex]->GetPlayerRespawned(); ++waitCount)
	{
		Sleep(50);
	}

	return S_OK;
}

