//--------------------------------------------------------------------------------------
// Name: CXuiSceneContainer::OnInit
// Desc: Message handler for XM_INIT
//--------------------------------------------------------------------------------------
HRESULT CXuiSceneContainer::OnInit(XUIMessageInit* pInitData, BOOL& bHandled)
{
    D3DXVECTOR3 pos;
    MapChildControls();
    Minecraft* gameInstance = Minecraft::GetInstance();
    ContainerScreenInput* initParams = static_cast<ContainerScreenInput*>(pInitData->pvInitData);

    XuiControlSetText(m_ChestText, app.GetString(initParams->container->getName()));
    ContainerMenu* menuPtr = new ContainerMenu(initParams->inventory, initParams->container);
    std::shared_ptr<Container> containerRef = initParams->container;

    m_iPad = initParams->iPad;
    m_bSplitscreen = initParams->bSplitscreen;

#ifdef _XBOX
    if (gameInstance->localgameModes[initParams->iPad] != nullptr)
    {
        TutorialMode* tMode = static_cast<TutorialMode*>(gameInstance->localgameModes[initParams->iPad]);
        m_previousTutorialState = tMode->getTutorial()->getCurrentState();
        tMode->getTutorial()->changeTutorialState(e_Tutorial_State_Container_Menu, this);
    }
#endif

    int totalSlots = containerRef->getContainerSize();
    int rowsCount = totalSlots / 9;

    float pointerW, pointerH;
    if (m_bSplitscreen)
    {
        app.AdjustSplitscreenScene(m_hObj, &m_OriginalPosition, m_iPad);
    }

    m_pointerControl->GetBounds(&pointerW, &pointerH);

    float sceneWidth, sceneHeight;
    this->GetBounds(&sceneWidth, &sceneHeight);

    int deltaRows = VISIBLE_ROW_COUNT - rowsCount;
    sceneHeight -= deltaRows * pointerH;
    this->SetBounds(sceneWidth, sceneHeight);

    this->GetPosition(&pos);
    pos.y += (deltaRows * pointerH) / 2.0f;

    // Ensure Y coordinate remains even in SD modes to prevent point-sampling artifacts
    if (!RenderManager.IsHiDef())
    {
        long yInt = static_cast<long>(pos.y);
        yInt &= ~1L;
        pos.y = static_cast<float>(yInt);
    }
    this->SetPosition(&pos);

    InitDataAssociations(initParams->iPad, menuPtr);
    CXuiSceneAbstractContainer::Initialize(initParams->iPad, menuPtr, true, totalSlots,
                                           eSectionContainerUsing, eSectionContainerMax);

    delete initParams;
    return S_OK;
}

HRESULT CXuiSceneContainer::OnDestroy()
{
    Minecraft* gameInstance = Minecraft::GetInstance();

#ifdef _XBOX
    if (gameInstance->localgameModes[m_iPad] != nullptr)
    {
        TutorialMode* tMode = static_cast<TutorialMode*>(gameInstance->localgameModes[m_iPad]);
        if (tMode != nullptr)
        {
            tMode->getTutorial()->changeTutorialState(m_previousTutorialState);
        }
    }
#endif

    // 4J Stu - Fix for #11302 - TCR 001: Network Connectivity: Host crashed after being killed by the client while accessing a chest during burst packet loss.
    // We need to make sure that we call closeContainer() anytime this menu is closed, even if it is forced to close by some other reason (like the player dying)
    if (gameInstance->localplayers[m_iPad] != nullptr)
    {
        gameInstance->localplayers[m_iPad]->closeContainer();
    }

    return S_OK;
}

