namespace BANCHO::Api {

// Helper: Determine authentication credentials based on current mode (OAuth vs legacy)
static std::pair<std::string, std::string> fetch_auth_credentials() {
    if (BanchoState::is_oauth) {
        return {"$token", BanchoState::cho_token};
    } else {
        return {BanchoState::get_username(), BanchoState::pw_md5.string()};
    }
}

// Helper: Format URL with auth parameters appended
static std::string build_request_url(const std::string& base_path) {
    std::string url = fmt::format("osu.{:s}{:s}", BanchoState::endpoint, base_path);
    auto [user_val, pass_val] = fetch_auth_credentials();
    url.append(fmt::format("&user={}&pass={}", user_val, pass_val));
    return url;
}

// Process raw HTTP response into API packet and dispatch to appropriate handler
static void dispatch_api_response(Mc::Net::Response&& http_resp, const Request& req) {
    if (!http_resp.success) {
        free(req.extra);
        return;
    }

    Packet api_packet{};
    api_packet.id = req.type;
    api_packet.extra = req.extra;
    api_packet.extra_int = req.extra_int;
    api_packet.size = http_resp.body.length();
    api_packet.memory = reinterpret_cast<u8*>(const_cast<char*>(http_resp.body.data()));

    // Route to specific handler based on request type
    switch (api_packet.id) {
        case RequestType::GET_BEATMAPSET_INFO:
            Downloader::process_beatmapset_info_response(api_packet);
            break;

        case RequestType::GET_MAP_LEADERBOARD:
            BANCHO::Leaderboard::process_leaderboard_response(api_packet);
            break;

        case RequestType::GET_REPLAY: {
            if (api_packet.size == 0) {
                ui->getNotificationOverlay()->addToast(US_("Failed to download replay"), ERROR_TOAST);
                break;
            }

            // Validate alignment before casting
            if (reinterpret_cast<uintptr_t>(api_packet.extra) % alignof(FinishedScore) != 0) {
                debugLog("WARNING: handle_api_response(GET_REPLAY) received misaligned extra data");
                ui->getNotificationOverlay()->addToast(US_("Internal error: replay data misalignment"), ERROR_TOAST);
                break;
            }

            FinishedScore score_copy = *reinterpret_cast<FinishedScore*>(api_packet.extra);

            std::string replay_dir = fmt::format(NEOMOD_REPLAYS_PATH "/{:d}", score_copy.server);
            std::string replay_file = fmt::format("{:d}.replay.lzma", score_copy.unixTimestamp);
            std::string full_path = replay_dir + "/" + replay_file;

            io->write(full_path, api_packet.memory, api_packet.size,
                      [score_copy](bool saved_successfully) {
                          if (saved_successfully) {
                              LegacyReplay::load_and_watch(score_copy);
                          } else {
                              ui->getNotificationOverlay()->addToast(US_("Failed to save replay"), ERROR_TOAST);
                          }
                      });
            break;
        }

        case RequestType::MARK_AS_READ:
            // Intentionally left blank — no action required
            break;

        default:
            debugLog("Unrecognized API response type: {:d}", static_cast<int>(api_packet.id));
            break;
    }

    free(req.extra);
}

void send_request(const Request& request) {
    if (!BanchoState::is_online()) {
        debugLog("API request of type {:d} rejected — client not authenticated.",
                 static_cast<int>(request.type));
        free(request.extra);
        return;
    }

    Mc::Net::RequestOptions opts{
        .user_agent = "osu!",
        .timeout = 60,
        .connect_timeout = 5
    };

    std::string full_url = build_request_url(request.path);

    networkHandler->httpRequestAsync(full_url, std::move(opts),
                                     [request](Mc::Net::Response resp) mutable {
                                         dispatch_api_response(std::move(resp), request);
                                     });
}

void append_auth_params(std::string& url, const std::string& user_key, const std::string& pass_key) {
    auto [user_val, pass_val] = fetch_auth_credentials();
    url += "&" + user_key + "=" + user_val + "&" + pass_key + "=" + pass_val;
}

