#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <random>
using namespace std;

int N;
int query_count = 0;

// Helper function to send a query and get the answer
int perform_query(const string& s) {
    if (query_count >= 3500) return 0; // Safety limit
    cout << "? " << s << endl;
    query_count++;
    int result;
    cin >> result;
    return result;
}

// Build query string based on subset of nodes
int query_nodes(const vector<int>& nodes, int total_nodes) {
    string pattern(total_nodes, '0');
    for (int node : nodes) {
        if (node >= 1 && node <= total_nodes) {
            pattern[node - 1] = '1';
        }
    }
    return perform_query(pattern);
}

// Global collections for tracking nodes
vector<int> processed_set;     // S: currently verified connected component
vector<int> active_candidates; // U: unprocessed nodes still in consideration
vector<int> deferred_nodes;    // skipped: temporarily set aside nodes

// Check if adding 'node' reduces the count by exactly 1 (indicating connection)
bool test_connection(int node, int current_value) {
    vector<int> temp = processed_set;
    temp.push_back(node);
    int new_value = query_nodes(temp, N);

    // If new_value == current_value - 1, then node connects directly to S
    return (new_value - current_value) == -1;
}

// Recursive binary search to find a connecting node
int locate_connecting_node(const vector<int>& candidates, int current_value) {
    if (candidates.empty()) return -1;

    if (candidates.size() == 1) {
        return test_connection(candidates[0], current_value) ? candidates[0] : -1;
    }

    // Split candidates into two halves
    size_t mid = candidates.size() / 2;
    vector<int> left(candidates.begin(), candidates.begin() + mid);
    vector<int> right(candidates.begin() + mid, candidates.end());

    // Build query set: processed_set + (active_candidates - left)
    vector<int> query_group = processed_set;
    vector<bool> is_in_left(N + 1, false);
    for (int x : left) is_in_left[x] = true;

    for (int x : active_candidates) {
        if (!is_in_left[x]) query_group.push_back(x);
    }
    for (int x : deferred_nodes) {
        if (!is_in_left[x]) query_group.push_back(x);
    }

    int val = query_nodes(query_group, N);

    if (val == 0) {
        // No connections found in left group → search right
        return locate_connecting_node(right, current_value);
    } else {
        // Try left first, then fall back to right
        int found = locate_connecting_node(left, current_value);
        if (found != -1) return found;
        return locate_connecting_node(right, current_value);
    }
}

void process_case() {
    cin >> N;
    query_count = 0;
    processed_set.clear();
    active_candidates.clear();
    deferred_nodes.clear();

    // Initialize with node 1 as starting point
    processed_set.push_back(1);
    for (int i = 2; i <= N; ++i) {
        active_candidates.push_back(i);
    }

    while (!active_candidates.empty() || !deferred_nodes.empty()) {
        int fS = query_nodes(processed_set, N);

        if (fS == 0) {
            cout << "! 0" << endl;
            return;
        }

        // If no active candidates left, restore deferred ones
        if (active_candidates.empty()) {
            active_candidates.swap(deferred_nodes);
        }

        // Shuffle candidates to avoid bias
        static mt19937 rng(42);
        shuffle(active_candidates.begin(), active_candidates.end(), rng);

        int candidate = locate_connecting_node(active_candidates, fS);

        if (candidate != -1) {
            // Successfully found a valid connection
            processed_set.push_back(candidate);

            // Remove candidate from active list
            vector<int> updated;
            for (int x : active_candidates) {
                if (x != candidate) updated.push_back(x);
            }
            active_candidates = move(updated);

            // Re-introduce deferred nodes since topology may have changed
            active_candidates.insert(active_candidates.end(), 
                                     deferred_nodes.begin(), deferred_nodes.end());
            deferred_nodes.clear();
        } else {
            // Could not verify any candidate — move one to deferred
            if (!active_candidates.empty()) {
                int last = active_candidates.back();
                deferred_nodes.push_back(last);
                active_candidates.pop_back();
            }
        }
    }

    cout << "! 1" << endl;
}

int main() {
    int T;
    if (cin >> T) {
        while (T--) {
            process_case();
        }
    }
    return 0;
}

