#include <bits/stdc++.h>
using namespace std;

int main() {
    int R, H;
    cin >> R >> H; // R=75, H=1

    const int robotCount = 40; // number of robots we will use
    const int itemCount = 1000;
    const double inclusionProb = 0.293;

    vector<uint64_t> itemMasks(itemCount);
    vector<vector<int>> testGroups(robotCount);

    // Generate a random matrix that is 2-separable
    mt19937_64 rng;
    bernoulli_distribution dist(inclusionProb);
    bool foundValidMatrix = false;

    for (int attemptSeed = 0; attemptSeed < 100; attemptSeed++) {
        rng.seed(attemptSeed);
        // Reset data structures
        fill(itemMasks.begin(), itemMasks.end(), 0ULL);
        for (int i = 0; i < robotCount; i++) testGroups[i].clear();

        // Build the testing matrix
        for (int robotIdx = 0; robotIdx < robotCount; robotIdx++) {
            for (int itemIdx = 0; itemIdx < itemCount; itemIdx++) {
                if (dist(rng)) {
                    itemMasks[itemIdx] |= (1ULL << robotIdx);
                    testGroups[robotIdx].push_back(itemIdx + 1); // positions are 1-indexed
                }
            }
        }

        // Verify 2-separability: all pair-wise ORs must be unique
        unordered_set<uint64_t> observedUnions;
        foundValidMatrix = true;
        for (int idx1 = 0; idx1 < itemCount && foundValidMatrix; idx1++) {
            for (int idx2 = idx1; idx2 < itemCount; idx2++) {
                uint64_t combinedMask = itemMasks[idx1] | itemMasks[idx2];
                if (observedUnions.find(combinedMask) != observedUnions.end()) {
                    foundValidMatrix = false;
                    break;
                }
                observedUnions.insert(combinedMask);
            }
        }
        if (foundValidMatrix) {
            break; // Found a suitable matrix
        }
    }

    // In the extremely unlikely case that no good matrix is found,
    // we fall back to the last generated matrix (still very likely to work).

    // Issue queries
    for (int robotIdx = 0; robotIdx < robotCount; robotIdx++) {
        cout << "? " << testGroups[robotIdx].size();
        for (int pos : testGroups[robotIdx]) {
            cout << " " << pos;
        }
        cout << endl;
        cout.flush();
    }

    // Request results
    cout << "@" << endl;
    cout.flush();

    int numPositiveTests;
    cin >> numPositiveTests;
    vector<int> testResults(numPositiveTests);
    for (int i = 0; i < numPositiveTests; i++) {
        cin >> testResults[i];
    }

    // Construct result mask from test outcomes
    uint64_t outputMask = 0;
    for (int robotIdx = 0; robotIdx < robotCount; robotIdx++) {
        if (testResults[robotIdx] == 1) {
            outputMask |= (1ULL << robotIdx);
        }
    }

    // Search for matching pair in precomputed masks
    int firstItem = -1, secondItem = -1;
    for (int idx1 = 0; idx1 < itemCount; idx1++) {
        for (int idx2 = idx1; idx2 < itemCount; idx2++) {
            if ((itemMasks[idx1] | itemMasks[idx2]) == outputMask) {
                firstItem = idx1 + 1;
                secondItem = idx2 + 1;
                goto done;
            }
        }
    }
done:

    // Output final answer
    cout << "! " << firstItem << " " << secondItem << endl;
    cout.flush();

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <chrono>
using namespace std;

int n;
vector<int> p; // Stores the permutation, 1-based. 0 means unknown.
vector<int> known_positions; // Stores indices where p is known.

// Helper function to ask a query and get the score
int query_permutation(const vector<int>& q) {
    cout << "0";
    for (int x : q) {
        cout << " " << x;
    }
    cout << endl;
    int result;
    cin >> result;
    return result;
}

// Send final answer and terminate
void submit_answer(const vector<int>& ans) {
    cout << "1";
    for (int val : ans) {
        cout << " " << val;
    }
    cout << endl;
    exit(0);
}

// Binary search to locate value 'target' among candidate positions
// Uses 'fill_value' as placeholder for non-target candidates
int locate_value(int target, vector<int>& positions, int fill_value) {
    int left = 0;
    int right = positions.size() - 1;

    while (left < right) {
        int mid = left + (right - left) / 2;
        vector<int> temp_query(n);

        // Fill in known values first
        for (int i = 1; i <= n; ++i) {
            if (p[i] != 0) {
                temp_query[i-1] = p[i];
            } else {
                temp_query[i-1] = fill_value;
            }
        }

        // Set positions in [left, mid] to target value
        for (int i = left; i <= mid; ++i) {
            temp_query[positions[i]-1] = target;
        }

        int current_score = query_permutation(temp_query);

        // Count how many known positions are correctly matched
        int base_score = 0;
        for (int idx : known_positions) {
            if (p[idx] == temp_query[idx-1]) {
                base_score++;
            }
        }

        // Adjust search range based on whether target is in first half
        if (current_score > base_score) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    return positions[left];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n)) return 0;

    p.assign(n + 1, 0);

    // Special case: n=1 trivial solution
    if (n == 1) {
        submit_answer({1});
    }

    // Initialize candidate list with all positions
    vector<int> all_positions(n);
    for (int i = 0; i < n; ++i) {
        all_positions[i] = i + 1;
    }

    // Random number generator initialization
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

    vector<int> group_a, group_b;

    // Phase 1: Separate positions of 1 and 2 using random partitioning
    while (true) {
        shuffle(all_positions.begin(), all_positions.end(), rng);
        int split_point = n / 2;
        group_a.clear();
        group_b.clear();

        vector<int> temp_query(n);
        for (int i = 0; i < n; ++i) {
            if (i < split_point) {
                group_a.push_back(all_positions[i]);
                temp_query[all_positions[i]-1] = 1;
            } else {
                group_b.push_back(all_positions[i]);
                temp_query[all_positions[i]-1] = 2;
            }
        }

        int score = query_permutation(temp_query);

        if (score == 2) {
            // 1 is in group_a, 2 is in group_b
            break;
        } else if (score == 0) {
            // 1 is in group_b, 2 is in group_a
            swap(group_a, group_b);
            break;
        }
        // If score == 1, try again with new shuffle
    }

    // Locate exact position of 1
    int pos_1 = locate_value(1, group_a, 2);
    p[pos_1] = 1;
    known_positions.push_back(pos_1);

    // Locate exact position of 2
    int pos_2 = locate_value(2, group_b, 1);
    p[pos_2] = 2;
    known_positions.push_back(pos_2);

    // Phase 2: Find remaining values from 3 to n
    vector<int> remaining_positions;
    for (int i = 1; i <= n; ++i) {
        if (p[i] == 0) {
            remaining_positions.push_back(i);
        }
    }

    for (int value = 3; value <= n; ++value) {
        if (remaining_positions.size() == 1) {
            p[remaining_positions[0]] = value;
            known_positions.push_back(remaining_positions[0]);
            remaining_positions.clear();
            break;
        }

        int found_pos = locate_value(value, remaining_positions, 1);
        p[found_pos] = value;
        known_positions.push_back(found_pos);

        // Remove found position from remaining list
        for (int i = 0; i < remaining_positions.size(); ++i) {
            if (remaining_positions[i] == found_pos) {
                remaining_positions.erase(remaining_positions.begin() + i);
                break;
            }
        }
    }

    // Construct final answer
    vector<int> final_permutation;
    for (int i = 1; i <= n; ++i) {
        final_permutation.push_back(p[i]);
    }

    submit_answer(final_permutation);

    return 0;
}

