//-----------------------------------------------------------------------------
void StyleData::addStyle(int styleId, TColorStyle *style) {
    m_styles.emplace_back(styleId, style);
}

//-----------------------------------------------------------------------------
TColorStyle *StyleData::getStyle(int pos) const {
    assert(pos >= 0 && pos < static_cast<int>(m_styles.size()));
    return m_styles[pos].second;
}

//-----------------------------------------------------------------------------
int StyleData::getStyleIndex(int pos) const {
    assert(pos >= 0 && pos < static_cast<int>(m_styles.size()));
    return m_styles[pos].first;
}

