__host__ void IpcOnImpl::ipcHostInit(int my_pe, const HEAP_BASES_T &heap_bases,
                                     MPI_Comm thread_comm) {
  MPI_Comm local_comm;
  mpilib_ftable_.Comm_split_type(thread_comm, MPI_COMM_TYPE_SHARED, 0, MPI_INFO_NULL,
                                 &local_comm);

  int local_count;
  mpilib_ftable_.Comm_size(local_comm, &local_count);
  this->local_proc_count = local_count;

  mpilib_ftable_.Comm_rank(local_comm, &this->local_rank);

  HIPAllocator *mem_alloc = get_default_allocator();
  HIPIpcHandleVec *handle_array = mem_alloc->AllocateIpcHandleVec(local_count);

  char *my_heap_base = heap_bases[my_pe];
  CHECK_HIP(mem_alloc->GetIpcHandle(my_heap_base, handle_array->GetHandleVecElem(this->local_rank)));

  size_t handle_byte_size = mem_alloc->GetIpcHandleSize();
  mpilib_ftable_.Allgather(MPI_IN_PLACE, handle_byte_size, MPI_CHAR,
                           handle_array->GetHandleVecElem(0), handle_byte_size, MPI_CHAR, local_comm);

  char **device_ipc_bases;
  CHECK_HIP(hipMalloc(reinterpret_cast<void **>(&device_ipc_bases),
                      local_count * sizeof(char *)));

  int idx = 0;
  while (idx < local_count) {
    if (idx != this->local_rank) {
      void **raw_ptr = reinterpret_cast<void **>(&device_ipc_bases[idx]);
      CHECK_HIP(mem_alloc->OpenIpcHandle(raw_ptr, handle_array->GetHandleVecElem(idx)));
    } else {
      device_ipc_bases[idx] = my_heap_base;
    }
    ++idx;
  }

  this->ipc_bases = device_ipc_bases;

  delete handle_array;

  if (envvar::ro::disable_ipc || envvar::disable_ipc) {
    if (0 == my_pe) {
      printf("ROCSHMEM_RO_DISABLE_IPC and RO_DISABLE_IPC environment variables have been deprecated.\n"
             "  Please use ROCSHMEM_DISABLE_MIXED_IPC as a replacement.\n");
    }
  }

  bool should_disable = envvar::disable_mixed_ipc || envvar::ro::disable_ipc || envvar::disable_ipc;
  if (!should_disable) {
    CHECK_HIP(hipMalloc(reinterpret_cast<void**>(&this->pes_with_ipc_avail),
                        local_count * sizeof(int)));

    MPI_Group global_grp, local_grp;
    mpilib_ftable_.Comm_group(thread_comm, &global_grp);
    mpilib_ftable_.Comm_group(local_comm, &local_grp);

    std::vector<int> local_indices(local_count);
    for (int k = 0; k < local_count; ++k) {
      local_indices[k] = k;
    }

    mpilib_ftable_.Group_translate_ranks(local_grp, local_count,
                                         local_indices.data(), global_grp,
                                         this->pes_with_ipc_avail);

    mpilib_ftable_.Group_free(&local_grp);
    mpilib_ftable_.Group_free(&global_grp);
  }

  mpilib_ftable_.Comm_free(&local_comm);
}

__host__ void IpcOnImpl::ipcHostInit(int my_pe, const HEAP_BASES_T &heap_bases,
                                     TcpBootstrap *bootstr) {
  this->local_proc_count = bootstr->getNranksPerNode();
  auto const& local_ranks = bootstr->getLocalRanks();

  this->local_rank = -1;
  for (size_t pos = 0; pos < local_ranks.size(); ++pos) {
    if (local_ranks[pos] == my_pe) {
      this->local_rank = static_cast<int>(pos);
      break;
    }
  }

  HIPAllocator *allocator = get_default_allocator();
  HIPIpcHandleVec *handle_storage = allocator->AllocateIpcHandleVec(this->local_proc_count);

  char *my_heap = heap_bases[my_pe];
  CHECK_HIP(allocator->GetIpcHandle(my_heap, handle_storage->GetHandleVecElem(this->local_rank)));

  size_t handle_bytesz = allocator->GetIpcHandleSize();
  bootstr->groupAllGather(handle_storage->GetHandleVecElem(0), handle_bytesz, local_ranks);

  char **dev_ipc_bases;
  CHECK_HIP(hipMalloc(reinterpret_cast<void **>(&dev_ipc_bases),
                      this->local_proc_count * sizeof(char *)));

  int j = 0;
  while (j < this->local_proc_count) {
    if (j != this->local_rank) {
      void **base_ref = reinterpret_cast<void **>(&dev_ipc_bases[j]);
      CHECK_HIP(allocator->OpenIpcHandle(base_ref, handle_storage->GetHandleVecElem(j)));
    } else {
      dev_ipc_bases[j] = my_heap;
    }
    ++j;
  }

  this->ipc_bases = dev_ipc_bases;
  delete handle_storage;

  if (envvar::ro::disable_ipc || envvar::disable_ipc) {
    if (0 == my_pe) {
      printf("ROCSHMEM_RO_DISABLE_IPC and RO_DISABLE_IPC environment variables have been deprecated.\n"
             "  Please use ROCSHMEM_DISABLE_MIXED_IPC as a replacement.\n");
    }
  }

  bool disable_flag = envvar::disable_mixed_ipc || envvar::ro::disable_ipc || envvar::disable_ipc;
  if (!disable_flag) {
    CHECK_HIP(hipMalloc(reinterpret_cast<void**>(&this->pes_with_ipc_avail),
                        this->local_proc_count * sizeof(int)));
    std::copy(local_ranks.begin(), local_ranks.end(), this->pes_with_ipc_avail);
  }
}

__host__ void IpcOnImpl::ipcHostStop() {
  HIPAllocator *mem_alloc = get_default_allocator();

  int counter = 0;
  while (counter < this->local_proc_count) {
    if (counter != this->local_rank) {
      CHECK_HIP(mem_alloc->CloseIpcHandle(this->ipc_bases[counter]));
    }
    ++counter;
  }

  CHECK_HIP(hipFree(this->ipc_bases));

  if (nullptr != this->pes_with_ipc_avail) {
    CHECK_HIP(hipFree(this->pes_with_ipc_avail));
  }
}

