// Custom streambuf implementation that writes to an IndexOutput
class OutputBuf final : public std::streambuf {
 public:
  explicit OutputBuf(IndexOutput& out) noexcept : _output{out} {}

  std::streamsize xsputn(const char_type* c, std::streamsize size) final {
    _output.WriteBytes(reinterpret_cast<const byte_type*>(c), size);
    return size;
  }

  int_type overflow(int_type c) final {
    _output.WriteByte(traits_type::to_char_type(c));
    return c;
  }

 private:
  IndexOutput& _output;
};

// Test case: heap::ForEachIf with condition checking for zero values
TEST(std_test, head_for_each_if) {
  /* standard scenario */
  {
    std::vector<int> source = {0, 7, 28, 1, 2, 5, 7, 9, 1, 3, 65,
                               0, 0, 0,  1, 2, 3, 0, 4, 0, 0, 1};

    // Build min-heap structure
    std::make_heap(source.begin(), source.end(), std::greater<int>());

    const std::vector<int> expected_values(7, 0);
    std::vector<int> collected_values;
    std::vector<const int*> address_references;

    irstd::heap::ForEachIf(
      source.begin(), source.end(),
      [](int value) { return 0 == value; },
      [&collected_values, &address_references](const int& element) {
        collected_values.push_back(element);
        address_references.push_back(&element);
      });

    // Remove duplicate addresses (if any)
    address_references.erase(
      std::unique(address_references.begin(), address_references.end()),
      address_references.end());

    ASSERT_EQ(expected_values, collected_values);
    // Ensure all references point to distinct elements
    ASSERT_EQ(collected_values.size(), address_references.size());
  }
}

