int main() {
    int n;
    cin >> n;

    // Special case for n = 1
    if (n == 1) {
        cout << 1 << " " << 1 << endl;
        cout.flush();
        return 0;
    }

    // Prepare random number generator
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

    // Try to find a base permutation that yields answer 0
    vector<int> base(n + 1, 0);
    bool found_base = false;
    int attempt_count = 0;

    while (!found_base && attempt_count < 100) {
        vector<int> temp_perm(n);
        iota(temp_perm.begin(), temp_perm.end(), 1);
        shuffle(temp_perm.begin(), temp_perm.end(), rng);

        // Query with this shuffled permutation
        cout << 0;
        for (int val : temp_perm) cout << " " << val;
        cout << endl;
        cout.flush();

        int response;
        cin >> response;

        if (response == 0) {
            found_base = true;
            for (int i = 0; i < n; ++i) {
                base[i + 1] = temp_perm[i];
            }
        }
        attempt_count++;
    }

    // Now determine the exact permutation using binary search approach
    vector<int> result_perm(n + 1, 0);
    int confirmed_elements = 0;

    for (int value_to_find = 1; value_to_find <= n; ++value_to_find) {
        // Collect available positions
        vector<int> available_positions;
        for (int pos = 1; pos <= n; ++pos) {
            if (result_perm[pos] == 0) {
                available_positions.push_back(pos);
            }
        }

        // Binary search to locate where 'value_to_find' belongs
        int left = 0, right = (int)available_positions.size() - 1;
        while (left < right) {
            int mid = (left + right) / 2;

            // Build query: copy base, then set selected positions to current value
            vector<int> query_perm(n + 1);
            for (int i = 1; i <= n; ++i) {
                query_perm[i] = base[i];
            }

            for (int idx = left; idx <= mid; ++idx) {
                query_perm[available_positions[idx]] = value_to_find;
            }

            // Send query
            cout << 0;
            for (int i = 1; i <= n; ++i) {
                cout << " " << query_perm[i];
            }
            cout << endl;
            cout.flush();

            int ans;
            cin >> ans;

            // Check how many new fixed points were added
            int delta = ans - confirmed_elements;

            if (delta > 0) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        // Found the position for current value
        int final_pos = available_positions[left];
        result_perm[final_pos] = value_to_find;
        base[final_pos] = value_to_find;
        confirmed_elements++;
    }

    // Output final answer
    cout << 1;
    for (int i = 1; i <= n; ++i) {
        cout << " " << result_perm[i];
    }
    cout << endl;
    cout.flush();

    return 0;
}

