#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <ctime>
using namespace std;

// Structure to represent an edge in the graph
struct Edge {
    int u, v;
};

// Global variables for problem configuration
int N, M;
vector<Edge> edges;
vector<vector<int>> adj; // adjacency list storing incident edge indices

vector<int> best_solution;   // Best vertex cover found so far
int min_vertex_count;        // Size of the smallest valid cover found

void optimize_cover() {
    const double time_budget = 1.9;
    clock_t start = clock();

    mt19937_64 rng(2025);

    // Initialize with full vertex set (trivial solution)
    best_solution.assign(N + 1, 1);
    min_vertex_count = N;

    // Precompute degrees for efficiency
    vector<int> initial_degrees(N + 1, 0);
    for (const auto& e : edges) {
        initial_degrees[e.u]++;
        initial_degrees[e.v]++;
    }

    // Reusable buffers for iterative improvement
    vector<int> current_assignment(N + 1);
    vector<int> dynamic_degrees(N + 1);
    vector<int> edge_status(M, 0);         // 0 = uncovered, 1 = covered
    vector<int> active_edges(M);           // List of currently uncovered edge indices
    vector<int> edge_position(M);          // Maps edge index -> position in active_edges
    vector<int> edge_coverage(M, 0);       // Number of selected endpoints covering each edge
    vector<int> selected_vertices;         // Temporary storage for vertices in current solution

    while (true) {
        if ((double)(clock() - start) / CLOCKS_PER_SEC > time_budget) break;

        // Reset state for new iteration
        fill(current_assignment.begin(), current_assignment.end(), 0);
        dynamic_degrees = initial_degrees;
        fill(edge_status.begin(), edge_status.end(), 0);

        // Set up active edge list
        for (int i = 0; i < M; ++i) {
            active_edges[i] = i;
            edge_position[i] = i;
        }
        int remaining_edges = M;
        int vertices_used = 0;

        // Greedy construction: iteratively pick uncovered edges and cover them
        while (remaining_edges > 0) {
            int idx = rng() % remaining_edges;
            int edge_index = active_edges[idx];

            int a = edges[edge_index].u;
            int b = edges[edge_index].v;

            int chosen = -1;
            if (dynamic_degrees[a] > dynamic_degrees[b]) {
                chosen = a;
            } else if (dynamic_degrees[b] > dynamic_degrees[a]) {
                chosen = b;
            } else {
                chosen = (rng() & 1) ? a : b;
            }

            current_assignment[chosen] = 1;
            vertices_used++;

            // Update all incident edges
            for (int inc_edge : adj[chosen]) {
                if (edge_status[inc_edge]) continue;

                edge_status[inc_edge] = 1;

                // Remove from active list in O(1)
                int pos = edge_position[inc_edge];
                int last_edge = active_edges[remaining_edges - 1];

                active_edges[pos] = last_edge;
                edge_position[last_edge] = pos;

                remaining_edges--;

                // Reduce degree of neighbor
                int neighbor = (edges[inc_edge].u == chosen) ? edges[inc_edge].v : edges[inc_edge].u;
                dynamic_degrees[neighbor]--;
            }
        }

        // Optimization phase: remove redundant vertices
        fill(edge_coverage.begin(), edge_coverage.end(), 0);
        selected_vertices.clear();

        for (int i = 1; i <= N; ++i) {
            if (current_assignment[i]) {
                selected_vertices.push_back(i);
                for (int e_idx : adj[i]) {
                    edge_coverage[e_idx]++;
                }
            }
        }

        shuffle(selected_vertices.begin(), selected_vertices.end(), rng);

        for (int vertex : selected_vertices) {
            bool essential = false;
            for (int e_idx : adj[vertex]) {
                if (edge_coverage[e_idx] == 1) {
                    essential = true;
                    break;
                }
            }

            if (!essential) {
                current_assignment[vertex] = 0;
                vertices_used--;
                for (int e_idx : adj[vertex]) {
                    edge_coverage[e_idx]--;
                }
            }
        }

        // Update best solution if improved
        if (vertices_used < min_vertex_count) {
            min_vertex_count = vertices_used;
            best_solution = current_assignment;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (cin >> N >> M) {
        adj.resize(N + 1);
        edges.reserve(M);

        for (int i = 0; i < M; ++i) {
            int u, v;
            cin >> u >> v;
            edges.emplace_back(u, v);
            adj[u].push_back(i);
            adj[v].push_back(i);
        }

        optimize_cover();

        for (int i = 1; i <= N; ++i) {
            cout << best_solution[i] << '\n';
        }
    }

    return 0;
}

