Y_UNIT_TEST_SUITE(TestSourceRoot) {
    Y_UNIT_TEST(TestStrip) {
        // Reconstruct() converts "\" -> "/" on Windows
        const TString path = TPathSplit(__SOURCE_FILE_IMPL__.As<TStringBuf>()).Reconstruct();
        UNIT_ASSERT_EQUAL(path, "util" LOCSLASH_S "system" LOCSLASH_S "src_root_ut.cpp");
    }

    Y_UNIT_TEST(TestPrivateChopPrefixRoutine) {
        static constexpr const char testStr[] = ":\0:\0: It's unlikely that this string has an ARCADIA_ROOT as its prefix :\0:\0:";
        static constexpr const auto testBuf = STATIC_BUF(testStr);
        UNIT_ASSERT_VALUES_EQUAL(TStringBuf(testStr, sizeof(testStr) - 1), ::NPrivate::StripRoot(testBuf).As<TStringBuf>());
        UNIT_ASSERT_VALUES_EQUAL(0, ::NPrivate::RootPrefixLength(testBuf));

        // Verify IsProperPrefix behavior with various inputs
        static_assert(::NPrivate::IsProperPrefix(STATIC_BUF("foo"), STATIC_BUF("foobar")), R"(IsProperPrefix("foo", "foobar") failed)");
        static_assert(!::NPrivate::IsProperPrefix(STATIC_BUF("foobar"), STATIC_BUF("foo")), R"(IsProperPrefix("foobar", "foo") failed)");
        static_assert(!::NPrivate::IsProperPrefix(STATIC_BUF("name"), STATIC_BUF("name")), R"(IsProperPrefix("name", "name") failed)");
        static_assert(::NPrivate::IsProperPrefix(STATIC_BUF("name"), STATIC_BUF("name/")), R"(IsProperPrefix("name", "name/") failed)");
        static_assert(::NPrivate::IsProperPrefix(STATIC_BUF(""), STATIC_BUF("foobar")), R"(IsProperPrefix("", "foobar") failed)");
        static_assert(!::NPrivate::IsProperPrefix(STATIC_BUF(""), STATIC_BUF("")), R"(IsProperPrefix("", "") failed)");
        static_assert(::NPrivate::IsProperPrefix(STATIC_BUF("dir"), STATIC_BUF("dir/file")), R"(IsProperPrefix("dir", "dir/file") failed)");
    }
} // Y_UNIT_TEST_SUITE(TestSourceRoot)

#include "draw_rectangular_marquee.h"
#include "gl.h"
#include "glu.h"
#include "../material_colors.h"

IGL_INLINE void igl::opengl2::draw_rectangular_marquee(
  const int x_start,
  const int y_start,
  const int x_end,
  const int y_end)
{
  using namespace std;

  // Save current OpenGL state
  GLint lighting_enabled = 0;
  glGetIntegerv(GL_LIGHTING, &lighting_enabled);

  GLint stipple_enabled = 0;
  glGetIntegerv(GL_LINE_STIPPLE, &stipple_enabled);

  GLdouble line_width = 1.0;
  glGetDoublev(GL_LINE_WIDTH, &line_width);

  // Disable lighting for consistent rendering
  glDisable(GL_LIGHTING);

  // Retrieve viewport dimensions
  GLint vp[4];
  glGetIntegerv(GL_VIEWPORT, vp);
  const int viewport_width  = vp[2];
  const int viewport_height = vp[3];

  // Set up orthographic projection for 2D drawing
  glMatrixMode(GL_PROJECTION);
  glPushMatrix();
  glLoadIdentity();
  gluOrtho2D(0.0, static_cast<GLdouble>(viewport_width),
             0.0, static_cast<GLdouble>(viewport_height));

  // Switch to modelview and reset matrix
  glMatrixMode(GL_MODELVIEW);
  glPushMatrix();
  glLoadIdentity();

  // Configure line appearance for marquee
  glEnable(GL_LINE_STIPPLE);
  glLineStipple(3, 0xAAAA);
  glLineWidth(1.0);
  glColor4f(0.2, 0.2, 0.2, 1.0);

  // Draw rectangular outline
  glBegin(GL_LINE_STRIP);
  glVertex2d(x_start, y_start);
  glVertex2d(x_end,   y_start);
  glVertex2d(x_end,   y_end);
  glVertex2d(x_start, y_end);
  glVertex2d(x_start, y_start);
  glEnd();

  // Restore original matrices
  glPopMatrix();
  glMatrixMode(GL_PROJECTION);
  glPopMatrix();
  glMatrixMode(GL_MODELVIEW);

  // Restore previous OpenGL state
  glLineWidth(static_cast<GLfloat>(line_width));
  if (stipple_enabled) {
    glEnable(GL_LINE_STIPPLE);
  } else {
    glDisable(GL_LINE_STIPPLE);
  }

  if (lighting_enabled) {
    glEnable(GL_LIGHTING);
  } else {
    glDisable(GL_LIGHTING);
  }
}

