//-*****************************************************************************
namespace AbcA = Alembic::AbcCoreAbstract;
using namespace Alembic::Util;

//-*****************************************************************************
void CreateAndPopulateArchive( const std::string &archivePath )
{
    AbcA::MetaData md;
    md.setUnique( "name", "arkive" );
    Alembic::AbcCoreOgawa::WriteArchive aw;
    AbcA::ArchiveWriterPtr archive = aw( archivePath, md );

    AbcA::ObjectWriterPtr rootObj = archive->getTop();
    AbcA::ObjectWriterPtr deepestChild;

    {
        // Build nested object hierarchy
        md.set( "name", "objLevel1" );
        AbcA::ObjectWriterPtr level1 = rootObj->createChild(
            AbcA::ObjectHeader( "childObject0", md ) );

        md.set( "name", "objLevel2" );
        AbcA::ObjectWriterPtr level2 = level1->createChild(
            AbcA::ObjectHeader( "archiveChildChild", md ) );

        md.set( "name", "objLevel3" );
        deepestChild = level2->createChild(
            AbcA::ObjectHeader( "archiveChildChildChild", md ) );
    }

    // Prepare property writer for the deepest object
    AbcA::CompoundPropertyWriterPtr objProps = deepestChild->getProperties();

    // First array property with cyclic sampling
    const AbcA::TimeSamplingType cyclicType( 2, 2.0 );
    const size_t sampleCount = 50;
    const Dimensions dims( sampleCount );
    const AbcA::DataType int32Type( kInt32POD, 1 );

    AbcA::PropertyHeader arrPropHeader(
        "firstInt32ArrayProp", kArrayProperty, AbcA::MetaData(), int32Type, cyclicType );
    AbcA::ArrayPropertyWriterPtr arrWriter = objProps->createArrayProperty( arrPropHeader );

    // Generate and write six samples with varying sizes
    std::vector<int32_t> buffer;

    // Sample 0: values 0..49
    buffer.clear(); buffer.reserve(sampleCount);
    for (size_t i = 0; i < sampleCount; ++i) buffer.push_back(static_cast<int32_t>(i));
    AbcA::ArraySample samp0(buffer.data(), int32Type, dims);
    arrWriter->setSample(0, 0.0, samp0);

    // Sample 1: values 1..30
    buffer.clear(); buffer.reserve(30);
    for (size_t i = 0; i < 30; ++i) buffer.push_back(static_cast<int32_t>(i + 1));
    AbcA::ArraySample samp1(buffer.data(), int32Type, Dimensions(30));
    arrWriter->setSample(1, 1.0, samp1);

    // Sample 2: values 2..51
    buffer.clear(); buffer.reserve(sampleCount);
    for (size_t i = 0; i < sampleCount; ++i) buffer.push_back(static_cast<int32_t>(i + 2));
    AbcA::ArraySample samp2(buffer.data(), int32Type, dims);
    arrWriter->setSample(2, 2.0, samp2);

    // Sample 3: values 3..52
    buffer.clear(); buffer.reserve(sampleCount);
    for (size_t i = 0; i < sampleCount; ++i) buffer.push_back(static_cast<int32_t>(i + 3));
    AbcA::ArraySample samp3(buffer.data(), int32Type, dims);
    arrWriter->setSample(3, 3.0, samp3);

    // Sample 4: values 4..53
    buffer.clear(); buffer.reserve(sampleCount);
    for (size_t i = 0; i < sampleCount; ++i) buffer.push_back(static_cast<int32_t>(i + 4));
    AbcA::ArraySample samp4(buffer.data(), int32Type, dims);
    arrWriter->setSample(4, 4.0, samp4);

    // Sample 5: values 5..6
    buffer.clear(); buffer.reserve(2);
    for (size_t i = 0; i < 2; ++i) buffer.push_back(static_cast<int32_t>(i + 5));
    AbcA::ArraySample samp5(buffer.data(), int32Type, Dimensions(2));
    arrWriter->setSample(5, 5.0, samp5);

    // Sample 6: values 6..83
    buffer.clear(); buffer.reserve(78);
    for (size_t i = 0; i < 78; ++i) buffer.push_back(static_cast<int32_t>(i + 6));
    AbcA::ArraySample samp6(buffer.data(), int32Type, Dimensions(78));
    arrWriter->setSample(6, 6.0, samp6);

    // Second array property with acyclic sampling
    AbcA::PropertyHeader secondArrHeader(
        "secondInt32ArrayProp", kArrayProperty, AbcA::MetaData(),
        int32Type, AbcA::TimeSamplingType(AbcA::TimeSamplingType::kAcyclic) );
    AbcA::ArrayPropertyWriterPtr secondArrWriter =
        objProps->createArrayProperty(secondArrHeader);

    // Three samples with different sizes
    std::vector<int32_t> secBuffer;

    // Sample 0: [0, 1]
    secBuffer.clear(); secBuffer.reserve(2);
    for (size_t i = 0; i < 2; ++i) secBuffer.push_back(static_cast<int32_t>(i));
    AbcA::ArraySample secSamp0(secBuffer.data(), int32Type, Dimensions(2));
    secondArrWriter->setSample(0, 0.0, secSamp0);

    // Sample 1: [1..10]
    secBuffer.clear(); secBuffer.reserve(10);
    for (size_t i = 0; i < 10; ++i) secBuffer.push_back(static_cast<int32_t>(i + 1));
    AbcA::ArraySample secSamp1(secBuffer.data(), int32Type, Dimensions(10));
    secondArrWriter->setSample(1, 0.5, secSamp1);

    // Sample 2: [2..24]
    secBuffer.clear(); secBuffer.reserve(23);
    for (size_t i = 0; i < 23; ++i) secBuffer.push_back(static_cast<int32_t>(i + 2));
    AbcA::ArraySample secSamp2(secBuffer.data(), int32Type, Dimensions(23));
    secondArrWriter->setSample(2, 2.3, secSamp2);

    // Scalar float property
    AbcA::PropertyHeader scalarHeader(
        "scalarProp", kScalarProperty, AbcA::MetaData(),
        AbcA::DataType(kFloat32POD, 1), cyclicType );
    AbcA::ScalarPropertyWriterPtr scalarWriter =
        objProps->createScalarProperty(scalarHeader);

    const float32_t scalarValue = 42.0f;
    scalarWriter->setSample(0, 0.0, &scalarValue);
}

//-*****************************************************************************
void LoadAndVerifyArchive( const std::string &archivePath )
{
    Alembic::AbcCoreOgawa::ReadArchive ar;
    AbcA::ArchiveReaderPtr arkive = ar( archivePath );

    AbcA::ObjectReaderPtr currentObj = arkive->getTop();
    AbcA::CompoundPropertyReaderPtr targetProps;

    // Navigate to the deepest child object
    while (currentObj->getNumChildren() > 0)
    {
        currentObj = currentObj->getChild(0);
    }

    std::cout << "Reached final object: " << currentObj->getFullName() << std::endl;
    targetProps = currentObj->getProperties();
    std::cout << "Found " << targetProps->getNumProperties() << " properties." << std::endl;

    // Locate properties by name and type
    AbcA::ScalarPropertyReaderPtr scalarProp;
    AbcA::ArrayPropertyReaderPtr firstArrayProp;
    AbcA::ArrayPropertyReaderPtr secondArrayProp;

    for (size_t i = 0; i < targetProps->getNumProperties(); ++i)
    {
        AbcA::BasePropertyReaderPtr baseProp = targetProps->getProperty(i);
        std::cout << "Property: " << baseProp->getName() << std::endl;

        if (baseProp->isScalar())
        {
            scalarProp = baseProp->asScalarPtr();
            std::cout << "Scalar has " << scalarProp->getNumSamples() << " samples." << std::endl;
        }
        else if (baseProp->isArray())
        {
            if (baseProp->getName() == "firstInt32ArrayProp")
                firstArrayProp = baseProp->asArrayPtr();
            else if (baseProp->getName() == "secondInt32ArrayProp")
                secondArrayProp = baseProp->asArrayPtr();
        }
    }

    // Verify scalar property
    for (size_t s = 0; s < scalarProp->getNumSamples(); ++s)
    {
        float32_t val = 0.0f;
        scalarProp->getSample(s, &val);
        TESTING_ASSERT(val == 42.0f);
