class Solution {
public:
    void reverseString(vector<char>& s) {
        int start = 0;
        int end = static_cast<int>(s.size()) - 1;

        while (start < end) {
            char temp = s[start];
            s[start] = s[end];
            s[end] = temp;

            start++;
            end--;
        }
    }
};

#include "IRrecv.h"
