/// @file
/// @brief Arris "Manchester code" based infrared protocol implementation.
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595
// Supports:
//   Brand: Arris,  Model: VIP1113M Set-top box
//   Brand: Arris,  Model: 120A V1.0 A18 remote

namespace {
  // Timing parameters in microseconds
  const uint8_t  overhead = 2;
  const uint16_t half_period = 320;  // Base clock period
  const uint16_t header_mark = half_period * 8;      // Header mark duration
  const uint16_t header_space = half_period * 6;     // Header space duration
  // Gap between repeated transmissions
  const uint32_t gap_duration = 102144 - ((8 + 6 + kArrisBits * 2) * half_period);

  // Bit positions and masks
  const uint32_t release_mask = 0x800008;
  const uint8_t checksum_width = 4;
  const uint8_t command_width = 19;
  const uint8_t release_position = checksum_width + command_width;
}

using irutils::sumNibbles;

#if SEND_ARRIS
/// Transmit an Arris Manchester-encoded IR signal.
/// Status: STABLE / Confirmed working.
/// @param[in] payload The data to send
/// @param[in] length Number of bits to transmit
/// @param[in] cycles How many times to repeat the transmission
void IRsend::sendArris(const uint64_t payload, const uint16_t length,
                       const uint16_t cycles) {
  enableIROut(38);
  for (uint16_t i = 0; i <= cycles; i++) {
    // Send header sequence
    mark(header_mark);
    space(header_space);
    // Send Manchester-encoded data with appropriate timing
    sendManchester(half_period * 2, 0, half_period,
                   0, gap_duration, payload, length);
  }
}

/// Modify the release flag in an Arris command.
/// Used to switch between button press and button release states.
/// @param[in] original The existing Arris message
/// @return Modified message with toggle bit flipped
uint32_t IRsend::toggleArrisRelease(const uint32_t original) {
  return original ^ release_mask;
}

/// Build a complete 32-bit Arris command from components.
/// @param[in] cmd The command value (19 bits)
/// @param[in] released True if button was released, false if pressed
/// @return Complete encoded message ready for transmission
uint32_t IRsend::encodeArris(const uint32_t cmd, const bool released) {
  uint32_t frame = 0x10000000;
  irutils::setBits(&frame, checksum_width, command_width, cmd);
  irutils::setBit(&frame, release_position, released);
  return frame + sumNibbles(frame);
}
#endif  // SEND_ARRIS

#if DECODE_ARRIS
/// Interpret received Arris Manchester-encoded signal.
/// Status: STABLE / Confirmed working.
/// @param[in,out] results Where decoded results are stored
/// @param[in] startIdx Position in raw buffer to begin decoding
/// @param[in] expectedBits Number of bits expected
/// @param[in] strict Whether to enforce protocol constraints
/// @return true if decoding succeeded, false otherwise
bool IRrecv::decodeArris(decode_results *results, uint16_t startIdx,
                         const uint16_t expectedBits, const bool strict) {
  // Check minimum buffer length requirement
  if (results->rawlen < expectedBits + overhead - startIdx)
    return false;

  // Validate protocol specification if strict mode enabled
  if (strict && expectedBits != kArrisBits)
    return false;

  // Verify header mark and space
  if (!matchMark(results->rawbuf[startIdx++], header_mark)) return false;
  if (!matchSpace(results->rawbuf[startIdx++], header_space)) return false;

  // Decode Manchester-encoded data portion
  uint64_t decoded = 0;
  if (!matchManchester(results->rawbuf + startIdx, &decoded,
                       results->rawlen - startIdx, expectedBits,
                       half_period * 2, 0,
                       half_period, 0, 0,
                       false, kUseDefTol, kMarkExcess, true, false))
    return false;

  // Optional checksum validation
  if (strict) {
    uint8_t stored_checksum = GETBITS32(decoded, 0, checksum_width);
    uint8_t calculated_checksum = sumNibbles(decoded >> checksum_width);
    if (stored_checksum != calculated_checksum)
      return false;
  }

  // Store successful decode results
  results->decode_type = decode_type_t::ARRIS;
  results->bits = expectedBits;
  results->value = decoded;
  results->address = static_cast<bool>(GETBIT32(decoded, release_position));
  results->command = GETBITS32(decoded, checksum_width, command_width);
  return true;
}
#endif  // DECODE_ARRIS

