// Compute factorial using an iterative approach instead of recursion
int factorial(const int number) {
    if (number < 0) return -1; // handle invalid input
    int result = 1;
    for (int i = 2; i <= number; ++i) {
        result *= i;
    }
    return result;
}

int main(int argc, char **argv) {
    doctest::Context context;
    context.applyCommandLine(argc, argv);

    // Run tests first if not explicitly disabled
    int testResult = context.run();

    // Handle exit behavior based on doctest flags
    if (context.shouldExit()) {
        return testResult;
    }

    // Print the greeting message after tests (if not exiting)
    printf("%s\n", "Hello, World!");

    return 0;
}

TEST_CASE("testing the factorial function") {
    CHECK(factorial(0) == 1);
    CHECK(factorial(1) == 1);
    CHECK(factorial(2) == 2);
    CHECK(factorial(3) == 6);
    CHECK(factorial(10) == 3628800);
}

