//****************************************************************************
//    ErodeDilate Fx (Refactored Clone)
//****************************************************************************
class ErodeDilateFx final : public TStandardRasterFx {
  FX_PLUGIN_DECLARATION(ErodeDilateFx)
  TRasterFxPort m_sourceInput;
  TIntEnumParamP m_operationMode;
  TDoubleParamP m_kernelSize;

public:
  ErodeDilateFx() 
    : m_operationMode(new TIntEnumParam(0, "Square")), 
      m_kernelSize(0.0) {
    addInputPort("Source", m_sourceInput);
    bindParam(this, "type", m_operationMode);
    m_operationMode->addItem(1, "Circular");
    m_kernelSize->setMeasureName("fxLength");
    bindParam(this, "radius", m_kernelSize);
  }

  bool doGetBBox(double frame, TRectD &bbox,
                 const TRenderSettings &info) override;
  void doDryCompute(TRectD &rect, double frame,
                    const TRenderSettings &ri) override;
  void doCompute(TTile &tile, double frame, const TRenderSettings &ri) override;
  int getMemoryRequirement(const TRectD &rect, double frame,
                           const TRenderSettings &info) override;
  bool canHandle(const TRenderSettings &info, double frame) override {
    return isAlmostIsotropic(info.m_affine);
  }
};

//-------------------------------------------------------------------
bool ErodeDilateFx::doGetBBox(double frame, TRectD &bbox,
                              const TRenderSettings &info) {
  if (!m_sourceInput.getFx()) return false;
  bool success = m_sourceInput->doGetBBox(frame, bbox, info);
  const double padding = tceil(m_kernelSize->getValue(frame));
  bbox = bbox.enlarge(static_cast<int>(padding));
  return success;
}

//-------------------------------------------------------------------
void ErodeDilateFx::doCompute(TTile &tile, double frame,
                              const TRenderSettings &info) {
  if (!m_sourceInput.isConnected()) return;

  const double rawRadius = m_kernelSize->getValue(frame);
  const double scaledRadius = rawRadius * std::sqrt(info.m_affine.det());

  const bool isDilation = scaledRadius >= 0.0;
  const int paddingPixels = static_cast<int>(tceil(std::abs(scaledRadius)));
  const TRop::ErodilateMaskType maskType = 
    static_cast<TRop::ErodilateMaskType>(m_operationMode->getValue());

  if (isDilation) {
    m_sourceInput->compute(tile, frame, info);
    const TRasterP &ras = tile.getRaster();
    TRop::erodilate(ras, ras, scaledRadius, maskType);
  } else {
    const TDimension &tileSize = tile.getRaster()->getSize();
    const TRectD inputRect(tile.m_pos, TDimensionD(tileSize.lx, tileSize.ly));
    const TRectD expandedRect = inputRect.enlarge(paddingPixels);
    const TDimension expandedDims(
        tround(expandedRect.getLx()),
        tround(expandedRect.getLy())
    );

    TTile sourceTile;
    m_sourceInput->allocateAndCompute(sourceTile, expandedRect.getP00(), expandedDims,
                                      tile.getRaster(), frame, info);

    const TRasterP &srcRaster = sourceTile.getRaster();
    TRop::erodilate(srcRaster, srcRaster, scaledRadius, maskType);

    tile.getRaster()->copy(srcRaster, -TPoint(paddingPixels, paddingPixels));
  }
}

//-------------------------------------------------------------------
void ErodeDilateFx::doDryCompute(TRectD &rect, double frame,
                                 const TRenderSettings &info) {
  if (!m_sourceInput.isConnected()) return;

  const double rawRadius = m_kernelSize->getValue(frame);
  const double scaledRadius = rawRadius * std::sqrt(info.m_affine.det());
  const bool isDilation = scaledRadius >= 0.0;

  if (isDilation) {
    m_sourceInput->dryCompute(rect, frame, info);
  } else {
    const int paddingPixels = static_cast<int>(tceil(std::abs(scaledRadius)));
    TRectD expandedRect = rect.enlarge(paddingPixels);
    m_sourceInput->dryCompute(expandedRect, frame, info);
  }
}

//------------------------------------------------------------------
int ErodeDilateFx::getMemoryRequirement(const TRectD &rect, double frame,
                                        const TRenderSettings &info) {
  const auto getBaseMem = [&](int channels) {
    return TRasterFx::memorySize(rect, channels);
  };

  const int modeVal = m_operationMode->getValue();
  if (modeVal == 0) {
    // Square mask: one extra greymap buffer
    return getBaseMem(8);
  } else {
    // Circular mask: two extra greymap buffers
    return 2 * getBaseMem(8);
  }
}

